        private static readonly Dictionary<string, CF75FollowPhysicalWatch> CF75FollowPhysicalWatches =
            new Dictionary<string, CF75FollowPhysicalWatch>(StringComparer.Ordinal);

        private static void ArmCF75FreshFollowPhysicalWatch(BotOwner bot, long followGeneration, string source)
        {
            if (bot == null || string.IsNullOrEmpty(bot.ProfileId) || bot.GetPlayer == null)
                return;
            Vector3 body = bot.GetPlayer.Position;
            if (!IsFinite(body) || followGeneration <= 0) return;
            CF75FollowPhysicalWatches[bot.ProfileId] = new CF75FollowPhysicalWatch
            {
                RaidGeneration = raidGeneration, FollowGeneration = followGeneration,
                StartedAt = Time.time, LastSampleAt = Time.time,
                StartBody = body, LastBody = body, Source = source ?? string.Empty
            };
        }

        private static void SampleCF75FreshFollowPhysicalWatch(BotOwner bot, Vector3 body)
        {
            if (bot == null || string.IsNullOrEmpty(bot.ProfileId) ||
                !CF75FollowPhysicalWatches.TryGetValue(bot.ProfileId, out CF75FollowPhysicalWatch watch))
                return;
            float elapsed = Time.time - watch.StartedAt;
            if (watch.RaidGeneration != raidGeneration || elapsed < -0.01f || !IsFinite(body))
            {
                CF75FollowPhysicalWatches.Remove(bot.ProfileId);
                return;
            }
            long generation = FollowerMovementWriterAuthority.PeekOwnerGenerationForCF75(
                bot, out FollowerMovementWriterAuthority.WriterDomain domain);
            bool exactOwner = domain == FollowerMovementWriterAuthority.WriterDomain.Follow &&
                              generation == watch.FollowGeneration;
            float dt = Mathf.Max(0.001f, Time.time - watch.LastSampleAt);
            Vector3 delta = body - watch.LastBody;
            float planar = new Vector2(delta.x, delta.z).magnitude;
            float speed = planar / dt;
            bool plausiblePhysical = exactOwner && planar <= 7f * dt + 0.5f &&
                                     Mathf.Abs(delta.y) < 1.5f;
            bool firstProgress = plausiblePhysical && planar >= 0.25f;
            if (firstProgress && !watch.FirstPhysicalSeen)
            {
                watch.FirstPhysicalSeen = true;
                watch.FirstPhysicalSeconds = elapsed;
            }
            if (plausiblePhysical && speed >= 3f && elapsed <= 5.5f)
                watch.StableSprintObserved = true;
            bool complete = !exactOwner || elapsed >= 4f;
            WriteEvent("cf75ShadowFreshFollowPhysicalAckWindow", bot, new
            {
                raidGeneration, source = watch.Source,
                expectedFollowGeneration = watch.FollowGeneration,
                observedGeneration = generation, observedOwner = domain.ToString(),
                elapsedSeconds = elapsed, sampleSeconds = dt, planarMeters = planar,
                verticalMeters = delta.y, planarMetersPerSecond = speed,
                plausiblePhysical, firstPhysicalSeen = watch.FirstPhysicalSeen,
                firstPhysicalSeconds = watch.FirstPhysicalSeen ? watch.FirstPhysicalSeconds : -1f,
                sprintSpeedObserved = watch.StableSprintObserved,
                playerState = bot.GetPlayer != null ? bot.GetPlayer.CurrentStateName.ToString() : "unknown",
                endOfWindow = complete, physicalAckIsNotPathCommit = true, physicalAckCannotExcludeAllManualInterventions = true,
                locomotionChanged = false, movementTargetChanged = false,
                traversalSuccessRecorded = false, bodyRelocated = false
            });
            if (complete) CF75FollowPhysicalWatches.Remove(bot.ProfileId);
            else { watch.LastSampleAt = Time.time; watch.LastBody = body; }
        }

