        // V2-RC7: read-only authoritative identity projection. No new registry,
        // generation or ownership policy. The movement producer supplies ONLY an
        // offered identity; the Authority independently reads the live mission and
        // cursor from here. A stale/absent route fails closed; it cannot create a
        // cursor or silently refresh a former producer's generation.
        internal static bool TryReadV2LiveRouteAdmission(
            BotOwner bot, out long missionId, out int stepIndex,
            out int episodeId, out int chainId, out long originGeneration,
            out string reason)
        {
            missionId = 0;
            stepIndex = -1;
            episodeId = -1;
            chainId = -1;
            originGeneration = 0;
            reason = "v2LiveRouteUnavailable";
            if (IsCapabilityPortalWaiting(bot)) { reason="portalQueueOwnsWait";return false; }
            if (IsCapabilityStrategyPending(bot)) { reason="sequenceSelectedAttemptOwnsRouteAdmission";return false; }
            if (IsCapabilityRecoveryPending(bot)) { reason="sequenceTerminalRecoveryOwnsMotion"; return false; }
            string id = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(id) || raidGeneration <= 0 ||
                !FollowerRouteMissions.TryGetValue(id, out FollowerRouteMission mission) ||
                mission == null || mission.Steps == null ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count ||
                !FollowerTraversalRouteCursors.TryGetValue(id, out FollowerTraversalRouteCursor cursor) ||
                cursor == null || !cursor.LearningV375TransactionActive ||
                cursor.LearningV375RouteMissionId != mission.MissionId ||
                cursor.LearningV375MovementGeneration <= 0)
                return false;
            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || step.EpisodeId < 0 || step.ChainId < 0)
            {
                reason = "v2LiveRouteStepInvalid";
                return false;
            }
            missionId = mission.MissionId;
            stepIndex = mission.CurrentStepIndex;
            episodeId = step.EpisodeId;
            chainId = step.ChainId;
            originGeneration = cursor.LearningV375MovementGeneration;
            reason = string.Empty;
            return true;
        }

