        // V1.3.18: traversal ownership is per follower. The previous single global activeProbe
        // serialized every Vault/Climb/Jump/WalkThrough attempt across the whole fireteam, which
        // effectively made followers queue at learned edges even though PIT already disables
        // follower-to-follower collision. Each bot now owns an independent probe and may traverse
        // the same learned edge concurrently with every other follower.
        private static readonly Dictionary<string, ProbeRuntime> ActiveProbes =
            new Dictionary<string, ProbeRuntime>(StringComparer.Ordinal);

        // CompileFix31: chain intermediates keep a short movement-authority barrier after the old
        // probe retires. FollowAction alone may use this window to start the preloaded successor
        // traversal; SAIN/combat/recovery remain blocked so a stale BotMover route cannot win one
        // FixedUpdate between adjacent traversal edges.
        private static readonly Dictionary<string, ChainHandoffAuthorityGuard> ChainHandoffAuthorityGuards =
            new Dictionary<string, ChainHandoffAuthorityGuard>(StringComparer.Ordinal);

        private static bool TryGetActiveProbe(BotOwner bot, out ProbeRuntime probe)
        {
            probe = null;
            string profileId = bot?.ProfileId ?? string.Empty;
            return !string.IsNullOrEmpty(profileId) &&
                   ActiveProbes.TryGetValue(profileId, out probe) &&
                   probe != null &&
                   probe.Generation == raidGeneration;
        }

        private static ProbeRuntime GetAnyActiveProbe()
        {
            return ActiveProbes.Values.FirstOrDefault(probe =>
                probe != null && probe.Generation == raidGeneration);
        }

        private static bool IsActiveProbe(ProbeRuntime probe)
        {
            return probe != null &&
                   probe.Generation == raidGeneration &&
                   TryGetActiveProbe(probe.Bot, out ProbeRuntime current) &&
                   ReferenceEquals(current, probe);
        }

        private static bool RegisterActiveProbe(ProbeRuntime probe)
        {
            if (!BindProbeLifecycle(probe)) return false;
            InstallLifecycleProbe(probe);
            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) && probe != null)
            {
                // V3.86 ownership handoff: a direct breadcrumb producer may have paused BotMover
                // while it exclusively translated the Player body. The moment an actuator probe
                // becomes the body consumer, release that producer and its pause token before the
                // probe starts. This is producer->consumer ownership transfer, not recovery.
                if ((LearningV365ContinuousRouteProducerStates.TryGetValue(
                        profileId, out LearningV365ContinuousRouteProducerState learningV386ProducerAtProbeStart)) &&
                    learningV386ProducerAtProbeStart != null &&
                    !learningV386ProducerAtProbeStart.Generic)
                {
                    ClearLearningV365ContinuousPhysicalRoute(
                        probe.Bot, "learningV386ActuatorProbeAcquiresExclusiveBodyAuthority");
                }

                if ((probe.LearningV322AttemptId <= 0))
                {
                    probe.LearningV322AttemptId = ++learningV322AttemptSequence;
                    if (probe.FrozenTraversalCommitment != null && probe.FrozenTraversalCommitment.SkillTransferParentAttemptId > 0)
                    {
                        probe.LearningV322ParentAttemptId = probe.FrozenTraversalCommitment.SkillTransferParentAttemptId;
                    }
                    WriteEvent("learningV322TraversalAttemptStarted", probe.Bot, new
                    {
                        attemptId = probe.LearningV322AttemptId,
                        parentAttemptId = probe.LearningV322ParentAttemptId,
                        edgeId = probe.LearnedEdgeId,
                        templateEdgeId = IsLearningV319TransientSkillTransfer(probe.FrozenTraversalCommitment)
                            ? probe.FrozenTraversalCommitment.SkillTemplateEdgeId
                            : 0,
                        kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                        requestSource = probe.RequestSource ?? string.Empty,
                        zeroShot = IsLearningV319TransientSkillTransfer(probe.FrozenTraversalCommitment)
                    });
                    if ((probe.FrozenTraversalCommitment != null) &&
                        probe.FrozenTraversalCommitment.RouteMissionId > 0 &&
                        FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission attemptMission) &&
                        attemptMission != null && attemptMission.MissionId == probe.FrozenTraversalCommitment.RouteMissionId)
                    {
                        int attemptStepIndex = probe.FrozenTraversalCommitment.RouteMissionStepIndex;
                        if (attemptStepIndex >= 0 && attemptStepIndex < attemptMission.Steps.Count)
                        {
                            FollowerRouteMissionStep attemptStep = attemptMission.Steps[attemptStepIndex];
                            bool sameRouteIdentity = attemptStep != null &&
                                (attemptStep.EdgeId <= 0 || probe.LearnedEdgeId <= 0 || attemptStep.EdgeId == probe.LearnedEdgeId) &&
                                (attemptStep.EpisodeId <= 0 || probe.TraversalEpisodeId <= 0 || attemptStep.EpisodeId == probe.TraversalEpisodeId);
                            if (sameRouteIdentity)
                            {
                                attemptStep.AttemptStartedObserved = true;
                                attemptStep.AttemptStartedAt = Time.time;
                                WriteEvent("learningV347TraversalOpportunityAttemptObserved", probe.Bot, new
                                {
                                    missionId = attemptMission.MissionId,
                                    stepIndex = attemptStepIndex,
                                    episodeId = attemptStep.EpisodeId,
                                    edgeId = attemptStep.EdgeId,
                                    chainId = attemptStep.ChainId,
                                    kind = attemptStep.Kind,
                                    attemptId = probe.LearningV322AttemptId,
                                    action = "bindAttemptStartedToStableRouteOpportunityIdentity"
                                });
                            }
                        }
                    }
                }
                if ((PostTraversalIntegrityWatches.TryGetValue(profileId, out PostTraversalIntegrityWatch predecessorWatch)) &&
                    predecessorWatch != null && predecessorWatch.ExpiresAt >= Time.time &&
                    predecessorWatch.CompletedChainId > 0 && probe.TraversalChainId > 0 &&
                    predecessorWatch.CompletedChainId == probe.TraversalChainId)
                {
                    Vector3 successorEntry = probe.FrozenTraversalCommitment != null && IsFinite(probe.FrozenTraversalCommitment.RawEntry)
                        ? probe.FrozenTraversalCommitment.RawEntry
                        : (probe.FrozenTraversalCommitment != null ? probe.FrozenTraversalCommitment.Entry : Vector3.zero);
                    float handoffDistance = IsFinite(successorEntry)
                        ? GetPlanarDistance(predecessorWatch.ReleasePosition, successorEntry)
                        : float.MaxValue;
                    if (handoffDistance <= RouteMissionTraversalAdjacentBridgeMaxDistance)
                    {
                        probe.LearningV343InheritedPhysicalLayerGuard = true;
                        WriteEvent("learningV343SuccessorPhysicalLayerGuardArmed", probe.Bot, new
                        {
                            predecessorEdgeId = predecessorWatch.EdgeId,
                            predecessorEpisodeId = predecessorWatch.EpisodeId,
                            successorEdgeId = probe.LearnedEdgeId,
                            chainId = probe.TraversalChainId,
                            releasePosition = Vec(predecessorWatch.ReleasePosition),
                            successorEntry = Vec(successorEntry),
                            handoffDistance,
                            maxDistance = RouteMissionTraversalAdjacentBridgeMaxDistance,
                            action = "preserveCurrentPhysicalLayerUntilSuccessorExecutorOwnsBody"
                        });
                    }
                }

                if (ChainHandoffAuthorityGuards.TryGetValue(profileId, out ChainHandoffAuthorityGuard guard) &&
                    guard != null && guard.Generation == raidGeneration)
                {
                    bool matchingSuccessor =
                        (guard.NextEdgeId <= 0 || probe.LearnedEdgeId <= 0 || guard.NextEdgeId == probe.LearnedEdgeId) &&
                        (guard.ChainId <= 0 || probe.TraversalChainId <= 0 || guard.ChainId == probe.TraversalChainId);
                    if (matchingSuccessor)
                    {
                        // CompileFix39: acquiring the successor probe is not the end of the handoff.
                        // Keep the guard alive until this successor probe is retired so late writes
                        // from the completed traversal cannot contaminate RollingApproach.
                        guard.SuccessorAuthorityAcquired = true;
                        guard.SuccessorAuthorityAcquiredAt = Time.time;
                        guard.SuccessorProbeEdgeId = probe.LearnedEdgeId;
                        guard.SuccessorProbeChainId = probe.TraversalChainId;
                        guard.MovementWriterGeneration = probe.MovementWriterGeneration;
                        guard.ExpiresAt = Mathf.Max(guard.ExpiresAt, Time.time + ChainHandoffSuccessorAuthoritySeconds);
                        Vector3 safePosition = probe.Player != null ? probe.Player.Position : probe.Bot.Position;
                        if (IsFinite(safePosition))
                        {
                            guard.LastSafeSuccessorPosition = safePosition;
                            guard.HasLastSafeSuccessorPosition = true;
                            guard.LastSafeSuccessorEntryDistance = IsFinite(guard.NextEntry)
                                ? Vector3.Distance(safePosition, guard.NextEntry)
                                : float.MaxValue;
                            guard.BestSuccessorEntryDistance = guard.LastSafeSuccessorEntryDistance;
                        }
                        // RC8: successor has a birth-time Traversal generation. Never
                        // fall back to an unscoped Pause when a superseding owner exists.
                        try
                        {
                            if (probe.Bot?.Mover != null &&
                                FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                                    probe.Bot, FollowerMovementWriterAuthority.WriterDomain.Traversal,
                                    probe.MovementWriterGeneration,
                                    out FollowerMovementWriterAuthority.WriteScope successorMotionScope, out _))
                            {
                                using (successorMotionScope)
                                {
                                    probe.Bot.Mover.SetBotMoverPause("R1-8C3F57CFD2F6",@probe?.Bot,false);
                                }
                            }
                        }
                        catch
                        {
                        }
                        string learningV354CompletedSemantic = GetLearningV354SemanticKind(guard.CompletedEdgeId, guard.CompletedKind);
                        string learningV354SuccessorSemantic = GetLearningV354SemanticKind(
                            probe.LearnedEdgeId, probe.TraversalKind ?? probe.RequestedTraversalKind);
                        RecordLearningV354TransitionOutcome(
                            learningV354CompletedSemantic, learningV354SuccessorSemantic, true, false,
                            "successorTraversalAuthorityAcquired");
                        WriteEvent("chainHandoffSuccessorAuthorityAcquired", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            chainId = probe.TraversalChainId,
                            position = probe.Player != null ? Vec(probe.Player.Position) : null,
                            guardRetained = true,
                            guardSeconds = ChainHandoffSuccessorAuthoritySeconds,
                            safeEntryDistance = guard.LastSafeSuccessorEntryDistance
                        });
                    }
                    else
                    {
                        ChainHandoffAuthorityGuards.Remove(profileId);
                        WriteEvent("chainHandoffGuardSupersededByUnrelatedProbe", probe.Bot, new
                        {
                            guardedNextEdgeId = guard.NextEdgeId,
                            guardedChainId = guard.ChainId,
                            probeEdgeId = probe.LearnedEdgeId,
                            probeChainId = probe.TraversalChainId
                        });
                    }
                }

                TrySynchronizeLearningV426TraversalConsumerEpochForSuccessorProbe(probe);
            }
            return true;
        }

        private static void EnsureLearningV328AttemptTerminalizedBeforeUnregister(
            ProbeRuntime probe, string reason)
        {
            if ((probe == null) ||
                probe.LearningV322AttemptId <= 0 || probe.LearningV322AttemptSummaryEmitted)
            {
                return;
            }

            string terminalReason = "implicitUnregister:" +
                                    (string.IsNullOrWhiteSpace(reason) ? probe.Stage.ToString() : reason);
            TraversalCompletionMode completionMode = GetTraversalCompletionMode(probe, terminalReason);
            string terminalClass = ClassifyTraversalOutcome(probe, false, completionMode, terminalReason);
            FollowerMovementWriterAuthority.WriterDomain owner;
            long currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(probe.Bot, out owner);
            EmitLearningV322TraversalAttemptSummary(
                probe, false, completionMode, terminalReason, probe.LearnedEdgeId);
            WriteEvent("learningV328TraversalAttemptImplicitTerminalized", probe.Bot, new
            {
                attemptId = probe.LearningV322AttemptId,
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                stage = probe.Stage.ToString(),
                reason = terminalReason,
                terminalClass,
                movementOwner = owner.ToString(),
                movementGeneration = currentGeneration,
                probeMovementGeneration = probe.MovementWriterGeneration,
                teleportActuallyAttempted = probe.TraversalTeleportAttempted || probe.TeleportFallbackUsed
            });
        }

        // Terminal consumer adoption is owned by FollowerCapabilityHandoffHost.

        private static bool TryRetainLearningV454TraversalEpochForLiveDebt(
            ProbeRuntime probe,
            string reason,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            PostTraversalIntegrityWatch watch)
        {
            if ((probe?.Bot == null))
            {
                return false;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                probe.Bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (owner != FollowerMovementWriterAuthority.WriterDomain.Traversal ||
                generation <= 0 || generation != probe.MovementWriterGeneration)
            {
                return false;
            }

            // The action node may retire, but its route/consumer epoch is still live. Return the
            // actuator's temporary body lease to the persistent route producer without minting a
            // new writer generation. This is deliberately semantic-kind agnostic.
            ReturnLearningV375ActuatorBodyAuthority(
                probe, "learningV454RetainPhysicalEpoch:" + (reason ?? "liveDebt"));
            if (watch != null)
            {
                watch.MovementGeneration = generation;
                watch.ReleasePosition = probe.Player != null ? probe.Player.Position : probe.Bot.Position;
            }
            UpdateLearningV375PersistentExecutablePhysicalRouteTransaction(probe.Bot);

            WriteEvent("learningV454TraversalEpochRetainedForLiveDebt", probe.Bot, new
            {
                reason = reason ?? string.Empty,
                missionId = mission?.MissionId ?? 0,
                stepIndex = mission?.CurrentStepIndex ?? -1,
                successorEdgeId = step?.EdgeId ?? 0,
                successorKind = step?.Kind ?? string.Empty,
                retiredProbeEdgeId = probe.LearnedEdgeId,
                retiredProbeKind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty,
                retiredProbeStage = probe.Stage.ToString(),
                traversalGeneration = generation,
                integrityWatchEdgeId = watch?.EdgeId ?? 0,
                body = probe.Player != null ? Vec(probe.Player.Position) : Vec(probe.Bot.Position),
                bodyRelocated = false,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "retireOnlyActionNodeKeepSamePhysicalEpochUntilRealConsumerClaimsBody"
            });
            return true;
        }

        private static bool TryCommitLearningV454TerminalConsumerAfterProbeRemoval(
            ProbeRuntime probe,
            string reason,
            out string detail)
        {
            detail = "notEligible";
            if ((probe?.Bot == null))
            {
                return false;
            }

            if (HasLearningV371PendingTraversalExecutionDebt(probe.Bot,out _,out _))
            { detail="currentLifecycleDebtRemains"; return true; }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                probe.Bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (owner != FollowerMovementWriterAuthority.WriterDomain.Traversal ||
                generation <= 0 || generation != probe.MovementWriterGeneration)
            {
                detail = "notExpectedTraversalEpoch:owner=" + owner + ":generation=" +
                         generation.ToString(CultureInfo.InvariantCulture);
                return false;
            }

            ReturnLearningV375ActuatorBodyAuthority(
                probe, "learningV454TerminalConsumer:" + (reason ?? "probeRemoved"));

            if (TryHandoffLearningV419TraversalToFreshFollowConsumer(
                    probe.Bot, generation,
                    "learningV454TerminalProbeRetirement:" + (reason ?? "probeRemoved"),
                    "post-traversal-fresh-epoch", out string freshFollowDetail))
            {
                EndLearningV375PersistentRouteTransaction(
                    probe.Bot, "learningV454FreshFollowConsumer:" + (reason ?? "probeRemoved"));
                detail = "freshFollow:" + (freshFollowDetail ?? string.Empty);
                WriteEvent("learningV454TerminalProbeConsumerCommitted", probe.Bot, new
                {
                    reason = reason ?? string.Empty,
                    retiredProbeEdgeId = probe.LearnedEdgeId,
                    retiredProbeKind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty,
                    previousTraversalGeneration = generation,
                    detail,
                    body = probe.Player != null ? Vec(probe.Player.Position) : Vec(probe.Bot.Position),
                    bodyRelocated = false,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "freshFollowConsumerClaimsCurrentPhysicalEpochBeforeTraversalRetires"
                });
                return true;
            }

            long continuationGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                probe.Bot, out FollowerMovementWriterAuthority.WriterDomain continuationOwner);
            if (continuationOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                continuationGeneration > 0 &&
                TryInstallLearningV423PhysicalContinuationConsumer(
                    probe.Bot, continuationGeneration,
                    "learningV454TerminalProbeRetirement:" + (reason ?? "probeRemoved"),
                    out string physicalContinuationDetail))
            {
                EndLearningV375PersistentRouteTransaction(
                    probe.Bot, "learningV454PhysicalContinuationConsumer:" + (reason ?? "probeRemoved"));
                detail = "physicalContinuation:" + (physicalContinuationDetail ?? string.Empty);
                WriteEvent("learningV454TerminalProbeConsumerCommitted", probe.Bot, new
                {
                    reason = reason ?? string.Empty,
                    retiredProbeEdgeId = probe.LearnedEdgeId,
                    retiredProbeKind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty,
                    previousTraversalGeneration = generation,
                    detail,
                    body = probe.Player != null ? Vec(probe.Player.Position) : Vec(probe.Bot.Position),
                    bodyRelocated = false,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "physicalBreadcrumbConsumerKeepsTraversalEpochAliveUntilFreshFollowExists"
                });
                return true;
            }

            // No successor is ready this frame. End only the semantic transaction; keep Traversal
            // itself. EnforceLearningV368TraversalProducerOwnership will retry V419/V423 from the
            // evolving current body and may use the already-existing V439 pathless ownership yield
            // only after topology has been scrubbed. There is intentionally no StopMove here.
            EndLearningV375PersistentRouteTransaction(
                probe.Bot, "learningV454TerminalConsumerDeferred:" + (reason ?? "probeRemoved"));
            detail = "consumerDeferredKeepTraversalEpoch";
            WriteEvent("learningV454TerminalProbeRetirementDeferred", probe.Bot, new
            {
                reason = reason ?? string.Empty,
                retiredProbeEdgeId = probe.LearnedEdgeId,
                retiredProbeKind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty,
                traversalGeneration = generation,
                body = probe.Player != null ? Vec(probe.Player.Position) : Vec(probe.Bot.Position),
                bodyRelocated = false,
                stopMoveCalled = false,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "semanticTransactionEndsButWriterWaitsForConcreteConsumerInsteadOfCreatingOwnerVacuum"
            });
            return true;
        }

        private static void UnregisterActiveProbe(ProbeRuntime probe)
        {
            if (!IsActiveProbe(probe)) { RetireLifecycleProbe(probe); return; }
            RetireLifecycleProbe(probe);
            EnsureLearningV328AttemptTerminalizedBeforeUnregister(probe, "probeUnregister");
            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }

            if (ActiveProbes.TryGetValue(profileId, out ProbeRuntime current) &&
                ReferenceEquals(current, probe))
            {
                UninstallLifecycleProbe(probe);
            }
            ReconcileCapabilityRetiredProbeConsumer(probe);

            if (ChainHandoffAuthorityGuards.TryGetValue(profileId, out ChainHandoffAuthorityGuard guard) &&
                guard != null && guard.Generation == raidGeneration && guard.SuccessorAuthorityAcquired &&
                (guard.SuccessorProbeEdgeId <= 0 || guard.SuccessorProbeEdgeId == probe.LearnedEdgeId) &&
                (guard.SuccessorProbeChainId <= 0 || probe.TraversalChainId <= 0 || guard.SuccessorProbeChainId == probe.TraversalChainId))
            {
                ChainHandoffAuthorityGuards.Remove(profileId);
                try
                {
                    if (probe.Bot?.Mover != null)
                    {
                        probe.Bot.Mover.SetBotMoverPause("R1-38CF018386FE",@current?.Bot,false);
                    }
                }
                catch
                {
                }
                WriteEvent("chainHandoffGuardReleasedWithSuccessorProbe", probe.Bot, new
                {
                    completedEdgeId = guard.CompletedEdgeId,
                    successorEdgeId = probe.LearnedEdgeId,
                    chainId = guard.ChainId,
                    stage = probe.Stage.ToString(),
                    snapbackDetected = guard.SnapbackLogged,
                    corrections = guard.CorrectionAttempts
                });
            }

            bool chainHandoffPending =
                ChainHandoffAuthorityGuards.TryGetValue(profileId, out ChainHandoffAuthorityGuard pendingGuard) &&
                pendingGuard != null && pendingGuard.Generation == raidGeneration;
            bool learningV375SameChainSuccessor =
                TryGetLearningV375CurrentSameChainSuccessorAfterProbe(
                    probe, out FollowerRouteMission learningV375SuccessorMission,
                    out FollowerRouteMissionStep learningV375SuccessorStep);
            // CF69: after a REAL physical completion the current mission may re-materialize
            // its rolling WalkThrough episode graph in this very frame. A historic completed
            // episode can then disappear from Steps, so V376's lookup by the retiring probe
            // cannot locate its old index even though the canonical cursor has already
            // consumed that exact episode and advanced to an unexecuted successor. Do not
            // confuse this with terminal completion: preserve the existing physical writer
            // ONLY with an exact same-generation/same-mission/same-chain successor and a
            // physically committed predecessor identity. Never invent a successor success.
            if (!learningV375SameChainSuccessor && !chainHandoffPending && probe.Bot != null &&
                probe.TraversalEpisodeId > 0 && probe.TraversalChainId > 0 &&
                FollowerTraversalRouteCursors.TryGetValue(profileId,
                    out FollowerTraversalRouteCursor cf69Cursor) && cf69Cursor != null &&
                cf69Cursor.LearningV375TransactionActive &&
                cf69Cursor.LearningV375MovementGeneration == probe.MovementWriterGeneration &&
                cf69Cursor.LastCompletedEpisodeId == probe.TraversalEpisodeId &&
                cf69Cursor.LearningV375RouteMissionId > 0 &&
                TryResolveLearningV376CursorMission(
                    probe.Bot, cf69Cursor, out FollowerRouteMission cf69Mission) &&
                cf69Mission != null &&
                cf69Mission.MissionId == cf69Cursor.LearningV375RouteMissionId &&
                cf69Mission.CurrentStepIndex > 0 &&
                cf69Mission.CurrentStepIndex < cf69Mission.Steps.Count &&
                FollowerMovementWriterAuthority.GetCurrentGeneration(
                    probe.Bot, out FollowerMovementWriterAuthority.WriterDomain cf69Owner) ==
                    probe.MovementWriterGeneration &&
                cf69Owner == FollowerMovementWriterAuthority.WriterDomain.Traversal)
            {
                FollowerRouteMissionStep cf69Next =
                    cf69Mission.Steps[cf69Mission.CurrentStepIndex];
                if (cf69Next != null && cf69Next.ChainId == probe.TraversalChainId &&
                    cf69Next.EpisodeId > 0 &&
                    cf69Next.EpisodeId != probe.TraversalEpisodeId &&
                    cf69Next.EndBreadcrumbSequence > cf69Cursor.ConsumedBreadcrumbSequence &&
                    (cf69Next.StartBreadcrumbSequence <= 0 ||
                     cf69Next.StartBreadcrumbSequence >= cf69Cursor.ConsumedBreadcrumbSequence))
                {
                    learningV375SameChainSuccessor = true;
                    learningV375SuccessorMission = cf69Mission;
                    learningV375SuccessorStep = cf69Next;
                    WriteEvent("cf69CanonicalSuccessorRetainsPhysicalWriterAfterEpisodeRebase", probe.Bot, new
                    {
                        missionId = cf69Mission.MissionId,
                        successorStepIndex = cf69Mission.CurrentStepIndex,
                        completedEpisodeId = probe.TraversalEpisodeId,
                        completedEdgeId = probe.LearnedEdgeId,
                        successorEpisodeId = cf69Next.EpisodeId,
                        successorEdgeId = cf69Next.EdgeId,
                        successorKind = cf69Next.Kind,
                        chainId = probe.TraversalChainId,
                        generation = probe.MovementWriterGeneration,
                        consumedSequence = cf69Cursor.ConsumedBreadcrumbSequence,
                        successorEndSequence = cf69Next.EndBreadcrumbSequence,
                        traversalSuccessRecordedForSuccessor = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "physicalPredecessorCursorRetainsSameWriterForCanonicalRebasedUnexecutedSuccessor"
                    });
                }
            }
            FollowerRouteMission pendingDebtMission = null;
            FollowerRouteMissionStep pendingDebtStep = null;
            bool pendingTraversalExecutionDebt = !chainHandoffPending && !learningV375SameChainSuccessor &&
                HasLearningV371PendingTraversalExecutionDebt(
                    probe.Bot,
                    out pendingDebtMission,
                    out pendingDebtStep);

            // V4.61 closes the remaining V458 visibility/lifetime split. Failure finalization may
            // have already bound this real Native Jump HOW to the exact RouteMission WHAT, but the
            // generic pending-debt query can still miss it during probe retirement. Resolve the same
            // probe/mission identity again here so the persistent current-body producer is installed
            // before the actuator lease is returned; never fall through to Follow/old-entry retry
            // for one owner-vacuum frame.
            if ((!chainHandoffPending) && !learningV375SameChainSuccessor &&
                !pendingTraversalExecutionDebt &&
                probe.JumpAttempted &&
                TryResolveLearningV376MissionForProbe(
                    probe, out FollowerRouteMission learningV461JumpDebtMission,
                    out int learningV461JumpDebtStepIndex) &&
                learningV461JumpDebtMission?.Steps != null &&
                learningV461JumpDebtStepIndex >= 0 &&
                learningV461JumpDebtStepIndex < learningV461JumpDebtMission.Steps.Count)
            {
                FollowerRouteMissionStep learningV461JumpDebtStep =
                    learningV461JumpDebtMission.Steps[learningV461JumpDebtStepIndex];
                if (learningV461JumpDebtStep != null &&
                    string.Equals(
                        learningV461JumpDebtStep.Kind, "Jump",
                        StringComparison.OrdinalIgnoreCase) &&
                    learningV461JumpDebtStep.LearningV455NativeJumpHowObserved)
                {
                    pendingTraversalExecutionDebt = true;
                    pendingDebtMission = learningV461JumpDebtMission;
                    pendingDebtStep = learningV461JumpDebtStep;
                    WriteEvent("learningV461CurrentBodyJumpDebtRetainedBeforeProbeRetirement", probe.Bot, new
                    {
                        missionId = learningV461JumpDebtMission.MissionId,
                        stepIndex = learningV461JumpDebtStepIndex,
                        edgeId = learningV461JumpDebtStep.EdgeId,
                        body = probe.Player != null
                            ? Vec(probe.Player.Position) : Vec(probe.Bot.Position),
                        retiredProbeStage = probe.Stage.ToString(),
                        traversalGeneration = probe.MovementWriterGeneration,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "exactProbeMissionDebtMaterializesCurrentBodyProducerBeforeActuatorLeaseCanYieldToFollow"
                    });
                }
            }
            if (learningV375SameChainSuccessor)
            {
                FollowerTraversalRouteCursor learningV375Cursor = GetOrCreateLearningV375RouteCursor(probe.Bot);
                long liveGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                    probe.Bot, out FollowerMovementWriterAuthority.WriterDomain liveOwner);
                bool generationPreserved = learningV375Cursor != null &&
                    learningV375Cursor.LearningV375TransactionActive &&
                    ((IsLearningV376CursorCompatibleWithProbe(learningV375Cursor, probe, out _))) &&
                    liveOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                    liveGeneration == probe.MovementWriterGeneration &&
                    liveGeneration == learningV375Cursor.LearningV375MovementGeneration;
                ReturnLearningV375ActuatorBodyAuthority(probe, "intermediateProbeRetired");
                WriteEvent("learningV375IntermediateProbeRetiredWriterPreserved", probe.Bot, new
                {
                    missionId = learningV375SuccessorMission?.MissionId ?? 0,
                    stepIndex = learningV375SuccessorMission?.CurrentStepIndex ?? -1,
                    successorEdgeId = learningV375SuccessorStep?.EdgeId ?? 0,
                    successorKind = learningV375SuccessorStep?.Kind ?? string.Empty,
                    chainId = probe.TraversalChainId,
                    generation = liveGeneration,
                    generationPreserved,
                    retiredProbeEdgeId = probe.LearnedEdgeId,
                    retiredProbeStage = probe.Stage.ToString(),
                    action = "retireActionNodeKeepPersistentRouteWriterAndProducerAlive"
                });
                UpdateLearningV375PersistentExecutablePhysicalRouteTransaction(probe.Bot);
            }
            else if (pendingTraversalExecutionDebt)
            {
                if (!TryRetainLearningV454TraversalEpochForLiveDebt(
                        probe,
                        "pendingTraversalExecutionDebt",
                        pendingDebtMission,
                        pendingDebtStep,
                        null))
                {
                    FollowerMovementWriterAuthority.TransitionTraversalToFollowIfCurrent(
                        probe.Bot,
                        probe.MovementWriterGeneration,
                        "learningV371PendingTraversalExecutionDebt");
                }
                WriteEvent("learningV371PostTraversalSuppressedForTraversalExecutionDebt", probe.Bot, new
                {
                    missionId = pendingDebtMission.MissionId,
                    stepIndex = pendingDebtMission.CurrentStepIndex,
                    edgeId = pendingDebtStep.EdgeId,
                    kind = pendingDebtStep.Kind,
                    retiredProbeEdgeId = probe.LearnedEdgeId,
                    retiredProbeStage = probe.Stage.ToString(),
                    retryAt = pendingDebtMission.NextMoveAttemptAt,
                    action = ("retireActionNodeKeepSameTraversalEpochForPendingDebt")
                });
            }
            else if (!chainHandoffPending)
            {
                if ((PostTraversalIntegrityWatches.TryGetValue(profileId, out PostTraversalIntegrityWatch terminalWatch)) &&
                    terminalWatch != null && terminalWatch.ExpiresAt >= Time.time && terminalWatch.EvaluateEndToEndFollow)
                {
                    if (TryAdoptLearningV374SeamlessTerminalConsumer(
                            probe, terminalWatch, out string learningV374SeamlessConsumerDetail))
                    {
                        WriteEvent("learningV374PostTraversalReprimeSuppressedForExistingConsumer", probe.Bot, new
                        {
                            edgeId = terminalWatch.EdgeId,
                            episodeId = terminalWatch.EpisodeId,
                            chainId = terminalWatch.CompletedChainId,
                            detail = learningV374SeamlessConsumerDetail,
                            action = "integrityWatchRemainsEvaluatorOnlyExistingFreshProducerContinues"
                        });
                    }
                    else
                    {
                    // V4.36: terminal semantic completion is not itself a movement-consumer handoff.
                    // V435 runtime showed WalkThrough physical passage could unregister the probe,
                    // immediately mint PostTraversal/Follow, then discover that the fresh body epoch
                    // was not NavMesh-sampleable for a few frames. That removed the only live forward
                    // producer and appeared as an exit brake. Keep the exact Traversal generation here;
                    // the already-existing V419 fresh Follow / V423 physical-continuation machinery
                    // will atomically replace it once a real downstream consumer exists.
                    bool learningV454RetainAnyTraversalKind =
                        true;
                    bool learningV436LegacyWalkThroughRetention =
                        (string.Equals(
                            probe.TraversalKind ?? probe.RequestedTraversalKind,
                            "WalkThrough", StringComparison.OrdinalIgnoreCase));
                    if ((learningV454RetainAnyTraversalKind || learningV436LegacyWalkThroughRetention) &&
                        TryRetainLearningV454TraversalEpochForLiveDebt(
                            probe,
                            "terminalIntegrityWatchAwaitingConsumer",
                            pendingDebtMission,
                            pendingDebtStep,
                            terminalWatch))
                    {
                        WriteEvent("learningV436TerminalTraversalWriterRetainedPendingConsumer", probe.Bot, new
                        {
                            edgeId = terminalWatch.EdgeId,
                            episodeId = terminalWatch.EpisodeId,
                            chainId = terminalWatch.CompletedChainId,
                            traversalGeneration = terminalWatch.MovementGeneration,
                            releasePosition = Vec(terminalWatch.ReleasePosition),
                            traversalSuccessRecorded = true,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = ("allTraversalKindsRetainPhysicalEpochUntilConcreteConsumerExists")
                        });
                        return;
                    }

                    EndLearningV375PersistentRouteTransaction(probe.Bot, "terminalPostTraversalConsumer");
                    long postGeneration = FollowerMovementWriterAuthority.BeginPostTraversal(
                        probe.Bot,
                        "terminalTraversalConsumer:" + probe.Stage);
                    terminalWatch.MovementGeneration = postGeneration;
                    // Bind a previously armed chase lease to the PostTraversal epoch
                    // actually issued for this completed edge; never sample a later epoch
                    // from a chase timeout callback.
                    if (PostTraversalChaseLeases.TryGetValue(probe.Bot.ProfileId, out PostTraversalChaseLease handoffChaseLease) &&
                        handoffChaseLease != null && handoffChaseLease.EdgeId == probe.LearnedEdgeId)
                    {
                        handoffChaseLease.PostTraversalWriterGeneration = postGeneration;
                    }
                    terminalWatch.ReleasePosition = probe.Player != null ? probe.Player.Position : probe.Bot.Position;
                    bool freshPostTraversalPathPrimed = TryPrimeFreshFollowPathAfterAuthorityReset(
                        probe.Bot, "postTraversalConsumerInstalled", "post-traversal-fresh-epoch",
                        out string freshPostTraversalPathDetail,
                        preserveLocomotion: true);
                    if ((freshPostTraversalPathPrimed))
                    {
                        MarkLearningV352PostTraversalConsumerPathProven(
                            probe.Bot, "post-traversal-fresh-epoch", postGeneration);
                    }
                    WriteEvent("learningV351PostTraversalFreshPathPrime", probe.Bot, new
                    {
                        edgeId = terminalWatch.EdgeId,
                        primed = freshPostTraversalPathPrimed,
                        detail = freshPostTraversalPathDetail,
                        releasePosition = Vec(terminalWatch.ReleasePosition),
                        action = "replaceRetiredPreTraversalPathBeforePostTraversalFollowWrites"
                    });

                    bool postTraversalAuthorityRetained =
                        (freshPostTraversalPathPrimed);
                    if (!postTraversalAuthorityRetained)
                    {
                        FollowerMovementWriterAuthority.TransitionPostTraversalToFollowExact(probe.Bot, postGeneration, "learningV371PostTraversalFreshPathUnavailable");
                        terminalWatch.MovementGeneration =
                            FollowerMovementWriterAuthority.GetCurrentGeneration(probe.Bot, out _);
                        ArmFollowReacquireAfterAuthorityReset(
                            probe.Bot,
                            "learningV371PostTraversalFreshPathUnavailable");
                        WriteEvent("learningV371PostTraversalAuthorityReleasedWithoutFreshPath", probe.Bot, new
                        {
                            edgeId = terminalWatch.EdgeId,
                            episodeId = terminalWatch.EpisodeId,
                            chainId = terminalWatch.CompletedChainId,
                            rejectedPostTraversalGeneration = postGeneration,
                            followGeneration = terminalWatch.MovementGeneration,
                            detail = freshPostTraversalPathDetail,
                            action = "neverHoldPostTraversalWriterWithoutFreshConsumerPath"
                        });
                    }
                    else
                    {
                        WriteEvent("learningV343PostTraversalConsumerAuthorityInstalled", probe.Bot, new
                        {
                            edgeId = terminalWatch.EdgeId,
                            episodeId = terminalWatch.EpisodeId,
                            chainId = terminalWatch.CompletedChainId,
                            previousTraversalGeneration = probe.MovementWriterGeneration,
                            postTraversalGeneration = postGeneration,
                            releasePosition = Vec(terminalWatch.ReleasePosition),
                            action = "followWritesRunInsidePostTraversalGenerationUntilIntegrityCloses"
                        });
                    }
                    }
                }
                else
                {
                    if ((TryCommitLearningV454TerminalConsumerAfterProbeRemoval(
                            probe,
                            "traversalProbeRetired:" + probe.Stage,
                            out _)))
                    {
                        return;
                    }
                    EndLearningV375PersistentRouteTransaction(probe.Bot, "traversalProbeRetired:" + probe.Stage);
                    FollowerMovementWriterAuthority.TransitionTraversalToFollowIfCurrent(
                        probe.Bot,
                        probe.MovementWriterGeneration,
                        "traversalProbeRetired:" + probe.Stage);
                }
            }
        }

        public static void Initialize()
        {
            if (initialized)
            {
                return;
            }

            BotOwnerUpdateHub.Register(UpdateHubSubscriptionId, OnBotOwnerUpdate);
            initialized = true;
        }

        public static bool IsRaidActive => raidActive;

        public static void EnsureRaidStarted(string newLocationId)
        {
            string normalizedLocation = string.IsNullOrWhiteSpace(newLocationId) ? "unknown" : newLocationId;
            if (raidActive && string.Equals(locationId, normalizedLocation, StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            StartRaid(normalizedLocation);
        }

