                    activeEdges = LearnedTraversalEdges.Count,
                    nativeProvenEdges = LearnedTraversalEdges.Count(IsLearningV3NativeProvenEdge),
                    activeExperienceRecords = TraversalExperiences.Count
                });
                LogInfo(($"LearningV3.2 NativeEntry: loaded {LearnedTraversalEdges.Count(IsLearningV3NativeProvenEdge)} Native-Proven edge(s); legacy mixed persistence remains bypassed."));
            }
            if ((LearningV354ActionProfiles.Count == 0))
            {
                LoadLearningV354TraversalProfileStore();
            }
            {
                PrewarmLearningV331TraversalColdPaths();
            }
            ResetBreadcrumbState();
            AttachLocalPlayer(FollowerEnvironment.LocalPlayer);
            Logger.LogRuntimeInfo($"[R9 Runtime] traversal raid generation {raidGeneration} started at {locationId}");
        }

        private static void PrewarmLearningV331TraversalColdPaths()
        {
            long startedAt = BeginTraversalPerfSample();
            int jitPrepared = 0;
            int jitFailed = 0;
            try
            {
                // Persistence has already been loaded above. This intentionally performs no file I/O
                // and uses no live Player/Bot object. The first visible WalkThrough in the V3.30 trace
                // shared one frame with the first local-player Vault finalization, so prewarm both the
                // follower corridor path and the player-capture/candidate path instead of treating the
                // 1-2 ms corridor builder as the whole hitch.
                List<Vector3> dummy = new List<Vector3>
                {
                    Vector3.zero,
                    new Vector3(0.48f, 0f, 0f),
                    new Vector3(0.96f, 0.05f, 0.12f)
                };
                List<Vector3> dense = BuildPrecisionWalkThroughCorridor(
                    null, dummy, dummy[0], dummy[dummy.Count - 1]);
                TryValidateWalkThroughPolyline(
                    null, dummy[0], dense, out _, out _, out _);
                GetFlatDirection(dummy[2] - dummy[0]);
                GetPlanarDistance(dummy[0], dummy[2]);

                // RuntimeHelpers.PrepareMethod moves CLR/JIT compilation of first-use hot methods to
                // raid initialization without executing gameplay side effects. It is best-effort because
                // some runtimes may reject PrepareMethod; the ordinary pure-math warmup above remains a
                // safe fallback. No thresholds, samples, persistence data or movement state are changed.
                string[] hotMethods =
                {
                    nameof(BuildPrecisionWalkThroughCorridor),
                    nameof(TryValidateWalkThroughPolyline),
                    nameof(BuildLocalVaultMotionProfile),
                    nameof(CompleteLocalPlayerVaultDemonstration),
                    nameof(RememberLearnedTraversalEdge),
                    nameof(PrepareSettledAnchorsForLearnedEdge),
                    nameof(RegisterTraversalEpisodeForEdge),
                    nameof(BeginWalkThroughProbe)
                };
                HashSet<string> hotNames = new HashSet<string>(hotMethods, StringComparer.Ordinal);
                foreach (MethodInfo method in typeof(FollowerTraversalTestRuntime).GetMethods(
                             BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic))
                {
                    if (!hotNames.Contains(method.Name) || method.ContainsGenericParameters)
                    {
                        continue;
                    }
                    try
                    {
                        System.Runtime.CompilerServices.RuntimeHelpers.PrepareMethod(method.MethodHandle);
                        jitPrepared++;
                    }
                    catch
                    {
                        jitFailed++;
                    }
                }
            }
            catch (Exception ex)
            {
                WriteEvent("learningV331TraversalColdPathPrewarmFailed", null, new
                {
                    error = ex.GetType().Name + ":" + ex.Message,
                    jitPrepared,
                    jitFailed,
                    fileIo = false
                });
                return;
            }

            double elapsedMs = (System.Diagnostics.Stopwatch.GetTimestamp() - startedAt) * 1000.0 /
                               System.Diagnostics.Stopwatch.Frequency;
            WriteEvent("learningV331TraversalColdPathPrewarmed", null, new
            {
                elapsedMs,
                jitPrepared,
                jitFailed,
                fileIo = false,
                persistenceAlreadyLoaded = true,
                phase = "raidInitializationAfterPersistenceLoad"
            });
        }

        public static void EndRaid(string reason)
        {
            foreach (ProbeRuntime probe in ActiveProbes.Values.ToArray())
            {
                ReleaseProbeForLifecycle(probe, reason ?? "raidEnd");
            }
            ClearLifecycleProbes();

            learningV337PersistenceFlushInProgress = (raidActive);
            if ((raidActive))
            {
                EmitLearningV2FreshSessionSummary(reason ?? "raidEnd");
                {
                    if ((learningV337NativeProvenDirty))
                    {
                        WriteEvent("learningV337NativeProvenRaidEndFlush", null, new
                        {
                            edges = LearnedTraversalEdges.Count(edge =>
                            IsLearningV3NativeProvenEdge(edge) ||
                            IsLearningV344HistoricalWalkThroughSemanticAuthority(edge)),
                            liveFrameWritesSuppressed = true,
                            reason = reason ?? "raidEnd"
                        });
                    }
                    SaveLearningV31NativeProvenStore();
                }
                {
                    if ((learningV322SkillEvidenceDirty))
                    {
                        WriteEvent("learningV335SkillEvidenceRaidEndFlush", null, new
                        {
                            records = LearningV322SkillEvidence.Count,
                            liveFrameWritesSuppressed = true,
                            reason = reason ?? "raidEnd"
                        });
                    }
                    SaveLearningV322PersistentSkillEvidenceStore();
                }
                {
                    SaveLearningV354TraversalProfileStore();
                }
            }
            ;
            ;
            DetachLocalPlayer();
            if (traversalExperienceDirty && false)
            {
                SaveTraversalExperience();
            }
            learningV337PersistenceFlushInProgress = false;
            CloseDiagnostics(reason ?? "raidEnd");
            FollowerRuntimeNavMeshLinks.ResetRaid();
            DiagnosticFollowers.Clear();
            CF75FollowPhysicalWatches.Clear();
            DiagnosticNextEmitAt.Clear();
            traversalExperienceDirty = false;
            nextTraversalExperienceSaveAt = 0f;
            learningV322SkillEvidenceDirty = false;
            nextLearningV322SkillEvidenceSaveAt = 0f;
            learningV354TraversalProfilesDirty = false;
            learningV337NativeProvenDirty = false;
            learningV337TraversalLinksDirty = false;
            learningV337PersistenceFlushInProgress = false;
            loadedTraversalSanitizerRevision = 0;
