        public static void Shutdown()
        {
            EndRaid("pluginShutdown");
            if (initialized)
            {
                BotOwnerUpdateHub.Unregister(UpdateHubSubscriptionId);
                initialized = false;
            }
        }

        public static void TickMainThread()
        {
            // Stage1 file-only shared F12 Debug authority. Do not keep writing JSONL after disable.
            if (BotTraversalSharedSettings.Present)
            {
                if (!BotTraversalSharedSettings.DebugLogEnabled && diagnosticsEnabled)
                    CloseDiagnostics("disabledByBotTraversalF12");
                else if (BotTraversalSharedSettings.DebugLogEnabled && raidActive && !diagnosticsEnabled)
                    TryOpenDiagnostics("enabledByBotTraversalF12", out _);
            }
            // R9 self-heal: Fika can enter a playable local raid through a path where the normal
            // BotsController first-player callback is delayed. Do not leave the entire traversal
            // recorder/executor dormant just because that lifecycle edge was missed.
            if (!raidActive)
            {
                GameWorld world = Singleton<GameWorld>.Instance;
                Player candidate = FollowerEnvironment.LocalPlayer;
                if (BossPlayers.Instance != null &&
                    FollowerEnvironment.IsActive &&
                    world != null &&
                    IsLivePlayer(candidate))
                {
                    EnsureRaidStarted(world.LocationId);
                }
            }

            if (!raidActive)
            {
                return;
            }

            Player localPlayer = FollowerEnvironment.LocalPlayer;
            if (!ReferenceEquals(observedLocalPlayer, localPlayer))
            {
                AttachLocalPlayer(localPlayer);
            }

            if (IsLivePlayer(localPlayer))
            {
                UpdateNaturalDropDownCandidate(localPlayer);
                CaptureBreadcrumb(localPlayer, false);
                TryCapturePendingPlayerAnimatorHint(localPlayer);
                CaptureActivePlayerVaultMotion(localPlayer);
                TryFinishLocalPlayerVault(localPlayer);
                TryFinishLocalPlayerJumpShortcut(localPlayer);
            }

            foreach (ProbeRuntime probe in ActiveProbes.Values.ToArray())
            {
                if (probe != null && !IsLiveBot(probe.Bot))
                {
                    ReleaseProbeForLifecycle(probe, "selectedFollowerUnavailable");
                }
            }

            TickCapabilityJumpPreparationFrames();

            if (traversalExperienceDirty && Time.time >= nextTraversalExperienceSaveAt)
            {
                SaveTraversalExperience();
            }
            ;
        }

        public static bool ToggleDiagnostics(out string message)
        {
            if (diagnosticsEnabled)
            {
                string stoppedFile = currentFilePath;
                CloseDiagnostics("consoleToggle");
                message = string.IsNullOrEmpty(stoppedFile)
                    ? "Traversal diagnostics stopped."
                    : $"Traversal diagnostics stopped: {stoppedFile}";
                return true;
            }

            if (!CanUseRaidCommands(out message))
            {
                return false;
            }

            if (!TryOpenDiagnostics("consoleToggle", out string openError))
            {
                message = $"Traversal diagnostics could not start: {openError}";
                return false;
            }

            message = $"Traversal diagnostics started: {currentFilePath}";
            return true;
        }

        public static bool TryStartNearestVaultProbe(out string message)
        {
            if (!CanUseRaidCommands(out message))
            {
                return false;
            }

            Player localPlayer = FollowerEnvironment.LocalPlayer;
            Vector3 requestedDirection = GetFlatDirection(localPlayer.MovementContext?.PlayerRealForward ?? localPlayer.LookDirection);
            if (requestedDirection.sqrMagnitude < 0.5f)
            {
                message = "Vault probe refused: the local player's horizontal look direction is invalid.";
                return false;
            }

            BotOwner bot = FindNearestEligibleFollower(localPlayer, out string selectionFailure);
            if (bot == null)
            {
                message = $"Vault probe refused: {selectionFailure}";
                return false;
            }

            return TryStartProbeForBot(
                bot,
                requestedDirection,
                "console",
                0,
                "Vault",
                "vaultProbe",
                out message);
        }


        public static bool TryStartNearestJumpProbe(out string message)
        {
            if (!CanUseRaidCommands(out message))
            {
                return false;
            }

            Player localPlayer = FollowerEnvironment.LocalPlayer;
            Vector3 requestedDirection = GetFlatDirection(localPlayer.MovementContext?.PlayerRealForward ?? localPlayer.LookDirection);
            if (requestedDirection.sqrMagnitude < 0.5f)
            {
                message = "Jump probe refused: the local player's horizontal look direction is invalid.";
                return false;
            }

            BotOwner bot = FindNearestEligibleFollower(localPlayer, out string selectionFailure);
            if (bot == null)
            {
                message = $"Jump probe refused: {selectionFailure}";
                return false;
            }

            return TryStartProbeForBot(
                bot,
                requestedDirection,
                "consoleJump",
                0,
                "Jump",
                "jumpProbe",
                out message);
        }


        private static bool TryStartProbeForBot(
            BotOwner bot,
            Vector3 requestedDirection,
            string requestSource,
            int learnedEdgeId,
            string requestedTraversalKind,
            string diagnosticReason,
            out string message)
        {
            message = string.Empty;
            if(IsCapabilityReturnInProgress(bot)){message="returnDriverOwnsCurrentUnfinishedEntry";return false;}
            if (!TryAdmitCapabilitySequenceProbe(bot,requestSource,learnedEdgeId,requestedTraversalKind,out message)) return false;
            if (!TryPrepareCapabilityAutomaticProbeMission(bot,requestSource,learnedEdgeId,out message))
            {
                if(ShouldEmitDiagnostic("capabilityAutomaticProbeAdmissionBlocked",bot,.5f))
                    WriteEvent("capabilityAutomaticProbeAdmissionBlocked",bot,new{requestSource,learnedEdgeId,requestedTraversalKind,message,nativeSuccessRecorded=false});
                return false;
            }
            if (IsCapabilityRecoveryPending(bot)) { message="sequenceTerminalRecoveryOwnsMotion"; return false; }
            requestedDirection = GetFlatDirection(requestedDirection);
            if (TryGetActiveProbe(bot, out ProbeRuntime existingProbe))
            {
                message = $"This follower already has an active traversal probe: {FormatProbeStatus(existingProbe)}";
                return false;
            }

            if (requestedDirection.sqrMagnitude < 0.5f)
            {
                message = "Vault probe refused: requested direction is invalid.";
                return false;
            }

            if (TickCapabilityPortalWait(bot)) { message="sharedPortalQueueWaiting"; return false; }
            if (!ValidateProbePreconditions(bot, out string preconditionFailure))
            {
                message = $"Vault probe refused for {GetBotName(bot)}: {preconditionFailure}";
                return false;
            }

            bool requestedJump = string.Equals(requestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase);
            bool requestedWalkThrough = string.Equals(requestedTraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            if(requestedJump&&!HasCapabilityFailureStrategy(bot)&&ShouldDeferCapabilityJumpProbe(bot,learnedEdgeId,out message))return false;
            Vector3 walkThroughEntry = default;
            Vector3 walkThroughRawEntry = default;
            Vector3 walkThroughTarget = default;
            if (requestedWalkThrough)
            {
                string profileId = bot.ProfileId ?? string.Empty;
                if (learnedEdgeId <= 0 ||
                    string.IsNullOrEmpty(profileId) ||
                    !LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment walkCommitment) ||
                    walkCommitment.EdgeId != learnedEdgeId ||
                    !string.Equals(walkCommitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    message = $"WalkThrough probe refused for {GetBotName(bot)}: matching learned commitment is unavailable.";
                    return false;
                }

                // V1.3.21 ownership model: approach is judged against the same projected/NavMesh
                // anchor that latched the commitment. RawEntry is only crossing geometry; using it
                // as a second entry gate made a probe arm at the projected point and immediately
                // abort as 1.2-2.3m "too far" from the player's transient raw sample.
                walkThroughEntry = walkCommitment.Entry;
                walkThroughRawEntry = IsFinite(walkCommitment.RawEntry) ? walkCommitment.RawEntry : walkCommitment.Entry;
                walkThroughTarget = IsFinite(walkCommitment.RawExit) ? walkCommitment.RawExit : walkCommitment.Exit;
            }
            else if (!requestedJump && learnedEdgeId <= 0 &&
                     !EnsureVaultingComponent(bot.GetPlayer, out string componentFailure))
            {
                // Native vaulting is now diagnostic-only. Automatic learned Vault/Climb never needs
                // Scanner/VaultingComponent initialization before Assisted Replay.
                message = $"Vault probe could not initialize {GetBotName(bot)}: {componentFailure}";
                return false;
            }

            bool diagnosticsAutoStarted = false;
            if (!diagnosticsEnabled)
            {
                diagnosticsAutoStarted = TryOpenDiagnostics(
                    string.IsNullOrWhiteSpace(diagnosticReason) ? "vaultProbe" : diagnosticReason,
                    out _);
            }

            ProbeRuntime probe = new ProbeRuntime(ProbeStage.Aligning)
            {
                Generation = raidGeneration,
                Bot = bot,
                Player = bot.GetPlayer,
                RequestedAt = Time.time,
                StageStartedAt = Time.time,
                OwnershipLeaseExpiresAt = Time.time + TraversalOwnershipLeaseSeconds,
                AlignStableSince = -1f,
                RequestedDirection = requestedDirection,
                RequestSource = string.IsNullOrWhiteSpace(requestSource) ? "unknown" : requestSource,
                LearnedEdgeId = learnedEdgeId,
                RequestedTraversalKind = string.IsNullOrWhiteSpace(requestedTraversalKind) ? "Vault" : requestedTraversalKind,
                StartPosition = bot.Position,
                PreviousInputDirection = bot.GetPlayer.InputDirection,
                PreviousMovementDirection = bot.GetPlayer.MovementContext.MovementDirection,
                LastState = bot.GetPlayer.CurrentStateName,
                LastSupportedAt = Time.time,
                WalkThroughEntry = walkThroughEntry,
                WalkThroughRawEntry = walkThroughRawEntry,
                WalkThroughRawExit = walkThroughTarget,
                WalkThroughTarget = walkThroughTarget,
                PreviousSprinting = bot.Mover?.Sprinting == true,
                PreviousRunning = bot.Mover?.IsMoving == true &&
                                  bot.GetPlayer?.MovementContext?.ClampedSpeed > 0.55f,
                TraversalLastMeaningfulPosition = bot.Position,
                TraversalLastMeaningfulProgressAt = Time.time
            };
            if (learnedEdgeId > 0)
            {
                string probeProfileId = bot.ProfileId ?? string.Empty;
                if (!string.IsNullOrEmpty(probeProfileId) &&
                    LearnedTraversalCommitments.TryGetValue(probeProfileId, out LearnedTraversalCommitment probeCommitment) &&
                    probeCommitment != null && probeCommitment.EdgeId == learnedEdgeId)
                {
                    // Freeze the oriented traversal mission at probe start. V3.19 transient
                    // instances already own new world-space anchors, so they must never be refreshed
                    // from the template edge's historical coordinates.
                    if (!IsLearningV319TransientSkillTransfer(probeCommitment))
