                        probe.RollingApproachLastProgressAt = Time.time;
                        probe.RollingApproachNextDirectPointAt = Time.time;
                        EmitLearningV346PhysicalNavigationEpochSnapshot(probe, "rollingApproachAcquired");
                        WriteEvent("traversalRollingApproachStarted", bot, new
                        {
                            edgeId = learnedEdgeId,
                            kind = probe.RequestedTraversalKind,
                            target = Vec(rollingTarget),
                            distance = rollingDistance,
                            previousSprinting = probe.PreviousSprinting,
                            previousRunning = probe.PreviousRunning
                        });
                        if(requestedJump&&probe.NativeStrategySelected&&!probe.AssistedStrategySelected)
                            TryCommitCapabilityJumpAtDispatch(probe,rollingCommitment);
                        message = $"Rolling {probe.RequestedTraversalKind} handoff requested for {GetBotName(bot)} source={probe.RequestSource}."
                            + (diagnosticsAutoStarted ? $" Diagnostics started: {currentFilePath}" : string.Empty);
                        LogInfo(message);
                        return true;
                    }
                }

                if (!TryBeginAssistedTraversalReplay(probe, "learnedExecutor", out string assistedStartFailure))
                {
                    WriteEvent("learnedTraversalExecutorStartFailed", bot, new
                    {
                        edgeId = learnedEdgeId,
                        kind = probe.RequestedTraversalKind,
                        reason = assistedStartFailure
                    });

                    if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "learnedExecutorStartFailed"))
                    {
                        FinishProbeWithoutReanchor(
                            probe,
                            "learnedExecutorStartFailed",
                            assistedStartFailure + "; deterministic RawExit teleport was unavailable");
                    }
                }

                message = $"Learned {probe.RequestedTraversalKind} traversal requested for {GetBotName(bot)} source={probe.RequestSource}."
                    + (diagnosticsAutoStarted ? $" Diagnostics started: {currentFilePath}" : string.Empty);
                LogInfo(message);
                return true;
            }

            string probeName = requestedWalkThrough ? "WalkThrough probe" : "Vault probe";
            message = $"{probeName} requested for {GetBotName(bot)} source={probe.RequestSource}."
                + (diagnosticsAutoStarted ? $" Diagnostics started: {currentFilePath}" : string.Empty);
            LogInfo(message);
            return true;
        }

        public static string GetStatus()
        {
            string diagnosticStatus = diagnosticsEnabled
                ? $"diagnostics=on file={currentFilePath}"
                : "diagnostics=off";
            PruneLearnedTraversalEdges();
            diagnosticStatus += $" learnedEdges={LearnedTraversalEdges.Count} experienceRecords={TraversalExperiences.Count}";
            ProbeRuntime[] active = ActiveProbes.Values
                .Where(probe => probe != null && probe.Generation == raidGeneration)
                .ToArray();
            if (active.Length == 0)
            {
                return $"Traversal test: no active traversal probe; {diagnosticStatus}.";
            }

            string sample = string.Join(" | ", active.Take(3).Select(FormatProbeStatus));
            if (active.Length > 3)
            {
                sample += $" | +{active.Length - 3} more";
            }
            return $"Traversal test: activeProbes={active.Length}; {sample}; {diagnosticStatus}.";
        }

        public static bool TryAbortProbe(out string message)
        {
            int cancelledReturns=0;
            foreach(var pair in FollowerRouteMissions.ToArray())
                if(IsCapabilityRouteRetryReturning(pair.Value)||IsCapabilityFullRouteReplay(pair.Value))
                {
                    pair.Value.Lifecycle.CancelFullRetry();pair.Value.RouteRetry=null;cancelledReturns++;
                    if(!ActiveProbes.Values.Any(p=>p?.Bot?.ProfileId==pair.Key))RemoveLifecycleMission(pair.Key,"manualAbort",pair.Value);
                }

            ProbeRuntime[] active = ActiveProbes.Values
                .Where(probe => probe != null && probe.Generation == raidGeneration)
                .Distinct()
                .ToArray();
            if (active.Length == 0)
            {
                message = cancelledReturns>0?"Full route retry cancelled.":"No active traversal probe or safety hold.";
                return cancelledReturns>0;
            }

            int released = 0;
            int deferred = 0;
            foreach (ProbeRuntime probe in active)
            {
                if (probe == null)
                {
                    continue;
                }

                if (!IsLiveBot(probe.Bot))
                {
                    ReleaseProbeForLifecycle(probe, "consoleAbortUnavailableFollower");
                    released++;
                    continue;
                }

                EPlayerState currentState = probe.Player.CurrentStateName;
                if (IsProbeTraversalState(currentState))
                {
                    // Never rip the capsule out from underneath an actual ClimbOver/ClimbUp frame.
                    // Clear the animator request now, but let EFT's native state Exit restore the
                    // capsule; the existing AbortAfterLanding path releases ownership immediately after.
                    try
                    {
                        probe.Player.MovementContext?.MovementContextPlayerAnimatorSetDoVault("R1-606453A42E3F",@probe?.Bot,false);
                        probe.Player.MovementContext?.MovementContextPlayerAnimatorSetDoClimb("R1-E97AB32C04E1",@probe?.Bot,false);
                    }
                    catch
                    {
                    }
                    probe.AbortAfterLanding = true;
                    deferred++;
                    WriteEvent("vaultProbeAbortDeferred", probe.Bot, new
                    {
                        state = currentState.ToString(),
                        scope = "allActive"
                    });
                    continue;
                }

                ForceReleaseTraversalProbe(probe, "consoleAbortAll");
                released++;
            }

            message = $"Traversal abort applied to all active followers: released={released}, deferredNative={deferred}.";
            return true;
        }

        private static long ResetFollowerMovementAuthorityForTeleport(
            BotOwner bot,
            bool preserveRouteMission,
            bool preserveActiveCommitment,
            string reason)
        {
            if (bot == null)
            {
                return 0;
            }

            ClearCapabilityRouteWorkForTeleport(bot,reason);
            preserveRouteMission=false;preserveActiveCommitment=false;
            long teleportGeneration = FollowerMovementWriterAuthority.BeginTeleport(
                bot,
                "teleportReset:" + (string.IsNullOrWhiteSpace(reason) ? "unspecified" : reason));

            string profileId = bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId))
            {
                if (!preserveActiveCommitment)
                {
                    LearnedTraversalCommitments.Remove(profileId);
                }
                ProvisionalWalkThroughReservations.Remove(profileId);
                NavigationRecoveryTraversalAnchors.Remove(profileId);
                BreadcrumbFollowCommitments.Remove(profileId);
                PostTraversalEntryQuarantines.Remove(profileId);
                BreadcrumbBarrierDetourUntil.Remove(profileId);
                FollowPathBaselines.Remove(profileId);
                FollowPathSanitySamples.Remove(profileId);
                FollowRejectLeases.Remove(profileId);
                PostTraversalIntegrityWatches.Remove(profileId);
                PhysicalNavigationEpochHandoffs.Remove(profileId);
                if (!preserveRouteMission)
                {
                    // Explicit reset retires debt before protected normal-failure removal.
                    if(FollowerRouteMissions.TryGetValue(profileId,out var cancelled)&&cancelled!=null)
                    {
                        cancelled.Lifecycle.Retire();
                        WriteEvent("capabilityFullRouteRetryCancelled",bot,new{missionId=cancelled.MissionId,reason,
                            source="explicitTeleportReset",nativeSuccessRecorded=false});
                    }
                    RemoveLifecycleMission(profileId, "ResetFollowerMovementAuthorityForTeleport",cancelled);
                }
            }

            if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                bot, FollowerMovementWriterAuthority.WriterDomain.Teleport, teleportGeneration,
                out FollowerMovementWriterAuthority.WriteScope teleportResetScope,
                out string teleportResetTicketReason))
            {
                WriteEvent("v2TeleportResetOriginRejected", bot, new
                {
                    reason = teleportResetTicketReason,
                    originGeneration = teleportGeneration,
                    action = "skipUnownedTeleportCleanup"
                });
                return 0;
            }
            using (teleportResetScope)
            try
            {
                MovementContext movement = bot.GetPlayer?.MovementContext;
                movement?.MovementContextPlayerAnimatorSetDoVault("R1-73522FE3FF3F",@bot,false);
                movement?.MovementContextPlayerAnimatorSetDoClimb("R1-DA93DB70FC68",@bot,false);
                if (bot.GetPlayer != null)
                {
                    bot.GetPlayer.SetPlayerInputDirection("R1-DCF27B541674",@bot,Vector2.zero);
                }
                if (movement != null)
                {
                    movement.SetMovementContextMovementDirection("R1-48077D33608D",@bot,Vector2.zero);
                    movement.TryMovementContextApplyApproachMotion("R1-0A91D7A8B9FE",@bot,Vector3.zero,Mathf.Max(0.001f, Time.deltaTime));
                }
                if (bot.Mover != null)
                {
                    bot.Mover.SetBotMoverPause("R1-5A533CF9C10A",@bot,false);
                    bot.Mover.BotMoverSprint("R1-7253E4961DCE",@bot,false,false);
                    bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-121F42DBE388",@bot);
                    bot.Mover.BotMoverStop("R1-07DCA9A78870",@bot);
                }
                bot.BotOwnerStopMove("R1-CF89577FBD8E",@bot);
                bot.GoToSomePointData?.BotGoToPointDataSetPoint("R1-2FDC0C6803CE",@bot,bot.Position);
                bot.GoToSomePointData?.BotGoToPointDataUpdateToGo("R1-6BFF756DE7A2",@bot,false);
            }
            catch
            {
                // Teleport recovery remains fail-open if one optional movement writer was disposed.
            }

            // LearningV4.31: never use the ordinary JumpLanding/general hard recovery during
            // teleport preparation because both recovery paths re-arm forward locomotion. Keep
            // the Teleport generation scoped while neutralizing any residual Player state.
            bool locomotionQuiesced = false;
            string locomotionQuiescenceDetail = "teleportOriginNotCurrent";
            if (FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                bot, FollowerMovementWriterAuthority.WriterDomain.Teleport, teleportGeneration,
                out FollowerMovementWriterAuthority.WriteScope teleportQuiesceScope,
                out locomotionQuiescenceDetail))
            {
                using (teleportQuiesceScope)
                {
                    locomotionQuiesced = TryQuiesceFollowerLocomotionForTeleport(
                        bot, reason + ":preTeleportQuiescence", out locomotionQuiescenceDetail,teleportGeneration);
                }
            }

            WriteEvent("teleportMovementAuthorityReset", bot, new
            {
                reason,
                preserveRouteMission,
                preserveActiveCommitment,
                locomotionQuiesced,
                locomotionQuiescenceDetail,
                forwardIntentInjected = false
            });
            return teleportGeneration;
        }

        private static void ArmLearningV364PhysicalNavigationEpochHandoff(
            BotOwner bot,
            int edgeId,
            int episodeId,
            int chainId,
            Vector3 entry,
            Vector3 exit,
            Vector3 anchor,
            string source)
        {
            if ((bot?.Mover == null) ||
                string.IsNullOrEmpty(bot.ProfileId) || !IsFinite(anchor))
            {
                return;
            }

            long movementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain movementOwner);
            PhysicalNavigationEpochHandoff handoff = new PhysicalNavigationEpochHandoff
            {
                Generation = raidGeneration,
                SourceEdgeId = edgeId,
                EpisodeId = episodeId,
                ChainId = chainId,
                Entry = entry,
                Exit = exit,
                PhysicalAnchor = anchor,
                ArmedAt = Time.time,
                SourceMovementGeneration = movementGeneration,
                SourceMovementOwner = movementOwner.ToString(),
                Source = source ?? "unknown",
                FreshConsumerPathObserved = false,
                FreshConsumerPathGeneration = 0,
                FreshConsumerPathSource = null,
                NativeBookkeepingSynchronized = false
            };
            PhysicalNavigationEpochHandoffs[bot.ProfileId] = handoff;

            bool scrubbed = TryScrubLearningV364NativeMoverEpochAnchor(
                bot, anchor, "arm:" + handoff.Source, out string scrubDetail);
            handoff.InitialAnchorScrubbed = scrubbed;
            handoff.InitialAnchorScrubDetail = scrubDetail;

            WriteEvent("learningV364PhysicalNavigationEpochHandoffArmed", bot, new
            {
                edgeId,
                episodeId,
                chainId,
                entry = IsFinite(entry) ? (object)Vec(entry) : null,
                exit = IsFinite(exit) ? (object)Vec(exit) : null,
                physicalAnchor = Vec(anchor),
                movementOwner = movementOwner.ToString(),
                movementGeneration,
                source = handoff.Source,
                initialAnchorScrubbed = scrubbed,
                scrubDetail,
                action = "physicalBodyEpochRemainsAuthoritativeUntilFreshConsumerPathAndNativeMoverBookkeepingAgree"
            });
        }

        private static bool TryScrubLearningV364NativeMoverEpochAnchor(
            BotOwner bot,
            Vector3 anchor,
            string source,
            out string detail)
        {
            detail = "unavailable";
            if ((bot?.Mover == null) || !IsFinite(anchor))
            {
                return false;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (generation <= 0 || owner == FollowerMovementWriterAuthority.WriterDomain.Unknown)
            {
                detail = "noCurrentMovementOwner";
                return false;
            }

            try
            {
                if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                    bot, owner, generation,
                    out FollowerMovementWriterAuthority.WriteScope epochScrubScope, out detail))
                    return false;
                using (epochScrubScope)
                {
                    // State-only epoch scrub. Do NOT call Teleport, method_10, SetPlayerToNavMesh,
                    // CharacterController.Move, or any other body relocation writer here.
                    bot.Mover.SetBotMoverPositionOnWayInner("R1-9B0F994D1A8D",@bot,anchor);
                    bot.Mover.SetBotMoverPrevSuccessLinkedFrom_1("R1-0B9EF795636C",@bot,anchor);
                    bot.Mover.SetBotMoverPrevPosLinkedTime_1("R1-E6C2FF653EFE",@bot,Time.time);
                }
                detail = "scrubbed:" + owner + ":generation=" +
                         generation.ToString(CultureInfo.InvariantCulture) +
                         ":source=" + (source ?? "unknown");
                return true;
            }
            catch (Exception ex)
            {
                detail = "scrubFailed:" + ex.GetType().Name;
                return false;
            }
        }

        internal static bool TryCommitLearningV432RelocationNativeMoverEpoch(
            BotOwner bot,
            Vector3 anchor,
            string source,
            out string detail)
        {
            detail = "disabled";
            ;

            // Relocation is a stronger boundary than a traversal handoff: even when no V364
            // PhysicalNavigationEpochHandoff object exists, EFT BotMover.method_12 can still use
            // PrevSuccessLinkedFrom_1 after AllowTeleport is consumed. Rebase both native link
            // anchors atomically while Teleport owns movement; this changes bookkeeping only and
            // never relocates the body itself.
            bool scrubbed = TryScrubLearningV364NativeMoverEpochAnchor(
                bot, anchor, "learningV432Relocation:" + (source ?? "unknown"), out detail);
            if (scrubbed)
            {
                WriteEvent("learningV432RelocationNativeMoverEpochCommitted", bot, new
                {
                    anchor = Vec(anchor),
                    source = source ?? string.Empty,
                    detail,
                    bodyRelocated = false,
                    action = "positionOnWayAndPrevLinkedShareRelocatedPhysicalEpochBeforeTeleportAuthorityRelease"
                });
            }
            return scrubbed;
        }

        private static bool TryProveLearningV364PhysicalNavigationEpochFromAcceptedPath(
            BotOwner bot,
            string source,
            out string detail)
        {
            detail = "noPendingEpoch";
            if ((bot?.Mover == null) ||
                string.IsNullOrEmpty(bot.ProfileId) ||
                !PhysicalNavigationEpochHandoffs.TryGetValue(
                    bot.ProfileId, out PhysicalNavigationEpochHandoff handoff) ||
                handoff == null || handoff.Generation != raidGeneration)
            {
                return false;
            }

            Vector3 body = bot.GetPlayer != null ? bot.GetPlayer.Position : bot.Position;
            if (!IsFinite(body))
            {
                detail = "bodyInvalid";
                return false;
            }

            handoff.FreshConsumerPathObserved = true;
            handoff.FreshConsumerPathSource = source ?? "unknown";
            handoff.FreshConsumerPathGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);

            NavMeshHit tightHit;
            bool tightSampled = NavMesh.SamplePosition(
                body, out tightHit, ExitAuthorityTopologyRejoinSampleRadius, NavMesh.AllAreas);
            float tightPlanar = tightSampled ? GetPlanarDistance(body, tightHit.position) : float.MaxValue;
            float tightVertical = tightSampled ? Mathf.Abs(body.y - tightHit.position.y) : float.MaxValue;

            BotPathController pathController = bot.Mover.ActualPathController;
            bool havePath = pathController?.HavePath == true;
            Vector3 currentCorner = default(Vector3);
            bool currentCornerFinite = false;
            if (havePath)
            {
                try
                {
                    currentCorner = pathController.CurrentCornerPoint;
                    currentCornerFinite = IsFinite(currentCorner);
                }
                catch
                {
                    currentCornerFinite = false;
                }
            }

            // CurrentCornerPoint is the next path corner, not the path origin, so requiring it to be
            // within a tiny body radius would deadlock perfectly healthy long path segments. V364
            // instead proves the native path origin/bookkeeping remained at the physical body across
            // the accepted GoToPoint write. This is exactly the state that was stale in V363.
            Vector3 positionOnWay = bot.Mover.PositionOnWayInner;
            Vector3 prevLinked = bot.Mover.PrevSuccessLinkedFrom;
            bool positionOnWayFinite = IsFinite(positionOnWay);
            bool prevLinkedFinite = IsFinite(prevLinked);
            float positionOnWayDistance = positionOnWayFinite
                ? GetPlanarDistance(body, positionOnWay)
                : float.MaxValue;
            float positionOnWayVertical = positionOnWayFinite
                ? Mathf.Abs(body.y - positionOnWay.y)
                : float.MaxValue;
            float prevLinkedDistance = prevLinkedFinite
                ? GetPlanarDistance(body, prevLinked)
                : float.MaxValue;
            float prevLinkedVertical = prevLinkedFinite
                ? Mathf.Abs(body.y - prevLinked.y)
                : float.MaxValue;
            bool localPathOrigin = positionOnWayFinite && prevLinkedFinite &&
                                   positionOnWayDistance <= ExitAuthorityTopologyRejoinMaxLinkedDistance &&
                                   positionOnWayVertical <= ExitAuthorityTopologyRejoinMaxVertical &&
                                   prevLinkedDistance <= ExitAuthorityTopologyRejoinMaxLinkedDistance &&
                                   prevLinkedVertical <= ExitAuthorityTopologyRejoinMaxVertical;

            if (!tightSampled ||
                tightPlanar > ExitAuthorityTopologyRejoinSampleRadius ||
                tightVertical > ExitAuthorityTopologyRejoinMaxVertical ||
                !havePath || !currentCornerFinite || !localPathOrigin)
            {
                detail = "consumerPathNotSamePhysicalEpoch" +
                         ":sampled=" + tightSampled +
                         ":planar=" + tightPlanar.ToString("0.000", CultureInfo.InvariantCulture) +
                         ":vertical=" + tightVertical.ToString("0.000", CultureInfo.InvariantCulture) +
                         ":havePath=" + havePath +
                         ":cornerFinite=" + currentCornerFinite +
                         ":positionOnWayDistance=" + positionOnWayDistance.ToString("0.000", CultureInfo.InvariantCulture) +
                         ":positionOnWayVertical=" + positionOnWayVertical.ToString("0.000", CultureInfo.InvariantCulture) +
                         ":prevLinkedDistance=" + prevLinkedDistance.ToString("0.000", CultureInfo.InvariantCulture) +
                         ":prevLinkedVertical=" + prevLinkedVertical.ToString("0.000", CultureInfo.InvariantCulture);
                if (ShouldEmitDiagnostic(
                        "learningV364ConsumerPathEpochNotYetProven:" + handoff.SourceEdgeId,
                        bot,
                        0.08f))
                {
                    WriteEvent("learningV364ConsumerPathEpochNotYetProven", bot, new
                    {
                        edgeId = handoff.SourceEdgeId,
                        episodeId = handoff.EpisodeId,
                        chainId = handoff.ChainId,
                        source = handoff.FreshConsumerPathSource,
                        body = Vec(body),
                        tightSampled,
                        tightSample = tightSampled ? (object)Vec(tightHit.position) : null,
                        tightPlanar,
                        tightVertical,
                        havePath,
                        currentCorner = currentCornerFinite ? (object)Vec(currentCorner) : null,
                        positionOnWay = positionOnWayFinite ? (object)Vec(positionOnWay) : null,
                        positionOnWayDistance,
                        positionOnWayVertical,
                        prevLinked = prevLinkedFinite ? (object)Vec(prevLinked) : null,
                        prevLinkedDistance,
                        prevLinkedVertical,
                        localPathOrigin,
                        movementOwner = owner.ToString(),
                        movementGeneration = handoff.FreshConsumerPathGeneration,
                        action = "keepPhysicalEpochProjectionBarrierNoBodyRelocation"
                    });
                }
                bool learningV406ConsumerPathQuarantine =
                    (havePath) && currentCornerFinite &&
                    !localPathOrigin && handoff.FreshConsumerPathGeneration > 0 &&
                    (owner == FollowerMovementWriterAuthority.WriterDomain.Follow ||
                     owner == FollowerMovementWriterAuthority.WriterDomain.PostTraversal ||
                     owner == FollowerMovementWriterAuthority.WriterDomain.Recovery);
                if (learningV406ConsumerPathQuarantine)
                {
                    bool retired = TryRetireNativeMoverPathAtCurrentBody(
                        bot, "learningV406UnprovenConsumerMoverPath", out string retireDetail);
                    WriteEvent("learningV406UnprovenConsumerMoverQuarantinedAtCurrentBody", bot, new
                    {
                        edgeId = handoff.SourceEdgeId,
                        episodeId = handoff.EpisodeId,
                        chainId = handoff.ChainId,
                        source = handoff.FreshConsumerPathSource,
                        movementOwner = owner.ToString(),
                        movementGeneration = handoff.FreshConsumerPathGeneration,
                        body = Vec(body),
                        currentCorner = currentCornerFinite ? (object)Vec(currentCorner) : null,
                        positionOnWayDistance,
                        positionOnWayVertical,
                        prevLinkedDistance,
                        prevLinkedVertical,
                        retired,
                        retireDetail,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "unprovenNativeConsumerEpochCannotPhysicallyDriveBodyRetireAndReprimeFromCurrentBody"
                    });
                    detail += ":v406Quarantined=" + retired + ":" + retireDetail;
                }
                return false;
            }

            if (!TryScrubLearningV364NativeMoverEpochAnchor(
                    bot, body, "acceptedPath:" + handoff.FreshConsumerPathSource, out string scrubDetail))
            {
                detail = scrubDetail;
                return false;
            }

            long synchronizedGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain synchronizedOwner);
            try
            {
                if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                    bot, synchronizedOwner, synchronizedGeneration,
                    out FollowerMovementWriterAuthority.WriteScope nativePathSyncScope, out detail))
                    return false;
                using (nativePathSyncScope)
                {
                    // A fresh accepted path starts locally at this body and local NavMesh evidence is
                    // within the same native method_10 radius. It is now safe to commit native link
                    // bookkeeping without invoking any native body relocation method.
                    bot.Mover.SetBotMoverLinkedToNavmeshInitially("R1-D0CE879B43B4",@bot,true);
                    bot.Mover.SetBotMoverPrevSuccessLinkedFrom_1("R1-7FD3FD1D9CF0",@bot,body);
                    bot.Mover.SetBotMoverPrevPosLinkedTime_1("R1-ABE52059E2E2",@bot,Time.time);
                    bot.Mover.SetBotMoverPositionOnWayInner("R1-2F13FB5FFED9",@bot,body);
                }
            }
            catch (Exception ex)
            {
                detail = "nativeBookkeepingCommitFailed:" + ex.GetType().Name;
                return false;
            }

            handoff.NativeBookkeepingSynchronized = true;
            handoff.SynchronizedAt = Time.time;
            handoff.SynchronizedMovementGeneration = synchronizedGeneration;
            handoff.SynchronizedMovementOwner = synchronizedOwner.ToString();
            detail = "synchronized:" + synchronizedOwner + ":generation=" +
                     synchronizedGeneration.ToString(CultureInfo.InvariantCulture);

            WriteEvent("learningV364PhysicalNavigationEpochSynchronized", bot, new
            {
                edgeId = handoff.SourceEdgeId,
                episodeId = handoff.EpisodeId,
                chainId = handoff.ChainId,
                source = handoff.FreshConsumerPathSource,
                physicalAnchor = Vec(handoff.PhysicalAnchor),
                body = Vec(body),
                navSample = Vec(tightHit.position),
                tightPlanar,
                tightVertical,
                currentCorner = Vec(currentCorner),
                preCommitPositionOnWay = Vec(positionOnWay),
                positionOnWayDistance,
                preCommitPrevLinked = Vec(prevLinked),
                prevLinkedDistance,
                movementOwner = synchronizedOwner.ToString(),
                movementGeneration = synchronizedGeneration,
                action = "freshConsumerPathAndNativeMoverBookkeepingNowSharePhysicalBodyEpoch"
            });

            PhysicalNavigationEpochHandoffs.Remove(bot.ProfileId);
            return true;
        }

        private static bool HasLearningV364UnsynchronizedPhysicalNavigationEpoch(
            BotOwner bot,
            out PhysicalNavigationEpochHandoff handoff)
        {
            handoff = null;
            if ((bot == null) ||
                string.IsNullOrEmpty(bot.ProfileId) ||
                !PhysicalNavigationEpochHandoffs.TryGetValue(bot.ProfileId, out handoff) ||
                handoff == null)
            {
                return false;
            }
            if (handoff.Generation != raidGeneration)
            {
                PhysicalNavigationEpochHandoffs.Remove(bot.ProfileId);
                handoff = null;
                return false;
            }
            return !handoff.NativeBookkeepingSynchronized;
        }

        private static bool ArmLearningV426CanonicalConsumerBoundary(
            ProbeRuntime probe,
            FollowerRouteMission routeMission,
            FollowerRouteMissionStep successorStep,
            string source)
        {
            if ((probe?.Bot == null) ||
                probe.Player == null || routeMission == null || string.IsNullOrEmpty(probe.Bot.ProfileId) ||
                !IsFinite(probe.Player.Position))
            {
                return false;
            }

            Vector3 anchor = probe.Player.Position;
            LearnedTraversalEdge completedEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == probe.LearnedEdgeId);
            Vector3 completedEntry = completedEdge != null
                ? (completedEdge.HasSettledStart && IsFinite(completedEdge.SettledStart)
                    ? completedEdge.SettledStart
                    : completedEdge.RawStart)
                : anchor;
            Vector3 completedExit = completedEdge != null
                ? (completedEdge.HasSettledEnd && IsFinite(completedEdge.SettledEnd)
                    ? completedEdge.SettledEnd
                    : completedEdge.RawEnd)
                : anchor;
            int boundaryChainId = successorStep != null && successorStep.ChainId > 0
                ? successorStep.ChainId
                : probe.TraversalChainId;

            ArmLearningV364PhysicalNavigationEpochHandoff(
                probe.Bot,
                probe.LearnedEdgeId,
                probe.TraversalEpisodeId,
                boundaryChainId,
                completedEntry,
                completedExit,
                anchor,
                "learningV426CanonicalConsumerBoundary:" + (source ?? "postCompletion"));

            if (!PhysicalNavigationEpochHandoffs.TryGetValue(
                    probe.Bot.ProfileId, out PhysicalNavigationEpochHandoff handoff) ||
                handoff == null || handoff.Generation != raidGeneration)
            {
                return false;
            }

            handoff.LearningV426CanonicalConsumerBoundary = true;
            handoff.LearningV426RouteMissionId = routeMission.MissionId;
            handoff.LearningV426ExpectedSuccessorEdgeId = successorStep?.EdgeId ?? 0;
            handoff.LearningV426ExpectedSuccessorEpisodeId = successorStep?.EpisodeId ?? 0;
            handoff.LearningV426ExpectedSuccessorKind = successorStep?.Kind ?? string.Empty;

            // ArmLearningV364 already performs a state-only anchor scrub. Repeat against the exact
            // current body after the canonical mission cursor has advanced so the ordering is
            // explicit and falsifiable. This never invokes a relocation writer.
            bool scrubbed = TryScrubLearningV364NativeMoverEpochAnchor(
                probe.Bot,
                anchor,
                "learningV426CanonicalConsumerBoundary",
                out string scrubDetail);

            WriteEvent("learningV426TraversalConsumerEpochArmed", probe.Bot, new
            {
                missionId = routeMission.MissionId,
                completedEdgeId = probe.LearnedEdgeId,
                completedEpisodeId = probe.TraversalEpisodeId,
                successorStepIndex = successorStep != null ? routeMission.Steps.IndexOf(successorStep) : -1,
                successorEdgeId = successorStep?.EdgeId ?? 0,
                successorEpisodeId = successorStep?.EpisodeId ?? 0,
                successorKind = successorStep?.Kind ?? string.Empty,
                chainId = boundaryChainId,
                physicalAnchor = Vec(anchor),
                scrubbed,
                scrubDetail,
                terminalBoundary = successorStep == null,
                traversalSuccessRecordedForSuccessor = false,
                persistentLearningChangedForSuccessor = false,
                bodyRelocated = false,
                action = "canonicalConsumerBoundaryKeepsCurrent3DPhysicalEpochUntilExactSuccessorOrFreshTerminalConsumerOwnsBody"
            });
            return true;
        }

        private static bool TryArmLearningV427MissionCursorConsumerBoundary(
            BotOwner bot,
            FollowerRouteMission routeMission,
            FollowerRouteMissionStep successorStep,
            int completedEpisodeId,
            int completedEdgeId,
            string source)
        {
            if ((bot == null) ||
                routeMission == null || successorStep == null || string.IsNullOrEmpty(bot.ProfileId) ||
                !ActiveProbes.TryGetValue(bot.ProfileId, out ProbeRuntime completedProbe) ||
                completedProbe == null || completedProbe.Bot != bot || completedProbe.Player == null)
            {
                return false;
            }

            bool exactCompletedProbe =
                (completedEpisodeId > 0
                    ? completedProbe.TraversalEpisodeId == completedEpisodeId
                    : completedProbe.LearnedEdgeId == completedEdgeId) &&
                (completedEdgeId <= 0 || completedProbe.LearnedEdgeId == completedEdgeId);
            if (!exactCompletedProbe)
            {
                return false;
            }

            if (PhysicalNavigationEpochHandoffs.TryGetValue(
                    bot.ProfileId, out PhysicalNavigationEpochHandoff existing) &&
                existing != null && existing.Generation == raidGeneration &&
                !existing.NativeBookkeepingSynchronized &&
                existing.LearningV426CanonicalConsumerBoundary &&
                existing.LearningV426RouteMissionId == routeMission.MissionId &&
                existing.LearningV426ExpectedSuccessorEdgeId == successorStep.EdgeId &&
                (existing.LearningV426ExpectedSuccessorEpisodeId <= 0 ||
                 successorStep.EpisodeId <= 0 ||
                 existing.LearningV426ExpectedSuccessorEpisodeId == successorStep.EpisodeId))
            {
                return true;
            }

            bool armed = ArmLearningV426CanonicalConsumerBoundary(
                completedProbe, routeMission, successorStep,
                "learningV427MissionCursorBoundaryLease:" + (source ?? "missionAdvance"));
            if (armed)
            {
                WriteEvent("learningV427MissionCursorConsumerBoundaryLeaseArmed", bot, new
                {
                    missionId = routeMission.MissionId,
                    completedEpisodeId,
                    completedEdgeId,
                    successorStepIndex = routeMission.CurrentStepIndex,
                    successorEpisodeId = successorStep.EpisodeId,
                    successorEdgeId = successorStep.EdgeId,
                    successorKind = successorStep.Kind,
                    source = source ?? string.Empty,
                    traversalSuccessRecordedForSuccessor = false,
                    persistentLearningChangedForSuccessor = false,
                    bodyRelocated = false,
                    action = "missionCursorMaterializationOwnsBoundaryLeaseBeforeAnyLaterConsumerCanReleasePhysicalEpoch"
                });
            }
            return armed;
        }

        private static bool TrySynchronizeLearningV426TraversalConsumerEpochForSuccessorProbe(
            ProbeRuntime probe)
        {
            if ((probe?.Bot == null) ||
                probe.Player == null || string.IsNullOrEmpty(probe.Bot.ProfileId) ||
                !PhysicalNavigationEpochHandoffs.TryGetValue(
                    probe.Bot.ProfileId, out PhysicalNavigationEpochHandoff handoff) ||
                handoff == null || handoff.Generation != raidGeneration ||
                !handoff.LearningV426CanonicalConsumerBoundary ||
                handoff.LearningV426ExpectedSuccessorEdgeId <= 0)
            {
                return false;
            }

            bool matchingEdge = probe.LearnedEdgeId > 0 &&
                probe.LearnedEdgeId == handoff.LearningV426ExpectedSuccessorEdgeId;
            bool matchingEpisode = handoff.LearningV426ExpectedSuccessorEpisodeId <= 0 ||
                probe.TraversalEpisodeId <= 0 ||
                probe.TraversalEpisodeId == handoff.LearningV426ExpectedSuccessorEpisodeId;
            bool matchingChain = handoff.ChainId <= 0 || probe.TraversalChainId <= 0 ||
                probe.TraversalChainId == handoff.ChainId;
            if (!matchingEdge || !matchingEpisode || !matchingChain)
            {
                WriteEvent("learningV426TraversalConsumerEpochSuccessorMismatch", probe.Bot, new
                {
                    missionId = handoff.LearningV426RouteMissionId,
                    sourceEdgeId = handoff.SourceEdgeId,
                    expectedSuccessorEdgeId = handoff.LearningV426ExpectedSuccessorEdgeId,
                    expectedSuccessorEpisodeId = handoff.LearningV426ExpectedSuccessorEpisodeId,
                    expectedSuccessorKind = handoff.LearningV426ExpectedSuccessorKind ?? string.Empty,
                    expectedChainId = handoff.ChainId,
                    probeEdgeId = probe.LearnedEdgeId,
                    probeEpisodeId = probe.TraversalEpisodeId,
                    probeChainId = probe.TraversalChainId,
                    action = "keepBoundaryBarrierUntilCanonicalSuccessorIdentityAcquiresTraversal"
                });
                return false;
            }

            Vector3 body = probe.Player.Position;
            if (!IsFinite(body))
            {
                return false;
            }

            long movementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                probe.Bot, out FollowerMovementWriterAuthority.WriterDomain movementOwner);
            bool walkThroughFollowPreflight =
                movementOwner == FollowerMovementWriterAuthority.WriterDomain.Follow &&
                probe.LearningV330WalkThroughPreflightFollowAuthority &&
                string.Equals(
                    probe.TraversalKind ?? probe.RequestedTraversalKind,
                    "WalkThrough",
                    StringComparison.OrdinalIgnoreCase);
            if (movementGeneration <= 0 ||
                (movementOwner != FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                 !walkThroughFollowPreflight) ||
                (probe.MovementWriterGeneration > 0 && movementGeneration != probe.MovementWriterGeneration))
            {
                return false;
            }

            // ActiveProbes is installed before this helper is called. Once this state-only scrub
            // commits, V349's active-probe physical epoch guard replaces V364's inter-boundary
            // guard without a frame where method_10 can regain body authority.
            if (!TryScrubLearningV364NativeMoverEpochAnchor(
                    probe.Bot,
                    body,
                    "learningV426ExactSuccessorProbeAcquired",
                    out string scrubDetail))
            {
                return false;
            }

            handoff.NativeBookkeepingSynchronized = true;
            handoff.SynchronizedAt = Time.time;
            handoff.SynchronizedMovementGeneration = movementGeneration;
            handoff.SynchronizedMovementOwner = movementOwner.ToString();

            WriteEvent("learningV426TraversalConsumerEpochSynchronized", probe.Bot, new
            {
                missionId = handoff.LearningV426RouteMissionId,
                sourceEdgeId = handoff.SourceEdgeId,
                sourceEpisodeId = handoff.EpisodeId,
                successorEdgeId = probe.LearnedEdgeId,
                successorEpisodeId = probe.TraversalEpisodeId,
                successorKind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty,
                chainId = probe.TraversalChainId,
                body = Vec(body),
                movementOwner = movementOwner.ToString(),
                movementGeneration,
                walkThroughFollowPreflight,
                scrubDetail,
                traversalSuccessRecordedForSuccessor = false,
                persistentLearningChangedForSuccessor = false,
                bodyRelocated = false,
                action = "exactSuccessorProbeAtomicallyReplacesInterBoundaryV364GuardWithActiveTraversalPhysicalEpoch"
            });

            PhysicalNavigationEpochHandoffs.Remove(probe.Bot.ProfileId);
            return true;
        }

        internal static bool TryRetireNativeMoverPathAtCurrentBody(BotOwner bot, string reason, out string detail)
        {
            detail = "unavailable";
            if ((bot?.GetPlayer == null) || bot.Mover == null ||
                !IsFinite(bot.GetPlayer.Position))
            {
                return false;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (generation <= 0 || owner == FollowerMovementWriterAuthority.WriterDomain.Unknown)
            {
                detail = "noCurrentMovementOwner";
                return false;
            }

            Vector3 anchor = bot.GetPlayer.Position;
            if ((!string.IsNullOrEmpty(bot.ProfileId)) &&
                PostTraversalIntegrityWatches.TryGetValue(
                    bot.ProfileId, out PostTraversalIntegrityWatch v364Watch) &&
                v364Watch != null)
            {
                ArmLearningV364PhysicalNavigationEpochHandoff(
                    bot,
                    v364Watch.EdgeId,
                    v364Watch.EpisodeId,
                    v364Watch.CompletedChainId,
                    v364Watch.Entry,
                    v364Watch.Exit,
                    anchor,
                    reason ?? "retireNativeMoverPath");
            }
            try
            {
                if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                    bot, owner, generation,
                    out FollowerMovementWriterAuthority.WriteScope pathRetirementScope, out detail))
                    return false;
                using (pathRetirementScope)
                {
                    // V351 retires the stale producer instead of adding another relocation writer.
                    // Stop the old path, neutralize its destination/avoidance residue at the current
                    // authoritative body, and let the NEXT owner install a fresh path from here.
                    // No Teleport/CharacterController relocation is introduced at this boundary.
                    bot.Mover.BotMoverStop("R1-D527961E3CB0",@bot);
                    bot.BotOwnerStopMove("R1-49C33D33DF5C",@bot);
                    bot.GoToSomePointData?.BotGoToPointDataSetPoint("R1-D2526D22D2DC",@bot,anchor);
                    bot.GoToSomePointData?.BotGoToPointDataUpdateToGo("R1-83F477FCC825",@bot,false);
                    bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-C1EB79EE8E82",@bot);
                }
                bool relocationEpochScrubbed = false;
                string relocationEpochDetail = "notRequired";
                if ((owner == FollowerMovementWriterAuthority.WriterDomain.Teleport))
                {
                    relocationEpochScrubbed = TryCommitLearningV432RelocationNativeMoverEpoch(
                        bot, anchor, "postRetireNativeMoverPath", out relocationEpochDetail);
                }
                else if ((HasLearningV364UnsynchronizedPhysicalNavigationEpoch(
                             bot, out PhysicalNavigationEpochHandoff _)))
                {
                    relocationEpochScrubbed = TryScrubLearningV364NativeMoverEpochAnchor(
                        bot, anchor, "postRetireNativeMoverPath", out relocationEpochDetail);
                }
                detail = "retired:" + owner + ":generation=" + generation.ToString(CultureInfo.InvariantCulture) +
                         ":anchorScrubbed=" + relocationEpochScrubbed +
                         ":anchorDetail=" + relocationEpochDetail;
                return true;
            }
            catch (Exception ex)
            {
                detail = "retireFailed:" + ex.GetType().Name;
                return false;
            }
        }

        private static bool TryRetireNativeMoverPathPreserveLocomotion(
            BotOwner bot, string reason, out string detail)
        {
            detail = "unavailable";
            if (HasCurrentCapabilityNativeWay(bot,out _))
            {
                detail="currentCapabilityNativeConsumerPreserved";
                return true;
            }
            if ((bot?.GetPlayer == null) || bot.Mover == null ||
                !IsFinite(bot.GetPlayer.Position))
            {
                return false;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (generation <= 0 || owner == FollowerMovementWriterAuthority.WriterDomain.Unknown)
            {
                detail = "noCurrentMovementOwner";
                return false;
            }

            try
            {
                Vector3 anchor = bot.GetPlayer.Position;
                if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                    bot, owner, generation,
                    out FollowerMovementWriterAuthority.WriteScope nativeContinuityScope, out detail))
                    return false;
                using (nativeContinuityScope)
                {
                    // Native BotMover continuity: remove only stale route topology. Do NOT call
                    // BotOwner.StopMove and do NOT zero Player input. The already-running EFT
                    // movement state consumes the replacement Player.Move intent in this same epoch.
                    if (bot.Mover.HasPathAndNoComplete)
                    {
                        bot.Mover.BotMoverStop("R1-33ACF026253C",@bot);
                    }
                    bot.Mover.BotMoverSetPointOnWay("R1-2CC2E38478A8",@bot,anchor);
                    bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-76DB96040BA0",@bot);
                    bot.Mover.SetBotMoverPause("R1-820C36746300",@bot,false);
                }
                detail = "retiredPathPreservedLocomotion:" + owner + ":generation=" +
                         generation.ToString(CultureInfo.InvariantCulture);
                if (ShouldEmitDiagnostic("learningV409NativeMoverPathRetiredWithoutBrake", bot, 0.35f))
                {
                    WriteEvent("learningV409NativeMoverPathRetiredWithoutBrake", bot, new
                    {
                        reason = reason ?? string.Empty,
                        owner = owner.ToString(),
                        generation,
                        anchor = Vec(anchor),
                        inputPreserved = true,
                        stopMoveCalled = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "retireStalePathTopologyWithoutBreakingNativeLocomotionState"
                    });
                }
                return true;
            }
            catch (Exception ex)
            {
                detail = "retirePreserveFailed:" + ex.GetType().Name;
                return false;
            }
        }

