        private static int GetLearningV362LatestBreadcrumbSequence()
        {
            return BreadcrumbRoute.Count > 0 && BreadcrumbRoute[BreadcrumbRoute.Count - 1] != null
                ? Math.Max(0, BreadcrumbRoute[BreadcrumbRoute.Count - 1].Sequence)
                : 0;
