        internal static long PrepareForAutomaticRecoveryTeleport(BotOwner bot, string reason)
        {
            if (bot == null)
            {
                return 0;
            }

            string resolvedReason = string.IsNullOrWhiteSpace(reason) ? "automaticRecovery" : reason;
            // CompileFix51: automatic recovery and F4 manual regroup share the exact same hard
            // locomotion-repair capability. Their only semantic difference is route ownership:
            // recovery keeps RouteMission intent so the follower can resume at the next physically
            // downstream traversal; F4 intentionally clears the whole route.
            long issuedTeleportGeneration = ResetFollowerMovementAuthorityForTeleport(
                bot,
                preserveRouteMission: true,
                preserveActiveCommitment: false,
                reason: resolvedReason);
            if (TryGetActiveProbe(bot, out ProbeRuntime teleportProbe) && teleportProbe != null)
            {
                teleportProbe.TeleportWriterGeneration = issuedTeleportGeneration;
            }
            if (!string.IsNullOrEmpty(bot.ProfileId) &&
                ChainHandoffAuthorityGuards.TryGetValue(bot.ProfileId, out ChainHandoffAuthorityGuard teleportGuard) &&
                teleportGuard != null && teleportGuard.Generation == raidGeneration)
            {
                teleportGuard.TeleportWriterGeneration = issuedTeleportGeneration;
            }
            WriteEvent("automaticRecoveryTeleportContextPrepared", bot, new
            {
                reason = resolvedReason,
                teleportOriginGeneration = issuedTeleportGeneration,
                routeMissionPreserved = FollowerRouteMissions.ContainsKey(bot.ProfileId ?? string.Empty),
                activeCommitmentPreserved = false
            });
            return issuedTeleportGeneration;
        }

        // RC61: ReconcileLearningV354RouteMissionAfterRecoveryTeleport extracted unchanged to FollowerTraversalRecoveryOwnership.cs.

        private static bool RetireLearningV355ValidatedRecoveryExecutionDebt(
            ProbeRuntime probe, TraversalCompletionMode completionMode, out string disposition)
        {
            disposition = "notApplicable";
            if ((probe?.Bot == null) ||
                completionMode != TraversalCompletionMode.TeleportFallback)
            {
                return false;
            }

            string profileId = probe.Bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) || mission == null ||
                mission.Steps == null || mission.Steps.Count == 0)
            {
                disposition = "noRouteMission";
                return false;
            }

            int matchedIndex = -1;
            var r2DebtObservation7 = CaptureRouteDebtObservation(probe.Bot, mission, null, true);

            for (int i = Math.Max(0, mission.CurrentStepIndex); i < mission.Steps.Count; i++)
            {
                FollowerRouteMissionStep candidate = mission.Steps[i];
                if (candidate == null) continue;
                bool sameExecutionIdentity = probe.TraversalEpisodeId > 0
                    ? candidate.EpisodeId == probe.TraversalEpisodeId
                    : (probe.LearnedEdgeId > 0 && candidate.EdgeId == probe.LearnedEdgeId);
                if (sameExecutionIdentity)
                {
                    matchedIndex = i;
                    break;
                }
            }
            if (matchedIndex < 0)
            {
                disposition = "matchingExecutionDebtNotFound";
                return false;
            }

            FollowerRouteMissionStep retired = mission.Steps[matchedIndex];
            Vector3 expectedFarSide = IsFinite(retired.RawExit) ? retired.RawExit : retired.Exit;
            float farSideDistance = IsFinite(expectedFarSide)
                ? GetPlanarDistance(probe.Bot.Position, expectedFarSide) : float.MaxValue;
            float acceptedExitDistance = IsFinite(probe.ExitAuthorityAnchor)
                ? GetPlanarDistance(probe.Bot.Position, probe.ExitAuthorityAnchor) : float.MaxValue;
            // CommitUnifiedTraversalSuccess is called only after stable ExitAuthority accepted the
            // actual body epoch. The distance checks are a second guard against retiring unrelated
            // mission debt when an old edge id was reused.
            if (farSideDistance > RouteMissionTraversalAdjacentBridgeMaxDistance * 1.5f &&
                acceptedExitDistance > RouteMissionTraversalAdjacentBridgeMaxDistance * 1.5f)
            {
                disposition = "validatedBodyOutsideMatchedFarSide";
                return false;
            }

            int previousStep = mission.CurrentStepIndex;
            int newStep = Math.Max(mission.CurrentStepIndex, matchedIndex + 1);
            int previousExecutionFloor = GetFollowerRouteExecutionFloor(profileId);
            int newExecutionFloor = Math.Max(previousExecutionFloor, retired.EndBreadcrumbSequence);
            FollowerRouteExecutionFloors[profileId] = newExecutionFloor;
            mission.ResumeFloorBreadcrumbSequence = Math.Max(mission.ResumeFloorBreadcrumbSequence, newExecutionFloor);
            mission.PhysicalApproachBreadcrumbSequence = Math.Max(mission.PhysicalApproachBreadcrumbSequence, retired.EndBreadcrumbSequence);
            mission.ApproachBreadcrumbSequence = Math.Max(mission.ApproachBreadcrumbSequence, retired.EndBreadcrumbSequence);
            mission.ObservedDownstreamBreadcrumbSequence = Math.Max(mission.ObservedDownstreamBreadcrumbSequence, retired.EndBreadcrumbSequence);
            if (!TryAdvanceRouteMission(probe.Bot, mission, newStep, RouteDebtEvidence.TeleportRecovery, "RetireLearningV355ValidatedRecoveryExecutionDebt:2", r2DebtObservation7)) return false;
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;
            mission.LocalRecoveryAttempts = 0;
            mission.PathRejectsSinceProgress = 0;
            mission.RejectedBreadcrumbSequences.Clear();
            mission.FailureSignatureCounts.Clear();
            mission.LastProgressAt = Time.time;
            mission.LastProgressPosition = probe.Bot.Position;
            mission.LearningV355ProgressStepIndex = -1;

            disposition = "executionDebtRetiredToStep:" + newStep.ToString(CultureInfo.InvariantCulture);
            WriteEvent("learningV355ValidatedRecoveryExecutionFrontierRetired", probe.Bot, new
            {
                missionId = mission.MissionId, previousStepIndex = previousStep, matchedStepIndex = matchedIndex,
                newStepIndex = newStep, episodeId = retired.EpisodeId, edgeId = retired.EdgeId, kind = retired.Kind,
                previousExecutionFloor, newExecutionFloor, farSideDistance, acceptedExitDistance,
                traversalSuccessRecorded = false, persistentLearningChanged = false,
                routeSemanticCursorAdvanced = false, executionDebtRetired = true,
                action = "keepRecoveryOutcomeAdvanceExecutionFrontierPreserveDownstreamRoute"
            });
            return true;
        }

        internal static void NotifyAutomaticRecoveryTeleportCompleted(BotOwner bot, string reason)
        {
            if (bot == null)
            {
                return;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            bool rebased = false;
            bool recoveryFrontierReanchored = false;
            string recoveryFrontierDisposition = "notApplicable";
            bool terminalRecoveryBoundary = !string.IsNullOrEmpty(profileId) &&
                FollowerMovementRecoveryStates.TryGetValue(profileId, out FollowerMovementRecoveryState terminalRecoveryState) &&
                terminalRecoveryState != null && terminalRecoveryState.LearningV350TerminalRecoveryEligible;
            int missionId = 0;
            int previousStepIndex = -1;
            int currentStepIndex = -1;
            if (!string.IsNullOrEmpty(profileId) &&
                FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) && mission != null)
            {
                missionId = mission.MissionId;
                previousStepIndex = mission.CurrentStepIndex;
                if (terminalRecoveryBoundary && true)
                {
                    recoveryFrontierReanchored = ReconcileLearningV354RouteMissionAfterRecoveryTeleport(
                        bot, mission, out recoveryFrontierDisposition);
                }
                rebased = recoveryFrontierReanchored || RebaseFollowerRouteMissionToCurrentPosition(bot, mission);
                currentStepIndex = mission.CurrentStepIndex;
            }

            bool locomotionRecovered = TryHardRecoverFollowerLocomotionAuthority(
                bot,
                "automaticRecoveryPostTeleport:" + (reason ?? "unknown"),
                out string locomotionDetail);
            if (locomotionRecovered)
            {
                FollowerStateAuthorityCoordinator.ClearLocomotionFault(bot, "automaticRecoveryPostTeleport");
            }

            if (true)
            {
                ClearLearningV351TerminalRecoveryState(bot, "automaticRecoveryTeleportCompleted");
            }
            else if (true && !string.IsNullOrEmpty(profileId) &&
                     FollowerMovementRecoveryStates.TryGetValue(profileId, out FollowerMovementRecoveryState recoveryState) &&
                     recoveryState != null)
            {
                recoveryState.LearningV350TerminalRecoveryEligible = false;
                recoveryState.LearningV350TerminalRecoverySince = -1f;
                recoveryState.LearningV350TerminalRecoveryReason = string.Empty;
                recoveryState.LearningV350GenericPassageArmedAt = -1f;
                recoveryState.LearningV350GenericPassageArmCursorSequence = 0;
                recoveryState.LearningV349GenericPassageLeaseUntil = -1f;
                recoveryState.LearningV349PhysicalStallSince = -1f;
                recoveryState.LearningV349LastPhysicalPosition = bot.Position;
                recoveryState.LearningV349LastPhysicalProgressAt = Time.time;
            }

            WriteEvent("automaticRecoveryTeleportCompleted", bot, new
            {
                reason = reason ?? "unknown",
                missionId,
                previousStepIndex,
                currentStepIndex,
                rebased,
                terminalRecoveryBoundary,
                recoveryFrontierReanchored,
                recoveryFrontierDisposition,
                locomotionRecovered,
                locomotionDetail,
                routeMissionPreserved = missionId > 0
            });
        }

        // RC107: ArmFollowReacquireAfterAuthorityReset is owned by FollowerCapabilityFollowControlHost.

        internal static bool PrepareForManualRegroup(BotOwner bot)
        {
            if (bot == null)
            {
                return false;
            }

            bool releasedProbe = false;
            if (TryGetActiveProbe(bot, out ProbeRuntime probe) && probe != null)
            {
                // F4 is an emergency authority override. Cancel PIT traversal ownership before the
                // manual regroup teleport so a stale TeleportArm/SafetyHold transaction cannot reclaim
                // the follower on the next update.
                ForceReleaseTraversalProbe(probe, "manualRegroupOverride");
                releasedProbe = true;
            }

            // Manual regroup is even stronger than automatic recovery: the user explicitly asked
            // the follower to abandon all old catch-up work and resume from the current player route.
            AdvanceFollowerRouteResumeFloor(bot, "manualRegroup", quarantineCurrentTraversal: false);
            long manualTeleportGeneration = ResetFollowerMovementAuthorityForTeleport(
                bot, preserveRouteMission: false, preserveActiveCommitment: false, reason: "manualRegroup");
            {
                ClearLearningV351TerminalRecoveryState(bot, "manualRegroup");
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId))
            {
                // Manual regroup intentionally abandons the currently pending traversal mission.
                // Do not let a preloaded FIFO edge or entry-side breadcrumb immediately take control
                // again after the F4 teleport.
                LearnedTraversalCommitments.Remove(profileId);
                ProvisionalWalkThroughReservations.Remove(profileId);
                NavigationRecoveryTraversalAnchors.Remove(profileId);
                BreadcrumbFollowCommitments.Remove(profileId);
                PostTraversalEntryQuarantines.Remove(profileId);
                BreadcrumbBarrierDetourUntil.Remove(profileId);
            }

            // ResetFollowerMovementAuthorityForTeleport already minted Teleport ownership. The
            // old duplicate cleanup below executed OUTSIDE that writer scope, so the movement
            // guards rejected BotMover.Stop/StopMove as a stale Traversal writer. Re-enter the
            // live Teleport generation and keep the body motionless until SafeTeleport commits.
            // Use the generation minted by THIS manual teleport, never the next owner.
            FollowerMovementWriterAuthority.WriterDomain manualTeleportOwner =
                manualTeleportGeneration > 0
                    ? FollowerMovementWriterAuthority.WriterDomain.Teleport
                    : FollowerMovementWriterAuthority.WriterDomain.Unknown;
            bool locomotionQuiesced = false;
            string locomotionQuiescenceDetail = "teleportOwnerUnavailable";
            if (manualTeleportGeneration > 0 &&
                manualTeleportOwner == FollowerMovementWriterAuthority.WriterDomain.Teleport)
            {
                if (FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                    bot, FollowerMovementWriterAuthority.WriterDomain.Teleport, manualTeleportGeneration,
                    out FollowerMovementWriterAuthority.WriteScope manualQuiesceScope,
                    out locomotionQuiescenceDetail))
                {
                    using (manualQuiesceScope)
                    {
                        locomotionQuiesced = TryQuiesceFollowerLocomotionForTeleport(
                            bot, "manualRegroupPreTeleport", out locomotionQuiescenceDetail,manualTeleportGeneration);
                    }
                }
            }

            WriteEvent("manualRegroupTraversalAuthorityCleared", bot, new
            {
                releasedProbe,
                profileId,
                locomotionQuiesced,
                locomotionQuiescenceDetail,
                writerOwner = manualTeleportOwner.ToString(),
                writerGeneration = manualTeleportGeneration,
                followReacquireDeferredUntilTeleportStable = true
            });
            // LearningV4.31: do not arm Follow before the body has even been relocated.
            // CompleteTeleportStabilization owns the single fresh Follow handoff.
            return releasedProbe;
        }

        private static void ForceReleaseTraversalProbe(ProbeRuntime probe, string reason)
        {
            if (probe == null)
            {
                return;
            }

            try
            {
                MovementContext movement = probe.Player?.MovementContext;
                movement?.MovementContextPlayerAnimatorSetDoVault("R1-E972CAEAE3E7",@probe?.Bot,false);
                movement?.MovementContextPlayerAnimatorSetDoClimb("R1-05D09D446276",@probe?.Bot,false);
            }
            catch
            {
            }

            probe.PendingTeleportSource = null;
            probe.PendingTeleportRequestedAt = 0f;
            probe.PendingTeleportStableSamples = 0;
            // V3.28: generic force-release is not a teleport attempt. The previous assignment
            // contaminated lifecycle telemetry and made an authority abort look like recovery.
            // Actual teleport branches set TraversalTeleportAttempted/TeleportFallbackUsed themselves.
            probe.UnifiedTraversalFlow = true;
            probe.AbortAfterLanding = false;
            probe.ExclusiveMoverGate = false;

            if (true)
            {
                TryCommitLearningV433FailedPhysicalActuatorEpoch(
                    probe, "learningV434ForceRelease:" + (reason ?? "unknown"));
            }

            try
            {
                if (probe.Bot?.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-51296BD5A233",@probe?.Bot,false);
                    probe.Bot.Mover.BotMoverSprint("R1-8E2495493003",@probe?.Bot,false,false);
                    probe.Bot.Mover.BotMoverStop("R1-351FCB34934F",@probe?.Bot);
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-C74B63C959BF",@probe?.Bot);
                }
                probe.Bot?.BotOwnerStopMove("R1-32F9E2A56B0A",@probe?.Bot);

                // CompileFix48: an abnormal traversal release is a full movement transaction abort.
                // Fix47 stopped BotMover but left GoToSomePointData active; combat then inherited a
                // 20 cm self-target and reported reachedTarget=true for the rest of the encounter.
                if (probe.Bot?.GoToSomePointData != null)
                {
                    Vector3 safePoint = probe.Player != null && IsFinite(probe.Player.Position)
                        ? probe.Player.Position
                        : probe.Bot.Position;
                    probe.Bot.GoToSomePointData.BotGoToPointDataSetPoint("R1-E82DB3C66217",@probe?.Bot,safePoint);
                    probe.Bot.GoToSomePointData.BotGoToPointDataUpdateToGo("R1-6B5BF1F20151",@probe?.Bot,false);
                }
            }
            catch
            {
            }

            RestoreProbeInput(probe);

            // If an assisted/native traversal was interrupted while already grounded, restore the
            // ordinary locomotion state immediately. Do not attempt a state transition while airborne.
            if (probe.Bot != null && probe.Player?.MovementContext?.IsGrounded == true &&
                (probe.AssistedAnimationStarted || probe.AssistedReplayAttempted ||
                 IsProbeTraversalState(probe.Player.CurrentStateName)))
            {
                if (TryRecoverBoundFollowerLocomotion(
                        probe.Bot,probe,
                        "forcedTraversalRelease:" + (reason ?? "unknown"),
                        out string locomotionRecoveryDetail))
                {
                    WriteEvent("forcedTraversalLocomotionRecovered", probe.Bot, new
                    {
                        reason,
                        detail = locomotionRecoveryDetail,
                        state = probe.Player.CurrentStateName.ToString()
                    });
                }
                else
                {
                    WriteEvent("forcedTraversalLocomotionRecoveryAttempt", probe.Bot, new
                    {
                        reason,
                        detail = locomotionRecoveryDetail,
                        state = probe.Player.CurrentStateName.ToString()
                    });
                }
            }
            string profileId = probe.Bot?.ProfileId ?? string.Empty;
            if (probe.LearnedEdgeId > 0 && probe.Bot != null)
            {
                ClearLearnedTraversalCommitment(probe.Bot, probe.LearnedEdgeId, reason);
            }
            if (!string.IsNullOrEmpty(profileId))
            {
                ProvisionalWalkThroughReservations.Remove(profileId);
                NavigationRecoveryTraversalAnchors.Remove(profileId);
            }
            EnsureLearningV328AttemptTerminalizedBeforeUnregister(
                probe, "forceRelease:" + (reason ?? "unknown"));
            WriteEvent("vaultProbeForcedRelease", probe.Bot, new
            {
                reason,
                stage = probe.Stage.ToString(),
                state = probe.Player?.CurrentStateName.ToString(),
                position = probe.Player != null ? Vec(probe.Player.Position) : null
            });
            DetachProbeStateHandler(probe);
            UnregisterActiveProbe(probe);
        }

        public static bool OwnsBot(BotOwner bot)
        {
            if (TryGetActiveProbe(bot, out ProbeRuntime probe) && probe.Generation == raidGeneration)
            {
                return true;
            }

            if (bot == null)
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) &&
                ChainHandoffAuthorityGuards.TryGetValue(profileId, out ChainHandoffAuthorityGuard guard) &&
                guard != null && guard.Generation == raidGeneration && Time.time <= guard.ExpiresAt)
            {
                return true;
            }

            long learningV423OwnsGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain learningV423OwnsOwner);
            if (learningV423OwnsOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                TryGetLearningV423TraversalOwnedPhysicalContinuation(
                    bot, learningV423OwnsGeneration, out _))
            {
                return true;
            }

            if ((!string.IsNullOrEmpty(profileId)) &&
                FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor learningV375Cursor) &&
                learningV375Cursor != null && learningV375Cursor.LearningV375TransactionActive &&
                (learningV375Cursor.LearningV375RouteMissionId > 0 || learningV375Cursor.LearningV375TransactionChainId > 0) &&
                FollowerMovementWriterAuthority.GetCurrentGeneration(
                    bot, out FollowerMovementWriterAuthority.WriterDomain learningV375Owner) ==
                    learningV375Cursor.LearningV375MovementGeneration &&
                learningV375Owner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                TryResolveLearningV376CursorMission(
                    bot, learningV375Cursor, out FollowerRouteMission learningV375Mission) &&
                learningV375Mission != null)
            {
                return true;
            }

            // A PIT teleport stabilization transaction owns movement too. FollowAction, SAIN,
            // ordnance and navigation recovery must not enqueue competing movement while either
            // an active traversal probe, a chain handoff barrier, or a follower teleport transaction
            // has authority.
            return IsTeleportTransactionActive(bot);
        }

        private static bool TryGetLearningV368LiveChainTraversalProducer(
            BotOwner bot,
            out ChainHandoffAuthorityGuard guard)
        {
            guard = null;
            if ((bot == null) ||
                string.IsNullOrEmpty(bot.ProfileId) ||
                !ChainHandoffAuthorityGuards.TryGetValue(bot.ProfileId, out ChainHandoffAuthorityGuard candidate) ||
                candidate == null || candidate.Generation != raidGeneration ||
                Time.time > candidate.ExpiresAt || candidate.SuccessorAuthorityAcquired ||
                candidate.NextEdgeId <= 0 || !IsFinite(candidate.NextEntry))
            {
                return false;
            }
            guard = candidate;
            return true;
        }

        private static bool TryGetLearningV423TraversalOwnedPhysicalContinuation(
            BotOwner bot, long generation, out LearningV365ContinuousRouteProducerState producer)
        {
            producer = null;
            if ((bot == null) || generation <= 0 ||
                string.IsNullOrEmpty(bot.ProfileId) ||
                !LearningV365ContinuousRouteProducerStates.TryGetValue(
                    bot.ProfileId, out LearningV365ContinuousRouteProducerState candidate) ||
                candidate == null || !candidate.Generic ||
                candidate.LearningV423TraversalOwnedGeneration != generation ||
                !FollowerMovementRecoveryStates.TryGetValue(
                    bot.ProfileId, out FollowerMovementRecoveryState recovery) ||
                recovery == null || Time.time > recovery.LearningV349GenericPassageLeaseUntil)
            {
                return false;
            }
            producer = candidate;
            return true;
        }

        private static void EnforceLearningV368TraversalProducerOwnership(BotOwner bot, string source)
        {
            if ((bot == null) ||
                string.IsNullOrEmpty(bot.ProfileId) || IsTeleportTransactionActive(bot))
            {
                return;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (owner != FollowerMovementWriterAuthority.WriterDomain.Traversal || generation <= 0)
            {
                return;
            }

            // A queued head, failure strategy or return driver is a producer even between probes.
            // Never install ordinary Follow over its still-live finite route debt.
            if (FollowerRouteMissions.TryGetValue(bot.ProfileId, out var pendingMission) &&
                pendingMission != null && pendingMission.LifecycleRaid == raidGeneration &&
                pendingMission.LifecycleBotId == bot.ProfileId && Time.time <= pendingMission.ExpiresAt &&
                HasCapabilityUnresolvedRouteWork(bot)) return;

            bool haveActiveProbe = TryGetActiveProbe(bot, out ProbeRuntime probe) &&
                probe != null && probe.Generation == raidGeneration;
            bool haveChainProducer = TryGetLearningV368LiveChainTraversalProducer(bot, out _);
            bool haveLearningV375PersistentProducer = false;
            if ((FollowerTraversalRouteCursors.TryGetValue(bot.ProfileId, out FollowerTraversalRouteCursor learningV375Cursor)) &&
                learningV375Cursor != null && learningV375Cursor.LearningV375TransactionActive &&
                learningV375Cursor.LearningV375MovementGeneration == generation &&
                TryResolveLearningV376CursorMission(bot, learningV375Cursor, out _))
            {
                haveLearningV375PersistentProducer = true;
            }
            if (haveActiveProbe || haveChainProducer || haveLearningV375PersistentProducer)
            {
                return;
            }

            if (TryGetLearningV423TraversalOwnedPhysicalContinuation(
                    bot, generation, out LearningV365ContinuousRouteProducerState learningV423Continuation))
            {
                bool learningV423FollowInstalled =
                    TryHandoffLearningV419TraversalToFreshFollowConsumer(
                        bot, generation,
                        "learningV423PhysicalContinuationFreshFollow",
                        "post-traversal-fresh-epoch",
                        out string learningV423FollowDetail);
                if (learningV423FollowInstalled)
                {
                    learningV423Continuation.LearningV423TraversalOwnedGeneration = 0;
                    ClearLearningV365ContinuousPhysicalRoute(
                        bot, "learningV423PhysicalContinuationFreshFollowInstalled");
                    WriteEvent("learningV423PhysicalContinuationFreshFollowInstalled", bot, new
                    {
                        source = source ?? "unknown",
                        previousTraversalGeneration = generation,
                        detail = learningV423FollowDetail,
                        body = Vec(bot.Position),
                        bodyRelocated = false,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "freshNativeFollowConsumerAtomicallySupersedesTraversalOwnedPhysicalContinuation"
                    });
                }
                else
                {
                    long learningV423CurrentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                        bot, out FollowerMovementWriterAuthority.WriterDomain learningV423CurrentOwner);
                    if (learningV423CurrentOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                        learningV423CurrentGeneration > 0 &&
                        learningV423CurrentGeneration != learningV423Continuation.LearningV423TraversalOwnedGeneration)
                    {
                        // The native Follow write can fail after the two-phase owner transition and
                        // V419 correctly rolls back to a NEW Traversal generation. Keep the same
                        // physical consumer bound to that rollback epoch so one failed GoToPoint
                        // cannot create a one-frame orphan gap.
                        learningV423Continuation.LearningV423TraversalOwnedGeneration = learningV423CurrentGeneration;
                    }
                    if (ShouldEmitDiagnostic(
                            "learningV423PhysicalContinuationFollowDeferred", bot, 0.18f))
                    {
                        WriteEvent("learningV423PhysicalContinuationFollowDeferred", bot, new
                        {
                            source = source ?? "unknown",
                            traversalGeneration = learningV423Continuation.LearningV423TraversalOwnedGeneration,
                            targetSequence = learningV423Continuation.TargetSequence,
                            detail = learningV423FollowDetail,
                            body = Vec(bot.Position),
                            bodyRelocated = false,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "keepForwardPhysicalConsumerAliveWhileFreshFollowPathIsUnavailable"
                        });
                    }
                }
                return;
            }

            bool removedStaleGuard = false;
            if (ChainHandoffAuthorityGuards.TryGetValue(bot.ProfileId, out ChainHandoffAuthorityGuard staleGuard) &&
                staleGuard != null && staleGuard.Generation == raidGeneration)
            {
                ChainHandoffAuthorityGuards.Remove(bot.ProfileId);
                removedStaleGuard = true;
            }

            bool learningV419FreshFollowPrimed = false;
            bool learningV423PhysicalContinuationInstalled = false;
            bool learningV419EpochScrubbed = false;
            string learningV419RetireDetail = string.Empty;
            string learningV419ScrubDetail = string.Empty;
            string learningV419PrimeDetail = string.Empty;
            string learningV423PhysicalContinuationDetail = string.Empty;
            {
                // A pathless traversal may finish while native BotMover still remembers the PRE-
                // traversal path epoch. V418 runtime proved that blindly changing only the writer
                // domain to Follow can let method_10 consume that stale epoch and snap the body
                // several metres backward/downward. Retire topology + scrub bookkeeping at the
                // CURRENT physical body, then release ownership only if a fresh Follow path can
                // actually be installed from this epoch. V423 adds a distinct physical breadcrumb
                // consumer when Follow/NavMesh is unavailable; never report that fallback as a
                // fresh Follow path.
                TryRetireNativeMoverPathPreserveLocomotion(
                    bot, "learningV419OrphanTraversalFreshFollow", out learningV419RetireDetail);
                learningV419EpochScrubbed = TryScrubLearningV364NativeMoverEpochAnchor(
                    bot, bot.Position, "learningV419OrphanTraversalFreshFollow",
                    out learningV419ScrubDetail);
                learningV419FreshFollowPrimed = TryHandoffLearningV419TraversalToFreshFollowConsumer(
                    bot, generation, "learningV419OrphanTraversalFreshFollow",
                    "post-traversal-fresh-epoch", out learningV419PrimeDetail);
                if ((!learningV419FreshFollowPrimed))
                {
                    long learningV423ContinuationGeneration =
                        FollowerMovementWriterAuthority.GetCurrentGeneration(
                            bot, out FollowerMovementWriterAuthority.WriterDomain learningV423ContinuationOwner);
                    learningV423PhysicalContinuationInstalled =
                        learningV423ContinuationOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                        learningV423ContinuationGeneration > 0 &&
                        TryInstallLearningV423PhysicalContinuationConsumer(
                            bot, learningV423ContinuationGeneration,
                            "learningV423OrphanTraversalPhysicalContinuation",
                            out learningV423PhysicalContinuationDetail);
                }
                // V4.39: if neither a fresh path nor a physical breadcrumb consumer exists, the
                // old path topology has already been retired and its mover epoch scrubbed. Keeping
                // Traversal ownership after this point creates an owner with no producer. Release
                // only the ownership domain to Follow so normal reacquisition can retry on later
                // ticks; do not issue GoToPoint and do not move the body here.
                if ((!learningV419FreshFollowPrimed) &&
                    !learningV423PhysicalContinuationInstalled &&
                    learningV419EpochScrubbed &&
                    bot.Mover?.ActualPathController?.HavePath != true)
                {
                    long learningV439OrphanGeneration =
                        FollowerMovementWriterAuthority.GetCurrentGeneration(
                            bot, out FollowerMovementWriterAuthority.WriterDomain learningV439OrphanOwner);
                    if (learningV439OrphanOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                        learningV439OrphanGeneration > 0)
                    {
                        FollowerMovementWriterAuthority.TransitionTraversalToFollowIfCurrent(
                            bot, learningV439OrphanGeneration,
                            "learningV439PathlessOrphanFollowReacquire:" + (source ?? "unknown"));
                        long learningV439AfterGeneration =
                            FollowerMovementWriterAuthority.GetCurrentGeneration(
                                bot, out FollowerMovementWriterAuthority.WriterDomain learningV439AfterOwner);
                        bool learningV439ReleasedToFollow =
                            learningV439AfterOwner == FollowerMovementWriterAuthority.WriterDomain.Follow &&
                            learningV439AfterGeneration != learningV439OrphanGeneration;
                        if (learningV439ReleasedToFollow)
                        {
                            ArmFollowReacquireAfterAuthorityReset(
                                bot, "learningV439PathlessOrphanFollowReacquire:" + (source ?? "unknown"));
                        }
                        WriteEvent("learningV439PathlessFollowOwnershipFallback", bot, new
                        {
                            source = source ?? "unknown",
                            previousGeneration = learningV439OrphanGeneration,
                            afterGeneration = learningV439AfterGeneration,
                            afterOwner = learningV439AfterOwner.ToString(),
                            released = learningV439ReleasedToFollow,
                            staleTopologyDetail = learningV419RetireDetail,
                            epochScrubbed = learningV419EpochScrubbed,
                            epochScrubDetail = learningV419ScrubDetail,
                            moverHasPath = bot.Mover?.ActualPathController?.HavePath == true,
                            body = Vec(bot.Position),
                            bodyRelocated = false,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "retiredPathlessTraversalOwnerWithoutAnyPhysicalProducerReleasesToFollowReacquireLease"
                        });
                    }
                }
            }

            long afterGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain afterOwner);
            bool released = afterOwner == FollowerMovementWriterAuthority.WriterDomain.Follow &&
                afterGeneration != generation;
            if (released && !learningV419FreshFollowPrimed && !learningV423PhysicalContinuationInstalled)
            {
                ArmFollowReacquireAfterAuthorityReset(
                    bot, "learningV368OrphanTraversalProducer:" + (source ?? "unknown"));
            }
            if ((ShouldEmitDiagnostic("learningV419OrphanTraversalFreshFollowEpoch", bot, 0.18f)))
            {
                string learningV423OrphanEvent = learningV419FreshFollowPrimed
                    ? "learningV419OrphanTraversalFreshFollowEpochInstalled"
                    : (learningV423PhysicalContinuationInstalled
                        ? "learningV423OrphanTraversalPhysicalContinuationInstalled"
                        : "learningV419OrphanTraversalFollowReleaseDeferred");
                WriteEvent(learningV423OrphanEvent, bot, new
                {
                    source = source ?? "unknown",
                    generation,
                    afterGeneration,
                    afterOwner = afterOwner.ToString(),
                    staleTopologyDetail = learningV419RetireDetail,
                    epochScrubbed = learningV419EpochScrubbed,
                    epochScrubDetail = learningV419ScrubDetail,
                    freshFollowPrimed = learningV419FreshFollowPrimed,
                    freshFollowDetail = learningV419PrimeDetail,
                    physicalContinuationInstalled = learningV423PhysicalContinuationInstalled,
                    physicalContinuationDetail = learningV423PhysicalContinuationDetail,
                    body = Vec(bot.Position),
                    bodyRelocated = false,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = learningV419FreshFollowPrimed
                        ? "followOwnershipBeginsOnlyAfterFreshPathSharesCurrentPhysicalEpoch"
                        : (learningV423PhysicalContinuationInstalled
                            ? "forwardPhysicalBreadcrumbConsumerOwnsContinuationUntilFreshFollowExists"
                            : (afterOwner == FollowerMovementWriterAuthority.WriterDomain.Follow
                                ? "pathlessOrphanReleasedToFollowReacquireLeaseAfterTopologyRetireAndEpochScrub"
                                : "retainTraversalEpochAndNativeLocomotionUntilFreshConsumerExists"))
                });
            }
            WriteEvent("learningV368OrphanTraversalAuthorityReleased", bot, new
            {
                source = source ?? "unknown",
                generation,
                afterGeneration,
                afterOwner = afterOwner.ToString(),
                removedStaleGuard,
                released,
                activeProbe = false,
                liveChainProducer = false,
                v419FreshFollowPrimed = learningV419FreshFollowPrimed,
                v423PhysicalContinuationInstalled = learningV423PhysicalContinuationInstalled,
                action = ((learningV419FreshFollowPrimed
                        ? "TraversalOwnerReturnsToFreshFollowConsumer"
                        : (learningV423PhysicalContinuationInstalled
                            ? "TraversalOwnerRetainsForwardPhysicalBreadcrumbConsumer"
                            : (released
                                ? "PathlessOrphanTraversalOwnerReleasedToFollowReacquireLease"
                                : "TraversalOwnerRetainedUntilFreshConsumerExists"))))
            });
        }

        internal static bool ResumeTraversalAuthorityAfterTeleport(BotOwner bot, string reason)
        {
            if (bot == null || string.IsNullOrEmpty(bot.ProfileId))
            {
                return false;
            }

            bool haveActiveProbe = TryGetActiveProbe(bot, out ProbeRuntime probe) && probe != null;
            bool haveAnyChainGuard = ChainHandoffAuthorityGuards.TryGetValue(
                bot.ProfileId, out ChainHandoffAuthorityGuard guard) &&
                guard != null && guard.Generation == raidGeneration && Time.time <= guard.ExpiresAt;
            bool haveActiveChainProducer = (TryGetLearningV368LiveChainTraversalProducer(bot, out guard));
            if (!haveActiveProbe && !haveActiveChainProducer)
            {
                if ((haveAnyChainGuard))
                {
                    ChainHandoffAuthorityGuards.Remove(bot.ProfileId);
                    WriteEvent("learningV368PostTeleportStaleChainGuardRejected", bot, new
                    {
                        reason = reason ?? "unknown",
                        nextEdgeId = guard?.NextEdgeId ?? 0,
                        chainId = guard?.ChainId ?? 0,
                        successorAuthorityAcquired = guard?.SuccessorAuthorityAcquired ?? false,
                        action = "doNotResumeTraversalWithoutLiveProbeOrLocalBridgeProducer"
                    });
                }
                return false;
            }

            // Teleport stabilization owns movement until this callback. Retire it atomically and
            // reacquire Traversal before any normal Follow tick can execute.
            long stabilizationTeleportOrigin = haveActiveProbe
                ? probe.TeleportWriterGeneration
                : (haveActiveChainProducer ? guard.TeleportWriterGeneration : 0);
            if (!FollowerMovementWriterAuthority.TransitionTeleportToFollowExact(
                bot, stabilizationTeleportOrigin, "traversalTeleportStabilizedBridge:" + (reason ?? "unknown")))
            {
                WriteEvent("v2TeleportRetirementOriginRejected", bot, new
                {
                    source = "stabilizedTraversalBridge",
                    originGeneration = stabilizationTeleportOrigin,
                    haveActiveProbe,
                    haveActiveChainProducer,
                    reason = reason ?? "unknown",
                    action = "rejectStaleStabilizationBeforeNewTraversalOwner"
                });
                return false;
            }
            if (haveActiveProbe) probe.TeleportWriterGeneration = 0;
            if (haveActiveChainProducer) guard.TeleportWriterGeneration = 0;
            long generation = FollowerMovementWriterAuthority.BeginTraversal(
                bot,
                "resumeTraversalAfterTeleport:" + (reason ?? "unknown"));
            if (generation <= 0)
            {
                return false;
            }

            if (haveActiveProbe)
            {
                probe.MovementWriterGeneration = generation;
                probe.OwnershipLeaseExpiresAt = Mathf.Max(
                    probe.OwnershipLeaseExpiresAt,
                    Time.time + TraversalOwnershipLeaseSeconds);
            }
            if (haveActiveChainProducer)
            {
                guard.ExpiresAt = Mathf.Max(guard.ExpiresAt, Time.time + 5.0f);
                guard.LocalBridgeActive = false;
                guard.LocalBridgeLastProgressAt = Time.time;
                guard.LocalBridgeLastDistance = IsFinite(guard.NextEntry)
                    ? Vector3.Distance(bot.Position, guard.NextEntry)
                    : float.MaxValue;
            }
            int learningV375RecoveryChainId = haveActiveProbe
                ? probe.TraversalChainId
                : (haveActiveChainProducer ? guard.ChainId : 0);
            RebaseLearningV375PersistentRouteTransactionAfterRecovery(
                bot, learningV375RecoveryChainId, generation, bot.Position,
                "resumeTraversalAfterTeleport:" + (reason ?? "unknown"));

            WriteEvent("traversalAuthorityResumedAfterTeleportStabilization", bot, new
            {
                reason = reason ?? "unknown",
                generation,
                activeProbe = haveActiveProbe,
                activeChain = haveActiveChainProducer,
                edgeId = haveActiveProbe ? probe.LearnedEdgeId : 0,
                nextEdgeId = haveActiveChainProducer ? guard.NextEdgeId : 0,
                chainId = haveActiveProbe ? probe.TraversalChainId : (haveActiveChainProducer ? guard.ChainId : 0)
            });
            return true;
        }

        internal static bool AllowsFollowDuringChainHandoff(BotOwner bot)
        {
            // CompileFix42 compatibility surface only. Intermediate chain movement is never
            // Follow-owned; the runtime drives the successor directly.
            return false;
        }

        internal static bool TryGetChainHandoffSuccessorTarget(
            BotOwner bot,
            out Vector3 successorEntry,
            out int successorEdgeId)
        {
            successorEntry = default;
            successorEdgeId = 0;
            string profileId = bot?.ProfileId ?? string.Empty;
            Player player = bot?.GetPlayer;
            if (string.IsNullOrEmpty(profileId) || player == null ||
                !ChainHandoffAuthorityGuards.TryGetValue(profileId, out ChainHandoffAuthorityGuard guard) ||
                guard == null || guard.Generation != raidGeneration || Time.time > guard.ExpiresAt ||
                guard.SuccessorAuthorityAcquired || !IsFinite(guard.NextEntry) || guard.NextEdgeId <= 0)
            {
                return false;
            }

            // CompileFix52: this helper can be called before the per-frame guard updater. Treat
            // MovementWriter generation as the authoritative route-intent token here as well so an
            // abandoned RouteMission cannot rehydrate a stale successor for even one frame.
            long currentMovementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain currentMovementOwner);
