            if (LearnedTraversalCommitments.TryGetValue(bot.ProfileId, out LearnedTraversalCommitment commitment) &&
                commitment != null)
            {
                return true;
            }
            if (ProvisionalWalkThroughReservations.TryGetValue(bot.ProfileId, out ProvisionalWalkThroughReservation reservation) &&
                reservation != null && Time.time <= reservation.ExpiresAt)
