            // blind spot where a PathComplete approach could stop 0.6-0.9 m before a proven Vault and
            // wait several seconds for the ordinary 1-2 s Follow cadence before recovery was eligible.
            if ((TryGetActiveFollowerRouteMission(bot, out FollowerRouteMission routeMission)) &&
                routeMission.CurrentStepIndex >= 0 && routeMission.CurrentStepIndex < routeMission.Steps.Count)
            {
                FollowerRouteMissionStep step = routeMission.Steps[routeMission.CurrentStepIndex];
                if (step != null && IsFinite(step.Entry) && IsFinite(bot.Position))
                {
                    bool adjacent = IsRouteMissionSameChainImmediateSuccessor(routeMission, routeMission.CurrentStepIndex);
                    float localWindow = adjacent
                        ? RouteMissionTraversalAdjacentBridgeMaxDistance
                        : RouteMissionExecutionCommitDistance;
