                    ? GetPlanarDistance(bot.Position, lease.NormalFollowAckLastPosition)
                    : 0f;
                float sampleSeconds = lease.NormalFollowAckLastSampleAt > 0f
                    ? Mathf.Max(0.001f, Time.time - lease.NormalFollowAckLastSampleAt)
                    : Mathf.Max(0.001f, Time.deltaTime);
                float leaderStep = IsFinite(lease.NormalFollowAckLastLeaderPosition)
                    ? GetPlanarDistance(leaderPosition, lease.NormalFollowAckLastLeaderPosition)
                    : 0f;
                float leaderSpeed = leaderStep / sampleSeconds;
                float followerSpeed = bodyStep / sampleSeconds;
                bool leaderMoving = leaderSpeed >= PostTraversalNormalFollowAckLeaderMovingSpeed;
                float windowRegression = leaderDistance - lease.NormalFollowAckWindowStartDistance;

                if (!leaderMoving && leaderDistance <= ExitAuthorityNoCommandLeaderDistance)
                {
                    targetAligned = true;
                }

                bool physicalEvidence = leaderMoving
                    ? followerSpeed >= PostTraversalNormalFollowAckFollowerMovingSpeed
                    : (leaderDistance <= ExitAuthorityNoCommandLeaderDistance || moverActive ||
                       followerSpeed >= PostTraversalNormalFollowAckStationaryFollowerSpeed);
                bool gapHealthy = gapRegression <= 0.10f &&
                                  windowRegression <= PostTraversalNormalFollowAckWindowMaxRegression;
                bool insideReleaseEnvelope = leaderDistance <= PostTraversalNormalFollowAckReleaseDistance;
                bool ackHealthy = targetAligned && physicalEvidence && gapHealthy && insideReleaseEnvelope;

                lease.NormalFollowAckLastLeaderDistance = leaderDistance;
                lease.NormalFollowAckLastPosition = bot.Position;
                lease.NormalFollowAckLastLeaderPosition = leaderPosition;
                lease.NormalFollowAckLastSampleAt = Time.time;

                bool hardRegression = leaderDistance > PostTraversalNormalFollowReacquireDistance ||
                                      gapRegression > PostTraversalNormalFollowAckMaxRegression ||
                                      windowRegression > PostTraversalNormalFollowAckWindowHardRegression ||
                                      (ackElapsed >= PostTraversalNormalFollowAckTargetGraceSeconds && !targetAligned);
                if (hardRegression || ackElapsed >= PostTraversalNormalFollowAckMaxSeconds)
                {
                    lease.NormalFollowAckActive = false;
                    lease.NormalFollowAckStableSince = -1f;
                    lease.WithinSettleSince = -1f;
                    lease.ExpiresAt = Mathf.Max(
                        lease.ExpiresAt,
                        Time.time + PostTraversalChaseLeaseMinSeconds);
                    WriteEvent(hardRegression ? "postTraversalNormalFollowAckRejected" : "postTraversalNormalFollowAckTimedOut", bot, new
                    {
                        edgeId = lease.EdgeId,
                        leaderDistance,
                        bestLeaderDistance = lease.BestLeaderDistance,
                        reacquireDistance = PostTraversalNormalFollowReacquireDistance,
                        ackElapsed,
                        targetAligned,
                        haveFollowTarget,
                        targetLeaderDistance,
                        targetForwardDot,
                        moverActive,
                        bodyStep,
                        leaderSpeed,
                        followerSpeed,
                        leaderMoving,
                        windowRegression,
                        gapRegression
                    });
                    forceSprint = leaderDistance > lease.SettleDistance + 0.50f;
                    return true;
                }

                if (ackHealthy)
                {
                    if (lease.NormalFollowAckStableSince < 0f)
                    {
                        lease.NormalFollowAckStableSince = Time.time;
                        WriteEvent("postTraversalNormalFollowAckPhysicalCandidate", bot, new
                        {
                            edgeId = lease.EdgeId,
                            leaderDistance,
                            targetLeaderDistance,
                            targetForwardDot,
                            moverActive,
                            bodyStep,
                            leaderSpeed,
                            followerSpeed,
                            leaderMoving,
                            windowRegression
                        });
                    }
                    else if (Time.time - lease.NormalFollowAckStableSince >= PostTraversalNormalFollowAckStableSeconds)
                    {
                        lease.NormalFollowAckActive = false;
                        lease.PostAckOwnershipActive = true;
                        lease.PostAckOwnershipStartedAt = Time.time;
                        lease.PostAckOwnershipUntil = Time.time + PostTraversalFollowOwnershipLeaseSeconds;
                        lease.PostAckLastLeaderPosition = leaderPosition;
                        lease.PostAckLastSampleAt = Time.time;
                        lease.PostAckLastTarget = followTarget;
                        lease.PostAckLastTargetSource = followTargetSource;
                        lease.PostAckNextTraceAt = Time.time;
                        RestartPostTraversalFollowEvaluationAfterAck(bot);
                        WriteEvent("postTraversalNormalFollowAckSatisfied", bot, new
                        {
                            edgeId = lease.EdgeId,
                            leaderDistance,
                            bestLeaderDistance = lease.BestLeaderDistance,
                            stableSeconds = Time.time - lease.NormalFollowAckStableSince,
                            ackElapsed,
                            targetLeaderDistance,
                            targetForwardDot,
                            moverActive,
                            bodyStep,
                            leaderSpeed,
                            followerSpeed,
                            leaderMoving,
                            windowRegression,
                            followTargetSource,
                            ownershipLeaseSeconds = PostTraversalFollowOwnershipLeaseSeconds,
                            elapsed = Time.time - lease.ArmedAt
                        });
                        return false;
                    }
                }
                else
                {
                    lease.NormalFollowAckStableSince = -1f;
                }

                // Ordinary Follow owns the proving window. The lease still monitors it every tick.
                return false;
            }

            if (leaderDistance <= lease.SettleDistance)
            {
                if (lease.WithinSettleSince < 0f)
                {
                    lease.WithinSettleSince = Time.time;
                    WriteEvent("postTraversalChaseLeaseSettleCandidate", bot, new
                    {
                        edgeId = lease.EdgeId,
                        leaderDistance,
                        settleDistance = lease.SettleDistance,
                        stableRequired = PostTraversalChaseStableHoldSeconds
                    });
                }

                if (Time.time - lease.WithinSettleSince >= PostTraversalChaseStableHoldSeconds)
                {
                    lease.NormalFollowAckActive = true;
                    lease.NormalFollowAckStartedAt = Time.time;
                    lease.NormalFollowAckStableSince = -1f;
                    lease.NormalFollowAckLastLeaderDistance = leaderDistance;
                    lease.NormalFollowAckLastPosition = bot.Position;
                    lease.NormalFollowAckLastLeaderPosition = leaderPosition;
                    lease.NormalFollowAckLastSampleAt = Time.time;
                    lease.NormalFollowAckWindowStartDistance = leaderDistance;
                    lease.NormalFollowFreshEpochIssued = false;
                    lease.NormalFollowFreshEpochIssuedAt = 0f;
                    lease.NormalFollowFreshEpochTarget = Vector3.zero;
                    lease.NormalFollowFreshEpochStatus = null;
                    WriteEvent("postTraversalNormalFollowAckArmed", bot, new
                    {
                        edgeId = lease.EdgeId,
                        leaderDistance,
                        bestLeaderDistance = lease.BestLeaderDistance,
                        settleDistance = lease.SettleDistance,
                        stableFor = Time.time - lease.WithinSettleSince,
                        ackMaxSeconds = PostTraversalNormalFollowAckMaxSeconds,
                        ackStableSeconds = PostTraversalNormalFollowAckStableSeconds,
                        releaseDistance = PostTraversalNormalFollowAckReleaseDistance,
                        reacquireDistance = PostTraversalNormalFollowReacquireDistance,
                        elapsed = Time.time - lease.ArmedAt
                    });
                    // V3.8 starts a new Follow target epoch from the CURRENT leader only once.
                    // This replaces stale pre-traversal mover targets without adding a retry loop.
                    TryInstallPostTraversalFreshFollowEpoch(
                        bot, leaderPosition, lease, "normalFollowAckArmed");
                    return false;
                }
            }
            else
            {
                lease.WithinSettleSince = -1f;
            }

            if (Time.time >= lease.NextLocomotionTraceAt)
            {
                lease.NextLocomotionTraceAt = Time.time + PostTraversalFollowLocomotionTraceIntervalSeconds;
                Player chasePlayer = bot.GetPlayer ?? bot.AIData?.Player;
                bool moverSprinting = bot.Mover?.Sprinting == true;
                bool playerSprintEnabled = chasePlayer?.MovementContext?.IsSprintEnabled == true;
                bool canSprint = chasePlayer?.MovementContext?.CanSprint == true;
                bool canWalk = chasePlayer?.MovementContext?.CanWalk == true;
                float clampedSpeed = chasePlayer?.MovementContext != null ? chasePlayer.MovementContext.ClampedSpeed : -1f;
                WriteEvent("postTraversalChaseLocomotionState", bot, new
                {
                    edgeId = lease.EdgeId,
                    leaderDistance,
                    bestLeaderDistance = lease.BestLeaderDistance,
                    closingSpeed = lease.ChaseClosingSpeedEma,
                    leaderSpeed = lease.ChaseLeaderSpeedEma,
                    sprintLeaseProtected = lease.ChaseLeaderSpeedEma >= PostTraversalSprintLeaseLeaderSpeed &&
                        leaderDistance >= PostTraversalSprintLeaseMinDistance,
                    moverSprinting,
                    playerSprintEnabled,
                    sprintStateMismatch = moverSprinting != playerSprintEnabled,
                    canSprint,
                    canWalk,
                    clampedSpeed,
                    moverPaused = bot.Mover?.Pause == true,
                    targetPose = bot.Mover != null ? bot.Mover.TargetPose : -1f
                });
            }

            if (Time.time > lease.ExpiresAt)
            {
                float totalLeaseAge = Time.time - lease.ArmedAt;
                if (!lease.SettleGraceUsed &&
                    lease.WithinSettleSince >= 0f &&
                    leaderDistance <= lease.SettleDistance)
                {
                    lease.SettleGraceUsed = true;
                    lease.ExpiresAt = Time.time + PostTraversalChaseSettleGraceSeconds;
                    WriteEvent("postTraversalChaseSettleGraceArmed", bot, new
                    {
                        edgeId = lease.EdgeId,
                        leaderDistance,
                        bestLeaderDistance = lease.BestLeaderDistance,
                        withinSettleFor = Time.time - lease.WithinSettleSince,
                        stableRequired = PostTraversalChaseStableHoldSeconds,
                        graceSeconds = PostTraversalChaseSettleGraceSeconds,
                        totalLeaseAge
                    });
                    forceSprint = lease.ChaseLeaderSpeedEma >= PostTraversalSprintLeaseLeaderSpeed &&
                        leaderDistance >= PostTraversalSprintLeaseMinDistance;
                    return true;
                }
                bool meaningfulConvergence = lease.ChaseClosingSpeedEma >= PostTraversalChaseConvergenceClosingSpeed &&
                    leaderDistance <= lease.InitialLeaderDistance - 1.0f;
                bool nearSettleAndImproving = lease.ChaseClosingSpeedEma >= 0f &&
                    leaderDistance <= lease.SettleDistance + 1.75f &&
                    leaderDistance <= lease.BestLeaderDistance + 0.75f;
                if (lease.ConvergenceExtensions < PostTraversalChaseMaxConvergenceExtensions &&
                    totalLeaseAge < PostTraversalChaseMaximumTotalSeconds &&
                    (meaningfulConvergence || nearSettleAndImproving))
                {
                    float remainingBudget = Mathf.Max(0f, PostTraversalChaseMaximumTotalSeconds - totalLeaseAge);
                    float extension = Mathf.Min(PostTraversalChaseConvergenceExtensionSeconds, remainingBudget);
                    if (extension > 0.10f)
                    {
                        lease.ConvergenceExtensions++;
                        lease.ExpiresAt = Time.time + extension;
                        WriteEvent("postTraversalChaseLeaseExtendedForConvergence", bot, new
                        {
                            edgeId = lease.EdgeId,
                            leaderDistance,
                            bestLeaderDistance = lease.BestLeaderDistance,
                            initialLeaderDistance = lease.InitialLeaderDistance,
                            closingSpeed = lease.ChaseClosingSpeedEma,
                            extension,
                            extensionCount = lease.ConvergenceExtensions,
                            totalLeaseAge
                        });
                        forceSprint = (lease.ChaseLeaderSpeedEma >= PostTraversalSprintLeaseLeaderSpeed &&
                                       leaderDistance >= PostTraversalSprintLeaseMinDistance) ||
                                      leaderDistance > lease.SettleDistance;
                        return true;
                    }
                }

                PostTraversalChaseLeases.Remove(bot.ProfileId);
                bool learningV430DeferredOwnerRollover =
                    QueueLearningV430DeferredPostTraversalFollowRollover(
                        bot, lease.EdgeId, "postTraversalAckRecoveryExhausted", armFollowReacquire: true);
                if (!learningV430DeferredOwnerRollover)
                {
                    FollowerMovementWriterAuthority.TransitionPostTraversalToFollowExact(bot, lease.PostTraversalWriterGeneration, "postTraversalAckRecoveryExhausted");
                }
                if (PostTraversalIntegrityWatches.TryGetValue(bot.ProfileId, out PostTraversalIntegrityWatch pendingWatch) &&
                    pendingWatch != null && pendingWatch.AwaitingFollowAck)
                {
                    pendingWatch.AwaitingFollowAck = false;
                    pendingWatch.ForcedFollowAckFailure = true;
                    pendingWatch.ExpiresAt = Time.time;
                }
                if (!learningV430DeferredOwnerRollover)
                {
                    ArmFollowReacquireAfterAuthorityReset(bot, "postTraversalAckRecoveryExhausted");
                }
                WriteEvent("postTraversalChaseLeaseExpired", bot, new
                {
                    edgeId = lease.EdgeId,
                    leaderDistance,
                    bestLeaderDistance = lease.BestLeaderDistance,
                    initialLeaderDistance = lease.InitialLeaderDistance,
                    settleDistance = lease.SettleDistance,
                    duration = lease.ExpiresAt - lease.ArmedAt,
                    ordinaryFollowReacquireArmed = true
                });
                return false;
            }

            bool movingLeaderSprintLease = lease.ChaseLeaderSpeedEma >= PostTraversalSprintLeaseLeaderSpeed &&
                                           leaderDistance >= PostTraversalSprintLeaseMinDistance;
            forceSprint = movingLeaderSprintLease ||
                          (leaderDistance > lease.SettleDistance &&
                           (lease.PreserveSprint || leaderDistance >= lease.SettleDistance + 1.0f));
            return true;
        }

        // RC67: one existing live RouteStep is the only authority for the Climb
        // walk/pose lease. No new dictionary, retry timer, ownership generation,
        // persisted state or special Edge ID. This is intentionally unavailable
        // after Native probe admission, combat preemption, or route retirement.
        internal static bool IsV2ClimbEntryWalkPoseOwned(BotOwner bot)
        {
            if (bot == null || string.IsNullOrEmpty(bot.ProfileId) ||
                !IsLiveBot(bot) || HasActiveTraversalProbe(bot) ||
                IsTeleportTransactionActive(bot) ||
                FollowerMedical.IsUsingMedical(bot) ||
                bot.Memory?.HaveEnemy == true || bot.Memory?.IsUnderFire == true ||
                bot.GetPlayer?.MovementContext == null ||
                !FollowerRouteMissions.TryGetValue(bot.ProfileId, out FollowerRouteMission mission) ||
                mission?.Steps == null || mission.CurrentStepIndex < 0 ||
                mission.CurrentStepIndex >= mission.Steps.Count)
                return false;
            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null ||
                !string.Equals(step.Kind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                !step.Rc48MoverPathRetired)
                return false;
            FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            return owner == FollowerMovementWriterAuthority.WriterDomain.Follow;
        }

        internal static void ReportV2RC67ClimbSprintRearmRejected(BotOwner bot, string caller)
        {
            if (bot == null || !ShouldEmitDiagnostic(
                    "v2rc67ClimbSprintRearmRejected:" + (bot.ProfileId ?? string.Empty),
                    bot, 0.30f))
                return;
            WriteEvent("v2rc67ClimbSprintRearmRejected", bot, new
            {
                caller,
                state = bot.GetPlayer?.CurrentStateName.ToString() ?? "Unknown",
                eftSprintEnabled = bot.GetPlayer?.MovementContext?.IsSprintEnabled == true,
                moverSprinting = bot.Mover?.Sprinting == true,
                action = "existingCurrentClimbStepWalkPoseLeaseOutranksUnscopedSprintEnable"
            });
        }

        internal static bool ShouldProtectPostTraversalSprint(BotOwner bot, out string reason)
        {
            reason = string.Empty;
            if (bot == null || string.IsNullOrEmpty(bot.ProfileId) ||
                !PostTraversalChaseLeases.TryGetValue(bot.ProfileId, out PostTraversalChaseLease lease) ||
                lease == null)
            {
                return false;
            }

            Player followerPlayer = bot.GetPlayer ?? bot.AIData?.Player;
            if (bot.Memory?.HaveEnemy == true ||
                followerPlayer?.MovementContext?.CanSprint != true ||
                followerPlayer.MovementContext.CanWalk != true ||
                lease.ChaseLeaderSpeedEma < PostTraversalSprintLeaseLeaderSpeed ||
                lease.LastChaseLeaderDistance < PostTraversalSprintLeaseMinDistance)
            {
                return false;
            }

            reason = lease.PostAckOwnershipActive ? "postAckOwnership" :
                     lease.NormalFollowAckActive ? "normalFollowAck" : "postTraversalChase";
            return true;
        }

        internal static void RecordMovementWriterAuthorityEvent(BotOwner bot, string eventType, object payload)
        {
            if (string.IsNullOrWhiteSpace(eventType))
            {
                return;
            }
            WriteEvent(eventType, bot, payload);
        }

        internal static Vector3 CaptureLearningV338WriterBodyStart(BotMover mover)
        {
            if ((mover == null))
            {
                return new Vector3(float.NaN, float.NaN, float.NaN);
            }

            BotOwner owner = mover._owner;
            if (owner == null)
            {
                return new Vector3(float.NaN, float.NaN, float.NaN);
            }
            if (TryGetActiveProbe(owner, out ProbeRuntime probe) && probe != null && probe.Generation == raidGeneration)
            {
                Vector3 activePosition = probe.Player != null ? probe.Player.Position : owner.Position;
                return IsFinite(activePosition) ? activePosition : new Vector3(float.NaN, float.NaN, float.NaN);
            }
            if ((PostTraversalIntegrityWatches.TryGetValue(owner.ProfileId ?? string.Empty, out PostTraversalIntegrityWatch watch)) &&
                watch != null && watch.ExpiresAt >= Time.time)
            {
                Vector3 watchPosition = owner.GetPlayer != null ? owner.GetPlayer.Position : owner.Position;
                return IsFinite(watchPosition) ? watchPosition : new Vector3(float.NaN, float.NaN, float.NaN);
            }
            return new Vector3(float.NaN, float.NaN, float.NaN);
        }

        internal static void ReportLearningV338WriterBodyEnd(BotMover mover, Vector3 before, string writerName)
        {
            if ((mover == null) || !IsFinite(before))
            {
                return;
            }

            try
            {
                BotOwner owner = mover._owner;
                if (owner == null)
                {
                    return;
                }
                bool hasActiveProbe = TryGetActiveProbe(owner, out ProbeRuntime probe) &&
                                      probe != null && probe.Generation == raidGeneration;
                if (!hasActiveProbe)
                {
                    if ((!PostTraversalIntegrityWatches.TryGetValue(owner.ProfileId ?? string.Empty, out PostTraversalIntegrityWatch watch)) ||
                        watch == null || watch.ExpiresAt < Time.time)
                    {
                        return;
                    }
                    Vector3 postAfter = owner.GetPlayer != null ? owner.GetPlayer.Position : owner.Position;
                    if (!IsFinite(postAfter))
                    {
                        return;
                    }
                    Vector3 postDelta = postAfter - before;
                    float postPlanar = new Vector2(postDelta.x, postDelta.z).magnitude;
                    float postVerticalAbs = Mathf.Abs(postDelta.y);
                    string postWriter = string.IsNullOrWhiteSpace(writerName) ? "unknownNativeWriter" : writerName;
                    if ((postPlanar >= LearningV338BodyDeltaPlanarTelemetryThreshold ||
                         postVerticalAbs >= LearningV338BodyDeltaVerticalTelemetryThreshold) &&
                        ShouldEmitDiagnostic("learningV343PostTraversalKnownWriterBodyDelta:" + postWriter, owner, 0.02f))
                    {
                        long postGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(owner, out FollowerMovementWriterAuthority.WriterDomain postOwner);
                        WriteEvent("learningV343PostTraversalKnownWriterBodyDelta", owner, new
                        {
                            edgeId = watch.EdgeId,
                            episodeId = watch.EpisodeId,
                            chainId = watch.CompletedChainId,
                            writer = postWriter,
                            before = Vec(before),
                            after = Vec(postAfter),
                            planarDelta = postPlanar,
                            verticalDelta = postDelta.y,
                            movementOwner = postOwner.ToString(),
                            movementGeneration = postGeneration,
                            watchGeneration = watch.MovementGeneration,
                            releasePosition = Vec(watch.ReleasePosition),
                            watchAge = Time.time - watch.ArmedAt
                        });
                    }
                    return;
                }

                Vector3 after = probe.Player != null ? probe.Player.Position : owner.Position;
                if (!IsFinite(after))
                {
                    return;
                }

                Vector3 delta = after - before;
                float planar = new Vector2(delta.x, delta.z).magnitude;
                float vertical = Mathf.Abs(delta.y);
                string writer = string.IsNullOrWhiteSpace(writerName) ? "unknownNativeWriter" : writerName;

                if ((planar >= LearningV338BodyDeltaPlanarTelemetryThreshold ||
                     vertical >= LearningV338BodyDeltaVerticalTelemetryThreshold) &&
                    ShouldEmitDiagnostic("learningV338KnownWriterBodyDelta:" + writer, owner, 0.04f))
                {
                    FollowerMovementWriterAuthority.WriterDomain currentOwner;
                    long currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(owner, out currentOwner);
                    WriteEvent("learningV338KnownWriterBodyDelta", owner, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        chainId = probe.TraversalChainId,
                        kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                        stage = probe.Stage.ToString(),
                        playerState = probe.Player != null ? probe.Player.CurrentStateName.ToString() : "unknown",
                        writer,
                        before = Vec(before),
                        after = Vec(after),
                        planarDelta = planar,
                        verticalDelta = delta.y,
                        fixedDeltaTime = Time.fixedDeltaTime,
                        movementOwner = currentOwner.ToString(),
                        movementGeneration = currentGeneration,
                        probeGeneration = probe.MovementWriterGeneration,
                        exclusiveMoverGate = probe.ExclusiveMoverGate,
                        grounded = probe.Player?.MovementContext?.IsGrounded == true,
                        inputDirection = probe.Player != null ? Vec2(probe.Player.InputDirection) : null,
                        relinkSuppressionExpected = ShouldSkipNavMeshRelink(mover)
                    });
                }

                probe.LearningV338BodySampleInitialized = true;
                probe.LearningV338LastBodySamplePosition = after;
                probe.LearningV338LastBodySampleAt = Time.time;
                probe.LearningV338LastBodySampleSource = "writer:" + writer;
            }
            catch
            {
                // V3.38 is diagnostic-only and must never perturb movement on telemetry failure.
            }
        }

        private static void ObserveLearningV338BodyBoundary(ProbeRuntime probe, string source)
        {
            if ((probe?.Bot == null))
            {
                return;
            }

            try
            {
                Vector3 current = probe.Player != null ? probe.Player.Position : probe.Bot.Position;
                if (!IsFinite(current))
                {
                    return;
                }

                if (!probe.LearningV338BodySampleInitialized || !IsFinite(probe.LearningV338LastBodySamplePosition))
                {
                    probe.LearningV338BodySampleInitialized = true;
                    probe.LearningV338LastBodySamplePosition = current;
                    probe.LearningV338LastBodySampleAt = Time.time;
                    probe.LearningV338LastBodySampleSource = source ?? "unknown";
                    return;
                }

                Vector3 delta = current - probe.LearningV338LastBodySamplePosition;
                float planar = new Vector2(delta.x, delta.z).magnitude;
                float vertical = Mathf.Abs(delta.y);
                float elapsed = probe.LearningV338LastBodySampleAt >= 0f
                    ? Mathf.Max(0f, Time.time - probe.LearningV338LastBodySampleAt)
                    : 0f;
                bool meaningful = planar >= LearningV338BodyDeltaPlanarTelemetryThreshold ||
                                  vertical >= LearningV338BodyDeltaVerticalTelemetryThreshold;

                if (meaningful && ShouldEmitDiagnostic("learningV338BodyAttributionBoundary:" + (source ?? "unknown"), probe.Bot, 0.04f))
                {
                    FollowerMovementWriterAuthority.WriterDomain currentOwner;
                    long currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(probe.Bot, out currentOwner);
                    string previousSource = probe.LearningV338LastBodySampleSource ?? "unknown";
                    bool previousWasKnownWriter = previousSource.StartsWith("writer:", StringComparison.Ordinal);
                    WriteEvent("learningV338BodyAttributionBoundary", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        chainId = probe.TraversalChainId,
                        kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                        stage = probe.Stage.ToString(),
                        playerState = probe.Player != null ? probe.Player.CurrentStateName.ToString() : "unknown",
                        source = source ?? "unknown",
                        previousSource,
                        previousWasKnownWriter,
                        from = Vec(probe.LearningV338LastBodySamplePosition),
                        to = Vec(current),
                        planarDelta = planar,
                        verticalDelta = delta.y,
                        elapsedSeconds = elapsed,
                        movementOwner = currentOwner.ToString(),
                        movementGeneration = currentGeneration,
                        probeGeneration = probe.MovementWriterGeneration,
                        exclusiveMoverGate = probe.ExclusiveMoverGate,
                        grounded = probe.Player?.MovementContext?.IsGrounded == true,
                        inputDirection = probe.Player != null ? Vec2(probe.Player.InputDirection) : null
                    });
                }

                probe.LearningV338BodySampleInitialized = true;
                probe.LearningV338LastBodySamplePosition = current;
                probe.LearningV338LastBodySampleAt = Time.time;
                probe.LearningV338LastBodySampleSource = source ?? "unknown";
            }
            catch
            {
                // Never let attribution telemetry influence traversal control flow.
            }
        }

        internal static void ReportPostTraversalSprintWriter(
            BotOwner bot, bool requestedSprint, bool moverSprinting, bool playerSprintEnabled, string caller, string reason)
        {
            if (bot == null || string.IsNullOrEmpty(bot.ProfileId) ||
                !PostTraversalChaseLeases.TryGetValue(bot.ProfileId, out PostTraversalChaseLease lease) ||
                lease == null)
            {
                return;
            }
            if (Time.time < lease.NextSprintWriterTraceAt)
            {
                return;
            }
            lease.NextSprintWriterTraceAt = Time.time + PostTraversalSprintWriterTraceCooldown;
            WriteEvent("postTraversalSprintWriterRequest", bot, new
            {
                edgeId = lease.EdgeId,
                requestedSprint,
                moverSprinting,
                playerSprintEnabled,
                leaderDistance = lease.LastChaseLeaderDistance,
                leaderSpeed = lease.ChaseLeaderSpeedEma,
                protectedByLease = !requestedSprint &&
                    lease.ChaseLeaderSpeedEma >= PostTraversalSprintLeaseLeaderSpeed &&
                    lease.LastChaseLeaderDistance >= PostTraversalSprintLeaseMinDistance,
                leasePhase = reason ?? string.Empty,
                caller = caller ?? string.Empty
            });
        }

        // RC107: RestartPostTraversalFollowEvaluationAfterAck is owned by FollowerCapabilityFollowControlHost.

        private static void ArmPostTraversalChaseLease(ProbeRuntime probe)
        {
            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }

            float leaderDistance = PostTraversalChaseSettleDistance;
            try
            {
                Player leader = FollowerEnvironment.LocalPlayer;
                if (IsLivePlayer(leader) && IsFinite(leader.Position) && probe.Player != null)
                {
                    leaderDistance = Vector3.Distance(probe.Player.Position, leader.Position);
                }
            }
            catch
            {
            }

            if ((probe.Bot != null) &&
                IsLivePlayer(FollowerEnvironment.LocalPlayer) && IsFinite(FollowerEnvironment.LocalPlayer.Position))
            {
                TryArmOrRefreshFollowerRouteMission(
                    probe.Bot, FollowerEnvironment.LocalPlayer.Position,
                    "learningV384PostTraversalFreshMission", true);
                if (TryGetActiveFollowerRouteMission(probe.Bot, out FollowerRouteMission freshMission) &&
                    freshMission != null && freshMission.Steps != null &&
                    freshMission.CurrentStepIndex >= 0 && freshMission.CurrentStepIndex < freshMission.Steps.Count)
                {
                    FollowerRouteMissionStep freshStep = freshMission.Steps[freshMission.CurrentStepIndex];
                    if (freshStep != null && freshStep.CurrentRaidRouteAuthority && freshStep.ChainLocalExecutable)
                    {
                        long issuedPostOrigin = 0;
                        if (PostTraversalIntegrityWatches.TryGetValue(profileId, out PostTraversalIntegrityWatch handoffWatch) &&
                            handoffWatch != null && handoffWatch.EdgeId == probe.LearnedEdgeId)
                        {
                            issuedPostOrigin = handoffWatch.MovementGeneration;
                        }
                        if (issuedPostOrigin <= 0 &&
                            PostTraversalChaseLeases.TryGetValue(profileId, out PostTraversalChaseLease handoffLease) &&
                            handoffLease != null && handoffLease.EdgeId == probe.LearnedEdgeId)
                        {
                            issuedPostOrigin = handoffLease.PostTraversalWriterGeneration;
                        }
                        if (FollowerMovementWriterAuthority.TransitionPostTraversalToFollowExact(
                            probe.Bot, issuedPostOrigin, "learningV384PostTraversalFreshMissionHandoff"))
                        {
                            PostTraversalChaseLeases.Remove(profileId);
                            WriteEvent("learningV384PostTraversalFreshMissionHandoff", probe.Bot, new
                        {
                            completedEdgeId = probe.LearnedEdgeId,
                            missionId = freshMission.MissionId,
                            stepIndex = freshMission.CurrentStepIndex,
                            nextEpisodeId = freshStep.EpisodeId,
                            nextEdgeId = freshStep.EdgeId,
                            nextKind = freshStep.Kind,
                            leaderDistance,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "freshCurrentRaidRouteMissionOwnsContinuationInsteadOfLowSpeedPostTraversalChase"
                            });
                            return;
                        }
                        WriteEvent("v2PostTraversalFreshHandoffOriginRejected", probe.Bot, new
                        {
                            completedEdgeId = probe.LearnedEdgeId,
                            missionId = freshMission.MissionId,
                            originGeneration = issuedPostOrigin,
                            action = "retainExistingOwnerAndFallbackToOrdinaryPostTraversalLease"
                        });
                    }
                }
            }

            float adaptiveSeconds = Mathf.Clamp(
                PostTraversalChaseLeaseMinSeconds +
                Mathf.Max(0f, leaderDistance - PostTraversalChaseSettleDistance) * PostTraversalChaseLeaseDistanceScale,
                PostTraversalChaseLeaseMinSeconds,
                PostTraversalChaseLeaseMaxSeconds);

            // V3.43: PostTraversal is the bounded consumer-handoff domain. The final traversal
            // probe enters it before ordinary Follow writes are permitted; AcquireFollow reuses the
            // same generation until this chase/ACK lease explicitly closes to Follow.

            // A chase born while PostTraversal already owns the bot can retain its
            // original generation. Otherwise BeginPostTraversal binds it once later.
            long chaseBornGeneration = FollowerMovementWriterAuthority.PeekExactGeneration(
                probe.Bot, out FollowerMovementWriterAuthority.WriterDomain chaseBornOwner);
            PostTraversalChaseLeases[profileId] = new PostTraversalChaseLease
            {
                EdgeId = probe.LearnedEdgeId,
                PostTraversalWriterGeneration =
                    chaseBornOwner == FollowerMovementWriterAuthority.WriterDomain.PostTraversal
                        ? chaseBornGeneration : 0,
                ArmedAt = Time.time,
                ExpiresAt = Time.time + adaptiveSeconds,
                SettleDistance = PostTraversalChaseSettleDistance,
                PreserveSprint = probe.PreviousSprinting,
                InitialLeaderDistance = leaderDistance,
                BestLeaderDistance = leaderDistance,
                WithinSettleSince = leaderDistance <= PostTraversalChaseSettleDistance ? Time.time : -1f,
                LastChaseLeaderDistance = leaderDistance,
                LastChaseLeaderPosition = IsLivePlayer(FollowerEnvironment.LocalPlayer) ? FollowerEnvironment.LocalPlayer.Position : default(Vector3),
                LastChaseSampleAt = Time.time,
                NextLocomotionTraceAt = Time.time
            };
            WriteEvent("postTraversalChaseLeaseArmed", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                seconds = adaptiveSeconds,
                initialLeaderDistance = leaderDistance,
                settleDistance = PostTraversalChaseSettleDistance,
                stableHoldSeconds = PostTraversalChaseStableHoldSeconds,
                preserveSprint = probe.PreviousSprinting,
                preserveRun = probe.PreviousRunning
            });
        }

        public static bool IsTeleportTransactionActive(BotOwner bot)
        {
            if (bot == null)
            {
                return false;
            }
            BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(bot.ProfileId);
            return follower?.IsTeleportStabilizing == true;
        }

        internal static void PrepareForNavigationRecovery(BotOwner bot, bool hard, string reason)
        {
            if (bot == null || string.IsNullOrEmpty(bot.ProfileId))
            {
                return;
            }

            string profileId = bot.ProfileId;
            bool hasTraversalMission = LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment traversalMission) &&
                                       traversalMission != null;
            bool hasLiveWalkReservation = ProvisionalWalkThroughReservations.TryGetValue(profileId, out ProvisionalWalkThroughReservation liveWalkReservation) &&
                                          liveWalkReservation != null && Time.time <= liveWalkReservation.ExpiresAt;
            ProbeRuntime activeTraversalProbe = null;
            bool hasActiveTraversalProbe = TryGetActiveProbe(bot, out activeTraversalProbe);

            if (hasLiveWalkReservation && !hasActiveTraversalProbe)
            {
                TraversalEpisodeMetadata finalizedLiveWalkEpisode = TraversalEpisodeStream
                    .LastOrDefault(item => item != null &&
                                           item.EpisodeId == liveWalkReservation.EpisodeId &&
                                           item.EdgeId > 0);
                float liveWalkEntryDistance = GetPlanarDistance(bot.Position, liveWalkReservation.Entry);
                bool finalizedEntryArrival =
                    (finalizedLiveWalkEpisode != null) &&
                    liveWalkEntryDistance <= WalkThroughEntryTolerance;
                if (!finalizedEntryArrival)
                {
                    liveWalkReservation.ExpiresAt = Mathf.Max(
                        liveWalkReservation.ExpiresAt,
                        Time.time + (hard ? LiveWalkThroughReservationSeconds : 4.0f));
                    ProvisionalWalkThroughReservations[profileId] = liveWalkReservation;
                }
                BreadcrumbFollowCommitments.Remove(profileId);
                BreadcrumbBarrierDetourUntil.Remove(profileId);
                WriteEvent(
                    finalizedEntryArrival
                        ? "learningV432NavigationRecoveryLiveWalkAdmissionEscalationRequested"
                        : "navigationRecoveryLiveWalkReservationPreserved",
                    bot,
                    new
                    {
                        episodeId = liveWalkReservation.EpisodeId,
                        edgeId = finalizedLiveWalkEpisode?.EdgeId ?? 0,
                        entry = Vec(liveWalkReservation.Entry),
                        entryDistance = liveWalkEntryDistance,
                        hard,
                        reason = reason ?? string.Empty,
                        reservationExtended = !finalizedEntryArrival,
                        action = finalizedEntryArrival
                            ? "stuckAtFinalizedEntryEscalatesAdmissionNeverRefreshesParkingLease"
                            : "provisionalBuilderBridgeStillNeedsReservation"
                    });
                return;
            }

            // V1.3.23: a pending traversal commitment is already a PIT navigation mission even
            // before the hard crossing probe starts. Soft NavRecovery used to delete this mission
            // in the small approach window, immediately returning Follow to leader-primary and
            // producing the huge NavMesh detours seen in the 2026-08-18 trace. Recovery may refresh
            // the route to the same authored entry, but it may not silently discard the episode.
            if (hasTraversalMission && !hasActiveTraversalProbe)
            {
                SnapshotTraversalCommitmentForRecovery(bot, traversalMission.EdgeId);
                BreadcrumbFollowCommitments.Remove(profileId);
                PostTraversalEntryQuarantines.Remove(profileId);

                traversalMission.ExpiresAt = Mathf.Max(
                    traversalMission.ExpiresAt,
                    Time.time + (hard ? LearnedTraversalExpiredExtensionSeconds : 4.0f));
                traversalMission.LastEntryProgressAt = Time.time;
                traversalMission.LastEntryDistance = Vector3.Distance(bot.Position, traversalMission.Entry);
                LearnedTraversalCommitments[profileId] = traversalMission;

                WriteEvent("navigationRecoveryTraversalMissionPreserved", bot, new
                {
                    edgeId = traversalMission.EdgeId,
                    episodeId = traversalMission.EpisodeId,
                    chainId = traversalMission.ChainId,
                    kind = traversalMission.Kind,
                    hard,
                    reason = reason ?? string.Empty,
                    entryDistance = traversalMission.LastEntryDistance
                });
                return;
            }

            SnapshotTraversalCommitmentForRecovery(bot, 0);
            LearnedTraversalCommitments.Remove(profileId);
            BreadcrumbFollowCommitments.Remove(profileId);
            PostTraversalEntryQuarantines.Remove(profileId);
            BreadcrumbBarrierDetourUntil[profileId] = Time.time + 2.5f;

            if (hard && activeTraversalProbe != null)
            {
                FinishProbeWithoutReanchor(
                    activeTraversalProbe,
                    "navigationRecovery",
                    reason ?? "shared navigation recovery requested");
            }
        }

        private static void SnapshotTraversalCommitmentForRecovery(BotOwner bot, int edgeId)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment traversalCommitment) ||
                traversalCommitment == null ||
                (edgeId > 0 && traversalCommitment.EdgeId != edgeId))
            {
                return;
            }

            if (IsLearningV319TransientSkillTransfer(traversalCommitment))
            {
                NavigationRecoveryTraversalAnchors.Remove(profileId);
                WriteEvent("learningV319TransientRecoverySnapshotSuppressed", bot, new
                {
                    templateEdgeId = traversalCommitment.SkillTemplateEdgeId,
                    kind = traversalCommitment.Kind,
                    source = traversalCommitment.SkillTransferSource ?? string.Empty,
                    nearFrontier = Vec(traversalCommitment.RawEntry),
                    farFrontier = Vec(traversalCommitment.RawExit)
                });
                return;
            }

            NavigationRecoveryTraversalAnchors[profileId] = new LearnedTraversalCommitment
            {
                EdgeId = traversalCommitment.EdgeId,
                EpisodeId = traversalCommitment.EpisodeId,
                ChainId = traversalCommitment.ChainId,
                Entry = traversalCommitment.Entry,
                Exit = traversalCommitment.Exit,
                RawEntry = traversalCommitment.RawEntry,
                RawExit = traversalCommitment.RawExit,
                HasSettledEntry = traversalCommitment.HasSettledEntry,
                SettledEntry = traversalCommitment.SettledEntry,
                HasSettledExit = traversalCommitment.HasSettledExit,
                SettledExit = traversalCommitment.SettledExit,
                Kind = traversalCommitment.Kind,
                ExpiresAt = Time.time + 6.0f
            };
        }

        private static string MakeLearningV319ZeroShotTemplateRetryKey(string profileId, int templateEdgeId)
        {
            return (profileId ?? string.Empty) + ":" + templateEdgeId.ToString(CultureInfo.InvariantCulture);
        }

        private static bool IsLearningV319TransientSkillTransfer(LearnedTraversalCommitment commitment)
        {
            return (commitment != null) && commitment.SkillTransferTransient;
        }

        private static bool TryGetLearningV319TransientSkillTransfer(
            ProbeRuntime probe,
            out LearnedTraversalCommitment commitment)
        {
            commitment = null;
            return probe != null &&
                   TryGetLearnedCommitmentForProbe(probe, out commitment) &&
                   IsLearningV319TransientSkillTransfer(commitment);
        }

        private static bool TryGetLearningV319ZeroShotTemplateGeometry(
            LearnedTraversalEdge edge,
            out float span,
            out float verticalDelta)
        {
            span = 0f;
            verticalDelta = 0f;
            if (edge == null || edge.Disabled || !IsLearningV3NativeProvenEdge(edge) ||
                !IsFinite(edge.RawStart) || !IsFinite(edge.RawEnd))
            {
                return false;
            }

            span = GetPlanarDistance(edge.RawStart, edge.RawEnd);
            verticalDelta = edge.RawEnd.y - edge.RawStart.y;
            if (span < 0.20f)
            {
                return false;
            }

            string kind = edge.Kind ?? string.Empty;
            return string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
        }

        // RC61: IsLearningV361RecoveryEdgeCompatibleWithActiveRouteMission extracted unchanged to FollowerTraversalRecoveryOwnership.cs.

        private static bool HasLearningV374RecoveryPortalCurrentRouteProvenance(
            BotOwner bot,
            LearnedTraversalEdge edge,
            out int episodeId,
            out int episodeEdgeId,
            out int episodeEndBreadcrumbSequence)
        {
            episodeId = 0;
            episodeEdgeId = 0;
            episodeEndBreadcrumbSequence = 0;
            if ((bot == null) || edge == null ||
                string.IsNullOrEmpty(bot.ProfileId))
            {
                return true;
            }

            // V3.61 already constrains recovery to the active mission graph. V3.74 only closes the
            // graph-less tail case: a nearby historical NativeProven portal is evidence, not authority,
            // unless the player actually demonstrated that semantic in the still-unconsumed route epoch.
            if (FollowerRouteMissions.TryGetValue(bot.ProfileId, out FollowerRouteMission mission) &&
                mission != null && mission.CurrentStepIndex >= 0 &&
                mission.CurrentStepIndex < mission.Steps.Count)
            {
                return true;
            }

            int executionFloor = GetFollowerRouteExecutionFloor(bot.ProfileId);
            foreach (TraversalEpisodeMetadata episode in TraversalEpisodeStream
                .Where(item => item != null &&
                    item.StartBreadcrumbSequence > 0 &&
                    item.EndBreadcrumbSequence > executionFloor)
                .OrderByDescending(item => item.EndBreadcrumbSequence)
                .ThenByDescending(item => item.EpisodeId))
            {
                LearnedTraversalEdge episodeEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == episode.EdgeId);
                if (episodeEdge == null)
                {
                    continue;
                }

                bool sameExecutionIdentity = episodeEdge.Id == edge.Id;
                bool shadowOfCandidate = false;
                if (!sameExecutionIdentity &&
                    TryGetLearningV31AuthoritativeProvenParent(
                        episodeEdge, out LearnedTraversalEdge provenParent) &&
                    provenParent != null)
                {
                    shadowOfCandidate = provenParent.Id == edge.Id;
                }
                if (!sameExecutionIdentity && !shadowOfCandidate)
                {
                    continue;
                }

                Vector3 episodeEntry = IsFinite(episode.RawStart) ? episode.RawStart : episode.Entry;
                Vector3 episodeExit = IsFinite(episode.RawEnd) ? episode.RawEnd : episode.Exit;
                if (!IsFinite(episodeEntry) || !IsFinite(episodeExit))
                {
                    continue;
                }

                return true;
            }

            return false;
        }

        private static bool HasLearningV398GraphlessRecoveryActuatorLocalProvenance(
            BotOwner bot,
            string candidateKind,
            Vector3 nearFrontier,
            Vector3 farFrontier)
        {
            if ((bot == null) ||
                string.IsNullOrEmpty(bot.ProfileId) || !IsFinite(nearFrontier) || !IsFinite(farFrontier))
            {
                return true;
            }

            string semanticKind = NormalizeLearningV354Kind(candidateKind);
            LearningV354TraversalCapabilityProfile profile = GetLearningV354ActionProfile(semanticKind);
            if (profile == null || !profile.RequiresActuator)
            {
                return true;
            }

            // An active canonical RouteMission is already governed by V3.61 exact graph semantics.
            // V3.98 is specifically the graph-less Follow/navigation-recovery tail where V3.19
            // historically allowed a remote Native-Proven actuator template to invent a local action.
            if (FollowerRouteMissions.TryGetValue(bot.ProfileId, out FollowerRouteMission mission) &&
                mission != null && mission.CurrentStepIndex >= 0 && mission.CurrentStepIndex < mission.Steps.Count)
            {
                return true;
            }

            int executionFloor = GetFollowerRouteExecutionFloor(bot.ProfileId);
            foreach (TraversalEpisodeMetadata episode in TraversalEpisodeStream
                .Where(item => item != null &&
                    item.StartBreadcrumbSequence > 0 &&
                    item.EndBreadcrumbSequence > executionFloor)
                .OrderByDescending(item => item.EndBreadcrumbSequence)
                .ThenByDescending(item => item.EpisodeId))
            {
                string episodeKind = GetLearningV354SemanticKind(episode.EdgeId, episode.Kind);
                if (!string.Equals(episodeKind, semanticKind, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                // Prefer V3.72 current-execution geometry because a learned edge identifies the
                // skill/template while these runtime-only points identify WHERE the current player
                // actually crossed during this raid. Fall back only to the episode's own raw/local
                // anchors; never to a relocated historical template.
                Vector3 episodeEntry = episode.LearningV372HasCurrentExecutionGeometry &&
                                       IsFinite(episode.LearningV372CurrentExecutionStart)
                    ? episode.LearningV372CurrentExecutionStart
                    : (IsFinite(episode.RawStart) ? episode.RawStart : episode.Entry);
                Vector3 episodeExit = episode.LearningV372HasCurrentExecutionGeometry &&
                                      IsFinite(episode.LearningV372CurrentExecutionEnd)
                    ? episode.LearningV372CurrentExecutionEnd
                    : (IsFinite(episode.RawEnd) ? episode.RawEnd : episode.Exit);
                if (!IsFinite(episodeEntry) || !IsFinite(episodeExit))
                {
                    continue;
                }

                bool forwardLocal =
                    GetPlanarDistance(nearFrontier, episodeEntry) <= LearningV2RevisionEndpointRadius &&
                    GetPlanarDistance(farFrontier, episodeExit) <= LearningV2RevisionEndpointRadius;
                bool reverseLocal =
                    GetPlanarDistance(nearFrontier, episodeExit) <= LearningV2RevisionEndpointRadius &&
                    GetPlanarDistance(farFrontier, episodeEntry) <= LearningV2RevisionEndpointRadius;
                if (!forwardLocal && !reverseLocal)
                {
                    continue;
                }

                return true;
            }

            return false;
        }

        private static bool TryCommitLearningV340LocalNativeProvenTraversalAtFrontier(
            BotOwner bot,
            Vector3 nearFrontier,
            Vector3 destination,
            Vector3 transferDirection,
            string recoverySource,
            out string source)
        {
            source = string.Empty;
            if ((bot == null) ||
                string.IsNullOrEmpty(bot.ProfileId) || !IsFinite(nearFrontier) ||
                !IsFinite(destination) || transferDirection.sqrMagnitude < 0.5f)
            {
                return false;
            }

            LearnedTraversalEdge bestEdge = null;
            bool bestForward = true;
            bool bestV475DestinationAxis = false;
            float bestV475PathTangentDot = 0f;
            float bestV475DestinationDot = 0f;
            float bestScore = float.MaxValue;
            float nearDestinationDistance = GetPlanarDistance(nearFrontier, destination);
            // A PathPartial terminal segment may run ALONG a ledge instead of pointing
            // ACROSS its physical crossing. Keep the original tangent as the primary
            // heading authority; a destination-facing alternative is admissible only
            // for an EXACT LOCAL, native-proven edge with a real downstream NavMesh path.
            Vector3 learningV475DestinationAxis = GetFlatDirection(destination - nearFrontier);
            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (edge == null || edge.Disabled || !IsLearningV3NativeProvenEdge(edge) ||
                    !IsTraversalEdgeTopologicallySelectableForFollower(bot, edge, out _))
                {
                    continue;
                }
                bool learningV433CandidateEpisodeAlreadyConsumed = IsTraversalEpisodeAlreadyConsumed(bot, edge);
                bool learningV433CandidateRecentRelatchBlocked =
                    IsRecentTraversalRelatchBlocked(bot, edge, out _);

                if (!IsLearningV361RecoveryEdgeCompatibleWithActiveRouteMission(
                    bot, edge, out int learningV361MissionId, out int learningV361StepIndex,
                    out int learningV361RouteEdgeId, out string learningV361RouteKind))
                {
                    if (ShouldEmitDiagnostic(
                        "learningV361RecoveryPortalRejectedOutsideRouteGraph:" +
                            edge.Id.ToString(CultureInfo.InvariantCulture), bot, 0.45f))
                    {
                        WriteEvent("learningV361RecoveryPortalRejectedOutsideRouteGraph", bot, new
                        {
                            candidateEdgeId = edge.Id,
                            candidateKind = edge.Kind,
                            missionId = learningV361MissionId,
                            stepIndex = learningV361StepIndex,
                            routeEdgeId = learningV361RouteEdgeId,
                            routeKind = learningV361RouteKind,
                            recoverySource = recoverySource ?? "navigationRecovery",
                            action = "activeRouteMissionGraphOutranksNearbyUnrelatedNativeProvenPortal"
                        });
                    }
                    continue;
                }

                bool learningV374HasCurrentRouteProvenance =
                    HasLearningV374RecoveryPortalCurrentRouteProvenance(
                        bot, edge,
                        out int learningV374RecoveryEpisodeId,
                        out int learningV374RecoveryEpisodeEdgeId,
                        out int learningV374RecoveryEpisodeEnd);

                for (int orientation = 0; orientation < 2; orientation++)
                {
                    bool forward = orientation == 0;
                    Vector3 entry = forward ? edge.A : edge.B;
                    Vector3 exit = forward ? edge.B : edge.A;
                    Vector3 rawEntry = forward ? edge.RawStart : edge.RawEnd;
                    Vector3 rawExit = forward ? edge.RawEnd : edge.RawStart;
                    if (!IsFinite(entry) || !IsFinite(exit) || !IsFinite(rawEntry) || !IsFinite(rawExit) ||
                        !IsTraversalOrientationAllowed(edge, entry, exit))
                    {
                        continue;
                    }

                    float entryDistance = GetPlanarDistance(nearFrontier, entry);
                    if (entryDistance > LearningV2RevisionEndpointRadius)
                    {
                        continue;
                    }

                    Vector3 edgeDirection = GetFlatDirection(rawExit - rawEntry);
                    float learningV475PathTangentDot = edgeDirection.sqrMagnitude >= 0.5f
                        ? Vector3.Dot(edgeDirection, transferDirection) : -1f;
                    bool learningV475PathTangentAligned =
                        learningV475PathTangentDot >= LearningV2RevisionMinDirectionDot;
                    float learningV475DestinationDot = edgeDirection.sqrMagnitude >= 0.5f &&
                        learningV475DestinationAxis.sqrMagnitude >= 0.5f
                        ? Vector3.Dot(edgeDirection, learningV475DestinationAxis) : -1f;
                    bool learningV475DestinationAxisAdmitted = false;
                    if ((!learningV475PathTangentAligned) &&
                        edgeDirection.sqrMagnitude >= 0.5f &&
                        learningV475DestinationDot >= LearningV2RevisionMinDirectionDot &&
                        GetPlanarDistance(bot.Position, nearFrontier) <= LearningV2RevisionEndpointRadius &&
                        Mathf.Abs(rawEntry.y - nearFrontier.y) <= LearningV2RevisionVerticalTolerance)
                    {
                        // The native-proven edge, entry location and height already matched.
                        // Demand a COMPLETE downstream route; otherwise the destination
                        // direction alone could authorize a jump into another isolated island.
                        StrictPathResult v475Downstream = CalculateStrictPath(exit, destination);
                        learningV475DestinationAxisAdmitted = v475Downstream != null &&
                            v475Downstream.CalculateReturned && v475Downstream.StrictComplete;
                    }
                    if (edgeDirection.sqrMagnitude < 0.5f ||
                        (!learningV475PathTangentAligned && !learningV475DestinationAxisAdmitted))
                    {
                        continue;
                    }

                    float exitDestinationDistance = GetPlanarDistance(exit, destination);
                    float destinationProgress = nearDestinationDistance - exitDestinationDistance;
                    if (destinationProgress < LearningV319ZeroShotMinDestinationProgress)
                    {
                        continue;
                    }

                    bool learningV433ExactLocalGraphlessActuatorAuthority = false;
                    if (!learningV374HasCurrentRouteProvenance)
                    {
                        bool activeMission = FollowerRouteMissions.TryGetValue(
                                bot.ProfileId, out FollowerRouteMission learningV433Mission) &&
                            learningV433Mission != null &&
                            learningV433Mission.CurrentStepIndex >= 0 &&
                            learningV433Mission.CurrentStepIndex < learningV433Mission.Steps.Count;
                        LearningV354TraversalCapabilityProfile learningV433Profile =
                            GetLearningV354ActionProfile(edge.Kind);
                        learningV433ExactLocalGraphlessActuatorAuthority =
                            (!activeMission) &&
                            learningV433Profile != null && learningV433Profile.RequiresActuator &&
                            entryDistance <= LearningV2RevisionEndpointRadius;
                        if (!learningV433ExactLocalGraphlessActuatorAuthority)
                        {
                            if (ShouldEmitDiagnostic(
                                "learningV374RecoveryPortalRejectedWithoutCurrentRouteProvenance:" +
                                    edge.Id.ToString(CultureInfo.InvariantCulture), bot, 0.45f))
                            {
                                WriteEvent("learningV374RecoveryPortalRejectedWithoutCurrentRouteProvenance", bot, new
                                {
                                    candidateEdgeId = edge.Id,
                                    candidateKind = edge.Kind,
                                    recoverySource = recoverySource ?? "navigationRecovery",
                                    executionFloor = GetFollowerRouteExecutionFloor(bot.ProfileId ?? string.Empty),
                                    action = "historicalNativeProvenPortalRemainsEvidenceOnlyWithoutUnconsumedCurrentPlayerRouteEpisode"
                                });
                            }
                            continue;
                        }

                        WriteEvent("learningV433ExactLocalNativeProvenActuatorAuthority", bot, new
                        {
                            candidateEdgeId = edge.Id,
                            candidateKind = edge.Kind,
                            recoverySource = recoverySource ?? "navigationRecovery",
                            nearFrontier = Vec(nearFrontier),
                            candidateEntry = Vec(entry),
                            candidateExit = Vec(exit),
                            entryDistance,
                            destinationProgress,
                            currentRouteProvenance = false,
                            persistentLearningChanged = false,
                            action = "exactPhysicalFrontierAndDestinationProgressAuthorizeExistingNativeProvenActuatorWithoutRemoteTemplateGeneralization"
                        });
                    }

                    if ((learningV433CandidateEpisodeAlreadyConsumed || learningV433CandidateRecentRelatchBlocked) &&
                        !learningV433ExactLocalGraphlessActuatorAuthority)
                    {
                        continue;
                    }

                    float score = entryDistance + exitDestinationDistance * 0.01f -
                                  Mathf.Min(5, Math.Max(0, edge.NativeSuccessCount)) * 0.05f;
                    if (bestEdge == null || score < bestScore)
                    {
                        bestEdge = edge;
                        bestForward = forward;
                        bestV475DestinationAxis = learningV475DestinationAxisAdmitted;
                        bestV475PathTangentDot = learningV475PathTangentDot;
                        bestV475DestinationDot = learningV475DestinationDot;
                        bestScore = score;
                    }
                }
            }

            if (bestEdge == null)
            {
                return false;
            }

            Vector3 bestEntry = bestForward ? bestEdge.A : bestEdge.B;
            Vector3 bestExit = bestForward ? bestEdge.B : bestEdge.A;
            Vector3 bestRawEntry = bestForward ? bestEdge.RawStart : bestEdge.RawEnd;
            Vector3 bestRawExit = bestForward ? bestEdge.RawEnd : bestEdge.RawStart;
            LearnedTraversalCommitment commitment = CreateLearnedTraversalCommitment(
                bestEdge, bestEntry, bestExit, bestRawEntry, bestRawExit);
            if (commitment == null)
            {
                return false;
            }

            LearnedTraversalCommitments[bot.ProfileId] = commitment;
            source = "learningV340LocalNativeProvenPreemptsZeroShot";
            if (bestV475DestinationAxis)
            {
                WriteEvent("learningV475ExactLocalNativeRecoveryDestinationAxisAdmitted", bot, new
                {
                    edgeId = bestEdge.Id,
                    kind = bestEdge.Kind,
                    nativeSuccesses = bestEdge.NativeSuccessCount,
                    nearFrontier = Vec(nearFrontier),
                    entry = Vec(bestEntry),
                    exit = Vec(bestExit),
                    destination = Vec(destination),
                    pathTangentDot = bestV475PathTangentDot,
                    destinationDot = bestV475DestinationDot,
                    downstreamStrictCompleteRequired = true,
                    currentRaidPhysicalProofMinted = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "localNativeProvenCrossingOutranksMisleadingPathPartialEdgeTangent"
                });
            }
            WriteEvent("learningV340LocalNativeProvenFrontierCommitted", bot, new
            {
                edgeId = bestEdge.Id,
                experienceKey = bestEdge.ExperienceKey,
                kind = bestEdge.Kind,
                nativeSuccesses = bestEdge.NativeSuccessCount,
                nearFrontier = Vec(nearFrontier),
                entry = Vec(bestEntry),
                exit = Vec(bestExit),
                destination = Vec(destination),
                recoverySource = recoverySource ?? "navigationRecovery",
                action = "exactLocalNativeProvenGeometryOutranksRemoteZeroShotTemplate"
            });
            return true;
        }

        private static bool HasLearningV339GroundedGapSemanticProof(
            Vector3 nearFrontier,
            Vector3 farFrontier,
            out int sampleCount,
            out float verticalSpread)
        {
            sampleCount = 0;
            verticalSpread = 0f;
            if ((!IsFinite(nearFrontier)) || !IsFinite(farFrontier))
            {
                return false;
            }

            PlayerBreadcrumbNode nearNode = BreadcrumbRoute
                .Where(node => node != null && IsOperationalBreadcrumbNode(node) &&
                    GetPlanarDistance(node.Position, nearFrontier) <= KnownWalkThroughPortalBreadcrumbEntryRadius)
                .OrderByDescending(node => node.Sequence)
                .FirstOrDefault();
            PlayerBreadcrumbNode farNode = BreadcrumbRoute
                .Where(node => node != null && IsOperationalBreadcrumbNode(node) &&
                    GetPlanarDistance(node.Position, farFrontier) <= KnownWalkThroughPortalBreadcrumbExitRadius)
                .OrderByDescending(node => node.Sequence)
                .FirstOrDefault();
            if (nearNode == null || farNode == null || farNode.Sequence <= nearNode.Sequence)
            {
                return false;
            }

            List<PlayerBreadcrumbNode> segment = BreadcrumbRoute
                .Where(node => node != null && IsOperationalBreadcrumbNode(node) &&
                    node.Sequence >= nearNode.Sequence && node.Sequence <= farNode.Sequence)
                .OrderBy(node => node.Sequence)
                .ToList();
            if (segment.Count == 0 || segment.Any(node => !node.Grounded ||
                    IsLearningV325ExplicitTraversalSemanticState(node.State)))
            {
                return false;
            }

            float minY = segment.Min(node => node.Position.y);
            float maxY = segment.Max(node => node.Position.y);
            verticalSpread = maxY - minY;
            sampleCount = segment.Count;
            return verticalSpread <= LearningV2RevisionVerticalTolerance;
        }

        private static bool IsLearningV431PhysicalActuatorSkillKind(string kind)
        {
            return string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsLearningV431CapabilityFamilyMatch(string kind, string requiredCapabilityFamily)
        {
            if (string.IsNullOrWhiteSpace(requiredCapabilityFamily))
            {
                return true;
            }
            if (string.Equals(requiredCapabilityFamily, "Barrier", StringComparison.OrdinalIgnoreCase))
            {
                // Climb and Vault are alternative actuators for the same generic solid-barrier
                // crossing problem. Selection still has to pass V319's topology, geometry, skill
                // evidence, span/vertical and downstream-progress contracts.
                return string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase);
            }
            if (string.Equals(requiredCapabilityFamily, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                return string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase);
            }
            return string.Equals(kind, requiredCapabilityFamily, StringComparison.OrdinalIgnoreCase);
        }

        private static string GetLearningV431CapabilityFamily(string kind)
        {
            if (string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase))
            {
                return "Barrier";
            }
            if (string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                return "DropDown";
            }
            return string.Empty;
        }

        internal static bool TryBeginLearningV319ZeroShotTraversalRecovery(
            BotOwner bot,
            Vector3 destination,
            string recoverySource,
            out string source,
            bool allowPendingRouteMission = false,
            bool allowGraphlessActuatorSkillTransfer = false,
            string requiredCapabilityFamily = null,
            int excludedTemplateEdgeId = 0,
            bool allowExistingLocalNativeProven = true)
        {
            source = string.Empty;
            if ((!raidActive) || !IsLiveBot(bot) ||
                !IsFinite(destination) || string.IsNullOrEmpty(bot.ProfileId) ||
                HasActiveTraversalProbe(bot) || (!allowPendingRouteMission && HasPendingTraversalMission(bot)))
            {
                return false;
            }

            StrictPathResult direct = CalculateStrictPath(bot.Position, destination);
            if (direct == null || direct.StrictComplete || !direct.CalculateReturned ||
                direct.Status != NavMeshPathStatus.PathPartial || direct.Corners == null || direct.Corners.Length == 0)
            {
                return false;
            }

            Vector3 rawNearFrontier = direct.Corners[direct.Corners.Length - 1];
            if (!FollowerSafeTeleport.TryValidateLocalTraversalEntryAnchor(bot, rawNearFrontier, out Vector3 nearFrontier))
            {
                return false;
            }

            float nearEntryDistance = GetPlanarDistance(bot.Position, nearFrontier);
            if (nearEntryDistance > LearningV319ZeroShotNearFrontierMaxDistance)
            {
                WriteEvent("learningV319ZeroShotFrontierDeferred", bot, new
                {
                    source = recoverySource ?? "navigationRecovery",
                    entryDistance = nearEntryDistance,
                    maximum = LearningV319ZeroShotNearFrontierMaxDistance,
                    nearFrontier = Vec(nearFrontier),
                    destination = Vec(destination),
                    direct = direct.ToPayload()
                });
                return false;
            }

            // The last segment of the follower's own PathPartial is the near-side approach
            // semantic and is therefore the least location-bound orientation signal available.
            // Use it before the remote leader vector; pointing directly at the leader can rotate a
            // valid gap crossing toward an unrelated corner on the far island.
            Vector3 transferDirection = direct.Corners.Length >= 2
                ? GetFlatDirection(direct.Corners[direct.Corners.Length - 1] - direct.Corners[direct.Corners.Length - 2])
                : Vector3.zero;
            if (transferDirection.sqrMagnitude < 0.5f)
            {
                transferDirection = GetFlatDirection(destination - nearFrontier);
            }
            if (transferDirection.sqrMagnitude < 0.5f)
            {
                return false;
            }

            if (allowExistingLocalNativeProven &&
                TryCommitLearningV340LocalNativeProvenTraversalAtFrontier(
                    bot, nearFrontier, destination, transferDirection, recoverySource, out source))
            {
                return true;
            }

            float nearDestinationDistance = Vector3.Distance(nearFrontier, destination);
            LearningV319ZeroShotTransferCandidate best = null;
            string profileId = bot.ProfileId;
            foreach (LearnedTraversalEdge template in LearnedTraversalEdges)
            {
                if (template == null || (excludedTemplateEdgeId > 0 && template.Id == excludedTemplateEdgeId))
                {
                    continue;
                }
                if (!IsLearningV431CapabilityFamilyMatch(template.Kind, requiredCapabilityFamily))
                {
                    continue;
                }
                if (!TryGetLearningV319ZeroShotTemplateGeometry(template, out float templateSpan, out float templateVerticalDelta))
                {
                    continue;
                }
                if (!IsLearningV322ZeroShotTemplateEligible(template, out string learningV322GeneralizationReason))
                {
                    WriteEvent("learningV322ZeroShotTemplateSuppressedByEvidence", bot, new
                    {
                        templateEdgeId = template.Id,
                        experienceKey = template.ExperienceKey,
                        kind = template.Kind,
                        reason = learningV322GeneralizationReason
                    });
                    continue;
                }

                // Zero-shot owns only unseen geometry. If this frontier already matches the same
                // authored edge location, ordinary learned-edge selection must retain authority.
                // Do not manufacture a transient alias for an existing location.
                bool directionalTemplate =
                    FollowerCapabilityHelperRules.TryBeginLearningV319ZeroShotTraversalRecovery_directionalTemplate_F293F992_1(template.Kind,template.Kind,template.Kind);
                Vector3 proposedTemplateEnd = nearFrontier + transferDirection * templateSpan +
                                              Vector3.up * templateVerticalDelta;
                if (IsLearningV2SameLocalSkill(template, nearFrontier, proposedTemplateEnd, directionalTemplate))
                {
                    continue;
                }

                string retryKey = MakeLearningV319ZeroShotTemplateRetryKey(profileId, template.Id);
                if (LearningV319ZeroShotTemplateRetryAfter.TryGetValue(retryKey, out float retryAt) && Time.time < retryAt)
                {
                    continue;
                }

                Vector3 requestedFar = nearFrontier + transferDirection * templateSpan + Vector3.up * templateVerticalDelta;
                if (!NavMesh.SamplePosition(
                        requestedFar,
                        out NavMeshHit farHit,
                        LearningV319ZeroShotFarSampleRadius,
                        NavMesh.AllAreas))
                {
                    continue;
                }

                if (!FollowerSafeTeleport.TryValidateLocalTraversalEntryAnchor(bot, farHit.position, out Vector3 farFrontier))
                {
                    continue;
                }

                bool learningV431EquivalentBarrierTransfer =
                    (allowGraphlessActuatorSkillTransfer) &&
                    IsLearningV431CapabilityFamilyMatch(template.Kind, requiredCapabilityFamily) &&
                    IsLearningV431PhysicalActuatorSkillKind(template.Kind);
                if (!learningV431EquivalentBarrierTransfer &&
                    !HasLearningV398GraphlessRecoveryActuatorLocalProvenance(
                        bot, template.Kind, nearFrontier, farFrontier))
                {
                    if (ShouldEmitDiagnostic(
                        "learningV398RecoveryActuatorTemplateRejectedWithoutLocalRouteProvenance:" +
                            template.Id.ToString(CultureInfo.InvariantCulture), bot, 0.45f))
                    {
                        WriteEvent("learningV398RecoveryActuatorTemplateRejectedWithoutLocalRouteProvenance", bot, new
                        {
                            templateEdgeId = template.Id,
                            templateKind = template.Kind,
                            recoverySource = recoverySource ?? "navigationRecovery",
                            nearFrontier = Vec(nearFrontier),
                            farFrontier = Vec(farFrontier),
                            executionFloor = GetFollowerRouteExecutionFloor(profileId),
                            action = "historicalActuatorTemplateRemainsSkillEvidenceUntilCurrentRaidLocalSemanticEpisodeProvesThisGap"
                        });
                    }
                    continue;
                }
                if (learningV431EquivalentBarrierTransfer)
                {
                    WriteEvent("learningV431EquivalentBarrierTemplateGeneralizationAdmitted", bot, new
                    {
                        templateEdgeId = template.Id,
                        templateKind = template.Kind,
                        requiredCapabilityFamily = requiredCapabilityFamily ?? string.Empty,
                        recoverySource = recoverySource ?? "navigationRecovery",
                        nearFrontier = Vec(nearFrontier),
                        farFrontier = Vec(farFrontier),
                        currentRaidLocalDemonstrationRequired = false,
                        templateRemainsReadOnlyUntilNativePhysicalSuccess = true,
                        action = "reuseNativeProvenPhysicalSkillAcrossUnseenEquivalentLocalBarrierGeometry"
                    });
                }

                float actualSpan = GetPlanarDistance(nearFrontier, farFrontier);
                float actualVerticalDelta = farFrontier.y - nearFrontier.y;
                float spanRatio = actualSpan / Mathf.Max(0.20f, templateSpan);
                float verticalError = Mathf.Abs(actualVerticalDelta - templateVerticalDelta);
                if (spanRatio < LearningV2RevisionMinSpanRatio ||
                    spanRatio > LearningV2RevisionMaxSpanRatio ||
                    verticalError > LearningV2RevisionVerticalTolerance)
                {
                    continue;
                }

                if (!string.Equals(template.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                    HasLearningV339GroundedGapSemanticProof(
                        nearFrontier, farFrontier, out int learningV339GroundedSamples,
                        out float learningV339GroundedVerticalSpread))
                {
                    WriteEvent("learningV339GroundedGapTraversalTemplateRejected", bot, new
                    {
                        templateEdgeId = template.Id,
                        templateKind = template.Kind,
                        nearFrontier = Vec(nearFrontier),
                        farFrontier = Vec(farFrontier),
                        breadcrumbSamples = learningV339GroundedSamples,
                        verticalSpread = learningV339GroundedVerticalSpread,
                        verticalTolerance = LearningV2RevisionVerticalTolerance,
                        action = "ordinaryGroundedLocomotionCannotBecomeZeroShotPhysicalTraversal"
                    });
                    continue;
                }

                // The generated instance must bridge a real topology break. If the follower can
                // already reach the sampled far side through ordinary NavMesh, this is not a
                // traversal problem and the Native-Proven skill must not claim it.
                StrictPathResult sameSide = CalculateStrictPath(bot.Position, farFrontier);
                if (sameSide.StrictComplete)
                {
                    continue;
                }

                float farDestinationDistance = Vector3.Distance(farFrontier, destination);
                if (farDestinationDistance + LearningV319ZeroShotMinDestinationProgress >= nearDestinationDistance)
                {
                    continue;
                }

                StrictPathResult downstream = CalculateStrictPath(farFrontier, destination);
                if (downstream == null || !downstream.CalculateReturned || downstream.Corners == null || downstream.Corners.Length == 0)
                {
                    continue;
                }

                Vector3 downstreamTerminal = downstream.Corners[downstream.Corners.Length - 1];
                float downstreamTerminalDistance = downstream.StrictComplete
                    ? 0f
                    : Vector3.Distance(downstreamTerminal, destination);
                float destinationProgress = nearDestinationDistance - downstreamTerminalDistance;
                if (destinationProgress < LearningV319ZeroShotMinDestinationProgress)
                {
                    continue;
                }

                if (string.Equals(template.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    // Zero-shot WT has no player-authored corridor authority. It may transfer only
                    // when the straight physical corridor validates and ordinary local NavMesh has
                    // no cheap bypass. This preserves V3.12/V3.15 proven seam behavior without
                    // teaching rough-ground micro-WT as a generic skill.
                    if (TryFindCheapLocalWalkThroughBypass(
                            nearFrontier,
                            farFrontier,
                            out _, out _, out _, out _) ||
                        !TryValidateWalkThroughCorridor(
                            bot.GetPlayer,
                            nearFrontier,
                            farFrontier,
                            out _,
                            out _))
                    {
                        continue;
                    }
                }

                float spanError = Mathf.Abs(actualSpan - templateSpan) / Mathf.Max(0.20f, templateSpan);
                float score = downstreamTerminalDistance * 0.10f +
                              spanError * 2.0f +
                              verticalError * 2.0f +
                              (downstream.StrictComplete ? 0f : 0.75f) -
                              Mathf.Min(5, Math.Max(0, template.NativeSuccessCount)) * 0.04f;
                if (best == null || score < best.Score)
                {
                    best = new LearningV319ZeroShotTransferCandidate
                    {
                        TemplateEdge = template,
                        NearFrontier = nearFrontier,
                        FarFrontier = farFrontier,
                        TemplateSpan = templateSpan,
                        ActualSpan = actualSpan,
                        TemplateVerticalDelta = templateVerticalDelta,
                        ActualVerticalDelta = actualVerticalDelta,
                        DestinationProgress = destinationProgress,
                        DownstreamTerminalDistance = downstreamTerminalDistance,
                        DownstreamComplete = downstream.StrictComplete,
                        Score = score
                    };
                }
            }

            if (best == null || best.TemplateEdge == null)
            {
                WriteEvent("learningV319ZeroShotTraversalTransferUnavailable", bot, new
                {
                    source = recoverySource ?? "navigationRecovery",
                    nearFrontier = Vec(nearFrontier),
                    destination = Vec(destination),
                    direct = direct.ToPayload(),
                    reason = "noNativeProvenTemplateMatchedDisconnectedFarSide"
                });
                return false;
            }

            int learningV322ParentAttemptId = 0;
            {
                LearningV322PendingParentAttemptByProfile.TryGetValue(profileId, out learningV322ParentAttemptId);
                LearningV322PendingParentAttemptByProfile.Remove(profileId);
            }

            LearnedTraversalCommitment transfer = new LearnedTraversalCommitment
            {
                EdgeId = best.TemplateEdge.Id,
                EpisodeId = 0,
                ChainId = 0,
                Entry = best.NearFrontier,
                Exit = best.FarFrontier,
                RawEntry = best.NearFrontier,
                RawExit = best.FarFrontier,
                HasSettledEntry = true,
                SettledEntry = best.NearFrontier,
                HasSettledExit = true,
                SettledExit = best.FarFrontier,
                Kind = best.TemplateEdge.Kind,
                SkillTransferTransient = true,
                SkillTemplateEdgeId = best.TemplateEdge.Id,
                SkillTransferParentAttemptId = learningV322ParentAttemptId,
                SkillTransferSource = recoverySource ?? "navigationRecovery",
                SkillTransferNearFrontier = best.NearFrontier,
                SkillTransferFarFrontier = best.FarFrontier,
                ExpiresAt = Time.time + LearningV319ZeroShotCommitmentSeconds,
                LastEntryDistance = nearEntryDistance,
                LastEntryProgressAt = Time.time,
                LastLeaderDistanceAtEntryProgress = Vector3.Distance(bot.Position, destination)
            };
            LearnedTraversalCommitments[profileId] = transfer;
            NavigationRecoveryTraversalAnchors.Remove(profileId);
            BreadcrumbFollowCommitments.Remove(profileId);
            FollowRejectLeases.Remove(profileId);

            source = $"learningV319ZeroShot:{best.TemplateEdge.Id}:{best.TemplateEdge.Kind}";
            WriteEvent("learningV319ZeroShotTraversalTransferCommitted", bot, new
            {
                source = recoverySource ?? "navigationRecovery",
                templateEdgeId = best.TemplateEdge.Id,
                templateExperienceKey = best.TemplateEdge.ExperienceKey,
                kind = best.TemplateEdge.Kind,
                templateNativeSuccesses = best.TemplateEdge.NativeSuccessCount,
                nearFrontier = Vec(best.NearFrontier),
                farFrontier = Vec(best.FarFrontier),
                templateSpan = best.TemplateSpan,
                actualSpan = best.ActualSpan,
                templateVerticalDelta = best.TemplateVerticalDelta,
                actualVerticalDelta = best.ActualVerticalDelta,
                destinationProgress = best.DestinationProgress,
                downstreamComplete = best.DownstreamComplete,
                downstreamTerminalDistance = best.DownstreamTerminalDistance,
                persistentEdgeCreated = false,
                playerValidatedInherited = false,
                learningAuthority = "transientUntilPhysicalNativeSuccess"
            });
            return true;
        }

        private static void RecordLearningV319TransientTransferFailure(ProbeRuntime probe, string reason)
        {
            if (probe == null || !TryGetLearningV319TransientSkillTransfer(probe, out LearnedTraversalCommitment commitment))
            {
                return;
            }

            int templateEdgeId = commitment.SkillTemplateEdgeId > 0
                ? commitment.SkillTemplateEdgeId
                : commitment.EdgeId;
            string profileId = probe.Bot?.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) && templateEdgeId > 0)
            {
                LearningV319ZeroShotTemplateRetryAfter[
                    MakeLearningV319ZeroShotTemplateRetryKey(profileId, templateEdgeId)] =
                    Time.time + LearningV319ZeroShotTemplateRetrySeconds;
            }

            TraversalCompletionMode learningV322FailureMode = GetTraversalCompletionMode(probe, reason);
            RecordLearningV322ZeroShotTemplateEvidence(
                probe, commitment, false, learningV322FailureMode, reason ?? "unknown");
            EmitLearningV322TraversalAttemptSummary(
                probe, false, learningV322FailureMode, reason ?? "unknown", templateEdgeId);

            WriteEvent("learningV319ZeroShotTraversalTransferFailed", probe.Bot, new
            {
                templateEdgeId,
                kind = commitment.Kind,
                source = commitment.SkillTransferSource ?? string.Empty,
                nearFrontier = Vec(commitment.RawEntry),
                farFrontier = Vec(commitment.RawExit),
                reason = reason ?? "unknown",
                templateExperienceUnchanged = true,
                persistentGeometryUnchanged = true,
                teleportUsed = probe.TraversalTeleportAttempted || probe.TeleportFallbackUsed
            });
        }

        private static bool TryPromoteLearningV319TransientSkillInstance(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            TraversalCompletionMode completionMode,
            string reason,
            out int promotedEdgeId)
        {
            promotedEdgeId = 0;
            if (probe == null || commitment == null ||
                !IsLearningV319TransientSkillTransfer(commitment) ||
                !IsLearningV3RetainableNativeSuccess(probe, completionMode))
            {
                return false;
            }

            LearnedTraversalEdge template = LearnedTraversalEdges.FirstOrDefault(edge =>
                edge != null && edge.Id == commitment.SkillTemplateEdgeId && IsLearningV3NativeProvenEdge(edge));
            if (template == null)
            {
                WriteEvent("learningV319ZeroShotNativePromotionRejected", probe.Bot, new
                {
                    templateEdgeId = commitment.SkillTemplateEdgeId,
                    kind = commitment.Kind,
                    reason = "nativeProvenTemplateMissing"
                });
                return false;
            }

            if (IsLearningV433ExactLocalActuatorSubstitution(commitment))
            {
                // V433 did not synthesize new geometry: this exact Native-Proven edge physically
                // executed as a substitute for another route action. Credit only the actuator that
                // actually ran; the original RouteMission step is consumed separately as raid-local
                // execution debt by the V431 route bridge and receives no persistent success.
                MarkLearnedTraversalEdgeSuccess(template.Id, completionMode, probe);
                promotedEdgeId = template.Id;
                WriteEvent("learningV433ExactLocalActuatorSubstitutionConfirmed", probe.Bot, new
                {
                    templateEdgeId = template.Id,
                    templateExperienceKey = template.ExperienceKey,
                    kind = template.Kind,
                    source = commitment.SkillTransferSource ?? string.Empty,
                    physicalBody = probe.Player != null ? (object)Vec(probe.Player.Position) : null,
                    persistentGeometryCreated = false,
                    originalRouteSuccessCredited = false,
                    action = "creditOnlyActuallyExecutedExistingNativeProvenActuatorNeverDuplicateGeometry"
                });
                return true;
            }

            Vector3 rawStart = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawEnd = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            if (!IsFinite(rawStart) || !IsFinite(rawEnd) || GetPlanarDistance(rawStart, rawEnd) < 0.20f)
            {
                return false;
            }

            bool directionalKind =
                FollowerCapabilityHelperRules.TryPromoteLearningV319TransientSkillInstance_directionalKind_7E0DD098_1(commitment.Kind,commitment.Kind,commitment.Kind);
            LearnedTraversalEdge existing = LearnedTraversalEdges.FirstOrDefault(edge =>
                edge != null && edge.Id != template.Id && !edge.Disabled &&
                IsLearningV3NativeProvenEdge(edge) &&
                string.Equals(edge.Kind, commitment.Kind, StringComparison.OrdinalIgnoreCase) &&
                IsLearningV2SameLocalSkill(edge, rawStart, rawEnd, directionalKind));
            if (existing != null)
            {
                existing.SuccessfulExecutions++;
                existing.NativeSuccessCount++;
                existing.FailedExecutions = 0;
                existing.CreatedAt = Time.time;
                SaveLearningV31NativeProvenStore();
                promotedEdgeId = existing.Id;
                WriteEvent("learningV319ZeroShotNativeSkillConfirmed", probe.Bot, new
                {
                    templateEdgeId = template.Id,
                    promotedEdgeId = existing.Id,
                    experienceKey = existing.ExperienceKey,
                    kind = existing.Kind,
                    rawStart = Vec(rawStart),
                    rawEnd = Vec(rawEnd),
                    nativeSuccesses = existing.NativeSuccessCount,
                    playerValidated = existing.PlayerValidated,
                    reason = reason ?? "verifiedStableExit"
                });
                return true;
            }

            Vector3 a = rawStart;
            Vector3 b = rawEnd;
            if (!string.Equals(commitment.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                NavMesh.SamplePosition(rawStart, out NavMeshHit aHit, 1.35f, NavMesh.AllAreas))
            {
                a = aHit.position;
            }
            if (NavMesh.SamplePosition(rawEnd, out NavMeshHit bHit, 1.35f, NavMesh.AllAreas))
            {
                b = bHit.position;
            }

            Vector3 settledEnd = IsFinite(probe.ExitAuthorityAnchor)
                ? probe.ExitAuthorityAnchor
                : (probe.Player != null && IsFinite(probe.Player.Position) ? probe.Player.Position : b);
            if (NavMesh.SamplePosition(settledEnd, out NavMeshHit settledHit, 1.35f, NavMesh.AllAreas))
            {
                settledEnd = settledHit.position;
            }

            NativeVaultParameters transferredNative = CreateLearningV319TransferredNativeVaultParameters(template, commitment);
            LearnedTraversalEdge promoted = new LearnedTraversalEdge
            {
                Id = ++learnedTraversalEdgeSequence,
                ExperienceKey = CreateTraversalExperienceKey(),
                SupersedesProvenEdgeId = 0,
                DemonstrationRevision = 1,
                Kind = commitment.Kind,
                A = a,
                B = b,
                RawStart = rawStart,
                RawEnd = rawEnd,
                HasSettledStart = true,
                SettledStart = a,
                HasSettledEnd = IsFinite(settledEnd),
                SettledEnd = settledEnd,
                CreatedAt = Time.time,
                Disabled = false,
                PlayerValidated = false,
                Verified = true,
                SuccessfulExecutions = 1,
                NativeSuccessCount = 1,
                AssistedSuccessCount = 0,
                TeleportFallbackCount = 0,
                FailedExecutions = 0,
                PlayerTraversalSequence = 0,
                ApproachDirection = GetFlatDirection(rawEnd - rawStart),
                ApproachSpeed = template.ApproachSpeed,
                ApproachMode = template.ApproachMode,
                TraversalDuration = template.TraversalDuration,
                WalkThroughCorridorSamples = string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)
                    ? new List<Vector3> { rawStart, rawEnd }
                    : new List<Vector3>(),
                EgressSamples = IsFinite(settledEnd) ? new List<Vector3> { settledEnd } : new List<Vector3>(),
                EgressSemanticSamples = IsFinite(settledEnd)
                    ? new List<TraversalEgressSemanticSample>
                    {
                        new TraversalEgressSemanticSample
                        {
                            Position = settledEnd,
                            Grounded = probe.Player?.MovementContext?.IsGrounded == true,
                            State = probe.Player?.CurrentStateName.ToString(),
                            NavMeshSampled = true,
                            NavMeshPosition = settledEnd
                        }
                    }
                    : new List<TraversalEgressSemanticSample>(),
                MotionSamples = template.MotionSamples != null
                    ? template.MotionSamples.Where(sample => sample != null).Select(CloneTraversalMotionSample).ToList()
                    : new List<TraversalMotionSample>(),
                ObstacleFingerprint = null,
                NativeVaultParameters = transferredNative
            };
            LearnedTraversalEdges.Add(promoted);
            TrimLearnedTraversalEdgesToLimit();
            if (string.Equals(promoted.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                RecordPrivateWalkThroughAvailable(promoted, "learningV319ZeroShotNativeProven");
            }
            SaveLearningV31NativeProvenStore();
            promotedEdgeId = promoted.Id;
            WriteEvent("learningV319ZeroShotNativeSkillPromoted", probe.Bot, new
            {
                templateEdgeId = template.Id,
                templateExperienceKey = template.ExperienceKey,
                promotedEdgeId = promoted.Id,
                experienceKey = promoted.ExperienceKey,
                kind = promoted.Kind,
                rawStart = Vec(rawStart),
                rawEnd = Vec(rawEnd),
                settledEnd = Vec(settledEnd),
                playerValidated = false,
                nativeVerified = true,
                nativeSuccesses = 1,
                reason = reason ?? "verifiedStableExit"
            });
            return true;
        }

        // RC61: TryGetLearningV373RouteLocalPhysicalRecoveryExit extracted unchanged to FollowerTraversalRecoveryOwnership.cs.

        internal static bool TryGetRecoveryAnchor(
            BotOwner bot,
            Vector3 destination,
            out Vector3 anchor,
            out string source)
        {
            anchor = default;
            source = string.Empty;
            if (bot == null || !raidActive || !IsFinite(destination))
            {
                return false;
            }

            PruneBreadcrumbRoute();
            float botDistance = Vector3.Distance(bot.Position, destination);
            string profileId = bot.ProfileId ?? string.Empty;

            // LearningV3.18: while recovering from a traversal, the player's current reachable
            // route owns recovery destination semantics. Prefer the recent player-authored NavMesh
            // anchor nearest to the current destination, but only after the existing recovery
            // validator proves standing safety and a PathComplete candidate->destination route.
            // This prevents a wrong Jump landing (for example on an isolated prop/island) from
            // teleporting back to the authored RawExit and repeating the same dead topology.
            bool learningV356TerminalRecoveryOwnsAnchorLease =
                (IsLearningV350TerminalPhysicalRecoveryEligible(bot));
            bool learningV373UnresolvedPhysicalBarrierRecovery =
                (!string.IsNullOrEmpty(profileId)) &&
                NavigationRecoveryTraversalAnchors.TryGetValue(
                    profileId, out LearnedTraversalCommitment learningV373RecoveryTraversal) &&
                learningV373RecoveryTraversal != null &&
                IsLearningV373PhysicalCompletionBarrierKind(learningV373RecoveryTraversal.Kind) &&
                (Time.time <= learningV373RecoveryTraversal.ExpiresAt || learningV356TerminalRecoveryOwnsAnchorLease);
            if ((!learningV373UnresolvedPhysicalBarrierRecovery) &&
                !string.IsNullOrEmpty(profileId) &&
                NavigationRecoveryTraversalAnchors.TryGetValue(profileId, out LearnedTraversalCommitment playerNearestRecoveryTraversal) &&
                playerNearestRecoveryTraversal != null &&
                (Time.time <= playerNearestRecoveryTraversal.ExpiresAt || learningV356TerminalRecoveryOwnsAnchorLease))
            {
                bool foundPlayerNearest = false;
                Vector3 playerNearestAnchor = default;
                long playerNearestSequence = 0;
                float playerNearestDistance = float.PositiveInfinity;
                for (int i = BreadcrumbRoute.Count - 1; i >= 0; i--)
                {
                    PlayerBreadcrumbNode node = BreadcrumbRoute[i];
                    if (node == null || Time.time - node.CreatedAt > 35f || IsTraversalStateName(node.State))
                    {
                        continue;
                    }

                    if (!FollowerSafeTeleport.TryValidateRecoveryAnchor(
                            bot, node.Position, destination, out Vector3 candidate))
                    {
                        continue;
                    }

                    float destinationDistance = Vector3.Distance(candidate, destination);
                    if (!foundPlayerNearest || destinationDistance < playerNearestDistance)
                    {
                        foundPlayerNearest = true;
                        playerNearestAnchor = candidate;
                        playerNearestSequence = node.Sequence;
                        playerNearestDistance = destinationDistance;
                    }
                }

                if (foundPlayerNearest)
                {
                    anchor = playerNearestAnchor;
                    source = $"learningV318PlayerNearestBreadcrumb:{playerNearestSequence}:edge{playerNearestRecoveryTraversal.EdgeId}";
                    NavigationRecoveryTraversalAnchors.Remove(profileId);
                    WriteEvent("learningV318NavigationRecoveryPlayerNearestAnchorSelected", bot, new
                    {
                        edgeId = playerNearestRecoveryTraversal.EdgeId,
                        kind = playerNearestRecoveryTraversal.Kind,
                        breadcrumbSequence = playerNearestSequence,
                        anchor = Vec(playerNearestAnchor),
                        destination = Vec(destination),
                        destinationDistance = playerNearestDistance,
                        reason = "safeAndPathCompleteNearestPlayerRouteAnchor"
                    });
                    WriteEvent("learningV318PlayerNearestNavMeshRecoveryCommitted", bot, new
                    {
                        edgeId = playerNearestRecoveryTraversal.EdgeId,
                        kind = playerNearestRecoveryTraversal.Kind,
                        breadcrumbSequence = playerNearestSequence,
                        recoveryCountsAsNativeTraversalSuccess = false,
                        classification = "TeleportRecoveredNotNative"
                    });
                    return true;
                }

                WriteEvent("learningV318PlayerNearestNavMeshRecoveryUnavailable", bot, new
                {
                    edgeId = playerNearestRecoveryTraversal.EdgeId,
                    kind = playerNearestRecoveryTraversal.Kind,
                    destination = Vec(destination),
                    fallback = "legacyTraversalExitThenGenericRecovery"
                });
            }

            // V1.3.14 legacy fallback: exact traversal exit remains available only after V3.18
            // cannot prove a safer player-nearest PathComplete recovery anchor.
            if (!string.IsNullOrEmpty(profileId) &&
                NavigationRecoveryTraversalAnchors.TryGetValue(profileId, out LearnedTraversalCommitment recoveryTraversal))
            {
                bool expiredWithoutTerminalLease =
                    recoveryTraversal == null ||
                    (Time.time > recoveryTraversal.ExpiresAt && !learningV356TerminalRecoveryOwnsAnchorLease);
                if (expiredWithoutTerminalLease)
                {
                    NavigationRecoveryTraversalAnchors.Remove(profileId);
                }
                else
                {
                    bool learningV373RouteLocalExit =
                        TryGetLearningV373RouteLocalPhysicalRecoveryExit(
                            recoveryTraversal, out Vector3 requestedExit, out string recoveryGeometrySource);
                    if (!learningV373RouteLocalExit)
                    {
                        requestedExit = recoveryTraversal.HasSettledExit && IsFinite(recoveryTraversal.SettledExit)
                            ? recoveryTraversal.SettledExit
                            : (IsFinite(recoveryTraversal.RawExit) ? recoveryTraversal.RawExit : recoveryTraversal.Exit);
                        recoveryGeometrySource = "legacyTraversalExit";
                    }
                    if (FollowerSafeTeleport.TryValidateTraversalExitAnchor(bot, requestedExit, out Vector3 traversalExit))
                    {
                        anchor = traversalExit;
                        source = learningV373RouteLocalExit
                            ? $"learningV373RouteLocalPhysicalBarrierExit:{recoveryTraversal.EdgeId}:{recoveryTraversal.Kind}"
                            : $"activeTraversalExit:{recoveryTraversal.EdgeId}:{recoveryTraversal.Kind}";
                        NavigationRecoveryTraversalAnchors.Remove(profileId);
                        if (learningV373RouteLocalExit)
                        {
                            WriteEvent("learningV373RouteLocalPhysicalRecoveryAnchorSelected", bot, new
                            {
                                edgeId = recoveryTraversal.EdgeId,
                                episodeId = recoveryTraversal.EpisodeId,
                                kind = recoveryTraversal.Kind,
                                requestedExit = Vec(requestedExit),
                                anchor = Vec(traversalExit),
                                geometrySource = recoveryGeometrySource,
                                recoveryCountsAsTraversalSuccess = false,
                                persistentLearningChanged = false,
                                action = "unresolvedPhysicalBarrierRecoveryCannotJumpToGlobalPlayerBreadcrumb"
                            });
                        }
                        return true;
                    }

                    if (learningV373UnresolvedPhysicalBarrierRecovery)
                    {
                        WriteEvent("learningV373RouteLocalPhysicalRecoveryAnchorUnavailable", bot, new
                        {
                            edgeId = recoveryTraversal.EdgeId,
                            episodeId = recoveryTraversal.EpisodeId,
                            kind = recoveryTraversal.Kind,
                            requestedExit = Vec(requestedExit),
                            geometrySource = recoveryGeometrySource,
                            destination = Vec(destination),
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "retainPhysicalDebtDoNotSubstituteGlobalBreadcrumbTeleport"
                        });
                        return false;
                    }
                }
            }

            // CompileFix54: generic Follow recovery may use a traversal exit only when the
            // player actually demonstrated that oriented episode in the current raid recently.
            // CompileFix53 and earlier scanned every persistent edge and inferred orientation from
            // whichever endpoint happened to be closest to the bot. That could select an unrelated
            // historical Vault/WalkThrough or even reverse a directional DropDown. Persistent
            // geometry remains available to RouteMission/selection; recovery Teleport requires
            // fresh route provenance. Active traversal snapshots above remain the highest authority.
            PruneLearnedTraversalEdges();
            LearnedTraversalEdge bestTraversal = null;
            Vector3 bestExit = default;
            float bestExitDistance = float.PositiveInfinity;
            for (int i = LearnedTraversalEdges.Count - 1; i >= 0; i--)
            {
                LearnedTraversalEdge edge = LearnedTraversalEdges[i];
                if (edge == null || edge.Disabled || (!edge.PlayerValidated && !edge.Verified) ||
                    !TraversalEpisodesByEdge.TryGetValue(edge.Id, out TraversalEpisodeMetadata recentEpisode) ||
                    recentEpisode == null ||
                    recentEpisode.StartBreadcrumbSequence <= 0 ||
                    recentEpisode.EndBreadcrumbSequence <= 0 ||
                    Time.time - recentEpisode.CreatedAt > NavigationRecoveryRecentTraversalEpisodeSeconds)
                {
                    continue;
                }

                Vector3 entry = recentEpisode.HasSettledStart && IsFinite(recentEpisode.SettledStart)
                    ? recentEpisode.SettledStart
                    : (IsFinite(recentEpisode.Entry) ? recentEpisode.Entry : recentEpisode.RawStart);
                Vector3 exit = recentEpisode.HasSettledEnd && IsFinite(recentEpisode.SettledEnd)
                    ? recentEpisode.SettledEnd
                    : (IsFinite(recentEpisode.Exit) ? recentEpisode.Exit : recentEpisode.RawEnd);
                if (!IsFinite(entry) || !IsFinite(exit) || GetPlanarDistance(entry, exit) < 0.25f)
                {
                    continue;
                }

                float entryDistance = GetPlanarDistance(bot.Position, entry);
                float exitDistanceFromBot = GetPlanarDistance(bot.Position, exit);
                float entryToDestination = Vector3.Distance(entry, destination);
                float exitToDestination = Vector3.Distance(exit, destination);

                // Recovery is allowed only while the follower is still on the demonstrated entry
                // side and the authored far side makes real progress toward the current Follow
                // destination. Never reverse the player episode merely because the bot is closer to
                // its old exit.
                if (entryDistance > 4.5f ||
                    exitDistanceFromBot < entryDistance + 0.20f ||
                    exitToDestination + 0.50f >= entryToDestination ||
                    exitToDestination + 0.75f >= botDistance)
                {
                    continue;
                }

                if (exitToDestination < bestExitDistance &&
                    FollowerSafeTeleport.TryValidateTraversalExitAnchor(bot, exit, out Vector3 candidate))
                {
                    bestTraversal = edge;
                    bestExit = candidate;
                    bestExitDistance = exitToDestination;
                }
            }
            if (bestTraversal != null)
            {
                anchor = bestExit;
                source = $"recentTraversalExit:{bestTraversal.Id}:{bestTraversal.Kind}";
                return true;
            }

            // Generic Follow recovery deliberately stays farther from the player. Prefer a recent
            // breadcrumb roughly 6-11m from the destination so the fallback looks like a squadmate
            // catching up from behind, not spawning at the player's shoulder. Grounded is advisory
            // only here; the final NavMesh/capsule/path validation remains authoritative.
            for (int pass = 0; pass < 2; pass++)
            {
                float minimumDestinationDistance = pass == 0 ? 6.0f : 4.5f;
                float maximumDestinationDistance = pass == 0 ? 11.0f : 12.0f;
                for (int i = BreadcrumbRoute.Count - 1; i >= 0; i--)
                {
                    PlayerBreadcrumbNode node = BreadcrumbRoute[i];
                    if (node == null || Time.time - node.CreatedAt > 35f || IsTraversalStateName(node.State))
                    {
                        continue;
                    }

                    float nodeDistance = Vector3.Distance(node.Position, destination);
                    if (nodeDistance < minimumDestinationDistance || nodeDistance > maximumDestinationDistance ||
                        nodeDistance + 1.5f >= botDistance)
                    {
                        continue;
                    }

                    if (FollowerSafeTeleport.TryValidateRecoveryAnchor(
                            bot,
                            node.Position,
                            destination,
                            out Vector3 candidate))
                    {
                        anchor = candidate;
                        source = $"breadcrumb:{node.Sequence}";
                        return true;
                    }
                }
            }

            if ((IsLearningV350TerminalPhysicalRecoveryEligible(bot)))
            {
                // V3.50 terminal fallback: the player route itself is the destination contract.
                // Do not demand a NavMesh path from the recovery point to a leader who may still
                // be traversing a long off-NavMesh span. Only recent, grounded, non-traversal
                // breadcrumbs that make real destination progress are eligible, and the shared
                // teleport helper still proves local ground/capsule safety.
                bool foundPhysicalRouteAnchor = false;
                Vector3 physicalRouteAnchor = default;
                int physicalRouteSequence = 0;
                float physicalRouteDestinationDistance = float.PositiveInfinity;
                for (int i = BreadcrumbRoute.Count - 1; i >= 0; i--)
                {
                    PlayerBreadcrumbNode node = BreadcrumbRoute[i];
                    if (node == null || Time.time - node.CreatedAt > 35f ||
                        !node.Grounded || IsTraversalStateName(node.State) ||
                        !IsFinite(node.Position))
                    {
                        continue;
                    }

                    float nodeDistance = GetPlanarDistance(node.Position, destination);
                    if (nodeDistance < 4.5f || nodeDistance > 14.0f ||
                        nodeDistance + 1.5f >= botDistance)
                    {
                        continue;
                    }

                    if (!TryValidateLearningV350PlayerRoutePhysicalRecoveryAnchor(
                            bot, node.Position, out Vector3 candidate))
                    {
                        continue;
                    }

                    float candidateDistance = GetPlanarDistance(candidate, destination);
                    if (!foundPhysicalRouteAnchor || candidateDistance < physicalRouteDestinationDistance)
                    {
                        foundPhysicalRouteAnchor = true;
                        physicalRouteAnchor = candidate;
                        physicalRouteSequence = node.Sequence;
                        physicalRouteDestinationDistance = candidateDistance;
                    }
                }

                if (foundPhysicalRouteAnchor)
                {
                    anchor = physicalRouteAnchor;
                    source = $"learningV350PhysicalBreadcrumb:{physicalRouteSequence}";
                    WriteEvent("learningV350PhysicalBreadcrumbRecoveryAnchorSelected", bot, new
                    {
                        breadcrumbSequence = physicalRouteSequence,
                        anchor = Vec(physicalRouteAnchor),
                        destination = Vec(destination),
                        destinationDistance = physicalRouteDestinationDistance,
                        botDistance,
                        navMeshPathToDestinationRequired = false,
                        action = "terminalRecoveryUsesRecentPlayerAuthoredPhysicalRoute"
                    });
                    return true;
                }

                WriteEvent("learningV350PhysicalBreadcrumbRecoveryAnchorUnavailable", bot, new
                {
                    destination = Vec(destination),
                    botDistance,
                    action = "fallThroughToNearDestinationSearch"
                });
            }

            return false;
        }

        internal static bool HasActiveTraversalProbe(BotOwner bot)
        {
            return bot != null && TryGetActiveProbe(bot, out _);
        }

        public static bool ShouldSkipManualFixedUpdate(BotMover mover)
        {
            if (mover == null)
            {
                return false;
            }

            BotOwner owner = mover._owner;
            BotFollowerPlayer follower = owner != null
                ? BossPlayers.GetFollowerByProfileId(owner.ProfileId)
                : null;
            if (follower?.IsTeleportStabilizing == true)
            {
                // V1.3.20 anti-rollback: suppress the stale BotMover writer until the shared
                // teleport stabilization state has verified the new authoritative position.
                return true;
            }

            if (!TryGetActiveProbe(owner, out ProbeRuntime probe) ||
                !probe.ExclusiveMoverGate || probe.Generation != raidGeneration)
            {
                return false;
            }

            if (probe.Stage == ProbeStage.ExitCommit)
            {
                // V3.48 keeps the motion integrator alive during ExitCommit. The regression was
                // specifically the stale NavMesh BODY projection leaf (method_10 /
                // SetPlayerToNavMesh), not ordinary method_21 path integration. Narrow projection
                // gates below suppress those leaves until consumer handoff installs a fresh epoch.
                return !probe.ExitAuthorityMoverValidationActive;
            }

            // RollingApproach and direct WalkThrough deliberately keep BotMover alive: those
            // stages are still consuming an ordinary approach path. Once a custom crossing or
            // rolling Egress owns the character, suppress stale BotMover fixed updates so the old
            // entry path cannot pull the follower backward.
            if (probe.Stage == ProbeStage.RollingApproach ||
                probe.Stage == ProbeStage.NativeEntryAcquisition ||
                probe.Stage == ProbeStage.WalkThrough)
            {
                return false;
            }

            // Native EFT jump execution is the one exception: after TryJump() the ordinary mover
            // provides horizontal run-up/air momentum. Assisted Jump uses AssistedReplay instead
            // and therefore remains exclusively traversal-owned.
            bool nativeJumpStage = probe.JumpAttempted &&
                                   (probe.Stage == ProbeStage.JumpPriming ||
                                    probe.Stage == ProbeStage.WaitingForState ||
                                    probe.Stage == ProbeStage.Traversing ||
                                    probe.Stage == ProbeStage.Landing);
            if (nativeJumpStage)
            {
                return false;
            }

            // CompileFix45 native DropDown also needs the ordinary mover/player movement update
            // alive while forward input carries the body off the ledge under real gravity.
            if (probe.NativeDropDownAttempted && probe.Stage == ProbeStage.NativeDropDown)
            {
                return false;
            }

            // V1.3.25-R4: Injected EFT Vault must keep the ordinary BotMover fixed-update
            // pipeline alive. R3 suppressed the entire ManualFixedUpdate while native root motion
            // was active; that also suppressed non-relink mover bookkeeping and correlated with
            // partial Vault displacement / lateral sliding. Native root motion still gates the
            // ordinary relink callback; WalkThrough uses the narrower SetPlayerToNavMesh gate.
            bool injectedNativeVaultStage = probe.InjectedNativeVaultAttempted &&
                                            (probe.Stage == ProbeStage.WaitingForState ||
                                             probe.Stage == ProbeStage.Traversing ||
                                             probe.Stage == ProbeStage.Landing);
            if (injectedNativeVaultStage)
            {
                return false;
            }

            return probe.Stage == ProbeStage.AssistedReplay ||
                   probe.Stage == ProbeStage.Egress ||
                   probe.Stage == ProbeStage.WaitingForState ||
                   probe.Stage == ProbeStage.Traversing ||
                   probe.Stage == ProbeStage.Landing ||
                   probe.Stage == ProbeStage.Verify ||
                   probe.Stage == ProbeStage.TeleportArm ||
                   probe.Stage == ProbeStage.SafetyHold;
        }


        private static bool IsLearningV420CanonicalPhysicalRouteRelinkBarrier(BotOwner bot)
        {
            if ((bot == null) ||
                string.IsNullOrEmpty(bot.ProfileId) ||
                !FollowerTraversalRouteCursors.TryGetValue(
                    bot.ProfileId, out FollowerTraversalRouteCursor cursor) ||
                cursor == null || !cursor.LearningV375TransactionActive ||
                cursor.LearningV375MovementGeneration <= 0)
            {
                return false;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (owner != FollowerMovementWriterAuthority.WriterDomain.Traversal ||
                generation != cursor.LearningV375MovementGeneration)
            {
                return false;
            }

            string producer = cursor.LearningV375ProducerKind ?? string.Empty;
            bool canonicalPhysicalProducer =
                string.Equals(producer, "V409NativeLocomotionIntent", StringComparison.Ordinal) ||
                string.Equals(producer, "V406CanonicalPhysical", StringComparison.Ordinal) ||
                string.Equals(producer, "ContinuousPhysicalRoute", StringComparison.Ordinal) ||
                string.Equals(producer, "PreProbePhysicalRoute", StringComparison.Ordinal) ||
                string.Equals(producer, "PhysicalCorridor", StringComparison.Ordinal) ||
                string.Equals(producer, "TraversalProbePhysicalProgress", StringComparison.Ordinal) ||
                string.Equals(producer, "V411ExactWalkThroughProbe", StringComparison.Ordinal) ||
                string.Equals(producer, "V410ExactWalkThroughProbe", StringComparison.Ordinal) ||
                string.Equals(producer, "V419ActuatorPostFrontierProbe", StringComparison.Ordinal) ||
                string.Equals(producer, "TraversalProbeActuatorLifecycle", StringComparison.Ordinal);
            return canonicalPhysicalProducer;
        }

        public static bool ShouldSkipNavMeshRelink(BotMover mover)
        {
            if (mover == null)
            {
                return false;
            }

            BotOwner owner = mover._owner;
            BotFollowerPlayer follower = owner != null
                ? BossPlayers.GetFollowerByProfileId(owner.ProfileId)
                : null;
            if (follower?.IsTeleportStabilizing == true)
            {
                return true;
            }

            if (IsLearningV420CanonicalPhysicalRouteRelinkBarrier(owner))
            {
                if (ShouldEmitDiagnostic(
                        "learningV420CanonicalPhysicalRouteNavMeshRelinkSuppressed", owner, 0.25f))
                {
                    long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                        owner, out FollowerMovementWriterAuthority.WriterDomain movementOwner);
                    FollowerTraversalRouteCursors.TryGetValue(
                        owner.ProfileId ?? string.Empty, out FollowerTraversalRouteCursor cursor);
                    WriteEvent("learningV420CanonicalPhysicalRouteNavMeshRelinkSuppressed", owner, new
                    {
                        movementOwner = movementOwner.ToString(),
                        movementGeneration = generation,
                        producer = cursor?.LearningV375ProducerKind ?? string.Empty,
                        missionId = cursor?.LearningV375RouteMissionId ?? 0,
                        body = Vec(owner.Position),
                        bodyRelocated = false,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "canonicalPhysicalRouteOwnsBodySuppressOnlyStaleNavMeshProjectionKeepManualFixedUpdateAlive"
                    });
                }
                return true;
            }

            if (!TryGetActiveProbe(owner, out ProbeRuntime probe) ||
                probe.Generation != raidGeneration)
            {
                return false;
            }

            if (IsLearningV349TraversalOwnedPhysicalEpoch(probe))
            {
                return true;
            }

            bool learningV337NativeJumpPhysicalBody =
                (probe.JumpAttempted) &&
                (probe.Stage == ProbeStage.WaitingForState ||
                 probe.Stage == ProbeStage.Traversing ||
                 probe.Stage == ProbeStage.Landing ||
                 (probe.Stage == ProbeStage.ExitCommit && probe.LearningV330NativeJumpQualifiedLandingWitness));
            if (learningV337NativeJumpPhysicalBody)
            {
                return true;
            }
            if ((probe.Stage == ProbeStage.ExitCommit) &&
                probe.LearningV337ConsumerFirstExitValidationActive)
            {
                return true;
            }

            if ((probe.LearningV343InheritedPhysicalLayerGuard) &&
                (probe.Stage == ProbeStage.Aligning ||
                 probe.Stage == ProbeStage.Approaching ||
                 probe.Stage == ProbeStage.RollingApproach ||
                 probe.Stage == ProbeStage.NativeEntryAcquisition ||
                 probe.Stage == ProbeStage.LearnedJumpTakeoffPriming))
            {
                return true;
            }

            if (!probe.ExclusiveMoverGate)
            {
                return false;
            }

            if (probe.Stage == ProbeStage.ExitCommit)
            {
                // V3.48: ExitCommit still belongs to the completed physical traversal. Do not
                // let stale NavMesh projection relocate the body while mover validation is
                // examining the landing. BotMoverImpostor.method_21 remains enabled separately so
                // legitimate motion/path integration is preserved.
                return (true);
            }

            // V3.8: V3.7 proved same-update dispatch works, but the successor DropDown could still
            // snap from ~0.42m to ~1.85m from its entry while already in RollingApproach. The old
            // relink gate did not cover RollingApproach. Keep ordinary BotMover integration alive,
            // but suppress native NavMesh body projection while this exact continuous passage guard
            // proves the successor owns the same WT->DropDown physical body.
            if ((probe.Stage == ProbeStage.RollingApproach || probe.Stage == ProbeStage.NativeEntryAcquisition) &&
                (IsContinuousWalkThroughDropDownSuccessor(probe) ||
                 TryGetLearningV354ContinuousSuccessorHandoffGuard(probe, out _)))
            {
                return true;
            }

            if (probe.Stage == ProbeStage.WalkThrough)
            {
                return true;
            }

            // R8: WalkThrough and player-authored Jump remain traversal-owned through Egress and
            // Verify. Re-enabling SetPlayerToNavMesh at the WalkThrough->Egress boundary could snap
            // a follower several metres back to the entry-side polygon after it physically crossed.
            bool unifiedAntiSnap = probe.UnifiedTraversalFlow &&
                                   (probe.Stage == ProbeStage.Egress || probe.Stage == ProbeStage.Verify) &&
                                   (string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                                    string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                                    string.Equals(probe.TraversalKind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                                    probe.NativeRunOutActive);
            if (unifiedAntiSnap)
            {
                return true;
            }

            // CompileFix45: while the body is actually leaving/falling from a DropDown ledge,
            // do not project it back onto the entry-side polygon. method_21 still runs so real
            // motion integration is preserved; only SetPlayerToNavMesh is suppressed.
            if (probe.NativeDropDownAttempted && probe.Stage == ProbeStage.NativeDropDown)
            {
                return true;
            }

            // Native root motion must not be projected back onto the old NavMesh route.
            return probe.InjectedNativeVaultAttempted &&
                   (probe.Stage == ProbeStage.WaitingForState ||
                    probe.Stage == ProbeStage.Traversing ||
                    probe.Stage == ProbeStage.Landing);
        }

        private static bool TryGetContinuousWalkThroughDropDownHandoffGuard(
            ProbeRuntime probe,
            out ChainHandoffAuthorityGuard guard)
        {
            guard = null;
            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || probe == null ||
                !ChainHandoffAuthorityGuards.TryGetValue(profileId, out guard) ||
                guard == null || guard.Generation != raidGeneration ||
                !guard.ContinuousWalkThroughDropDownPassage || !guard.SuccessorAuthorityAcquired)
            {
                guard = null;
                return false;
            }

            bool matchingSuccessor =
                (guard.SuccessorProbeEdgeId <= 0 || guard.SuccessorProbeEdgeId == probe.LearnedEdgeId) &&
                (guard.SuccessorProbeChainId <= 0 || probe.TraversalChainId <= 0 ||
                 guard.SuccessorProbeChainId == probe.TraversalChainId);
            if (!matchingSuccessor)
            {
                guard = null;
            }
            return matchingSuccessor;
        }

        private static bool IsContinuousWalkThroughDropDownSuccessor(ProbeRuntime probe)
        {
            {
                return false;
            }
            return TryGetContinuousWalkThroughDropDownHandoffGuard(probe, out _);
        }


        private static void EmitLearningV346PhysicalNavigationEpochSnapshot(
            ProbeRuntime probe, string boundary, Vector3? rejectedProjectionCandidate = null)
        {
            if ((probe?.Bot == null))
            {
                return;
            }

            try
            {
                BotOwner bot = probe.Bot;
                BotMover mover = bot.Mover;
                Vector3 body = probe.Player != null ? probe.Player.Position : bot.Position;
                long currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                    bot, out FollowerMovementWriterAuthority.WriterDomain currentOwner);

                NavMeshHit navHit = default(NavMeshHit);
                bool navSampled = IsFinite(body) && NavMesh.SamplePosition(body, out navHit, 1.50f, NavMesh.AllAreas);
                Vector3 navPosition = navSampled ? navHit.position : body;
                int navAreaMask = navSampled ? navHit.mask : 0;

                bool hasMoverTarget = false;
                Vector3 moverTarget = default(Vector3);
                bool hasCurrentCorner = false;
                Vector3 currentCorner = default(Vector3);
                bool moverHavePath = false;
                bool moverHasPathAndNoComplete = false;
                bool moverIsMoving = false;
                bool moverPaused = false;
                bool moverSprinting = false;
                bool hasPositionOnWay = false;
                Vector3 positionOnWay = default(Vector3);
                bool hasPrevLinked = false;
                Vector3 prevLinked = default(Vector3);

                if (mover != null)
                {
                    if (mover.TargetPoint is Vector3 target && IsFinite(target))
                    {
                        hasMoverTarget = true;
                        moverTarget = target;
                    }
                    moverHavePath = mover.ActualPathController?.HavePath == true;
                    moverHasPathAndNoComplete = mover.HasPathAndNoComplete == true;
                    moverIsMoving = mover.IsMoving == true;
                    moverPaused = mover.Pause == true;
                    moverSprinting = mover.Sprinting == true;
                    if (IsFinite(mover.PositionOnWayInner))
                    {
                        hasPositionOnWay = true;
                        positionOnWay = mover.PositionOnWayInner;
                    }
                    if (IsFinite(mover.PrevSuccessLinkedFrom))
                    {
                        hasPrevLinked = true;
                        prevLinked = mover.PrevSuccessLinkedFrom;
                    }
                    if (moverHavePath)
                    {
                        Vector3 corner = mover.ActualPathController.CurrentCornerPoint;
                        if (IsFinite(corner))
                        {
                            hasCurrentCorner = true;
                            currentCorner = corner;
                        }
                    }
                }

                int routeMissionId = 0;
                int routeStepIndex = -1;
                int routeStepEdgeId = 0;
                string routeStepKind = string.Empty;
                if (FollowerRouteMissions.TryGetValue(bot.ProfileId ?? string.Empty, out FollowerRouteMission mission) &&
                    mission?.Steps != null && mission.CurrentStepIndex >= 0 && mission.CurrentStepIndex < mission.Steps.Count)
                {
                    routeMissionId = mission.MissionId;
                    routeStepIndex = mission.CurrentStepIndex;
                    FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
                    routeStepEdgeId = step?.EdgeId ?? 0;
                    routeStepKind = step?.Kind ?? string.Empty;
                }

                WriteEvent("learningV346PhysicalNavigationEpochSnapshot", bot, new
                {
                    boundary = boundary ?? string.Empty,
                    edgeId = probe.LearnedEdgeId,
                    chainId = probe.TraversalChainId,
                    kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                    stage = probe.Stage.ToString(),
                    body = IsFinite(body) ? (object)Vec(body) : null,
                    navSampled,
                    navPosition = navSampled ? (object)Vec(navPosition) : null,
                    navAreaMask,
                    moverPositionOnWay = hasPositionOnWay ? (object)Vec(positionOnWay) : null,
                    moverPrevSuccessLinkedFrom = hasPrevLinked ? (object)Vec(prevLinked) : null,
                    moverTarget = hasMoverTarget ? (object)Vec(moverTarget) : null,
                    currentCorner = hasCurrentCorner ? (object)Vec(currentCorner) : null,
                    moverHavePath,
                    moverHasPathAndNoComplete,
                    moverIsMoving,
                    moverPaused,
                    moverSprinting,
                    movementOwner = currentOwner.ToString(),
                    movementGeneration = currentGeneration,
                    probeMovementGeneration = probe.MovementWriterGeneration,
                    exclusiveMoverGate = probe.ExclusiveMoverGate,
                    routeMissionId,
                    routeStepIndex,
                    routeStepEdgeId,
                    routeStepKind,
                    rejectedProjectionCandidate = rejectedProjectionCandidate.HasValue && IsFinite(rejectedProjectionCandidate.Value)
                        ? (object)Vec(rejectedProjectionCandidate.Value) : null
                });
            }
            catch (Exception ex)
            {
                WriteEvent("learningV346PhysicalNavigationEpochSnapshotFailed", probe?.Bot, new
                {
                    boundary = boundary ?? string.Empty,
                    edgeId = probe?.LearnedEdgeId ?? 0,
                    failure = ex.GetType().Name + ": " + ex.Message
                });
            }
        }

        private static bool IsLearningV345TraversalEntryPhysicalEpoch(ProbeRuntime probe)
        {
            return (probe != null) &&
                   probe.Generation == raidGeneration && probe.ExclusiveMoverGate &&
                   (probe.Stage == ProbeStage.RollingApproach ||
                    probe.Stage == ProbeStage.NativeEntryAcquisition);
        }

        private static bool IsLearningV349TraversalOwnedPhysicalEpoch(ProbeRuntime probe)
        {
            if ((probe?.Bot == null) ||
                probe.Generation != raidGeneration || !IsActiveProbe(probe))
            {
                return false;
            }

            long currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                probe.Bot, out FollowerMovementWriterAuthority.WriterDomain currentOwner);
            bool learningV349WalkThroughPreflightPhysicalEpoch =
                currentOwner == FollowerMovementWriterAuthority.WriterDomain.Follow &&
                probe.Stage == ProbeStage.Aligning &&
                probe.LearningV330WalkThroughPreflightFollowAuthority &&
                string.Equals(
                    probe.TraversalKind ?? probe.RequestedTraversalKind,
                    "WalkThrough", StringComparison.OrdinalIgnoreCase);
            bool learningV349TraversalOwnedPhysicalEpoch =
                currentOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal;
            if ((!learningV349TraversalOwnedPhysicalEpoch && !learningV349WalkThroughPreflightPhysicalEpoch) ||
                (probe.MovementWriterGeneration > 0 && currentGeneration != probe.MovementWriterGeneration))
            {
                return false;
            }

            // This is a body-projection barrier, not a ManualFixedUpdate barrier. method_21 may
            // continue integrating legitimate locomotion while method_10/SetPlayerToNavMesh may
            // not replace the Traversal-owned body with stale navigation truth.
            switch (probe.Stage)
            {
                case ProbeStage.Aligning:
                case ProbeStage.Approaching:
                case ProbeStage.RollingApproach:
                case ProbeStage.NativeEntryAcquisition:
                case ProbeStage.JumpPriming:
                case ProbeStage.LearnedJumpTakeoffPriming:
                case ProbeStage.Priming:
                case ProbeStage.ForwardHop:
                case ProbeStage.NativeDropDown:
                case ProbeStage.AssistedReplay:
                case ProbeStage.NativeGroundContinuation:
                case ProbeStage.WalkThrough:
                case ProbeStage.Egress:
                case ProbeStage.Verify:
                case ProbeStage.ExitCommit:
                case ProbeStage.WaitingForState:
                case ProbeStage.PostLandingCommit:
                case ProbeStage.Traversing:
                case ProbeStage.Landing:
                    return true;
                default:
                    return false;
            }
        }

        /// <summary>
        /// V3.8 final body-writer gate. BotMover.method_10 is the native relink leaf that actually
        /// writes BotOwner.Transform.position. Existing method_12/SetPlayerToNavMesh gates catch
        /// normal callers; this leaf gate also catches any direct method_9 -> method_10 path and
        /// provides a falsifiable diagnostic for the WT->DropDown snap hypothesis.
        /// </summary>
        public static bool ShouldSuppressNativeNavMeshBodyRelink(BotMover mover, Vector3 possiblePosition, bool withExtra)
        {
            if (mover == null)
            {
                return false;
            }

            BotOwner owner = mover._owner;
            if(ProtectCapabilityLocalBodyProjection(owner)||RejectCapabilityPostCompletionProjection(owner,possiblePosition))
            {
                if(owner?.GetPlayer!=null&&IsFinite(possiblePosition)&&OwnsCapabilityAdmittedIngress(owner)&&
                    ShouldEmitDiagnostic("capabilityIngressProjectionRejected",owner,.10f))
                    WriteEvent("capabilityIngressProjectionRejected",owner,new{body=Vec(owner.GetPlayer.Position),
                        candidate=Vec(possiblePosition),withExtra,bodyRelocated=false,nativeSuccessRecorded=false});
                return true;
            }
            if (owner != null &&
                HasLearningV364UnsynchronizedPhysicalNavigationEpoch(
                    owner, out PhysicalNavigationEpochHandoff learningV364Handoff))
            {
                long movementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                    owner, out FollowerMovementWriterAuthority.WriterDomain movementOwner);
                if (ShouldEmitDiagnostic(
                        "learningV364StaleNavigationEpochProjectionSuppressed:" +
                            learningV364Handoff.SourceEdgeId.ToString(CultureInfo.InvariantCulture),
                        owner,
                        0.04f))
                {
                    WriteEvent("learningV364StaleNavigationEpochProjectionSuppressed", owner, new
                    {
                        edgeId = learningV364Handoff.SourceEdgeId,
                        episodeId = learningV364Handoff.EpisodeId,
                        chainId = learningV364Handoff.ChainId,
                        source = learningV364Handoff.Source ?? string.Empty,
                        physicalAnchor = Vec(learningV364Handoff.PhysicalAnchor),
                        current = Vec(owner.GetPlayer != null ? owner.GetPlayer.Position : owner.Position),
                        candidate = IsFinite(possiblePosition) ? (object)Vec(possiblePosition) : null,
                        movementOwner = movementOwner.ToString(),
                        movementGeneration,
                        freshConsumerPathObserved = learningV364Handoff.FreshConsumerPathObserved,
                        freshConsumerPathSource = learningV364Handoff.FreshConsumerPathSource ?? string.Empty,
                        withExtra,
                        action = "rejectNativeBodyProjectionUntilPhysicalAndNavigationEpochsAreSynchronized"
                    });
                }
                return true;
            }
            if (owner != null && TryGetActiveProbe(owner, out ProbeRuntime learningV349Probe) &&
                IsLearningV349TraversalOwnedPhysicalEpoch(learningV349Probe))
            {
                if (ShouldEmitDiagnostic("learningV349TraversalPhysicalEpochProjectionSuppressed", owner, 0.08f))
                {
                    EmitLearningV346PhysicalNavigationEpochSnapshot(
                        learningV349Probe, "learningV349ProjectionRejected", possiblePosition);
                    WriteEvent("learningV349TraversalPhysicalEpochProjectionSuppressed", owner, new
                    {
                        edgeId = learningV349Probe.LearnedEdgeId,
                        kind = learningV349Probe.TraversalKind ?? learningV349Probe.RequestedTraversalKind,
                        stage = learningV349Probe.Stage.ToString(),
                        current = Vec(learningV349Probe.Player != null ? learningV349Probe.Player.Position : owner.Position),
                        candidate = Vec(possiblePosition),
                        movementGeneration = learningV349Probe.MovementWriterGeneration,
                        withExtra,
                        action = "rejectNavMeshBodyProjectionAcrossWholeTraversalPhysicalEpochAllowMethod21Integration"
                    });
                }
                return true;
            }
            if ((owner != null) &&
                TryGetActiveProbe(owner, out ProbeRuntime exitProbe) &&
                exitProbe != null && exitProbe.Generation == raidGeneration &&
                exitProbe.ExclusiveMoverGate && exitProbe.Stage == ProbeStage.ExitCommit)
            {
                if (ShouldEmitDiagnostic("learningV348ExitCommitNavMeshBodyProjectionSuppressed", owner, 0.08f))
                {
                    EmitLearningV346PhysicalNavigationEpochSnapshot(exitProbe, "exitProjectionRejected", possiblePosition);
                    WriteEvent("learningV348ExitCommitNavMeshBodyProjectionSuppressed", owner, new
                    {
                        edgeId = exitProbe.LearnedEdgeId,
                        kind = exitProbe.TraversalKind ?? exitProbe.RequestedTraversalKind,
                        stage = exitProbe.Stage.ToString(),
                        current = Vec(exitProbe.Player != null ? exitProbe.Player.Position : owner.Position),
                        candidate = Vec(possiblePosition),
                        movementGeneration = exitProbe.MovementWriterGeneration,
                        action = "preservePhysicalExitBodyAllowMethod21Integration"
                    });
                }
                return true;
            }
            if (owner != null && TryGetActiveProbe(owner, out ProbeRuntime entryProbe) &&
                IsLearningV345TraversalEntryPhysicalEpoch(entryProbe))
            {
                if (ShouldEmitDiagnostic("learningV345TraversalEntryNavMeshBodyProjectionSuppressed", owner, 0.08f))
                {
                    EmitLearningV346PhysicalNavigationEpochSnapshot(entryProbe, "entryProjectionRejected", possiblePosition);
                    WriteEvent("learningV345TraversalEntryNavMeshBodyProjectionSuppressed", owner, new
                    {
                        edgeId = entryProbe.LearnedEdgeId,
                        kind = entryProbe.TraversalKind ?? entryProbe.RequestedTraversalKind,
                        stage = entryProbe.Stage.ToString(),
                        current = Vec(entryProbe.Player != null ? entryProbe.Player.Position : owner.Position),
                        candidate = Vec(possiblePosition),
                        movementGeneration = entryProbe.MovementWriterGeneration,
                        action = "keepTraversalOwnedPhysicalBodyEpochWhileAllowingMotionIntegration"
                    });
                }
                return true;
            }
            if ((owner != null) && IsFinite(possiblePosition) &&
                PostTraversalIntegrityWatches.TryGetValue(owner.ProfileId ?? string.Empty, out PostTraversalIntegrityWatch postWatch) &&
                postWatch != null && postWatch.ExpiresAt >= Time.time &&
                IsFinite(postWatch.Entry) && IsFinite(postWatch.Exit))
            {
                long postGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                    owner, out FollowerMovementWriterAuthority.WriterDomain postOwner);
                bool learningV418PersistentTraversalConsumer = false;
                int learningV418LiveMissionId = 0;
                int learningV418LiveMissionStepIndex = -1;
                if ((postOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal) &&
                    postWatch.MovementGeneration > 0 && postGeneration == postWatch.MovementGeneration &&
                    FollowerRouteMissions.TryGetValue(
                        owner.ProfileId ?? string.Empty, out FollowerRouteMission learningV418LiveMission) &&
                    learningV418LiveMission != null)
                {
                    learningV418LiveMissionId = learningV418LiveMission.MissionId;
                    learningV418LiveMissionStepIndex = learningV418LiveMission.CurrentStepIndex;
                    learningV418PersistentTraversalConsumer =
                        postWatch.MissionId > 0 &&
                        learningV418LiveMission.MissionId == postWatch.MissionId &&
                        postWatch.MissionStepIndex >= 0 &&
                        learningV418LiveMission.CurrentStepIndex > postWatch.MissionStepIndex;
                }
                bool learningV418MonotonicPostConsumer =
                    postOwner == FollowerMovementWriterAuthority.WriterDomain.PostTraversal ||
                    learningV418PersistentTraversalConsumer;
                Vector3 currentBody = owner.GetPlayer != null ? owner.GetPlayer.Position : owner.Position;
                float currentEntryDistance = GetPlanarDistance(currentBody, postWatch.Entry);
                float currentExitDistance = GetPlanarDistance(currentBody, postWatch.Exit);
                float candidateEntryDistance = GetPlanarDistance(possiblePosition, postWatch.Entry);
                float candidateExitDistance = GetPlanarDistance(possiblePosition, postWatch.Exit);
                bool currentFarSide = currentExitDistance + PostTraversalRollbackSideMargin < currentEntryDistance;
                bool candidateRegressesToEntry =
                    candidateEntryDistance + PostTraversalRollbackSideMargin < candidateExitDistance;
                if ((IsFinite(postWatch.Entry)) && IsFinite(postWatch.Exit))
                {
                    Vector3 semanticAxis = postWatch.Exit - postWatch.Entry;
                    semanticAxis.y = 0f;
                    float semanticSpan = semanticAxis.magnitude;
                    if (semanticSpan >= WalkThroughCandidateMinDistance)
                    {
                        semanticAxis /= semanticSpan;
                        Vector3 currentOffset = currentBody - postWatch.Entry; currentOffset.y = 0f;
                        Vector3 candidateOffset = possiblePosition - postWatch.Entry; candidateOffset.y = 0f;
                        float currentProjection = Vector3.Dot(currentOffset, semanticAxis);
                        float candidateProjection = Vector3.Dot(candidateOffset, semanticAxis);
                        currentFarSide = currentProjection >= semanticSpan - PostTraversalRollbackSideMargin;
                        candidateRegressesToEntry = candidateProjection <= PostTraversalRollbackSideMargin;
                    }
                }
                bool learningV352SoftProjectionGuardActive =
                    ((!postWatch.FreshConsumerPathProven &&
                     Time.time <= postWatch.ArmedAt + LearningV352PostTraversalSoftProjectionGraceSeconds));
                if ((learningV352SoftProjectionGuardActive) &&
                    learningV418MonotonicPostConsumer)
                {
                    Vector3 monotonicAxis = postWatch.Exit - postWatch.Entry;
                    monotonicAxis.y = 0f;
                    float monotonicSpan = monotonicAxis.magnitude;
                    if (monotonicSpan >= WalkThroughCandidateMinDistance)
                    {
                        monotonicAxis /= monotonicSpan;
                        Vector3 currentMonotonicOffset = currentBody - postWatch.Entry;
                        currentMonotonicOffset.y = 0f;
                        Vector3 candidateMonotonicOffset = possiblePosition - postWatch.Entry;
                        candidateMonotonicOffset.y = 0f;
                        float currentMonotonicProjection = Vector3.Dot(currentMonotonicOffset, monotonicAxis);
                        float candidateMonotonicProjection = Vector3.Dot(candidateMonotonicOffset, monotonicAxis);
                        float regression = currentMonotonicProjection - candidateMonotonicProjection;
                        if (regression >= LearningV350PostTraversalProjectionRegressionTolerance)
                        {
                            if (ShouldEmitDiagnostic(
                                    "learningV350PostTraversalProjectionRegressionSuppressed", owner, 0.04f))
                            {
                                WriteEvent("learningV350PostTraversalProjectionRegressionSuppressed", owner, new
                                {
                                    edgeId = postWatch.EdgeId,
                                    episodeId = postWatch.EpisodeId,
                                    chainId = postWatch.CompletedChainId,
                                    current = Vec(currentBody),
                                    candidate = Vec(possiblePosition),
                                    currentProjection = currentMonotonicProjection,
                                    candidateProjection = candidateMonotonicProjection,
                                    regression,
                                    tolerance = LearningV350PostTraversalProjectionRegressionTolerance,
                                    movementOwner = postOwner.ToString(),
                                    movementGeneration = postGeneration,
                                    learningV418PersistentTraversalConsumer,
                                    learningV418LiveMissionId,
                                    learningV418LiveMissionStepIndex,
                                    watchedMissionId = postWatch.MissionId,
                                    watchedMissionStepIndex = postWatch.MissionStepIndex,
                                    withExtra,
                                    softProjectionGuardActive = learningV352SoftProjectionGuardActive,
                                    freshConsumerPathProven = postWatch.FreshConsumerPathProven,
                                    freshConsumerPathSource = postWatch.FreshConsumerPathSource ?? string.Empty,
                                    action = "rejectBackwardNavMeshProjectionOnlyBeforeFreshConsumerEpoch"
                                });
                            }
                            if (learningV418PersistentTraversalConsumer)
                            {
                                WriteEvent("learningV418PersistentTraversalPostFrontierRelinkSuppressed", owner, new
                                {
                                    edgeId = postWatch.EdgeId,
                                    episodeId = postWatch.EpisodeId,
                                    missionId = learningV418LiveMissionId,
                                    previousStepIndex = postWatch.MissionStepIndex,
                                    currentStepIndex = learningV418LiveMissionStepIndex,
                                    movementGeneration = postGeneration,
                                    currentProjection = currentMonotonicProjection,
                                    candidateProjection = candidateMonotonicProjection,
                                    regression,
                                    action = "sameTraversalTransactionSuccessorInheritsCompletedFrontierNavMeshMayNotProjectBehindIt"
                                });
                            }
                            return true;
                        }
                    }
                }

                if (learningV418MonotonicPostConsumer &&
                    currentFarSide && candidateRegressesToEntry)
                {
                    if (ShouldEmitDiagnostic("learningV343PostTraversalNativeRelinkRollbackSuppressed", owner, 0.04f))
                    {
                        WriteEvent("learningV343PostTraversalNativeRelinkRollbackSuppressed", owner, new
                        {
                            edgeId = postWatch.EdgeId,
                            episodeId = postWatch.EpisodeId,
                            chainId = postWatch.CompletedChainId,
                            current = Vec(currentBody),
                            candidate = Vec(possiblePosition),
                            entry = Vec(postWatch.Entry),
                            exit = Vec(postWatch.Exit),
                            currentEntryDistance,
                            currentExitDistance,
                            candidateEntryDistance,
                            candidateExitDistance,
                            movementOwner = postOwner.ToString(),
                            movementGeneration = postGeneration,
                            learningV418PersistentTraversalConsumer,
                            learningV418LiveMissionId,
                            learningV418LiveMissionStepIndex,
                            watchedMissionId = postWatch.MissionId,
                            watchedMissionStepIndex = postWatch.MissionStepIndex,
                            withExtra,
                            action = "rejectNativeNavMeshRollbackDuringPostTraversalConsumerIntegrity"
                        });
                    }
                    return true;
                }
            }

            if (!ShouldSkipNavMeshRelink(mover))
            {
                return false;
            }

            owner = mover._owner;
            if (owner != null && TryGetActiveProbe(owner, out ProbeRuntime probe) &&
                probe != null && probe.Generation == raidGeneration &&
                ShouldEmitDiagnostic("nativeBotMoverBodyRelinkSuppressed", owner, 0.08f))
            {
                WriteEvent("nativeBotMoverBodyRelinkSuppressed", owner, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                    stage = probe.Stage.ToString(),
                    current = Vec(probe.Player != null ? probe.Player.Position : owner.Position),
                    candidate = Vec(possiblePosition),
                    withExtra,
                    continuousWalkThroughDropDown = IsContinuousWalkThroughDropDownSuccessor(probe),
                    physicalTraversalPenalty = false
                });
            }
            return true;
        }

        /// <summary>
        /// BotMoverImpostor.method_21 is not merely a NavMesh relink. It also integrates actual motion
        /// into PositionOnWayInner and advances the active path corner. WalkThrough therefore
        /// MUST let method_21 run; SetPlayerToNavMesh itself is suppressed by a narrower patch.
        /// Native Vault and teleport stabilization still skip the whole callback because their
        /// motion is not ordinary BotMover path motion.
        /// </summary>
        public static bool ShouldSkipMotionAppliedRelink(BotMover mover)
        {
            if (mover == null)
            {
                return false;
            }

            BotOwner owner = mover._owner;
            BotFollowerPlayer follower = owner != null
                ? BossPlayers.GetFollowerByProfileId(owner.ProfileId)
                : null;
            if (follower?.IsTeleportStabilizing == true)
            {
                return true;
            }

            if (!TryGetActiveProbe(owner, out ProbeRuntime probe) ||
                probe.Generation != raidGeneration ||
                !probe.ExclusiveMoverGate)
            {
                return false;
            }

            if (probe.Stage == ProbeStage.ExitCommit)
            {
                return !probe.ExitAuthorityMoverValidationActive;
            }

            return probe.InjectedNativeVaultAttempted &&
                   (probe.Stage == ProbeStage.WaitingForState ||
                    probe.Stage == ProbeStage.Traversing ||
                    probe.Stage == ProbeStage.Landing);
        }

        /// <summary>
        /// Narrow anti-snap gate used by the SetPlayerToNavMesh Harmony patch. During WalkThrough
        /// the path integrator continues to run, but its final projection onto the old NavMesh is
        /// suppressed until the follower reaches the demonstrated far-side run-out.
        /// </summary>
        public static bool ShouldSuppressSetPlayerToNavMesh(BotMover mover)
        {
            if(ProtectCapabilityLocalBodyProjection(mover?._owner))return true;
            if (mover != null &&
                HasLearningV364UnsynchronizedPhysicalNavigationEpoch(
                    mover._owner, out PhysicalNavigationEpochHandoff _))
            {
                return true;
            }
            if (mover != null && TryGetActiveProbe(mover._owner, out ProbeRuntime probe))
            {
                if (IsLearningV349TraversalOwnedPhysicalEpoch(probe))
                {
                    return true;
                }
                if (IsLearningV345TraversalEntryPhysicalEpoch(probe))
                {
                    return true;
                }
                if ((probe != null) &&
                    probe.Generation == raidGeneration && probe.ExclusiveMoverGate &&
                    probe.Stage == ProbeStage.ExitCommit)
                {
                    return true;
                }
            }
            return ShouldSkipNavMeshRelink(mover);
        }


        /// <summary>
        /// T3 foundation: converts the player's diagnostic breadcrumb stream into an operational
        /// raid-local route. It only takes over when the current Bot->leader NavMesh route is
        /// incomplete, clearly inflated, or suddenly becomes much longer while direct distance
        /// changes only modestly. Once latched, normal Follow refreshes cannot overwrite the
        /// breadcrumb target until the follower advances or the commitment expires.
        /// </summary>
        public static bool TryGetOperationalBreadcrumbFollowTarget(
            BotOwner bot,
            Vector3 leaderPosition,
            out Vector3 target,
            out int breadcrumbTargetSequence)
        {
            target = default;
            breadcrumbTargetSequence = 0;

            if (!raidActive || !IsLiveBot(bot) ||
                (!BossPlayers.IsFollower(bot) && !FollowerEvacuationRuntime.IsDeathEvacuating(bot)) ||
                !IsFinite(bot.Position) || !IsFinite(leaderPosition))
            {
                return false;
            }

            PruneBreadcrumbRoute();
            if (BreadcrumbRoute.Count < 2)
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return false;
            }

            int consumedBreadcrumbSequence = 0;
            if (FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor routeCursor) && routeCursor != null)
            {
                consumedBreadcrumbSequence = routeCursor.ConsumedBreadcrumbSequence;
            }

            if (TryUseBreadcrumbFollowCommitment(bot, leaderPosition, out target, out breadcrumbTargetSequence))
            {
                return true;
            }

            if (BreadcrumbBarrierDetourUntil.TryGetValue(profileId, out float detourUntil))
            {
                if (Time.time < detourUntil)
                {
                    // The active barrier resolver already proved this local breadcrumb region could
                    // not be crossed. For a few seconds hand control back to ordinary Follow so it can
                    // commit to a genuine NavMesh detour instead of selecting a neighboring breadcrumb
                    // on the same wall.
                    return false;
                }
                BreadcrumbBarrierDetourUntil.Remove(profileId);
            }

            float directDistance = Vector3.Distance(bot.Position, leaderPosition);
            if (directDistance <= 1.0f || directDistance > BreadcrumbFollowMaxLeaderDistance)
            {
                UpdateFollowPathBaseline(profileId, directDistance, directDistance, false);
                return false;
            }

            StrictPathResult leaderPath = CalculateStrictPath(bot.Position, leaderPosition);
            CacheFollowPathSanity(bot, leaderPosition, directDistance, leaderPath);
            bool suddenInflation = IsSuddenFollowPathInflation(profileId, directDistance, leaderPath);
            bool suspicious = IsSuspiciousFollowPath(directDistance, leaderPath) || suddenInflation;
            UpdateFollowPathBaseline(profileId, directDistance, leaderPath.PathLength, leaderPath.StrictComplete);
            if (!suspicious)
            {
                return false;
            }

            // Work backwards from the most recent player position. The first breadcrumb with a
            // short, locally sane Bot->breadcrumb path is the newest point the follower can still
            // prove it can reach without accepting the leader detour. CompileFix30 bounds expensive
            // path probes per resolver pass; vector filtering remains free and later frames continue
            // from fresh geometry instead of monopolising the main thread.
            int breadcrumbPathEvaluations = 0;
            for (int index = BreadcrumbRoute.Count - 1; index >= 0; index--)
            {
                PlayerBreadcrumbNode node = BreadcrumbRoute[index];
                if (node.Sequence <= consumedBreadcrumbSequence)
                {
                    continue;
                }
                float age = Time.time - node.CreatedAt;
                if (age < 0f || age > BreadcrumbTtlSeconds || !IsOperationalBreadcrumbNode(node))
                {
                    continue;
                }

                Vector3 operationalNodeTarget = GetOperationalBreadcrumbTarget(node);
                if (!node.NavMeshSampled)
                {
                    continue;
                }
                float nodeDirect = Vector3.Distance(bot.Position, operationalNodeTarget);
                if (nodeDirect > BreadcrumbFollowMaxBotDistance)
                {
                    continue;
                }

                if (IsPostTraversalEntryBreadcrumbBlocked(bot, node.Position, out _, out _))
                {
                    continue;
                }

                // A gap already proven unresolved must not be selected again as an ordinary anchor
                // during its quarantine window. This is the direct fix for the #149 -> #150
                // release/re-latch loop seen in the V1.3.6 raid logs.
                if (IsBreadcrumbGapAnchorQuarantined(profileId, node.Position))
                {
                    continue;
                }

                if (breadcrumbPathEvaluations++ >= BreadcrumbReachabilityPathBudget)
                {
                    break;
                }
                StrictPathResult nodePath = CalculateStrictPath(bot.Position, operationalNodeTarget);
                bool reachable =
                    nodePath.StrictComplete &&
                    nodePath.PathLength <= Mathf.Max(
                        nodeDirect * BreadcrumbReachableRatioThreshold,
                        nodeDirect + BreadcrumbReachableExtraDistance);
                if (!reachable)
                {
                    continue;
                }

                BreadcrumbFollowCommitments[profileId] = new BreadcrumbFollowCommitment
                {
                    TargetSequence = node.Sequence,
                    LastReachedSequence = node.Sequence - 1,
                    ExpiresAt = Time.time + BreadcrumbFollowCommitmentSeconds,
                    LastProgressAt = Time.time,
                    LastDistance = nodeDirect
                };

                target = operationalNodeTarget;
                breadcrumbTargetSequence = node.Sequence;
                WriteEvent("followBreadcrumbCommitLatched", bot, new
                {
                    targetSequence = node.Sequence,
                    target = Vec(operationalNodeTarget),
                    rawTarget = Vec(node.Position),
                    nodeAge = age,
                    leaderDirectDistance = directDistance,
                    leaderPathLength = leaderPath.PathLength,
                    suddenInflation,
                    longRangeRescue = directDistance > BreadcrumbFollowMaxBotDistance,
                    routeCount = BreadcrumbRoute.Count
                });
                return true;
            }

            WriteEvent("followBreadcrumbNoReachableAnchor", bot, new
            {
                leaderDirectDistance = directDistance,
                leaderPathLength = leaderPath.PathLength,
                leaderStrictComplete = leaderPath.StrictComplete,
                suddenInflation,
                routeCount = BreadcrumbRoute.Count
            });
            return false;
        }

        private static bool TryUseBreadcrumbFollowCommitment(
            BotOwner bot,
            Vector3 leaderPosition,
            out Vector3 target,
            out int breadcrumbTargetSequence)
        {
            target = default;
            breadcrumbTargetSequence = 0;

            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !BreadcrumbFollowCommitments.TryGetValue(profileId, out BreadcrumbFollowCommitment commitment))
            {
                return false;
            }

            if (FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor routeCursor) &&
                routeCursor != null && commitment.TargetSequence <= routeCursor.ConsumedBreadcrumbSequence)
            {
                BreadcrumbFollowCommitments.Remove(profileId);
                WriteEvent("followBreadcrumbCommitReleased", bot, new
                {
                    reason = "consumedByTraversal",
                    targetSequence = commitment.TargetSequence,
                    consumedThrough = routeCursor.ConsumedBreadcrumbSequence
                });
                return false;
            }

            if (Time.time > commitment.ExpiresAt)
            {
                BreadcrumbFollowCommitments.Remove(profileId);
                WriteEvent("followBreadcrumbCommitReleased", bot, new
                {
                    reason = "expired",
                    targetSequence = commitment.TargetSequence
                });
                return false;
            }

            int index = BreadcrumbRoute.FindIndex(node => node.Sequence == commitment.TargetSequence);
            if (index < 0)
            {
                BreadcrumbFollowCommitments.Remove(profileId);
                WriteEvent("followBreadcrumbCommitReleased", bot, new
                {
                    reason = "targetPruned",
                    targetSequence = commitment.TargetSequence
                });
                return false;
            }

            PlayerBreadcrumbNode node = BreadcrumbRoute[index];
            if (!IsOperationalBreadcrumbNode(node))
            {
                BreadcrumbFollowCommitments.Remove(profileId);
                WriteEvent("followBreadcrumbCommitReleased", bot, new
                {
                    reason = "transientTraversalTarget",
                    targetSequence = commitment.TargetSequence,
                    state = node.State,
                    grounded = node.Grounded
                });
                return false;
            }

            if (IsPostTraversalEntryBreadcrumbBlocked(bot, node.Position, out Vector3 blockedEntry, out Vector3 blockedExit))
            {
                BreadcrumbFollowCommitments.Remove(profileId);
                WriteEvent("followBreadcrumbEntrySideRejected", bot, new
                {
                    targetSequence = node.Sequence,
                    target = Vec(node.Position),
                    entry = Vec(blockedEntry),
                    exit = Vec(blockedExit),
                    reason = "postTraversalEntryQuarantine"
                });
                return false;
            }

            Vector3 operationalTarget = GetOperationalBreadcrumbTarget(node);
            float distance = Vector3.Distance(bot.Position, operationalTarget);
            if (distance + 0.20f < commitment.LastDistance)
            {
                commitment.LastDistance = distance;
                commitment.LastProgressAt = Time.time;
                BreadcrumbFollowCommitments[profileId] = commitment;
            }

            if (distance <= BreadcrumbFollowReachDistance)
            {
                commitment.LastReachedSequence = node.Sequence;
                commitment.LastProgressAt = Time.time;

                // Advance along the actual route the player walked. Skip tiny adjacent breadcrumbs
                // so the follower does not micro-stop every 0.5m.
                int nextIndex = index + 1;
                while (nextIndex < BreadcrumbRoute.Count &&
                       (!IsOperationalBreadcrumbNode(BreadcrumbRoute[nextIndex]) ||
                        Vector3.Distance(node.Position, BreadcrumbRoute[nextIndex].Position) < 0.65f))
                {
                    nextIndex++;
                }

                if (nextIndex >= BreadcrumbRoute.Count)
                {
                    BreadcrumbFollowCommitments.Remove(profileId);
                    WriteEvent("followBreadcrumbCommitReleased", bot, new
                    {
                        reason = "caughtUpToNewestBreadcrumb",
                        targetSequence = node.Sequence,
                        leaderDistance = Vector3.Distance(bot.Position, leaderPosition)
                    });
                    return false;
                }

                PlayerBreadcrumbNode next = BreadcrumbRoute[nextIndex];
                Vector3 nextOperationalTarget = GetOperationalBreadcrumbTarget(next);
                float nextDirect = Vector3.Distance(bot.Position, nextOperationalTarget);
                StrictPathResult nextPath = next.NavMeshSampled
                    ? CalculateStrictPath(bot.Position, nextOperationalTarget)
                    : CalculateStrictPath(bot.Position, next.Position);
                bool gap = IsSuspiciousBreadcrumbGap(nextDirect, nextPath);
                if (gap)
                {
                    // A breadcrumb gap is already proof that the player's actual route crossed a local
                    // NavMesh discontinuity. Do not require the *current* Bot->leader route to remain
                    // suspicious as well: by the time the player has moved farther away it may be a
                    // perfectly normal route on the far-side island, which previously left the follower
                    // parked forever on the last reachable breadcrumb. Match the gap directly to a
                    // learned Jump/Vault/Climb edge and hand ownership to that edge on the next tick.
                    bool traversalLatched = TryLatchLearnedTraversalForBreadcrumbGap(bot, node, next, out int traversalEdgeId);
                    WriteEvent("followBreadcrumbTraversalGap", bot, new
                    {
                        fromSequence = node.Sequence,
                        toSequence = next.Sequence,
                        from = Vec(node.Position),
                        to = Vec(next.Position),
                        directDistance = nextDirect,
                        pathLength = nextPath.PathLength,
                        strictComplete = nextPath.StrictComplete,
                        traversalLatched,
                        traversalEdgeId
                    });

                    if (!traversalLatched)
                    {
                        // V1.3.7 gap quarantine: never release/re-latch the same unresolved seam on
                        // every Follow tick. Hold the last reachable anchor while WalkThrough learning
                        // catches up, or skip the bad anchor if a later player breadcrumb is reachable.
                        if (TryResolveQuarantinedBreadcrumbGap(
                                bot,
                                profileId,
                                node,
                                next,
                                nextIndex,
                                ref commitment,
                                out target,
                                out breadcrumbTargetSequence))
                        {
                            BreadcrumbFollowCommitments[profileId] = commitment;
                            return true;
                        }

                        // The quarantine resolver always owns unresolved gaps. Reaching this branch
                        // means the route was pruned underneath us; let the main resolver rebuild once.
                        BreadcrumbFollowCommitments.Remove(profileId);
                        return false;
                    }

                    BreadcrumbGapQuarantines.Remove(profileId);
                    target = node.Position;
                    breadcrumbTargetSequence = node.Sequence;
                    commitment.ExpiresAt = Time.time + BreadcrumbFollowCommitmentSeconds;
                    commitment.LastProgressAt = Time.time;
                    commitment.LastDistance = 0f;
                    BreadcrumbFollowCommitments[profileId] = commitment;
                    return true;
                }

                commitment.TargetSequence = next.Sequence;
                commitment.ExpiresAt = Time.time + BreadcrumbFollowCommitmentSeconds;
                node = next;
                operationalTarget = GetOperationalBreadcrumbTarget(node);
                distance = Vector3.Distance(bot.Position, operationalTarget);
                commitment.LastDistance = distance;
                commitment.LastProgressAt = Time.time;
                BreadcrumbFollowCommitments[profileId] = commitment;
                WriteEvent("followBreadcrumbAdvanced", bot, new
                {
                    targetSequence = node.Sequence,
                    target = Vec(node.Position),
                    targetDistance = distance
                });
            }
            else if (Time.time - commitment.LastProgressAt > 6f)
            {
                // Let the main resolver rebuild from a newer reachable anchor if the chosen
                // breadcrumb itself stopped producing progress.
                BreadcrumbFollowCommitments.Remove(profileId);
                WriteEvent("followBreadcrumbCommitReleased", bot, new
                {
                    reason = "noProgressWatchdog",
                    targetSequence = commitment.TargetSequence,
                    targetDistance = distance
                });
                return false;
            }

            target = operationalTarget;
            breadcrumbTargetSequence = node.Sequence;
            WriteEvent("followBreadcrumbCommitReused", bot, new
            {
                targetSequence = node.Sequence,
                target = Vec(operationalTarget),
                rawTarget = Vec(node.Position),
                targetDistance = distance,
                expiresIn = Mathf.Max(0f, commitment.ExpiresAt - Time.time)
            });
            return true;
        }

        private static bool IsBreadcrumbGapAnchorQuarantined(string profileId, Vector3 position)
        {
            if (string.IsNullOrEmpty(profileId) ||
                !BreadcrumbGapQuarantines.TryGetValue(profileId, out BreadcrumbGapQuarantine quarantine))
            {
                return false;
            }

            if (Time.time > quarantine.ExpiresAt)
            {
                BreadcrumbGapQuarantines.Remove(profileId);
                return false;
            }

            // V1.3.9 quarantines the physical barrier region, not one sequence id. Adjacent
            // breadcrumbs (#606 then #605) on the same wall must not recreate the same gap loop.
            return GetPlanarDistance(position, quarantine.Center) <= quarantine.Radius;
        }

        private static bool TryResolveQuarantinedBreadcrumbGap(
            BotOwner bot,
            string profileId,
            PlayerBreadcrumbNode from,
            PlayerBreadcrumbNode to,
            int toIndex,
            ref BreadcrumbFollowCommitment commitment,
            out Vector3 target,
            out int breadcrumbTargetSequence)
        {
            target = from?.Position ?? bot?.Position ?? Vector3.zero;
            breadcrumbTargetSequence = from?.Sequence ?? 0;
            if (bot == null || from == null || to == null || string.IsNullOrEmpty(profileId))
            {
                return false;
            }

            Vector3 gapCenter = Vector3.Lerp(from.Position, to.Position, 0.5f);
            bool sameQuarantine = BreadcrumbGapQuarantines.TryGetValue(profileId, out BreadcrumbGapQuarantine quarantine) &&
                                  GetPlanarDistance(gapCenter, quarantine.Center) <= quarantine.Radius &&
                                  Time.time <= quarantine.ExpiresAt;
            if (!sameQuarantine)
            {
                quarantine = new BreadcrumbGapQuarantine
                {
                    FromSequence = from.Sequence,
                    ToSequence = to.Sequence,
                    Center = gapCenter,
                    Radius = BreadcrumbGapSpatialQuarantineRadius,
                    CreatedAt = Time.time,
                    ExpiresAt = Time.time + BreadcrumbGapQuarantineSeconds,
                    NextDiagnosticAt = 0f
                };
                BreadcrumbGapQuarantines[profileId] = quarantine;
                WriteEvent("followBreadcrumbGapQuarantined", bot, new
                {
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    from = Vec(from.Position),
                    to = Vec(to.Position),
                    center = Vec(gapCenter),
                    radius = quarantine.Radius,
                    quarantineSeconds = BreadcrumbGapQuarantineSeconds
                });
            }

            // V1.3.22: follower-side gap handling is diagnostic/consumption only. The authoritative
            // player traversal stream owns WalkThrough learning and coalesces adjacent gaps into one
            // corridor episode. Never persist a new micro-edge here, otherwise a fast corridor is
            // fragmented again into one edge per breadcrumb pair.
            if (TryLatchLearnedTraversalForBreadcrumbGap(bot, from, to, out int traversalEdgeId))
            {
                BreadcrumbGapQuarantines.Remove(profileId);
                BreadcrumbBarrierDetourUntil.Remove(profileId);
                commitment.ExpiresAt = Time.time + BreadcrumbFollowCommitmentSeconds;
                commitment.LastProgressAt = Time.time;
                commitment.LastDistance = 0f;
                WriteEvent("followBreadcrumbGapQuarantineResolvedTraversal", bot, new
                {
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    traversalEdgeId
                });
                return true;
            }

            // V3.56: the producer sees adjacent breadcrumbs, while the follower deliberately
            // compacts sub-0.65m nodes. That means the consumer can discover a real NavMesh seam
            // spanning multiple player samples which no adjacent producer pair ever classified.
            // Compile that seam into a runtime-only PhysicalCorridor and immediately retry the
            // ordinary traversal latch. This is route truth, not WalkThrough semantic persistence.
            if (TryCaptureLearningV356RuntimePhysicalCorridorFromBreadcrumbGap(
                    bot, from, to, out int backfilledEdgeId) &&
                TryLatchLearnedTraversalForBreadcrumbGap(
                    bot, from, to, out int backfilledTraversalEdgeId))
            {
                BreadcrumbGapQuarantines.Remove(profileId);
                BreadcrumbBarrierDetourUntil.Remove(profileId);
                commitment.ExpiresAt = Time.time + BreadcrumbFollowCommitmentSeconds;
                commitment.LastProgressAt = Time.time;
                commitment.LastDistance = 0f;
                WriteEvent("learningV356ConsumerGapBackfillLatched", bot, new
                {
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    capturedEdgeId = backfilledEdgeId,
                    traversalEdgeId = backfilledTraversalEdgeId,
                    action = "consumerAndProducerNowShareOneExecutablePhysicalRouteFact"
                });
                return true;
            }

            if (TryFindReachableBreadcrumbAfterGap(bot, toIndex + 1, out PlayerBreadcrumbNode skipTarget))
            {
                // Keep the spatial barrier quarantine alive even after finding a later reachable
                // node so the main resolver cannot immediately select an adjacent entry anchor.
                commitment.TargetSequence = skipTarget.Sequence;
                commitment.ExpiresAt = Time.time + BreadcrumbFollowCommitmentSeconds;
                commitment.LastProgressAt = Time.time;
                commitment.LastDistance = Vector3.Distance(bot.Position, skipTarget.Position);
                target = skipTarget.Position;
                breadcrumbTargetSequence = skipTarget.Sequence;
                WriteEvent("followBreadcrumbGapQuarantineSkipped", bot, new
                {
                    fromSequence = from.Sequence,
                    blockedSequence = to.Sequence,
                    skippedToSequence = skipTarget.Sequence,
                    target = Vec(skipTarget.Position),
                    targetDistance = commitment.LastDistance
                });
                return true;
            }

            // Quarantine prevents release/re-latch loops, but it must not become a new permanent
            // stop state. After a short resolver window, release this commitment while keeping the
            // broken FromSequence quarantined so normal Follow can take a detour or another anchor.
            if (Time.time - quarantine.CreatedAt >= BreadcrumbGapHoldBeforeBypassSeconds)
            {
                BreadcrumbBarrierDetourUntil[profileId] = Time.time + BreadcrumbBarrierDetourSeconds;
                BreadcrumbFollowCommitments.Remove(profileId);
                WriteEvent("followBreadcrumbGapQuarantineBypass", bot, new
                {
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    heldSeconds = Time.time - quarantine.CreatedAt,
                    quarantineRemaining = Mathf.Max(0f, quarantine.ExpiresAt - Time.time),
                    detourSeconds = BreadcrumbBarrierDetourSeconds
                });
                return false;
            }

            commitment.TargetSequence = from.Sequence;
            commitment.ExpiresAt = Mathf.Max(commitment.ExpiresAt, Time.time + BreadcrumbGapQuarantineSeconds);
            commitment.LastProgressAt = Time.time;
            commitment.LastDistance = Vector3.Distance(bot.Position, from.Position);
            target = from.Position;
            breadcrumbTargetSequence = from.Sequence;

            if (Time.time >= quarantine.NextDiagnosticAt)
            {
                quarantine.NextDiagnosticAt = Time.time + BreadcrumbGapDiagnosticInterval;
                BreadcrumbGapQuarantines[profileId] = quarantine;
                WriteEvent("followBreadcrumbGapQuarantineHolding", bot, new
                {
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    hold = Vec(from.Position),
                    expiresIn = Mathf.Max(0f, quarantine.ExpiresAt - Time.time)
                });
            }
            return true;
        }


        private static bool TryFindCheapLocalWalkThroughBypass(
            Vector3 from,
            Vector3 to,
            out float bypassCost,
            out Vector3 bypassStart,
            out Vector3 bypassEnd,
            out float shoulderOffset)
        {
            bypassCost = float.MaxValue;
            bypassStart = default;
            bypassEnd = default;
            shoulderOffset = 0f;
            if (!IsFinite(from) || !IsFinite(to))
            {
                return false;
            }

            float direct = GetPlanarDistance(from, to);
            if (direct < 0.20f || direct > WalkThroughLocalBypassMaxCandidateDistance)
            {
                return false;
            }

            Vector3 direction = GetFlatDirection(to - from);
            if (direction.sqrMagnitude < 0.5f)
            {
                return false;
            }
            Vector3 right = Vector3.Cross(Vector3.up, direction).normalized;
            float localStep = WalkThroughLocalBypassShoulderDistance * 0.55f;
            List<Vector3> localOffsets = new List<Vector3>
            {
                Vector3.zero,
                right * localStep,
                -right * localStep,
                right * WalkThroughLocalBypassShoulderDistance,
                -right * WalkThroughLocalBypassShoulderDistance
            };
            if (true)
            {
                // Same existing 0.605m local scale, now probing fore/aft and diagonal truth as well.
                // This closes the "normal NavMesh exists ~0.5m away" hole without widening the
                // 0.65m SamplePosition radius or the 0.85m persistence threshold.
                localOffsets.Add(direction * localStep);
                localOffsets.Add(-direction * localStep);
                localOffsets.Add((direction + right).normalized * localStep);
                localOffsets.Add((direction - right).normalized * localStep);
                localOffsets.Add((-direction + right).normalized * localStep);
                localOffsets.Add((-direction - right).normalized * localStep);
            }

            // "Nearby bypass" must remain genuinely local. For a 0.5 m pothole, a 3.5 m
            // NavMesh loop is not cheap just because the absolute +3 m cap allows it; conversely a
            // ~1 m shoulder around the hole is preferable to inventing a traversal. Use a small
            // minimum absolute allowance, then tighten long candidates with the +3 m ceiling.
            float allowed = Mathf.Min(
                direct + WalkThroughLocalBypassExtraDistance,
                Mathf.Max(
                    direct + WalkThroughLocalBypassMinimumExtraDistance,
                    direct * WalkThroughLocalBypassRatio));
            bool found = false;
            foreach (Vector3 localOffset in localOffsets)
            {
                Vector3 requestedStart = from + localOffset;
                Vector3 requestedEnd = to + localOffset;
                if (!NavMesh.SamplePosition(
                        requestedStart,
                        out NavMeshHit startHit,
                        WalkThroughLocalBypassSampleRadius,
                        NavMesh.AllAreas) ||
                    !NavMesh.SamplePosition(
                        requestedEnd,
                        out NavMeshHit endHit,
                        WalkThroughLocalBypassSampleRadius,
                        NavMesh.AllAreas))
                {
                    continue;
                }

                if (Mathf.Abs(startHit.position.y - requestedStart.y) > 1.10f ||
                    Mathf.Abs(endHit.position.y - requestedEnd.y) > 1.10f)
                {
                    continue;
                }

                StrictPathResult path = CalculateStrictPath(startHit.position, endHit.position);
                if (!path.StrictComplete)
                {
                    continue;
                }

                float total = path.PathLength +
                              GetPlanarDistance(from, startHit.position) +
                              GetPlanarDistance(to, endHit.position);
                if (total > allowed)
                {
                    continue;
                }

                if (!found || total < bypassCost)
                {
                    found = true;
                    bypassCost = total;
                    bypassStart = startHit.position;
                    bypassEnd = endHit.position;
                    shoulderOffset = Vector3.Dot(localOffset, right);
                }
            }

            return found;
        }

        private static bool ShouldOverrideCheapLocalWalkThroughBypassForFollowers(
            Vector3 playerFrom,
            Vector3 playerTo,
            BotOwner focusBot,
            out string followerProfileId,
            out float followerDirectDistance,
            out float followerPathLength,
            out float followerDetourRatio)
        {
            followerProfileId = string.Empty;
            followerDirectDistance = 0f;
            followerPathLength = 0f;
            followerDetourRatio = 0f;

            List<BotOwner> candidates = new List<BotOwner>();
            if (IsLiveBot(focusBot) && BossPlayers.IsFollower(focusBot))
            {
                candidates.Add(focusBot);
            }
            else
            {
                Player leader = FollowerEnvironment.LocalPlayer;
                if (IsLivePlayer(leader))
                {
                    List<BotFollowerPlayer> followers = BossPlayers.GetFollowersByBoss(leader.ProfileId);
                    if (followers != null)
                    {
                        foreach (BotFollowerPlayer follower in followers)
                        {
                            BotOwner owner = follower?.GetBot();
                            if (IsLiveBot(owner) && BossPlayers.IsFollower(owner))
                            {
                                candidates.Add(owner);
                            }
                        }
                    }
                }
            }

            float bestRatio = 0f;
            foreach (BotOwner candidate in candidates)
            {
                float direct = GetPlanarDistance(candidate.Position, playerTo);
                if (direct < 0.25f || direct > WalkThroughFollowerUtilityOverrideMaxDirectDistance)
                {
                    continue;
                }

                StrictPathResult path = CalculateStrictPath(candidate.Position, playerTo);
                if (!path.StrictComplete || path.PathLength <= 0f)
                {
                    continue;
                }

                float ratio = path.PathLength / Mathf.Max(0.25f, direct);
                float extra = path.PathLength - direct;
                if (ratio > bestRatio)
                {
                    bestRatio = ratio;
                    followerProfileId = candidate.ProfileId ?? string.Empty;
                    followerDirectDistance = direct;
                    followerPathLength = path.PathLength;
                    followerDetourRatio = ratio;
                }

                bool legacyHighCostOverride =
                    ratio >= WalkThroughFollowerUtilityOverrideMinDetourRatio &&
                    extra >= WalkThroughFollowerUtilityOverrideMinExtraPath;
                bool learningV388GlobalSuspiciousFollowerRoute =
                    (IsSuspiciousFollowPath(direct, path));
                if (legacyHighCostOverride || learningV388GlobalSuspiciousFollowerRoute)
                {
                    if (learningV388GlobalSuspiciousFollowerRoute &&
                        ShouldEmitDiagnostic(
                            "learningV388FollowerExecutionUtilityOverridesLocalSemanticBypass:" +
                            (candidate.ProfileId ?? string.Empty), candidate, 0.35f))
                    {
                        WriteEvent("learningV388FollowerExecutionUtilityOverridesLocalSemanticBypass", candidate, new
                        {
                            followerProfileId = candidate.ProfileId ?? string.Empty,
                            followerDirectDistance = direct,
                            followerPathLength = path.PathLength,
                            followerDetourRatio = ratio,
                            followerExtraPath = extra,
                            suspiciousRatioThreshold = FollowDetourRatioThreshold,
                            suspiciousExtraDistanceThreshold = FollowDetourExtraDistanceThreshold,
                            legacyHighCostOverride,
                            persistentLearningChanged = false,
                            traversalSuccessRecorded = false,
                            action = "reuseGlobalSuspiciousFollowPathContractToPreservePlayerProvenPassageExecution"
                        });
                    }
                    return true;
                }
            }

            return false;
        }

        private static bool TryCaptureLearningV356RuntimePhysicalCorridorFromBreadcrumbGap(
            BotOwner bot,
            PlayerBreadcrumbNode from,
            PlayerBreadcrumbNode to,
            out int edgeId)
        {
            edgeId = 0;
            if ((bot == null) ||
                from == null || to == null || from.Sequence <= 0 || to.Sequence <= from.Sequence ||
                !IsFinite(from.Position) || !IsFinite(to.Position))
            {
                return false;
            }

            float direct = GetPlanarDistance(from.Position, to.Position);
            float vertical = Mathf.Abs(from.Position.y - to.Position.y);
            if (direct < WalkThroughCandidateMinDistance ||
                direct > WalkThroughMaxExecutionDistance ||
                vertical > WalkThroughMaxVerticalDelta)
            {
                return false;
            }

            List<PlayerBreadcrumbNode> corridor = BreadcrumbRoute
                .Where(node => node != null &&
                               node.Sequence >= from.Sequence &&
                               node.Sequence <= to.Sequence &&
                               IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            if (corridor.Count < 2)
            {
                corridor = new List<PlayerBreadcrumbNode> { from, to };
            }

            // A consumer-compacted seam is only allowed to backfill "there is a traversable
            // physical corridor". Never guess an actuator. If the original player stream contains
            // an explicit traversal state or a typed episode already overlaps this sequence range,
            // the typed learner remains authoritative.
            if (corridor.Any(node => IsTraversalStateName(node.State)))
            {
                return false;
            }
            TraversalEpisodeMetadata typedOverlap = TraversalEpisodeStream
                .Where(item => item != null &&
                               item.EndBreadcrumbSequence >= from.Sequence &&
                               item.StartBreadcrumbSequence <= to.Sequence &&
                               !string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                .OrderByDescending(item => item.EpisodeId)
                .FirstOrDefault();
            if (typedOverlap != null)
            {
                WriteEvent("learningV356ConsumerGapBackfillDeferredToTypedEpisode", bot, new
                {
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    typedEpisodeId = typedOverlap.EpisodeId,
                    typedEdgeId = typedOverlap.EdgeId,
                    typedKind = typedOverlap.Kind,
                    action = "doNotGuessActuatorFromConsumerCompaction"
                });
                return false;
            }

            StrictPathResult learningV369CorridorPath = CalculateStrictPath(from.Position, to.Position);
            if (IsLearningV369OrdinaryNavMeshRouteWindow(corridor, learningV369CorridorPath))
            {
                WriteEvent("learningV369ConsumerGapOrdinaryNavMeshNotPromoted", bot, new
                {
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    sampleCount = corridor.Count,
                    strictPathLength = learningV369CorridorPath.PathLength,
                    persistentLearningChanged = false,
                    action = "consumerGapUsesOrdinaryNavMeshInsteadOfSyntheticTraversal"
                });
                return false;
            }

            // Reuse an already-created runtime corridor for the exact consumer seam so quarantine
            // retries cannot fragment one doorway/threshold into a new edge every tick.
            foreach (TraversalEpisodeMetadata existingEpisode in TraversalEpisodeStream
                .Where(item => item != null &&
                               item.StartBreadcrumbSequence == from.Sequence &&
                               item.EndBreadcrumbSequence == to.Sequence)
                .OrderByDescending(item => item.EpisodeId))
            {
                LearnedTraversalEdge existingEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == existingEpisode.EdgeId &&
                    candidate.SyntheticPhysicalCorridor);
                if (existingEdge != null)
                {
                    edgeId = existingEdge.Id;
                    return true;
                }
            }

            LearnedTraversalEdge synthetic = new LearnedTraversalEdge
            {
                Id = ++learnedTraversalEdgeSequence,
                ExperienceKey = null,
                DemonstrationRevision = 1,
                Kind = ("PhysicalCorridor"),
                // Runtime-only consumer seam remains PhysicalCorridor at both semantic and route layers.
                A = from.Position,
                B = to.Position,
                RawStart = from.Position,
                RawEnd = to.Position,
                CreatedAt = Time.time,
                PlayerValidated = true,
                Verified = false,
                Disabled = false,
                SyntheticPhysicalCorridor = true,
                RuntimeSemanticKind = "PhysicalCorridor",
                ApproachDirection = GetFlatDirection(to.Position - from.Position),
                ApproachSpeed = GetLearningV381PhysicalCorridorApproachSpeed(corridor),
                ApproachMode = GetLearningV381PhysicalCorridorApproachMode(corridor),
                WalkThroughCorridorSamples = corridor
                    .Select(node => node.Position)
                    .Where(IsFinite)
                    .ToList(),
                EgressSamples = new List<Vector3>()
            };
            LearnedTraversalEdges.Add(synthetic);
            TrimLearnedTraversalEdgesToLimit();

            TraversalEpisodeMetadata metadata = RegisterTraversalEpisodeForEdge(
                synthetic.Id,
                ("PhysicalCorridor"),
                from.Position,
                to.Position,
                from.Sequence,
                to.Sequence,
                allowChain: false,
                preferredEpisodeId: 0,
                skipPreGapEmission: true);
            edgeId = synthetic.Id;
            WriteEvent("learningV356ConsumerGapPhysicalCorridorCaptured", bot, new
            {
                edgeId,
                episodeId = metadata?.EpisodeId ?? 0,
                fromSequence = from.Sequence,
                toSequence = to.Sequence,
                start = Vec(from.Position),
                end = Vec(to.Position),
                directDistance = direct,
                verticalDelta = to.Position.y - from.Position.y,
                sampleCount = corridor.Count,
                approachSpeed = synthetic.ApproachSpeed,
                approachMode = synthetic.ApproachMode,
                semanticKind = "PhysicalCorridor",
                executorKind = ("PhysicalCorridor"),
                persistent = false,
                action = "compileConsumerCompactedGapIntoRuntimePhysicalRouteFact"
            });
            return true;
        }

        private static bool TryLearnWalkThroughEdgeFromBreadcrumbGap(
            BotOwner bot,
            PlayerBreadcrumbNode from,
            PlayerBreadcrumbNode to,
            out int edgeId)
        {
            edgeId = 0;
            if (bot?.GetPlayer?.MovementContext == null || from == null || to == null ||
                IsTraversalStateName(from.State) || IsTraversalStateName(to.State))
            {
                return false;
            }

            float direct = Vector3.Distance(from.Position, to.Position);
            float vertical = Mathf.Abs(from.Position.y - to.Position.y);
            if (direct < WalkThroughCandidateMinDistance ||
                direct > WalkThroughMaxExecutionDistance ||
                vertical > WalkThroughMaxVerticalDelta)
            {
                return false;
            }

            if (TryFindCheapLocalWalkThroughBypass(
                    from.Position,
                    to.Position,
                    out float bypassCost,
                    out Vector3 bypassStart,
                    out Vector3 bypassEnd,
                    out float bypassShoulder))
            {
                bool followerUtilityOverride = ShouldOverrideCheapLocalWalkThroughBypassForFollowers(
                    from.Position, to.Position, bot,
                    out string utilityFollowerProfileId,
                    out float utilityDirectDistance,
                    out float utilityPathLength,
                    out float utilityDetourRatio);
                LearnedTraversalEdge historicalSemantic = FindLearningV344HistoricalWalkThroughMatch(
                    from.Position, to.Position);
                if (historicalSemantic != null)
                {
                    edgeId = historicalSemantic.Id;
                    RegisterTraversalEpisodeForEdge(
                        historicalSemantic.Id, "WalkThrough", from.Position, to.Position,
                        from.Sequence, to.Sequence, allowChain: true);
                    WriteEvent("learningV345HistoricalWalkThroughBreadcrumbGapAdmitted", bot, new
                    {
                        edgeId = historicalSemantic.Id,
                        experienceKey = historicalSemantic.ExperienceKey,
                        fromSequence = from.Sequence,
                        toSequence = to.Sequence,
                        localBypassCost = bypassCost,
                        action = "historicalEmpiricalTruthOwnsTraversalAdmission"
                    });
                    return true;
                }
                if ((!followerUtilityOverride))
                {
                    WriteEvent("learningV318WalkThroughLocalBypassAuthoritySuppressed", bot, new
                    {
                        source = "breadcrumbGap",
                        fromSequence = from.Sequence,
                        toSequence = to.Sequence,
                        start = Vec(from.Position),
                        end = Vec(to.Position),
                        directDistance = direct,
                        localBypassCost = bypassCost,
                        bypassStart = Vec(bypassStart),
                        bypassEnd = Vec(bypassEnd),
                        shoulderOffset = bypassShoulder,
                        followerProfileId = utilityFollowerProfileId,
                        followerDirectDistance = utilityDirectDistance,
                        followerPathLength = utilityPathLength,
                        followerDetourRatio = utilityDetourRatio,
                        reason = "cheapLocalNavMeshBypassOwnsLocalSemanticTruth"
                    });
                    return false;
                }
                WriteEvent("learningV345FollowerUtilityOverridesCheapLocalWalkThroughBypass", bot, new
                {
                    source = "breadcrumbGap",
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    followerProfileId = utilityFollowerProfileId,
                    followerDirectDistance = utilityDirectDistance,
                    followerPathLength = utilityPathLength,
                    followerDetourRatio = utilityDetourRatio,
                    action = "followerRouteRequiresPlayerProvenPassage"
                });
            }

            // The local player already proved this short seam is traversable. Corridor/floor
            // probes are diagnostic only in V1.3.14 because slopes and uneven thresholds can make
            // IsGrounded/floor samples flicker even while the player walks through normally.
            bool corridorAdvisory = TryValidateWalkThroughCorridor(
                bot.GetPlayer,
                from.Position,
                to.Position,
                out string corridorFailure,
                out string blocker);

            edgeId = RememberLearnedTraversalEdge(from.Position, to.Position, "WalkThrough", true);
            if (edgeId <= 0)
            {
                return false;
            }

            WriteEvent("followBreadcrumbGapWalkThroughLearned", bot, new
            {
                edgeId,
                fromSequence = from.Sequence,
                toSequence = to.Sequence,
                start = Vec(from.Position),
                end = Vec(to.Position),
                directDistance = direct,
                corridorAdvisory,
                corridorFailure,
                blocker
            });
            return true;
        }

        private static bool TryFindReachableBreadcrumbAfterGap(
            BotOwner bot,
            int startIndex,
            out PlayerBreadcrumbNode reachable)
        {
            reachable = null;
            if (bot == null)
            {
                return false;
            }

            for (int index = Mathf.Max(0, startIndex); index < BreadcrumbRoute.Count; index++)
            {
                PlayerBreadcrumbNode candidate = BreadcrumbRoute[index];
                if (!IsOperationalBreadcrumbNode(candidate))
                {
                    continue;
                }

                if (IsPostTraversalEntryBreadcrumbBlocked(bot, candidate.Position, out _, out _))
                {
                    continue;
                }

                if (IsBreadcrumbGapAnchorQuarantined(bot.ProfileId ?? string.Empty, candidate.Position))
                {
                    continue;
                }

                float direct = Vector3.Distance(bot.Position, candidate.Position);
                if (direct > 10f)
                {
                    continue;
                }

                StrictPathResult path = CalculateStrictPath(bot.Position, candidate.Position);
                bool reachablePath = path.StrictComplete &&
                                     path.PathLength <= Mathf.Max(
                                         direct * BreadcrumbReachableRatioThreshold,
                                         direct + BreadcrumbReachableExtraDistance);
                if (!reachablePath)
                {
                    continue;
                }

                reachable = candidate;
                return true;
            }
            return false;
        }

        private static bool TryLatchLearnedTraversalForBreadcrumbGap(
            BotOwner bot,
            PlayerBreadcrumbNode from,
            PlayerBreadcrumbNode to,
            out int edgeId)
        {
            edgeId = 0;
            if (bot == null || from == null || to == null || LearnedTraversalEdges.Count == 0)
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return false;
            }

            LearnedTraversalEdge bestEdge = null;
            Vector3 bestEntry = default;
            Vector3 bestExit = default;
            float bestScore = float.MaxValue;

            // The player's breadcrumb endpoints are much stronger evidence than the current leader
            // position. Match either orientation, but require both learned-edge endpoints to be local
            // to the actual gap so an old nearby fence cannot hijack an unrelated route.
            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (!IsTraversalEdgeTopologicallySelectableForFollower(bot, edge, out _))
                {
                    continue;
                }
                if (IsTraversalEpisodeAlreadyConsumed(bot, edge))
                {
                    continue;
                }
                if (IsRecentTraversalRelatchBlocked(bot, edge, out _))
                {
                    continue;
                }
                if (string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                    IsFollowerAlreadyBelowDropDownLanding(bot.Position, edge.RawStart, edge.RawEnd, edge.B))
                {
                    continue;
                }
                float forwardEntry = Vector3.Distance(from.Position, edge.A);
                float forwardExit = Vector3.Distance(to.Position, edge.B);
                float reverseEntry = Vector3.Distance(from.Position, edge.B);
                float reverseExit = Vector3.Distance(to.Position, edge.A);

                // For a grounded breadcrumb gap, prefer a local WalkThrough edge when scores are
                // otherwise similar; Jump/Vault/Climb still win when they are a materially better fit.
                float kindBias = string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ? -0.35f : 0f;
                float experienceBias = GetTraversalExperienceSelectionAdjustment(edge);
                float forwardSemanticBias = GetTraversalSemanticSelectionAdjustment(edge, edge.A, edge.B);
                float reverseSemanticBias = GetTraversalSemanticSelectionAdjustment(edge, edge.B, edge.A);
                float forwardScore = forwardEntry + forwardExit + kindBias + experienceBias + forwardSemanticBias;
                float reverseScore = reverseEntry + reverseExit + kindBias + experienceBias + reverseSemanticBias;
                bool forwardLocal = IsTraversalOrientationAllowed(edge, edge.A, edge.B) &&
                                    forwardEntry <= 2.25f && forwardExit <= 2.25f;
                bool reverseLocal = IsTraversalOrientationAllowed(edge, edge.B, edge.A) &&
                                    reverseEntry <= 2.25f && reverseExit <= 2.25f;

                if (forwardLocal && forwardScore < bestScore)
                {
                    bestEdge = edge;
                    bestEntry = edge.A;
                    bestExit = edge.B;
                    bestScore = forwardScore;
                }

                if (reverseLocal && reverseScore < bestScore)
                {
                    bestEdge = edge;
                    bestEntry = edge.B;
                    bestExit = edge.A;
                    bestScore = reverseScore;
                }
            }

            if (bestEdge == null)
            {
                return false;
            }

            bool forwardOrientationSelected = Vector3.Distance(bestEntry, bestEdge.A) <= Vector3.Distance(bestEntry, bestEdge.B);
            LearnedTraversalCommitments[profileId] = CreateLearnedTraversalCommitment(
                bestEdge,
                bestEntry,
                bestExit,
                forwardOrientationSelected ? bestEdge.RawStart : bestEdge.RawEnd,
                forwardOrientationSelected ? bestEdge.RawEnd : bestEdge.RawStart);
            edgeId = bestEdge.Id;

            WriteEvent("followBreadcrumbGapTraversalLatched", bot, new
            {
                edgeId,
                kind = bestEdge.Kind,
                fromSequence = from.Sequence,
                toSequence = to.Sequence,
                entry = Vec(bestEntry),
                exit = Vec(bestExit),
                matchScore = bestScore
            });
            return true;
        }

        // RC107: IsSuspiciousFollowPath is owned by FollowerCapabilityFollowControlHost.

        private static bool IsSuspiciousBreadcrumbGap(float directDistance, StrictPathResult path)
        {
            if (directDistance <= 0.05f)
            {
                return false;
            }

            return !path.StrictComplete ||
                   path.PathLength >= Mathf.Max(
                       directDistance * BreadcrumbGapRatioThreshold,
                       directDistance + BreadcrumbGapExtraDistance);
        }

        // RC107: IsSuddenFollowPathInflation is owned by FollowerCapabilityFollowControlHost.

        // RC107: UpdateFollowPathBaseline is owned by FollowerCapabilityFollowControlHost.

        private static void PruneBreadcrumbRoute()
        {
            float now = Time.time;
            while (BreadcrumbRoute.Count > 0 &&
                   (BreadcrumbRoute.Count > BreadcrumbBufferLimit ||
                    now - BreadcrumbRoute[0].CreatedAt > BreadcrumbTtlSeconds))
            {
                BreadcrumbRoute.RemoveAt(0);
            }

            foreach (string profileId in BreadcrumbFollowCommitments
                .Where(pair => now > pair.Value.ExpiresAt)
                .Select(pair => pair.Key)
                .ToList())
            {
                BreadcrumbFollowCommitments.Remove(profileId);
            }

            foreach (string profileId in BreadcrumbGapQuarantines
                .Where(pair => now > pair.Value.ExpiresAt)
                .Select(pair => pair.Key)
                .ToList())
            {
                BreadcrumbGapQuarantines.Remove(profileId);
            }

            foreach (string profileId in PostTraversalEntryQuarantines
                .Where(pair => now > pair.Value.ExpiresAt)
                .Select(pair => pair.Key)
                .ToList())
            {
                PostTraversalEntryQuarantines.Remove(profileId);
            }

            foreach (string profileId in RecentTraversalCompletions
                .Where(pair => now > pair.Value.ExpiresAt)
                .Select(pair => pair.Key)
                .ToList())
            {
                RecentTraversalCompletions.Remove(profileId);
            }

            foreach (string profileId in FollowPathBaselines
                .Where(pair => now - pair.Value.SampledAt > BreadcrumbTtlSeconds)
                .Select(pair => pair.Key)
                .ToList())
            {
                FollowPathBaselines.Remove(profileId);
            }

            foreach (string profileId in FollowPathSanitySamples
                .Where(pair => pair.Value == null || now - pair.Value.SampledAt > FollowPathBaselineTtlSeconds)
                .Select(pair => pair.Key)
                .ToList())
            {
                FollowPathSanitySamples.Remove(profileId);
            }
        }

        private static bool IsTraversalStateName(string state)
        {
            if (string.IsNullOrEmpty(state))
            {
                return false;
            }

            return state.IndexOf("Jump", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   state.IndexOf("Vault", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   state.IndexOf("Climb", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   state.IndexOf("Fall", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static bool IsLocomotionResumeStateName(string state)
        {
            if (string.IsNullOrEmpty(state))
            {
                return false;
            }

            // V1.3.23: Vault Assisted replay must terminate at the first authored point where the
            // player has fully left Vault/Landing and ordinary locomotion has resumed. This is a
            // stronger semantic anchor than RawEnd, which can still be on top of / inside the
            // obstacle while EFT is transitioning out of the vault state.
            return state.IndexOf("Sprint", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   state.IndexOf("Run", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   state.IndexOf("Walk", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static bool IsOperationalBreadcrumbNode(PlayerBreadcrumbNode node)
        {
            // IsGrounded can flicker for one or two frames on slopes, curbs and uneven thresholds.
            // Traversal state is a more reliable hard exclusion: a Run/Sprint breadcrumb remains
            // operational even if the grounded flag momentarily drops.
            return node != null && !IsTraversalStateName(node.State);
        }

        private static Vector3 GetOperationalBreadcrumbTarget(PlayerBreadcrumbNode node)
        {
            if (node == null)
            {
                return Vector3.zero;
            }

            // V1.3.24: player raw positions can sit a few decimeters outside the bot NavMesh.
            // The previous resolver proved a nearby sampled point was reachable, then passed the
            // raw player position to BotOwner.GoToPoint, which could still return PathInvalid.
            return node.NavMeshSampled && IsFinite(node.NavMeshPosition)
                ? node.NavMeshPosition
                : node.Position;
        }

        public static bool TryGetLiveWalkThroughReservationTarget(
            BotOwner bot,
            Vector3 leaderPosition,
            out Vector3 target,
            out int episodeId)
        {
            target = default;
            episodeId = 0;
            if (!raidActive || !IsLiveBot(bot) || !BossPlayers.IsFollower(bot) ||
                !IsFinite(bot.Position) || !IsFinite(leaderPosition))
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return false;
            }

            // Per-follower traversal FIFO: once an earlier episode owns this follower, a newer
            // live episode may be learned globally but it must not replace the current route mission.
            // The chain preloader will promote the next episode immediately after completion.
            if (LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment activeCommitment) &&
                activeCommitment != null && Time.time <= activeCommitment.ExpiresAt)
            {
                return false;
            }

            // A live reservation outlives the short player-side builder. This is intentional:
            // the builder can close in under one second, while FollowAction historically refreshed
            // its primary route every 1-2 seconds. Keep the follower pinned to the sampled entry
            // until the finalized episode is promoted to a learned commitment (or the reservation
            // expires), instead of falling back to normal NavMesh routing during that handoff gap.
            if (ProvisionalWalkThroughReservations.TryGetValue(profileId, out ProvisionalWalkThroughReservation existing))
            {
                if (existing != null && Time.time <= existing.ExpiresAt)
                {
                    // If the player has already closed this builder, promote immediately instead
                    // of keeping the high-frequency Follow reservation parked at the entry until
                    // its timeout. The caller will consume the learned commitment on the same tick.
                    if (TryPromoteProvisionalWalkThroughReservation(bot))
                    {
                        return false;
                    }
                    if ((TryEscalateLearningV432FinalizedLiveWalkReservationAtEntry(
                            bot, existing, leaderPosition, "followReservation")))
                    {
                        return false;
                    }
                    target = existing.Entry;
                    episodeId = existing.EpisodeId;
                    return true;
                }
                ProvisionalWalkThroughReservations.Remove(profileId);
            }

            WalkThroughEpisodeBuilder episode = activeWalkThroughEpisode;
            if (episode == null || Time.time - episode.LastUpdatedAt > WalkThroughEpisodeMaxGapSeconds + 0.35f)
            {
                return false;
            }

            float leaderDistance = Vector3.Distance(bot.Position, leaderPosition);
            if (leaderDistance > LiveWalkThroughReservationMaxBotDistance)
            {
                return false;
            }

            Vector3 entry = episode.RawStart;
            if (NavMesh.SamplePosition(entry, out NavMeshHit entryHit, LiveWalkThroughEntrySampleRadius, NavMesh.AllAreas))
            {
                entry = entryHit.position;
            }
            float entryDistance = Vector3.Distance(bot.Position, entry);
            if (entryDistance > LiveWalkThroughReservationMaxBotDistance)
            {
                return false;
            }

            StrictPathResult entryPath = CalculateStrictPath(bot.Position, entry);
            if (!entryPath.StrictComplete ||
                entryPath.PathLength > Mathf.Max(entryDistance * 2.75f + 1f, entryDistance + 8f))
            {
                return false;
            }

            Vector3 episodeDirection = GetFlatDirection(episode.RawEnd - episode.RawStart);
            if (episodeDirection.sqrMagnitude > 0.5f)
            {
                float playerProgress = Vector3.Dot(leaderPosition - episode.RawStart, episodeDirection);
                float botProgress = Vector3.Dot(bot.Position - episode.RawStart, episodeDirection);
                // Only reserve followers that have not clearly passed the player through this live seam.
                if (botProgress > playerProgress + 2.0f)
                {
                    return false;
                }
            }

            ProvisionalWalkThroughReservations[profileId] = new ProvisionalWalkThroughReservation
            {
                EpisodeId = episode.EpisodeId,
                Entry = entry,
                ExpiresAt = Time.time + LiveWalkThroughReservationSeconds
            };
            target = entry;
            episodeId = episode.EpisodeId;
            BreadcrumbBarrierDetourUntil.Remove(profileId);
            WriteEvent("liveWalkThroughReserved", bot, new
            {
                episodeId,
                entry = Vec(entry),
                rawEntry = Vec(episode.RawStart),
                entryDistance,
                leaderDistance,
                currentEpisodeEnd = Vec(episode.RawEnd)
            });
            return true;
        }

        private static bool TryEscalateLearningV432FinalizedLiveWalkReservationAtEntry(
            BotOwner bot,
            ProvisionalWalkThroughReservation reservation,
            Vector3 leaderPosition,
            string source)
        {
            if ((bot == null) ||
                reservation == null || !IsFinite(leaderPosition))
            {
                return false;
            }

            TraversalEpisodeMetadata episode = TraversalEpisodeStream
                .LastOrDefault(item => item != null &&
                                       item.EpisodeId == reservation.EpisodeId &&
                                       item.EdgeId > 0);
            if (episode == null)
            {
                return false;
            }

            float entryDistance = GetPlanarDistance(bot.Position, reservation.Entry);
            if (entryDistance > WalkThroughEntryTolerance)
            {
                return false;
            }

            // The player episode is already finalized and the follower has physically arrived at
            // its entry. At this point the provisional reservation has completed its only job:
            // bridging Follow to admission. Force the existing route-mission selector to consume
            // current-raid/shadow-parent authority NOW rather than parking at the entry until an
            // arbitrary eight-second lease expires.
            bool missionArmed = TryArmOrRefreshFollowerRouteMission(
                bot,
                leaderPosition,
                "learningV432LiveWalkEntryArrival:" + (source ?? "unknown"),
                true);
            if (!missionArmed)
            {
                WriteEvent("learningV432LiveWalkReservationAdmissionEscalationDeferred", bot, new
                {
                    episodeId = episode.EpisodeId,
                    edgeId = episode.EdgeId,
                    entryDistance,
                    source = source ?? string.Empty,
                    action = "finalizedEntryArrivalCannotExtendReservationButRouteMissionSelectorStillOwnsAdmissionTruth"
                });
                return false;
            }

            ProvisionalWalkThroughReservations.Remove(bot.ProfileId);
            BreadcrumbBarrierDetourUntil.Remove(bot.ProfileId);
            RecordLearningV432AdmissionEvidence(episode.EdgeId, "liveReservationEntryArrivalEscalated", source);
            WriteEvent("learningV432LiveWalkReservationAdmissionEscalated", bot, new
            {
                episodeId = episode.EpisodeId,
                edgeId = episode.EdgeId,
                chainId = episode.ChainId,
                entry = Vec(reservation.Entry),
                entryDistance,
                source = source ?? string.Empty,
                reservationReleased = true,
                routeMissionArmed = true,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "finalizedCurrentRaidWalkThroughEntryArrivalImmediatelyCedesReservationToTraversalAdmission"
            });
            return true;
        }

        private static bool TryPromoteProvisionalWalkThroughReservation(BotOwner bot, bool allowStalePreemption = false)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !ProvisionalWalkThroughReservations.TryGetValue(profileId, out ProvisionalWalkThroughReservation reservation) ||
                reservation == null)
            {
                return false;
            }
            if (Time.time > reservation.ExpiresAt)
            {
                ProvisionalWalkThroughReservations.Remove(profileId);
                return false;
            }

            TraversalEpisodeMetadata episode = TraversalEpisodeStream
                .LastOrDefault(item => item != null && item.EpisodeId == reservation.EpisodeId && item.EdgeId > 0);

            if (LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment activeCommitment) &&
                activeCommitment != null && Time.time <= activeCommitment.ExpiresAt)
            {
                bool preempted = false;
                if (allowStalePreemption && episode != null && !HasActiveTraversalProbe(bot) &&
                    reservation.EpisodeId > activeCommitment.EpisodeId)
                {
                    StrictPathResult reservationPath = CalculateStrictPath(bot.Position, reservation.Entry);
                    StrictPathResult activePath = CalculateStrictPath(bot.Position, activeCommitment.Entry);
                    float reservationDistance = GetPlanarDistance(bot.Position, reservation.Entry);
                    bool reservationReachable = reservationPath.StrictComplete &&
                        reservationPath.PathLength <= Mathf.Max(reservationDistance * 2.25f + 1f, reservationDistance + 6f);
                    bool followTopologyRejected = FollowRejectLeases.ContainsKey(profileId);
                    bool activeStale = activeCommitment.ApproachPathFailures >= 2 ||
                                       !activePath.StrictComplete ||
                                       followTopologyRejected;
                    if (reservationReachable && activeStale)
                    {
                        LearnedTraversalCommitments.Remove(profileId);
                        preempted = true;
                        WriteEvent("liveWalkThroughBridgePreemptedStaleCommitment", bot, new
                        {
                            reservedEpisodeId = reservation.EpisodeId,
                            activeEpisodeId = activeCommitment.EpisodeId,
                            activeEdgeId = activeCommitment.EdgeId,
                            activeKind = activeCommitment.Kind,
                            activeApproachFailures = activeCommitment.ApproachPathFailures,
                            activePathComplete = activePath.StrictComplete,
                            reservationPathLength = reservationPath.PathLength,
                            reservationDistance,
                            followTopologyRejected
                        });
                    }
                }

                if (!preempted)
                {
                    WriteEvent("liveWalkThroughPromotionDeferredByFifo", bot, new
                    {
                        reservedEpisodeId = reservation.EpisodeId,
                        activeEpisodeId = activeCommitment.EpisodeId,
                        activeEdgeId = activeCommitment.EdgeId,
                        activeChainId = activeCommitment.ChainId
                    });
                    return false;
                }
            }

            // CompileFix46: never promote a reservation for an episode the follower route cursor has
            // already consumed. This is the second guard against the edge23 stale-recommit loop seen
            // after a physically successful WalkThrough in the Fix45.1 raid.
            if (episode != null && episode.EndBreadcrumbSequence > 0 &&
                FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor completedCursor) &&
                completedCursor != null && episode.EndBreadcrumbSequence <= completedCursor.ConsumedBreadcrumbSequence)
            {
                ProvisionalWalkThroughReservations.Remove(profileId);
                WriteEvent("liveWalkThroughPromotionSuppressedConsumedEpisode", bot, new
                {
                    reservedEpisodeId = reservation.EpisodeId,
                    edgeId = episode.EdgeId,
                    consumedEpisodeId = completedCursor.LastCompletedEpisodeId,
                    consumedBreadcrumbSequence = completedCursor.ConsumedBreadcrumbSequence
                });
                return false;
            }

            LearnedTraversalEdge edge = episode != null
                ? LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == episode.EdgeId)
                : null;
            if (edge == null || edge.Disabled ||
                !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            // CompileFix17: promotion may merge a fresh live episode into an older edge whose
            // generic NavMesh A endpoint was sampled on the wrong side of an off-NavMesh seam.
            // Preserve the current reservation/settled near-side anchor instead of snapping the
            // follower back to edge.A and monopolising Follow with an unreachable target.
            Vector3 promotedEntry = edge.HasSettledStart && IsFinite(edge.SettledStart)
                ? edge.SettledStart
                : (IsFinite(reservation.Entry) ? reservation.Entry : edge.A);
            Vector3 promotedExit = edge.HasSettledEnd && IsFinite(edge.SettledEnd)
                ? edge.SettledEnd
                : edge.B;
            LearnedTraversalCommitment promotedCommitment = CreateLearnedTraversalCommitment(
                edge, promotedEntry, promotedExit, edge.RawStart, edge.RawEnd);
            if (promotedCommitment == null)
            {
                return false;
            }
            promotedCommitment.EpisodeId = episode.EpisodeId;
            promotedCommitment.ChainId = episode.ChainId;
            LearnedTraversalCommitments[profileId] = promotedCommitment;
            ProvisionalWalkThroughReservations.Remove(profileId);
            BreadcrumbBarrierDetourUntil.Remove(profileId);
            WriteEvent("liveWalkThroughReservationPromoted", bot, new
            {
                episodeId = episode.EpisodeId,
                edgeId = edge.Id,
                entry = Vec(promotedEntry),
                exit = Vec(promotedExit),
                rawEntry = Vec(edge.RawStart),
                settledEntryUsed = edge.HasSettledStart && IsFinite(edge.SettledStart),
                currentDistance = Vector3.Distance(bot.Position, promotedEntry)
            });
            return true;
        }

        public static bool CanAcceptFollowPath(
            BotOwner bot,
            Vector3 target,
            out float pathLength,
            out float detourRatio)
        {
            return CanAcceptFollowPath(bot, target, null, out pathLength, out detourRatio);
        }

        public static bool CanAcceptFollowPath(
            BotOwner bot,
            Vector3 target,
            string source,
            out float pathLength,
            out float detourRatio)
        {
            pathLength = 0f;
            detourRatio = 0f;
            if (bot == null || !IsFinite(bot.Position) || !IsFinite(target))
            {
                return false;
            }

            float direct = Vector3.Distance(bot.Position, target);
            bool leaderRoute = IsLeaderFollowPathSource(source);
            bool routeMissionRoute = IsRouteMissionPathSource(source);
            if (leaderRoute && IsLearningV331RouteRetryMovementHoldActive(bot))
            {
                bool learningV453LiveTraversalProducer =
                    (HasLearningV453LiveTraversalPhysicalProducer(bot));
                ApplyLearningV331RouteRetryMovementHold(
                    bot,
                    "followPath:" + (source ?? "unknown") +
                    (learningV453LiveTraversalProducer ? ":producerAlive" : ":producerAbsentYield"));
                if (learningV453LiveTraversalProducer)
                {
                    pathLength = 0f;
                    detourRatio = 0f;
                    return false;
                }
            }

            // R8.8 negative-route cache: once this same leader path was proven pathological, do not
            // call CalculatePath again until the bot/leader geometry meaningfully changes.
            if (leaderRoute && TryGetMatchingFollowRejectLease(bot, target, out FollowRejectLease rejectedLease))
            {
                pathLength = rejectedLease.PathLength;
                detourRatio = rejectedLease.DetourRatio;
                return false;
            }

            // Pre-validated traversal/breadcrumb targets retain the historical low-cost behavior
            // beyond 10 m. The R8.5 all-distance guard is deliberately limited to ordinary
            // leader-primary/retry so combat/path producers elsewhere are not globally rewritten.
            if (!leaderRoute && !routeMissionRoute && direct > 10f)
            {
                pathLength = direct;
                detourRatio = 1f;
                return true;
            }

            // Initialize explicitly because the RHS is short-circuited when leaderRoute is false.
            // C# definite-assignment analysis does not infer that haveCached==true implies the out call ran.
            FollowPathSanitySample cached = null;
            // V3.55: leader-primary keeps the cheap microcache, but RouteMission approach
            // targets are moving-frontier transactions. Reusing a cached PathPartial/invalid result
            // after the body advanced can reject every later near-side breadcrumb before the
            // physical producer ever owns movement. RouteMission already has bounded retry cadence,
            // so calculate its strict path from the current body epoch.
            bool cacheablePath = leaderRoute;
            bool haveCached = cacheablePath &&
                              TryGetCachedFollowPathSanity(bot, target, out cached);
            bool strictComplete;
            if (haveCached)
            {
                pathLength = cached.PathLength;
                detourRatio = cached.DetourRatio;
                strictComplete = cached.StrictComplete;
            }
            else
            {
                StrictPathResult path = CalculateStrictPath(bot.Position, target);
                pathLength = path.PathLength;
                detourRatio = direct > 0.01f ? path.PathLength / direct : 1f;
                strictComplete = path.StrictComplete;
                if (cacheablePath)
                {
                    CacheFollowPathSanity(bot, target, direct, path);
                }
            }

            if (!strictComplete)
            {
                return false;
            }

            float allowedPathLength = GetAllowedFollowPathLength(direct, leaderRoute || routeMissionRoute);
            return pathLength <= allowedPathLength;
        }

