        private static bool HasLearningV371PendingTraversalExecutionDebt(
            BotOwner bot, out FollowerRouteMission mission, out FollowerRouteMissionStep step)
        {
            mission=null;step=null;
            if (bot==null || !FollowerRouteMissions.TryGetValue(bot.ProfileId,out mission) ||
                mission==null || mission.Lifecycle.Retired || mission.LifecycleRaid!=raidGeneration ||
                mission.CurrentStepIndex<0 || mission.CurrentStepIndex>=mission.Steps.Count) return false;
            step=mission.Steps[mission.CurrentStepIndex];
            return step!=null && step.Lifecycle.DebtOutstanding;
        }

