        private static bool TryParsePriorityTraversalEdgeSource(string source, out int edgeId)
        {
            edgeId = 0;
            const string prefix = "priority-traversal-edge-";
            if (string.IsNullOrEmpty(source) ||
                !source.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }
            string suffix = source.Substring(prefix.Length);
            return int.TryParse(suffix, NumberStyles.Integer, CultureInfo.InvariantCulture, out edgeId) &&
                   edgeId > 0;
        }


        private static int GetFollowerRouteResumeFloor(string profileId)
        {
            if(!string.IsNullOrEmpty(profileId)&&FollowerRouteMissions.TryGetValue(profileId,out var replay)&&IsCapabilityFullRouteReplay(replay))
                return replay.RouteRetry.ProgressFloor;
            if (string.IsNullOrEmpty(profileId))
            {
                return 0;
            }
            return FollowerRouteResumeFloors.TryGetValue(profileId, out int floor)
                ? Mathf.Max(0, floor)
                : 0;
        }

        private static int GetFollowerRouteExecutionFloor(string profileId)
        {
