            }
            return FollowerRouteExecutionFloors.TryGetValue(profileId, out int floor)
                ? Mathf.Max(0, floor)
                : 0;
        }

        private static string MakeFollowerTraversalEdgeQuarantineKey(string profileId, int edgeId)
        {
            return (profileId ?? string.Empty) + ":" + edgeId.ToString(CultureInfo.InvariantCulture);
        }

        private static bool IsFollowerTraversalEdgeQuarantined(string profileId, int edgeId)
        {
            if (string.IsNullOrEmpty(profileId) || edgeId <= 0)
            {
                return false;
            }

            string key = MakeFollowerTraversalEdgeQuarantineKey(profileId, edgeId);
            if (FollowerTraversalEdgeRaidBlacklists.Contains(key))
            {
                return true;
            }
            if (!FollowerTraversalEdgeQuarantines.TryGetValue(key, out float expiresAt))
            {
                return false;
            }
            if (Time.time >= expiresAt)
            {
                FollowerTraversalEdgeQuarantines.Remove(key);
                return false;
            }
            return true;
        }

        private static void BlacklistFollowerTraversalEdgeForRaid(BotOwner bot, int edgeId, string reason)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || edgeId <= 0)
            {
                return;
            }

            string key = MakeFollowerTraversalEdgeQuarantineKey(profileId, edgeId);
            bool added = FollowerTraversalEdgeRaidBlacklists.Add(key);
            bool clearedCommitment =
                LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment commitment) &&
                commitment != null && commitment.EdgeId == edgeId;
            if (clearedCommitment)
            {
                LearnedTraversalCommitments.Remove(profileId);
            }

            bool clearedRecoveryAnchor =
                NavigationRecoveryTraversalAnchors.TryGetValue(profileId, out LearnedTraversalCommitment recoveryAnchor) &&
                recoveryAnchor != null && recoveryAnchor.EdgeId == edgeId;
            if (clearedRecoveryAnchor)
            {
                NavigationRecoveryTraversalAnchors.Remove(profileId);
            }

            ProvisionalWalkThroughReservations.Remove(profileId);
            BreadcrumbFollowCommitments.Remove(profileId);
            FollowRejectLeases.Remove(profileId);
            WriteEvent("followerTraversalEdgeRaidBlacklisted", bot, new
            {
                edgeId,
                reason = reason ?? "unknown",
                added,
                clearedCommitment,
                clearedRecoveryAnchor,
                routeMissionPreserved = FollowerRouteMissions.ContainsKey(profileId)
            });
        }

        private static void QuarantineFollowerTraversalEdge(BotOwner bot, int edgeId, string reason)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || edgeId <= 0)
            {
                return;
            }

            string key = MakeFollowerTraversalEdgeQuarantineKey(profileId, edgeId);
            float expiresAt = Time.time + FollowerTraversalEdgeQuarantineSeconds;
            FollowerTraversalEdgeQuarantines[key] = expiresAt;

            // R8.12: quarantine is an ownership invalidation, not merely a future selector hint.
            // Existing commitments/route missions were able to keep reusing an edge after it had
            // already entered the quarantine dictionary. Remove every follower-local reference
            // that can resurrect the same route. The currently executing ProbeRuntime is not
            // forcibly detached here; its caller owns the bounded failure/recovery transition.
            bool clearedCommitment =
                LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment commitment) &&
                commitment != null && commitment.EdgeId == edgeId;
            if (clearedCommitment)
            {
                LearnedTraversalCommitments.Remove(profileId);
            }

            bool clearedRecoveryAnchor =
                NavigationRecoveryTraversalAnchors.TryGetValue(profileId, out LearnedTraversalCommitment recoveryAnchor) &&
                recoveryAnchor != null && recoveryAnchor.EdgeId == edgeId;
            if (clearedRecoveryAnchor)
            {
                NavigationRecoveryTraversalAnchors.Remove(profileId);
            }

            bool clearedMission = false;
            if (FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) && mission != null)
            {
                bool missionReferencesEdge = mission.Steps != null &&
                    mission.Steps.Any(step => step != null && step.EdgeId == edgeId);
                if (missionReferencesEdge)
                {
                    RemoveLifecycleMission(profileId, "QuarantineFollowerTraversalEdge");
                    clearedMission = true;
                }
            }

            ProvisionalWalkThroughReservations.Remove(profileId);
            BreadcrumbFollowCommitments.Remove(profileId);
            FollowRejectLeases.Remove(profileId);
            if (FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) &&
                cursor != null)
            {
                cursor.PreloadedEpisodeId = 0;
            }

            WriteEvent("followerTraversalEdgeQuarantined", bot, new
            {
                edgeId,
                reason = reason ?? "unknown",
                seconds = FollowerTraversalEdgeQuarantineSeconds,
                clearedCommitment,
                clearedRecoveryAnchor,
                clearedMission
            });
        }

        private static int TryExtractTraversalExitEdgeId(string reason)
        {
            if (string.IsNullOrWhiteSpace(reason))
            {
                return 0;
            }

            const string token = "traversalExit:";
            int start = reason.IndexOf(token, StringComparison.OrdinalIgnoreCase);
            if (start < 0)
            {
                return 0;
            }
            start += token.Length;
            int end = start;
            while (end < reason.Length && char.IsDigit(reason[end]))
            {
                end++;
            }
            if (end <= start)
            {
                return 0;
            }
            return int.TryParse(reason.Substring(start, end - start), NumberStyles.Integer, CultureInfo.InvariantCulture, out int edgeId)
                ? Math.Max(0, edgeId)
                : 0;
        }

        private static void AdvanceFollowerRouteResumeFloor(BotOwner bot, string reason, bool quarantineCurrentTraversal)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }

            int previousFloor = GetFollowerRouteResumeFloor(profileId);
            int newFloor = Math.Max(previousFloor, breadcrumbSequence);

            // CompileFix31 failure attribution: navigation recovery can fire after the route
            // mission has already advanced beyond the traversal that actually stranded the bot.
            // Prefer the typed origin encoded by traversalExit:<edgeId>:<kind> over whatever step
            // happens to be current at recovery time. This prevents e.g. Vault13 from poisoning
            // unrelated edge140.
            int abandonedEdgeId = TryExtractTraversalExitEdgeId(reason);
            string abandonedEdgeSource = abandonedEdgeId > 0 ? "recoveryReasonOrigin" : "currentRouteState";
            if (abandonedEdgeId <= 0 &&
                LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment activeCommitment) &&
                activeCommitment != null)
            {
                abandonedEdgeId = activeCommitment.EdgeId;
            }
            else if (abandonedEdgeId <= 0 &&
                     FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission activeMission) &&
                     activeMission != null &&
                     activeMission.CurrentStepIndex >= 0 &&
                     activeMission.CurrentStepIndex < activeMission.Steps.Count)
            {
                abandonedEdgeId = activeMission.Steps[activeMission.CurrentStepIndex]?.EdgeId ?? 0;
            }

            if (quarantineCurrentTraversal && abandonedEdgeId > 0)
            {
                QuarantineFollowerTraversalEdge(bot, abandonedEdgeId, reason);
            }

            FollowerRouteResumeFloors[profileId] = newFloor;
            if (!FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) || cursor == null)
            {
                cursor = new FollowerTraversalRouteCursor();
                FollowerTraversalRouteCursors[profileId] = cursor;
            }
            // RC26: cancellation advances the floor but cannot author a new
            // completed episode. Clearing the pending preload is explicit policy.
            CommitFollowerTraversalRouteCursor(
                cursor, 0, 0, newFloor,
                FollowerMovementV2IntentGateway.RouteCursorMutationKind.RouteIntentCancelled);

            // Capture the route transaction's issuer BEFORE End clears its generation.
            // A stale cancellation must not retire whichever unrelated Traversal acquired
            // the Bot in the meantime.
            long cancelledRouteOrigin = 0;
            if (FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cancellationCursor) &&
                cancellationCursor != null && cancellationCursor.LearningV375TransactionActive)
            {
                cancelledRouteOrigin = cancellationCursor.LearningV375MovementGeneration;
            }
            EndLearningV375PersistentRouteTransaction(bot, "routeIntentCancelled:" + (reason ?? "unknown"));
            RemoveLifecycleMission(profileId, "AdvanceFollowerRouteResumeFloor");
            LearnedTraversalCommitments.Remove(profileId);
            ProvisionalWalkThroughReservations.Remove(profileId);
            NavigationRecoveryTraversalAnchors.Remove(profileId);
            BreadcrumbFollowCommitments.Remove(profileId);
            FollowRejectLeases.Remove(profileId);

            bool staleChainGuardCleared = ChainHandoffAuthorityGuards.Remove(profileId);
            TraversalChainLocomotionIntents.Remove(profileId);
            if (!HasActiveTraversalProbe(bot))
            {
                bool originRetired = FollowerMovementWriterAuthority.TransitionTraversalToFollowIfIdleExact(
                    bot, cancelledRouteOrigin, "routeIntentCancelled:" + (reason ?? "unknown"));
                if (!originRetired && cancelledRouteOrigin > 0)
                {
                    WriteEvent("v2CancelledRouteRetirementOriginRejected", bot, new
                    {
                        reason = reason ?? "unknown",
                        originGeneration = cancelledRouteOrigin,
                        action = "doNotRetireDifferentTraversalOwner"
                    });
                }
            }
            long routeResumeMovementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(bot, out _);

            WriteEvent("followerRouteResumeFloorAdvanced", bot, new
            {
                reason = reason ?? "unknown",
                previousFloor,
                newFloor,
                abandonedEdgeId,
                abandonedEdgeSource,
                quarantined = quarantineCurrentTraversal && abandonedEdgeId > 0,
                staleChainGuardCleared,
                movementGeneration = routeResumeMovementGeneration
            });
        }

