        private static bool TryEvaluateLearningV452CurrentBodySemanticFrontier(
            BotOwner bot,
            FollowerRouteMissionStep step,
            out float projection,
            out float requiredProjection,
            out float lateralDistance,
            out string proofSource)
        {
            projection = 0f;
            requiredProjection = 0f;
            lateralDistance = float.PositiveInfinity;
            proofSource = string.Empty;
            if ((bot == null) || step == null ||
                !IsFinite(bot.Position))
            {
                return false;
            }

            Vector3 rawEntry = IsFinite(step.RawEntry) ? step.RawEntry : step.Entry;
            Vector3 rawExit = IsFinite(step.RawExit) ? step.RawExit : step.Exit;
            if (!IsFinite(rawEntry) || !IsFinite(rawExit))
            {
                return false;
            }

            float entryDistance = GetPlanarDistance(bot.Position, rawEntry);
            float exitDistance = GetPlanarDistance(bot.Position, rawExit);
            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            float length = axis.magnitude;
            if (length < 0.25f)
            {
                bool compactReached = FollowerCapabilityHelperRules.TryEvaluateLearningV452CurrentBodySemanticFrontier_compactReached_AE0E5BF8_1(exitDistance,exitDistance,entryDistance);
                if (compactReached)
                {
                    proofSource = "compactDirectedSemanticExit";
                    lateralDistance = exitDistance;
                }
                return compactReached;
            }

            Vector3 direction = axis / length;
            Vector3 fromEntry = bot.Position - rawEntry;
            fromEntry.y = 0f;
            projection = Vector3.Dot(fromEntry, direction);
            requiredProjection = Mathf.Max(0.12f, length - 0.25f);
            lateralDistance = GetPlanarDistanceToSegment(bot.Position, rawEntry, rawExit);
            bool verticalCredible = Mathf.Abs(bot.Position.y - rawExit.y) <= 1.35f;
            bool nearExit = FollowerCapabilityHelperRules.TryEvaluateLearningV452CurrentBodySemanticFrontier_nearExit_AE0E5BF8_2(exitDistance,exitDistance,entryDistance);
            bool directedReached = FollowerCapabilityHelperRules.TryEvaluateLearningV452CurrentBodySemanticFrontier_directedReached_AE0E5BF8_3(verticalCredible,projection,requiredProjection,nearExit,lateralDistance,RouteMissionDirectionalWalkThroughMaxLateral);

            if (string.Equals(step.Kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                directedReached = directedReached &&
                    IsFollowerAlreadyBelowDropDownLanding(bot.Position, rawEntry, rawExit, step.Exit);
                proofSource = directedReached
                    ? "dropDownCurrentBodyLandingPostcondition"
                    : string.Empty;
            }
            else if (directedReached)
            {
                proofSource = "finiteDirectedCurrentBodySemanticFrontier";
            }
            return directedReached;
        }

        private static bool TryConsumeLearningV452CurrentBodySuccessorPostcondition(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep predecessor,
            FollowerRouteMissionStep successor,
            out string proofSource)
        {
            var r2DebtObservation8 = CaptureRouteDebtObservation(bot, mission, successor, false);

            proofSource = string.Empty;
            if ((bot == null) || mission == null ||
                predecessor == null || successor == null || predecessor.ChainId <= 0 ||
                successor.ChainId != predecessor.ChainId ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count ||
                !ReferenceEquals(mission.Steps[mission.CurrentStepIndex], successor))
            {
                return false;
            }

            if (!TryEvaluateLearningV452CurrentBodySemanticFrontier(
                    bot, successor, out float projection, out float requiredProjection,
                    out float lateralDistance, out proofSource))
            {
                return false;
            }

            bool consumed = ConsumeFollowerRouteMissionPhysicalPass(
                bot, mission, successor,
                "learningV452CurrentBodySuccessorPostcondition:" + proofSource,
                projection, requiredProjection);
            if (!consumed)
            {
                return false;
            }

            if (!TryAdvanceRouteMission(bot, mission, mission.CurrentStepIndex + 1, RouteDebtEvidence.PhysicalPass, "TryConsumeLearningV452CurrentBodySuccessorPostcondition:3", r2DebtObservation8)) return false;
            mission.ApproachBreadcrumbSequence = Math.Max(
                mission.ApproachBreadcrumbSequence, successor.EndBreadcrumbSequence);
            mission.LastProgressAt = Time.time;
            mission.LastProgressPosition = bot.Position;
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;
            WriteEvent("learningV452SuccessorPostconditionSubsumedByCurrentBodyEpoch", bot, new
            {
                missionId = mission.MissionId,
                predecessorEdgeId = predecessor.EdgeId,
                predecessorKind = predecessor.Kind,
                successorEdgeId = successor.EdgeId,
                successorKind = successor.Kind,
                successorEpisodeId = successor.EpisodeId,
                body = Vec(bot.Position),
                projection,
                requiredProjection,
                lateralDistance,
                proofSource,
                traversalSuccessRecorded = false,
                nativeSuccessRecorded = false,
                persistentLearningChanged = false,
                bodyRelocated = false,
                action = "retireOnlyRaidLocalSuccessorExecutionDebtAlreadySatisfiedByCurrentPhysicalBody"
            });
            return true;
        }

        // RC61: IsFollowerRouteMissionStepPhysicallyPassed extracted unchanged to FollowerTraversalRouteMissionLifecycle.cs.

        // RC61: MarkLearningV388PhysicalPassageExecutionDebtConsumed extracted unchanged to FollowerTraversalRouteMissionLifecycle.cs.

        // RC61: TryConsumeLearningV408ImmediatePhysicalPassageCompletion extracted unchanged to FollowerTraversalRouteMissionLifecycle.cs.

