        private static bool TryProveLearningV366FiniteWalkThroughDownstreamRouteRejoin(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            float projection,
            float requiredProjection,
            out PlayerBreadcrumbNode downstreamNode,
            out float downstreamDistance,
            out float downstreamPathLength)
        {
            downstreamNode = null;
            downstreamDistance = float.MaxValue;
            downstreamPathLength = 0f;
            if ((bot == null) || mission?.RouteBreadcrumbs == null ||
                step == null || !string.Equals(step.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                step.EndBreadcrumbSequence <= 0 || requiredProjection <= 0f || projection < requiredProjection ||
                HasActiveTraversalProbe(bot))
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment liveCommitment) &&
                liveCommitment != null && liveCommitment.EpisodeId == step.EpisodeId)
            {
                return false;
            }

            foreach (PlayerBreadcrumbNode node in mission.RouteBreadcrumbs
                .Where(candidate => candidate != null &&
                                    candidate.Sequence > step.EndBreadcrumbSequence &&
                                    candidate.Sequence <= mission.TargetBreadcrumbSequence &&
                                    IsOperationalBreadcrumbNode(candidate))
                .OrderByDescending(candidate => candidate.Sequence))
            {
                Vector3 target = GetOperationalBreadcrumbTarget(node);
                if (!IsFinite(target))
                {
                    continue;
                }
                float direct = GetPlanarDistance(bot.Position, target);
                if (direct <= 0.001f || direct > RouteMissionBreadcrumbLookAheadDistance)
                {
                    continue;
                }

                StrictPathResult strict = CalculateStrictPath(bot.Position, target);
                float allowed = GetAllowedFollowPathLength(direct, true);
                if (strict == null || !strict.StrictComplete || strict.PathLength <= 0f ||
                    strict.PathLength > allowed)
                {
                    continue;
                }

                downstreamNode = node;
                downstreamDistance = direct;
                downstreamPathLength = strict.PathLength;
                return true;
            }
            return false;
        }

        private static bool TryProveLearningV367DownstreamExecutionDebtBypass(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            PlayerBreadcrumbNode downstreamNode,
            float downstreamDistance,
            out float downstreamPathLength,
            out float actionEntryDistance,
            out float actionExitDistance)
        {
            downstreamPathLength = 0f;
            actionEntryDistance = float.MaxValue;
            actionExitDistance = float.MaxValue;
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment liveCommitment) &&
                liveCommitment != null && liveCommitment.EpisodeId == step.EpisodeId)
            {
                return false;
            }

            Vector3 entry = IsFinite(step.RawEntry) ? step.RawEntry : step.Entry;
            Vector3 exit = IsFinite(step.RawExit) ? step.RawExit : step.Exit;
            if (!IsFinite(entry) || !IsFinite(exit))
            {
                return false;
            }
            actionEntryDistance = GetPlanarDistance(bot.Position, entry);
            actionExitDistance = GetPlanarDistance(bot.Position, exit);

            // This proof is intentionally about EXECUTION debt, not semantic truth. The follower
            // must already be much more local to a newer player-route node than to either side of
            // the old actuator action. This prevents a merely reachable cheap NavMesh bypass from
            // erasing empirical route knowledge while still allowing a body that genuinely joined
            // a later player route epoch to continue instead of running backwards to old entry.
            float actionDistance = Mathf.Min(actionEntryDistance, actionExitDistance);
            if (downstreamDistance <= 0.001f || downstreamDistance > RouteMissionBreadcrumbLookAheadDistance ||
                downstreamDistance + RouteMissionBreadcrumbReachDistance >= actionDistance)
            {
                return false;
            }

            Vector3 target = GetOperationalBreadcrumbTarget(downstreamNode);
            if (!IsFinite(target))
            {
                return false;
            }
            StrictPathResult strict = CalculateStrictPath(bot.Position, target);
            float allowed = GetAllowedFollowPathLength(Mathf.Max(0.25f, downstreamDistance), true);
            if (strict == null || !strict.StrictComplete || strict.PathLength <= 0f || strict.PathLength > allowed)
            {
                return false;
            }

            downstreamPathLength = strict.PathLength;
            return true;
        }

