                        // -> RawEntry -> lane during the same Climb mission (edge 15).
                        // Preserve the already-authored V3.63 lane until the existing
                        // executor trigger boundary is physically reached. Never infer
                        // native admission, success, or a new movement generation here.
                        cf42PreTriggerLaneOwnsTranslation =
                            learningV424EntryDistance > learningV424TriggerDistance;
                        if (cf42PreTriggerLaneOwnsTranslation)
                        {
                            readyForProbe = false;
                            laneSource = (laneSource ?? string.Empty) + ":cf42PreTriggerLane";
                            if (ShouldEmitDiagnostic(
                                    "cf42ActuatorPreTriggerLaneRetained:" +
                                        step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.35f))
                            {
                                WriteEvent("cf42ActuatorPreTriggerLaneRetained", bot, new
                                {
                                    missionId = mission.MissionId,
                                    stepIndex = mission.CurrentStepIndex,
                                    edgeId = step.EdgeId,
                                    kind = step.Kind,
                                    entryDistance = learningV424EntryDistance,
                                    nativeTriggerDistance = learningV424TriggerDistance,
                                    forwardEntryProjection,
                                    lateralEntryOffset,
                                    laneSource,
                                    traversalSuccessRecorded = false,
                                    persistentLearningChanged = false,
                                    bodyRelocated = false,
                                    action = "keepExistingActuatorLaneTranslationUntilExistingNativeTriggerBoundary"
                                });
                            }
                        }
                        else
                        {
                            target = learningV424AdmissionTarget;
                            laneSource = (laneSource ?? string.Empty) + ":learningV424ExecutorAdmission";
                            if (actuatorDirection.sqrMagnitude > 0.5f)
                            {
                                try { bot.Steering?.BotSteeringLookToDirection("R1-70E5366E3B7B",@bot,actuatorDirection); } catch { }
                            }
                        }
                    }
                }

                if (ShouldEmitDiagnostic(
                        "learningV424ActuatorAdmissionFrontier:" +
                            step.EdgeId.ToString(CultureInfo.InvariantCulture),
                        bot, 0.18f))
                {
                    WriteEvent(learningV424ExecutorAdmissible
                        ? "learningV424ActuatorExecutorAdmissionConfirmed"
                        : "learningV424ActuatorBeforeAdmissionFrontier", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = mission.CurrentStepIndex,
                        edgeId = step.EdgeId,
                        kind = step.Kind,
                        entryDistance = learningV424EntryDistance,
                        triggerDistance = learningV424TriggerDistance,
                        forwardEntryProjection = learningV424ForwardProjection,
                        maxForwardOvershoot = learningV424MaxForwardOvershoot,
                        lateralEntryOffset = learningV424LateralOffset,
                        maxLateral = learningV424MaxLateral,
                        alignmentAngle = learningV424AlignmentAngle,
                        maxAlignmentAngle = learningV424MaxAlignmentAngle,
                        laneSource,
                        admissionDetail = learningV424AdmissionDetail,
                        learningV425OrientationOnlyAdmission,
                        learningV425OrientationOnlyDetail,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = learningV424ExecutorAdmissible
                            ? "existingExecutorEnvelopeAtomicallyReceivesCurrentPhysicalBodyEpoch"
                            : ((learningV425OrientationOnlyAdmission) &&
                               learningV418ProbeOwnsFinalHeading
                                ? "passiveHeadingAdmissionTransfersCurrentBodyEpochToActualRollingActuatorProbe"
                                : ((learningV425OrientationOnlyAdmission)
                                    ? "passiveHeadingAdmissionSteersExistingTranslationProducerContinues"
                                    : (learningV425OrientationOnlyAdmission
                                        ? "existingPositionEnvelopeHoldsBodyWhileNativeSteeringOwnsFinalHeading"
                                        : "samePhysicalProducerApproachesImmutableAdmissionFrontierNoProbeGenerationSwap")))
                    });
                }

