                      learningV418ProbeOwnsFinalHeading) &&
                    !cf42PreTriggerLaneOwnsTranslation)
                {
                    return IsFinite(target);
                }
            }

            if (readyForProbe)
            {
                target = bot.Position;
                if (ShouldEmitDiagnostic(
                        "learningV363ActuatorRouteEntryLaneReady:" +
                            step.EdgeId.ToString(CultureInfo.InvariantCulture),
                        bot, 0.18f))
                {
                    WriteEvent("learningV363ActuatorRouteEntryLaneReady", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = mission.CurrentStepIndex,
                        edgeId = step.EdgeId,
                        kind = step.Kind,
                        anchorSequence,
                        laneSource,
                        forwardEntryProjection,
                        lateralEntryOffset,
                        maxLateral,
                        actuatorAlignmentAngle,
                        actuatorHeadingReady,
                        learningV418PositionFrontierReady,
                        learningV418ProbeOwnsFinalHeading,
                        action = learningV418ProbeOwnsFinalHeading && !actuatorHeadingReady
                            ? "positionFrontierTransfersAuthorityProbeOwnsFinalHeadingNativeTriggerStillUsesExistingAlignmentGate"
                            : "positionAndHeadingReadyAllowExistingTraversalProbeToAcquireAuthority"
                    });
                }
                return true;
            }

