            // the CURRENT-RAID approach axis and bound the look-ahead to RawEntry; no entry
            // readiness, jump/climb invocation, or physical success can be inferred here.
            bool cf62ClimbBoundedForwardStaging =
                string.Equals(step.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                laneDirection.sqrMagnitude > 0.5f &&
                forwardEntryProjection >= -LearningV3NativeEntryCorrectionStagingDistance &&
                forwardEntryProjection < -0.15f &&
                lateralEntryOffset <= maxLateral &&
                GetPlanarDistance(bot.Position, rawEntry) > InjectedNativeVaultEntryTriggerDistance;
            if (cf62ClimbBoundedForwardStaging)
            {
