            // forward lead slightly BEFORE that station only with current-raid route
            // provenance, same-height body geometry, and a short strict NavMesh path.
            // This is translation evidence only: it never grants Climb admission,
            // claims a physical crossing, or permits a path through the obstacle.
            bool cf70ValidatedCurrentRaidClimbNearStagingLead = false;
            Vector3 cf70ValidatedClimbLeadTarget = Vector3.zero;
            float cf70ValidatedClimbLeadPathLength = 0f;
            float cf70OriginalRequestedProjection = requestedProjection;
            if (string.Equals(step.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                !cf62ClimbBoundedForwardStaging &&
                string.Equals(laneSource, "currentRaidBreadcrumb", StringComparison.Ordinal) &&
                forwardEntryProjection < -LearningV3NativeEntryCorrectionStagingDistance &&
                forwardEntryProjection >= -LearningV3NativeEntryCorrectionStagingDistance - 0.24f &&
                lateralEntryOffset <= Mathf.Min(maxLateral * 0.70f, 0.45f) &&
