            // breadcrumb whose off-NavMesh staging producer points away from the actuator.
            // The witness is passive: no path permission, stage target or exit proof changes.
            if (string.Equals(step.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                ShouldEmitDiagnostic("cf59ClimbLaneGeometry:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.65f))
            {
                Vector3 requestedFlat = GetFlatDirection(requested - bot.Position);
                WriteEvent("cf59ClimbPreProbeLaneWitness", bot, new
                {
                    missionId = mission.MissionId,
                    stepIndex = mission.CurrentStepIndex,
                    edgeId = step.EdgeId,
                    episodeId = step.EpisodeId,
                    rawEntry = Vec(rawEntry),
                    rawExit = Vec(rawExit),
                    body = Vec(bot.Position),
                    requested = Vec(requested),
                    anchorSequence,
                    laneSource,
                    forwardEntryProjection,
                    lateralEntryOffset,
                    actuatorAlignmentAngle,
                    requestedForwardDot = requestedFlat.sqrMagnitude > 0.5f
                        ? Vector3.Dot(requestedFlat, laneDirection) : 0f,
                    bodyVerticalDeltaFromRawEntry = bot.Position.y - rawEntry.y,
                    nativeSuccessRecorded = false,
                    bodyRelocated = false,
                    action = "observeExactCurrentRaidClimbLaneAndHeightBeforeChangingAnyProducer"
                });
            }
            // V2-RC57: Climb staging-geometry side quest retired.
            // Return to the already existing CF62/CF65/CF70 current-body lane.
            // RC43 replay proves short complete paths plus side stages did not
            // guarantee physical body progress. No normal-stage replan exists here.

            // CF65: a persistent Climb ingress axis can be trustworthy as a *semantic*
            // orientation, yet be unusable as a translation lane when the follower is
            // against the obstacle beside its entrance.  Projecting onto the persistent
            // axis then creates a purely lateral target (zero longitudinal progress) and
            // can repeat indefinitely.  Prefer the CURRENT body -> original entry only
            // when a short, strict, same-height NavMesh path proves that approach really
            // exists.  Never infer Native readiness, move across an unproven wall, alter
            // the player-authored Climb axis or pull a body already past the entry back.
            if (string.Equals(step.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                string.Equals(laneSource, "persistentApproachDirection", StringComparison.Ordinal) &&
                forwardEntryProjection < -0.10f &&
                forwardEntryProjection >= -LearningV3NativeEntryCorrectionStagingDistance &&
                lateralEntryOffset > maxLateral + 0.20f &&
                Mathf.Abs(bot.Position.y - rawEntry.y) <= 0.65f)
            {
                float directEntryDistance = GetPlanarDistance(bot.Position, rawEntry);
                if (directEntryDistance >= 0.85f && directEntryDistance <= 4.0f &&
                    NavMesh.SamplePosition(rawEntry, out NavMeshHit cf65EntryHit,
                        0.45f, NavMesh.AllAreas) &&
                    GetPlanarDistance(rawEntry, cf65EntryHit.position) <= 0.40f &&
                    Mathf.Abs(rawEntry.y - cf65EntryHit.position.y) <= 0.45f)
                {
                    StrictPathResult cf65Ingress = CalculateStrictPath(bot.Position, cf65EntryHit.position);
                    if (cf65Ingress != null && cf65Ingress.StrictComplete &&
                        cf65Ingress.PathLength >= directEntryDistance - 0.10f &&
                        cf65Ingress.PathLength <= Mathf.Min(
                            RouteMissionTraversalAdjacentBridgeMaxDistance,
                            directEntryDistance * 1.60f + 0.20f))
                    {
                        target = cf65EntryHit.position;
                        laneSource += ":cf65CurrentBodyStrictClimbIngress";
                        if (ShouldEmitDiagnostic("cf65StrictClimbIngress:" +
                            mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                            step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.35f))
                        {
                            WriteEvent("cf65CurrentBodyStrictClimbIngressPublished", bot, new
                            {
                                missionId = mission.MissionId,
                                edgeId = step.EdgeId,
                                source = "persistentApproachDirection",
                                originalRequested = Vec(requested),
                                currentBody = Vec(bot.Position),
                                rawEntry = Vec(rawEntry),
                                pathTarget = Vec(target),
                                strictPathLength = cf65Ingress.PathLength,
                                directEntryDistance,
                                forwardEntryProjection,
                                lateralEntryOffset,
                                maxLateral,
                                nativeSuccessRecorded = false,
                                bodyRelocated = false,
                                action = "strictCurrentBodyToAuthoredEntryPathOutranksPerpendicularPersistentLateralChase"
                            });
                        }
                        return true;
                    }
                }
            }

            if (cf70ValidatedCurrentRaidClimbNearStagingLead)
            {
                target = cf70ValidatedClimbLeadTarget;
                laneSource += ":navMeshLane";
                if (ShouldEmitDiagnostic("cf70ClimbNearStageLead:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.35f))
                {
                    WriteEvent("cf70CurrentRaidClimbStrictNearStagingLead", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = mission.CurrentStepIndex,
                        edgeId = step.EdgeId,
                        episodeId = step.EpisodeId,
                        laneSource,
                        body = Vec(bot.Position),
                        rawEntry = Vec(rawEntry),
                        originalRequestedProjection = cf70OriginalRequestedProjection,
                        forwardEntryProjection,
                        validatedRequestedProjection = requestedProjection,
                        validatedTarget = Vec(target),
                        strictPathLength = cf70ValidatedClimbLeadPathLength,
                        nativeAdmissionGranted = false,
                        nativeSuccessRecorded = false,
                        bodyRelocated = false,
                        action = "currentRaidShortStrictPathMovesClimbIngressForwardWithoutPrematureNativeAdmission"
                    });
                }
                return IsFinite(target);
            }

            bool sampledLane = NavMesh.SamplePosition(
                requested,
                out NavMeshHit hit,
                LearningV3NativeEntryCorrectionSampleRadius,
                NavMesh.AllAreas) &&
                GetPlanarDistance(requested, hit.position) <= LearningV3NativeEntryCorrectionMaxSampleOffset &&
                (rc116VaultLead<=0f || FollowerCapabilityApproachPolicy.ForwardSample(rc116VaultLead,
                    Vector3.Dot(GetFlatDelta(bot.Position,hit.position),laneDirection),
                    (GetFlatDelta(requested,hit.position)-laneDirection*Vector3.Dot(GetFlatDelta(requested,hit.position),laneDirection)).magnitude));
            sampledLane=sampledLane&&FollowerCapabilityPassagePolicy.ForwardLaneSample(currentDropLead,forwardEntryProjection,
                Vector3.Dot(GetFlatDelta(rawEntry,hit.position),laneDirection));
            if (sampledLane)
            {
                StrictPathResult path = CalculateStrictPath(bot.Position, hit.position);
                if (path != null && path.StrictComplete &&
                    path.PathLength <= RouteMissionTraversalAdjacentBridgeMaxDistance)
                {
                    target = hit.position;
                    laneSource = (laneSource ?? string.Empty) + ":navMeshLane";
                    return IsFinite(target);
                }
            }

            ;

            // The lane came from current player breadcrumbs or persisted ApproachDirection and is
            // already bounded to the existing staging/forward-overshoot contract. NavMesh is only a
            // backend here, not semantic authority. When it cannot represent the demonstrated lane,
            // return the physical point so the persistent Traversal writer can use the existing
            // collision-active physical route primitive instead of holding action debt forever.
            target = requested;
            laneSource = (laneSource ?? string.Empty) + ":physicalNoNavMesh";
            return IsFinite(target);
        }

        private static bool TryProveLearningV420ActiveTerminalWalkThroughDownstreamRouteRejoin(
            ProbeRuntime probe,
            out FollowerRouteMission mission,
            out FollowerRouteMissionStep step,
            out PlayerBreadcrumbNode downstreamNode,
            out float projection,
            out float requiredProjection,
            out float downstreamDistance,
            out float downstreamPathLength)
        {
            mission = null;
            step = null;
            downstreamNode = null;
            projection = 0f;
            requiredProjection = 0f;
            downstreamDistance = float.MaxValue;
            downstreamPathLength = 0f;
            if ((probe?.Bot == null) ||
                probe.Player == null || !IsActiveProbe(probe) ||
                !string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority ||
                !TryGetLearningV419WalkThroughTerminalFrontierContinuation(
                    probe, probe.Player.Position, out _, out _, out _))
            {
                return false;
            }

            string profileId = probe.Bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowerRouteMissions.TryGetValue(profileId, out mission) || mission == null ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null || commitment.RouteMissionId != mission.MissionId ||
                commitment.RouteMissionStepIndex != mission.CurrentStepIndex)
            {
                mission = null;
                return false;
            }

            step = mission.Steps[mission.CurrentStepIndex];
            if (step == null ||
                !string.Equals(step.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                step.EpisodeId != probe.TraversalEpisodeId ||
                step.EdgeId != probe.LearnedEdgeId ||
                step.EndBreadcrumbSequence <= 0)
            {
                mission = null;
                step = null;
                return false;
            }

            // Reuse the existing route-step projection contract. V3.42 may reject the WT as
            // non-local even while still returning the finite forward projection; V4.20 requires
            // that the body has already passed that finite step before downstream route evidence
            // can supplement the active terminal transaction.
            IsFollowerRouteMissionStepPhysicallyPassed(
                probe.Bot, step, out projection, out requiredProjection);
            if (requiredProjection <= 0f || projection < requiredProjection ||
                mission.RouteBreadcrumbs == null)
            {
                return false;
            }

            // COMPILEFIX1: C# forbids capturing out parameters (`step`/`mission`) inside
            // the LINQ lambda. Snapshot the already-validated scalar bounds into ordinary locals;
            // this changes no runtime semantics, ordering, authority, or completion threshold.
            int completedStepEndBreadcrumbSequence = step.EndBreadcrumbSequence;
            int missionTargetBreadcrumbSequence = mission.TargetBreadcrumbSequence;
            foreach (PlayerBreadcrumbNode node in mission.RouteBreadcrumbs
                .Where(candidate => candidate != null &&
                                    candidate.Sequence > completedStepEndBreadcrumbSequence &&
                                    candidate.Sequence <= missionTargetBreadcrumbSequence &&
                                    IsOperationalBreadcrumbNode(candidate))
                .OrderByDescending(candidate => candidate.Sequence))
            {
                Vector3 target = GetOperationalBreadcrumbTarget(node);
                if (!IsFinite(target))
                {
                    continue;
                }
                float direct = GetPlanarDistance(probe.Bot.Position, target);
                if (direct <= 0.001f || direct > RouteMissionBreadcrumbLookAheadDistance)
                {
                    continue;
                }

                StrictPathResult strict = CalculateStrictPath(probe.Bot.Position, target);
                float allowed = GetAllowedFollowPathLength(direct, true);
                if (strict == null || !strict.StrictComplete || strict.PathLength <= 0f ||
                    strict.PathLength > allowed)
                {
                    continue;
                }

                downstreamNode = node;
                downstreamDistance = direct;
                downstreamPathLength = strict.PathLength;
                return true;
            }
            return false;
        }

        private static bool TryGetRouteMissionApproachAnchorTarget(
            BotOwner bot,
            FollowerRouteMissionStep step,
            out Vector3 target)
        {
            target = default;
            if (bot == null || step == null || !IsFinite(step.Entry))
            {
                return false;
            }

            Vector3 direction = GetFlatDirection(
                (IsFinite(step.RawExit) ? step.RawExit : step.Exit) -
                (IsFinite(step.RawEntry) ? step.RawEntry : step.Entry));
            Vector3 requested = step.Entry;
            if (direction.sqrMagnitude > 0.5f)
            {
                requested -= direction * 0.85f;
            }

            if (!NavMesh.SamplePosition(
                    requested,
                    out NavMeshHit hit,
                    RouteMissionApproachAnchorSampleRadius,
                    NavMesh.AllAreas))
            {
                return false;
            }

            StrictPathResult path = CalculateStrictPath(bot.Position, hit.position);
            if (!path.StrictComplete)
            {
                return false;
            }

            float direct = GetPlanarDistance(bot.Position, hit.position);
            float allowed = Mathf.Max(direct + 4.0f, direct * 1.75f);
            if (path.PathLength > allowed)
            {
                return false;
            }

            target = hit.position;
            return IsFinite(target);
        }

        private static bool TryRetireLearningV420FollowRejectLeaseFromTraversalBodyEpoch(
            BotOwner bot, FollowRejectLease lease, string source)
        {
            if ((bot == null) || lease == null ||
                string.IsNullOrEmpty(bot.ProfileId) ||
                GetPlanarDistance(lease.Start, bot.Position) < BreadcrumbMinDistance)
            {
                return false;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (owner != FollowerMovementWriterAuthority.WriterDomain.Traversal || generation <= 0)
            {
                return false;
            }

            bool activeTraversalBodyEpoch =
                (TryGetActiveProbe(bot, out ProbeRuntime activeProbe) &&
                 activeProbe != null && activeProbe.Generation == raidGeneration &&
                 activeProbe.MovementWriterGeneration == generation) ||
                (FollowerTraversalRouteCursors.TryGetValue(
                     bot.ProfileId, out FollowerTraversalRouteCursor cursor) &&
                 cursor != null && cursor.LearningV375TransactionActive &&
                 cursor.LearningV375MovementGeneration == generation);
            if (!activeTraversalBodyEpoch)
            {
                return false;
            }

            FollowRejectLeases.Remove(bot.ProfileId);
            WriteEvent("learningV420FollowRejectLeaseRetiredByNewTraversalBodyEpoch", bot, new
            {
                source = source ?? "unknown",
                leaseStart = Vec(lease.Start),
                currentBody = Vec(bot.Position),
                bodyProgress = GetPlanarDistance(lease.Start, bot.Position),
                leaseMovementOwner = lease.MovementOwner ?? string.Empty,
                leaseMovementGeneration = lease.MovementGeneration,
                currentMovementOwner = owner.ToString(),
                currentMovementGeneration = generation,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "negativeFollowPathEvidenceCannotOutliveNewPhysicalTraversalBodyObservation"
            });
            return true;
        }

        private static bool TryGetFollowRejectLease(BotOwner bot, out FollowRejectLease lease)
        {
            lease = null;
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowRejectLeases.TryGetValue(profileId, out lease) ||
                lease == null)
            {
                return false;
            }

            if (Time.time > lease.ExpiresAt)
            {
                FollowRejectLeases.Remove(profileId);
                lease = null;
                return false;
            }
            if (TryRetireLearningV420FollowRejectLeaseFromTraversalBodyEpoch(
                    bot, lease, "TryGetFollowRejectLease"))
            {
                lease = null;
                return false;
            }
            return true;
        }

        private static bool TryGetMatchingFollowRejectLease(BotOwner bot, Vector3 target, out FollowRejectLease lease)
        {
            if (!TryGetFollowRejectLease(bot, out lease))
            {
                return false;
            }

            if (Vector3.Distance(lease.Target, target) > FollowRejectLeaseTargetMoveTolerance ||
                Vector3.Distance(lease.Start, bot.Position) > FollowRejectLeaseBotMoveTolerance)
            {
                return false;
            }
            return true;
        }

        private static int FindFollowerRouteStartBreadcrumbSequence(BotOwner bot)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            int routeFloor = GetFollowerRouteResumeFloor(profileId);
            if (!string.IsNullOrEmpty(profileId) &&
                FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) &&
                cursor != null && cursor.ConsumedBreadcrumbSequence > 0)
            {
                return Math.Max(routeFloor, cursor.ConsumedBreadcrumbSequence);
            }

            PlayerBreadcrumbNode bestLocal = null;
            PlayerBreadcrumbNode bestAny = null;
            float bestAnyDistance = float.MaxValue;
            for (int index = BreadcrumbRoute.Count - 1; index >= 0; index--)
            {
                PlayerBreadcrumbNode node = BreadcrumbRoute[index];
                if (node == null || Time.time - node.CreatedAt > BreadcrumbTtlSeconds || !IsOperationalBreadcrumbNode(node))
                {
                    continue;
                }

                float distance = GetPlanarDistance(bot.Position, node.Position);
                if (distance <= 5.5f)
                {
                    if (bestLocal == null || node.Sequence > bestLocal.Sequence)
                    {
                        bestLocal = node;
                    }
                }
                if (distance < bestAnyDistance)
                {
                    bestAnyDistance = distance;
                    bestAny = node;
                }
            }
            return Math.Max(routeFloor, bestLocal?.Sequence ?? bestAny?.Sequence ?? 0);
        }

        // RC61: AreRouteMissionWalkThroughStepsRedundant extracted unchanged to FollowerTraversalRouteMissionLifecycle.cs.

        // RC61: AreRouteMissionPassageStepsRedundant extracted unchanged to FollowerTraversalRouteMissionLifecycle.cs.

        private static FollowerRouteMissionStep SelectRouteMissionPassageWinner(
            FollowerRouteMissionStep first,
            FollowerRouteMissionStep second)
        {
            if (first == null) return second;
            if (second == null) return first;
            bool firstWalk = string.Equals(first.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            bool secondWalk = string.Equals(second.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            if (firstWalk != secondWalk)
            {
                // A real Vault/Climb/Jump/DropDown is the minimum necessary executor for this
                // obstacle. The overlapping WT remains persistent geometry but is not another
                // mandatory step in this particular passage mission.
                return firstWalk ? second : first;
            }
            if (firstWalk && secondWalk)
            {
                float firstSpan = GetPlanarDistance(first.RawEntry, first.RawExit);
                float secondSpan = GetPlanarDistance(second.RawEntry, second.RawExit);
                bool firstMicro = firstSpan < WalkThroughStandalonePersistMinDistance;
                bool secondMicro = secondSpan < WalkThroughStandalonePersistMinDistance;
                if (firstMicro != secondMicro)
                {
                    // Passage geometry beats a micro seam even if the seam was observed a few
                    // breadcrumbs later; the seam remains an internal corridor sample.
                    return firstMicro ? second : first;
                }
            }
            return IsRouteMissionStepFresher(first, second) ? first : second;
        }

        // RC61: IsRouteMissionStepFresher extracted unchanged to FollowerTraversalRouteMissionLifecycle.cs.

        // RC61: TryAddCanonicalRouteMissionStep extracted unchanged to FollowerTraversalRouteMissionLifecycle.cs.

        // CF57: preserve OrderByDescending(EpisodeId).FirstOrDefault() semantics without
        // allocating/sorting an entire chain on each fresh route admission.
        // Equal EpisodeId ties retain the first stream entry (LINQ's stable ordering).
        private static TraversalEpisodeMetadata FindLatestEarlierEpisodeInSameChain(
            TraversalEpisodeMetadata episode)
        {
            if (episode == null || episode.ChainId <= 0)
            {
                return null;
            }
            TraversalEpisodeMetadata latest = null;
            foreach (TraversalEpisodeMetadata item in TraversalEpisodeStream)
            {
                if (item == null || item.ChainId != episode.ChainId || item.EpisodeId >= episode.EpisodeId)
                {
                    continue;
                }
                if (latest == null || item.EpisodeId > latest.EpisodeId)
                {
                    latest = item;
                }
            }
            return latest;
        }

        private static bool HasFreshRaidLocalDropDownAuthority(
            LearnedTraversalEdge edge,
            TraversalEpisodeMetadata episode)
        {
            if (edge == null || episode == null || !edge.Disabled || !edge.PlayerValidated ||
                !string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                episode.EdgeId != edge.Id || episode.ChainId <= 0 ||
                episode.StartBreadcrumbSequence <= 0 || episode.EndBreadcrumbSequence < episode.StartBreadcrumbSequence)
            {
                return false;
            }

            TraversalEpisodeMetadata predecessor = FindLatestEarlierEpisodeInSameChain(episode);
            if (predecessor == null || !string.Equals(predecessor.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 previousExit = IsFinite(predecessor.RawEnd) ? predecessor.RawEnd : predecessor.Exit;
            Vector3 dropEntry = IsFinite(episode.RawStart) ? episode.RawStart : edge.RawStart;
            return IsFinite(previousExit) && IsFinite(dropEntry) &&
                   GetPlanarDistance(previousExit, dropEntry) <= 1.60f &&
                   Mathf.Abs(previousExit.y - dropEntry.y) <= 0.85f;
        }

        private static bool HasLearningV341FreshRaidLocalSemanticSuccessorAuthority(
            LearnedTraversalEdge edge,
            TraversalEpisodeMetadata episode)
        {
            if ((edge == null) || episode == null ||
                !edge.Disabled || !edge.PlayerValidated || episode.EdgeId != edge.Id || episode.ChainId <= 0 ||
                episode.StartBreadcrumbSequence <= 0 || episode.EndBreadcrumbSequence < episode.StartBreadcrumbSequence ||
                (!string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                 !string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            TraversalEpisodeMetadata predecessor = FindLatestEarlierEpisodeInSameChain(episode);
            if (predecessor == null || !IsLearningV340DownstreamBridgeKind(predecessor.Kind) ||
                !IsImmediateTraversalChainSuccessor(predecessor, episode, out _, out _))
            {
                return false;
            }

            Vector3 previousExit = IsFinite(predecessor.RawEnd) ? predecessor.RawEnd : predecessor.Exit;
            Vector3 successorEntry = IsFinite(episode.RawStart) ? episode.RawStart : edge.RawStart;
            return IsFinite(previousExit) && IsFinite(successorEntry) &&
                   GetPlanarDistance(previousExit, successorEntry) <= TraversalChainImmediateMaxSpatialGap;
        }

        private static bool IsLearningV381OrdinaryNavMeshEpisodeWindow(
            TraversalEpisodeMetadata episode,
            out StrictPathResult strictPath,
            out int sampleCount)
        {
            strictPath = null;
            sampleCount = 0;
            if ((episode == null) ||
                episode.StartBreadcrumbSequence <= 0 ||
                episode.EndBreadcrumbSequence < episode.StartBreadcrumbSequence)
            {
                return false;
            }

            List<PlayerBreadcrumbNode> window = BreadcrumbRoute
                .Where(node => node != null &&
                               node.Sequence >= episode.StartBreadcrumbSequence &&
                               node.Sequence <= episode.EndBreadcrumbSequence &&
                               IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            sampleCount = window.Count;
            if (window.Count < 2)
            {
                return false;
            }

            strictPath = CalculateStrictPath(window[0].Position, window[window.Count - 1].Position);
            return IsLearningV369OrdinaryNavMeshRouteWindow(window, strictPath);
        }

        private static bool HasLearningV437JumpEpisodePostLandingRetention(TraversalEpisodeMetadata episode)
        {
            if ((episode == null) ||
                !string.Equals(episode.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            Vector3 direction = GetFlatDirection(episode.RawEnd - episode.RawStart);
            if (direction.sqrMagnitude < 0.5f || episode.EndBreadcrumbSequence <= 0)
            {
                return false;
            }

            int maximumSequence = episode.EndBreadcrumbSequence +
                TraversalChainImmediateMaxBreadcrumbGap * JumpExtendedEgressStableSamples;
            bool groundedLandingObserved = false;
            bool forwardRetentionObserved = false;
            foreach (PlayerBreadcrumbNode node in BreadcrumbRoute)
            {
                if (node == null || !IsFinite(node.Position) ||
                    node.Sequence < episode.EndBreadcrumbSequence || node.Sequence > maximumSequence)
                {
                    continue;
                }

                float planarFromLanding = GetPlanarDistance(node.Position, episode.RawEnd);
                if (planarFromLanding > JumpRollingLandingMaxPlanarDistance)
                {
                    continue;
                }

                if (node.Grounded && !IsTraversalStateName(node.State))
                {
                    groundedLandingObserved = true;
                }

                Vector3 continuation = node.Position - episode.RawEnd;
                continuation.y = 0f;
                if (Vector3.Dot(continuation, direction) >= JumpRollingLandingMinForwardContinuation)
                {
                    forwardRetentionObserved = true;
                }
            }

            if (groundedLandingObserved && forwardRetentionObserved)
            {
                return true;
            }

            // V4.59: the player's already-captured settled egress is the same physical retention
            // fact in a stronger form. V4.37 previously looked only inside a short breadcrumb
            // window after RawEnd, so a legitimate landing followed by a longer same-gesture
            // forward run could be captured into SettledEnd/EgressSamples yet remain forever
            // non-executable in an already-armed RouteMission. Reuse the existing settled-capture
            // contract and the existing minimum forward continuation; do not widen distance/time.
            LearnedTraversalEdge learningV459RetainedJumpEdge = (LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == episode.EdgeId));
            if (learningV459RetainedJumpEdge != null &&
                learningV459RetainedJumpEdge.HasSettledEnd &&
                learningV459RetainedJumpEdge.SettledBreadcrumbSequence > episode.EndBreadcrumbSequence &&
                IsFinite(learningV459RetainedJumpEdge.SettledEnd))
            {
                Vector3 learningV459SettledContinuation =
                    learningV459RetainedJumpEdge.SettledEnd - episode.RawEnd;
                learningV459SettledContinuation.y = 0f;
                float learningV459SettledForwardRetention =
                    Vector3.Dot(learningV459SettledContinuation, direction);
                if (learningV459SettledForwardRetention >= JumpRollingLandingMinForwardContinuation)
                {
                    if (ShouldEmitDiagnostic(
                            "learningV459JumpSettledTailRetention:" +
                            episode.EpisodeId.ToString(CultureInfo.InvariantCulture), null, 0.50f))
                    {
                        WriteEvent("learningV459JumpPostLandingRetentionProvenBySettledTail", null, new
                        {
                            episodeId = episode.EpisodeId,
                            edgeId = episode.EdgeId,
                            chainId = episode.ChainId,
                            rawLanding = Vec(episode.RawEnd),
                            settledExit = Vec(learningV459RetainedJumpEdge.SettledEnd),
                            settledBreadcrumbSequence = learningV459RetainedJumpEdge.SettledBreadcrumbSequence,
                            rawEndBreadcrumbSequence = episode.EndBreadcrumbSequence,
                            settledForwardRetention = learningV459SettledForwardRetention,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
