                    edgeId = edge.Id,
                    episodeId = episode.EpisodeId,
                    chainId = episode.ChainId,
                    startBreadcrumbSequence = episode.StartBreadcrumbSequence,
                    endBreadcrumbSequence = episode.EndBreadcrumbSequence,
                    sampleCount = learningV383NavMeshEpisodeSamples,
                    strictPathLength = learningV383NavMeshEpisodePath?.PathLength ?? 0f,
                    previousSemanticDisproof = LearningV349CurrentRaidSemanticDisproofEdges.Contains(edge.Id),
                    persistentLearningChanged = false,
                    traversalSuccessRecorded = false,
                    action = "exactCurrentEpisodeHealthyNavMeshMeansNoTraversalExecutionDebtHistoricalSemanticRemainsReadable"
