            }

            if ((string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)) &&
                LearningV349CurrentRaidSemanticDisproofEdges.Contains(edge.Id) &&
                IsLearningV381OrdinaryNavMeshEpisodeWindow(
                    episode, out StrictPathResult learningV381NavMeshEpisodePath,
