                LearningV349CurrentRaidSemanticDisproofEdges.Contains(edge.Id) &&
                !((episode.LearningV372HasCurrentExecutionGeometry) &&
                  IsFinite(episode.LearningV372CurrentExecutionStart) &&
                  IsFinite(episode.LearningV372CurrentExecutionEnd)))
            {
