        private static bool TryGetLearningV373ConsolidatedWalkThroughExecutionGeometry(
            TraversalEpisodeMetadata episode,
            out Vector3 executionStart,
            out Vector3 executionEnd,
            out long consolidatedStartSequence,
            out long consolidatedEndSequence,
            out int contributingEpisodes)
        {
            executionStart = default;
            executionEnd = default;
            consolidatedStartSequence = 0;
            consolidatedEndSequence = 0;
            contributingEpisodes = 0;
            if ((episode == null) ||
                !string.Equals(episode.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                episode.ChainId <= 0 || !episode.LearningV372HasCurrentExecutionGeometry ||
                !IsFinite(episode.LearningV372CurrentExecutionStart) ||
                !IsFinite(episode.LearningV372CurrentExecutionEnd))
            {
                return false;
