                episode.LearningV372CurrentExecutionEnd - episode.LearningV372CurrentExecutionStart);
            if (referenceDirection.sqrMagnitude < 0.5f)
            {
                return false;
            }

            long startSequence = episode.StartBreadcrumbSequence;
            long endSequence = episode.EndBreadcrumbSequence;
            bool expanded;
