                        candidate.ChainId != episode.ChainId ||
                        !string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                        !candidate.LearningV372HasCurrentExecutionGeometry ||
                        candidate.StartBreadcrumbSequence <= 0 || candidate.EndBreadcrumbSequence < candidate.StartBreadcrumbSequence ||
                        !IsFinite(candidate.LearningV372CurrentExecutionStart) ||
                        !IsFinite(candidate.LearningV372CurrentExecutionEnd))
                    {
                        continue;
                    }

                    Vector3 candidateDirection = GetFlatDirection(
                        candidate.LearningV372CurrentExecutionEnd - candidate.LearningV372CurrentExecutionStart);
                    if (candidateDirection.sqrMagnitude < 0.5f ||
                        Vector3.Dot(referenceDirection, candidateDirection) < WalkThroughTerminalConnectorMinForwardDot)
                    {
                        continue;
