                        FollowerCapabilityHelperRules.TryGetLearningV373ConsolidatedWalkThroughExecutionGeometry_sequenceConnected_1AC3AAF0_1(candidate.StartBreadcrumbSequence,endSequence,TraversalChainImmediateMaxBreadcrumbGap,candidate.EndBreadcrumbSequence,TraversalChainImmediateMaxBreadcrumbGap,startSequence);
                    if (!sequenceConnected)
