                        continue;
                    }

                    long nextStart = Math.Min(startSequence, candidate.StartBreadcrumbSequence);
                    long nextEnd = Math.Max(endSequence, candidate.EndBreadcrumbSequence);
                    if (nextStart != startSequence || nextEnd != endSequence)
                    {
