                    FollowerCapabilityHelperRules.TryGetLearningV373ConsolidatedWalkThroughExecutionGeometry_sequenceConnected_1AC3AAF0_2(candidate.StartBreadcrumbSequence,endSequence,TraversalChainImmediateMaxBreadcrumbGap,candidate.EndBreadcrumbSequence,TraversalChainImmediateMaxBreadcrumbGap,startSequence);
