                {
                    continue;
                }

                contributingEpisodes++;
                if (earliest == null || candidate.StartBreadcrumbSequence < earliest.StartBreadcrumbSequence ||
                    (candidate.StartBreadcrumbSequence == earliest.StartBreadcrumbSequence && candidate.EpisodeId < earliest.EpisodeId))
                {
                    earliest = candidate;
                }
                if (latest == null || candidate.EndBreadcrumbSequence > latest.EndBreadcrumbSequence ||
                    (candidate.EndBreadcrumbSequence == latest.EndBreadcrumbSequence && candidate.EpisodeId > latest.EpisodeId))
                {
                    latest = candidate;
                }
            }

            if (earliest == null || latest == null)
            {
                return false;
            }

            executionStart = earliest.LearningV372CurrentExecutionStart;
            executionEnd = latest.LearningV372CurrentExecutionEnd;
            consolidatedStartSequence = earliest.StartBreadcrumbSequence;
            consolidatedEndSequence = latest.EndBreadcrumbSequence;
            return IsFinite(executionStart) && IsFinite(executionEnd);
        }

