        private static bool TryRefreshLearningV439JumpStepCurrentEpisodeLandingFrontier(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step)
        {
            if ((step == null) || step.EpisodeId <= 0 || !step.CurrentRaidRouteAuthority ||
                !string.Equals(step.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            TraversalEpisodeMetadata episode = TraversalEpisodeStream.LastOrDefault(item =>
                item != null && item.EpisodeId == step.EpisodeId);
            if (episode == null || episode.ChainId <= 0 ||
                !IsFinite(episode.RawStart) || !IsFinite(episode.RawEnd) ||
                !TryGetNextTraversalEpisode(episode.EpisodeId, out TraversalEpisodeMetadata successor) ||
                successor == null ||
                !IsImmediateTraversalChainSuccessor(
                    episode, successor, out int breadcrumbGap, out float spatialGap) ||
                !IsFinite(successor.RawStart) ||
                GetPlanarDistance(episode.RawEnd, successor.RawStart) >
                    TraversalChainImmediateMaxSpatialGap)
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == step.EdgeId);
            if (edge == null)
            {
                return false;
            }

            Vector3 persistentDirection = GetFlatDirection(edge.RawEnd - edge.RawStart);
            Vector3 episodeDirection = GetFlatDirection(episode.RawEnd - episode.RawStart);
            if (persistentDirection.sqrMagnitude >= 0.5f &&
                episodeDirection.sqrMagnitude >= 0.5f &&
                Vector3.Dot(persistentDirection, episodeDirection) < LearningV2RevisionMinDirectionDot)
            {
                return false;
            }

            bool changed =
                GetPlanarDistance(step.RawExit, episode.RawEnd) > 0.05f ||
                GetPlanarDistance(step.Exit, episode.RawEnd) > 0.05f;
            if (!changed)
            {
                return true;
            }

            Vector3 preservedTakeoffRawEntry = step.RawEntry;
            Vector3 preservedTakeoffEntry = step.Entry;
            Vector3 previousRawExit = step.RawExit;
            step.RawExit = episode.RawEnd;
            step.Exit = episode.RawEnd;
            step.ChainId = episode.ChainId;
            step.ChainLocalExecutable = true;

            WriteEvent("learningV439LateJumpLandingFrontierMaterialized", bot, new
            {
                missionId = mission?.MissionId ?? 0,
                stepIndex = mission?.CurrentStepIndex ?? -1,
                episodeId = episode.EpisodeId,
                edgeId = step.EdgeId,
                chainId = episode.ChainId,
                preservedTakeoffRawEntry = Vec(preservedTakeoffRawEntry),
                preservedTakeoffEntry = Vec(preservedTakeoffEntry),
                previousRawExit = Vec(previousRawExit),
                currentEpisodeRawExit = Vec(step.RawExit),
                successorEpisodeId = successor.EpisodeId,
                successorEdgeId = successor.EdgeId,
                successorKind = successor.Kind ?? string.Empty,
                successorRawEntry = Vec(successor.RawStart),
                breadcrumbGap,
                spatialGap,
                persistentLearningChanged = false,
                traversalSuccessRecorded = false,
                bodyRelocated = false,
                action = "lateSameChainSuccessorRefreshesOnlyRuntimeJumpLandingFrontierProvenTakeoffEntryRemainsUnchanged"
            });
            return true;
        }

        private static PlayerBreadcrumbNode CloneRouteMissionBreadcrumb(PlayerBreadcrumbNode node)
        {
            if (node == null)
            {
                return null;
            }
            return new PlayerBreadcrumbNode
            {
                Sequence = node.Sequence,
                Position = node.Position,
                Direction = node.Direction,
                State = node.State,
                Sprinting = node.Sprinting,
                Grounded = node.Grounded,
                Pose = node.Pose,
                CreatedAt = node.CreatedAt,
                NavMeshSampled = node.NavMeshSampled,
                NavMeshPosition = node.NavMeshPosition
            };
        }

        private static void RefreshRouteMissionBreadcrumbSnapshot(FollowerRouteMission mission)
        {
            if(IsCapabilityFullRouteReplay(mission)||IsCapabilityRouteRetryReturning(mission))return;
            if (mission == null)
            {
                return;
            }

            int lastSequence = mission.RouteBreadcrumbs.Count > 0
                ? mission.RouteBreadcrumbs[mission.RouteBreadcrumbs.Count - 1].Sequence
                : mission.StartBreadcrumbSequence;
            foreach (PlayerBreadcrumbNode node in BreadcrumbRoute)
            {
                if (node == null || node.Sequence <= lastSequence || !IsOperationalBreadcrumbNode(node))
                {
                    continue;
                }
                PlayerBreadcrumbNode copy = CloneRouteMissionBreadcrumb(node);
                if (copy != null)
                {
                    mission.RouteBreadcrumbs.Add(copy);
                }
            }

            // The mission is already a compact per-follower recovery object; retain a long route
            // history even after the global 60-second breadcrumb buffer is pruned. This is what
            // lets a follower consume several Vault/Climb/Jump/WalkThrough episodes in order
            // instead of forgetting the ordinary running segments between them.
            const int maxMissionBreadcrumbs = 1536;
            if (mission.RouteBreadcrumbs.Count > maxMissionBreadcrumbs)
            {
                int protectedSequence = mission.CurrentStepIndex < mission.Steps.Count
                    ? mission.Steps[mission.CurrentStepIndex].StartBreadcrumbSequence
                    : mission.ApproachBreadcrumbSequence;
                int removable = mission.RouteBreadcrumbs
                    .TakeWhile(node => node != null && FollowerCapabilityHelperRules.RefreshRouteMissionBreadcrumbSnapshot_removable_178B8CF4_1(node.Sequence,protectedSequence))
                    .Count();
                removable = Math.Min(removable, mission.RouteBreadcrumbs.Count - maxMissionBreadcrumbs);
                if (removable > 0)
                {
                    mission.RouteBreadcrumbs.RemoveRange(0, removable);
                }
            }
        }

        private static bool TryFindDirectionalWalkThroughBreadcrumbCrossing(
            LearnedTraversalEdge edge,
            IEnumerable<PlayerBreadcrumbNode> sourceNodes,
            int minimumSequenceExclusive,
            int maximumSequenceInclusive,
            out int startSequence,
            out int endSequence,
            out Vector3 observedStart,
            out Vector3 observedEnd,
            List<PlayerBreadcrumbNode> cf36PreparedSortedNodes = null)
        {
            startSequence = 0;
            endSequence = 0;
            observedStart = default(Vector3);
            observedEnd = default(Vector3);
            if (edge == null || sourceNodes == null ||
                !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                (edge.Disabled && false) || !edge.PlayerValidated ||
                !IsFinite(edge.RawStart) || !IsFinite(edge.RawEnd))
            {
                return false;
            }

            Vector3 axis = edge.RawEnd - edge.RawStart;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < 0.35f)
            {
                return false;
            }
            Vector3 direction = axis / span;

            // CF36: cold RouteMission synthesis may inspect many authored WT edges against
            // the same, immutable breadcrumb snapshot/window. Its caller prepares this
            // identical operational, bounded, sequence-ordered candidate list ONCE for
            // that invocation; do not re-run LINQ/OrderBy for each authored edge.
            // The live player crossing detector passes no list and keeps its independent
            // per-call filtering (it has a different and evolving window).
            List<PlayerBreadcrumbNode> nodes = cf36PreparedSortedNodes ?? sourceNodes
                .Where(node => node != null && node.Sequence > minimumSequenceExclusive &&
                               node.Sequence <= maximumSequenceInclusive && IsOperationalBreadcrumbNode(node) &&
                               IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            for (int entryIndex = 0; entryIndex < nodes.Count; entryIndex++)
            {
                PlayerBreadcrumbNode entryNode = nodes[entryIndex];
                if (GetPlanarDistance(entryNode.Position, edge.RawStart) > RouteMissionDirectionalWalkThroughEntryRadius ||
                    Mathf.Abs(entryNode.Position.y - edge.RawStart.y) > RouteMissionDirectionalWalkThroughVerticalTolerance)
                {
                    continue;
                }

                for (int exitIndex = entryIndex + 1; exitIndex < nodes.Count; exitIndex++)
                {
                    PlayerBreadcrumbNode exitNode = nodes[exitIndex];
                    if (exitNode.CreatedAt - entryNode.CreatedAt > RouteMissionDirectionalWalkThroughMaxSeconds)
                    {
                        break;
                    }
                    if (GetPlanarDistance(exitNode.Position, edge.RawEnd) > RouteMissionDirectionalWalkThroughExitRadius ||
                        Mathf.Abs(exitNode.Position.y - edge.RawEnd.y) > RouteMissionDirectionalWalkThroughVerticalTolerance)
                    {
                        continue;
                    }

                    Vector3 fromEntry = exitNode.Position - edge.RawStart;
                    fromEntry.y = 0f;
                    float projection = Vector3.Dot(fromEntry, direction);
                    Vector3 lateralVector = fromEntry - direction * projection;
                    if (projection < span * RouteMissionDirectionalWalkThroughMinProgressRatio ||
                        lateralVector.magnitude > RouteMissionDirectionalWalkThroughMaxLateral)
                    {
                        continue;
                    }

                    // V3.21: endpoint-radius overlap is not directional traversal proof. V3.20 runtime
                    // synthesized reciprocal edges 44/48 from the same forward breadcrumb passage,
                    // then composed them into a U-turn. Require the OBSERVED entry->exit displacement
                    // to agree with the authored edge direction. Reuse the established rolling forward
                    // semantic threshold rather than introducing a new map/edge-specific tolerance.
                    {
                        Vector3 observedMotion = exitNode.Position - entryNode.Position;
                        observedMotion.y = 0f;
                        float observedDistance = observedMotion.magnitude;
                        if (observedDistance <= 0.01f ||
                            Vector3.Dot(observedMotion / observedDistance, direction) < RollingTraversalMinForwardDot)
                        {
                            continue;
                        }
                    }

                    startSequence = entryNode.Sequence;
                    endSequence = exitNode.Sequence;
                    observedStart = entryNode.Position;
                    observedEnd = exitNode.Position;
                    return true;
                }
            }
            return false;
        }

        private static bool IsLearningV349CurrentRaidOrdinaryWalkThroughDisproof(
            LearnedTraversalEdge semanticEdge,
            int startSequence,
            int endSequence,
            Vector3 observedStart,
            Vector3 observedEnd,
            out StrictPathResult strictPath,
            out int ordinarySampleCount,
            out float localBypassCost,
            out float localBypassRatio)
        {
            strictPath = null;
            ordinarySampleCount = 0;
            localBypassCost = 0f;
            localBypassRatio = 0f;
            if(FollowerCapabilityPosturePolicy.Crouched(semanticEdge?.RequiredPose??1f))return false;
            if ((startSequence <= 0) || endSequence < startSequence ||
                !IsFinite(observedStart) || !IsFinite(observedEnd))
            {
                return false;
            }

            // CF52: the original two LastOrDefault calls each scanned the complete
            // breadcrumb history. One reverse pass preserves the exact *last matching*
            // identity (including duplicate sequences), without caching a NavMesh
            // result or changing the evidence/disproof authority of either node.
            PlayerBreadcrumbNode crossingStart = null;
            PlayerBreadcrumbNode crossingEnd = null;
            for (int cf52Index = BreadcrumbRoute.Count - 1; cf52Index >= 0; cf52Index--)
            {
                PlayerBreadcrumbNode cf52Node = BreadcrumbRoute[cf52Index];
                if (cf52Node == null)
                {
                    continue;
                }
                if (crossingEnd == null && cf52Node.Sequence == endSequence)
                {
                    crossingEnd = cf52Node;
                }
                if (crossingStart == null && cf52Node.Sequence == startSequence)
                {
                    crossingStart = cf52Node;
                }
                if (crossingStart != null && crossingEnd != null)
                {
                    break;
                }
            }
            if (crossingStart == null || crossingEnd == null)
            {
                return false;
            }

            {
                // V3.49/V3.69 used broad before/after NavMesh continuity as current-raid anti-evidence.
                // That is insufficient for a narrow door: NavMesh may offer a nearby shoulder detour
                // while the exact demonstrated passage still requires physical WT execution. Reuse the
                // existing V3.18 local-bypass geometry and its established ratio contract, but require
                // the bypass to be near-direct before it can ERASE typed WT debt. The older absolute
                // allowance remains useful for discovery, but cannot by itself disprove empirical WT.
                Vector3 localStart = semanticEdge != null && IsFinite(semanticEdge.RawStart)
                    ? semanticEdge.RawStart
                    : observedStart;
                Vector3 localEnd = semanticEdge != null && IsFinite(semanticEdge.RawEnd)
                    ? semanticEdge.RawEnd
                    : observedEnd;
                float localDirect = GetPlanarDistance(localStart, localEnd);
                bool localBypassFound = localDirect >= 0.20f &&
                    TryFindCheapLocalWalkThroughBypass(
                        localStart, localEnd,
                        out localBypassCost, out _, out _, out _);
                localBypassRatio = localBypassFound && localDirect > 0.01f
                    ? localBypassCost / localDirect
                    : 0f;
                if (!localBypassFound || localBypassRatio > WalkThroughLocalBypassRatio)
                {
                    if (semanticEdge != null && ShouldEmitDiagnostic(
                            "learningV378WalkThroughDisproofRejectedByLocalTopology:" +
                                semanticEdge.Id.ToString(CultureInfo.InvariantCulture), null, 0.25f))
                    {
                        WriteEvent("learningV378CurrentRaidWalkThroughDisproofRejectedByLocalTopology", null, new
                        {
                            edgeId = semanticEdge.Id,
                            experienceKey = semanticEdge.ExperienceKey,
                            localStart = Vec(localStart),
                            localEnd = Vec(localEnd),
                            localDirectDistance = localDirect,
                            localBypassFound,
                            localBypassCost,
                            localBypassRatio,
                            localBypassRatioLimit = WalkThroughLocalBypassRatio,
                            persistentLearningChanged = false,
                            traversalSuccessRecorded = false,
                            action = "nearbyDetourCannotDisproveExactPhysicalWalkThroughPassage"
                        });
                    }
                    return false;
                }
            }

            // A short PathComplete between WT endpoints is not enough to disprove historical
            // passage truth. Require ordinary route continuity on BOTH sides of the candidate,
            // using the existing directional-WT time envelope. This distinguishes an edge embedded
            // in a continuous slope/route from a doorway/seam whose local samples happen to touch
            // nearby NavMesh while the surrounding route still breaks or detours.
            float minimumTime = crossingStart.CreatedAt - RouteMissionDirectionalWalkThroughMaxSeconds;
            float maximumTime = crossingEnd.CreatedAt + RouteMissionDirectionalWalkThroughMaxSeconds;
            List<PlayerBreadcrumbNode> samples = BreadcrumbRoute
                .Where(node => node != null && node.CreatedAt >= minimumTime && node.CreatedAt <= maximumTime &&
                               IsOperationalBreadcrumbNode(node) && IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            if (samples.Count < 4 || samples[0].Sequence >= startSequence ||
                samples[samples.Count - 1].Sequence <= endSequence ||
                samples.Any(node => !node.NavMeshSampled || !IsFinite(node.NavMeshPosition)))
            {
                return false;
            }

            ordinarySampleCount = samples.Count;
            Vector3 contextStart = samples[0].Position;
            Vector3 contextEnd = samples[samples.Count - 1].Position;
            strictPath = CalculateStrictPath(contextStart, contextEnd);
            float directDistance = Vector3.Distance(contextStart, contextEnd);
            float allowedPathLength = GetAllowedFollowPathLength(directDistance, true);
            return strictPath != null && strictPath.StrictComplete &&
                   strictPath.PathLength <= allowedPathLength;
        }

        private static void RegisterLearningV347KnownWalkThroughCrossings(PlayerBreadcrumbNode newestNode)
        {
            if ((newestNode == null) ||
                BreadcrumbRoute.Count < 2 || !IsOperationalBreadcrumbNode(newestNode))
            {
                return;
            }

            int floor = Math.Max(0, newestNode.Sequence - RouteMissionDirectionalWalkThroughLookbackBreadcrumbs);
            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges
                .Where(candidate => candidate != null && candidate.PlayerValidated &&
                                    string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                .OrderBy(candidate => candidate.Id))
            {
                // Cheap spatial prefilter: only inspect a known passage when the newest player body
                // sample is actually near its authored far side. This avoids a broad per-frame route scan.
                if (!IsFinite(edge.RawEnd) ||
                    GetPlanarDistance(newestNode.Position, edge.RawEnd) > RouteMissionDirectionalWalkThroughExitRadius ||
                    Mathf.Abs(newestNode.Position.y - edge.RawEnd.y) > RouteMissionDirectionalWalkThroughVerticalTolerance)
                {
                    continue;
                }

                bool alreadyRegistered = TraversalEpisodeStream.Any(item =>
                    item != null && item.EdgeId == edge.Id &&
                    item.StartBreadcrumbSequence > floor &&
                    item.EndBreadcrumbSequence >= item.StartBreadcrumbSequence &&
                    item.EndBreadcrumbSequence <= newestNode.Sequence);
                if (alreadyRegistered)
                {
                    continue;
                }

                if (!TryFindDirectionalWalkThroughBreadcrumbCrossing(
                        edge,
                        BreadcrumbRoute,
                        floor,
                        newestNode.Sequence,
                        out int crossingStartSequence,
                        out int crossingEndSequence,
                        out Vector3 observedStart,
                        out Vector3 observedEnd))
                {
                    continue;
                }

                {
                    // V3.66 identity must converge at the producer, not only later during mission
                    // synthesis. V365 could register End=N / Start=N+1 as a brand-new episode for
                    // the same directed edge, which bypassed a follower's already-completed execution
                    // frontier before RouteMission had any chance to canonicalize it. Suppress only
                    // a contiguous tail re-observation of the SAME directed edge; a later true repeat
                    // after a route reversal receives a non-contiguous episode as before.
                    TraversalEpisodeMetadata contiguousEpisode = TraversalEpisodeStream
                        .Where(item => item != null && item.EdgeId == edge.Id &&
                                       item.StartBreadcrumbSequence > 0 && item.EndBreadcrumbSequence > 0 &&
                                       crossingStartSequence >= item.EndBreadcrumbSequence &&
                                       crossingStartSequence - item.EndBreadcrumbSequence <=
                                           TraversalChainImmediateMaxBreadcrumbGap)
                        .OrderByDescending(item => item.EndBreadcrumbSequence)
                        .ThenByDescending(item => item.EpisodeId)
                        .FirstOrDefault();
                    if (contiguousEpisode != null)
                    {
                        WriteEvent("learningV366ContiguousDirectedEpisodeRegistrationSuppressed", null, new
                        {
                            edgeId = edge.Id,
                            reusedEpisodeId = contiguousEpisode.EpisodeId,
                            previousStartBreadcrumbSequence = contiguousEpisode.StartBreadcrumbSequence,
                            previousEndBreadcrumbSequence = contiguousEpisode.EndBreadcrumbSequence,
                            observedStartBreadcrumbSequence = crossingStartSequence,
                            observedEndBreadcrumbSequence = crossingEndSequence,
                            gap = crossingStartSequence - contiguousEpisode.EndBreadcrumbSequence,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "sameDirectedContiguousObservationDoesNotMintNewRouteDebt"
                        });
                        continue;
                    }
                }

                if ((newestNode.Sequence <= crossingEndSequence))
                {
                    if (ShouldEmitDiagnostic(
                        "learningV369KnownWalkThroughCrossingDeferredForPostContext:" +
                            edge.Id.ToString(CultureInfo.InvariantCulture) + ":" +
                            crossingEndSequence.ToString(CultureInfo.InvariantCulture), null, 0.25f))
                    {
                        WriteEvent("learningV369KnownWalkThroughCrossingDeferredForPostContext", null, new
                        {
                            edgeId = edge.Id,
                            startBreadcrumbSequence = crossingStartSequence,
                            endBreadcrumbSequence = crossingEndSequence,
                            newestBreadcrumbSequence = newestNode.Sequence,
                            persistentLearningChanged = false,
                            action = "waitOneOperationalBreadcrumbBeforeTypedAdmissionSoOrdinaryRouteAntiEvidenceCanExist"
                        });
                    }
                    continue;
                }

                if (IsLearningV349CurrentRaidOrdinaryWalkThroughDisproof(
                        edge, crossingStartSequence, crossingEndSequence, observedStart, observedEnd,
                        out StrictPathResult learningV349DisproofPath, out int learningV349OrdinarySamples,
                        out float learningV378LocalBypassCost, out float learningV378LocalBypassRatio))
                {
                    LearningV349CurrentRaidSemanticDisproofEdges.Add(edge.Id);
                    WriteEvent("learningV349CurrentRaidWalkThroughSemanticDisproved", null, new
                    {
                        edgeId = edge.Id,
                        experienceKey = edge.ExperienceKey,
                        startBreadcrumbSequence = crossingStartSequence,
                        endBreadcrumbSequence = crossingEndSequence,
                        observedStart = Vec(observedStart),
                        observedEnd = Vec(observedEnd),
                        ordinarySampleCount = learningV349OrdinarySamples,
                        localBypassCost = learningV378LocalBypassCost,
                        localBypassRatio = learningV378LocalBypassRatio,
                        localBypassRatioLimit = WalkThroughLocalBypassRatio,
                        strictPathStatus = learningV349DisproofPath.Status.ToString(),
                        strictPathLength = learningV349DisproofPath.PathLength,
                        directDistance = Vector3.Distance(observedStart, observedEnd),
                        persistentLearningChanged = false,
                        action = ("nearDirectLocalNavMeshPlusBroadCurrentRaidContinuitySuppressesPersistentWalkThroughAdmissionOnlyForThisRaid")
                    });
                    continue;
                }

                TraversalEpisodeMetadata episode = RegisterTraversalEpisodeForEdge(
                    edge.Id,
                    "WalkThrough",
                    edge.RawStart,
                    edge.RawEnd,
                    crossingStartSequence,
                    crossingEndSequence,
                    allowChain: true);
                if (episode != null)
                {
                    ApplyLearningV372CurrentEpisodeWalkThroughExecutionGeometry(
                        null, episode, edge, observedStart, observedEnd,
                        "knownWalkThroughCurrentRaidCrossing");
                    WriteEvent("learningV347KnownWalkThroughCurrentRaidCrossingRegistered", null, new
                    {
                        episodeId = episode.EpisodeId,
                        edgeId = edge.Id,
                        chainId = episode.ChainId,
                        persistentDisabled = edge.Disabled,
                        historicalSemanticAuthority = edge.HistoricalSemanticAuthority,
                        startBreadcrumbSequence = crossingStartSequence,
                        endBreadcrumbSequence = crossingEndSequence,
                        observedStart = Vec(observedStart),
                        observedEnd = Vec(observedEnd),
                        action = "currentPlayerPhysicalCrossingCreatesRuntimeRouteFactBeforePlannerAdmission"
                    });
                }
            }
        }

        // Current-episode geometry publication is owned by FollowerCapabilityIngressGeometryHost: ApplyLearningV372CurrentEpisodeWalkThroughExecutionGeometry.

        private static bool IsLearningV366RuntimeEpisodeBehindExecutionFrontier(
            BotOwner bot,
            TraversalEpisodeMetadata episode)
        {
            if(episode!=null&&IsCapabilityDebtResolved(bot,episode.EpisodeId,episode.EdgeId))return true;
            string profileId = bot?.ProfileId ?? string.Empty;
            if ((episode == null) ||
                string.IsNullOrEmpty(profileId))
            {
                return false;
            }

            // CF41: the consumed physical/semantic floor survives a missing route cursor.
            // During post-Follow handoff a contiguous WT tail (e.g. 923..924) can alias an
            // already-consumed episode (915..922). Requiring a cursor first resurrected its
            // old execution debt, built an empty mission, then skipped it by resume floor.
            // Read the authoritative per-follower floors independently of cursor lifetime;
            // only the extra exact chain/episode completion witness needs the cursor.
            int executionFloor = Math.Max(
                GetFollowerRouteResumeFloor(profileId),
                GetFollowerRouteExecutionFloor(profileId));
            bool hasCursor = FollowerTraversalRouteCursors.TryGetValue(
                profileId, out FollowerTraversalRouteCursor cursor) && cursor != null;
            if (hasCursor)
            {
                executionFloor = Math.Max(executionFloor, cursor.ConsumedBreadcrumbSequence);
            }
            if (episode.EndBreadcrumbSequence > 0 &&
                episode.EndBreadcrumbSequence <= executionFloor)
            {
                return true;
            }
            return hasCursor && cursor.LastCompletedChainId == episode.ChainId &&
                   cursor.LastCompletedEpisodeId == episode.EpisodeId;
        }

        private static int AppendDirectionalWalkThroughRouteStepsFromBreadcrumbs(
            BotOwner bot,
            FollowerRouteMission mission,
            int scanFloorSequence,
            string source)
        {
            if (bot == null || mission == null || mission.RouteBreadcrumbs == null || mission.RouteBreadcrumbs.Count == 0)
            {
                return 0;
            }

            int ceilingSequence = breadcrumbSequence;
            int floor = Math.Max(
                mission.ResumeFloorBreadcrumbSequence,
                Math.Max(0, scanFloorSequence - RouteMissionDirectionalWalkThroughLookbackBreadcrumbs));
            HashSet<int> liveStepEpisodes = new HashSet<int>(mission.Steps.Where(step => step != null).Select(step => step.EpisodeId));
            int added = 0;
            // CF36: prepare lazily only if an authored WT reaches crossing inspection;
            // reuse for all edges in this ONE cold/refresh invocation. Never persist a
            // negative result across breadcrumbs or missions (V370 Phase 3 admission).
            List<PlayerBreadcrumbNode> cf36PreparedCrossingNodes = null;

            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges
                .Where(candidate => candidate != null && candidate.PlayerValidated &&
                                    string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                .OrderBy(candidate => candidate.Id))
            {
                // V3.47: do not ask persistent/global topology policy before observing the player's
                // current-raid crossing. A persistently Disabled historical WT can be the exact
                // passage demonstrated now; filtering it here made current-route authority
                // impossible to create (self-denying admission). Persistent state remains unchanged.
                // V3.49 adds equally direct current-raid anti-evidence: when the player crossed the
                // same geometry as ordinary operational locomotion over a healthy continuous NavMesh
                // connector, do not synthesize a typed WT from stale persistence in this raid.
                if (LearningV349CurrentRaidSemanticDisproofEdges.Contains(edge.Id))
                {
                    continue;
                }
                bool alreadyFresh = mission.Steps.Any(step => step != null && step.EdgeId == edge.Id &&
                    step.StartBreadcrumbSequence > floor && step.EndBreadcrumbSequence <= ceilingSequence);
                if (alreadyFresh)
                {
                    continue;
                }

                if (cf36PreparedCrossingNodes == null)
                {
                    // Exactly the predicate/order used by the original crossing helper.
                    // The route breadcrumb snapshot is immutable within this method.
                    cf36PreparedCrossingNodes = mission.RouteBreadcrumbs
                        .Where(node => node != null && node.Sequence > floor &&
                                       node.Sequence <= ceilingSequence && IsOperationalBreadcrumbNode(node) &&
                                       IsFinite(node.Position))
                        .OrderBy(node => node.Sequence)
                        .ToList();
                }
                if (!TryFindDirectionalWalkThroughBreadcrumbCrossing(
                        edge,
                        mission.RouteBreadcrumbs,
                        floor,
                        ceilingSequence,
                        out int crossingStartSequence,
                        out int crossingEndSequence,
                        out Vector3 observedStart,
                        out Vector3 observedEnd,
                        cf36PreparedCrossingNodes))
                {
                    continue;
                }

                if ((ceilingSequence <= crossingEndSequence))
                {
                    continue;
                }
                if (IsLearningV349CurrentRaidOrdinaryWalkThroughDisproof(
                        edge, crossingStartSequence, crossingEndSequence, observedStart, observedEnd,
                        out StrictPathResult learningV369DisproofPath, out int learningV369OrdinarySamples,
                        out float learningV378DeferredLocalBypassCost, out float learningV378DeferredLocalBypassRatio))
                {
                    LearningV349CurrentRaidSemanticDisproofEdges.Add(edge.Id);
                    WriteEvent("learningV369DeferredCurrentRaidWalkThroughSemanticDisproved", bot, new
                    {
                        missionId = mission.MissionId,
                        edgeId = edge.Id,
                        startBreadcrumbSequence = crossingStartSequence,
                        endBreadcrumbSequence = crossingEndSequence,
                        ordinarySampleCount = learningV369OrdinarySamples,
                        localBypassCost = learningV378DeferredLocalBypassCost,
                        localBypassRatio = learningV378DeferredLocalBypassRatio,
                        localBypassRatioLimit = WalkThroughLocalBypassRatio,
                        strictPathStatus = learningV369DisproofPath.Status.ToString(),
                        strictPathLength = learningV369DisproofPath.PathLength,
                        persistentLearningChanged = false,
                        action = ("nearDirectLocalNavMeshPlusBroadContextSuppressesTypedWalkThroughAfterPostCrossingContext")
                    });
                    continue;
                }

                TraversalEpisodeMetadata existingEpisode = TraversalEpisodeStream
                    .Where(item => item != null && item.EdgeId == edge.Id &&
                                   item.StartBreadcrumbSequence > 0 && item.EndBreadcrumbSequence > 0 &&
                                   item.StartBreadcrumbSequence <= crossingEndSequence &&
                                   item.EndBreadcrumbSequence >= crossingStartSequence)
                    .OrderByDescending(item => item.EpisodeId)
                    .FirstOrDefault();
                bool learningV366ContiguousAlias = false;
                if ((existingEpisode == null))
                {
                    // Directional breadcrumb synthesis can observe the tail of a passage one sample
                    // after the original detector closed it. V365 treated End=N / Start=N+1 as a
                    // brand-new episode even when the directed edge was identical, bypassing the
                    // completed execution frontier and recreating debt for an action already done.
                    existingEpisode = TraversalEpisodeStream
                        .Where(item => item != null && item.EdgeId == edge.Id &&
                                       item.StartBreadcrumbSequence > 0 && item.EndBreadcrumbSequence > 0 &&
                                       crossingStartSequence >= item.EndBreadcrumbSequence &&
                                       crossingStartSequence - item.EndBreadcrumbSequence <=
                                           TraversalChainImmediateMaxBreadcrumbGap)
                        .OrderByDescending(item => item.EndBreadcrumbSequence)
                        .ThenByDescending(item => item.EpisodeId)
                        .FirstOrDefault();
                    learningV366ContiguousAlias = existingEpisode != null;
                    if (learningV366ContiguousAlias)
                    {
                        WriteEvent("learningV366ContiguousDirectedEpisodeAliasReused", bot, new
                        {
                            missionId = mission.MissionId,
                            edgeId = edge.Id,
                            reusedEpisodeId = existingEpisode.EpisodeId,
                            previousStartBreadcrumbSequence = existingEpisode.StartBreadcrumbSequence,
                            previousEndBreadcrumbSequence = existingEpisode.EndBreadcrumbSequence,
                            observedStartBreadcrumbSequence = crossingStartSequence,
                            observedEndBreadcrumbSequence = crossingEndSequence,
                            gap = crossingStartSequence - existingEpisode.EndBreadcrumbSequence,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "sameDirectedRuntimePassageKeepsOneExecutionIdentity"
                        });
                    }
                }
                if (learningV366ContiguousAlias &&
                    IsLearningV366RuntimeEpisodeBehindExecutionFrontier(bot, existingEpisode))
                {
                    WriteEvent("learningV366ContiguousDirectedEpisodeAlreadyConsumed", bot, new
                    {
                        missionId = mission.MissionId,
                        edgeId = edge.Id,
                        episodeId = existingEpisode.EpisodeId,
                        observedStartBreadcrumbSequence = crossingStartSequence,
                        observedEndBreadcrumbSequence = crossingEndSequence,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "doNotRecreateExecutionDebtBehindFollowerFrontier"
                    });
                    continue;
                }
                // CF47: an exact current-raid episode whose WT debt was already
                // retired by V386 cannot become executable again by re-observing
                // later breadcrumbs.  Skip redundant geometry updates as well as
                // downstream step admission; a NEW episode is never filtered here.
                if ((existingEpisode != null) &&
                    string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                    existingEpisode.LearningV386ExecutionDebtRetiredByOrdinaryNavMesh)
                {
                    continue;
                }
                TraversalEpisodeMetadata episode = existingEpisode ?? RegisterTraversalEpisodeForEdge(
                    edge.Id,
                    "WalkThrough",
                    edge.RawStart,
                    edge.RawEnd,
                    crossingStartSequence,
                    crossingEndSequence,
                    allowChain: false);
                ApplyLearningV372CurrentEpisodeWalkThroughExecutionGeometry(
                    bot, episode, edge, observedStart, observedEnd,
                    "directionalWalkThroughMissionSynthesis");
                if (episode == null || liveStepEpisodes.Contains(episode.EpisodeId))
                {
                    continue;
                }
                // CF46: V384's verified ordinary-NavMesh refusal is already a canonical V386
                // episode-level retirement, not just a one-call synthesis decision. A later
                // mission must not synthesize the same WT debt or re-run expensive topology
                // proof when that exact episode has already been retired. New episode IDs
                // remain fully eligible; no persistent learned edge is disabled or changed.
                if ((string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)) &&
                    episode.LearningV386ExecutionDebtRetiredByOrdinaryNavMesh)
                {
                    continue;
                }
                if ((string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)) &&
                    IsLearningV381OrdinaryNavMeshEpisodeWindow(
                        episode, out StrictPathResult learningV384DirectionalNavMeshPath,
                        out int learningV384DirectionalNavMeshSamples))
                {
                    // CF46: publish the same exact-episode retirement used by V383/V385.
                    // The strict NavMesh window proof must succeed before this write;
                    // unresolved or geometrically disconnected crossings are not retired.
                    {
                        episode.LearningV386ExecutionDebtRetiredByOrdinaryNavMesh = true;
                        episode.LearningV386ExecutionDebtRetirementSource =
                            "cf46DirectionalWalkThroughHealthyCurrentEpisodeNavMesh";
                    }
                    // CF54 diagnostic only: a local start->end NavMesh witness says nothing
                    // about whether the follower's present approach to the start is viable.
                    // Do not promote the edge, defeat the V386 retirement, or invent a path.
                    StrictPathResult cf54BodyApproach =
                        bot != null && IsFinite(bot.Position) && IsFinite(episode.RawStart)
                            ? CalculateStrictPath(bot.Position, episode.RawStart)
                            : null;
                    if (ShouldEmitDiagnostic(
                            "cf54RetiredWalkThroughApproachWitness:" +
                                episode.EpisodeId.ToString(CultureInfo.InvariantCulture), bot, 2f))
                    {
                        WriteEvent("cf54RetiredWalkThroughFollowerApproachWitness", bot, new
                        {
                            missionId = mission.MissionId,
                            episodeId = episode.EpisodeId,
                            edgeId = edge.Id,
                            chainId = episode.ChainId,
                            bodyToEntryDistance = bot != null && IsFinite(bot.Position)
                                ? GetPlanarDistance(bot.Position, episode.RawStart) : -1f,
                            bodyApproachPathComplete = cf54BodyApproach?.StrictComplete ?? false,
                            bodyApproachPathLength = cf54BodyApproach?.PathLength ?? 0f,
                            localWindowPathLength = learningV384DirectionalNavMeshPath?.PathLength ?? 0f,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "recordLiveFollowerApproachSeparatelyFromPlayerLocalNavMeshProofNoAdmissionMutation"
                        });
                    }
                    WriteEvent("learningV384DirectionalWalkThroughSynthesisRetiredByCurrentNavMesh", bot, new
                    {
                        missionId = mission.MissionId,
                        episodeId = episode.EpisodeId,
                        edgeId = edge.Id,
                        chainId = episode.ChainId,
                        sampleCount = learningV384DirectionalNavMeshSamples,
                        strictPathLength = learningV384DirectionalNavMeshPath?.PathLength ?? 0f,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "currentEpisodeHealthyNavMeshNecessityProofAppliesBeforeDirectionalStepCreation"
                    });
                    continue;
                }

                FollowerRouteMissionStep synthesized = CreateFollowerRouteMissionStep(episode);
                if (synthesized == null)
                {
                    EmitLearningV347TraversalEpisodeRejectedBeforeMission(
                        bot, episode, "directionalWalkThroughSynthesis", "stepCreationRejected");
                    continue;
                }
                if (!IsTraversalEdgeTopologicallySelectableForRouteStep(
                        bot, edge, synthesized, out string synthesizedPolicyReason))
                {
                    EmitLearningV347TraversalOpportunityNoStart(
                        bot, mission, synthesized, "directionalWalkThroughSynthesisSelector", synthesizedPolicyReason);
                    continue;
                }
                if (!AddLifecycleMissionStep(mission, synthesized))
                {
                    EmitLearningV347TraversalOpportunityNoStart(
                        bot, mission, synthesized, "directionalWalkThroughCanonicalization",
                        "redundantWithEquivalentRouteStep");
                    continue;
                }
                liveStepEpisodes.Add(episode.EpisodeId);
                mission.LastPlayerEpisodeId = Math.Max(mission.LastPlayerEpisodeId, episode.EpisodeId);
                mission.TargetBreadcrumbSequence = Math.Max(mission.TargetBreadcrumbSequence, crossingEndSequence);
                added++;
                WriteEvent("followerRouteMissionDirectionalWalkThroughSynthesized", bot, new
                {
                    missionId = mission.MissionId,
                    source = source ?? "breadcrumbDirectionalCrossing",
                    episodeId = episode.EpisodeId,
                    edgeId = edge.Id,
                    kind = edge.Kind,
                    startBreadcrumbSequence = crossingStartSequence,
                    endBreadcrumbSequence = crossingEndSequence,
                    observedStart = Vec(observedStart),
                    observedEnd = Vec(observedEnd),
                    entry = Vec(synthesized.Entry),
                    exit = Vec(synthesized.Exit)
                });
            }

            if (added > 0)
            {
                SetLifecycleMissionSteps(mission, mission.Steps
                    .Where(step => step != null)
                    .OrderBy(step => step.StartBreadcrumbSequence)
                    .ThenBy(step => step.EpisodeId)
                    .ToList());
                ApplyLearningV366DirectedPhysicalStepOrder(bot, mission, "directionalWalkThroughSynthesis");
            }
            return added;
        }

        private static void ApplyLearningV366DirectedPhysicalStepOrder(
            BotOwner bot,
            FollowerRouteMission mission,
            string source)
        {
            if ((mission?.Steps == null) ||
                mission.Steps.Count < 2)
            {
                return;
            }

            // Breadcrumb timestamps from independent detectors can overlap by one or two samples.
            // Sequence order is therefore not a physical ordering oracle by itself. Only reverse
            // two adjacent same-chain steps when endpoint connectivity proves B->A and not A->B,
            // reusing the existing immediate-chain gap/geometry contract rather than adding a
            // site/action-pair rule or a new tolerance.
            bool changed = false;
            for (int pass = 0; pass < mission.Steps.Count; pass++)
            {
                bool passChanged = false;
                for (int index = Math.Max(0, mission.CurrentStepIndex);
                     index + 1 < mission.Steps.Count; index++)
                {
                    FollowerRouteMissionStep first = mission.Steps[index];
                    FollowerRouteMissionStep second = mission.Steps[index + 1];
                    if (first == null || second == null || first.ChainId <= 0 ||
                        first.ChainId != second.ChainId)
                    {
                        continue;
                    }

                    int sequenceGap = Math.Max(0,
                        first.StartBreadcrumbSequence - second.EndBreadcrumbSequence);
                    int reverseSequenceGap = Math.Max(0,
                        second.StartBreadcrumbSequence - first.EndBreadcrumbSequence);
                    if (Math.Min(sequenceGap, reverseSequenceGap) >
                        TraversalChainImmediateMaxBreadcrumbGap)
                    {
                        continue;
                    }

                    float firstToSecond = IsFinite(first.RawExit) && IsFinite(second.RawEntry)
                        ? Vector3.Distance(first.RawExit, second.RawEntry)
                        : float.PositiveInfinity;
                    float secondToFirst = IsFinite(second.RawExit) && IsFinite(first.RawEntry)
                        ? Vector3.Distance(second.RawExit, first.RawEntry)
                        : float.PositiveInfinity;
                    bool authoredForward = firstToSecond <= TraversalChainImmediateMaxSpatialGap;
                    bool authoredReverse = secondToFirst <= TraversalChainImmediateMaxSpatialGap;
                    if (!authoredReverse || authoredForward)
                    {
                        continue;
                    }

                    if (!SwapLifecycleMissionSteps(mission,index,index+1)) continue;
                    passChanged = true;
                    changed = true;
                    WriteEvent("learningV366DirectedPhysicalStepReordered", bot, new
                    {
                        missionId = mission.MissionId,
                        source = source ?? "routeMission",
                        previousFirstEpisodeId = first.EpisodeId,
                        previousFirstEdgeId = first.EdgeId,
                        previousFirstKind = first.Kind,
                        previousSecondEpisodeId = second.EpisodeId,
                        previousSecondEdgeId = second.EdgeId,
                        previousSecondKind = second.Kind,
                        firstToSecondDistance = firstToSecond,
                        secondToFirstDistance = secondToFirst,
                        action = "endpointConnectivityOverridesOverlappingDetectorSequenceOrder"
                    });
                }
                if (!passChanged)
                {
                    break;
                }
            }

            if (changed)
            {
                // Cursor is preserved by the structural edit operation.
            }
        }

        private static bool IsLearningV368LateSameChainMissionExtension(
            FollowerRouteMission mission,
            TraversalEpisodeMetadata episode,
            int previousLastPlayerEpisodeId,
            int executionFloor,
            out FollowerRouteMissionStep predecessor,
            out int breadcrumbGap,
            out float spatialGap)
        {
            predecessor = null;
            breadcrumbGap = int.MaxValue;
            spatialGap = float.PositiveInfinity;
            if ((mission?.Steps == null) || episode == null ||
                !FollowerCapabilityPreparationPolicy.CanMaterialize(episode.EpisodeId,
                    mission.Steps.Any(item => item != null && item.EpisodeId == episode.EpisodeId),
                    episode.EndBreadcrumbSequence, executionFloor) || episode.ChainId <= 0 ||
                episode.EndBreadcrumbSequence <= executionFloor)
            {
                return false;
            }

            predecessor = mission.Steps
                .Where(step => step != null && step.ChainId == episode.ChainId)
                .OrderByDescending(step => step.EndBreadcrumbSequence)
                .ThenByDescending(step => step.EpisodeId)
                .FirstOrDefault();
            if (predecessor == null || predecessor.EndBreadcrumbSequence <= 0 ||
                episode.StartBreadcrumbSequence <= 0 ||
                episode.EndBreadcrumbSequence <= predecessor.EndBreadcrumbSequence)
            {
                return false;
            }

            breadcrumbGap = (GetLearningV442InterveningBreadcrumbCount(
                    predecessor.EndBreadcrumbSequence, episode.StartBreadcrumbSequence));
            if (episode.StartBreadcrumbSequence <
                    predecessor.EndBreadcrumbSequence - TraversalChainImmediateMaxBreadcrumbGap ||
                breadcrumbGap > TraversalChainImmediateMaxBreadcrumbGap)
            {
                return false;
            }

            Vector3 previousExit = IsFinite(predecessor.RawExit) ? predecessor.RawExit : predecessor.Exit;
            Vector3 nextEntry = IsFinite(episode.RawStart) ? episode.RawStart : episode.Entry;
            if (!IsFinite(previousExit) || !IsFinite(nextEntry))
            {
                return false;
            }
            spatialGap = GetPlanarDistance(previousExit, nextEntry);
            return spatialGap <= TraversalChainImmediateMaxSpatialGap;
        }

        private static bool IsLearningV421NestedSubthresholdNativeProvenDropDownAlias(
            FollowerRouteMissionStep drop,
            TraversalEpisodeMetadata authoredDropEpisode,
            LearnedTraversalEdge canonicalEvidenceEdge,
            out float runtimeVerticalDrop,
            out float canonicalVerticalDrop)
        {
            runtimeVerticalDrop = 0f;
            canonicalVerticalDrop = 0f;
            if ((drop == null) || authoredDropEpisode == null ||
                canonicalEvidenceEdge == null || !IsLearningV3NativeProvenEdge(canonicalEvidenceEdge) ||
                authoredDropEpisode.EdgeId != canonicalEvidenceEdge.Id ||
                !string.Equals(drop.Kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 runtimeStart = IsFinite(authoredDropEpisode.RawStart)
                ? authoredDropEpisode.RawStart
                : drop.RawEntry;
            Vector3 runtimeEnd = IsFinite(authoredDropEpisode.RawEnd)
                ? authoredDropEpisode.RawEnd
                : drop.RawExit;
            Vector3 canonicalStart = IsFinite(canonicalEvidenceEdge.RawStart)
                ? canonicalEvidenceEdge.RawStart
                : (canonicalEvidenceEdge.HasSettledStart ? canonicalEvidenceEdge.SettledStart : canonicalEvidenceEdge.A);
            Vector3 canonicalEnd = IsFinite(canonicalEvidenceEdge.RawEnd)
                ? canonicalEvidenceEdge.RawEnd
                : (canonicalEvidenceEdge.HasSettledEnd ? canonicalEvidenceEdge.SettledEnd : canonicalEvidenceEdge.B);
            if (!IsFinite(runtimeStart) || !IsFinite(runtimeEnd) ||
                !IsFinite(canonicalStart) || !IsFinite(canonicalEnd))
            {
                return false;
            }

            runtimeVerticalDrop = Mathf.Max(0f, runtimeStart.y - runtimeEnd.y);
            canonicalVerticalDrop = Mathf.Max(0f, canonicalStart.y - canonicalEnd.y);
            return runtimeVerticalDrop > 0f &&
                   runtimeVerticalDrop < PlayerNaturalDropDownMinVerticalDrop &&
                   canonicalVerticalDrop >= PlayerNaturalDropDownMinVerticalDrop;
        }

        private static int ApplyLearningV369NestedUnprovenDropDownCanonicalization(
            BotOwner bot,
            FollowerRouteMission mission,
            string source)
        {
            if ((mission?.Steps == null) ||
                mission.Steps.Count < 1)
            {
                return 0;
            }

            int removed = 0;
            for (int index = mission.Steps.Count - 1; index >= Math.Max(0, mission.CurrentStepIndex); index--)
            {
                FollowerRouteMissionStep drop = mission.Steps[index];
                if (drop == null || !string.Equals(drop.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                    drop.ChainId <= 0 || drop.StartBreadcrumbSequence <= 0 || drop.EndBreadcrumbSequence <= drop.StartBreadcrumbSequence)
                {
                    continue;
                }
                LearnedTraversalEdge dropEdge = LearnedTraversalEdges.FirstOrDefault(edge => edge != null && edge.Id == drop.EdgeId);
                TraversalEpisodeMetadata authoredDropEpisode = TraversalEpisodeStream.FirstOrDefault(item =>
                    item != null && item.EpisodeId == drop.EpisodeId);
                LearnedTraversalEdge authoredDropEdge = authoredDropEpisode != null
                    ? LearnedTraversalEdges.FirstOrDefault(edge => edge != null && edge.Id == authoredDropEpisode.EdgeId)
                    : dropEdge;
                LearnedTraversalEdge canonicalEvidenceEdge =
                    (authoredDropEdge);
                bool learningV421NestedNativeProvenAlias = IsLearningV421NestedSubthresholdNativeProvenDropDownAlias(
                    drop, authoredDropEpisode, canonicalEvidenceEdge,
                    out float learningV421RuntimeVerticalDrop, out float learningV421CanonicalVerticalDrop);
                if (canonicalEvidenceEdge == null ||
                    (canonicalEvidenceEdge.Verified && !learningV421NestedNativeProvenAlias) ||
                    (IsLearningV3NativeProvenEdge(canonicalEvidenceEdge) && !learningV421NestedNativeProvenAlias))
                {
                    continue;
                }

                FollowerRouteMissionStep containingWalkThrough = mission.Steps.FirstOrDefault(candidate =>
                    candidate != null && candidate != drop && candidate.ChainId == drop.ChainId &&
                    (string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                     ((IsLearningV369PhysicalCorridorStep(candidate)))) &&
                    candidate.CurrentRaidRouteAuthority &&
                    candidate.StartBreadcrumbSequence <= drop.StartBreadcrumbSequence &&
                    candidate.EndBreadcrumbSequence >= drop.EndBreadcrumbSequence &&
                    (candidate.StartBreadcrumbSequence < drop.StartBreadcrumbSequence ||
                     candidate.EndBreadcrumbSequence > drop.EndBreadcrumbSequence));

                TraversalEpisodeMetadata containingPassageEpisode = null;
                if ((containingWalkThrough == null))
                {
                    // A containing WT can be removed from mission.Steps as redundant while its current-raid
                    // semantic observation is still the correct explanation for a nested natural DropDown.
                    // Use the immutable raid-local episode stream as semantic provenance; this retires only
                    // execution debt and never awards traversal/skill success.
                    containingPassageEpisode = TraversalEpisodeStream
                        .Where(candidate => candidate != null && candidate.EpisodeId != drop.EpisodeId &&
                                            candidate.ChainId == drop.ChainId &&
                                            (string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                                             string.Equals(candidate.Kind, "PhysicalCorridor", StringComparison.OrdinalIgnoreCase)) &&
                                            candidate.StartBreadcrumbSequence > 0 && candidate.EndBreadcrumbSequence > 0 &&
                                            candidate.StartBreadcrumbSequence <= drop.StartBreadcrumbSequence &&
                                            candidate.EndBreadcrumbSequence >= drop.EndBreadcrumbSequence &&
                                            (candidate.StartBreadcrumbSequence < drop.StartBreadcrumbSequence ||
                                             candidate.EndBreadcrumbSequence > drop.EndBreadcrumbSequence))
                        .OrderBy(candidate => candidate.EndBreadcrumbSequence - candidate.StartBreadcrumbSequence)
                        .ThenBy(candidate => candidate.EpisodeId)
                        .FirstOrDefault();
                }
                if (containingWalkThrough == null && containingPassageEpisode == null)
                {
                    continue;
                }

                if (!RemoveLifecycleMissionStep(mission,index,"canonicalStepRemoval")) continue;
                removed++;
                string nestedSuppressionEvent = learningV421NestedNativeProvenAlias
                    ? "learningV421NestedSubthresholdNativeProvenDropDownAliasSuppressed"
                    : "learningV369NestedUnprovenDropDownSuppressedByCurrentRaidPassage";
                WriteEvent(nestedSuppressionEvent, bot, new
                {
                    missionId = mission.MissionId,
                    source = source ?? "routeMission",
                    dropEpisodeId = drop.EpisodeId,
                    dropEdgeId = drop.EdgeId,
                    authoredDropEdgeId = authoredDropEpisode?.EdgeId ?? drop.EdgeId,
                    executorEdgeSubstituted = (authoredDropEpisode?.EdgeId ?? drop.EdgeId) != drop.EdgeId,
                    dropStartBreadcrumbSequence = drop.StartBreadcrumbSequence,
                    dropEndBreadcrumbSequence = drop.EndBreadcrumbSequence,
                    runtimeVerticalDrop = learningV421RuntimeVerticalDrop,
                    canonicalVerticalDrop = learningV421CanonicalVerticalDrop,
                    minVerticalDrop = PlayerNaturalDropDownMinVerticalDrop,
                    nativeProvenRuntimeAlias = learningV421NestedNativeProvenAlias,
                    passageEpisodeId = containingWalkThrough?.EpisodeId ?? containingPassageEpisode?.EpisodeId ?? 0,
                    passageEdgeId = containingWalkThrough?.EdgeId ?? containingPassageEpisode?.EdgeId ?? 0,
                    passageStartBreadcrumbSequence = containingWalkThrough?.StartBreadcrumbSequence ?? containingPassageEpisode?.StartBreadcrumbSequence ?? 0,
                    passageEndBreadcrumbSequence = containingWalkThrough?.EndBreadcrumbSequence ?? containingPassageEpisode?.EndBreadcrumbSequence ?? 0,
                    passageSource = containingWalkThrough != null ? "routeMissionStep" : "currentRaidEpisodeStream",
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = learningV421NestedNativeProvenAlias
                        ? "persistentNativeProvenPortalRemainsReadOnlyCurrentSubthresholdFragmentIsContainedPassageNotIndependentActuatorDebt"
                        : (containingPassageEpisode != null
                            ? "currentRaidEpisodeSemanticContainmentSurvivesRouteStepCanonicalizationNestedPassiveDropDoesNotBecomeActuatorDebt"
                            : (("authoredEpisodeProvenanceOwnsSemanticAmbiguityNestedPassiveObservationDoesNotBecomeSequentialActuatorDebt")))
                });
            }
            return removed;
        }

        private static void RefreshFollowerRouteMission(BotOwner bot, FollowerRouteMission mission)
        {
            if(IsCapabilityFullRouteReplay(mission)||IsCapabilityRouteRetryReturning(mission))return;
            if (bot == null || mission == null)
            {
                return;
            }

            RefreshRouteMissionBreadcrumbSnapshot(mission);
            HashSet<int> existingEpisodes = new HashSet<int>(mission.Steps.Where(step => step != null).Select(step => step.EpisodeId));
            string profileId = bot.ProfileId ?? string.Empty;
            int routeFloor = Math.Max(GetFollowerRouteResumeFloor(profileId), mission.ResumeFloorBreadcrumbSequence);
            int executionFloor = Math.Max(routeFloor, GetFollowerRouteExecutionFloor(profileId));
            int floorSequence = Math.Max(routeFloor, Math.Max(mission.StartBreadcrumbSequence, mission.TargetBreadcrumbSequence));
            int learningV368PreviousLastPlayerEpisodeId = mission.LastPlayerEpisodeId;
            foreach (TraversalEpisodeMetadata episode in TraversalEpisodeStream
                .Where(item => item != null && item.EpisodeId > 0)
                .OrderBy(item => item.EpisodeId))
            {
                mission.LastPlayerEpisodeId = Math.Max(mission.LastPlayerEpisodeId, episode.EpisodeId);
                bool learningV368LateSameChainExtension = IsLearningV368LateSameChainMissionExtension(
                    mission, episode, learningV368PreviousLastPlayerEpisodeId, executionFloor,
                    out FollowerRouteMissionStep learningV368Predecessor,
                    out int learningV368BreadcrumbGap, out float learningV368SpatialGap);
                bool learningV442CanonicalizedPredecessorProof = false;
                TraversalEpisodeMetadata learningV442DeferredPredecessorEpisode = null;
                FollowerRouteMissionStep learningV442CanonicalPredecessorStep = null;
                int learningV442DeferredPredecessorBreadcrumbGap = int.MaxValue;
                float learningV442DeferredPredecessorSpatialGap = float.PositiveInfinity;
                bool learningV440DirectSameChainPredecessor = mission.Steps.Any(candidate =>
                    candidate != null && candidate.ChainId == episode.ChainId &&
                    candidate.EndBreadcrumbSequence <= episode.StartBreadcrumbSequence &&
                    ((GetLearningV442InterveningBreadcrumbCount(
                            candidate.EndBreadcrumbSequence, episode.StartBreadcrumbSequence))) <=
                            TraversalChainImmediateMaxBreadcrumbGap);
                if (!learningV440DirectSameChainPredecessor)
                {
                    learningV442CanonicalizedPredecessorProof =
                        TryFindLearningV442CanonicalizedPredecessorForDeferredJump(
                            mission, episode, out learningV442DeferredPredecessorEpisode,
                            out learningV442CanonicalPredecessorStep,
                            out learningV442DeferredPredecessorBreadcrumbGap,
                            out learningV442DeferredPredecessorSpatialGap);
                }
                bool learningV440DeferredJumpMaterialization =
                    (string.Equals(episode.Kind, "Jump", StringComparison.OrdinalIgnoreCase)) &&
                    episode.ChainId > 0 && episode.EndBreadcrumbSequence > executionFloor &&
                    (HasLearningV437JumpEpisodePostLandingRetention(episode) ||
                     IsLearningV453RetainedNativeProvenJumpSubtrajectory(episode)) &&
                    (learningV440DirectSameChainPredecessor || learningV442CanonicalizedPredecessorProof);
                int applicableFloor = (learningV368LateSameChainExtension || learningV440DeferredJumpMaterialization)
                    ? executionFloor : floorSequence;
                if (existingEpisodes.Contains(episode.EpisodeId) || episode.EndBreadcrumbSequence <= applicableFloor)
                {
                    continue;
                }

                FollowerRouteMissionStep step = CreateFollowerRouteMissionStep(episode);
                if (step == null)
                {
                    EmitLearningV347TraversalEpisodeRejectedBeforeMission(
                        bot, episode, "routeMissionRefresh", "stepCreationRejected");
                    continue;
                }
                LearnedTraversalEdge refreshEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == step.EdgeId);
                if (!IsTraversalEdgeTopologicallySelectableForRouteStep(bot, refreshEdge, step, out string refreshPolicyReason))
                {
                    EmitLearningV347TraversalOpportunityNoStart(
                        bot, mission, step, "routeMissionRefreshSelector", refreshPolicyReason);
                    if (ShouldEmitDiagnostic("routeMissionRefreshSuppressed:" + step.EdgeId, bot, 1.25f))
                    {
                        WriteEvent("followerRouteMissionRefreshStepSuppressed", bot, new
                        {
                            missionId = mission.MissionId,
                            edgeId = step.EdgeId,
                            kind = step.Kind,
                            episodeId = step.EpisodeId,
                            reason = refreshPolicyReason
                        });
                    }
                    continue;
                }
                if (!AddLifecycleMissionStep(mission, step))
                {
                    EmitLearningV347TraversalOpportunityNoStart(
                        bot, mission, step, "routeMissionRefreshCanonicalization",
                        "redundantWithEquivalentRouteStep");
                    if (ShouldEmitDiagnostic("routeMissionCanonicalSuppressed:" + step.EdgeId, bot, 1.25f))
                    {
                        WriteEvent("followerRouteMissionCanonicalStepSuppressed", bot, new
                        {
                            missionId = mission.MissionId,
                            edgeId = step.EdgeId,
                            episodeId = step.EpisodeId,
                            kind = step.Kind,
                            source = "refresh"
                        });
                    }
                    continue;
                }
                existingEpisodes.Add(step.EpisodeId);
                mission.TargetBreadcrumbSequence = Math.Max(mission.TargetBreadcrumbSequence, step.EndBreadcrumbSequence);
                if (learningV440DeferredJumpMaterialization)
                {
                    if (learningV442CanonicalizedPredecessorProof)
                    {
                        WriteEvent("learningV442CanonicalizedPredecessorRetainsDownstreamActionDebt", bot, new
                        {
                            missionId = mission.MissionId,
                            jumpEpisodeId = episode.EpisodeId,
                            jumpEdgeId = step.EdgeId,
                            jumpChainId = episode.ChainId,
                            predecessorEpisodeId = learningV442DeferredPredecessorEpisode?.EpisodeId ?? 0,
                            predecessorEdgeId = learningV442DeferredPredecessorEpisode?.EdgeId ?? 0,
                            canonicalMissionEpisodeId = learningV442CanonicalPredecessorStep?.EpisodeId ?? 0,
                            canonicalMissionEdgeId = learningV442CanonicalPredecessorStep?.EdgeId ?? 0,
                            interveningBreadcrumbs = learningV442DeferredPredecessorBreadcrumbGap,
                            spatialGap = learningV442DeferredPredecessorSpatialGap,
                            executionFloor,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = "passageCanonicalizationMayReplacePredecessorIdentityButCannotDeleteItsImmediateDownstreamActuatorDebt"
                        });
                    }
                    WriteEvent("learningV440DeferredJumpMaterializedByImmediateSuccessor", bot, new
                    {
                        missionId = mission.MissionId,
                        episodeId = step.EpisodeId,
                        edgeId = step.EdgeId,
                        kind = step.Kind,
                        chainId = step.ChainId,
                        startBreadcrumbSequence = step.StartBreadcrumbSequence,
                        endBreadcrumbSequence = step.EndBreadcrumbSequence,
                        executionFloor,
                        leaderTargetBreadcrumbSequence = floorSequence,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "previouslyDeferredJumpBecomesExecutableWhenTypedImmediateSuccessorProvesLandingRetention"
                    });
                }
                if (learningV368LateSameChainExtension)
                {
                    WriteEvent("learningV368LateSameChainMissionStepAppended", bot, new
                    {
                        missionId = mission.MissionId,
                        episodeId = step.EpisodeId,
                        edgeId = step.EdgeId,
                        kind = step.Kind,
                        chainId = step.ChainId,
                        predecessorEpisodeId = learningV368Predecessor?.EpisodeId ?? 0,
                        predecessorEdgeId = learningV368Predecessor?.EdgeId ?? 0,
                        breadcrumbGap = learningV368BreadcrumbGap,
                        spatialGap = learningV368SpatialGap,
                        executionFloor,
                        leaderTargetBreadcrumbSequence = floorSequence,
                        action = "appendLateDetectedSameChainActionWithoutTreatingLeaderTargetAsExecutionFloor"
                    });
                }
            }

            AppendDirectionalWalkThroughRouteStepsFromBreadcrumbs(
                bot,
                mission,
                Math.Max(routeFloor, mission.TargetBreadcrumbSequence),
                "refresh");

            SetLifecycleMissionSteps(mission, mission.Steps
                .Where(step => step != null)
                .OrderBy(step => step.StartBreadcrumbSequence)
                .ThenBy(step => step.EpisodeId)
                .ToList());
            ApplyLearningV366DirectedPhysicalStepOrder(bot, mission, "routeMissionRefresh");
            ApplyLearningV369NestedUnprovenDropDownCanonicalization(bot, mission, "routeMissionRefresh");
            mission.TargetBreadcrumbSequence = Math.Max(mission.TargetBreadcrumbSequence, breadcrumbSequence);
            // V3.43: ExpiresAt is a hard transaction lifetime established when the mission is armed.
            // Refresh may append newer route facts, but may not renew ownership forever.
            ;
        }

        private static void EmitLearningV347TraversalOpportunityNoStart(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            string stage,
            string reason)
        {
            if ((bot == null) || step == null ||
                step.AttemptStartedObserved)
            {
                return;
            }

            string key = "learningV347TraversalOpportunityNoStart:" +
                (mission != null ? mission.MissionId.ToString(CultureInfo.InvariantCulture) : "0") + ":" +
                step.EpisodeId.ToString(CultureInfo.InvariantCulture) + ":" +
                (stage ?? string.Empty) + ":" + (reason ?? string.Empty);
            if (!ShouldEmitDiagnostic(key, bot, 0.25f))
            {
                return;
            }

            WriteEvent("learningV347TraversalOpportunityNoStart", bot, new
            {
                missionId = mission != null ? mission.MissionId : 0,
                stepIndex = mission != null ? mission.CurrentStepIndex : -1,
                episodeId = step.EpisodeId,
                edgeId = step.EdgeId,
                chainId = step.ChainId,
                kind = step.Kind,
                startBreadcrumbSequence = step.StartBreadcrumbSequence,
                endBreadcrumbSequence = step.EndBreadcrumbSequence,
                approachBreadcrumbSequence = mission != null ? mission.ApproachBreadcrumbSequence : 0,
                chainLocalExecutable = step.ChainLocalExecutable,
                currentRaidRouteAuthority = step.CurrentRaidRouteAuthority,
                body = Vec(bot.Position),
                entry = Vec(IsFinite(step.RawEntry) ? step.RawEntry : step.Entry),
                exit = Vec(IsFinite(step.RawExit) ? step.RawExit : step.Exit),
                entryDistance = GetPlanarDistance(bot.Position, IsFinite(step.RawEntry) ? step.RawEntry : step.Entry),
                exitDistance = GetPlanarDistance(bot.Position, IsFinite(step.RawExit) ? step.RawExit : step.Exit),
                lastValidStage = stage ?? "unknown",
                rejectionReason = reason ?? "unknown",
                missingEvent = "TraversalAttemptStarted"
            });
        }

