        private static bool TryParseTraversalRetryCooldownSeconds(string reason, out float seconds)
        {
            seconds = 0f;
            const string prefix = "retryCooldown=";
            if (string.IsNullOrWhiteSpace(reason) ||
                !reason.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }
            string value = reason.Substring(prefix.Length).Trim();
            if (value.EndsWith("s", StringComparison.OrdinalIgnoreCase))
            {
                value = value.Substring(0, value.Length - 1);
            }
            return float.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out seconds) &&
                   seconds > 0f;
        }

        private static bool TryCanonicalizeLearningV334DirectionalWalkThroughSuccessor(
            BotOwner bot, FollowerRouteMission mission)
        {
            if(IsCapabilityFullRouteReplay(mission))return false;
            if ((bot == null) || mission == null ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) ||
                cursor == null || cursor.ConsumedBreadcrumbSequence <= 0)
            {
                return false;
            }

            FollowerRouteMissionStep stale = mission.Steps[mission.CurrentStepIndex];
            int floor = cursor.ConsumedBreadcrumbSequence;
            if (stale == null ||
                !string.Equals(stale.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                stale.StartBreadcrumbSequence >= floor || stale.EndBreadcrumbSequence <= floor)
            {
                return false;
            }

            FollowerRouteMissionStep replacement = null;
            foreach (TraversalEpisodeMetadata episode in TraversalEpisodeStream
                .Where(item => item != null &&
                               item.EpisodeId != stale.EpisodeId &&
                               string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                               item.StartBreadcrumbSequence == floor &&
                               item.EndBreadcrumbSequence > floor &&
                               item.EndBreadcrumbSequence <= stale.EndBreadcrumbSequence)
                .OrderByDescending(item => item.EndBreadcrumbSequence)
                .ThenByDescending(item => item.EpisodeId))
            {
                FollowerRouteMissionStep candidate = CreateFollowerRouteMissionStep(episode);
                if (candidate == null)
                {
                    continue;
                }
                LearnedTraversalEdge candidateEdge = LearnedTraversalEdges.FirstOrDefault(edge =>
                    edge != null && edge.Id == candidate.EdgeId);
                if (!IsTraversalEdgeTopologicallySelectableForRouteStep(bot, candidateEdge, candidate, out _))
                {
                    continue;
                }

                Vector3 staleDirection = GetFlatDirection(stale.RawExit - stale.RawEntry);
                Vector3 candidateDirection = GetFlatDirection(candidate.RawExit - candidate.RawEntry);
                if (staleDirection.sqrMagnitude < 0.5f || candidateDirection.sqrMagnitude < 0.5f ||
                    Vector3.Dot(staleDirection, candidateDirection) < WalkThroughTerminalConnectorMinForwardDot ||
                    GetPlanarDistance(stale.Exit, candidate.Exit) > WalkThroughTerminalConnectorMaxDistance)
                {
                    continue;
                }
                replacement = candidate;
                break;
            }

            if (replacement == null)
            {
                return false;
            }

            int staleEdgeId = stale.EdgeId;
            int staleEpisodeId = stale.EpisodeId;
            if (!ReplaceLifecycleMissionStep(mission,mission.CurrentStepIndex,replacement)) return false;
            for (int index = mission.Steps.Count - 1; index >= 0; index--)
            {
                if (index == mission.CurrentStepIndex)
                {
                    continue;
                }
                FollowerRouteMissionStep duplicate = mission.Steps[index];
                if (duplicate != null && duplicate.EpisodeId == replacement.EpisodeId)
                {
                    if (!RemoveLifecycleMissionStep(mission,index,"canonicalStepRemoval")) continue;
                }
            }

            mission.ApproachBreadcrumbSequence = Math.Max(mission.ApproachBreadcrumbSequence, floor);
            WriteEvent("learningV334DirectionalWalkThroughSuccessorCanonicalized", bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                consumedBreadcrumbSequence = floor,
                staleEpisodeId,
                staleEdgeId,
                staleStartBreadcrumbSequence = stale.StartBreadcrumbSequence,
                staleEndBreadcrumbSequence = stale.EndBreadcrumbSequence,
                replacementEpisodeId = replacement.EpisodeId,
                replacementEdgeId = replacement.EdgeId,
