        private static bool TryValidateLearningV410TerminalFollowFirstCornerForward(
            BotOwner bot,
            FollowerRouteMission mission,
            Vector3 target,
            out float firstCornerForwardDot,
            out float targetForwardDot,
            out float firstCornerDistance,
            out string detail)
        {
            firstCornerForwardDot = 1f;
            targetForwardDot = 1f;
            firstCornerDistance = 0f;
            detail = "notRequired";
            if ((bot == null) || mission == null ||
                !IsFinite(bot.Position) || !IsFinite(target))
            {
                return true;
            }

            FollowerTraversalRouteCursor cursor = GetOrCreateLearningV375RouteCursor(bot);
            Vector3 tangent = cursor?.LearningV375RouteTangent ?? Vector3.zero;
            tangent.y = 0f;
            if (tangent.sqrMagnitude <= 0.0001f && mission.Steps != null && mission.Steps.Count > 0)
            {
                FollowerRouteMissionStep last = mission.Steps[mission.Steps.Count - 1];
                if (last != null)
                {
                    Vector3 routeEntry = IsFinite(last.RawEntry) ? last.RawEntry : last.Entry;
                    Vector3 routeExit = IsFinite(last.RawExit) ? last.RawExit : last.Exit;
                    tangent = routeExit - routeEntry;
                    tangent.y = 0f;
                }
            }
            if (tangent.sqrMagnitude <= 0.0001f)
            {
                detail = "routeTangentUnavailable";
                return true;
            }
            tangent.Normalize();

            StrictPathResult path = CalculateStrictPath(bot.Position, target);
            if (path == null || !path.StrictComplete || path.Corners == null || path.Corners.Length == 0)
            {
                detail = "strictPathUnavailable";
                return true;
            }

            Vector3 firstCorner = Vector3.zero;
            bool haveFirstCorner = false;
            foreach (Vector3 corner in path.Corners)
            {
                Vector3 delta = corner - bot.Position;
                delta.y = 0f;
                float distance = delta.magnitude;
                if (distance <= 0.15f)
                {
                    continue;
                }
                firstCorner = corner;
                firstCornerDistance = distance;
                firstCornerForwardDot = Vector3.Dot(delta / distance, tangent);
                haveFirstCorner = true;
                break;
            }

            Vector3 targetDelta = target - bot.Position;
            targetDelta.y = 0f;
            if (targetDelta.sqrMagnitude > 0.0001f)
            {
                targetForwardDot = Vector3.Dot(targetDelta.normalized, tangent);
            }
            if (!haveFirstCorner)
            {
                detail = "noMeaningfulCorner";
                return true;
            }

            bool staleLocalBackwardCorner =
                FollowerCapabilityHelperRules.TryValidateLearningV410TerminalFollowFirstCornerForward_staleLocalBackwardCorner_471D083D_1(firstCornerDistance,PostTraversalRollbackMinReleaseDisplacement,firstCornerForwardDot,targetForwardDot);
            if (!staleLocalBackwardCorner)
            {
                detail = "forwardCompatible";
                return true;
            }

            detail = "localFirstCornerBehindPhysicalFrontier";
            WriteEvent("learningV410FollowBackwardCornerRejected", bot, new
            {
                missionId = mission.MissionId,
                body = Vec(bot.Position),
                target = Vec(target),
                firstCorner = Vec(firstCorner),
                routeTangent = Vec(tangent),
                firstCornerDistance,
                firstCornerForwardDot,
                targetForwardDot,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "rejectOnlyStaleLocalBackwardFirstCornerRetryFollowFromEvolvingCurrentBody"
            });
            return false;
        }

        private static bool TryPrimeLearningV409TerminalFollowConsumerWithoutBrake(
            BotOwner bot,
            FollowerRouteMission mission,
            string source,
            out string detail)
        {
            detail = "notEligible";
            if ((bot?.GetPlayer == null) || bot.Mover == null ||
                mission == null || HasActiveTraversalProbe(bot))
            {
                return false;
            }

            Player leader = FollowerEnvironment.LocalPlayer;
            if (!IsLivePlayer(leader) || !IsFinite(leader.Position) || !IsFinite(bot.GetPlayer.Position))
            {
                detail = "leaderUnavailable";
                return false;
            }

            // Validate a real successor before surrendering Traversal authority. Native BotMover
            // corner changes never insert a Stop boundary; terminal traversal should follow the same
            // rule and hand ownership only when a fresh Follow consumer is available.
            if (!CanAcceptFollowPath(
                    bot, leader.Position, "post-traversal-fresh-epoch",
                    out float pathLength, out float detourRatio))
            {
                detail = "successorPathRejected:length=" +
                         pathLength.ToString("0.00", CultureInfo.InvariantCulture) +
                         ":detour=" + detourRatio.ToString("0.00", CultureInfo.InvariantCulture);
                return false;
            }
            if (!TryValidateLearningV410TerminalFollowFirstCornerForward(
                    bot, mission, leader.Position,
                    out float firstCornerForwardDot, out float targetForwardDot,
                    out float firstCornerDistance, out string forwardDetail))
            {
                detail = "successorPathBackwardCorner:" + forwardDetail +
                         ":cornerDot=" + firstCornerForwardDot.ToString("0.00", CultureInfo.InvariantCulture) +
                         ":targetDot=" + targetForwardDot.ToString("0.00", CultureInfo.InvariantCulture) +
                         ":cornerDistance=" + firstCornerDistance.ToString("0.00", CultureInfo.InvariantCulture);
                return false;
            }

            long traversalGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            bool primed;
            string primeDetail;
            if ((owner == FollowerMovementWriterAuthority.WriterDomain.Traversal) &&
                traversalGeneration > 0)
            {
                primed = TryHandoffLearningV419TraversalToFreshFollowConsumer(
                    bot, traversalGeneration,
                    "learningV420TerminalSuccessorFirst:" + (source ?? "routeComplete"),
                    "post-traversal-fresh-epoch", out primeDetail);
            }
            else
            {
                if (owner == FollowerMovementWriterAuthority.WriterDomain.Traversal && traversalGeneration > 0)
                {
                    FollowerMovementWriterAuthority.TransitionTraversalToFollowIfCurrent(
                        bot, traversalGeneration,
                        "learningV409TerminalSuccessorFirst:" + (source ?? "routeComplete"));
                }
                primed = TryPrimeFreshFollowPathAfterAuthorityReset(
                    bot,
                    "learningV409TerminalSuccessorFirst",
                    "post-traversal-fresh-epoch",
                    out primeDetail,
                    preserveLocomotion: true);
            }
            detail = primeDetail;
            if (!primed)
            {
                return false;
            }

            long followGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain followOwner);
            if (followOwner != FollowerMovementWriterAuthority.WriterDomain.Follow || followGeneration <= 0)
            {
                detail = "followOwnerUnavailableAfterSuccessorValidation:" + followOwner;
                return false;
            }

            WriteEvent("learningV409TerminalFollowConsumerInstalledWithoutBrake", bot, new
            {
                missionId = mission.MissionId,
                source = source ?? "routeComplete",
                generation = followGeneration,
                body = Vec(bot.Position),
                leader = Vec(leader.Position),
                pathLength,
                detourRatio,
                stalePathStoppedBeforeSuccessor = false,
                stopMoveCalledBeforeSuccessor = false,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "installFreshFollowConsumerBeforeRetiringTraversalTransactionPreserveNativeLocomotion"
            });
            return true;
        }

