        private static bool IsLearningV435WalkThroughEpisodeSemanticAlias(
            TraversalEpisodeMetadata episode,
            int semanticEdgeId,
            out int authoredEdgeId,
            out int provenParentEdgeId)
        {
            authoredEdgeId = episode?.EdgeId ?? 0;
            provenParentEdgeId = 0;
            if (episode == null || semanticEdgeId <= 0 || authoredEdgeId <= 0)
            {
                return false;
            }
            if (authoredEdgeId == semanticEdgeId)
            {
                return true;
            }
            ;

            int authoredEpisodeEdgeId = authoredEdgeId;
            LearnedTraversalEdge authoredEpisodeEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == authoredEpisodeEdgeId &&
                string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase));
            LearnedTraversalEdge semanticEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == semanticEdgeId &&
                string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase));
            if (authoredEpisodeEdge == null || semanticEdge == null)
            {
                return false;
            }

            if (TryGetLearningV31AuthoritativeProvenParent(
                    authoredEpisodeEdge, out LearnedTraversalEdge authoredParent) &&
                authoredParent != null && authoredParent.Id == semanticEdgeId)
            {
                provenParentEdgeId = authoredParent.Id;
                return true;
            }

            // Keep the relation symmetric only when the opposite side is itself an explicit
            // V3.1 authoritative-parent alias. This supports a live mission that still carries the
            // shadow identity while the episode was canonicalized to the proven parent; unrelated
            // nearby WT edges remain ineligible.
            if (TryGetLearningV31AuthoritativeProvenParent(
                    semanticEdge, out LearnedTraversalEdge semanticParent) &&
                semanticParent != null && semanticParent.Id == authoredEdgeId)
            {
                provenParentEdgeId = semanticParent.Id;
                return true;
            }
            return false;
        }

        private static bool TryResolveLearningV424CurrentEpisodeWalkThroughGeometry(
            int edgeId,
            int preferredEpisodeId,
            int crossingStartSequence,
            int crossingEndSequence,
            out TraversalEpisodeMetadata episode,
            out Vector3 executionEntry,
            out Vector3 executionExit)
        {
            episode = null;
            executionEntry = default;
            executionExit = default;
            if ((edgeId <= 0))
            {
                return false;
            }

            IEnumerable<TraversalEpisodeMetadata> candidates = TraversalEpisodeStream.Where(item =>
                item != null &&
                IsLearningV435WalkThroughEpisodeSemanticAlias(item, edgeId, out _, out _) &&
                item.LearningV372HasCurrentExecutionGeometry &&
                IsFinite(item.LearningV372CurrentExecutionStart) &&
                IsFinite(item.LearningV372CurrentExecutionEnd));
            if (preferredEpisodeId > 0)
            {
                candidates = candidates.Where(item => item.EpisodeId == preferredEpisodeId);
            }
            else if (crossingStartSequence > 0 && crossingEndSequence >= crossingStartSequence)
            {
                int sequenceSlack = TraversalChainImmediateMaxBreadcrumbGap;
                candidates = candidates.Where(item =>
                    item.StartBreadcrumbSequence <= crossingEndSequence + sequenceSlack &&
                    item.EndBreadcrumbSequence + sequenceSlack >= crossingStartSequence);
            }

            episode = candidates
                .OrderByDescending(item => item.EndBreadcrumbSequence)
                .ThenByDescending(item => item.EpisodeId)
                .FirstOrDefault();
            if (episode == null)
            {
                return false;
            }

            executionEntry = episode.LearningV372CurrentExecutionStart;
            executionExit = episode.LearningV372CurrentExecutionEnd;
            if ((TryGetLearningV373ConsolidatedWalkThroughExecutionGeometry(
                    episode,
                    out Vector3 consolidatedStart,
                    out Vector3 consolidatedEnd,
                    out _, out _, out _)) &&
                IsFinite(consolidatedStart) && IsFinite(consolidatedEnd))
            {
                executionEntry = consolidatedStart;
                executionExit = consolidatedEnd;
            }
            return IsFinite(executionEntry) && IsFinite(executionExit) &&
                   GetPlanarDistance(executionEntry, executionExit) > 0.05f;
        }

