        private static bool TryDriveLearningV347EmpiricalRouteCorridor(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            out int targetSequence)
        {
            targetSequence = 0;
            int learningV369RouteBoundary = IsLearningV369PhysicalCorridorStep(step)
                ? step.EndBreadcrumbSequence
                : step.StartBreadcrumbSequence;
            if ((bot == null) || mission == null || step == null ||
                mission.PhysicalApproachBreadcrumbSequence >= learningV369RouteBoundary)
            {
                return false;
            }

            Player player = bot.GetPlayer ?? bot.AIData?.Player;
            if (player?.MovementContext == null)
            {
                return false;
            }

            RefreshRouteMissionBreadcrumbSnapshot(mission);
            PlayerBreadcrumbNode next = null;
            int skippedRemotePrefixCount = 0;
            int skippedRemotePrefixLastSequence = 0;
            for (int index = 0; index < mission.RouteBreadcrumbs.Count; index++)
            {
                PlayerBreadcrumbNode candidate = mission.RouteBreadcrumbs[index];
                if (candidate == null || candidate.Sequence <= mission.PhysicalApproachBreadcrumbSequence ||
                    candidate.Sequence > learningV369RouteBoundary || !IsOperationalBreadcrumbNode(candidate) ||
                    !IsFinite(candidate.Position))
                {
                    continue;
                }

                float reachedDistance = GetLearningV380PhysicalBreadcrumbDistance(step, bot.Position, candidate.Position);
                if (reachedDistance <= GetLearningV380PhysicalBreadcrumbReachDistance(step))
                {
