            float learningV355AfterTargetDistance = GetLearningV380PhysicalBreadcrumbDistance(step, learningV355AfterPhysicalPosition, physicalTarget);
            float learningV355TargetClosure = learningV355BeforeTargetDistance - learningV355AfterTargetDistance;
            Vector3 learningV355CumulativePhysicalDelta = learningV355AfterPhysicalPosition - mission.LastProgressPosition;
            if (!learningV380ThreeDimensionalStep)
