            bool learningV355MeasuredRouteProgress = FollowerCapabilityHelperRules.TryDriveLearningV347EmpiricalRouteCorridor_learningV355MeasuredRouteProgress_3A6819C4_1(learningV355CumulativePhysicalDisplacement,LearningV350MeasuredPhysicalProgressDistance,learningV355CumulativeRouteForwardProgress,LearningV350MeasuredTargetProgressDistance);
            if (learningV355MeasuredRouteProgress)
