        private static void ClearLearningV365ContinuousPhysicalRoute(BotOwner bot, string reason)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }
            LearningV365ContinuousRouteProducerState releasedProducer = null;
            LearningV365ContinuousRouteProducerStates.TryGetValue(profileId, out releasedProducer);
            bool removed = LearningV365ContinuousRouteProducerStates.Remove(profileId);
            // V2-RC11: the producer that set Pause owns the only permission to clear it.
            // An old cleanup callback must not borrow a new Owner's live generation.
            // A failed origin check leaves the newer owner untouched; its own physical
            // consumer is responsible for setting its own Pause state.
            bool pauseReleaseAccepted = true;
            if ((removed) &&
                releasedProducer?.MoverPausedForExclusiveTranslation == true)
            {
                pauseReleaseAccepted = TryReleaseMoverPauseAtOrigin(
                    bot, FollowerMovementWriterAuthority.WriterDomain.Traversal,
                    releasedProducer.ExclusivePauseWriterGeneration);
                if (!pauseReleaseAccepted)
                {
                    WriteEvent("v2ExclusiveRoutePauseOriginRejected", bot, new
                    {
                        reason = reason ?? "unknown",
                        missionId = releasedProducer.MissionId,
                        stepIndex = releasedProducer.StepIndex,
                        edgeId = releasedProducer.EdgeId,
                        originGeneration = releasedProducer.ExclusivePauseWriterGeneration,
                        action = "staleProducerCannotUnpauseNewOwner"
                    });
                }
            }
            if (removed &&
                ShouldEmitDiagnostic("learningV365ContinuousPhysicalRouteReleased:" + (reason ?? string.Empty), bot, 0.35f))
            {
                WriteEvent("learningV365ContinuousPhysicalRouteReleased", bot, new
                {
                    reason = reason ?? "unknown",
                    exclusiveTranslationReleaseRequested = releasedProducer?.MoverPausedForExclusiveTranslation == true,
                    exclusiveTranslationReleased = releasedProducer?.MoverPausedForExclusiveTranslation == true && pauseReleaseAccepted,
                    action = "releaseContinuousProducerWithoutChangingRouteSemantic"
                });
            }
        }

        private static void ArmLearningV365ContinuousTypedPhysicalRoute(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            PlayerBreadcrumbNode node,
            Vector3 target)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || mission == null || step == null || node == null || !IsFinite(target))
            {
                return;
            }
            bool preserveProducerState =
                LearningV365ContinuousRouteProducerStates.TryGetValue(
                    profileId, out LearningV365ContinuousRouteProducerState existingProducer) &&
                existingProducer != null && !existingProducer.Generic &&
                existingProducer.MissionId == mission.MissionId &&
                existingProducer.StepIndex == mission.CurrentStepIndex &&
                existingProducer.EdgeId == step.EdgeId;
            bool preserveExclusiveMoverPause = preserveProducerState &&
                existingProducer.MoverPausedForExclusiveTranslation;
            LearningV365ContinuousRouteProducerStates[profileId] = new LearningV365ContinuousRouteProducerState
            {
                Generic = false,
                MissionId = mission.MissionId,
                StepIndex = mission.CurrentStepIndex,
                EdgeId = step.EdgeId,
                TargetSequence = node.Sequence,
                Target = target,
                Pose = Mathf.Clamp01(node.Pose),
                MoverPausedForExclusiveTranslation = preserveExclusiveMoverPause,
                ExclusivePauseWriterGeneration = preserveExclusiveMoverPause
                    ? existingProducer.ExclusivePauseWriterGeneration : 0,
                LearningV386ProgressTargetSequence = preserveProducerState
                    ? existingProducer.LearningV386ProgressTargetSequence
                    : node.Sequence,
                LearningV386AccumulatedBodyDistance = preserveProducerState
                    ? existingProducer.LearningV386AccumulatedBodyDistance
                    : 0f,
                LearningV386AccumulatedTargetClosure = preserveProducerState
                    ? existingProducer.LearningV386AccumulatedTargetClosure
                    : 0f,
                LearningV386LastMeasuredForwardProgressAt = preserveProducerState
                    ? existingProducer.LearningV386LastMeasuredForwardProgressAt
                    : -1f,
                LearningV457SuccessorAdmissionLeaseActive = preserveProducerState &&
                    existingProducer.LearningV457SuccessorAdmissionLeaseActive,
                LearningV457SuccessorStepIndex = preserveProducerState
                    ? existingProducer.LearningV457SuccessorStepIndex
                    : -1,
                LearningV457SuccessorEdgeId = preserveProducerState
                    ? existingProducer.LearningV457SuccessorEdgeId
                    : 0,
                LearningV457SuccessorKind = preserveProducerState
                    ? existingProducer.LearningV457SuccessorKind
                    : string.Empty,
                LearningV457SuccessorAxis = preserveProducerState
                    ? existingProducer.LearningV457SuccessorAxis
                    : Vector3.zero
            };
        }

        private static void ArmLearningV365ContinuousGenericPhysicalRoute(
            BotOwner bot, PlayerBreadcrumbNode node, long learningV423TraversalGeneration = 0)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || node == null || !IsFinite(node.Position))
            {
                return;
            }
            LearningV365ContinuousRouteProducerStates[profileId] = new LearningV365ContinuousRouteProducerState
            {
                Generic = true,
                MissionId = 0,
                StepIndex = -1,
                EdgeId = 0,
                TargetSequence = node.Sequence,
                Target = node.Position,
                Pose = Mathf.Clamp01(node.Pose),
                LearningV423TraversalOwnedGeneration = learningV423TraversalGeneration
            };
        }

        private static bool TryAdvanceLearningV365TypedPhysicalTarget(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            LearningV365ContinuousRouteProducerState producer)
        {
            if (bot == null || mission == null || step == null || producer == null)
            {
                return false;
            }

            // V4.60: rolling Jump preparation is a physical-consumer concern, not a semantic
            // predecessor-completion concern. Begin the existing V427/V457 single-producer lease
            // as soon as the body enters the already-learned V452 preparation envelope. The
            // predecessor remains the current semantic step until V388 can atomically transfer it.
            if (TryLeaseLearningV460PreBoundaryRollingJumpAdmission(
                    bot, mission, step, producer))
            {
                return true;
            }

            int learningV369RouteBoundary = IsLearningV369PhysicalCorridorStep(step)
                ? step.EndBreadcrumbSequence
                : step.StartBreadcrumbSequence;
            while (true)
            {
                float learningV391TargetDistance =
                    GetLearningV380PhysicalBreadcrumbDistance(step, bot.Position, producer.Target);
                bool learningV391ReachedByDistance = learningV391TargetDistance <=
                    GetLearningV380PhysicalBreadcrumbReachDistance(step);
                bool learningV391ReachedByRouteFrontier = false;
                float learningV391BodyArc = 0f;
                float learningV391TargetArc = 0f;
                if ((IsLearningV369PhysicalCorridorStep(step)) &&
                    producer.TargetSequence > mission.PhysicalApproachBreadcrumbSequence &&
                    TryProjectLearningV375RouteArc(
                        mission, bot.Position,
                        out learningV391BodyArc, out _, out _, out _) &&
                    TryGetLearningV375SequenceArc(
                        mission, producer.TargetSequence,
                        out learningV391TargetArc, out _) &&
                    learningV391BodyArc >= learningV391TargetArc)
                {
                    learningV391ReachedByRouteFrontier = true;
                }
                if (!learningV391ReachedByDistance && !learningV391ReachedByRouteFrontier)
                {
                    break;
                }
                if (learningV391ReachedByRouteFrontier && !learningV391ReachedByDistance &&
                    ShouldEmitDiagnostic(
                        "learningV391TypedPhysicalBreadcrumbPassedByRouteFrontier:" +
                            producer.TargetSequence.ToString(CultureInfo.InvariantCulture),
                        bot, 0.12f))
                {
                    WriteEvent("learningV391TypedPhysicalBreadcrumbPassedByRouteFrontier", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = mission.CurrentStepIndex,
                        edgeId = step.EdgeId,
                        kind = step.Kind,
                        breadcrumbSequence = producer.TargetSequence,
                        bodyArc = learningV391BodyArc,
                        targetArc = learningV391TargetArc,
                        targetDistance = learningV391TargetDistance,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "monotonicRouteFrontierAdvancesTypedPhysicalCursorWithoutExactRadiusTouch"
                    });
                }
                {
                    // Reaching the currently authored breadcrumb is direct physical progress proof.
                    // Credit the same existing route lease here before changing target direction so
                    // a bend/slope cannot make the next segment retroactively look like regression.
                    mission.LastProgressAt = Time.time;
                    mission.LastProgressPosition = bot.Position;
                    producer.LearningV386LastMeasuredForwardProgressAt = Time.time;
                    producer.LearningV386AccumulatedBodyDistance = 0f;
                    producer.LearningV386AccumulatedTargetClosure = 0f;
                }
                mission.PhysicalApproachBreadcrumbSequence = Math.Max(
                    mission.PhysicalApproachBreadcrumbSequence, producer.TargetSequence);
                mission.ApproachBreadcrumbSequence = Math.Max(
                    mission.ApproachBreadcrumbSequence, producer.TargetSequence);
                if (mission.PhysicalApproachBreadcrumbSequence >= learningV369RouteBoundary)
                {
                    if (IsLearningV369PhysicalCorridorStep(step) &&
                        TryLeaseLearningV427PendingRollingSuccessorBoundary(
                            bot, mission, step, producer))
                    {
                        // Preserve the same physical writer, body epoch and locomotion mode. The
                        // next frame begins with V388 again; once its existing readiness proof is
                        // true, it performs the canonical actuator handoff and consumes this debt.
                        return true;
                    }

                    ClearLearningV365ContinuousPhysicalRoute(
                        bot,
                        IsLearningV369PhysicalCorridorStep(step)
                            ? "learningV369PhysicalCorridorSegmentReachedEnd"
                            : "typedReachedTraversalEntry");
                    return false;
                }

                PlayerBreadcrumbNode next = mission.RouteBreadcrumbs.FirstOrDefault(candidate =>
                    candidate != null && candidate.Sequence > producer.TargetSequence &&
                    candidate.Sequence <= learningV369RouteBoundary &&
                    IsOperationalBreadcrumbNode(candidate) && IsFinite(candidate.Position));
                if (next == null)
                {
                    ClearLearningV365ContinuousPhysicalRoute(bot, "typedSnapshotAwaitRefresh");
                    return false;
                }
                Vector3 target = GetOperationalBreadcrumbTarget(next);
                if (!IsFinite(target) || GetLearningV380PhysicalBreadcrumbDistance(step, bot.Position, target) > RouteMissionBreadcrumbLookAheadDistance)
                {
                    ClearLearningV365ContinuousPhysicalRoute(bot, "typedNextTargetOutsideLookAhead");
                    return false;
                }
                producer.TargetSequence = next.Sequence;
                producer.Target = target;
                producer.Pose = Mathf.Clamp01(next.Pose);
                {
                    producer.LearningV386ProgressTargetSequence = next.Sequence;
                    producer.LearningV386AccumulatedBodyDistance = 0f;
                    producer.LearningV386AccumulatedTargetClosure = 0f;
                }
            }
            return true;
        }

        private static bool TryBuildLearningV457LatchedSuccessorAdmissionTarget(
            BotOwner bot,
            FollowerRouteMissionStep successor,
            LearningV365ContinuousRouteProducerState producer,
            out Vector3 target,
            out string source)
        {
            target = default;
            source = string.Empty;
            if ((bot?.GetPlayer?.MovementContext == null) ||
                successor == null || producer == null ||
                !producer.LearningV457SuccessorAdmissionLeaseActive ||
                producer.LearningV457SuccessorEdgeId != successor.EdgeId ||
                producer.LearningV457SuccessorStepIndex < 0)
            {
                return false;
            }

            if (!string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 identityRawEntry = IsFinite(successor.RawEntry) ? successor.RawEntry : successor.Entry;
            Vector3 admissionEntry = GetLearningV442JumpAdmissionEntry(successor);
            Vector3 rawExit = IsFinite(successor.RawExit) ? successor.RawExit : successor.Exit;
            Vector3 axis = producer.LearningV457SuccessorAxis.sqrMagnitude > 0.5f
                ? producer.LearningV457SuccessorAxis
                : GetFlatDirection(rawExit - identityRawEntry);
            if (!IsFinite(admissionEntry) || axis.sqrMagnitude < 0.5f)
            {
                return false;
            }

            Vector3 bodyOffset = bot.Position - admissionEntry;
            bodyOffset.y = 0f;
            float forwardProjection = Vector3.Dot(bodyOffset, axis);
            bool liveFirstRefusal = TryGetLearningV455LiveJumpFirstRefusalEnvelope(
                bot, successor, forwardProjection, out float liveMaxForwardProjection);
            if (IsLearningV449JumpTakeoffFrontierMissed(forwardProjection) && !liveFirstRefusal)
            {
                // Do not create an infinite boundary lease after the physical Jump frontier is
                // genuinely gone. Let V408 retire the predecessor on this frame so the successor
                // semantic step can use the existing V433/V450 current-body HOW substitution.
                return false;
            }

            float forwardHorizon = liveFirstRefusal
                ? liveMaxForwardProjection
                : LearningV352JumpTakeoffCorridorMaxForwardOvershoot;
            float targetProjection;
            {
                // One successor admission producer may steer toward centerline, but its positional
                // target must stay ahead of the live body. A same-projection axis point is a hidden
                // brake/turn command and was the common cause of fence Climb/Vault substitution.
                targetProjection = Mathf.Min(
                    forwardProjection + ProbeJumpRunupDistance,
                    forwardHorizon);
                if (targetProjection <= forwardProjection)
                {
                    return false;
                }
            }
            target = admissionEntry + axis * targetProjection;
            target.y = bot.Position.y;
            producer.LearningV457SuccessorAxis = axis;
            try
            {
                // Position target owns centerline/forward convergence; steering owns facing. These
                // are the same two physical dimensions already required by V352 and do not alter
                // any admission threshold.
                bot.Steering?.BotSteeringLookToDirection("R1-091DEE0ACD41",@bot,axis);
            }
            catch
            {
            }
            source = ("learningV458LatchedJumpReservationForwardAxis");
            return IsFinite(target);
        }

        private static bool TryLeaseLearningV427PendingRollingSuccessorBoundary(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep physicalStep,
            LearningV365ContinuousRouteProducerState producer)
        {
            if ((bot == null) ||
                mission?.Steps == null || physicalStep == null || producer == null ||
                !IsLearningV369PhysicalCorridorStep(physicalStep) ||
                mission.CurrentStepIndex < 0 ||
                mission.CurrentStepIndex + 1 >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep successor = mission.Steps[mission.CurrentStepIndex + 1];
            LearningV354TraversalCapabilityProfile successorProfile = successor != null
                ? GetLearningV354ActionProfile(successor.Kind)
                : null;
            bool canonicalAdjacent =
                (successor != null);
            bool sameAuthoredChain = successor != null && physicalStep.ChainId > 0 &&
                successor.ChainId == physicalStep.ChainId;
            if (successor == null || successorProfile == null ||
                (!sameAuthoredChain && !canonicalAdjacent) ||
                !successorProfile.RequiresActuator || !successorProfile.SupportsRollingEntry)
            {
                return false;
            }

            if ((sameAuthoredChain) &&
                string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                // V427 can be the earliest V353/V429 reservation producer; it must share the
                // same current-episode axis BEFORE a reservation can be granted.
                Vector3 axisBefore = GetFlatDirection(successor.RawExit - successor.RawEntry);
                bool episodeReconciled = TryRefreshLearningV439JumpStepCurrentEpisodeLandingFrontier(
                    bot, mission, successor);
                Vector3 axisAfter = GetFlatDirection(successor.RawExit - successor.RawEntry);
                if (episodeReconciled && axisBefore.sqrMagnitude > 0.5f &&
                    axisAfter.sqrMagnitude > 0.5f && Vector3.Dot(axisBefore, axisAfter) < 0.999f &&
                    ShouldEmitDiagnostic("learningV473JumpAxisReconciledBeforeReservation:" +
                        mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                        successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.18f))
                {
                    WriteEvent("learningV473JumpAxisReconciledBeforeReservation", bot, new
                    {
                        missionId = mission.MissionId,
                        physicalEdgeId = physicalStep.EdgeId,
                        successorEdgeId = successor.EdgeId,
                        beforeAxis = Vec(axisBefore),
                        afterAxis = Vec(axisAfter),
                        nativeSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "v427ReconcileLandingBeforeAnyPreStagingV429Reservation"
                    });
                }
            }

            Vector3 stagingTarget = default;
            bool haveStagingTarget = false;
            bool successorReady = false;
            string stagingSource = string.Empty;
            if (string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                haveStagingTarget = TryGetLearningV353JumpRouteFunnelTarget(
                    bot, successor, out stagingTarget, out successorReady,
                    out _, out _, out _, out _, out _);
                stagingSource = "learningV353JumpRollingFunnel";
                if ((!successorReady) &&
                    TryBuildLearningV448MonotonicJumpOpportunityTarget(
                        bot, successor, out Vector3 learningV448SuccessorTarget, out _))
                {
                    stagingTarget = learningV448SuccessorTarget;
                    haveStagingTarget = true;
                    stagingSource = "learningV448MonotonicJumpOpportunity";
                }
            }
            else
            {
                haveStagingTarget = TryGetLearningV363ActuatorRouteEntryLaneTarget(
                    bot, mission, successor,
                    out stagingTarget, out successorReady, out _,
                    out _, out _, out _, out _, out _, out string laneSource);
                stagingSource = "learningV363ActuatorEntryLane:" + (laneSource ?? string.Empty);
            }

            // V388 owns the exact ready transition. V457 turns V427 from a frame-local staging
            // query into one physical boundary epoch: once the predecessor reaches this boundary,
            // successor admission owns movement direction until it is atomically dispatched or its
            // existing typed physical frontier is genuinely missed.
            bool learningV457LeaseAlreadyActive = (producer.LearningV457SuccessorAdmissionLeaseActive) &&
                producer.LearningV457SuccessorStepIndex == mission.CurrentStepIndex + 1 &&
                producer.LearningV457SuccessorEdgeId == successor.EdgeId &&
                string.Equals(
                    producer.LearningV457SuccessorKind ?? string.Empty,
                    successor.Kind ?? string.Empty,
                    StringComparison.OrdinalIgnoreCase);

            if ((!learningV457LeaseAlreadyActive))
            {
                Vector3 successorEntry = IsFinite(successor.RawEntry) ? successor.RawEntry : successor.Entry;
                Vector3 successorExit = IsFinite(successor.RawExit) ? successor.RawExit : successor.Exit;
                Vector3 successorAxis = GetFlatDirection(successorExit - successorEntry);
                producer.LearningV457SuccessorAdmissionLeaseActive = true;
                producer.LearningV457SuccessorStepIndex = mission.CurrentStepIndex + 1;
                producer.LearningV457SuccessorEdgeId = successor.EdgeId;
                producer.LearningV457SuccessorKind = successor.Kind ?? string.Empty;
                producer.LearningV457SuccessorAxis = successorAxis;
                learningV457LeaseAlreadyActive = true;
                WriteEvent("learningV457SuccessorAdmissionProducerLatched", bot, new
                {
                    missionId = mission.MissionId,
                    predecessorStepIndex = mission.CurrentStepIndex,
                    predecessorEdgeId = physicalStep.EdgeId,
                    successorStepIndex = mission.CurrentStepIndex + 1,
                    successorEdgeId = successor.EdgeId,
                    successorKind = successor.Kind,
                    successorAxis = Vec(successorAxis),
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "semanticPredecessorMayRemainPendingButPhysicalMovementProducerTransfersOnceToImmediateSuccessorAdmission"
                });
            }

            if (successorReady &&
                !string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                // CF61: only non-Jump consumers retain the legacy readiness hold. For Jump,
                // V388 can be waiting for the strict physical trigger horizon even AFTER V353
                // reports ready. Publishing bot.Position as a Jump target there is a zero-length
                // translation order that brakes Sprint into EFT Transition before V429 can jump.
                stagingTarget = bot.Position;
                haveStagingTarget = learningV457LeaseAlreadyActive;
                stagingSource = "learningV457ReadySuccessorAwaitAtomicV388Dispatch";
            }
            else if (learningV457LeaseAlreadyActive &&
                     string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                // CF61: even when V353 reports ready, V388 may wait until the physical trigger
                // horizon. Maintain a NONZERO monotonic authored-axis target throughout that wait.
                // Never replace it with bot.Position, which converted proven Sprint to Transition
                // while consuming the remaining takeoff distance in CF60 Edge87.
                // V353/V448 remain geometry witnesses, not competing movement producers.
                haveStagingTarget = TryBuildLearningV457LatchedSuccessorAdmissionTarget(
                    bot, successor, producer, out stagingTarget, out stagingSource);
                if (haveStagingTarget && successorReady &&
                    ShouldEmitDiagnostic("cf61ReadyJumpForwardProducer:" +
                        mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                        successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.10f))
                {
                    WriteEvent("cf61ReadyJumpForwardProducerPreserved", bot, new
                    {
                        missionId = mission.MissionId,
                        predecessorEdgeId = physicalStep.EdgeId,
                        successorEdgeId = successor.EdgeId,
                        state = bot.GetPlayer?.CurrentStateName.ToString() ?? string.Empty,
                        body = Vec(bot.Position),
                        stagingTarget = Vec(stagingTarget),
                        stagingDistance = GetPlanarDistance(bot.Position, stagingTarget),
                        stagingSource,
                        nativeSuccessRecorded = false,
                        bodyRelocated = false,
                        action = "readyNativeJumpKeepsForwardAxisProducerUntilSameEpochV388V429Consume"
                    });
                }
                if (!haveStagingTarget)
                {
                    // A latched Jump lease may end only because its existing typed frontier has
                    // genuinely been lost. Clear only the physical producer latch; V408 can now
                    // advance the semantic cursor so V433/V450 can choose a current-body HOW.
                    producer.LearningV457SuccessorAdmissionLeaseActive = false;
                    producer.LearningV457SuccessorStepIndex = -1;
                    producer.LearningV457SuccessorEdgeId = 0;
                    producer.LearningV457SuccessorKind = string.Empty;
                    producer.LearningV457SuccessorAxis = Vector3.zero;
                    WriteEvent("learningV457SuccessorAdmissionProducerYieldedAtPhysicalFrontier", bot, new
                    {
                        missionId = mission.MissionId,
                        predecessorStepIndex = mission.CurrentStepIndex,
                        predecessorEdgeId = physicalStep.EdgeId,
                        successorStepIndex = mission.CurrentStepIndex + 1,
                        successorEdgeId = successor.EdgeId,
                        successorKind = successor.Kind,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "typedFrontierLostEndBoundaryLeaseLetExistingCurrentBodyEquivalentHowOwnSuccessor"
                    });
                    return false;
                }
            }
            else if ((!haveStagingTarget || !IsFinite(stagingTarget)) && learningV457LeaseAlreadyActive)
            {
                haveStagingTarget = TryBuildLearningV457LatchedSuccessorAdmissionTarget(
                    bot, successor, producer, out stagingTarget, out stagingSource);
            }

            if (!haveStagingTarget || !IsFinite(stagingTarget))
            {
                return false;
            }

            float targetDistance = GetPlanarDistance(bot.Position, stagingTarget);
            if (!IsFinite(targetDistance) ||
                (!learningV457LeaseAlreadyActive && targetDistance <= 0.001f) ||
                targetDistance > RouteMissionBreadcrumbLookAheadDistance)
            {
                return false;
            }

            producer.Target = stagingTarget;
            // Keep TargetSequence at the predecessor boundary. The route semantic cursor does not
            // consume successor debt here; only the physical producer target is extended until the
            // existing V388 readiness proof can acquire it on a later frame. Do not renew any
            // recovery clock merely because the boundary lease exists; only measured body progress
            // may renew the existing route/recovery lifetime.

            WriteEvent("learningV427PendingRollingSuccessorBoundaryLease", bot, new
            {
                missionId = mission.MissionId,
                predecessorStepIndex = mission.CurrentStepIndex,
                predecessorEpisodeId = physicalStep.EpisodeId,
                predecessorEdgeId = physicalStep.EdgeId,
                predecessorKind = physicalStep.Kind,
                successorStepIndex = mission.CurrentStepIndex + 1,
                successorEpisodeId = successor.EpisodeId,
                successorEdgeId = successor.EdgeId,
                successorKind = successor.Kind,
                stagingTarget = Vec(stagingTarget),
                stagingDistance = targetDistance,
                stagingSource,
                learningV457LeaseAlreadyActive,
                moverPausedForExclusiveTranslation = producer.MoverPausedForExclusiveTranslation,
                moverSprinting = bot.Mover?.Sprinting == true,
                playerState = bot.GetPlayer != null ? bot.GetPlayer.CurrentStateName.ToString() : string.Empty,
                traversalSuccessRecordedForSuccessor = false,
                persistentLearningChangedForSuccessor = false,
                bodyRelocated = false,
                action = ("singleSuccessorAdmissionProducerOwnsBodyUntilAtomicDispatchOrTypedFrontierYield")
            });
            return true;
        }

        private static bool TryGetLearningV460JumpAdmissionGeometry(
            BotOwner bot,
            FollowerRouteMissionStep jumpStep,
            out Vector3 admissionEntry,
            out Vector3 axis,
            out float forwardProjection,
            out float planarSpeed)
        {
            admissionEntry = default;
            axis = default;
            forwardProjection = 0f;
            planarSpeed = 0f;
            if ((bot?.GetPlayer == null) ||
                jumpStep == null ||
                !string.Equals(jumpStep.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 identityRawEntry = IsFinite(jumpStep.RawEntry) ? jumpStep.RawEntry : jumpStep.Entry;
            Vector3 rawExit = IsFinite(jumpStep.RawExit) ? jumpStep.RawExit : jumpStep.Exit;
            admissionEntry = GetLearningV442JumpAdmissionEntry(jumpStep);
            axis = GetFlatDirection(rawExit - identityRawEntry);
            if (!IsFinite(admissionEntry) || axis.sqrMagnitude < 0.5f)
            {
                return false;
            }

            Vector3 bodyOffset = bot.Position - admissionEntry;
            bodyOffset.y = 0f;
            forwardProjection = Vector3.Dot(bodyOffset, axis);
            Vector3 velocity = GetCapabilityJumpPlanarVelocity(bot.GetPlayer);
            velocity.y = 0f;
            planarSpeed = velocity.magnitude;
            return true;
        }

        private static bool TryLeaseLearningV460PreBoundaryRollingJumpAdmission(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep physicalStep,
            LearningV365ContinuousRouteProducerState producer)
        {
            if ((bot == null) ||
                mission?.Steps == null || physicalStep == null || producer == null ||
                !IsLearningV369PhysicalCorridorStep(physicalStep) ||
                mission.CurrentStepIndex < 0 ||
                mission.CurrentStepIndex + 1 >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep successor = mission.Steps[mission.CurrentStepIndex + 1];
            LearningV354TraversalCapabilityProfile successorProfile = successor != null
                ? GetLearningV354ActionProfile(successor.Kind)
                : null;
            bool canonicalAdjacent = (successor != null);
            bool sameAuthoredChain = successor != null && physicalStep.ChainId > 0 &&
                successor.ChainId == physicalStep.ChainId;
            if ((sameAuthoredChain) &&
                successor != null &&
                string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                // Previously V439 ran only after V388 retired the physical predecessor. V429
                // could reserve a geometrically ready Jump on OLD RawExit direction, then V439
                // changed RawExit to the current-episode DropDown entrance in that same frame.
                // V472 raid Mission30: lateral 0.289 -> 0.737 m in 15 ms while body moved
                // only 0.08 m. Reconcile both directions BEFORE any V353/V457/V429 lease.
                Vector3 oldTakeoffAxis = GetFlatDirection(
                    (IsFinite(successor.RawExit) ? successor.RawExit : successor.Exit) -
                    (IsFinite(successor.RawEntry) ? successor.RawEntry : successor.Entry));
                bool refreshed = TryRefreshLearningV439JumpStepCurrentEpisodeLandingFrontier(
                    bot, mission, successor);
                Vector3 reconciledAxis = GetFlatDirection(
                    (IsFinite(successor.RawExit) ? successor.RawExit : successor.Exit) -
                    (IsFinite(successor.RawEntry) ? successor.RawEntry : successor.Entry));
                if (refreshed && oldTakeoffAxis.sqrMagnitude > 0.5f &&
                    reconciledAxis.sqrMagnitude > 0.5f &&
                    Vector3.Dot(oldTakeoffAxis, reconciledAxis) < 0.999f &&
                    ShouldEmitDiagnostic(
                        "learningV473JumpAxisReconciledBeforeReservation:" +
                        mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                        successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.18f))
                {
                    WriteEvent("learningV473JumpAxisReconciledBeforeReservation", bot, new
                    {
                        missionId = mission.MissionId,
                        physicalEdgeId = physicalStep.EdgeId,
                        successorEdgeId = successor.EdgeId,
                        beforeAxis = Vec(oldTakeoffAxis),
                        afterAxis = Vec(reconciledAxis),
                        writer = "Traversal",
                        currentStepIndex = mission.CurrentStepIndex,
                        nativeJumpTriggered = false,
                        nativeSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "materializeSameEpisodeLandingBeforeAnyJumpReservationOrCenterlineAdmission"
                    });
                }
            }
            if (successor == null || successorProfile == null ||
                (!sameAuthoredChain && !canonicalAdjacent) ||
                !successorProfile.RequiresActuator || !successorProfile.SupportsRollingEntry ||
                !string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                !TryGetLearningV460JumpAdmissionGeometry(
                    bot, successor, out Vector3 learningV472AdmissionEntry,
                    out Vector3 learningV472JumpAxis,
                    out float forwardProjection, out float planarSpeed))
            {
                return false;
            }

            float preparationLead = GetLearningV452JumpPreparationLeadDistance(planarSpeed);
            float originalPreparationLead = preparationLead;
            float learningV472LateralOffset = 0f;
            bool learningV472EarlyCenterlineAdmission = false;
            if ((sameAuthoredChain) && !IsTeleportTransactionActive(bot) &&
                !producer.Generic && producer.MissionId == mission.MissionId &&
                producer.StepIndex == mission.CurrentStepIndex &&
                FollowerMovementWriterAuthority.GetCurrentGeneration(
                    bot, out FollowerMovementWriterAuthority.WriterDomain learningV472Owner) > 0 &&
                learningV472Owner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                IsFinite(learningV472AdmissionEntry) &&
                learningV472JumpAxis.sqrMagnitude > 0.5f)
            {
                // V4.72: V470/V471 fence witnesses show that preloading at only the
                // animation lead distance is too late when a fast bot is still lateral
                // to the Jump line. That lead measures animation latency, not the
                // physical distance needed for centerline convergence. Compute the
                // *additional* path-length from the live lateral error using the
                // existing V3.53 rolling alignment angle and existing route lookahead.
                // No new Jump readiness threshold, gain, sample, timer, or success
                // credit is introduced. Only the ONE existing V427/V457 predecessor
                // producer may steer earlier toward the exact typed Jump centerline.
                Vector3 learningV472Delta = bot.Position - learningV472AdmissionEntry;
                learningV472Delta.y = 0f;
                Vector3 learningV472Lateral = learningV472Delta -
                    learningV472JumpAxis * Vector3.Dot(learningV472Delta, learningV472JumpAxis);
                learningV472LateralOffset = learningV472Lateral.magnitude;
                if (learningV472LateralOffset > LearningV352JumpTakeoffCorridorMaxLateral)
                {
                    float learningV472AlignmentRadian = ProbeRollingAlignmentAngle * Mathf.Deg2Rad;
                    float learningV472RequiredPath =
                        (learningV472LateralOffset - LearningV352JumpTakeoffCorridorMaxLateral) /
                        Mathf.Max(0.01f, Mathf.Tan(learningV472AlignmentRadian));
                    // V4.73: V472 budgeted only the INBOUND lateral correction. In Mission28
                    // the bot reached lateral=0.056 m at the takeoff plane but velocity dot=0.836
                    // (< existing 0.94 proof): the outbound tangent had no room to realign.
                    // Use the same proven 18-degree curvature envelope twice (turn IN + turn OUT)
                    // before the existing actuator lead. This is geometry, not a timeout/gain,
                    // and does not relax V352/V449/V450 Jump safety thresholds.
                    float learningV473TwoLegPath = (learningV472RequiredPath + learningV472RequiredPath);
                    preparationLead = Mathf.Min(RouteMissionBreadcrumbLookAheadDistance,
                        originalPreparationLead + learningV473TwoLegPath);
                    learningV472EarlyCenterlineAdmission =
                        forwardProjection < -originalPreparationLead &&
                        forwardProjection >= -preparationLead;
                }
                // A previously acquired live producer lease is the same body epoch.
                // Do not allow improved lateral geometry to shrink the admission
                // budget in a later frame and hand the body back to the predecessor.
                if (producer.LearningV457SuccessorAdmissionLeaseActive &&
                    producer.LearningV457SuccessorStepIndex == mission.CurrentStepIndex + 1 &&
                    producer.LearningV457SuccessorEdgeId == successor.EdgeId &&
                    string.Equals(producer.LearningV457SuccessorKind, "Jump",
                        StringComparison.OrdinalIgnoreCase) &&
                    forwardProjection < -preparationLead &&
                    forwardProjection >= -RouteMissionBreadcrumbLookAheadDistance)
                {
                    preparationLead = -forwardProjection;
                }
            }
            if (forwardProjection < -preparationLead ||
                IsLearningV449JumpTakeoffFrontierMissed(forwardProjection))
            {
                return false;
            }

            if (!TryLeaseLearningV427PendingRollingSuccessorBoundary(
                    bot, mission, physicalStep, producer))
            {
                return false;
            }

            if (ShouldEmitDiagnostic(
                    "learningV460PreBoundarySuccessorAdmissionLease:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.12f))
            {
                WriteEvent("learningV460PreBoundarySuccessorAdmissionLease", bot, new
                {
                    missionId = mission.MissionId,
                    predecessorStepIndex = mission.CurrentStepIndex,
                    predecessorEdgeId = physicalStep.EdgeId,
                    predecessorKind = physicalStep.Kind,
                    successorStepIndex = mission.CurrentStepIndex + 1,
                    successorEdgeId = successor.EdgeId,
                    successorKind = successor.Kind,
                    forwardProjection,
                    preparationLead,
                    originalPreparationLead,
                    learningV472LateralOffset,
                    learningV472EarlyCenterlineAdmission,
                    planarSpeed,
                    body = Vec(bot.Position),
                    stagingTarget = Vec(producer.Target),
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "rollingJumpPhysicalAdmissionBeginsInsideExistingPreparationEnvelopeBeforeSemanticPredecessorRetires"
                });
            }
            if (learningV472EarlyCenterlineAdmission &&
                ShouldEmitDiagnostic(
                    "learningV472GeometryBudgetedJumpCenterlinePreAdmission:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.18f))
            {
                WriteEvent("learningV472GeometryBudgetedJumpCenterlinePreAdmission", bot, new
                {
                    missionId = mission.MissionId,
                    physicalEdgeId = physicalStep.EdgeId,
                    successorEdgeId = successor.EdgeId,
                    successorKind = successor.Kind,
                    forwardProjection,
                    learningV472LateralOffset,
                    requiredLateral = LearningV352JumpTakeoffCorridorMaxLateral,
                    originalPreparationLead,
                    geometryBudgetedLead = preparationLead,
                    twoLegTangentBudget = true,
                    centerlineAngle = ProbeRollingAlignmentAngle,
                    movementWriter = "Traversal",
                    nativeJumpTriggered = false,
                    nativeSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "prepareExistingSinglePhysicalJumpProducerEarlyEnoughForObservedLateralConvergenceWithoutChangingNativeAdmission"
                });
            }
            return true;
        }

        private static bool TryHandoffLearningV388PhysicalCorridorToReadySuccessor(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep physicalStep)
        {
            if ((bot == null) ||
                mission?.Steps == null || physicalStep == null ||
                (!IsLearningV369PhysicalCorridorStep(physicalStep)&&!IsCapabilityWalkPrefixForJump(bot,mission,physicalStep)) || HasActiveTraversalProbe(bot) ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex + 1 >= mission.Steps.Count)
            {
                return false;
            }

            int physicalIndex = mission.CurrentStepIndex;
            FollowerRouteMissionStep successor = mission.Steps[physicalIndex + 1];
            bool learningV389CanonicalMissionAdjacentSuccessor =
                (successor != null);
            bool sameAuthoredChain = successor != null && physicalStep.ChainId > 0 &&
                successor.ChainId == physicalStep.ChainId;
            if ((sameAuthoredChain) &&
                successor != null &&
                string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                // Last-chance same-epoch reconciliation for a directly ready successor.
                // V460 performs this earlier when the continuous producer can stage.
                TryRefreshLearningV439JumpStepCurrentEpisodeLandingFrontier(bot, mission, successor);
            }
            if (successor == null || (!sameAuthoredChain && !learningV389CanonicalMissionAdjacentSuccessor))
            {
                return false;
            }
            LearningV354TraversalCapabilityProfile successorProfile =
                GetLearningV354ActionProfile(successor.Kind);
            if (successorProfile == null || !successorProfile.RequiresActuator ||
                !successorProfile.SupportsRollingEntry)
            {
                return false;
            }

            bool ready = false;
            string readinessSource = string.Empty;
            float entryDistance = GetPlanarDistance(bot.Position, successor.Entry);
            if (string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                ready = TryGetLearningV353JumpRouteFunnelTarget(
                    bot, successor, out _, out bool jumpReady,
                    out _, out _, out _, out _, out _) && jumpReady;
                readinessSource = "learningV353JumpRollingFunnel";

                // V4.60: a live V4.29 reservation in the current Traversal writer epoch is already
                // a concrete Jump consumer. Do not strand that reservation behind a semantic
                // PhysicalCorridor step until the body passes the takeoff plane. This does NOT
                // trigger TryJump here; it only advances ownership so the canonical Jump probe can
                // consume the same reservation under the existing V449/V459 actuator rules.
                if (!ready &&
                    TryGetLearningV460JumpAdmissionGeometry(
                        bot, successor, out _, out _, out float reservedForwardProjection, out _) &&
                    TryGetLearningV455LiveJumpFirstRefusalEnvelope(
                        bot, successor, reservedForwardProjection, out float reservedMaxForwardProjection))
                {
                    ready = true;
                    readinessSource = "learningV460LiveV429ReservationConsumer";
                    if (ShouldEmitDiagnostic(
                            "learningV460ReservedJumpAtomicHandoff:" +
                            mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                            successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.12f))
                    {
                        WriteEvent("learningV460ReservedJumpAtomicHandoff", bot, new
                        {
                            missionId = mission.MissionId,
                            predecessorStepIndex = physicalIndex,
                            predecessorEdgeId = physicalStep.EdgeId,
                            successorStepIndex = physicalIndex + 1,
                            successorEdgeId = successor.EdgeId,
                            successorKind = successor.Kind,
                            forwardProjection = reservedForwardProjection,
                            maxForwardProjection = reservedMaxForwardProjection,
                            body = Vec(bot.Position),
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = "livePhysicalReservationIsConcreteConsumerReadinessAdvanceSemanticCursorBeforeTakeoffOpportunityCanBeLost"
                        });
                    }
                }
            }
            else if (TryGetLearningV363ActuatorRouteEntryLaneTarget(
                         bot, mission, successor,
                         out _, out bool laneReady, out _, out _, out _, out _, out _, out _, out string laneSource))
            {
                ready = laneReady;
                readinessSource = "learningV363ActuatorEntryLane:" + (laneSource ?? string.Empty);
            }
            if ((ShouldEmitDiagnostic("learningV470JumpBoundaryHeadingWitness:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.18f)) &&
                string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                TryGetLearningV460JumpAdmissionGeometry(
                    bot, successor, out _, out Vector3 learningV470JumpAxis,
                    out float learningV470ForwardProjection, out float learningV470PlanarSpeed))
            {
                Vector3 learningV470Velocity = bot.GetPlayer.Velocity;
                learningV470Velocity.y = 0f;
                Vector3 learningV470StagingDirection = Vector3.zero;
                bool learningV470StagingAvailable = false;
                if (!string.IsNullOrEmpty(bot.ProfileId) &&
                    LearningV365ContinuousRouteProducerStates.TryGetValue(
                        bot.ProfileId, out LearningV365ContinuousRouteProducerState learningV470Producer) &&
                    learningV470Producer != null && !learningV470Producer.Generic &&
                    learningV470Producer.MissionId == mission.MissionId &&
                    learningV470Producer.StepIndex == physicalIndex &&
                    IsFinite(learningV470Producer.Target))
                {
                    learningV470StagingDirection = GetFlatDirection(learningV470Producer.Target - bot.Position);
                    learningV470StagingAvailable = learningV470StagingDirection.sqrMagnitude > 0.5f;
                }
                bool cf60ForecastEligible = IsCf60LegalOneFrameJumpTriggerForecast(
                    bot, learningV470ForwardProjection, learningV470PlanarSpeed,
                    out float cf60BoundaryFrameDistance, out float cf60BoundaryNativeLead);
                WriteEvent("learningV470JumpBoundaryHeadingWitness", bot, new
                {
                    cf60ForecastEligible,
                    cf60BoundaryFrameDistance,
                    cf60BoundaryNativeLead,
                    playerState = bot.GetPlayer.CurrentStateName.ToString(),
                    isGrounded = bot.GetPlayer.MovementContext?.IsGrounded == true,
                    canJump = bot.GetPlayer.MovementContext?.CanJump == true,
                    missionId = mission.MissionId,
                    predecessorStepIndex = physicalIndex,
                    successorStepIndex = physicalIndex + 1,
                    successorEdgeId = successor.EdgeId,
                    readinessSource,
                    forwardProjection = learningV470ForwardProjection,
                    planarSpeed = learningV470PlanarSpeed,
                    velocityHeadingDot = learningV470Velocity.sqrMagnitude > 0.01f
                        ? Vector3.Dot(learningV470Velocity.normalized, learningV470JumpAxis) : 0f,
                    stagingHeadingDot = learningV470StagingAvailable
                        ? Vector3.Dot(learningV470StagingDirection, learningV470JumpAxis) : 0f,
                    stagingTargetValid = learningV470StagingAvailable,
                    nativeSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "observeExactPreJumpHeadingContinuityWithoutChangingV388Admission"
                });
            }
            if (!ready)
            {
                return false;
            }

            // CF39: PhysicalCorridor -> Jump may reserve the successor at the outer
            // 0.95m rolling window, but handing the body to a Jump probe there
            // is too early.  In the 2026-10-12 Edge 87 replay the corridor was
            // still Sprinting at -0.922m; the probe owned the next frame as EFT
            // Transition and spent the WHOLE physical takeoff window unable to
            // call TryJump.  The existing V449 trigger horizon is the earliest
            // point where the exact Native consumer can take the body and
            // atomically trigger in the SAME dispatch frame.  Until then the
            // canonical PhysicalCorridor keeps its existing producer and writer.
            // Do not change native Jump mode, speed, geometry, or success gates.
            if (string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                successor.LearningV429JumpAdmissionReserved &&
                TryGetLearningV460JumpAdmissionGeometry(
                    bot, successor, out _, out _,
                    out float cf39ForwardProjection, out float cf39PhysicalSpeed) &&
                !IsLearningV449JumpTakeoffFrontierMissed(cf39ForwardProjection) &&
                !IsLearningV449JumpInsidePhysicalTriggerHorizon(
                    cf39ForwardProjection, cf39PhysicalSpeed, bot) &&
                !IsCf60LegalOneFrameJumpTriggerForecast(
                    bot, cf39ForwardProjection, cf39PhysicalSpeed,
                    out _, out _))
            {
                long cf39Generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                    bot, out FollowerMovementWriterAuthority.WriterDomain cf39Owner);
                if (cf39Owner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                    cf39Generation > 0 &&
                    successor.LearningV429JumpAdmissionMovementGeneration == cf39Generation)
                {
                    if (ShouldEmitDiagnostic(
                        "cf39CorridorJumpHandoffAwaitNativeTriggerHorizon:" +
                        mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                        successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.25f))
                    {
                        WriteEvent("cf39CorridorJumpHandoffAwaitNativeTriggerHorizon", bot, new
                        {
                            missionId = mission.MissionId,
                            physicalStepIndex = physicalIndex,
                            physicalEdgeId = physicalStep.EdgeId,
                            successorStepIndex = physicalIndex + 1,
                            successorEdgeId = successor.EdgeId,
                            forwardEntryProjection = cf39ForwardProjection,
                            planarSpeed = cf39PhysicalSpeed,
                            nativeTriggerLead = GetLearningV449JumpPhysicalTriggerLeadDistance(cf39PhysicalSpeed),
                            movementGeneration = cf39Generation,
                            bodyRelocated = false,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "retainLivePhysicalCorridorUntilExistingNativeJumpTriggerHorizonNoPrematureProbeHandoff"
                        });
                    }
                    return false;
                }
            }

            if (string.Equals(successor.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                successor.LearningV429JumpAdmissionReserved &&
                TryGetLearningV460JumpAdmissionGeometry(
                    bot, successor, out _, out _,
                    out float cf60Projection, out float cf60PlanarSpeed) &&
                IsCf60LegalOneFrameJumpTriggerForecast(
                    bot, cf60Projection, cf60PlanarSpeed,
                    out float cf60OneFrameTravel, out float cf60NativeTriggerLead) &&
                ShouldEmitDiagnostic("cf60OneFrameBoundaryForecast:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    successor.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.10f))
            {
                WriteEvent("cf60OneFrameBoundaryForecastAdmission", bot, new
                {
                    missionId = mission.MissionId,
                    predecessorStepIndex = physicalIndex,
                    predecessorEdgeId = physicalStep.EdgeId,
                    successorStepIndex = physicalIndex + 1,
                    successorEdgeId = successor.EdgeId,
                    state = bot.GetPlayer.CurrentStateName.ToString(),
                    writerGeneration = successor.LearningV429JumpAdmissionMovementGeneration,
                    forwardEntryProjection = cf60Projection,
                    measuredPlanarSpeed = cf60PlanarSpeed,
                    physicalTriggerLeadDistance = cf60NativeTriggerLead,
                    oneFrameDistance = cf60OneFrameTravel,
                    nativeSuccessRecorded = false,
                    bodyRelocated = false,
                    action = "allowExactSameFrameNativeConsumerToCheckOriginalStrictStateAndMomentum"
                });
            }

            // V2 A3.1: readiness is not ownership. Re-check the identical
            // predecessor + successor Step references immediately before any
            // execution floor, debt, or mission cursor can be mutated.
            if (!TryValidateV2AdjacentPhysicalContinuationBoundary(
                    bot, mission, physicalStep, successor, true, out string boundaryRejectReason))
            {
                RecordV2TypedStepLeaseRejection(bot, mission, physicalStep,
                    "learningV388ReadySuccessorBeforeCommit",
                    boundaryRejectReason, "v2rc73PhysicalContinuationBoundaryRejected");
                return false;
            }
            RecordV2PhysicalContinuationBoundary(bot, mission, physicalStep, successor,
                "readyPhysicalCorridorHandoff", readinessSource);
            string profileId = bot.ProfileId ?? string.Empty;
            int previousExecutionFloor = GetFollowerRouteExecutionFloor(profileId);
            int newExecutionFloor = Math.Max(previousExecutionFloor, physicalStep.EndBreadcrumbSequence);
            if (!string.IsNullOrEmpty(profileId))
            {
                FollowerRouteExecutionFloors[profileId] = newExecutionFloor;
            }
            mission.ResumeFloorBreadcrumbSequence = Math.Max(
                mission.ResumeFloorBreadcrumbSequence, newExecutionFloor);
            ConsumeFollowerRouteMissionPhysicalPass(
                bot, mission, physicalStep,
                "learningV388PhysicalCorridorReadySuccessorHandoff", 0f, 0f);
            MarkLearningV388PhysicalPassageExecutionDebtConsumed(
                bot, physicalStep, "learningV388PhysicalCorridorReadySuccessorHandoff");
            MarkFollowerTraversalEpisodeCompleted(bot, physicalStep.EpisodeId, physicalStep.EdgeId);
            int learningV391AuthoritativeSuccessorStepIndex = mission.CurrentStepIndex;
            mission.LastProgressAt = Time.time;
            mission.LastProgressPosition = bot.Position;
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;
            mission.LearningV355ProgressStepIndex = -1;
            ClearLearningV365ContinuousPhysicalRoute(
                bot, "learningV388PhysicalCorridorReadySuccessorHandoff");
            LearnedTraversalCommitments.Remove(profileId);

            bool commitmentBound = EnsureFollowerRouteMissionCommitment(bot, mission);
            string dispatchResult = commitmentBound ? "readinessPending" : "commitmentUnavailable";
            bool dispatched = commitmentBound &&
                TryDispatchLearningV378PersistentActuatorFrontierProbe(
                    bot, mission, successor.EdgeId, successor.Kind, out dispatchResult);
            WriteEvent("learningV388PhysicalCorridorReadySuccessorHandoff", bot, new
            {
                missionId = mission.MissionId,
                physicalStepIndex = physicalIndex,
                physicalEpisodeId = physicalStep.EpisodeId,
                physicalEdgeId = physicalStep.EdgeId,
                successorStepIndex = learningV391AuthoritativeSuccessorStepIndex,
                successorEpisodeId = successor.EpisodeId,
                successorEdgeId = successor.EdgeId,
                successorKind = successor.Kind,
                physicalChainId = physicalStep.ChainId,
                successorChainId = successor.ChainId,
                sameAuthoredChain,
                canonicalMissionAdjacentSuccessor = learningV389CanonicalMissionAdjacentSuccessor,
                entryDistance,
                readinessSource,
                previousExecutionFloor,
                newExecutionFloor,
                commitmentBound,
                dispatched,
                dispatchResult = dispatchResult ?? string.Empty,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "readySameChainActuatorInheritsLivePhysicalCorridorBodyBeforeTerminalCursorCanBrakeMomentum"
            });
            return true;
        }

        private static void RefreshLearningV424RecoveryLeaseFromTypedPhysicalProgress(
            BotOwner bot,
            LearningV365ContinuousRouteProducerState producer,
            Vector3 body,
            string source)
        {
            if ((bot == null) || producer == null || producer.Generic ||
                producer.LearningV386LastMeasuredForwardProgressAt < 0f || !IsFinite(body))
            {
                return;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowerMovementRecoveryStates.TryGetValue(
                    profileId, out FollowerMovementRecoveryState recovery) ||
                recovery == null || recovery.LearningV350GenericPassageArmedAt < 0f ||
                recovery.LearningV350TerminalRecoveryEligible ||
                producer.LearningV386LastMeasuredForwardProgressAt <= recovery.LearningV349LastPhysicalProgressAt)
            {
                return;
            }

            // V4.24: the typed breadcrumb producer can prove progress only when it reaches/passes a
            // current-raid breadcrumb (V386) or accumulates the existing measured body+closure proof.
            // V350 is the recovery consumer for the same body epoch; copy that exact timestamp into
            // its liveness state instead of inventing a second timeout or treating movement intent as
            // progress. The existing hard-recovery duration remains the only lease length.
            float progressAt = producer.LearningV386LastMeasuredForwardProgressAt;
            recovery.LearningV349LastPhysicalPosition = body;
            recovery.LearningV349LastPhysicalProgressAt = progressAt;
            recovery.LearningV349PhysicalStallSince = -1f;
            recovery.LearningV349GenericPassageLeaseUntil = Mathf.Max(
                recovery.LearningV349GenericPassageLeaseUntil,
                progressAt + RouteMissionHardRecoverySeconds);

            if (ShouldEmitDiagnostic(
                    "learningV424TypedPhysicalProgressRenewedRecoveryLease:" + profileId, bot, 0.18f))
            {
                WriteEvent("learningV424TypedPhysicalProgressRenewedRecoveryLease", bot, new
                {
                    missionId = producer.MissionId,
                    stepIndex = producer.StepIndex,
                    edgeId = producer.EdgeId,
                    breadcrumbSequence = producer.TargetSequence,
                    measuredProgressAt = progressAt,
                    leaseUntil = recovery.LearningV349GenericPassageLeaseUntil,
                    source = source ?? string.Empty,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "sameMeasuredPhysicalProgressFeedsRouteProducerAndExistingRecoveryConsumer"
                });
            }
        }

        private static bool TryRetireLearningV435WalkThroughDebtOnDownstreamNavMeshRejoin(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            string source)
        {
            if ((bot == null) || mission == null || step == null ||
                !string.Equals(step.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                step.EpisodeId <= 0 || step.EdgeId <= 0 ||
                HasActiveTraversalProbe(bot))
            {
                return false;
            }

            if (!TryResolveLearningV424CurrentEpisodeWalkThroughGeometry(
                    step.EdgeId, step.EpisodeId, 0, 0,
                    out TraversalEpisodeMetadata episode,
                    out Vector3 executionEntry,
                    out Vector3 executionExit))
            {
                return false;
            }

            Vector3 axis = executionExit - executionEntry;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < WalkThroughPassageSampleMinPlanarSpacing)
            {
                return false;
            }
            Vector3 direction = axis / span;
            Vector3 body = bot.GetPlayer != null ? bot.GetPlayer.Position : bot.Position;
            if (!IsFinite(body))
            {
                return false;
            }

            Vector3 fromEntry = body - executionEntry;
            fromEntry.y = 0f;
            float projection = Vector3.Dot(fromEntry, direction);
            Vector3 axisPoint = executionEntry + direction * projection;
            float lateral = GetPlanarDistance(body, axisPoint);
            bool crossedFiniteFarSide =
                FollowerCapabilityHelperRules.TryRetireLearningV435WalkThroughDebtOnDownstreamNavMeshRejoin_crossedFiniteFarSide_25D4784E_1(projection,LearningV32EntryProgressEpsilon,span,lateral,WalkThroughPassageStraightLateralTolerance);
            if (!crossedFiniteFarSide)
            {
                return false;
            }

            Player leader = FollowerEnvironment.LocalPlayer;
            if (!IsLivePlayer(leader) || !IsFinite(leader.Position))
            {
                return false;
            }
            StrictPathResult strict = CalculateStrictPath(body, leader.Position);
            if (strict == null || !strict.StartSampled || !strict.TargetSampled || !strict.StrictComplete)
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            int previousExecutionFloor = GetFollowerRouteExecutionFloor(profileId);
            int newExecutionFloor = Math.Max(previousExecutionFloor, step.EndBreadcrumbSequence);
            if (!string.IsNullOrEmpty(profileId))
            {
                FollowerRouteExecutionFloors[profileId] = newExecutionFloor;
            }
            mission.ResumeFloorBreadcrumbSequence = Math.Max(
                mission.ResumeFloorBreadcrumbSequence, newExecutionFloor);

            bool routeDebtConsumed = ConsumeFollowerRouteMissionPhysicalPass(
                bot, mission, step,
                "learningV435WalkThroughDownstreamNavMeshRejoin",
                projection, span);
            bool executionDebtConsumed = MarkLearningV388PhysicalPassageExecutionDebtConsumed(
                bot, step, "learningV435WalkThroughDownstreamNavMeshRejoin");

            // This is runtime route debt retirement only. The ordinary NavMesh path proves that the
            // body has rejoined downstream navigation after crossing the finite WT far-side plane;
            // it does NOT fabricate WalkThrough/Native/executor success.
            int previousStepIndex = mission.CurrentStepIndex;
            MarkFollowerTraversalEpisodeCompleted(bot, step.EpisodeId, step.EdgeId);
            ClearLearningV365ContinuousPhysicalRoute(
                bot, "learningV435WalkThroughDownstreamNavMeshRejoin");

            WriteEvent("learningV435WalkThroughDownstreamNavMeshRejoinRetiredExecutionDebt", bot, new
            {
                missionId = mission.MissionId,
                previousStepIndex,
                currentStepIndex = mission.CurrentStepIndex,
                episodeId = step.EpisodeId,
                authoredEpisodeEdgeId = episode?.EdgeId ?? 0,
                edgeId = step.EdgeId,
                projection,
                span,
                lateral,
                body = Vec(body),
                executionEntry = Vec(executionEntry),
                executionExit = Vec(executionExit),
                strictPath = strict.ToPayload(),
                previousExecutionFloor,
                newExecutionFloor,
                routeDebtConsumed,
                executionDebtConsumed,
                source = source ?? string.Empty,
                traversalSuccessRecorded = false,
                nativeSuccessRecorded = false,
                persistentLearningChanged = false,
                recoveryTeleportUsed = false,
                bodyRelocated = false,
                action = "finitePassageFarSidePlusHealthyDownstreamNavMeshRetiresOnlyRuntimeExecutionDebtAndReturnsMovementToCanonicalFollow"
            });
            return true;
        }

        // RC61: TryContinueLearningV365ContinuousTypedPhysicalRoute extracted unchanged to FollowerTraversalPhysicalContinuum.cs.

        private static bool TryAdvanceLearningV365GenericPhysicalTarget(
            BotOwner bot,
            FollowerMovementRecoveryState recovery,
            LearningV365ContinuousRouteProducerState producer)
        {
            if (bot == null || recovery == null || producer == null)
            {
                return false;
            }

            int resolvedFloor=CapabilityGenericResumeFloor(bot);
            if(!FollowerCapabilityPassagePolicy.TargetAfterFloor(producer.Generic,producer.TargetSequence,resolvedFloor))
            {
                recovery.LearningV349GenericPassageCursorSequence=Math.Max(recovery.LearningV349GenericPassageCursorSequence,resolvedFloor);
                recovery.LowStepActive=false;recovery.LowStepAttempted=false;
                ClearLearningV365ContinuousPhysicalRoute(bot,"genericTargetBehindCompletedRouteFloor");return false;
            }
            // CF20: reaching a historical breadcrumb by radius alone is insufficient
            // for a traversal-owned terminal physical consumer. CF19 Climb Edge16
            // landed successfully, but the body repeatedly travelled PAST sequence
            // 368 without coming within the strict 0.5m 3D radius. The old consumer
            // steered back to 368 for ~10 seconds while live leader breadcrumbs moved
            // onward and the strict Follow/NavMesh path correctly failed closed.
            //
            // The only added advancement is a PHYSICAL, ordered, bounded witness:
            // the body lies beyond the immediate successor's forward crossing plane,
            // inside the existing 1.15m route reach lane and at a compatible height.
            // Never skip by time, leader distance, arbitrary nearest breadcrumb, or
            // path success claims. No traversal completion or experience is credited.
            int examined = 0;
            while (examined++ < BreadcrumbRoute.Count)
            {
                float reachDistance = (BreadcrumbMinDistance);
                float distance = (Vector3.Distance(bot.Position, producer.Target));
                bool radiusReached = distance <= reachDistance;
                bool traversalOwned = producer.LearningV423TraversalOwnedGeneration > 0;
                PlayerBreadcrumbNode successor = BreadcrumbRoute.FirstOrDefault(candidate =>
                    candidate != null && candidate.Sequence > producer.TargetSequence &&
                    IsOperationalBreadcrumbNode(candidate) && IsFinite(candidate.Position) &&
                    GetPlanarDistance(bot.Position, candidate.Position) <= RouteMissionBreadcrumbLookAheadDistance);
                // For the NEW crossing proof the successor must truly be the
                // earliest operational newer node, not just a farther breadcrumb
                // that happens to be within lookahead on a folding route.
                PlayerBreadcrumbNode immediateSuccessor = BreadcrumbRoute.FirstOrDefault(candidate =>
                    candidate != null && candidate.Sequence > producer.TargetSequence &&
                    IsOperationalBreadcrumbNode(candidate) && IsFinite(candidate.Position));
                bool physicallyPassed = false;
                if (!radiusReached && traversalOwned && successor != null &&
                    immediateSuccessor != null &&
                    successor.Sequence == immediateSuccessor.Sequence)
                {
                    physicallyPassed = FollowerGenericRouteCursorContract.IsSuccessorPhysicallyPassed(
                        bot.Position, producer.Target, successor.Position,
                        RouteMissionBreadcrumbReachDistance,
                        LearningV350MeasuredTargetProgressDistance);
                }
                if (!radiusReached && !physicallyPassed)
                {
                    return true;
                }
                if (successor == null)
                {
                    // Keep the original no-successor behavior. It must not silently
                    // reuse a consumed target or manufacture any new route segment.
                    ClearLearningV365ContinuousPhysicalRoute(bot, "genericAwaitNextBreadcrumb");
                    return false;
                }
                int consumedSequence = producer.TargetSequence;
                Vector3 consumedTarget = producer.Target;
                recovery.LearningV349GenericPassageCursorSequence = Math.Max(
                    recovery.LearningV349GenericPassageCursorSequence, consumedSequence);
                producer.TargetSequence = successor.Sequence;
                producer.Target = successor.Position;
                producer.Pose = Mathf.Clamp01(successor.Pose);
                if (physicallyPassed && ShouldEmitDiagnostic(
                    "cf20TerminalPhysicalBreadcrumbForwardWitness", bot, 0.2f))
                {
                    WriteEvent("cf20TerminalPhysicalBreadcrumbForwardWitness", bot, new
                    {
                        consumedSequence,
                        successorSequence = successor.Sequence,
                        body = Vec(bot.Position),
                        passedTarget = Vec(consumedTarget),
                        consumerGeneration = producer.LearningV423TraversalOwnedGeneration,
                        physicalEvidence = true,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "advanceOrderedPhysicalBreadcrumbCursorOnlyAfterBoundedBodyCrossingWitness"
                    });
                }
            }
            // Defensive: a bad breadcrumb cycle must never turn into an unlimited
            // game-frame while-loop. Next frame retains normal guarded arbitration.
            return true;
        }

        private static bool TryContinueLearningV365ContinuousGenericPhysicalRoute(BotOwner bot, out int targetSequence)
        {
            targetSequence = 0;
