            if (!FollowerMovementRecoveryStates.TryGetValue(profileId, out FollowerMovementRecoveryState recovery) ||
                recovery == null)
            {
                ClearLearningV365ContinuousPhysicalRoute(bot, "genericRecoveryStateMissing");
                return false;
            }
            if (Time.time > recovery.LearningV349GenericPassageLeaseUntil)
            {
