                    bool rc116StepAssist=TryDriveCapabilityGenericLowStep(bot,player,recovery,producer,direction,generation,dt);
                    bool learningV438TerminalLocomotionLease =
                        (producer.LearningV423TraversalOwnedGeneration > 0);
