                ? Vector3.Dot(cumulative, learningV380GenericProgressDirection)
                : 0f;
            bool measured = FollowerCapabilityApproachPolicy.HorizontalProgress(cumulativeDisplacement,cumulativeForward,
                LearningV350MeasuredPhysicalProgressDistance,LearningV350MeasuredTargetProgressDistance);
            if (measured)
            {
