                if ((producer.LearningV423TraversalOwnedGeneration > 0))
                {
                    recovery.LearningV349GenericPassageLeaseUntil = Mathf.Max(
                        recovery.LearningV349GenericPassageLeaseUntil,
                        Time.time + RouteMissionHardRecoverySeconds);
                }
                if ((!recovery.LearningV350TerminalRecoveryEligible))
                {
                    recovery.LearningV350TerminalRecoveryEligible = false;
                }
            }
            if (ShouldEmitDiagnostic("learningV365ContinuousGenericPhysicalRouteProducer", bot, 0.35f))
            {
                WriteEvent("learningV365ContinuousPhysicalRouteProducer", bot, new
                {
                    missionId = 0,
                    stepIndex = -1,
                    episodeId = 0,
                    edgeId = 0,
                    kind = "PhysicalCorridor",
                    breadcrumbSequence = producer.TargetSequence,
                    target = Vec(producer.Target),
                    physicalDisplacement = (Vector3.Distance(before, after)),
                    targetClosure = beforeTargetDistance - ((Vector3.Distance(after, producer.Target))),
                    verticalTargetError = producer.Target.y - before.y,
                    threeDimensionalPhysicalPassage = true,
                    cumulativePhysicalDisplacement = cumulativeDisplacement,
                    cumulativeRouteForwardProgress = cumulativeForward,
                    measuredPhysicalProgress = measured,
                    frame,
                    movementOwner = movementDomain.ToString(),
                    movementGeneration = generation,
                    traversalOwnedContinuation =
                        producer.LearningV423TraversalOwnedGeneration > 0,
                    locomotionModeLeasePreserved = (producer.LearningV423TraversalOwnedGeneration > 0),
                    moverSprinting = bot.Mover?.Sprinting == true,
                    playerState = player.CurrentStateName.ToString(),
                    producer = "genericEmpiricalPassage",
                    action = producer.LearningV423TraversalOwnedGeneration > 0
                        ? (("terminalPhysicalContinuationConsumesExistingTraversalEpochAndPreservesNativeLocomotionModeUntilFreshFollowExists"))
                        : "integrateAlreadyAdmittedPhysicalRouteWithoutPerFramePathReplanning"
                });
            }
            return true;
        }

        private static void UpdateLearningV365ContinuousEmpiricalRouteProducer(BotOwner bot)
        {
            if ((bot == null) || HasActiveTraversalProbe(bot))
            {
                return;
            }
            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !LearningV365ContinuousRouteProducerStates.TryGetValue(profileId, out LearningV365ContinuousRouteProducerState producer) ||
                producer == null)
            {
                return;
            }
            if (producer.Generic)
            {
                TryContinueLearningV365ContinuousGenericPhysicalRoute(bot, out _);
                return;
            }
            if (!TryGetActiveFollowerRouteMission(bot, out FollowerRouteMission mission) ||
                mission.Steps == null || mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                ClearLearningV365ContinuousPhysicalRoute(bot, "typedMissionEnded");
                return;
            }
            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || mission.MissionId != producer.MissionId || step.EdgeId != producer.EdgeId)
            {
                ClearLearningV365ContinuousPhysicalRoute(bot, "typedMissionIdentityChanged");
                return;
            }

            // V373: V357 already marks a strict actuator debt once bounded self-rescue is exhausted,
            // but the continuous pre-entry producer can otherwise immediately reacquire the stale
            // entry after the failed probe retires. Consume that existing debt proof here, before
            // another physical-producer frame rewrites the body toward the old action. This retires
            // EXECUTION debt only; the demonstrated semantic remains intact and no success is minted.
            if (TryRetireLearningV373ExhaustedPhysicalDebtByDownstreamBodyEpoch(
                    bot, mission, "continuousPhysicalProducerBeforeStaleEntryReacquire",
                    out _, out _))
            {
                ClearLearningV365ContinuousPhysicalRoute(
                    bot, "learningV373ExhaustedPhysicalDebtRetiredBeforeProducerReacquire");
                return;
            }

            TryContinueLearningV365ContinuousTypedPhysicalRoute(bot, mission, step, out _);
        }

        private static bool TryDriveLearningV349GenericEmpiricalPassageCorridor(
            BotOwner bot,
            out int targetSequence)
        {
            targetSequence = 0;
            if ((bot == null) || HasActiveTraversalProbe(bot))
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            Player player = bot.GetPlayer ?? bot.AIData?.Player;
            if (string.IsNullOrEmpty(profileId) || player?.MovementContext == null ||
                !FollowerMovementRecoveryStates.TryGetValue(profileId, out FollowerMovementRecoveryState state) ||
                state == null || Time.time > state.LearningV349GenericPassageLeaseUntil ||
                BreadcrumbRoute.Count == 0)
            {
                return false;
            }

            // V350: an untyped generic passage is a temporary physical bridge, not a new Follow
            // implementation. Once ordinary leader navigation becomes sane again and no typed route
            // mission remains to be honoured, return movement authority to normal Follow immediately.
            // This prevents a no-learning slope/terrain seam from turning into an endless breadcrumb
            // march after the follower has already rejoined usable NavMesh.
            bool haveActiveRouteMission = FollowerRouteMissions.TryGetValue(
                profileId, out FollowerRouteMission genericRouteMission) &&
                genericRouteMission != null && Time.time <= genericRouteMission.ExpiresAt &&
                genericRouteMission.CurrentStepIndex >= 0 &&
                genericRouteMission.CurrentStepIndex < genericRouteMission.Steps.Count;
            Player leader = FollowerEnvironment.LocalPlayer;
            if ((!haveActiveRouteMission) &&
                ((!state.LearningV350TerminalRecoveryEligible)) &&
                IsLivePlayer(leader) && IsFinite(leader.Position) &&
                CanAcceptFollowPath(bot, leader.Position, "leader-primary",
                    out float rejoinPathLength, out float rejoinDetourRatio))
            {
                // V4.19: CanAcceptFollowPath deliberately answers a broader question than a
                // physical-producer handoff. A long leader route may be legal Follow navigation
                // (R8.5 permits real building detours) while still being pathological compared with
                // the already-live empirical physical corridor. Do not relinquish a working physical
                // producer merely because that broad Follow policy says the route is legal. Yield
                // only when the same strict-complete path is also non-suspicious under the existing
                // 1.60x / +5.5m Follow topology thresholds. This changes no global threshold and
                // creates no scene exception; it only tightens the producer-ownership transition.
                float rejoinDirectDistance = GetPlanarDistance(bot.Position, leader.Position);
                float rejoinSuspiciousThreshold = Mathf.Max(
                    rejoinDirectDistance * FollowDetourRatioThreshold,
                    rejoinDirectDistance + FollowDetourExtraDistanceThreshold);
                bool learningV419SuspiciousFollowYield =
                    FollowerCapabilityHelperRules.TryDriveLearningV349GenericEmpiricalPassageCorridor_learningV419SuspiciousFollowYield_12FDB6E0_1(rejoinDirectDistance,rejoinPathLength,rejoinSuspiciousThreshold);
                if (learningV419SuspiciousFollowYield)
                {
                    WriteEvent("learningV419GenericPassageSuspiciousFollowYieldSuppressed", bot, new
                    {
                        leaderDistance = rejoinDirectDistance,
                        pathLength = rejoinPathLength,
                        detourRatio = rejoinDetourRatio,
                        suspiciousPathThreshold = rejoinSuspiciousThreshold,
                        suspiciousRatioThreshold = FollowDetourRatioThreshold,
                        suspiciousExtraDistanceThreshold = FollowDetourExtraDistanceThreshold,
                        cursorSequence = state.LearningV349GenericPassageCursorSequence,
                        physicalProducerRetained = true,
                        bodyRelocated = false,
                        action = "legalFollowDetourCannotPreemptHealthierActiveEmpiricalPhysicalProducer"
                    });
                }
                else if (bot.Mover?.ActualPathController?.HavePath != true ||
                         bot.Mover?.HasPathAndNoComplete != true ||
                         bot.Mover?.IsMoving != true)
                {
                    // CF38: PathComplete preflight alone cannot consume the empirical
                    // passage lease. The previous run released it with no live native
                    // mover, leaving a stalled bot 11 m from a reachable leader.
                    if (ShouldEmitDiagnostic("cf38GenericPassageYieldMissingFollowConsumer", bot, 1.0f))
                    {
                        WriteEvent("cf38GenericPassageYieldMissingFollowConsumer", bot, new
                        {
                            leaderDistance = rejoinDirectDistance,
                            pathLength = rejoinPathLength,
                            detourRatio = rejoinDetourRatio,
                            moverHasPath = bot.Mover?.ActualPathController?.HavePath == true,
                            moverMoving = bot.Mover?.IsMoving == true,
                            physicalProducerRetained = true,
                            bodyRelocated = false,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "doNotRetireLivePhysicalPassageUntilNativeFollowConsumerReallyExists"
                        });
                    }
                }
                else if (state.LearningV350GenericPassageArmedAt < 0f ||
                         state.LearningV349LastPhysicalProgressAt < state.LearningV350GenericPassageArmedAt ||
                         Time.time - state.LearningV349LastPhysicalProgressAt > TraversalRouteRecoveryDebounceSeconds)
                {
                    // CF40: mover.HasPath / IsMoving report command acceptance, not physical
                    // consumer liveness. CF38 repeatedly retired the recovery lease at a
                    // stationary body (767..790 s) despite both flags staying true. Retain
                    // the EXISTING V350 measured-progress timeout unless this same passage
                    // lease has a fresh real-body progress witness. This avoids the three-
                    // second rescue -> immediate false Follow rejoin -> rescue loop.
                    // No new timeout, movement writer, teleport or semantic credit.
                    if (ShouldEmitDiagnostic("cf40GenericPassageYieldUnverifiedPhysicalConsumer", bot, 1.0f))
                    {
                        WriteEvent("cf40GenericPassageYieldUnverifiedPhysicalConsumer", bot, new
                        {
                            leaderDistance = rejoinDirectDistance,
                            pathLength = rejoinPathLength,
                            detourRatio = rejoinDetourRatio,
                            moverHasPath = bot.Mover?.ActualPathController?.HavePath == true,
                            moverMoving = bot.Mover?.IsMoving == true,
                            genericPassageArmedAt = state.LearningV350GenericPassageArmedAt,
                            lastMeasuredPhysicalProgressAt = state.LearningV349LastPhysicalProgressAt,
                            measuredProgressWithinCurrentLease =
                                state.LearningV350GenericPassageArmedAt >= 0f &&
                                state.LearningV349LastPhysicalProgressAt >= state.LearningV350GenericPassageArmedAt,
                            physicalProducerRetained = true,
                            bodyRelocated = false,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "retainExistingMeasuredRecoveryLeaseUntilRealBodyProgressBeforeFollowYield"
                        });
                    }
                }
                else
                {
                    state.LearningV349GenericPassageLeaseUntil = -1f;
                    state.LearningV350GenericPassageArmedAt = -1f;
                    state.LearningV350GenericPassageArmCursorSequence = 0;
                    state.LearningV349PhysicalStallSince = -1f;
                    state.LearningV350TerminalRecoveryEligible = false;
                    state.LearningV350TerminalRecoverySince = -1f;
                    state.LearningV350TerminalRecoveryReason = string.Empty;
                    {
                        ClearLearningV365ContinuousPhysicalRoute(bot, "genericHealthyNavMeshRejoin");
                    }
                    WriteEvent("learningV350GenericPassageRejoinedNormalNavigation", bot, new
                    {
                        leaderDistance = rejoinDirectDistance,
                        pathLength = rejoinPathLength,
                        detourRatio = rejoinDetourRatio,
                        cursorSequence = state.LearningV349GenericPassageCursorSequence,
                        action = "releaseTemporaryPhysicalProducerToNormalFollow"
                    });
                    return false;
                }
            }

            if (state.LearningV349GenericPassageCursorSequence <= 0)
            {
                state.LearningV349GenericPassageCursorSequence =
                    Math.Max(0, FindFollowerRouteStartBreadcrumbSequence(bot));
            }

            state.LearningV349GenericPassageCursorSequence=Math.Max(state.LearningV349GenericPassageCursorSequence,CapabilityGenericResumeFloor(bot));

            PlayerBreadcrumbNode next = null;
            for (int index = 0; index < BreadcrumbRoute.Count; index++)
            {
                PlayerBreadcrumbNode candidate = BreadcrumbRoute[index];
                if (candidate == null ||
                    candidate.Sequence <= state.LearningV349GenericPassageCursorSequence ||
                    !IsOperationalBreadcrumbNode(candidate) || !IsFinite(candidate.Position))
                {
                    continue;
                }

                float distance = (Vector3.Distance(bot.Position, candidate.Position));
                float reachDistance = (BreadcrumbMinDistance);
                if (distance <= reachDistance)
                {
                    // V3.50: advancing a route cursor is chronology, not body progress. The follower
                    // may already be standing inside a newly appended breadcrumb radius while still
                    // physically jammed. Only measured displacement/target closure refreshes the
                    // physical-progress watchdog.
                    state.LearningV349GenericPassageCursorSequence =
                        Math.Max(state.LearningV349GenericPassageCursorSequence, candidate.Sequence);
                    continue;
                }

                if (distance <= RouteMissionBreadcrumbLookAheadDistance)
                {
                    next = candidate;
                    break;
                }
            }

            if (next == null)
            {
                return false;
            }

            Vector3 physicalDelta = next.Position - bot.Position;
            Vector3 flat = physicalDelta;
            flat.y = 0f;
            float flatDistance = flat.magnitude;
            float distanceToTarget = (physicalDelta.magnitude);
            if (distanceToTarget <= 0.001f)
            {
                state.LearningV349GenericPassageCursorSequence =
                    Math.Max(state.LearningV349GenericPassageCursorSequence, next.Sequence);
                targetSequence = next.Sequence;
                return true;
            }

            {
                ArmLearningV365ContinuousGenericPhysicalRoute(bot, next);
                return TryContinueLearningV365ContinuousGenericPhysicalRoute(bot, out targetSequence);
            }

            Vector3 direction = flatDistance > 0.001f
                ? flat / flatDistance
                : Vector3.zero;
            Vector3 motionDirection = (physicalDelta / distanceToTarget);
            float deltaTime = Mathf.Max(0.001f, Time.deltaTime);
            Vector3 motion = motionDirection * Mathf.Min(distanceToTarget, ChainLocalSuccessorBridgeSpeed * deltaTime);
            Vector3 beforePhysicalPosition = bot.Position;
            float beforeTargetDistance = distanceToTarget;
            // V2-RC17-CF1: preserve the original issued generation for the drive
            // diagnostic after RC17 moved acquisition into the physical scope facade.
            long generation = 0L;
            try
            {
                // V2-RC17: issue Follow ownership and physical scope through one
                // existing Authority facade; no split producer-side generation mint.
                if (!FollowerMovementWriterAuthority.TryEnterFollowPhysicalMotion(
                    bot, "learningV349GenericEmpiricalPassage",
                    out FollowerMovementWriterAuthority.WriteScope physicalScope, out _))
                    return false;
                generation = physicalScope.IssuedGeneration;
                using (physicalScope)
                {
                    if (bot.Mover != null)
                    {
                        bot.Mover.SetBotMoverPause("R1-CFF9670AEEC4",@bot,false);
                    }
                    ApplyCollisionActivePhysicalRouteMotion(
                        bot,
                        player,
                        direction,
                        motion,
                        deltaTime,
                        Mathf.Clamp01(next.Pose),deliveryTarget:next.Position,deliveryPurpose:CapabilityMotionPurpose.TypedRoute);
                }
            }
            catch (Exception ex)
            {
                WriteEvent("learningV349GenericEmpiricalPassageDriveException", bot, new
                {
                    breadcrumbSequence = next.Sequence,
                    error = ex.GetType().Name + ": " + ex.Message
                });
                return true;
            }

            Vector3 afterPhysicalPosition = bot.Position;
            float physicalDisplacement = (Vector3.Distance(beforePhysicalPosition, afterPhysicalPosition));
            float afterTargetDistance = (Vector3.Distance(afterPhysicalPosition, next.Position));
            float targetProgress = beforeTargetDistance - afterTargetDistance;
            Vector3 cumulativePhysicalDelta = afterPhysicalPosition - state.LearningV349LastPhysicalPosition;
            ;
            float cumulativePhysicalDisplacement = cumulativePhysicalDelta.magnitude;
            Vector3 learningV380ProgressDirection = (motionDirection);
            float cumulativeRouteForwardProgress = learningV380ProgressDirection.sqrMagnitude > 0.5f
                ? Vector3.Dot(cumulativePhysicalDelta, learningV380ProgressDirection)
                : 0f;
            // Measure accumulated BODY displacement from the last credited point. Per-frame motion
            // is often below 5.5 cm at normal framerates, so testing only one Move() call would
            // falsely terminalize smooth movement. Conversely, sideways/backward shuffling must not
            // keep the lease alive merely because CharacterController changed world position.
            bool measuredPhysicalProgress = FollowerCapabilityHelperRules.TryDriveLearningV349GenericEmpiricalPassageCorridor_measuredPhysicalProgress_12FDB6E0_2(cumulativePhysicalDisplacement,LearningV350MeasuredPhysicalProgressDistance,cumulativeRouteForwardProgress,LearningV350MeasuredTargetProgressDistance);
            if (measuredPhysicalProgress)
            {
                state.LearningV349LastPhysicalProgressAt = Time.time;
                state.LearningV349LastPhysicalPosition = afterPhysicalPosition;
                state.LearningV349PhysicalStallSince = -1f;
                if ((!state.LearningV350TerminalRecoveryEligible))
                {
                    state.LearningV350TerminalRecoveryEligible = false;
                    state.LearningV350TerminalRecoverySince = -1f;
                    state.LearningV350TerminalRecoveryReason = string.Empty;
                }
            }
            targetSequence = next.Sequence;
            if (ShouldEmitDiagnostic(
                "learningV349GenericEmpiricalPassageDrive:" +
                    next.Sequence.ToString(CultureInfo.InvariantCulture), bot, 0.25f))
            {
                WriteEvent("learningV349GenericEmpiricalPassageDrive", bot, new
                {
                    breadcrumbSequence = next.Sequence,
                    cursorSequence = state.LearningV349GenericPassageCursorSequence,
                    target = Vec(next.Position),
                    distance = distanceToTarget,
                    pose = Mathf.Clamp01(next.Pose),
                    navMeshSampled = next.NavMeshSampled,
                    leaseRemaining = Mathf.Max(0f, state.LearningV349GenericPassageLeaseUntil - Time.time),
                    movementGeneration = generation,
                    physicalDisplacement,
                    targetProgress,
                    cumulativePhysicalDisplacement,
                    cumulativeRouteForwardProgress,
                    measuredPhysicalProgress,
                    verticalTargetError = next.Position.y - beforePhysicalPosition.y,
                    threeDimensionalPhysicalPassage = true,
                    action = measuredPhysicalProgress
                        ? "collisionActivePlayerBreadcrumbPassageMeasuredBodyProgress"
                        : "collisionActivePlayerBreadcrumbPassageCommandOnlyNoProgressCredit"
                });
            }
            return true;
        }

        // RC61: TryValidateLearningV350PlayerRoutePhysicalRecoveryAnchor extracted unchanged to FollowerTraversalRecoveryOwnership.cs.

        internal static bool ShouldDeferGenericNavigationRecoveryTeleport(BotOwner bot, out string reason)
        {
            reason = string.Empty;
            if ((bot == null))
            {
                return false;
            }
            string profileId = bot.ProfileId ?? string.Empty;
            if ((!string.IsNullOrEmpty(profileId)) &&
                FollowerMovementRecoveryStates.TryGetValue(profileId, out FollowerMovementRecoveryState learningV350RecoveryState) &&
                learningV350RecoveryState != null &&
                learningV350RecoveryState.LearningV350TerminalRecoveryEligible)
            {
                if ((FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission learningV373RecoveryMission)) &&
                    learningV373RecoveryMission != null &&
                    TryRetireLearningV373ExhaustedPhysicalDebtByDownstreamBodyEpoch(
                        bot, learningV373RecoveryMission, "beforeGenericRecoveryTeleport",
                        out int learningV373RetiredEdgeId, out int learningV373RetiredEpisodeId))
                {
                    ClearLearningV351TerminalRecoveryState(
                        bot, "learningV373DownstreamBodyEpochRetiredExecutionDebt");
                    reason = "learningV373DownstreamBodyEpochContinuesRoute";
                    WriteEvent("learningV373GenericRecoveryTeleportSuppressedByDownstreamBodyEpoch", bot, new
                    {
                        missionId = learningV373RecoveryMission.MissionId,
                        currentStepIndex = learningV373RecoveryMission.CurrentStepIndex,
                        retiredEdgeId = learningV373RetiredEdgeId,
                        retiredEpisodeId = learningV373RetiredEpisodeId,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "continueNewerPlayerRouteInsteadOfTeleportingBackToExhaustedPhysicalEntry"
                    });
                    return true;
                }
                reason = "learningV350TerminalRecovery:" +
                         (learningV350RecoveryState.LearningV350TerminalRecoveryReason ?? "physicalNoProgress");
                if (ShouldEmitDiagnostic("learningV350NavigationRecoveryTeleportReleased", bot, 0.50f))
                {
                    WriteEvent("learningV350NavigationRecoveryTeleportReleased", bot, new
                    {
                        reason,
                        terminalSince = learningV350RecoveryState.LearningV350TerminalRecoverySince,
                        cursorSequence = learningV350RecoveryState.LearningV349GenericPassageCursorSequence,
                        action = "terminalRecoveryCannotBeDeferredByStaleTraversalOrGenericPassage"
                    });
                }
                return false;
            }
            if ((!string.IsNullOrEmpty(profileId)) &&
                FollowerMovementRecoveryStates.TryGetValue(profileId, out FollowerMovementRecoveryState learningV349RecoveryState) &&
                learningV349RecoveryState != null &&
                Time.time <= learningV349RecoveryState.LearningV349GenericPassageLeaseUntil &&
                BreadcrumbRoute.Count > 0)
            {
                float progressReference = (Mathf.Max(learningV349RecoveryState.LearningV350GenericPassageArmedAt,
                                learningV349RecoveryState.LearningV349LastPhysicalProgressAt));
                float noMeasuredProgressSeconds = (Mathf.Max(0f, Time.time - progressReference));
                if ((noMeasuredProgressSeconds >= LearnedTraversalMissedFallbackNoProgressSeconds))
                {
                    learningV349RecoveryState.LearningV350TerminalRecoveryEligible = true;
                    learningV349RecoveryState.LearningV350TerminalRecoverySince = Time.time;
                    learningV349RecoveryState.LearningV350TerminalRecoveryReason =
                        "navigationRecoveryObservedGenericPassageNoProgress";
                    CaptureLearningV362TerminalRecoveryEpoch(
                        bot, learningV349RecoveryState,
                        "navigationRecoveryObservedGenericPassageNoProgress");
                    learningV349RecoveryState.LearningV349GenericPassageLeaseUntil = -1f;
                    reason = "learningV350GenericPassageNoMeasuredProgress";
                    WriteEvent("learningV350NavigationRecoveryDeferralExpired", bot, new
                    {
                        reason,
                        cursorSequence = learningV349RecoveryState.LearningV349GenericPassageCursorSequence,
                        noMeasuredProgressSeconds,
                        terminalRecoveryEpochEpisodeId = learningV349RecoveryState.LearningV362TerminalRecoveryLatchEpisodeId,
                        terminalRecoveryEpochBreadcrumbSequence = learningV349RecoveryState.LearningV362TerminalRecoveryLatchBreadcrumbSequence,
                        terminalRecoveryEpochAt = learningV349RecoveryState.LearningV362TerminalRecoveryLatchAt,
                        action = "releaseGenericTeleportDeferralAndLatchTerminalRecovery"
                    });
                    return false;
                }

                reason = "learningV349GenericEmpiricalPassageLease:" +
                         Mathf.Max(0f, learningV349RecoveryState.LearningV349GenericPassageLeaseUntil - Time.time)
                             .ToString("0.00", CultureInfo.InvariantCulture) + "s";
                if (ShouldEmitDiagnostic("learningV349NavigationRecoveryTeleportDeferred", bot, 0.50f))
                {
                    WriteEvent("learningV349NavigationRecoveryTeleportDeferred", bot, new
                    {
                        reason,
                        cursorSequence = learningV349RecoveryState.LearningV349GenericPassageCursorSequence,
                        noMeasuredProgressSeconds,
                        action = "allowCollisionActivePlayerBreadcrumbRecoveryBeforeGenericTeleport"
                    });
                }
                return true;
            }
            if (string.IsNullOrEmpty(profileId) || !FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) ||
                mission == null || mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }
            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || IsFollowerRouteMissionStepPhysicallyPassed(bot, step, out _, out _))
            {
                return false;
            }
            bool havePlayerPhysicalCorridor = mission.RouteBreadcrumbs != null && mission.RouteBreadcrumbs.Any(node =>
                node != null && node.Sequence > mission.PhysicalApproachBreadcrumbSequence &&
                node.Sequence <= step.StartBreadcrumbSequence && IsOperationalBreadcrumbNode(node));
            if (!havePlayerPhysicalCorridor && !step.CurrentRaidRouteAuthority)
            {
                return false;
            }
            reason = "outstandingRouteObligation:mission=" + mission.MissionId.ToString(CultureInfo.InvariantCulture) +
                     ":step=" + mission.CurrentStepIndex.ToString(CultureInfo.InvariantCulture) +
                     ":edge=" + step.EdgeId.ToString(CultureInfo.InvariantCulture) +
                     ":kind=" + (step.Kind ?? string.Empty);
            WriteEvent("learningV348NavigationRecoveryTeleportDeferredToPhysicalRoute", bot, new
            {
                missionId = mission.MissionId, stepIndex = mission.CurrentStepIndex,
                episodeId = step.EpisodeId, edgeId = step.EdgeId, kind = step.Kind,
                physicalApproachBreadcrumbSequence = mission.PhysicalApproachBreadcrumbSequence,
                startBreadcrumbSequence = step.StartBreadcrumbSequence,
                currentRaidRouteAuthority = step.CurrentRaidRouteAuthority,
                havePlayerPhysicalCorridor
            });
            return true;
        }

        private static bool HasLearningV348EmpiricalRouteCorridorRetryBypass(BotOwner bot)
        {
            if ((bot == null) || HasActiveTraversalProbe(bot))
            {
                return false;
            }
            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) ||
                mission == null || mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }
            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || mission.PhysicalApproachBreadcrumbSequence >= step.StartBreadcrumbSequence)
            {
                return false;
            }

            RefreshRouteMissionBreadcrumbSnapshot(mission);
            PlayerBreadcrumbNode next = mission.RouteBreadcrumbs.FirstOrDefault(candidate =>
                candidate != null && candidate.Sequence > mission.PhysicalApproachBreadcrumbSequence &&
                candidate.Sequence <= step.StartBreadcrumbSequence && IsOperationalBreadcrumbNode(candidate) &&
                IsFinite(candidate.Position));
            if (next == null)
            {
                return false;
            }
            float distance = GetPlanarDistance(bot.Position, next.Position);
            if (distance <= 0.001f || distance > RouteMissionBreadcrumbLookAheadDistance)
            {
                return false;
            }
            string source = "route-mission-breadcrumb-" + next.Sequence.ToString(CultureInfo.InvariantCulture);
            bool navHealthy = next.NavMeshSampled &&
                CanAcceptFollowPath(bot, next.Position, source, out _, out _);
            return !navHealthy;
        }

        // RC107: IsLearningV350TerminalPhysicalRecoveryEligible is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryDriveLearningV374NearSideRetryForwardProducer is owned by FollowerCapabilityGeneralRecoveryHost.

        internal static bool ShouldHoldMovementForTraversalRetry(BotOwner bot, string source)
        {
            if ((IsLearningV350TerminalPhysicalRecoveryEligible(bot)))
            {
                ReleaseLearningV353TerminalRecoveryRetryLease(
                    bot, "retryHoldBypass:" + (source ?? "externalMovementProducer"));
                if (ShouldEmitDiagnostic("learningV353TerminalRecoveryBypassedRouteRetryHold", bot, 0.50f))
                {
                    WriteEvent("learningV353TerminalRecoveryBypassedRouteRetryHold", bot, new
                    {
                        source = source ?? "externalMovementProducer",
                        action = "allowFollowAndNavigationRecoveryToAgeTowardTerminalSafetyNet"
                    });
                }
                return false;
            }
            if (!IsLearningV331RouteRetryMovementHoldActive(bot))
            {
                return false;
            }
            if (TryDriveLearningV374NearSideRetryForwardProducer(
                    bot, source ?? "externalMovementProducer"))
            {
                return true;
            }
            if (HasLearningV348EmpiricalRouteCorridorRetryBypass(bot))
            {
