        private static bool HasLearningV453LiveTraversalPhysicalProducer(BotOwner bot)
        {
            if ((bot == null))
            {
                return false;
            }
            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (generation <= 0 || owner != FollowerMovementWriterAuthority.WriterDomain.Traversal)
            {
                return false;
            }
            if (HasActiveTraversalProbe(bot))
            {
                return true;
            }
            string profileId = bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) &&
                FollowerTraversalRouteCursors.TryGetValue(
                    profileId, out FollowerTraversalRouteCursor cursor) &&
                cursor != null && cursor.LearningV375TransactionActive &&
                cursor.LearningV375MovementGeneration == generation)
            {
                return true;
            }
            return bot.Mover?.IsMoving == true && bot.Mover?.HasPathAndNoComplete == true;
        }

        private static bool IsLearningV331RouteRetryMovementHoldActive(BotOwner bot)
        {
            if ((bot == null))
            {
                return false;
            }
            string profileId = bot.ProfileId ?? string.Empty;
            return !string.IsNullOrEmpty(profileId) &&
                   FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) &&
                   mission != null && mission.CurrentStepIndex >= 0 &&
                   mission.CurrentStepIndex < mission.Steps.Count &&
                   Time.time < mission.TraversalRetryMovementHoldUntil;
        }

        private static void ApplyLearningV331RouteRetryMovementHold(BotOwner bot, string source)
        {
            if (!IsLearningV331RouteRetryMovementHoldActive(bot))
            {
                return;
            }
            // V4.53: retry is a semantic/competition lease, not a translation producer. The
            // existing V3.74/current physical producer may continue to move the collision-active
            // body, while this lease only rejects a competing leader route until the bounded
            // same-step retry window expires. Never brake, clear input or replace the mover here.
            if (ShouldEmitDiagnostic("learningV331RouteRetryMovementAuthorityHeld", bot, 0.50f))
            {
                string profileId = bot.ProfileId ?? string.Empty;
                FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission);
                FollowerRouteMissionStep step = mission != null && mission.CurrentStepIndex >= 0 &&
                    mission.CurrentStepIndex < mission.Steps.Count
                    ? mission.Steps[mission.CurrentStepIndex]
                    : null;
                WriteEvent("learningV331RouteRetryMovementAuthorityHeld", bot, new
                {
                    missionId = mission?.MissionId ?? 0,
                    stepIndex = mission?.CurrentStepIndex ?? -1,
                    edgeId = step?.EdgeId ?? 0,
                    kind = step?.Kind ?? string.Empty,
                    remaining = mission != null ? Mathf.Max(0f, mission.TraversalRetryMovementHoldUntil - Time.time) : 0f,
                    genericRouteRetryRemaining = mission != null ? Mathf.Max(0f, mission.NextMoveAttemptAt - Time.time) : 0f,
                    source = source ?? string.Empty,
                    movementWritePerformed = false,
                    bodyRelocated = false,
                    action = ("retryLeaseRejectsCompetingLeaderPathWithoutStoppingCurrentPhysicalProducer")
                });
            }
        }

        private static bool IsLearningV339NativeProvenWalkThroughRouteStep(FollowerRouteMissionStep step)
        {
            if ((step == null) ||
                !string.Equals(step.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) || step.EdgeId <= 0)
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == step.EdgeId);
            return edge != null && !edge.Disabled &&
                   (IsLearningV3NativeProvenEdge(edge) ||
                    IsLearningV344HistoricalWalkThroughSemanticAuthority(edge));
        }

        private static bool TryGetLearningV339WalkThroughNearSideFrontierTarget(
            BotOwner bot,
            FollowerRouteMissionStep step,
            out Vector3 target)
        {
            target = default;
            if (!IsLearningV339NativeProvenWalkThroughRouteStep(step) || bot == null || !IsFinite(step.Entry))
            {
                return false;
            }

            StrictPathResult partial = CalculateStrictPath(bot.Position, step.Entry);
            if (partial == null || !partial.CalculateReturned || partial.StrictComplete ||
                partial.Status != NavMeshPathStatus.PathPartial || partial.Corners == null || partial.Corners.Length == 0)
            {
                return false;
            }

            Vector3 frontier = partial.Corners[partial.Corners.Length - 1];
            if (!IsFinite(frontier) || GetPlanarDistance(bot.Position, frontier) <= RouteMissionBreadcrumbReachDistance)
            {
                return false;
            }

            target = frontier;
            return true;
        }

        private static bool IsLearningV341FreshPlayerTraversalRouteStep(FollowerRouteMissionStep step)
        {
            if ((step == null) || step.EdgeId <= 0 || step.EpisodeId <= 0)
            {
                return false;
            }
            TraversalEpisodeMetadata episode = TraversalEpisodeStream.LastOrDefault(item =>
                item != null && item.EpisodeId == step.EpisodeId && item.EdgeId == step.EdgeId);
            if (episode == null)
            {
                return false;
            }
            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == step.EdgeId);
            return edge != null && edge.PlayerValidated &&
                   (!edge.Disabled || step.ChainLocalExecutable ||
                    ((step.CurrentRaidRouteAuthority)));
        }

        private static bool TryGetLearningV341FreshTraversalNearSideFrontier(
            BotOwner bot,
            FollowerRouteMissionStep step,
            out Vector3 frontier,
            out StrictPathResult partial)
        {
            frontier = default;
            partial = null;
            if ((!IsLearningV341FreshPlayerTraversalRouteStep(step)) || bot == null || !IsFinite(step.Entry))
            {
                return false;
            }

            partial = CalculateStrictPath(bot.Position, step.Entry);
            if (partial == null || !partial.CalculateReturned || partial.StrictComplete ||
                partial.Status != NavMeshPathStatus.PathPartial || partial.Corners == null || partial.Corners.Length == 0)
            {
                return false;
            }
            frontier = partial.Corners[partial.Corners.Length - 1];
            return IsFinite(frontier);
        }

