                    FollowerCapabilityDecisionRules.TryGetPlayerRouteMissionFollowTarget_releaseDeferredApproach_4(mission.ApproachDeferredCount,RouteMissionApproachDeferredReleaseCount,approachDeferredFor,RouteMissionApproachDeferredReleaseSeconds);
                if (releaseDeferredApproach)
                {
                    long perfStart = BeginTraversalPerfSample();
                    StrictPathResult leaderPath = CalculateStrictPath(bot.Position, leaderPosition);
                    EndTraversalPerfSample("RouteMissionApproachLeaderPath", perfStart, bot, step.EdgeId, step.Kind);
                    float leaderDistance = GetPlanarDistance(bot.Position, leaderPosition);
                    float allowedLeaderPath = GetAllowedFollowPathLength(leaderDistance, true);
                    bool leaderRouteUsable = FollowerCapabilityDecisionRules.TryGetPlayerRouteMissionFollowTarget_leaderRouteUsable_5(leaderPath.StrictComplete,leaderPath.PathLength,allowedLeaderPath);
                    if (leaderRouteUsable && learningV354StrictCurrentActuator &&
                        !learningV339NativeProvenWalkThroughBarrier && !learningV341FreshTraversalAdmission &&
                        ShouldEmitDiagnostic("learningV354StrictActuatorLeaderBypassRejected:" + step.EdgeId, bot, 0.40f))
                    {
                        WriteEvent("learningV354StrictActuatorLeaderBypassRejected", bot, new
                        {
                            missionId = mission.MissionId, stepIndex = mission.CurrentStepIndex, edgeId = step.EdgeId,
                            kind = step.Kind, entryDistance, leaderDistance, leaderPathLength = leaderPath.PathLength,
                            action = "retainStrictActuatorRouteDebtAndLetRecoveryOwnFailure"
                        });
                    }
                    if (leaderRouteUsable && !learningV339NativeProvenWalkThroughBarrier && !learningV341FreshTraversalAdmission &&
                        !learningV354StrictCurrentActuator)
                    {
                        WriteEvent("followerRouteMissionApproachReleasedForReachableLeader", bot, new
                        {
                            missionId = mission.MissionId,
                            stepIndex = mission.CurrentStepIndex,
                            episodeId = step.EpisodeId,
                            edgeId = step.EdgeId,
                            kind = step.Kind,
                            entryDistance,
                            deferredFor = approachDeferredFor,
                            deferredCount = mission.ApproachDeferredCount,
                            leaderDistance,
                            leaderPathLength = leaderPath.PathLength,
                            allowedLeaderPath
                        });
                        AdvanceFollowerRouteResumeFloor(
                            bot,
                            "routeMissionApproachUnreachableReachableLeader:" + step.EdgeId.ToString(CultureInfo.InvariantCulture),
                            quarantineCurrentTraversal: true);
                        handledInternally = false;
                        return false;
                    }

                    int previousStepIndex = mission.CurrentStepIndex;
                    if (RebaseFollowerRouteMissionToCurrentPosition(bot, mission) && mission.CurrentStepIndex != previousStepIndex)
                    {
                        WriteEvent("followerRouteMissionApproachReleasedAfterRebase", bot, new
                        {
                            missionId = mission.MissionId,
                            previousStepIndex,
                            newStepIndex = mission.CurrentStepIndex,
                            edgeId = step.EdgeId,
                            kind = step.Kind,
                            entryDistance,
                            deferredFor = approachDeferredFor,
                            deferredCount = mission.ApproachDeferredCount
                        });
                        return TryGetPlayerRouteMissionFollowTarget(
                            bot, leaderPosition, out target, out handledInternally, out edgeId, out routeBreadcrumbSequence);
                    }

                    // V3.39: a Native-Proven WT is a route fact, not an optional shortcut. A
                    // healthy leader detour must not erase/quarantine the authored passage merely
                    // because the generic approach anchor is temporarily unavailable. Keep the
                    // same step admitted and let the PathPartial frontier / subsequent retry own
                    // convergence. Negative-space telemetry makes a missing AttemptStarted visible.
                    if (((learningV339NativeProvenWalkThroughBarrier || learningV341FreshTraversalAdmission)))
                    {
                        if ((step.CurrentRaidRouteAuthority))
                        {
                            // A current player-authored route fact is not discarded because one
                            // NavMesh/anchor producer failed. Keep the step and allow the physical
                            // breadcrumb producer/rebase to converge from the follower body epoch.
                            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.ProposalDeferred,Mathf.Max(
                                mission.NextMoveAttemptAt, Time.time + RouteMissionMoveRetrySeconds));
                            WriteEvent("learningV348CurrentRaidRouteOwnershipRetainedAfterBoundedApproach", bot, new
                            {
                                missionId = mission.MissionId,
                                stepIndex = mission.CurrentStepIndex,
                                episodeId = step.EpisodeId,
                                edgeId = step.EdgeId,
                                kind = step.Kind,
                                entryDistance,
                                deferredFor = approachDeferredFor,
                                deferredCount = mission.ApproachDeferredCount,
                                physicalApproachBreadcrumbSequence = mission.PhysicalApproachBreadcrumbSequence,
                                chronologyApproachBreadcrumbSequence = mission.ApproachBreadcrumbSequence,
                                action = "retainCurrentRaidPhysicalRouteDebtForEmpiricalCorridor"
                            });
                            return true;
                        }

                        // V3.43: the edge remains proven/fresh knowledge, but this RouteMission no
                        // longer owns movement after the existing bounded approach proof failed.
                        // Release only the runtime transaction; do not consume, quarantine or delete
                        // the learned edge/episode. This lets known-portal/ordinary Follow compete.
                        int releasedMissionId = mission.MissionId;
                        int releasedStepIndex = mission.CurrentStepIndex;
                        EmitLearningV347TraversalOpportunityNoStart(
                            bot, mission, step, "routeMissionApproach", "boundedApproachOwnershipReleased");
                        LearnedTraversalCommitments.Remove(profileId);
                        RemoveLifecycleMission(profileId, "TryGetPlayerRouteMissionFollowTarget");
                        FollowRejectLeases.Remove(profileId);
                        FollowerRouteMissionRearmBlockedUntil[profileId] =
                            Time.time + RouteMissionFailureRearmBlockSeconds;
                        if ((string.Equals(step.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)) && step.EpisodeId > 0)
                        {
                            LearningV344ReleasedWalkThroughEpisodeByFollower[profileId] = step.EpisodeId;
                        }
                        WriteEvent("learningV343BoundedWalkThroughOwnershipReleased", bot, new
                        {
                            missionId = releasedMissionId,
                            stepIndex = releasedStepIndex,
                            episodeId = step.EpisodeId,
                            edgeId = step.EdgeId,
                            kind = step.Kind,
                            entryDistance,
                            deferredFor = approachDeferredFor,
                            deferredCount = mission.ApproachDeferredCount,
                            nativeProven = learningV339NativeProvenWalkThroughBarrier,
                            freshEpisode = learningV341FreshTraversalAdmission,
                            rearmBlockSeconds = RouteMissionFailureRearmBlockSeconds,
                            persistentEdgePreserved = true,
                            episodeConsumed = false
                        });
                        return false;
                    }

                    if (learningV339NativeProvenWalkThroughBarrier || learningV341FreshTraversalAdmission)
                    {
                        CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.ProposalDeferred,Mathf.Max(
                            mission.NextMoveAttemptAt, Time.time + RouteMissionMoveRetrySeconds));
                        if ((learningV339NativeProvenWalkThroughBarrier) &&
                            ShouldEmitDiagnostic("learningV339WalkThroughAdmissionNegativeSpace:" + step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.50f))
                        {
                            WriteEvent("learningV339WalkThroughAdmissionNegativeSpace", bot, new
                            {
                                missionId = mission.MissionId,
                                stepIndex = mission.CurrentStepIndex,
                                episodeId = step.EpisodeId,
                                edgeId = step.EdgeId,
                                kind = step.Kind,
                                entryDistance,
                                deferredFor = approachDeferredFor,
                                deferredCount = mission.ApproachDeferredCount,
                                leaderRouteUsable,
                                lastPipelineStage = "RouteMissionApproach",
                                missingEvent = "TraversalAttemptStarted",
                                action = learningV341FreshTraversalAdmission
                                    ? "retainFreshPlayerTraversalAdmissionNoSkipNoQuarantine"
                                    : "retainNativeProvenWalkThroughAdmissionNoSkipNoQuarantine"
                            });
                        }
                        if ((learningV341FreshTraversalAdmission) &&
                            ShouldEmitDiagnostic("learningV341FreshTraversalAdmissionNegativeSpace:" + step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.50f))
                        {
                            WriteEvent("learningV341FreshTraversalAdmissionNegativeSpace", bot, new
                            {
                                missionId = mission.MissionId,
                                stepIndex = mission.CurrentStepIndex,
                                episodeId = step.EpisodeId,
                                edgeId = step.EdgeId,
                                kind = step.Kind,
                                entryDistance,
                                deferredFor = approachDeferredFor,
                                deferredCount = mission.ApproachDeferredCount,
                                leaderRouteUsable,
                                lastPipelineStage = "RouteMissionApproach",
                                missingEvent = "TraversalAttemptStarted",
                                action = "freshPlayerTraversalRemainsAuthoritativeUntilPhysicalEntryOrExplicitFailure"
                            });
                        }
                        return true;
                    }

                    // CompileFix49: noReachableApproachAnchor is a real unreachable-step failure,
                    // not a reason to keep the bot parked while mission rebases renew the timer.
                    // After the bounded ~0.85 s / 3-attempt window, skip this step immediately.
                    int skippedIndex = mission.CurrentStepIndex;
                    if (!TryAdvanceRouteMission(bot, mission, mission.CurrentStepIndex + 1, RouteDebtEvidence.PolicySuppression, "TryGetPlayerRouteMissionFollowTarget:7", r2DebtObservation10)) return false;
                    mission.ApproachBreadcrumbSequence = Math.Max(
                        mission.ApproachBreadcrumbSequence, step.EndBreadcrumbSequence);
                    mission.LastProgressAt = Time.time;
                    mission.LastProgressPosition = bot.Position;
                    mission.ApproachDeferredSince = 0f;
                    mission.ApproachDeferredCount = 0;
                    mission.ApproachDeferredLastEntryDistance = float.MaxValue;
                    LearnedTraversalCommitments.Remove(bot.ProfileId ?? string.Empty);
                    WriteEvent("followerRouteMissionNoReachableApproachFastSkipped", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = skippedIndex,
                        episodeId = step.EpisodeId,
                        edgeId = step.EdgeId,
                        kind = step.Kind,
                        entryDistance,
                        deferredFor = approachDeferredFor,
                        deferredCount = RouteMissionApproachDeferredReleaseCount,
                        reason = "noReachableApproachAnchorFastFail"
                    });
                    return TryGetPlayerRouteMissionFollowTarget(
                        bot, leaderPosition, out target, out handledInternally, out edgeId, out routeBreadcrumbSequence);
                }

                CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.ProposalDeferred,Mathf.Max(mission.NextMoveAttemptAt, Time.time + RouteMissionMoveRetrySeconds));
                if (ShouldEmitDiagnostic("followerRouteMissionApproachDeferred:" + step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.75f))
                {
                    WriteEvent("followerRouteMissionApproachDeferred", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = mission.CurrentStepIndex,
                        episodeId = step.EpisodeId,
                        edgeId = step.EdgeId,
                        kind = step.Kind,
                        entryDistance,
                        deferredFor = approachDeferredFor,
                        deferredCount = mission.ApproachDeferredCount,
                        reason = "noReachableApproachAnchor"
                    });
