                return true;
            }

            if (TryUseLearnedTraversalCommitment(bot, leaderPosition, out target, out bool probeStarted, out edgeId))
            {
                handledInternally = probeStarted;
                return true;
            }
            return false;
        }

        public static bool ShouldHoldRejectedFollowRoute(BotOwner bot, Vector3 leaderPosition)
        {
            if (!TryGetFollowRejectLease(bot, out FollowRejectLease lease))
            {
                return false;
            }

            if (Vector3.Distance(lease.Target, leaderPosition) > FollowRejectLeaseTargetMoveTolerance ||
                Vector3.Distance(lease.Start, bot.Position) > FollowRejectLeaseBotMoveTolerance)
            {
                // Geometry changed enough that the old rejection is no longer authoritative.
                // Release the cheap hold and allow exactly one fresh path/mission decision.
                FollowRejectLeases.Remove(bot.ProfileId);
                return false;
            }

            if (GetLatestTraversalEpisodeId() > lease.LatestEpisodeId)
            {
                TryArmOrRefreshFollowerRouteMission(bot, leaderPosition, "newTraversalAfterReject", true);
                lease.LatestEpisodeId = GetLatestTraversalEpisodeId();
            }

            return true;
        }

        private static void ArmFollowRejectLease(
            BotOwner bot,
            Vector3 target,
            float pathLength,
            float detourRatio,
            string source)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }

            // CompileFix29: consult the existing reject lease before doing any RouteMission/NavMesh
            // work. FIX28 armed a mission first and only then noticed the same target was already
            // leased, which created the observed arm->rebase->complete storm.
            FollowRejectLeases.TryGetValue(profileId, out FollowRejectLease existing);
            if (existing != null &&
                TryRetireLearningV420FollowRejectLeaseFromTraversalBodyEpoch(
                    bot, existing, "ArmFollowRejectLease:refresh"))
            {
                existing = null;
            }
            if (existing != null &&
                Time.time <= existing.ExpiresAt && Vector3.Distance(existing.Target, target) <= FollowRejectLeaseTargetMoveTolerance)
            {
                existing.ExpiresAt = Mathf.Max(existing.ExpiresAt, Time.time + FollowRejectLeaseSeconds);
                existing.PathLength = pathLength;
                existing.DetourRatio = detourRatio;
                existing.LatestEpisodeId = Math.Max(existing.LatestEpisodeId, GetLatestTraversalEpisodeId());
                return;
            }

            bool missionArmed = TryArmOrRefreshFollowerRouteMission(bot, target, "followPathRejected", true);
            long leaseMovementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain leaseMovementOwner);
            FollowRejectLease lease = new FollowRejectLease
            {
                Start = bot.Position,
                Target = target,
                PathLength = pathLength,
                DetourRatio = detourRatio,
                CreatedAt = Time.time,
                ExpiresAt = Time.time + (missionArmed ? FollowRejectLeaseMissionSeconds : FollowRejectLeaseSeconds),
                BreadcrumbSequence = breadcrumbSequence,
                LatestEpisodeId = GetLatestTraversalEpisodeId(),
                HoldStopApplied = true,
                MovementGeneration = leaseMovementGeneration,
                MovementOwner = leaseMovementOwner.ToString()
            };
            FollowRejectLeases[profileId] = lease;

            // Reject is a state transition, not a loop. Clear the stale ordinary path exactly once;
            // subsequent Follow updates simply observe the lease / Route Mission and do no path work.
            try
            {
                bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-109D6F01A73A",@bot);
                bot.Mover?.BotMoverStop("R1-269601948C8F",@bot);
                bot.BotOwnerStopMove("R1-6F7FBED6AFBC",@bot);
            }
            catch
            {
            }

            WriteEvent("followRejectLeaseArmed", bot, new
            {
                source,
                target = Vec(target),
                pathLength,
                detourRatio,
                missionArmed,
                expiresIn = lease.ExpiresAt - Time.time,
                breadcrumbSequence = lease.BreadcrumbSequence,
                latestEpisodeId = lease.LatestEpisodeId
            });
        }

        private static void RecordRouteMissionMoveResult(
            BotOwner bot,
            Vector3 requestedTarget,
            string source,
            NavMeshPathStatus reportedStatus)
        {
            if (!IsRouteMissionPathSource(source) || bot == null || string.IsNullOrEmpty(bot.ProfileId) ||
                !FollowerRouteMissions.TryGetValue(bot.ProfileId, out FollowerRouteMission mission) || mission == null)
            {
                return;
            }

            if (reportedStatus != NavMeshPathStatus.PathInvalid)
            {
                CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
                return;
            }

            int failedBreadcrumbSequence = 0;
            int failedEdgeId = 0;
            if (source.StartsWith("route-mission-breadcrumb-", StringComparison.OrdinalIgnoreCase))
            {
                string suffix = source.Substring("route-mission-breadcrumb-".Length);
                int.TryParse(suffix, NumberStyles.Integer, CultureInfo.InvariantCulture, out failedBreadcrumbSequence);
            }
            else if (source.StartsWith("route-mission-edge-", StringComparison.OrdinalIgnoreCase) ||
                     source.StartsWith("rejected-route-edge-", StringComparison.OrdinalIgnoreCase))
            {
                string prefix = source.StartsWith("route-mission-edge-", StringComparison.OrdinalIgnoreCase)
                    ? "route-mission-edge-"
                    : "rejected-route-edge-";
                string suffix = source.Substring(prefix.Length);
                int.TryParse(suffix, NumberStyles.Integer, CultureInfo.InvariantCulture, out failedEdgeId);
            }

            string failureSignature = (source ?? string.Empty) + "|" +
                Mathf.RoundToInt(requestedTarget.x * 2f).ToString(CultureInfo.InvariantCulture) + "," +
                Mathf.RoundToInt(requestedTarget.z * 2f).ToString(CultureInfo.InvariantCulture);
            mission.FailureSignatureCounts.TryGetValue(failureSignature, out int signatureFailures);
            signatureFailures++;
            mission.FailureSignatureCounts[failureSignature] = signatureFailures;
            mission.PathRejectsSinceProgress++;
            mission.LocalRecoveryAttempts++;
            mission.LastFailedTarget = requestedTarget;

            if (failedBreadcrumbSequence > 0)
            {
                mission.LastFailedBreadcrumbSequence = failedBreadcrumbSequence;
                if (signatureFailures >= RouteMissionFailureSignatureMaxAttempts &&
                    mission.RejectedBreadcrumbSequences.Add(failedBreadcrumbSequence))
                {
                    WriteEvent("followerRouteMissionBreadcrumbRejectedForMission", bot, new
                    {
                        missionId = mission.MissionId,
                        breadcrumbSequence = failedBreadcrumbSequence,
                        signatureFailures,
                        target = Vec(requestedTarget),
                        reason = "boundedRepeatedPathInvalid"
                    });
                }
            }
            if (failedEdgeId > 0)
            {
                mission.LastFailedEdgeId = failedEdgeId;
            }

            float noProgressFor = Mathf.Max(0f, Time.time - mission.LastProgressAt);
            bool recoveryExhausted =
                mission.PathRejectsSinceProgress >= RouteMissionMaxPathRejectsWithoutProgress ||
                (mission.PathRejectsSinceProgress >= RouteMissionFailureSignatureMaxAttempts + 1 &&
                 noProgressFor >= RouteMissionPathRejectNoProgressSeconds);

            try
            {
                bot.Mover?.BotMoverStop("R1-81B56BD07391",@bot);
                bot.BotOwnerStopMove("R1-182310A27B7D",@bot);
            }
            catch
            {
            }

            if (recoveryExhausted)
            {
                int missionId = mission.MissionId;
                int currentStepIndex = mission.CurrentStepIndex;
                FollowerRouteMissionStep currentStep =
                    currentStepIndex >= 0 && currentStepIndex < mission.Steps.Count
                        ? mission.Steps[currentStepIndex]
                        : null;
                int currentEdgeId = currentStep?.EdgeId ?? 0;

                if ((currentStep != null) &&
                    (currentStep.CurrentRaidRouteAuthority || currentStep.ChainLocalExecutable))
                {
                    if (FollowerMovementRecoveryStates.TryGetValue(
                            bot.ProfileId, out FollowerMovementRecoveryState recoveryState) &&
                        recoveryState != null)
                    {
                        recoveryState.LearningV349GenericPassageLeaseUntil =
                            Mathf.Max(recoveryState.LearningV349GenericPassageLeaseUntil,
                                Time.time + RouteMissionHardRecoverySeconds);
                        recoveryState.LearningV349GenericPassageCursorSequence =
                            Math.Max(recoveryState.LearningV349GenericPassageCursorSequence,
                                mission.PhysicalApproachBreadcrumbSequence);
                    }
                    mission.PathRejectsSinceProgress = 0;
                    mission.LocalRecoveryAttempts = 0;
                    mission.FailureSignatureCounts.Clear();
                    mission.RejectedBreadcrumbSequences.Clear();
                    CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
                    mission.TraversalRetryMovementHoldUntil = 0f;
                    mission.LastProgressAt = Time.time;
                    mission.LastProgressPosition = bot.Position;
                    WriteEvent("learningV349RouteRecoveryConvertedToPhysicalCorridor", bot, new
                    {
                        missionId,
                        stepIndex = currentStepIndex,
                        edgeId = currentEdgeId,
                        kind = currentStep.Kind,
                        source,
                        target = Vec(requestedTarget),
                        currentRaidRouteAuthority = currentStep.CurrentRaidRouteAuthority,
                        chainLocalExecutable = currentStep.ChainLocalExecutable,
                        noProgressFor,
                        action = "preserveRouteSemanticSwitchProducerFromRejectedNavMeshToPlayerPhysicalBreadcrumbCorridor"
                    });
                    return;
                }

                RemoveLifecycleMission(bot.ProfileId, "RecordRouteMissionMoveResult");
                FollowRejectLeases.Remove(bot.ProfileId);
                LearnedTraversalCommitments.Remove(bot.ProfileId);
                FollowerRouteMissionRearmBlockedUntil[bot.ProfileId] = Time.time + RouteMissionFailureRearmBlockSeconds;
                WriteEvent("followerRouteMissionRecoveryExhausted", bot, new
                {
                    missionId,
                    stepIndex = currentStepIndex,
                    edgeId = currentEdgeId,
                    source,
                    target = Vec(requestedTarget),
                    pathRejectsSinceProgress = mission.PathRejectsSinceProgress,
                    localRecoveryAttempts = mission.LocalRecoveryAttempts,
                    noProgressFor,
                    rejectedBreadcrumbs = mission.RejectedBreadcrumbSequences.Count,
                    reason = "boundedPathRejectStateMachine"
                });
                return;
            }

            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.AttemptOrExplicitHold,Time.time + RouteMissionMoveRetrySeconds);
            WriteEvent("followerRouteMissionMoveDeferred", bot, new
            {
                missionId = mission.MissionId,
                source,
                target = Vec(requestedTarget),
                signatureFailures,
                pathRejectsSinceProgress = mission.PathRejectsSinceProgress,
                localRecoveryAttempts = mission.LocalRecoveryAttempts,
                rejectedBreadcrumbs = mission.RejectedBreadcrumbSequences.Count,
                retryIn = RouteMissionMoveRetrySeconds
            });
        }


        public static bool CanAcceptFollowFallbackPath(BotOwner bot, Vector3 target, out float pathLength, out float detourRatio)
        {
            pathLength = 0f;
            detourRatio = 0f;
            if (bot == null || !IsFinite(bot.Position) || !IsFinite(target))
            {
                return false;
            }

            // A leader-route rejection lease already owns this recovery window. Cover fallback must
            // not launch a second strict path calculation against the same barrier.
            if (TryGetFollowRejectLease(bot, out FollowRejectLease rejectedLease))
            {
                pathLength = rejectedLease.PathLength;
                detourRatio = rejectedLease.DetourRatio;
                return false;
            }

            float direct = Vector3.Distance(bot.Position, target);
            if (direct <= 10f)
            {
                if (!CanAcceptFollowPath(bot, target, out pathLength, out detourRatio))
                {
                    return false;
                }
            }
            else
            {
                // Cover fallback is an exceptional path producer rather than the normal chase
                // refresh, so keep its original strict-path validation even beyond 10 m.
                StrictPathResult path = CalculateStrictPath(bot.Position, target);
                pathLength = path.PathLength;
                detourRatio = direct > 0.01f ? path.PathLength / direct : 1f;
                if (!path.StrictComplete)
                {
                    return false;
                }
            }

            float allowed = Mathf.Min(
                FollowFallbackAbsolutePathLimit,
                Mathf.Max(direct * FollowFallbackMaxDetourRatio, direct + FollowFallbackMaxExtraDistance));
            return pathLength <= allowed;
        }

        public static bool CanUseOrdinaryFollowStarvationRecovery(
            BotOwner bot,
            Vector3 leaderPosition,
            out float directDistance,
            out float pathLength)
        {
            directDistance = 0f;
            pathLength = 0f;
            if (!raidActive || bot == null || !IsLiveBot(bot) || !BossPlayers.IsFollower(bot) ||
                !IsFinite(bot.Position) || !IsFinite(leaderPosition) ||
                OwnsBot(bot) || HasPendingTraversalMission(bot) ||
                FollowerStateAuthorityCoordinator.HasCombatMovementClaim(bot, out _))
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                (FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) &&
                 mission != null && Time.time <= mission.ExpiresAt))
            {
                return false;
            }

            BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(profileId);
            if (follower != null &&
                follower.TryPeekActiveCommand(out FollowerCommandType activeCommand, out _, out _) &&
                activeCommand != FollowerCommandType.None)
            {
                return false;
            }

            directDistance = GetPlanarDistance(bot.Position, leaderPosition);
            if (directDistance < 12.0f)
            {
                return false;
            }

            long perfStart = BeginTraversalPerfSample();
            StrictPathResult path = CalculateStrictPath(bot.Position, leaderPosition);
            EndTraversalPerfSample("FollowStarvationLeaderPath", perfStart, bot);
            pathLength = path.PathLength;
            float allowed = Mathf.Max(directDistance + 6.0f, directDistance * 1.35f);
            if (!path.StrictComplete || path.PathLength > allowed)
            {
                return false;
            }

            // A previous reject lease described an older/pathological leader target. The current
            // near-1:1 complete route is stronger evidence and must be allowed to refresh movement.
            FollowRejectLeases.Remove(profileId);
            return true;
        }

