        public static void RecordFollowPathWriteException(
            BotOwner bot,
            Vector3 target,
            string source,
            Exception exception)
        {
            string handsController = null;
            string playerState = null;
            try
            {
                handsController = bot?.GetPlayer?.HandsController?.GetType().FullName;
                playerState = bot?.GetPlayer != null
                    ? bot.GetPlayer.CurrentStateName.ToString()
                    : null;
            }
            catch
            {
            }

            string exceptionName = exception?.GetType().Name ?? "unknown";
            string sourceName = source ?? "unknown";
            WriteEvent("followPathWriteException", bot, new
            {
                source = sourceName,
                target = Vec(target),
                exception = exceptionName,
                message = exception?.Message ?? string.Empty,
                handsController,
                playerState,
                action = "deferSinglePathWriteWithoutGlobalStop"
            });
            Logger.LogWarning(
                "[FollowAction] deferred path write after " + exceptionName +
                " source=" + sourceName +
                " hands=" + (handsController ?? "null") +
                " state=" + (playerState ?? "unknown"));
        }

        public static void RecordFollowPathSanityRejected(
            BotOwner bot,
            Vector3 target,
            string source,
            float pathLength,
            float detourRatio)
        {
            bool leaderRoute = IsLeaderFollowPathSource(source);
            bool exitAuthorityHandoff =
                string.Equals(source, "exit-authority-follow-handoff", StringComparison.OrdinalIgnoreCase);

            // CompileFix18: FollowAction's priority traversal approach used to report PathInvalid only
