        public static bool TryGetKnownWalkThroughPortalPreemptionTarget(
            BotOwner bot,
            Vector3 leaderPosition,
            out Vector3 target,
            out bool probeStarted,
            out int edgeId)
        {
            target = default;
            probeStarted = false;
            edgeId = 0;

            if ((!raidActive) || !IsLiveBot(bot) || !BossPlayers.IsFollower(bot) ||
                !IsFinite(bot.Position) || !IsFinite(leaderPosition) ||
                HasPendingTraversalMission(bot) || HasActiveTraversalProbe(bot) ||
                localVaultActive || localJumpCandidateActive || localNaturalDropCandidateActive)
            {
                return false;
            }

            // V3.17: RouteMission is the higher-level ordered traversal owner even during the
            // short approach interval before EnsureFollowerRouteMissionCommitment creates the
            // current step commitment. V3.13 must not erase that mission just because its own
            // narrower pending-commitment test is temporarily false.
            if ((TryGetActiveFollowerRouteMission(bot, out FollowerRouteMission routeMission)))
            {
                if (ShouldEmitDiagnostic("learningV317KnownPortalDeferredToRouteMission", bot, 0.50f))
                {
                    FollowerRouteMissionStep step = routeMission.Steps[routeMission.CurrentStepIndex];
                    WriteEvent("learningV317KnownPortalPreemptionDeferredToRouteMission", bot, new
                    {
                        missionId = routeMission.MissionId,
                        currentStepIndex = routeMission.CurrentStepIndex,
                        traversalCount = routeMission.Steps.Count,
                        currentEdgeId = step?.EdgeId ?? 0,
                        currentKind = step?.Kind,
                        expiresIn = Mathf.Max(0f, routeMission.ExpiresAt - Time.time),
                        reason = "activeRouteMissionOwnsTraversalOrdering"
                    });
                }
                return false;
            }

            // V3.13 is intentionally a fact-delivery fast path, not a second traversal selector.
            // Reuse the exact proven-portal predicate/commitment producer; do not prune/search all
            // generic learned traversal candidates or calculate leader detour topology here.
            if (!TryLatchProvenWalkThroughPortalAhead(
                    bot, leaderPosition, out target, out probeStarted, out edgeId))
            {
                return false;
            }

            WriteEvent("learningV313KnownWalkThroughPortalFactDelivered", bot, new
            {
                edgeId,
                entry = Vec(target),
                probeStarted,
                delivery = "followTickPreCadence",
                ordinaryFollowCadenceBypassed = true
            });
            return true;
        }

        // RC48: no new controller, registry, lease or per-action state machine.
        // This is a bounded, exact-Step observation in the existing route owner.
        // Measure next-frame STRICT remaining path distance; a coincident path
        // API result or same-frame Player.Move delta cannot acknowledge motion.
        private static bool TryObserveRC48PhysicalIngress(
            BotOwner bot, FollowerRouteMission mission, FollowerRouteMissionStep step,
            Vector3 target, out bool stalled)
        {
            stalled = false;
            if (bot == null || mission == null || step == null || !IsFinite(target))
                return false;
            if (Time.time < step.Rc48IngressLastSampleAt + 0.16f &&
                GetPlanarDistance(step.Rc48IngressObservedTarget, target) < 0.10f)
                return true;
            StrictPathResult remaining = CalculateStrictPath(bot.Position, target);
            if (remaining?.StrictComplete != true)
            {
                // No trusted complete path means no native-mover permission;
                // do not infer progress from an invalid cost metric.
                step.Rc48MoverCommandAccepted = false;
                return false;
            }
            float cost = remaining.PathLength;
            bool newTarget = step.Rc48IngressLastSampleAt <= 0f ||
                GetPlanarDistance(step.Rc48IngressObservedTarget, target) >= 0.10f;
            if (newTarget)
            {
                step.Rc48IngressObservedTarget = target;
                step.Rc48IngressFirstObservedAt = Time.time;
                step.Rc48IngressLastProgressAt = Time.time;
                step.Rc48IngressBestPathCost = cost;
                step.Rc48MoverCommandAccepted = false;
            }
            else if (cost <= step.Rc48IngressBestPathCost - 0.075f)
            {
                step.Rc48IngressBestPathCost = cost;
                step.Rc48IngressLastProgressAt = Time.time;
                // Real measured closure, not pathStatus, is progress.
                mission.LastProgressAt = Time.time;
                mission.LastProgressPosition = bot.Position;
            }
            step.Rc48IngressLastSampleAt = Time.time;
            stalled = !newTarget && cost > 0.55f &&
                Time.time - step.Rc48IngressFirstObservedAt >= 1.10f &&
                Time.time - step.Rc48IngressLastProgressAt >= 1.05f;
            if (ShouldEmitDiagnostic("v2rc48PhysicalIngressProgressAck:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    step.EdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.35f))
                WriteEvent("v2rc48PhysicalIngressProgressAck", bot, new
                {
                    missionId = mission.MissionId, edgeId = step.EdgeId,
                    position = Vec(bot.Position), exactTarget = Vec(target),
                    remainingPathCost = cost, bestPathCost = step.Rc48IngressBestPathCost,
                    progressAge = Time.time - step.Rc48IngressLastProgressAt,
                    nativeMoverAccepted = step.Rc48MoverCommandAccepted,
                    livenessBlocked = stalled, nativeSuccessRecorded = false,
                    action = "nextFrameBodyStrictPathClosureIsTheOnlyIngressAck"
                });
            return true;
        }

        // RC57 regression-bisect: restore the V475 collision-active single Climb
        // producer, under V2's already existing Follow write-scope. No stage planner,
        // first NavMesh corner, GoToPoint, stale mover strategy ACK, or fallback
        // policy can issue a competing Climb target. The original V424 admission
