        {
            target = default;
            probeStarted = false;
            edgeId = 0;

            if (!raidActive || !IsLiveBot(bot) || !BossPlayers.IsFollower(bot) ||
                !IsFinite(bot.Position) || !IsFinite(leaderPosition))
            {
                return false;
            }

            PruneCapabilityResolvedCommitment(bot);
            if(IsCapabilityReturnInProgress(bot)){target=bot.Position;probeStarted=true;return true;}
            if (TickCapabilityPortalWait(bot)){target=bot.Position;probeStarted=true;return true;}
            if (HasCapabilityFailureStrategy(bot))
            { TickCapabilityFailureSequence(bot); target=bot.Position;probeStarted=true;return true; }
            if (IsCapabilityRecoveryPending(bot))
            { TickCapabilityFailureSequence(bot); target=bot.Position;probeStarted=true;return true; }
            if(TryGetCapabilityPortalApproachTarget(bot,out target,out edgeId))return true;
            PruneLearnedTraversalEdges();

            if ((IsLearningV350TerminalPhysicalRecoveryEligible(bot)))
            {
                // Terminal recovery is a movement-ownership state, not a selector hint. Do not let
                // generic/priority traversal selection recreate any executor while NavigationRecovery
                // is aging toward its bounded safety net. Route semantic state remains intact.
                ReleaseLearningV353TerminalRecoveryRetryLease(bot, "learnedTraversalSelector");
