            string botProfileId = bot.ProfileId ?? string.Empty;
            bool playerSemanticCaptureActive = FollowerCapabilityHelperRules.TryGetLearnedTraversalFollowTarget_playerSemanticCaptureActive_DF09F3AC_1(localVaultActive,localJumpCandidateActive,localNaturalDropCandidateActive);

