                    if (priorityEntryDistance <= priorityLocalWindow &&
                        EnsureFollowerRouteMissionCommitment(bot, priorityRouteMission) &&
                        LearnedTraversalCommitments.TryGetValue(botProfileId, out LearnedTraversalCommitment priorityCommitment) &&
                        priorityCommitment != null && priorityCommitment.RouteMissionId == priorityRouteMission.MissionId &&
                        priorityCommitment.EdgeId == priorityStep.EdgeId)
                    {
                        if ((string.Equals(priorityStep.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
                        {
