                float leaderA = GetLocalTraversalPathCost(leaderToA, candidate.LeaderDirectA, LearnedTraversalLeaderPathLimit);
                float leaderB = GetLocalTraversalPathCost(leaderToB, candidate.LeaderDirectB, LearnedTraversalLeaderPathLimit);

