        private static bool TryGetLearningV414KnownWalkThroughPhysicalPreflight(
            BotOwner bot,
            LearnedTraversalEdge edge,
            int crossingStartSequence,
            int crossingEndSequence,
            out string reason,
            out float projection,
            out float span,
            out float lateral,
            out float verticalDeviation,
            out bool supported)
        {
            reason = string.Empty;
            projection = 0f;
            span = 0f;
            lateral = float.MaxValue;
            verticalDeviation = float.MaxValue;
            supported = false;
            Player player = bot?.GetPlayer ?? bot?.AIData?.Player;
            if ((player?.MovementContext == null) ||
                edge == null || !IsFinite(player.Position))
            {
                reason = "preflightUnavailable";
                return false;
            }

            Vector3 entry = IsFinite(edge.RawStart) ? edge.RawStart : edge.A;
            Vector3 exit = IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B;
            if ((TryResolveLearningV424CurrentEpisodeWalkThroughGeometry(
                    edge.Id, 0, crossingStartSequence, crossingEndSequence,
                    out _, out Vector3 learningV424ExecutionEntry, out Vector3 learningV424ExecutionExit)))
            {
                entry = learningV424ExecutionEntry;
                exit = learningV424ExecutionExit;
            }
            if (!IsFinite(entry) || !IsFinite(exit))
            {
                reason = "invalidPortalGeometry";
                return false;
            }

            Vector3 axis = exit - entry;
            axis.y = 0f;
            span = axis.magnitude;
            if (span < 0.25f)
            {
                reason = "degeneratePortalAxis";
                return false;
            }
            Vector3 direction = axis / span;
            Vector3 bodyDelta = player.Position - entry;
            bodyDelta.y = 0f;
            projection = Vector3.Dot(bodyDelta, direction);
            Vector3 projected = entry + direction * projection;
            lateral = GetPlanarDistance(player.Position, projected);
            float routeT = Mathf.Clamp01(projection / span);
            float expectedY = Mathf.Lerp(entry.y, exit.y, routeT);
            verticalDeviation = Mathf.Abs(player.Position.y - expectedY);
            supported = IsEffectivelySupportedForProbe(bot, player) &&
                        !IsProbeTraversalState(player.CurrentStateName);

            bool longitudinalLane = FollowerCapabilityHelperRules.TryGetLearningV414KnownWalkThroughPhysicalPreflight_longitudinalLane_278593DB_1(projection,KnownWalkThroughPortalEntryDistance,projection,span,KnownWalkThroughPortalFarSideProjectionSlack);
            bool lateralLane = lateral <= WalkThroughHardLateralDeviation;
            bool verticalLane = FollowerCapabilityHelperRules.TryGetLearningV414KnownWalkThroughPhysicalPreflight_verticalLane_278593DB_2(verticalDeviation,WalkThroughMaxVerticalDelta);
            if (!longitudinalLane)
            {
                reason = "outsideFiniteLongitudinalLane";
                return false;
            }
            if (!lateralLane)
            {
                reason = "outsideLateralLane";
                return false;
            }
            if (!verticalLane)
            {
                reason = "outsideVerticalLane";
                return false;
            }
            if (!supported)
            {
                reason = "bodyNotSupportedForPortalPreemption";
                return false;
            }

            reason = "currentBodyInsideSupportedFinitePortalLane";
            return true;
        }

        private static bool TryLatchProvenWalkThroughPortalAhead(
            BotOwner bot,
            Vector3 leaderPosition,
            out Vector3 target,
            out bool probeStarted,
            out int edgeId)
        {
            target = default;
            probeStarted = false;
            edgeId = 0;
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || LearnedTraversalEdges.Count == 0 || HasActiveTraversalProbe(bot))
            {
                return false;
            }

            int consumedBreadcrumbSequence = 0;
            if (FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) && cursor != null)
            {
                consumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence;
            }

            LearnedTraversalEdge bestEdge = null;
            float bestEntryDistance = float.MaxValue;
            int bestEntrySequence = 0;
            int bestExitSequence = 0;
            int bestPhysical = 0;
            int bestAttempts = 0;
            float bestPhysicalRate = 0f;

            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (edge == null || !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                    !IsTraversalEdgeSelectableForFollower(bot, edge, checkExperience: false, out _) ||
                    IsTraversalEpisodeAlreadyConsumed(bot, edge) ||
                    IsRecentTraversalRelatchBlocked(bot, edge, out _))
                {
                    continue;
                }

                int physical = GetTraversalPhysicalSuccessCount(edge);
                int attempts = 0;
                float physicalRate = physical > 0 ? 1f : 0f;
                if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                    TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord experience) &&
                    experience != null)
                {
                    attempts = Math.Max(0, experience.Attempts);
                    physicalRate = physical / (float)Math.Max(1, attempts);
