                if (followerAlreadyOnExitSide)
                {
                    if (ShouldEmitDiagnostic(
                            "learningV320KnownWalkThroughAlreadyExitSide:" + edge.Id, bot, 0.75f))
                    {
                        WriteEvent("learningV320KnownWalkThroughPreemptionSuppressed", bot, new
                        {
                            edgeId = edge.Id,
                            entry = Vec(entry),
                            exit = Vec(exit),
                            entryDistance,
                            exitDistance = followerExitDistance,
                            reason = "alreadyOnExitSide"
                        });
                    }
                    continue;
                }

                if (!TryFindRecentBreadcrumbPortalCrossing(
                        entry,
                        exit,
                        consumedBreadcrumbSequence,
                        out int entrySequence,
                        out int exitSequence))
                {
                    continue;
                }

                Vector3 portalDirection = GetFlatDirection(exit - entry);
                float portalLength = GetPlanarDistance(entry, exit);
                Vector3 leaderOffset = leaderPosition - entry;
                leaderOffset.y = 0f;
                float leaderProjection = portalDirection.sqrMagnitude > 0.5f
                    ? Vector3.Dot(leaderOffset, portalDirection)
                    : 0f;
                bool leaderOnFarSide = FollowerCapabilityHelperRules.TryLatchProvenWalkThroughPortalAhead_leaderOnFarSide_CEF6B5C6_2(leaderProjection,portalLength,KnownWalkThroughPortalFarSideProjectionSlack) ||
                                       GetPlanarDistance(leaderPosition, exit) + 0.25f < GetPlanarDistance(leaderPosition, entry);
                if (!leaderOnFarSide)
                {
                    continue;
                }

                if ((!TryGetLearningV414KnownWalkThroughPhysicalPreflight(
                        bot, edge, entrySequence, exitSequence, out string learningV414PreflightReason,
                        out float learningV414Projection, out float learningV414Span,
                        out float learningV414Lateral, out float learningV414Vertical,
                        out bool learningV414Supported)))
                {
                    WriteEvent("learningV414KnownWalkThroughPreemptionRejectedBeforeAuthorityMutation", bot, new
                    {
                        edgeId = edge.Id,
                        experienceKey = edge.ExperienceKey,
                        bodyPosition = Vec(bot.GetPlayer != null ? bot.GetPlayer.Position : bot.Position),
                        entry = Vec(entry),
                        exit = Vec(exit),
                        projection = learningV414Projection,
                        span = learningV414Span,
                        lateral = learningV414Lateral,
                        verticalDeviation = learningV414Vertical,
                        supported = learningV414Supported,
                        reason = learningV414PreflightReason,
                        commitmentCreated = false,
                        routeMissionChanged = false,
                        followLeaseChanged = false,
                        authorityChanged = false,
                        action = "currentBodyPhysicalAdmissionMustPassBeforeHistoricalPortalMayPreemptFollow"
                    });
                    continue;
                }

                if (entryDistance < bestEntryDistance)
                {
                    bestEdge = edge;
                    bestEntryDistance = entryDistance;
                    bestEntrySequence = entrySequence;
                    bestExitSequence = exitSequence;
                    bestPhysical = physical;
                    bestAttempts = attempts;
                    bestPhysicalRate = physicalRate;
                }
            }

            if (bestEdge == null)
            {
                return false;
            }

            if ((IsFinite(bot.Position)) && IsFinite(leaderPosition))
            {
                StrictPathResult currentFollowPath = CalculateStrictPath(bot.Position, leaderPosition);
                float directLeaderDistance = GetPlanarDistance(bot.Position, leaderPosition);
                float necessityPathLimit = Math.Min(
                    GetAllowedFollowPathLength(Mathf.Max(0.25f, directLeaderDistance), true),
                    Mathf.Max(0.25f, directLeaderDistance) * WalkThroughLocalBypassRatio);
