            Vector3 learningV424ExecutionEntry = bestEdge.A;
            Vector3 learningV424ExecutionExit = bestEdge.B;
            Vector3 learningV424ExecutionRawEntry = bestEdge.RawStart;
            Vector3 learningV424ExecutionRawExit = bestEdge.RawEnd;
            TraversalEpisodeMetadata learningV424ExecutionEpisode = null;
            bool learningV424CurrentEpisodeGeometry =
                (TryResolveLearningV424CurrentEpisodeWalkThroughGeometry(
                    bestEdge.Id, 0, bestEntrySequence, bestExitSequence,
                    out learningV424ExecutionEpisode,
                    out learningV424ExecutionRawEntry,
                    out learningV424ExecutionRawExit));
            if (learningV424CurrentEpisodeGeometry)
            {
                learningV424ExecutionEntry = learningV424ExecutionRawEntry;
                learningV424ExecutionExit = learningV424ExecutionRawExit;
                bestEntryDistance = GetPlanarDistance(bot.Position, learningV424ExecutionEntry);
                if (bestEntryDistance > KnownWalkThroughPortalEntryDistance)
                {
                    WriteEvent("learningV424KnownWalkThroughPreemptionDeferredForFreshExecutionGeometry", bot, new
                    {
                        edgeId = bestEdge.Id,
                        episodeId = learningV424ExecutionEpisode?.EpisodeId ?? 0,
                        semanticEntry = Vec(bestEdge.A),
                        currentExecutionEntry = Vec(learningV424ExecutionEntry),
                        currentExecutionExit = Vec(learningV424ExecutionExit),
                        entryDistance = bestEntryDistance,
                        maximumEntryDistance = KnownWalkThroughPortalEntryDistance,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "semanticPortalMayIdentifyPassageButCannotPreemptUntilFreshExecutionEntryIsPhysicallyLocal"
                    });
                    return false;
                }
            }

            LearnedTraversalCommitment commitment = CreateLearnedTraversalCommitment(
                bestEdge, learningV424ExecutionEntry, learningV424ExecutionExit,
                learningV424ExecutionRawEntry, learningV424ExecutionRawExit);
            if (commitment == null)
            {
                return false;
            }
            if (learningV424CurrentEpisodeGeometry && learningV424ExecutionEpisode != null)
            {
                commitment.EpisodeId = learningV424ExecutionEpisode.EpisodeId;
                commitment.ChainId = learningV424ExecutionEpisode.ChainId;
            }

            LearnedTraversalCommitments[profileId] = commitment;
            BreadcrumbFollowCommitments.Remove(profileId);
            BreadcrumbGapQuarantines.Remove(profileId);
            RemoveLifecycleMission(profileId, "TryLatchProvenWalkThroughPortalAhead");
            FollowRejectLeases.Remove(profileId);
            target = learningV424ExecutionEntry;
            edgeId = bestEdge.Id;

            WriteEvent("knownWalkThroughPortalPreempted", bot, new
            {
                edgeId,
                entry = Vec(learningV424ExecutionEntry),
                exit = Vec(learningV424ExecutionExit),
                semanticEntry = learningV424CurrentEpisodeGeometry ? (object)Vec(bestEdge.A) : null,
                semanticExit = learningV424CurrentEpisodeGeometry ? (object)Vec(bestEdge.B) : null,
                currentExecutionEpisodeId = learningV424ExecutionEpisode?.EpisodeId ?? 0,
                currentEpisodeGeometry = learningV424CurrentEpisodeGeometry,
                entryDistance = bestEntryDistance,
                physicalSuccesses = bestPhysical,
                attempts = bestAttempts,
                physicalRate = bestPhysicalRate,
                recentEntrySequence = bestEntrySequence,
                recentExitSequence = bestExitSequence,
                leaderDistance = Vector3.Distance(bot.Position, leaderPosition)
            });

            if (!ShouldArmLearnedTraversalProbe(
                    bot, bestEdge.Kind, bestEntryDistance,
                    learningV424ExecutionEntry, learningV424ExecutionRawExit))
            {
                return true;
            }

            string retryKey = profileId + ":" + edgeId.ToString(CultureInfo.InvariantCulture);
            if (LearnedTraversalRetryAfter.TryGetValue(retryKey, out float retryAt) && Time.time < retryAt)
            {
                return true;
            }

            Vector3 direction = GetFlatDirection(learningV424ExecutionRawExit - learningV424ExecutionRawEntry);
            if (TryStartProbeForBot(
                    bot,
                    direction,
                    "knownWalkThroughPortalPreemption",
                    edgeId,
                    bestEdge.Kind,
                    "knownWalkThroughPortalPreemption",
                    out string startMessage))
            {
                LearnedTraversalRetryAfter[retryKey] = Time.time + LearnedTraversalRetryCooldown;
                probeStarted = true;
                WriteEvent("knownWalkThroughPortalProbeStarted", bot, new
                {
                    edgeId,
                    entry = Vec(learningV424ExecutionEntry),
                    exit = Vec(learningV424ExecutionExit),
                    currentExecutionEpisodeId = learningV424ExecutionEpisode?.EpisodeId ?? 0,
                    currentEpisodeGeometry = learningV424CurrentEpisodeGeometry,
                    message = startMessage
                });
            }
            return true;
        }

        private static bool TryFindRecentBreadcrumbPortalCrossing(
            Vector3 entry,
            Vector3 exit,
            int consumedBreadcrumbSequence,
            out int entrySequence,
            out int exitSequence)
        {
            entrySequence = 0;
            exitSequence = 0;
            int candidateEntrySequence = 0;
            float now = Time.time;
            for (int index = 0; index < BreadcrumbRoute.Count; index++)
            {
                PlayerBreadcrumbNode node = BreadcrumbRoute[index];
                if (node == null || node.Sequence <= consumedBreadcrumbSequence ||
                    now - node.CreatedAt > BreadcrumbTtlSeconds || !IsOperationalBreadcrumbNode(node))
                {
                    continue;
                }

                if (candidateEntrySequence <= 0 &&
                    GetPlanarDistance(node.Position, entry) <= KnownWalkThroughPortalBreadcrumbEntryRadius)
                {
                    candidateEntrySequence = node.Sequence;
                    continue;
                }

                if (candidateEntrySequence > 0 && node.Sequence > candidateEntrySequence &&
                    GetPlanarDistance(node.Position, exit) <= KnownWalkThroughPortalBreadcrumbExitRadius)
                {
                    entrySequence = candidateEntrySequence;
                    exitSequence = node.Sequence;
                    return true;
                }
            }
            return false;
        }

        private static bool IsLearningV325ExplicitTraversalSemanticState(string state)
        {
            if (string.IsNullOrWhiteSpace(state))
            {
                return false;
            }
            return state.IndexOf("Vault", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   state.IndexOf("Climb", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   state.IndexOf("Jump", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static bool HasLearningV325ObservedReverseWalkThroughLocomotionProof(
            PlayerBreadcrumbNode entry, PlayerBreadcrumbNode exit, out string reason, out int sampleCount)
        {
            reason = string.Empty;
            sampleCount = 0;
            if (entry == null || exit == null || entry.Sequence <= 0 || exit.Sequence <= entry.Sequence)
            {
                reason = "invalidObservedEpisode";
                return false;
            }
            List<PlayerBreadcrumbNode> observed = BreadcrumbRoute
                .Where(node => node != null && node.Sequence >= entry.Sequence && node.Sequence <= exit.Sequence &&
                               IsOperationalBreadcrumbNode(node) && IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            sampleCount = observed.Count;
            if (sampleCount < 2)
            {
                reason = "insufficientObservedBreadcrumbs";
                return false;
            }
            PlayerBreadcrumbNode first = observed[0];
            PlayerBreadcrumbNode last = observed[observed.Count - 1];
            if (!first.Grounded || !last.Grounded)
            {
                reason = "observedEndpointsNotGrounded";
                return false;
            }
            PlayerBreadcrumbNode semanticTraversal = observed.FirstOrDefault(node =>
                IsLearningV325ExplicitTraversalSemanticState(node.State));
            if (semanticTraversal != null)
            {
                reason = "observedTraversalState=" + (semanticTraversal.State ?? string.Empty);
                return false;
            }
            return true;
        }

        private static bool TryCaptureLearningV339ForwardKnownWalkThroughRouteFact(PlayerBreadcrumbNode current)
        {
            if ((current == null) ||
                LearnedTraversalEdges.Count == 0 || !IsOperationalBreadcrumbNode(current) ||
                !IsFinite(current.Position))
            {
                return false;
            }

            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (edge == null || edge.Disabled || !IsLearningV344AuthoritativeWalkThroughSemanticEdge(edge) ||
                    !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                    !IsFinite(edge.RawStart) || !IsFinite(edge.RawEnd))
                {
                    continue;
                }

                Vector3 axis = edge.RawEnd - edge.RawStart;
                axis.y = 0f;
                float span = axis.magnitude;
                if (span < WalkThroughCandidateMinDistance ||
                    GetPlanarDistance(current.Position, edge.RawEnd) > KnownWalkThroughPortalBreadcrumbExitRadius ||
                    Mathf.Abs(current.Position.y - edge.RawEnd.y) > RouteMissionDirectionalWalkThroughVerticalTolerance)
                {
                    continue;
                }

                Vector3 direction = axis / span;
                Vector3 currentOffset = current.Position - edge.RawStart;
                currentOffset.y = 0f;
                float currentProjection = Vector3.Dot(currentOffset, direction);
                Vector3 currentLateral = currentOffset - direction * currentProjection;
                if (currentProjection < span + KnownWalkThroughPortalFarSideProjectionSlack ||
                    currentLateral.magnitude > RouteMissionDirectionalWalkThroughMaxLateral)
                {
                    continue;
                }

                PlayerBreadcrumbNode entryNode = BreadcrumbRoute
                    .Where(node => node != null && node.Sequence < current.Sequence &&
                        IsOperationalBreadcrumbNode(node) && IsFinite(node.Position) &&
                        current.CreatedAt - node.CreatedAt >= 0f &&
                        current.CreatedAt - node.CreatedAt <= WalkThroughEpisodeMaxGapSeconds &&
                        GetPlanarDistance(node.Position, edge.RawStart) <= KnownWalkThroughPortalBreadcrumbEntryRadius &&
                        Mathf.Abs(node.Position.y - edge.RawStart.y) <= RouteMissionDirectionalWalkThroughVerticalTolerance)
                    .OrderByDescending(node => node.Sequence)
                    .FirstOrDefault();
                if (entryNode == null)
                {
                    continue;
                }

                Vector3 entryOffset = entryNode.Position - edge.RawStart;
                entryOffset.y = 0f;
                float entryProjection = Vector3.Dot(entryOffset, direction);
                Vector3 entryLateral = entryOffset - direction * entryProjection;
                if (entryProjection >= span || entryLateral.magnitude > RouteMissionDirectionalWalkThroughMaxLateral)
                {
                    continue;
                }

                bool alreadyRegistered = TraversalEpisodeStream.Any(item => item != null &&
                    item.EdgeId == edge.Id && item.EndBreadcrumbSequence >= entryNode.Sequence);
                if (alreadyRegistered)
                {
                    continue;
                }

                if ((IsLearningV349CurrentRaidOrdinaryWalkThroughDisproof(
                        edge,
                        entryNode.Sequence,
                        current.Sequence,
                        entryNode.Position,
                        current.Position,
                        out StrictPathResult learningV381KnownForwardPath,
                        out int learningV381KnownForwardSamples,
                        out float learningV381KnownForwardBypassCost,
                        out float learningV381KnownForwardBypassRatio)))
                {
                    LearningV349CurrentRaidSemanticDisproofEdges.Add(edge.Id);
                    WriteEvent("learningV381KnownWalkThroughRouteFactRetiredByNavMesh", null, new
                    {
                        edgeId = edge.Id,
                        direction = "forward",
                        startBreadcrumbSequence = entryNode.Sequence,
                        endBreadcrumbSequence = current.Sequence,
                        ordinarySampleCount = learningV381KnownForwardSamples,
                        localBypassCost = learningV381KnownForwardBypassCost,
                        localBypassRatio = learningV381KnownForwardBypassRatio,
                        strictPathStatus = learningV381KnownForwardPath?.Status.ToString() ?? string.Empty,
                        strictPathLength = learningV381KnownForwardPath?.PathLength ?? 0f,
                        persistentLearningChanged = false,
                        traversalSuccessRecorded = false,
                        action = "healthyCurrentRaidNavMeshCancelsKnownWalkThroughExecutionDebtBeforeRouteFactRegistration"
                    });
                    continue;
                }

                TraversalEpisodeMetadata episode = RegisterTraversalEpisodeForEdge(
                    edge.Id, "WalkThrough", edge.RawStart, edge.RawEnd,
                    entryNode.Sequence, current.Sequence, allowChain: true);
                if (episode == null)
                {
                    continue;
                }

                WriteEvent("learningV339ForwardKnownWalkThroughRouteFactCaptured", null, new
                {
                    edgeId = edge.Id,
                    nativeSuccesses = edge.NativeSuccessCount,
                    startBreadcrumbSequence = entryNode.Sequence,
                    endBreadcrumbSequence = current.Sequence,
                    observedStart = Vec(entryNode.Position),
                    observedEnd = Vec(current.Position),
                    entry = Vec(edge.RawStart),
                    exit = Vec(edge.RawEnd),
                    routeConsumer = "existingFollowerRouteMission",
                    action = "nativeProvenForwardCrossingBecomesOrderedRouteFact"
                });
                return true;
            }
            return false;
        }

        private static bool TryCaptureLearningV314ReverseKnownWalkThroughRouteFact(PlayerBreadcrumbNode current)
        {
            if ((current == null) ||
                LearnedTraversalEdges.Count == 0 || !IsOperationalBreadcrumbNode(current) ||
                !IsFinite(current.Position))
            {
                return false;
            }

            LearnedTraversalEdge bestForward = null;
            PlayerBreadcrumbNode bestReverseEntryNode = null;
            float bestReverseEntryDistance = float.MaxValue;
            float bestReverseExitDistance = float.MaxValue;
            int bestReverseEntrySequence = 0;

            // V3.14 does not infer bidirectional permission. It only asks whether the player's
            // fresh breadcrumbs independently prove a B->A crossing of an already Native-Proven
            // directional WalkThrough. The reverse execution edge remains a separate sibling.
            foreach (LearnedTraversalEdge provenForward in LearnedTraversalEdges)
            {
                if (provenForward == null || provenForward.Disabled ||
                    !string.Equals(provenForward.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                    !IsLearningV344AuthoritativeWalkThroughSemanticEdge(provenForward) ||
                    !IsFinite(provenForward.RawStart) || !IsFinite(provenForward.RawEnd))
                {
                    continue;
                }

                Vector3 reverseEntry = provenForward.RawEnd;
                Vector3 reverseExit = provenForward.RawStart;
                Vector3 reverseAxis = reverseExit - reverseEntry;
                reverseAxis.y = 0f;
                float reverseSpan = reverseAxis.magnitude;
                if (reverseSpan < WalkThroughCandidateMinDistance)
                {
                    continue;
                }
                float reverseVerticalDelta = reverseExit.y - reverseEntry.y;
                Vector3 reverseDirection = reverseAxis / reverseSpan;

                float reverseExitDistance = GetPlanarDistance(current.Position, reverseExit);
                if (reverseExitDistance > KnownWalkThroughPortalBreadcrumbEntryRadius ||
                    Mathf.Abs(current.Position.y - reverseExit.y) > RouteMissionDirectionalWalkThroughVerticalTolerance)
                {
                    continue;
                }

                Vector3 currentFromReverseEntry = current.Position - reverseEntry;
                currentFromReverseEntry.y = 0f;
                float currentProjection = Vector3.Dot(currentFromReverseEntry, reverseDirection);
                Vector3 currentLateral = currentFromReverseEntry - reverseDirection * currentProjection;
                if (currentProjection < reverseSpan + KnownWalkThroughPortalFarSideProjectionSlack ||
                    currentLateral.magnitude > RouteMissionDirectionalWalkThroughMaxLateral)
                {
                    continue;
                }

                PlayerBreadcrumbNode reverseEntryNode = BreadcrumbRoute
                    .Where(node =>
                    {
                        if (node == null || node.Sequence >= current.Sequence ||
                            !IsOperationalBreadcrumbNode(node) || !IsFinite(node.Position) ||
                            current.CreatedAt - node.CreatedAt < 0f ||
                            current.CreatedAt - node.CreatedAt > WalkThroughEpisodeMaxGapSeconds ||
                            GetPlanarDistance(node.Position, reverseEntry) > KnownWalkThroughPortalBreadcrumbExitRadius ||
                            Mathf.Abs(node.Position.y - reverseEntry.y) > RouteMissionDirectionalWalkThroughVerticalTolerance)
                        {
                            return false;
                        }

                        {
                            Vector3 candidateFromReverseEntry = node.Position - reverseEntry;
                            candidateFromReverseEntry.y = 0f;
                            float candidateProjection = Vector3.Dot(candidateFromReverseEntry, reverseDirection);
                            // V3.15 semantic boundary: the route episode's entry proof must still
                            // be on the pre-exit side. Far-side slack belongs only to the current
                            // exit confirmation and may not authorize a post-exit entry sample.
                            if (candidateProjection >= reverseSpan)
                            {
                                return false;
                            }
                        }

                        return true;
                    })
                    .OrderByDescending(node => node.Sequence)
                    .FirstOrDefault();
                if (reverseEntryNode == null)
                {
                    continue;
                }

                Vector3 entryFromReverseEntry = reverseEntryNode.Position - reverseEntry;
                entryFromReverseEntry.y = 0f;
                float entryProjection = Vector3.Dot(entryFromReverseEntry, reverseDirection);
                Vector3 entryLateral = entryFromReverseEntry - reverseDirection * entryProjection;
                if (((entryProjection >= reverseSpan)) ||
                    entryLateral.magnitude > RouteMissionDirectionalWalkThroughMaxLateral)
                {
                    continue;
                }

                if ((Mathf.Abs(reverseVerticalDelta) > WalkThroughCandidateMaxVerticalDelta))
                {
                    if (!HasLearningV325ObservedReverseWalkThroughLocomotionProof(
                            reverseEntryNode, current, out string observedSemanticReason,
                            out int observedSemanticSamples))
                    {
                        if (ShouldEmitDiagnostic(
                            "learningV325ReverseWalkThroughObservedSemanticRejected:" + provenForward.Id, null, 0.75f))
                        {
                            WriteEvent("learningV325ReverseWalkThroughObservedSemanticRejected", null, new
                            {
                                provenForwardEdgeId = provenForward.Id,
                                reverseEntry = Vec(reverseEntry),
                                reverseExit = Vec(reverseExit),
                                reverseVerticalDelta,
                                observedSemanticSamples,
                                reason = observedSemanticReason,
                                action = "requireObservedLocomotionOrIndependentTraversalKind"
                            });
                        }
                        continue;
                    }
                    WriteEvent("learningV325ReverseWalkThroughObservedLocomotionProofAccepted", null, new
                    {
                        provenForwardEdgeId = provenForward.Id,
                        reverseEntry = Vec(reverseEntry),
                        reverseExit = Vec(reverseExit),
                        reverseVerticalDelta,
                        observedSemanticSamples,
                        startBreadcrumbSequence = reverseEntryNode.Sequence,
                        endBreadcrumbSequence = current.Sequence
                    });
                }

                float reverseEntryDistance = GetPlanarDistance(reverseEntryNode.Position, reverseEntry);
                bool better = bestForward == null ||
                              reverseEntryNode.Sequence > bestReverseEntrySequence ||
                              (reverseEntryNode.Sequence == bestReverseEntrySequence &&
                               reverseEntryDistance + reverseExitDistance < bestReverseEntryDistance + bestReverseExitDistance);
                if (!better)
                {
                    continue;
                }

                bestForward = provenForward;
                bestReverseEntryNode = reverseEntryNode;
                bestReverseEntryDistance = reverseEntryDistance;
                bestReverseExitDistance = reverseExitDistance;
                bestReverseEntrySequence = reverseEntryNode.Sequence;
            }

            if (bestForward == null || bestReverseEntryNode == null)
            {
                return false;
            }

            if ((IsLearningV349CurrentRaidOrdinaryWalkThroughDisproof(
                    bestForward,
                    bestReverseEntryNode.Sequence,
                    current.Sequence,
                    bestReverseEntryNode.Position,
                    current.Position,
                    out StrictPathResult learningV381KnownReversePath,
                    out int learningV381KnownReverseSamples,
                    out float learningV381KnownReverseBypassCost,
                    out float learningV381KnownReverseBypassRatio)))
            {
                WriteEvent("learningV381KnownWalkThroughRouteFactRetiredByNavMesh", null, new
                {
                    edgeId = bestForward.Id,
                    direction = "reverse",
                    startBreadcrumbSequence = bestReverseEntryNode.Sequence,
                    endBreadcrumbSequence = current.Sequence,
                    ordinarySampleCount = learningV381KnownReverseSamples,
                    localBypassCost = learningV381KnownReverseBypassCost,
                    localBypassRatio = learningV381KnownReverseBypassRatio,
                    strictPathStatus = learningV381KnownReversePath?.Status.ToString() ?? string.Empty,
                    strictPathLength = learningV381KnownReversePath?.PathLength ?? 0f,
                    reverseSiblingCreated = false,
                    persistentLearningChanged = false,
                    traversalSuccessRecorded = false,
                    action = "healthyCurrentRaidNavMeshCancelsReverseWalkThroughExecutionDebtBeforeSiblingCreation"
                });
                return false;
            }

            Vector3 reverseRawStart = bestForward.RawEnd;
            Vector3 reverseRawEnd = bestForward.RawStart;
            LearnedTraversalEdge reverseEdge = LearnedTraversalEdges
                .Where(edge => edge != null && edge.Id != bestForward.Id && !edge.Disabled && edge.PlayerValidated &&
                               string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                               IsLearningV2SameLocalSkill(edge, reverseRawStart, reverseRawEnd, directionalKind: true))
                .OrderByDescending(edge => IsLearningV3NativeProvenEdge(edge) ? 1 : 0)
                .ThenByDescending(edge => edge.PlayerTraversalSequence)
                .FirstOrDefault();

            bool reverseSiblingCreated = false;
            if (reverseEdge == null)
            {
                int reverseEdgeId = RememberLearnedTraversalEdge(
                    reverseRawStart,
                    reverseRawEnd,
                    "WalkThrough",
                    requireSameKindForRefresh: true);
                if (reverseEdgeId <= 0 || reverseEdgeId == bestForward.Id)
                {
                    return false;
                }

                reverseEdge = LearnedTraversalEdges.FirstOrDefault(edge => edge != null && edge.Id == reverseEdgeId);
                if (reverseEdge == null)
                {
                    return false;
                }
                reverseSiblingCreated = true;

                // A reverse sibling inherits only the proven geometry description, never the
                // forward edge's verification/experience authority. Its corridor is a reversed
                // copy at creation time; subsequent learning belongs to the sibling itself.
                reverseEdge.SupersedesProvenEdgeId = 0;
                reverseEdge.A = bestForward.B;
                reverseEdge.B = bestForward.A;
                reverseEdge.RawStart = reverseRawStart;
                reverseEdge.RawEnd = reverseRawEnd;
                reverseEdge.HasSettledStart = bestForward.HasSettledEnd;
                reverseEdge.SettledStart = bestForward.SettledEnd;
                reverseEdge.HasSettledEnd = bestForward.HasSettledStart;
                reverseEdge.SettledEnd = bestForward.SettledStart;
                reverseEdge.SettledBreadcrumbSequence = 0;
                reverseEdge.RequiredPose=bestForward.RequiredPose;
                reverseEdge.WalkThroughCorridorSamples = bestForward.WalkThroughCorridorSamples != null
                    ? bestForward.WalkThroughCorridorSamples.Where(IsFinite).Reverse().ToList()
                    : new List<Vector3>();
                reverseEdge.ExperienceKey = null;
                reverseEdge.Verified = false;
                reverseEdge.SuccessfulExecutions = 0;
                reverseEdge.NativeSuccessCount = 0;
                reverseEdge.AssistedSuccessCount = 0;
                reverseEdge.TeleportFallbackCount = 0;
                reverseEdge.FailedExecutions = 0;
                reverseEdge.PlayerValidated = true;
                reverseEdge.Disabled = false;
                SavePersistentTraversalLinks();
            }

            // Ordinary player WT detection gets first authority. If it already registered the
            // same directional sibling for this crossing, V3.14 must not manufacture a duplicate.
            bool alreadyRegistered = TraversalEpisodeStream.Any(item => item != null &&
                item.EdgeId == reverseEdge.Id &&
                item.EndBreadcrumbSequence >= bestReverseEntryNode.Sequence);
            if (alreadyRegistered)
            {
                return false;
            }

            TraversalEpisodeMetadata episode = RegisterTraversalEpisodeForEdge(
                reverseEdge.Id,
                "WalkThrough",
                reverseEdge.RawStart,
                reverseEdge.RawEnd,
                bestReverseEntryNode.Sequence,
                current.Sequence,
                allowChain: true);
            if (episode == null)
            {
                return false;
            }

            Vector3 selectedReverseAxis = bestForward.RawStart - bestForward.RawEnd;
            selectedReverseAxis.y = 0f;
            float selectedReverseSpan = selectedReverseAxis.magnitude;
            Vector3 selectedReverseDirection = selectedReverseSpan > 0.0001f
                ? selectedReverseAxis / selectedReverseSpan
                : Vector3.zero;
            Vector3 selectedStartOffset = bestReverseEntryNode.Position - bestForward.RawEnd;
            selectedStartOffset.y = 0f;
            Vector3 selectedEndOffset = current.Position - bestForward.RawEnd;
            selectedEndOffset.y = 0f;
            float selectedStartProjection = Vector3.Dot(selectedStartOffset, selectedReverseDirection);
            float selectedEndProjection = Vector3.Dot(selectedEndOffset, selectedReverseDirection);

            WriteEvent("learningV314ReverseKnownWalkThroughRouteFactCaptured", null, new
            {
                provenForwardEdgeId = bestForward.Id,
                reverseEdgeId = reverseEdge.Id,
                reverseSiblingCreated,
                reverseSiblingNativeProven = IsLearningV3NativeProvenEdge(reverseEdge),
                forwardNativeSuccesses = bestForward.NativeSuccessCount,
                startBreadcrumbSequence = bestReverseEntryNode.Sequence,
                endBreadcrumbSequence = current.Sequence,
                observedStart = Vec(bestReverseEntryNode.Position),
                observedEnd = Vec(current.Position),
                reverseEntry = Vec(reverseEdge.RawStart),
                reverseExit = Vec(reverseEdge.RawEnd),
                entryDistance = bestReverseEntryDistance,
                exitDistance = bestReverseExitDistance,
                reverseSpan = selectedReverseSpan,
                startProjection = selectedStartProjection,
                endProjection = selectedEndProjection,
                crossingBoundaryAuthority = ("preExitPlane"),
                forwardAuthorityChanged = false,
                routeConsumer = "existingFollowerRouteMission"
            });
            WriteEvent("learningV315ReverseWalkThroughCrossingBoundaryAuthorityApplied", null, new
            {
                provenForwardEdgeId = bestForward.Id,
                reverseEdgeId = reverseEdge.Id,
                startBreadcrumbSequence = bestReverseEntryNode.Sequence,
                endBreadcrumbSequence = current.Sequence,
                reverseSpan = selectedReverseSpan,
                startProjection = selectedStartProjection,
                endProjection = selectedEndProjection,
                entryBoundary = "preExitPlane",
                exitBoundary = "farSidePlanePlusExistingSlack",
                farSideSlack = KnownWalkThroughPortalFarSideProjectionSlack,
                routeConsumer = "existingFollowerRouteMission"
            });
            return true;
        }

        /// <summary>
        /// V1.3.11 multi-edge hybrid route planner. NavMesh islands and learned traversal
        /// endpoints form a small graph. Dijkstra selects a complete route and returns the first
        /// traversal bridge to execute; after crossing it, callers re-plan from the new island.
        /// </summary>
        public static bool TryGetHybridTraversalBridgeTarget(
            BotOwner bot,
            Vector3 destination,
            out Vector3 target,
            out bool probeStarted,
            out int edgeId)
        {
            target = default;
            probeStarted = false;
            edgeId = 0;

            if (!raidActive || !IsLiveBot(bot) ||
                (!BossPlayers.IsFollower(bot) && !FollowerEvacuationRuntime.IsDeathEvacuating(bot)) ||
                !IsFinite(bot.Position) || !IsFinite(destination))
            {
                return false;
            }

            PruneLearnedTraversalEdges();
            string profileId = bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) &&
                TryUseLearnedTraversalCommitment(bot, destination, out target, out probeStarted, out edgeId))
            {
                return true;
            }

            if (!TryBuildHybridRoutePlan(bot.Position, destination, out HybridRoutePlan plan) ||
                plan == null || plan.FirstTraversalEdgeId <= 0)
            {
                return false;
            }

            LearnedTraversalEdge plannedEdge = LearnedTraversalEdges.FirstOrDefault(edge => edge.Id == plan.FirstTraversalEdgeId);
            if (!IsTraversalEdgeTopologicallySelectableForFollower(bot, plannedEdge, out string hybridEligibilityReason))
            {
                WriteEvent("hybridTraversalRouteSuppressed", bot, new
                {
                    edgeId = plan.FirstTraversalEdgeId,
                    kind = plannedEdge?.Kind,
                    reason = hybridEligibilityReason
                });
                return false;
            }
            if (plannedEdge != null && IsRecentTraversalRelatchBlocked(bot, plannedEdge, out RecentTraversalCompletion recentCompletion))
            {
                WriteEvent("hybridTraversalRelatchBlocked", bot, new
                {
                    edgeId = plannedEdge.Id,
                    kind = plannedEdge.Kind,
                    secondsRemaining = Mathf.Max(0f, recentCompletion.ExpiresAt - Time.time),
                    playerTraversalSequence = plannedEdge.PlayerTraversalSequence
                });
                return false;
            }

            target = plan.FirstTraversalEntry;
            edgeId = plan.FirstTraversalEdgeId;
            if (!string.IsNullOrEmpty(profileId))
            {
                LearnedTraversalCommitments[profileId] = CreateLearnedTraversalCommitment(
                    plannedEdge,
                    plan.FirstTraversalEntry,
                    plan.FirstTraversalExit,
                    plan.FirstRawEntry,
                    plan.FirstRawExit);
            }

            float entryDistance = Vector3.Distance(bot.Position, plan.FirstTraversalEntry);
            WriteEvent("hybridTraversalRouteLatched", bot, new
            {
                edgeId,
                kind = plan.FirstTraversalKind,
                entry = Vec(plan.FirstTraversalEntry),
                exit = Vec(plan.FirstTraversalExit),
                destination = Vec(destination),
                totalCost = plan.TotalCost,
                traversalCount = plan.TraversalCount,
                entryDistance
            });

            if (!ShouldArmLearnedTraversalProbe(bot, plan.FirstTraversalKind, entryDistance, plan.FirstTraversalEntry, plan.FirstRawExit) || HasActiveTraversalProbe(bot))
            {
                return true;
            }

            string retryKey = profileId + ":" + edgeId.ToString(CultureInfo.InvariantCulture);
            if (LearnedTraversalRetryAfter.TryGetValue(retryKey, out float retryAt) && Time.time < retryAt)
            {
                return true;
            }

            Vector3 direction = GetFlatDirection(
                (IsFinite(plan.FirstRawExit) ? plan.FirstRawExit : plan.FirstTraversalExit) -
                (IsFinite(plan.FirstRawEntry) ? plan.FirstRawEntry : plan.FirstTraversalEntry));
            if (TryStartProbeForBot(
                    bot,
                    direction,
                    "hybridTraversalGraph",
                    edgeId,
                    plan.FirstTraversalKind,
                    "hybridTraversalGraph",
                    out string startMessage))
            {
                LearnedTraversalRetryAfter[retryKey] = Time.time + LearnedTraversalRetryCooldown;
                probeStarted = true;
                WriteEvent("hybridTraversalBridgeProbeStarted", bot, new
                {
                    edgeId,
                    kind = plan.FirstTraversalKind,
                    message = startMessage,
                    traversalCount = plan.TraversalCount
                });
            }

            return true;
        }

        public static bool TryEstimateHybridRoute(
            Vector3 start,
            Vector3 end,
            out float pathLength,
            out int traversalEdgeId)
        {
            pathLength = 0f;
            traversalEdgeId = 0;
            if (!raidActive || !IsFinite(start) || !IsFinite(end))
            {
                return false;
            }

            StrictPathResult direct = CalculateStrictPath(start, end);
            if (direct.StrictComplete)
            {
                pathLength = direct.PathLength;
                return true;
            }

            PruneLearnedTraversalEdges();
            if (!TryBuildHybridRoutePlan(start, end, out HybridRoutePlan plan) || plan == null)
            {
                return false;
            }

            pathLength = plan.TotalCost;
            traversalEdgeId = plan.FirstTraversalEdgeId;
            return traversalEdgeId > 0;
        }

        private static bool TryBuildHybridRoutePlan(Vector3 start, Vector3 end, out HybridRoutePlan plan)
        {
            plan = null;
            if (LearnedTraversalEdges.Count == 0)
            {
                return false;
            }

            List<HybridRouteNode> nodes = new List<HybridRouteNode>
            {
                new HybridRouteNode { Position = start },
                new HybridRouteNode { Position = end }
            };

            Dictionary<int, int> aNodeByEdge = new Dictionary<int, int>();
            Dictionary<int, int> bNodeByEdge = new Dictionary<int, int>();
            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (edge == null || edge.Disabled ||
                    TryGetLearningV31AuthoritativeProvenParent(edge, out _))
                {
                    continue;
                }
                if (!IsFinite(edge.A) || !IsFinite(edge.B))
                {
                    continue;
                }

                aNodeByEdge[edge.Id] = nodes.Count;
                nodes.Add(new HybridRouteNode { Position = edge.A, EdgeId = edge.Id, IsA = true });
                bNodeByEdge[edge.Id] = nodes.Count;
                nodes.Add(new HybridRouteNode { Position = edge.B, EdgeId = edge.Id, IsA = false });
            }

            if (nodes.Count <= 2)
            {
                return false;
            }

            List<HybridRouteArc>[] arcs = new List<HybridRouteArc>[nodes.Count];
            for (int i = 0; i < arcs.Length; i++)
            {
                arcs[i] = new List<HybridRouteArc>();
            }

            // NavMesh arcs are bidirectional only when strict pathing succeeds from the source.
            // Keep this graph local to route planning; learned-edge counts are normally small.
            for (int i = 0; i < nodes.Count; i++)
            {
                for (int j = i + 1; j < nodes.Count; j++)
                {
                    StrictPathResult ij = CalculateStrictPath(nodes[i].Position, nodes[j].Position);
                    if (ij.StrictComplete)
                    {
                        arcs[i].Add(new HybridRouteArc { To = j, Cost = Mathf.Max(0.01f, ij.PathLength) });
                    }

                    StrictPathResult ji = CalculateStrictPath(nodes[j].Position, nodes[i].Position);
                    if (ji.StrictComplete)
                    {
                        arcs[j].Add(new HybridRouteArc { To = i, Cost = Mathf.Max(0.01f, ji.PathLength) });
                    }
                }
            }

            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (edge == null || edge.Disabled ||
                    TryGetLearningV31AuthoritativeProvenParent(edge, out _))
                {
                    continue;
                }
                if (!aNodeByEdge.TryGetValue(edge.Id, out int a) || !bNodeByEdge.TryGetValue(edge.Id, out int b))
                {
                    continue;
                }

                float traversalCost = Mathf.Max(0.35f, Vector3.Distance(
                    IsFinite(edge.RawStart) ? edge.RawStart : edge.A,
                    IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B));
                if (IsTraversalOrientationAllowed(edge, edge.A, edge.B))
                {
                    arcs[a].Add(CreateTraversalArc(
                        b, edge, edge.A, edge.B, edge.RawStart, edge.RawEnd,
                        traversalCost + GetTraversalSemanticSelectionAdjustment(edge, edge.A, edge.B)));
                }
                if (IsTraversalOrientationAllowed(edge, edge.B, edge.A))
                {
                    arcs[b].Add(CreateTraversalArc(
                        a, edge, edge.B, edge.A, edge.RawEnd, edge.RawStart,
                        traversalCost + GetTraversalSemanticSelectionAdjustment(edge, edge.B, edge.A)));
                }
            }

            float[] dist = Enumerable.Repeat(float.MaxValue, nodes.Count).ToArray();
            bool[] visited = new bool[nodes.Count];
            int[] previous = Enumerable.Repeat(-1, nodes.Count).ToArray();
            HybridRouteArc[] previousArc = new HybridRouteArc[nodes.Count];
            dist[0] = 0f;

            for (int step = 0; step < nodes.Count; step++)
            {
                int current = -1;
                float currentDistance = float.MaxValue;
                for (int i = 0; i < nodes.Count; i++)
                {
                    if (!visited[i] && dist[i] < currentDistance)
                    {
                        current = i;
                        currentDistance = dist[i];
                    }
                }

                if (current < 0 || current == 1)
                {
                    break;
                }

                visited[current] = true;
                foreach (HybridRouteArc arc in arcs[current])
                {
                    float next = currentDistance + Mathf.Max(0.01f, arc.Cost);
                    if (next + 0.001f >= dist[arc.To])
                    {
                        continue;
                    }

                    dist[arc.To] = next;
                    previous[arc.To] = current;
                    previousArc[arc.To] = arc;
                }
            }

            if (!IsFinite(dist[1]) || dist[1] == float.MaxValue || previous[1] < 0)
            {
                return false;
            }

            List<HybridRouteArc> route = new List<HybridRouteArc>();
            int cursor = 1;
            int guard = nodes.Count + 4;
            while (cursor != 0 && cursor >= 0 && guard-- > 0)
            {
                HybridRouteArc arc = previousArc[cursor];
                if (arc == null)
                {
                    return false;
                }
                route.Add(arc);
                cursor = previous[cursor];
            }
            route.Reverse();

            HybridRouteArc firstTraversal = route.FirstOrDefault(arc => arc.TraversalEdgeId > 0);
            if (firstTraversal == null)
            {
                return false;
            }

            plan = new HybridRoutePlan
            {
                TotalCost = dist[1],
                TraversalCount = route.Count(arc => arc.TraversalEdgeId > 0),
                FirstTraversalEdgeId = firstTraversal.TraversalEdgeId,
                FirstTraversalKind = firstTraversal.TraversalKind,
                FirstTraversalEntry = firstTraversal.Entry,
                FirstTraversalExit = firstTraversal.Exit,
                FirstRawEntry = firstTraversal.RawEntry,
                FirstRawExit = firstTraversal.RawExit
            };
            return true;
        }

        private static HybridRouteArc CreateTraversalArc(
            int to,
            LearnedTraversalEdge edge,
            Vector3 entry,
            Vector3 exit,
            Vector3 rawEntry,
            Vector3 rawExit,
            float cost)
        {
            return new HybridRouteArc
            {
                To = to,
                Cost = cost,
                TraversalEdgeId = edge.Id,
                TraversalKind = edge.Kind,
                Entry = entry,
                Exit = exit,
                RawEntry = rawEntry,
                RawExit = rawExit
            };
        }

        private static bool TryStartEmpiricalLocalEntryBridge(
            BotOwner bot,
            LearnedTraversalCommitment commitment,
            float entryDistance,
            out string message,
            bool nativeWalkThroughFrontierReady = false,
            bool freshTraversalFrontierReady = false)
        {
            message = string.Empty;
            bool traversalAdjacent = commitment != null &&
                (((commitment.TraversalAdjacentSuccessor || commitment.ChainLocalExecutable))) &&
                entryDistance <= RouteMissionTraversalAdjacentBridgeMaxDistance;
            bool empiricalRejectReady = commitment != null &&
                commitment.ApproachPathFailures >= RouteMissionLocalEntryBridgeRejectCount &&
                entryDistance <= RouteMissionLocalEntryBridgeMaxDistance;
            bool acceptedPathNoMoverReady = commitment != null &&
                commitment.ApproachMoverCommitFailures >= RouteMissionAcceptedPathNoMoverBridgeCount &&
                entryDistance <= RouteMissionLocalEntryBridgeMaxDistance;
            bool learningV340WalkThroughFrontierReady =
                (nativeWalkThroughFrontierReady) && commitment != null &&
                string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                entryDistance <= RouteMissionTraversalAdjacentBridgeMaxDistance;
            bool learningV341FreshTraversalFrontierReady =
                (freshTraversalFrontierReady) && commitment != null &&
                entryDistance <= RouteMissionTraversalAdjacentBridgeMaxDistance;
            if (bot == null || commitment == null ||
                commitment.RouteMissionId <= 0 ||
                (!traversalAdjacent && !empiricalRejectReady && !acceptedPathNoMoverReady &&
                 !learningV340WalkThroughFrontierReady && !learningV341FreshTraversalFrontierReady) ||
                HasActiveTraversalProbe(bot))
            {
                return false;
            }

            bool supportedKind =
                FollowerCapabilityHelperRules.TryStartEmpiricalLocalEntryBridge_supportedKind_84EF7147_1(commitment.Kind,commitment.Kind,commitment.Kind,commitment.Kind,learningV340WalkThroughFrontierReady,learningV341FreshTraversalFrontierReady,commitment.Kind);
            if (!supportedKind)
            {
                return false;
            }

            bool learningV437PreciseBarrierEntryKind =
                string.Equals(commitment.Kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(commitment.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
            if ((traversalAdjacent) &&
                learningV437PreciseBarrierEntryKind && entryDistance > RouteMissionLocalEntryBridgeMaxDistance)
            {
                WriteEvent("learningV437TraversalAdjacentActuatorDeferredToEntryLane", bot, new
                {
                    missionId = commitment.RouteMissionId,
                    stepIndex = commitment.RouteMissionStepIndex,
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    entryDistance,
                    localBridgeMaxDistance = RouteMissionLocalEntryBridgeMaxDistance,
                    traversalAdjacentMaxDistance = RouteMissionTraversalAdjacentBridgeMaxDistance,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "farTraversalAdjacentBarrierCannotBypassDataDrivenV363EntryLaneProducer"
                });
                return false;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 direction = GetFlatDirection(rawExit - rawEntry);
            if (direction.sqrMagnitude < 0.5f)
            {
                message = "empirical local entry bridge has no authored direction";
                return false;
            }

            if ((string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
            {
                Vector3 learningV437EntryDelta = bot.Position - rawEntry;
                learningV437EntryDelta.y = 0f;
                float learningV437EntryProjection = Vector3.Dot(learningV437EntryDelta, direction);
                if (learningV437EntryProjection > LearningV352JumpTakeoffCorridorMaxForwardOvershoot)
                {
                    bool learningV446PrimaryRetired = false;
                    if ((TryGetActiveFollowerRouteMission(bot, out FollowerRouteMission learningV446FrontierMission)) &&
                        learningV446FrontierMission != null && learningV446FrontierMission.Steps != null &&
                        learningV446FrontierMission.CurrentStepIndex >= 0 &&
                        learningV446FrontierMission.CurrentStepIndex < learningV446FrontierMission.Steps.Count)
                    {
                        FollowerRouteMissionStep learningV446FrontierStep =
                            learningV446FrontierMission.Steps[learningV446FrontierMission.CurrentStepIndex];
                        learningV446PrimaryRetired = learningV446FrontierStep != null &&
                            IsLearningV446PhysicalStrategyRetiredForCurrentStep(
                                learningV446FrontierMission, learningV446FrontierStep, commitment.Kind);
                    }

                    if (learningV446PrimaryRetired)
                    {
                        WriteEvent("learningV446RetiredJumpAllowsNonPrimaryConsumerPastTakeoffFrontier", bot, new
                        {
                            missionId = commitment.RouteMissionId,
                            stepIndex = commitment.RouteMissionStepIndex,
                            edgeId = commitment.EdgeId,
                            kind = commitment.Kind,
                            entryDistance,
                            forwardEntryProjection = learningV437EntryProjection,
                            maxForwardOvershoot = LearningV352JumpTakeoffCorridorMaxForwardOvershoot,
                            semanticDebtPreserved = true,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = "doNotRewindForRetiredNativeJumpAllowStrategySelectorToStartAssistFromCurrentBody"
                        });
                    }
                    else
                    {
                        string learningV437TransferSource = string.Empty;
                        bool learningV437SubstituteSelected =
                            TryGetActiveFollowerRouteMission(bot, out FollowerRouteMission learningV437Mission) &&
                            learningV437Mission != null &&
                            TryBeginLearningV433EquivalentPhysicalActuatorFrontierRecovery(
                                bot,
                                "learningV437LocalBridgeMissedJumpTakeoffFrontierSamePortalSubstitution",
                                out learningV437TransferSource);
                        WriteEvent("learningV437JumpLocalEntryBridgeRejectedPastTakeoffFrontier", bot, new
                        {
                            missionId = commitment.RouteMissionId,
                            stepIndex = commitment.RouteMissionStepIndex,
                            edgeId = commitment.EdgeId,
                            kind = commitment.Kind,
                            entryDistance,
                            forwardEntryProjection = learningV437EntryProjection,
                            maxForwardOvershoot = LearningV352JumpTakeoffCorridorMaxForwardOvershoot,
                            substituteSelected = learningV437SubstituteSelected,
                            transferSource = learningV437TransferSource ?? string.Empty,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = "pastTakeoffPlaneCannotStartJumpProbeFromRestOrRewindSamePortalFallbackOwnsRecoveryWhenAvailable"
                        });
                        return false;
                    }
                }
            }

            if (string.Equals(commitment.Kind, "Climb", StringComparison.OrdinalIgnoreCase))
            {
                // CF13: a Climb probe is a Native actuator consumer, not an entry-
                // seeking navigation producer. Until the actual V424 envelope is
                // satisfied, the CF12 route mission/physical lane retains its target
                // and movement ownership. The admission helper also issues the
                // bounded native sprint-release request once the physical body aligns.
                if (!TryGetActiveFollowerRouteMission(bot, out FollowerRouteMission cf13Mission) ||
                    cf13Mission == null || cf13Mission.MissionId != commitment.RouteMissionId ||
                    cf13Mission.Steps == null ||
                    commitment.RouteMissionStepIndex < 0 ||
                    commitment.RouteMissionStepIndex >= cf13Mission.Steps.Count ||
                    cf13Mission.Steps[commitment.RouteMissionStepIndex]?.EdgeId != commitment.EdgeId ||
                    !TryGetLearningV424ActuatorExecutorAdmission(
                        bot, cf13Mission.Steps[commitment.RouteMissionStepIndex],
                        out bool cf13ExecutorReady, out _, out _, out _, out _, out _,
                        out _, out _, out _, out _, out _) || !cf13ExecutorReady)
                    return false;
            }

            string bridgeSource = learningV341FreshTraversalFrontierReady
                ? "learningV341FreshTraversalPartialFrontierBridge"
                : (learningV340WalkThroughFrontierReady
                    ? "learningV340NativeProvenWalkThroughFrontierBridge"
                    : (traversalAdjacent
                        ? "traversalAdjacentLocalEntryBridge"
                        : (acceptedPathNoMoverReady ? "acceptedPathNoMoverLocalEntryBridge" : "empiricalLocalEntryBridge")));
            bool started = TryStartProbeForBot(
                bot,
                direction,
                bridgeSource,
                commitment.EdgeId,
                commitment.Kind,
                bridgeSource,
                out message);
            if (started)
            {
                commitment.NextApproachPathAttemptAt = 0f;
                commitment.ApproachMoverCommitFailures = 0;
                commitment.LastApproachMoverCommitFailureAt = 0f;
                commitment.ExpiresAt = Mathf.Max(
                    commitment.ExpiresAt,
                    Time.time + RouteMissionTraversalCommitmentSeconds);
                LearnedTraversalCommitments[bot.ProfileId ?? string.Empty] = commitment;

                int localRecoveryAttempts = 0;
                if (FollowerRouteMissions.TryGetValue(bot.ProfileId ?? string.Empty, out FollowerRouteMission mission) &&
                    mission != null && mission.MissionId == commitment.RouteMissionId)
                {
                    if (Time.time >= mission.NextLocalRecoveryCountAt)
                    {
                        mission.LocalRecoveryAttempts++;
                        mission.NextLocalRecoveryCountAt = Time.time + RouteMissionLocalRecoveryCountInterval;
                    }
                    localRecoveryAttempts = mission.LocalRecoveryAttempts;
                }

                WriteEvent("routeMissionTraversalLocalEntryBridgeStarted", bot, new
                {
                    missionId = commitment.RouteMissionId,
                    stepIndex = commitment.RouteMissionStepIndex,
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    entry = Vec(commitment.Entry),
                    rawEntry = Vec(rawEntry),
                    rawExit = Vec(rawExit),
                    entryDistance,
                    approachPathFailures = commitment.ApproachPathFailures,
                    localRecoveryAttempts,
                    source = traversalAdjacent
                        ? "traversalAdjacentAnchor"
                        : (acceptedPathNoMoverReady ? "acceptedPathWithoutMoverCommit" : "empiricalPriorityPathReject")
                });
            }
            return started;
        }

        // CompileFix24: stale GrenadeHandsController is an equipment-authority blocker, not
        // evidence that a traversal Entry is unreachable. Hold progress clocks while bounded hands
        // recovery runs and never penalize/quarantine the learned edge for this condition.
        private static bool TryHoldTraversalForGrenadeHandsRecovery(
            BotOwner bot,
            LearnedTraversalCommitment commitment,
            FollowerRouteMission routeMission,
            float entryDistance,
            float exitDistance,
            out bool releasedToFollow)
        {
            releasedToFollow = false;
            Player player = bot?.GetPlayer;
            if (player == null || !(player.HandsController is Player.GrenadeHandsController))
            {
                if (commitment != null)
                {
                    commitment.GrenadeHandsBlockedSince = 0f;
                    commitment.NextGrenadeHandsRecoveryAt = 0f;
                    commitment.GrenadeHandsRecoveryAttempts = 0;
                }
                return false;
            }

            BotGrenadeController grenades = bot.WeaponManager?.Grenades;
            bool grenadeControllerActive = grenades?.ThrowindNow == true || grenades?.ReadyToThrow == true;
            bool activeGrenadeTransaction =
                FollowerGrenadeRuntimeGate.IsExplicitThrowActive(bot) ||
                (grenadeControllerActive && !FollowerGrenadeRuntimeGate.IsCurrentTransactionTerminal(bot));
            if (commitment.GrenadeHandsBlockedSince <= 0f)
            {
                commitment.GrenadeHandsBlockedSince = Time.time;
            }

            float blockedFor = Time.time - commitment.GrenadeHandsBlockedSince;
            bool recoveryGuarded = FollowerStateAuthorityCoordinator.IsHandsRecoveryGuarded(bot, out _, out _);

            // Do not immediately re-arm another 3s hands guard once the bounded traversal hold has
            // expired; release the runtime route first so equipment failure cannot monopolize a valid edge.
            if (!activeGrenadeTransaction && !recoveryGuarded && blockedFor >= TraversalGrenadeHandsReleaseSeconds)
            {
                int blockedEdgeId = commitment.EdgeId;
                int missionId = routeMission?.MissionId ?? 0;
                ClearLearnedTraversalCommitment(bot, blockedEdgeId, "grenadeHandsEquipmentBlock");
                if (missionId > 0)
                {
                    RemoveLifecycleMission(bot.ProfileId, "TryHoldTraversalForGrenadeHandsRecovery");
                }
                FollowRejectLeases.Remove(bot.ProfileId);
                WriteEvent("traversalEquipmentBlockReleasedToFollow", bot, new
                {
                    edgeId = blockedEdgeId,
                    kind = commitment.Kind,
                    missionId,
                    blockedFor,
                    recoveryAttempts = commitment.GrenadeHandsRecoveryAttempts,
                    entryDistance,
                    exitDistance
                });
                releasedToFollow = true;
                return true;
            }

            if (!activeGrenadeTransaction && !recoveryGuarded && Time.time >= commitment.NextGrenadeHandsRecoveryAt)
            {
                commitment.GrenadeHandsRecoveryAttempts++;
                commitment.NextGrenadeHandsRecoveryAt = Time.time + TraversalGrenadeHandsRecoveryRetrySeconds;
                FollowerStateAuthorityCoordinator.EnsureGrenadeHandsRecovery(bot, "traversalProbe");
                recoveryGuarded = FollowerStateAuthorityCoordinator.IsHandsRecoveryGuarded(bot, out _, out _);
            }

            commitment.LastEntryProgressAt = Time.time;
            commitment.LastEntryDistance = entryDistance;
            commitment.ExpiresAt = Mathf.Max(commitment.ExpiresAt, Time.time + LearnedTraversalExpiredExtensionSeconds);
            commitment.NextApproachPathAttemptAt = Mathf.Max(
                commitment.NextApproachPathAttemptAt,
                Time.time + TraversalGrenadeHandsHoldRetrySeconds);
            LearnedTraversalCommitments[bot.ProfileId] = commitment;

            if (routeMission != null)
            {
                routeMission.LastProgressAt = Time.time;
                CommitCapabilityMoveRetry(routeMission,FollowerCapabilityRetryPolicy.Change.AttemptOrExplicitHold,Mathf.Max(
                    routeMission.NextMoveAttemptAt,
                    Time.time + TraversalGrenadeHandsHoldRetrySeconds));
            }

            if (ShouldEmitDiagnostic(
                    "traversalGrenadeHandsBlock:" + commitment.EdgeId.ToString(CultureInfo.InvariantCulture),
                    bot,
                    0.75f))
            {
                WriteEvent("traversalEquipmentBlockHold", bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    missionId = routeMission?.MissionId ?? 0,
                    blockedFor,
                    activeGrenadeTransaction,
                    recoveryGuarded,
                    recoveryAttempts = commitment.GrenadeHandsRecoveryAttempts,
                    entryDistance,
                    exitDistance
                });
            }
            return true;
        }

        private static bool TryUseLearnedTraversalCommitment(
            BotOwner bot,
            Vector3 leaderPosition,
            out Vector3 target,
            out bool probeStarted,
            out int edgeId)
        {
            target = default;
            probeStarted = false;
            edgeId = 0;

            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment commitment))
            {
                return false;
            }

            if(RejectCapabilityForeignCommitment(bot,commitment))return false;
            LearnedTraversalEdge commitmentEdge = LearnedTraversalEdges.FirstOrDefault(edge =>
                edge != null && edge.Id == commitment.EdgeId);
            if (commitmentEdge == null)
            {
                ClearLearnedTraversalCommitment(bot, commitment.EdgeId, "edgeMissing");
                return false;
            }

            // CompileFix22: a downward/upward Jump demonstration is directional. Do not fall back to
            // CompatibilityExecutor when a stale/generic route has reversed it; release the owner and
            // let Vault/Climb/normal Follow compete instead.
            // CF44-COMPILEFIX1: initialize the diagnostics even when && short-circuits the out call.
            // No orientation/admission contract, retry, or native-success condition is changed.
            float cf44TailDot = 0f;
            float cf44TailStartProjection = 0f;
            float cf44TailEndProjection = 0f;
            bool cf44AuthoredForward = IsTraversalCommitmentOrientationAllowed(commitmentEdge, commitment);
            bool cf44MonotonicTail = !cf44AuthoredForward &&
                TryCF44AdmitCurrentEpisodeForwardWalkThroughTail(bot, commitmentEdge, commitment,
                    out cf44TailDot, out cf44TailStartProjection, out cf44TailEndProjection);
            if (!cf44AuthoredForward && !cf44MonotonicTail)
            {
                string orientationRetryKey = profileId + ":" + commitment.EdgeId.ToString(CultureInfo.InvariantCulture);
                LearnedTraversalRetryAfter[orientationRetryKey] = Time.time + JumpEntryFailureRetryCooldownSeconds;
                ClearLearnedTraversalCommitment(bot, commitment.EdgeId, "jumpReverseDirectionRejected");
                RemoveLifecycleMission(profileId, "TryUseLearnedTraversalCommitment");
                FollowRejectLeases.Remove(profileId);
                WriteEvent("learnedJumpReverseDirectionRejected", bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    rawEntry = Vec(commitment.RawEntry),
                    rawExit = Vec(commitment.RawExit),
                    authoredRawStart = Vec(commitmentEdge.RawStart),
                    authoredRawEnd = Vec(commitmentEdge.RawEnd),
                    authoredVerticalDelta = commitmentEdge.RawEnd.y - commitmentEdge.RawStart.y,
                    cooldownSeconds = JumpEntryFailureRetryCooldownSeconds
                });
                return false;
