            // V1.3.22 rolling handoff: do not make a running follower finish a tiny GoTo path,
            // settle to Idle, and only then acquire traversal ownership. If the follower is still
            // moving toward the authored entry, arm early enough for the crossing primitive to take
            // over while locomotion is continuous. WalkThrough corridors use a smaller lead because
            // their direct controller motion begins at the projected corridor entry.
            Player player = bot?.GetPlayer;
            Vector3 flatVelocity = player != null ? player.Velocity : Vector3.zero;
            flatVelocity.y = 0f;
            float speed = flatVelocity.magnitude;
            Vector3 toEntry = entry - (player != null ? player.Position : (bot != null ? bot.Position : entry));
            toEntry.y = 0f;
            float forwardDot = speed > 0.05f && toEntry.sqrMagnitude > 0.01f
                ? Vector3.Dot(flatVelocity.normalized, toEntry.normalized)
                : 0f;
            float rollingArmDistance = walkThrough
                ? Mathf.Max(WalkThroughEntryTolerance, 1.55f)
                : (speed >= 4.0f || bot?.Mover?.Sprinting == true
                    ? RollingTraversalSprintArmDistance
                    : RollingTraversalRunArmDistance);
            bool vaultOrClimb =
                string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase);
            bool semanticRollingLaneEligible = true;
            float semanticLaneLateral = 0f;
            float semanticLaneProjection = 0f;
            if (vaultOrClimb && entryDistance > normalArmDistance)
            {
                Vector3 semanticAxis = rawExit - entry;
                semanticAxis.y = 0f;
                float semanticSpan = semanticAxis.magnitude;
                if (semanticSpan >= 0.25f)
                {
                    Vector3 semanticDirection = semanticAxis / semanticSpan;
                    Vector3 bodyDelta = (player != null ? player.Position : bot.Position) - entry;
                    bodyDelta.y = 0f;
                    semanticLaneProjection = Vector3.Dot(bodyDelta, semanticDirection);
                    semanticLaneLateral =
                        (bodyDelta - semanticDirection * semanticLaneProjection).magnitude;
                    float semanticLaneMaxLateral =
                        Mathf.Max(1.10f, InjectedNativeVaultEntryStagingDistance + 0.15f);
                    semanticRollingLaneEligible =
                        semanticLaneProjection <= 0.45f &&
                        semanticLaneLateral <= semanticLaneMaxLateral &&
                        forwardDot >= 0.55f;
                    if (!semanticRollingLaneEligible &&
                        speed >= RollingTraversalMinSpeed &&
                        forwardDot >= RollingTraversalMinForwardDot &&
                        entryDistance <= rollingArmDistance &&
                        ShouldEmitDiagnostic(
                            "rollingTraversalSemanticLaneHandoffDeferred:" +
                                (bot?.ProfileId ?? string.Empty) + ":" + kind,
                            bot,
                            0.35f))
                    {
                        WriteEvent("rollingTraversalSemanticLaneHandoffDeferred", bot, new
                        {
                            kind,
                            entryDistance,
                            speed,
                            forwardDot,
                            semanticLaneProjection,
                            semanticLaneLateral,
                            semanticLaneMaxLateral,
                            entry = Vec(entry),
                            rawExit = Vec(rawExit)
                        });
                    }
                }
            }

            if (speed >= RollingTraversalMinSpeed &&
                forwardDot >= RollingTraversalMinForwardDot &&
                entryDistance <= rollingArmDistance &&
                semanticRollingLaneEligible)
            {
                WriteEvent("traversalRollingHandoffArmed", bot, new
                {
                    kind,
                    entryDistance,
                    speed,
                    forwardDot,
                    semanticLaneProjection,
                    semanticLaneLateral,
                    entry = Vec(entry),
                    rawExit = Vec(rawExit)
                });
                return true;
            }

            // Dead-zone guard: EFT's mover can consider the entry reached around 0.6-0.9m.
            float stoppedArmDistance = walkThrough ? WalkThroughEntryTolerance : 1.35f;
            bool moverStopped = bot?.Mover == null || bot.Mover.HasPathAndNoComplete != true;
            return moverStopped && entryDistance <= stoppedArmDistance;
        }

        private static LearnedTraversalCommitment CreateLearnedTraversalCommitment(
            LearnedTraversalEdge edge,
            Vector3 entry,
            Vector3 exit,
            Vector3 rawEntry,
            Vector3 rawExit,
            int preferredEpisodeId = 0)
        {
            if (edge == null)
            {
                return null;
            }

            bool forward = Vector3.Distance(rawEntry, edge.RawStart) <= Vector3.Distance(rawEntry, edge.RawEnd);
            TraversalEpisodeMetadata episode = preferredEpisodeId > 0
                ? TraversalEpisodeStream.LastOrDefault(item => item != null && item.EpisodeId == preferredEpisodeId)
                : null;
            if (episode == null)
            {
                TraversalEpisodesByEdge.TryGetValue(edge.Id, out episode);
            }

            bool learningV439CurrentEpisodeJumpLandingAuthority = false;
            TraversalEpisodeMetadata learningV439ImmediateSuccessor = null;
            float learningV439SuccessorGap = float.MaxValue;
            if ((preferredEpisodeId > 0) && episode != null && episode.EpisodeId == preferredEpisodeId &&
                string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                episode.ChainId > 0 &&
                IsFinite(episode.RawStart) && IsFinite(episode.RawEnd) &&
                TryGetNextTraversalEpisode(episode.EpisodeId, out learningV439ImmediateSuccessor) &&
                learningV439ImmediateSuccessor != null &&
                IsImmediateTraversalChainSuccessor(
                    episode, learningV439ImmediateSuccessor,
                    out _, out learningV439SuccessorGap) &&
                IsFinite(learningV439ImmediateSuccessor.RawStart))
            {
                Vector3 persistentDirection = GetFlatDirection(edge.RawEnd - edge.RawStart);
                Vector3 episodeDirection = GetFlatDirection(episode.RawEnd - episode.RawStart);
                bool directionCompatible =
                    persistentDirection.sqrMagnitude < 0.5f ||
                    episodeDirection.sqrMagnitude < 0.5f ||
                    Vector3.Dot(persistentDirection, episodeDirection) >= LearningV2RevisionMinDirectionDot;
                learningV439CurrentEpisodeJumpLandingAuthority =
                    directionCompatible &&
                    GetPlanarDistance(episode.RawEnd, learningV439ImmediateSuccessor.RawStart) <=
                        TraversalChainImmediateMaxSpatialGap;
            }

            // Preserve the proven actuator/takeoff geometry first. V4.39 only replaces the live
            // landing frontier below; it never lets one fresh player endpoint erase a proven Jump
            // run-up, direction or obstacle identity.
            if ((string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase)) &&
                IsLearningV3NativeProvenEdge(edge))
            {
                if (!forward && !IsTraversalOrientationAllowed(edge, edge.B, edge.A))
                {
                    forward = true;
                }
                Vector3 requestedRawEntry = rawEntry;
                Vector3 requestedRawExit = rawExit;
                rawEntry = forward ? edge.RawStart : edge.RawEnd;
                rawExit = forward ? edge.RawEnd : edge.RawStart;
                entry = forward ? edge.A : edge.B;
                exit = forward ? edge.B : edge.A;
                if (GetPlanarDistance(requestedRawEntry, rawEntry) > 0.05f ||
                    GetPlanarDistance(requestedRawExit, rawExit) > 0.05f)
                {
                    WriteEvent("learningV332NativeProvenJumpCommitmentGeometryCorrected", null, new
                    {
                        edgeId = edge.Id,
                        requestedRawEntry = Vec(requestedRawEntry),
                        requestedRawExit = Vec(requestedRawExit),
                        rawEntry = Vec(rawEntry),
                        rawExit = Vec(rawExit),
                        action = "nativeProvenTakeoffAndDefaultLandingGeometryOutrankFreshEpisodeUntilLiveSuccessorFrontierIsProven"
                    });
                }
            }

            Vector3 learningV442JumpTakeoffFrontier = default;
            float learningV442JumpTakeoffLayerDelta = 0f;
            float learningV442JumpSpanRatio = 0f;
            float learningV442JumpDirectionDot = -1f;
            float learningV442JumpVerticalDeltaError = float.PositiveInfinity;
            bool learningV442CurrentEpisodeJumpTakeoffFrontier =
                (preferredEpisodeId > 0 && episode != null && episode.EpisodeId == preferredEpisodeId) &&
                string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                IsLearningV3NativeProvenEdge(edge) &&
                TryResolveLearningV442CurrentEpisodeJumpTakeoffFrontier(
                    episode, rawEntry, rawExit,
                    out learningV442JumpTakeoffFrontier,
                    out learningV442JumpTakeoffLayerDelta,
                    out learningV442JumpSpanRatio,
                    out learningV442JumpDirectionDot,
                    out learningV442JumpVerticalDeltaError);
            if (learningV442CurrentEpisodeJumpTakeoffFrontier &&
                ShouldEmitDiagnostic(
                    "learningV442CommitmentCurrentEpisodeJumpTakeoffFrontier:" +
                    edge.Id.ToString(CultureInfo.InvariantCulture), null, 0.15f))
            {
                WriteEvent("learningV442CommitmentCurrentEpisodeJumpTakeoffFrontier", null, new
                {
                    edgeId = edge.Id,
                    episodeId = episode.EpisodeId,
                    chainId = episode.ChainId,
                    persistentRawEntry = Vec(rawEntry),
                    persistentRawExit = Vec(rawExit),
                    runtimeTakeoffFrontier = Vec(learningV442JumpTakeoffFrontier),
                    takeoffLayerDelta = learningV442JumpTakeoffLayerDelta,
                    materialLayerThreshold = LearningV332NativeGroundMoverStartMaxVerticalRebase,
                    spanRatio = learningV442JumpSpanRatio,
                    directionDot = learningV442JumpDirectionDot,
                    verticalDeltaError = learningV442JumpVerticalDeltaError,
                    persistentLearningChanged = false,
                    traversalSuccessRecorded = false,
                    bodyRelocated = false
                });
            }

            if (learningV439CurrentEpisodeJumpLandingAuthority)
            {
                Vector3 persistentLanding = rawExit;
                rawExit = episode.RawEnd;
                exit = rawExit;
                WriteEvent("learningV439CurrentEpisodeJumpLandingFrontierAuthority", null, new
                {
                    edgeId = edge.Id,
                    episodeId = episode.EpisodeId,
                    chainId = episode.ChainId,
                    successorEpisodeId = learningV439ImmediateSuccessor?.EpisodeId ?? 0,
                    successorEdgeId = learningV439ImmediateSuccessor?.EdgeId ?? 0,
                    successorKind = learningV439ImmediateSuccessor?.Kind ?? string.Empty,
                    preservedTakeoffRawEntry = Vec(rawEntry),
                    liveRawExit = Vec(rawExit),
                    persistentLanding = Vec(persistentLanding),
                    successorRawEntry = learningV439ImmediateSuccessor != null
                        ? (object)Vec(learningV439ImmediateSuccessor.RawStart)
                        : null,
                    successorGap = learningV439SuccessorGap,
                    persistentLearningChanged = false,
                    traversalSuccessRecorded = false,
                    action = "nativeProvenTakeoffRemainsAuthoritativeCurrentEpisodeImmediateSuccessorOwnsOnlyLiveLandingFrontier"
                });
            }

            bool hasSettledEntry = forward ? edge.HasSettledStart : edge.HasSettledEnd;
            Vector3 settledEntry = forward ? edge.SettledStart : edge.SettledEnd;
            bool hasSettledExit = forward ? edge.HasSettledEnd : edge.HasSettledStart;
            Vector3 settledExit = forward ? edge.SettledEnd : edge.SettledStart;
            if (learningV439CurrentEpisodeJumpLandingAuthority)
            {
                // A persistent settled exit beyond the freshly demonstrated DropDown entry would
                // reintroduce exactly the stale landing authority this version is retiring.
                hasSettledExit = false;
                settledExit = rawExit;
            }

            return new LearnedTraversalCommitment
            {
                EdgeId = edge.Id,
                EpisodeId = episode?.EpisodeId ?? 0,
                ChainId = episode?.ChainId ?? 0,
                Entry = entry,
                Exit = exit,
                RawEntry = rawEntry,
                RawExit = rawExit,
                HasSettledEntry = hasSettledEntry,
                SettledEntry = settledEntry,
                HasSettledExit = hasSettledExit,
                SettledExit = settledExit,
                Kind = edge.Kind,
                LearningV442HasCurrentEpisodeJumpTakeoffFrontier = learningV442CurrentEpisodeJumpTakeoffFrontier,
                LearningV442CurrentEpisodeJumpTakeoffFrontier = learningV442CurrentEpisodeJumpTakeoffFrontier
                    ? learningV442JumpTakeoffFrontier : default,
                ExpiresAt = Time.time + LearnedTraversalCommitmentSeconds
            };
        }

        private static bool TryTeleportMissedLearnedTraversal(
            BotOwner bot,
            LearnedTraversalCommitment commitment,
            string source,
            float entryDistance,
            float exitDistance,
            float noEntryProgress)
        {
            if (!IsLiveBot(bot) || commitment == null || HasActiveTraversalProbe(bot))
            {
                return false;
            }

            if(HandleCapabilityRecordedTeleportFailure(bot,commitment,source))return false;
            Player player = bot.GetPlayer;
            Vector3 flatVelocity = player != null ? player.Velocity : Vector3.zero;
            flatVelocity.y = 0f;
            bool moverBlocked = bot.Mover?.Blocked == true;
            bool moverStopped = bot.Mover == null || bot.Mover.HasPathAndNoComplete != true;
            bool locomotionFaulted = FollowerStateAuthorityCoordinator.IsLocomotionFaulted(
                bot, out float locomotionFaultRemaining, out string locomotionFaultReason);
            // CompileFix51: state poisoning (notably a persistent JumpLanding) is a hard-stuck
            // condition even when the body is only centimetres from the traversal entry or stale
            // velocity values make it appear to be moving.
            bool hardStuck = locomotionFaulted ||
                             (noEntryProgress >= TraversalHardStuckSeconds &&
                              flatVelocity.magnitude <= TraversalHardStuckVelocity &&
                              (moverBlocked || moverStopped));
            if (!hardStuck)
            {
                WriteEvent("missedTraversalTeleportSuppressedNotStuck", bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    source,
                    entryDistance,
                    exitDistance,
                    noEntryProgress,
                    velocity = flatVelocity.magnitude,
                    moverBlocked,
                    moverStopped,
                    locomotionFaulted,
                    locomotionFaultRemaining,
                    locomotionFaultReason
                });
                return false;
            }

            Vector3 requestedExit = commitment.HasSettledExit && IsFinite(commitment.SettledExit) &&
                                    IsCredibleSettledExit(commitment.Kind, commitment.RawEntry, commitment.RawExit, commitment.SettledExit)
                ? commitment.SettledExit
                : (IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit);
            if (!IsFinite(requestedExit))
            {
                return false;
            }

            Vector3 from = bot.Position;
            string fallbackMode = "validatedFarSideFan";
            long missedTeleportOrigin = PrepareForAutomaticRecoveryTeleport(
                bot, "missedTraversal:" + commitment.EdgeId + ":" + source);
            if (missedTeleportOrigin <= 0)
            {
                return false;
            }
            bool teleported = FollowerSafeTeleport.TryTeleportAcrossTraversalExit(
                bot,
                requestedExit,
                $"missedTraversal:{commitment.EdgeId}:{source}",
                out Vector3 crossedTo,
                issuedTeleportGeneration: missedTeleportOrigin);

            if (!teleported)
            {
                WriteEvent("missedTraversalExitTeleportRejected", bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    source,
                    from = Vec(from),
                    requestedExit = Vec(requestedExit),
                    entryDistance,
                    exitDistance,
                    noEntryProgress
                });
                return false;
            }

            NotifyAutomaticRecoveryTeleportCompleted(
                bot,
                $"missedTraversal:{commitment.EdgeId}:{source}");
            if (!FollowerMovementWriterAuthority.TransitionTeleportToFollowExact(
                bot, missedTeleportOrigin, "missedTraversalTeleportCommitted"))
            {
                WriteEvent("v2TeleportRetirementOriginRejected", bot, new
                {
                    source = "missedTraversal",
                    originGeneration = missedTeleportOrigin,
                    edgeId = commitment.EdgeId,
                    action = "rejectStaleMissedTraversalVerifyOwner"
                });
                return false;
            }
            long traversalMovementGeneration = FollowerMovementWriterAuthority.BeginTraversal(
                bot,
                $"missedTraversalVerify edge={commitment.EdgeId} chain={commitment.ChainId}");
            if (traversalMovementGeneration <= 0)
            {
                return false;
            }
            RebaseLearningV375PersistentRouteTransactionAfterRecovery(
                bot, commitment.ChainId, traversalMovementGeneration, crossedTo,
                "missedTraversalTeleport:" + (source ?? string.Empty));

            ProbeRuntime probe = new ProbeRuntime(ProbeStage.Verify)
            {
                Generation = raidGeneration,
                MovementWriterGeneration = traversalMovementGeneration,
                Bot = bot,
                Player = player,
                RequestedAt = Time.time,
                StageStartedAt = Time.time,
                OwnershipLeaseExpiresAt = Time.time + TraversalOwnershipLeaseSeconds + TraversalOwnershipLeaseTeleportExtraSeconds,
                RequestedDirection = GetFlatDirection(requestedExit - from),
                RequestSource = "missedTraversalTeleport",
                LearnedEdgeId = commitment.EdgeId,
                TraversalEpisodeId = commitment.EpisodeId,
                TraversalChainId = commitment.ChainId,
                RequestedTraversalKind = commitment.Kind,
                TraversalKind = commitment.Kind,
                StartPosition = from,
                PreviousInputDirection = player?.InputDirection ?? Vector2.zero,
                PreviousMovementDirection = player?.MovementContext?.MovementDirection ?? Vector2.zero,
                PreviousSprinting = bot.Mover?.Sprinting == true,
                PreviousRunning = bot.Mover?.IsMoving == true,
                UnifiedTraversalFlow = true,
                ExclusiveMoverGate = true,
                TeleportFallbackUsed = true,
                TraversalTeleportAttempted = true,
                TraversalVerifyTarget = crossedTo,
                TraversalVerifyLastPosition = crossedTo,
                TraversalVerifyStableSince = -1f,
                TraversalVerifyNextLogAt = Time.time,
                FrozenTraversalCommitment = CloneTraversalCommitment(commitment),
                TraversalLastMeaningfulPosition = crossedTo,
                TraversalLastMeaningfulProgressAt = Time.time
            };
            if (player?.MovementContext != null)
            {
                probe.StateHandler = (previous, next) => OnProbeStateChanged(probe, previous, next);
                player.MovementContext.SubscribeMovementContextOnStateChanged("R1-86E4EB75EAF6",@bot,probe.StateHandler);
            }
            if (!RegisterActiveProbe(probe)) { DetachProbeStateHandler(probe); return false; }

            WriteEvent("missedTraversalExitTeleport", bot, new
            {
                edgeId = commitment.EdgeId,
                kind = commitment.Kind,
                source,
                fallbackMode,
                from = Vec(from),
                requestedExit = Vec(requestedExit),
                teleportedTo = Vec(crossedTo),
                entryDistance,
                exitDistance,
                noEntryProgress,
                releaseDeferredUntilVerify = true
            });
            return true;
        }

        private static void RegisterRecentTraversalCompletion(
            BotOwner bot,
            int edgeId,
            LearnedTraversalCommitment commitment,
            string source,
            TraversalCompletionMode completionMode = TraversalCompletionMode.Legacy,
            int learningV322AttemptId = 0,
            ProbeRuntime rc58PhysicalProof = null)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || edgeId <= 0)
            {
                return;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate.Id == edgeId);
            RecentTraversalCompletion completion = new RecentTraversalCompletion
            {
                EdgeId = edgeId,
                Entry = commitment?.Entry ?? Vector3.zero,
                Exit = commitment?.Exit ?? Vector3.zero,
                CompletedAt = Time.time,
                ExpiresAt = Time.time + RecentTraversalRelatchSeconds,
                PlayerTraversalSequence = edge?.PlayerTraversalSequence ?? 0
            };
            ProbeRuntime receiptProbe=rc58PhysicalProof;
            if (receiptProbe==null) TryGetActiveProbe(bot,out receiptProbe);
            if (receiptProbe?.Lifecycle!=null && IsProbeLifecycleCurrent(receiptProbe,true) &&
                receiptProbe.LearnedEdgeId==edgeId && receiptProbe.TraversalEpisodeId==commitment?.EpisodeId)
            {
                completion.LifecycleOrigin=receiptProbe.Lifecycle.Origin;
                completion.LifecycleStep=receiptProbe.LifecycleStep;
            }
            if (rc58PhysicalProof != null && IsProbeLifecycleCurrent(rc58PhysicalProof,true) &&
                IsLearningV3RetainableNativeSuccess(rc58PhysicalProof,completionMode) && completionMode == TraversalCompletionMode.Native &&
                rc58PhysicalProof.Bot == bot &&
                rc58PhysicalProof.NativeDropDownAttempted &&
                string.Equals(commitment?.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                rc58PhysicalProof.TraversalEpisodeId > 0 &&
                rc58PhysicalProof.TraversalChainId > 0 &&
                IsFinite(rc58PhysicalProof.NativeDropDownStartPosition) &&
                IsFinite(bot.Position) &&
                Vector3.Distance(rc58PhysicalProof.NativeDropDownStartPosition, bot.Position) <= 12f)
            {
                completion.Rc58VerifiedNativePhysical = true;
                completion.Rc58EpisodeId = rc58PhysicalProof.TraversalEpisodeId;
                completion.Rc58ChainId = rc58PhysicalProof.TraversalChainId;
                completion.Rc58ObservedNativeStart = rc58PhysicalProof.NativeDropDownStartPosition;
                completion.Rc58ObservedNativeEnd = bot.Position;
            }
            RecentTraversalCompletions[MakeRecentTraversalCompletionKey(profileId, edgeId)] = completion;

            // CompileFix27: chain-intermediate edges are not terminal movement boundaries. A
            // per-edge rollback watchdog can see the next edge's legal approach as a snap-back and
            // kill the active successor probe (observed WalkThrough->DropDown in Fix26 after 36ms).
            // Keep only the anti-relatch marker. The final edge owns the chain's integrity/E2E watch.
            bool nonTerminalChainCompletion =
                string.Equals(source, "chainIntermediate", StringComparison.Ordinal) ||
                string.Equals(source, "microEdgeCoalesced", StringComparison.Ordinal);
            if (nonTerminalChainCompletion)
            {
                WriteEvent("recentTraversalCompletionGuardArmed", bot, new
                {
                    edgeId,
                    kind = commitment?.Kind ?? edge?.Kind,
                    source,
                    seconds = RecentTraversalRelatchSeconds,
                    playerTraversalSequence = completion.PlayerTraversalSequence,
                    entry = Vec(completion.Entry),
                    exit = Vec(completion.Exit),
                    postTraversalWatch = false,
                    chainTerminal = false
                });
                WriteEvent("postTraversalIntegrityWatchSuppressedForChain", bot, new
                {
                    edgeId,
                    source,
                    reason = "successorTraversalOwnsMovementAuthority"
                });
                return;
            }

            TraversalEpisodeMetadata integrityEpisode = null;
            TraversalEpisodesByEdge.TryGetValue(edgeId, out integrityEpisode);
            FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor integrityCursor);
            FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission integrityMission);
            Player integrityLeader = FollowerEnvironment.LocalPlayer;
            float integrityLeaderDistance = IsLivePlayer(integrityLeader) && IsFinite(integrityLeader.Position)
                ? GetPlanarDistance(bot.Position, integrityLeader.Position)
                : float.MaxValue;
            PostTraversalIntegrityWatches[profileId] = new PostTraversalIntegrityWatch
            {
                AttemptId = learningV322AttemptId,
                EdgeId = edgeId,
                EpisodeId = integrityEpisode?.EpisodeId ?? 0,
                MissionId = integrityMission?.MissionId ?? 0,
                MissionStepIndex = integrityMission?.CurrentStepIndex ?? -1,
                Entry = completion.Entry,
                Exit = completion.Exit,
                ReleasePosition = bot.Position,
                ArmedAt = Time.time,
                ExpiresAt = Time.time + PostTraversalIntegrityWatchSeconds,
                InitialLeaderDistance = integrityLeaderDistance,
                BestLeaderDistance = integrityLeaderDistance,
                LastLeaderDistance = integrityLeaderDistance,
                LastFollowProgressAt = Time.time,
                EvaluateEndToEndFollow = !string.Equals(source, "chainIntermediate", StringComparison.Ordinal) &&
                                         !string.Equals(source, "microEdgeCoalesced", StringComparison.Ordinal),
                AwaitingFollowAck = !string.Equals(source, "chainIntermediate", StringComparison.Ordinal) &&
                                    !string.Equals(source, "microEdgeCoalesced", StringComparison.Ordinal),
                CompletionMode = completionMode,
                PreviousCompletedEpisodeId = integrityCursor?.LastCompletedEpisodeId ?? 0,
                PreviousCompletedChainId = integrityCursor?.LastCompletedChainId ?? 0,
                CompletedChainId = integrityEpisode?.ChainId ?? commitment?.ChainId ?? 0,
                PreviousConsumedBreadcrumbSequence = integrityCursor?.ConsumedBreadcrumbSequence ?? 0,
                PreviousApproachBreadcrumbSequence = integrityMission?.ApproachBreadcrumbSequence ?? 0,
                MovementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(bot, out _)
            };

            WriteEvent("postTraversalIntegrityWatchArmed", bot, new
            {
                attemptId = learningV322AttemptId,
                edgeId,
                episodeId = integrityEpisode?.EpisodeId ?? 0,
                missionId = integrityMission?.MissionId ?? 0,
                source,
                releasePosition = Vec(bot.Position),
                entry = Vec(completion.Entry),
                exit = Vec(completion.Exit),
                initialLeaderDistance = integrityLeaderDistance,
                evaluateEndToEndFollow = !string.Equals(source, "chainIntermediate", StringComparison.Ordinal) &&
                                         !string.Equals(source, "microEdgeCoalesced", StringComparison.Ordinal),
                completionMode = completionMode.ToString(),
                seconds = PostTraversalIntegrityWatchSeconds
            });

            WriteEvent("recentTraversalCompletionGuardArmed", bot, new
            {
                edgeId,
                kind = commitment?.Kind ?? edge?.Kind,
                source,
                seconds = RecentTraversalRelatchSeconds,
                playerTraversalSequence = completion.PlayerTraversalSequence,
                entry = Vec(completion.Entry),
                exit = Vec(completion.Exit)
            });
        }


        private static void UpdatePostTraversalIntegrityWatch(BotOwner bot)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !PostTraversalIntegrityWatches.TryGetValue(profileId, out PostTraversalIntegrityWatch watch) ||
                watch == null)
            {
                return;
            }

            BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(profileId);
            if (follower?.IsTeleportStabilizing == true || !IsFinite(bot.Position) ||
                !IsFinite(watch.Entry) || !IsFinite(watch.Exit))
            {
                return;
            }

            bool newerProbe = TryGetActiveProbe(bot, out ProbeRuntime liveProbe) && liveProbe != null &&
                              liveProbe.RequestedAt > watch.ArmedAt + 0.05f;
            bool newerMission = FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission liveMission) &&
                                liveMission != null && liveMission.MissionId > watch.MissionId;
            long currentMovementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain integrityOwner);
            bool newerMovementEpoch = watch.MovementGeneration > 0 &&
                                      currentMovementGeneration > watch.MovementGeneration + 1;
            bool newerMissionSupersedes = newerMission &&
                !((integrityOwner == FollowerMovementWriterAuthority.WriterDomain.PostTraversal));
            if (newerProbe || newerMissionSupersedes || newerMovementEpoch)
            {
                WriteEvent("postTraversalIntegrityWatchSuperseded", bot, new
                {
                    edgeId = watch.EdgeId,
                    watchMissionId = watch.MissionId,
                    liveMissionId = liveMission?.MissionId ?? 0,
                    watchMovementGeneration = watch.MovementGeneration,
                    currentMovementGeneration,
                    liveProbeEdgeId = liveProbe?.LearnedEdgeId ?? 0,
                    newerProbe,
                    newerMission,
                    newerMissionSupersedes,
                    integrityOwner = integrityOwner.ToString(),
                    newerMovementEpoch
                });
                PostTraversalIntegrityWatches.Remove(profileId);
                return;
            }

            float releaseDisplacement = GetPlanarDistance(bot.Position, watch.ReleasePosition);
            watch.MaxReleaseDisplacement = Mathf.Max(watch.MaxReleaseDisplacement, releaseDisplacement);

            Player leader = FollowerEnvironment.LocalPlayer;
            float leaderDistance = IsLivePlayer(leader) && IsFinite(leader.Position)
                ? GetPlanarDistance(bot.Position, leader.Position)
                : float.MaxValue;
            if (IsFinite(leaderDistance) && leaderDistance < float.MaxValue)
            {
                if (leaderDistance + 0.10f < watch.BestLeaderDistance)
                {
                    watch.BestLeaderDistance = leaderDistance;
                    watch.LastFollowProgressAt = Time.time;
                }
                watch.LastLeaderDistance = leaderDistance;
            }

            FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain followWatchOwner);
            bool followOwned = followWatchOwner == FollowerMovementWriterAuthority.WriterDomain.Follow ||
                               followWatchOwner == FollowerMovementWriterAuthority.WriterDomain.PostTraversal;
            bool moverHealthyNow = bot.Mover?.HasPathAndNoComplete == true ||
                                   bot.Mover?.IsMoving == true ||
                                   leaderDistance <= 1.25f;
            bool normalFormationConsumer=HasCapabilityNormalFormationConsumer(bot);
            bool closeFormationHealthy = watch.EvaluateEndToEndFollow && !watch.FollowOutcomeInterrupted &&
                                         leaderDistance <= 2.0f && followOwned && moverHealthyNow &&
                                         normalFormationConsumer;
            if (closeFormationHealthy)
            {
                if (watch.CloseFormationStableSince < 0f)
                {
                    watch.CloseFormationStableSince = Time.time;
                }
                else if (Time.time - watch.CloseFormationStableSince >= 0.60f)
                {
                    RecordPostTraversalFollowOutcome(
                        bot,
                        watch,
                        movementResumed: true,
                        formationRecovered: true,
                        reason: "stableCloseNormalFollow");
                    WriteEvent("postTraversalEndToEndClosedOnStableFollow", bot, new
                    {
                        edgeId = watch.EdgeId,
                        leaderDistance,
                        stableSeconds = Time.time - watch.CloseFormationStableSince,
                        movementOwner = followWatchOwner.ToString(),
                        moverHealthy = moverHealthyNow
                    });
                    PostTraversalIntegrityWatches.Remove(profileId);
                    return;
                }
            }
            else
            {
                watch.CloseFormationStableSince = -1f;
            }

            if (bot.Mover != null && bot.Mover.HasPathAndNoComplete)
            {
                watch.SawHealthyMoverPath = true;
                watch.LastMoverEvidenceAt = Time.time;
            }
            if (FollowerStateAuthorityCoordinator.HasImmediateCombatThreatClaim(bot, out string combatResumeReason))
            {
                if (!watch.FollowOutcomeInterrupted)
                {
                    watch.FollowOutcomeInterrupted = true;
                    watch.AwaitingFollowAck = false;
                    watch.ExpiresAt = Time.time;
                    bool chaseReleased = PostTraversalChaseLeases.Remove(profileId);
                    FollowerMovementWriterAuthority.AcquireCombat(
                        bot,
                        "postTraversalIntegrityCombat:" + (combatResumeReason ?? "immediateCombatThreat"));
                    WriteEvent("postTraversalCombatResumeSatisfied", bot, new
                    {
                        edgeId = watch.EdgeId,
                        reason = combatResumeReason ?? "immediateCombatThreat",
                        chaseReleased,
                        leaderDistance
                    });
                }
            }

            if (!watch.AwaitingFollowAck && Time.time > watch.ExpiresAt)
            {
                if (watch.EvaluateEndToEndFollow && !watch.FollowOutcomeInterrupted && watch.ForcedFollowAckFailure)
                {
                    // CompileFix43: the short NormalFollow ACK window is useful for ownership
                    // proving, but it is not authoritative evidence that Follow never resumed.
                    // Fix42 could move 7-30m with a healthy mover and close much of the leader gap,
                    // yet still be recorded as movementResumed=false because the ACK timer missed
                    // its narrow aligned-target window. Reconcile the final watch with physical
                    // displacement + leader-distance progress before writing learning outcomes.
                    bool closeToLeader = leaderDistance <= PostTraversalFollowResumeCloseLeaderDistance;
                    bool leaderGapImproved =
                        watch.InitialLeaderDistance < float.MaxValue &&
                        watch.BestLeaderDistance <= watch.InitialLeaderDistance - 0.75f;
                    bool physicalFollowResumed =
                        watch.MaxReleaseDisplacement >= PostTraversalFollowResumeMinDisplacement &&
                        (watch.SawHealthyMoverPath || leaderGapImproved);
                    float dynamicFormationLimit = watch.InitialLeaderDistance < float.MaxValue
                        ? Mathf.Clamp(
                            watch.InitialLeaderDistance * PostTraversalFormationInitialDistanceFactor,
                            PostTraversalFormationMinDynamicDistance,
                            PostTraversalFormationMaxDynamicDistance)
                        : PostTraversalFormationMaxDynamicDistance;
                    bool formationRecoveredByDistance =
                        physicalFollowResumed &&
                        watch.InitialLeaderDistance < float.MaxValue &&
                        watch.BestLeaderDistance <= watch.InitialLeaderDistance - PostTraversalFormationBestImprovement &&
                        watch.LastLeaderDistance <= watch.InitialLeaderDistance - PostTraversalFormationLastImprovement &&
                        watch.LastLeaderDistance <= dynamicFormationLimit &&
                        watch.LastLeaderDistance <= watch.BestLeaderDistance + PostTraversalFormationRegressionTolerance;
                    bool formationRecovered = normalFormationConsumer && (closeToLeader || formationRecoveredByDistance);
                    RecordPostTraversalFollowOutcome(
                        bot,
                        watch,
                        movementResumed: physicalFollowResumed || closeToLeader,
                        formationRecovered: formationRecovered,
                        reason: !normalFormationConsumer ? "normalFollowConsumerNotEstablished" : closeToLeader ? "closeToLeaderAfterAckMiss" :
                            (formationRecoveredByDistance ? "leaderDistanceRecoveredAfterAckMiss" :
                             (physicalFollowResumed ? "movementResumedAfterAckMiss" : "normalFollowPhysicalAckNotEstablished")));
                }
                else if (watch.EvaluateEndToEndFollow && !watch.FollowOutcomeInterrupted)
                {
                    bool closeToLeader = leaderDistance <= PostTraversalFollowResumeCloseLeaderDistance;
                    bool physicalFollowResumed = watch.MaxReleaseDisplacement >= PostTraversalFollowResumeMinDisplacement &&
                                                 watch.SawHealthyMoverPath;
                    float dynamicFormationLimit = watch.InitialLeaderDistance < float.MaxValue
                        ? Mathf.Clamp(
                            watch.InitialLeaderDistance * PostTraversalFormationInitialDistanceFactor,
                            PostTraversalFormationMinDynamicDistance,
                            PostTraversalFormationMaxDynamicDistance)
                        : PostTraversalFormationMaxDynamicDistance;
                    bool formationRecoveredByDistance =
                        physicalFollowResumed &&
                        watch.InitialLeaderDistance < float.MaxValue &&
                        watch.BestLeaderDistance <= watch.InitialLeaderDistance - PostTraversalFormationBestImprovement &&
                        watch.LastLeaderDistance <= watch.InitialLeaderDistance - PostTraversalFormationLastImprovement &&
                        watch.LastLeaderDistance <= dynamicFormationLimit &&
                        watch.LastLeaderDistance <= watch.BestLeaderDistance + PostTraversalFormationRegressionTolerance;
                    bool formationRecovered = normalFormationConsumer && (closeToLeader || formationRecoveredByDistance);
                    RecordPostTraversalFollowOutcome(
                        bot,
                        watch,
                        movementResumed: physicalFollowResumed || closeToLeader,
                        formationRecovered: formationRecovered,
                        reason: !normalFormationConsumer ? "normalFollowConsumerNotEstablished" : closeToLeader ? "closeToLeader" :
                            (formationRecoveredByDistance ? "leaderDistanceRecovered" :
                             (physicalFollowResumed ? "movementResumedWithoutFormation" : "followResumeNotObserved")));
                }
                else if (watch.EvaluateEndToEndFollow && watch.FollowOutcomeInterrupted)
                {
                    WriteEvent("traversalEndToEndFollowOutcomeSkipped", bot, new
                    {
                        edgeId = watch.EdgeId,
                        reason = "combatInterruptedFollowWatch",
                        maxReleaseDisplacement = watch.MaxReleaseDisplacement,
                        lastLeaderDistance = watch.LastLeaderDistance
                    });
                }
                PostTraversalIntegrityWatches.Remove(profileId);
                return;
            }

            if (releaseDisplacement < PostTraversalRollbackMinReleaseDisplacement)
            {
                return;
            }

            float entryDistance = GetPlanarDistance(bot.Position, watch.Entry);
            float exitDistance = GetPlanarDistance(bot.Position, watch.Exit);
            Vector3 traversalAxis = watch.Exit - watch.Entry;
            traversalAxis.y = 0f;
            float traversalLength = traversalAxis.magnitude;
            if (traversalLength > 0.01f) traversalAxis /= traversalLength;
            Vector3 fromEntry = bot.Position - watch.Entry;
            fromEntry.y = 0f;
            float forwardProjection = traversalLength > 0.01f
                ? Vector3.Dot(fromEntry, traversalAxis)
                : 0f;
            bool snappedBackToEntrySide =
                entryDistance + PostTraversalRollbackSideMargin < exitDistance &&
                entryDistance <= PostTraversalRollbackEntryDistance &&
                traversalLength > 0.25f &&
                forwardProjection <= Mathf.Max(0.65f, traversalLength * 0.35f);
            if (!snappedBackToEntrySide)
            {
                return;
            }

            // CompileFix44: PostTraversal is an evaluator, never a movement/mission owner. Older
            // watches were allowed to release a newer active traversal, delete its RouteMission,
            // restore an old cursor and arm a replacement mission. That stale mutation was the
            // direct cause of Vault->WalkThrough chains disappearing several seconds after a prior
            // traversal completed. Record the rollback evidence, but never mutate newer runtime state.
            bool movementResumed = watch.MaxReleaseDisplacement >= PostTraversalFollowResumeMinDisplacement &&
                                   watch.SawHealthyMoverPath;
            RecordPostTraversalFollowOutcome(
                bot, watch, movementResumed: movementResumed, formationRecovered: false, reason: "postTraversalRollback");
            PostTraversalIntegrityWatches.Remove(profileId);
            WriteEvent("postTraversalIntegrityRollbackDetected", bot, new
            {
                edgeId = watch.EdgeId,
                episodeId = watch.EpisodeId,
                previousMissionId = watch.MissionId,
                previousMissionStepIndex = watch.MissionStepIndex,
                releasePosition = Vec(watch.ReleasePosition),
                currentPosition = Vec(bot.Position),
                releaseDisplacement,
                entryDistance,
                exitDistance,
                forwardProjection,
                traversalLength,
                evaluatorOnly = true,
                missionRearmed = false
            });
        }

        private static void RecordPostTraversalFollowOutcome(
            BotOwner bot,
            PostTraversalIntegrityWatch watch,
            bool movementResumed,
            bool formationRecovered,
            string reason)
        {
            if (watch == null || watch.FollowOutcomeRecorded || watch.EdgeId <= 0)
            {
                return;
            }
            watch.FollowOutcomeRecorded = true;

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == watch.EdgeId);
            if (edge == null || string.IsNullOrWhiteSpace(edge.ExperienceKey))
            {
                return;
            }
            RecordLearningV322FollowEvidence(edge, movementResumed, formationRecovered, reason);
            WriteEvent("learningV322TraversalFollowOutcome", bot, new
            {
                attemptId = watch.AttemptId,
                edgeId = watch.EdgeId,
                experienceKey = edge.ExperienceKey,
                kind = edge.Kind,
                movementResumed,
                formationRecovered,
                completionMode = watch.CompletionMode.ToString(),
                initialLeaderDistance = watch.InitialLeaderDistance,
                bestLeaderDistance = watch.BestLeaderDistance,
                lastLeaderDistance = watch.LastLeaderDistance,
                releaseDisplacement = watch.MaxReleaseDisplacement,
                reason = reason ?? string.Empty
            });
            if (!TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) ||
                record == null)
            {
                return;
            }

            if (movementResumed)
            {
                record.FollowMovementResumedSuccesses++;
            }
            if (formationRecovered)
            {
                record.FormationRecoveredSuccesses++;
                record.EndToEndFollowSuccesses++;
                record.ConsecutiveFollowResumeFailures = 0;
                if (watch.CompletionMode == TraversalCompletionMode.Native)
                {
                    record.NativeEndToEndFollowSuccesses++;
                }
                else if (watch.CompletionMode == TraversalCompletionMode.AssistedReplay)
                {
                    record.AssistedEndToEndFollowSuccesses++;
                }
                else if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    record.WalkThroughEndToEndFollowSuccesses++;
                }
            }
            else
            {
                record.FormationRecoveryFailures++;

                // CompileFix44: crossing, Follow movement resume, and formation recovery are three
                // independent rewards. A bot that moved 10-30m on a healthy Follow path is not a
                // FollowResumeFailure merely because the player kept sprinting and formation was
                // still lagging when the watch expired. Only a truly stationary/non-resumed Follow
                // increments FollowResumeFailures and executor-specific continuation failures.
                if (!movementResumed)
                {
                    record.FollowResumeFailures++;
                    record.ConsecutiveFollowResumeFailures++;
                    if (watch.CompletionMode == TraversalCompletionMode.Native)
                    {
                        record.NativeFollowResumeFailures++;
                    }
                    else if (watch.CompletionMode == TraversalCompletionMode.AssistedReplay)
                    {
                        record.AssistedFollowResumeFailures++;
                    }
                    else if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                    {
                        record.WalkThroughFollowResumeFailures++;
                    }
                }
                else
                {
                    record.ConsecutiveFollowResumeFailures = 0;
                }

                if (string.Equals(reason, "postTraversalRollback", StringComparison.Ordinal))
                {
                    record.PostTraversalRollbacks++;
                }
            }

            float elapsed = Mathf.Max(0f, Time.time - watch.ArmedAt);
            int followAttempts = Math.Max(1, record.EndToEndFollowSuccesses + GetEndToEndFollowFailureCount(record));
            if (movementResumed)
            {
                int movementSamples = Math.Max(1, record.FollowMovementResumedSuccesses);
                record.MeanFollowResumeSeconds = movementSamples <= 1
                    ? elapsed
                    : Mathf.Lerp(
                        record.MeanFollowResumeSeconds, elapsed,
                        1f / Mathf.Min(12f, movementSamples));
            }
            float followSampleScore = formationRecovered ? 1f : (movementResumed ? 0.72f : 0f);
            record.FollowResumeRecentScore = followAttempts <= 1 &&
                                             record.FollowResumeRecentScore <= 0f
                ? followSampleScore
                : Mathf.Clamp01(Mathf.Lerp(
                    record.FollowResumeRecentScore <= 0f ? 0.5f : record.FollowResumeRecentScore,
                    followSampleScore,
                    0.28f));
            record.LastFollowOutcome = formationRecovered
                ? "FormationRecovered"
                : (movementResumed ? "FollowResumedFormationLagging" : "FollowResumeFailure");
            record.LastFollowReason = reason ?? string.Empty;
            record.LastFollowUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            RefreshTraversalExperienceConfidence(record);
            traversalExperienceDirty = true;

            WriteEvent("traversalEndToEndFollowOutcome", bot, new
            {
                edgeId = watch.EdgeId,
                experienceKey = edge.ExperienceKey,
                kind = edge.Kind,
                success = formationRecovered,
                movementResumed,
                formationRecovered,
                reason,
                watchSeconds = elapsed,
                maxReleaseDisplacement = watch.MaxReleaseDisplacement,
                initialLeaderDistance = watch.InitialLeaderDistance,
                bestLeaderDistance = watch.BestLeaderDistance,
                lastLeaderDistance = watch.LastLeaderDistance,
                sawHealthyMoverPath = watch.SawHealthyMoverPath,
                completionMode = watch.CompletionMode.ToString(),
                endToEndSuccesses = record.EndToEndFollowSuccesses,
                followResumeFailures = record.FollowResumeFailures,
                formationRecoveredSuccesses = record.FormationRecoveredSuccesses,
                formationRecoveryFailures = record.FormationRecoveryFailures,
                effectiveScore = GetTraversalExperienceEffectiveScore(record),
                confidence = record.Confidence
            });
        }

        private static bool IsRecentTraversalRelatchBlocked(
            BotOwner bot,
            LearnedTraversalEdge edge,
            out RecentTraversalCompletion completion)
        {
            completion = null;
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || edge == null)
            {
                return false;
            }

            string completionKey = MakeRecentTraversalCompletionKey(profileId, edge.Id);
            if (!RecentTraversalCompletions.TryGetValue(completionKey, out completion) || completion == null)
            {
                return false;
            }

            if (Time.time > completion.ExpiresAt)
            {
                RecentTraversalCompletions.Remove(completionKey);
                completion = null;
                return false;
            }

            if (edge.PlayerTraversalSequence > completion.PlayerTraversalSequence)
            {
                // The player genuinely demonstrated this edge again after the follower completed it,
                // so a deliberate reverse traversal may proceed immediately.
                RecentTraversalCompletions.Remove(completionKey);
                completion = null;
                return false;
            }

            // R8.8 post-release integrity recovery: if EFT authority snaps the follower back to the
            // entry side immediately after an apparently successful traversal, the anti-relatch guard
            // must not strand it there for 2.75s. Re-open the same player-authored episode at once.
            if (bot != null && IsFinite(completion.Entry) && IsFinite(completion.Exit))
            {
                float entryDistance = GetPlanarDistance(bot.Position, completion.Entry);
                float exitDistance = GetPlanarDistance(bot.Position, completion.Exit);
                if (entryDistance + 0.35f < exitDistance && entryDistance <= 1.75f)
                {
                    WriteEvent("recentTraversalRelatchReleasedAfterRollback", bot, new
                    {
                        edgeId = edge.Id,
                        kind = edge.Kind,
                        entryDistance,
                        exitDistance,
                        secondsSinceCompletion = Mathf.Max(0f, Time.time - completion.CompletedAt)
                    });
                    RecentTraversalCompletions.Remove(completionKey);
                    completion = null;
                    return false;
                }
            }

            if (!completion.BlockLogged)
            {
                completion.BlockLogged = true;
                WriteEvent("recentTraversalRelatchBlocked", bot, new
                {
                    edgeId = edge.Id,
                    kind = edge.Kind,
                    secondsRemaining = Mathf.Max(0f, completion.ExpiresAt - Time.time),
                    playerTraversalSequence = edge.PlayerTraversalSequence
                });
            }
            return true;
        }

        private static string MakeRecentTraversalCompletionKey(string profileId, int edgeId)
        {
            return (profileId ?? string.Empty) + ":" + edgeId;
        }

        private static void ClearLearnedTraversalCommitment(BotOwner bot, int edgeId, string reason)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }

            if (LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment existing) &&
                (edgeId <= 0 || existing.EdgeId == edgeId))
            {
                LearnedTraversalCommitments.Remove(profileId);
                WriteEvent("followTraversalCommitCleared", bot, new
                {
                    edgeId = existing.EdgeId,
                    episodeId = existing.EpisodeId,
                    chainId = existing.ChainId,
                    kind = existing.Kind,
                    reason
                });
            }
        }

        private static bool IsTraversalEpisodeAlreadyConsumed(BotOwner bot, LearnedTraversalEdge edge)
        {
            if(edge!=null&&TraversalEpisodesByEdge.TryGetValue(edge.Id,out var recorded)&&recorded!=null&&
                IsCapabilityDebtResolved(bot,recorded.EpisodeId,edge.Id))return true;
            string profileId = bot?.ProfileId ?? string.Empty;
            if (edge == null || string.IsNullOrEmpty(profileId) ||
                !TraversalEpisodesByEdge.TryGetValue(edge.Id, out TraversalEpisodeMetadata episode) || episode == null ||
                !FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) || cursor == null)
            {
                return false;
            }

            // R8.9: a manual/recovery teleport advances a per-follower route floor. That floor
            // must suppress the generic learned-edge selector too; otherwise Route Mission can be
            // cleared correctly and the old fallback selector immediately recreates the same stale
            // destination from traversal history on the next Follow tick.
            int routeFloor = Math.Max(GetFollowerRouteResumeFloor(profileId), cursor.ConsumedBreadcrumbSequence);
            if (episode.EndBreadcrumbSequence > 0 && episode.EndBreadcrumbSequence <= routeFloor)
            {
                return true;
            }

            // Otherwise suppress episodes already consumed in the same active player-authored chain.
            // A later player reversal/second demonstration receives a new episode id and remains eligible.
            return cursor.LastCompletedChainId == episode.ChainId &&
                   episode.EpisodeId == cursor.LastCompletedEpisodeId;
        }

        private static bool IsTraversalOrientationAllowed(
            LearnedTraversalEdge edge,
            Vector3 entry,
            Vector3 exit)
        {
            if (edge == null)
            {
                return false;
            }

            bool forward = Vector3.Distance(entry, edge.A) <= Vector3.Distance(entry, edge.B);
            // CompileFix46: WalkThrough and DropDown are directional demonstrations. A reverse
            // traversal is only legal when the player has taught a separate reverse sibling edge.
            // Reversing one authored corridor in-place was causing valid forward geometry to be
            // replayed backwards through one-way seams/collider lips.
            if (string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return forward;
            }

            if (!string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) || forward)
            {
                return true;
            }

            Vector3 rawStart = IsFinite(edge.RawStart) ? edge.RawStart : edge.A;
            Vector3 rawEnd = IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B;
            return Mathf.Abs(rawEnd.y - rawStart.y) <= JumpReverseBidirectionalMaxVerticalDelta;
        }

        // CF44: V424 may legitimately refresh a directional WT to the remaining final
        // portion of the *same* player's live episode. Its RawEntry can then be closer
        // to the authored RawEnd than RawStart. That is progress, not reverse traversal.
        // Require exact live mission+episode ownership and positive physical direction;
        // unrelated, cross-episode and actual reverse WT stay one-way.
        private static bool TryCF44AdmitCurrentEpisodeForwardWalkThroughTail(
            BotOwner bot, LearnedTraversalEdge edge, LearnedTraversalCommitment commitment,
            out float headingDot, out float startProjection, out float endProjection)
        {
            headingDot = 0f;
            startProjection = 0f;
            endProjection = 0f;
            if (bot == null || edge == null || commitment == null ||
                !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                commitment.EpisodeId <= 0 || commitment.ChainId <= 0 ||
                commitment.RouteMissionId <= 0 || commitment.RouteMissionStepIndex < 0 ||
                !IsFinite(edge.RawStart) || !IsFinite(edge.RawEnd) ||
                !IsFinite(commitment.RawEntry) || !IsFinite(commitment.RawExit) ||
                !FollowerRouteMissions.TryGetValue(bot.ProfileId, out FollowerRouteMission mission) ||
                mission == null || mission.MissionId != commitment.RouteMissionId ||
                mission.CurrentStepIndex != commitment.RouteMissionStepIndex ||
                mission.Steps == null || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || step.EdgeId != edge.Id ||
                step.EpisodeId != commitment.EpisodeId || step.ChainId != commitment.ChainId ||
                !string.Equals(step.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            TraversalEpisodeMetadata episode = TraversalEpisodeStream.FirstOrDefault(item =>
                item != null && item.EpisodeId == commitment.EpisodeId &&
                item.EdgeId == edge.Id && item.ChainId == commitment.ChainId &&
                !item.LearningV386ExecutionDebtRetiredByOrdinaryNavMesh &&
                !item.LearningV386ExecutionDebtConsumedByPhysicalPassage);
            if (episode == null)
            {
                return false;
            }

            Vector3 authored = edge.RawEnd - edge.RawStart;
            Vector3 tail = commitment.RawExit - commitment.RawEntry;
            authored.y = 0f;
            tail.y = 0f;
            float authoredSpan = authored.magnitude;
            float tailSpan = tail.magnitude;
            if (authoredSpan < 0.35f || tailSpan < 0.06f ||
                tailSpan > authoredSpan + 0.15f)
            {
                return false;
            }

            Vector3 direction = authored / authoredSpan;
            headingDot = Vector3.Dot(tail / tailSpan, direction);
            Vector3 fromStart = commitment.RawEntry - edge.RawStart;
            Vector3 fromEnd = commitment.RawExit - edge.RawStart;
            fromStart.y = 0f;
            fromEnd.y = 0f;
            startProjection = Vector3.Dot(fromStart, direction);
            endProjection = Vector3.Dot(fromEnd, direction);
            float entryLateral = (fromStart - direction * startProjection).magnitude;
            float exitLateral = (fromEnd - direction * endProjection).magnitude;

            return headingDot >= 0.85f &&
                   startProjection >= -0.10f && startProjection <= authoredSpan + 0.25f &&
                   endProjection > startProjection + 0.05f &&
                   endProjection <= authoredSpan + 0.35f &&
                   entryLateral <= WalkThroughMaxLateralDeviation &&
                   exitLateral <= WalkThroughMaxLateralDeviation;
        }

        private static bool IsTraversalCommitmentOrientationAllowed(
            LearnedTraversalEdge edge,
            LearnedTraversalCommitment commitment)
        {
            if (edge == null || commitment == null)
            {
                return false;
            }
            if (IsLearningV319TransientSkillTransfer(commitment))
            {
                return true;
            }

            bool forward = Vector3.Distance(commitment.RawEntry, edge.RawStart) <=
                           Vector3.Distance(commitment.RawEntry, edge.RawEnd);
            if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                return forward;
            }
            return forward ||
                   !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                   Mathf.Abs(edge.RawEnd.y - edge.RawStart.y) <= JumpReverseBidirectionalMaxVerticalDelta;
        }

        private static float GetTraversalSemanticSelectionAdjustment(
            LearnedTraversalEdge edge,
            Vector3 entry,
            Vector3 exit)
        {
            if (edge == null ||
                !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return 0f;
            }

            bool forward = Vector3.Distance(entry, edge.A) <= Vector3.Distance(entry, edge.B);
            Vector3 rawEntry = forward && IsFinite(edge.RawStart) ? edge.RawStart :
                               (!forward && IsFinite(edge.RawEnd) ? edge.RawEnd : entry);
            Vector3 rawExit = forward && IsFinite(edge.RawEnd) ? edge.RawEnd :
                              (!forward && IsFinite(edge.RawStart) ? edge.RawStart : exit);

            foreach (LearnedTraversalEdge sibling in LearnedTraversalEdges)
            {
                if (sibling == null || sibling.Id == edge.Id || sibling.Disabled ||
                    (!string.Equals(sibling.Kind, "Vault", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(sibling.Kind, "Climb", StringComparison.OrdinalIgnoreCase)) ||
                    ShouldSuppressTraversalByExperience(sibling, out _))
