        private static bool AreCrossKindTraversalEndpointsEquivalent(
            Vector3 rawStart,
            Vector3 rawEnd,
            Vector3 candidateStart,
            Vector3 candidateEnd,
            out bool reversed,
            out float score)
        {
            reversed = false;
            score = float.MaxValue;
            if (!IsFinite(rawStart) || !IsFinite(rawEnd) ||
                !IsFinite(candidateStart) || !IsFinite(candidateEnd))
            {
                return false;
            }

            float forwardStartPlanar = GetPlanarDistance(rawStart, candidateStart);
            float forwardEndPlanar = GetPlanarDistance(rawEnd, candidateEnd);
            float forwardStartVertical = Mathf.Abs(rawStart.y - candidateStart.y);
            float forwardEndVertical = Mathf.Abs(rawEnd.y - candidateEnd.y);
            bool forward =
                FollowerCapabilityHelperRules.AreCrossKindTraversalEndpointsEquivalent_forward_1A56A4C5_1(forwardStartPlanar,CrossKindJumpSiblingPlanarEndpointDistance,forwardEndPlanar,CrossKindJumpSiblingPlanarEndpointDistance,forwardStartVertical,CrossKindJumpSiblingVerticalEndpointDistance,forwardEndVertical,CrossKindJumpSiblingVerticalEndpointDistance);

            float reverseStartPlanar = GetPlanarDistance(rawStart, candidateEnd);
            float reverseEndPlanar = GetPlanarDistance(rawEnd, candidateStart);
            float reverseStartVertical = Mathf.Abs(rawStart.y - candidateEnd.y);
            float reverseEndVertical = Mathf.Abs(rawEnd.y - candidateStart.y);
            bool reverse =
                FollowerCapabilityHelperRules.AreCrossKindTraversalEndpointsEquivalent_reverse_1A56A4C5_2(reverseStartPlanar,CrossKindJumpSiblingPlanarEndpointDistance,reverseEndPlanar,CrossKindJumpSiblingPlanarEndpointDistance,reverseStartVertical,CrossKindJumpSiblingVerticalEndpointDistance,reverseEndVertical,CrossKindJumpSiblingVerticalEndpointDistance);

            if (!forward && !reverse)
            {
                return false;
            }

            float forwardScore = forward
                ? forwardStartPlanar + forwardEndPlanar +
                  0.25f * (forwardStartVertical + forwardEndVertical)
                : float.MaxValue;
            float reverseScore = reverse
                ? reverseStartPlanar + reverseEndPlanar +
                  0.25f * (reverseStartVertical + reverseEndVertical)
                : float.MaxValue;
            reversed = reverseScore < forwardScore;
            score = Mathf.Min(forwardScore, reverseScore);
            return true;
        }

        private static bool RegisterCrossKindJumpCandidate(
            LearnedTraversalEdge sibling,
            bool reversed,
            Vector3 rawStart,
            Vector3 rawEnd,
            out int demonstrations)
        {
            demonstrations = 0;
            if (sibling == null || sibling.Id <= 0)
            {
                return false;
            }

            float now = Time.time;
            bool reset = !CrossKindJumpCandidates.TryGetValue(
                sibling.Id, out CrossKindJumpCandidateState state) ||
                state == null ||
                now - state.LastAt > CrossKindJumpCandidateLifetimeSeconds ||
                state.Reversed != reversed ||
                !AreCrossKindTraversalEndpointsEquivalent(
                    rawStart, rawEnd, state.RawStart, state.RawEnd, out bool candidateReversed, out _) ||
                candidateReversed;

            if (reset)
            {
                state = new CrossKindJumpCandidateState
                {
                    SiblingEdgeId = sibling.Id,
                    RawStart = rawStart,
                    RawEnd = rawEnd,
                    Reversed = reversed,
                    Demonstrations = 1,
                    FirstAt = now,
                    LastAt = now
                };
                CrossKindJumpCandidates[sibling.Id] = state;
            }
            else if (now - state.LastAt >= CrossKindJumpCandidateRepeatMinSeconds)
            {
                state.Demonstrations++;
                state.RawStart = rawStart;
                state.RawEnd = rawEnd;
                state.LastAt = now;
            }

            demonstrations = state.Demonstrations;
            return demonstrations >= CrossKindJumpAlternativeRequiredDemonstrations;
        }

        private static bool TryFindVaultClimbSemanticSibling(
            Vector3 rawStart,
            Vector3 rawEnd,
            out LearnedTraversalEdge sibling,
            out bool reversed)
        {
            sibling = null;
            reversed = false;
            float best = float.MaxValue;
            foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges)
            {
                if (candidate == null || candidate.Disabled ||
                    (!string.Equals(candidate.Kind, "Vault", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(candidate.Kind, "Climb", StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                Vector3 start = IsFinite(candidate.RawStart) ? candidate.RawStart : candidate.A;
                Vector3 end = IsFinite(candidate.RawEnd) ? candidate.RawEnd : candidate.B;
                if (!AreCrossKindTraversalEndpointsEquivalent(
                        rawStart, rawEnd, start, end,
                        out bool candidateReversed, out float candidateScore) ||
                    candidateScore >= best)
                {
                    continue;
                }

                sibling = candidate;
                reversed = candidateReversed;
                best = candidateScore;
            }
            return sibling != null;
        }

        private static void TryConsiderTraversalOrientation(
            LearnedTraversalEdge edge,
            Vector3 entry,
            Vector3 exit,
            float botEntryCost,
            float leaderExitCost,
            float sameSideCost,
            ref LearnedTraversalCandidate best)
        {
            if (!IsTraversalOrientationAllowed(edge, entry, exit) ||
                ShouldSuppressLearningV322PersistentEvidence(edge, out _) ||
                ShouldSuppressTraversalByExperience(edge, out _))
            {
                return;
            }

            float crossCost = SafeAdd(botEntryCost, leaderExitCost);
            if (!IsFinite(crossCost))
            {
                return;
            }

            if (IsFinite(sameSideCost) && crossCost + LearnedTraversalOrientationMargin >= sameSideCost)
            {
                return;
            }

            int physicalSuccesses = GetTraversalPhysicalSuccessCount(edge);
            float agePenalty = physicalSuccesses > 0 ? 0f : Mathf.Max(0f, Time.time - edge.CreatedAt) * 0.05f;
            float experienceAdjustment = GetTraversalExperienceSelectionAdjustment(edge);
            float semanticAdjustment = GetTraversalSemanticSelectionAdjustment(edge, entry, exit);
            float recentRouteEvidenceAge = -1f;
            float recentRouteAdjustment = 0f;
            {
                if (!TryGetFreshDirectionalTraversalRouteEvidence(
                        edge, entry, exit, out recentRouteEvidenceAge, out recentRouteAdjustment))
                {
                    return;
                }
            }
            float score = crossCost + agePenalty + experienceAdjustment + semanticAdjustment + recentRouteAdjustment;
            if (best == null || score < best.Score)
            {
                bool forwardOrientation = Vector3.Distance(entry, edge.A) <= Vector3.Distance(entry, edge.B);
                best = new LearnedTraversalCandidate
                {
                    Edge = edge,
                    Entry = entry,
                    Exit = exit,
                    RawEntry = forwardOrientation ? edge.RawStart : edge.RawEnd,
                    RawExit = forwardOrientation ? edge.RawEnd : edge.RawStart,
                    Score = score,
                    RecentRouteAdjustment = recentRouteAdjustment,
                    RecentRouteEvidenceAge = recentRouteEvidenceAge
                };
            }
        }

        private static bool TryGetFreshDirectionalTraversalRouteEvidence(
            LearnedTraversalEdge edge,
            Vector3 entry,
            Vector3 exit,
            out float age,
            out float adjustment)
        {
            age = float.MaxValue;
            adjustment = 0f;
            if (edge == null ||
                !TraversalEpisodesByEdge.TryGetValue(edge.Id, out TraversalEpisodeMetadata episode) ||
                episode == null ||
                episode.StartBreadcrumbSequence <= 0 || episode.EndBreadcrumbSequence <= 0)
            {
                return false;
            }

            age = Mathf.Max(0f, Time.time - episode.CreatedAt);
            if (age > LearnedTraversalRecentRouteSelectionWindowSeconds)
            {
                return false;
            }

            Vector3 episodeEntry = episode.HasSettledStart && IsFinite(episode.SettledStart)
                ? episode.SettledStart
                : (IsFinite(episode.Entry) ? episode.Entry : episode.RawStart);
            Vector3 episodeExit = episode.HasSettledEnd && IsFinite(episode.SettledEnd)
                ? episode.SettledEnd
                : (IsFinite(episode.Exit) ? episode.Exit : episode.RawEnd);
            if (!IsFinite(episodeEntry) || !IsFinite(episodeExit) ||
                GetPlanarDistance(entry, episodeEntry) > LearnedTraversalRecentRouteSelectionEndpointTolerance ||
                GetPlanarDistance(exit, episodeExit) > LearnedTraversalRecentRouteSelectionEndpointTolerance)
            {
                return false;
            }

            Vector3 requestedDirection = GetFlatDirection(exit - entry);
            Vector3 observedDirection = GetFlatDirection(episodeExit - episodeEntry);
            if (requestedDirection.sqrMagnitude < 0.5f || observedDirection.sqrMagnitude < 0.5f ||
                Vector3.Dot(requestedDirection, observedDirection) < RollingTraversalMinForwardDot)
            {
                return false;
            }

            float freshness = 1f - Mathf.Clamp01(age / LearnedTraversalRecentRouteSelectionWindowSeconds);
            adjustment = -LearnedTraversalRecentRouteSelectionMaxBonus * freshness;
            return true;
        }

        private static float GetRecentTraversalRouteSelectionAdjustment(
            LearnedTraversalEdge edge,
            Vector3 entry,
            Vector3 exit)
        {
            if (edge == null ||
                !TraversalEpisodesByEdge.TryGetValue(edge.Id, out TraversalEpisodeMetadata episode) ||
                episode == null ||
                episode.StartBreadcrumbSequence <= 0 || episode.EndBreadcrumbSequence <= 0)
            {
                return 0f;
            }

            float age = Mathf.Max(0f, Time.time - episode.CreatedAt);
            if (age > LearnedTraversalRecentRouteSelectionWindowSeconds)
            {
                return 0f;
            }

            Vector3 episodeEntry = episode.HasSettledStart && IsFinite(episode.SettledStart)
                ? episode.SettledStart
                : (IsFinite(episode.Entry) ? episode.Entry : episode.RawStart);
            Vector3 episodeExit = episode.HasSettledEnd && IsFinite(episode.SettledEnd)
                ? episode.SettledEnd
                : (IsFinite(episode.Exit) ? episode.Exit : episode.RawEnd);
            if (!IsFinite(episodeEntry) || !IsFinite(episodeExit) ||
                GetPlanarDistance(entry, episodeEntry) > LearnedTraversalRecentRouteSelectionEndpointTolerance ||
                GetPlanarDistance(exit, episodeExit) > LearnedTraversalRecentRouteSelectionEndpointTolerance)
            {
                return 0f;
