        private static float GetLocalTraversalPathCost(StrictPathResult path, float directDistance, float absoluteLimit)
        {
            if (path == null || !path.StrictComplete)
            {
                return float.PositiveInfinity;
            }

            float relativeLimit = Mathf.Max(3f, directDistance * 2.5f + 1f);
            if (path.PathLength > absoluteLimit || path.PathLength > relativeLimit)
            {
                return float.PositiveInfinity;
            }

            return path.PathLength;
        }

        private static float SafeAdd(float left, float right)
        {
            if (!IsFinite(left) || !IsFinite(right))
            {
                return float.PositiveInfinity;
            }

            return left + right;
        }

