        private static NativeVaultParameters CreateLearningV319TransferredNativeVaultParameters(
            LearnedTraversalEdge template,
            LearnedTraversalCommitment commitment)
        {
            NativeVaultParameters transferred = CloneNativeVaultParameters(template?.NativeVaultParameters);
            if (transferred == null || template == null || commitment == null ||
                !IsLearningV319TransientSkillTransfer(commitment))
            {
                return transferred;
            }

            Vector3 templateStart = IsFinite(template.RawStart) ? template.RawStart : template.A;
            Vector3 templateEnd = IsFinite(template.RawEnd) ? template.RawEnd : template.B;
            Vector3 targetStart = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 targetEnd = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 templateForward = GetFlatDirection(templateEnd - templateStart);
            Vector3 targetForward = GetFlatDirection(targetEnd - targetStart);
            if (templateForward.sqrMagnitude < 0.5f || targetForward.sqrMagnitude < 0.5f ||
                !IsFinite(transferred.VaultingPoint))
            {
                transferred.VaultingPoint = targetStart;
                return transferred;
            }

            Vector3 templateRight = new Vector3(-templateForward.z, 0f, templateForward.x);
            Vector3 targetRight = new Vector3(-targetForward.z, 0f, targetForward.x);
            Vector3 local = transferred.VaultingPoint - templateStart;
            float forwardOffset = Vector3.Dot(new Vector3(local.x, 0f, local.z), templateForward);
            float lateralOffset = Vector3.Dot(new Vector3(local.x, 0f, local.z), templateRight);
            transferred.VaultingPoint = targetStart +
                targetForward * forwardOffset +
                targetRight * lateralOffset +
                Vector3.up * local.y;
            return transferred;
        }

        private static NativeVaultParameters CaptureNativeVaultParameters(Player player, EPlayerState state)
        {
            if (player?.MovementContext == null)
            {
                return null;
            }

            try
            {
                IVaultingParameters parameters = player.VaultingParameters;
                EVaultingStrategy strategy = parameters?.GetVaultingStrategy() ?? EVaultingStrategy.None;
                if (strategy == EVaultingStrategy.None)
                {
                    strategy = state == EPlayerState.ClimbUp ? EVaultingStrategy.Climb : EVaultingStrategy.Vault;
                }

                float height = player.MovementContext.PlayerAnimatorGetObstacleHeight();
                float length = player.MovementContext.PlayerAnimatorGetObstacleLength();
                if ((!IsFinite(height) || height <= 0.001f) && parameters != null)
                {
                    height = parameters.VaultingHeight;
                }
                if ((!IsFinite(length) || length <= 0.001f) && parameters != null)
                {
                    length = parameters.VaultingLength;
                }

                return new NativeVaultParameters
                {
                    Strategy = strategy.ToString(),
                    VaultingPoint = parameters != null && IsFinite(parameters.MaxWeightPointPosition)
                        ? parameters.MaxWeightPointPosition
                        : player.Position,
                    VaultingHeight = Mathf.Max(0f, IsFinite(height) ? height : 0f),
                    VaultingLength = Mathf.Max(0f, IsFinite(length) ? length : 0f),
                    DemonstratedVaultingSpeed = Mathf.Max(0f, IsFinite(player.MovementContext.VaultingSpeed)
                        ? player.MovementContext.VaultingSpeed
                        : 0f),
                    BehindObstacleRatio = parameters != null && IsFinite(parameters.BehindObstacleRatio)
                        ? parameters.BehindObstacleRatio
                        : 0f,
                    AbsoluteForwardVelocity = parameters != null && IsFinite(parameters.AbsoluteForwardVelocity)
                        ? parameters.AbsoluteForwardVelocity
                        : new Vector2(player.Velocity.x, player.Velocity.z).magnitude
                };
            }
            catch (Exception ex)
            {
                WriteEvent("nativeVaultParametersCaptureFailed", null, new
                {
                    state = state.ToString(),
                    error = ex.GetType().Name + ": " + ex.Message
                });
                return null;
            }
        }

        private static bool TryParseNativeVaultStrategy(string value, out EVaultingStrategy strategy)
        {
            strategy = EVaultingStrategy.None;
            if (string.IsNullOrWhiteSpace(value))
            {
                return false;
            }
            if (!Enum.TryParse(value, true, out strategy))
            {
                strategy = EVaultingStrategy.None;
                return false;
            }
            return strategy == EVaultingStrategy.Vault || strategy == EVaultingStrategy.Climb;
        }

        private static bool IsLearningV2SameLocalSkill(
            LearnedTraversalEdge edge,
            Vector3 rawStart,
            Vector3 rawEnd,
            bool directionalKind)
        {
            if ((edge == null) ||
                !IsFinite(edge.RawStart) || !IsFinite(edge.RawEnd) ||
                !IsFinite(rawStart) || !IsFinite(rawEnd))
            {
                return false;
            }

            Func<Vector3, Vector3, Vector3, Vector3, bool> matches = (storedStart, storedEnd, candidateStart, candidateEnd) =>
            {
                if (GetPlanarDistance(storedStart, candidateStart) > LearningV2RevisionEndpointRadius ||
                    GetPlanarDistance(storedEnd, candidateEnd) > LearningV2RevisionEndpointRadius ||
                    Mathf.Abs(storedStart.y - candidateStart.y) > LearningV2RevisionVerticalTolerance ||
                    Mathf.Abs(storedEnd.y - candidateEnd.y) > LearningV2RevisionVerticalTolerance)
                {
                    return false;
                }
                float storedSpan = GetPlanarDistance(storedStart, storedEnd);
                float candidateSpan = GetPlanarDistance(candidateStart, candidateEnd);
                if (FollowerCapabilityHelperRules.IsLearningV2SameLocalSkill_matches_8E1C451B_1(storedSpan,candidateSpan))
                {
                    float spanRatio = candidateSpan / storedSpan;
                    if (FollowerCapabilityHelperRules.IsLearningV2SameLocalSkill_matches_8E1C451B_2(spanRatio,LearningV2RevisionMinSpanRatio,spanRatio,LearningV2RevisionMaxSpanRatio))
                    {
                        return false;
                    }
                }
                Vector3 storedDirection = GetFlatDirection(storedEnd - storedStart);
                Vector3 candidateDirection = GetFlatDirection(candidateEnd - candidateStart);
                return storedDirection.sqrMagnitude < 0.5f || candidateDirection.sqrMagnitude < 0.5f ||
                       Vector3.Dot(storedDirection, candidateDirection) >= LearningV2RevisionMinDirectionDot;
            };

            if (matches(edge.RawStart, edge.RawEnd, rawStart, rawEnd))
            {
                return true;
            }
            return !directionalKind && matches(edge.RawEnd, edge.RawStart, rawStart, rawEnd);
        }

