        private static bool IsLearningV31WalkThroughNativeLocomotionEvidence(ProbeRuntime probe)
        {
            if ((probe == null))
            {
                return false;
            }
            string kind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            if (!string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            // WalkThrough has no EFT vault-state actuator. Its native proof is the ordinary physical
            // BotMover/body locomotion corridor itself. Keep this proof strict: collision-active
