            bool recovery = FollowerCapabilityHelperRules.IsLearningV31WalkThroughNativeLocomotionEvidence_recovery_92879F18_1(probe.TraversalTeleportAttempted,probe.TeleportFallbackUsed,probe.RecoveryExitAlreadySatisfied,probe.LearningV341ForcedEgressPhysicalWriterUsed,probe.UnifiedEgressForcedDistance,ForcedEgressRecoveryDistance,probe.IslandExitNominalClimbTopBridge);
            bool customAssist = FollowerCapabilityHelperRules.IsLearningV31WalkThroughNativeLocomotionEvidence_customAssist_92879F18_2(probe.AssistedReplayAttempted,probe.AssistedPartialNativeContinuation,probe.WalkThroughStepAssistAttempts,probe.WalkThroughSharpTurnGateCount);
            bool corridorActuated = FollowerCapabilityHelperRules.IsLearningV31WalkThroughNativeLocomotionEvidence_corridorActuated_92879F18_3(probe.WalkThroughTotalLength,probe.WalkThroughProgressS);
            return corridorActuated && !recovery && !customAssist && !probe.NativeLandingRejected;
