        private static bool WasLearningV330NativeActuatorActuallyAttempted(ProbeRuntime probe)
        {
            if (probe == null)
            {
                return false;
            }
            string kind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            if (string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return probe.JumpAttempted;
            }
            if (string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                return probe.NativeDropDownAttempted;
            }
            if (string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return IsLearningV31WalkThroughNativeLocomotionEvidence(probe);
            }
            if (string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase))
            {
                return probe.InjectedNativeVaultAttempted || probe.NativeTraversalStarted;
            }
            return probe.NativeTraversalStarted || probe.NativeDropDownAttempted ||
                   probe.InjectedNativeVaultAttempted;
        }

        private static bool IsLearningV3RetainableNativeSuccess(ProbeRuntime probe, TraversalCompletionMode completionMode)
        {
            if (probe == null || completionMode != TraversalCompletionMode.Native)
            {
                return false;
            }
            bool nativeActuatorEvidence = (WasLearningV330NativeActuatorActuallyAttempted(probe));
            bool recovery = FollowerCapabilityHelperRules.IsLearningV3RetainableNativeSuccess_recovery_5170C182_2(probe.TraversalTeleportAttempted,probe.TeleportFallbackUsed,probe.RecoveryExitAlreadySatisfied,probe.LearningV341ForcedEgressPhysicalWriterUsed,probe.UnifiedEgressForcedDistance,ForcedEgressRecoveryDistance,probe.IslandExitNominalClimbTopBridge);
            return nativeActuatorEvidence && !recovery &&
                   !probe.AssistedReplayAttempted &&
                   !probe.AssistedPartialNativeContinuation &&
                   !probe.NativePartialCrossingObserved &&
                   !probe.NativeLandingRejected;
        }

