        private static void RetireLearningV3SupersededProvenEdge(LearnedTraversalEdge promoted)
        {
            if ((promoted == null) || promoted.SupersedesProvenEdgeId <= 0)
            {
                return;
            }
            LearnedTraversalEdge previous = LearnedTraversalEdges.FirstOrDefault(edge =>
                edge != null && edge.Id == promoted.SupersedesProvenEdgeId);
            if (previous == null || previous.Id == promoted.Id || !IsLearningV3NativeProvenEdge(previous))
            {
                return;
            }
            if (IsTraversalEdgeActivelyReferenced(previous.Id))
            {
                WriteEvent("learningV3SupersededProvenRetireDeferred", null, new
                {
                    promotedEdgeId = promoted.Id,
                    previousEdgeId = previous.Id,
                    reason = "activeTraversalReference"
                });
                return;
            }
            WriteEvent("learningV3SupersededProvenRetired", null, new
            {
                promotedEdgeId = promoted.Id,
                previousEdgeId = previous.Id,
                previousExperienceKey = previous.ExperienceKey
            });
            RemoveLowValueTraversalEdge(previous, "learningV3SupersededNativeProven");
            {
                SaveLearningV31NativeProvenStore();
            }
        }

        private static bool TryBeginLearningV3NativeEntryCorrection(
