                return false;
            }

            if (TryRequestCapabilityFullRouteRetry(probe,"entryConvergenceFailed:"+source,true)) return true;
            edgeDirection = GetFlatDirection(edgeDirection);
            if (edgeDirection.sqrMagnitude < 0.5f)
            {
                edgeDirection = GetFlatDirection(rawEntry - probe.Player.Position);
            }
            if (edgeDirection.sqrMagnitude < 0.5f)
            {
                return false;
            }

            Vector3 correctionTarget = rawEntry - edgeDirection * LearningV3NativeEntryCorrectionStagingDistance;
            bool sampled = NavMesh.SamplePosition(
                correctionTarget, out NavMeshHit correctionHit,
                LearningV3NativeEntryCorrectionSampleRadius, NavMesh.AllAreas);
            bool dropDownCorrection = string.Equals(
                probe.RequestedTraversalKind, "DropDown", StringComparison.OrdinalIgnoreCase);
            float correctionVerticalTolerance = dropDownCorrection
                ? 0.35f
                : LearningV3NativeEntryCorrectionMaxSampleOffset;
            if (sampled &&
                GetPlanarDistance(correctionTarget, correctionHit.position) <= LearningV3NativeEntryCorrectionMaxSampleOffset &&
                Mathf.Abs(rawEntry.y - correctionHit.position.y) <= correctionVerticalTolerance)
            {
                correctionTarget = correctionHit.position;
            }
            else if (!IsFinite(correctionTarget))
            {
                correctionTarget = rawEntry;
            }

            probe.LearningV3EntryCorrectionAttempts++;
            probe.PoseRecoveryAttempts = 0;
            probe.PoseExclusiveOrientationAuthority = true;
            probe.NativeEntryConvergenceRejected = false;
            probe.NativeEntryConvergenceRejectReason = null;
            probe.StageStartedAt = Time.time;
            probe.RollingApproachLastProgressAt = Time.time;
            probe.RollingApproachLastDistance = distance;
            probe.RollingApproachLastLateralOffset = lateralEntryOffset;
            probe.RollingApproachLastAlignmentAngle = alignmentAngle;
            probe.PoseLastAlignmentAngle = float.MaxValue;
            probe.PoseLastAlignmentProgressAt = Time.time;

            try
            {
                probe.Bot.Mover?.BotMoverSprint("R1-001CBCABBE03",@probe?.Bot,false,false);
                probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-AB1B124217F5",@probe?.Bot);
                probe.Bot.Mover?.BotMoverStop("R1-9F706410ECCF",@probe?.Bot);
                probe.Bot.BotOwnerStopMove("R1-B89A847AC118",@probe?.Bot);
                if (probe.Bot.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-0DC498DF3282",@probe?.Bot,false);
                    probe.Bot.Mover.BotMoverGoToPointNoWay("R1-B54381E8D8F9",@probe?.Bot,correctionTarget);
                }
            }
            catch
            {
            }

            DriveTraversalPoseAcquisition(
                probe, edgeDirection, alignmentAngle,
                "learningV3NativeEntryCorrection:" + (source ?? "unknown"), true);
            WriteEvent("learningV3NativeEntryCorrectionStarted", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.RequestedTraversalKind,
                source = source ?? string.Empty,
                attempt = probe.LearningV3EntryCorrectionAttempts,
                maxAttempts = LearningV3NativeEntryCorrectionMaxAttempts,
                correctionTarget = Vec(correctionTarget),
                rawEntry = Vec(rawEntry),
                distance,
                alignmentAngle,
                lateralEntryOffset,
                forwardEntryProjection,
                action = "repositionAndReorientThenRetryNative"
            });
            return true;
        }

        private static void EmitLearningV2FreshSessionSummary(string reason)
        {
            ;
            TraversalExperienceRecord[] records = TraversalExperiences.Values
                .Where(record => record != null)
                .ToArray();
            LearningV322PersistentSkillEvidenceRecord[] persistentEvidence = LearningV322SkillEvidence.Values
                .Where(record => record != null)
                .ToArray();
            int nativeProvenSkillCount = LearnedTraversalEdges.Count(IsLearningV3NativeProvenEdge);
            int activeCandidateCount = LearnedTraversalEdges.Count(edge => edge != null && !IsLearningV3NativeProvenEdge(edge));
            object[] learningV322EvidenceByKind = persistentEvidence
                .GroupBy(record => string.IsNullOrWhiteSpace(record.Kind) ? "Unknown" : record.Kind)
                .OrderBy(group => group.Key, StringComparer.Ordinal)
                .Select(group =>
                {
                    int nativeAttempts = group.Sum(record => Math.Max(0, record.NativeAttempts));
                    int nativeSuccesses = group.Sum(record => Math.Max(0, record.NativeSuccesses));
                    return (object)new
                    {
                        kind = group.Key,
                        records = group.Count(),
                        nativeAttempts,
                        nativeSuccesses,
                        nativeFailures = group.Sum(record => Math.Max(0, record.NativeFailures)),
                        nativeRate = nativeSuccesses / (float)Math.Max(1, nativeAttempts),
                        assistedAttempts = group.Sum(record => Math.Max(0, record.AssistedAttempts)),
                        assistedPhysicalCompletions = group.Sum(record => Math.Max(0, record.AssistedPhysicalCompletions)),
                        teleportRescues = group.Sum(record => Math.Max(0, record.TeleportRescues)),
                        zeroShotAttempts = group.Sum(record => Math.Max(0, record.ZeroShotAttempts)),
                        zeroShotNativeSuccesses = group.Sum(record => Math.Max(0, record.ZeroShotNativeSuccesses)),
                        zeroShotAssistSalvages = group.Sum(record => Math.Max(0, record.ZeroShotAssistSalvages)),
                        zeroShotTeleportRescues = group.Sum(record => Math.Max(0, record.ZeroShotTeleportRescues)),
                        zeroShotFailures = group.Sum(record => Math.Max(0, record.ZeroShotFailures))
                    };
                })
                .ToArray();
            WriteEvent(("learningV3NativeProvenSessionSummary"), null, new
            {
                mode = LearningV2ModeName,
                reason = reason ?? string.Empty,
                activeSkillCount = (nativeProvenSkillCount),
                nativeProvenSkillCount,
                activeCandidateCount,
                revisionReplacementCount = LearnedTraversalEdges.Sum(edge => edge == null ? 0 : Math.Max(0, edge.DemonstrationRevision - 1)),
                experienceRecordCount = records.Length,
                attempts = learningV2AuditAttempts,
                nativeAttempts = learningV2AuditNativeAttempts,
                nativeSuccesses = learningV2AuditNativeSuccesses,
                assistedAttempts = learningV2AuditAssistedAttempts,
                assistedSuccesses = learningV2AuditAssistedSuccesses,
                assistedLearningPromotions = learningV2AuditAssistedSuccesses,
                assistedPhysicalCompletions = persistentEvidence.Sum(record => Math.Max(0, record.AssistedPhysicalCompletions)),
                teleportRecoveries = learningV2AuditTeleportRecoveries,
                persistentTeleportRescues = persistentEvidence.Sum(record => Math.Max(0, record.TeleportRescues)),
                persistentEvidenceRecords = persistentEvidence.Length,
                zeroShotAttempts = persistentEvidence.Sum(record => Math.Max(0, record.ZeroShotAttempts)),
                zeroShotNativeSuccesses = persistentEvidence.Sum(record => Math.Max(0, record.ZeroShotNativeSuccesses)),
                zeroShotAssistSalvages = persistentEvidence.Sum(record => Math.Max(0, record.ZeroShotAssistSalvages)),
                zeroShotTeleportRescues = persistentEvidence.Sum(record => Math.Max(0, record.ZeroShotTeleportRescues)),
                zeroShotFailures = persistentEvidence.Sum(record => Math.Max(0, record.ZeroShotFailures)),
                skillEvidenceByKind = learningV322EvidenceByKind,
                immutableAuditLedger = true,
                persistentReadsUsedForSelection = true,
                persistentWrites = true,
                legacyMixedPersistenceUsed = false,
                nativeProvenStorePath = (GetLearningV31NativeProvenStorePath()),
                skillEvidenceStorePath = (GetLearningV322SkillEvidencePath())
            });
        }

        private static int BeginTraversalDemonstrationRevision(LearnedTraversalEdge edge)
        {
            if (edge == null)
            {
                return 0;
            }

            string previousExperienceKey = edge.ExperienceKey;
            int previousRevision = Math.Max(1, edge.DemonstrationRevision);
            if (true)
            {
                if (true)
                {
                    // A player re-demonstration is still only a candidate. Do not inherit an
                    // ExperienceKey, Assist quality, failure score, or strategy prior.
                    if (!string.IsNullOrWhiteSpace(previousExperienceKey))
                    {
                        TraversalExperiences.Remove(previousExperienceKey);
                    }
                    edge.ExperienceKey = null;
                    LearningV2StrategyPriors.Remove(edge.Id);
                }
                else
                {
                    if (!string.IsNullOrWhiteSpace(previousExperienceKey) &&
                        TraversalExperiences.TryGetValue(previousExperienceKey, out TraversalExperienceRecord previousRecord) &&
                        previousRecord != null)
                    {
                        LearningV2StrategyPriors[edge.Id] = LearningV2StrategyPrior.Merge(
                            LearningV2StrategyPriors.TryGetValue(edge.Id, out LearningV2StrategyPrior existingPrior) ? existingPrior : null,
                            previousRecord);
                    }
                    edge.ExperienceKey = CreateTraversalExperienceKey();
                }
                TraversalExecutorExplorationLeases.Remove(edge.Id);
                TraversalRecentFarSideFailureCounts.Remove(edge.Id);
                TraversalRecentToxicSuppressUntil.Remove(edge.Id);
            }
            edge.DemonstrationRevision = Math.Max(1, edge.DemonstrationRevision + 1);
            if (true)
            {
                WriteEvent(true ? "learningV3CandidateRevisionReplaced" : "learningV2FreshRevisionReplaced", null, new
                {
                    edgeId = edge.Id,
                    kind = edge.Kind,
                    previousRevision,
                    revision = edge.DemonstrationRevision,
                    previousExperienceKey,
                    experienceKey = edge.ExperienceKey,
                    previousExperienceDiscarded = true && !string.IsNullOrWhiteSpace(previousExperienceKey),
                    previousExperienceRetainedAsSkillPrior = !true && !string.IsNullOrWhiteSpace(previousExperienceKey),
                    candidateOnly = true
                });
            }
            edge.HasSettledStart = false;
            edge.SettledStart = default(Vector3);
            edge.HasSettledEnd = false;
            edge.SettledEnd = default(Vector3);
            edge.SettledBreadcrumbSequence = 0;
            // Link-local verification belongs to this exact geometry revision. Previous-revision
            // strategy evidence is retained only through the bounded LearningV2StrategyPrior;
            // the new ExperienceKey remains revision-local and cannot mark new geometry verified.
            edge.Verified = false;
            edge.SuccessfulExecutions = 0;
            edge.NativeSuccessCount = 0;
            edge.AssistedSuccessCount = 0;
            edge.TeleportFallbackCount = 0;
            edge.FailedExecutions = 0;
            edge.WalkThroughCorridorSamples = new List<Vector3>();
            edge.EgressSamples = new List<Vector3>();
            edge.EgressSemanticSamples = new List<TraversalEgressSemanticSample>();
            edge.MotionSamples = new List<TraversalMotionSample>();
            edge.ObstacleFingerprint = null;
            edge.NativeVaultParameters = null;
            edge.ApproachDirection = Vector3.zero;
            edge.ApproachSpeed = 0f;
            edge.ApproachMode = null;
            edge.TraversalDuration = 0f;
            PendingTraversalSettledExitCaptures.Remove(edge.Id);
            TraversalExperienceRouteSuppressUntil.Remove(edge.Id);
            TraversalExperienceRouteRevalidationUntil[edge.Id] = Time.time + TraversalExperienceRevalidationLeaseSeconds;
            WriteEvent("traversalExperienceRevalidationArmed", null, new
            {
                edgeId = edge.Id,
                kind = edge.Kind,
                demonstrationRevision = edge.DemonstrationRevision,
                seconds = TraversalExperienceRevalidationLeaseSeconds,
                reason = "freshPlayerDemonstration"
            });
            return edge.DemonstrationRevision;
        }

        private static bool TrySampleCredibleDropDownTopEntry(
            Vector3 rawStart,
            Vector3 approachDirection,
            out Vector3 sampled)
        {
            sampled = default(Vector3);
            if (!IsFinite(rawStart))
            {
                return false;
            }

            Vector3 flatDirection = GetFlatDirection(approachDirection);
            float bestScore = float.PositiveInfinity;
            bool found = false;
            for (int i = 0; i < DropDownTopEntryProbeCount; i++)
            {
                Vector3 probe = rawStart;
                if (flatDirection.sqrMagnitude > 0.01f)
                {
                    probe -= flatDirection * (DropDownTopEntryProbeBackstep * i);
                }

                if (!NavMesh.SamplePosition(probe, out NavMeshHit hit, DropDownTopEntryProbeRadius, NavMesh.AllAreas))
                {
                    continue;
                }

                float vertical = Mathf.Abs(hit.position.y - rawStart.y);
                float planar = GetPlanarDistance(hit.position, rawStart);
                if (vertical > DropDownTopEntryMaxVerticalSampleOffset || planar > 1.25f)
                {
                    continue;
                }

                float score = vertical * 2f + planar;
                if (!found || score < bestScore)
                {
                    found = true;
                    bestScore = score;
                    sampled = hit.position;
                }
            }

            return found;
        }

        private static bool IsFollowerAlreadyBelowDropDownLanding(
            Vector3 followerPosition,
            Vector3 rawEntry,
            Vector3 rawExit,
            Vector3 sampledExit)
        {
            if (!IsFinite(followerPosition))
            {
                return false;
            }

            Vector3 landing = IsFinite(sampledExit) ? sampledExit : rawExit;
            if (!IsFinite(landing) || !IsFinite(rawExit))
            {
                return false;
            }

            // CompileFix32: height alone is not proof that a DropDown was crossed. A stale mover
            // snapback can put the follower below landing Y while still 5-8 m away on the wrong
            // side. Require local exit proximity or credible directed projection through the portal.
            if (followerPosition.y > landing.y + DropDownAlreadyBelowLandingMargin)
            {
                return false;
            }

            float landingDistance = GetPlanarDistance(followerPosition, landing);
            float rawExitDistance = GetPlanarDistance(followerPosition, rawExit);
            if (Mathf.Min(landingDistance, rawExitDistance) <= 1.75f)
            {
                return true;
            }

            if (!IsFinite(rawEntry))
            {
                return false;
            }

            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            float length = axis.magnitude;
            if (length < 0.25f)
            {
                return false;
            }

            Vector3 direction = axis / length;
            Vector3 fromEntry = followerPosition - rawEntry;
            fromEntry.y = 0f;
            float projection = Vector3.Dot(fromEntry, direction);
            Vector3 lateralVector = fromEntry - direction * projection;
            float lateral = lateralVector.magnitude;
            float requiredProjection = Mathf.Max(0.12f, length - 0.30f);
            return projection >= requiredProjection &&
                   lateral <= 1.50f &&
                   rawExitDistance <= 3.00f;
        }

        private static bool IsMateriallyDifferentFreshWalkThrough(
            LearnedTraversalEdge existing,
            Vector3 rawStart,
            Vector3 rawEnd,
            List<Vector3> candidateSamples)
        {
            if (existing == null || candidateSamples == null || candidateSamples.Count < 2 ||
                existing.WalkThroughCorridorSamples == null || existing.WalkThroughCorridorSamples.Count < 2)
            {
                return false;
            }

            List<Vector3> candidate = candidateSamples.Where(IsFinite).ToList();
            List<Vector3> stored = existing.WalkThroughCorridorSamples.Where(IsFinite).ToList();
            if (candidate.Count < 2 || stored.Count < 2)
            {
                return false;
            }

            float endpointShift = Mathf.Max(
                GetPlanarDistance(rawStart, existing.RawStart),
                GetPlanarDistance(rawEnd, existing.RawEnd));
            float maxCandidateDeviation = 0f;
            foreach (Vector3 point in candidate)
            {
                float nearest = stored.Min(storedPoint => GetPlanarDistance(point, storedPoint));
                maxCandidateDeviation = Mathf.Max(maxCandidateDeviation, nearest);
            }

            bool sampleShapeChanged = Mathf.Abs(candidate.Count - stored.Count) >= 2 && maxCandidateDeviation >= 0.20f;
            bool endpointAndShapeChanged = endpointShift >= 0.12f && maxCandidateDeviation >= 0.22f;
            bool stronglyDifferentShape = maxCandidateDeviation >= 0.42f;
            return sampleShapeChanged || endpointAndShapeChanged || stronglyDifferentShape;
        }

        private static int RememberLearnedTraversalEdge(
            Vector3 rawStart,
            Vector3 rawEnd,
            string kind,
            bool requireSameKindForRefresh = false,
            PlayerTraversalMotionProfile motion = null,
            List<Vector3> walkThroughCorridorSamples = null,
            bool runtimeOnlyTraversal = false,
            int runtimeAlternativeParentEdgeId = 0,
            string runtimeAuthoritySource = null)
        {
            if (!raidActive || !IsFinite(rawStart) || !IsFinite(rawEnd))
            {
                return 0;
            }

            string normalizedKind = string.IsNullOrWhiteSpace(kind) ? "Vault" : kind;
            bool walkThrough = string.Equals(normalizedKind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            float requiredPose=walkThrough?FollowerCapabilityPosturePolicy.Normalize(motion?.RequiredPose??1f):1f;
            bool jump = string.Equals(normalizedKind, "Jump", StringComparison.OrdinalIgnoreCase);
            bool dropDownKind = string.Equals(normalizedKind, "DropDown", StringComparison.OrdinalIgnoreCase);
            float displacement = Vector3.Distance(rawStart, rawEnd);
            float minimumDisplacement = walkThrough ? WalkThroughCandidateMinDistance : 0.45f;
            float maximumDisplacement = walkThrough
                ? WalkThroughEpisodeMaxDirectDistance
                : (jump ? PlayerJumpLearnedMaxDirectDistance : (dropDownKind ? 4.75f : 4.0f));
            if (displacement < minimumDisplacement || displacement > maximumDisplacement)
            {
                return 0;
            }

            // Player traversal is the authority for persistence. A NavMesh seam is exactly where
            // one endpoint can legitimately fail SamplePosition, so endpoint sampling must never
            // discard the demonstrated traversal. Keep sampled anchors when available and raw
            // player positions otherwise. Runtime NavMesh-link publication performs its own
            // best-effort endpoint sampling; deterministic exact-exit recovery can always use raw B.
            const float endpointSampleRadius = 2.25f;
            bool startSampled = NavMesh.SamplePosition(rawStart, out NavMeshHit startHit, endpointSampleRadius, NavMesh.AllAreas);
            bool endSampled = NavMesh.SamplePosition(rawEnd, out NavMeshHit endHit, endpointSampleRadius, NavMesh.AllAreas);
            bool dropDownTopEntryCredible = true;
            Vector3 a = startSampled ? startHit.position : rawStart;
            Vector3 b = endSampled ? endHit.position : rawEnd;

            // R9.7 DropDown topology guard. NavMesh.SamplePosition can project a ledge start
            // vertically through the floor and return the lower landing polygon. That turns a
            // one-way drop into a fake same-level edge and makes followers on the lower floor
            // re-enter the traversal. Only accept a top entry close to the demonstrated RawStart.
            if (dropDownKind)
            {
                dropDownTopEntryCredible = TrySampleCredibleDropDownTopEntry(
                    rawStart,
                    motion?.ApproachDirection ?? GetFlatDirection(rawEnd - rawStart),
                    out Vector3 credibleTopEntry);
                if (dropDownTopEntryCredible)
                {
                    a = credibleTopEntry;
                    startSampled = true;
                }
                else
                {
                    a = rawStart;
                    startSampled = false;
                }
            }

            if (Vector3.Distance(a, b) < 0.35f)
            {
                // Nearest-navmesh projection can collapse both sides onto the same polygon. Keep
                // the player's real endpoints instead of rejecting a passage that was just used.
                a = rawStart;
                b = rawEnd;
            }

            WriteEvent("playerTraversalEndpointSampling", null, new
            {
                kind = normalizedKind,
                startSampled,
                endSampled,
                dropDownTopEntryCredible,
                startVerticalOffset = startSampled ? Mathf.Abs(a.y - rawStart.y) : -1f,
                sampledStart = Vec(a),
                sampledEnd = Vec(b),
                rawStart = Vec(rawStart),
                rawEnd = Vec(rawEnd)
            });

            PruneLearnedTraversalEdges();
            int currentPlayerTraversalSequence = ++playerTraversalSequence;

            // R8.7: WalkThrough is directional knowledge. A reverse passage through the same
            // physical seam is a sibling strategy, not permission to overwrite the verified
            // forward corridor. Other traversal kinds keep their historical bidirectional match.
            bool directionalKind = walkThrough ||
                string.Equals(normalizedKind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(normalizedKind, "Jump", StringComparison.OrdinalIgnoreCase);
            Func<LearnedTraversalEdge, bool> sameGeometry = edge => edge != null &&
                (directionalKind
                    ? (Vector3.Distance(edge.A, a) <= 1.25f && Vector3.Distance(edge.B, b) <= 1.25f)
                    : ((Vector3.Distance(edge.A, a) <= 1.25f && Vector3.Distance(edge.B, b) <= 1.25f) ||
                       (Vector3.Distance(edge.A, b) <= 1.25f && Vector3.Distance(edge.B, a) <= 1.25f)));
            // R8.2 Kind Lock: geometry proximity may identify the same obstacle, but it must never
            // authorize a cross-kind overwrite. A Jump, Climb, Vault and WalkThrough may coexist as
            // sibling strategies around one obstacle and retain independent ExperienceKey histories.
            LearnedTraversalEdge exactFreshSameRaid = walkThrough
                ? LearnedTraversalEdges
                    .Where(edge => edge != null &&
                        string.Equals(edge.Kind, normalizedKind, StringComparison.OrdinalIgnoreCase) &&
                        FollowerCapabilityPosturePolicy.Same(edge.RequiredPose,requiredPose) &&
                        edge.PlayerTraversalSequence > 0 &&
                        currentPlayerTraversalSequence - edge.PlayerTraversalSequence <= 2 &&
                        GetPlanarDistance(edge.RawStart, rawStart) <= 0.08f &&
                        GetPlanarDistance(edge.RawEnd, rawEnd) <= 0.08f &&
                        Mathf.Abs(edge.RawStart.y - rawStart.y) <= 0.10f &&
                        Mathf.Abs(edge.RawEnd.y - rawEnd.y) <= 0.10f)
                    .OrderByDescending(edge => edge.PlayerTraversalSequence)
                    .FirstOrDefault()
                : null;
            if (exactFreshSameRaid != null)
            {
                exactFreshSameRaid.PlayerValidated = true;
                exactFreshSameRaid.PlayerTraversalSequence = currentPlayerTraversalSequence;
                exactFreshSameRaid.CreatedAt = Time.time;
                WriteEvent("playerTraversalExactFreshDuplicateSuppressed", null, new
                {
                    edgeId = exactFreshSameRaid.Id,
                    kind = exactFreshSameRaid.Kind,
                    rawStart = Vec(rawStart),
                    rawEnd = Vec(rawEnd),
                    reason = "sameRaidExactGeometry"
                });
                SavePersistentTraversalLinks();
                return exactFreshSameRaid.Id;
            }

            int learningV3SupersedesProvenEdgeId = 0;
            LearnedTraversalEdge existing = (LearnedTraversalEdges
                    .Where(edge => edge != null &&
                        (edge.PlayerTraversalSequence > 0 ||
                         ((IsLearningV3NativeProvenEdge(edge)))) &&
                        string.Equals(edge.Kind, normalizedKind, StringComparison.OrdinalIgnoreCase) &&
                        FollowerCapabilityPosturePolicy.Same(edge.RequiredPose,requiredPose) &&
                        !IsTraversalEdgeActivelyReferenced(edge.Id) &&
                        IsLearningV2SameLocalSkill(edge, rawStart, rawEnd, directionalKind))
                    .OrderByDescending(edge => IsLearningV3NativeProvenEdge(edge) ? 1 : 0)
                    .ThenByDescending(edge => edge.PlayerTraversalSequence)
                    .FirstOrDefault());
            if ((existing != null))
            {
                WriteEvent("learningV2FreshRevisionCandidateMatched", null, new
                {
                    edgeId = existing.Id,
                    kind = existing.Kind,
                    previousRevision = existing.DemonstrationRevision,
                    previousStart = Vec(existing.RawStart),
                    previousEnd = Vec(existing.RawEnd),
                    candidateStart = Vec(rawStart),
                    candidateEnd = Vec(rawEnd)
                });
            }
            if ((existing != null) && IsLearningV3NativeProvenEdge(existing))
            {
                if (IsLearningV3ExactProvenRedemonstration(existing, rawStart, rawEnd))
                {
                    existing.PlayerValidated = true;
                    existing.PlayerTraversalSequence = currentPlayerTraversalSequence;
                    existing.CreatedAt = Time.time;
                    WriteEvent("learningV3ProvenRedemonstrationSuppressed", null, new
                    {
                        edgeId = existing.Id,
                        kind = existing.Kind,
                        experienceKey = existing.ExperienceKey,
                        nativeSuccesses = existing.NativeSuccessCount,
                        reason = "exactNativeProvenGeometryPreserved"
                    });
                    return existing.Id;
                }

                learningV3SupersedesProvenEdgeId = existing.Id;
                WriteEvent("learningV3ProvenSkillShadowCandidateRequired", null, new
                {
                    previousEdgeId = existing.Id,
                    kind = existing.Kind,
                    previousExperienceKey = existing.ExperienceKey,
                    previousNativeSuccesses = existing.NativeSuccessCount,
                    candidateStart = Vec(rawStart),
                    candidateEnd = Vec(rawEnd),
                    reason = "provenGeometryCannotBeOverwrittenUntilNewNativeSuccess"
                });
                existing = null;
            }

            if ((existing != null) && IsTraversalEdgeActivelyReferenced(existing.Id))
            {
                WriteEvent("learningV2RevisionReplacementDeferredActiveEdge", null, new
                {
                    edgeId = existing.Id,
                    kind = existing.Kind,
                    revision = existing.DemonstrationRevision,
                    rawStart = Vec(existing.RawStart),
                    rawEnd = Vec(existing.RawEnd),
                    reason = "activeTraversalReference"
                });
                existing = null;
            }
            LearnedTraversalEdge conflictingKindEdge = LearnedTraversalEdges.FirstOrDefault(edge =>
                sameGeometry(edge) && !string.Equals(edge.Kind, normalizedKind, StringComparison.OrdinalIgnoreCase));
            if (existing == null && conflictingKindEdge != null)
            {
                WriteEvent("playerTraversalSiblingEdgeCreated", null, new
                {
                    kind = normalizedKind,
                    start = Vec(rawStart),
                    end = Vec(rawEnd),
                    displacement,
                    siblingEdgeId = conflictingKindEdge.Id,
                    siblingKind = conflictingKindEdge.Kind,
                    kindLock = true
                });
            }

            // CompileFix49: a proven WalkThrough remains frozen against minor jitter, but materially
            // different fresh player corridor geometry must survive as a new directional sibling.
            // This prevents a 60+ success historical edge from swallowing the exact route the player
            // just used across a different obstacle/topology seam.
            ;

            if (existing != null)
            {
                int historicalPhysicalSuccesses = GetTraversalPhysicalSuccessCount(existing);
                bool freezeVerifiedWalkThrough = (false);
                if (freezeVerifiedWalkThrough)
                {
                    existing.PlayerValidated = true;
                    existing.Disabled = false;
                    existing.PlayerTraversalSequence = currentPlayerTraversalSequence;
                    WriteEvent("walkThroughVerifiedGeometryPreserved", null, new
                    {
                        edgeId = existing.Id,
                        experienceKey = existing.ExperienceKey,
                        candidateStart = Vec(rawStart),
                        candidateEnd = Vec(rawEnd),
                        storedStart = Vec(existing.RawStart),
                        storedEnd = Vec(existing.RawEnd),
                        successes = existing.SuccessfulExecutions,
                        historicalPhysicalSuccesses,
                        candidateRejectedAsRefresh = true
                    });
                    SavePersistentTraversalLinks();
                    return existing.Id;
                }

                existing.A = a;
                existing.B = b;
                ;
                int historicalPhysicalSuccessesBeforeRefresh = GetTraversalPhysicalSuccessCount(existing);
                float previousBotValidatedApproachSpeed = existing.ApproachSpeed;
                string previousBotValidatedApproachMode = existing.ApproachMode;
                bool preserveProvenJumpLanding = (false);
                Vector3 previousProvenJumpSettledEnd = existing.SettledEnd;
                int previousProvenJumpSettledSequence = existing.SettledBreadcrumbSequence;
                List<Vector3> previousProvenJumpEgress = preserveProvenJumpLanding && existing.EgressSamples != null
                    ? existing.EgressSamples.Where(IsFinite).ToList()
                    : null;
                List<TraversalEgressSemanticSample> previousProvenJumpSemanticEgress = preserveProvenJumpLanding && existing.EgressSemanticSamples != null
                    ? existing.EgressSemanticSamples.Where(sample => sample != null).Select(CloneTraversalEgressSemanticSample).ToList()
                    : null;
                int demonstrationRevision = BeginTraversalDemonstrationRevision(existing);
                existing.RawStart = rawStart;
                existing.RawEnd = rawEnd;
                // Kind is immutable after creation. The lookup above already required same-kind.
                existing.CreatedAt = Time.time;
                existing.PlayerValidated = true;
                existing.Disabled = dropDownKind && !dropDownTopEntryCredible;
                existing.FailedExecutions = 0;
                existing.PlayerTraversalSequence = currentPlayerTraversalSequence;
                if (string.Equals(existing.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                    Mathf.Abs(existing.RawEnd.y - existing.RawStart.y) > WalkThroughReclassificationVerticalDelta)
                {
                    existing.Disabled = true;
                }
                existing.RequiredPose=requiredPose;
                existing.ApproachDirection = motion?.ApproachDirection ?? GetFlatDirection(rawEnd - rawStart);
                float candidateApproachSpeed = motion?.ApproachSpeed ?? 0f;
                string candidateApproachMode = motion?.ApproachMode;
                bool vaultOrClimbRefresh = string.Equals(existing.Kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                                           string.Equals(existing.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
                bool preserveProvenBotApproach = (false);
                existing.ApproachSpeed = preserveProvenBotApproach
                    ? previousBotValidatedApproachSpeed
                    : candidateApproachSpeed;
                existing.ApproachMode = preserveProvenBotApproach
                    ? previousBotValidatedApproachMode
                    : candidateApproachMode;
                existing.TraversalDuration = motion?.TraversalDuration ?? 0f;
                if (preserveProvenBotApproach)
                {
                    WriteEvent("playerTraversalHighSpeedApproachHeldForBotValidation", null, new
                    {
                        edgeId = existing.Id,
                        kind = existing.Kind,
                        physicalSuccesses = historicalPhysicalSuccessesBeforeRefresh,
                        preservedSpeed = previousBotValidatedApproachSpeed,
                        preservedMode = previousBotValidatedApproachMode,
                        candidateSpeed = candidateApproachSpeed,
                        candidateMode = candidateApproachMode
                    });
                }
                existing.MotionSamples = motion?.MotionSamples != null
                    ? motion.MotionSamples.Where(sample => sample != null && IsFinite(sample.LocalOffset)).Select(CloneTraversalMotionSample).ToList()
                    : new List<TraversalMotionSample>();
                existing.ObstacleFingerprint = CloneTraversalObstacleFingerprint(motion?.ObstacleFingerprint);
                existing.NativeVaultParameters = CloneNativeVaultParameters(motion?.NativeVaultParameters);
                WriteEvent("playerTraversalEdgeRefreshed", null, new
                {
                    edgeId = existing.Id,
                    kind = existing.Kind,
                    demonstrationRevision,
                    linkVerificationReset = true,
                    a = Vec(existing.A),
                    b = Vec(existing.B),
                    displacement
                });
                PrepareSettledAnchorsForLearnedEdge(existing);
                if (preserveProvenJumpLanding && !existing.HasSettledEnd &&
                    IsCredibleSettledExit(existing.Kind, existing.RawStart, existing.RawEnd, previousProvenJumpSettledEnd))
                {
                    existing.HasSettledEnd = true;
                    existing.SettledEnd = previousProvenJumpSettledEnd;
                    existing.SettledBreadcrumbSequence = previousProvenJumpSettledSequence;
                    if ((existing.EgressSamples == null || existing.EgressSamples.Count == 0) && previousProvenJumpEgress != null)
                    {
                        existing.EgressSamples = previousProvenJumpEgress;
                    }
                    if ((existing.EgressSemanticSamples == null || existing.EgressSemanticSamples.Count == 0) && previousProvenJumpSemanticEgress != null)
                    {
                        existing.EgressSemanticSamples = previousProvenJumpSemanticEgress;
                    }
                    WriteEvent("provenJumpLandingPreservedAcrossRefresh", null, new
                    {
                        edgeId = existing.Id,
                        experienceKey = existing.ExperienceKey,
                        demonstrationRevision,
                        historicalPhysicalSuccesses = historicalPhysicalSuccessesBeforeRefresh,
                        rawExit = Vec(existing.RawEnd),
                        preservedSettledEnd = Vec(existing.SettledEnd)
                    });
                }
                if (!existing.Disabled && string.Equals(existing.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    RecordPrivateWalkThroughAvailable(existing, "refresh");
                }
                else if (existing.Disabled && string.Equals(existing.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    FollowerRuntimeNavMeshLinks.Remove(existing.Id);
                    WriteEvent("traversalEdgeQuarantinedForReclassification", null, new
                    {
                        edgeId = existing.Id,
                        kind = existing.Kind,
                        suggestedKind = "Drop",
                        verticalDelta = Mathf.Abs(existing.RawEnd.y - existing.RawStart.y),
                        threshold = WalkThroughReclassificationVerticalDelta
                    });
                }
                SavePersistentTraversalLinks();
                return existing.Id;
            }

            LearnedTraversalEdge learned = new LearnedTraversalEdge
            {
                Id = ++learnedTraversalEdgeSequence,
                ExperienceKey = (null),
                SupersedesProvenEdgeId = learningV3SupersedesProvenEdgeId,
                DemonstrationRevision = 1,
                Kind = normalizedKind,
                RequiredPose = requiredPose,
                A = a,
                B = b,
                RawStart = rawStart,
                RawEnd = rawEnd,
                CreatedAt = Time.time,
                PlayerValidated = true,
                Verified = false,
                Disabled = (string.Equals(normalizedKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                            Mathf.Abs(rawEnd.y - rawStart.y) > WalkThroughReclassificationVerticalDelta) ||
                           (dropDownKind && !dropDownTopEntryCredible),
                SuccessfulExecutions = 0,
                FailedExecutions = 0,
                PlayerTraversalSequence = currentPlayerTraversalSequence,
                ApproachDirection = motion?.ApproachDirection ?? GetFlatDirection(rawEnd - rawStart),
                ApproachSpeed = motion?.ApproachSpeed ?? 0f,
                ApproachMode = motion?.ApproachMode,
                TraversalDuration = motion?.TraversalDuration ?? 0f,
                MotionSamples = motion?.MotionSamples != null
                    ? motion.MotionSamples.Where(sample => sample != null && IsFinite(sample.LocalOffset)).Select(CloneTraversalMotionSample).ToList()
                    : new List<TraversalMotionSample>(),
                ObstacleFingerprint = CloneTraversalObstacleFingerprint(motion?.ObstacleFingerprint),
                NativeVaultParameters = CloneNativeVaultParameters(motion?.NativeVaultParameters),
                RuntimeOnlyTraversal = runtimeOnlyTraversal,
                RuntimeAlternativeParentEdgeId = runtimeAlternativeParentEdgeId,
                RuntimeAuthoritySource = runtimeAuthoritySource
            };
            LearnedTraversalEdges.Add(learned);
            PrepareSettledAnchorsForLearnedEdge(learned);
            TrimLearnedTraversalEdgesToLimit();

            if (!learned.Disabled && string.Equals(learned.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                RecordPrivateWalkThroughAvailable(learned, "learned");
            }
            else if (learned.Disabled && string.Equals(learned.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                WriteEvent("traversalEdgeQuarantinedForReclassification", null, new
                {
                    edgeId = learned.Id,
                    kind = learned.Kind,
                    suggestedKind = "Drop",
                    verticalDelta = Mathf.Abs(learned.RawEnd.y - learned.RawStart.y),
                    threshold = WalkThroughReclassificationVerticalDelta
                });
            }
            SavePersistentTraversalLinks();
            Logger.LogInfo(
                learned.RuntimeOnlyTraversal
                    ? $"[TraversalLink] Runtime-only current-episode alternative edge={learned.Id} kind={learned.Kind} " +
                      $"rawStart=({rawStart.x:0.00},{rawStart.y:0.00},{rawStart.z:0.00}) " +
                      $"rawEnd=({rawEnd.x:0.00},{rawEnd.y:0.00},{rawEnd.z:0.00})."
                    : (($"[TraversalLink] {(("LearningV3 candidate"))} edge={learned.Id} kind={learned.Kind} " +
                          $"rawStart=({rawStart.x:0.00},{rawStart.y:0.00},{rawStart.z:0.00}) " +
                          $"rawEnd=({rawEnd.x:0.00},{rawEnd.y:0.00},{rawEnd.z:0.00}).")));
            {
                WriteEvent(("learningV3CandidateObserved"), null, new
                {
                    edgeId = learned.Id,
                    experienceKey = learned.ExperienceKey,
                    kind = learned.Kind,
                    revision = learned.DemonstrationRevision,
                    candidateOnly = true,
                    supersedesProvenEdgeId = learned.SupersedesProvenEdgeId,
                    rawStart = Vec(learned.RawStart),
                    rawEnd = Vec(learned.RawEnd)
                });
            }
            WriteEvent(("playerTraversalCandidateObserved"), null, new
            {
                edgeId = learned.Id,
                kind = learned.Kind,
                demonstrationRevision = learned.DemonstrationRevision,
                playerValidated = learned.PlayerValidated,
                a = Vec(learned.A),
                b = Vec(learned.B),
                rawStart = Vec(rawStart),
                rawEnd = Vec(rawEnd),
                displacement,
                runtimeOnly = learned.RuntimeOnlyTraversal,
                runtimeAlternativeParentEdgeId = learned.RuntimeAlternativeParentEdgeId,
                persistentLearningChanged = !learned.RuntimeOnlyTraversal
            });
            return learned.Id;
        }

        private static void PrepareSettledAnchorsForLearnedEdge(LearnedTraversalEdge edge)
        {
            if (edge == null || !edge.PlayerValidated)
            {
                return;
            }

            bool walkThrough = string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            bool dropDown = string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase);
            bool extendedJumpEgress =
                string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                edge.RawEnd.y - edge.RawStart.y >= JumpExtendedEgressRiseThreshold;
            bool captureBridgeEgress = extendedJumpEgress ||
                string.Equals(edge.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
            Vector3 settledStart;
            bool haveSettledStart = dropDown
                ? TrySampleCredibleDropDownTopEntry(edge.RawStart, edge.ApproachDirection, out settledStart)
                : TrySampleTraversalSettledAnchor(edge.RawStart, walkThrough ? 0.80f : TraversalSettledCaptureNavRadius, out settledStart);
            if (haveSettledStart)
            {
                edge.HasSettledStart = true;
                edge.SettledStart = settledStart;
                if (dropDown)
                {
                    edge.A = settledStart;
                }
            }
            else if (dropDown)
            {
                edge.Disabled = true;
            }

            if (walkThrough)
            {
                if (TrySampleTraversalSettledAnchor(edge.RawEnd, 0.80f, out Vector3 settledEnd) &&
                    IsCredibleWalkThroughTerminalConnector(
                        edge.RawStart, edge.RawEnd, settledEnd, edge.WalkThroughCorridorSamples))
                {
                    edge.HasSettledEnd = true;
                    edge.SettledEnd = settledEnd;
                    edge.SettledBreadcrumbSequence = breadcrumbSequence;
                }

                // V1.3.22: a WalkThrough corridor owns its complete start/end provenance. Never let
                // a later unrelated grounded breadcrumb retroactively become this corridor's exit;
                // that was the source of one breadcrumb being assigned to several micro-edges.
                PendingTraversalSettledExitCaptures.Remove(edge.Id);
                return;
            }

            Vector3 direction = GetFlatDirection(edge.RawEnd - edge.RawStart);
            if (extendedJumpEgress &&
                !TrySampleTraversalSettledAnchor(edge.RawEnd, JumpPlatformRawExitStableNavRadius, out _))
            {
                edge.Disabled = true;
                WriteEvent("playerJumpPlatformLandingPending", null, new
                {
                    edgeId = edge.Id,
                    rawExit = Vec(edge.RawEnd),
                    disabledUntilEgressCaptured = true
                });
            }

            PendingTraversalSettledExitCaptures[edge.Id] = new PendingTraversalSettledExitCapture
            {
                EdgeId = edge.Id,
                DemonstrationRevision = Math.Max(1, edge.DemonstrationRevision),
                Kind = edge.Kind,
                RawExit = edge.RawEnd,
                Direction = direction.sqrMagnitude > 0.5f ? direction : Vector3.forward,
                ArmedAt = Time.time,
                ExpiresAt = Time.time + (captureBridgeEgress ? JumpExtendedEgressTimeout : TraversalSettledCaptureTimeout),
                MinimumBreadcrumbSequence = breadcrumbSequence + 1,
                PlayerTraversalSequence = edge.PlayerTraversalSequence,
                ExtendedJumpEgress = extendedJumpEgress,
                CaptureBridgeEgress = captureBridgeEgress,
                StableNavSamples = 0,
                // R8.12.2: every EgressSamples[i] must have EgressSemanticSamples[i].
                // RawExit is already stored separately and must not be an unpaired sentinel.
                EgressSamples = new List<Vector3>(),
                EgressSemanticSamples = new List<TraversalEgressSemanticSample>()
            };
        }

        private static bool TrySampleTraversalSettledAnchor(Vector3 requested, float radius, out Vector3 anchor)
        {
            anchor = default;
            if (!IsFinite(requested) ||
                !NavMesh.SamplePosition(requested, out NavMeshHit hit, radius, NavMesh.AllAreas))
            {
                return false;
            }

            if (Mathf.Abs(hit.position.y - requested.y) > TraversalSettledCaptureMaxNavVertical)
            {
                return false;
            }

            anchor = hit.position;
            return true;
        }

        private static bool IsCredibleJumpLandingForRefresh(Vector3 rawExit, Vector3 settledExit)
        {
            if (!IsFinite(rawExit) || !IsFinite(settledExit))
            {
                return false;
            }

            return GetPlanarDistance(rawExit, settledExit) <= JumpPreservedLandingMaxPlanarDistance &&
                   Mathf.Abs(settledExit.y - rawExit.y) <= JumpPreservedLandingMaxVerticalDelta;
        }

        private static void UpdatePendingTraversalSettledExitCaptures(PlayerBreadcrumbNode node)
        {
            if (node == null || PendingTraversalSettledExitCaptures.Count == 0)
            {
                return;
            }

            foreach (int edgeId in PendingTraversalSettledExitCaptures.Keys.ToArray())
            {
                if (!PendingTraversalSettledExitCaptures.TryGetValue(edgeId, out PendingTraversalSettledExitCapture pending) || pending == null)
                {
                    continue;
                }

                LearnedTraversalEdge revisionEdge = LearnedTraversalEdges.FirstOrDefault(
                    candidate => candidate != null && candidate.Id == edgeId);
                if (revisionEdge == null || revisionEdge.DemonstrationRevision != pending.DemonstrationRevision)
                {
                    PendingTraversalSettledExitCaptures.Remove(edgeId);
                    WriteEvent("playerTraversalSettledExitCaptureDiscarded", null, new
                    {
                        edgeId,
                        pendingRevision = pending.DemonstrationRevision,
                        currentRevision = revisionEdge?.DemonstrationRevision ?? 0,
                        reason = revisionEdge == null ? "edgeMissing" : "demonstrationRevisionSuperseded"
                    });
                    continue;
                }

                if (Time.time > pending.ExpiresAt)
                {
                    LearnedTraversalEdge timedOutEdge = revisionEdge;
                    bool platformEgressCaptured = false;
                    if (pending.ExtendedJumpEgress && timedOutEdge != null)
                    {
                        List<Vector3> platformSamples = pending.EgressSamples != null
                            ? pending.EgressSamples.Where(IsFinite).ToList()
                            : new List<Vector3>();
                        float platformProgress = platformSamples.Count > 0
                            ? GetPlanarDistance(pending.RawExit, platformSamples[platformSamples.Count - 1])
                            : 0f;
                        if (platformSamples.Count >= JumpPlatformEgressMinSamples &&
                            platformProgress >= JumpPlatformEgressMinPlanarProgress)
                        {
                            timedOutEdge.EgressSamples = platformSamples;
                            timedOutEdge.EgressSemanticSamples = pending.EgressSemanticSamples != null
                                ? pending.EgressSemanticSamples
                                    .Where(sample => sample != null && IsFinite(sample.Position))
                                    .Select(CloneTraversalEgressSemanticSample)
                                    .ToList()
                                : new List<TraversalEgressSemanticSample>();
                            timedOutEdge.Disabled = false;
                            platformEgressCaptured = true;
                            SavePersistentTraversalLinks();
                            WriteEvent("playerJumpPlatformEgressCaptured", null, new
                            {
                                edgeId,
                                rawExit = Vec(pending.RawExit),
                                sampleCount = timedOutEdge.EgressSamples.Count,
                                semanticSampleCount = timedOutEdge.EgressSemanticSamples.Count,
                                platformProgress,
                                hasSettledExit = false
                            });
                        }
                        else
                        {
                            timedOutEdge.Disabled = true;
                            SavePersistentTraversalLinks();
                            WriteEvent("playerTraversalEdgeQuarantinedIncompleteJump", null, new
                            {
                                edgeId,
                                rawExit = Vec(pending.RawExit),
                                sampleCount = platformSamples.Count,
                                platformProgress,
                                reason = "noStableExitOrPlatformEgress"
                            });
                        }
                    }
                    PendingTraversalSettledExitCaptures.Remove(edgeId);
                    WriteEvent("playerTraversalSettledExitUnavailable", null, new
                    {
                        edgeId,
                        rawExit = Vec(pending.RawExit),
                        reason = platformEgressCaptured ? "platformEgressCapturedWithoutNavMesh" : "captureTimeout"
                    });
                    continue;
                }

                bool vaultLandingResume = string.Equals(pending.Kind, "Vault", StringComparison.OrdinalIgnoreCase);
                bool climbLandingResume = string.Equals(pending.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
                bool jumpLandingResume = string.Equals(pending.Kind, "Jump", StringComparison.OrdinalIgnoreCase);
                bool extendedJumpEgress = pending.ExtendedJumpEgress;
                bool captureBridgeEgress = pending.CaptureBridgeEgress;
                float minimumDelay = extendedJumpEgress ? JumpExtendedEgressMinDelay : TraversalSettledCaptureMinDelay;
                float maximumDistance = captureBridgeEgress ? JumpExtendedEgressMaxDistance : TraversalSettledCaptureMaxDistance;

                if (node.Sequence < pending.MinimumBreadcrumbSequence ||
                    Vector3.Distance(node.Position, pending.RawExit) > maximumDistance)
                {
                    continue;
                }

                if (jumpLandingResume &&
                    Time.time - pending.ArmedAt >= JumpRollingLandingMinDelay &&
                    node.Grounded &&
                    !IsTraversalStateName(node.State) &&
                    IsLocomotionResumeStateName(node.State) &&
                    IsFinite(node.Position))
                {
                    float jumpPlanarFromExit = GetPlanarDistance(node.Position, pending.RawExit);
                    Vector3 jumpContinuation = node.Position - pending.RawExit;
                    jumpContinuation.y = 0f;
                    float jumpForwardContinuation = Vector3.Dot(jumpContinuation, pending.Direction);
                    if (jumpPlanarFromExit >= JumpRollingLandingMinPlanarContinuation &&
                        jumpPlanarFromExit <= JumpRollingLandingMaxPlanarDistance &&
                        jumpForwardContinuation >= JumpRollingLandingMinForwardContinuation &&
                        TrySampleTraversalSettledAnchor(node.Position, TraversalSettledCaptureNavRadius, out Vector3 rollingLanding) &&
                        Mathf.Abs(rollingLanding.y - node.Position.y) <= JumpRollingLandingMaxNavVertical)
                    {
                        LearnedTraversalEdge jumpEdge = revisionEdge;
                        jumpEdge.HasSettledEnd = true;
                        jumpEdge.SettledEnd = rollingLanding;
                        jumpEdge.SettledBreadcrumbSequence = node.Sequence;
                        jumpEdge.PlayerValidated = true;
                        jumpEdge.Disabled = false;
                        // The landing itself terminates this Jump. Subsequent platform movement is
                        // intentionally left in the breadcrumb stream so it can become the next
                        // DropDown/WalkThrough/etc. chain edge.
                        jumpEdge.EgressSamples = new List<Vector3> { node.Position };
                        jumpEdge.EgressSemanticSamples = new List<TraversalEgressSemanticSample>
                        {
                            new TraversalEgressSemanticSample
                            {
                                Position = node.Position,
                                Grounded = true,
                                State = node.State,
                                NavMeshSampled = true,
                                NavMeshPosition = rollingLanding
                            }
                        };
                        PendingTraversalSettledExitCaptures.Remove(edgeId);
                        SavePersistentTraversalLinks();
                        WriteEvent("playerJumpRollingLandingCaptured", null, new
                        {
                            edgeId,
                            demonstrationRevision = jumpEdge.DemonstrationRevision,
                            rawExit = Vec(pending.RawExit),
                            rollingLanding = Vec(rollingLanding),
                            physicalPosition = Vec(node.Position),
                            breadcrumbSequence = node.Sequence,
                            delay = Time.time - pending.ArmedAt,
                            planarFromRawExit = jumpPlanarFromExit,
                            forwardContinuation = jumpForwardContinuation,
                            locomotionState = node.State
                        });
                        continue;
                    }
                }

                if (captureBridgeEgress && IsFinite(node.Position))
                {
                    if (pending.EgressSamples == null)
                    {
                        pending.EgressSamples = new List<Vector3>();
                    }
                    if (pending.EgressSemanticSamples == null)
                    {
                        pending.EgressSemanticSamples = new List<TraversalEgressSemanticSample>();
                    }
                    if (pending.EgressSamples.Count == 0 ||
                        Vector3.Distance(pending.EgressSamples[pending.EgressSamples.Count - 1], node.Position) >= 0.16f)
                    {
                        pending.EgressSamples.Add(node.Position);
                        pending.EgressSemanticSamples.Add(new TraversalEgressSemanticSample
                        {
                            Position = node.Position,
                            Grounded = node.Grounded,
                            State = node.State,
                            NavMeshSampled = node.NavMeshSampled,
                            NavMeshPosition = node.NavMeshPosition
                        });
                        if (pending.EgressSamples.Count > 18)
                        {
                            pending.EgressSamples.RemoveAt(1);
                            if (pending.EgressSemanticSamples.Count > 1)
                            {
                                pending.EgressSemanticSamples.RemoveAt(1);
                            }
                        }
                    }
                }

                // CompileFix15: Climb completion is the first credible grounded upper landing,
                // not the later point where the player may immediately walk/drop back to lower NavMesh.
                // The upper platform itself may intentionally be off NavMesh, so preserve the physical
                // grounded point when NavMesh sampling is unavailable there.
                if (climbLandingResume &&
                    Time.time - pending.ArmedAt >= ClimbUpperLandingCaptureMinDelay &&
                    node.Grounded &&
                    !IsTraversalStateName(node.State) &&
                    IsLocomotionResumeStateName(node.State) &&
                    IsFinite(node.Position))
                {
                    float climbPlanarFromExit = GetPlanarDistance(node.Position, pending.RawExit);
                    bool upperHeightCredible = node.Position.y >= pending.RawExit.y - ClimbUpperLandingMaxBelowRawExit;
                    if (climbPlanarFromExit <= ClimbUpperLandingCaptureMaxPlanarDistance && upperHeightCredible)
                    {
                        Vector3 upperLanding = node.Position;
                        if (node.NavMeshSampled && IsFinite(node.NavMeshPosition) &&
                            Mathf.Abs(node.NavMeshPosition.y - node.Position.y) <= UnifiedTraversalVerifyMaxNavVertical)
                        {
                            upperLanding = node.NavMeshPosition;
                        }

                        LearnedTraversalEdge climbEdge = revisionEdge;
                        climbEdge.HasSettledEnd = true;
                        climbEdge.SettledEnd = upperLanding;
                        climbEdge.Disabled = false;
                        climbEdge.SettledBreadcrumbSequence = node.Sequence;
                        climbEdge.EgressSamples = new List<Vector3> { node.Position };
                        climbEdge.EgressSemanticSamples = new List<TraversalEgressSemanticSample>
                        {
                            new TraversalEgressSemanticSample
                            {
                                Position = node.Position,
                                Grounded = true,
                                State = node.State,
                                NavMeshSampled = node.NavMeshSampled,
                                NavMeshPosition = node.NavMeshPosition
                            }
                        };
                        PendingTraversalSettledExitCaptures.Remove(edgeId);
                        SavePersistentTraversalLinks();
                        WriteEvent("playerClimbUpperLandingCaptured", null, new
                        {
                            edgeId,
                            demonstrationRevision = climbEdge.DemonstrationRevision,
                            rawExit = Vec(pending.RawExit),
                            upperLanding = Vec(upperLanding),
                            physicalPosition = Vec(node.Position),
                            navMeshSampled = node.NavMeshSampled,
                            breadcrumbSequence = node.Sequence,
                            delay = Time.time - pending.ArmedAt,
                            planarFromRawExit = climbPlanarFromExit,
                            locomotionState = node.State
                        });
                        continue;
                    }
                }

                if (Time.time - pending.ArmedAt < minimumDelay ||
                    !node.Grounded || IsTraversalStateName(node.State) ||
                    ((vaultLandingResume || climbLandingResume || extendedJumpEgress) && !IsLocomotionResumeStateName(node.State)))
                {
                    if (extendedJumpEgress)
                    {
                        pending.StableNavSamples = 0;
                    }
                    continue;
                }

                Vector3 fromRawExit = node.Position - pending.RawExit;
                float forward = Vector3.Dot(GetFlatDirection(fromRawExit), pending.Direction);
                float planarFromExit = GetPlanarDistance(node.Position, pending.RawExit);
                if (planarFromExit > 0.20f && forward < 0.05f && Time.time - pending.ArmedAt < 0.45f)
                {
                    if (extendedJumpEgress)
                    {
                        pending.StableNavSamples = 0;
                    }
                    continue;
                }

                if (!TrySampleTraversalSettledAnchor(node.Position, TraversalSettledCaptureNavRadius, out Vector3 anchor))
                {
                    if (extendedJumpEgress)
                    {
                        pending.StableNavSamples = 0;
                    }
                    continue;
                }

                if (extendedJumpEgress)
                {
                    float navVertical = Mathf.Abs(anchor.y - node.Position.y);
                    if (navVertical > JumpExtendedEgressStableNavVertical)
                    {
                        pending.StableNavSamples = 0;
                        continue;
                    }

                    pending.StableNavSamples++;
                    if (pending.StableNavSamples < JumpExtendedEgressStableSamples)
                    {
                        continue;
                    }
                }

                LearnedTraversalEdge edge = revisionEdge;
                edge.HasSettledEnd = true;
                edge.SettledEnd = anchor;
                edge.Disabled = false;
                edge.SettledBreadcrumbSequence = node.Sequence;
                if (captureBridgeEgress)
                {
                    if (pending.EgressSamples == null)
                    {
                        pending.EgressSamples = new List<Vector3>();
                    }
                    if (pending.EgressSamples.Count == 0 ||
                        Vector3.Distance(pending.EgressSamples[pending.EgressSamples.Count - 1], anchor) >= 0.12f)
                    {
                        pending.EgressSamples.Add(anchor);
                        pending.EgressSemanticSamples.Add(new TraversalEgressSemanticSample
                        {
                            Position = anchor,
                            Grounded = true,
                            State = node.State,
                            NavMeshSampled = true,
                            NavMeshPosition = anchor
                        });
                    }
                    edge.EgressSamples = pending.EgressSamples
                        .Where(IsFinite)
                        .ToList();
                    edge.EgressSemanticSamples = pending.EgressSemanticSamples
                        .Where(sample => sample != null && IsFinite(sample.Position))
                        .Select(CloneTraversalEgressSemanticSample)
                        .ToList();
                }
                else
                {
                    edge.EgressSamples.Clear();
                    edge.EgressSemanticSamples.Clear();
                }
                PendingTraversalSettledExitCaptures.Remove(edgeId);
                SavePersistentTraversalLinks();
                WriteEvent("playerTraversalSettledExitCaptured", null, new
                {
                    edgeId,
                    kind = edge.Kind,
                    demonstrationRevision = edge.DemonstrationRevision,
                    rawExit = Vec(pending.RawExit),
                    settledExit = Vec(anchor),
                    breadcrumbSequence = node.Sequence,
                    delay = Time.time - pending.ArmedAt,
                    planarFromRawExit = planarFromExit,
                    landingResume = vaultLandingResume || climbLandingResume,
                    climbLandingResume,
                    extendedJumpEgress,
                    captureBridgeEgress,
                    egressSampleCount = edge.EgressSamples?.Count ?? 0,
                    egressSemanticSampleCount = edge.EgressSemanticSamples?.Count ?? 0,
                    locomotionState = node.State
                });
            }
        }

        private static void CancelPendingTraversalSettledExitCaptures(string reason)
        {
            if (PendingTraversalSettledExitCaptures.Count == 0)
            {
                return;
            }

            foreach (PendingTraversalSettledExitCapture pending in PendingTraversalSettledExitCaptures.Values.ToArray())
            {
                if (pending == null)
                {
                    continue;
                }

                WriteEvent("playerTraversalSettledExitUnavailable", null, new
                {
                    edgeId = pending.EdgeId,
                    rawExit = Vec(pending.RawExit),
                    reason = string.IsNullOrEmpty(reason) ? "superseded" : reason
                });
            }

            PendingTraversalSettledExitCaptures.Clear();
        }

        private static int GetTraversalExperiencePhysicalSuccessCount(TraversalExperienceRecord record)
        {
            if (record == null)
            {
                return 0;
            }

            int summed = Math.Max(0, record.CleanPhysicalSuccesses) +
                         Math.Max(0, record.NativeSuccesses) +
                         Math.Max(0, record.NativePartialAssistedSuccesses) +
                         Math.Max(0, record.AssistedCrossingSuccesses) +
                         Math.Max(0, record.FullEgressSuccesses);
            // NativePartialAssistedSuccess can also carry FullEgress evidence, so those counters
            // are not guaranteed to be mutually exclusive. Never let adaptive crossing rate exceed
            // the number of non-interrupted attempts.
            return record.Attempts > 0 ? Math.Min(record.Attempts, summed) : summed;
        }

        private static int GetEndToEndFollowFailureCount(TraversalExperienceRecord record)
        {
            if (record == null)
            {
                return 0;
            }

            // CompileFix44 separates Follow movement resume from formation recovery. Historical
            // FormationRecoveryFailures remain useful for the formation score, but they must not
            // masquerade as failures to resume Follow movement itself.
            return Math.Max(0, record.FollowResumeFailures);
        }

        private static int GetTraversalPhysicalSuccessCount(LearnedTraversalEdge edge)
        {
            if (edge == null)
            {
                return 0;
            }

            int linkPhysical = Math.Max(0, edge.SuccessfulExecutions);
            if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) &&
                record != null)
            {
                return Math.Max(linkPhysical, GetTraversalExperiencePhysicalSuccessCount(record));
            }

            return linkPhysical;
        }

        private static float GetTraversalExperienceEffectiveScore(TraversalExperienceRecord record)
        {
            if (record == null)
            {
                return 0.5f;
            }

            float crossingScore = Mathf.Clamp01(record.RecentScore <= 0f ? 0.5f : record.RecentScore);
            int followAttempts = Math.Max(0, record.EndToEndFollowSuccesses) + GetEndToEndFollowFailureCount(record);
            float followScore = followAttempts > 0
                ? Mathf.Clamp01(record.FollowResumeRecentScore <= 0f
                    ? (record.EndToEndFollowSuccesses + 1f) / (followAttempts + 2f)
                    : record.FollowResumeRecentScore)
                : 1f;

            int formationAttempts = Math.Max(0, record.FormationRecoveredSuccesses) +
                                    Math.Max(0, record.FormationRecoveryFailures);
            float formationScore;
            if (formationAttempts > 0)
            {
                formationScore = Mathf.Clamp01(
                    (Math.Max(0, record.FormationRecoveredSuccesses) + 1f) /
                    (formationAttempts + 2f));
            }
            else if (followAttempts > 0)
            {
                // Backward-compatible proxy for PolicyVersion 8 records created before CompileFix18.
                formationScore = Mathf.Clamp01(
                    (Math.Max(0, record.EndToEndFollowSuccesses) + 1f) /
                    (followAttempts + 2f));
            }
            else
            {
                formationScore = 1f;
            }

            float crossingEvidence = Mathf.Clamp01(Math.Max(0, record.Attempts) / 8f);
            float continuationEvidence = Mathf.Clamp01(followAttempts / 4f);

            // CompileFix38: physical crossing alone is not a useful learned route, but physical
            // history must not masquerade as continuation evidence either. Follow/Formation build
            // their own confidence over several completed post-traversal watches: one failure
            // noticeably demotes the edge, repeated failures rapidly remove it from selection.
            float continuationScore = Mathf.Clamp01(followScore * formationScore);
            float combined = crossingScore * Mathf.Lerp(1f, continuationScore, continuationEvidence);
            float rollbackPenalty = Mathf.Min(6, Math.Max(0, record.PostTraversalRollbacks)) * 0.10f * crossingEvidence;
            float consecutivePenalty = Mathf.Min(6, Math.Max(0, record.ConsecutiveFollowResumeFailures)) * 0.08f * continuationEvidence;
            return Mathf.Clamp01(combined - rollbackPenalty - consecutivePenalty);
        }

        private static bool HasLearningV320CheapLocalWalkThroughBypass(
            BotOwner bot,
            LearnedTraversalEdge edge)
        {
            if ((edge == null) || edge.Id <= 0 ||
                !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            if (IsLearningV344HistoricalWalkThroughSemanticAuthority(edge))
            {
                LearningV320WalkThroughCheapLocalBypassCache[edge.Id] = false;
                return false;
            }

            if ((edge.SyntheticPhysicalCorridor) &&
                string.Equals(edge.RuntimeSemanticKind, "PhysicalCorridor", StringComparison.OrdinalIgnoreCase))
            {
                LearningV320WalkThroughCheapLocalBypassCache[edge.Id] = false;
                if (ShouldEmitDiagnostic(
                    "learningV361StrictGapSyntheticPhysicalAuthority:" +
                        edge.Id.ToString(CultureInfo.InvariantCulture), bot, 0.50f))
                {
                    WriteEvent("learningV361StrictGapSyntheticPhysicalAuthority", bot, new
                    {
                        edgeId = edge.Id,
                        rawStart = Vec(IsFinite(edge.RawStart) ? edge.RawStart : edge.A),
                        rawEnd = Vec(IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B),
                        runtimeSemanticKind = edge.RuntimeSemanticKind,
                        action = "consumerStrictGapPhysicalFactOutranksCheapLocalNavMeshSemanticVeto"
                    });
                }
                return false;
            }

            if (LearningV320WalkThroughCheapLocalBypassCache.TryGetValue(edge.Id, out bool cached))
            {
                return cached;
            }

            Vector3 rawStart = IsFinite(edge.RawStart) ? edge.RawStart : edge.A;
            Vector3 rawEnd = IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B;
            bool bypass = TryFindCheapLocalWalkThroughBypass(
                rawStart, rawEnd,
                out float bypassCost,
                out Vector3 bypassStart,
                out Vector3 bypassEnd,
                out float bypassShoulder);
            LearningV320WalkThroughCheapLocalBypassCache[edge.Id] = bypass;
            if (bypass)
            {
                WriteEvent("learningV320WalkThroughRuntimeSemanticBypassSuppressed", bot, new
                {
                    edgeId = edge.Id,
                    experienceKey = edge.ExperienceKey,
                    rawStart = Vec(rawStart),
                    rawEnd = Vec(rawEnd),
                    bypassCost,
                    bypassStart = Vec(bypassStart),
                    bypassEnd = Vec(bypassEnd),
                    shoulderOffset = bypassShoulder,
                    reason = "cheapLocalNavMeshBypassOwnsLocalSemanticTruth"
                });
            }
            return bypass;
        }

        private static bool IsTraversalEdgeTopologicallySelectableForFollower(
            BotOwner bot,
            LearnedTraversalEdge edge,
            out string reason)
        {
            return IsTraversalEdgeSelectableForFollower(
                bot, edge, checkExperience: false, out reason, currentRaidRouteAuthority: false);
        }

        private static bool IsTraversalEdgeTopologicallySelectableForRouteStep(
            BotOwner bot,
            LearnedTraversalEdge edge,
            FollowerRouteMissionStep step,
            out string reason)
        {
            bool currentRaidRouteAuthority =
                (step != null) && step.CurrentRaidRouteAuthority && step.EpisodeId > 0;
            return IsTraversalEdgeSelectableForFollower(
                bot, edge, checkExperience: false, out reason, currentRaidRouteAuthority);
        }

        private static bool IsTraversalEdgeSelectableForFollower(
            BotOwner bot,
            LearnedTraversalEdge edge,
            bool checkExperience,
            out string reason,
            bool currentRaidRouteAuthority = false)
        {
            reason = string.Empty;
            if (edge == null)
            {
                reason = "edgeMissing";
                return false;
            }
            if ((!currentRaidRouteAuthority) &&
                string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                LearningV349CurrentRaidSemanticDisproofEdges.Contains(edge.Id))
            {
                reason = "learningV349CurrentRaidSemanticDisproof";
                return false;
            }
            if (edge.Disabled && !currentRaidRouteAuthority)
            {
                reason = "disabled";
                return false;
            }
            if (((!currentRaidRouteAuthority)) &&
                TryGetLearningV31AuthoritativeProvenParent(edge, out LearnedTraversalEdge authoritativeParent))
            {
                reason = "learningV31ShadowTrainingOnly:provenParent=" +
                         authoritativeParent.Id.ToString(CultureInfo.InvariantCulture);
                return false;
            }
            if (!currentRaidRouteAuthority && HasLearningV320CheapLocalWalkThroughBypass(bot, edge))
            {
                reason = "learningV320CheapLocalNavMeshBypass";
                return false;
            }
            if ((currentRaidRouteAuthority) &&
                (edge.Disabled || string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)))
            {
                if (ShouldEmitDiagnostic(
                        "learningV347CurrentRaidAuthoritySelector:" +
                            edge.Id.ToString(CultureInfo.InvariantCulture),
                        bot,
                        0.50f))
                {
                    WriteEvent("learningV347CurrentRaidAuthoritySelectorAccepted", bot, new
                    {
                        edgeId = edge.Id,
                        kind = edge.Kind,
                        persistentDisabled = edge.Disabled,
                        action = "currentRaidPlayerEpisodeOutranksPersistentSuppressionForRuntimeRouteOnly"
                    });
                }
            }

            string profileId = bot?.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId))
            {
                if (IsFollowerTraversalEdgeQuarantined(profileId, edge.Id))
                {
                    reason = "followerQuarantine";
                    return false;
                }
                string retryKey = profileId + ":" + edge.Id.ToString(CultureInfo.InvariantCulture);
                if (LearnedTraversalRetryAfter.TryGetValue(retryKey, out float retryAt) && Time.time < retryAt)
                {
                    reason = $"retryCooldown={Mathf.Max(0f, retryAt - Time.time):0.00}s";
                    return false;
                }
            }

            if (TraversalRecentToxicSuppressUntil.TryGetValue(edge.Id, out float toxicUntil))
            {
                if (Time.time < toxicUntil)
                {
                    reason = $"recentFarSideToxicCooldown={Mathf.Max(0f, toxicUntil - Time.time):0.0}s";
                    return false;
                }
                TraversalRecentToxicSuppressUntil.Remove(edge.Id);
            }

            if (checkExperience && ShouldSuppressLearningV322PersistentEvidence(edge, out string persistentEvidenceReason))
            {
                reason = persistentEvidenceReason;
                WriteEvent("learningV322TraversalSuppressedByPersistentEvidence", bot, new
                {
                    edgeId = edge.Id,
                    experienceKey = edge.ExperienceKey,
                    kind = edge.Kind,
                    reason = persistentEvidenceReason
                });
                return false;
            }
            if (checkExperience && ShouldSuppressTraversalByExperience(edge, out string experienceReason))
            {
                reason = experienceReason;
                return false;
            }
            return true;
        }

        private static bool ShouldSuppressTraversalByExperience(LearnedTraversalEdge edge, out string reason)
        {
            reason = string.Empty;
            if (edge == null || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) ||
                record == null)
            {
                if (edge != null) TraversalExperienceRouteSuppressUntil.Remove(edge.Id);
                return false;
            }

            int physical = GetTraversalExperiencePhysicalSuccessCount(record);
            float physicalRate = physical / (float)Math.Max(1, record.Attempts);
            float effective = GetTraversalExperienceEffectiveScore(record);
            float crossingScore = Mathf.Clamp01(record.RecentScore <= 0f ? 0.5f : record.RecentScore);
            bool recentToxicCrossing = FollowerCapabilityHelperRules.ShouldSuppressTraversalByExperience_recentToxicCrossing_E3F830D1_1(record.Attempts,TraversalRecentToxicPersistentMinAttempts,physicalRate,TraversalRecentToxicPersistentPhysicalRate,crossingScore,TraversalRecentToxicPersistentScore);
            bool repeatedExecutorFailure = FollowerCapabilityHelperRules.ShouldSuppressTraversalByExperience_repeatedExecutorFailure_E3F830D1_2(record.Attempts,TraversalExperienceSuppressMinAttempts,record.ConsecutiveFailures,TraversalExperienceSuppressConsecutiveFailures);
            bool poorPhysicalEvidence = physicalRate <= TraversalExperienceSuppressMaxPhysicalRate;
            bool poorEffectiveQuality = effective <= TraversalExperienceSuppressMaxEffectiveScore;
            bool physicalSuppression = FollowerCapabilityHelperRules.ShouldSuppressTraversalByExperience_physicalSuppression_E3F830D1_3(repeatedExecutorFailure,poorPhysicalEvidence,poorEffectiveQuality,recentToxicCrossing);

            int endToEndFailures = GetEndToEndFollowFailureCount(record);
            int endToEndAttempts = Math.Max(0, record.EndToEndFollowSuccesses) + endToEndFailures;
            float endToEndReliability = endToEndAttempts > 0
                ? Mathf.Clamp01((Math.Max(0, record.EndToEndFollowSuccesses) + 1f) / (endToEndAttempts + 2f))
                : 1f;
            bool enoughEndToEndEvidence = endToEndAttempts >= TraversalExperienceSuppressMinEndToEndAttempts;
            bool repeatedFollowFailure = enoughEndToEndEvidence && record.ConsecutiveFollowResumeFailures >= 3;
            bool zeroSuccessEndToEndFailure = enoughEndToEndEvidence &&
                                              record.EndToEndFollowSuccesses == 0 &&
                                              endToEndFailures >= TraversalExperienceSuppressMinEndToEndAttempts;
            bool rollbackToxic = enoughEndToEndEvidence && record.PostTraversalRollbacks >= 3;
            bool poorEndToEnd = FollowerCapabilityHelperRules.ShouldSuppressTraversalByExperience_poorEndToEnd_E3F830D1_4(endToEndAttempts,endToEndReliability);
            // CompileFix31 Policy V9: physical trust protects the portal geometry, not route
            // usefulness. A 38/41 physically clean portal that repeatedly fails to rejoin formation
            // must still be eligible for bounded route suppression/revalidation.
            bool endToEndSuppression =
                FollowerCapabilityHelperRules.ShouldSuppressTraversalByExperience_endToEndSuppression_E3F830D1_5(poorEndToEnd,repeatedFollowFailure,zeroSuccessEndToEndFailure,rollbackToxic,effective);
            if ((!physicalSuppression))
            {
                // End-to-end Follow quality remains recorded and may steer successor/handoff policy,
                // but it cannot make an otherwise physically reliable traversal disappear from the
                // route graph. Crossing suppression is reserved for crossing/executor evidence.
                endToEndSuppression = false;
            }

            if (TraversalExperienceRouteRevalidationUntil.TryGetValue(edge.Id, out float revalidationUntil))
            {
                if (Time.time < revalidationUntil)
                {
                    reason = $"revalidationLease={Mathf.Max(0f, revalidationUntil - Time.time):0.0}s";
                    return false;
                }
                TraversalExperienceRouteRevalidationUntil.Remove(edge.Id);
            }

            if (!physicalSuppression && !endToEndSuppression)
            {
                TraversalExperienceRouteSuppressUntil.Remove(edge.Id);
                return false;
            }

            if (TraversalExperienceRouteSuppressUntil.TryGetValue(edge.Id, out float suppressUntil))
            {
                if (Time.time < suppressUntil)
                {
                    reason = $"effective={effective:0.00} physical={physical}/{record.Attempts} e2e={record.EndToEndFollowSuccesses}/{Math.Max(1, endToEndAttempts)} e2eFailures={endToEndFailures} rollback={record.PostTraversalRollbacks} cooldown={Mathf.Max(0f, suppressUntil - Time.time):0.0}s";
                    return true;
                }

                // CompileFix28: the old code re-armed the 30 s suppression *before* returning the
                // bounded exploration selection. A second selector poll then suppressed the same
                // edge before a bot could reach it. Expiry now creates a real execution lease.
                TraversalExperienceRouteSuppressUntil.Remove(edge.Id);
                TraversalExperienceRouteRevalidationUntil[edge.Id] = Time.time + TraversalExperienceRevalidationLeaseSeconds;
                reason = "boundedRevalidation";
                return false;
            }

            float suppressionSeconds = recentToxicCrossing
                ? TraversalRecentToxicSuppressSeconds
                : TraversalExperienceSuppressSeconds;
            TraversalExperienceRouteSuppressUntil[edge.Id] = Time.time + suppressionSeconds;
            reason = $"effective={effective:0.00} physical={physical}/{record.Attempts} recent={crossingScore:0.00} recentToxic={recentToxicCrossing} e2e={record.EndToEndFollowSuccesses}/{Math.Max(1, endToEndAttempts)} e2eFailures={endToEndFailures} rollback={record.PostTraversalRollbacks} cooldown={suppressionSeconds:0}s";
            return true;
        }

        private static float GetTraversalExperienceSelectionAdjustment(LearnedTraversalEdge edge)
        {
            if (edge == null || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) ||
                record == null)
            {
                return edge?.Verified == true ? -0.40f : 0f;
            }

            int physical = GetTraversalExperiencePhysicalSuccessCount(record);
            float physicalRate = physical / (float)Math.Max(1, record.Attempts);
            bool strongPhysicalTrust = FollowerCapabilityHelperRules.GetTraversalExperienceSelectionAdjustment_strongPhysicalTrust_372204F5_1(physical,physicalRate);
            float crossingScore = Mathf.Clamp01(record.RecentScore <= 0f ? 0.5f : record.RecentScore);
            float effectiveScore = GetTraversalExperienceEffectiveScore(record);
            int recovery = Math.Max(0, record.TeleportRecoveries) + Math.Max(0, record.ForcedEgressRecoveries);
            int hard = Math.Max(0, record.HardFailures) + Math.Max(0, record.TeleportRejected) +
                       Math.Max(0, record.EgressFailures) + Math.Max(0, record.DropBacks);

            // R9.7 first adaptive-selection step: proven physical routes should beat equally local
            // unverified routes. Recovery/failure penalties remain meaningful, but once geometry has
            // physical proof they are treated as execution noise rather than evidence that the route
            // itself is invalid.
            float successBonus = Mathf.Min(3.25f, physical * 0.24f) +
                                 (strongPhysicalTrust ? crossingScore : effectiveScore) * 1.75f +
                                 Mathf.Clamp01(record.Confidence) * 0.55f;
            if (edge.Verified) successBonus += 0.55f;
            if (edge.NativeSuccessCount > 0 || record.NativeExecutorSuccesses > 0) successBonus += 0.35f;

            float penaltyScale = strongPhysicalTrust ? 0.65f : 1.0f;
            float failurePenalty = (Mathf.Min(5, recovery) * 0.30f + Mathf.Min(6, hard) * 0.55f) * penaltyScale;

            // CompileFix10: crossing the obstacle and resuming formation are different rewards.
            // A geometry edge that repeatedly strands the follower must lose selection priority even
            // if its physical crossing animation itself is reliable. Conversely, proven Follow resume
            // is a strong signal that the entire traversal transaction is useful in live play.
            int followAttempts = Math.Max(0, record.EndToEndFollowSuccesses) +
                                 GetEndToEndFollowFailureCount(record);
            float followSuccessBonus = 0f;
            float followFailurePenalty = 0f;
            if (followAttempts > 0)
            {
                float followReliability = Mathf.Clamp01(
                    (Math.Max(0, record.EndToEndFollowSuccesses) + 1f) / (followAttempts + 2f));
                followSuccessBonus = Mathf.Min(2.0f, record.EndToEndFollowSuccesses * 0.24f) +
                                     followReliability * 0.85f;
                int endToEndFailures = GetEndToEndFollowFailureCount(record);
                followFailurePenalty = Mathf.Min(8, endToEndFailures) * 0.46f +
                                       Mathf.Min(4, record.ConsecutiveFollowResumeFailures) * 0.34f +
                                       Mathf.Min(4, record.PostTraversalRollbacks) * 0.38f;
            }
            // CompileFix31 Policy V9: route utility is independent from physical portal trust.
            // Strong physical evidence still earns the crossing bonus above, but no longer reduces
            // Follow/Formation penalties to 15%. This prevents physically reliable yet strategically
            // toxic routes from permanently outranking useful alternatives.
            float followPenaltyScale = 1f;
            float effectiveFailurePenalty = (1f - effectiveScore) * Mathf.Clamp01(record.Attempts / 6f) * 1.75f * followPenaltyScale;
            return failurePenalty + followFailurePenalty * followPenaltyScale + effectiveFailurePenalty - successBonus - followSuccessBonus;
        }

        private static bool ShouldPreferAssistedExecutor(
            BotOwner bot,
            LearnedTraversalEdge edge,
            string traversalKind,
            out string reason,
            out float effectiveScore,
            out bool explorationOverride)
        {
            reason = string.Empty;
            effectiveScore = 0.5f;
            explorationOverride = false;
            {
                if ((edge != null) &&
                    ShouldSuppressLearningV322PersistentEvidence(edge, out string persistentExecutorReason) &&
                    !string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                    LearningV322SkillEvidence.TryGetValue(edge.ExperienceKey, out LearningV322PersistentSkillEvidenceRecord persistentRecord) &&
                    persistentRecord != null && persistentRecord.AssistedPhysicalCompletions > 0)
                {
                    effectiveScore = persistentRecord.NativeSuccesses / (float)Math.Max(1, persistentRecord.NativeAttempts);
                    reason = "learningV325PersistentEvidenceDegradesExecutor:" + persistentExecutorReason +
                             $":assistPhysical={persistentRecord.AssistedPhysicalCompletions}/{persistentRecord.AssistedAttempts}";
