                record == null)
            {
                return false;
            }

            effectiveScore = GetTraversalExperienceEffectiveScore(record);
            int nativeAttempts = Math.Max(0, record.NativeExecutorAttempts);
            int assistedAttempts = Math.Max(0, record.AssistedExecutorAttempts);
            int minimumComparativeAttempts = (1);
            if (nativeAttempts < minimumComparativeAttempts ||
                assistedAttempts < minimumComparativeAttempts ||
                record.AssistedExecutorSuccesses < 1)
            {
                reason = $"insufficientExperience effective={effectiveScore:0.00} " +
                         $"native={record.NativeExecutorSuccesses}/{nativeAttempts} " +
                         $"assisted={record.AssistedExecutorSuccesses}/{assistedAttempts}";
                return false;
            }

