            float priorNativeAttempts = prior?.NativeAttempts ?? 0f;
            float priorNativeSuccesses = prior?.NativeSuccesses ?? 0f;
            float priorAssistedAttempts = prior?.AssistedAttempts ?? 0f;
            float priorAssistedSuccesses = prior?.AssistedSuccesses ?? 0f;
            float weightedNativeAttempts = nativeAttempts + priorNativeAttempts * LearningV2SkillPriorWeight;
            float weightedNativeSuccesses = record.NativeExecutorSuccesses + priorNativeSuccesses * LearningV2SkillPriorWeight;
            float weightedAssistedAttempts = assistedAttempts + priorAssistedAttempts * LearningV2SkillPriorWeight;
            float weightedAssistedSuccesses = record.AssistedExecutorSuccesses + priorAssistedSuccesses * LearningV2SkillPriorWeight;
            float nativeRate = Mathf.Clamp01(weightedNativeSuccesses / Math.Max(1f, weightedNativeAttempts));
            float assistedRate = Mathf.Clamp01(weightedAssistedSuccesses / Math.Max(1f, weightedAssistedAttempts));
            int nativeFollowAttempts = Math.Max(0, record.NativeEndToEndFollowSuccesses) +
                                       Math.Max(0, record.NativeFollowResumeFailures);
            int assistedFollowAttempts = Math.Max(0, record.AssistedEndToEndFollowSuccesses) +
                                         Math.Max(0, record.AssistedFollowResumeFailures);
            float nativeFollowRate = nativeFollowAttempts > 0
                ? Mathf.Clamp01((record.NativeEndToEndFollowSuccesses + 1f) / (nativeFollowAttempts + 2f))
                : 1f;
            float assistedFollowRate = assistedFollowAttempts > 0
                ? Mathf.Clamp01((record.AssistedEndToEndFollowSuccesses + 1f) / (assistedFollowAttempts + 2f))
                : 1f;
            float nativeQuality = nativeRate * nativeFollowRate;
            float assistedQuality = assistedRate * assistedFollowRate;
            bool freshSingleSampleCorrection = FollowerCapabilityHelperRules.ShouldPreferAssistedExecutor_freshSingleSampleCorrection_EBB76326_2(nativeAttempts) && record.NativeExecutorSuccesses == 0 &&
                                               assistedAttempts >= 1 && record.AssistedExecutorSuccesses >= 1;
            bool prefer = FollowerCapabilityHelperRules.ShouldPreferAssistedExecutor_prefer_EBB76326_3(freshSingleSampleCorrection,assistedQuality,nativeQuality,assistedRate,nativeAttempts,nativeRate,assistedRate);
            if (prefer)
            {
                int totalExecutorAttempts = nativeAttempts + assistedAttempts;
                bool explorationDue = FollowerCapabilityHelperRules.ShouldPreferAssistedExecutor_explorationDue_EBB76326_4(totalExecutorAttempts,totalExecutorAttempts);
                string explorationDetail = string.Empty;
                if (explorationDue && edge.Id > 0 && bot != null)
                {
                    string profileId = bot.ProfileId ?? string.Empty;
                    if (TraversalExecutorExplorationLeases.TryGetValue(edge.Id, out TraversalExecutorExplorationLease lease) &&
                        lease != null && Time.time <= lease.ExpiresAt)
                    {
                        if (string.Equals(lease.ProfileId, profileId, StringComparison.Ordinal))
                        {
                            explorationOverride = true;
                            explorationDetail = " exploration=native lease=owned";
                        }
                        else
                        {
                            explorationDetail = " exploration=assisted lease=peer";
                        }
                    }
                    else
                    {
                        TraversalExecutorExplorationLeases[edge.Id] = new TraversalExecutorExplorationLease
                        {
                            ProfileId = profileId,
                            ExpiresAt = Time.time + TraversalExecutorExplorationLeaseSeconds
                        };
                        explorationOverride = true;
                        explorationDetail = " exploration=native lease=acquired";
                    }
                }
                reason = $"effective={effectiveScore:0.00} assistedQuality={assistedQuality:0.00} nativeQuality={nativeQuality:0.00} " +
                         $"assistedCross={record.AssistedExecutorSuccesses}/{assistedAttempts} " +
                         $"nativeCross={record.NativeExecutorSuccesses}/{nativeAttempts} " +
                         $"assistedFollow={record.AssistedEndToEndFollowSuccesses}/{assistedFollowAttempts} " +
                         $"nativeFollow={record.NativeEndToEndFollowSuccesses}/{nativeFollowAttempts} " +
                         $"priorNative={priorNativeSuccesses:0.##}/{priorNativeAttempts:0.##} " +
                         $"priorAssisted={priorAssistedSuccesses:0.##}/{priorAssistedAttempts:0.##}" +
                         explorationDetail;
            }
            return prefer && !explorationOverride;
        }

        private static bool ShouldSuppressWalkThroughLearnedSubStrategy(
            ProbeRuntime probe,
            bool stepAssist,
            out string reason)
        {
            reason = string.Empty;
            if (probe == null || probe.LearnedEdgeId <= 0)
            {
                return false;
            }

            // V3.19: sub-strategy history belongs to the authored location/executor pairing.
            // A zero-shot WT instance has only current-geometry corridor authority, so historical
            // sharp-turn/step-assist failures from the template must not suppress a valid new seam.
            if (TryGetLearningV319TransientSkillTransfer(probe, out _))
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == probe.LearnedEdgeId);
            if (edge == null || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) ||
                record == null)
            {
                return false;
            }

            int attempts = stepAssist
                ? Math.Max(0, record.WalkThroughStepAssistAttempts)
                : Math.Max(0, record.WalkThroughSharpTurnExecutorAttempts);
            int successes = stepAssist
                ? Math.Max(0, record.WalkThroughStepAssistSuccesses)
                : Math.Max(0, record.WalkThroughSharpTurnExecutorSuccesses);
            int failures = stepAssist
                ? Math.Max(0, record.WalkThroughStepAssistFailures)
                : Math.Max(0, record.WalkThroughSharpTurnExecutorFailures);
            if (attempts < WalkThroughAdaptiveStrategyMinAttempts || failures < WalkThroughAdaptiveStrategyMinAttempts)
            {
                return false;
            }

            float failureRate = Mathf.Clamp01(failures / (float)Math.Max(1, attempts));
            bool consistentlyBad = FollowerCapabilityHelperRules.ShouldSuppressWalkThroughLearnedSubStrategy_consistentlyBad_395D49FD_1(successes,attempts,successes,failureRate,WalkThroughAdaptiveStrategyFailureRate);
            if (!consistentlyBad)
            {
                return false;
            }

            // Keep bounded exploration. If geometry is re-taught or a different approach makes the
            // strategy viable, every fourth traversal can earn successful evidence and remove the
            // suppression naturally.
            bool explorationAttempt = ((Math.Max(0, record.Attempts) + 1) %
                                       WalkThroughAdaptiveExplorationModulo) == 0;
            if (explorationAttempt)
            {
                return false;
            }

            reason = $"historicalFailures={failures}/{attempts} successes={successes} " +
                     $"failureRate={failureRate:0.00} experienceAttempts={record.Attempts}";
            return true;
        }

        private static bool IsTraversalEdgeActivelyReferenced(int edgeId)
        {
            if (edgeId <= 0)
            {
                return false;
            }

            if (ActiveProbes.Values.Any(probe => probe != null && probe.LearnedEdgeId == edgeId) ||
                LearnedTraversalCommitments.Values.Any(commitment => commitment != null && commitment.EdgeId == edgeId) ||
                PostTraversalIntegrityWatches.Values.Any(watch => watch != null && watch.EdgeId == edgeId && !watch.FollowOutcomeRecorded))
            {
                return true;
            }

            foreach (FollowerRouteMission mission in FollowerRouteMissions.Values)
            {
                if (mission?.Steps == null)
                {
                    continue;
                }
                for (int i = Math.Max(0, mission.CurrentStepIndex); i < mission.Steps.Count; i++)
                {
                    if (mission.Steps[i]?.EdgeId == edgeId)
                    {
                        return true;
                    }
                }
            }

            return HasCapabilityRecordedEdgeReference(edgeId);
        }

        private static bool IsLearningV345ProtectedHistoricalWalkThroughSemantic(LearnedTraversalEdge edge)
        {
            return (edge != null) &&
                   edge.HistoricalSemanticAuthority &&
                   string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                   !string.IsNullOrWhiteSpace(edge.ExperienceKey);
        }

        private static int GetTraversalPruneTier(LearnedTraversalEdge edge)
        {
            if (edge == null) return 0;
            if (IsLearningV345ProtectedHistoricalWalkThroughSemantic(edge)) return 4;
            if (edge.Disabled) return 0;
            if (!edge.PlayerValidated) return 1;
            if (!edge.Verified) return 2;

            if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) &&
                record != null && GetTraversalExperiencePhysicalSuccessCount(record) == 0 &&
                (record.TeleportRecoveries > 0 || record.ForcedEgressRecoveries > 0))
            {
                return 3;
            }

            return 4;
        }

        private static void RemoveLowValueTraversalEdge(LearnedTraversalEdge edge, string reason)
        {
            if (edge == null)
            {
                return;
            }
            if (IsLearningV345ProtectedHistoricalWalkThroughSemantic(edge))
            {
                WriteEvent("learningV345HistoricalSemanticPruneRejected", null, new
                {
                    edgeId = edge.Id,
                    experienceKey = edge.ExperienceKey,
                    kind = edge.Kind,
                    reason = reason ?? string.Empty,
                    action = "preserveEmpiricalHistoricalPassageAuthority"
                });
                return;
            }

            LearnedTraversalEdges.Remove(edge);
            FollowerRuntimeNavMeshLinks.Remove(edge.Id);
            ClearCommitmentsForEdge(edge.Id);
            TraversalEpisodesByEdge.Remove(edge.Id);
            TraversalEpisodeStream.RemoveAll(episode => episode != null && episode.EdgeId == edge.Id);
            if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) && TraversalExperiences.Remove(edge.ExperienceKey))
            {
                traversalExperienceDirty = true;
            }

            WriteEvent("traversalLowValueEdgePruned", null, new
            {
                edgeId = edge.Id,
                kind = edge.Kind,
                reason,
                physicalSuccesses = GetTraversalPhysicalSuccessCount(edge),
                verified = edge.Verified,
                disabled = edge.Disabled
            });
        }

        private static void TrimLearnedTraversalEdgesToLimit()
        {
            while (LearnedTraversalEdges.Count > LearnedTraversalEdgeLimit)
            {
                LearnedTraversalEdge candidate = LearnedTraversalEdges
                    .Where(CanDiscardCapabilityTraversalEdge)
                    .OrderBy(GetTraversalPruneTier)
                    .ThenBy(edge =>
                    {
                        if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                            TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) && record != null)
                        {
                            return record.Confidence;
                        }
                        return 0f;
                    })
                    .ThenBy(edge => edge.CreatedAt)
                    .FirstOrDefault();

                if (candidate == null)
                {
                    // Proven, freshly demonstrated and live-referenced definitions share one soft-limit contract.
                    if(ShouldEmitDiagnostic("capabilityLearningCapacityDeferred",null,5f))
                        WriteEvent("capabilityLearningCapacityDeferred",null,new{edges=LearnedTraversalEdges.Count,
                            softLimit=LearnedTraversalEdgeLimit,reason="allRemainingDefinitionsProtected",
                            persistentLearningChanged=false,nativeSuccessRecorded=false});
                    break;
                }

                RemoveLowValueTraversalEdge(candidate, "smartCapacity");
            }
        }

        private static void PruneLearnedTraversalEdges()
        {
            for (int index = LearnedTraversalEdges.Count - 1; index >= 0; index--)
            {
                LearnedTraversalEdge edge = LearnedTraversalEdges[index];
                bool learningV3ExpiredCandidate = (edge.PlayerValidated) &&
                    !IsLearningV3NativeProvenEdge(edge) &&
                    !IsLearningV345ProtectedHistoricalWalkThroughSemantic(edge) &&
                    Time.time - edge.CreatedAt > LearningV3UnprovenCandidateTtlSeconds;
                bool legacyExpiredTransient = !edge.PlayerValidated && !edge.Verified &&
                    Time.time - edge.CreatedAt > LearnedTraversalEdgeTtlSeconds;
                if ((learningV3ExpiredCandidate || legacyExpiredTransient) &&
                    CanDiscardCapabilityTraversalEdge(edge))
                {
                    RemoveLowValueTraversalEdge(edge, learningV3ExpiredCandidate
                        ? "learningV3UnprovenCandidateTtl"
                        : "ttl");
                }
            }

            TrimLearnedTraversalEdgesToLimit();

            foreach (string key in LearnedTraversalRetryAfter
                .Where(pair => Time.time >= pair.Value + LearnedTraversalEdgeTtlSeconds)
                .Select(pair => pair.Key)
                .ToArray())
            {
                LearnedTraversalRetryAfter.Remove(key);
            }
        }

        public static void RecordFollowPathResult(
            BotOwner bot,
            Vector3 requestedTarget,
            string source,
            NavMeshPathStatus reportedStatus)
        {
            if (bot != null && IsFinite(requestedTarget))
            {
                RecordRouteMissionMoveResult(bot, requestedTarget, source, reportedStatus);

                if (reportedStatus == NavMeshPathStatus.PathComplete &&
                    TryParsePriorityTraversalEdgeSource(source, out int acceptedTraversalEdgeId) &&
                    LearnedTraversalCommitments.TryGetValue(bot.ProfileId ?? string.Empty, out LearnedTraversalCommitment acceptedCommitment) &&
                    acceptedCommitment != null && acceptedCommitment.EdgeId == acceptedTraversalEdgeId)
                {
                    acceptedCommitment.ApproachPathFailures = 0;
                    acceptedCommitment.LastApproachPathRejectedAt = 0f;
                    acceptedCommitment.NextApproachPathAttemptAt = 0f;

                    bool routeMissionOwned = acceptedCommitment.RouteMissionId > 0 &&
                        FollowerRouteMissions.TryGetValue(bot.ProfileId ?? string.Empty, out FollowerRouteMission acceptedMission) &&
                        acceptedMission != null && acceptedMission.MissionId == acceptedCommitment.RouteMissionId;
                    float acceptedEntryDistance = Vector3.Distance(bot.Position, acceptedCommitment.Entry);
                    bool moverCommitted = bot.Mover?.HasPathAndNoComplete == true || bot.Mover?.IsMoving == true;
                    bool acceptedButInactive = routeMissionOwned &&
                        !HasActiveTraversalProbe(bot) &&
                        acceptedEntryDistance > RouteMissionAcceptedPathNoMoverMinimumDistance &&
                        acceptedEntryDistance <= RouteMissionLocalEntryBridgeMaxDistance &&
                        !moverCommitted;

                    if (acceptedButInactive)
                    {
                        acceptedCommitment.ApproachMoverCommitFailures++;
                        acceptedCommitment.LastApproachMoverCommitFailureAt = Time.time;
                        WriteEvent("routeMissionPathAcceptedWithoutMoverCommit", bot, new
                        {
                            missionId = acceptedCommitment.RouteMissionId,
                            stepIndex = acceptedCommitment.RouteMissionStepIndex,
                            edgeId = acceptedCommitment.EdgeId,
                            kind = acceptedCommitment.Kind,
                            source = source ?? "unknown",
                            entry = Vec(acceptedCommitment.Entry),
                            entryDistance = acceptedEntryDistance,
                            failures = acceptedCommitment.ApproachMoverCommitFailures,
                            hasPath = bot.Mover?.HasPathAndNoComplete == true,
                            moving = bot.Mover?.IsMoving == true,
                            realDestination = bot.Mover != null ? (object)Vec(bot.Mover.RealDestPoint) : null,
                            action = acceptedCommitment.ApproachMoverCommitFailures >= RouteMissionAcceptedPathNoMoverBridgeCount
                                ? "authorizeExistingLocalEntryBridge"
                                : "confirmOnNextAcceptedWrite"
                        });
                    }
                    else
                    {
                        acceptedCommitment.ApproachMoverCommitFailures = 0;
                        acceptedCommitment.LastApproachMoverCommitFailureAt = 0f;
                    }
                }

                if ((reportedStatus == NavMeshPathStatus.PathComplete))
                {
                    TryProveLearningV364PhysicalNavigationEpochFromAcceptedPath(
                        bot, source ?? "unknown", out string _);
                }

                if (TryGetActiveProbe(bot, out ProbeRuntime handoffProbe) &&
                    handoffProbe.Generation == raidGeneration &&
                    handoffProbe.Stage == ProbeStage.ExitCommit &&
                    handoffProbe.ExitAuthorityFollowHandoffActive)
                {
                    if (!handoffProbe.ExitAuthorityFollowPathObserved)
                    {
                        handoffProbe.ExitAuthorityFollowPathFirstObservedAt = Time.time;
                    }
                    handoffProbe.ExitAuthorityFollowPathObserved = true;
                    handoffProbe.ExitAuthorityFollowPathObservedAt = Time.time;
                    handoffProbe.ExitAuthorityFollowTarget = requestedTarget;
                    handoffProbe.ExitAuthorityFollowPathSource = source ?? "unknown";
                    handoffProbe.ExitAuthorityFollowPathStatus = reportedStatus.ToString();
                    WriteEvent("exitAuthorityFollowPathObserved", bot, new
                    {
                        edgeId = handoffProbe.LearnedEdgeId,
                        kind = handoffProbe.TraversalKind,
                        source = source ?? "unknown",
                        target = Vec(requestedTarget),
                        status = reportedStatus.ToString(),
                        current = Vec(bot.Position)
                    });
                }
            }

            if (!diagnosticsEnabled || !IsLiveBot(bot) || !BossPlayers.IsFollower(bot) ||
                !IsFinite(bot.Position) || !IsFinite(requestedTarget))
            {
                return;
            }

            if (!ShouldEmitDiagnostic("followPathResult:" + (source ?? "unknown"), bot, 0.75f))
            {
                return;
            }

            try
            {
                // R8.8 route missions already know the player-authored topology. Do not spend a
                // second CalculateStrictPath merely to enrich diagnostics after GoToPoint just ran.
                if (IsRouteMissionPathSource(source))
                {
                    WriteEvent("followPathResult", bot, new
                    {
                        source = source ?? "unknown",
                        requestedTarget = Vec(requestedTarget),
                        reportedStatus = reportedStatus.ToString(),
                        routeMission = true
                    });
                    return;
                }

                StrictPathResult strict = CalculateStrictPath(bot.Position, requestedTarget);
                WriteEvent("followPathResult", bot, new
                {
                    source = source ?? "unknown",
                    requestedTarget = Vec(requestedTarget),
                    reportedStatus = reportedStatus.ToString(),
                    strict = strict.ToPayload(),
                    reportedCompleteStrictNonComplete =
                        reportedStatus == NavMeshPathStatus.PathComplete && !strict.StrictComplete
                });
            }
            catch (Exception ex)
            {
                DisableDiagnosticsAfterFailure("follow path diagnostic failed", ex);
            }
        }

        private static void OnBotOwnerUpdate(BotOwner bot)
        {
            using var phase = FollowerControlBackend.EnterPhase(ControlUpdatePhase.BotUpdate);
            if (!raidActive || bot == null)
            {
                return;
            }

            if(IsCapabilityRetryWalking(bot))ApplyCapabilitySequenceWalking(bot,CapabilityIngressDistance(bot));
            bool recoveryHandled=TickCapabilityFullRouteRetry(bot);
            if(!recoveryHandled)TryReleaseCapabilityResolvedAuthority(bot);
            if(!recoveryHandled)QuiesceCapabilityCompletedFollowInput(bot);
            if(!recoveryHandled)
            {
            // CompileFix39: authority rollback must be corrected before RollingApproach consumes
            // the contaminated body position and classifies it as a geometry miss.
            UpdateChainHandoffAuthorityGuard(bot);
            if (TryGetActiveProbe(bot, out ProbeRuntime botProbe))
            {
                UpdateProbe(botProbe);
            }
            EnforceLearningV368TraversalProducerOwnership(bot, "OnBotOwnerUpdate");
            UpdateLearningV375PersistentExecutablePhysicalRouteTransaction(bot);

            if (!IsLiveBot(bot) || !BossPlayers.IsFollower(bot))
            {
                return;
            }

            // V3.65: empirical route corridors are physical movement transactions. Integrate them
            // on the bot update cadence so Time.deltaTime represents elapsed producer time rather
            // than a sparse Follow-target polling interval. Healthy NavMesh still wins inside the
            // producer's existing connector check, and active Traversal probes remain exclusive.
            UpdateLearningV365ContinuousEmpiricalRouteProducer(bot);

            UpdateFollowerMovementStateRecovery(bot);
            UpdateCF63DormantFollowConsumerWatch(bot);
            UpdateFollowReacquireWatch(bot);
            UpdateCF64FollowPhysicalWitness(bot);
            UpdatePostTraversalIntegrityWatch(bot);
            }
            if (!IsLiveBot(bot) || !BossPlayers.IsFollower(bot))return;
            UpdateWorldSafetyWatchdog(bot);

            if ((diagnosticsEnabled) &&
                Time.unscaledDeltaTime * 1000f >= LearningV343FrameLoadTelemetryThresholdMs &&
                ShouldEmitDiagnostic("learningV343TraversalFrameLoadSample", bot, 0.12f))
            {
                TryGetActiveProbe(bot, out ProbeRuntime loadProbe);
                FollowerRouteMissions.TryGetValue(bot.ProfileId ?? string.Empty, out FollowerRouteMission loadMission);
                long loadGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                    bot, out FollowerMovementWriterAuthority.WriterDomain loadOwner);
                WriteEvent("learningV343TraversalFrameLoadSample", bot, new
                {
                    frameMilliseconds = Time.unscaledDeltaTime * 1000f,
                    movementOwner = loadOwner.ToString(),
                    movementGeneration = loadGeneration,
                    activeProbe = loadProbe != null,
                    probeEdgeId = loadProbe?.LearnedEdgeId ?? 0,
                    probeKind = loadProbe?.TraversalKind ?? loadProbe?.RequestedTraversalKind ?? string.Empty,
                    probeStage = loadProbe != null ? loadProbe.Stage.ToString() : string.Empty,
                    routeMissionId = loadMission?.MissionId ?? 0,
                    routeStepIndex = loadMission?.CurrentStepIndex ?? -1,
                    routeStepCount = loadMission?.Steps?.Count ?? 0,
                    moverHasPath = bot.Mover?.HasPathAndNoComplete == true,
                    moverMoving = bot.Mover?.IsMoving == true,
                    moverPaused = bot.Mover?.Pause == true
                });
            }

            if (!diagnosticsEnabled)
            {
                return;
            }

            string profileId = bot.ProfileId;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }

            if (!DiagnosticFollowers.TryGetValue(profileId, out DiagnosticFollowerState state))
            {
                state = new DiagnosticFollowerState
                {
                    LastPosition = bot.Position,
                    LastProgressAt = Time.time,
                    LastLeaderDistance = -1f
                };
                DiagnosticFollowers[profileId] = state;
            }

            if (Time.time < state.NextSnapshotAt)
            {
                return;
            }

            state.NextSnapshotAt = Time.time + DiagnosticSnapshotInterval;
            RecordFollowerSnapshot(bot, state);
        }


        // CF63: CF38 only repairs a known Follow epoch; CF45 needs a stale terminal corner.
        // A normal Follow bot can have neither path nor terminal corner while the leader
        // leaves an idle/teleport regroup. Admit just one fresh ordinary-Follow recovery
        // after measured stationary body evidence, not from a path query or a timer alone.
        // RC107: UpdateCF63DormantFollowConsumerWatch is owned by FollowerCapabilityFollowControlHost.

        // CF64: observe actual EFT body motion following a CF63 accepted native path.
        // The witness is short-lived and passive. Epoch changes, teleport/stabilization,
        // commands, combat, active traversal and implausible deltas CANNOT prove recovery.
        // RC107: UpdateCF64FollowPhysicalWitness is owned by FollowerCapabilityFollowControlHost.

        // RC107: UpdateFollowReacquireWatch is owned by FollowerCapabilityFollowControlHost.

        // CF38: restore an already-owned Follow consumer that LOST its native path shortly
        // after a successful traversal handoff. This is not a route retry: no action truth,
        // mission cursor, writer generation, teleport or persistent experience is changed.
        // Admission is guarded by a live Follow epoch and a single attempt per generation.
        // RC107: TryCF38ReprimeLostFollowConsumerPath is owned by FollowerCapabilityFollowControlHost.

        // CF45: the V402 terminal boundary may return the writer to Follow while EFT's
        // BotMover still reports the PREVIOUS traversal physical anchor as its current corner.
        // A valid-looking path and IsMoving are NOT proof of an actual live Follow consumer.
        // Repair only after measured no-progress, under the same Follow generation, when
        // that exact stale physical epoch/corner identity is observed. Never inject input,
        // teleport, change semantic debt, or repeatedly reprime the same generation.
        // RC107: TryCF45RepairStaleTerminalFollowConsumer is owned by FollowerCapabilityFollowControlHost.

        // RC107: UpdateLearningV349GenericPhysicalProgressWatchdog is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: UpdateFollowerMovementStateRecovery is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryNeutralizeLearningV432StationaryVisualLocomotionResidue is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: BeginJumpLandingReleaseGate is owned by FollowerCapabilityRecoveryHost.

        // RC107: NeedsJumpPostLandingChainCommit is owned by FollowerCapabilityRecoveryHost.

        // RC107: BeginJumpPostLandingChainCommit is owned by FollowerCapabilityRecoveryHost.

        // RC107: UpdateJumpPostLandingChainCommit is owned by FollowerCapabilityRecoveryHost.

        // RC107: UpdateJumpLandingReleaseGate is owned by FollowerCapabilityRecoveryHost.

        // RC107: TryRepairStuckJumpLanding is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryRecoverGeneralFollowerLocomotion is owned by FollowerCapabilityGeneralRecoveryHost.

        // LearningV4.31: teleport is a relocation transaction, not a locomotion recovery beat.
        // The previous shared hard-recovery helper deliberately injected Vector2.up after every
        // teleport. When the Player state was still Sprint, that new forward intent moved the body
        // ~1.25 m before the stabilization controller could observe/correct it, creating the
        // visible "teleport then ghost-pull back" loop. Keep teleport recovery quiescent: clear
        // traversal animation/state, zero every PIT-owned movement intent, and leave Follow to
        // install the first fresh post-teleport producer only after stabilization completes.
        // RC107: TryQuiesceFollowerLocomotionForTeleport is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryHardRecoverFollowerLocomotionAuthority is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryHardRecoverStuckJumpLanding is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryInvokeOptionalBoolMethod is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryInvokeMovementStateTransition is owned by FollowerCapabilityGeneralRecoveryHost.

        // RC107: TryCrossFadeFollowerLocomotion is owned by FollowerCapabilityGeneralRecoveryHost.

        private static void UpdateWorldSafetyWatchdog(BotOwner bot)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            Player player = bot?.GetPlayer;
            if (string.IsNullOrEmpty(profileId) || player?.MovementContext == null ||
                bot.HealthController?.IsAlive != true || !IsFinite(bot.Position))
            {
                return;
            }

            if (!FollowerWorldSafetyStates.TryGetValue(profileId, out FollowerWorldSafetyState state) || state == null)
            {
                state = new FollowerWorldSafetyState();
                FollowerWorldSafetyStates[profileId] = state;
            }

            if (Time.time < state.NextCheckAt)
            {
                return;
            }
            state.NextCheckAt = Time.time + WorldSafetyCheckIntervalSeconds;

            BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(profileId);
            if (follower?.IsTeleportStabilizing == true)
            {
                return;
            }

            Vector3 position = bot.Position;
            bool grounded = player.MovementContext.IsGrounded;
            bool sampled = NavMesh.SamplePosition(position, out NavMeshHit navHit, WorldSafetyNavSampleRadius, NavMesh.AllAreas);
            bool stableNav = sampled && Mathf.Abs(navHit.position.y - position.y) <= WorldSafetySafeNavVertical;

            if (grounded && stableNav)
            {
                state.HasSafeAnchor = true;
                state.LastSafeNavPosition = navHit.position;
                state.LastSafeNavAt = Time.time;
                return;
            }

            if (!state.HasSafeAnchor || grounded || stableNav || Time.time < state.RecoveryCooldownUntil ||
                Time.time - state.LastSafeNavAt > WorldSafetySafeAnchorMaxAgeSeconds)
            {
                return;
            }

            float fallDepth = state.LastSafeNavPosition.y - position.y;
            if (fallDepth < WorldSafetyEmergencyFallDepth)
            {
                return;
            }

            state.RecoveryCooldownUntil = Time.time + WorldSafetyRecoveryCooldownSeconds;
            WriteEvent("worldSafetyFallDetected", bot, new
            {
                position = Vec(position),
                lastSafeNavPosition = Vec(state.LastSafeNavPosition),
                lastSafeAge = Time.time - state.LastSafeNavAt,
                fallDepth,
                grounded,
                navSampled = sampled,
                threshold = WorldSafetyEmergencyFallDepth
            });

            // World-fall is a system safety event, not a route-quality failure. Release traversal
            // ownership without poisoning the learned edge's success/failure counters.
            if (TryGetActiveProbe(bot, out ProbeRuntime probe) && probe != null)
            {
                ReleaseProbeForLifecycle(probe, "worldSafetyFall");
            }
            LearnedTraversalCommitments.Remove(profileId);
            ProvisionalWalkThroughReservations.Remove(profileId);
            NavigationRecoveryTraversalAnchors.Remove(profileId);
            BreadcrumbFollowCommitments.Remove(profileId);
            PostTraversalEntryQuarantines.Remove(profileId);
            BreadcrumbBarrierDetourUntil.Remove(profileId);

            if (!FollowerSafeTeleport.TryValidateEmergencyAnchor(bot, state.LastSafeNavPosition, out Vector3 safeAnchor))
            {
                WriteEvent("worldSafetyRecoveryRejected", bot, new
                {
                    reason = "lastSafeAnchorValidationFailed",
                    requested = Vec(state.LastSafeNavPosition),
                    fallDepth
                });
                return;
            }

            long worldSafetyTeleportOrigin = PrepareForAutomaticRecoveryTeleport(bot, "worldSafety:lastSafeNav");
            if (worldSafetyTeleportOrigin <= 0)
            {
                return;
            }
            if (FollowerSafeTeleport.TryTeleport(bot, safeAnchor, "worldSafety:lastSafeNav",
                    out Vector3 teleportedTo, issuedTeleportGeneration: worldSafetyTeleportOrigin))
            {
                NotifyAutomaticRecoveryTeleportCompleted(bot, "worldSafety:lastSafeNav");
                state.HasSafeAnchor = true;
                state.LastSafeNavPosition = teleportedTo;
                state.LastSafeNavAt = Time.time;
                WriteEvent("worldSafetyRecovered", bot, new
                {
                    from = Vec(position),
                    to = Vec(teleportedTo),
                    fallDepth,
                    recovery = "lastSafeNav"
                });
                Logger.LogWarning($"[WorldSafety] Recovered follower '{GetBotName(bot)}' from an out-of-world fall depth={fallDepth:0.0}m.");
            }
        }

        private static void RecordFollowerSnapshot(BotOwner bot, DiagnosticFollowerState state)
        {
            try
            {
                Player leader = FollowerEnvironment.LocalPlayer;
                if (!IsLivePlayer(leader) || !IsFinite(bot.Position) || !IsFinite(leader.Position))
                {
                    return;
                }

                Vector3 botPosition = bot.Position;
                Vector3 leaderPosition = leader.Position;
                float leaderDistance = Vector3.Distance(botPosition, leaderPosition);
                float displacement = Vector3.Distance(botPosition, state.LastPosition);
                float distanceProgress = state.LastLeaderDistance < 0f
                    ? 0f
                    : state.LastLeaderDistance - leaderDistance;
                if (displacement >= 0.1f || distanceProgress >= 0.1f)
                {
                    state.LastProgressAt = Time.time;
                }
                state.LastPosition = botPosition;
                state.LastLeaderDistance = leaderDistance;
                // CF75: one passive sample per normal follower snapshot; never writes to BotMover.
                SampleCF75FreshFollowPhysicalWatch(bot, botPosition);

                StrictPathResult strict = CalculateStrictPath(botPosition, leaderPosition);
                BotPathController pathController = bot.Mover?.ActualPathController;
                Vector3? moverTarget = pathController?.TargetPoint;
                Vector3[] moverWaypoints = Array.Empty<Vector3>();
                if (pathController?.HavePath == true)
                {
                    try
                    {
                        moverWaypoints = pathController.GetWayPoints(16) ?? Array.Empty<Vector3>();
                    }
                    catch
                    {
                        moverWaypoints = Array.Empty<Vector3>();
                    }
                }

                BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(bot.ProfileId);
                string activeCommand = follower != null &&
                    follower.TryPeekActiveCommand(out FollowerCommandType command, out _, out _)
                    ? command.ToString()
                    : FollowerCommandType.None.ToString();

                NavMeshDoorLink currentDoorLink = bot.DoorOpener?._currentDoorLink;
                WriteEvent("followerSnapshot", bot, new
                {
                    breadcrumbSequence,
                    botPosition = Vec(botPosition),
                    leaderPosition = Vec(leaderPosition),
                    leaderDistance,
                    displacement,
                    distanceProgress,
                    noProgressSeconds = Mathf.Max(0f, Time.time - state.LastProgressAt),
                    playerState = bot.GetPlayer.CurrentStateName.ToString(),
                    grounded = bot.GetPlayer.MovementContext?.IsGrounded == true,
                    inputDirection = Vec2(bot.GetPlayer.InputDirection),
                    activeCommand,
                    combat = bot.Memory?.HaveEnemy == true,
                    strict = strict.ToPayload(),
                    mover = new
                    {
                        hasPath = pathController?.HavePath == true,
                        hasPathAndNoComplete = bot.Mover?.HasPathAndNoComplete == true,
                        blocked = bot.Mover?.Blocked == true,
                        isMoving = bot.Mover?.IsMoving == true,
                        pause = bot.Mover?.Pause == true,
                        sprinting = bot.Mover?.Sprinting == true,
                        realDestination = bot.Mover != null ? Vec(bot.Mover.RealDestPoint) : null,
                        currentCorner = pathController?.HavePath == true ? Vec(pathController.CurrentCornerPoint) : null,
                        target = moverTarget.HasValue ? Vec(moverTarget.Value) : null,
                        remainingDistance = pathController?.PlayerRemainingDist ?? 0f,
                        waypoints = moverWaypoints.Select(Vec).ToArray()
                    },
                    door = new
                    {
                        interacting = bot.DoorOpener?.Interacting == true,
                        haveDoorToOpen = bot.DoorOpener?.HaveDoorToOpen == true,
                        linkId = currentDoorLink?.Id,
                        state = currentDoorLink?.Door?.DoorState.ToString()
                    }
                });
            }
            catch (Exception ex)
            {
                DisableDiagnosticsAfterFailure("follower snapshot failed", ex);
            }
        }

        private static void ApplyTraversalMovementIsolation(ProbeRuntime probe)
        {
            if (probe?.Bot?.Mover == null)
            {
                return;
            }

            // R8.11: Physics pass-through does not prevent EFT BotMover.LocalAvoidance from
            // creating a lateral offset around another squad member. While PIT owns a precision
            // traversal transaction, the demonstrated corridor/entry is the movement authority.
            // Clear only the transient avoidance offset; world collision and all non-traversal
            // BotMover behavior remain intact outside this lease.
            try
            {
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-245ECAC116FC",@probe?.Bot);
            }
            catch
            {
                // Avoidance is optional movement state; traversal remains fail-open.
            }
        }

        private static void InterruptTraversalForImmediateSurvival(ProbeRuntime probe, string threat)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            string reason = "survivalPreempt:" + (string.IsNullOrWhiteSpace(threat) ? "SAIN" : threat);
            EPlayerState state = probe.Player != null ? probe.Player.CurrentStateName : default;

            // Never tear an EFT native vault/climb/jump capsule out from underneath its active
            // root-motion state.  Cancel future animator requests and release at the first safe
            // landing/state exit.  Flash blind-fire/steering can still run immediately; panic
            // locomotion becomes authoritative as soon as EFT exits the physical traversal state.
            if (IsProbeTraversalState(state) || state == EPlayerState.JumpLanding)
            {
                try
                {
                    probe.Player?.MovementContext?.MovementContextPlayerAnimatorSetDoVault("R1-146886345FA6",@probe?.Bot,false);
                    probe.Player?.MovementContext?.MovementContextPlayerAnimatorSetDoClimb("R1-D876A76C9219",@probe?.Bot,false);
                }
                catch
                {
                }

                if (!probe.AbortAfterLanding)
                {
                    probe.AbortAfterLanding = true;
                    WriteEvent("traversalSurvivalPreemptDeferred", probe.Bot, new
                    {
                        reason,
                        stage = probe.Stage.ToString(),
                        state = state.ToString()
                    });
                }
                return;
            }

            WriteEvent("traversalSurvivalPreempt", probe.Bot, new
            {
                reason,
                stage = probe.Stage.ToString(),
                state = state.ToString()
            });
            FollowerMovementWriterAuthority.AcquireCombat(probe.Bot, reason);
            ForceReleaseTraversalProbe(probe, reason);
        }

        private static void UpdateProbe(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Generation != raidGeneration)
            {
                return;
            }

            BotOwner bot = probe.Bot;
            Player player = probe.Player;
            if (!IsLiveBot(bot) || player?.MovementContext == null)
            {
                ReleaseProbeForLifecycle(probe, "selectedFollowerUnavailable");
                return;
            }

            ObserveLearningV338BodyBoundary(probe, "UpdateProbeEntry");

            FollowerMovementWriterAuthority.WriterDomain owner;
            long currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(bot, out owner);
            if ((owner == FollowerMovementWriterAuthority.WriterDomain.Teleport) &&
                probe.Stage == ProbeStage.Verify && probe.RecoveryExitAlreadySatisfied &&
                EnsureLearningV328TraversalAuthorityBeforeVerify(
                    probe, "verifyInvariantRepair"))
            {
                currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(bot, out owner);
                WriteEvent("learningV328VerifyAuthorityInvariantRepaired", bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    chainId = probe.TraversalChainId,
                    currentOwner = owner.ToString(),
                    currentGeneration,
                    probeGeneration = probe.MovementWriterGeneration
                });
            }
            bool teleportArmOwnsMovement =
                owner == FollowerMovementWriterAuthority.WriterDomain.Teleport &&
                probe.Stage == ProbeStage.TeleportArm;
            bool traversalOwnsMovement = owner == FollowerMovementWriterAuthority.WriterDomain.Traversal;
            bool walkThroughPreflightFollowOwnsMovement =
                (probe.LearningV330WalkThroughPreflightFollowAuthority) &&
                probe.Stage == ProbeStage.Aligning &&
                string.Equals(probe.RequestedTraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                owner == FollowerMovementWriterAuthority.WriterDomain.Follow;
            if (probe.MovementWriterGeneration <= 0 || currentGeneration != probe.MovementWriterGeneration ||
                (!traversalOwnsMovement && !teleportArmOwnsMovement && !walkThroughPreflightFollowOwnsMovement))
            {
                WriteEvent("traversalProbeMovementGenerationSuperseded", bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    chainId = probe.TraversalChainId,
                    probeGeneration = probe.MovementWriterGeneration,
                    currentGeneration,
                    currentOwner = owner.ToString(),
                    stage = probe.Stage.ToString()
                });
                ForceReleaseTraversalProbe(probe, "movementWriterGenerationSuperseded");
                return;
            }

            // RC8: a probe's origin generation, not an arbitrary current-owner
            // snapshot, is the sole ticket to its entire physical executor frame.
            FollowerMovementWriterAuthority.WriterDomain probeDomain =
                teleportArmOwnsMovement
                    ? FollowerMovementWriterAuthority.WriterDomain.Teleport
                    : (walkThroughPreflightFollowOwnsMovement
                        ? FollowerMovementWriterAuthority.WriterDomain.Follow
                        : FollowerMovementWriterAuthority.WriterDomain.Traversal);
            if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                bot, probeDomain, probe.MovementWriterGeneration,
                out FollowerMovementWriterAuthority.WriteScope probeExecutionScope,
                out string probeTicketRejection))
            {
                WriteEvent("v2ProbeExecutionOriginRejected", bot, new
                {
                    probeGeneration = probe.MovementWriterGeneration,
                    currentGeneration,
                    owner = owner.ToString(),
                    requestedDomain = probeDomain.ToString(),
                    reason = probeTicketRejection,
                    action = "rejectBeforeNativeProbeExecutorMutation"
                });
                return;
            }
            using (probeExecutionScope)
            {
                UpdateProbeWithMovementAuthority(probe);
                if (IsActiveProbe(probe))
                {
                    ObserveLearningV338BodyBoundary(probe, "UpdateProbeExit");
                }
            }
        }

        private static void UpdateLearningV349MonotonicPhysicalPassageProof(ProbeRuntime probe)
        {
            if ((probe?.Player == null) ||
                probe.LearningV349PhysicalPassageCrossed || !IsActiveProbe(probe) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return;
            }

            string kind = commitment.Kind ?? probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            bool crossed = false;
            string proof = string.Empty;
            float projection = 0f;
            float requiredProjection = 0f;
            float lateralDeviation = 0f;
            float exitDistance = float.PositiveInfinity;

            if (string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                crossed = probe.LearningV33PassageBoundaryState >= LearningV33PassageBoundaryState.CrossingCommitted;
                proof = "walkThroughPassageBoundaryCommitted";
            }
            else if (string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                crossed = probe.NativeDropDownAttempted && probe.NativeDropDownSawFarSide &&
                          (probe.NativeDropDownSawDescent || probe.NativeDropDownPhysicalLandingAuthority);
                proof = "dropDownFarSideDescentObserved";
            }
            else if (string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                     string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase))
            {
                crossed = (probe.NativeTraversalStarted || probe.NativeStateObserved ||
                           WasLearningV330NativeActuatorActuallyAttempted(probe)) &&
                          IsVaultClimbFarSideForEgress(
                              probe, commitment, out projection, out requiredProjection);
                proof = "vaultClimbFarSidePlaneCrossed";
            }
            else if (string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                crossed = probe.JumpAttempted && TryGetLearningV331CurrentGroundContinuationProof(
                    probe, commitment, out projection, out requiredProjection,
                    out lateralDeviation, out exitDistance);
                proof = "jumpSupportedFarSideTrajectory";
            }

            if (!crossed)
            {
                return;
            }

            probe.LearningV349PhysicalPassageCrossed = true;
            probe.LearningV349PhysicalPassageCrossedAt = Time.time;
            probe.LearningV349PhysicalPassagePosition = probe.Player.Position;
            probe.LearningV349PhysicalPassageReason = proof;
            WriteEvent("learningV349PhysicalPassageCrossed", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                episodeId = probe.TraversalEpisodeId,
                chainId = probe.TraversalChainId,
                kind,
                stage = probe.Stage.ToString(),
                position = Vec(probe.Player.Position),
                proof,
                projection,
                requiredProjection,
                lateralDeviation,
                exitDistance,
                monotonic = true,
                action = "preserveUpstreamPhysicalCrossingTruthAcrossLandingExitAndFollowConsumerFailures"
            });
        }

        private static void UpdateProbeWithMovementAuthority(ProbeRuntime probe)
        {
            if (!IsProbeLifecycleCurrent(probe)) { FinishProbeWithoutReanchor(probe,"lifecycleOriginChanged","mission, step or geometry changed"); return; }
            FollowerCapabilityProbeFrameDriver.Commit(new CapabilityProbeFramePort(probe));
        }

        private static bool TryConsumeLearningV385SameBodyDropDownPhysicalContinuation(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            Vector3 rawEntry,
            Vector3 rawExit,
            Vector3 direction,
            float forwardEntryProjection,
            float lateralEntryOffset,
            float alignmentAngle)
        {
            if ((probe?.Player?.MovementContext == null) ||
                probe.Bot == null || commitment == null || probe.LearningV32NativeEntryAcquired ||
                probe.NativeExecutorConsumed ||
                !string.Equals(commitment.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                !IsFinite(rawEntry) || !IsFinite(rawExit) || direction.sqrMagnitude < 0.5f)
            {
                return false;
            }

            // This is deliberately limited to the exact already-authorized same-chain successor.
            // It does not make historical DropDowns globally executable and it does not weaken the
            // standalone entry gate. NavStableAtArm is intentionally NOT required: a legitimate
            // DropDown successor is expected to leave NavMesh while gravity owns the same body.
            if (!TryGetLearningV354ContinuousSuccessorHandoffGuard(
                    probe, out ChainHandoffAuthorityGuard guard) || guard == null ||
                guard.ChainId != probe.TraversalChainId || guard.NextEdgeId != commitment.EdgeId ||
                !guard.SuccessorAuthorityAcquired)
            {
                return false;
            }

            Vector3 planarAxis = rawExit - rawEntry;
            planarAxis.y = 0f;
            float planarSpan = planarAxis.magnitude;
            if (planarSpan < 0.35f ||
                forwardEntryProjection <= NativeDropDownEntryMaxForwardOvershoot ||
                forwardEntryProjection >= planarSpan + AssistedAlreadyCrossedPlaneSlack ||
                lateralEntryOffset > NativeDropDownEntryMaxLateralOffset)
            {
                return false;
            }

            float verticalDropFromEntry = rawEntry.y - probe.Player.Position.y;
            if (verticalDropFromEntry < LearningV33DropDownCrossingMinVerticalDrop ||
                probe.Player.Position.y < rawExit.y - LearningV2RevisionVerticalTolerance ||
                IsFollowerAlreadyBelowDropDownLanding(
                    probe.Player.Position, rawEntry, rawExit, commitment.Exit))
            {
                return false;
            }

            // The body has physically left the standalone entry envelope in the demonstrated
            // successor direction. Rewinding to RawEntry would fight gravity and predecessor
            // momentum. Bind Native DropDown monitoring to this current body frontier instead;
            // landing/far-side proof remains unchanged and no success is minted here.
            MarkLearningV32NativeEntryAcquired(
                probe, rawEntry, rawExit,
                GetPlanarDistance(probe.Player.Position, rawEntry),
                alignmentAngle, lateralEntryOffset, forwardEntryProjection,
                "learningV385SameBodyDropDownPhysicalContinuation", directHandoff: true);

            if (!TryBeginNativeDropDown(
                    probe, commitment,
                    "learningV385SameBodyDropDownPhysicalContinuation",
                    out string startFailure))
            {
                FinalizeOrEscalateTraversalFailure(
                    probe, "learningV385SameBodyDropDownPhysicalContinuationStartFailed:" +
                    (startFailure ?? string.Empty));
                return true;
            }

            WriteEvent("learningV385SameBodyDropDownPhysicalContinuationAdopted", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                chainId = probe.TraversalChainId,
                completedEdgeId = guard.CompletedEdgeId,
                position = Vec(probe.Player.Position),
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                forwardEntryProjection,
                planarSpan,
                lateralEntryOffset,
                verticalDropFromEntry,
                predecessorNavStableAtArm = guard.NavStableAtArm,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "sameBodySuccessorAlreadyDescendingContinuePhysicalTrajectoryWithoutEntryRewind"
            });
            return true;
        }

