                probe, rawEntry, rawExit,
                GetPlanarDistance(probe.Player.Position, rawEntry),
                alignmentAngle,
                lateralEntryOffset, forwardEntryProjection,
                "learningV369DownstreamPhysicalFrontier", directHandoff: true);

            WriteEvent("learningV369DownstreamActuatorEntryAcquiredFromPhysicalFrontier", probe.Bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                edgeId = commitment.EdgeId,
                chainId = currentStep.ChainId,
                kind = commitment.Kind,
                position = Vec(probe.Player.Position),
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                forwardEntryProjection,
                planarSpan,
                lateralEntryOffset,
                maxLateral,
                verticalDeviation,
                normalForwardOvershoot,
                transitionFrontierInherited = learningV370ContinuousTransitionFrontier,
                action = learningV370ContinuousTransitionFrontier
                    ? "continuousCursorKeepsSameBodyActuatorFrontierAcrossTransitionNoCompletionCredit"
                    : "preserveCurrentBodyFrontierBeginActuatorWithoutEntryRewindNoCompletionCredit"
