                currentStepIndex <= 0 || currentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep previous = mission.Steps[currentStepIndex - 1];
            FollowerRouteMissionStep current = mission.Steps[currentStepIndex];
            if (previous == null || current == null ||
                previous.EpisodeId <= 0 || current.EpisodeId <= 0 ||
                previous.ChainId <= 0 || previous.ChainId != current.ChainId ||
                !previous.CurrentRaidRouteAuthority || !current.CurrentRaidRouteAuthority ||
                !string.Equals(current.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                !(string.Equals(previous.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                  string.Equals(previous.Kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                  string.Equals(previous.Kind, "Climb", StringComparison.OrdinalIgnoreCase)) ||
