        private static bool TryRejectLearningV430HistoricalEntryAcquisition(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            Vector3 rawEntry,
            Vector3 rawExit,
            string source)
        {
            if ((probe?.Player == null) || commitment == null ||
                !IsFinite(rawEntry) || !IsFinite(rawExit))
            {
                return false;
            }

            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < 0.25f)
            {
                return false;
            }

            Vector3 direction = axis / span;
            Vector3 currentDelta = probe.Player.Position - rawEntry;
            currentDelta.y = 0f;
            float currentProjection = Vector3.Dot(currentDelta, direction);
            bool dropDownCrossed =
                string.Equals(commitment.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                (probe.LearningV33PassageBoundaryState >= LearningV33PassageBoundaryState.CrossingCommitted ||
                 IsFollowerAlreadyBelowDropDownLanding(
                     probe.Player.Position, rawEntry, rawExit, commitment.Exit));
            bool monotonicPhysicalPassageCrossed =
                probe.LearningV349PhysicalPassageCrossed || dropDownCrossed;
            bool beyondExitPlane = FollowerCapabilityHelperRules.TryRejectLearningV430HistoricalEntryAcquisition_beyondExitPlane_1BB4CC9D_1(currentProjection,span);
            if (!monotonicPhysicalPassageCrossed || !beyondExitPlane)
            {
                return false;
            }

            bool persistentChronologyEvidenceChanged =
                RecordLearningV430MonotonicConsumerEvidence(
                    commitment.EdgeId,
                    "historicalEntryReacquireRejected",
                    source);
            WriteEvent("learningV430HistoricalEntryReacquireRejected", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                kind = commitment.Kind,
                source = source ?? "unknown",
                position = Vec(probe.Player.Position),
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                currentProjection,
                authoredSpan = span,
                passageState = probe.LearningV33PassageBoundaryState.ToString(),
                dropDownCrossed,
                beyondExitPlane,
                traversalSuccessRecorded = false,
                persistentLearningChanged = persistentChronologyEvidenceChanged,
                returnToEntry = false,
                action = "historicalNearSideEntryCannotReacquireAfterPhysicalConsumerCrossedFarSideFrontier"
            });
            BeginUnifiedTraversalEgressOrVerify(
                probe, "learningV430HistoricalEntryReacquireRejected:" + (source ?? "unknown"));
            return true;
        }

        // RC104: TryBeginLearningV32NativeEntryAcquisition lives in the shared native obstacle capability host.

        private static bool UpdateLearningV33MonotonicPassageBoundary(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            Vector3 rawEntry,
            Vector3 rawExit,
            Vector3 direction,
            float forwardEntryProjection,
            float lateralEntryOffset,
            float physicalForwardProgress,
            bool grounded)
        {
            if ((probe == null) || commitment == null ||
                probe.Player == null || !IsFinite(rawEntry) || !IsFinite(rawExit) ||
                direction.sqrMagnitude < 0.5f)
            {
                return false;
            }

            bool kindDropDown = string.Equals(commitment.Kind, "DropDown", StringComparison.OrdinalIgnoreCase);
            if (!kindDropDown)
            {
                // V3.3 deliberately does not manufacture generic crossing semantics for Vault,
                // Climb or Jump. Those kinds require their own native actuator evidence. Their
                // V3.2 entry gate remains byte-for-behaviour unchanged until runtime proves the
                // same side-transition bug for that actuator.
                return false;
            }

            float authoredDrop = Mathf.Max(0f, rawEntry.y - rawExit.y);
            float verticalDropFromEntry = rawEntry.y - probe.Player.Position.y;
            float verticalCommitThreshold = Mathf.Max(
                LearningV33DropDownCrossingMinVerticalDrop,
                authoredDrop * LearningV33DropDownCrossingVerticalFraction);

            // Preserve physical evidence gathered while the normal Mover/gravity is acquiring the
            // passage entry. For DropDown this drive already targets rawExit; if the body commits
            // the fall before the stable-entry timer completes, throwing this evidence away would
            // be a producer/consumer contract error rather than a failed Native attempt.
            float entryEpochDescent = probe.LearningV32NativeEntryStartPosition.y - probe.Player.Position.y;
            probe.LearningV33DropDownEntryMaxDescent = Mathf.Max(
                probe.LearningV33DropDownEntryMaxDescent, entryEpochDescent);
            probe.LearningV33DropDownEntryMaxForwardProjection = Mathf.Max(
                probe.LearningV33DropDownEntryMaxForwardProjection, forwardEntryProjection);
            if (!grounded && forwardEntryProjection >= LearningV32DropDownAirborneEvidenceMinProjection)
            {
                if (probe.LearningV33DropDownEntryAirborneSince < 0f)
                {
                    probe.LearningV33DropDownEntryAirborneSince = Time.time;
                }
                if (Time.time - probe.LearningV33DropDownEntryAirborneSince >= NativeDropDownMinAirborneSeconds)
                {
                    probe.LearningV33DropDownEntrySawAirborne = true;
                }
            }

            bool farSide = IsFollowerAlreadyBelowDropDownLanding(
                probe.Player.Position, rawEntry, rawExit, commitment.Exit);
            bool crossingCommitted = FollowerCapabilityHelperRules.UpdateLearningV33MonotonicPassageBoundary_crossingCommitted_0B7B5DEF_1(farSide,forwardEntryProjection,LearningV33DropDownCrossingMinForwardProjection,physicalForwardProgress,LearningV33DropDownCrossingMinForwardProgress,verticalDropFromEntry,verticalCommitThreshold,lateralEntryOffset,LearningV33DropDownCrossingMaxLateral);

            LearningV33PassageBoundaryState previousBoundaryState = probe.LearningV33PassageBoundaryState;
            LearningV33PassageBoundaryState nextState = previousBoundaryState;
            if (farSide)
            {
                nextState = LearningV33PassageBoundaryState.FarSide;
            }
            else if (crossingCommitted)
            {
                nextState = LearningV33PassageBoundaryState.CrossingCommitted;
            }
            else if (forwardEntryProjection >= -LearningV32DropDownAcquireNearSideDistance &&
                     lateralEntryOffset <= LearningV33DropDownCrossingMaxLateral)
            {
                nextState = LearningV33PassageBoundaryState.EntryBand;
            }
            else if (nextState == LearningV33PassageBoundaryState.Unknown)
            {
                nextState = LearningV33PassageBoundaryState.NearSide;
            }

            if ((int)nextState > (int)previousBoundaryState)
            {
                probe.LearningV33PassageBoundaryState = nextState;
                probe.LearningV33PassageBoundaryChangedAt = Time.time;
                WriteEvent("learningV33PassageBoundaryAdvanced", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    previousState = previousBoundaryState.ToString(),
                    state = nextState.ToString(),
                    position = Vec(probe.Player.Position),
                    rawEntry = Vec(rawEntry),
                    rawExit = Vec(rawExit),
                    forwardEntryProjection,
                    lateralEntryOffset,
                    physicalForwardProgress,
                    verticalDropFromEntry,
                    verticalCommitThreshold,
                    grounded
                });
            }

            if (probe.LearningV33PassageBoundaryState < LearningV33PassageBoundaryState.CrossingCommitted)
            {
                return false;
            }

            // Crossing authority is monotonic. A near-side reacquire started before the side flip
            // loses authority immediately; no Mover target may drag the body back through the portal.
            if (probe.LearningV32NativeEntryReacquireActive)
            {
                probe.LearningV32NativeEntryReacquireActive = false;
                WriteEvent("learningV33NearSideReacquireCancelledAfterCrossing", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    state = probe.LearningV33PassageBoundaryState.ToString(),
                    position = Vec(probe.Player.Position),
                    previousTarget = Vec(probe.LearningV32NativeEntryReacquireTarget),
                    forwardEntryProjection,
                    physicalForwardProgress,
                    verticalDropFromEntry
                });
            }

            // LearningV3.4 contract: CrossingCommitted is a threshold, not a state that must be
            // observed for one frame. The V3.3 producer can legitimately advance NearSide -> FarSide
            // in one fixed update. Consume that threshold crossing exactly once when the acquisition
            // epoch itself supplies physical forward/drop evidence. If the follower was already on
            // the far side when acquisition began (no physical progress in this epoch), keep V3.3's
            // proof-integrity behavior and egress without inventing a Native actuator after the fact.
            bool commitThresholdCrossed =
                previousBoundaryState < LearningV33PassageBoundaryState.CrossingCommitted &&
                probe.LearningV33PassageBoundaryState >= LearningV33PassageBoundaryState.CrossingCommitted;
            bool physicalCommitEvidence =
                FollowerCapabilityHelperRules.UpdateLearningV33MonotonicPassageBoundary_physicalCommitEvidence_0B7B5DEF_2(physicalForwardProgress,LearningV33DropDownCrossingMinForwardProgress,verticalDropFromEntry,verticalCommitThreshold) &&
                probe.LearningV33DropDownEntryMaxDescent >= NativeDropDownMinDescent &&
                !probe.AssistedReplayAttempted &&
                !probe.TraversalTeleportAttempted;

            if (!probe.LearningV34PassageCommitConsumed)
            {
                if ((!commitThresholdCrossed) || !physicalCommitEvidence)
                {
                    if (probe.LearningV33PassageBoundaryState == LearningV33PassageBoundaryState.FarSide &&
                        !probe.NativeExecutorConsumed)
                    {
                        return TryAcceptAlreadyCrossedBeforeAssistedReplay(
                            probe, commitment, "learningV34FarSideWithoutAcquisitionCommit");
                    }
                    return false;
                }

                probe.LearningV34PassageCommitConsumed = true;
                probe.LearningV34PassageCommitConsumedAt = Time.time;
                WriteEvent("learningV34PassageCommitConsumed", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    previousState = previousBoundaryState.ToString(),
                    state = probe.LearningV33PassageBoundaryState.ToString(),
                    position = Vec(probe.Player.Position),
                    rawEntry = Vec(rawEntry),
                    rawExit = Vec(rawExit),
                    forwardEntryProjection,
                    lateralEntryOffset,
                    physicalForwardProgress,
                    verticalDropFromEntry,
                    verticalCommitThreshold,
                    skippedExactCrossingCommittedState =
                        probe.LearningV33PassageBoundaryState == LearningV33PassageBoundaryState.FarSide &&
                        previousBoundaryState < LearningV33PassageBoundaryState.CrossingCommitted
                });

                // The body is now physically on/through the DropDown boundary. V3.3 re-issued
                // GoToPointNoWay(rawExit) but left BotMover's previous near-side path controller
                // alive; runtime edge20 then reported a lower-floor body while CurrentCorner still
                // pointed to the upper ledge. Rebuild the Mover from the CURRENT body position before
                // beginning the Native execution epoch. This is a topology handoff, not a retry,
                // teleport, SetPosition, tolerance increase or extra learning authority.
                if (!TryInstallLearningV34FarSideMoverRebase(
                        probe, commitment, rawEntry, rawExit, direction,
                        forwardEntryProjection, physicalForwardProgress, verticalDropFromEntry))
                {
                    WriteEvent("learningV34PassageCommitNativeContinuationBlocked", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        kind = commitment.Kind,
                        reason = "farSideMoverRebaseFailed",
                        position = Vec(probe.Player.Position),
                        state = probe.LearningV33PassageBoundaryState.ToString(),
                        nativeExecutorConsumed = probe.NativeExecutorConsumed
                    });
                    return probe.LearningV33PassageBoundaryState == LearningV33PassageBoundaryState.FarSide &&
                        TryAcceptAlreadyCrossedBeforeAssistedReplay(
                            probe, commitment, "learningV34FarSideMoverRebaseFailed");
                }
            }

            if (!probe.LearningV34FarSideMoverRebaseSucceeded)
            {
                return false;
            }

            if (!probe.NativeExecutorConsumed)
            {
                MarkLearningV32NativeEntryAcquired(
                    probe, rawEntry, rawExit,
                    GetPlanarDistance(probe.Player.Position, rawEntry),
                    0f,
                    lateralEntryOffset,
                    forwardEntryProjection,
                    "learningV34PassageCommitConsumed",
                    directHandoff: false);

                if (TryBeginNativeDropDown(
                        probe, commitment, "learningV34PassageCommitConsumed", out string nativeFailure))
                {
                    // The execution epoch begins after the Mover topology rebase, but its proof
                    // carries the immediately preceding collision/gravity acquisition evidence.
                    probe.NativeDropDownStartPosition = probe.LearningV32NativeEntryStartPosition;
                    bool carriedPhysicalDropEvidence = FollowerCapabilityHelperRules.UpdateLearningV33MonotonicPassageBoundary_carriedPhysicalDropEvidence_0B7B5DEF_3(probe.LearningV33DropDownEntrySawAirborne,verticalDropFromEntry,verticalCommitThreshold,physicalForwardProgress,LearningV33DropDownCrossingMinForwardProgress,probe.AssistedReplayAttempted,probe.TraversalTeleportAttempted);
                    probe.NativeDropDownSawAirborne = carriedPhysicalDropEvidence;
                    probe.NativeDropDownSawDescent =
                        probe.LearningV33DropDownEntryMaxDescent >= NativeDropDownMinDescent;
                    Vector3 axis = rawExit - rawEntry;
                    axis.y = 0f;
                    float planarLength = Mathf.Max(0.01f, axis.magnitude);
                    float requiredProjection = FollowerCapabilityDropDownTransitionPolicy.RequiredProjection(planarLength, NativeDropDownFarSideRatio);
                    probe.NativeDropDownSawFarSide =
                        probe.LearningV33DropDownEntryMaxForwardProjection >= requiredProjection;
                    if (!grounded && probe.LearningV33DropDownEntryAirborneSince >= 0f)
                    {
                        probe.NativeDropDownAirborneSince = probe.LearningV33DropDownEntryAirborneSince;
                    }
                    probe.NativeDropDownBestForwardProjection = Mathf.Max(
                        probe.NativeDropDownBestForwardProjection,
                        probe.LearningV33DropDownEntryMaxForwardProjection);
                    WriteEvent("learningV34DropDownNativeExecutionContinuedFromPassageCommit", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        position = Vec(probe.Player.Position),
                        state = probe.LearningV33PassageBoundaryState.ToString(),
                        forwardEntryProjection,
                        physicalForwardProgress,
                        moverRebased = probe.LearningV34FarSideMoverRebaseSucceeded,
                        carriedSawAirborne = probe.NativeDropDownSawAirborne,
                        carriedPhysicalDropEvidence,
                        carriedSawDescent = probe.NativeDropDownSawDescent,
                        carriedSawFarSide = probe.NativeDropDownSawFarSide,
                        carriedMaxDescent = probe.LearningV33DropDownEntryMaxDescent,
                        carriedMaxForwardProjection = probe.LearningV33DropDownEntryMaxForwardProjection
