                    return true;
                }

                WriteEvent("learningV34DropDownNativeContinuationRejected", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    position = Vec(probe.Player.Position),
                    state = probe.LearningV33PassageBoundaryState.ToString(),
                    moverRebased = probe.LearningV34FarSideMoverRebaseSucceeded,
                    failure = nativeFailure ?? string.Empty
                });
            }

            return false;
        }

        private static bool TryInstallLearningV34FarSideMoverRebase(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            Vector3 rawEntry,
            Vector3 rawExit,
            Vector3 direction,
            float forwardEntryProjection,
            float physicalForwardProgress,
            float verticalDropFromEntry)
        {
            if ((probe?.Bot?.Mover == null) || probe.Player == null ||
                commitment == null || !IsFinite(rawEntry) || !IsFinite(rawExit))
            {
                return false;
            }

            bool preHavePath = false;
            bool preCornerValid = false;
            Vector3 preCorner = Vector3.zero;
            float preCornerProjection = 0f;
            float preCornerVerticalDrop = 0f;
            try
            {
                var prePath = probe.Bot.Mover.ActualPathController;
                preHavePath = prePath?.HavePath == true;
                if (preHavePath)
                {
                    preCorner = prePath.CurrentCornerPoint;
                    preCornerValid = IsFinite(preCorner);
                    if (preCornerValid)
                    {
                        Vector3 fromEntry = preCorner - rawEntry;
                        fromEntry.y = 0f;
                        preCornerProjection = Vector3.Dot(fromEntry, direction);
                        preCornerVerticalDrop = rawEntry.y - preCorner.y;
                    }
                }
            }
            catch
            {
            }

            try
            {
                // V3.4 only does this after acquisition has physically crossed the passage commit
                // threshold. This is intentionally different from CompileFix45.1, which stopped the
                // Mover BEFORE the ledge and froze every DropDown. Here the body is already through
                // the boundary, so Stop() is used once to discard the stale near-side path topology,
                // then the ordinary Mover is rebuilt from the current body position to rawExit.
                probe.Bot.Mover.SetBotMoverPause("R1-D80E67B0D7D8",@probe?.Bot,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-F876B20FF245",@probe?.Bot);
                probe.Bot.Mover.BotMoverStop("R1-975D95013002",@probe?.Bot);
                probe.Bot.Mover.SetBotMoverPause("R1-A392608EAD80",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverGoToPointNoWay("R1-03144B907757",@probe?.Bot,rawExit);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-788F5332DB1B",@probe?.Bot,direction);
            }
            catch (Exception ex)
            {
                probe.LearningV34FarSideMoverRebaseSucceeded = false;
                WriteEvent("learningV34FarSideMoverRebaseFailed", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    position = Vec(probe.Player.Position),
                    rawEntry = Vec(rawEntry),
                    rawExit = Vec(rawExit),
                    preHavePath,
                    preCorner = preCornerValid ? (object)Vec(preCorner) : null,
                    preCornerProjection,
                    preCornerVerticalDrop,
                    failure = ex.GetType().Name
                });
                return false;
            }

            bool postHavePath = false;
            bool postCornerValid = false;
            Vector3 postCorner = Vector3.zero;
            float postCornerProjection = 0f;
            float postCornerVerticalDrop = 0f;
            try
            {
                var postPath = probe.Bot.Mover.ActualPathController;
                postHavePath = postPath?.HavePath == true;
                if (postHavePath)
                {
                    postCorner = postPath.CurrentCornerPoint;
                    postCornerValid = IsFinite(postCorner);
                    if (postCornerValid)
                    {
                        Vector3 fromEntry = postCorner - rawEntry;
                        fromEntry.y = 0f;
                        postCornerProjection = Vector3.Dot(fromEntry, direction);
                        postCornerVerticalDrop = rawEntry.y - postCorner.y;
                    }
                }
            }
            catch
            {
            }

            probe.LearningV34FarSideMoverRebaseSucceeded = true;
            WriteEvent("learningV34FarSideMoverRebaseInstalled", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                kind = commitment.Kind,
                position = Vec(probe.Player.Position),
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                forwardEntryProjection,
                physicalForwardProgress,
                verticalDropFromEntry,
                preHavePath,
                preCorner = preCornerValid ? (object)Vec(preCorner) : null,
                preCornerProjection,
                preCornerVerticalDrop,
                postHavePath,
                postCorner = postCornerValid ? (object)Vec(postCorner) : null,
                postCornerProjection,
                postCornerVerticalDrop,
                realDestination = Vec(probe.Bot.Mover.RealDestPoint),
                action = "stopNearSidePathThenRebuildFromCurrentBodyToRawExit"
            });
            return true;
        }

