        private static void DriveCompatibilityTraversalMicroSettle(
            ProbeRuntime probe,
            Vector3 rawEntry,
            Vector3 edgeDirection,
            float alignmentAngle,
            float lateralEntryOffset,
            float forwardEntryProjection)
        {
            if (probe?.Bot?.Mover == null || probe.Player?.MovementContext == null)
            {
                return;
            }

            if (probe.CompatibilityMicroSettleStartedAt < 0f)
            {
                probe.CompatibilityMicroSettleStartedAt = Time.time;
                WriteEvent("compatibilityTraversalMicroSettleStarted", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.RequestedTraversalKind,
                    alignmentAngle,
                    lateralEntryOffset,
                    forwardEntryProjection
                });
            }

            Vector3 target = rawEntry;
            bool needsLaneRecovery = FollowerCapabilityHelperRules.DriveCompatibilityTraversalMicroSettle_needsLaneRecovery_538605C3_1(lateralEntryOffset,CompatibilityTraversalEntryMaxLateralOffset,forwardEntryProjection,CompatibilityTraversalEntryMaxForwardOvershoot);
            if (needsLaneRecovery && edgeDirection.sqrMagnitude > 0.5f)
            {
                target -= edgeDirection * CompatibilityTraversalMicroSettleBackstep;
            }

            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-2570D79C7403",@probe?.Bot,false);
                if (probe.Bot.Mover.Sprinting)
                {
                    probe.Bot.Mover.BotMoverSprint("R1-5985E1F2E923",@probe?.Bot,false,false);
                }
                if (Time.time >= probe.RollingApproachNextDirectPointAt && IsFinite(target))
                {
                    probe.Bot.Mover.BotMoverGoToPointNoWay("R1-522E30904240",@probe?.Bot,target);
                    probe.RollingApproachNextDirectPointAt = Time.time + 0.12f;
                }
                float governedSpeed = alignmentAngle > 35f
                    ? 0.20f
                    : CompatibilityTraversalMicroSettleMoveSpeed;
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-0762B29D5AAD",@probe?.Bot,governedSpeed);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-ACF016839905",@probe?.Bot,edgeDirection);
                // Do not Stop/StopMove here. Steering keeps the body turning while a tiny amount of
                // translation remains available to centre the capsule on the demonstrated lane.
                DriveTraversalPoseAcquisition(
                    probe, edgeDirection, alignmentAngle, "compatibilityMicroSettle", false);
            }
            catch
            {
            }

            if (Time.time - probe.CompatibilityMicroSettleStartedAt >= CompatibilityTraversalMicroSettleSeconds &&
                ShouldEmitDiagnostic("compatibilityTraversalMicroSettleProgress", probe.Bot, 0.45f))
            {
                WriteEvent("compatibilityTraversalMicroSettleProgress", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.RequestedTraversalKind,
                    elapsed = Time.time - probe.CompatibilityMicroSettleStartedAt,
                    alignmentAngle,
                    lateralEntryOffset,
                    forwardEntryProjection,
                    target = Vec(target)
                });
            }
        }


        private static void DriveTraversalPoseAcquisition(
            ProbeRuntime probe,
            Vector3 desiredDirection,
            float alignmentAngle,
            string source,
            bool stopTranslationWhenMisaligned)
        {
            if (probe?.Bot == null || probe.Player?.MovementContext == null)
            {
                return;
            }

            desiredDirection = GetFlatDirection(desiredDirection);
            if (desiredDirection.sqrMagnitude < 0.5f)
            {
                return;
            }

            if (probe.PoseLastAlignmentProgressAt <= 0f)
            {
                probe.PoseLastAlignmentProgressAt = Time.time;
                probe.PoseLastAlignmentAngle = alignmentAngle;
            }
            else if (alignmentAngle + TraversalPoseProgressAngleEpsilon < probe.PoseLastAlignmentAngle)
            {
                probe.PoseLastAlignmentAngle = alignmentAngle;
                probe.PoseLastAlignmentProgressAt = Time.time;
                if (probe.PoseExclusiveOrientationAuthority && alignmentAngle <= 18f)
                {
                    WriteEvent("traversalPoseAuthorityRelaxed", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.RequestedTraversalKind,
                        source,
                        alignmentAngle,
                        recoveryAttempts = probe.PoseRecoveryAttempts
                    });
                    probe.PoseExclusiveOrientationAuthority = false;
                }
            }

            // CompileFix50 passage pose authority: normal Steering owns modest corrections across a
            // multi-edge passage. Hard Stop/Transform yaw is reserved for a genuinely wrong heading;
            // this avoids the visible look-back on every WT/Vault fragment in the same passage.
            bool alignmentStalled =
                alignmentAngle > 28f &&
                Time.time - probe.PoseLastAlignmentProgressAt >= TraversalPoseEscalationNoProgressSeconds;
            if (alignmentStalled)
            {
                probe.PoseExclusiveOrientationAuthority = true;
            }

            if (probe.PoseExclusiveOrientationAuthority)
            {
                if (Time.time >= probe.PoseNextHardResetAt)
                {
                    probe.PoseNextHardResetAt = Time.time + TraversalPoseHardResetInterval;
                    probe.PoseRecoveryAttempts++;
                    try
                    {
                        probe.Bot.Mover?.BotMoverSprint("R1-DA8B16EECEF6",@probe?.Bot,false,false);
                        probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-999B8946C40E",@probe?.Bot);
                        probe.Bot.Mover?.BotMoverStop("R1-E2067F4F5111",@probe?.Bot);
