        private static bool TryTraversalPoseLastResortRecovery(ProbeRuntime probe, string source)
        {
            if (probe == null || probe.LearnedEdgeId <= 0 ||
                probe.PoseRecoveryAttempts < TraversalPoseRecoveryAttemptsBeforeHardRecovery ||
                Time.time - probe.RequestedAt < RouteMissionHardRecoverySeconds)
            {
                return false;
            }

            if (!IsTraversalHardStuck(probe, out string stuckReason))
            {
                return false;
            }

            WriteEvent("traversalPoseLastResortEligible", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.RequestedTraversalKind,
                source,
                recoveryAttempts = probe.PoseRecoveryAttempts,
                heldFor = Time.time - probe.RequestedAt,
                stuckReason
            });
            return TryTeleportPlayerValidatedTraversalAtExit(
                probe,
                "poseRecoveryExhausted:" + source + ":" + stuckReason);
        }


        private static int RegisterTraversalLocalRecovery(ProbeRuntime probe, string source)
        {
            if (probe?.Bot == null || string.IsNullOrEmpty(probe.Bot.ProfileId))
            {
                return probe?.PoseRecoveryAttempts ?? 0;
            }
            if (FollowerRouteMissions.TryGetValue(probe.Bot.ProfileId, out FollowerRouteMission mission) && mission != null)
            {
                bool counted = Time.time >= mission.NextLocalRecoveryCountAt;
                if (counted)
                {
                    mission.LocalRecoveryAttempts++;
                    mission.NextLocalRecoveryCountAt = Time.time + RouteMissionLocalRecoveryCountInterval;
                }
                if (counted || ShouldEmitDiagnostic("followerRouteMissionLocalRecovery:" + (source ?? "unknown"), probe.Bot, 0.75f))
                {
                    WriteEvent("followerRouteMissionLocalRecovery", probe.Bot, new
                    {
                        missionId = mission.MissionId,
                        edgeId = probe.LearnedEdgeId,
                        source,
                        counted,
                        localRecoveryAttempts = mission.LocalRecoveryAttempts
                    });
                }
                return mission.LocalRecoveryAttempts;
            }
            return probe.PoseRecoveryAttempts;
        }

        private static bool CanUseFinalTraversalRecovery(ProbeRuntime probe, string source, out string stuckReason)
        {
            stuckReason = string.Empty;
            if (probe == null)
            {
                return false;
            }

            bool provenWalkThrough = TryGetProvenWalkThroughRecoveryTrust(probe, out int physicalSuccesses);
            bool terminalizedAssistedTraversal = probe.AssistedReplayTerminalized &&
                (string.Equals(probe.TraversalKind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(probe.TraversalKind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(probe.TraversalKind, "DropDown", StringComparison.OrdinalIgnoreCase));
            float requiredHeldSeconds = provenWalkThrough
                ? ProvenWalkThroughHardRecoverySeconds
                : (terminalizedAssistedTraversal
                    ? AssistedTraversalFailedHardRecoverySeconds
                    : RouteMissionHardRecoverySeconds);
            int requiredLocalRecoveries = provenWalkThrough
                ? ProvenWalkThroughLocalRecoveriesBeforeTeleport
                : (terminalizedAssistedTraversal
                    ? AssistedTraversalFailedLocalRecoveriesBeforeTeleport
                    : RouteMissionMaxLocalRecoveriesBeforeTeleport);

            if (Time.time - probe.RequestedAt < requiredHeldSeconds)
            {
                return false;
            }

            string profileId = probe.Bot?.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) &&
                FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) && mission != null &&
                mission.LocalRecoveryAttempts < requiredLocalRecoveries)
            {
                return false;
            }

            if (!IsTraversalHardStuck(probe, out stuckReason))
            {
                return false;
            }

            WriteEvent("traversalFinalRecoveryEligible", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                source,
                heldFor = Time.time - probe.RequestedAt,
                stuckReason,
                provenWalkThrough,
                physicalSuccesses,
                requiredHeldSeconds,
                requiredLocalRecoveries
            });
            return true;
        }

        private static bool TryGetProvenWalkThroughRecoveryTrust(ProbeRuntime probe, out int physicalSuccesses)
        {
            physicalSuccesses = 0;
            if (probe == null || probe.LearnedEdgeId <= 0 ||
                !string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind, "WalkThrough", StringComparison.Ordinal))
            {
                return false;
            }

            // V3.19: fast hard-recovery timing is location evidence. Do not inherit it from the
            // Native-Proven template at an unseen geometry; transient transfer gets the ordinary
            // bounded recovery window and its own raid-local retry lease.
            if (TryGetLearningV319TransientSkillTransfer(probe, out _))
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == probe.LearnedEdgeId);
            if (edge == null)
            {
                return false;
            }

            physicalSuccesses = GetTraversalPhysicalSuccessCount(edge);
            return physicalSuccesses >= ProvenWalkThroughFastRecoverySuccesses;
        }

        private static void UpdateProbeAlignment(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Bot?.Mover == null || probe.Player?.MovementContext == null)
            {
                return;
            }

            BotOwner bot = probe.Bot;
            Player player = probe.Player;
            bot.Mover.SetBotMoverPause("R1-D1666CC86989",@bot,false);

            Vector3 actualForward = GetFlatDirection(player.MovementContext.PlayerRealForward);
            float angle = actualForward.sqrMagnitude > 0.5f
                ? Vector3.Angle(actualForward, probe.RequestedDirection)
                : 180f;

            bool rollingAlignment = FollowerCapabilityHelperRules.UpdateProbeAlignment_rollingAlignment_98802E5C_1(probe.PreviousSprinting,probe.PreviousRunning,angle,ProbeRollingAlignmentAngle);
            probe.MomentumRollingApproach = rollingAlignment;
            if (rollingAlignment)
            {
                ApplyProbeLocomotionIntent(probe, 0.55f, allowSprint: true);
            }
            else if (angle > 35f)
            {
                if (bot.Mover.Sprinting)
                {
                    bot.Mover.BotMoverSprint("R1-9C45F26CC4DA",@bot,false,false);
                    probe.SprintTemporarilySuppressed = true;
                }
                bot.BotOwnerSetTargetMoveSpeed("R1-D20130EF56C6",@bot,0f);
            }
            else
            {
                ApplyProbeLocomotionIntent(probe, 0.55f, allowSprint: angle <= ProbeRollingAlignmentAngle);
            }

            // R8.8: angle is a control error to correct, not a pass/fail gate. If ordinary
            // Steering does not reduce it, DriveTraversalPoseAcquisition clears competing movement
            // writers and ultimately rotates the body yaw while leaving capsule position untouched.
            DriveTraversalPoseAcquisition(probe, probe.RequestedDirection, angle, "probeAlignment", true);

            if (angle <= 12f)
            {
                if (probe.AlignStableSince < 0f)
                {
                    probe.AlignStableSince = Time.time;
                }
                else if (Time.time - probe.AlignStableSince >= ProbeAlignStableTime)
                {
                    probe.PoseExclusiveOrientationAuthority = false;
                    if (probe.ApproachCompleted)
                    {
                        BeginProbePriming(probe, angle);
                    }
                    else
                    {
                        BeginProbeApproach(probe, angle);
                    }
                    return;
                }
            }
            else
            {
                probe.AlignStableSince = -1f;
            }

            if (IsActiveProbe(probe) && Time.time - probe.StageStartedAt > ProbeAlignTimeout)
            {
                WriteEvent("traversalPoseAcquisitionCycle", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.RequestedTraversalKind,
                    stage = probe.Stage.ToString(),
                    angle,
                    recoveryAttempts = probe.PoseRecoveryAttempts,
                    action = "continueCorrection"
                });
                probe.StageStartedAt = Time.time;
                probe.AlignStableSince = -1f;
                probe.PoseExclusiveOrientationAuthority = true;
                if (TryTraversalPoseLastResortRecovery(probe, "probeAlignment"))
                {
                    return;
                }
            }
        }

        private static bool TryGetLearningV367WalkThroughFiniteProgress(
            ProbeRuntime probe,
            out float projection,
            out float span,
            out float lateral,
            out float verticalDeviation)
        {
            projection = 0f;
            span = 0f;
            lateral = float.MaxValue;
            verticalDeviation = float.MaxValue;
            if ((probe?.Player == null))
            {
                return false;
            }

            Vector3 rawEntry = IsFinite(probe.WalkThroughRawEntry)
                ? probe.WalkThroughRawEntry
                : probe.WalkThroughEntry;
            Vector3 rawExit = IsFinite(probe.WalkThroughTarget)
                ? probe.WalkThroughTarget
                : probe.WalkThroughRawExit;
            if (!IsFinite(rawEntry) || !IsFinite(rawExit))
            {
                return false;
            }

            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            span = axis.magnitude;
            if (span < 0.25f)
            {
                return false;
            }

            Vector3 direction = axis / span;
            Vector3 bodyDelta = probe.Player.Position - rawEntry;
            bodyDelta.y = 0f;
            projection = Vector3.Dot(bodyDelta, direction);
            Vector3 projectedOnAxis = rawEntry + direction * projection;
            lateral = GetPlanarDistance(probe.Player.Position, projectedOnAxis);
            float routeT = Mathf.Clamp01(projection / span);
            float expectedY = Mathf.Lerp(rawEntry.y, rawExit.y, routeT);
            verticalDeviation = Mathf.Abs(probe.Player.Position.y - expectedY);
            return true;
        }

