            // itself is never a traversal pose contract. Outside the envelope, angle is telemetry
            // for the mover-owned approach only. Inside, the authored corridor is the one and only
            // orientation contract.
            float angle = converged ? corridorAlignmentAngle : entryApproachAngle;
            bool currentNavSampled = NavMesh.SamplePosition(
                player.Position, out _, 0.55f, NavMesh.AllAreas);
            bool learningV373OffNavEntryEpochReady =
                !true ||
                !probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority ||
                learningV372EpisodeCorridorEntryLane;
            if (!currentNavSampled &&
                entryDistance <= WalkThroughOffNavMeshNearEntryDistance &&
                corridorAlignmentAngle <= WalkThroughOffNavMeshNearEntryMaxAlignment &&
                learningV373OffNavEntryEpochReady)
            {
                // CompileFix16: position convergence, not yaw, is the missing authority here.
                // A player-proven private corridor may begin just off NavMesh; when the body is
                // already aligned and near the authored entry, enter the direct corridor instead
                // of repeatedly forcing a zero-degree yaw correction.
                probe.PoseExclusiveOrientationAuthority = false;
                probe.AlignStableSince = -1f;
                WriteEvent("walkThroughOffNavMeshNearEntryAccepted", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    entryDistance,
                    alignmentAngle = corridorAlignmentAngle,
                    position = Vec(player.Position),
                    entry = Vec(entry)
                });
                BeginWalkThroughProbe(probe, corridorAlignmentAngle);
                return;
            }
            if (!currentNavSampled &&
                entryDistance <= WalkThroughOffNavMeshNearEntryDistance &&
                corridorAlignmentAngle <= WalkThroughOffNavMeshNearEntryMaxAlignment &&
                !learningV373OffNavEntryEpochReady &&
                ShouldEmitDiagnostic("learningV373OffNavWalkThroughEntryRejectedOutsideCurrentEpisode:" +
                    probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.35f))
            {
                WriteEvent("learningV373OffNavWalkThroughEntryRejectedOutsideCurrentEpisode", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    episodeId = probe.TraversalEpisodeId,
                    entryDistance,
                    alignmentAngle = corridorAlignmentAngle,
                    episodeCorridorWitness = learningV372EpisodeCorridorWitness,
                    episodeProjectedS = learningV372EntryProjectedS,
                    episodeLateral = learningV372EntryLateral,
                    episodeVerticalDeviation = learningV372EntryVerticalDeviation,
                    action = "offNavDirectStartCannotBypassCurrentEpisodePhysicalLane"
                });
            }

            // CF19-A: Do not keep the OLD entry mover producer after the current body has
            // demonstrably gone past the finite WT exit *outside* this episode's corridor.
            // CF18 Edge131 advanced >14 m while the entry vector was ~170 deg backwards,
            // yet the Aligning probe kept targeting the old entry and eventually entered
            // Teleport/SafetyHold.  No missing corridor witness can be converted to success.
            // This is a bounded failure/authority release, not a skipped traversal or a
            // reverse relocation. Preserve all V367/V372 strict success gates unchanged.
            bool cf19MissedEntryMovingDownstream = false;
            if (!probe.LearningV367WalkThroughEntryFrontierAcquired &&
                learningV367FiniteProgress && !converged &&
                learningV367PreviousProjection >= 0f &&
                learningV367Projection >= learningV367Span + 0.25f &&
                entryDistance > WalkThroughEntryTolerance &&
                (learningV367Lateral > WalkThroughPassageStraightLateralTolerance ||
                 learningV367VerticalDeviation > WalkThroughMaxVerticalDelta + 0.20f))
            {
                Vector3 cf19Velocity = player.Velocity;
                cf19Velocity.y = 0f;
                cf19MissedEntryMovingDownstream = cf19Velocity.magnitude > 0.75f &&
                    corridorDirection.sqrMagnitude > 0.5f &&
                    Vector3.Dot(cf19Velocity.normalized, corridorDirection) > 0.35f;
            }
            if (cf19MissedEntryMovingDownstream)
            {
                if(TryRequestCapabilityFullRouteRetry(probe,"cf19WTUnwitnessedDownstreamEntryEscape",true))return;
                Vector3 cf19CurrentBody = player.Position;
                bool cf19Retired = TryRetireNativeMoverPathPreserveLocomotion(
                    bot, "cf19WTUnwitnessedDownstreamEntryEscape", out string cf19RetireDetail);
                bool cf19Scrubbed = TryScrubLearningV364NativeMoverEpochAnchor(
                    bot, cf19CurrentBody, "cf19WTUnwitnessedDownstreamEntryEscape",
                    out string cf19ScrubDetail);
                WriteEvent("cf19WalkThroughExpiredEntryProducerReleased", bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    episodeId = probe.TraversalEpisodeId,
                    chainId = probe.TraversalChainId,
                    entryDistance,
                    projection = learningV367Projection,
                    span = learningV367Span,
                    lateral = learningV367Lateral,
                    verticalDeviation = learningV367VerticalDeviation,
                    physicalEntryWitness = false,
                    retireSucceeded = cf19Retired,
                    retireDetail = cf19RetireDetail,
                    nativeEpochScrubbed = cf19Scrubbed,
                    scrubDetail = cf19ScrubDetail,
                    body = Vec(cf19CurrentBody),
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "unwitnessedDownstreamOffCorridorMustReleaseExpiredEntryTargetBeforeTeleportEscalation"
                });
                ClearLearnedTraversalCommitment(
                    bot, probe.LearnedEdgeId, "cf19WTUnwitnessedDownstreamEntryEscape");
                FinishProbeWithoutReanchor(
                    probe, "cf19WTUnwitnessedDownstreamEntryEscape",
                    "Current body physically beyond finite WT exit but outside the authored corridor; reject stale entry mover without manufacturing success");
                // A rejected entry can no longer own a Route Mission asking the body
                // to drive backwards through a physically missed corridor. Release
                // only the runtime mission, give the exact failed edge a bounded retry
                // cooldown, and let ordinary fresh-route selection proceed. Do not
                // advance execution/breadcrumb floors or register a physical success.
                if (!string.IsNullOrEmpty(bot.ProfileId))
                {
                    string cf19ProfileId = bot.ProfileId;
                    string cf19RetryKey = cf19ProfileId + ":" +
                        probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture);
                    LearnedTraversalRetryAfter[cf19RetryKey] = Time.time + FarSideFailureRetryCooldownSeconds;
                    RemoveLifecycleMission(cf19ProfileId, "UpdateWalkThroughEntryConvergence");
                    FollowRejectLeases.Remove(cf19ProfileId);
                    EndLearningV375PersistentRouteTransaction(
                        bot, "cf19UnwitnessedWTEntryProducerRetired");
                    FollowerMovementWriterAuthority.TransitionTraversalToFollowIfIdleExact(bot, probe.MovementWriterGeneration, "cf19UnwitnessedWTEntryProducerRetired");
                    WriteEvent("cf19ExpiredEntryMissionReplanAdmitted", bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        episodeId = probe.TraversalEpisodeId,
                        cooldownSeconds = FarSideFailureRetryCooldownSeconds,
                        successCredited = false,
                        executionFloorAdvanced = false,
                        bodyRelocated = false,
                        action = "releaseOnlyRuntimeFailedMissionAllowFreshRouteToAvoidHistoricalEntryReplay"
                    });
                }
                return;
            }

            if (!converged)
            {
                if (true)
                {
                    // V3.12: BotMover owns translation to the entry anchor. Do not convert the
                    // instantaneous bot->entry vector into exclusive body-yaw authority. Runtime
                    // edge22 proved that doing so can force one yaw toward the anchor, then force a
                    // second near-opposite yaw to corridorDirection as soon as the 0.90m envelope is
                    // crossed. Clear any inherited pose-exclusive lease and keep moving instead.
                    bool releasedPoseAuthority = probe.PoseExclusiveOrientationAuthority;
                    probe.PoseExclusiveOrientationAuthority = false;
                    probe.AlignStableSince = -1f;
                    probe.WalkThroughEntryCorridorOrientationAuthorityAcquired = false;
                    if (releasedPoseAuthority)
                    {
                        WriteEvent("learningV312WalkThroughEntryTranslationAuthorityRestored", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            entryDistance,
                            entryApproachAngle,
                            corridorAlignmentAngle,
                            action = "releasePoseExclusiveAndContinueMoverTranslation"
                        });
                    }
                    DispatchV2WalkThroughEntryApproach(
                        probe, entry, entryDistance, entryApproachAngle,
                        corridorAlignmentAngle, learningV372EpisodeCorridorWitness||learningV367FiniteProgress,
                        capabilityEntryLane);
                }
                else if (angle > WalkThroughEntryConvergenceTurnOnlyAngle || probe.PoseExclusiveOrientationAuthority)
                {
                    bot.Mover.BotMoverStop("R1-24C3AEC98E1D",@bot);
                    bot.BotOwnerSetTargetMoveSpeed("R1-4372554B375D",@bot,0f);
                    player.SetPlayerInputDirection("R1-F108CC2C50B4",@bot,Vector2.zero);
                    player.MovementContext.SetMovementContextMovementDirection("R1-38F7AB272340",@bot,Vector2.zero);
                    probe.AlignStableSince = -1f;
                }
                else
                {
                    if (Time.time >= probe.WalkThroughNextDirectPointAt)
                    {
                        bot.Mover.BotMoverGoToPointNoWay("R1-A1E3BE1E4909",@bot,entry);
                        probe.WalkThroughNextDirectPointAt = Time.time + WalkThroughDirectPointRefreshSeconds;
                    }
                    ApplyProbeLocomotionIntent(
                        probe,
                        Mathf.Max(WalkThroughEntryGovernorSpeed, 0.88f),
                        allowSprint: angle <= ProbeRollingAlignmentAngle);
                    HoldForwardInput(probe);
                }
            }
            else
            {
                if (true &&
                    !probe.WalkThroughEntryCorridorOrientationAuthorityAcquired)
                {
                    // Entering the existing spatial envelope is the authority handoff. Reset only
                    // the pose-progress clock so corridor steering gets a fresh, bounded chance to
                    // converge before the existing hard-yaw fallback is eligible. No angle or time
                    // threshold is changed.
                    probe.WalkThroughEntryCorridorOrientationAuthorityAcquired = true;
                    probe.PoseExclusiveOrientationAuthority = false;
                    probe.PoseLastAlignmentAngle = corridorAlignmentAngle;
                    probe.PoseLastAlignmentProgressAt = Time.time;
                    probe.AlignStableSince = -1f;
                    WriteEvent("learningV312WalkThroughCorridorOrientationAuthorityAcquired", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        entryDistance,
                        corridorAlignmentAngle,
                        direction = Vec(corridorDirection),
                        action = "singleCorridorHeadingContract"
                    });
                }

                // CompileFix26: reaching the entry envelope is not a mandatory full stop. Keep
                // rolling while the steering actuator trims a modest final yaw; only a large/exclusive
                // orientation correction is allowed to freeze translation.
                if (angle > WalkThroughEntryConvergenceTurnOnlyAngle || probe.PoseExclusiveOrientationAuthority)
                {
                    bot.Mover.BotMoverStop("R1-9166EDB24765",@bot);
                    bot.BotOwnerSetTargetMoveSpeed("R1-CA31583D2AA3",@bot,0f);
                    player.SetPlayerInputDirection("R1-768DC0AC0803",@bot,Vector2.zero);
                    player.MovementContext.SetMovementContextMovementDirection("R1-F642D94A06A8",@bot,Vector2.zero);
                }
                else
                {
                    ApplyProbeLocomotionIntent(probe, 0.92f, allowSprint: angle <= ProbeRollingAlignmentAngle);
                    HoldForwardInput(probe);
                }
            }

            if (converged || !true)
            {
                Vector3 poseDirection = converged ? corridorDirection : entryDirection;
                DriveTraversalPoseAcquisition(probe, poseDirection, angle, "walkThroughEntry", true);
            }

            if (converged && angle <= 12f)
            {
                if (probe.AlignStableSince < 0f)
                {
                    probe.AlignStableSince = Time.time;
                }
                else if (Time.time - probe.AlignStableSince >= ProbeAlignStableTime)
                {
                    probe.PoseExclusiveOrientationAuthority = false;
                    BeginWalkThroughProbe(probe, angle);
                    return;
                }
            }
            else if (!converged || angle > 12f)
            {
                probe.AlignStableSince = -1f;
            }

            if (IsActiveProbe(probe) && Time.time - probe.StageStartedAt > WalkThroughEntryConvergenceTimeout)
            {
                bool headingSolved = FollowerCapabilityDecisionRules.UpdateWalkThroughEntryConvergence_headingSolved_8(converged,corridorAlignmentAngle,entryApproachAngle);
                bool moverHasPath = probe.Bot.Mover?.HasPathAndNoComplete == true;
                if (!converged && headingSolved && !moverHasPath)
                {
                    probe.PoseExclusiveOrientationAuthority = false;
                    probe.AlignStableSince = -1f;
                    if (probe.WalkThroughEntryPathRecoveryAttempts < WalkThroughEntryMaxPathRecoveryAttempts)
                    {
                        probe.WalkThroughEntryPathRecoveryAttempts++;
                        probe.StageStartedAt = Time.time;
                        probe.WalkThroughNextDirectPointAt = Time.time + WalkThroughDirectPointRefreshSeconds;
                        NavMeshPathStatus topologyStatus = NavMeshPathStatus.PathInvalid;
                        try
                        {
                            probe.Bot.Mover.SetBotMoverPause("R1-E0948977451A",@bot,false);
                            probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-DD5A17C386F5",@bot);
                            // V3.8: this branch exists specifically because Mover has no path while
                            // heading is already solved. GoToPointNoWay only installs a direct local
                            // corridor; it cannot reacquire NavMesh topology. Use EFT PathFinder here.
                            topologyStatus = probe.Bot.BotOwnerGoToPoint("R1-11B97F6A85AF",@bot,entry,false,-1f,false,true);
                            if (topologyStatus == NavMeshPathStatus.PathComplete)
                            {
                                ApplyProbeLocomotionIntent(
                                    probe,
                                    Mathf.Max(WalkThroughEntryGovernorSpeed, 0.88f),
                                    allowSprint: true);
                                HoldForwardInput(probe);
                            }
                        }
                        catch
                        {
                            topologyStatus = NavMeshPathStatus.PathInvalid;
                        }
                        RegisterTraversalLocalRecovery(probe, "walkThroughEntryTopologyReacquire");
                        WriteEvent("walkThroughEntryPathRecoveryRequested", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            entryDistance,
                            alignmentAngle = angle,
                            attempt = probe.WalkThroughEntryPathRecoveryAttempts,
                            maxAttempts = WalkThroughEntryMaxPathRecoveryAttempts,
                            moverHasPathBefore = false,
                            topologyStatus = topologyStatus.ToString(),
                            action = "nativePathFinderTopologyReacquireWithoutYawReset"
                        });
                        return;
                    }

                    probe.StageStartedAt = Time.time;
                    string entryPathStuckReason = string.Empty;
                    bool hardStuck = FollowerCapabilityDecisionRules.UpdateWalkThroughEntryConvergence_hardStuck_9(Time.time,probe.RequestedAt,RouteMissionHardRecoverySeconds) &&
                                     IsTraversalHardStuck(probe, out entryPathStuckReason);
                    WriteEvent("walkThroughEntryPathRecoveryExhausted", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        entryDistance,
                        alignmentAngle = angle,
                        attempts = probe.WalkThroughEntryPathRecoveryAttempts,
                        hardStuck,
                        stuckReason = hardStuck ? entryPathStuckReason : null,
                        action = hardStuck ? "monotonicRecovery" : "holdForPhysicalEvidence"
                    });
                    if (hardStuck && EscalateTraversalFailureMonotonic(probe, "walkThroughEntryPathUnavailable"))
                    {
                        return;
                    }
                    return;
                }

                if (true && !converged)
                {
                    // A body that still has a mover path but has not reached the entry envelope has
                    // a translation/progress problem, not an orientation contract failure. Preserve
                    // the existing timeout cadence and ownership watchdog, but never manufacture
                    // pose-exclusive authority from entry-vector yaw.
                    WriteEvent("learningV312WalkThroughEntryTranslationRecoveryCycle", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        entryDistance,
                        entryApproachAngle,
                        corridorAlignmentAngle,
                        moverHasPath,
                        recoveryAttempts = probe.PoseRecoveryAttempts,
                        action = "continueMoverTranslationWithoutPoseEscalation"
                    });
                    probe.StageStartedAt = Time.time;
                    probe.PoseExclusiveOrientationAuthority = false;
                    return;
                }

                WriteEvent("walkThroughEntryPoseRecoveryCycle", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    entryDistance,
                    angle,
                    recoveryAttempts = probe.PoseRecoveryAttempts,
                    action = "continueCorrection"
                });
                probe.StageStartedAt = Time.time;
                // Only a real heading problem owns pose-exclusive recovery. A pathless body with an
                // already-correct heading is handled by the branch above and can never spin in a
                // zero-degree yaw-recovery loop.
                probe.PoseExclusiveOrientationAuthority = angle > 12f;
                if (TryTraversalPoseLastResortRecovery(probe, "walkThroughEntry"))
                {
                    return;
                }
            }
        }

        private static List<Vector3> BuildOrientedWalkThroughCorridor(
            LearnedTraversalEdge edge,
            Vector3 rawEntry,
            Vector3 rawExit)
        {
            List<Vector3> source = edge?.WalkThroughCorridorSamples != null
                ? edge.WalkThroughCorridorSamples.Where(IsFinite).ToList()
                : new List<Vector3>();
            return NormalizeWalkThroughCorridorToAuthoredSpan(
                source,
                rawEntry,
                rawExit,
                out _,
                out _,
                out _);
        }

        private static bool TryBuildLearningV372CurrentEpisodeWalkThroughCorridor(
            ProbeRuntime probe,
            LearnedTraversalEdge semanticEdge,
            Vector3 runtimeEntry,
            Vector3 runtimeExit,
            out List<Vector3> corridor)
        {
            corridor = null;
            if ((probe == null) || semanticEdge == null ||
                probe.TraversalEpisodeId <= 0 ||
                !string.Equals(semanticEdge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            TraversalEpisodeMetadata episode = TraversalEpisodeStream
                .Where(item => item != null && item.EpisodeId == probe.TraversalEpisodeId &&
                               IsLearningV435WalkThroughEpisodeSemanticAlias(
                                   item, semanticEdge.Id, out _, out _))
                .OrderByDescending(item => item.EpisodeId)
                .FirstOrDefault();
            if (episode == null || !episode.LearningV372HasCurrentExecutionGeometry ||
                !IsFinite(episode.LearningV372CurrentExecutionStart) ||
                !IsFinite(episode.LearningV372CurrentExecutionEnd) ||
                episode.StartBreadcrumbSequence <= 0 ||
                episode.EndBreadcrumbSequence < episode.StartBreadcrumbSequence)
            {
                return false;
            }

            Vector3 currentEntry = IsFinite(runtimeEntry)
                ? runtimeEntry
                : episode.LearningV372CurrentExecutionStart;
            Vector3 currentExit = IsFinite(runtimeExit)
                ? runtimeExit
                : episode.LearningV372CurrentExecutionEnd;
            List<Vector3> samples = BreadcrumbRoute
                .Where(node => node != null && node.Sequence >= episode.StartBreadcrumbSequence &&
                               node.Sequence <= episode.EndBreadcrumbSequence &&
                               IsOperationalBreadcrumbNode(node) && IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .Select(node => node.Position)
                .ToList();
            corridor = NormalizeWalkThroughCorridorToAuthoredSpan(
                samples, currentEntry, currentExit, out _, out _, out _);
            return corridor != null && corridor.Count >= 2;
        }

        private static List<Vector3> NormalizeWalkThroughCorridorToAuthoredSpan(
            IList<Vector3> source,
            Vector3 rawEntry,
            Vector3 rawExit,
            out int removedPrefix,
            out int removedSuffix,
            out bool reversed)
        {
            removedPrefix = 0;
            removedSuffix = 0;
            reversed = false;
            List<Vector3> corridor = source != null
                ? source.Where(IsFinite).ToList()
                : new List<Vector3>();
            if (!IsFinite(rawEntry) || !IsFinite(rawExit))
            {
                return corridor;
            }
            if (corridor.Count < 2)
            {
                corridor.Clear();
                corridor.Add(rawEntry);
                corridor.Add(rawExit);
                return corridor;
            }

            float forwardFit = Vector3.Distance(corridor[0], rawEntry) +
                               Vector3.Distance(corridor[corridor.Count - 1], rawExit);
            float reverseFit = Vector3.Distance(corridor[corridor.Count - 1], rawEntry) +
                               Vector3.Distance(corridor[0], rawExit);
            if (reverseFit + 0.05f < forwardFit)
            {
                corridor.Reverse();
                reversed = true;
            }

            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            float authoredLength = axis.magnitude;
            if (authoredLength >= 0.10f)
            {
                Vector3 forward = axis / authoredLength;
                int firstKept = 0;
                while (firstKept < corridor.Count)
                {
                    Vector3 delta = corridor[firstKept] - rawEntry;
                    delta.y = 0f;
                    if (Vector3.Dot(delta, forward) >= -WalkThroughAuthoredSpanProjectionSlack)
                    {
                        break;
                    }
                    firstKept++;
                }

                int lastKept = corridor.Count - 1;
                while (lastKept >= firstKept)
                {
                    Vector3 delta = corridor[lastKept] - rawEntry;
                    delta.y = 0f;
                    if (Vector3.Dot(delta, forward) <= authoredLength + WalkThroughAuthoredSpanProjectionSlack)
                    {
                        break;
                    }
                    lastKept--;
                }

                removedPrefix = firstKept;
                removedSuffix = Math.Max(0, corridor.Count - 1 - lastKept);
                if (firstKept > 0 || lastKept < corridor.Count - 1)
                {
                    corridor = lastKept >= firstKept
                        ? corridor.GetRange(firstKept, lastKept - firstKept + 1)
                        : new List<Vector3>();
                }
            }

            List<Vector3> normalized = new List<Vector3> { rawEntry };
            foreach (Vector3 point in corridor)
            {
                if (Vector3.Distance(normalized[normalized.Count - 1], point) >= WalkThroughCorridorDeduplicateDistance &&
                    Vector3.Distance(point, rawExit) >= WalkThroughCorridorDeduplicateDistance)
                {
                    normalized.Add(point);
                }
            }
            if (Vector3.Distance(normalized[normalized.Count - 1], rawExit) >= WalkThroughCorridorDeduplicateDistance)
            {
                normalized.Add(rawExit);
            }
            else
            {
                normalized[normalized.Count - 1] = rawExit;
            }
            if (normalized.Count < 2)
            {
                normalized.Clear();
                normalized.Add(rawEntry);
                normalized.Add(rawExit);
            }
            return normalized;
        }


        private static bool TryExtendWalkThroughProbeWithRouteMissionComposite(ProbeRuntime probe)
        {
            if (probe == null || probe.Bot == null ||
                !string.Equals(probe.RequestedTraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null || commitment.RouteMissionId <= 0)
            {
                return false;
            }

            string profileId = probe.Bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) ||
                mission == null || mission.MissionId != commitment.RouteMissionId ||
                mission.Steps == null || mission.Steps.Count == 0)
            {
                return false;
            }

            int currentStepIndex = commitment.RouteMissionStepIndex;
            if (currentStepIndex < 0 || currentStepIndex >= mission.Steps.Count ||
                mission.Steps[currentStepIndex]?.EdgeId != probe.LearnedEdgeId)
            {
                currentStepIndex = mission.Steps.FindIndex(step => step != null && step.EdgeId == probe.LearnedEdgeId);
            }
            if (currentStepIndex < 0 || currentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            if (probe.WalkThroughCorridorPoints == null)
            {
                probe.WalkThroughCorridorPoints = new List<Vector3>();
            }
            if (probe.WalkThroughAuthoredCorridorPoints == null)
            {
                probe.WalkThroughAuthoredCorridorPoints = new List<Vector3>();
            }

            float totalLength = GetWalkThroughPolylinePlanarLength(probe.WalkThroughCorridorPoints);
            FollowerRouteMissionStep previousStep = mission.Steps[currentStepIndex];
            Vector3 previousTerminal = IsFinite(probe.WalkThroughTarget)
                ? probe.WalkThroughTarget
                : previousStep.Exit;
            int appended = 0;

            for (int stepIndex = currentStepIndex + 1;
                 stepIndex < mission.Steps.Count && appended < WalkThroughCompositeMaxExtraEdges;
                 stepIndex++)
            {
                FollowerRouteMissionStep nextStep = mission.Steps[stepIndex];
                if (nextStep == null ||
                    !string.Equals(nextStep.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    break;
                }

                int breadcrumbGap = Math.Max(0, nextStep.StartBreadcrumbSequence - previousStep.EndBreadcrumbSequence);
                Vector3 nextRawEntry = IsFinite(nextStep.RawEntry) ? nextStep.RawEntry : nextStep.Entry;
                Vector3 nextRawExit = IsFinite(nextStep.RawExit) ? nextStep.RawExit : nextStep.Exit;
                float authoredGap = GetPlanarDistance(previousTerminal, nextRawEntry);
                if (breadcrumbGap > WalkThroughCompositeMaxBreadcrumbGap ||
                    authoredGap > WalkThroughCompositeMaxAuthoredGap)
                {
                    break;
                }

                {
                    Vector3 previousRawEntry = IsFinite(previousStep.RawEntry) ? previousStep.RawEntry : previousStep.Entry;
                    Vector3 previousRawExit = IsFinite(previousStep.RawExit) ? previousStep.RawExit : previousStep.Exit;
                    Vector3 previousDirection = GetFlatDirection(previousRawExit - previousRawEntry);
                    Vector3 nextDirection = GetFlatDirection(nextRawExit - nextRawEntry);
                    if (previousDirection.sqrMagnitude > 0.5f && nextDirection.sqrMagnitude > 0.5f)
                    {
                        float directionDot = Vector3.Dot(previousDirection, nextDirection);
                        if (directionDot < RollingTraversalMinForwardDot)
                        {
                            WriteEvent("learningV321WalkThroughCompositeDirectionRejected", probe.Bot, new
                            {
                                learnedEdgeId = probe.LearnedEdgeId,
                                previousEdgeId = previousStep.EdgeId,
                                rejectedEdgeId = nextStep.EdgeId,
                                directionDot,
                                minimumForwardDot = RollingTraversalMinForwardDot,
                                previousExit = Vec(previousRawExit),
                                nextEntry = Vec(nextRawEntry),
                                action = "keepCurrentPassageDoNotUTurn"
                            });
                            break;
                        }
                    }
                }

                LearnedTraversalEdge nextEdge = LearnedTraversalEdges.FirstOrDefault(edge =>
                    edge != null && edge.Id == nextStep.EdgeId && !edge.Disabled && edge.PlayerValidated &&
                    string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase));
                if (nextEdge == null)
                {
                    break;
                }

                List<Vector3> nextCorridor = BuildOrientedWalkThroughCorridor(nextEdge, nextRawEntry, nextRawExit);
                List<Vector3> preview = probe.WalkThroughCorridorPoints.Where(IsFinite).ToList();
                AppendWalkThroughSamplesWithoutPrefixReplay(preview, nextCorridor);
                Vector3 nextTerminal = IsFinite(nextStep.Exit) ? nextStep.Exit : nextRawExit;
                if (IsFinite(nextTerminal) &&
                    (preview.Count == 0 || GetPlanarDistance(preview[preview.Count - 1], nextTerminal) > 0.05f))
                {
                    preview.Add(nextTerminal);
                }

                float previewLength = GetWalkThroughPolylinePlanarLength(preview);
                if (previewLength > WalkThroughCompositeMaxTotalLength ||
                    previewLength > WalkThroughMaxExecutionDistance)
                {
                    break;
                }

                probe.WalkThroughCorridorPoints = preview;
                probe.WalkThroughAuthoredCorridorPoints = preview.ToList();
                probe.WalkThroughRawExit = nextRawExit;
                probe.WalkThroughTarget = nextTerminal;
                probe.WalkThroughCompletionTargetSource = "routeCompositeExit";
                probe.CompositeWalkThroughEpisodeIds.Add(nextStep.EpisodeId);
                probe.CompositeWalkThroughEdgeIds.Add(nextStep.EdgeId);
                totalLength = previewLength;
                previousTerminal = nextTerminal;
                previousStep = nextStep;
                appended++;
            }

            if (appended <= 0)
            {
                return false;
            }

            WriteEvent("walkThroughCompositeCorridorBuilt", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                routeMissionId = mission.MissionId,
                currentStepIndex,
                appendedEdges = probe.CompositeWalkThroughEdgeIds.ToArray(),
                appendedEpisodes = probe.CompositeWalkThroughEpisodeIds.ToArray(),
                pointCount = probe.WalkThroughCorridorPoints.Count,
                totalLength,
                target = Vec(probe.WalkThroughTarget)
            });
            return true;
        }

        private static float GetWalkThroughPolylinePlanarLength(IEnumerable<Vector3> points)
        {
            if (points == null)
            {
                return 0f;
            }
            Vector3 previous = Vector3.zero;
            bool havePrevious = false;
            float total = 0f;
            foreach (Vector3 point in points.Where(IsFinite))
            {
                if (havePrevious)
                {
                    total += GetPlanarDistance(previous, point);
                }
                previous = point;
                havePrevious = true;
            }
            return total;
        }

        private static List<Vector3> BuildPrecisionWalkThroughCorridor(
            Player player,
            List<Vector3> rawPoints,
            Vector3 rawEntry,
            Vector3 completionTarget)
        {
            float learningV323StartedAt = Time.realtimeSinceStartup;
            List<Vector3> source = new List<Vector3>();
            if (rawPoints != null)
            {
                for (int index = 0; index < rawPoints.Count; index++)
                {
                    Vector3 candidate = rawPoints[index];
                    if (IsFinite(candidate))
                    {
                        source.Add(candidate);
                    }
                }
            }
            if (source.Count == 0 && IsFinite(rawEntry))
            {
                source.Add(rawEntry);
            }
            if (IsFinite(completionTarget) &&
                (source.Count == 0 || GetPlanarDistance(source[source.Count - 1], completionTarget) > 0.05f))
            {
                source.Add(completionTarget);
            }
            if (source.Count < 2)
            {
                return source;
            }

            List<Vector3> dense = new List<Vector3> { source[0] };
            for (int i = 0; i < source.Count - 1; i++)
            {
                Vector3 a = source[i];
                Vector3 b = source[i + 1];
                float planar = GetPlanarDistance(a, b);
                int steps = Mathf.Max(1, Mathf.CeilToInt(planar / WalkThroughPrecisionSampleSpacing));
                for (int step = 1; step <= steps; step++)
                {
                    Vector3 point = Vector3.Lerp(a, b, step / (float)steps);
                    if (dense.Count == 0 || GetPlanarDistance(dense[dense.Count - 1], point) > 0.08f)
                    {
                        dense.Add(point);
                    }
                }
            }

            for (int i = 1; i < dense.Count - 1; i++)
            {
                Vector3 incoming = GetFlatDirection(dense[i] - dense[i - 1]);
                Vector3 outgoing = GetFlatDirection(dense[i + 1] - dense[i]);
                Vector3 tangent = incoming + outgoing;
                tangent = tangent.sqrMagnitude > 0.01f ? tangent.normalized : outgoing;
                dense[i] = ApplyWalkThroughClearanceCorrection(player, dense[i], tangent);
            }

            WriteEvent("walkThroughPrecisionCorridorBuilt", null, new
            {
                rawPointCount = source.Count,
                precisionPointCount = dense.Count,
                spacing = WalkThroughPrecisionSampleSpacing,
                elapsedMs = (Time.realtimeSinceStartup - learningV323StartedAt) * 1000f,
                queryMode = ("boundedNonAllocExactOverflowFallback")
            });
            return dense;
        }

        private static Vector3 ApplyWalkThroughClearanceCorrection(Player player, Vector3 point, Vector3 tangent)
        {
            tangent = GetFlatDirection(tangent);
            if (player == null || tangent.sqrMagnitude < 0.5f)
            {
                return point;
            }

            Vector3 right = Vector3.Cross(Vector3.up, tangent);
            right = GetFlatDirection(right);
            if (right.sqrMagnitude < 0.5f)
            {
                return point;
            }

            Vector3 origin = point + Vector3.up * 0.85f;
            float leftClearance = WalkThroughPrecisionWallProbeDistance;
            float rightClearance = WalkThroughPrecisionWallProbeDistance;
            if (TryGetFirstNonSelfRaycastHit(
                    player,
                    origin,
                    -right,
                    WalkThroughPrecisionWallProbeDistance,
                    LayersMaskController.HighPolyWithTerrainMask,
                    out RaycastHit leftHit))
            {
                leftClearance = leftHit.distance;
            }
            if (TryGetFirstNonSelfRaycastHit(
                    player,
                    origin,
                    right,
                    WalkThroughPrecisionWallProbeDistance,
                    LayersMaskController.HighPolyWithTerrainMask,
                    out RaycastHit rightHit))
            {
                rightClearance = rightHit.distance;
            }

            float shift = 0f;
            if (leftClearance < WalkThroughPrecisionDesiredWallClearance &&
                rightClearance > leftClearance + 0.08f)
            {
                shift = Mathf.Min(
                    WalkThroughPrecisionMaxCenterShift,
                    WalkThroughPrecisionDesiredWallClearance - leftClearance);
            }
            else if (rightClearance < WalkThroughPrecisionDesiredWallClearance &&
                     leftClearance > rightClearance + 0.08f)
            {
                shift = -Mathf.Min(
                    WalkThroughPrecisionMaxCenterShift,
                    WalkThroughPrecisionDesiredWallClearance - rightClearance);
            }

            Vector3 corrected = point + right * shift;
            if (Mathf.Abs(shift) > 0.01f)
            {
                Vector3 floorOrigin = corrected + Vector3.up * WalkThroughFloorProbeHeight;
                if (TryGetFirstNonSelfRaycastHit(
                        player,
                        floorOrigin,
                        Vector3.down,
                        WalkThroughFloorProbeDistance,
                        LayersMaskController.HighPolyWithTerrainMask,
                        out RaycastHit floorHit) &&
                    Mathf.Abs(floorHit.point.y - corrected.y) <= WalkThroughFloorMaxOffset)
                {
                    corrected.y = floorHit.point.y;
                }
                else
                {
                    corrected = point;
                }
            }
            return corrected;
        }

        private static void InitializeWalkThroughArcProgress(ProbeRuntime probe, Vector3 position)
        {
            if (probe == null)
            {
                return;
            }
            probe.WalkThroughCorridorCumulativeLengths.Clear();
            probe.WalkThroughTotalLength = 0f;
            if (probe.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count == 0)
            {
                probe.WalkThroughProgressS = 0f;
                return;
            }

            probe.WalkThroughCorridorCumulativeLengths.Add(0f);
            for (int i = 1; i < probe.WalkThroughCorridorPoints.Count; i++)
            {
                probe.WalkThroughTotalLength += GetPlanarDistance(
                    probe.WalkThroughCorridorPoints[i - 1],
                    probe.WalkThroughCorridorPoints[i]);
                probe.WalkThroughCorridorCumulativeLengths.Add(probe.WalkThroughTotalLength);
            }
            probe.WalkThroughProgressS = 0f;
            UpdateWalkThroughArcProgress(probe, position);
        }

        private static bool TryProjectOntoWalkThroughCorridor(
            ProbeRuntime probe,
            Vector3 position,
            out float projectedS,
            out Vector3 projectedPoint,
            out int segmentIndex,
            out float lateralDistance)
        {
            projectedS = 0f;
            projectedPoint = position;
            segmentIndex = 0;
            lateralDistance = float.MaxValue;
            if (probe?.WalkThroughCorridorPoints == null ||
                probe.WalkThroughCorridorPoints.Count < 2 ||
                probe.WalkThroughCorridorCumulativeLengths == null ||
                probe.WalkThroughCorridorCumulativeLengths.Count != probe.WalkThroughCorridorPoints.Count)
            {
                return false;
            }

            float minimumS = Mathf.Max(0f, probe.WalkThroughProgressS - WalkThroughArcProjectionBackSlack);
            for (int i = 0; i < probe.WalkThroughCorridorPoints.Count - 1; i++)
            {
                Vector3 a = probe.WalkThroughCorridorPoints[i];
                Vector3 b = probe.WalkThroughCorridorPoints[i + 1];
                Vector3 ab = b - a;
                ab.y = 0f;
                float len = ab.magnitude;
                if (len < 0.001f)
                {
                    continue;
                }
                Vector3 ap = position - a;
                ap.y = 0f;
                float t = Mathf.Clamp01(Vector3.Dot(ap, ab) / (len * len));
                float candidateS = probe.WalkThroughCorridorCumulativeLengths[i] + len * t;
                if (candidateS + 0.001f < minimumS)
                {
                    continue;
                }
                Vector3 candidate = Vector3.Lerp(a, b, t);
                float distance = GetPlanarDistance(position, candidate);
                if (distance < lateralDistance - 0.001f ||
                    (Mathf.Abs(distance - lateralDistance) <= 0.001f && candidateS > projectedS))
                {
                    lateralDistance = distance;
                    projectedS = candidateS;
                    projectedPoint = candidate;
                    segmentIndex = i;
                }
            }
            return lateralDistance < float.MaxValue;
        }

        private static bool TryGetLearningV372CurrentEpisodeWalkThroughCorridorWitness(
            ProbeRuntime probe,
            Vector3 position,
            out float projectedS,
            out float totalLength,
            out float lateralDistance,
            out float verticalDeviation)
        {
            projectedS = 0f;
            totalLength = 0f;
            lateralDistance = float.MaxValue;
            verticalDeviation = float.MaxValue;
            if ((probe == null) ||
                !probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority ||
                probe.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 2)
            {
                return false;
            }
            Vector3 projectedPoint;
            if (TryProjectOntoWalkThroughCorridor(
                    probe, position, out projectedS, out projectedPoint, out _, out lateralDistance))
            {
                totalLength = probe.WalkThroughTotalLength;
                verticalDeviation = Mathf.Abs(position.y - projectedPoint.y);
                return totalLength > 0.05f && projectedS >= -0.001f &&
                       projectedS <= totalLength + WalkThroughAuthoredSpanProjectionSlack;
            }

            // Entry acquisition runs before BeginWalkThroughProbe initializes the monotonic arc
            // cache. For that stage only, project against the same finite episode polyline with a
            // local cumulative length; no movement cursor/frontier is mutated by this observation.
            float runningS = 0f;
            projectedS = 0f;
            projectedPoint = position;
            lateralDistance = float.MaxValue;
            for (int i = 0; i < probe.WalkThroughCorridorPoints.Count - 1; i++)
            {
                Vector3 a = probe.WalkThroughCorridorPoints[i];
                Vector3 b = probe.WalkThroughCorridorPoints[i + 1];
                Vector3 ab = b - a;
                ab.y = 0f;
                float len = ab.magnitude;
                if (len < 0.001f)
                {
                    continue;
                }
                Vector3 ap = position - a;
                ap.y = 0f;
                float t = Mathf.Clamp01(Vector3.Dot(ap, ab) / (len * len));
                Vector3 candidate = Vector3.Lerp(a, b, t);
                float candidateDistance = GetPlanarDistance(position, candidate);
                float candidateS = runningS + len * t;
                if (candidateDistance < lateralDistance - 0.001f ||
                    (Mathf.Abs(candidateDistance - lateralDistance) <= 0.001f && candidateS > projectedS))
                {
                    lateralDistance = candidateDistance;
                    projectedS = candidateS;
                    projectedPoint = candidate;
                }
                runningS += len;
            }
            totalLength = runningS;
            verticalDeviation = Mathf.Abs(position.y - projectedPoint.y);
            return lateralDistance < float.MaxValue && totalLength > 0.05f &&
                   projectedS >= -0.001f && projectedS <= totalLength + WalkThroughAuthoredSpanProjectionSlack;
        }

        private static bool TryLatchLearningV373CurrentEpisodeWalkThroughEntryFrontier(
            ProbeRuntime probe,
            string source)
        {
            if ((probe == null) ||
                !probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority ||
                probe.LearningV367WalkThroughEntryFrontierAcquired)
            {
                return probe?.LearningV367WalkThroughEntryFrontierAcquired == true;
            }

            bool witnessed = TryGetLearningV372CurrentEpisodeWalkThroughCorridorWitness(
                probe, probe.Player.Position, out float projectedS, out float totalLength,
                out float lateralDistance, out float verticalDeviation);
            bool insideFiniteEntryPortal = FollowerCapabilityHelperRules.TryLatchLearningV373CurrentEpisodeWalkThroughEntryFrontier_insideFiniteEntryPortal_3CCCC486_1(witnessed,totalLength,projectedS) &&
                projectedS <= Mathf.Min(totalLength, WalkThroughEntryConvergenceDistance) &&
                lateralDistance <= WalkThroughPassageStraightLateralTolerance &&
                verticalDeviation <= WalkThroughPassageMicroVerticalDeviation;

            bool learningV400CurrentRouteEpochInsideFinitePassage = false;
            int learningV400ProjectedSequence = 0;
            float learningV400BodyArc = 0f;
            if ((!insideFiniteEntryPortal) &&
                witnessed && totalLength > 0.05f && projectedS > WalkThroughEntryConvergenceDistance &&
                projectedS <= totalLength + WalkThroughAuthoredSpanProjectionSlack &&
                lateralDistance <= WalkThroughPassageStraightLateralTolerance &&
                verticalDeviation <= WalkThroughPassageMicroVerticalDeviation &&
                !probe.TraversalTeleportAttempted &&
                TryGetActiveFollowerRouteMission(probe.Bot, out FollowerRouteMission learningV400Mission) &&
                learningV400Mission != null && learningV400Mission.CurrentStepIndex >= 0 &&
                learningV400Mission.CurrentStepIndex < learningV400Mission.Steps.Count)
            {
                FollowerRouteMissionStep learningV400Step =
                    learningV400Mission.Steps[learningV400Mission.CurrentStepIndex];
                if (learningV400Step != null &&
                    learningV400Step.StartBreadcrumbSequence > 0 &&
                    (learningV400Step.EpisodeId == probe.TraversalEpisodeId ||
                     (learningV400Step.EdgeId == probe.LearnedEdgeId &&
                      (learningV400Step.ChainId <= 0 || probe.TraversalChainId <= 0 ||
                       learningV400Step.ChainId == probe.TraversalChainId))) &&
                    TryProjectLearningV375RouteArc(
                        learningV400Mission, probe.Bot.Position,
                        out learningV400BodyArc, out _, out _, out learningV400ProjectedSequence) &&
                    learningV400ProjectedSequence >= learningV400Step.StartBreadcrumbSequence)
                {
                    learningV400CurrentRouteEpochInsideFinitePassage = true;
                }
            }

            if (!insideFiniteEntryPortal && !learningV400CurrentRouteEpochInsideFinitePassage)
            {
                return false;
            }

            probe.LearningV367WalkThroughEntryFrontierAcquired = true;
            probe.LearningV367WalkThroughEntryFrontierAcquiredAt = Time.time;
            WriteEvent(
                learningV400CurrentRouteEpochInsideFinitePassage
                    ? "learningV400CurrentRouteEpochWalkThroughEntryFrontierRecovered"
                    : "learningV373CurrentEpisodeWalkThroughEntryFrontierAcquired",
                probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                episodeId = probe.TraversalEpisodeId,
                chainId = probe.TraversalChainId,
                source = source ?? "unknown",
                projectedS,
                totalLength,
                lateralDistance,
                verticalDeviation,
                routeMissionBodyArc = learningV400BodyArc,
                routeMissionProjectedSequence = learningV400ProjectedSequence,
                recoveredFromCurrentRouteEpoch = learningV400CurrentRouteEpochInsideFinitePassage,
                allowedLateral = WalkThroughPassageStraightLateralTolerance,
                allowedVertical = WalkThroughPassageMicroVerticalDeviation,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                bodyRelocated = false,
                action = learningV400CurrentRouteEpochInsideFinitePassage
                    ? "currentRouteEpochInsideFiniteEpisodeCorridorRecoversOnlyRuntimeEntryFrontierFarSideProofStillRequired"
                    : "currentEpisodeFinitePortalEntryOwnsMonotonicPhysicalFrontier"
            });
            return true;
        }

        private static bool TryProveLearningV392CurrentEpisodeWalkThroughFarSidePlane(
            ProbeRuntime probe,
            out float farSideProjection,
            out float playerFarSideProjection,
            out float bodyFarSideProjection,
            out float lateralDistance,
            out float verticalDistance)
        {
            farSideProjection = float.MinValue;
            playerFarSideProjection = float.MinValue;
            bodyFarSideProjection = float.MinValue;
            lateralDistance = float.MaxValue;
            verticalDistance = float.MaxValue;
            ;
            if (probe?.Player == null || probe.Bot == null ||
                !probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority ||
                probe.TraversalEpisodeId <= 0)
            {
                return false;
            }

            if (!TryMeasureV2CurrentEpisodeWalkThroughFarSide(
                    probe, out V2WalkThroughFarSideObservation observation))
                return false;
            farSideProjection = observation.FarSideProjection;
            playerFarSideProjection = observation.PlayerProjection;
            bodyFarSideProjection = observation.BodyProjection;
            lateralDistance = observation.LateralDistance;
            verticalDistance = observation.VerticalDistance;

            return farSideProjection + LearningV32EntryProgressEpsilon >= 0f &&
                lateralDistance <= WalkThroughPassageStraightLateralTolerance &&
                verticalDistance <= WalkThroughMaxVerticalDelta;
        }

        private static bool TryLatchLearningV372WalkThroughPhysicalPassageProof(
            ProbeRuntime probe,
            string source)
        {
            if ((probe == null) ||
                !probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority)
            {
                return true;
            }
            if (probe.LearningV372WalkThroughPhysicalPassageProven)
            {
                return true;
            }
            bool witnessed = TryGetLearningV372CurrentEpisodeWalkThroughCorridorWitness(
                probe, probe.Player.Position, out float projectedS, out float totalLength,
                out float lateralDistance, out float verticalDeviation);
            float remaining = witnessed ? Mathf.Max(0f, totalLength - projectedS) : float.MaxValue;
            bool legacyFiniteCompletionCandidate =
                witnessed && probe.LearningV367WalkThroughEntryFrontierAcquired &&
                remaining <= WalkThroughSemanticCompletionRemaining &&
                lateralDistance <= WalkThroughPassageStraightLateralTolerance &&
                verticalDeviation <= WalkThroughPassageMicroVerticalDeviation;
            float learningV392FarSideProjection = float.MinValue;
            float learningV392PlayerFarSideProjection = float.MinValue;
            float learningV392BodyFarSideProjection = float.MinValue;
            float learningV392FarSideLateral = float.MaxValue;
            float learningV392FarSideVertical = float.MaxValue;
            bool learningV392FarSidePlaneProven =
                (TryProveLearningV392CurrentEpisodeWalkThroughFarSidePlane(
                    probe,
                    out learningV392FarSideProjection,
                    out learningV392PlayerFarSideProjection,
                    out learningV392BodyFarSideProjection,
                    out learningV392FarSideLateral,
                    out learningV392FarSideVertical));
            bool proven = legacyFiniteCompletionCandidate && learningV392FarSidePlaneProven;
            if ((legacyFiniteCompletionCandidate) && !learningV392FarSidePlaneProven &&
                ShouldEmitDiagnostic(
                    "learningV392WalkThroughNearExitProofDeferred:" +
                        probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.20f))
            {
                WriteEvent("learningV392WalkThroughNearExitProofDeferred", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    episodeId = probe.TraversalEpisodeId,
                    chainId = probe.TraversalChainId,
                    source = source ?? "unknown",
                    projectedS,
                    totalLength,
                    remaining,
                    farSideProjection = learningV392FarSideProjection,
                    playerFarSideProjection = learningV392PlayerFarSideProjection,
                    bodyFarSideProjection = learningV392BodyFarSideProjection,
                    farSideLateral = learningV392FarSideLateral,
                    farSideVertical = learningV392FarSideVertical,
                    numericalEnvelope = LearningV32EntryProgressEpsilon,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "nearExitEnvelopeCannotBecomePhysicalCompletionBeforeCurrentEpisodeFarSidePlane"
                });
            }
            if (!proven)
            {
                if (ShouldEmitDiagnostic(
                    "learningV372WalkThroughPhysicalPassageProofRejected:" +
                        probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.35f))
                {
                    WriteEvent("learningV372WalkThroughPhysicalPassageProofRejected", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        episodeId = probe.TraversalEpisodeId,
                        source = source ?? "unknown",
                        entryFrontier = probe.LearningV367WalkThroughEntryFrontierAcquired,
                        witnessed,
                        projectedS,
                        totalLength,
                        remaining,
                        lateralDistance,
                        verticalDeviation,
                        allowedLateral = WalkThroughPassageStraightLateralTolerance,
                        allowedVertical = WalkThroughPassageMicroVerticalDeviation,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "doNotConvertProjectionOrFarSideIntoPhysicalCrossing"
                    });
                }
                return false;
            }

            {
                WriteEvent("learningV392WalkThroughFarSidePlaneConfirmed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    episodeId = probe.TraversalEpisodeId,
                    chainId = probe.TraversalChainId,
                    source = source ?? "unknown",
                    farSideProjection = learningV392FarSideProjection,
                    playerFarSideProjection = learningV392PlayerFarSideProjection,
                    bodyFarSideProjection = learningV392BodyFarSideProjection,
                    farSideLateral = learningV392FarSideLateral,
                    farSideVertical = learningV392FarSideVertical,
                    numericalEnvelope = LearningV32EntryProgressEpsilon,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "currentEpisodeFarSidePlaneAuthorizesWalkThroughPhysicalCompletion"
                });
            }

            probe.LearningV372WalkThroughPhysicalPassageProven = true;
            probe.LearningV372WalkThroughPhysicalPassageProvenAt = Time.time;
            WriteEvent("learningV372WalkThroughPhysicalPassageProven", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                episodeId = probe.TraversalEpisodeId,
                chainId = probe.TraversalChainId,
                source = source ?? "unknown",
                projectedS,
                totalLength,
                remaining,
                lateralDistance,
                verticalDeviation,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "finiteCurrentEpisodeCorridorCrossingMayProceedToEgressConsumer"
            });
            return true;
        }

        private static void UpdateWalkThroughArcProgress(ProbeRuntime probe, Vector3 position)
        {
            if (!TryProjectOntoWalkThroughCorridor(
                    probe,
                    position,
                    out float projectedS,
                    out _,
                    out int segmentIndex,
                    out _))
            {
                return;
            }
            // Monotonic progress is the key R8.4 invariant: once a follower has physically passed
            // a corridor station it can never be commanded backwards to reacquire an old waypoint.
            probe.WalkThroughProgressS = Mathf.Clamp(
                Mathf.Max(probe.WalkThroughProgressS, projectedS),
                0f,
                probe.WalkThroughTotalLength);
            probe.WalkThroughCorridorIndex = Mathf.Clamp(
                segmentIndex + 1,
                0,
                probe.WalkThroughCorridorPoints.Count - 1);
        }

        private static Vector3 SampleWalkThroughCorridorAtDistance(ProbeRuntime probe, float distanceS)
        {
            if (probe?.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count == 0)
            {
                return probe != null ? probe.WalkThroughTarget : default(Vector3);
            }
            if (probe.WalkThroughCorridorPoints.Count == 1 ||
                probe.WalkThroughCorridorCumulativeLengths == null ||
                probe.WalkThroughCorridorCumulativeLengths.Count != probe.WalkThroughCorridorPoints.Count)
            {
                return probe.WalkThroughCorridorPoints[probe.WalkThroughCorridorPoints.Count - 1];
            }

            float s = Mathf.Clamp(distanceS, 0f, probe.WalkThroughTotalLength);
            for (int i = 0; i < probe.WalkThroughCorridorPoints.Count - 1; i++)
            {
                float aS = probe.WalkThroughCorridorCumulativeLengths[i];
                float bS = probe.WalkThroughCorridorCumulativeLengths[i + 1];
                if (s <= bS + 0.0001f)
                {
                    float span = Mathf.Max(0.0001f, bS - aS);
                    return Vector3.Lerp(
                        probe.WalkThroughCorridorPoints[i],
                        probe.WalkThroughCorridorPoints[i + 1],
                        Mathf.Clamp01((s - aS) / span));
                }
            }
            return probe.WalkThroughCorridorPoints[probe.WalkThroughCorridorPoints.Count - 1];
        }

        private static float GetWalkThroughTurnAngle(ProbeRuntime probe)
        {
            if (probe?.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 3)
            {
                return 0f;
            }
            float currentS = Mathf.Clamp(probe.WalkThroughProgressS, 0f, probe.WalkThroughTotalLength);
            Vector3 current = SampleWalkThroughCorridorAtDistance(probe, currentS);
            Vector3 near = SampleWalkThroughCorridorAtDistance(probe, currentS + 0.28f);
            Vector3 baseDirection = GetFlatDirection(near - current);
            if (baseDirection.sqrMagnitude < 0.5f)
            {
                return 0f;
            }

            float maxAngle = 0f;
            for (float look = 0.45f; look <= WalkThroughArcTurnLookAheadDistance + 0.01f; look += 0.25f)
            {
                Vector3 p0 = SampleWalkThroughCorridorAtDistance(probe, currentS + look);
                Vector3 p1 = SampleWalkThroughCorridorAtDistance(probe, currentS + look + 0.24f);
                Vector3 futureDirection = GetFlatDirection(p1 - p0);
                if (futureDirection.sqrMagnitude >= 0.5f)
                {
                    maxAngle = Mathf.Max(maxAngle, Vector3.Angle(baseDirection, futureDirection));
                }
            }
            return maxAngle;
        }

        private static bool TryGetWalkThroughSharpTurnGateGeometry(
            ProbeRuntime probe,
            out float apexS,
            out float exitS,
            out float turnAngle,
            out Vector3 postDirection)
        {
            apexS = 0f;
            exitS = 0f;
            turnAngle = 0f;
            postDirection = Vector3.zero;
            if (probe?.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 4 ||
                probe.WalkThroughTotalLength <= 0.5f)
            {
                return false;
            }

            float currentS = Mathf.Clamp(probe.WalkThroughProgressS, 0f, probe.WalkThroughTotalLength);
            float scanStart = Mathf.Min(probe.WalkThroughTotalLength, currentS + 0.16f);
            float scanEnd = Mathf.Min(
                probe.WalkThroughTotalLength - 0.18f,
                currentS + WalkThroughSharpTurnDetectAheadDistance);
            if (scanEnd <= scanStart + 0.05f)
            {
                return false;
            }

            float bestAngle = 0f;
            float bestS = 0f;
            Vector3 bestPostDirection = Vector3.zero;
            for (float candidateS = scanStart; candidateS <= scanEnd + 0.001f; candidateS += 0.10f)
            {
                Vector3 pre = SampleWalkThroughCorridorAtDistance(
                    probe,
                    Mathf.Max(0f, candidateS - WalkThroughSharpTurnPreSpan));
                Vector3 apex = SampleWalkThroughCorridorAtDistance(probe, candidateS);
                Vector3 post = SampleWalkThroughCorridorAtDistance(
                    probe,
                    Mathf.Min(probe.WalkThroughTotalLength, candidateS + WalkThroughSharpTurnPostSpan));
                Vector3 preDirection = GetFlatDirection(apex - pre);
                Vector3 candidatePostDirection = GetFlatDirection(post - apex);
                if (preDirection.sqrMagnitude < 0.5f || candidatePostDirection.sqrMagnitude < 0.5f)
                {
                    continue;
                }

                float candidateAngle = Vector3.Angle(preDirection, candidatePostDirection);
                if (candidateAngle > bestAngle)
                {
                    bestAngle = candidateAngle;
                    bestS = candidateS;
                    bestPostDirection = candidatePostDirection;
                }
            }

            float cumulativeTurnAngle = GetWalkThroughTurnAngle(probe);
            if (bestAngle < WalkThroughSharpTurnThreshold || cumulativeTurnAngle < 45f)
            {
                return false;
            }

            apexS = bestS;
            exitS = Mathf.Min(
                probe.WalkThroughTotalLength,
                bestS + WalkThroughSharpTurnExitAdvance);
            turnAngle = Mathf.Max(bestAngle, cumulativeTurnAngle);
            postDirection = bestPostDirection;
            return exitS > apexS + 0.20f;
        }

        private static bool TryUpdateWalkThroughStepAssist(ProbeRuntime probe)
        {
            if (probe?.Player?.MovementContext == null || probe.Bot?.Mover == null ||
                probe.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 2)
            {
                return false;
            }

            Player player = probe.Player;
            UpdateWalkThroughArcProgress(probe, player.Position);
            Vector3 assistTarget = SampleWalkThroughCorridorAtDistance(
                probe,
                Mathf.Min(probe.WalkThroughTotalLength,
                    probe.WalkThroughProgressS + WalkThroughStepAssistForwardProbeDistance));
            Vector3 direction = GetFlatDirection(assistTarget - player.Position);
            if (direction.sqrMagnitude < 0.5f)
            {
                direction = probe.WalkThroughSharpTurnPostDirection;
            }
            if (direction.sqrMagnitude < 0.5f)
            {
                return false;
            }

            if (!probe.WalkThroughStepAssistActive)
            {
                if (ShouldSuppressWalkThroughLearnedSubStrategy(probe, stepAssist: true, out string suppressionReason))
                {
                    if (!probe.WalkThroughStepAssistExperienceSuppressionLogged)
                    {
                        probe.WalkThroughStepAssistExperienceSuppressionLogged = true;
                        WriteEvent("walkThroughStepAssistSuppressedByExperience", probe.Bot, new
                        {
                            learnedEdgeId = probe.LearnedEdgeId,
                            reason = suppressionReason
                        });
                    }
                    return false;
                }

                if (probe.WalkThroughStepAssistAttemptedThisGate ||
                    probe.WalkThroughStepAssistAttempts >= 8)
                {
                    return false;
                }

                if(!TryObserveCapabilityLowStep(player,direction,out RaycastHit bodyHit,out RaycastHit raisedHit,out bool raisedClear))return false;
                if(!raisedClear)
                {
                    probe.WalkThroughStepAssistAttemptedThisGate = true;
                    probe.WalkThroughStepAssistAttempts++;
                    probe.WalkThroughStepAssistFailures++;
                    WriteEvent("walkThroughStepAssistRejected", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        blocker = raisedHit.collider?.name ?? bodyHit.collider?.name ?? "unknown",
                        bodyHitDistance = bodyHit.distance,
                        raisedHitDistance = raisedHit.distance,
                        action = "raisedCorridorStillBlocked"
                    });
                    return false;
                }

                probe.WalkThroughStepAssistActive = true;
                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughStepAssistNativeEnteredAt = -1f;
                probe.WalkThroughStepAssistNativeReleasedAt = -1f;
                probe.WalkThroughStepAssistAttemptedThisGate = true;
                probe.WalkThroughStepAssistAttempts++;
                probe.WalkThroughStepAssistStartedAt = Time.time;
                probe.WalkThroughStepAssistStartPosition = player.Position;
                probe.WalkThroughStepAssistBlocker = bodyHit.collider?.name ?? "unknown";
                bool stepAssistAnimationPlayed = false;
                string stepAssistAnimationState = ("suppressed:WalkThroughOwnsSemanticBody");
                ;
                WriteEvent("walkThroughStepAssistAnimation", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    played = stepAssistAnimationPlayed,
                    state = stepAssistAnimationState,
                    semanticOwner = ("WalkThrough")
                });
                WriteEvent("walkThroughStepAssistEntered", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    corridorIndex = probe.WalkThroughCorridorIndex,
                    progressS = probe.WalkThroughProgressS,
                    blocker = probe.WalkThroughStepAssistBlocker,
                    bodyHitDistance = bodyHit.distance,
                    lift = WalkThroughStepAssistLift,
                    collisionActive = true
                });
            }

            float elapsed = Time.time - probe.WalkThroughStepAssistStartedAt;
            float planarProgress = GetPlanarDistance(player.Position, probe.WalkThroughStepAssistStartPosition);

            if (probe.WalkThroughStepAssistNativeOwned)
            {
                // V3.7: StepAssist deliberately asked EFT to play Vault/ClimbOver. Once that native
                // state owns root motion, PIT becomes an observer. Never run ApplyApproachMotion in
                // parallel with EFT's traversal controller.
                if (IsProbeTraversalState(player.CurrentStateName))
                {
                    if (Time.time - probe.WalkThroughStepAssistNativeEnteredAt >= AssistedNativeOwnershipMaxSeconds)
                    {
                        WriteEvent("walkThroughStepAssistNativeOwnershipTimedOut", probe.Bot, new
                        {
                            learnedEdgeId = probe.LearnedEdgeId,
                            blocker = probe.WalkThroughStepAssistBlocker,
                            state = player.CurrentStateName.ToString(),
                            planarProgress,
                            elapsed = Time.time - probe.WalkThroughStepAssistNativeEnteredAt
                        });
                        AbortWalkThroughProbe(
                            probe,
                            "stepAssistNativeOwnershipTimeout",
                            "StepAssist native traversal state did not release",
                            false);
                    }
                    return true;
                }

                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughStepAssistNativeReleasedAt = Time.time;
                WriteEvent("walkThroughStepAssistNativeOwnershipReleased", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    blocker = probe.WalkThroughStepAssistBlocker,
                    state = player.CurrentStateName.ToString(),
                    planarProgress,
                    ownedSeconds = probe.WalkThroughStepAssistNativeEnteredAt > 0f
                        ? Time.time - probe.WalkThroughStepAssistNativeEnteredAt
                        : 0f
                });
            }

            if (planarProgress >= WalkThroughStepAssistSuccessDistance)
            {
                probe.WalkThroughStepAssistActive = false;
                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughStepAssistSuccesses++;
                probe.WalkThroughSharpTurnLastPhysicalProgressAt = Time.time;
                probe.WalkThroughSharpTurnLastPosition = player.Position;
                probe.WalkThroughLastProgressAt = Time.time;
                WriteEvent("walkThroughStepAssistSucceeded", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    blocker = probe.WalkThroughStepAssistBlocker,
                    planarProgress,
                    elapsed,
                    position = Vec(player.Position)
                });
                return false;
            }

            if (elapsed >= WalkThroughStepAssistMaxSeconds)
            {
                probe.WalkThroughStepAssistActive = false;
                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughStepAssistFailures++;
                WriteEvent("walkThroughStepAssistFailed", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    blocker = probe.WalkThroughStepAssistBlocker,
                    planarProgress,
                    elapsed,
                    position = Vec(player.Position)
                });
                return false;
            }

            float dt = Mathf.Max(0.001f, Time.deltaTime);
            float forwardStep = Mathf.Min(
                WalkThroughSharpTurnMaxStep,
                WalkThroughStepAssistForwardSpeed * dt);
            float liftStep = elapsed < WalkThroughStepAssistLiftPhaseSeconds
                ? Mathf.Min(0.035f, WalkThroughStepAssistLiftSpeed * dt)
                : 0f;
            Vector3 step = direction * forwardStep + Vector3.up * liftStep;
            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-2AC09B31BC26",@probe?.Bot,false);
                probe.Bot.BotOwnerSetPose("R1-016F260A128D",@probe?.Bot,GetCapabilityProbePosture(probe));
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-6B663310343C",@probe?.Bot,WalkThroughPrecisionSlowSpeed);
                if (probe.Bot.Mover.Sprinting)
                {
                    probe.Bot.Mover.BotMoverSprint("R1-7B17061B0ACE",@probe?.Bot,false,false);
                }
                HoldForwardInput(probe);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-EDF2C836BEF4",@probe?.Bot,direction);
                // Collision remains active. The raised capsule probe above must be clear before
                // any vertical component is applied, so this cannot be used as a wall-phase path.
                player.MovementContext.TryMovementContextApplyApproachMotion("R1-37E8988B2772",@probe?.Bot,step,dt);
            }
            catch (Exception ex)
            {
                probe.WalkThroughStepAssistActive = false;
                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughStepAssistFailures++;
                WriteEvent("walkThroughStepAssistException", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    blocker = probe.WalkThroughStepAssistBlocker,
                    error = ex.GetType().Name + ": " + ex.Message
                });
                return false;
            }

            return true;
        }

        private static bool TryUpdateWalkThroughSharpTurnGate(ProbeRuntime probe)
        {
            if (probe?.Bot?.Mover == null || probe.Player?.MovementContext == null ||
                probe.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 4)
            {
                return false;
            }

            Player player = probe.Player;
            UpdateWalkThroughArcProgress(probe, player.Position);

            {
                // V415: under the V414 virtual corridor, sharp-turn geometry is advisory only.
                // The old sub-executor is a second movement producer: on entry it may Sprint(false),
                // Stop BotMover, and later fall back to ApplyApproachMotion. Runtime A/B on the bridge
                // showed those gates correlate with Sprint/Transition stalls while smooth passes need
                // only the virtual corridor's per-frame native Player.Move lease. Keep detecting the
                // corner for diagnostics, but never mutate locomotion mode/path/body authority here.
                probe.WalkThroughSharpTurnGateActive = false;
                probe.LearningV332WalkThroughSharpTurnMoverOwned = false;
                if (TryGetWalkThroughSharpTurnGateGeometry(
                        probe,
                        out float observedApexS,
                        out float observedExitS,
                        out float observedTurnAngle,
                        out Vector3 observedPostDirection))
                {
                    float observedDistanceToApex = observedApexS - probe.WalkThroughProgressS;
                    if (observedDistanceToApex >= -0.08f &&
                        observedDistanceToApex <= WalkThroughSharpTurnActivationDistance &&
                        ShouldEmitDiagnostic(
                            "learningV415WalkThroughSharpTurnObserved:" +
                            probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture),
                            probe.Bot, 0.20f))
                    {
                        WriteEvent("learningV415WalkThroughSharpTurnObservedWithoutLegacyExecutor", probe.Bot, new
                        {
                            learnedEdgeId = probe.LearnedEdgeId,
                            progressS = probe.WalkThroughProgressS,
                            apexS = observedApexS,
                            exitS = observedExitS,
                            distanceToApex = observedDistanceToApex,
                            turnAngle = observedTurnAngle,
                            postDirection = Vec(observedPostDirection),
                            position = Vec(player.Position),
                            moverHasPath = probe.Bot.Mover.HasPathAndNoComplete,
                            action = "observeCornerGeometryVirtualCorridorRemainsOnlyMovementProducerNoSprintStopOrApplyApproachMotion"
                        });
                    }
                }
                return false;
            }

            if (!probe.WalkThroughSharpTurnGateActive)
            {
                if (ShouldSuppressWalkThroughLearnedSubStrategy(probe, stepAssist: false, out string suppressionReason))
                {
                    if (!probe.WalkThroughSharpTurnExperienceSuppressionLogged)
                    {
                        probe.WalkThroughSharpTurnExperienceSuppressionLogged = true;
                        WriteEvent("walkThroughSharpTurnSuppressedByExperience", probe.Bot, new
                        {
                            learnedEdgeId = probe.LearnedEdgeId,
                            reason = suppressionReason
                        });
                    }
                    return false;
                }

                if (!TryGetWalkThroughSharpTurnGateGeometry(
                        probe,
                        out float apexS,
                        out float exitS,
                        out float turnAngle,
                        out Vector3 postDirection))
                {
                    return false;
                }

                if (probe.WalkThroughSharpTurnRetryBlocked)
                {
                    bool distinctApex = Mathf.Abs(apexS - probe.WalkThroughSharpTurnBlockedApexS) >=
                                        WalkThroughSharpTurnDistinctApexDistance;
                    bool progressedPastFailure = FollowerCapabilityHelperRules.TryUpdateWalkThroughSharpTurnGate_progressedPastFailure_F2FCF20C_1(probe.WalkThroughProgressS,probe.WalkThroughSharpTurnBlockedProgressS,WalkThroughSharpTurnRetryProgressDistance);
                    if (!distinctApex && !progressedPastFailure)
                    {
                        if (!probe.WalkThroughSharpTurnReentrySuppressionLogged)
                        {
                            probe.WalkThroughSharpTurnReentrySuppressionLogged = true;
                            WriteEvent("walkThroughSharpTurnGateReentrySuppressed", probe.Bot, new
                            {
                                learnedEdgeId = probe.LearnedEdgeId,
                                progressS = probe.WalkThroughProgressS,
                                blockedProgressS = probe.WalkThroughSharpTurnBlockedProgressS,
                                apexS,
                                blockedApexS = probe.WalkThroughSharpTurnBlockedApexS,
                                reason = "sameApexRequiresPhysicalProgress"
                            });
                        }
                        return false;
                    }

                    probe.WalkThroughSharpTurnRetryBlocked = false;
                    probe.WalkThroughSharpTurnReentrySuppressionLogged = false;
                }

                float distanceToApex = apexS - probe.WalkThroughProgressS;
                if (distanceToApex < -0.08f || distanceToApex > WalkThroughSharpTurnActivationDistance)
                {
                    return false;
                }

                probe.WalkThroughSharpTurnGateActive = true;
                probe.WalkThroughSharpTurnUsed = true;
                probe.WalkThroughSharpTurnGateCount++;
                probe.WalkThroughSharpTurnApexS = apexS;
                probe.WalkThroughSharpTurnExitS = exitS;
                probe.WalkThroughSharpTurnAngle = turnAngle;
                probe.WalkThroughSharpTurnPostDirection = postDirection;
                probe.WalkThroughSharpTurnStartedAt = Time.time;
                probe.WalkThroughSharpTurnLastPhysicalProgressAt = Time.time;
                probe.WalkThroughSharpTurnLastPosition = player.Position;
                probe.WalkThroughStepAssistActive = false;
                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughStepAssistAttemptedThisGate = false;
                probe.WalkThroughStepAssistBlocker = null;
                probe.WalkThroughPathRecoveryAttempts = 0;
                probe.WalkThroughRecenterAttempts = 0;
                probe.WalkThroughNextDirectPointAt = Time.time + WalkThroughDirectPointRefreshSeconds;
                probe.WalkThroughMoverAckUntil = Time.time + WalkThroughMoverAckWindowSeconds;
                probe.WalkThroughHasInstalledTarget = false;

                bool learningV332KeepSingleMoverProducer =
                    (probe.Bot.Mover.HasPathAndNoComplete) &&
                    probe.Bot.Mover.IsMoving && !probe.Bot.Mover.Blocked &&
                    Time.time - probe.WalkThroughLastProgressAt <= WalkThroughSharpTurnStallSeconds;
                probe.LearningV332WalkThroughSharpTurnMoverOwned = learningV332KeepSingleMoverProducer;
                try
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-79B87AF77DFF",@probe?.Bot,false);
                    if (probe.Bot.Mover.Sprinting)
                    {
                        probe.Bot.Mover.BotMoverSprint("R1-41015F51C7AF",@probe?.Bot,false,false);
                    }
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-D5AD2E69F51B",@probe?.Bot);
                    if (!learningV332KeepSingleMoverProducer)
                    {
                        probe.Bot.Mover.BotMoverStop("R1-CB8581D81B7E",@probe?.Bot);
                    }
                }
                catch
                {
                    probe.LearningV332WalkThroughSharpTurnMoverOwned = false;
                }

                Vector3 apex = SampleWalkThroughCorridorAtDistance(probe, apexS);
                Vector3 exit = SampleWalkThroughCorridorAtDistance(probe, exitS);
                WriteEvent("walkThroughSharpTurnGateEntered", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    corridorIndex = probe.WalkThroughCorridorIndex,
                    progressS = probe.WalkThroughProgressS,
                    apexS,
                    exitS,
                    distanceToApex,
                    turnAngle,
                    apex = Vec(apex),
                    postTurnTarget = Vec(exit),
                    navMeshBypassed = !probe.LearningV332WalkThroughSharpTurnMoverOwned,
                    collisionActive = true,
                    singleMoverProducer = probe.LearningV332WalkThroughSharpTurnMoverOwned
                });
            }

            UpdateWalkThroughArcProgress(probe, player.Position);
            float elapsed = Time.time - probe.WalkThroughSharpTurnStartedAt;
            Vector3 gateExit = SampleWalkThroughCorridorAtDistance(probe, probe.WalkThroughSharpTurnExitS);
            float gateExitDistance = GetPlanarDistance(player.Position, gateExit);
            if (probe.WalkThroughProgressS >= probe.WalkThroughSharpTurnExitS - 0.10f || gateExitDistance <= 0.24f)
            {
                probe.WalkThroughSharpTurnGateActive = false;
                probe.WalkThroughStepAssistActive = false;
                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughSharpTurnRetryBlocked = false;
                probe.WalkThroughSharpTurnReentrySuppressionLogged = false;
                probe.WalkThroughSharpTurnCompletedCount++;
                probe.WalkThroughLastProgressAt = Time.time;
                probe.WalkThroughPathRecoveryAttempts = 0;
                probe.WalkThroughRecenterAttempts = 0;
                probe.WalkThroughNextDirectPointAt = Time.time;
                WriteEvent("walkThroughSharpTurnGateExited", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    corridorIndex = probe.WalkThroughCorridorIndex,
                    progressS = probe.WalkThroughProgressS,
                    apexS = probe.WalkThroughSharpTurnApexS,
                    exitS = probe.WalkThroughSharpTurnExitS,
                    turnAngle = probe.WalkThroughSharpTurnAngle,
                    position = Vec(player.Position),
                    exit = Vec(gateExit),
                    elapsed
                });
                bool retainedMover = (probe.LearningV332WalkThroughSharpTurnMoverOwned) &&
                    probe.Bot.Mover.HasPathAndNoComplete && !probe.Bot.Mover.Blocked;
                probe.LearningV332WalkThroughSharpTurnMoverOwned = false;
                if (!retainedMover)
                {
                    InstallWalkThroughMoverPath(probe, "sharpTurnGateExit");
                }
                else
                {
                    WriteEvent("learningV332WalkThroughSharpTurnMoverPreserved", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        progressS = probe.WalkThroughProgressS,
                        exitS = probe.WalkThroughSharpTurnExitS,
                        action = "sameBotMoverProducerContinuesAcrossSharpTurn"
                    });
                }
                return true;
            }

            float physicalStep = GetPlanarDistance(player.Position, probe.WalkThroughSharpTurnLastPosition);
            if (physicalStep >= 0.006f)
            {
                probe.WalkThroughSharpTurnLastPosition = player.Position;
                probe.WalkThroughSharpTurnLastPhysicalProgressAt = Time.time;
                probe.WalkThroughLastProgressAt = Time.time;
                probe.WalkThroughExecutionDeadlineAt = Mathf.Max(
                    probe.WalkThroughExecutionDeadlineAt,
                    Time.time + 2.0f);
                probe.OwnershipLeaseExpiresAt = Mathf.Max(
                    probe.OwnershipLeaseExpiresAt,
                    probe.WalkThroughExecutionDeadlineAt + 1.0f);
            }

            float sharpTurnNoProgress = Time.time - probe.WalkThroughSharpTurnLastPhysicalProgressAt;
            if (sharpTurnNoProgress >= WalkThroughStepAssistTriggerNoProgressSeconds &&
                TryUpdateWalkThroughStepAssist(probe))
            {
                return true;
            }

            sharpTurnNoProgress = Time.time - probe.WalkThroughSharpTurnLastPhysicalProgressAt;
            if (sharpTurnNoProgress >= WalkThroughSharpTurnStallSeconds ||
                elapsed >= WalkThroughSharpTurnMaxSeconds)
            {
                string reason = elapsed >= WalkThroughSharpTurnMaxSeconds
                    ? "turnGateTimeout"
                    : "turnGateNoPhysicalProgress";
                probe.WalkThroughSharpTurnGateActive = false;
                probe.WalkThroughStepAssistActive = false;
                probe.WalkThroughStepAssistNativeOwned = false;
                probe.WalkThroughSharpTurnRetryBlocked = true;
                probe.WalkThroughSharpTurnBlockedApexS = probe.WalkThroughSharpTurnApexS;
                probe.WalkThroughSharpTurnBlockedProgressS = probe.WalkThroughProgressS;
                probe.WalkThroughSharpTurnReentrySuppressionLogged = false;
                probe.WalkThroughSharpTurnFailures++;
                probe.WalkThroughNextDirectPointAt = Time.time;
                probe.WalkThroughLastProgressAt = Time.time;
                WriteEvent("walkThroughSharpTurnGateReleasedToRecovery", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    reason,
                    corridorIndex = probe.WalkThroughCorridorIndex,
                    progressS = probe.WalkThroughProgressS,
                    apexS = probe.WalkThroughSharpTurnApexS,
                    exitS = probe.WalkThroughSharpTurnExitS,
                    turnAngle = probe.WalkThroughSharpTurnAngle,
                    elapsed,
                    noProgress = sharpTurnNoProgress,
                    stepAssistAttempts = probe.WalkThroughStepAssistAttempts,
                    stepAssistSuccesses = probe.WalkThroughStepAssistSuccesses,
                    stepAssistFailures = probe.WalkThroughStepAssistFailures,
                    position = Vec(player.Position),
                    gateExit = Vec(gateExit)
                });
                return false;
            }

            float driveTargetS = Mathf.Min(
                probe.WalkThroughSharpTurnExitS,
                probe.WalkThroughProgressS + WalkThroughSharpTurnMotionLookAhead);
            Vector3 driveTarget = SampleWalkThroughCorridorAtDistance(probe, driveTargetS);
            Vector3 motion = driveTarget - player.Position;
            float motionDistance = motion.magnitude;
            if (motionDistance <= 0.002f)
            {
                return true;
            }

            float steeringS = Mathf.Min(
                probe.WalkThroughSharpTurnExitS,
                Mathf.Max(
                    probe.WalkThroughSharpTurnApexS + 0.12f,
                    probe.WalkThroughProgressS + WalkThroughSharpTurnSteeringLookAhead));
            Vector3 steeringTarget = SampleWalkThroughCorridorAtDistance(probe, steeringS);
            Vector3 steeringDirection = GetFlatDirection(steeringTarget - player.Position);
            if (steeringDirection.sqrMagnitude < 0.5f)
            {
                steeringDirection = probe.WalkThroughSharpTurnPostDirection;
            }

            if ((probe.LearningV332WalkThroughSharpTurnMoverOwned))
            {
                bool moverHealthy = probe.Bot.Mover.HasPathAndNoComplete &&
                                    probe.Bot.Mover.IsMoving && !probe.Bot.Mover.Blocked;
                if (moverHealthy)
                {
                    try
                    {
                        probe.Bot.Mover.SetBotMoverPause("R1-A68DB77F2322",@probe?.Bot,false);
                        probe.Bot.BotOwnerSetPose("R1-4C71E5FD8D1C",@probe?.Bot,GetCapabilityProbePosture(probe));
                        probe.Bot.BotOwnerSetTargetMoveSpeed("R1-096F143352E2",@probe?.Bot,Mathf.Max(WalkThroughPrecisionMediumSpeed, 0.86f));
                        HoldForwardInput(probe);
                        if (steeringDirection.sqrMagnitude > 0.5f)
                        {
                            probe.Bot.Steering?.BotSteeringLookToDirection("R1-606F712CA649",@probe?.Bot,steeringDirection);
                        }
                    }
                    catch { }
                    if (Time.time >= probe.WalkThroughNextProgressLogAt)
                    {
                        probe.WalkThroughNextProgressLogAt = Time.time + 0.25f;
                        WriteEvent("learningV332WalkThroughSharpTurnSingleProducerProgress", probe.Bot, new
                        {
                            learnedEdgeId = probe.LearnedEdgeId,
                            progressS = probe.WalkThroughProgressS,
                            apexS = probe.WalkThroughSharpTurnApexS,
                            exitS = probe.WalkThroughSharpTurnExitS,
                            position = Vec(player.Position),
                            moverHasPath = true,
                            action = "steerExistingMoverWithoutStopOrApplyApproachMotion"
                        });
                    }
                    return true;
                }
                probe.LearningV332WalkThroughSharpTurnMoverOwned = false;
                WriteEvent("learningV332WalkThroughSharpTurnSingleProducerReleasedToFallback", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    progressS = probe.WalkThroughProgressS,
                    blocked = probe.Bot.Mover.Blocked,
                    hasPath = probe.Bot.Mover.HasPathAndNoComplete,
                    isMoving = probe.Bot.Mover.IsMoving,
                    action = "existingMoverLostPhysicalAuthorityUseBoundedLegacySharpTurnFallback"
                });
                try { probe.Bot.Mover.BotMoverStop("R1-01C5921F1600",@probe?.Bot); } catch { }
            }

            float dt = Mathf.Max(0.001f, Time.deltaTime);
            float stepDistance = Mathf.Min(
                Mathf.Min(motionDistance, WalkThroughSharpTurnMaxStep),
                WalkThroughSharpTurnSpeed * dt);
            Vector3 step = motion.normalized * stepDistance;
            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-FDD71B7EC874",@probe?.Bot,false);
                probe.Bot.BotOwnerSetPose("R1-0D90187E8917",@probe?.Bot,GetCapabilityProbePosture(probe));
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-8F1409468B85",@probe?.Bot,WalkThroughSharpTurnSpeed);
                if (probe.Bot.Mover.Sprinting)
                {
                    probe.Bot.Mover.BotMoverSprint("R1-3362431D6254",@probe?.Bot,false,false);
                }
                HoldForwardInput(probe);
                if (steeringDirection.sqrMagnitude > 0.5f)
                {
                    probe.Bot.Steering?.BotSteeringLookToDirection("R1-58FA52889B33",@probe?.Bot,steeringDirection);
                }

                // Collision remains fully active. ApplyApproachMotion moves through EFT's normal
                // character controller and therefore cannot phase through the narrow corner wall;
                // unlike BotMover it does not require a NavMesh polygon at the turn apex.
                player.MovementContext.TryMovementContextApplyApproachMotion("R1-3DE0A70F7C6B",@probe?.Bot,step,dt);
            }
            catch (Exception ex)
            {
                probe.WalkThroughSharpTurnGateActive = false;
                probe.WalkThroughSharpTurnFailures++;
                probe.WalkThroughNextDirectPointAt = Time.time;
                probe.WalkThroughLastProgressAt = Time.time;
                WriteEvent("walkThroughSharpTurnGateMotionException", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    error = ex.GetType().Name + ": " + ex.Message,
                    corridorIndex = probe.WalkThroughCorridorIndex,
                    progressS = probe.WalkThroughProgressS,
                    position = Vec(player.Position)
                });
                return false;
            }

            if (Time.time >= probe.WalkThroughNextProgressLogAt)
            {
                probe.WalkThroughNextProgressLogAt = Time.time + 0.25f;
                WriteEvent("walkThroughSharpTurnGateProgress", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    corridorIndex = probe.WalkThroughCorridorIndex,
                    progressS = probe.WalkThroughProgressS,
                    apexS = probe.WalkThroughSharpTurnApexS,
                    exitS = probe.WalkThroughSharpTurnExitS,
                    turnAngle = probe.WalkThroughSharpTurnAngle,
                    position = Vec(player.Position),
                    driveTarget = Vec(driveTarget),
                    steeringTarget = Vec(steeringTarget),
                    gateExit = Vec(gateExit),
                    gateExitDistance,
                    elapsed,
                    physicalNoProgress = Time.time - probe.WalkThroughSharpTurnLastPhysicalProgressAt,
                    moverHasPath = probe.Bot.Mover.HasPathAndNoComplete,
                    collisionActive = true
                });
            }
            return true;
        }

        private static bool IsWalkThroughStableRunEligible(ProbeRuntime probe)
        {
            if (probe?.Player == null || probe.WalkThroughCorridorPoints == null ||
                probe.WalkThroughCorridorPoints.Count < 2 ||
                !probe.Player.MovementContext.IsGrounded ||
                probe.WalkThroughSharpTurnGateActive || probe.WalkThroughStepAssistActive ||
                probe.WalkThroughPathRecoveryAttempts > 0)
            {
                return false;
            }

            float angle = GetWalkThroughTurnAngle(probe);
            float lateral = GetPlanarDistanceToWalkThroughCorridor(probe, probe.Player.Position);
            float remaining = Mathf.Max(0f, probe.WalkThroughTotalLength - probe.WalkThroughProgressS);
            bool recentProgress = probe.WalkThroughLastProgressAt > 0f &&
                                  Time.time - probe.WalkThroughLastProgressAt <= WalkThroughStableRunProgressLeaseSeconds;
            bool recenterCooledDown = probe.WalkThroughLastRecenterAt <= 0f ||
                                      Time.time - probe.WalkThroughLastRecenterAt >= WalkThroughStableRunRecenterCooldownSeconds;
            return probe.WalkThroughProgressS >= WalkThroughStableRunMinProgress &&
                   remaining >= WalkThroughStableRunMinRemaining &&
                   angle <= WalkThroughStableRunMaxTurnAngle &&
                   lateral <= WalkThroughStableRunMaxLateralDeviation &&
                   recentProgress &&
                   recenterCooledDown;
        }

        private static float GetWalkThroughPrecisionSpeed(ProbeRuntime probe)
        {
            if (probe?.WalkThroughTerminalFinishActive == true)
            {
                // CF62: a short physical WT endpoint is not a high-speed waypoint. CF61
                // Edge135 reversed its target when only ~0.08m beyond RawExit, while the
                // native body still had Sprint momentum; it then diverged and teleported.
                // Preserve the EFT locomotion MODE and Native proof gate, but taper the
                // existing pathless input speed envelope before the final short turn.
                float cf62TerminalDistance = probe.Player != null &&
                    IsFinite(probe.WalkThroughTarget)
                    ? GetPlanarDistance(probe.Player.Position, probe.WalkThroughTarget)
                    : float.MaxValue;
                if (cf62TerminalDistance <= 0.65f)
                {
                    probe.WalkThroughStableRunActive = false;
                    return Mathf.Lerp(WalkThroughPrecisionSlowSpeed, WalkThroughStableRunSpeed,
                        Mathf.Clamp01((cf62TerminalDistance - 0.15f) / 0.50f));
                }
                probe.WalkThroughStableRunActive = true;
                return WalkThroughStableRunSpeed;
            }

            if ((probe != null) &&
                TryGetWalkThroughSharpTurnGateGeometry(
                    probe,
                    out float learningV416ApexS,
                    out _,
                    out float learningV416TurnAngle,
                    out _))
            {
                float learningV416DistanceToApex = learningV416ApexS - probe.WalkThroughProgressS;
                if (learningV416DistanceToApex >= -0.08f &&
                    learningV416DistanceToApex <= WalkThroughSharpTurnActivationDistance)
                {
                    probe.WalkThroughStableRunActive = false;
                    if (learningV416TurnAngle >= 65f)
                    {
                        return WalkThroughPrecisionSlowSpeed;
                    }
                    if (learningV416TurnAngle >= 35f)
                    {
                        return WalkThroughPrecisionMediumSpeed;
                    }
                    if (learningV416TurnAngle >= 18f)
                    {
                        return 0.86f;
                    }
                }
            }

            if (IsWalkThroughStableRunEligible(probe))
            {
                probe.WalkThroughStableRunActive = true;
                return WalkThroughStableRunSpeed;
            }
            if (probe != null)
            {
                probe.WalkThroughStableRunActive = false;
            }

            float angle = GetWalkThroughTurnAngle(probe);
            float lateral = probe?.Player != null
                ? GetPlanarDistanceToWalkThroughCorridor(probe, probe.Player.Position)
                : float.MaxValue;
            bool recoveryPressure = probe != null &&
                (FollowerCapabilityHelperRules.GetWalkThroughPrecisionSpeed_recoveryPressure_467D6FD8_1(probe.WalkThroughSharpTurnGateActive,probe.WalkThroughStepAssistActive,probe.WalkThroughRecenterAttempts,probe.WalkThroughLateralRecoveryAttempts,probe.WalkThroughPathRecoveryAttempts));

            // CompileFix26: Run/Sprint is the normal locomotion intent. Precision Walk is a bounded
            // recovery mode, not the default just because a WalkThrough executor is active. A clean,
            // aligned corridor keeps full Run speed from the entry instead of spending the first
            // meter at 0.58 and visually dragging the follower's feet.
            if (!recoveryPressure && probe != null && (probe.PreviousSprinting || probe.PreviousRunning))
            {
                if (angle <= 18f && lateral <= 0.55f)
                {
                    return WalkThroughStableRunSpeed;
                }
                if (angle <= 35f && lateral <= 0.75f)
                {
                    return 0.90f;
                }
            }

            if (probe != null && probe.WalkThroughProgressS < WalkThroughEarlyCorridorDistance)
            {
                return WalkThroughEarlyCorridorSpeed;
            }

            if (angle >= 65f)
            {
                return WalkThroughPrecisionSlowSpeed;
            }
            if (angle >= 35f)
            {
                return WalkThroughPrecisionMediumSpeed;
            }
            if (angle >= 18f)
            {
                return 0.86f;
            }
            return WalkThroughMoverTargetSpeed;
        }

        private static bool TryInstallWalkThroughRecenterPath(ProbeRuntime probe, string source)
        {
            if (probe?.Bot?.Mover == null || probe.Player == null ||
                probe.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 2 ||
                probe.WalkThroughRecenterAttempts >= WalkThroughMaxRecenterAttempts)
            {
                return false;
            }

            Vector3 position = probe.Player.Position;
            if (!TryProjectOntoWalkThroughCorridor(
                    probe,
                    position,
                    out float projectedS,
                    out Vector3 bestPoint,
                    out int bestSegment,
                    out float bestDistance) ||
                bestDistance > WalkThroughHardLateralDeviation + 0.45f)
            {
                return false;
            }

            probe.WalkThroughProgressS = Mathf.Max(probe.WalkThroughProgressS, projectedS);
            int nextIndex = Mathf.Min(bestSegment + 1, probe.WalkThroughCorridorPoints.Count - 1);
            Vector3 recenter = SampleWalkThroughCorridorAtDistance(
                probe,
                Mathf.Min(probe.WalkThroughTotalLength, probe.WalkThroughProgressS + 0.28f));
            Vector3 forward = GetFlatDirection(recenter - bestPoint);
            recenter = ApplyWalkThroughClearanceCorrection(probe.Player, recenter, forward);
            probe.WalkThroughCorridorIndex = Mathf.Max(probe.WalkThroughCorridorIndex, nextIndex);
            probe.WalkThroughRecenterAttempts++;
            probe.WalkThroughLastRecenterTarget = recenter;
            probe.WalkThroughLastRecenterAt = Time.time;
            bool learningV321NoProgressHandoff =
                (!probe.WalkThroughValidatorDisagreement) &&
                !string.IsNullOrEmpty(source) &&
                source.StartsWith("noProgressRecovery", StringComparison.OrdinalIgnoreCase);
            if (learningV321NoProgressHandoff)
            {
                // The native full-corridor controller already failed to make progress. Keep the
                // remainder of THIS probe on PIT's monotonic local cursor instead of switching
                // straight back to GoToByWay on the next cursor refresh. Consume the existing
                // bounded path-recovery budget so a second stall yields/replans rather than cycles.
                probe.LearningV321WalkThroughDirectDriveAfterNoProgress = true;
                probe.WalkThroughPathRecoveryAttempts = WalkThroughMaxPathRecoveryAttempts;
            }

            {
                // Recovery changes only the virtual corridor target. Do not Stop/GoToPointNoWay or
                // toggle Sprint: those operations were the remaining bridge WT jitter/Transition
                // producer. The same native input lease now steers toward the recenter point.
                try
                {
                    if (probe.Bot.Mover.HasPathAndNoComplete)
                    {
                        TryRetireNativeMoverPathPreserveLocomotion(
                            probe.Bot, "learningV414WalkThroughRecenter", out _);
                    }
                    probe.Bot.Mover.SetBotMoverPause("R1-5D181FF3820B",@probe?.Bot,false);
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-028729EEC023",@probe?.Bot);
                    probe.Bot.BotOwnerSetTargetMoveSpeed("R1-A440BDAD1CE2",@probe?.Bot,WalkThroughPrecisionSlowSpeed);
                    probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-F60BDB1D62B8",@probe?.Bot,WalkThroughPrecisionSlowSpeed);
                    probe.Bot.Steering?.BotSteeringLookToDirection(
"R1-E2DEDECF7E25",@probe?.Bot,                        forward.sqrMagnitude > 0.5f ? forward : probe.RequestedDirection);
                    probe.LearningV414WalkThroughPathlessInputLeaseActive = true;
                    probe.WalkThroughDirectDriveActive = false;
                    probe.WalkThroughFullCorridorActive = false;
                    probe.WalkThroughNextDirectPointAt = Time.time + WalkThroughDirectPointRefreshSeconds;
                    probe.WalkThroughMoverAckUntil = Time.time;
                    probe.WalkThroughLastInstalledTarget = recenter;
                    probe.WalkThroughHasInstalledTarget = true;
                    HoldForwardInput(probe);
                }
                catch
                {
                    return false;
                }
                bool published = TryPublishLearningV414PathlessNativeInputLease(
                    probe, recenter, WalkThroughPrecisionSlowSpeed,
                    "walkThroughRecenter:" + (source ?? string.Empty));
                WriteEvent("learningV414WalkThroughVirtualRecenter", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    source = source ?? string.Empty,
                    deviation = bestDistance,
                    recenterAttempt = probe.WalkThroughRecenterAttempts,
                    recenterTarget = Vec(recenter),
                    inputPublished = published,
                    syntheticPathInstalled = false,
                    locomotionModeRewritten = false,
                    action = "recenterVirtualCursorWithoutStopOrNavMeshPathRewrite"
                });
                return published;
            }

            // R8.8 Direct Corridor Drive: never hand the complete off-NavMesh corridor to
            // GoToByWay(). EFT's NavMesh corner solver can legally replace that player-authored
            // corridor with a corner several metres behind/sideways, which is the visible
            // "ghost pull". Give the mover one short physical target only; the traversal runtime
            // remains the authoritative cursor and will issue the next look-ahead point.
            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-BB4722F15614",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverSprint("R1-C4C6FE1710AB",@probe?.Bot,false,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-F5A806D49F4B",@probe?.Bot);
                probe.Bot.Mover.BotMoverStop("R1-006F9B835ACB",@probe?.Bot);
                probe.Bot.Mover.BotMoverGoToPointNoWay("R1-6D489EC6906B",@probe?.Bot,recenter);
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-9752A2E4BAB4",@probe?.Bot,WalkThroughPrecisionSlowSpeed);
                HoldForwardInput(probe);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-11B630EBAA17",@probe?.Bot,forward.sqrMagnitude > 0.5f ? forward : probe.RequestedDirection);
                probe.WalkThroughDirectDriveActive = true;
                if (learningV321NoProgressHandoff)
                {
                    probe.WalkThroughFullCorridorActive = false;
                }
                probe.WalkThroughLastProgressAt = Time.time;
                probe.WalkThroughNextDirectPointAt = Time.time + WalkThroughDirectPointRefreshSeconds;
                probe.WalkThroughMoverAckUntil = Time.time + WalkThroughMoverAckWindowSeconds;
                probe.WalkThroughLastInstalledTarget = recenter;
                probe.WalkThroughHasInstalledTarget = true;
            }
            catch
            {
                return false;
            }

            WriteEvent("walkThroughLocalRecenter", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                source,
                deviation = bestDistance,
                recenterAttempt = probe.WalkThroughRecenterAttempts,
                recenterTarget = Vec(recenter),
                corridorIndex = probe.WalkThroughCorridorIndex,
                directCorridorDrive = true,
                learningV321NoProgressHandoff,
                fullCorridorMayResume = !learningV321NoProgressHandoff
            });
            return true;
        }

        private static int FindInitialWalkThroughCorridorIndex(ProbeRuntime probe, Vector3 position)
        {
            if (probe?.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count == 0)
            {
                return 0;
            }

            int bestIndex = 0;
            float bestDistance = float.MaxValue;
            for (int index = 0; index < probe.WalkThroughCorridorPoints.Count; index++)
            {
                float candidateDistance = GetPlanarDistance(position, probe.WalkThroughCorridorPoints[index]);
                if (candidateDistance < bestDistance)
                {
                    bestDistance = candidateDistance;
                    bestIndex = index;
                }
            }

            if (bestIndex < probe.WalkThroughCorridorPoints.Count - 1 && bestDistance <= 0.45f)
            {
                bestIndex++;
            }
            return bestIndex;
        }

        private static Vector3 GetCurrentWalkThroughCorridorTarget(ProbeRuntime probe, Vector3 position)
        {
            if (probe?.WalkThroughTerminalFinishActive == true && IsFinite(probe.WalkThroughTarget))
            {
                return probe.WalkThroughTarget;
            }
            if (probe?.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count == 0)
            {
                return probe != null ? probe.WalkThroughTarget : position;
            }
            UpdateWalkThroughArcProgress(probe, position);
            float turnAngle = GetWalkThroughTurnAngle(probe);
            float lookAhead = turnAngle >= 45f
                ? 0.48f
                : (IsWalkThroughStableRunEligible(probe)
                    ? WalkThroughStableRunLookAheadDistance
                    : WalkThroughArcLookAheadDistance);
            float targetS=Mathf.Min(probe.WalkThroughTotalLength,probe.WalkThroughProgressS+lookAhead);
            return SelectCapabilityWalkThroughCornerTarget(probe,position,targetS);
        }

        private static float GetRemainingWalkThroughCorridorDistance(ProbeRuntime probe, Vector3 position)
        {
            if (probe?.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count == 0)
            {
                return probe != null ? GetPlanarDistance(position, probe.WalkThroughTarget) : 0f;
            }
            UpdateWalkThroughArcProgress(probe, position);
            return Mathf.Max(0f, probe.WalkThroughTotalLength - probe.WalkThroughProgressS);
        }

        private static float GetPlanarDistanceToWalkThroughCorridor(ProbeRuntime probe, Vector3 position)
        {
            return TryProjectOntoWalkThroughCorridor(
                probe,
                position,
                out _,
                out _,
                out _,
                out float lateral)
                ? lateral
                : (probe != null ? GetPlanarDistanceToSegment(position, probe.TriggerPosition, probe.WalkThroughTarget) : 0f);
        }

        private static bool IsCredibleWalkThroughTerminalConnector(
            Vector3 rawStart,
            Vector3 rawEnd,
            Vector3 settledEnd,
            IList<Vector3> corridor)
        {
            if (!IsFinite(rawEnd) || !IsFinite(settledEnd))
            {
                return false;
            }

            Vector3 connector = settledEnd - rawEnd;
            connector.y = 0f;
            float connectorDistance = connector.magnitude;
            if (connectorDistance <= WalkThroughTerminalConnectorAlwaysAcceptDistance)
            {
                return true;
            }
            if (connectorDistance > WalkThroughTerminalConnectorMaxDistance)
            {
                return false;
            }

            Vector3 terminalDirection = Vector3.zero;
            if (corridor != null && corridor.Count >= 2)
            {
                for (int i = corridor.Count - 1; i > 0; i--)
                {
                    if (!IsFinite(corridor[i]) || !IsFinite(corridor[i - 1]))
                    {
                        continue;
                    }
                    Vector3 segment = GetFlatDirection(corridor[i] - corridor[i - 1]);
                    if (segment.sqrMagnitude > 0.5f)
                    {
                        terminalDirection = segment;
                        break;
                    }
                }
            }
            if (terminalDirection.sqrMagnitude < 0.5f)
            {
                terminalDirection = GetFlatDirection(rawEnd - rawStart);
            }
            if (terminalDirection.sqrMagnitude < 0.5f || connector.sqrMagnitude < 0.01f)
            {
                return true;
            }
            return Vector3.Dot(terminalDirection, connector.normalized) >= WalkThroughTerminalConnectorMinForwardDot;
        }

        private static void PrepareWalkThroughCompletionTarget(ProbeRuntime probe)
        {
            if (probe == null)
            {
                return;
            }

            Vector3 rawExit = IsFinite(probe.WalkThroughRawExit)
                ? probe.WalkThroughRawExit
                : probe.WalkThroughTarget;
            probe.WalkThroughRawExit = rawExit;
            probe.WalkThroughTarget = rawExit;
            probe.WalkThroughCompletionTargetSource = "rawExit";

            if ((probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority))
            {
                probe.WalkThroughCompletionTargetSource = "learningV373CurrentEpisodeExit";
                WriteEvent("learningV373WalkThroughCompletionTargetBoundToCurrentEpisode", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    episodeId = probe.TraversalEpisodeId,
                    target = Vec(rawExit),
                    historicalSettledExitIgnoredForExecution = true,
                    persistentLearningChanged = false,
                    action = "entryCorridorCompletionAndEgressShareOneCurrentEpisodeGeometryEpoch"
                });
                return;
            }

            if (!TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null ||
                !commitment.HasSettledExit ||
                !IsFinite(commitment.SettledExit))
            {
                return;
            }

            Vector3 settledExit = commitment.SettledExit;
            float planarRunOut = GetPlanarDistance(rawExit, settledExit);
            float verticalRunOut = Mathf.Abs(rawExit.y - settledExit.y);
            Vector3 runOutDirection = GetFlatDirection(settledExit - rawExit);
            float forwardDot = probe.RequestedDirection.sqrMagnitude > 0.5f &&
                               runOutDirection.sqrMagnitude > 0.5f
                ? Vector3.Dot(probe.RequestedDirection, runOutDirection)
                : 1f;

            // SettledExit is the player's proven grounded run-out. Append it only when it is a
            // short continuation on the same far side; never turn a WalkThrough corridor into a
            // long arbitrary follow route.
            Vector3 terminalRawStart = IsFinite(commitment.RawEntry) ? commitment.RawEntry : probe.TriggerPosition;
            bool terminalConnectorCredible = IsCredibleWalkThroughTerminalConnector(
                terminalRawStart, rawExit, settledExit, probe.WalkThroughCorridorPoints);
            if (planarRunOut <= 0.05f ||
                planarRunOut > WalkThroughSettledRunOutMaxDistance ||
                verticalRunOut > WalkThroughMaxVerticalDelta ||
                forwardDot < -0.20f ||
                !terminalConnectorCredible)
            {
                if (!terminalConnectorCredible)
                {
                    WriteEvent("walkThroughSettledExitRejected", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        rawExit = Vec(rawExit),
                        settledExit = Vec(settledExit),
                        planarRunOut,
                        reason = "nonCredibleTerminalConnector"
                    });
                }
                return;
            }

            if (probe.WalkThroughCorridorPoints == null)
            {
                probe.WalkThroughCorridorPoints = new List<Vector3>();
            }
            if (probe.WalkThroughCorridorPoints.Count == 0 ||
                GetPlanarDistance(probe.WalkThroughCorridorPoints[probe.WalkThroughCorridorPoints.Count - 1], settledExit) > 0.05f)
            {
                probe.WalkThroughCorridorPoints.Add(settledExit);
            }

            probe.WalkThroughTarget = settledExit;
            probe.WalkThroughCompletionTargetSource = "settledExit";
        }

        private static Vector3[] BuildRemainingWalkThroughWay(BotOwner bot, ProbeRuntime probe)
        {
            if (probe == null)
            {
                return Array.Empty<Vector3>();
            }

            Vector3 position = bot != null ? bot.Position : probe.Player.Position;
            UpdateWalkThroughArcProgress(probe, position);
            List<Vector3> result = new List<Vector3>();
            if (probe.WalkThroughCorridorPoints != null && probe.WalkThroughCorridorPoints.Count > 0)
            {
                float targetS = Mathf.Min(
                    probe.WalkThroughTotalLength,
                    probe.WalkThroughProgressS + WalkThroughArcLookAheadDistance);
                Vector3 first = SampleWalkThroughCorridorAtDistance(probe, targetS);
                if (GetPlanarDistance(position, first) > 0.08f)
                {
                    result.Add(first);
                }

                for (int index = 0; index < probe.WalkThroughCorridorPoints.Count; index++)
                {
                    if (probe.WalkThroughCorridorCumulativeLengths == null ||
                        index >= probe.WalkThroughCorridorCumulativeLengths.Count ||
                        probe.WalkThroughCorridorCumulativeLengths[index] <= targetS + 0.12f)
                    {
                        continue;
                    }
                    Vector3 point = probe.WalkThroughCorridorPoints[index];
                    if (IsFinite(point) &&
                        (result.Count == 0 || GetPlanarDistance(result[result.Count - 1], point) > 0.08f))
                    {
                        result.Add(point);
                    }
                }
            }

            if (result.Count == 0 && IsFinite(probe.WalkThroughTarget))
            {
                result.Add(probe.WalkThroughTarget);
            }
            else if (result.Count > 0 && IsFinite(probe.WalkThroughTarget) &&
                     GetPlanarDistance(result[result.Count - 1], probe.WalkThroughTarget) > 0.05f)
            {
                result.Add(probe.WalkThroughTarget);
            }
            return result.ToArray();
        }

        private static bool InstallLearningV320WalkThroughAdvisoryDirectDrive(ProbeRuntime probe, string source)
        {
            if (probe?.Bot?.Mover == null || probe.Player == null ||
                probe.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 2)
            {
                return false;
            }

            Vector3 position = probe.Player.Position;
            Vector3 target = GetCurrentWalkThroughCorridorTarget(probe, position);
            if (!IsFinite(target))
            {
                return false;
            }
            Vector3 direction = GetFlatDirection(target - position);
            target = ApplyWalkThroughClearanceCorrection(
                probe.Player, target,
                direction.sqrMagnitude > 0.5f ? direction : probe.RequestedDirection);
            float commandedSpeed = GetWalkThroughPrecisionSpeed(probe);
            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-1923E15FDB25",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverSprint("R1-0830188D1403",@probe?.Bot,false,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-506E5DF759FF",@probe?.Bot);
                if (!probe.WalkThroughDirectDriveActive)
                {
                    probe.Bot.Mover.BotMoverStop("R1-7D5DB078FA5B",@probe?.Bot);
                }
                probe.Bot.Mover.BotMoverGoToPointNoWay("R1-449F01CD28A4",@probe?.Bot,target);
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-3A0674DBCBC8",@probe?.Bot,commandedSpeed);
                probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-867567714F7A",@probe?.Bot,commandedSpeed);
                HoldForwardInput(probe);
                probe.Bot.Steering?.BotSteeringLookToDirection(
"R1-17D19B41E6CC",@probe?.Bot,                    direction.sqrMagnitude > 0.5f ? direction : probe.RequestedDirection);
                probe.WalkThroughDirectDriveActive = true;
                probe.WalkThroughFullCorridorActive = false;
                probe.WalkThroughNextDirectPointAt = Time.time + WalkThroughDirectPointRefreshSeconds;
                probe.WalkThroughMoverAckUntil = Time.time + WalkThroughMoverAckWindowSeconds;
                probe.WalkThroughLastInstalledTarget = target;
                probe.WalkThroughHasInstalledTarget = true;
            }
            catch
            {
                return false;
            }

            WriteEvent("learningV320WalkThroughAdvisoryDirectDriveInstalled", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                source,
                target = Vec(target),
                corridorIndex = probe.WalkThroughCorridorIndex,
                completionTargetSource = probe.WalkThroughCompletionTargetSource,
                validatorDisagreement = probe.WalkThroughValidatorDisagreement,
                forcedByNoProgress = probe.LearningV321WalkThroughDirectDriveAfterNoProgress,
                directCorridorDrive = true,
                fullCorridorDrive = false,
                commandedSpeed
            });
            return true;
        }

        private static bool InstallWalkThroughMoverPath(ProbeRuntime probe, string source)
        {
            if (probe?.Bot?.Mover == null || probe.Player == null)
            {
                return false;
            }

            if (true)
            {
                // V414 source-grounded off-NavMesh contract: learned WT geometry is a PIT-owned
                // virtual corridor, not native NavMesh topology. Native BotMover paths may skip
                // Player.Move through path/corner gates and OnMotionApplied may relink off-NavMesh
                // motion back to NavMesh. Retire stale topology once, then keep EFT's movement
                // state alive with a fresh native input lease on every traversal update.
                Vector3 position = probe.Player.Position;
                Vector3 virtualTarget = GetCurrentWalkThroughCorridorTarget(probe, position);
                if (!IsFinite(virtualTarget))
                {
                    return false;
                }
                float virtualCommandedSpeed = GetWalkThroughPrecisionSpeed(probe);
                string retireDetail = "alreadyPathless";
                if (probe.Bot.Mover.HasPathAndNoComplete)
                {
                    TryRetireNativeMoverPathPreserveLocomotion(
                        probe.Bot, "learningV414WalkThroughPathlessLease", out retireDetail);
                }
                try
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-2615F8F02B26",@probe?.Bot,false);
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-97BB3EBD4EEC",@probe?.Bot);
                    probe.Bot.BotOwnerSetTargetMoveSpeed("R1-11F99EF31E5C",@probe?.Bot,virtualCommandedSpeed);
                    probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-CF9F1463A5C6",@probe?.Bot,virtualCommandedSpeed);
