                    {
                        WriteEvent("learningV357WalkThroughRunEnvelope", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            state = walkThroughPhysicalState.ToString(),
                            commandedSpeed,
                            precisionRecovery,
                            recoveryOwnsLocomotionMode = learningV413RecoveryOwnsLocomotionMode,
