                {
                    probe.Bot.Mover.BotMoverSprint("R1-5DAC2E84C8D4",@probe?.Bot,false,false);
                    if (true && !walkThroughSprintCoherent &&
                        ShouldEmitDiagnostic("learningV337WalkThroughSprintStateCoherence", probe.Bot, 0.15f))
                    {
                        WriteEvent("learningV337WalkThroughSprintStateCoherence", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            state = walkThroughPhysicalState.ToString(),
                            grounded = probe.Player.MovementContext?.IsGrounded == true,
                            action = "keepForwardProducerSuppressSprintUntilPhysicalLocomotionReady"
