                probe.Bot.Mover.BotMoverGoToByWay("R1-44159F8F2140",@probe?.Bot,way,WalkThroughDirectPointReachDistance);
                EndTraversalPerfSample("WalkThroughGoToByWay", moverInstallPerfStart, probe.Bot, probe.LearnedEdgeId, "WalkThrough");
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-78944624F50D",@probe?.Bot,commandedSpeed);
                probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-2A008320F4E5",@probe?.Bot,commandedSpeed);
                HoldForwardInput(probe);
                probe.Bot.Steering?.BotSteeringLookToDirection(
"R1-A8ADEF4CD788",@probe?.Bot,                    direction.sqrMagnitude > 0.5f ? direction : probe.RequestedDirection);
                probe.WalkThroughDirectDriveActive = false;
                probe.WalkThroughFullCorridorActive = true;
                probe.WalkThroughNextDirectPointAt = Time.time + WalkThroughPathRecoveryRefreshSeconds;
                probe.WalkThroughMoverAckUntil = Time.time + WalkThroughMoverAckWindowSeconds;
                probe.WalkThroughLastInstalledTarget = target;
                probe.WalkThroughHasInstalledTarget = true;
            }
            catch
            {
                return false;
            }

            WriteEvent("walkThroughMoverPathInstalled", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                source,
                waypointCount = way.Length,
                corridorIndex = probe.WalkThroughCorridorIndex,
                completionTargetSource = probe.WalkThroughCompletionTargetSource,
                target = Vec(target),
                privateTopology = true,
                globalNavMeshLink = false,
                directCorridorDrive = false,
                fullCorridorDrive = true,
                stableRun = probe.WalkThroughStableRunActive,
