        private static bool RejectConflictingWalkThroughMoverCorner(ProbeRuntime probe, string source)
        {
            if (probe?.Bot?.Mover?.ActualPathController == null ||
                probe.Player == null ||
                probe.WalkThroughCorridorPoints == null ||
                probe.WalkThroughCorridorPoints.Count < 2 ||
                !probe.Bot.Mover.ActualPathController.HavePath)
            {
                return false;
            }

            // R8.11: BotMover's CurrentCorner may still describe the path that existed before
            // GoToPointNoWay() for a few fixed updates. Do not reject that stale corner while
            // the newly installed direct target is inside its command-acceptance window.
            if (Time.time < probe.WalkThroughMoverAckUntil)
            {
                return false;
            }

            Vector3 corner;
            try
            {
                corner = probe.Bot.Mover.ActualPathController.CurrentCornerPoint;
            }
            catch
            {
                return false;
            }
            if (!IsFinite(corner) ||
                !TryProjectOntoWalkThroughCorridor(
                    probe,
                    corner,
                    out float cornerS,
                    out _,
                    out _,
                    out float cornerLateral))
            {
                return false;
            }

            bool behind = FollowerCapabilityHelperRules.RejectConflictingWalkThroughMoverCorner_behind_5CE20BC5_1(cornerS,WalkThroughMoverConflictBacktrack,probe.WalkThroughProgressS);
            bool lateral = cornerLateral > WalkThroughMoverConflictLateral;
            if (!behind && !lateral)
            {
                return false;
            }

            bool recentlyProgressing = probe.WalkThroughLastProgressAt > 0f &&
                                       Time.time - probe.WalkThroughLastProgressAt <= WalkThroughProgressLeaseSeconds;
            float bodyLateral = GetPlanarDistanceToWalkThroughCorridor(probe, probe.Player.Position);
            bool bodyStillOwnsCorridor = FollowerCapabilityHelperRules.RejectConflictingWalkThroughMoverCorner_bodyStillOwnsCorridor_5CE20BC5_2(recentlyProgressing,bodyLateral,WalkThroughStaleCornerBodyLateralTolerance) &&
                                         probe.WalkThroughHasInstalledTarget &&
                                         probe.WalkThroughActualDisplacement >= 0.10f;
            if (bodyStillOwnsCorridor)
            {
                if (ShouldEmitDiagnostic("walkThroughMoverCornerIgnoredAsStale", probe.Bot, 0.75f))
                {
                    WriteEvent("walkThroughMoverCornerIgnoredAsStale", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        source,
                        corner = Vec(corner),
                        cornerS,
                        progressS = probe.WalkThroughProgressS,
                        cornerLateral,
                        bodyLateral,
                        installedTarget = Vec(probe.WalkThroughLastInstalledTarget),
                        reason = "bodyProgressingOnAuthoredCorridor"
                    });
                }
                return false;
            }

            bool hardBehind = FollowerCapabilityHelperRules.RejectConflictingWalkThroughMoverCorner_hardBehind_5CE20BC5_3(cornerS,WalkThroughMoverConflictHardBacktrack,probe.WalkThroughProgressS);
            bool hardLateral = cornerLateral > WalkThroughMoverConflictHardLateral;
            if (recentlyProgressing && !hardBehind && !hardLateral)
            {
                if (ShouldEmitDiagnostic("walkThroughMoverCornerRetained", probe.Bot, 0.75f))
                {
                    WriteEvent("walkThroughMoverCornerRetained", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        source,
                        corner = Vec(corner),
                        cornerS,
                        progressS = probe.WalkThroughProgressS,
                        cornerLateral,
                        behind,
                        lateral,
                        reason = "healthyProgressLease"
                    });
                }
                return false;
            }

            probe.WalkThroughMoverConflictCount++;
            try
            {
                probe.Bot.Mover.BotMoverSprint("R1-E6B1C29DB10D",@probe?.Bot,false,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-31CDC27C46A7",@probe?.Bot);
                probe.Bot.Mover.BotMoverStop("R1-2B654548D268",@probe?.Bot);
            }
            catch
            {
            }
            probe.WalkThroughNextDirectPointAt = Time.time;

            if (ShouldEmitDiagnostic("walkThroughMoverCornerRejected", probe.Bot, 0.35f))
            {
                WriteEvent("walkThroughMoverCornerRejected", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    source,
                    corner = Vec(corner),
                    cornerS,
                    progressS = probe.WalkThroughProgressS,
                    cornerLateral,
                    behind,
                    lateral,
                    conflictCount = probe.WalkThroughMoverConflictCount
                });
            }
            return true;
