        private static void BeginWalkThroughProbe(ProbeRuntime probe, float alignmentAngle)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            if ((probe.LearningV330WalkThroughPreflightFollowAuthority))
            {
                long traversalGeneration = AcquireLearningV375PersistentRouteTransaction(
                    probe, "learningV330WalkThroughPreflightReady", out bool learningV375PreflightWriterReused);
                if (traversalGeneration <= 0)
                {
                    WriteEvent("learningV330WalkThroughTraversalAuthorityCommitDeferred", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        chainId = probe.TraversalChainId,
                        alignmentAngle,
                        reason = "higherPriorityMovementOwner"
                    });
                    return;
                }

                probe.MovementWriterGeneration = traversalGeneration;
                probe.LearningV330WalkThroughPreflightFollowAuthority = false;
                {
                    probe.LearningV335WalkThroughCorridorStartPending = true;
                    probe.LearningV335WalkThroughCorridorStartAlignmentAngle = alignmentAngle;
                }
                WriteEvent("learningV330WalkThroughTraversalAuthorityCommitted", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    chainId = probe.TraversalChainId,
                    generation = traversalGeneration,
                    alignmentAngle,
                    action = ("commitPendingCorridorStartsFirstTraversalOwnedTick")
                });
                // This frame is still executing inside the old Follow write scope. Do not issue
                // Traversal mover writes until UpdateProbe re-enters under the new generation.
                return;
