            if (probe.LearningV367WalkThroughEntryFrontierAcquired)
            {
                float learningV367BeginProjection,learningV367BeginSpan,learningV367BeginLateral,learningV367BeginVerticalDeviation;
                bool finite=probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority
                    ? TryGetLearningV372CurrentEpisodeWalkThroughCorridorWitness(probe,probe.Player.Position,
                        out learningV367BeginProjection,out learningV367BeginSpan,out learningV367BeginLateral,out learningV367BeginVerticalDeviation)
                    : TryGetLearningV367WalkThroughFiniteProgress(probe,out learningV367BeginProjection,out learningV367BeginSpan,
                        out learningV367BeginLateral,out learningV367BeginVerticalDeviation);
                learningV367EntryFrontierStillValid=probe.LearningV372CurrentEpisodeWalkThroughCorridorAuthority
                    ? FollowerCapabilityPassagePolicy.WalkingInterior(finite,learningV367BeginProjection,learningV367BeginSpan,
                        learningV367BeginLateral,learningV367BeginVerticalDeviation)
                    : finite&&learningV367BeginProjection>=-.05f&&learningV367BeginProjection<learningV367BeginSpan&&
                        learningV367BeginLateral<=WalkThroughHardLateralDeviation&&learningV367BeginVerticalDeviation<=WalkThroughMaxVerticalDelta+.20f;
                if (entryDistance > WalkThroughEntryTolerance && learningV367EntryFrontierStillValid)
                {
                    WriteEvent("learningV367WalkThroughEntryDistanceGateSatisfiedByMonotonicFrontier", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        entryDistance,
                        rawEntryDistance,
                        projection = learningV367BeginProjection,
                        span = learningV367BeginSpan,
                        lateral = learningV367BeginLateral,
                        verticalDeviation = learningV367BeginVerticalDeviation,
                        action = "doNotReacquireUpstreamEntryAfterSameTransactionEnteredFinitePassage"
                    });
