        private static bool ShouldDeferWalkThroughTerminalCompletionForTransientPosition(
            ProbeRuntime probe,
            float completionDistance,
            string completionReason)
        {
            Player player = probe?.Player;
            BotOwner bot = probe?.Bot;
            if (player == null || bot == null ||
                player.CurrentStateName != EPlayerState.Transition ||
                !IsFinite(player.Position) || !IsFinite(bot.Position) ||
                !IsFinite(probe.WalkThroughTarget))
            {
                return false;
            }

            float positionDivergence = GetPlanarDistance(player.Position, bot.Position);
            float playerRemaining = GetPlanarDistance(player.Position, probe.WalkThroughTarget);
            float bodyRemaining = GetPlanarDistance(bot.Position, probe.WalkThroughTarget);
            bool defer = FollowerCapabilityHelperRules.ShouldDeferWalkThroughTerminalCompletionForTransientPosition_defer_34890B28_1(positionDivergence,WalkThroughTransitionTerminalPositionMaxDivergence,bodyRemaining,completionDistance);
            if (defer && ShouldEmitDiagnostic(
                    "walkThroughTransientPositionCompletionDeferred:" + probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture),
                    bot,
                    0.20f))
            {
                WriteEvent("walkThroughTransientPositionCompletionDeferred", bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    completionReason,
                    playerState = player.CurrentStateName.ToString(),
                    playerPosition = Vec(player.Position),
                    bodyPosition = Vec(bot.Position),
                    positionDivergence,
                    playerRemaining,
                    bodyRemaining,
                    completionDistance
                });
            }
            return defer;
        }

        private static bool TryConsumeLearningV414WalkThroughPhysicalPassBeforeRecovery(ProbeRuntime probe, bool allowEgressFallback = true)
