                    EdgeId = commitment.EdgeId,
                    Kind = commitment.Kind,
                    Entry = commitment.Entry,
                    Exit = commitment.Exit,
                    RawEntry = commitment.RawEntry,
                    RawExit = commitment.RawExit,
                    ChainId = commitment.ChainId,
                    ChainLocalExecutable = commitment.ChainLocalExecutable,
                    CurrentRaidRouteAuthority = true,
                    CreatedAt = probe.RequestedAt
