            // successor success credit.
            FollowerRouteMission learningV423PhysicalPassMission = null;
            bool learningV423ExactMissionStep =
                (!string.IsNullOrEmpty(probe.Bot.ProfileId)) &&
                FollowerRouteMissions.TryGetValue(
                    probe.Bot.ProfileId, out learningV423PhysicalPassMission) &&
                learningV423PhysicalPassMission != null &&
                learningV423PhysicalPassMission.Steps != null &&
                learningV423PhysicalPassMission.CurrentStepIndex >= 0 &&
                learningV423PhysicalPassMission.CurrentStepIndex < learningV423PhysicalPassMission.Steps.Count;
            if (learningV423ExactMissionStep)
            {
