                    learningV423CurrentStep.EpisodeId == probe.TraversalEpisodeId &&
                    learningV423CurrentStep.EdgeId == probe.LearnedEdgeId &&
                    learningV423PassageProfile != null &&
                    !learningV423PassageProfile.RequiresActuator &&
                    learningV423PassageProfile.PhysicalPassageCanProveCompletion &&
