        private static bool TryGetLearningV419WalkThroughTerminalFrontierContinuation(
            ProbeRuntime probe, Vector3 body,
            out Vector3 terminalForward, out float forwardProjection, out float lateralDistance)
        {
            terminalForward = Vector3.zero;
            forwardProjection = float.MinValue;
            lateralDistance = float.MaxValue;
            if ((probe == null) ||
                !probe.LearningV367WalkThroughEntryFrontierAcquired ||
                probe.WalkThroughCorridorPoints == null || probe.WalkThroughCorridorPoints.Count < 2 ||
                !IsFinite(body))
            {
                return false;
            }

            int last = probe.WalkThroughCorridorPoints.Count - 1;
            Vector3 terminal = probe.WalkThroughCorridorPoints[last];
            Vector3 previous = probe.WalkThroughCorridorPoints[last - 1];
            terminalForward = GetFlatDirection(terminal - previous);
            if (!IsFinite(terminal) || terminalForward.sqrMagnitude <= 0.5f)
            {
                return false;
            }

            Vector3 delta = body - terminal;
            delta.y = 0f;
            forwardProjection = Vector3.Dot(delta, terminalForward);
            Vector3 axisPoint = terminal + terminalForward * forwardProjection;
            lateralDistance = GetPlanarDistance(body, axisPoint);

            // This is movement-authority evidence only, never traversal success. V4.22 stops
            // reusing the ENTRY acquisition epsilon as a TERMINAL crossing proof: current runtime
            // showed that doing so can transfer authority a few centimetres before the body actually
            // crosses the finite terminal plane, injecting an avoidable EFT Transition/Idle epoch.
            // Keep the existing hard lateral envelope, but terminal ownership now requires true
            // non-negative forward projection. Egress/Verify still decides physical completion.
