            return terminalPlaneActuallyCrossed &&
                   lateralDistance <= WalkThroughHardLateralDeviation;
        }

        private static void UpdateWalkThroughProbe(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Player?.MovementContext == null)
            {
                return;
            }

            Player player = probe.Player;
            float observedStep = GetPlanarDistance(player.Position, probe.WalkThroughLastObservedPosition);
            if (observedStep > 0.001f)
            {
                probe.WalkThroughActualDisplacement += observedStep;
