                probe.WalkThroughStepAssistNativeOwned &&
                IsProbeTraversalState(player.CurrentStateName))
            {
                if (ShouldEmitDiagnostic(
                        "walkThroughStepAssistNativeConsumerPrecedence:" + probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture),
                        probe.Bot,
                        0.50f))
                {
                    WriteEvent("walkThroughStepAssistNativeConsumerPrecedence", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        state = player.CurrentStateName.ToString(),
                        blocker = probe.WalkThroughStepAssistBlocker,
                        nativeOwned = true
