                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    state = player.CurrentStateName.ToString()
                });
                // Keep the traversal mission. EFT may have promoted the seam into a native state;
                // unified Verify will decide whether it actually ended on the far side.
                BeginUnifiedTraversalEgressOrVerify(probe, "walkThroughUnexpectedNativeState");
                return;
            }

            float verticalDisplacement = Mathf.Abs(player.Position.y - probe.TriggerPosition.y);
            float verticalCorridorDeviation = verticalDisplacement;
            bool verticalCorridorProjection = false;
            if (true &&
                TryProjectOntoWalkThroughCorridor(
                    probe, player.Position,
                    out _, out Vector3 learningV365VerticalProjection, out _, out _))
            {
                verticalCorridorProjection = true;
                verticalCorridorDeviation = Mathf.Abs(player.Position.y - learningV365VerticalProjection.y);
            }
