                    learnedEdgeId = probe.LearnedEdgeId,
                    position = Vec(player.Position),
                    target = Vec(probe.WalkThroughTarget),
                    motionTarget = Vec(motionTarget),
                    corridorIndex = probe.WalkThroughCorridorIndex,
                    remainingDistance = distance,
                    finalDistance,
                    lateralDeviation,
                    commandedSegmentDistance = segmentDistance,
                    observedStep,
                    actualDisplacement = probe.WalkThroughActualDisplacement,
                    moverFixedUpdateAllowed = true,
                    moverHasPath = probe.Bot.Mover.HasPathAndNoComplete,
                    ownershipRemaining = probe.OwnershipLeaseExpiresAt - Time.time,
                    recoveryAttempts = probe.WalkThroughPathRecoveryAttempts,
                    recenterAttempts = probe.WalkThroughRecenterAttempts,
                    turnAngle = GetWalkThroughTurnAngle(probe),
                    commandedSpeed = GetWalkThroughPrecisionSpeed(probe),
                    stableRun = probe.WalkThroughStableRunActive,
                    precisionCorridor = probe.WalkThroughPrecisionCorridorActive,
                    completionTargetSource = probe.WalkThroughCompletionTargetSource,
                    grounded = player.MovementContext.IsGrounded
                });
            }
        }

        private static void AbortWalkThroughProbe(
            ProbeRuntime probe,
            string reason,
            string details,
            bool invalidateEdge)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            WriteEvent("walkThroughAborted", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                reason,
                details,
                invalidateEdge,
                position = probe.Player != null ? Vec(probe.Player.Position) : null,
                target = Vec(probe.WalkThroughTarget)
            });

            bool zeroShotTransfer = TryGetLearningV319TransientSkillTransfer(
                probe, out LearnedTraversalCommitment zeroShotCommitment);
            if (!zeroShotTransfer && invalidateEdge)
            {
                InvalidateLearnedTraversalEdge(probe.LearnedEdgeId, reason);
            }
            else if (!zeroShotTransfer && probe.LearnedEdgeId > 0)
            {
                SnapshotTraversalCommitmentForRecovery(probe.Bot, probe.LearnedEdgeId);
                ClearLearnedTraversalCommitment(probe.Bot, probe.LearnedEdgeId, reason);
            }
            else if (zeroShotTransfer)
            {
                WriteEvent("learningV319ZeroShotWalkThroughAbortIsolated", probe.Bot, new
                {
                    templateEdgeId = zeroShotCommitment.SkillTemplateEdgeId,
                    kind = zeroShotCommitment.Kind,
                    reason = reason ?? string.Empty,
                    invalidateRequested = invalidateEdge,
                    templateExperienceUnchanged = true
                });
            }

            if (probe.Player != null &&
                TryGetWalkThroughReanchor(probe.Player.Position, out NavMeshHit navHit, out _) &&
                TryReanchorAndRelease(probe, navHit.position, reason, out _))
            {
                return;
            }

            FinishProbeWithoutReanchor(probe, reason, details);
        }

        private static bool TryValidateWalkThroughPolyline(
            Player player,
            Vector3 currentPosition,
            List<Vector3> points,
            out string failure,
            out string blocker,
            out int failedSegment)
        {
            failure = string.Empty;
            blocker = string.Empty;
            failedSegment = -1;
            if (points == null || points.Count < 2)
            {
                failure = "WalkThrough polyline has fewer than two points";
                return false;
            }

            Vector3 previous = currentPosition;
            for (int i = 0; i < points.Count; i++)
            {
                Vector3 current = points[i];
                if (!IsFinite(current) || GetPlanarDistance(previous, current) < 0.18f)
                {
                    previous = current;
                    continue;
                }
                if (!TryValidateWalkThroughCorridor(player, previous, current, out failure, out blocker, polylineSegment:true))
                {
                    failedSegment = i;
                    failure = $"polyline segment {i} failed: {failure}";
                    return false;
                }
                previous = current;
            }
            return true;
        }

        private static bool TryValidateWalkThroughCorridor(
            Player player,
            Vector3 start,
            Vector3 end,
            out string failure,
            out string blocker,
            bool polylineSegment = false)
        {
            failure = string.Empty;
            blocker = string.Empty;
            if (player?.MovementContext == null || !IsFinite(start) || !IsFinite(end))
            {
                failure = "invalid player or corridor endpoints";
                return false;
            }

            Vector3 planar = end - start;
            float verticalDelta = Mathf.Abs(planar.y);
            planar.y = 0f;
            float distance = planar.magnitude;
            if (!FollowerCapabilityPassagePolicy.CorridorSegmentLength(distance,polylineSegment))
            {
                failure = "WalkThrough corridor is too short";
                return false;
            }
            if (distance > WalkThroughMaxExecutionDistance)
            {
                failure = $"WalkThrough corridor is too long ({distance:0.00}m)";
                return false;
            }
            if (verticalDelta > WalkThroughMaxVerticalDelta)
            {
                failure = $"WalkThrough corridor vertical delta is too large ({verticalDelta:0.00}m)";
                return false;
            }

            Vector3 direction = planar / distance;
            float capsuleDistance = Mathf.Max(0.05f, distance - 0.08f);
            GetCapabilityCorridorCapsule(player,start,out var capsuleBottom,out var capsuleTop,out float capsuleRadius);
            if (TryGetFirstNonSelfCapsuleCastHit(
                    player,
                    capsuleBottom,
                    capsuleTop,
                    capsuleRadius,
                    direction,
                    capsuleDistance,
                    LayersMaskController.HighPolyWithTerrainMask,
                    out RaycastHit bodyHit))
            {
                Vector3 raisedBottom = capsuleBottom + Vector3.up * WalkThroughStepAssistLift;
                Vector3 raisedTop = capsuleTop + Vector3.up * WalkThroughStepAssistLift;
                if (TryGetFirstNonSelfCapsuleCastHit(
                        player,
                        raisedBottom,
                        raisedTop,
                        capsuleRadius,
                        direction,
                        capsuleDistance,
                        LayersMaskController.HighPolyWithTerrainMask,
                        out RaycastHit raisedHit))
                {
                    blocker = raisedHit.collider?.name ?? bodyHit.collider?.name ?? "unknown";
                    failure = $"solid world geometry blocks both normal and step-assist WalkThrough corridors at {raisedHit.distance:0.00}m";
                    return false;
                }

                blocker = "stepAssist:" + (bodyHit.collider?.name ?? "unknown");
            }

            float[] floorSamples = { 0.25f, 0.50f, 0.75f };
            for (int index = 0; index < floorSamples.Length; index++)
            {
                Vector3 expected = Vector3.Lerp(start, end, floorSamples[index]);
                Vector3 floorOrigin = expected + Vector3.up * WalkThroughFloorProbeHeight;
                if (!TryGetFirstNonSelfRaycastHit(
                        player,
                        floorOrigin,
                        Vector3.down,
                        WalkThroughFloorProbeDistance,
                        LayersMaskController.HighPolyWithTerrainMask,
                        out RaycastHit floorHit))
                {
                    failure = $"WalkThrough floor probe {index + 1} found no physical floor";
                    return false;
                }

                float floorOffset = Mathf.Abs(floorHit.point.y - expected.y);
                if (floorOffset > WalkThroughFloorMaxOffset)
                {
                    failure = $"WalkThrough floor probe {index + 1} offset is unsafe ({floorOffset:0.00}m)";
                    blocker = floorHit.collider?.name ?? string.Empty;
                    return false;
                }
            }

            return true;
        }

        private static bool TryGetWalkThroughReanchor(Vector3 position, out NavMeshHit navHit, out string failure)
        {
            navHit = default;
            failure = string.Empty;
            if (!NavMesh.SamplePosition(position, out navHit, WalkThroughReanchorRadius, NavMesh.AllAreas))
            {
                failure = $"no NavMesh within {WalkThroughReanchorRadius:0.00}m";
                return false;
            }

            float verticalOffset = Mathf.Abs(position.y - navHit.position.y);
            if (verticalOffset > ProbeLandingMaxVerticalOffset)
            {
                failure = $"nearest NavMesh vertical offset is {verticalOffset:0.00}m";
                return false;
            }

            return true;
        }

        private static float GetPlanarDistance(Vector3 left, Vector3 right)
        {
            Vector3 delta = right - left;
            delta.y = 0f;
            return delta.magnitude;
        }

        private static float GetPlanarDistanceToSegment(Vector3 point, Vector3 start, Vector3 end)
        {
            point.y = 0f;
            start.y = 0f;
            end.y = 0f;
            Vector3 segment = end - start;
            float lengthSquared = segment.sqrMagnitude;
            if (lengthSquared <= 0.0001f)
            {
                return Vector3.Distance(point, start);
            }

            float t = Mathf.Clamp01(Vector3.Dot(point - start, segment) / lengthSquared);
            return Vector3.Distance(point, start + segment * t);
        }

        private static void InvalidateLearnedTraversalEdge(int edgeId, string reason)
        {
            if (edgeId <= 0)
            {
                return;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate.Id == edgeId);
            if (edge == null)
            {
                return;
            }

            bool historicalSemanticProtected =
                (IsLearningV345ProtectedHistoricalWalkThroughSemantic(edge));
            if (historicalSemanticProtected)
            {
                // Fail closed: this generic invalidation API expresses execution/controller failure,
                // not independent proof that the player-authored historical passage is semantically
                // false. Record the failure through the causality barrier and clear only transient
                // commitments; never remove persistent historical geometry here.
                MarkLearnedTraversalEdgeFailure(edgeId, reason);
                WriteEvent("learningV346HistoricalSemanticInvalidationSuppressed", null, new
                {
                    edgeId = edge.Id,
                    experienceKey = edge.ExperienceKey,
                    kind = edge.Kind,
                    reason,
                    action = "preserveUpstreamHistoricalPassageClearTransientCommitmentsOnly"
                });
            }
            else if (edge.Verified)
            {
                MarkLearnedTraversalEdgeFailure(edgeId, reason);
            }
            else
            {
                LearnedTraversalEdges.Remove(edge);
                FollowerRuntimeNavMeshLinks.Remove(edgeId);
            }

            ClearCommitmentsForEdge(edgeId);

            WriteEvent("playerTraversalEdgeInvalidated", null, new
            {
                edgeId,
                kind = edge.Kind,
                reason,
                verified = edge.Verified,
                disabled = edge.Disabled,
                failures = edge.FailedExecutions,
                a = Vec(edge.A),
                b = Vec(edge.B)
            });
        }


        private static bool IsTraversalExecutionFailure(string reason)
        {
            if (string.IsNullOrEmpty(reason))
            {
                return false;
            }

            return reason.IndexOf("scanRefused", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   reason.IndexOf("strategy", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   reason.IndexOf("alignmentTimeout", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   reason.IndexOf("walkThroughNoProgress", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   reason.IndexOf("walkThroughTimeout", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   reason.IndexOf("stateEnterTimeout", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   reason.IndexOf("executionTimeout", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static void MarkLearnedTraversalEdgeSuccess(
            int edgeId,
            TraversalCompletionMode completionMode,
            ProbeRuntime probe)
        {
            if (probe!=null && !IsProbeLifecycleCurrent(probe,true)) return;
            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate.Id == edgeId);
            if (edge == null)
            {
                return;
            }

            string learningV354SemanticKind = GetLearningV354SemanticKind(edge.Id, edge.Kind);
            if (edge.SyntheticPhysicalCorridor)
            {
                bool learningV355SyntheticRecovery = ((completionMode == TraversalCompletionMode.TeleportFallback ||
                     probe?.TraversalTeleportAttempted == true || probe?.TeleportFallbackUsed == true));
                if (!learningV355SyntheticRecovery)
                {
                    edge.SuccessfulExecutions++;
                    edge.FailedExecutions = 0;
                }
                RecordLearningV354ActionOutcome(
                    learningV354SemanticKind, !learningV355SyntheticRecovery, learningV355SyntheticRecovery,
                    learningV355SyntheticRecovery ? "runtimePhysicalCorridorRecovery" : "runtimePhysicalCorridorCompleted");
                WriteEvent("learningV354AnonymousPhysicalCorridorCompleted", probe?.Bot, new
                {
                    edgeId = edge.Id, semanticKind = learningV354SemanticKind, executorKind = edge.Kind,
                    completionMode = completionMode.ToString(), persistent = false,
                    recoveryOutcome = learningV355SyntheticRecovery
                });
                return;
            }
            bool learningV355RecoveryOutcome = ((completionMode == TraversalCompletionMode.TeleportFallback ||
                 probe?.TraversalTeleportAttempted == true || probe?.TeleportFallbackUsed == true));
            RecordLearningV354ActionOutcome(
                learningV354SemanticKind, !learningV355RecoveryOutcome, learningV355RecoveryOutcome,
                learningV355RecoveryOutcome
                    ? "traversalRecoveryCompleted:" + completionMode
                    : "traversalActionCompleted:" + completionMode);

            {
                bool retainableNative = IsLearningV3RetainableNativeSuccess(probe, completionMode);
                if (!retainableNative)
                {
                    WriteEvent("learningV3CandidateRuntimeRescueNotLearned", probe?.Bot, new
                    {
                        edgeId = edge.Id,
                        kind = edge.Kind,
                        completionMode = completionMode.ToString(),
                        nativeProven = IsLearningV3NativeProvenEdge(edge),
                        retainedExperience = false,
                        assisted = probe?.AssistedReplayAttempted == true || probe?.AssistedPartialNativeContinuation == true,
                        teleport = probe?.TraversalTeleportAttempted == true || probe?.TeleportFallbackUsed == true,
                        forcedEgressDistance = probe?.UnifiedEgressForcedDistance ?? 0f
                    });
                    return;
                }

                bool learningV379RuntimeAlternativePromotion =
                    (edge.RuntimeOnlyTraversal);
                if (learningV379RuntimeAlternativePromotion)
                {
                    edge.RuntimeOnlyTraversal = false;
                    edge.RuntimeAuthoritySource = null;
                    WriteEvent("learningV379RuntimeAlternativePromotedByNativeSuccess", probe?.Bot, new
                    {
                        edgeId = edge.Id,
                        kind = edge.Kind,
                        parentEdgeId = edge.RuntimeAlternativeParentEdgeId,
                        completionMode = completionMode.ToString(),
                        action = "cleanFollowerNativeSuccessPromotesRaidLocalAffordanceToPersistentCandidate"
                    });
                }

                bool firstPromotion = !IsLearningV3NativeProvenEdge(edge);
                if ((firstPromotion) &&
                    string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    LearnedTraversalEdge canonicalWalkThrough = FindLearningV325CanonicalNativeWalkThrough(edge);
                    if (canonicalWalkThrough != null)
                    {
                        edge.SupersedesProvenEdgeId = canonicalWalkThrough.Id;
                        edge.Verified = false;
                        edge.NativeSuccessCount = 0;
                        edge.SuccessfulExecutions = 0;
                        WriteEvent("learningV325NativeWalkThroughPromotionCanonicalized", probe?.Bot, new
                        {
                            transientEdgeId = edge.Id, canonicalEdgeId = canonicalWalkThrough.Id,
                            transientRawStart = Vec(edge.RawStart), transientRawEnd = Vec(edge.RawEnd),
                            canonicalRawStart = Vec(canonicalWalkThrough.RawStart), canonicalRawEnd = Vec(canonicalWalkThrough.RawEnd),
                            canonicalNativeSuccesses = canonicalWalkThrough.NativeSuccessCount,
                            persistentGeometryMutated = false, successCreditMerged = false
                        });
                        SaveLearningV31NativeProvenStore();
                        return;
                    }
                }
                if (string.IsNullOrWhiteSpace(edge.ExperienceKey))
                {
                    edge.ExperienceKey = CreateTraversalExperienceKey();
                }
                bool learningV345HistoricalGraduation =
                    (edge.HistoricalSemanticAuthority) &&
                    string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
                if (learningV345HistoricalGraduation)
                {
                    edge.HistoricalSemanticAuthority = false;
                    LearningV344HistoricalWalkThroughSemanticKeys.Remove(edge.ExperienceKey);
                    WriteEvent("learningV345HistoricalSemanticGraduatedToModernNative", probe?.Bot, new
                    {
                        edgeId = edge.Id,
                        experienceKey = edge.ExperienceKey,
                        kind = edge.Kind,
                        action = "modernCleanNativeProofReplacesHistoricalOnlyAuthority"
                    });
                }
                edge.SuccessfulExecutions++;
                edge.NativeSuccessCount++;
                edge.FailedExecutions = 0;
                edge.Verified = true;
                edge.Disabled = false;
                edge.CreatedAt = Time.time;
                if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    ;
                    RecordPrivateWalkThroughAvailable(edge, "learningV3NativeProven");
                }
                {
                    SaveLearningV31NativeProvenStore();
                }
                WriteEvent(firstPromotion ? "learningV3NativeSkillPromoted" : "learningV3NativeSkillConfirmed", probe?.Bot, new
                {
                    edgeId = edge.Id,
                    experienceKey = edge.ExperienceKey,
                    kind = edge.Kind,
                    demonstrationRevision = edge.DemonstrationRevision,
                    nativeSuccesses = edge.NativeSuccessCount,
                    successfulExecutions = edge.SuccessfulExecutions,
                    entryCorrectionAttempts = probe?.LearningV3EntryCorrectionAttempts ?? 0,
                    supersedesProvenEdgeId = edge.SupersedesProvenEdgeId,
                    retainedExperience = true
                });
                WriteEvent("traversalLinkNativeVerified", null, new
                {
                    edgeId = edge.Id,
                    kind = edge.Kind,
                    completionMode = TraversalCompletionMode.Native.ToString(),
                    nativeVerified = true,
                    successes = edge.SuccessfulExecutions,
                    nativeSuccesses = edge.NativeSuccessCount,
                    assistedSuccesses = 0,
                    teleportFallbacks = 0,
                    disabled = edge.Disabled,
                    a = Vec(edge.A),
                    b = Vec(edge.B)
                });
                if (firstPromotion)
                {
                    RetireLearningV3SupersededProvenEdge(edge);
                }
                return;
            }

            bool teleportRecovery = completionMode == TraversalCompletionMode.TeleportFallback ||
                                    probe?.TraversalTeleportAttempted == true ||
                                    probe?.TeleportFallbackUsed == true;
            bool forcedEgressRecovery =
                (probe?.UnifiedEgressForcedDistance >= ForcedEgressRecoveryDistance &&
                 probe?.IslandExitNominalClimbTopBridge != true) ||
                probe?.RecoveryExitAlreadySatisfied == true;
            if (teleportRecovery || forcedEgressRecovery)
            {
                // R8.7 learning integrity: recovery proves only that PIT can rescue the follower.
                // It must never make the geometry NativeVerified/WalkThrough-verified or increase
                // physical SuccessfulExecutions. Keep only an explicit fallback count.
                if (teleportRecovery)
                {
                    edge.TeleportFallbackCount++;
                }
                edge.CreatedAt = Time.time;
                SavePersistentTraversalLinks();
                WriteEvent("traversalLinkRecoveryOnly", null, new
                {
                    edgeId = edge.Id,
                    kind = edge.Kind,
                    completionMode = completionMode.ToString(),
                    teleportRecovery,
                    forcedEgressRecovery,
                    forcedEgressDistance = probe?.UnifiedEgressForcedDistance ?? 0f,
                    physicalSuccesses = edge.SuccessfulExecutions,
                    teleportFallbacks = edge.TeleportFallbackCount,
                    verified = edge.Verified
                });
                return;
            }

            if (completionMode == TraversalCompletionMode.Native &&
                probe?.NativePartialCrossingObserved == true)
            {
                // CompileFix47: native state participation is not native completion. If PIT egress
                // or another assisted stage had to finish a partial crossing, keep the traversal
                // successful but account it as assisted/hybrid and never NativeVerified.
                WriteEvent("nativePartialCompletionReclassifiedAssisted", probe.Bot, new
                {
                    edgeId = edge.Id,
                    kind = edge.Kind,
                    previousMode = TraversalCompletionMode.Native.ToString(),
                    replacementMode = TraversalCompletionMode.AssistedReplay.ToString()
                });
                completionMode = TraversalCompletionMode.AssistedReplay;
                probe.AssistedPartialNativeContinuation = true;
            }

            bool preserveChainLocalDisabledDropDown = false;
            if (edge.Disabled && probe != null &&
                string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment chainLocalCommitment) &&
                chainLocalCommitment != null && chainLocalCommitment.ChainLocalExecutable)
            {
                preserveChainLocalDisabledDropDown = true;
            }

            edge.SuccessfulExecutions++;
            edge.FailedExecutions = 0;
            if (!preserveChainLocalDisabledDropDown)
            {
                edge.Disabled = false;
            }
            edge.CreatedAt = Time.time;

            if (probe?.AssistedPartialNativeContinuation == true)
            {
                edge.AssistedSuccessCount++;
            }
            else
            {
                switch (completionMode)
                {
                    case TraversalCompletionMode.Native:
                        edge.NativeSuccessCount++;
                        edge.Verified = true;
                        break;
                    case TraversalCompletionMode.AssistedReplay:
                        edge.AssistedSuccessCount++;
                        break;
                    default:
                        if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                        {
                            edge.Verified = true;
                        }
                        break;
                }
            }

            if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                edge.Verified = true;
                RecordPrivateWalkThroughAvailable(edge, "verified");
            }
            SavePersistentTraversalLinks();
            string completionEvent = completionMode switch
            {
                TraversalCompletionMode.Native => "traversalLinkNativeVerified",
                TraversalCompletionMode.AssistedReplay => "traversalLinkAssistedSuccess",
                _ => "traversalLinkVerified"
            };
            WriteEvent(completionEvent, null, new
            {
                edgeId = edge.Id,
                kind = edge.Kind,
                completionMode = completionMode.ToString(),
                nativeVerified = edge.Verified,
                successes = edge.SuccessfulExecutions,
                nativeSuccesses = edge.NativeSuccessCount,
                assistedSuccesses = edge.AssistedSuccessCount,
                teleportFallbacks = edge.TeleportFallbackCount,
                persistentDisabledPreserved = preserveChainLocalDisabledDropDown,
                disabled = edge.Disabled,
                a = Vec(edge.A),
                b = Vec(edge.B)
            });
        }

        private static void MarkLearnedTraversalEdgeFailure(int edgeId, string reason)
        {
            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate.Id == edgeId);
            if (edge == null)
            {
                return;
            }

            string learningV354SemanticKind = GetLearningV354SemanticKind(edge.Id, edge.Kind);
            RecordLearningV354ActionOutcome(learningV354SemanticKind, false, false, reason ?? "traversalFailure");
            if (edge.SyntheticPhysicalCorridor)
            {
                edge.FailedExecutions++;
                WriteEvent("learningV354AnonymousPhysicalCorridorFailure", null, new
                {
                    edgeId = edge.Id, semanticKind = learningV354SemanticKind, executorKind = edge.Kind,
                    failures = edge.FailedExecutions, reason, persistent = false
                });
                return;
            }

            edge.FailedExecutions++;
            bool deterministicFailure = IsDeterministicTraversalFailure(reason);
            int physicalSuccesses = GetTraversalPhysicalSuccessCount(edge);
            bool successProtected = physicalSuccesses > 0;
            bool historicalSemanticProtected =
                (IsLearningV345ProtectedHistoricalWalkThroughSemantic(edge));
            int disableThreshold = historicalSemanticProtected
                ? int.MaxValue
                : (edge.Verified ? 2 : (deterministicFailure ? 2 : int.MaxValue));
            // COMPILEFIX9: never permanently disable a player-authored edge merely because the
            // follower controller failed to converge. Only deterministic geometry validation may
            // quarantine an unverified PlayerValidated edge. This prevents RollingApproach/chain
            // policy failures from deleting valid authored traversal knowledge.
            bool shouldDisable =
                !historicalSemanticProtected &&
                !successProtected &&
                (FollowerCapabilityHelperRules.MarkLearnedTraversalEdgeFailure_shouldDisable_5AA4BD0B_1(edge.Verified,edge.PlayerValidated,deterministicFailure)) &&
                edge.FailedExecutions >= disableThreshold;
            if (historicalSemanticProtected && deterministicFailure &&
                (edge.FailedExecutions % 2 == 0 || edge.FailedExecutions == 1))
            {
                WriteEvent("learningV346HistoricalSemanticFailureCausalityBarrier", null, new
                {
                    edgeId = edge.Id,
                    experienceKey = edge.ExperienceKey,
                    kind = edge.Kind,
                    failures = edge.FailedExecutions,
                    reason,
                    deterministicFailure,
                    action = "recordDownstreamFailureWithoutDisablingUpstreamHistoricalPassageTruth"
                });
            }

            if ((edge.PlayerValidated || edge.Verified) &&
                (edge.FailedExecutions % 2 == 0 || shouldDisable))
            {
                SavePersistentTraversalLinks();
            }

            if (shouldDisable && !edge.Disabled)
            {
                edge.Disabled = true;
                if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    FollowerRuntimeNavMeshLinks.Remove(edge.Id);
                }

                // R8.11: PlayerValidated-but-never-BotVerified links used to be immortal because
                // only edge.Verified was eligible for disablement. A deterministic geometry reject
                // could therefore re-arm forever (the R8.10 Jump edge 67 trace reached ten failures).
                // Disable bounded repeat offenders and purge every queued commitment immediately.
                ClearCommitmentsForEdge(edge.Id);
                SavePersistentTraversalLinks();
            }

            WriteEvent("traversalLinkFailure", null, new
            {
                edgeId = edge.Id,
                kind = edge.Kind,
                verified = edge.Verified,
                playerValidated = edge.PlayerValidated,
                failures = edge.FailedExecutions,
                deterministicFailure,
                physicalSuccesses,
                successProtected,
                historicalSemanticProtected,
                disableThreshold,
                disabled = edge.Disabled,
                reason
            });
        }

        private static bool IsDeterministicTraversalFailure(string reason)
        {
            if (string.IsNullOrWhiteSpace(reason))
            {
                return false;
            }

            string value = reason.ToLowerInvariant();
            return value.Contains("geometry rejected") ||
                   value.Contains("hardvalidation") ||
                   value.Contains("solidgeometry") ||
                   value.Contains("solid world geometry") ||
                   // RollingApproach / Entry convergence is a controller/chain-policy failure,
                   // not proof that the player-authored passage geometry itself is invalid.
                   value.Contains("corridorvalidation");
        }

        private static void ClearCommitmentsForEdge(int edgeId)
        {
            HashSet<string> affectedProfiles = new HashSet<string>(StringComparer.Ordinal);

            foreach (string profileId in LearnedTraversalCommitments
                .Where(pair => pair.Value != null && pair.Value.EdgeId == edgeId)
                .Select(pair => pair.Key)
                .ToArray())
            {
                LearnedTraversalCommitments.Remove(profileId);
                affectedProfiles.Add(profileId);
            }

            foreach (string profileId in NavigationRecoveryTraversalAnchors
                .Where(pair => pair.Value != null && pair.Value.EdgeId == edgeId)
                .Select(pair => pair.Key)
                .ToArray())
            {
                NavigationRecoveryTraversalAnchors.Remove(profileId);
                affectedProfiles.Add(profileId);
            }

            // R8.12: a disabled/quarantined edge must also disappear from already-built Route
            // Missions. Otherwise Follow can resurrect it without consulting the edge selector.
            foreach (string profileId in FollowerRouteMissions
                .Where(pair => pair.Value?.Steps != null &&
                               pair.Value.Steps.Any(step => step != null && step.EdgeId == edgeId))
                .Select(pair => pair.Key)
                .ToArray())
            {
                RemoveLifecycleMission(profileId, "ClearCommitmentsForEdge");
                affectedProfiles.Add(profileId);
            }

            foreach (string profileId in affectedProfiles)
            {
                ProvisionalWalkThroughReservations.Remove(profileId);
                BreadcrumbFollowCommitments.Remove(profileId);
                FollowRejectLeases.Remove(profileId);
                if (FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) &&
                    cursor != null)
                {
                    cursor.PreloadedEpisodeId = 0;
                }
            }

            string retrySuffix = ":" + edgeId.ToString(CultureInfo.InvariantCulture);
            foreach (string retryKey in LearnedTraversalRetryAfter.Keys
                .Where(key => key.EndsWith(retrySuffix, StringComparison.Ordinal))
                .ToArray())
            {
                LearnedTraversalRetryAfter.Remove(retryKey);
            }
        }

        private static void RecordPrivateWalkThroughAvailable(LearnedTraversalEdge edge, string source)
        {
            if (edge == null || edge.Disabled ||
                !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            WriteEvent("privateWalkThroughEdgeAvailable", null, new
            {
                edgeId = edge.Id,
                kind = edge.Kind,
                source = source ?? "unknown",
                entry = Vec(edge.A),
                exit = Vec(edge.B),
                globalNavMeshLink = false
            });
        }

        private static string NormalizeLearningV354Kind(string kind)
        {
            return string.IsNullOrWhiteSpace(kind) ? "Unknown" : kind.Trim();
        }

        private static string GetLearningV354SemanticKind(int edgeId, string fallbackKind)
        {
            LearnedTraversalEdge edge = edgeId > 0
                ? LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == edgeId)
                : null;
            if (edge?.SyntheticPhysicalCorridor == true && !string.IsNullOrWhiteSpace(edge.RuntimeSemanticKind))
            {
                return edge.RuntimeSemanticKind;
            }
            return NormalizeLearningV354Kind(fallbackKind ?? edge?.Kind);
        }

        private static bool TryGetLearningV354ContinuousSuccessorHandoffGuard(
            ProbeRuntime probe, out ChainHandoffAuthorityGuard guard)
        {
            guard = null;
            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            if ((string.IsNullOrEmpty(profileId)) || probe == null ||
                !ChainHandoffAuthorityGuards.TryGetValue(profileId, out guard) || guard == null ||
                guard.Generation != raidGeneration || !guard.ContinuousExactSuccessor || !guard.SuccessorAuthorityAcquired)
            {
                guard = null;
                return false;
            }
            bool matching =
                (guard.SuccessorProbeEdgeId <= 0 || guard.SuccessorProbeEdgeId == probe.LearnedEdgeId) &&
                (guard.SuccessorProbeChainId <= 0 || probe.TraversalChainId <= 0 || guard.SuccessorProbeChainId == probe.TraversalChainId);
            if (!matching) guard = null;
            return matching;
        }

        private static bool LearningV354HasStableRouteReleaseProof(ProbeRuntime probe)
        {
            if (probe == null || probe.Player == null) return false;
            string semanticKind = GetLearningV354SemanticKind(
                probe.LearnedEdgeId, probe.TraversalKind ?? probe.RequestedTraversalKind);
            LearningV354TraversalCapabilityProfile profile = GetLearningV354ActionProfile(semanticKind);
            if (!profile.RequiresLandingProof)
            {
                return IsEffectivelySupportedForProbe(probe.Bot, probe.Player) && !IsProbeTraversalState(probe.Player.CurrentStateName);
            }
            if (string.Equals(semanticKind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return probe.LearningV330NativeJumpQualifiedLandingWitness &&
                       IsEffectivelySupportedForProbe(probe.Bot, probe.Player) && !IsProbeTraversalState(probe.Player.CurrentStateName);
            }
            if (string.Equals(semanticKind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                return probe.NativeDropDownPhysicalLandingAuthority ||
                       (IsEffectivelySupportedForProbe(probe.Bot, probe.Player) && !IsProbeTraversalState(probe.Player.CurrentStateName));
            }
            return IsEffectivelySupportedForProbe(probe.Bot, probe.Player) && !IsProbeTraversalState(probe.Player.CurrentStateName);
        }

        private static string MakeLearningV354TransitionKey(string fromKind, string toKind)
        {
            return NormalizeLearningV354Kind(fromKind) + "->" + NormalizeLearningV354Kind(toKind);
        }

        private static LearningV354TraversalCapabilityProfile CreateLearningV354SeedProfile(string kind)
        {
            string normalized = NormalizeLearningV354Kind(kind);
            var traits=FollowerCapabilityStrategyPolicy.Describe(
                FollowerCapabilityDeliveryPolicy.Parse(normalized),LearningV354JumpActuatorLeadInitialSeconds);
            LearningV354TraversalCapabilityProfile profile = new LearningV354TraversalCapabilityProfile
            {
                Kind=normalized,RequiresActuator=traits.Actuator,
                PhysicalPassageCanProveCompletion=traits.PassageCompletion,
                CanFinishOffNavMesh=traits.FinishOffMesh,CanAcquireFromOffNavMesh=traits.AcquireOffMesh,
                SupportsRollingEntry=traits.Rolling,MayLeaveTransitionState=traits.Transition,
                RequiresLandingProof=traits.Landing,ActuatorLeadSeconds=traits.Lead,
                RecentSuccessScore=0.5f,SeedSource=string.Equals(normalized,"Crouch",StringComparison.OrdinalIgnoreCase)
                    ?"postureContractOnWalkThrough":traits.Source
            };
            return profile;
        }

        private static LearningV354TraversalCapabilityProfile GetLearningV354ActionProfile(string kind)
        {
            string normalized = NormalizeLearningV354Kind(kind);
            if (!LearningV354ActionProfiles.TryGetValue(normalized, out LearningV354TraversalCapabilityProfile profile) || profile == null)
            {
                profile = CreateLearningV354SeedProfile(normalized);
                LearningV354ActionProfiles[normalized] = profile;
                learningV354TraversalProfilesDirty = true;
            }
            return profile;
        }

        private static bool HasLearningV372DemonstratedDownhillJumpNativeAuthority(
            LearnedTraversalEdge edge,
            LearnedTraversalCommitment commitment)
        {
            // Exact healthy V3.58 semantic contract, re-ported without the other V3.58 runtime
            // experiments. Negative height alone is weak classification evidence. A deliberate
            // player Jump with settled landing + egress + approach direction/speed is stronger.
            if ((edge == null) || commitment == null ||
                !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                !edge.PlayerValidated || edge.Disabled || !edge.HasSettledEnd ||
                edge.EgressSamples == null || edge.EgressSamples.Count == 0 ||
                edge.TraversalDuration < 0.08f || edge.ApproachSpeed < 0.75f ||
                !IsFinite(commitment.RawEntry) || !IsFinite(commitment.RawExit))
            {
                return false;
            }

            Vector3 jumpDirection = GetFlatDirection(commitment.RawExit - commitment.RawEntry);
            Vector3 approachDirection = GetFlatDirection(edge.ApproachDirection);
            if (jumpDirection.sqrMagnitude < 0.5f || approachDirection.sqrMagnitude < 0.5f ||
                Vector3.Dot(jumpDirection, approachDirection) < 0.35f)
            {
                return false;
            }

            return commitment.RawExit.y - commitment.RawEntry.y <= PlayerJumpDropDownMinVerticalDelta;
        }

        private static bool TryGetLearningV374LearnedActuatorTriggerFrontier(
            LearnedTraversalEdge edge,
            out float minimumForwardProjection,
            out string proofSource)
        {
            minimumForwardProjection = float.NegativeInfinity;
            proofSource = string.Empty;
            if ((edge == null) ||
                edge.Disabled || !IsLearningV3NativeProvenEdge(edge) ||
                edge.NativeSuccessCount <= 0 ||
                edge.NativeVaultParameters == null ||
                edge.MotionSamples == null || edge.MotionSamples.Count < 2 ||
                !IsFinite(edge.RawStart) || !IsFinite(edge.RawEnd))
            {
                return false;
            }

            bool actuatorKind =
                string.Equals(edge.Kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(edge.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
            if (!actuatorKind)
            {
                return false;
            }

            // The successful native recording starts at RawStart. Reuse the existing bounded
            // staging-release envelope as tolerance; do not invent or widen a new site-specific
            // distance. Historical success constrains WHEN the actuator may fire, while the learned
            // obstacle corridor may remain wider for continuous approach.
            minimumForwardProjection = -InjectedNativeVaultEntryStagingReleaseDistance;
            proofSource = "nativeProvenRawStart+motionSamples+nativeVaultParameters";
            return true;
        }

        private static float GetLearningV357ActuatorEntryLateralTolerance(
            LearnedTraversalEdge edge,
            Vector3 traversalDirection,
            float fallback)
        {
            float boundedFallback = Mathf.Max(0.05f, fallback);
            if ((edge?.ObstacleFingerprint == null) ||
                traversalDirection.sqrMagnitude < 0.5f)
            {
                return boundedFallback;
            }

            Vector3 direction = GetFlatDirection(traversalDirection);
            if (direction.sqrMagnitude < 0.5f)
            {
                return boundedFallback;
            }

            Vector3 size = edge.ObstacleFingerprint.BoundsSize;
            if (!IsFinite(size) || size.x <= 0.02f || size.z <= 0.02f)
            {
                return boundedFallback;
            }

            Vector3 perpendicular = new Vector3(-direction.z, 0f, direction.x);
            float obstacleHalfExtent =
                0.5f * (Mathf.Abs(perpendicular.x) * Mathf.Abs(size.x) +
                        Mathf.Abs(perpendicular.z) * Mathf.Abs(size.z));
            // EFT's exposed player controller is not UnityEngine.CharacterController on every build,
            // so keep a conservative body half-width rather than reflecting a map-specific collider.
            // The learned obstacle bounds remain the only source that can widen this lane.
            const float ConservativeFollowerHalfWidth = 0.32f;
            float learnedLane = obstacleHalfExtent - ConservativeFollowerHalfWidth;
            return Mathf.Clamp(
                Mathf.Max(boundedFallback, learnedLane),
                boundedFallback,
                LearningV357ActuatorLaneMaxLateral);
        }

        private static LearningV354TraversalTransitionProfile GetLearningV354TransitionProfile(string fromKind, string toKind)
        {
            string key = MakeLearningV354TransitionKey(fromKind, toKind);
            if (!LearningV354TransitionProfiles.TryGetValue(key, out LearningV354TraversalTransitionProfile profile) || profile == null)
            {
                profile = new LearningV354TraversalTransitionProfile
                {
                    Key = key,
                    FromKind = NormalizeLearningV354Kind(fromKind),
                    ToKind = NormalizeLearningV354Kind(toKind),
                    RecentSuccessScore = 0.5f,
                    LastUpdatedUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture)
                };
                LearningV354TransitionProfiles[key] = profile;
                learningV354TraversalProfilesDirty = true;
            }
            return profile;
        }

        private static void RecordLearningV354TransitionOutcome(string fromKind, string toKind, bool success, bool recoveryTeleport, string reason)
        {
            ;
            LearningV354TraversalTransitionProfile transition = GetLearningV354TransitionProfile(fromKind, toKind);
            transition.Attempts++;
            if (success) transition.SuccessfulDirectHandoffs++;
            else transition.TerminalFailures++;
            if (recoveryTeleport) transition.RecoveryTeleports++;
            transition.RecentSuccessScore = transition.Attempts <= 1
                ? (success ? 1f : 0f)
                : Mathf.Clamp01(Mathf.Lerp(transition.RecentSuccessScore, success ? 1f : 0f, 0.20f));
            transition.LastReason = reason ?? string.Empty;
            transition.LastUpdatedUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            learningV354TraversalProfilesDirty = true;
        }

        private static void RecordLearningV354ActionOutcome(string kind, bool success, bool recoveryTeleport, string reason)
        {
            ;
            LearningV354TraversalCapabilityProfile profile = GetLearningV354ActionProfile(kind);
            profile.Attempts++;
            if (success) profile.Successes++; else profile.Failures++;
            if (recoveryTeleport) profile.RecoveryTeleports++;
            profile.RecentSuccessScore = profile.Attempts <= 1
                ? (success ? 1f : 0f)
                : Mathf.Clamp01(Mathf.Lerp(profile.RecentSuccessScore, success ? 1f : 0f, 0.20f));
            profile.LastReason = reason ?? string.Empty;
            profile.LastUpdatedUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            learningV354TraversalProfilesDirty = true;
        }

        private static void RecordLearningV355ConfirmedJumpActuatorLatency(ProbeRuntime probe, string source)
        {
            if ((probe == null) ||
                probe.LearningV355JumpLatencyRecorded || probe.NativeJumpTriggerAt <= 0f)
            {
                return;
            }
            float latency = Time.time - probe.NativeJumpTriggerAt;
            if (latency <= 0f || latency > 2f) return;
            probe.LearningV355JumpLatencyRecorded = true;
            RecordLearningV354ActuatorLatency("Jump", latency);
            WriteEvent("learningV355ActuatorLatencyObservedAtPhysicalTakeoff", probe.Bot, new
            {
                kind = "Jump", latencySeconds = latency, source = source ?? "unknown",
                physicalTakeoffConfirmed = true
            });
        }

        private static void RecordLearningV354ActuatorLatency(string kind, float latencySeconds)
        {
            if ((latencySeconds <= 0f) || latencySeconds > 2f) return;
            LearningV354TraversalCapabilityProfile profile = GetLearningV354ActionProfile(kind);
            float bounded = string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase)
                ? Mathf.Clamp(latencySeconds, LearningV354JumpActuatorLeadMinSeconds, LearningV354JumpActuatorLeadMaxSeconds)
                : Mathf.Clamp(latencySeconds, 0.02f, 0.75f);
            profile.ActuatorLatencySamples++;
            profile.ActuatorLeadSeconds = profile.ActuatorLatencySamples <= 1 || profile.ActuatorLeadSeconds <= 0f
                ? bounded
                : Mathf.Lerp(profile.ActuatorLeadSeconds, bounded, 0.25f);
            profile.LastUpdatedUtc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            learningV354TraversalProfilesDirty = true;
        }

        private static bool LearningV354CanUseContinuousSuccessor(string fromKind, string toKind, bool successorPreloaded)
        {
            if ((!successorPreloaded)) return successorPreloaded;
            LearningV354TraversalCapabilityProfile from = GetLearningV354ActionProfile(fromKind);
            LearningV354TraversalCapabilityProfile to = GetLearningV354ActionProfile(toKind);
            GetLearningV354TransitionProfile(fromKind, toKind);
            // No pair is whitelisted or blacklisted. Exact successor preload is the producer-order proof.
            // Outcome statistics remain reusable evidence for recovery and diagnostics, never an executor switch.
            return from.SupportsRollingEntry && to.SupportsRollingEntry;
        }

        private static bool LearningV354CanBridgeOffNavMesh(string fromKind, string toKind)
        {
            ;
            LearningV354TraversalCapabilityProfile from = GetLearningV354ActionProfile(fromKind);
            LearningV354TraversalCapabilityProfile to = GetLearningV354ActionProfile(toKind);
            return from.CanFinishOffNavMesh && to.CanAcquireFromOffNavMesh;
        }

        private static bool LearningV354ShouldReleaseInheritedTransition(string fromKind, string toKind)
        {
            ;
            return GetLearningV354ActionProfile(fromKind).MayLeaveTransitionState &&
                   GetLearningV354ActionProfile(toKind).RequiresActuator;
        }

        private static string GetLearningV354TraversalProfilePath()
        {
            string directory = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "BepInEx", "plugins", "BotTraversal", "Data", "Learning");
            Directory.CreateDirectory(directory);
            return Path.Combine(directory, "global.traversalprofiles.json");
        }

        private static void LoadLearningV354TraversalProfileStore()
        {
            ;
            LearningV354ActionProfiles.Clear();
            LearningV354TransitionProfiles.Clear();
            foreach (string seedKind in new[] { "WalkThrough", "PhysicalCorridor", "Jump", "Vault", "Climb", "DropDown", "Crouch" })
            {
                LearningV354TraversalCapabilityProfile seed = CreateLearningV354SeedProfile(seedKind);
                LearningV354ActionProfiles[seed.Kind] = seed;
            }
            string path = GetLearningV354TraversalProfilePath();
            if (File.Exists(path))
            {
                try
                {
                    LearningV354TraversalProfileDatabase db = JsonConvert.DeserializeObject<LearningV354TraversalProfileDatabase>(File.ReadAllText(path));
                    if (db != null && db.SchemaVersion == LearningV354TraversalProfileSchemaVersion)
                    {
                        foreach (LearningV354TraversalCapabilityProfile item in db.Actions ?? new List<LearningV354TraversalCapabilityProfile>())
                        {
                            if (item == null || string.IsNullOrWhiteSpace(item.Kind)) continue;
                            item.RecentSuccessScore = Mathf.Clamp01(item.RecentSuccessScore);
                            LearningV354ActionProfiles[item.Kind] = item;
                        }
                        foreach (LearningV354TraversalTransitionProfile item in db.Transitions ?? new List<LearningV354TraversalTransitionProfile>())
                        {
                            if (item == null || string.IsNullOrWhiteSpace(item.FromKind) || string.IsNullOrWhiteSpace(item.ToKind)) continue;
                            item.Key = MakeLearningV354TransitionKey(item.FromKind, item.ToKind);
                            item.RecentSuccessScore = Mathf.Clamp01(item.RecentSuccessScore);
                            LearningV354TransitionProfiles[item.Key] = item;
                        }
                    }
                }
                catch (Exception ex)
                {
                    LogError("LearningV3.54 traversal profile load failed: " + ex.Message);
                }
            }
            learningV354TraversalProfilesDirty = false;
            WriteEvent("learningV354TraversalProfilesLoaded", null, new
            {
                path,
                actionProfiles = LearningV354ActionProfiles.Count,
                transitionProfiles = LearningV354TransitionProfiles.Count,
                pairSpecificExecutionBranchesEnabled = false
            });
        }

        private static void SaveLearningV354TraversalProfileStore()
        {
            if ((!raidActive) || !learningV354TraversalProfilesDirty) return;
            try
            {
                LearningV354TraversalProfileDatabase db = new LearningV354TraversalProfileDatabase
                {
                    SchemaVersion = LearningV354TraversalProfileSchemaVersion,
                    Actions = LearningV354ActionProfiles.Values.OrderBy(x => x.Kind).ToList(),
                    Transitions = LearningV354TransitionProfiles.Values.OrderBy(x => x.FromKind).ThenBy(x => x.ToKind).ToList()
                };
                string path = GetLearningV354TraversalProfilePath();
                string temp = path + ".tmp";
                File.WriteAllText(temp, JsonConvert.SerializeObject(db, Formatting.Indented));
                if (File.Exists(path)) File.Copy(temp, path, true); else File.Move(temp, path);
                if (File.Exists(temp)) File.Delete(temp);
                learningV354TraversalProfilesDirty = false;
                WriteEvent("learningV354TraversalProfilesSaved", null, new { path, actions = db.Actions.Count, transitions = db.Transitions.Count });
            }
            catch (Exception ex)
            {
                LogError("LearningV3.54 traversal profile save failed: " + ex.Message);
            }
        }

