        private static void LoadLearningV322PersistentSkillEvidenceStore(string mapId)
        {
            if ((string.IsNullOrWhiteSpace(mapId)))
            {
                return;
            }
            try
            {
                string path = GetLearningV322SkillEvidencePath();
                if (!File.Exists(path))
                {
                    WriteEvent("learningV322SkillEvidenceStoreLoaded", null, new
                    {
                        path,
                        loaded = 0,
                        reason = "storeMissing"
                    });
                    return;
                }

                LearningV322PersistentSkillEvidenceDatabase database =
                    JsonConvert.DeserializeObject<LearningV322PersistentSkillEvidenceDatabase>(File.ReadAllText(path));
                if (database == null || database.SchemaVersion != LearningV322SkillEvidenceSchemaVersion || database.Records == null)
                {
                    WriteEvent("learningV322SkillEvidenceStoreIgnored", null, new
                    {
                        path,
                        expectedSchema = LearningV322SkillEvidenceSchemaVersion,
                        actualSchema = database?.SchemaVersion ?? -1
                    });
                    return;
                }

                int loaded = 0;
                foreach (LearningV322PersistentSkillEvidenceRecord item in database.Records)
                {
                    if (item == null || string.IsNullOrWhiteSpace(item.ExperienceKey) || string.IsNullOrWhiteSpace(item.Kind))
                    {
                        continue;
                    }
                    item.NativeAttempts = Math.Max(0, item.NativeAttempts);
                    item.NativeSuccesses = Math.Max(0, item.NativeSuccesses);
                    item.NativeFailures = Math.Max(0, item.NativeFailures);
                    item.ConsecutiveNativeFailures = Math.Max(0, item.ConsecutiveNativeFailures);
                    item.AssistedAttempts = Math.Max(0, item.AssistedAttempts);
                    item.AssistedPhysicalCompletions = Math.Max(0, item.AssistedPhysicalCompletions);
                    item.TeleportRescues = Math.Max(0, item.TeleportRescues);
                    item.ZeroShotAttempts = Math.Max(0, item.ZeroShotAttempts);
                    item.ZeroShotNativeSuccesses = Math.Max(0, item.ZeroShotNativeSuccesses);
                    item.ZeroShotAssistSalvages = Math.Max(0, item.ZeroShotAssistSalvages);
                    item.ZeroShotTeleportRescues = Math.Max(0, item.ZeroShotTeleportRescues);
                    item.ZeroShotFailures = Math.Max(0, item.ZeroShotFailures);
                    item.FollowOutcomeAttempts = Math.Max(0, item.FollowOutcomeAttempts);
                    item.FollowMovementResumedSuccesses = Math.Max(0, item.FollowMovementResumedSuccesses);
                    item.FormationRecoveredSuccesses = Math.Max(0, item.FormationRecoveredSuccesses);
                    item.FollowResumeFailures = Math.Max(0, item.FollowResumeFailures);
                    item.NativeJumpRunTakeoffSuccesses = Math.Max(0, item.NativeJumpRunTakeoffSuccesses);
                    item.NativeJumpRunMinSuccessfulTakeoffSpeed = Mathf.Max(0f, item.NativeJumpRunMinSuccessfulTakeoffSpeed);
                    item.NativeJumpSprintTakeoffSuccesses = Math.Max(0, item.NativeJumpSprintTakeoffSuccesses);
                    item.NativeJumpSprintMinSuccessfulTakeoffSpeed = Mathf.Max(0f, item.NativeJumpSprintMinSuccessfulTakeoffSpeed);
                    item.PlayerJumpRunDemonstrations = Math.Max(0, item.PlayerJumpRunDemonstrations);
                    item.PlayerJumpRunMinObservedTakeoffSpeed = Mathf.Max(0f, item.PlayerJumpRunMinObservedTakeoffSpeed);
                    item.PlayerJumpRunTrialAttempts = Math.Max(0, item.PlayerJumpRunTrialAttempts);
                    item.PlayerJumpRunTrialFailures = Math.Max(0, item.PlayerJumpRunTrialFailures);
                    item.PlayerJumpSprintDemonstrations = Math.Max(0, item.PlayerJumpSprintDemonstrations);
                    item.PlayerJumpSprintMinObservedTakeoffSpeed = Mathf.Max(0f, item.PlayerJumpSprintMinObservedTakeoffSpeed);
                    // V430 additive generalized chronology evidence. Older schema-v1 files simply
                    // deserialize these optional fields as zero, so no migration or geometry rewrite
                    // is required. They are observational counters only; they never mint success.
                    item.MonotonicPhysicalChronologyPromotions = Math.Max(0, item.MonotonicPhysicalChronologyPromotions);
                    item.HistoricalEntryReacquireRejects = Math.Max(0, item.HistoricalEntryReacquireRejects);
                    item.StaleUpstreamConsumerRetirements = Math.Max(0, item.StaleUpstreamConsumerRetirements);
                    item.DeferredConsumerGenerationRollovers = Math.Max(0, item.DeferredConsumerGenerationRollovers);
                    item.LiveReservationAdmissionEscalations = Math.Max(0, item.LiveReservationAdmissionEscalations);
                    item.EquivalentPhysicalActuatorSubstitutions = Math.Max(0, item.EquivalentPhysicalActuatorSubstitutions);
                    item.FailedPhysicalActuatorEpochCommits = Math.Max(0, item.FailedPhysicalActuatorEpochCommits);
                    item.MonotonicWalkThroughConsumerRetirements = Math.Max(0, item.MonotonicWalkThroughConsumerRetirements);
                    item.RecentNativeSuccessScore = Mathf.Clamp01(item.RecentNativeSuccessScore);
                    LearningV322SkillEvidence[item.ExperienceKey] = item;
                    loaded++;
                }
                WriteEvent("learningV322SkillEvidenceStoreLoaded", null, new
                {
                    path,
                    loaded,
                    schemaVersion = database.SchemaVersion,
                    geometryAuthority = false,
                    selectionAuthority = "boundedToxicSuppressionOnly"
                });
            }
            catch (Exception ex)
            {
                LogError("LearningV3.22 skill-evidence store load failed: " + ex.Message);
            }
        }

        private static void SaveLearningV322PersistentSkillEvidenceStore()
        {
            if ((!raidActive) || string.IsNullOrWhiteSpace(locationId))
            {
                return;
            }
            try
            {
                LearningV322PersistentSkillEvidenceDatabase database = new LearningV322PersistentSkillEvidenceDatabase
                {
                    SchemaVersion = LearningV322SkillEvidenceSchemaVersion,
                    Records = LearningV322SkillEvidence.Values
                        .Where(record => record != null && !string.IsNullOrWhiteSpace(record.ExperienceKey))
                        .OrderBy(record => record.Kind)
                        .ThenBy(record => record.ExperienceKey)
                        .ToList()
                };
                string path = GetLearningV322SkillEvidencePath();
                string tempPath = path + ".tmp";
                string backupPath = path + ".replace.bak";
                File.WriteAllText(tempPath, JsonConvert.SerializeObject(database, Formatting.Indented));
                bool atomicReplace = false;
                if (File.Exists(path))
                {
                    try
                    {
                        if (File.Exists(backupPath))
                        {
                            File.Delete(backupPath);
                        }
                        File.Replace(tempPath, path, backupPath, true);
                        atomicReplace = true;
                        if (File.Exists(backupPath))
                        {
                            File.Delete(backupPath);
                        }
                    }
                    catch
                    {
                        // Compatibility fallback only: keep the temp-write discipline even on a
                        // filesystem/runtime where File.Replace is unavailable. The next save will
                        // retry the atomic path.
                        File.Copy(tempPath, path, true);
                        File.Delete(tempPath);
                    }
                }
                else
                {
                    File.Move(tempPath, path);
                    atomicReplace = true;
                }
                learningV322SkillEvidenceDirty = false;
                nextLearningV322SkillEvidenceSaveAt = Time.time + LearningV322SkillEvidenceSaveIntervalSeconds;
                WriteEvent("learningV322SkillEvidenceStoreSaved", null, new
                {
                    path,
                    records = database.Records.Count,
                    schemaVersion = database.SchemaVersion,
                    atomicReplace,
                    nativeProvenGeometryMutated = false
                });
            }
            catch (Exception ex)
            {
                LogError("LearningV3.22 skill-evidence store save failed: " + ex.Message);
            }
        }

        private static LearningV322PersistentSkillEvidenceRecord GetOrCreateLearningV322SkillEvidence(LearnedTraversalEdge edge)
        {
            if ((edge == null) || string.IsNullOrWhiteSpace(edge.ExperienceKey))
            {
                return null;
            }
            if (!LearningV322SkillEvidence.TryGetValue(edge.ExperienceKey, out LearningV322PersistentSkillEvidenceRecord record) || record == null)
            {
                record = new LearningV322PersistentSkillEvidenceRecord
                {
                    ExperienceKey = edge.ExperienceKey,
                    Kind = edge.Kind,
                    LastPolicyVersion = TraversalExperiencePolicyVersion,
                    RecentNativeSuccessScore = 0.5f
                };
                LearningV322SkillEvidence[edge.ExperienceKey] = record;
            }
            if (string.IsNullOrWhiteSpace(record.Kind))
            {
                record.Kind = edge.Kind;
            }
            return record;
        }

        // V430 stores generalized consumer-chronology repairs in the existing per-ExperienceKey
        // skill-evidence database. These counters are intentionally non-authoritative: future policy
        // can learn which portal/consumer lifetimes are prone to stale rewind, while current success,
        // geometry, admission and capability scores remain untouched.
        private static bool RecordLearningV430MonotonicConsumerEvidence(
            int edgeId,
            string evidenceKind,
            string source)
        {
            if ((edgeId <= 0) ||
                string.IsNullOrWhiteSpace(evidenceKind))
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == edgeId);
            LearningV322PersistentSkillEvidenceRecord record =
                GetOrCreateLearningV322SkillEvidence(edge);
            if (record == null)
            {
                return false;
            }

            switch (evidenceKind)
            {
                case "physicalChronologyPromotion":
                    record.MonotonicPhysicalChronologyPromotions++;
                    break;
                case "historicalEntryReacquireRejected":
                    record.HistoricalEntryReacquireRejects++;
                    break;
                case "staleUpstreamConsumerRetired":
                    record.StaleUpstreamConsumerRetirements++;
                    break;
                case "deferredConsumerGenerationRollover":
                    record.DeferredConsumerGenerationRollovers++;
                    break;
                default:
                    return false;
            }

            record.LastPolicyVersion = TraversalExperiencePolicyVersion;
            record.LastReason = "learningV430:" + evidenceKind + ":" + (source ?? string.Empty);
            record.LastUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            learningV322SkillEvidenceDirty = true;
            return true;
        }

