        private static void RecordLearningV418PlayerJumpApproachEvidence(
            LearnedTraversalEdge edge,
            string approachMode,
            float approachSpeed,
            string source)
        {
            if ((edge == null) ||
                !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                string.IsNullOrWhiteSpace(edge.ExperienceKey) || !IsFinite(approachSpeed) ||
                approachSpeed <= 0f)
            {
                return;
            }

            LearningV322PersistentSkillEvidenceRecord record = GetOrCreateLearningV322SkillEvidence(edge);
            if (record == null)
            {
                return;
            }

            bool changed = false;
            if (string.Equals(approachMode, "Run", StringComparison.OrdinalIgnoreCase))
            {
                record.PlayerJumpRunDemonstrations++;
                record.PlayerJumpRunMinObservedTakeoffSpeed =
                    record.PlayerJumpRunMinObservedTakeoffSpeed <= 0f
                        ? approachSpeed
                        : Mathf.Min(record.PlayerJumpRunMinObservedTakeoffSpeed, approachSpeed);
                changed = true;
            }
            else if (string.Equals(approachMode, "Sprint", StringComparison.OrdinalIgnoreCase))
            {
                record.PlayerJumpSprintDemonstrations++;
                record.PlayerJumpSprintMinObservedTakeoffSpeed =
                    record.PlayerJumpSprintMinObservedTakeoffSpeed <= 0f
                        ? approachSpeed
                        : Mathf.Min(record.PlayerJumpSprintMinObservedTakeoffSpeed, approachSpeed);
                changed = true;
            }

            if (!changed)
            {
                return;
            }

            record.LastPolicyVersion = TraversalExperiencePolicyVersion;
            learningV322SkillEvidenceDirty = true;
            WriteEvent("learningV418PlayerJumpApproachCapabilityEvidenceRecorded", null, new
            {
                edgeId = edge.Id,
                experienceKey = edge.ExperienceKey,
                approachMode = approachMode ?? string.Empty,
                approachSpeed,
                runDemonstrations = record.PlayerJumpRunDemonstrations,
                runMinObservedTakeoffSpeed = record.PlayerJumpRunMinObservedTakeoffSpeed,
                runTrialAttempts = record.PlayerJumpRunTrialAttempts,
                runTrialFailures = record.PlayerJumpRunTrialFailures,
                runTrialsAvailable = Math.Max(0, record.PlayerJumpRunDemonstrations - record.PlayerJumpRunTrialAttempts),
                sprintDemonstrations = record.PlayerJumpSprintDemonstrations,
                sprintMinObservedTakeoffSpeed = record.PlayerJumpSprintMinObservedTakeoffSpeed,
                source = source ?? string.Empty,
                followerNativeSuccessCreditChanged = false,
                persistentGeometryChanged = false,
                action = "playerProofAuthorizesBoundedSamePortalModeTrialNeverMintsFollowerCapability"
            });
        }

        private static string ClassifyLearningV322FailureStage(ProbeRuntime probe, string reason)
        {
            string text = reason ?? string.Empty;
            if (probe?.NativeLandingRejected == true ||
                text.IndexOf("landing", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("farSide", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Landing";
            }
            if (text.IndexOf("entry", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("align", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("approach", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "EntryAcquisition";
            }
            if (text.IndexOf("topology", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("downstream", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("island", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("rejoin", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "TopologyRejoin";
            }
            if ((probe != null && string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                 probe.JumpAttempted && !HasNativeJumpPhysicalTakeoffEvidence(probe, out _, out _)) ||
                text.IndexOf("actuator", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("state transition", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("TryJump", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Actuator";
            }
            return "Executor";
        }

        private static void ApplyLearningV322FailureStage(LearningV322PersistentSkillEvidenceRecord record, string stage)
        {
            if (record == null)
            {
                return;
            }
            switch (stage ?? string.Empty)
            {
                case "EntryAcquisition": record.EntryAcquisitionFailures++; break;
                case "Actuator": record.ActuatorFailures++; break;
                case "Landing": record.LandingFailures++; break;
                case "TopologyRejoin": record.TopologyRejoinFailures++; break;
                default: record.ExecutorFailures++; break;
            }
        }

        private static void RecordLearningV322PersistentSkillEvidence(
            ProbeRuntime probe,
            LearnedTraversalEdge edge,
            bool success,
            TraversalCompletionMode completionMode,
            string reason)
        {
            if ((probe == null) || edge == null || probe.LearningV322BaseEvidenceRecorded)
            {
                return;
            }
            LearningV322PersistentSkillEvidenceRecord record = GetOrCreateLearningV322SkillEvidence(edge);
            if (record == null)
            {
                return;
            }
            probe.LearningV322BaseEvidenceRecorded = true;
            bool nativeAttempted = (WasLearningV330NativeActuatorActuallyAttempted(probe));
            bool assistedAttempted = probe.AssistedStrategySelected || probe.AssistedReplayAttempted;
            bool teleportUsed = probe.TraversalTeleportAttempted || probe.TeleportFallbackUsed ||
                                completionMode == TraversalCompletionMode.TeleportFallback;
            bool nativeSuccess = success && IsLearningV3RetainableNativeSuccess(probe, completionMode);
            string classifiedFailureStage = !success
                ? ClassifyLearningV322FailureStage(probe, reason)
                : string.Empty;
            bool preExecutionInfrastructureFailure =
                (!success) &&
                !probe.JumpAttempted &&
                !probe.NativeDropDownAttempted &&
                !probe.InjectedNativeVaultAttempted &&
                !probe.NativeTraversalStarted &&
                ((string.Equals(classifiedFailureStage, "EntryAcquisition", StringComparison.Ordinal) &&
                  probe.LearningV32NativeExecutionEpochStartedAt < 0f) ||
                 (string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                  (reason ?? string.Empty).IndexOf("learningV329PreActuatorJumpMomentumFailure", StringComparison.OrdinalIgnoreCase) >= 0));
            bool postLandingMovementAuthorityFailure =
                (!success) && probe.JumpAttempted &&
                string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                probe.LearningV332PostLandingMovementAuthorityFailure &&
                (reason ?? string.Empty).IndexOf("learningV331NativeJumpForwardContinuationFailed", StringComparison.OrdinalIgnoreCase) >= 0;
            if (preExecutionInfrastructureFailure || postLandingMovementAuthorityFailure)
            {
                record.LastFailureStage = classifiedFailureStage;
                ApplyLearningV322FailureStage(record, classifiedFailureStage);
                WriteEvent(postLandingMovementAuthorityFailure
                        ? "learningV332PostLandingMovementAuthorityFailureIsolatedFromNativeReliability"
                        : "learningV329PreExecutionFailureIsolatedFromNativeReliability",
                    probe.Bot, new
                    {
                        edgeId = edge.Id,
                        kind = edge.Kind,
                        reason = reason ?? string.Empty,
                        failureStage = classifiedFailureStage,
                        nativeAttemptCounterUnchanged = true,
                        nativeFailureCounterUnchanged = true,
                        authority = postLandingMovementAuthorityFailure
                            ? "postLandingMovementOrNavMeshAuthority"
                            : "preExecutionInfrastructure"
                    });
            }
            else if (nativeAttempted)
            {
                record.NativeAttempts++;
                if (nativeSuccess)
                {
                    record.NativeSuccesses++;
                    record.ConsecutiveNativeFailures = 0;
                    record.RecentNativeSuccessScore = record.NativeAttempts <= 1
                        ? 1f
                        : Mathf.Clamp01(Mathf.Lerp(record.RecentNativeSuccessScore, 1f, 0.25f));
                    if ((string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase)) &&
                        probe.LearningV414JumpTakeoffCapabilityCaptured &&
                        probe.LearningV414JumpTakeoffPlanarSpeed > 0f)
                    {
                        float successfulTakeoffSpeed = probe.LearningV414JumpTakeoffPlanarSpeed;
                        if (probe.LearningV414JumpTakeoffState == EPlayerState.Run)
                        {
                            record.NativeJumpRunTakeoffSuccesses++;
                            record.NativeJumpRunMinSuccessfulTakeoffSpeed =
                                record.NativeJumpRunMinSuccessfulTakeoffSpeed <= 0f
                                    ? successfulTakeoffSpeed
                                    : Mathf.Min(record.NativeJumpRunMinSuccessfulTakeoffSpeed, successfulTakeoffSpeed);
                        }
                        else if (probe.LearningV414JumpTakeoffState == EPlayerState.Sprint)
                        {
                            record.NativeJumpSprintTakeoffSuccesses++;
                            record.NativeJumpSprintMinSuccessfulTakeoffSpeed =
                                record.NativeJumpSprintMinSuccessfulTakeoffSpeed <= 0f
                                    ? successfulTakeoffSpeed
                                    : Mathf.Min(record.NativeJumpSprintMinSuccessfulTakeoffSpeed, successfulTakeoffSpeed);
                        }
                        learningV322SkillEvidenceDirty = true;
                        WriteEvent("learningV414FollowerJumpTakeoffCapabilityLearned", probe.Bot, new
                        {
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            takeoffState = probe.LearningV414JumpTakeoffState.ToString(),
                            successfulTakeoffSpeed,
                            runSuccesses = record.NativeJumpRunTakeoffSuccesses,
                            runMinSuccessfulSpeed = record.NativeJumpRunMinSuccessfulTakeoffSpeed,
                            sprintSuccesses = record.NativeJumpSprintTakeoffSuccesses,
                            sprintMinSuccessfulSpeed = record.NativeJumpSprintMinSuccessfulTakeoffSpeed,
                            action = "persistFollowerLocalObstacleClearingCapabilityWithoutPlayerSpeedThreshold"
                        });
                    }
                }
                else
                {
                    record.NativeFailures++;
                    record.ConsecutiveNativeFailures++;
                    if ((probe.LearningV418PlayerRunTrialConsumed) &&
                        string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
                    {
                        record.PlayerJumpRunTrialFailures++;
                        learningV322SkillEvidenceDirty = true;
                        WriteEvent("learningV418PlayerProvenRunJumpTrialFailed", probe.Bot, new
                        {
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            trialAttempt = probe.LearningV418PlayerRunTrialOrdinal,
                            demonstrationCount = probe.LearningV418PlayerRunTrialDemonstrationCount,
                            trialFailures = record.PlayerJumpRunTrialFailures,
                            reason = reason ?? string.Empty,
                            failureStage = classifiedFailureStage,
                            followerRunCapabilityPromoted = false,
                            action = "closeRunTrialReturnToExistingSiblingSelfRescueUntilFreshPlayerProof"
                        });
                    }
                    record.RecentNativeSuccessScore = record.NativeAttempts <= 1
                        ? 0f
                        : Mathf.Clamp01(Mathf.Lerp(record.RecentNativeSuccessScore, 0f, 0.25f));
                    record.LastFailureStage = classifiedFailureStage;
                    ApplyLearningV322FailureStage(record, classifiedFailureStage);
                    bool correctedNativeJumpFailure =
                        (string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase)) &&
                        IsLearningV3NativeProvenEdge(edge) &&
                        probe.LearningV32NativeExecutionEpochStartedAt >= 0f &&
                        probe.JumpAttempted &&
                        (string.Equals(classifiedFailureStage, "Actuator", StringComparison.Ordinal) ||
                         string.Equals(classifiedFailureStage, "Landing", StringComparison.Ordinal));
                    if (correctedNativeJumpFailure &&
                        LearningV329CorrectedNativeJumpFailureObservedEdges.Add(edge.Id))
                    {
                        WriteEvent("learningV329CorrectedNativeJumpFailureObserved", probe.Bot, new
                        {
                            edgeId = edge.Id,
                            reason = reason ?? string.Empty,
                            failureStage = classifiedFailureStage,
                            action = "legacyAssistPreferenceMayReenterOnFutureAttempt"
                        });
                    }
                }
            }
            if (assistedAttempted)
            {
                record.AssistedAttempts++;
                if (success && completionMode == TraversalCompletionMode.AssistedReplay)
                {
                    record.AssistedPhysicalCompletions++;
                }
            }
            if (teleportUsed && success)
            {
                record.TeleportRescues++;
            }
            record.LastPolicyVersion = TraversalExperiencePolicyVersion;
            record.LastOutcome = nativeSuccess ? "NativeSuccess" :
                (success ? completionMode.ToString() : "Failure");
            record.LastReason = reason ?? string.Empty;
            record.LastUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            learningV322SkillEvidenceDirty = true;
            WriteEvent("learningV322PersistentSkillEvidenceUpdated", probe.Bot, new
            {
                attemptId = probe.LearningV322AttemptId,
                edgeId = edge.Id,
                experienceKey = edge.ExperienceKey,
                kind = edge.Kind,
                nativeAttempted,
                nativeSuccess,
                nativeAttempts = record.NativeAttempts,
                nativeSuccesses = record.NativeSuccesses,
                nativeFailures = record.NativeFailures,
                consecutiveNativeFailures = record.ConsecutiveNativeFailures,
                assistedAttempted,
                assistedPhysicalCompletions = record.AssistedPhysicalCompletions,
                teleportRescues = record.TeleportRescues,
                recentNativeSuccessScore = record.RecentNativeSuccessScore,
                failureStage = record.LastFailureStage ?? string.Empty,
                nativeProvenGeometryMutated = false
            });
        }

        private static void RecordLearningV322ZeroShotTemplateEvidence(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            bool success,
            TraversalCompletionMode completionMode,
            string reason)
        {
            if ((probe == null) || commitment == null ||
                !IsLearningV319TransientSkillTransfer(commitment) || probe.LearningV322ZeroShotEvidenceRecorded)
            {
                return;
            }
            int templateEdgeId = commitment.SkillTemplateEdgeId > 0 ? commitment.SkillTemplateEdgeId : commitment.EdgeId;
            LearnedTraversalEdge template = LearnedTraversalEdges.FirstOrDefault(edge =>
                edge != null && edge.Id == templateEdgeId && IsLearningV3NativeProvenEdge(edge));
            LearningV322PersistentSkillEvidenceRecord record = GetOrCreateLearningV322SkillEvidence(template);
            if (record == null)
            {
                return;
            }
            probe.LearningV322ZeroShotEvidenceRecorded = true;
            bool nativeSuccess = success && IsLearningV3RetainableNativeSuccess(probe, completionMode);
            record.ZeroShotAttempts++;
            if (nativeSuccess)
            {
                record.ZeroShotNativeSuccesses++;
            }
            else if (success && completionMode == TraversalCompletionMode.AssistedReplay)
            {
                record.ZeroShotAssistSalvages++;
            }
            else if (success && completionMode == TraversalCompletionMode.TeleportFallback)
            {
                record.ZeroShotTeleportRescues++;
            }
            else
            {
                record.ZeroShotFailures++;
            }
            record.LastPolicyVersion = TraversalExperiencePolicyVersion;
            record.LastOutcome = nativeSuccess ? "ZeroShotNativeSuccess" :
                (success ? "ZeroShot" + completionMode : "ZeroShotFailure");
            record.LastReason = reason ?? string.Empty;
            record.LastUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            learningV322SkillEvidenceDirty = true;
            WriteEvent("learningV322ZeroShotTemplateEvidenceUpdated", probe.Bot, new
            {
                attemptId = probe.LearningV322AttemptId,
                parentAttemptId = probe.LearningV322ParentAttemptId,
                templateEdgeId,
                experienceKey = template?.ExperienceKey,
                kind = commitment.Kind,
                success,
                completionMode = completionMode.ToString(),
                zeroShotAttempts = record.ZeroShotAttempts,
                zeroShotNativeSuccesses = record.ZeroShotNativeSuccesses,
                zeroShotAssistSalvages = record.ZeroShotAssistSalvages,
                zeroShotTeleportRescues = record.ZeroShotTeleportRescues,
                zeroShotFailures = record.ZeroShotFailures,
                templateGeometryMutated = false,
                reason = reason ?? string.Empty
            });
        }

        private static void RecordLearningV322FollowEvidence(
            LearnedTraversalEdge edge,
            bool movementResumed,
            bool formationRecovered,
            string reason)
        {
            LearningV322PersistentSkillEvidenceRecord record = GetOrCreateLearningV322SkillEvidence(edge);
            if (record == null)
            {
                return;
            }
            record.FollowOutcomeAttempts++;
            if (movementResumed) record.FollowMovementResumedSuccesses++;
            if (formationRecovered) record.FormationRecoveredSuccesses++;
            if (!movementResumed) record.FollowResumeFailures++;
            record.LastUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            if (!string.IsNullOrWhiteSpace(reason)) record.LastReason = reason;
            learningV322SkillEvidenceDirty = true;
        }

        private static bool ShouldSuppressLearningV322PersistentEvidence(LearnedTraversalEdge edge, out string reason)
        {
            reason = string.Empty;
            if ((edge == null) || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !LearningV322SkillEvidence.TryGetValue(edge.ExperienceKey, out LearningV322PersistentSkillEvidenceRecord record) ||
                record == null)
            {
                return false;
            }
            bool enoughNativeEvidence = record.NativeAttempts >= LearningV322PersistentSuppressionMinNativeAttempts;
            bool enoughFollowEvidence = record.FollowOutcomeAttempts >= LearningV322PersistentFollowSuppressionMinAttempts;
            if (!enoughNativeEvidence && !enoughFollowEvidence)
            {
                return false;
            }
            float nativeRate = record.NativeSuccesses / (float)Math.Max(1, record.NativeAttempts);
            bool nativeToxic = enoughNativeEvidence &&
                               record.ConsecutiveNativeFailures >= LearningV322PersistentSuppressionMinConsecutiveNativeFailures &&
                               nativeRate <= LearningV322PersistentSuppressionMaxNativeRate;
            float followResumeRate = record.FollowMovementResumedSuccesses /
                                     (float)Math.Max(1, record.FollowOutcomeAttempts);
            bool followToxic = FollowerCapabilityHelperRules.ShouldSuppressLearningV322PersistentEvidence_followToxic_BE16881B_1(record.FollowOutcomeAttempts,LearningV322PersistentFollowSuppressionMinAttempts,record.FollowResumeFailures,LearningV322PersistentFollowSuppressionMinFailures,followResumeRate,LearningV322PersistentFollowSuppressionMaxResumeRate);
            bool continuationOnlyToxic = followToxic && !nativeToxic;
            bool toxic = FollowerCapabilityHelperRules.ShouldSuppressLearningV322PersistentEvidence_toxic_BE16881B_2(nativeToxic,followToxic);
            if (!toxic)
            {
                // V3.56 keeps follow/formation quality as continuation evidence, but it no longer
                // vetoes a physically usable crossing. A portal that crosses cleanly and resumes
                // poorly needs a safer downstream handoff, not deletion of the crossing itself.
                LearningV322PersistentEvidenceSuppressUntil.Remove(edge.Id);
                LearningV322PersistentEvidenceRevalidationUntil.Remove(edge.Id);
                if ((continuationOnlyToxic))
                {
                    reason = $"learningV356ContinuationOnly:native={record.NativeSuccesses}/{record.NativeAttempts}:" +
                             $"followResume={record.FollowMovementResumedSuccesses}/{record.FollowOutcomeAttempts}:" +
                             $"followFailures={record.FollowResumeFailures}";
                }
                return false;
            }

            if (LearningV322PersistentEvidenceRevalidationUntil.TryGetValue(edge.Id, out float revalidationUntil))
            {
                if (Time.time < revalidationUntil)
                {
                    reason = $"learningV322PersistentEvidenceRevalidation={Mathf.Max(0f, revalidationUntil - Time.time):0.0}s";
                    return false;
                }
                LearningV322PersistentEvidenceRevalidationUntil.Remove(edge.Id);
            }
            if (LearningV322PersistentEvidenceSuppressUntil.TryGetValue(edge.Id, out float suppressUntil))
            {
                if (Time.time < suppressUntil)
                {
                    reason = $"learningV322PersistentEvidenceCooldown={Mathf.Max(0f, suppressUntil - Time.time):0.0}s:" +
                             $"native={record.NativeSuccesses}/{record.NativeAttempts}:rate={nativeRate:0.00}";
                    return true;
                }
                LearningV322PersistentEvidenceSuppressUntil.Remove(edge.Id);
                LearningV322PersistentEvidenceRevalidationUntil[edge.Id] = Time.time + TraversalExperienceRevalidationLeaseSeconds;
                reason = "learningV322PersistentEvidenceBoundedRevalidation";
                return false;
            }

            LearningV322PersistentEvidenceSuppressUntil[edge.Id] = Time.time + TraversalExperienceSuppressSeconds;
            reason = $"learningV322PersistentEvidence:native={record.NativeSuccesses}/{record.NativeAttempts}:" +
                     $"consecutiveFailures={record.ConsecutiveNativeFailures}:rate={nativeRate:0.00}:" +
                     $"followResume={record.FollowMovementResumedSuccesses}/{record.FollowOutcomeAttempts}:" +
                     $"followFailures={record.FollowResumeFailures}:cooldown={TraversalExperienceSuppressSeconds:0}s";
            return true;
        }

        private static bool IsLearningV322ZeroShotTemplateEligible(LearnedTraversalEdge edge, out string reason)
        {
            reason = string.Empty;
            if ((edge == null) || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !LearningV322SkillEvidence.TryGetValue(edge.ExperienceKey, out LearningV322PersistentSkillEvidenceRecord record) ||
                record == null || record.ZeroShotAttempts < LearningV322GeneralizationSuppressionMinAttempts)
            {
                return true;
            }
            float nativeRate = record.ZeroShotNativeSuccesses / (float)Math.Max(1, record.ZeroShotAttempts);
            bool unreliable = nativeRate <= LearningV322GeneralizationSuppressionMaxNativeRate &&
                              FollowerCapabilityHelperRules.IsLearningV322ZeroShotTemplateEligible_unreliable_C30313EF_1(record.ZeroShotFailures,record.ZeroShotAssistSalvages,record.ZeroShotTeleportRescues,LearningV322GeneralizationSuppressionMinAttempts);
            if (!unreliable)
            {
                LearningV322ZeroShotEvidenceSuppressUntil.Remove(edge.Id);
                LearningV322ZeroShotEvidenceRevalidationUntil.Remove(edge.Id);
                return true;
            }

            if (LearningV322ZeroShotEvidenceRevalidationUntil.TryGetValue(edge.Id, out float revalidationUntil))
            {
                if (Time.time < revalidationUntil)
                {
                    reason = $"zeroShotBoundedRevalidation={Mathf.Max(0f, revalidationUntil - Time.time):0.0}s";
                    return true;
                }
                LearningV322ZeroShotEvidenceRevalidationUntil.Remove(edge.Id);
            }
            if (LearningV322ZeroShotEvidenceSuppressUntil.TryGetValue(edge.Id, out float suppressUntil))
            {
                if (Time.time < suppressUntil)
                {
                    reason = $"zeroShotEvidenceCooldown={Mathf.Max(0f, suppressUntil - Time.time):0.0}s:" +
                             $"native={record.ZeroShotNativeSuccesses}/{record.ZeroShotAttempts}:rate={nativeRate:0.00}";
                    return false;
                }
                LearningV322ZeroShotEvidenceSuppressUntil.Remove(edge.Id);
                LearningV322ZeroShotEvidenceRevalidationUntil[edge.Id] = Time.time + TraversalExperienceRevalidationLeaseSeconds;
                reason = "zeroShotPersistentEvidenceBoundedRevalidation";
                return true;
            }

            LearningV322ZeroShotEvidenceSuppressUntil[edge.Id] = Time.time + TraversalExperienceSuppressSeconds;
            reason = $"zeroShotNative={record.ZeroShotNativeSuccesses}/{record.ZeroShotAttempts}:rate={nativeRate:0.00}:" +
                     $"cooldown={TraversalExperienceSuppressSeconds:0}s";
            return false;
        }

        private static void EmitLearningV322TraversalAttemptSummary(
            ProbeRuntime probe,
            bool success,
            TraversalCompletionMode completionMode,
            string reason,
            int effectiveEdgeId = 0)
        {
            if ((probe == null) || probe.LearningV322AttemptSummaryEmitted)
            {
                return;
            }
            if (success && !IsProbeLifecycleCurrent(probe,true)) success=false;
            probe.LearningV322AttemptSummaryEmitted = true;
            LearnedTraversalCommitment commitment = probe.FrozenTraversalCommitment;
            bool zeroShot = IsLearningV319TransientSkillTransfer(commitment);
            bool nativeAttempted = (WasLearningV330NativeActuatorActuallyAttempted(probe));
            bool forcedEgressUsed = (probe.LearningV341ForcedEgressPhysicalWriterUsed);
            bool nativePhysicalSuccess = success && IsLearningV3RetainableNativeSuccess(probe, completionMode) && !forcedEgressUsed;
            bool teleportUsed = probe.TraversalTeleportAttempted || probe.TeleportFallbackUsed ||
                                completionMode == TraversalCompletionMode.TeleportFallback;
            bool assistLikeCompletion = completionMode == TraversalCompletionMode.AssistedReplay || forcedEgressUsed;
            bool cleanSuccess = success && !assistLikeCompletion && !teleportUsed &&
                                !probe.RecoveryExitAlreadySatisfied && !probe.NativeLandingRejected;
            // RC39: diagnostic truth is classified from the already-existing evidence,
            // never from a mission cursor, animation, body chronology or success alone.
            FollowerMovementV2IntentGateway.TraversalExecutionTruth executionTruth =
                FollowerMovementV2IntentGateway.ClassifyTraversalExecutionTruth(
                    success, nativePhysicalSuccess, teleportUsed);
            WriteEvent("learningV322TraversalAttemptSummary", probe.Bot, new
            {
                attemptId = probe.LearningV322AttemptId,
                parentAttemptId = probe.LearningV322ParentAttemptId,
                edgeId = effectiveEdgeId > 0 ? effectiveEdgeId : probe.LearnedEdgeId,
                templateEdgeId = zeroShot ? commitment.SkillTemplateEdgeId : 0,
                kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                requestSource = probe.RequestSource ?? string.Empty,
                selectedExecutor = probe.NativeStrategySelected ? "Native" :
                    (probe.AssistedStrategySelected ? "Assist" : "Auto"),
                actualExecutor = forcedEgressUsed ? "Native+ForcedEgress" :
                    (completionMode == TraversalCompletionMode.Native ? "Native" :
                     (completionMode == TraversalCompletionMode.AssistedReplay ? "Assist" :
                      (completionMode == TraversalCompletionMode.TeleportFallback ? "Teleport" : completionMode.ToString()))),
                nativeAttempted,
                assistedAttempted = probe.AssistedStrategySelected || probe.AssistedReplayAttempted || forcedEgressUsed,
                teleportUsed,
                nativeActuatorTriggered = (WasLearningV330NativeActuatorActuallyAttempted(probe)),
                physicalCrossing = probe.LearningV349PhysicalPassageCrossed ||
                                   (success && completionMode != TraversalCompletionMode.TeleportFallback),
                assistedPhysicalCompletion = success && assistLikeCompletion,
                teleportRescue = success && completionMode == TraversalCompletionMode.TeleportFallback,
                forcedEgressUsed,
                forcedEgressDistance = probe.UnifiedEgressForcedDistance,
                cleanSuccess,
                stableExit = success,
                topologyRejoined = probe.ExitAuthorityTopologyRejoinConfirmed || probe.ExitAuthorityActionableTopologyCandidate,
                zeroShot,
                nativePhysicalSuccess,
                executionTruth = executionTruth.ToString(),
                completionMode = forcedEgressUsed ? "NativeForcedEgress" : completionMode.ToString(),
                success,
                failureStage = success ? string.Empty : ClassifyLearningV322FailureStage(probe, reason),
                reason = reason ?? string.Empty,
                elapsed = Mathf.Max(0f, Time.time - probe.RequestedAt)
            });
        }

        private static string GetLearningV31NativeProvenStorePath()
        {
            string directory = Path.Combine(
                AppDomain.CurrentDomain.BaseDirectory,
                "BepInEx",
                "plugins",
                "BotTraversal",
                "Data",
                "Learning");
            Directory.CreateDirectory(directory);
            return Path.Combine(directory, SanitizeFileName(locationId) + ".nativeproven.json");
        }

        private static bool IsLearningV325SameDirectionalWalkThroughPortal(
            LearnedTraversalEdge left, LearnedTraversalEdge right)
        {
            if (left == null || right == null ||
                !string.Equals(left.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(right.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !IsFinite(left.RawStart) || !IsFinite(left.RawEnd) || !IsFinite(right.RawStart) || !IsFinite(right.RawEnd))
            {
                return false;
            }
            Vector3 leftDirection = GetFlatDirection(left.RawEnd - left.RawStart);
            Vector3 rightDirection = GetFlatDirection(right.RawEnd - right.RawStart);
            if (leftDirection.sqrMagnitude < 0.5f || rightDirection.sqrMagnitude < 0.5f ||
                Vector3.Dot(leftDirection, rightDirection) < LearningV2RevisionMinDirectionDot)
            {
                return false;
            }
            bool endpointEquivalent =
                GetPlanarDistance(left.RawStart, right.RawStart) <= LearningV2RevisionEndpointRadius &&
                GetPlanarDistance(left.RawEnd, right.RawEnd) <= LearningV2RevisionEndpointRadius &&
                Mathf.Abs(left.RawStart.y - right.RawStart.y) <= LearningV2RevisionVerticalTolerance &&
                Mathf.Abs(left.RawEnd.y - right.RawEnd.y) <= LearningV2RevisionVerticalTolerance;
            if (endpointEquivalent) return true;
            float leftSpan = GetPlanarDistance(left.RawStart, left.RawEnd);
            if (leftSpan < WalkThroughCandidateMinDistance) return false;
            Vector3 rightStartDelta = right.RawStart - left.RawStart;
            Vector3 rightEndDelta = right.RawEnd - left.RawStart;
            rightStartDelta.y = 0f; rightEndDelta.y = 0f;
            float startProjection = Vector3.Dot(rightStartDelta, leftDirection);
            float endProjection = Vector3.Dot(rightEndDelta, leftDirection);
            Vector3 startLateral = rightStartDelta - leftDirection * startProjection;
            Vector3 endLateral = rightEndDelta - leftDirection * endProjection;
            if (startProjection < -WalkThroughSemanticCompletionLateral || endProjection < startProjection ||
                endProjection > leftSpan + WalkThroughSemanticCompletionDistance ||
                startLateral.magnitude > WalkThroughSemanticCompletionLateral ||
                endLateral.magnitude > WalkThroughSemanticCompletionLateral) return false;
            float startT = Mathf.Clamp01(startProjection / leftSpan);
            float endT = Mathf.Clamp01(endProjection / leftSpan);
            return Mathf.Abs(right.RawStart.y - Mathf.Lerp(left.RawStart.y, left.RawEnd.y, startT)) <= LearningV2RevisionVerticalTolerance &&
                   Mathf.Abs(right.RawEnd.y - Mathf.Lerp(left.RawStart.y, left.RawEnd.y, endT)) <= LearningV2RevisionVerticalTolerance;
        }

        private static LearnedTraversalEdge FindLearningV325CanonicalNativeWalkThrough(LearnedTraversalEdge candidate)
        {
            if ((candidate == null) ||
                !string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)) return null;
            return LearnedTraversalEdges
                .Where(edge => edge != null && edge.Id != candidate.Id && !edge.Disabled &&
                               IsLearningV3NativeProvenEdge(edge) &&
                               string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                               IsLearningV325SameDirectionalWalkThroughPortal(edge, candidate))
                .OrderByDescending(edge => GetPlanarDistance(edge.RawStart, edge.RawEnd))
                .ThenByDescending(edge => edge.NativeSuccessCount)
                .ThenByDescending(edge => edge.SuccessfulExecutions)
                .ThenByDescending(edge => edge.DemonstrationRevision)
                .FirstOrDefault();
        }

        private static int RetireLearningV325ContainedNativeWalkThroughFragments(LearnedTraversalEdge canonical)
        {
            if ((canonical == null) ||
                !string.Equals(canonical.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return 0;
            }
            int retired = 0;
            foreach (LearnedTraversalEdge fragment in LearnedTraversalEdges.Where(edge =>
                edge != null && edge.Id != canonical.Id && !edge.Disabled &&
                IsLearningV3NativeProvenEdge(edge) &&
                string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                IsLearningV325SameDirectionalWalkThroughPortal(canonical, edge)).ToList())
            {
                fragment.Verified = false;
                fragment.NativeSuccessCount = 0;
                fragment.SuccessfulExecutions = 0;
                fragment.SupersedesProvenEdgeId = canonical.Id;
                retired++;
                WriteEvent("learningV325NativeWalkThroughFragmentRetiredOnline", null, new
                {
                    canonicalEdgeId = canonical.Id, retiredEdgeId = fragment.Id,
                    canonicalRawStart = Vec(canonical.RawStart), canonicalRawEnd = Vec(canonical.RawEnd),
                    retiredRawStart = Vec(fragment.RawStart), retiredRawEnd = Vec(fragment.RawEnd),
                    persistentGeometryMutated = false, successCreditMerged = false
                });
            }
            return retired;
        }

        private static List<PersistentTraversalLink> CanonicalizeLearningV325NativeProvenWalkThroughLinks(
            IEnumerable<PersistentTraversalLink> source, out int retired)
        {
            retired = 0;
            List<PersistentTraversalLink> all = source?.Where(item => item != null).ToList()
                ?? new List<PersistentTraversalLink>();
            if ((all.Count <= 1)) return all;

            List<PersistentTraversalLink> candidates = all
                .Where(item => string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                               item.NativeVerified && item.NativeSuccessCount > 0 && !item.Disabled)
                // V3.25: a contained short fragment can accumulate more repetitions than the full
                // portal. Geometry authority therefore prefers the widest proven corridor first;
                // success count breaks ties but is never merged from retired fragments.
                .OrderByDescending(item => GetPlanarDistance(item.RawStart.ToVector3(), item.RawEnd.ToVector3()))
                .ThenByDescending(item => item.NativeSuccessCount)
                .ThenByDescending(item => item.SuccessfulExecutions)
                .ThenByDescending(item => item.DemonstrationRevision)
                .ToList();
            List<PersistentTraversalLink> survivors = new List<PersistentTraversalLink>();
            HashSet<PersistentTraversalLink> retiredLinks = new HashSet<PersistentTraversalLink>();
            foreach (PersistentTraversalLink candidate in candidates)
            {
                PersistentTraversalLink canonical = survivors.FirstOrDefault(existing =>
                    IsLearningV324SameDirectionalWalkThroughPortal(existing, candidate));
                if (canonical == null)
                {
                    survivors.Add(candidate);
                    continue;
                }
                retiredLinks.Add(candidate);
                retired++;
                WriteEvent("learningV325NativeProvenWalkThroughFragmentRetired", null, new
                {
                    retiredExperienceKey = candidate.ExperienceKey, canonicalExperienceKey = canonical.ExperienceKey,
                    retiredNativeSuccesses = candidate.NativeSuccessCount, canonicalNativeSuccesses = canonical.NativeSuccessCount,
                    retiredRawStart = Vec(candidate.RawStart.ToVector3()), retiredRawEnd = Vec(candidate.RawEnd.ToVector3()),
                    canonicalRawStart = Vec(canonical.RawStart.ToVector3()), canonicalRawEnd = Vec(canonical.RawEnd.ToVector3()),
                    reason = "widestSameDirectionalPortalCanonicalization", successCreditMerged = false
                });
            }
            return all.Where(item => !retiredLinks.Contains(item)).ToList();
        }

        private static bool IsLearningV324SameDirectionalWalkThroughPortal(
            PersistentTraversalLink left,
            PersistentTraversalLink right)
        {
            if (left == null || right == null ||
                !string.Equals(left.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(right.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 leftStart = left.RawStart.ToVector3();
            Vector3 leftEnd = left.RawEnd.ToVector3();
            Vector3 rightStart = right.RawStart.ToVector3();
            Vector3 rightEnd = right.RawEnd.ToVector3();
            if (!IsFinite(leftStart) || !IsFinite(leftEnd) || !IsFinite(rightStart) || !IsFinite(rightEnd))
            {
                return false;
            }

            Vector3 leftDirection = GetFlatDirection(leftEnd - leftStart);
            Vector3 rightDirection = GetFlatDirection(rightEnd - rightStart);
            if (leftDirection.sqrMagnitude < 0.5f || rightDirection.sqrMagnitude < 0.5f ||
                Vector3.Dot(leftDirection, rightDirection) < LearningV2RevisionMinDirectionDot)
            {
                return false;
            }

            bool endpointEquivalent =
                GetPlanarDistance(leftStart, rightStart) <= LearningV2RevisionEndpointRadius &&
                GetPlanarDistance(leftEnd, rightEnd) <= LearningV2RevisionEndpointRadius &&
                Mathf.Abs(leftStart.y - rightStart.y) <= LearningV2RevisionVerticalTolerance &&
                Mathf.Abs(leftEnd.y - rightEnd.y) <= LearningV2RevisionVerticalTolerance;
            if (endpointEquivalent)
            {
                return true;
            }

            // Fragment hygiene: old WT producers could persist only the middle of a portal. Retire
            // a weaker fragment when both of its endpoints lie on the stronger survivor's same
            // directional segment. Reuse existing WT lateral/completion and revision vertical
            // envelopes; no V3.24 distance tolerance is added.
            float leftSpan = GetPlanarDistance(leftStart, leftEnd);
            if (leftSpan < WalkThroughCandidateMinDistance)
            {
                return false;
            }
            Vector3 rightStartDelta = rightStart - leftStart;
            Vector3 rightEndDelta = rightEnd - leftStart;
            rightStartDelta.y = 0f;
            rightEndDelta.y = 0f;
            float startProjection = Vector3.Dot(rightStartDelta, leftDirection);
            float endProjection = Vector3.Dot(rightEndDelta, leftDirection);
            Vector3 startLateral = rightStartDelta - leftDirection * startProjection;
            Vector3 endLateral = rightEndDelta - leftDirection * endProjection;
            bool contained =
                startProjection >= -WalkThroughSemanticCompletionLateral &&
                endProjection >= startProjection &&
                endProjection <= leftSpan + WalkThroughSemanticCompletionDistance &&
                startLateral.magnitude <= WalkThroughSemanticCompletionLateral &&
                endLateral.magnitude <= WalkThroughSemanticCompletionLateral;
            if (!contained)
            {
                return false;
            }
            float startT = Mathf.Clamp01(startProjection / leftSpan);
            float endT = Mathf.Clamp01(endProjection / leftSpan);
            float expectedStartY = Mathf.Lerp(leftStart.y, leftEnd.y, startT);
            float expectedEndY = Mathf.Lerp(leftStart.y, leftEnd.y, endT);
            return Mathf.Abs(rightStart.y - expectedStartY) <= LearningV2RevisionVerticalTolerance &&
                   Mathf.Abs(rightEnd.y - expectedEndY) <= LearningV2RevisionVerticalTolerance;
        }

        private static List<PersistentTraversalLink> CanonicalizeLearningV324NativeProvenWalkThroughLinks(
            IEnumerable<PersistentTraversalLink> source,
            out int retired)
        {
            retired = 0;
            List<PersistentTraversalLink> all = source?.Where(item => item != null).ToList()
                ?? new List<PersistentTraversalLink>();
            if ((all.Count <= 1))
            {
                return all;
            }

            List<PersistentTraversalLink> candidates = all
                .Where(item => string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                               item.NativeVerified && item.NativeSuccessCount > 0 && !item.Disabled)
                .OrderByDescending(item => item.NativeSuccessCount)
                .ThenByDescending(item => GetPlanarDistance(item.RawStart.ToVector3(), item.RawEnd.ToVector3()))
                .ThenByDescending(item => item.SuccessfulExecutions)
                .ThenByDescending(item => item.DemonstrationRevision)
                .ToList();
            List<PersistentTraversalLink> survivors = new List<PersistentTraversalLink>();
            HashSet<PersistentTraversalLink> retiredLinks = new HashSet<PersistentTraversalLink>();

            foreach (PersistentTraversalLink candidate in candidates)
            {
                PersistentTraversalLink canonical = survivors.FirstOrDefault(existing =>
                    IsLearningV324SameDirectionalWalkThroughPortal(existing, candidate));
                if (canonical == null)
                {
                    survivors.Add(candidate);
                    continue;
                }

                retiredLinks.Add(candidate);
                retired++;
                WriteEvent("learningV324NativeProvenWalkThroughDuplicateRetired", null, new
                {
                    retiredExperienceKey = candidate.ExperienceKey,
                    canonicalExperienceKey = canonical.ExperienceKey,
                    retiredNativeSuccesses = candidate.NativeSuccessCount,
                    canonicalNativeSuccesses = canonical.NativeSuccessCount,
                    retiredRawStart = Vec(candidate.RawStart.ToVector3()),
                    retiredRawEnd = Vec(candidate.RawEnd.ToVector3()),
                    canonicalRawStart = Vec(canonical.RawStart.ToVector3()),
                    canonicalRawEnd = Vec(canonical.RawEnd.ToVector3()),
                    reason = "sameDirectionalPortalCanonicalization"
                });
            }

            return all.Where(item => !retiredLinks.Contains(item)).ToList();
        }

        private static bool IsLearningV344SafeHistoricalWalkThrough(PersistentTraversalLink item)
        {
            return (item != null) &&
                   string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                   item.PlayerValidated && item.BotVerified && item.NativeVerified && !item.Disabled &&
                   item.SuccessfulExecutions > 0 && !string.IsNullOrWhiteSpace(item.ExperienceKey) &&
                   IsFinite(item.RawStart.ToVector3()) && IsFinite(item.RawEnd.ToVector3());
        }

        private static bool IsLearningV344SameDirectionalPersistentWalkThrough(
            PersistentTraversalLink left, PersistentTraversalLink right)
        {
            if (left == null || right == null ||
                !string.Equals(left.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(right.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }
            Vector3 a0 = left.RawStart.ToVector3(); Vector3 a1 = left.RawEnd.ToVector3();
            Vector3 b0 = right.RawStart.ToVector3(); Vector3 b1 = right.RawEnd.ToVector3();
            if (!IsFinite(a0) || !IsFinite(a1) || !IsFinite(b0) || !IsFinite(b1) ||
                GetPlanarDistance(a0, b0) > LearningV344HistoricalWalkThroughMatchEndpointRadius ||
                GetPlanarDistance(a1, b1) > LearningV344HistoricalWalkThroughMatchEndpointRadius ||
                Mathf.Abs(a0.y - b0.y) > LearningV344HistoricalWalkThroughMatchVerticalTolerance ||
                Mathf.Abs(a1.y - b1.y) > LearningV344HistoricalWalkThroughMatchVerticalTolerance)
            {
                return false;
            }
            Vector3 ad = GetFlatDirection(a1 - a0); Vector3 bd = GetFlatDirection(b1 - b0);
            if (ad.sqrMagnitude >= 0.5f && bd.sqrMagnitude >= 0.5f &&
                Vector3.Dot(ad, bd) < LearningV2RevisionMinDirectionDot)
            {
                return false;
            }
            float aspan = GetPlanarDistance(a0, a1); float bspan = GetPlanarDistance(b0, b1);
            if (aspan > 0.20f && bspan > 0.20f)
            {
                float ratio = bspan / aspan;
                if (ratio < LearningV2RevisionMinSpanRatio || ratio > LearningV2RevisionMaxSpanRatio)
                {
                    return false;
                }
            }
            return true;
        }

        private static int ApplyLearningV346V344FabricatedNativeCreditRepair(
            PersistentTraversalLinkDatabase database, string nativeStorePath)
        {
            if ((database?.Links == null) ||
                database.V346FabricatedNativeCreditRepairRevision >= LearningV346FabricatedNativeCreditRepairRevision)
            {
                return 0;
            }

            List<PersistentTraversalLink> repairable = database.Links.Where(item =>
                item != null && string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                !string.IsNullOrWhiteSpace(item.ExperienceKey) &&
                LearningV346V344FabricatedNativeCreditByExperienceKey.TryGetValue(item.ExperienceKey, out int fabricated) &&
                item.NativeSuccessCount >= fabricated && item.SuccessfulExecutions >= fabricated).ToList();
            if (repairable.Count == 0)
            {
                return 0;
            }

            string backupPath = nativeStorePath + ".pre-v346-v344-fabricated-credit-repair.bak";
            if (File.Exists(nativeStorePath) && !File.Exists(backupPath))
            {
                File.Copy(nativeStorePath, backupPath, false);
            }

            int totalNativeBefore = database.Links.Sum(item => item != null ? Math.Max(0, item.NativeSuccessCount) : 0);
            int totalSuccessfulBefore = database.Links.Sum(item => item != null ? Math.Max(0, item.SuccessfulExecutions) : 0);
            int repairedEdges = 0;
            int removedNativeCredit = 0;
            int removedSuccessfulCredit = 0;

            foreach (PersistentTraversalLink item in repairable)
            {
                int fabricated = LearningV346V344FabricatedNativeCreditByExperienceKey[item.ExperienceKey];
                int previousNative = item.NativeSuccessCount;
                int previousSuccessful = item.SuccessfulExecutions;
                item.NativeSuccessCount = Math.Max(0, previousNative - fabricated);
                item.SuccessfulExecutions = Math.Max(0, previousSuccessful - fabricated);
                item.HistoricalSemanticAuthority = item.NativeSuccessCount <= 0;
                repairedEdges++;
                removedNativeCredit += previousNative - item.NativeSuccessCount;
                removedSuccessfulCredit += previousSuccessful - item.SuccessfulExecutions;

                WriteEvent("learningV346V344FabricatedNativeCreditEdgeRepaired", null, new
                {
                    experienceKey = item.ExperienceKey,
                    kind = item.Kind,
                    fabricatedBaseline = fabricated,
                    nativeBefore = previousNative,
                    nativeAfter = item.NativeSuccessCount,
                    successfulBefore = previousSuccessful,
                    successfulAfter = item.SuccessfulExecutions,
                    historicalSemanticAuthority = item.HistoricalSemanticAuthority,
                    modernNativeCreditPreserved = item.NativeSuccessCount,
                    action = "subtractOnlyTraceProvenV344FabricatedBaseline"
                });
            }

            database.V346FabricatedNativeCreditRepairRevision = LearningV346FabricatedNativeCreditRepairRevision;
            database.SanitizerRevision = Math.Max(database.SanitizerRevision, LearningV346NativeProvenSanitizerRevision);
            int totalNativeAfter = database.Links.Sum(item => item != null ? Math.Max(0, item.NativeSuccessCount) : 0);
            int totalSuccessfulAfter = database.Links.Sum(item => item != null ? Math.Max(0, item.SuccessfulExecutions) : 0);

            string tempPath = nativeStorePath + ".v346-credit-repair.tmp";
            File.WriteAllText(tempPath, JsonConvert.SerializeObject(database, Formatting.Indented));
            File.Copy(tempPath, nativeStorePath, true);
            File.Delete(tempPath);

            WriteEvent("learningV346V344FabricatedNativeCreditRepairCompleted", null, new
            {
                path = nativeStorePath,
                backupPath,
                repairedEdges,
                removedNativeCredit,
                removedSuccessfulCredit,
                nativeSuccessCreditBefore = totalNativeBefore,
                nativeSuccessCreditAfter = totalNativeAfter,
                successfulExecutionCreditBefore = totalSuccessfulBefore,
                successfulExecutionCreditAfter = totalSuccessfulAfter,
                migrationRevision = database.V346FabricatedNativeCreditRepairRevision,
                sanitizerRevision = database.SanitizerRevision,
                action = "reversibleExactProvenanceRepairBeforeHistoricalSemanticMerge"
            });
            return repairedEdges;
        }

        private static int MergeLearningV344HistoricalWalkThroughSemanticTruth(
            PersistentTraversalLinkDatabase database, string nativeStorePath)
        {
            if ((database?.Links == null))
            {
                return 0;
            }
            LearningV344HistoricalWalkThroughSemanticKeys.Clear();
            {
                foreach (PersistentTraversalLink persisted in database.Links.Where(item => item != null &&
                    item.HistoricalSemanticAuthority && item.NativeSuccessCount <= 0 &&
                    string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                    !string.IsNullOrWhiteSpace(item.ExperienceKey)))
                {
                    LearningV344HistoricalWalkThroughSemanticKeys.Add(persisted.ExperienceKey);
                }
            }
            int restored = 0;
            HashSet<string> knownKeys = new HashSet<string>(
                database.Links.Where(item => item != null && !string.IsNullOrWhiteSpace(item.ExperienceKey))
                    .Select(item => item.ExperienceKey), StringComparer.Ordinal);
            string[] sources = new[]
            {
                nativeStorePath + ".pre-v337-sanitizer35.bak",
                GetTraversalLinksPath()
            };
            foreach (string sourcePath in sources.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
                {
                    continue;
                }
                try
                {
                    PersistentTraversalLinkDatabase historical = JsonConvert.DeserializeObject<PersistentTraversalLinkDatabase>(
                        File.ReadAllText(sourcePath));
                    if (historical?.Links == null)
                    {
                        continue;
                    }
                    int sourceRestored = 0;
                    int sourceNativeSuccessCreditIsolated = 0;
                    foreach (PersistentTraversalLink candidate in historical.Links)
                    {
                        if (!IsLearningV344SafeHistoricalWalkThrough(candidate))
                        {
                            continue;
                        }
                        PersistentTraversalLink equivalent = database.Links.FirstOrDefault(existing =>
                            existing != null && IsLearningV344SameDirectionalPersistentWalkThrough(existing, candidate));
                        if (equivalent != null)
                        {
                            if (equivalent.NativeSuccessCount <= 0 &&
                                !string.IsNullOrWhiteSpace(equivalent.ExperienceKey))
                            {
                                equivalent.HistoricalSemanticAuthority =
                                    true;
                                LearningV344HistoricalWalkThroughSemanticKeys.Add(equivalent.ExperienceKey);
                            }
                            continue;
                        }
                        if (knownKeys.Contains(candidate.ExperienceKey))
                        {
                            continue;
                        }
                        {
                            sourceNativeSuccessCreditIsolated += Math.Max(0, candidate.NativeSuccessCount);
                            candidate.SuccessfulExecutions = 0;
                            candidate.NativeSuccessCount = 0;
                            candidate.AssistedSuccessCount = 0;
                            candidate.TeleportFallbackCount = 0;
                        }
                        candidate.HistoricalSemanticAuthority =
                            true;
                        database.Links.Add(candidate);
                        knownKeys.Add(candidate.ExperienceKey);
                        // Every newly imported record came from a historical-only source. Its old
                        // BotVerified/NativeVerified provenance proves passage semantics, not a
                        // modern clean-Native execution in this runtime/policy epoch.
                        LearningV344HistoricalWalkThroughSemanticKeys.Add(candidate.ExperienceKey);
                        restored++;
                        sourceRestored++;
                    }
                    WriteEvent("learningV344HistoricalWalkThroughSemanticSourceMerged", null, new
                    {
                        sourcePath,
                        restored = sourceRestored,
                        totalRestored = restored,
                        nativeSuccessCreditIsolated = sourceNativeSuccessCreditIsolated,
                        action = "restoreHistoricalSemanticAuthorityWithoutInventingNativeSuccessCredit"
                    });
                }
                catch (Exception ex)
                {
                    WriteEvent("learningV344HistoricalWalkThroughSemanticSourceRejected", null, new
                    {
                        sourcePath,
                        error = ex.GetType().Name + ": " + ex.Message
                    });
                }
            }
            return restored;
        }

        private static void LoadLearningV31NativeProvenStore(string mapId)
        {
            if ((string.IsNullOrWhiteSpace(mapId)))
            {
                return;
            }
            try
            {
                string path = GetLearningV31NativeProvenStorePath();
                PersistentTraversalLinkDatabase database;
                if (!File.Exists(path))
                {
                    database = new PersistentTraversalLinkDatabase
                    {
                        SchemaVersion = 9,
                        SanitizerRevision = LearningV346NativeProvenSanitizerRevision,
                        V346FabricatedNativeCreditRepairRevision = LearningV346FabricatedNativeCreditRepairRevision,
                        Links = new List<PersistentTraversalLink>()
                    };
                    WriteEvent("learningV344NativeProvenStoreMissingHistoricalSemanticRecovery", null, new
                    {
                        path,
                        action = "continueWithEmptyNativeStoreAndRestoreHistoricalSemanticTruth"
                    });
                }
                else
                {
                    database = JsonConvert.DeserializeObject<PersistentTraversalLinkDatabase>(File.ReadAllText(path));
                    if (database == null || database.SchemaVersion != 9 || database.Links == null)
                    {
                        LogInfo("ignored unsupported LearningV3.1 Native-Proven store; expected schemaVersion=9");
                        return;
                    }
                }

                int learningV346FabricatedCreditEdgesRepaired =
                    ApplyLearningV346V344FabricatedNativeCreditRepair(database, path);
                WriteEvent("learningV346PersistentTruthRepairLoadBoundary", null, new
                {
                    repairedEdges = learningV346FabricatedCreditEdgesRepaired,
                    migrationRevision = database.V346FabricatedNativeCreditRepairRevision,
                    sanitizerRevision = database.SanitizerRevision
                });

                int learningV320PreviousSanitizerRevision = database.SanitizerRevision;
                bool learningV320SemanticHygieneMigration =
                    (false);
                List<PersistentTraversalLink> learningV320RetainedLinks = learningV320SemanticHygieneMigration
                    ? new List<PersistentTraversalLink>()
                    : null;
                int learningV320Retired = 0;
                if (learningV320SemanticHygieneMigration)
                {
                    string backupPath = path + ".pre-v320-sanitizer32.bak";
                    if (!File.Exists(backupPath))
                    {
                        File.Copy(path, backupPath, false);
                    }
                }

                int learningV324PreviousSanitizerRevision = database.SanitizerRevision;
                bool learningV324WalkThroughCanonicalizationMigration =
                    (false);
                int learningV324RetiredDuplicates = 0;
                if (learningV324WalkThroughCanonicalizationMigration)
                {
