                    if (!File.Exists(backupPath))
                    {
                        File.Copy(path, backupPath, false);
                    }
                    database.Links = CanonicalizeLearningV324NativeProvenWalkThroughLinks(
                        database.Links, out learningV324RetiredDuplicates);
                }

                int learningV337PreviousSanitizerRevision = database.SanitizerRevision;
                bool learningV337LocalTruthMigration =
                    (false);
                HashSet<string> learningV337RetiredExperienceKeys = learningV337LocalTruthMigration
                    ? new HashSet<string>(StringComparer.Ordinal)
                    : null;
                int learningV337RetiredWalkThroughs = 0;
                if (learningV337LocalTruthMigration)
                {
                    string backupPath = path + ".pre-v337-sanitizer35.bak";
                    if (!File.Exists(backupPath))
                    {
                        File.Copy(path, backupPath, false);
                    }
                    foreach (PersistentTraversalLink candidate in database.Links)
                    {
                        if (candidate == null ||
                            !string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }
                        Vector3 candidateStart = candidate.RawStart.ToVector3();
                        Vector3 candidateEnd = candidate.RawEnd.ToVector3();
                        if (!IsFinite(candidateStart) || !IsFinite(candidateEnd))
                        {
                            continue;
                        }
                        float candidateSpan = GetPlanarDistance(candidateStart, candidateEnd);
                        bool micro = candidateSpan < WalkThroughStandalonePersistMinDistance;
                        bool localBypass = TryFindCheapLocalWalkThroughBypass(
                            candidateStart, candidateEnd,
                            out float candidateBypassCost,
                            out Vector3 candidateBypassStart,
                            out Vector3 candidateBypassEnd,
                            out float candidateBypassShoulder);
                        if (!micro && !localBypass)
                        {
                            continue;
                        }
                        if (!string.IsNullOrWhiteSpace(candidate.ExperienceKey))
                        {
                            learningV337RetiredExperienceKeys.Add(candidate.ExperienceKey);
                        }
                        learningV337RetiredWalkThroughs++;
                        WriteEvent("learningV337NativeProvenWalkThroughLocalTruthRetired", null, new
                        {
                            experienceKey = candidate.ExperienceKey,
                            directDistance = candidateSpan,
                            micro,
                            localBypass,
                            bypassCost = localBypass ? candidateBypassCost : 0f,
                            bypassStart = localBypass ? (object)Vec(candidateBypassStart) : null,
                            bypassEnd = localBypass ? (object)Vec(candidateBypassEnd) : null,
                            shoulderOffset = localBypass ? candidateBypassShoulder : 0f,
                            reason = micro ? "microWalkThroughRequiresLocalTopology" : "cheapLocalNavMeshBypassReproven"
                        });
                    }
                    WriteEvent("learningV337NativeProvenWalkThroughLocalTruthMigrationPrepared", null, new
                    {
                        previousRevision = learningV337PreviousSanitizerRevision,
                        revision = LearningV337NativeProvenSanitizerRevision,
                        retired = learningV337RetiredWalkThroughs,
                        backupPath
                    });
                }

                int learningV325PreviousSanitizerRevision = database.SanitizerRevision;
                int learningV325RetiredDuplicates = 0;
                bool learningV325CanonicalizationMigration =
                    (false);
                if (learningV325CanonicalizationMigration)
                {
                    string backupPath = path + ".pre-v325-sanitizer34.bak";
                    if (!File.Exists(backupPath)) File.Copy(path, backupPath, false);
                    database.Links = CanonicalizeLearningV325NativeProvenWalkThroughLinks(
                        database.Links, out learningV325RetiredDuplicates);
                    database.SanitizerRevision = LearningV325NativeProvenSanitizerRevision;
                    WriteEvent("learningV325NativeProvenWalkThroughCanonicalizationPrepared", null, new
                    {
                        previousRevision = learningV325PreviousSanitizerRevision,
                        revision = LearningV325NativeProvenSanitizerRevision,
                        retiredDuplicates = learningV325RetiredDuplicates, retained = database.Links.Count,
                        backupPath, nativeGeometryMutated = false, successCreditMerged = false
                    });
                }

                int learningV344BeforeLinkCount = database.Links.Count;
                int learningV344BeforeWalkThroughCount = database.Links.Count(item => item != null &&
                    string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase));
                int learningV344BeforeNativeSuccessCredit = database.Links.Sum(item =>
                    item != null ? Math.Max(0, item.NativeSuccessCount) : 0);
                HashSet<string> learningV344BeforeExperienceKeys = new HashSet<string>(
                    database.Links.Where(item => item != null && !string.IsNullOrWhiteSpace(item.ExperienceKey))
                        .Select(item => item.ExperienceKey), StringComparer.Ordinal);
                int learningV344HistoricalRestored = MergeLearningV344HistoricalWalkThroughSemanticTruth(database, path);
                int learningV344AfterWalkThroughCount = database.Links.Count(item => item != null &&
                    string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase));
                int learningV344AfterNativeSuccessCredit = database.Links.Sum(item =>
                    item != null ? Math.Max(0, item.NativeSuccessCount) : 0);
                int learningV344ExistingKeysRemoved = learningV344BeforeExperienceKeys.Count(key =>
                    !database.Links.Any(item => item != null && string.Equals(item.ExperienceKey, key, StringComparison.Ordinal)));
                WriteEvent("learningV344PersistenceMigrationDeltaCensus", null, new
                {
                    beforeLinks = learningV344BeforeLinkCount,
                    afterLinks = database.Links.Count,
                    beforeWalkThroughs = learningV344BeforeWalkThroughCount,
                    afterWalkThroughs = learningV344AfterWalkThroughCount,
                    historicalSemanticRestored = learningV344HistoricalRestored,
                    existingKeysRemoved = learningV344ExistingKeysRemoved,
                    nativeSuccessCreditBefore = learningV344BeforeNativeSuccessCredit,
                    nativeSuccessCreditAfter = learningV344AfterNativeSuccessCredit,
                    destructiveMigrationEnabled = false,
                    action = "auditPersistentTruthDeltaBeforeRuntimeAdmission"
                });
                int loaded = 0;
                foreach (PersistentTraversalLink item in database.Links)
                {
                    if (learningV337LocalTruthMigration && item != null &&
                        !string.IsNullOrWhiteSpace(item.ExperienceKey) &&
                        learningV337RetiredExperienceKeys.Contains(item.ExperienceKey))
                    {
                        continue;
                    }
                    if (learningV320SemanticHygieneMigration && item != null &&
                        string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                    {
                        Vector3 hygieneRawStart = item.RawStart.ToVector3();
                        Vector3 hygieneRawEnd = item.RawEnd.ToVector3();
                        if (IsFinite(hygieneRawStart) && IsFinite(hygieneRawEnd) &&
                            TryFindCheapLocalWalkThroughBypass(
                                hygieneRawStart, hygieneRawEnd,
                                out float hygieneBypassCost,
                                out Vector3 hygieneBypassStart,
                                out Vector3 hygieneBypassEnd,
                                out float hygieneBypassShoulder))
                        {
                            learningV320Retired++;
                            WriteEvent("learningV320NativeProvenSemanticHygieneRetired", null, new
                            {
                                experienceKey = item.ExperienceKey,
                                kind = item.Kind,
                                rawStart = Vec(hygieneRawStart),
                                rawEnd = Vec(hygieneRawEnd),
                                nativeSuccessCount = item.NativeSuccessCount,
                                bypassCost = hygieneBypassCost,
                                bypassStart = Vec(hygieneBypassStart),
                                bypassEnd = Vec(hygieneBypassEnd),
                                shoulderOffset = hygieneBypassShoulder,
                                reason = "learningV320CheapLocalNavMeshBypassReproven"
                            });
                            continue;
                        }
                    }
                    learningV320RetainedLinks?.Add(item);
                    bool learningV344HistoricalSemantic = item != null &&
                        !string.IsNullOrWhiteSpace(item.ExperienceKey) &&
                        item.NativeSuccessCount <= 0 &&
                        (((item.HistoricalSemanticAuthority)) ||
                         LearningV344HistoricalWalkThroughSemanticKeys.Contains(item.ExperienceKey));
                    if (item == null || string.IsNullOrWhiteSpace(item.Kind) ||
                        string.IsNullOrWhiteSpace(item.ExperienceKey) || !item.NativeVerified ||
                        (item.NativeSuccessCount <= 0 && !learningV344HistoricalSemantic) || item.Disabled)
                    {
                        continue;
                    }
                    Vector3 rawStart = item.RawStart.ToVector3();
                    Vector3 rawEnd = item.RawEnd.ToVector3();
                    if (!IsFinite(rawStart) || !IsFinite(rawEnd))
                    {
                        continue;
                    }

                    bool dropDown = string.Equals(item.Kind, "DropDown", StringComparison.OrdinalIgnoreCase);
                    Vector3 approachDirection = IsFinite(item.ApproachDirection.ToVector3())
                        ? item.ApproachDirection.ToVector3()
                        : GetFlatDirection(rawEnd - rawStart);
                    Vector3 a = rawStart;
                    if (dropDown)
                    {
                        if (TrySampleCredibleDropDownTopEntry(rawStart, approachDirection, out Vector3 credibleTopEntry))
                        {
                            a = credibleTopEntry;
                        }
                    }
                    else if (NavMesh.SamplePosition(rawStart, out NavMeshHit aHit, 2.25f, NavMesh.AllAreas))
                    {
                        a = aHit.position;
                    }
                    Vector3 b = NavMesh.SamplePosition(rawEnd, out NavMeshHit bHit, 2.25f, NavMesh.AllAreas)
                        ? bHit.position
                        : rawEnd;
                    if (!dropDown && Vector3.Distance(a, b) < 0.35f)
                    {
                        a = rawStart;
                        b = rawEnd;
                    }

                    LearnedTraversalEdge edge = new LearnedTraversalEdge
                    {
                        Id = ++learnedTraversalEdgeSequence,
                        ExperienceKey = item.ExperienceKey,
                        SupersedesProvenEdgeId = 0,
                        DemonstrationRevision = Math.Max(1, item.DemonstrationRevision),
                        Kind = item.Kind,
                        RequiredPose = FollowerCapabilityPosturePolicy.Normalize(item.RequiredPose),
                        A = a,
                        B = b,
                        RawStart = rawStart,
                        RawEnd = rawEnd,
                        HasSettledStart = item.HasSettledStart && IsFinite(item.SettledStart.ToVector3()),
                        SettledStart = item.HasSettledStart ? item.SettledStart.ToVector3() : default(Vector3),
                        HasSettledEnd = item.HasSettledEnd && IsFinite(item.SettledEnd.ToVector3()),
                        SettledEnd = item.HasSettledEnd ? item.SettledEnd.ToVector3() : default(Vector3),
                        CreatedAt = Time.time,
                        PlayerValidated = item.PlayerValidated,
                        Verified = !learningV344HistoricalSemantic,
                        HistoricalSemanticAuthority = learningV344HistoricalSemantic,
                        Disabled = false,
                        SuccessfulExecutions = learningV344HistoricalSemantic
                            ? 0
                            : Math.Max(Math.Max(1, item.NativeSuccessCount), item.SuccessfulExecutions),
                        FailedExecutions = 0,
                        NativeSuccessCount = learningV344HistoricalSemantic ? 0 : Math.Max(1, item.NativeSuccessCount),
                        AssistedSuccessCount = 0,
                        TeleportFallbackCount = 0,
                        ApproachDirection = approachDirection,
                        ApproachSpeed = item.ApproachSpeed,
                        ApproachMode = item.ApproachMode,
                        TraversalDuration = item.TraversalDuration,
                        WalkThroughCorridorSamples = item.CorridorSamples != null
                            ? item.CorridorSamples.Select(sample => sample.ToVector3()).Where(IsFinite).ToList()
                            : new List<Vector3>(),
                        EgressSamples = item.EgressSamples != null
                            ? item.EgressSamples.Select(sample => sample.ToVector3()).Where(IsFinite).ToList()
                            : new List<Vector3>(),
                        EgressSemanticSamples = item.EgressSemanticSamples != null
                            ? item.EgressSemanticSamples
                                .Where(sample => sample != null && IsFinite(sample.Position.ToVector3()))
                                .Select(sample => new TraversalEgressSemanticSample
                                {
                                    Position = sample.Position.ToVector3(),
                                    Grounded = sample.Grounded,
                                    State = sample.State,
                                    NavMeshSampled = sample.NavMeshSampled,
                                    NavMeshPosition = sample.NavMeshPosition.ToVector3()
                                }).ToList()
                            : new List<TraversalEgressSemanticSample>(),
                        MotionSamples = item.MotionSamples != null
                            ? item.MotionSamples
                                .Where(sample => sample != null && IsFinite(sample.LocalOffset.ToVector3()))
                                .Select(sample => new TraversalMotionSample
                                {
                                    Time = Mathf.Max(0f, sample.Time),
                                    LocalOffset = sample.LocalOffset.ToVector3(),
                                    State = sample.State,
                                    Grounded = sample.Grounded
                                }).OrderBy(sample => sample.Time).ToList()
                            : new List<TraversalMotionSample>(),
                        ObstacleFingerprint = item.ObstacleFingerprint != null
                            ? new TraversalObstacleFingerprint
                            {
                                Name = item.ObstacleFingerprint.Name,
                                Layer = item.ObstacleFingerprint.Layer,
                                BoundsCenter = item.ObstacleFingerprint.BoundsCenter.ToVector3(),
                                BoundsSize = item.ObstacleFingerprint.BoundsSize.ToVector3()
                            }
                            : null,
                        NativeVaultParameters = item.NativeVaultParameters != null
                            ? new NativeVaultParameters
                            {
                                Strategy = item.NativeVaultParameters.Strategy,
                                VaultingPoint = item.NativeVaultParameters.VaultingPoint.ToVector3(),
                                VaultingHeight = item.NativeVaultParameters.VaultingHeight,
                                VaultingLength = item.NativeVaultParameters.VaultingLength,
                                DemonstratedVaultingSpeed = item.NativeVaultParameters.DemonstratedVaultingSpeed,
                                BehindObstacleRatio = item.NativeVaultParameters.BehindObstacleRatio,
                                AbsoluteForwardVelocity = item.NativeVaultParameters.AbsoluteForwardVelocity
                            }
                            : null
                    };
                    LearnedTraversalEdges.Add(edge);
                    if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                    {
                        RecordPrivateWalkThroughAvailable(edge, "learningV31NativeProvenLoad");
                    }
                    loaded++;
                    WriteEvent("learningV31NativeProvenEdgeLoaded", null, new
                    {
                        edgeId = edge.Id,
                        experienceKey = edge.ExperienceKey,
                        kind = edge.Kind,
                        nativeSuccesses = edge.NativeSuccessCount,
                        successfulExecutions = edge.SuccessfulExecutions,
                        historicalSemanticAuthority = edge.HistoricalSemanticAuthority
                    });
