                if (learningV320SemanticHygieneMigration)
                {
                    database.Links = learningV320RetainedLinks;
                    database.SanitizerRevision = LearningV320NativeProvenSanitizerRevision;
                    string migrationTempPath = path + ".v320.tmp";
                    File.WriteAllText(migrationTempPath, JsonConvert.SerializeObject(database, Formatting.Indented));
                    if (File.Exists(path))
                    {
                        File.Delete(path);
                    }
                    File.Move(migrationTempPath, path);
                    WriteEvent("learningV320NativeProvenSemanticHygieneCompleted", null, new
                    {
                        path,
                        previousRevision = learningV320PreviousSanitizerRevision,
                        revision = LearningV320NativeProvenSanitizerRevision,
                        retired = learningV320Retired,
                        retained = learningV320RetainedLinks.Count,
                        backupPath = path + ".pre-v320-sanitizer32.bak"
                    });
                }

                if (learningV324WalkThroughCanonicalizationMigration)
                {
                    // If an older store also required V3.20 cleanup, that pass may have replaced
                    // database.Links after the first V3.24 canonicalization. Re-run the idempotent
                    // canonicalizer on the retained set before committing revision 33.
                    int postV320Retired = 0;
                    database.Links = CanonicalizeLearningV324NativeProvenWalkThroughLinks(
                        database.Links, out postV320Retired);
                    learningV324RetiredDuplicates += postV320Retired;
                    database.SanitizerRevision = LearningV324NativeProvenSanitizerRevision;
                    string migrationTempPath = path + ".v324.tmp";
                    File.WriteAllText(migrationTempPath, JsonConvert.SerializeObject(database, Formatting.Indented));
                    if (File.Exists(path))
                    {
                        File.Delete(path);
                    }
                    File.Move(migrationTempPath, path);
                    WriteEvent("learningV324NativeProvenWalkThroughCanonicalizationCompleted", null, new
                    {
                        path,
                        previousRevision = learningV324PreviousSanitizerRevision,
                        revision = LearningV324NativeProvenSanitizerRevision,
                        retiredDuplicates = learningV324RetiredDuplicates,
                        retained = database.Links.Count,
                        backupPath = path + ".pre-v324-sanitizer33.bak",
                        nativeGeometryMutated = false
                    });
                }

                if (learningV325CanonicalizationMigration)
                {
                    // V3.20/V3.24 may have rewritten the retained set after the first V3.25 pass.
                    // Re-run the same idempotent canonicalizer last, then commit Sanitizer34.
                    int postLegacyRetired = 0;
                    database.Links = CanonicalizeLearningV325NativeProvenWalkThroughLinks(
                        database.Links, out postLegacyRetired);
                    learningV325RetiredDuplicates += postLegacyRetired;
                    database.SanitizerRevision = LearningV325NativeProvenSanitizerRevision;
                    string migrationTempPath = path + ".v325.tmp";
                    File.WriteAllText(migrationTempPath, JsonConvert.SerializeObject(database, Formatting.Indented));
                    if (File.Exists(path)) File.Delete(path);
                    File.Move(migrationTempPath, path);
                    WriteEvent("learningV325NativeProvenWalkThroughCanonicalizationCompleted", null, new
                    {
                        path, previousRevision = learningV325PreviousSanitizerRevision,
                        revision = LearningV325NativeProvenSanitizerRevision,
                        retiredDuplicates = learningV325RetiredDuplicates, retained = database.Links.Count,
                        backupPath = path + ".pre-v325-sanitizer34.bak",
