                string path = GetLearningV31NativeProvenStorePath();
                string backupPath = path + ".pre-v345-global-architecture.bak";
                if (true && File.Exists(path) && !File.Exists(backupPath))
                {
                    File.Copy(path, backupPath, false);
                    WriteEvent("learningV345NativeProvenPreWriteBackupCreated", null, new
                    {
                        path,
                        backupPath,
                        action = "preserveReversiblePreV345PersistentState"
                    });
                }
                string tempPath = path + ".tmp";
                File.WriteAllText(tempPath, JsonConvert.SerializeObject(database, Formatting.Indented));
                File.Copy(tempPath, path, true);
                File.Delete(tempPath);
                learningV337NativeProvenDirty = false;
                WriteEvent("learningV31NativeProvenStoreSaved", null, new
                {
                    path,
                    nativeProvenEdges = database.Links.Count,
                    legacyMixedPersistenceWritten = false,
                    sanitizerRevision = LearningV346NativeProvenSanitizerRevision,
                    fabricatedCreditRepairRevision = LearningV346FabricatedNativeCreditRepairRevision,
                    raidEndFlush = learningV337PersistenceFlushInProgress
                });
            }
            catch (Exception ex)
            {
                LogError("LearningV3.1 Native-Proven store save failed: " + ex.Message);
            }
        }

        private static string GetTraversalLinksPath()
        {
            string directory = Path.Combine(
                AppDomain.CurrentDomain.BaseDirectory,
                "BepInEx",
                "plugins",
                "BotTraversal",
                "Data",
                "Learning");
            Directory.CreateDirectory(directory);
            return Path.Combine(directory, SanitizeFileName(locationId) + ".json");
        }

        private static void LoadPersistentTraversalLinks(string mapId)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(mapId))
                {
                    return;
                }

                string path = GetTraversalLinksPath();
                if (!File.Exists(path))
                {
                    return;
                }

                string json = File.ReadAllText(path);
                string trimmed = json.TrimStart();
                if (trimmed.StartsWith("[", StringComparison.Ordinal))
                {
                    LogInfo("ignored legacy traversal-link schema v1; links must be re-learned under v1.3.14");
                    return;
                }

                PersistentTraversalLinkDatabase database =
                    JsonConvert.DeserializeObject<PersistentTraversalLinkDatabase>(json);
                if (database == null || (database.SchemaVersion != 3 && database.SchemaVersion != 4 && database.SchemaVersion != 5 && database.SchemaVersion != 6 && database.SchemaVersion != 7 && database.SchemaVersion != 8 && database.SchemaVersion != 9) || database.Links == null)
                {
                    LogInfo("ignored unsupported traversal-link database; expected schemaVersion=3, 4, 5, 6, 7, 8 or 9");
                    return;
                }

                loadedTraversalSanitizerRevision = Math.Max(0, database.SanitizerRevision);
                int rehabilitatedWalkThroughEdges = 0;
                foreach (PersistentTraversalLink item in database.Links)
                {
                    if (item == null || string.IsNullOrWhiteSpace(item.Kind) ||
                        (!item.PlayerValidated && item.SuccessfulExecutions <= 0))
                    {
                        continue;
                    }

                    if (database.SchemaVersion < 6 &&
                        string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                    {
                        // V1.3.22 invalidates pre-corridor WalkThrough persistence. Older files
                        // contain micro-edges generated every ~0.5m and cannot be safely migrated
                        // into ordered episodes without the original breadcrumb provenance.
                        continue;
                    }

                    Vector3 rawStart = item.RawStart.ToVector3();
                    Vector3 rawEnd = item.RawEnd.ToVector3();
                    if (!IsFinite(rawStart) || !IsFinite(rawEnd))
                    {
                        continue;
                    }

                    bool dropDown = string.Equals(item.Kind, "DropDown", StringComparison.OrdinalIgnoreCase);
                    Vector3 persistedApproachDirection =
                        database.SchemaVersion >= 4 && IsFinite(item.ApproachDirection.ToVector3())
                            ? item.ApproachDirection.ToVector3()
                            : GetFlatDirection(rawEnd - rawStart);

                    // R9.7: never let a generic SamplePosition project a DropDown entry through the
                    // ledge onto the lower floor. That turns a one-way descent into a fake same-level
                    // path and can make followers already below the ledge "re-enter" the traversal.
                    bool aSampled;
                    NavMeshHit aHit = default(NavMeshHit);
                    Vector3 a;
                    if (dropDown)
                    {
                        aSampled = TrySampleCredibleDropDownTopEntry(
                            rawStart,
                            persistedApproachDirection,
                            out a);
                    }
                    else
                    {
                        aSampled = NavMesh.SamplePosition(rawStart, out aHit, 2.25f, NavMesh.AllAreas);
                        a = aSampled ? aHit.position : rawStart;
                    }

                    bool bSampled = NavMesh.SamplePosition(rawEnd, out NavMeshHit bHit, 2.25f, NavMesh.AllAreas);
                    Vector3 b = bSampled ? bHit.position : rawEnd;
                    if (!dropDown && Vector3.Distance(a, b) < 0.35f)
                    {
                        a = rawStart;
                        b = rawEnd;
                    }

                    // Schema 5 is the first version where a player-authored traversal is counted
                    // only after Egress + Verify. Older AssistedSuccess counters include transient
                    // RawEnd hits that could immediately drop back to the entry side, so reset those
                    // player-authored counters during migration instead of preserving false success.
                    bool playerValidatedTraversalCountersAreAuthoritative =
                        database.SchemaVersion >= 5 && item.PlayerValidated;
                    int typedSuccessfulExecutions =
                        Math.Max(0, item.NativeSuccessCount) +
                        Math.Max(0, item.AssistedSuccessCount) +
                        Math.Max(0, item.TeleportFallbackCount);
                    int successfulExecutions = playerValidatedTraversalCountersAreAuthoritative
                        ? typedSuccessfulExecutions
                        : (item.PlayerValidated && database.SchemaVersion < 5 ? 0 : item.SuccessfulExecutions);

                    // R9.7: WalkThrough's clean physical completion uses the legacy/physical
                    // completion mode, so it is intentionally not represented by Native/Assisted
                    // subtype counters. Schema-9 stores SuccessfulExecutions authoritatively; do not
                    // erase that learned proof on every reload. Experience remains an independent
                    // second source of evidence.
                    if (database.SchemaVersion >= 9 &&
                        string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                    {
                        successfulExecutions = Math.Max(successfulExecutions, Math.Max(0, item.SuccessfulExecutions));
                    }

                    // R5 materially changes the WalkThrough executor. R4-R1 could disable an otherwise
                    // proven player-authored corridor solely because the global 6-second ownership lease
                    // expired while the follower was still making forward progress. Revive only Schema-8
                    // WalkThrough links that are player validated AND have succeeded before; do not revive
                    // never-proven or non-WalkThrough links.
                    bool rehabilitateWalkThroughForR5 =
                        database.SchemaVersion == 8 &&
                        item.PlayerValidated &&
                        item.Disabled &&
                        item.SuccessfulExecutions > 0 &&
                        string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);

                    LearnedTraversalEdge edge = new LearnedTraversalEdge
                    {
                        Id = ++learnedTraversalEdgeSequence,
                        ExperienceKey = string.IsNullOrWhiteSpace(item.ExperienceKey) ? CreateTraversalExperienceKey() : item.ExperienceKey,
                        DemonstrationRevision = database.SchemaVersion >= 9 ? Math.Max(1, item.DemonstrationRevision) : 1,
                        Kind = item.Kind,
                        RequiredPose = FollowerCapabilityPosturePolicy.Normalize(item.RequiredPose),
                        A = a,
                        B = b,
                        RawStart = rawStart,
                        RawEnd = rawEnd,
                        HasSettledStart = database.SchemaVersion >= 5 && item.HasSettledStart && IsFinite(item.SettledStart.ToVector3()),
                        SettledStart = database.SchemaVersion >= 5 && item.HasSettledStart ? item.SettledStart.ToVector3() : default(Vector3),
                        HasSettledEnd = database.SchemaVersion >= 5 && item.HasSettledEnd && IsFinite(item.SettledEnd.ToVector3()),
                        SettledEnd = database.SchemaVersion >= 5 && item.HasSettledEnd ? item.SettledEnd.ToVector3() : default(Vector3),
                        CreatedAt = Time.time,
                        PlayerValidated = item.PlayerValidated,
                        // Schema 3 BotVerified may have been produced by exact-exit teleport. Do not
                        // migrate that polluted flag into NativeVerified for player-authored edges.
                        Verified = database.SchemaVersion >= 4
                            ? item.NativeVerified
                            : (!item.PlayerValidated && item.BotVerified),
                        Disabled = (rehabilitateWalkThroughForR5 ? false : item.Disabled) ||
                                   (string.Equals(item.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                                    Mathf.Abs(rawEnd.y - rawStart.y) > WalkThroughReclassificationVerticalDelta) ||
                                   (dropDown && !aSampled),
                        SuccessfulExecutions = successfulExecutions,
                        FailedExecutions = rehabilitateWalkThroughForR5 ? 0 : item.FailedExecutions,
                        NativeSuccessCount = database.SchemaVersion >= 5 || !item.PlayerValidated ? item.NativeSuccessCount : 0,
                        AssistedSuccessCount = database.SchemaVersion >= 5 || !item.PlayerValidated ? item.AssistedSuccessCount : 0,
                        TeleportFallbackCount = database.SchemaVersion >= 5 || !item.PlayerValidated ? item.TeleportFallbackCount : 0,
                        ApproachDirection = persistedApproachDirection,
                        ApproachSpeed = database.SchemaVersion >= 4 ? item.ApproachSpeed : 0f,
                        ApproachMode = database.SchemaVersion >= 4 ? item.ApproachMode : null,
                        TraversalDuration = database.SchemaVersion >= 4 ? item.TraversalDuration : 0f,
                        WalkThroughCorridorSamples = database.SchemaVersion >= 6 && item.CorridorSamples != null
                            ? item.CorridorSamples.Select(sample => sample.ToVector3()).Where(IsFinite).ToList()
                            : new List<Vector3>(),
                        EgressSamples = item.EgressSamples != null
                            ? item.EgressSamples.Select(sample => sample.ToVector3()).Where(IsFinite).ToList()
                            : new List<Vector3>(),
                        EgressSemanticSamples = item.EgressSemanticSamples != null
                            ? item.EgressSemanticSamples
                                .Where(sample => sample != null && IsFinite(sample.Position.ToVector3()))
                                .Select(sample => new TraversalEgressSemanticSample
                                {
                                    Position = sample.Position.ToVector3(),
                                    Grounded = sample.Grounded,
                                    State = sample.State,
                                    NavMeshSampled = sample.NavMeshSampled,
                                    NavMeshPosition = sample.NavMeshPosition.ToVector3()
                                }).ToList()
                            : new List<TraversalEgressSemanticSample>(),
                        MotionSamples = database.SchemaVersion >= 7 && item.MotionSamples != null
                            ? item.MotionSamples
                                .Where(sample => sample != null && IsFinite(sample.LocalOffset.ToVector3()))
                                .Select(sample => new TraversalMotionSample
                                {
                                    Time = Mathf.Max(0f, sample.Time),
                                    LocalOffset = sample.LocalOffset.ToVector3(),
                                    State = sample.State,
                                    Grounded = sample.Grounded
                                })
                                .OrderBy(sample => sample.Time)
                                .ToList()
                            : new List<TraversalMotionSample>(),
                        ObstacleFingerprint = database.SchemaVersion >= 7 && item.ObstacleFingerprint != null
                            ? new TraversalObstacleFingerprint
                            {
                                Name = item.ObstacleFingerprint.Name,
                                Layer = item.ObstacleFingerprint.Layer,
                                BoundsCenter = item.ObstacleFingerprint.BoundsCenter.ToVector3(),
                                BoundsSize = item.ObstacleFingerprint.BoundsSize.ToVector3()
                            }
                            : null,
                        NativeVaultParameters = database.SchemaVersion >= 8 && item.NativeVaultParameters != null
                            ? new NativeVaultParameters
                            {
                                Strategy = item.NativeVaultParameters.Strategy,
                                VaultingPoint = item.NativeVaultParameters.VaultingPoint.ToVector3(),
                                VaultingHeight = item.NativeVaultParameters.VaultingHeight,
                                VaultingLength = item.NativeVaultParameters.VaultingLength,
                                DemonstratedVaultingSpeed = item.NativeVaultParameters.DemonstratedVaultingSpeed,
                                BehindObstacleRatio = item.NativeVaultParameters.BehindObstacleRatio,
                                AbsoluteForwardVelocity = item.NativeVaultParameters.AbsoluteForwardVelocity
                            }
                            : null
                    };
                    LearnedTraversalEdges.Add(edge);
                    if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                        Mathf.Abs(edge.RawEnd.y - edge.RawStart.y) > WalkThroughReclassificationVerticalDelta)
                    {
                        WriteEvent("traversalEdgeQuarantinedForReclassification", null, new
                        {
                            edgeId = edge.Id,
                            kind = edge.Kind,
                            suggestedKind = "Drop",
                            verticalDelta = Mathf.Abs(edge.RawEnd.y - edge.RawStart.y),
                            threshold = WalkThroughReclassificationVerticalDelta
                        });
                    }
                    if (rehabilitateWalkThroughForR5)
                    {
                        rehabilitatedWalkThroughEdges++;
                        LogInfo($"R5 traversal migration re-enabled proven WalkThrough edge {edge.Id} after legacy executor disablement.");
                    }
                    if (database.SchemaVersion >= 6)
                    {
                        RegisterTraversalEpisodeForEdge(edge.Id, edge.Kind, edge.RawStart, edge.RawEnd, 0, 0, false);
                    }
                    if (database.SchemaVersion < 5 &&
                        string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                    {
                        PrepareSettledAnchorsForLearnedEdge(edge);
                    }

                    if (!edge.Disabled && (edge.PlayerValidated || edge.Verified) &&
                        string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                    {
                        RecordPrivateWalkThroughAvailable(edge, "load");
                    }
                }

                if (rehabilitatedWalkThroughEdges > 0)
                {
                    // Persist the rehabilitation immediately so a crash/early exit cannot leave the old
                    // R4-R1 disable flag in the Schema-8 database for the next raid.
                    SavePersistentTraversalLinks();
                    LogInfo($"R5 traversal migration persisted {rehabilitatedWalkThroughEdges} rehabilitated WalkThrough edge(s).");
                }
            }
            catch (Exception ex)
            {
                LogError("persistent traversal link load failed: " + ex.Message);
            }
        }

        private static void SavePersistentTraversalLinks()
        {
            {
                return;
            }
            if ((!learningV337PersistenceFlushInProgress))
            {
                learningV337TraversalLinksDirty = true;
                return;
            }
            try
            {
                if (!raidActive || string.IsNullOrWhiteSpace(locationId))
                {
                    return;
                }

                PersistentTraversalLinkDatabase database = new PersistentTraversalLinkDatabase
                {
                    SchemaVersion = 9,
                    SanitizerRevision = TraversalPersistenceSanitizerRevision,
                    Links = LearnedTraversalEdges
                        .Where(edge => edge != null && !edge.SyntheticPhysicalCorridor && !edge.RuntimeOnlyTraversal && (edge.PlayerValidated || edge.Verified))
                        .Select(edge => new PersistentTraversalLink
                        {
                            ExperienceKey = string.IsNullOrWhiteSpace(edge.ExperienceKey) ? CreateTraversalExperienceKey() : edge.ExperienceKey,
                            DemonstrationRevision = Math.Max(1, edge.DemonstrationRevision),
                            Kind = edge.Kind,
                            RequiredPose = FollowerCapabilityPosturePolicy.Normalize(edge.RequiredPose),
                            RawStart = PersistentVector3.From(edge.RawStart),
                            RawEnd = PersistentVector3.From(edge.RawEnd),
                            HasSettledStart = edge.HasSettledStart,
                            SettledStart = PersistentVector3.From(edge.SettledStart),
                            HasSettledEnd = edge.HasSettledEnd,
                            SettledEnd = PersistentVector3.From(edge.SettledEnd),
                            PlayerValidated = edge.PlayerValidated,
                            BotVerified = edge.Verified,
                            NativeVerified = edge.Verified,
                            SuccessfulExecutions = edge.SuccessfulExecutions,
                            NativeSuccessCount = edge.NativeSuccessCount,
                            AssistedSuccessCount = edge.AssistedSuccessCount,
                            TeleportFallbackCount = edge.TeleportFallbackCount,
                            ApproachDirection = PersistentVector3.From(edge.ApproachDirection),
                            ApproachSpeed = edge.ApproachSpeed,
                            ApproachMode = edge.ApproachMode,
                            TraversalDuration = edge.TraversalDuration,
                            FailedExecutions = edge.FailedExecutions,
                            Disabled = edge.Disabled,
                            CorridorSamples = edge.WalkThroughCorridorSamples != null
                                ? edge.WalkThroughCorridorSamples.Where(IsFinite).Select(PersistentVector3.From).ToList()
                                : new List<PersistentVector3>(),
                            EgressSamples = edge.EgressSamples != null
                                ? edge.EgressSamples.Where(IsFinite).Select(PersistentVector3.From).ToList()
                                : new List<PersistentVector3>(),
                            EgressSemanticSamples = edge.EgressSemanticSamples != null
                                ? edge.EgressSemanticSamples
                                    .Where(sample => sample != null && IsFinite(sample.Position))
                                    .Select(sample => new PersistentTraversalEgressSemanticSample
                                    {
                                        Position = PersistentVector3.From(sample.Position),
                                        Grounded = sample.Grounded,
                                        State = sample.State,
                                        NavMeshSampled = sample.NavMeshSampled,
                                        NavMeshPosition = PersistentVector3.From(sample.NavMeshPosition)
                                    }).ToList()
                                : new List<PersistentTraversalEgressSemanticSample>(),
                            MotionSamples = edge.MotionSamples != null
                                ? edge.MotionSamples
                                    .Where(sample => sample != null && IsFinite(sample.LocalOffset))
                                    .OrderBy(sample => sample.Time)
                                    .Select(sample => new PersistentTraversalMotionSample
                                    {
                                        Time = sample.Time,
                                        LocalOffset = PersistentVector3.From(sample.LocalOffset),
                                        State = sample.State,
                                        Grounded = sample.Grounded
                                    })
                                    .ToList()
                                : new List<PersistentTraversalMotionSample>(),
                            ObstacleFingerprint = edge.ObstacleFingerprint == null
                                ? null
                                : new PersistentTraversalObstacleFingerprint
                                {
                                    Name = edge.ObstacleFingerprint.Name,
                                    Layer = edge.ObstacleFingerprint.Layer,
                                    BoundsCenter = PersistentVector3.From(edge.ObstacleFingerprint.BoundsCenter),
                                    BoundsSize = PersistentVector3.From(edge.ObstacleFingerprint.BoundsSize)
                                },
                            NativeVaultParameters = edge.NativeVaultParameters == null
                                ? null
                                : new PersistentNativeVaultParameters
                                {
                                    Strategy = edge.NativeVaultParameters.Strategy,
                                    VaultingPoint = PersistentVector3.From(edge.NativeVaultParameters.VaultingPoint),
                                    VaultingHeight = edge.NativeVaultParameters.VaultingHeight,
                                    VaultingLength = edge.NativeVaultParameters.VaultingLength,
                                    DemonstratedVaultingSpeed = edge.NativeVaultParameters.DemonstratedVaultingSpeed,
                                    BehindObstacleRatio = edge.NativeVaultParameters.BehindObstacleRatio,
                                    AbsoluteForwardVelocity = edge.NativeVaultParameters.AbsoluteForwardVelocity
                                }
                        })
                        .ToList()
                };

                File.WriteAllText(
                    GetTraversalLinksPath(),
                    JsonConvert.SerializeObject(database, Formatting.Indented));
                learningV337TraversalLinksDirty = false;
            }
            catch (Exception ex)
            {
                LogError("persistent traversal link save failed: " + ex.Message);
            }
        }


        private static TraversalEgressSemanticSample CloneTraversalEgressSemanticSample(TraversalEgressSemanticSample sample)
        {
            if (sample == null)
            {
                return null;
            }
            return new TraversalEgressSemanticSample
            {
                Position = sample.Position,
                Grounded = sample.Grounded,
                State = sample.State,
                NavMeshSampled = sample.NavMeshSampled,
                NavMeshPosition = sample.NavMeshPosition
            };
        }

        private static string CreateTraversalExperienceKey()
        {
            return Guid.NewGuid().ToString("N");
        }

        private static string GetTraversalExperiencePath()
        {
            string directory = Path.Combine(
                AppDomain.CurrentDomain.BaseDirectory,
                "BepInEx",
                "plugins",
                "BotTraversal",
                "Data",
                "Learning");
            Directory.CreateDirectory(directory);
            return Path.Combine(directory, SanitizeFileName(locationId) + ".experience.json");
        }

        private static void LoadTraversalExperience(string mapId)
        {
            TraversalExperiences.Clear();
            try
            {
                if (string.IsNullOrWhiteSpace(mapId))
                {
                    return;
                }
                string path = GetTraversalExperiencePath();
                if (!File.Exists(path))
                {
                    return;
                }
                PersistentTraversalExperienceDatabase database =
                    JsonConvert.DeserializeObject<PersistentTraversalExperienceDatabase>(File.ReadAllText(path));
                if (database == null || database.SchemaVersion != TraversalExperienceSchemaVersion || database.Edges == null)
                {
                    LogInfo("ignored unsupported traversal experience database");
                    return;
                }
                foreach (TraversalExperienceRecord record in database.Edges)
                {
                    if (record == null || string.IsNullOrWhiteSpace(record.ExperienceKey))
                    {
                        continue;
                    }
                    if (record.PolicyVersion <= 0)
                    {
                        record.PolicyVersion = 1;
                    }
                    TraversalExperiences[record.ExperienceKey] = record;
                }
                LogInfo($"loaded {TraversalExperiences.Count} traversal experience record(s) for {mapId}");
            }
            catch (Exception ex)
            {
                LogError("traversal experience load failed: " + ex.Message);
            }
        }

