        private static void BackupTraversalPersistenceBeforeSanitization()
        {
            try
            {
                string linksPath = GetTraversalLinksPath();
                string experiencePath = GetTraversalExperiencePath();
                string linksBackup = linksPath + ".compilefix15-pre-sanitize.bak";
                string experienceBackup = experiencePath + ".compilefix15-pre-sanitize.bak";
                if (File.Exists(linksPath) && !File.Exists(linksBackup))
                {
                    File.Copy(linksPath, linksBackup, false);
                }
                if (File.Exists(experiencePath) && !File.Exists(experienceBackup))
                {
                    File.Copy(experiencePath, experienceBackup, false);
                }
            }
            catch (Exception ex)
            {
                // Sanitization may proceed even if the optional backup cannot be written, but make
                // the failure visible so the user knows the original file was not protected.
                LogError("CompileFix15 traversal sanitizer backup failed: " + ex.Message);
            }
        }

        private static void SanitizeTraversalPersistenceAfterLoad()
        {
            try
            {
                if (!raidActive)
                {
                    return;
                }

                if (loadedTraversalSanitizerRevision < TraversalPersistenceSanitizerRevision)
                {
                    BackupTraversalPersistenceBeforeCompileFix46SemanticCleanup();
                    BackupTraversalPersistenceBeforeCompileFix50PassageCleanup();
                    BackupTraversalPersistenceBeforeCompileFix51CrossKindCleanup();
                }
                BackupTraversalPersistenceBeforeSanitization();

                List<LearnedTraversalEdge> removedEdges = new List<LearnedTraversalEdge>();
                HashSet<string> removedExperienceKeys = new HashSet<string>(StringComparer.Ordinal);
                int removedExperienceRecordCount = 0;
                int resetExecutionStatLinkCount = 0;
                int rekeyedExperienceLinkCount = 0;
                List<object> reasons = new List<object>();

                // 1) Stable ExperienceKey must describe one immutable traversal kind. R8.1 allowed
                // Vault/Climb capture to refresh a nearby Jump edge and overwrite Kind/geometry while
                // the experience record still described Jump. Both sides of such a pair are tainted:
                // remove the geometry and its experience so the player can demonstrate it again under
                // R8.2 Kind Lock.
                foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                {
                    if (edge == null || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                        !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord experience) ||
                        experience == null)
                    {
                        continue;
                    }

                    if (string.IsNullOrWhiteSpace(experience.Kind))
                    {
                        experience.Kind = edge.Kind;
                        traversalExperienceDirty = true;
                        continue;
                    }

                    if (!string.Equals(edge.Kind, experience.Kind, StringComparison.OrdinalIgnoreCase))
                    {
                        removedEdges.Add(edge);
                        removedExperienceKeys.Add(edge.ExperienceKey);
                        reasons.Add(new
                        {
                            reason = "experienceKindMismatch",
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            linkKind = edge.Kind,
                            experienceKind = experience.Kind
                        });
                    }
                }

                // 2) The same R8.1 cross-kind overwrite can be surrounded by short WalkThrough
                // fragments learned while the player moved around the same elevated obstacle. Those
                // fragments were dangerous only because global AddLink published them as ordinary
                // topology, but keeping the contaminated local cluster would also poison adaptive
                // experience. Clean only the immediate WalkThrough cluster around a confirmed
                // mismatch seed; unrelated map knowledge is untouched.
                foreach (LearnedTraversalEdge seed in removedEdges.ToArray())
                {
                    Vector3 seedCenter = GetTraversalEdgePlanarCenter(seed);
                    if (!IsFinite(seedCenter))
                    {
                        continue;
                    }

                    foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges.ToArray())
                    {
                        if (candidate == null || removedEdges.Contains(candidate) ||
                            !string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        Vector3 candidateCenter = GetTraversalEdgePlanarCenter(candidate);
                        if (!IsFinite(candidateCenter) ||
                            GetPlanarDistance(seedCenter, candidateCenter) > TraversalMismatchClusterCleanupRadius)
                        {
                            continue;
                        }

                        removedEdges.Add(candidate);
                        if (!string.IsNullOrWhiteSpace(candidate.ExperienceKey))
                        {
                            removedExperienceKeys.Add(candidate.ExperienceKey);
                        }
                        reasons.Add(new
                        {
                            reason = "nearMismatchWalkThroughCluster",
                            edgeId = candidate.Id,
                            experienceKey = candidate.ExperienceKey,
                            kind = candidate.Kind,
                            distanceFromMismatch = GetPlanarDistance(seedCenter, candidateCenter)
                        });
                    }
                }

                // 3) R8.2 could record a Jump as FullEgressSuccess after the moving-Verify
                // state-release grace expired even though EFT still reported JumpLanding. Geometry
                // is still valuable, but those success statistics are invalid and must not feed R9.
                foreach (TraversalExperienceRecord experience in TraversalExperiences.Values.ToArray())
                {
                    if (experience == null || string.IsNullOrWhiteSpace(experience.ExperienceKey) ||
                        !string.Equals(experience.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                        !string.Equals(
                            experience.LastReason,
                            "movingVerifyFarSideStateReleaseGraceExpired",
                            StringComparison.Ordinal))
                    {
                        continue;
                    }

                    removedExperienceKeys.Add(experience.ExperienceKey);
                    reasons.Add(new
                    {
                        reason = "r8_2FalseJumpStateReleaseSuccessReset",
                        experienceKey = experience.ExperienceKey,
                        kind = experience.Kind,
                        previousOutcome = experience.LastOutcome,
                        previousReason = experience.LastReason
                    });
                }

                // 4) R8.3 persisted elevated Jump edges as executable even when their RawEnd
                // had no stable NavMesh anchor and the platform continuation timed out. Keep the
                // geometry for future relearning, but quarantine it and reset its misleading
                // experience until a same-edge SettledExit or private platform egress exists.
                foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                {
                    if (edge == null || removedEdges.Contains(edge) ||
                        !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                    bool hasPrivatePlatformEgress = edge.EgressSamples != null &&
                                                    edge.EgressSamples.Count >= JumpPlatformEgressMinSamples &&
                                                    GetPlanarDistance(edge.RawEnd, edge.EgressSamples[edge.EgressSamples.Count - 1]) >=
                                                    JumpPlatformEgressMinPlanarProgress;
                    bool rawExitStable = edge.HasSettledEnd ||
                                         TrySampleTraversalSettledAnchor(edge.RawEnd, JumpPlatformRawExitStableNavRadius, out _);
                    if (!rawExitStable && !hasPrivatePlatformEgress)
                    {
                        bool changedIncompleteJump = !edge.Disabled;
                        edge.Disabled = true;
                        bool hadExperience = !string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                                             TraversalExperiences.ContainsKey(edge.ExperienceKey);
                        if (hadExperience)
                        {
                            removedExperienceKeys.Add(edge.ExperienceKey);
                        }
                        if (changedIncompleteJump || hadExperience)
                        {
                            reasons.Add(new
                            {
                                reason = "r8_3IncompletePlatformJumpQuarantined",
                                edgeId = edge.Id,
                                experienceKey = edge.ExperienceKey,
                                rawExit = Vec(edge.RawEnd),
                                hasSettledExit = edge.HasSettledEnd,
                                egressSampleCount = edge.EgressSamples?.Count ?? 0
                            });
                        }
                    }
                }

                // 5) R8.4 could persist a SettledStart/SettledEnd that lies back on the wrong side
                // of RawStart/RawEnd. That turns post-traversal egress into a forced U-turn and can
                // make a follower appear to complete WalkThrough/Jump/Climb, then run back into the
                // obstacle. Clear only the invalid settled anchor; preserve the demonstrated raw
                // geometry and private corridor/egress samples. Reset experience because historical
                // TeleportRecovered results may have been credited against the bad anchor.
                foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                {
                    if (edge == null || removedEdges.Contains(edge))
                    {
                        continue;
                    }

                    bool invalidStart = edge.HasSettledStart &&
                                        (!IsFinite(edge.SettledStart) ||
                                         !IsCredibleSettledExit(edge.Kind, edge.RawEnd, edge.RawStart, edge.SettledStart));
                    bool invalidEnd = edge.HasSettledEnd &&
                                      (!IsFinite(edge.SettledEnd) ||
                                       !IsCredibleSettledExit(edge.Kind, edge.RawStart, edge.RawEnd, edge.SettledEnd));
                    if (!invalidStart && !invalidEnd)
                    {
                        continue;
                    }

                    Vector3 oldStart = edge.SettledStart;
                    Vector3 oldEnd = edge.SettledEnd;
                    if (invalidStart)
                    {
                        edge.HasSettledStart = false;
                        edge.SettledStart = default(Vector3);
                    }
                    if (invalidEnd)
                    {
                        edge.HasSettledEnd = false;
                        edge.SettledEnd = default(Vector3);
                    }
                    if (!string.IsNullOrWhiteSpace(edge.ExperienceKey))
                    {
                        removedExperienceKeys.Add(edge.ExperienceKey);
                    }
                    reasons.Add(new
                    {
                        reason = "r8_6InvalidSettledAnchorCleared",
                        edgeId = edge.Id,
                        experienceKey = edge.ExperienceKey,
                        kind = edge.Kind,
                        invalidStart,
                        invalidEnd,
                        rawStart = Vec(edge.RawStart),
                        rawEnd = Vec(edge.RawEnd),
                        previousSettledStart = invalidStart ? Vec(oldStart) : null,
                        previousSettledEnd = invalidEnd ? Vec(oldEnd) : null
                    });
                }

                // 5b) R8.12.2 demonstration integrity migration. Schema-8 could refresh Raw/Egress
                // evidence while retaining an older SettledEnd, and its bridge recorder stored RawExit
                // without a matching semantic sample. Preserve ExperienceKey/statistics, but normalize
                // demonstration-specific geometry once before Schema-9 is saved.
                bool r8122DemonstrationIntegrityMigration = loadedTraversalSanitizerRevision < 7;
                if (r8122DemonstrationIntegrityMigration)
                {
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge))
                        {
                            continue;
                        }

                        edge.DemonstrationRevision = Math.Max(1, edge.DemonstrationRevision);
                        bool bridgeKind = string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                                          string.Equals(edge.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
                        if (bridgeKind && edge.EgressSemanticSamples != null && edge.EgressSemanticSamples.Count > 0)
                        {
                            List<Vector3> semanticPositions = edge.EgressSemanticSamples
                                .Where(sample => sample != null && IsFinite(sample.Position))
                                .Select(sample => sample.Position)
                                .ToList();
                            bool pairingMismatch = edge.EgressSamples == null ||
                                edge.EgressSamples.Count != semanticPositions.Count ||
                                edge.EgressSamples.Where(IsFinite).Zip(semanticPositions, (a, b) => GetPlanarDistance(a, b)).Any(distance => distance > 0.08f);
                            if (pairingMismatch)
                            {
                                int previousCount = edge.EgressSamples?.Count ?? 0;
                                edge.EgressSamples = semanticPositions;
                                reasons.Add(new
                                {
                                    reason = "r8_12_2EgressSemanticPairingNormalized",
                                    edgeId = edge.Id,
                                    experienceKey = edge.ExperienceKey,
                                    kind = edge.Kind,
                                    previousCount,
                                    semanticCount = semanticPositions.Count
                                });
                            }

                            if (edge.HasSettledEnd)
                            {
                                Vector3 previousSettledEnd = edge.SettledEnd;
                                edge.HasSettledEnd = false;
                                edge.SettledEnd = default(Vector3);
                                edge.SettledBreadcrumbSequence = 0;
                                reasons.Add(new
                                {
                                    reason = "r8_12_2LegacyBridgeSettledEndInvalidated",
                                    edgeId = edge.Id,
                                    experienceKey = edge.ExperienceKey,
                                    kind = edge.Kind,
                                    previousSettledEnd = Vec(previousSettledEnd),
                                    demonstrationRevision = edge.DemonstrationRevision
                                });
                            }
                        }

                        if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                            edge.HasSettledEnd &&
                            !IsCredibleWalkThroughTerminalConnector(
                                edge.RawStart, edge.RawEnd, edge.SettledEnd, edge.WalkThroughCorridorSamples))
                        {
                            Vector3 previousSettledEnd = edge.SettledEnd;
                            edge.HasSettledEnd = false;
                            edge.SettledEnd = default(Vector3);
                            edge.SettledBreadcrumbSequence = 0;
                            reasons.Add(new
                            {
                                reason = "r8_12_2WalkThroughTerminalConnectorCleared",
                                edgeId = edge.Id,
                                experienceKey = edge.ExperienceKey,
                                previousSettledEnd = Vec(previousSettledEnd),
                                rawEnd = Vec(edge.RawEnd)
                            });
                        }

                        // A legacy Jump that loses an unproven SettledEnd during this migration must
                        // not remain executable unless the same demonstration still contains a
                        // meaningful semantic egress tail or RawExit itself is a stable NavMesh exit.
                        // Preserve the long-term ExperienceKey/record; only quarantine this exact
                        // demonstration geometry until the player teaches it again.
                        if (string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                            !edge.HasSettledEnd)
                        {
                            bool hasPrivatePlatformEgress =
                                edge.EgressSamples != null &&
                                edge.EgressSamples.Count >= JumpPlatformEgressMinSamples &&
                                GetPlanarDistance(edge.RawEnd, edge.EgressSamples[edge.EgressSamples.Count - 1]) >=
                                    JumpPlatformEgressMinPlanarProgress;
                            bool rawExitStable = TrySampleTraversalSettledAnchor(
                                edge.RawEnd, JumpPlatformRawExitStableNavRadius, out _);
                            if (!hasPrivatePlatformEgress && !rawExitStable && !edge.Disabled)
                            {
                                edge.Disabled = true;
                                FollowerRuntimeNavMeshLinks.Remove(edge.Id);
                                ClearCommitmentsForEdge(edge.Id);
                                reasons.Add(new
                                {
                                    reason = "r8_12_2LegacyIncompleteJumpQuarantined",
                                    edgeId = edge.Id,
                                    experienceKey = edge.ExperienceKey,
                                    demonstrationRevision = edge.DemonstrationRevision,
                                    rawExit = Vec(edge.RawEnd),
                                    egressSampleCount = edge.EgressSamples?.Count ?? 0,
                                    preservedExperience = !string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                                        TraversalExperiences.ContainsKey(edge.ExperienceKey)
                                });
                            }
                        }
                    }
                }

                // 6) Policy V8 changed traversal reward so pre-V8 adaptive records cannot be
                // compared with modern physical/end-to-end evidence. CompileFix31 advances current
                // records to V9 later in this sanitizer, but V8 itself is deliberately preserved: it
                // contains valuable physical crossing/executor evidence that must not be discarded.
                foreach (TraversalExperienceRecord experience in TraversalExperiences.Values.ToArray())
                {
                    if (experience == null || string.IsNullOrWhiteSpace(experience.ExperienceKey) ||
                        experience.PolicyVersion >= 8)
                    {
                        continue;
                    }
                    removedExperienceKeys.Add(experience.ExperienceKey);
                    reasons.Add(new
                    {
                        reason = "compileFix10PreV8EndToEndFollowExperienceReset",
                        experienceKey = experience.ExperienceKey,
                        kind = experience.Kind,
                        previousPolicyVersion = experience.PolicyVersion,
                        attempts = experience.Attempts,
                        teleports = experience.TeleportRecoveries,
                        previousConfidence = experience.Confidence
                    });
                }

                bool r87LinkStatMigration = loadedTraversalSanitizerRevision < 5;
                foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                {
                    if (!r87LinkStatMigration || edge == null || removedEdges.Contains(edge) || !edge.PlayerValidated)
                    {
                        continue;
                    }

                    bool jump = string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase);
                    bool walkThrough = string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
                    bool vaultOrClimb = string.Equals(edge.Kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                                        string.Equals(edge.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
                    if (!jump && !walkThrough && !vaultOrClimb)
                    {
                        continue;
                    }

                    int previousSuccessful = edge.SuccessfulExecutions;
                    int previousNative = edge.NativeSuccessCount;
                    int previousAssisted = edge.AssistedSuccessCount;
                    int previousTeleport = edge.TeleportFallbackCount;
                    bool previousVerified = edge.Verified;

                    if (jump || walkThrough)
                    {
                        edge.SuccessfulExecutions = 0;
                        edge.NativeSuccessCount = 0;
                        edge.AssistedSuccessCount = 0;
                        edge.TeleportFallbackCount = 0;
                        edge.FailedExecutions = 0;
                        edge.Verified = false;
                        if (walkThrough)
                        {
                            // Old WalkThrough geometry is retained for comparison/re-demonstration,
                            // but is not executable until the player traverses that same direction
                            // once under R8.7. We cannot reconstruct which R8.6 refresh represented
                            // the trustworthy direction after forward/reverse overwrite pollution.
                            edge.Disabled = true;
                            FollowerRuntimeNavMeshLinks.Remove(edge.Id);
                            ClearCommitmentsForEdge(edge.Id);
                        }
                        if (jump)
                        {
                            bool hasBridgeEvidence = edge.HasSettledEnd ||
                                (edge.EgressSamples != null && edge.EgressSamples.Count >= JumpPlatformEgressMinSamples);
                            if (hasBridgeEvidence)
                            {
                                edge.Disabled = false;
                            }
                        }
                    }
                    else
                    {
                        edge.TeleportFallbackCount = 0;
                        edge.SuccessfulExecutions = Math.Max(0, edge.NativeSuccessCount) +
                                                    Math.Max(0, edge.AssistedSuccessCount);
                        edge.Verified = edge.SuccessfulExecutions > 0;
                    }

                    if (previousSuccessful != edge.SuccessfulExecutions ||
                        previousNative != edge.NativeSuccessCount ||
                        previousAssisted != edge.AssistedSuccessCount ||
                        previousTeleport != edge.TeleportFallbackCount ||
                        previousVerified != edge.Verified)
                    {
                        resetExecutionStatLinkCount++;
                        reasons.Add(new
                        {
                            reason = jump ? "r8_7JumpForcedEgressStatsReset" :
                                     (walkThrough ? "r8_7WalkThroughDirectionalStatsReset" : "r8_7TeleportSuccessRemoved"),
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            kind = edge.Kind,
                            previousSuccessful,
                            previousNative,
                            previousAssisted,
                            previousTeleport,
                            newSuccessful = edge.SuccessfulExecutions,
                            newVerified = edge.Verified,
                            newDisabled = edge.Disabled,
                            requiresFreshDirectionalDemonstration = walkThrough
                        });
                    }
                }

                // 7) R8.12 load-time toxic edge migration. Runtime quarantine can only react
                // after an edge is attempted again; an old 0-success / many-failure edge could
                // therefore survive forever if it was not revisited in the current raid. Disable
                // only player-demonstrated edges with strong historical failure evidence and no
                // trustworthy physical success. Preserve the experience record for diagnostics.
                bool r812ToxicEdgeMigration = loadedTraversalSanitizerRevision < 6;
                if (r812ToxicEdgeMigration)
                {
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge) || !edge.PlayerValidated || edge.Disabled)
                        {
                            continue;
                        }

                        TraversalExperienceRecord experience = null;
                        if (!string.IsNullOrWhiteSpace(edge.ExperienceKey))
                        {
                            TraversalExperiences.TryGetValue(edge.ExperienceKey, out experience);
                        }

                        int physicalExperienceSuccesses = experience == null
                            ? 0
                            : Math.Max(0, experience.CleanPhysicalSuccesses) +
                              Math.Max(0, experience.NativeSuccesses) +
                              Math.Max(0, experience.NativePartialAssistedSuccesses) +
                              Math.Max(0, experience.AssistedCrossingSuccesses) +
                              Math.Max(0, experience.FullEgressSuccesses);
                        int hardFailures = experience?.HardFailures ?? 0;
                        int consecutiveFailures = experience?.ConsecutiveFailures ?? 0;
                        int failureEvidence = Math.Max(
                            Math.Max(0, edge.FailedExecutions),
                            Math.Max(hardFailures, consecutiveFailures));

                        bool noPhysicalSuccess =
                            edge.SuccessfulExecutions <= 0 &&
                            edge.NativeSuccessCount <= 0 &&
                            edge.AssistedSuccessCount <= 0 &&
                            physicalExperienceSuccesses <= 0;
                        if (!noPhysicalSuccess || failureEvidence < 4)
                        {
                            continue;
                        }

                        edge.Disabled = true;
                        FollowerRuntimeNavMeshLinks.Remove(edge.Id);
                        ClearCommitmentsForEdge(edge.Id);
                        reasons.Add(new
                        {
                            reason = "r8_12ToxicZeroSuccessEdgeDisabled",
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            kind = edge.Kind,
                            failedExecutions = edge.FailedExecutions,
                            hardFailures,
                            consecutiveFailures,
                            failureEvidence,
                            successfulExecutions = edge.SuccessfulExecutions,
                            physicalExperienceSuccesses
                        });
                    }
                }

                if (r812ToxicEdgeMigration)
                {
                    // Success counters from pre-R8.12 builds were committed before authority
                    // handoff. Reset execution statistics once so Policy V6 confidence grows only
                    // from traversals that survive ExitAuthorityCommit. Disabled toxic geometry
                    // remains disabled; player-authored geometry itself is preserved.
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge) || !edge.PlayerValidated)
                        {
                            continue;
                        }

                        int previousSuccessful = edge.SuccessfulExecutions;
                        int previousNative = edge.NativeSuccessCount;
                        int previousAssisted = edge.AssistedSuccessCount;
                        int previousTeleport = edge.TeleportFallbackCount;
                        int previousFailed = edge.FailedExecutions;
                        bool previousVerified = edge.Verified;

                        edge.SuccessfulExecutions = 0;
                        edge.NativeSuccessCount = 0;
                        edge.AssistedSuccessCount = 0;
                        edge.TeleportFallbackCount = 0;
                        edge.FailedExecutions = 0;
                        edge.Verified = false;

                        if (previousSuccessful != 0 || previousNative != 0 ||
                            previousAssisted != 0 || previousTeleport != 0 ||
                            previousFailed != 0 || previousVerified)
                        {
                            resetExecutionStatLinkCount++;
                            reasons.Add(new
                            {
                                reason = "r8_12AuthorityCommitStatsReset",
                                edgeId = edge.Id,
                                experienceKey = edge.ExperienceKey,
                                kind = edge.Kind,
                                previousSuccessful,
                                previousNative,
                                previousAssisted,
                                previousTeleport,
                                previousFailed,
                                previousVerified,
                                disabled = edge.Disabled
                            });
                        }
                    }
                }

                // 8) R9.6 natural-drop migration. Older builds had no independent DropDown
                // semantic, so a grounded -> airborne -> lower grounded route could be coalesced into
                // WalkThrough. Short, steep descending WalkThrough geometry is reclassified once,
                // while its old executor statistics are discarded because they describe the wrong
                // movement policy. Long ramps remain WalkThrough.
                bool r96NaturalDropMigration = loadedTraversalSanitizerRevision < 8;
                if (r96NaturalDropMigration)
                {
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge) ||
                            !edge.PlayerValidated ||
                            !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        float planar = GetPlanarDistance(edge.RawStart, edge.RawEnd);
                        float rawDrop = edge.RawStart.y - edge.RawEnd.y;
                        float settledDrop = edge.HasSettledStart && edge.HasSettledEnd &&
                                            IsFinite(edge.SettledStart) && IsFinite(edge.SettledEnd)
                            ? edge.SettledStart.y - edge.SettledEnd.y
                            : rawDrop;
                        float strongestDrop = Mathf.Max(rawDrop, settledDrop);
                        float steepness = strongestDrop / Mathf.Max(0.20f, planar);
                        bool looksLikeNaturalDrop = strongestDrop >= 0.60f &&
                                                    strongestDrop <= PlayerNaturalDropDownMaxVerticalDrop &&
                                                    planar <= 2.75f &&
                                                    steepness >= 0.30f;
                        if (!looksLikeNaturalDrop)
                        {
                            continue;
                        }

                        string oldExperienceKey = edge.ExperienceKey;
                        if (!string.IsNullOrWhiteSpace(oldExperienceKey))
                        {
                            removedExperienceKeys.Add(oldExperienceKey);
                        }

                        edge.ExperienceKey = CreateTraversalExperienceKey();
                        edge.Kind = "DropDown";
                        edge.Verified = false;
                        edge.SuccessfulExecutions = 0;
                        edge.NativeSuccessCount = 0;
                        edge.AssistedSuccessCount = 0;
                        edge.TeleportFallbackCount = 0;
                        edge.FailedExecutions = 0;
                        edge.WalkThroughCorridorSamples = new List<Vector3>();
                        edge.EgressSamples = new List<Vector3>();
                        edge.EgressSemanticSamples = new List<TraversalEgressSemanticSample>();
                        edge.MotionSamples = new List<TraversalMotionSample>();
                        edge.ObstacleFingerprint = null;
                        edge.NativeVaultParameters = null;

                        bool credibleLanding = edge.HasSettledEnd && IsFinite(edge.SettledEnd);
                        if (!credibleLanding &&
                            TrySampleTraversalSettledAnchor(edge.RawEnd, TraversalSettledCaptureNavRadius, out Vector3 migratedLanding))
                        {
                            edge.HasSettledEnd = true;
                            edge.SettledEnd = migratedLanding;
                            credibleLanding = true;
                        }
                        edge.Disabled = !credibleLanding;
                        FollowerRuntimeNavMeshLinks.Remove(edge.Id);
                        ClearCommitmentsForEdge(edge.Id);
                        reasons.Add(new
                        {
                            reason = "r9_6WalkThroughReclassifiedAsDropDown",
                            edgeId = edge.Id,
                            oldExperienceKey,
                            newExperienceKey = edge.ExperienceKey,
                            rawDrop,
                            settledDrop,
                            planar,
                            steepness,
                            credibleLanding,
                            disabled = edge.Disabled
                        });
                    }

                    // The old Jump downstream-island verifier could credit a physically crossed jump
                    // as repeated TeleportRejected/SemanticEgress failures solely because it selected
                    // a pre-landing breadcrumb behind the follower. Those policy failures must not
                    // depress confidence after R9.6 fixes the landing release. Preserve the learned
                    // geometry/key, but remove only strongly identifiable contaminated experience.
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge) ||
                            !edge.PlayerValidated ||
                            !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                            string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                            !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord experience) ||
                            experience == null)
                        {
                            continue;
                        }

                        bool contaminatedSemanticEgress =
                            string.Equals(experience.LastReason, "verifyIslandBridgeExhausted", StringComparison.Ordinal) &&
                            string.Equals(experience.LastFailureAttribution, "SemanticEgress", StringComparison.Ordinal) &&
                            experience.TeleportRejected >= 2 &&
                            experience.EgressFailures >= 2 &&
                            experience.NativeSuccesses == 0 &&
                            experience.CleanPhysicalSuccesses == 0;
                        if (!contaminatedSemanticEgress)
                        {
                            continue;
                        }

                        removedExperienceKeys.Add(edge.ExperienceKey);
                        int previousFailedExecutions = edge.FailedExecutions;
                        edge.FailedExecutions = 0;
                        if (edge.HasSettledEnd && IsFinite(edge.SettledEnd))
                        {
                            edge.Disabled = false;
                        }
                        reasons.Add(new
                        {
                            reason = "r9_6JumpSemanticEgressExperienceReset",
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            previousFailedExecutions,
                            attempts = experience.Attempts,
                            egressFailures = experience.EgressFailures,
                            teleportRejected = experience.TeleportRejected,
                            previousConfidence = experience.Confidence,
                            lastReason = experience.LastReason,
                            lastFailureAttribution = experience.LastFailureAttribution
                        });
                    }
                }

                // 9) R9.7 DropDown topology repair. R9.6 could accept NavMesh.SamplePosition
                // results from the lower floor as the entry anchor for a ledge demonstration. Repair
                // the top-side anchor from RawStart/ApproachDirection when possible. If no credible
                // top polygon exists, keep the demonstration but disable replay rather than letting a
                // follower already on the lower floor re-enter the DropDown. Recovery-only statistics
                // from the bad topology are discarded so the repaired executor starts with clean data.
                bool r97DropDownTopologyMigration = loadedTraversalSanitizerRevision < 9;
                if (r97DropDownTopologyMigration)
                {
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge) ||
                            !string.Equals(edge.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                            !edge.PlayerValidated)
                        {
                            continue;
                        }

                        float previousEntryVertical = IsFinite(edge.A)
                            ? Mathf.Abs(edge.A.y - edge.RawStart.y)
                            : float.PositiveInfinity;
                        bool entrySuspicious = previousEntryVertical > DropDownTopEntryMaxVerticalSampleOffset;
                        bool credibleTop = TrySampleCredibleDropDownTopEntry(
                            edge.RawStart,
                            edge.ApproachDirection,
                            out Vector3 repairedTop);
                        if (!entrySuspicious && credibleTop)
                        {
                            continue;
                        }

                        Vector3 previousA = edge.A;
                        bool previousDisabled = edge.Disabled;
                        int previousSuccessful = edge.SuccessfulExecutions;
                        int previousNative = edge.NativeSuccessCount;
                        int previousAssisted = edge.AssistedSuccessCount;
                        int previousTeleport = edge.TeleportFallbackCount;
                        int previousFailed = edge.FailedExecutions;

                        if (credibleTop)
                        {
                            edge.A = repairedTop;
                            edge.HasSettledStart = true;
                            edge.SettledStart = repairedTop;
                            edge.Disabled = !(edge.HasSettledEnd && IsFinite(edge.SettledEnd));
                        }
                        else
                        {
                            edge.Disabled = true;
                        }

                        bool resetRecoveryOnlyExperience = false;
                        if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                            TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord dropExperience) &&
                            dropExperience != null &&
                            GetTraversalExperiencePhysicalSuccessCount(dropExperience) == 0 &&
                            (dropExperience.TeleportRecoveries > 0 || dropExperience.ForcedEgressRecoveries > 0 ||
                             dropExperience.HardFailures > 0 || dropExperience.EgressFailures > 0))
                        {
                            removedExperienceKeys.Add(edge.ExperienceKey);
                            resetRecoveryOnlyExperience = true;
                        }

                        if (entrySuspicious || resetRecoveryOnlyExperience)
                        {
                            edge.Verified = false;
                            edge.SuccessfulExecutions = 0;
                            edge.NativeSuccessCount = 0;
                            edge.AssistedSuccessCount = 0;
                            edge.TeleportFallbackCount = 0;
                            edge.FailedExecutions = 0;
                            FollowerRuntimeNavMeshLinks.Remove(edge.Id);
                            ClearCommitmentsForEdge(edge.Id);
                        }

                        reasons.Add(new
                        {
                            reason = credibleTop ? "r9_7DropDownTopEntryRepaired" : "r9_7DropDownTopEntryDisabled",
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            previousA = Vec(previousA),
                            repairedA = credibleTop ? Vec(repairedTop) : null,
                            rawStart = Vec(edge.RawStart),
                            previousEntryVertical,
                            previousDisabled,
                            disabled = edge.Disabled,
                            resetRecoveryOnlyExperience,
                            previousSuccessful,
                            previousNative,
                            previousAssisted,
                            previousTeleport,
                            previousFailed
                        });
                    }
                }

                // 10) CompileFix9 sustained-follow migration. Policy V6 could credit a traversal
                // after only a short stable mover observation (or no Follow command at all), then
                // the follower could remain Idle for seconds while the leader ran away. Preserve all
                // player-authored geometry, but reset bot-execution trust so V7 must re-earn it under
                // the stricter physical Follow acknowledgement. Also rehabilitate Jump links that
                // were disabled solely by the old RollingApproach controller-timeout classification.
                bool compileFix9SustainedFollowMigration = loadedTraversalSanitizerRevision < 10;
                if (compileFix9SustainedFollowMigration)
                {
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge) || !edge.PlayerValidated)
                        {
                            continue;
                        }

                        int previousSuccessful = edge.SuccessfulExecutions;
                        int previousNative = edge.NativeSuccessCount;
                        int previousAssisted = edge.AssistedSuccessCount;
                        int previousTeleport = edge.TeleportFallbackCount;
                        int previousFailed = edge.FailedExecutions;
                        bool previousVerified = edge.Verified;
                        bool previousDisabled = edge.Disabled;
                        bool rehabilitatedControllerDisabledJump = false;

                        if (edge.Disabled &&
                            string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                            TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord jumpExperience) &&
                            jumpExperience != null &&
                            string.Equals(jumpExperience.LastFailureAttribution, "ChainPolicy", StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(jumpExperience.LastReason) &&
                            jumpExperience.LastReason.IndexOf("rollingApproachTimeout", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            edge.Disabled = false;
                            rehabilitatedControllerDisabledJump = true;
                        }

                        bool hadExecutionTrust = previousVerified || previousSuccessful > 0 || previousNative > 0 ||
                                                 previousAssisted > 0 || previousTeleport > 0 || previousFailed > 0;
                        if (hadExecutionTrust || rehabilitatedControllerDisabledJump)
                        {
                            edge.Verified = false;
                            edge.SuccessfulExecutions = 0;
                            edge.NativeSuccessCount = 0;
                            edge.AssistedSuccessCount = 0;
                            edge.TeleportFallbackCount = 0;
                            edge.FailedExecutions = 0;
                            resetExecutionStatLinkCount++;
                            ClearCommitmentsForEdge(edge.Id);
                            reasons.Add(new
                            {
                                reason = rehabilitatedControllerDisabledJump
                                    ? "compileFix9RollingApproachJumpRehabilitated"
                                    : "compileFix9SustainedFollowLinkTrustReset",
                                edgeId = edge.Id,
                                experienceKey = edge.ExperienceKey,
                                kind = edge.Kind,
                                previousVerified,
                                previousDisabled,
                                disabled = edge.Disabled,
                                previousSuccessful,
                                previousNative,
                                previousAssisted,
                                previousTeleport,
                                previousFailed
                            });
                        }
                    }
                }

                // 11) CompileFix10 introduces end-to-end Follow reward and executor-attempt
                // counters. Mark the persistence revision even on an otherwise-clean/empty map so
                // this migration is not reconsidered every raid.
                bool compileFix10EndToEndRewardMigration = loadedTraversalSanitizerRevision < 11;
                if (compileFix10EndToEndRewardMigration)
                {
                    reasons.Add(new
                    {
                        reason = "compileFix10EndToEndRewardMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision
                    });
                }

                // 12) CompileFix11 repairs executor-specific end-to-end Follow attribution.
                // CompileFix10 could classify a Native->Assisted rescue as Native at the final
                // ExitAuthority commit, so old per-executor Follow counters are not trustworthy.
                // Preserve aggregate crossing/E2E reward and reset only the four strategy-specific
                // Follow counters; subsequent attempts re-earn credit under the corrected mode.
                bool compileFix11ExecutorFollowCreditMigration = loadedTraversalSanitizerRevision < 12;
                if (compileFix11ExecutorFollowCreditMigration)
                {
                    int repairedExperienceCount = 0;
                    foreach (TraversalExperienceRecord experience in TraversalExperiences.Values)
                    {
                        if (experience == null)
                        {
                            continue;
                        }

                        bool hadStrategyFollowCredit =
                            experience.NativeEndToEndFollowSuccesses != 0 ||
                            experience.NativeFollowResumeFailures != 0 ||
                            experience.AssistedEndToEndFollowSuccesses != 0 ||
                            experience.AssistedFollowResumeFailures != 0;
                        if (!hadStrategyFollowCredit)
                        {
                            continue;
                        }

                        experience.NativeEndToEndFollowSuccesses = 0;
                        experience.NativeFollowResumeFailures = 0;
                        experience.AssistedEndToEndFollowSuccesses = 0;
                        experience.AssistedFollowResumeFailures = 0;
                        repairedExperienceCount++;
                        traversalExperienceDirty = true;
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix11ExecutorFollowCreditMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        repairedExperienceCount,
                        aggregateFollowRewardPreserved = true
                    });
                }

                // 13) CompileFix12 rehabilitates player-authored WalkThroughs that were poisoned
                // only by the old off-NavMesh Verify/recovery feedback loop. Preserve geometry and
                // successful history; clear only the failure evidence whose reason is now known to
                // be controller-policy contamination. The revision marker is also persisted on an
                // otherwise-clean map so this migration runs exactly once.
                bool compileFix12WalkThroughRecoveryMigration = loadedTraversalSanitizerRevision < 13;
                if (compileFix12WalkThroughRecoveryMigration)
                {
                    int rehabilitatedWalkThroughCount = 0;
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
                    {
                        if (edge == null || !edge.PlayerValidated ||
                            !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                            string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                            !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord experience) ||
                            experience == null)
                        {
                            continue;
                        }

                        string lastReason = experience.LastReason ?? string.Empty;
                        bool contaminated =
                            lastReason.IndexOf("verifyTimeoutWithoutHardStuck", StringComparison.OrdinalIgnoreCase) >= 0 ||
                            lastReason.IndexOf("routeRecoveryExhausted", StringComparison.OrdinalIgnoreCase) >= 0 ||
                            lastReason.IndexOf("verifyTimeoutHardStuck", StringComparison.OrdinalIgnoreCase) >= 0;
                        if (!contaminated)
                        {
                            continue;
                        }

                        edge.Disabled = false;
                        edge.FailedExecutions = 0;
                        experience.HardFailures = 0;
                        experience.EgressFailures = 0;
                        experience.ConsecutiveFailures = 0;
                        experience.LastFailureAttribution = "CompileFix12Migration";
                        experience.LastReason = "compileFix12OffNavMeshVerifyRecoveryReset";
                        experience.RecentScore = Mathf.Max(experience.RecentScore, 0.50f);
                        rehabilitatedWalkThroughCount++;
                        traversalExperienceDirty = true;
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix12WalkThroughRecoveryMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        rehabilitatedWalkThroughCount,
                        geometryPreserved = true
                    });
                }

                // 14) CompileFix13 repairs two controller-policy artifacts observed in the
                // CompileFix12 Customs rough-turn run: rejected-airborne merge could replay the
                // episode prefix into CorridorSamples, and the old TurnGate could accumulate 30
                // failures by re-entering the same apex without physical progress. Preserve all
                // authored geometry except exact prefix replays and reset only affected strategy
                // evidence / routeRecoveryExhausted controller failures.
                bool compileFix13WalkThroughOwnershipMigration = loadedTraversalSanitizerRevision < 14;
                if (compileFix13WalkThroughOwnershipMigration)
                {
                    int repairedCorridorCount = 0;
                    int resetSharpTurnExperienceCount = 0;
                    int rehabilitatedTerminalOwnershipCount = 0;
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
                    {
                        if (edge == null || !edge.PlayerValidated ||
                            !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        if (edge.WalkThroughCorridorSamples != null && edge.WalkThroughCorridorSamples.Count >= 4)
                        {
                            int before = edge.WalkThroughCorridorSamples.Count;
                            List<Vector3> repaired = RemoveWalkThroughPrefixReplayContamination(edge.WalkThroughCorridorSamples);
                            if (repaired.Count >= 2 && repaired.Count < before)
                            {
                                edge.WalkThroughCorridorSamples = repaired;
                                repairedCorridorCount++;
                            }
                        }

                        if (string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                            !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord experience) ||
                            experience == null)
                        {
                            continue;
                        }

                        if (experience.WalkThroughSharpTurnExecutorAttempts != 0 ||
                            experience.WalkThroughSharpTurnExecutorSuccesses != 0 ||
                            experience.WalkThroughSharpTurnExecutorFailures != 0)
                        {
                            experience.WalkThroughSharpTurnExecutorAttempts = 0;
                            experience.WalkThroughSharpTurnExecutorSuccesses = 0;
                            experience.WalkThroughSharpTurnExecutorFailures = 0;
                            experience.WalkThroughStepAssistAttempts = 0;
                            experience.WalkThroughStepAssistSuccesses = 0;
                            experience.WalkThroughStepAssistFailures = 0;
                            experience.ConsecutiveFailures = 0;
                            experience.RecentScore = Mathf.Max(experience.RecentScore, 0.45f);
                            resetSharpTurnExperienceCount++;
                            traversalExperienceDirty = true;
                        }

                        string lastReason = experience.LastReason ?? string.Empty;
                        if (lastReason.IndexOf("routeRecoveryExhausted", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            experience.HardFailures = 0;
                            experience.ConsecutiveFailures = 0;
                            experience.LastFailureAttribution = "CompileFix13Migration";
                            experience.LastReason = "compileFix13TerminalRouteOwnershipReset";
                            experience.RecentScore = Mathf.Max(experience.RecentScore, 0.50f);
                            edge.Disabled = false;
                            edge.FailedExecutions = 0;
                            rehabilitatedTerminalOwnershipCount++;
                            traversalExperienceDirty = true;
                        }
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix13WalkThroughOwnershipMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        repairedCorridorCount,
                        resetSharpTurnExperienceCount,
                        rehabilitatedTerminalOwnershipCount
                    });
                }

                // 15) CompileFix14 restores proven Jump far-side knowledge that a later
                // demonstration refresh could erase before its delayed settled-exit capture fired.
                // Only links with prior physical success are eligible, and the candidate must come
                // from their own recorded grounded/NavMesh egress tail and remain directionally
                // credible relative to the current authored Jump.
                bool compileFix14JumpLandingMigration = loadedTraversalSanitizerRevision < 15;
                if (compileFix14JumpLandingMigration)
                {
                    int rehabilitatedJumpLandingCount = 0;
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
                    {
                        if (edge == null || !edge.PlayerValidated || edge.Disabled ||
                            !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                            edge.HasSettledEnd || GetTraversalPhysicalSuccessCount(edge) <= 0 ||
                            edge.EgressSemanticSamples == null || edge.EgressSemanticSamples.Count == 0)
                        {
                            continue;
                        }

                        TraversalEgressSemanticSample candidate = edge.EgressSemanticSamples
                            .Where(sample => sample != null && sample.Grounded && sample.NavMeshSampled &&
                                             IsFinite(sample.Position) && IsFinite(sample.NavMeshPosition))
                            .LastOrDefault();
                        if (candidate == null)
                        {
                            continue;
                        }

                        Vector3 migratedLanding = candidate.Position;
                        if (!IsCredibleSettledExit(edge.Kind, edge.RawStart, edge.RawEnd, migratedLanding))
                        {
                            migratedLanding = candidate.NavMeshPosition;
                        }
                        if (!IsCredibleSettledExit(edge.Kind, edge.RawStart, edge.RawEnd, migratedLanding))
                        {
                            continue;
                        }

                        edge.HasSettledEnd = true;
                        edge.SettledEnd = migratedLanding;
                        edge.Disabled = false;
                        rehabilitatedJumpLandingCount++;
                        reasons.Add(new
                        {
                            reason = "compileFix14ProvenJumpLandingRehabilitated",
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            physicalSuccesses = GetTraversalPhysicalSuccessCount(edge),
                            rawExit = Vec(edge.RawEnd),
                            settledEnd = Vec(migratedLanding)
                        });
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix14JumpDispatchLandingMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        rehabilitatedJumpLandingCount
                    });
                }

                // 16) CompileFix15 repairs Climb links whose delayed settled-exit capture
                // followed the player back down from the actual upper landing. The first grounded
                // locomotion-resume sample close to RawEnd is the Climb completion, even when that
                // upper platform itself is off NavMesh.
                bool compileFix15ClimbUpperLandingMigration = loadedTraversalSanitizerRevision < 16;
                if (compileFix15ClimbUpperLandingMigration)
                {
                    int rehabilitatedClimbLandingCount = 0;
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
                    {
                        if (edge == null || !edge.PlayerValidated ||
                            !string.Equals(edge.Kind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                            edge.EgressSemanticSamples == null || edge.EgressSemanticSamples.Count == 0)
                        {
                            continue;
                        }

                        TraversalEgressSemanticSample candidate = edge.EgressSemanticSamples
                            .FirstOrDefault(sample => sample != null && sample.Grounded &&
                                IsFinite(sample.Position) &&
                                IsLocomotionResumeStateName(sample.State) &&
                                GetPlanarDistance(sample.Position, edge.RawEnd) <= ClimbUpperLandingCaptureMaxPlanarDistance &&
                                sample.Position.y >= edge.RawEnd.y - ClimbUpperLandingMaxBelowRawExit);
                        if (candidate == null)
                        {
                            continue;
                        }

                        Vector3 migratedLanding = candidate.Position;
                        if (candidate.NavMeshSampled && IsFinite(candidate.NavMeshPosition) &&
                            Mathf.Abs(candidate.NavMeshPosition.y - candidate.Position.y) <= UnifiedTraversalVerifyMaxNavVertical)
                        {
                            migratedLanding = candidate.NavMeshPosition;
                        }

                        float oldDistance = edge.HasSettledEnd && IsFinite(edge.SettledEnd)
                            ? Vector3.Distance(edge.RawEnd, edge.SettledEnd)
                            : float.MaxValue;
                        float candidateDistance = Vector3.Distance(edge.RawEnd, migratedLanding);
                        if (edge.HasSettledEnd && oldDistance <= candidateDistance + 0.35f && !edge.Disabled)
                        {
                            continue;
                        }

                        Vector3 previousSettledEnd = edge.SettledEnd;
                        edge.HasSettledEnd = true;
                        edge.SettledEnd = migratedLanding;
                        edge.Disabled = false;
                        edge.FailedExecutions = 0;
                        edge.EgressSamples = new List<Vector3> { candidate.Position };
                        edge.EgressSemanticSamples = new List<TraversalEgressSemanticSample>
                        {
                            CloneTraversalEgressSemanticSample(candidate)
                        };
                        rehabilitatedClimbLandingCount++;

                        if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                            TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord climbExperience) &&
                            climbExperience != null)
                        {
                            climbExperience.PartialCrossings = 0;
                            climbExperience.ConsecutiveFailures = 0;
                            climbExperience.LastFailureAttribution = "CompileFix15Migration";
                            climbExperience.LastReason = "compileFix15ClimbUpperLandingSegmentationReset";
                            climbExperience.RecentScore = Mathf.Max(climbExperience.RecentScore, 0.50f);
                            traversalExperienceDirty = true;
                        }

                        reasons.Add(new
                        {
                            reason = "compileFix15ClimbUpperLandingRehabilitated",
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            rawExit = Vec(edge.RawEnd),
                            previousSettledEnd = IsFinite(previousSettledEnd) ? Vec(previousSettledEnd) : null,
                            settledEnd = Vec(migratedLanding),
                            oldDistance,
                            candidateDistance
                        });
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix15ClimbSegmentationMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        rehabilitatedClimbLandingCount
                    });
                }

                // 17) CompileFix17 clips recorder lead-in/lead-out contamination outside the
                // authored RawStart..RawEnd span. CompileFix16 prepended RawStart in front of those
                // stale samples at runtime, creating a synthetic U-turn and repeatedly selecting
                // SharpTurn/StepAssist against geometry the player never authored.
                bool compileFix17WalkThroughAuthoredSpanMigration = loadedTraversalSanitizerRevision < 17;
                if (compileFix17WalkThroughAuthoredSpanMigration)
                {
                    int repairedWalkThroughCorridorCount = 0;
                    int removedPrefixSampleCount = 0;
                    int removedSuffixSampleCount = 0;
                    int resetAdaptiveSubStrategyCount = 0;
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
                    {
                        if (edge == null || !edge.PlayerValidated ||
                            !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                            edge.WalkThroughCorridorSamples == null || edge.WalkThroughCorridorSamples.Count < 2)
                        {
                            continue;
                        }

                        List<Vector3> repaired = NormalizeWalkThroughCorridorToAuthoredSpan(
                            edge.WalkThroughCorridorSamples,
                            edge.RawStart,
                            edge.RawEnd,
                            out int removedPrefix,
                            out int removedSuffix,
                            out bool reversed);
                        bool geometryChanged = removedPrefix > 0 || removedSuffix > 0 || reversed;
                        if (!geometryChanged || repaired.Count < 2)
                        {
                            continue;
                        }

                        edge.WalkThroughCorridorSamples = repaired;
                        repairedWalkThroughCorridorCount++;
                        removedPrefixSampleCount += removedPrefix;
                        removedSuffixSampleCount += removedSuffix;

                        if (!string.IsNullOrWhiteSpace(edge.ExperienceKey) &&
                            TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord walkExperience) &&
                            walkExperience != null)
                        {
                            walkExperience.WalkThroughSharpTurnExecutorAttempts = 0;
                            walkExperience.WalkThroughSharpTurnExecutorSuccesses = 0;
                            walkExperience.WalkThroughSharpTurnExecutorFailures = 0;
                            walkExperience.WalkThroughStepAssistAttempts = 0;
                            walkExperience.WalkThroughStepAssistSuccesses = 0;
                            walkExperience.WalkThroughStepAssistFailures = 0;
                            walkExperience.ConsecutiveFailures = 0;
                            walkExperience.LastFailureAttribution = "CompileFix17Migration";
                            walkExperience.LastReason = "compileFix17WalkThroughAuthoredSpanClip";
                            walkExperience.LastUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
                            resetAdaptiveSubStrategyCount++;
                            traversalExperienceDirty = true;
                        }

                        reasons.Add(new
                        {
                            reason = "compileFix17WalkThroughCorridorEndpointClipped",
                            edgeId = edge.Id,
                            experienceKey = edge.ExperienceKey,
                            removedPrefix,
                            removedSuffix,
                            reversed,
                            repairedSampleCount = repaired.Count,
                            rawStart = Vec(edge.RawStart),
                            rawEnd = Vec(edge.RawEnd)
                        });
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix17WalkThroughAuthoredSpanMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        repairedWalkThroughCorridorCount,
                        removedPrefixSampleCount,
                        removedSuffixSampleCount,
                        resetAdaptiveSubStrategyCount
                    });
                }

                // 18) CompileFix21 rehabilitates only Jump links falsely disabled because old replay
                // validation measured the follower's approach-to-exit vector as if it were the authored
                // Jump span. Preserve ExperienceKey and all unrelated learned geometry.
                bool compileFix21JumpGeometryMigration = loadedTraversalSanitizerRevision < 18;
                if (compileFix21JumpGeometryMigration)
                {
                    int rehabilitatedJumpGeometryCount = 0;
                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
                    {
                        if (edge == null || !edge.PlayerValidated || !edge.Disabled ||
                            !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                            edge.SuccessfulExecutions > 0 || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                            !TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord jumpExperience) ||
                            jumpExperience == null || GetTraversalExperiencePhysicalSuccessCount(jumpExperience) > 0 ||
                            !string.Equals(jumpExperience.LastFailureAttribution, "Executor", StringComparison.OrdinalIgnoreCase) ||
                            string.IsNullOrWhiteSpace(jumpExperience.LastReason) ||
                            jumpExperience.LastReason.IndexOf("assisted replay geometry rejected", StringComparison.OrdinalIgnoreCase) < 0)
                        {
                            continue;
                        }

                        float authoredDistance = Vector3.Distance(edge.RawStart, edge.RawEnd);
                        float authoredHorizontal = GetPlanarDistance(edge.RawStart, edge.RawEnd);
                        float authoredVertical = edge.RawEnd.y - edge.RawStart.y;
                        bool authoredGeometryValid = IsFinite(edge.RawStart) && IsFinite(edge.RawEnd) &&
                            authoredDistance >= 0.35f &&
                            authoredHorizontal <= PlayerJumpExtendedMaxHorizontalDistance &&
                            Mathf.Abs(authoredVertical) <= PlayerJumpExtendedMaxVerticalDelta;
                        if (!authoredGeometryValid)
                        {
                            continue;
