                // 19) CompileFix25 repairs the end-to-end reward semantics. CompileFix18 recorded
                // movementResumedWithoutFormation only as FormationRecoveryFailures, so old records
                // could show zero FollowResumeFailures despite repeatedly stranding the follower.
                // Preserve physical knowledge, but backfill the complete-transaction failure floor and
                // cap the recent Follow score to its observed Bayesian reliability.
                bool compileFix25EndToEndFollowMigration = loadedTraversalSanitizerRevision < 19;
                if (compileFix25EndToEndFollowMigration)
                {
                    int repairedEndToEndRecordCount = 0;
                    foreach (TraversalExperienceRecord experience in TraversalExperiences.Values.Where(value => value != null))
                    {
                        int previousFailures = Math.Max(0, experience.FollowResumeFailures);
                        int repairedFailures = Math.Max(previousFailures, Math.Max(0, experience.FormationRecoveryFailures));
                        if (repairedFailures > previousFailures)
                        {
                            experience.FollowResumeFailures = repairedFailures;
                            int attempts = Math.Max(0, experience.EndToEndFollowSuccesses) + repairedFailures;
                            float reliability = attempts > 0
                                ? Mathf.Clamp01((Math.Max(0, experience.EndToEndFollowSuccesses) + 1f) / (attempts + 2f))
                                : 0.5f;
                            experience.FollowResumeRecentScore = experience.FollowResumeRecentScore <= 0f
                                ? reliability
                                : Mathf.Min(experience.FollowResumeRecentScore, reliability);
                            if (string.Equals(experience.LastFollowOutcome, "FollowResumedFormationLagging", StringComparison.Ordinal))
                            {
                                experience.ConsecutiveFollowResumeFailures = Math.Max(1, experience.ConsecutiveFollowResumeFailures);
                            }
                            RefreshTraversalExperienceConfidence(experience);
                            repairedEndToEndRecordCount++;
                        }
