                    foreach (LearnedTraversalEdge jumpEdge in LearnedTraversalEdges.ToArray())
                    {
                        if (jumpEdge == null || removedEdges.Contains(jumpEdge) || jumpEdge.Disabled ||
                            !jumpEdge.PlayerValidated ||
                            !string.Equals(jumpEdge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                            jumpEdge.DemonstrationRevision >= JumpSemanticConflictTrustedDemonstrationRevision ||
                            jumpEdge.Verified || jumpEdge.NativeSuccessCount > 0 ||
                            !IsFinite(jumpEdge.RawStart) || !IsFinite(jumpEdge.RawEnd))
                        {
                            continue;
                        }

                        Vector3 jumpCenter = GetTraversalEdgePlanarCenter(jumpEdge);
                        Vector3 jumpDirection = GetFlatDirection(jumpEdge.RawEnd - jumpEdge.RawStart);
                        if (!IsFinite(jumpCenter) || jumpDirection.sqrMagnitude < 0.5f)
                        {
                            continue;
                        }

                        LearnedTraversalEdge bestConflict = null;
                        float bestConflictScore = float.MaxValue;
                        float bestCenterDistance = 0f;
                        float bestStartDistance = 0f;
                        float bestEndDistance = 0f;
                        float bestDirectionDot = 0f;
                        foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges)
                        {
                            if (candidate == null || candidate == jumpEdge || removedEdges.Contains(candidate) ||
                                candidate.Disabled || !candidate.PlayerValidated ||
                                !(string.Equals(candidate.Kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                                  string.Equals(candidate.Kind, "Climb", StringComparison.OrdinalIgnoreCase)) ||
                                !IsFinite(candidate.RawStart) || !IsFinite(candidate.RawEnd))
                            {
                                continue;
                            }

                            Vector3 candidateDirection = GetFlatDirection(candidate.RawEnd - candidate.RawStart);
                            if (candidateDirection.sqrMagnitude < 0.5f)
                            {
                                continue;
                            }
                            float directionDot = Vector3.Dot(jumpDirection, candidateDirection);
                            if (directionDot < JumpSemanticConflictMinDirectionDot)
                            {
                                continue;
                            }

                            float centerDistance = GetPlanarDistance(jumpCenter, GetTraversalEdgePlanarCenter(candidate));
                            float startDistance = GetPlanarDistance(jumpEdge.RawStart, candidate.RawStart);
                            float endDistance = GetPlanarDistance(jumpEdge.RawEnd, candidate.RawEnd);
                            if (centerDistance > JumpSemanticConflictMaxCenterDistance ||
                                startDistance > JumpSemanticConflictMaxStartPlanarDistance ||
                                endDistance > JumpSemanticConflictMaxEndPlanarDistance)
                            {
                                continue;
                            }

                            float score = centerDistance + startDistance + endDistance;
                            if (score < bestConflictScore)
                            {
                                bestConflict = candidate;
                                bestConflictScore = score;
                                bestCenterDistance = centerDistance;
                                bestStartDistance = startDistance;
                                bestEndDistance = endDistance;
                                bestDirectionDot = directionDot;
                            }
                        }

                        if (bestConflict == null)
                        {
                            continue;
                        }

                        removedEdges.Add(jumpEdge);
                        if (!string.IsNullOrWhiteSpace(jumpEdge.ExperienceKey))
                        {
                            removedExperienceKeys.Add(jumpEdge.ExperienceKey);
                        }
                        removedJumpSemanticConflictCount++;
                        reasons.Add(new
                        {
                            reason = "compileFix46JumpVaultClimbSemanticConflictRemoved",
                            jumpEdgeId = jumpEdge.Id,
                            jumpExperienceKey = jumpEdge.ExperienceKey,
                            jumpDemonstrationRevision = jumpEdge.DemonstrationRevision,
                            jumpNativeSuccesses = jumpEdge.NativeSuccessCount,
                            jumpAssistedSuccesses = jumpEdge.AssistedSuccessCount,
                            conflictingEdgeId = bestConflict.Id,
                            conflictingKind = bestConflict.Kind,
                            centerDistance = bestCenterDistance,
                            startDistance = bestStartDistance,
                            endDistance = bestEndDistance,
                            directionDot = bestDirectionDot
                        });
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix46JumpSemanticCleanupMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        removedJumpSemanticConflictCount,
                        repeatedJumpDemonstrationsProtected = true,
                        nativeJumpSuccessProtected = true
                    });
                }

                // 28) CompileFix50 passage sanitizer. The supplied Bigmap database demonstrated
                // that rough-ground NavMesh flicker could create dozens of independent WalkThrough
                // records inside one 3-5 m junk-pile passage, while old disabled DropDowns occupied
                // most of the 256-link capacity. Preserve physically valuable geometry, but remove
                // zero-value disabled links, micro seams without independent topology value, malformed
                // hairpins and same-direction WalkThrough fragments contained by a stronger passage.
                bool compileFix50PassageSanitizerMigration = loadedTraversalSanitizerRevision < 28;
                if (compileFix50PassageSanitizerMigration)
                {
                    int removedDisabledZeroValueCount = 0;
                    int removedMicroWalkThroughCount = 0;
                    int removedMalformedWalkThroughCount = 0;
                    int removedRedundantWalkThroughCount = 0;
                    int simplifiedWalkThroughCount = 0;

                    foreach (LearnedTraversalEdge edge in LearnedTraversalEdges.ToArray())
                    {
                        if (edge == null || removedEdges.Contains(edge))
                        {
                            continue;
                        }

                        int physicalSuccesses = GetTraversalPhysicalSuccessCount(edge);
                        if (edge.Disabled && !IsTraversalEdgeActivelyReferenced(edge.Id))
                        {
                            removedEdges.Add(edge);
                            // Disabled geometry can never be selected again, so it should not occupy
                            // the 256-link capacity. Preserve proven historical experience as orphan
                            // evidence; discard only zero-value experience together with the edge.
                            if (physicalSuccesses <= 0 && !string.IsNullOrWhiteSpace(edge.ExperienceKey))
                            {
                                removedExperienceKeys.Add(edge.ExperienceKey);
                            }
                            removedDisabledZeroValueCount++;
                            reasons.Add(new
                            {
                                reason = "compileFix50DisabledLinkRemoved",
                                edgeId = edge.Id,
                                kind = edge.Kind,
                                demonstrationRevision = edge.DemonstrationRevision,
                                physicalSuccesses,
                                provenExperienceRetained = physicalSuccesses > 0
                            });
                            continue;
                        }

                        if (!string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        float direct = GetPlanarDistance(edge.RawStart, edge.RawEnd);
                        if (direct < WalkThroughStandalonePersistMinDistance && physicalSuccesses <= 0)
                        {
                            removedEdges.Add(edge);
                            if (!string.IsNullOrWhiteSpace(edge.ExperienceKey))
                            {
                                removedExperienceKeys.Add(edge.ExperienceKey);
                            }
                            removedMicroWalkThroughCount++;
                            reasons.Add(new
                            {
                                reason = "compileFix50MicroWalkThroughRemoved",
                                edgeId = edge.Id,
                                directDistance = direct,
                                physicalSuccesses
                            });
                            continue;
                        }

                        if (IsMalformedWalkThroughGeometry(edge, out string malformedReason) && physicalSuccesses <= 0)
                        {
                            removedEdges.Add(edge);
                            if (!string.IsNullOrWhiteSpace(edge.ExperienceKey))
                            {
                                removedExperienceKeys.Add(edge.ExperienceKey);
                            }
                            removedMalformedWalkThroughCount++;
                            reasons.Add(new
                            {
                                reason = "compileFix50MalformedWalkThroughRemoved",
                                edgeId = edge.Id,
                                detail = malformedReason,
                                directDistance = direct,
                                physicalSuccesses
                            });
                            continue;
                        }

                        List<Vector3> simplified = SimplifyWalkThroughPassageSamples(
                            edge.WalkThroughCorridorSamples, edge.RawStart, edge.RawEnd);
                        if (simplified.Count >= 2 &&
                            (edge.WalkThroughCorridorSamples == null || simplified.Count < edge.WalkThroughCorridorSamples.Count))
                        {
                            int before = edge.WalkThroughCorridorSamples?.Count ?? 0;
                            edge.WalkThroughCorridorSamples = simplified;
                            simplifiedWalkThroughCount++;
                            reasons.Add(new
                            {
                                reason = "compileFix50WalkThroughCorridorSimplified",
                                edgeId = edge.Id,
                                beforeSamples = before,
                                afterSamples = simplified.Count
                            });
                        }
                    }

                    LearnedTraversalEdge[] walkThroughs = LearnedTraversalEdges
                        .Where(edge => edge != null && !removedEdges.Contains(edge) &&
                                       string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                        .OrderBy(edge => edge.Id)
                        .ToArray();
                    for (int i = 0; i < walkThroughs.Length; i++)
                    {
                        LearnedTraversalEdge first = walkThroughs[i];
                        if (first == null || removedEdges.Contains(first))
                        {
                            continue;
                        }
                        for (int j = i + 1; j < walkThroughs.Length; j++)
                        {
                            LearnedTraversalEdge second = walkThroughs[j];
                            if (second == null || removedEdges.Contains(second) ||
                                !AreWalkThroughEdgesPassageRedundant(first, second))
                            {
                                continue;
                            }

                            LearnedTraversalEdge winner = CompareWalkThroughPassageValue(first, second) >= 0 ? first : second;
                            LearnedTraversalEdge loser = ReferenceEquals(winner, first) ? second : first;
                            removedEdges.Add(loser);
                            int loserPhysicalSuccesses = GetTraversalPhysicalSuccessCount(loser);
                            // Proven loser experience is retained as orphan evidence by the existing
                            // knowledge-retention pass; zero-value duplicate experience is discarded.
                            if (loserPhysicalSuccesses <= 0 && !string.IsNullOrWhiteSpace(loser.ExperienceKey))
                            {
                                removedExperienceKeys.Add(loser.ExperienceKey);
                            }
                            winner.DemonstrationRevision = Math.Max(winner.DemonstrationRevision, loser.DemonstrationRevision);
                            winner.PlayerValidated = winner.PlayerValidated || loser.PlayerValidated;
                            removedRedundantWalkThroughCount++;
                            reasons.Add(new
                            {
                                reason = "compileFix50RedundantWalkThroughPassageMerged",
                                winnerEdgeId = winner.Id,
                                removedEdgeId = loser.Id,
                                winnerPhysicalSuccesses = GetTraversalPhysicalSuccessCount(winner),
                                removedPhysicalSuccesses = loserPhysicalSuccesses,
                                winnerSpan = GetPlanarDistance(winner.RawStart, winner.RawEnd),
                                removedSpan = GetPlanarDistance(loser.RawStart, loser.RawEnd)
                            });

                            if (ReferenceEquals(loser, first))
                            {
                                first = winner;
                            }
                        }
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix50PassageSanitizerMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        removedDisabledZeroValueCount,
                        removedMicroWalkThroughCount,
                        removedMalformedWalkThroughCount,
                        removedRedundantWalkThroughCount,
                        simplifiedWalkThroughCount,
                        reverseDirectionalSiblingsProtected = true,
                        provenExperienceRetainedAsOrphanEvidence = true
                    });
                }

                // 29) CompileFix51 re-runs cross-kind Jump semantic cleanup with the same
                // planar/vertical topology used by live learning. CompileFix46 ran before edge260
                // existed, so a one-off Jump learned later on top of a Vault/Climb could survive
                // indefinitely despite zero physical success.
                bool compileFix51CrossKindJumpCleanupMigration = loadedTraversalSanitizerRevision < 29;
                if (compileFix51CrossKindJumpCleanupMigration)
                {
                    int removedCrossKindJumpCount = 0;
                    foreach (LearnedTraversalEdge jumpEdge in LearnedTraversalEdges.ToArray())
                    {
                        if (jumpEdge == null || removedEdges.Contains(jumpEdge) || jumpEdge.Disabled ||
                            !jumpEdge.PlayerValidated ||
                            !string.Equals(jumpEdge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                            jumpEdge.DemonstrationRevision >= CrossKindJumpAlternativeRequiredDemonstrations ||
                            jumpEdge.Verified || jumpEdge.NativeSuccessCount > 0 ||
                            GetTraversalPhysicalSuccessCount(jumpEdge) > 0 ||
                            !IsFinite(jumpEdge.RawStart) || !IsFinite(jumpEdge.RawEnd))
                        {
                            continue;
                        }

                        if (!TryFindVaultClimbSemanticSibling(
                                jumpEdge.RawStart,
                                jumpEdge.RawEnd,
                                out LearnedTraversalEdge sibling,
                                out bool siblingReversed) ||
                            sibling == null || removedEdges.Contains(sibling))
                        {
                            continue;
                        }

                        removedEdges.Add(jumpEdge);
                        if (!string.IsNullOrWhiteSpace(jumpEdge.ExperienceKey))
                        {
                            removedExperienceKeys.Add(jumpEdge.ExperienceKey);
                        }
                        removedCrossKindJumpCount++;
                        reasons.Add(new
                        {
                            reason = "compileFix51OneOffJumpOverVaultClimbRemoved",
                            jumpEdgeId = jumpEdge.Id,
                            jumpExperienceKey = jumpEdge.ExperienceKey,
                            jumpDemonstrationRevision = jumpEdge.DemonstrationRevision,
                            conflictingEdgeId = sibling.Id,
                            conflictingKind = sibling.Kind,
                            siblingReversed,
                            physicalSuccesses = GetTraversalPhysicalSuccessCount(jumpEdge)
                        });
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix51CrossKindJumpCleanupMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        removedCrossKindJumpCount,
                        repeatedAlternativesProtected = true,
                        physicalSuccessesProtected = true
                    });
                }

                // 30) CompileFix52 exact fresh-duplicate cleanup. Fix50 deliberately used broad
                // passage semantics and therefore only ran once; later runtime learning could still
                // append an exact same-direction WalkThrough twin (for example candidateGap followed
                // immediately by naturalDropConfirmed). Remove only zero-value twins whose authored
                // endpoints are effectively identical. Do not geometrically collapse distinct nearby
                // corridors, reverse directions, or any edge that already owns physical evidence.
                bool compileFix52ExactDuplicateCleanupMigration = loadedTraversalSanitizerRevision < 30;
                if (compileFix52ExactDuplicateCleanupMigration)
                {
                    int removedExactWalkThroughDuplicateCount = 0;
                    LearnedTraversalEdge[] exactDuplicateCandidates = LearnedTraversalEdges
                        .Where(edge => edge != null && !removedEdges.Contains(edge) &&
                                       string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                                       IsFinite(edge.RawStart) && IsFinite(edge.RawEnd))
                        .OrderBy(edge => edge.Id)
                        .ToArray();

                    for (int i = 0; i < exactDuplicateCandidates.Length; i++)
                    {
                        LearnedTraversalEdge first = exactDuplicateCandidates[i];
                        if (first == null || removedEdges.Contains(first)) continue;

                        Vector3 firstDirection = GetFlatDirection(first.RawEnd - first.RawStart);
                        if (firstDirection.sqrMagnitude < 0.5f) continue;

                        for (int j = i + 1; j < exactDuplicateCandidates.Length; j++)
                        {
                            LearnedTraversalEdge second = exactDuplicateCandidates[j];
                            if (second == null || removedEdges.Contains(second)) continue;
                            if(!FollowerCapabilityPosturePolicy.Same(first.RequiredPose,second.RequiredPose))continue;

                            Vector3 secondDirection = GetFlatDirection(second.RawEnd - second.RawStart);
                            if (secondDirection.sqrMagnitude < 0.5f || Vector3.Dot(firstDirection, secondDirection) < 0.995f)
                            {
                                continue;
                            }

                            float startPlanar = GetPlanarDistance(first.RawStart, second.RawStart);
                            float endPlanar = GetPlanarDistance(first.RawEnd, second.RawEnd);
                            float startVertical = Mathf.Abs(first.RawStart.y - second.RawStart.y);
                            float endVertical = Mathf.Abs(first.RawEnd.y - second.RawEnd.y);
                            if (startPlanar > 0.10f || endPlanar > 0.10f ||
                                startVertical > 0.12f || endVertical > 0.12f)
                            {
                                continue;
                            }

                            int firstPhysical = GetTraversalPhysicalSuccessCount(first);
                            int secondPhysical = GetTraversalPhysicalSuccessCount(second);
                            if (firstPhysical > 0 && secondPhysical > 0)
                            {
                                // Two independently proven records are left untouched. Their geometry
                                // may look identical after quantization but their execution history is
                                // valuable and sanitizer30 must not guess which identity is canonical.
                                continue;
                            }

                            LearnedTraversalEdge winner;
                            LearnedTraversalEdge loser;
                            if (firstPhysical != secondPhysical)
                            {
                                winner = firstPhysical > secondPhysical ? first : second;
                            }
                            else if (first.DemonstrationRevision != second.DemonstrationRevision)
                            {
                                winner = first.DemonstrationRevision > second.DemonstrationRevision ? first : second;
                            }
                            else if (first.PlayerTraversalSequence != second.PlayerTraversalSequence)
                            {
                                winner = first.PlayerTraversalSequence > second.PlayerTraversalSequence ? first : second;
                            }
                            else
                            {
                                winner = first.Id <= second.Id ? first : second;
                            }
                            loser = ReferenceEquals(winner, first) ? second : first;

                            int loserPhysical = GetTraversalPhysicalSuccessCount(loser);
                            if (loserPhysical > 0)
                            {
                                // Never discard the only proven identity in a pair.
                                continue;
                            }

                            removedEdges.Add(loser);
                            if (!string.IsNullOrWhiteSpace(loser.ExperienceKey))
                            {
                                removedExperienceKeys.Add(loser.ExperienceKey);
                            }
                            winner.DemonstrationRevision = Math.Max(winner.DemonstrationRevision, loser.DemonstrationRevision);
                            winner.PlayerValidated = winner.PlayerValidated || loser.PlayerValidated;
                            winner.PlayerTraversalSequence = Math.Max(winner.PlayerTraversalSequence, loser.PlayerTraversalSequence);
                            removedExactWalkThroughDuplicateCount++;
                            reasons.Add(new
                            {
                                reason = "compileFix52ExactWalkThroughDuplicateRemoved",
                                winnerEdgeId = winner.Id,
                                removedEdgeId = loser.Id,
                                winnerPhysicalSuccesses = GetTraversalPhysicalSuccessCount(winner),
                                removedPhysicalSuccesses = loserPhysical,
                                startPlanar,
                                endPlanar,
                                startVertical,
                                endVertical
                            });

                            if (ReferenceEquals(loser, first))
                            {
                                first = winner;
                                firstDirection = GetFlatDirection(first.RawEnd - first.RawStart);
                            }
                        }
                    }

                    reasons.Add(new
                    {
                        reason = "compileFix52ExactDuplicateCleanupMigration",
                        previousRevision = loadedTraversalSanitizerRevision,
                        revision = TraversalPersistenceSanitizerRevision,
                        removedExactWalkThroughDuplicateCount,
                        exactGeometryOnly = true,
                        reverseDirectionalSiblingsProtected = true,
                        dualProvenRecordsProtected = true
                    });
                }

                // 24) Duplicate keys are ambiguous even when the kind matches. Preserve the first
                // edge, assign fresh experience identities to siblings, and discard the ambiguous
                // old experience so future learning starts clean rather than sharing statistics.
                foreach (IGrouping<string, LearnedTraversalEdge> group in LearnedTraversalEdges
                    .Where(edge => edge != null && !removedEdges.Contains(edge) && !string.IsNullOrWhiteSpace(edge.ExperienceKey))
                    .GroupBy(edge => edge.ExperienceKey, StringComparer.Ordinal)
                    .Where(group => group.Count() > 1))
                {
                    LearnedTraversalEdge[] duplicates = group.OrderBy(edge => edge.Id).ToArray();
                    removedExperienceKeys.Add(group.Key);
                    for (int i = 1; i < duplicates.Length; i++)
                    {
                        string oldKey = duplicates[i].ExperienceKey;
                        duplicates[i].ExperienceKey = CreateTraversalExperienceKey();
                        rekeyedExperienceLinkCount++;
                        reasons.Add(new
                        {
                            reason = "duplicateExperienceKeyRekeyed",
                            edgeId = duplicates[i].Id,
                            oldExperienceKey = oldKey,
                            newExperienceKey = duplicates[i].ExperienceKey,
                            kind = duplicates[i].Kind
                        });
                    }
                }

                if (removedEdges.Count > 0)
                {
                    foreach (LearnedTraversalEdge edge in removedEdges.Distinct().ToArray())
                    {
                        LearnedTraversalEdges.Remove(edge);
                        FollowerRuntimeNavMeshLinks.Remove(edge.Id);
                        ClearCommitmentsForEdge(edge.Id);
                    }
                }

                foreach (string key in removedExperienceKeys)
                {
                    if (TraversalExperiences.Remove(key))
                    {
                        removedExperienceRecordCount++;
                    }
                }

                // Orphan experience records have no geometry to execute and can only contaminate a
                // future edge if an identity is accidentally reused. Remove them automatically.
                HashSet<string> liveKeys = new HashSet<string>(
                    LearnedTraversalEdges
                        .Where(edge => edge != null && !string.IsNullOrWhiteSpace(edge.ExperienceKey))
                        .Select(edge => edge.ExperienceKey),
                    StringComparer.Ordinal);
                foreach (string key in TraversalExperiences.Keys.Where(key => !liveKeys.Contains(key)).ToArray())
                {
                    TraversalExperienceRecord orphan = TraversalExperiences[key];
                    int orphanPhysicalSuccesses = GetTraversalExperiencePhysicalSuccessCount(orphan);
                    if (orphanPhysicalSuccesses > 0)
                    {
                        // R9.7 knowledge retention: older FIFO pruning could delete a proven link
                        // while leaving its high-value experience behind. Do not destroy that last
                        // evidence during sanitization. The optional repair tool can reconstruct a
                        // WalkThrough geometry from diagnostics when available.
                        reasons.Add(new
                        {
                            reason = "orphanProvenExperiencePreserved",
                            experienceKey = key,
                            kind = orphan?.Kind,
                            physicalSuccesses = orphanPhysicalSuccesses,
                            attempts = orphan?.Attempts ?? 0
                        });
                        continue;
                    }

                    if (TraversalExperiences.Remove(key))
                    {
                        removedExperienceRecordCount++;
                    }
                    removedExperienceKeys.Add(key);
                    reasons.Add(new { reason = "orphanExperienceRemoved", experienceKey = key });
                }

                // CompileFix54: informational preservation diagnostics are not mutations.
                // orphanProvenExperiencePreserved used to make reasons.Count > 0 every raid, which
                // falsely marked a clean database changed, cleared/rebuilt the runtime episode index,
                // emitted every persistent episode twice, and rewrote both persistence files.
                bool changed = removedEdges.Count > 0 || removedExperienceRecordCount > 0 ||
                               rekeyedExperienceLinkCount > 0 || resetExecutionStatLinkCount > 0 || traversalExperienceDirty ||
                               r8122DemonstrationIntegrityMigration || r96NaturalDropMigration ||
                               r97DropDownTopologyMigration || compileFix9SustainedFollowMigration ||
                               compileFix10EndToEndRewardMigration || compileFix11ExecutorFollowCreditMigration ||
                               compileFix12WalkThroughRecoveryMigration || compileFix13WalkThroughOwnershipMigration ||
                               compileFix21JumpGeometryMigration || compileFix25EndToEndFollowMigration ||
                               compileFix31PolicyV9Migration || compileFix32PolicyV10Migration ||
                               compileFix46JumpSemanticCleanupMigration || compileFix50PassageSanitizerMigration ||
                               compileFix51CrossKindJumpCleanupMigration || compileFix52PolicyV16Migration ||
                               compileFix52ExactDuplicateCleanupMigration;
                if (!changed)
                {
                    WriteEvent("traversalDatabaseSanitizerCompleted", null, new
                    {
                        revision = TraversalPersistenceSanitizerRevision,
                        changed = false,
                        links = LearnedTraversalEdges.Count,
                        experiences = TraversalExperiences.Count,
                        informationalReasonCount = reasons.Count
                    });
                    return;
                }

                // Sanitization occurs before followers are attached, so rebuild the raid-local episode
                // index from the surviving geometry instead of trying to surgically repair chain ids.
                TraversalEpisodesByEdge.Clear();
                TraversalEpisodeStream.Clear();
                traversalEpisodeSequence = 0;
                traversalChainSequence = 0;
                foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
                {
                    if (edge != null)
                    {
                        RegisterTraversalEpisodeForEdge(edge.Id, edge.Kind, edge.RawStart, edge.RawEnd, 0, 0, false);
                    }
                }

                traversalExperienceDirty = true;
                SavePersistentTraversalLinks();
                SaveTraversalExperience();
                WriteEvent("traversalDatabaseSanitized", null, new
                {
                    revision = TraversalPersistenceSanitizerRevision,
                    changed = true,
                    removedLinkCount = removedEdges.Distinct().Count(),
                    removedExperienceCount = removedExperienceRecordCount,
                    remainingLinks = LearnedTraversalEdges.Count,
                    remainingExperiences = TraversalExperiences.Count,
                    resetExecutionStatLinkCount,
                    reasons = reasons.ToArray()
                });
                LogInfo($"CompileFix50 traversal sanitizer repaired/removed contaminated traversal data: removed {removedEdges.Distinct().Count()} link(s), reset {resetExecutionStatLinkCount} execution-stat link(s), and removed {removedExperienceRecordCount} stale/policy experience record(s).");
            }
            catch (Exception ex)
            {
                LogError("traversal persistence sanitizer failed: " + ex.Message);
            }
        }

        private static Vector3 GetTraversalEdgePlanarCenter(LearnedTraversalEdge edge)
        {
            if (edge == null)
            {
                return default(Vector3);
            }
            Vector3 start = IsFinite(edge.RawStart) ? edge.RawStart : edge.A;
            Vector3 end = IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B;
            if (!IsFinite(start) || !IsFinite(end))
            {
                return default(Vector3);
            }
            Vector3 center = (start + end) * 0.5f;
            center.y = 0f;
            return center;
        }

        private static bool AreWalkThroughEdgesPassageRedundant(
            LearnedTraversalEdge first,
            LearnedTraversalEdge second)
        {
            if (first == null || second == null || first == second ||
                !string.Equals(first.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(second.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !IsFinite(first.RawStart) || !IsFinite(first.RawEnd) ||
                !IsFinite(second.RawStart) || !IsFinite(second.RawEnd))
            {
                return false;
            }

            Vector3 firstDirection = GetFlatDirection(first.RawEnd - first.RawStart);
            Vector3 secondDirection = GetFlatDirection(second.RawEnd - second.RawStart);
            if (firstDirection.sqrMagnitude < 0.5f || secondDirection.sqrMagnitude < 0.5f ||
                Vector3.Dot(firstDirection, secondDirection) < 0.92f)
            {
                return false;
            }

            // Opposite-direction passages never reach this point. Same-direction micro fragments
            // are redundant when both endpoints lie close to the other authored segment or their
            // corresponding entry/exit anchors are nearly identical.
            float correspondingStart = GetPlanarDistance(first.RawStart, second.RawStart);
            float correspondingEnd = GetPlanarDistance(first.RawEnd, second.RawEnd);
            bool endpointsNear = FollowerCapabilityHelperRules.AreWalkThroughEdgesPassageRedundant_endpointsNear_5EA58FC2_1(correspondingStart,correspondingEnd) &&
                                 Mathf.Abs(first.RawStart.y - second.RawStart.y) <= 0.85f &&
                                 Mathf.Abs(first.RawEnd.y - second.RawEnd.y) <= 0.95f;
            bool firstContained = GetPlanarDistanceToSegment(first.RawStart, second.RawStart, second.RawEnd) <= 0.70f &&
                                  GetPlanarDistanceToSegment(first.RawEnd, second.RawStart, second.RawEnd) <= 0.70f;
            bool secondContained = GetPlanarDistanceToSegment(second.RawStart, first.RawStart, first.RawEnd) <= 0.70f &&
                                   GetPlanarDistanceToSegment(second.RawEnd, first.RawStart, first.RawEnd) <= 0.70f;
            float centerDistance = GetPlanarDistance(GetTraversalEdgePlanarCenter(first), GetTraversalEdgePlanarCenter(second));
            return centerDistance <= 1.65f && (endpointsNear || firstContained || secondContained);
        }

        private static int CompareWalkThroughPassageValue(LearnedTraversalEdge first, LearnedTraversalEdge second)
        {
            if (ReferenceEquals(first, second)) return 0;
            if (first == null) return -1;
            if (second == null) return 1;

            int firstPhysical = GetTraversalPhysicalSuccessCount(first);
            int secondPhysical = GetTraversalPhysicalSuccessCount(second);
            if (firstPhysical != secondPhysical)
            {
                return firstPhysical.CompareTo(secondPhysical);
            }
            if (first.Verified != second.Verified)
            {
                return first.Verified ? 1 : -1;
            }
            if (first.PlayerValidated != second.PlayerValidated)
            {
                return first.PlayerValidated ? 1 : -1;
            }

            float firstSpan = GetPlanarDistance(first.RawStart, first.RawEnd);
            float secondSpan = GetPlanarDistance(second.RawStart, second.RawEnd);
            bool firstPassage = firstSpan >= WalkThroughStandalonePersistMinDistance;
            bool secondPassage = secondSpan >= WalkThroughStandalonePersistMinDistance;
            if (firstPassage != secondPassage)
            {
                return firstPassage ? 1 : -1;
            }
            if (first.DemonstrationRevision != second.DemonstrationRevision)
            {
                return first.DemonstrationRevision.CompareTo(second.DemonstrationRevision);
            }
            if (Mathf.Abs(firstSpan - secondSpan) > 0.05f)
            {
                return firstSpan.CompareTo(secondSpan);
            }
            return first.Id.CompareTo(second.Id);
        }

        private static void SaveTraversalExperience()
        {
            {
                traversalExperienceDirty = false;
                nextTraversalExperienceSaveAt = Time.time + TraversalExperienceSaveIntervalSeconds;
                return;
            }
            try
            {
                if (!raidActive || string.IsNullOrWhiteSpace(locationId))
                {
                    return;
                }
                PersistentTraversalExperienceDatabase database = new PersistentTraversalExperienceDatabase
                {
                    SchemaVersion = TraversalExperienceSchemaVersion,
                    Edges = TraversalExperiences.Values
                        .Where(record => record != null && !string.IsNullOrWhiteSpace(record.ExperienceKey))
                        .OrderBy(record => record.Kind)
                        .ThenBy(record => record.ExperienceKey)
                        .ToList()
                };
                File.WriteAllText(GetTraversalExperiencePath(), JsonConvert.SerializeObject(database, Formatting.Indented));
                traversalExperienceDirty = false;
                nextTraversalExperienceSaveAt = Time.time + TraversalExperienceSaveIntervalSeconds;
            }
            catch (Exception ex)
            {
                LogError("traversal experience save failed: " + ex.Message);
            }
        }

        private static string ClassifyTraversalOutcome(ProbeRuntime probe, bool success, TraversalCompletionMode completionMode, string reason)
        {
            string text = reason ?? string.Empty;
            if (text.IndexOf("combat", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("abort", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("manual", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Interrupted";
            }
            if (text.IndexOf("exitAuthority", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("movementWriterGenerationSuperseded", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.StartsWith("chainSuccessorMovementAuthorityContaminated:", StringComparison.OrdinalIgnoreCase) ||
                probe?.JumpPostLandingCommitPolicyFailure == true)
            {
                return "AuthorityHandoffFailure";
            }
            if (text.IndexOf("assisted replay geometry rejected", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("assisted V2 geometry rejected", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "SelectionGeometryMiss";
            }
            if (probe?.TraversalTeleportAttempted == true || probe?.TeleportFallbackUsed == true || completionMode == TraversalCompletionMode.TeleportFallback)
            {
                return success ? "TeleportRecovered" : "TeleportRejected";
            }
            if (success && probe?.RecoveryExitAlreadySatisfied == true)
            {
                return "ForcedEgressRecovery";
            }
            // LearningV2A.1 reward contract: forced egress is recovery, even when the native landing
            // was rejected and Assisted happened to move the body across first. Recovery semantics
            // outrank executor labels so the scorer never learns a false clean Assisted success.
            if (success && probe != null &&
                probe.UnifiedEgressForcedDistance >= ForcedEgressRecoveryDistance &&
                !probe.IslandExitNominalClimbTopBridge)
            {
                return "ForcedEgressRecovery";
            }
            if (probe?.TraversalEgressTimedOut == true)
            {
                return "EgressFailure";
            }
            if (text.IndexOf("dropBack", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("dropped back", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "DropBack";
            }
            if (!success)
            {
                return probe?.AssistedReplayAttempted == true || probe?.NativeTraversalStarted == true
                    ? "PartialCrossing"
                    : "HardFailure";
            }
            if (success && probe?.NativeLandingRejected == true)
            {
                return probe.AssistedReplayAttempted
                    ? "NativeLandingRejectedAssistRecovered"
                    : "NativeLandingRejectedRunOutRecovered";
            }
            if (success && probe?.AssistedPartialNativeContinuation == true)
            {
                return "NativePartialAssistedSuccess";
            }
            if (probe?.TraversalEgressAttempted == true && probe.TraversalEgressCompleted)
            {
                if (probe.UnifiedEgressForcedDistance >= ForcedEgressRecoveryDistance &&
                    !probe.IslandExitNominalClimbTopBridge)
                {
                    return "ForcedEgressRecovery";
                }
                return "FullEgressSuccess";
            }
            if (completionMode == TraversalCompletionMode.Native)
            {
                return "NativeSuccess";
            }
            if (completionMode == TraversalCompletionMode.AssistedReplay)
            {
                return "AssistedCrossingSuccess";
            }
            return "CleanPhysicalSuccess";
        }

        private static string ClassifyTraversalFailureAttribution(ProbeRuntime probe, string outcome, string reason)
        {
            string text = reason ?? string.Empty;
            if (string.Equals(outcome, "AuthorityHandoffFailure", StringComparison.Ordinal))
            {
                return "AuthorityHandoff";
            }
            if (string.Equals(outcome, "SelectionGeometryMiss", StringComparison.Ordinal))
            {
                return "SelectionGeometry";
            }
            if (text.IndexOf("commitment", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("missedTraversal", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("chain", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "ChainPolicy";
            }
            if (probe?.TraversalEgressTimedOut == true ||
                text.IndexOf("egress", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return string.Equals(probe?.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase)
                    ? "SemanticEgress"
                    : (probe?.NativeRunOutActive == true ? "NativeRunOut" : "EgressPolicy");
            }
            if (string.Equals(outcome, "TeleportRecovered", StringComparison.Ordinal) ||
                string.Equals(outcome, "TeleportRejected", StringComparison.Ordinal) ||
                string.Equals(outcome, "ForcedEgressRecovery", StringComparison.Ordinal))
            {
                return "RecoveryPolicy";
            }
            if (string.Equals(outcome, "HardFailure", StringComparison.Ordinal) ||
                string.Equals(outcome, "PartialCrossing", StringComparison.Ordinal))
            {
                return "Executor";
            }
            return "None";
        }

        private static void RefreshTraversalExperienceConfidence(TraversalExperienceRecord record)
        {
            if (record == null)
            {
                return;
            }

            int accumulatedPhysicalSuccesses = GetTraversalExperiencePhysicalSuccessCount(record);
            float evidence = Mathf.Clamp01(record.Attempts / 8f);
            float crossingReliability = record.Attempts > 0
                ? Mathf.Clamp01((accumulatedPhysicalSuccesses + 1f) / (record.Attempts + 2f))
                : 0f;
            float effectiveScore = GetTraversalExperienceEffectiveScore(record);
            float confidence = Mathf.Clamp01(Mathf.Lerp(effectiveScore, crossingReliability, 0.55f) * evidence);

            int followAttempts = Math.Max(0, record.EndToEndFollowSuccesses) + GetEndToEndFollowFailureCount(record);
            float followReliability = 0.5f;
            if (followAttempts > 0)
            {
                followReliability = Mathf.Clamp01(
                    (Math.Max(0, record.EndToEndFollowSuccesses) + 1f) / (followAttempts + 2f));
                float followEvidence = Mathf.Clamp01(followAttempts / 6f);
                float followFactor = Mathf.Lerp(1f, Mathf.Lerp(0.55f, 1.10f, followReliability), followEvidence);
                confidence = Mathf.Clamp01(confidence * followFactor);
            }

            bool followHealthy = followAttempts == 0 || followReliability >= 0.55f;
            if (accumulatedPhysicalSuccesses >= 3 && followHealthy)
            {
                confidence = Mathf.Max(confidence, 0.55f);
            }
            if (accumulatedPhysicalSuccesses >= 8 &&
                (followAttempts == 0 || followReliability >= 0.70f))
            {
                confidence = Mathf.Max(confidence, 0.75f);
            }
            record.Confidence = Mathf.Clamp01(confidence);
        }

        private static void RecordTraversalExperience(
            ProbeRuntime probe,
            bool success,
            TraversalCompletionMode completionMode,
            string reason,
            int edgeIdOverride = 0)
        {
            int experienceEdgeId = edgeIdOverride > 0 ? edgeIdOverride : (probe?.LearnedEdgeId ?? 0);
            if (probe == null || experienceEdgeId <= 0)
            {
                return;
            }
            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == experienceEdgeId);
            if (edge == null)
            {
                return;
            }
            RecordLearningV322PersistentSkillEvidence(probe, edge, success, completionMode, reason);
            EmitLearningV322TraversalAttemptSummary(probe, success, completionMode, reason, experienceEdgeId);
            {
                string learningV3Outcome = ClassifyTraversalOutcome(probe, success, completionMode, reason);
                bool learningV3RetainableNativeSuccess = success &&
                    IsLearningV3RetainableNativeSuccess(probe, completionMode);
                if (learningV3RetainableNativeSuccess)
                {
                    // In V3.1 a stable native completion remains NativeSuccess even when the older
                    // classifier also observed an egress phase. Egress is transaction detail, not a
                    // different learning authority.
                    learningV3Outcome = "NativeSuccess";
                }
                bool learningV3Interrupted = string.Equals(learningV3Outcome, "Interrupted", StringComparison.Ordinal);
                bool learningV3AuthorityFailure = string.Equals(learningV3Outcome, "AuthorityHandoffFailure", StringComparison.Ordinal);
                bool learningV3SelectionMiss = string.Equals(learningV3Outcome, "SelectionGeometryMiss", StringComparison.Ordinal);
                bool learningV3ExcludedAudit = learningV3Interrupted || learningV3AuthorityFailure || learningV3SelectionMiss;
                bool learningV3NativeAttempted = (WasLearningV330NativeActuatorActuallyAttempted(probe));
                bool learningV3AssistedAttempted = probe.AssistedStrategySelected || probe.AssistedReplayAttempted;
                if (!learningV3ExcludedAudit)
                {
                    learningV2AuditAttempts++;
                    if (learningV3NativeAttempted) learningV2AuditNativeAttempts++;
                    if (learningV3AssistedAttempted) learningV2AuditAssistedAttempts++;
                    if (learningV3RetainableNativeSuccess)
                    {
                        learningV2AuditNativeSuccesses++;
                    }
                    if (string.Equals(learningV3Outcome, "TeleportRecovered", StringComparison.Ordinal))
                    {
                        learningV2AuditTeleportRecoveries++;
                    }
                }

                bool retainNativeExperience = learningV3RetainableNativeSuccess;
                if (!retainNativeExperience)
                {
                    WriteEvent("learningV3TransientOutcomeObserved", probe.Bot, new
                    {
                        edgeId = edge.Id,
                        kind = edge.Kind,
                        outcome = learningV3Outcome,
                        completionMode = completionMode.ToString(),
                        success,
                        nativeAttempted = learningV3NativeAttempted,
                        assistedAttempted = learningV3AssistedAttempted,
                        teleportAttempted = probe.TraversalTeleportAttempted || probe.TeleportFallbackUsed,
                        forcedEgressDistance = probe.UnifiedEgressForcedDistance,
                        entryCorrectionAttempts = probe.LearningV3EntryCorrectionAttempts,
                        retainedExperience = false,
                        reason = reason ?? string.Empty
                    });
                    return;
                }
            }

            if (string.IsNullOrWhiteSpace(edge.ExperienceKey))
            {
                edge.ExperienceKey = CreateTraversalExperienceKey();
                SavePersistentTraversalLinks();
            }
            if (!TraversalExperiences.TryGetValue(edge.ExperienceKey, out TraversalExperienceRecord record) || record == null)
            {
                record = new TraversalExperienceRecord
                {
                    ExperienceKey = edge.ExperienceKey,
                    Kind = edge.Kind,
                    PolicyVersion = TraversalExperiencePolicyVersion,
                    RecentScore = 0.5f
                };
                TraversalExperiences[edge.ExperienceKey] = record;
            }

            string outcome = ClassifyTraversalOutcome(probe, success, completionMode, reason);
            string recoveryPenaltyKey = string.Equals(outcome, "TeleportRejected", StringComparison.Ordinal)
                ? $"{edge.Id}:{edge.DemonstrationRevision}:{outcome}:{reason ?? string.Empty}"
                : string.Empty;
            bool duplicateRecoveryPenalty = !string.IsNullOrEmpty(recoveryPenaltyKey) &&
                                            !TraversalRecoveryPenaltyKeys.Add(recoveryPenaltyKey);
            if (duplicateRecoveryPenalty)
            {
                WriteEvent("traversalRepeatedFailurePenaltySuppressed", probe.Bot, new
                {
                    edgeId = edge.Id,
                    demonstrationRevision = edge.DemonstrationRevision,
                    outcome,
                    reason
                });
            }
            bool interrupted = string.Equals(outcome, "Interrupted", StringComparison.Ordinal);
            bool authorityHandoffFailure = string.Equals(outcome, "AuthorityHandoffFailure", StringComparison.Ordinal);
            bool selectionGeometryMiss = string.Equals(outcome, "SelectionGeometryMiss", StringComparison.Ordinal);
            bool excludedFromAdaptiveLearning = interrupted || authorityHandoffFailure || selectionGeometryMiss || duplicateRecoveryPenalty;
            if (!excludedFromAdaptiveLearning)
            {
                record.Attempts++;
            }
            if (!duplicateRecoveryPenalty)
            {
            switch (outcome)
            {
                case "CleanPhysicalSuccess": record.CleanPhysicalSuccesses++; break;
                case "NativeSuccess": record.NativeSuccesses++; break;
                case "NativePartialAssistedSuccess": record.NativePartialAssistedSuccesses++; break;
                case "AssistedCrossingSuccess": record.AssistedCrossingSuccesses++; break;
                case "FullEgressSuccess": record.FullEgressSuccesses++; break;
                case "ForcedEgressRecovery": record.ForcedEgressRecoveries++; break;
                case "TeleportRecovered": record.TeleportRecoveries++; break;
                case "PartialCrossing": record.PartialCrossings++; break;
                case "EgressFailure": record.EgressFailures++; break;
                case "DropBack": record.DropBacks++; break;
                case "TeleportRejected": record.TeleportRejected++; break;
                case "HardFailure": record.HardFailures++; break;
                case "AuthorityHandoffFailure": record.AuthorityHandoffFailures++; break;
                case "SelectionGeometryMiss": record.SelectionGeometryMisses++; break;
                case "Interrupted": record.Interrupted++; break;
            }
            }
            if (!duplicateRecoveryPenalty && probe.TraversalEgressTimedOut && !string.Equals(outcome, "EgressFailure", StringComparison.Ordinal))
            {
                record.EgressFailures++;
            }
            bool physicalLearningSuccess = success &&
                !string.Equals(outcome, "TeleportRecovered", StringComparison.Ordinal) &&
                !string.Equals(outcome, "ForcedEgressRecovery", StringComparison.Ordinal) &&
                !string.Equals(outcome, "EgressFailure", StringComparison.Ordinal);
            if (physicalLearningSuccess && probe.TraversalEgressAttempted && probe.TraversalEgressCompleted &&
                !string.Equals(outcome, "FullEgressSuccess", StringComparison.Ordinal))
            {
                // R9.7 adaptive-learning integrity: a successful rescue teleport/forced egress
                // proves recovery, not traversal geometry. Never leak recovery completion into the
                // FullEgress physical-success bucket used by sticky trust and smart pruning.
                record.FullEgressSuccesses++;
            }

            bool nativeStrategyAttempted = (WasLearningV330NativeActuatorActuallyAttempted(probe));
            bool assistedStrategyAttempted = probe.AssistedStrategySelected || probe.AssistedReplayAttempted;
            bool teleportStrategyAttempted = probe.TraversalTeleportAttempted || probe.TeleportFallbackUsed ||
                                            completionMode == TraversalCompletionMode.TeleportFallback;
            ;
            if (!excludedFromAdaptiveLearning)
            {
                if (nativeStrategyAttempted) record.NativeExecutorAttempts++;
                if (assistedStrategyAttempted) record.AssistedExecutorAttempts++;
                if (teleportStrategyAttempted) record.TeleportExecutorAttempts++;
                if (string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    record.WalkThroughExecutorAttempts++;
                    if (probe.WalkThroughSharpTurnGateCount > 0)
                    {
                        record.WalkThroughSharpTurnExecutorAttempts += probe.WalkThroughSharpTurnGateCount;
                        record.WalkThroughSharpTurnExecutorSuccesses += Math.Min(
                            probe.WalkThroughSharpTurnCompletedCount,
                            probe.WalkThroughSharpTurnGateCount);
                        record.WalkThroughSharpTurnExecutorFailures += Math.Min(
                            probe.WalkThroughSharpTurnFailures,
                            probe.WalkThroughSharpTurnGateCount);
                    }
                    record.WalkThroughStepAssistAttempts += probe.WalkThroughStepAssistAttempts;
                    record.WalkThroughStepAssistSuccesses += probe.WalkThroughStepAssistSuccesses;
                    record.WalkThroughStepAssistFailures += probe.WalkThroughStepAssistFailures;
                }
            }

            if (probe.AssistedPartialNativeContinuation && physicalLearningSuccess)
            {
                record.AssistedExecutorSuccesses++;
            }
            else if (completionMode == TraversalCompletionMode.Native && physicalLearningSuccess)
            {
                record.NativeExecutorSuccesses++;
            }
            else if (completionMode == TraversalCompletionMode.AssistedReplay && physicalLearningSuccess)
            {
                record.AssistedExecutorSuccesses++;
            }
            if (completionMode == TraversalCompletionMode.TeleportFallback && success) record.TeleportExecutorSuccesses++;
            int accumulatedPhysicalSuccesses = GetTraversalExperiencePhysicalSuccessCount(record);
            bool provenWalkThrough = string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                                     accumulatedPhysicalSuccesses > 0;
            float failureSample = provenWalkThrough ? 0.65f : 0.0f;
            float sampleScore = excludedFromAdaptiveLearning
                ? record.RecentScore
                : (physicalLearningSuccess ? 1.0f : failureSample);
            if (!excludedFromAdaptiveLearning)
            {
                record.RecentScore = Mathf.Clamp01(Mathf.Lerp(record.RecentScore, sampleScore, 0.22f));
                if (provenWalkThrough)
                {
                    // A follower-local stall must not erase globally proven WalkThrough geometry.
                    record.RecentScore = Mathf.Max(record.RecentScore, 0.58f);
                }
                record.ConsecutiveFailures = physicalLearningSuccess ? 0 : record.ConsecutiveFailures + 1;
            }
            float elapsed = Mathf.Max(0f, Time.time - probe.RequestedAt);
            if (!excludedFromAdaptiveLearning)
            {
                record.MeanDuration = record.Attempts <= 1
                    ? elapsed
                    : Mathf.Lerp(record.MeanDuration, elapsed, 1f / Mathf.Min(16f, record.Attempts));
            }
            record.PolicyVersion = TraversalExperiencePolicyVersion;
            record.LastOutcome = outcome;
            record.LastReason = reason;
            record.LastFailureAttribution = ClassifyTraversalFailureAttribution(probe, outcome, reason);
            if (physicalLearningSuccess)
            {
                TraversalRecentFarSideFailureCounts.Remove(edge.Id);
                if (record.RecentScore >= 0.60f)
                {
                    TraversalRecentToxicSuppressUntil.Remove(edge.Id);
                }
            }
            record.LastUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);

            // CompileFix20: a bounded Native exploration sample owns the edge only until its owner
            // reports a terminal traversal outcome. Releasing here prevents a stale 10 s lease from
            // suppressing the next legitimate exploration sample if counters advance quickly.
            if (TraversalExecutorExplorationLeases.TryGetValue(edge.Id, out TraversalExecutorExplorationLease explorationLease) &&
                explorationLease != null &&
                (Time.time >= explorationLease.ExpiresAt ||
                 string.Equals(explorationLease.ProfileId, probe.Bot?.ProfileId ?? string.Empty, StringComparison.Ordinal)))
            {
                TraversalExecutorExplorationLeases.Remove(edge.Id);
                WriteEvent("traversalExecutorExplorationLeaseReleased", probe.Bot, new
                {
                    edgeId = edge.Id,
                    kind = edge.Kind,
                    ownerProfileId = explorationLease.ProfileId ?? string.Empty,
                    reason = Time.time >= explorationLease.ExpiresAt ? "expiredOnOutcome" : "ownerOutcome",
                    outcome
                });
            }

            RefreshTraversalExperienceConfidence(record);
            traversalExperienceDirty = true;
            if (Time.time >= nextTraversalExperienceSaveAt)
            {
                SaveTraversalExperience();
            }

            int followOutcomeAttempts = Math.Max(0, record.EndToEndFollowSuccesses) +
                                       GetEndToEndFollowFailureCount(record);
            WriteEvent("traversalExperienceUpdated", probe.Bot, new
            {
                edgeId = edge.Id,
                experienceKey = edge.ExperienceKey,
                kind = edge.Kind,
                outcome,
                attempts = record.Attempts,
                physicalSuccesses = accumulatedPhysicalSuccesses,
                crossingRate = record.Attempts > 0
                    ? accumulatedPhysicalSuccesses / (float)record.Attempts
                    : 0f,
                endToEndFollowAttempts = followOutcomeAttempts,
                endToEndFollowSuccesses = record.EndToEndFollowSuccesses,
                endToEndFollowRate = followOutcomeAttempts > 0
                    ? record.EndToEndFollowSuccesses / (float)followOutcomeAttempts
                    : 0f,
                nativeExecutor = new
                {
                    attempts = record.NativeExecutorAttempts,
                    successes = record.NativeExecutorSuccesses
                },
                assistedExecutor = new
                {
                    attempts = record.AssistedExecutorAttempts,
                    successes = record.AssistedExecutorSuccesses
                },
                walkThroughSharpTurnExecutor = new
                {
                    attempts = record.WalkThroughSharpTurnExecutorAttempts,
                    successes = record.WalkThroughSharpTurnExecutorSuccesses,
                    failures = record.WalkThroughSharpTurnExecutorFailures
                },
                walkThroughStepAssist = new
                {
                    attempts = record.WalkThroughStepAssistAttempts,
                    successes = record.WalkThroughStepAssistSuccesses,
                    failures = record.WalkThroughStepAssistFailures
                },
                recentScore = record.RecentScore,
                effectiveScore = GetTraversalExperienceEffectiveScore(record),
                followResumeRecentScore = record.FollowResumeRecentScore,
                formationRecoveredSuccesses = record.FormationRecoveredSuccesses,
                formationRecoveryFailures = record.FormationRecoveryFailures,
                confidence = record.Confidence,
                reason
            });
        }

        private static void BeginProbeApproach(ProbeRuntime probe, float alignmentAngle)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            if (!TryFindProbeObstacleApproach(
                    probe,
                    out Vector3 approachTarget,
                    out Vector3 obstaclePoint,
                    out string obstacleCollider,
                    out Vector3 correctedDirection,
                    out string failure))
            {
                probe.ApproachCompleted = true;
                probe.ApproachError = failure;
                WriteEvent("vaultProbeApproachFallback", probe.Bot, new
                {
                    failure,
                    requestedDirection = Vec(probe.RequestedDirection),
                    position = Vec(probe.Bot.Position)
                });

                // If the follower is already pressed against the obstacle, priming in place is
                // exactly the failure mode that produces side-stepping or a stationary vault scan.
                // Refuse that unsafe fallback; release Follow so the next attempt can approach from
                // a valid stand-off instead of locking the bot against the collider.
                if (failure.IndexOf("too close", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    FinishProbeWithoutReanchor(probe, "approachTooClose", failure);
                    return;
                }

                BeginProbePriming(probe, alignmentAngle);
                return;
            }

            if (correctedDirection.sqrMagnitude > 0.5f)
            {
                probe.RequestedDirection = correctedDirection;
            }

            probe.ApproachTarget = approachTarget;
            probe.ApproachObstaclePoint = obstaclePoint;
            probe.ApproachObstacleCollider = obstacleCollider;

            // V1.3.10 learned-edge fast path: once the player has taught this edge, a follower
            // already running in the correct direction should not enter a short GoToPoint that
            // brakes its physical velocity immediately before the native scanner. Backing-off and
            // unknown/non-moving probes still use the conservative approach state.
            if (probe.LearnedEdgeId > 0 &&
                (probe.PreviousSprinting || probe.PreviousRunning) &&
                !probe.ApproachBackingOff &&
                alignmentAngle <= ProbeRollingAlignmentAngle)
            {
                probe.ApproachCompleted = true;
                WriteEvent("vaultProbeLearnedFastApproach", probe.Bot, new
                {
                    learnedEdgeId = probe.LearnedEdgeId,
                    obstaclePoint = Vec(obstaclePoint),
                    obstacleCollider,
                    currentDistance = Vector3.Distance(probe.Bot.Position, obstaclePoint),
                    previousSprinting = probe.PreviousSprinting,
                    previousRunning = probe.PreviousRunning
                });
                BeginProbePriming(probe, alignmentAngle);
                return;
            }

            TransitionProbeStage(probe, ProbeStage.Approaching);
            probe.StageStartedAt = Time.time;
            probe.Bot.Mover.SetBotMoverPause("R1-4E23DFDFEDC4",@probe?.Bot,false);
            probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-4CA9A851F10E",@probe?.Bot);
            float approachSpeed = FollowerCapabilityHelperRules.BeginProbeApproach_approachSpeed_FC888179_1(probe.ApproachBackingOff,probe.PreviousSprinting,probe.PreviousRunning)
                ? ProbeMomentumFullMoveSpeed
                : 0.55f;
            probe.Bot.BotOwnerSetTargetMoveSpeed("R1-210F40518F48",@probe?.Bot,approachSpeed);
            if (probe.PreviousSprinting && !probe.ApproachBackingOff && probe.Bot.Mover?.Sprinting == false)
            {
                probe.Bot.Mover.BotMoverSprint("R1-D6D58798A238",@probe?.Bot,true,false);
            }
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-ADFFC8D47354",@probe?.Bot,probe.RequestedDirection);

            NavMeshPathStatus pathStatus = NavMeshPathStatus.PathInvalid;
            try
            {
                pathStatus = probe.Bot.BotOwnerGoToPoint(
"R1-933FDACB43CD",@probe?.Bot,                    approachTarget,                    false,                    0.10f,                    false,                    false,                    false,                    false,                    false);
            }
            catch (Exception ex)
            {
                probe.ApproachError = ex.GetType().Name + ": " + ex.Message;
            }

            WriteEvent("vaultProbeApproachStarted", probe.Bot, new
            {
                target = Vec(approachTarget),
                obstaclePoint = Vec(obstaclePoint),
                obstacleCollider,
                distance = Vector3.Distance(probe.Bot.Position, approachTarget),
                correctedDirection = Vec(probe.RequestedDirection),
                backingOff = probe.ApproachBackingOff,
                pathStatus = pathStatus.ToString(),
                error = probe.ApproachError
            });

            if (pathStatus == NavMeshPathStatus.PathInvalid)
            {
                probe.ApproachCompleted = true;
                BeginProbePriming(probe, alignmentAngle);
            }
        }

        private static void UpdateProbeApproaching(ProbeRuntime probe)
        {
            if (!ValidateProbePreconditions(probe.Bot, out string failure))
            {
                FinishProbeWithoutReanchor(probe, "preconditionChanged", failure);
                return;
            }

            probe.Bot.Mover.SetBotMoverPause("R1-613142E26BD6",@probe?.Bot,false);
            float approachSpeed = FollowerCapabilityHelperRules.UpdateProbeApproaching_approachSpeed_E7A97DCD_1(probe.ApproachBackingOff,probe.PreviousSprinting,probe.PreviousRunning)
                ? ProbeMomentumFullMoveSpeed
                : 0.55f;
            probe.Bot.BotOwnerSetTargetMoveSpeed("R1-41046964AC9E",@probe?.Bot,approachSpeed);
            if (probe.PreviousSprinting && !probe.ApproachBackingOff && probe.Bot.Mover?.Sprinting == false)
            {
                probe.Bot.Mover.BotMoverSprint("R1-035461AF6AC1",@probe?.Bot,true,false);
            }
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-ADEEE040B6FD",@probe?.Bot,probe.RequestedDirection);

            float distance = Vector3.Distance(probe.Bot.Position, probe.ApproachTarget);
            if (distance <= ProbeApproachArrivalDistance)
            {
                probe.ApproachCompleted = true;
                Vector3 actualForward = GetFlatDirection(probe.Player.MovementContext.PlayerRealForward);
                float arrivalAngle = actualForward.sqrMagnitude > 0.5f
                    ? Vector3.Angle(actualForward, probe.RequestedDirection)
                    : 180f;
                bool rolling = FollowerCapabilityHelperRules.UpdateProbeApproaching_rolling_E7A97DCD_2(probe.PreviousSprinting,probe.PreviousRunning,probe.ApproachBackingOff,arrivalAngle,ProbeRollingAlignmentAngle);

                WriteEvent("vaultProbeApproachCompleted", probe.Bot, new
                {
                    target = Vec(probe.ApproachTarget),
                    obstaclePoint = Vec(probe.ApproachObstaclePoint),
                    obstacleCollider = probe.ApproachObstacleCollider,
                    distance,
                    rolling,
                    previousSprinting = probe.PreviousSprinting,
                    arrivalAngle
                });

                if (rolling)
                {
                    // Keep the real ground velocity alive into native Jump/Vault priming.
                    BeginProbePriming(probe, arrivalAngle);
                }
                else
                {
                    probe.Bot.BotOwnerStopMove("R1-F4A37F808788",@probe?.Bot);
                    TransitionProbeStage(probe, ProbeStage.Aligning);
                    probe.StageStartedAt = Time.time;
                    probe.AlignStableSince = -1f;
                }
                return;
            }

            if (Time.time - probe.StageStartedAt > ProbeApproachTimeout)
            {
                FinishProbeWithoutReanchor(
                    probe,
                    "approachTimeout",
                    $"could not reach pre-vault approach point; remaining={distance:0.00}m");
            }
        }

        private static bool TryFindProbeObstacleApproach(
            ProbeRuntime probe,
            out Vector3 approachTarget,
            out Vector3 obstaclePoint,
            out string obstacleCollider,
            out Vector3 correctedDirection,
            out string failure)
        {
            approachTarget = default;
            obstaclePoint = default;
            obstacleCollider = string.Empty;
            correctedDirection = probe?.RequestedDirection ?? Vector3.zero;
            failure = string.Empty;

            if (probe?.Player == null || probe.Player.MovementContext == null)
            {
                failure = "player or movement context unavailable";
                return false;
            }

            Vector3 baseDirection = GetFlatDirection(probe.RequestedDirection);
            if (baseDirection.sqrMagnitude < 0.5f)
            {
                failure = "invalid requested direction";
                return false;
            }

            Vector3 origin = probe.Player.Position + Vector3.up * ProbeApproachRayHeight;
            float[] yawOffsets = { 0f, -10f, 10f, -20f, 20f };
            bool found = false;
            RaycastHit bestHit = default;
            Vector3 bestDirection = baseDirection;
            float bestScore = float.MaxValue;

            foreach (float yaw in yawOffsets)
            {
                Vector3 direction = GetFlatDirection(Quaternion.AngleAxis(yaw, Vector3.up) * baseDirection);
                if (!TryGetFirstNonSelfRaycastHit(
                        probe.Player,
                        origin,
                        direction,
                        ProbeApproachMaxObstacleDistance,
                        out RaycastHit hit))
                {
                    continue;
                }

                float score = hit.distance + Mathf.Abs(yaw) * 0.025f;
                if (!found || score < bestScore)
                {
                    found = true;
                    bestScore = score;
                    bestHit = hit;
                    bestDirection = direction;
                }
            }

            if (!found)
            {
                failure = $"no non-self obstacle collider within {ProbeApproachMaxObstacleDistance:0.0}m";
                return false;
            }

            Vector3 towardHit = GetFlatDirection(bestHit.point - probe.Bot.Position);
            if (towardHit.sqrMagnitude < 0.5f)
            {
                towardHit = bestDirection;
            }

            float standOffDistance =
                string.Equals(probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                !probe.JumpFallbackToVault
                    ? 1.20f
                    : ProbeApproachStandOffDistance;
            Vector3 desired = bestHit.point - towardHit * standOffDistance;
            if (!NavMesh.SamplePosition(
                    desired,
                    out NavMeshHit approachHit,
                    0.55f,
                    NavMesh.AllAreas))
            {
                failure = "pre-vault stand-off point is not on nearby NavMesh";
                return false;
            }

            Vector3 delta = approachHit.position - probe.Bot.Position;
            float approachDistance = delta.magnitude;
            bool tooCloseToObstacle = bestHit.distance < standOffDistance - 0.12f;
            if (tooCloseToObstacle)
            {
                StrictPathResult backOffPath = CalculateStrictPath(probe.Bot.Position, approachHit.position);
                bool safeBackOff = approachDistance <= 1.10f &&
                                   Mathf.Abs(delta.y) <= 0.55f &&
                                   backOffPath.StrictComplete &&
                                   FollowerCapabilityHelperRules.TryFindProbeObstacleApproach_safeBackOff_A2EB79F8_1(backOffPath.PathLength,approachDistance);
                if (!safeBackOff)
                {
                    failure = $"too close to obstacle ({bestHit.distance:0.00}m) and no safe local back-off path";
                    return false;
                }

                probe.ApproachBackingOff = true;
            }
            else if (Vector3.Dot(GetFlatDirection(delta), towardHit) < 0.10f ||
                     Mathf.Abs(delta.y) > 0.55f)
            {
                failure = "pre-vault stand-off point is not safely ahead on the same local surface";
                return false;
            }

            approachTarget = approachHit.position;
            obstaclePoint = bestHit.point;
            obstacleCollider = bestHit.collider?.name ?? "unknown";
            correctedDirection = towardHit;
            return true;
        }

        private static void BeginProbePriming(ProbeRuntime probe, float alignmentAngle)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            if (string.Equals(probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                !probe.JumpFallbackToVault)
            {
                BeginProbeJumpPriming(probe, alignmentAngle);
                return;
            }

            TransitionProbeStage(probe, ProbeStage.Priming);
            probe.StageStartedAt = Time.time;
            probe.TriggerAlignmentAngle = alignmentAngle;
            probe.Bot.Mover.SetBotMoverPause("R1-4E17C16BFB9B",@probe?.Bot,false);
            probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-746B527BDD39",@probe?.Bot);
            ApplyProbeLocomotionIntent(probe, ProbeMomentumNormalMoveSpeed, allowSprint: true);
            HoldForwardInput(probe);

            // CompileFix17: DropDown has no native Vault-scanner primitive. A player-authored
            // DropDown is an explicit one-way physical replay; sending it through TryVaulting is
            // what produced Strategy=None / h~0.05 scans and "action not executed" failures.
            if (string.Equals(probe.RequestedTraversalKind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                IsPlayerValidatedTraversalProbe(probe))
            {
                if (TryBeginAssistedTraversalReplay(probe, "playerValidatedDropDownDirect", out string dropDownFailure))
                {
                    WriteEvent("dropDownExecutorSelected", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        source = "playerValidatedDropDownDirect",
                        chainLocalExecutable = probe.FrozenTraversalCommitment?.ChainLocalExecutable == true
                    });
                    return;
                }

                FinishProbeWithoutReanchor(
                    probe,
                    "dropDownExecutorUnavailable",
                    dropDownFailure);
                return;
            }

            // V1.3.17 Player Demonstration Authority: a player-validated Vault/Climb gets exactly
            // one scanner refresh and one native TryVaulting attempt. Strategy=None is diagnostic
            // only; it never parks the bot in Priming waiting for repeated scanner confirmation.
            if (IsPlayerValidatedTraversalProbe(probe) &&
                !string.Equals(probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                bool scannerTicked = TryTickNativeVaultScanner(probe.Player, out string oneShotScannerError);
                float oneShotForwardVelocity = GetProbeForwardVelocity(probe.Player);
                WriteEvent("vaultProbeOneShotNative", probe.Bot, new
                {
                    kind = probe.RequestedTraversalKind,
                    learnedEdgeId = probe.LearnedEdgeId,
                    scannerTicked,
                    scannerError = oneShotScannerError,
                    forwardVelocity = oneShotForwardVelocity,
                    parameters = CreateVaultParameterPayload(probe.Player)
                });
                TriggerNativeVaultScan(
                    probe,
                    alignmentAngle,
                    oneShotForwardVelocity >= ProbePrimeForwardVelocity);
                return;
            }

            // V1 stopped the bot for alignment and then tried to vault without restoring any AI path.
            // Merely writing InputDirection is not guaranteed to produce physical AI velocity, so T1.1
            // also gives the bot a very short same-direction NavMesh approach when one is available.
            // The target is intentionally kept well short of a typical low-fence scan point; if it cannot
            // be sampled or produces an invalid path, priming safely falls back to forward-input only.
            bool learnedFastPath = probe.LearnedEdgeId > 0;
            float incomingForwardVelocity = GetProbeForwardVelocity(probe.Player);
            bool needsVelocityAssist = FollowerCapabilityHelperRules.BeginProbePriming_needsVelocityAssist_F761D99B_1(learnedFastPath,incomingForwardVelocity);
            float approachDistance = needsVelocityAssist ? 0.85f : ProbePrimeApproachDistance;
            Vector3 desiredApproach = probe.Bot.Position + probe.RequestedDirection * approachDistance;
            NavMeshPathStatus? approachStatus = null;
            if ((!learnedFastPath || needsVelocityAssist) &&
                NavMesh.SamplePosition(
                    desiredApproach,
                    out NavMeshHit approachHit,
                    ProbePrimeApproachSampleRadius,
                    NavMesh.AllAreas) &&
                Vector3.Dot(GetFlatDirection(approachHit.position - probe.Bot.Position), probe.RequestedDirection) > 0.25f &&
                Mathf.Abs(approachHit.position.y - probe.Bot.Position.y) <= 0.45f)
            {
                try
                {
                    approachStatus = probe.Bot.BotOwnerGoToPoint(
"R1-CCD5658BE95B",@probe?.Bot,                        approachHit.position,                        false,                        0.05f,                        false,                        false,                        false,                        false,                        false);
                    if (approachStatus != NavMeshPathStatus.PathInvalid)
                    {
                        probe.PrimeApproachTarget = approachHit.position;
                        probe.HasPrimeApproachTarget = true;
                    }
                }
                catch (Exception ex)
                {
                    probe.PrimeApproachError = ex.GetType().Name + ": " + ex.Message;
                }
            }

            WriteEvent("vaultProbePrimingStarted", probe.Bot, new
            {
                alignmentAngle,
                inputDirection = Vec2(probe.Player.InputDirection),
                movementDirection = Vec2(probe.Player.MovementContext.MovementDirection),
                isForwardInputDirection = ReadBoolProperty(probe.Player, "IsForwardInputDirection"),
                desiredApproach = Vec(desiredApproach),
                approachTarget = probe.HasPrimeApproachTarget ? Vec(probe.PrimeApproachTarget) : null,
                approachStatus = approachStatus?.ToString(),
                approachError = probe.PrimeApproachError,
                learnedFastPath,
                incomingForwardVelocity,
                needsVelocityAssist,
                primeMaxSeconds = learnedFastPath ? LearnedProbePrimeMaxTime : ProbePrimeMaxTime,
                parameters = CreateVaultParameterPayload(probe.Player)
            });
        }

        private static bool TryBuildJumpRunupDesiredTarget(
            ProbeRuntime probe, out Vector3 desired, out Vector3 direction)
        {
            desired = default;
            direction = default;
            if (probe?.Bot == null || !IsFinite(probe.Bot.Position))
            {
                return false;
            }

            direction = GetFlatDirection(probe.RequestedDirection);
            if (direction.sqrMagnitude < 0.5f)
            {
                return false;
            }

            desired = probe.Bot.Position + direction * ProbeJumpRunupDistance;
            if (probe.ApproachObstaclePoint != Vector3.zero && IsFinite(probe.ApproachObstaclePoint))
            {
                // One geometry contract feeds both the NavMesh-backed legacy producer and V4.46's
                // collision-active pathless producer. Do not let the two consumers drift apart.
                Vector3 obstacleSideTarget = probe.ApproachObstaclePoint - direction * 0.10f;
                float forwardDistance = Vector3.Dot(obstacleSideTarget - probe.Bot.Position, direction);
                if (forwardDistance >= 0.12f && forwardDistance <= 0.75f)
                {
                    desired = obstacleSideTarget;
                }
            }
            return IsFinite(desired);
        }

        private static bool TryBuildLearningV446PathlessJumpRunupTarget(ProbeRuntime probe, out Vector3 target)
        {
            target = default;
            if ((!TryBuildJumpRunupDesiredTarget(probe, out Vector3 desired, out Vector3 direction)))
            {
                return false;
            }

            // V411 owns collision-active movement, not NavMesh. Keep the readiness frontier on the
            // current support plane; it is a progress witness only and never relocates the body.
            desired.y = probe.Bot.Position.y;
            Vector3 delta = desired - probe.Bot.Position;
            delta.y = 0f;
            float projection = Vector3.Dot(delta, direction);
            if (delta.sqrMagnitude < 0.01f || projection <= 0.15f)
            {
                return false;
            }

            target = desired;
            return true;
        }

        private static void PublishLearningV446PathlessJumpRunup(ProbeRuntime probe, string source)
        {
            if ((probe == null) ||
                !probe.LearningV446PathlessJumpRunupActive)
            {
                return;
            }

            Vector3 direction = GetFlatDirection(probe.RequestedDirection);
            if (direction.sqrMagnitude < 0.5f)
            {
                return;
            }

            PublishLearningV411JumpTakeoffLocomotionContinuum(
                probe, direction, "learningV446PathlessJumpRunup:" + (source ?? string.Empty));
        }

        private static void ResetLearningV446PhysicalStrategyEpoch(FollowerRouteMission mission)
        {
            if (mission == null)
            {
                return;
            }
            mission.LearningV446StrategyEpochStepIndex = -1;
            mission.LearningV446StrategyEpochSemanticEdgeId = 0;
            mission.LearningV446RetiredPhysicalStrategyEdgeId = 0;
            mission.LearningV446RetiredPhysicalStrategyKind = null;
            mission.LearningV446RetiredPhysicalStrategySource = null;
            mission.LearningV446RetiredPhysicalStrategyAt = -1f;
        }

        private static void RetireLearningV446PhysicalStrategy(
            FollowerRouteMission mission, FollowerRouteMissionStep step, string source)
        {
            if ((mission == null) || step == null ||
                mission.Steps == null || mission.CurrentStepIndex < 0 ||
                mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return;
            }

            mission.LearningV446StrategyEpochStepIndex = mission.CurrentStepIndex;
            mission.LearningV446StrategyEpochSemanticEdgeId = step.EdgeId;
            mission.LearningV446RetiredPhysicalStrategyEdgeId = step.EdgeId;
            mission.LearningV446RetiredPhysicalStrategyKind = step.Kind;
            mission.LearningV446RetiredPhysicalStrategySource = source ?? string.Empty;
            mission.LearningV446RetiredPhysicalStrategyAt = Time.time;
        }

        private static bool IsLearningV446PhysicalStrategyRetiredForCurrentStep(
            FollowerRouteMission mission, FollowerRouteMissionStep step, string requestedKind)
        {
            if ((mission == null) || step == null)
            {
                return false;
            }

            if (mission.LearningV446StrategyEpochStepIndex != mission.CurrentStepIndex ||
                mission.LearningV446StrategyEpochSemanticEdgeId != step.EdgeId)
            {
                ResetLearningV446PhysicalStrategyEpoch(mission);
                return false;
            }

            return FollowerCapabilityActuationPolicy.RetiredPhysicalStrategy(mission.CurrentStepIndex,
                mission.LearningV446StrategyEpochStepIndex,step.EdgeId,mission.LearningV446StrategyEpochSemanticEdgeId,
                mission.LearningV446RetiredPhysicalStrategyEdgeId,mission.LearningV446RetiredPhysicalStrategyKind,
                requestedKind??step.Kind);
        }

        private static bool TryRetireLearningV446CurrentSemanticStrategy(
            ProbeRuntime probe, string source)
        {
            if ((probe?.Bot == null) ||
                !TryGetActiveFollowerRouteMission(probe.Bot, out FollowerRouteMission mission) ||
                mission == null || mission.Steps == null || mission.CurrentStepIndex < 0 ||
                mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || !string.Equals(
                    step.Kind, probe.RequestedTraversalKind, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            if (IsLearningV446PhysicalStrategyRetiredForCurrentStep(
                    mission, step, probe.RequestedTraversalKind))
            {
                return true;
            }

            RetireLearningV446PhysicalStrategy(mission, step, source);
            WriteEvent("learningV446PrimaryPhysicalStrategyRetired", probe.Bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                semanticEdgeId = step.EdgeId,
                semanticKind = step.Kind,
                source = source ?? string.Empty,
                semanticDebtPreserved = true,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                bodyRelocated = false,
                action = "retireOnlyPrimaryPhysicalStrategyKeepSemanticDebtAvailableForEquivalentOrAssistConsumer"
            });
            return true;
        }

        private static void BeginProbeJumpPriming(ProbeRuntime probe, float alignmentAngle)
        {
            TransitionProbeStage(probe, ProbeStage.JumpPriming);
            probe.StageStartedAt = Time.time;
            probe.TriggerAlignmentAngle = alignmentAngle;
            probe.ExclusiveMoverGate = true;
            probe.Bot.Mover.SetBotMoverPause("R1-14CF0D33C08D",@probe?.Bot,false);
            probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-20E1B54AB0C7",@probe?.Bot);
            probe.Bot.BotOwnerSetPose("R1-E26810CB5896",@probe?.Bot,1f);
            ApplyProbeLocomotionIntent(
                probe, ProbeMomentumFullMoveSpeed, allowSprint: true,
                preserveSprintMode: true);

            probe.JumpTakeoffPathReleased = false;
            probe.LearningV446PathlessJumpRunupActive = false;
            probe.HasJumpRunupTarget = TryBuildJumpRunupTarget(probe, out probe.JumpRunupTarget);
            bool learningV446MissedTakeoffFrontier = false;
            float learningV446ForwardEntryProjection = float.NaN;
            if (!probe.HasJumpRunupTarget &&
                TryGetLearnedCommitmentForProbe(
                    probe, out LearnedTraversalCommitment learningV446JumpCommitment) &&
                learningV446JumpCommitment != null &&
                string.Equals(learningV446JumpCommitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                Vector3 learningV446IdentityEntry = IsFinite(learningV446JumpCommitment.RawEntry)
                    ? learningV446JumpCommitment.RawEntry : learningV446JumpCommitment.Entry;
                Vector3 learningV446AdmissionEntry = GetLearningV442JumpAdmissionEntry(learningV446JumpCommitment);
                Vector3 learningV446RawExit = IsFinite(learningV446JumpCommitment.RawExit)
                    ? learningV446JumpCommitment.RawExit : learningV446JumpCommitment.Exit;
                Vector3 learningV446Direction = GetFlatDirection(learningV446RawExit - learningV446IdentityEntry);
                if (learningV446Direction.sqrMagnitude >= 0.5f && IsFinite(learningV446AdmissionEntry))
                {
                    Vector3 learningV446EntryDelta = probe.Bot.Position - learningV446AdmissionEntry;
                    learningV446EntryDelta.y = 0f;
                    learningV446ForwardEntryProjection =
                        Vector3.Dot(learningV446EntryDelta, learningV446Direction);
                    learningV446MissedTakeoffFrontier =
                        learningV446ForwardEntryProjection > LearningV352JumpTakeoffCorridorMaxForwardOvershoot;
                }

                if (learningV446MissedTakeoffFrontier &&
                    TryBeginLearningV433EquivalentPhysicalActuatorFrontierRecovery(
                        probe.Bot,
                        "learningV446NavMeshRunupUnavailableAfterTakeoffFrontier",
                        out string learningV446TransferSource,
                        allowActiveProbe: true))
                {
                    WriteEvent("learningV446MissedJumpFrontierYieldedWithoutNavMeshRetryLoop", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.RequestedTraversalKind,
                        position = Vec(probe.Bot.Position),
                        forwardEntryProjection = learningV446ForwardEntryProjection,
                        maxForwardOvershoot = LearningV352JumpTakeoffCorridorMaxForwardOvershoot,
                        transferSource = learningV446TransferSource,
                        semanticDebtPreserved = true,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "navMeshRunupLossAfterMissedTakeoffFrontierImmediatelyChangesPhysicalStrategyInsteadOfReplayingSameJump"
                    });
                    FinalizeUnifiedTraversalFailure(
                        probe, "learningV446MissedTakeoffFrontierSameStepStrategySwitch");
                    return;
                }
                if (learningV446MissedTakeoffFrontier)
                {
                    TryRetireLearningV446CurrentSemanticStrategy(
                        probe, "learningV446MissedTakeoffFrontierNoEquivalentActuator");
                }
            }
            if (!probe.HasJumpRunupTarget && !learningV446MissedTakeoffFrontier &&
                TryBuildLearningV446PathlessJumpRunupTarget(probe, out Vector3 learningV446VirtualRunupTarget))
            {
                probe.JumpRunupTarget = learningV446VirtualRunupTarget;
                probe.HasJumpRunupTarget = true;
                probe.LearningV446PathlessJumpRunupActive = true;
                WriteEvent("learningV446PathlessJumpConsumerConverged", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.RequestedTraversalKind,
                    position = Vec(probe.Bot.Position),
                    virtualRunupTarget = Vec(probe.JumpRunupTarget),
                    direction = Vec(GetFlatDirection(probe.RequestedDirection)),
                    navMeshRunupRequired = false,
                    physicalProducer = "learningV411CollisionActivePlayerMove",
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "missingNavMeshSampleCannotDisproveJumpReuseExistingCollisionActiveRunupProducer"
                });
            }
            if (!probe.HasJumpRunupTarget)
            {
                TryRetireLearningV446CurrentSemanticStrategy(
                    probe, learningV446MissedTakeoffFrontier
                        ? "learningV446TakeoffFrontierPassedWithoutRunnableStrategy"
                        : "learningV446NoNativeOrPathlessRunupStrategy");
                FallbackJumpToVault(
                    probe,
                    learningV446MissedTakeoffFrontier
                        ? "takeoff frontier already passed before a valid run-up producer was acquired"
                        : "no valid native or pathless run-up target");
                return;
            }

            probe.JumpRunupStartPosition = probe.Bot.Position;
            probe.JumpRunupStartAt = Time.time;
            probe.JumpRunupGroundProgress = 0f;
            if (probe.LearningV446PathlessJumpRunupActive)
            {
                PublishLearningV446PathlessJumpRunup(probe, "begin");
            }
            else
            {
                DriveProbeJumpRunup(probe);
            }
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-F15F32C877F0",@probe?.Bot,probe.RequestedDirection);

            WriteEvent("jumpProbeRunupStarted", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                requestedKind = probe.RequestedTraversalKind,
                alignmentAngle,
                canJump = probe.Player.MovementContext?.CanJump == true,
                sprinting = probe.Bot.Mover?.Sprinting == true,
                position = Vec(probe.Player.Position),
                direction = Vec(probe.RequestedDirection),
                hasRunupTarget = probe.HasJumpRunupTarget,
                runupTarget = probe.HasJumpRunupTarget ? Vec(probe.JumpRunupTarget) : null,
                learningV446PathlessRunup = probe.LearningV446PathlessJumpRunupActive
            });
        }

        private static void UpdateProbeJumpPriming(ProbeRuntime probe)
        {
            if (!ValidateProbePreconditions(probe.Bot, out string failure))
            {
                // During the short run-up CanJump/grounded can transition on the same frame as the
                // real jump. If we already entered a jump state, the state callback owns the transition.
                if (IsJumpState(probe.Player.CurrentStateName))
                {
                    BeginTraversalStage(probe, probe.Player.CurrentStateName, "jumpPrimingPolled");
                    return;
                }

                FinishProbeWithoutReanchor(probe, "jumpPreconditionChanged", failure);
                return;
            }

            probe.Bot.Mover.SetBotMoverPause("R1-5F32573E4DBB",@probe?.Bot,false);
            probe.Bot.BotOwnerSetPose("R1-233D007B0B8E",@probe?.Bot,1f);
            ApplyProbeLocomotionIntent(
                probe, ProbeMomentumFullMoveSpeed, allowSprint: true,
                preserveSprintMode: true);
            if (probe.LearningV446PathlessJumpRunupActive)
            {
                PublishLearningV446PathlessJumpRunup(probe, "update");
            }
            else
            {
                DriveProbeJumpRunup(probe);
            }
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-A34ED43DE4DF",@probe?.Bot,probe.RequestedDirection);

            if (!probe.HasJumpRunupTarget)
            {
                FallbackJumpToVault(probe, "run-up producer became invalid before jump");
                return;
            }

            Vector3 runupDelta = probe.Bot.Position - probe.JumpRunupStartPosition;
