                        kind = probe.RequestedTraversalKind,
                        elapsed,
                        canJump,
                        groundProgress = probe.JumpRunupGroundProgress,
                        remainingToRunupTarget,
                        transferSource = learningV446ExhaustedTransferSource,
                        semanticDebtPreserved = true,
                        traversalSuccessRecorded = false,
