                    probe,
                    !canJump
                        ? "MovementContext.CanJump stayed false during run-up"
                        : $"no real ground run-up before trigger; progress={probe.JumpRunupGroundProgress:0.00}m remaining={remainingToRunupTarget:0.00}m");
            }
        }

        private static bool TryBuildJumpRunupTarget(ProbeRuntime probe, out Vector3 target)
        {
            target = default;
            if (probe?.Bot == null)
            {
                return false;
            }

            if (!TryBuildJumpRunupDesiredTarget(probe, out Vector3 desired, out Vector3 direction))
            {
                return false;
            }

            if (!NavMesh.SamplePosition(desired, out NavMeshHit hit, ProbeJumpRunupSampleRadius, NavMesh.AllAreas))
            {
                return false;
            }

            Vector3 delta = hit.position - probe.Bot.Position;
            float projection = Vector3.Dot(GetFlatDirection(delta), direction);
            if (delta.sqrMagnitude < 0.01f ||
                projection <= 0.15f ||
                Mathf.Abs(hit.position.y - probe.Bot.Position.y) > ProbeSupportMaxVerticalOffset)
            {
                return false;
            }

            target = hit.position;
            return true;
        }

        private static void DriveProbeJumpRunup(ProbeRuntime probe)
        {
            if (probe?.Bot == null || !probe.HasJumpRunupTarget)
            {
                return;
            }

            try
            {
                NavMeshPathStatus status = probe.Bot.BotOwnerGoToPoint(
"R1-B128A327D646",@probe?.Bot,                    probe.JumpRunupTarget,                    false,                    0.05f,                    false,                    false,                    false,                    false,                    false);
                if (status == NavMeshPathStatus.PathInvalid)
                {
                    probe.HasJumpRunupTarget = false;
                }
            }
            catch
            {
                probe.HasJumpRunupTarget = false;
            }
        }

        private static bool HasNativeJumpPhysicalTakeoffEvidence(
            ProbeRuntime probe,
            out float rise,
            out bool airborne)
        {
            rise = 0f;
            airborne = false;
            if (probe?.Player?.MovementContext == null || !IsFinite(probe.Player.Position))
            {
                return false;
            }

            Vector3 baseline = IsFinite(probe.TriggerPosition) ? probe.TriggerPosition : probe.Player.Position;
            rise = probe.Player.Position.y - baseline.y;
            airborne = probe.Player.MovementContext.IsGrounded != true;
            ;

            bool traversalState = probe.Player.CurrentStateName == EPlayerState.Jump ||
                                  probe.Player.CurrentStateName == EPlayerState.JumpLanding;
            bool candidate = FollowerCapabilityHelperRules.HasNativeJumpPhysicalTakeoffEvidence_candidate_E5B41F18_1(airborne,traversalState,rise,NativeJumpPhysicalTakeoffMinRise);
            bool learningV456MonotonicCandidate =
                (probe.NativeJumpStateCandidateObserved) &&
                probe.LearningV332NativeJumpPhysicalTakeoffEvidenceSince >= 0f &&
                rise >= NativeJumpPhysicalTakeoffMinRise;
            if (!candidate && !learningV456MonotonicCandidate)
            {
                probe.LearningV332NativeJumpPhysicalTakeoffEvidenceSince = -1f;
                return false;
            }
            if (probe.LearningV332NativeJumpPhysicalTakeoffEvidenceSince < 0f)
            {
                probe.LearningV332NativeJumpPhysicalTakeoffEvidenceSince = Time.time;
                return false;
            }
            return Time.time - probe.LearningV332NativeJumpPhysicalTakeoffEvidenceSince >=
                   LearnedJumpTakeoffStableSeconds;
        }

        private static void TriggerNativeJump(ProbeRuntime probe, bool atomicAdmission = false)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            if (probe.Player?.MovementContext?.CanJump != true)
            {
                FallbackJumpToVault(probe, "MovementContext.CanJump was false at trigger");
                return;
            }

            // RC116: all consumers, including legacy rolling fallback, share the last live guard.
            if (!IsCapabilityJumpTriggerReady(probe,out string rc116Refusal,atomicAdmission))
            {
                WriteEvent("capabilityJumpFinalConsumerRejected",probe.Bot,new{edgeId=probe.LearnedEdgeId,
                    reason=rc116Refusal,state=probe.Player.CurrentStateName.ToString(),speed=GetLearningV329PlanarSpeed(probe.Player),nativeJumpTriggered=false});
                if(rc116Refusal=="velocityObservationPending")return;
                if(TryRequestCapabilityFullRouteRetry(probe,"jumpFinalConsumer:"+rc116Refusal,true))return;
                return;
            }

            // V418 bounded bootstrap: if this is a Run attempt against a historically Sprint-
            // demonstrated Jump, consume one independent player Run+Jump proof now, immediately
            // before native TryJump. The pre-entry gates only inspect availability; they never
            // consume evidence. Successful native takeoff promotes V414 follower-local capability;
            // failure closes this trial until another player Run+Jump demonstration is observed.
            TryConsumeLearningV418PlayerProvenRunJumpTrial(probe);

            probe.Bot.Mover.SetBotMoverPause("R1-229197ADE7F3",@probe?.Bot,false);
            probe.Bot.BotOwnerSetPose("R1-53AA60E363DA",@probe?.Bot,1f);
            ApplyProbeLocomotionIntent(
                probe, ProbeMomentumFullMoveSpeed, allowSprint: true,
                preserveSprintMode: true);
            // Do not write InputDirection/MovementDirection here. V1.3.3 kept forcing
            // Vector2.up through take-off and airborne frames, which produced an artificial
            // "air slide" several metres long. The only horizontal momentum allowed for native
            // Jump is the BotMover locomotion already observed during the grounded run-up.
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-AFFDCBC7C49A",@probe?.Bot,probe.RequestedDirection);
            float capabilityTakeoffSpeed=GetLearningV329PlanarSpeed(probe.Player);
            probe.TriggerPosition = probe.Player.Position;
            probe.JumpAttempted = true;
            probe.NativeJumpTriggerAt = Time.time;
            probe.NativeJumpStateCandidateObserved = false;
            probe.LearningV355JumpLatencyRecorded = false;
            probe.NativeJumpStateCandidateAt = -1f;
            probe.LearningV332NativeJumpPhysicalTakeoffEvidenceSince = -1f;
            {
                probe.LearningV414JumpTakeoffCapabilityCaptured = true;
                probe.LearningV414JumpTakeoffState = probe.Player.CurrentStateName;
                probe.LearningV414JumpTakeoffPlanarSpeed = capabilityTakeoffSpeed;
                WriteEvent("learningV414JumpTakeoffCapabilitySnapshot", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    state = probe.LearningV414JumpTakeoffState.ToString(),
                    planarSpeed = probe.LearningV414JumpTakeoffPlanarSpeed,
                    demonstratedApproachMode = probe.DemonstratedApproachMode ?? string.Empty,
                    action = "snapshotFollowerLocalCapabilityOnlyPersistAfterNativePhysicalSuccess"
                });
            }

            // CompileFix46 normally re-targets BotMover to RawExit for horizontal run-through.
            // V3.17 narrows only the V3.16 strong rolling path: runtime proved PathPartial Jump
            // RawExit can make NavMesh steering own the airborne heading and pull Ghost onto the
            // partial ground-path corner. Preserve the already-live rolling entry momentum instead;
            // semantic forward input/steering owns the bounded takeoff carry below. Legacy/ambiguous
            // CompileFix47 priming still uses the exact CompileFix46 RawExit behavior.
            if (TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment jumpCommitment) &&
                jumpCommitment != null && probe.Bot?.Mover != null)
            {
                Vector3 jumpRunOut = IsFinite(jumpCommitment.RawExit)
                    ? jumpCommitment.RawExit
                    : jumpCommitment.Exit;
                if (IsFinite(jumpRunOut))
                {
                    if ((probe.LearningV317NativeJumpSemanticTrajectoryAuthority))
                    {
                        WriteEvent("learningV317NativeJumpRawExitGroundPathSuppressed", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            position = Vec(probe.Player.Position),
                            rawExit = Vec(jumpRunOut),
                            requestedDirection = Vec(probe.RequestedDirection),
                            moverHasPath = probe.Bot.Mover.HasPathAndNoComplete,
                            reason = "physicalJumpEndpointIsNotGroundNavTarget"
                        });
                    }
                    else
                    {
                        probe.Bot.Mover.BotMoverGoToPointNoWay("R1-3F2B0205AA90",@probe?.Bot,jumpRunOut);
                    }
                }
            }
            // Do not freeze BotMover for Jump. Native EFT jumping needs the mover's horizontal
            // locomotion to continue through take-off and airborne frames.
            probe.ExclusiveMoverGate = false;

            try
            {
                // Same native EFT movement API SAIN uses for real jumps. Do not call SAIN here so
                // learned Jump traversal behaves identically with SAIN enabled or disabled.
                TryConsumeCapabilityColdRunJumpTrial(probe);
                probe.Player.MovementContext.MovementContextTryJump("R1-112482C5E08D",@probe?.Bot);
            }
            catch (Exception ex)
            {
                WriteEvent("jumpProbeException", probe.Bot, new
                {
                    phase = "MovementContext.TryJump",
                    error = ex.ToString()
                });
                FallbackJumpToVault(probe, "MovementContext.TryJump threw " + ex.GetType().Name);
                return;
            }

            TransitionProbeStage(probe, ProbeStage.WaitingForState);
            probe.StageStartedAt = Time.time;
            probe.TraversalKind = "Jump";
            WriteEvent("jumpProbeTriggered", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                position = Vec(probe.Player.Position),
                forward = Vec(probe.Player.MovementContext.PlayerRealForward),
                inputDirection = Vec2(probe.Player.InputDirection),
                movementDirection = Vec2(probe.Player.MovementContext.MovementDirection),
                sprinting = probe.Bot.Mover?.Sprinting == true
            });
        }

        private static bool TryBeginNativeJumpAfterVaultRefusal(ProbeRuntime probe, out string failure)
        {
            failure = string.Empty;
            if (probe?.Player?.MovementContext == null)
            {
                failure = "movement context unavailable";
                return false;
            }

            EFT.Vaulting.IVaultingParameters parameters = probe.Player.VaultingParameters;
            if (parameters == null)
            {
                failure = "vault parameters unavailable";
                return false;
            }

            float obstacleHeight;
            float obstacleLength;
            try
            {
                obstacleHeight = parameters.VaultingHeight;
                obstacleLength = parameters.VaultingLength;
            }
            catch (Exception ex)
            {
                failure = "vault parameter read failed: " + ex.GetType().Name;
                return false;
            }

            // Native Jump is collision-respecting and can safely be attempted on a slightly wider
            // low-wall envelope than the synthetic Forward-Hop. The latest test log had several
            // real ~0.99-1.02m fences rejected only because the old 0.95m Hop ceiling was reused here.
            if (obstacleHeight < ProbeHopMinObstacleHeight ||
                obstacleHeight > ProbeNativeJumpMaxObstacleHeight ||
                obstacleLength <= 0f ||
                obstacleLength > ProbeNativeJumpMaxObstacleLength)
            {
                failure = $"not a low jumpable obstacle h={obstacleHeight:0.00} len={obstacleLength:0.00}";
                return false;
            }

            probe.JumpAfterVaultRefusal = true;
            probe.JumpFallbackToVault = false;
            WriteEvent("vaultProbeJumpSalvageStarted", probe.Bot, new
            {
                obstacleHeight,
                obstacleLength,
                canJump = probe.Player.MovementContext.CanJump,
                learnedEdgeId = probe.LearnedEdgeId
            });
            BeginProbeJumpPriming(probe, probe.TriggerAlignmentAngle);
            return true;
        }

        private static void FallbackJumpToVault(ProbeRuntime probe, string reason)
        {
            if (IsPlayerValidatedTraversalProbe(probe) &&
                TryRecoverPlayerValidatedTraversal(probe, "jumpNativeUnavailable:" + reason))
            {
                return;
            }
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            // V446 central strategy arbitration: reaching this common fallback means the current
            // Native Jump HOW has yielded. Preserve the semantic Jump debt, but remember that this
            // primary strategy may not be reacquired again for the same RouteMission step.
            TryRetireLearningV446CurrentSemanticStrategy(
                probe, "learningV446JumpPrimaryYieldToVault:" + (reason ?? string.Empty));

            if (probe.JumpAfterVaultRefusal)
            {
                probe.JumpAfterVaultRefusal = false;
                if (TryBeginSafeForwardHopFallback(probe, out string hopFailure))
                {
                    WriteEvent("vaultProbeJumpSalvageFallbackToHop", probe.Bot, new
                    {
                        reason,
                        learnedEdgeId = probe.LearnedEdgeId
                    });
                    return;
                }

                FinishProbeWithoutReanchor(
                    probe,
                    "jumpSalvageRefused",
                    $"{reason}; hopFallback={hopFailure}");
                return;
            }

            if (!EnsureVaultingComponent(probe.Player, out string componentFailure))
            {
                FinishProbeWithoutReanchor(
                    probe,
                    "jumpFallbackVaultUnavailable",
                    $"{reason}; VaultingComponent unavailable: {componentFailure}");
                return;
            }

            probe.JumpFallbackToVault = true;
            probe.JumpAttempted = false;
            probe.ExclusiveMoverGate = false;
            if (probe.Bot.Mover?.Sprinting == true)
            {
                probe.Bot.Mover.BotMoverSprint("R1-A477B077FC0B",@probe?.Bot,false,false);
            }
            WriteEvent("jumpProbeFallbackToVault", probe.Bot, new
            {
                learnedEdgeId = probe.LearnedEdgeId,
                reason,
                position = Vec(probe.Player.Position)
            });

            BeginProbePriming(probe, probe.TriggerAlignmentAngle);
        }

        private static void UpdateProbePriming(ProbeRuntime probe)
        {
            if (!ValidateProbePreconditions(probe.Bot, out string failure))
            {
                FinishProbeWithoutReanchor(probe, "preconditionChanged", failure);
                return;
            }

            HoldForwardInput(probe);
            probe.Bot.Mover.SetBotMoverPause("R1-159D1196E329",@probe?.Bot,false);
            ApplyProbeLocomotionIntent(probe, ProbeMomentumNormalMoveSpeed, allowSprint: true);
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-4EA858B61741",@probe?.Bot,probe.RequestedDirection);

            string vaultTickError = null;
            bool vaultTickInvoked = TryTickNativeVaultScanner(probe.Player, out vaultTickError);

            float elapsed = Time.time - probe.StageStartedAt;
            float forwardVelocity = 0f;
            string strategy = "None";
            try
            {
                EFT.Vaulting.IVaultingParameters parameters = probe.Player.VaultingParameters;
                forwardVelocity = Mathf.Abs(parameters?.AbsoluteForwardVelocity ?? 0f);
                strategy = parameters?.GetVaultingStrategy().ToString() ?? "None";
            }
            catch
            {
                forwardVelocity = 0f;
                strategy = "None";
            }

            bool velocityReady = forwardVelocity >= ProbePrimeForwardVelocity;
            bool strategyReady = !string.Equals(strategy, "None", StringComparison.OrdinalIgnoreCase);
            if (strategyReady)
            {
                if (probe.StrategyStableSince < 0f)
                {
                    probe.StrategyStableSince = Time.time;
                    WriteEvent("vaultProbeStrategyReady", probe.Bot, new
                    {
                        strategy,
                        forwardVelocity,
                        vaultTickInvoked,
                        vaultTickError,
                        parameters = CreateVaultParameterPayload(probe.Player)
                    });
                }
            }
            else
            {
                probe.StrategyStableSince = -1f;
            }

            bool strategyStable = strategyReady &&
                                  probe.StrategyStableSince >= 0f &&
                                  FollowerCapabilityDecisionRules.UpdateProbePriming_strategyStable_1(Time.time,probe.StrategyStableSince,ProbeStrategyStableTime);

            // The 2026-08-13 raid log showed a perfect correlation: both successful bot vaults had
            // Strategy=Vault before TryVaulting(), while later failures remained Strategy=None even
            // with valid obstacle dimensions and ~0.8-1.0 forward velocity. Wait for the native
            // scanner decision instead of using speed as the trigger. At max time, make one final
            // native attempt and then consider the guarded forward-hop fallback.
            float primeMinTime = probe.LearnedEdgeId > 0 ? LearnedProbePrimeMinTime : ProbePrimeMinTime;
            float primeMaxTime = probe.LearnedEdgeId > 0 ? LearnedProbePrimeMaxTime : ProbePrimeMaxTime;
            if (elapsed >= primeMinTime && strategyStable)
            {
                TriggerNativeVaultScan(probe, probe.TriggerAlignmentAngle, velocityReady);
            }
            else if (elapsed >= primeMaxTime)
            {
                WriteEvent("vaultProbeStrategyTimeout", probe.Bot, new
                {
                    strategy,
                    forwardVelocity,
                    velocityReady,
                    vaultTickInvoked,
                    vaultTickError,
                    parameters = CreateVaultParameterPayload(probe.Player)
                });
                TriggerNativeVaultScan(probe, probe.TriggerAlignmentAngle, velocityReady);
            }
        }

        private static bool IsPlayerValidatedTraversalProbe(ProbeRuntime probe)
        {
            if (probe == null || probe.LearnedEdgeId <= 0)
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(item => item != null && item.Id == probe.LearnedEdgeId);
            if (edge == null || (!edge.PlayerValidated && !edge.Verified))
            {
                return false;
            }

            if (!edge.Disabled)
            {
                return true;
            }

            if (TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment localCommitment) &&
                localCommitment != null && localCommitment.ChainLocalExecutable &&
                localCommitment.EpisodeId > 0)
            {
                TraversalEpisodeMetadata episode = TraversalEpisodeStream.LastOrDefault(item =>
                    item != null && item.EpisodeId == localCommitment.EpisodeId);
                return HasFreshRaidLocalDropDownAuthority(edge, episode) ||
                       HasLearningV341FreshRaidLocalSemanticSuccessorAuthority(edge, episode);
            }

            return false;
        }

        private static bool TryBeginLearningV408JumpPartialCrossingForwardContinuation(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string source,
            string failureStage)
        {
            if ((probe?.Player == null) ||
                probe.Bot == null || commitment == null || !probe.JumpAttempted ||
                !string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                (!probe.NativeTraversalStarted && !probe.NativePartialCrossingObserved && !probe.NativeLandingRejected))
            {
                return false;
            }

            bool started = TryBeginLearningV331NativeGroundContinuation(
                probe, commitment,
                "learningV408JumpPartialCrossingCurrentBody:" + (source ?? "unknown"));
            if (!started)
            {
                return false;
            }

            WriteEvent("learningV408JumpPartialCrossingForwardContinuationSelected", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                source = source ?? "unknown",
                failureStage = failureStage ?? string.Empty,
                position = Vec(probe.Player.Position),
                partialCrossingObserved = probe.NativePartialCrossingObserved,
                nativeLandingRejected = probe.NativeLandingRejected,
                nativeTraversalStarted = probe.NativeTraversalStarted,
                newPhysicalTransaction = false,
                returnToEntry = false,
                landingProofStillRequired = true,
                persistentLearningChanged = false,
                action = "singleJumpTakeoffRecoveryOriginIsCurrentPhysicalBodyContinueForwardWithExistingV331GroundContract"
            });
            return true;
        }

        private static bool TryBeginLearningV337FarSideJumpPhysicalRescue(
            ProbeRuntime probe,
            string source,
            string failureStage)
        {
            if ((probe?.Player == null) || probe.Bot == null ||
                probe.LearningV337FarSidePhysicalRescueAttempted || !probe.JumpAttempted ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null || !string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 entry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 exit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 axis = exit - entry;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < 0.25f)
            {
                return false;
            }
            Vector3 direction = axis / span;
            Vector3 fromEntry = probe.Player.Position - entry;
            fromEntry.y = 0f;
            float projection = Vector3.Dot(fromEntry, direction);
            float requiredProjection = Mathf.Max(0.45f, span * JumpNativeLandingMinProjectionRatio);
            bool supported = IsEffectivelySupportedForProbe(probe.Bot, probe.Player) ||
                NavMesh.SamplePosition(probe.Player.Position, out NavMeshHit supportHit, 0.90f, NavMesh.AllAreas);
            bool physicallyFarSide = FollowerCapabilityHelperRules.TryBeginLearningV337FarSideJumpPhysicalRescue_physicallyFarSide_D9EC3DE7_1(projection,requiredProjection,supported);
            if (!physicallyFarSide)
            {
                return false;
            }

            probe.LearningV337FarSidePhysicalRescueAttempted = true;
            probe.LearningV331NativeGroundContinuationActive = false;
            bool started = TryBeginLearningV331NativeGroundContinuation(
                probe, commitment,
                "learningV337FarSidePhysicalRescue:" + (source ?? "unknown"));
            WriteEvent("learningV337FarSideJumpPhysicalRescueSelected", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                source = source ?? "unknown",
                failureStage = failureStage ?? string.Empty,
                position = Vec(probe.Player.Position),
                projection,
                requiredProjection,
                supported,
                started,
                newPhysicalTransaction = false,
                returnToEntry = false,
                action = "samePhysicalTransactionForwardOnlyRescue"
            });
            return started;
        }

        private static bool TryBeginLearningV339LowerSideDropDownPhysicalRescue(
            ProbeRuntime probe,
            string source,
            string failureStage)
        {
            if ((probe?.Player == null) ||
                probe.LearningV339LowerSideDropDownRescueAttempted ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null ||
                !string.Equals(commitment.Kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            if (!IsFollowerAlreadyBelowDropDownLanding(
                    probe.Player.Position, rawEntry, rawExit, commitment.Exit))
            {
                return false;
            }

            probe.LearningV339LowerSideDropDownRescueAttempted = true;
            WriteEvent("learningV339LowerSideDropDownPhysicalRescue", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                source = source ?? "unknown",
                failureStage = failureStage ?? string.Empty,
                position = Vec(probe.Player.Position),
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                returnToEntry = false,
                upwardAssistedReplay = false,
                action = "currentPhysicalBodyDirectToExistingDropDownEgressVerify"
            });
            BeginUnifiedTraversalEgressOrVerify(
                probe, "learningV339LowerSideDropDownPhysicalRescue:" + (source ?? "unknown"));
            return true;
        }

        private static bool IsLearningV431EquivalentBarrierTransfer(LearnedTraversalCommitment commitment)
        {
            if (commitment == null || !IsLearningV319TransientSkillTransfer(commitment) ||
                string.IsNullOrWhiteSpace(commitment.SkillTransferSource))
            {
                return false;
            }

            return commitment.SkillTransferSource.StartsWith(
                       "learningV431EquivalentLocalBarrierSelfRescue", StringComparison.OrdinalIgnoreCase) ||
                   ((commitment.SkillTransferSource.StartsWith(
                        "learningV433EquivalentPhysicalActuatorFrontier", StringComparison.OrdinalIgnoreCase)));
        }

        private static bool IsLearningV433ObstacleClearanceActuatorKind(string kind)
        {
            return string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsLearningV433ExactLocalActuatorSubstitution(
            LearnedTraversalCommitment commitment)
        {
            return (commitment != null) && IsLearningV319TransientSkillTransfer(commitment) &&
                   !string.IsNullOrWhiteSpace(commitment.SkillTransferSource) &&
                   commitment.SkillTransferSource.StartsWith(
                       "learningV433EquivalentPhysicalActuatorFrontier", StringComparison.OrdinalIgnoreCase);
        }

        private static bool TryProveLearningV438EquivalentActuatorFrontierIdentity(
            LearnedTraversalEdge candidate,
            Vector3 stepEntry,
            Vector3 stepExit,
            Vector3 candidateRawEntry,
            Vector3 candidateRawExit,
            out float identityDistance,
            out string proofSource)
        {
            identityDistance = GetPlanarDistance(stepEntry, candidateRawEntry);
            proofSource = string.Empty;

            // Preserve V4.33's original exact endpoint identity unchanged. V4.38 only adds a
            // second proof path when different actuator semantics naturally place their trigger
            // points on different sides of the same physical barrier.
            if (identityDistance <= LearningV2RevisionEndpointRadius)
            {
                proofSource = "endpointRadius";
                return true;
            }

            if ((candidate == null) ||
                candidate.ObstacleFingerprint == null || candidate.NativeVaultParameters == null ||
                candidate.MotionSamples == null || candidate.MotionSamples.Count < 2 ||
                identityDistance > RouteMissionLocalEntryBridgeMaxDistance ||
                !IsFinite(stepEntry) || !IsFinite(stepExit) ||
                !IsFinite(candidateRawEntry) || !IsFinite(candidateRawExit))
            {
                return false;
            }

            Vector3 stepDirection = GetFlatDirection(stepExit - stepEntry);
            Vector3 candidateDirection = GetFlatDirection(candidateRawExit - candidateRawEntry);
            if (stepDirection.sqrMagnitude < 0.5f || candidateDirection.sqrMagnitude < 0.5f ||
                Vector3.Dot(stepDirection, candidateDirection) < LearningV2RevisionMinDirectionDot)
            {
                return false;
            }

            TraversalObstacleFingerprint obstacle = candidate.ObstacleFingerprint;
            Vector3 center = obstacle.BoundsCenter;
            Vector3 size = obstacle.BoundsSize;
            if (!IsFinite(center) || !IsFinite(size) ||
                size.x <= 0.02f || size.y <= 0.02f || size.z <= 0.02f ||
                Mathf.Max(Mathf.Abs(size.x), Mathf.Max(Mathf.Abs(size.y), Mathf.Abs(size.z))) >
                    AssistedObstacleFingerprintMaxExtent)
            {
                return false;
            }

            Vector3 perpendicular = new Vector3(-stepDirection.z, 0f, stepDirection.x);
            Vector3 centerDelta = center - stepEntry;
            centerDelta.y = 0f;
            float obstacleForward = Vector3.Dot(centerDelta, stepDirection);
            float obstacleLateral = Mathf.Abs(Vector3.Dot(centerDelta, perpendicular));
            float obstacleForwardHalfExtent = 0.5f *
                (Mathf.Abs(stepDirection.x) * Mathf.Abs(size.x) +
                 Mathf.Abs(stepDirection.z) * Mathf.Abs(size.z));
            float obstacleLateralHalfExtent = 0.5f *
                (Mathf.Abs(perpendicular.x) * Mathf.Abs(size.x) +
                 Mathf.Abs(perpendicular.z) * Mathf.Abs(size.z));
            float stepSpan = GetPlanarDistance(stepEntry, stepExit);

            // Reuse existing physical envelopes only. The candidate collider must overlap the
            // original directed traversal corridor longitudinally and laterally; this prevents a
            // nearby but unrelated rail/panel from becoming an actuator substitute just because
            // its recorded trigger point happens to be within the local 2.5m bridge radius.
            bool forwardOverlap =
                FollowerCapabilityHelperRules.TryProveLearningV438EquivalentActuatorFrontierIdentity_forwardOverlap_9D28967B_1(obstacleForward,obstacleForwardHalfExtent,InjectedNativeVaultEntryStagingReleaseDistance,obstacleForward,obstacleForwardHalfExtent,stepSpan,PostTraversalRollbackSideMargin);
            bool lateralOverlap =
                FollowerCapabilityHelperRules.TryProveLearningV438EquivalentActuatorFrontierIdentity_lateralOverlap_9D28967B_2(obstacleLateral,obstacleLateralHalfExtent,InjectedNativeVaultEntryStagingReleaseDistance);
            if (!forwardOverlap || !lateralOverlap)
            {
                return false;
            }

            proofSource = "nativeProvenObstacleBoundsCorridor:" + (obstacle.Name ?? string.Empty);
            return true;
        }

        internal static bool TryBeginLearningV433EquivalentPhysicalActuatorFrontierRecovery(
            BotOwner bot,
            string source,
            out string transferSource,
            bool allowActiveProbe = false)
        {
            transferSource = string.Empty;
            if ((!raidActive) || !IsLiveBot(bot) ||
                string.IsNullOrEmpty(bot.ProfileId) || (!allowActiveProbe && HasActiveTraversalProbe(bot)) ||
                !TryGetActiveFollowerRouteMission(bot, out FollowerRouteMission mission) ||
                mission == null || mission.Steps == null || mission.CurrentStepIndex < 0 ||
                mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || !IsLearningV433ObstacleClearanceActuatorKind(step.Kind))
            {
                return false;
            }

            // CF49: sibling-actuator substitution is a POST-original-attempt recovery,
            // never a pre-admission alternative for a Jump that has not been attempted.
            // V436 protected the legacy strategy-adoption path, but V433/V434 could still
            // capture the identical physical frontier during a slow rolling approach.
            // Preserve the original Jump's exact mission/episode/step and the existing
            // native trigger window. Failed or exhausted real probes retain V433 recovery.
            if ((string.Equals(step.Kind, "Jump", StringComparison.OrdinalIgnoreCase)) &&
                !step.AttemptStartedObserved)
            {
                if (ShouldEmitDiagnostic(
                    "cf49PreAttemptJumpSiblingSubstitutionDeferred:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    mission.CurrentStepIndex.ToString(CultureInfo.InvariantCulture),
                    bot, 0.35f))
                {
                    WriteEvent("cf49PreAttemptJumpSiblingSubstitutionDeferred", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = mission.CurrentStepIndex,
                        episodeId = step.EpisodeId,
                        edgeId = step.EdgeId,
                        originalAttemptObserved = false,
                        source = source ?? string.Empty,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "deferSameFrontierSiblingUntilOriginalJumpAttemptObserved"
                    });
                }
                return false;
            }

            // This is the SAME-frontier substitution layer. V431 remains responsible for finding
            // a different nearby barrier after an entry itself has become unusable. Never stack the
            // two producers or relaunch the same route step indefinitely.
            if (mission.LearningV431EquivalentBarrierRescueStepIndex != mission.CurrentStepIndex ||
                mission.LearningV431EquivalentBarrierRescueEdgeId != step.EdgeId)
            {
                ResetLearningV431EquivalentBarrierSelfRescueState(mission);
                mission.LearningV431EquivalentBarrierRescueAttempts = 0;
            }
            if (mission.LearningV431EquivalentBarrierRescuePending ||
                mission.LearningV431EquivalentBarrierRescueActive ||
                mission.LearningV431EquivalentBarrierRescueAttempts >=
                    LearningV431EquivalentBarrierSelfRescueMaxAttempts)
            {
                return false;
            }

            Player leader = FollowerEnvironment.LocalPlayer;
            if (!IsLivePlayer(leader) || !IsFinite(leader.Position) || !IsFinite(bot.Position))
            {
                return false;
            }

            Vector3 stepEntry = IsFinite(step.RawEntry) ? step.RawEntry : step.Entry;
            Vector3 stepExit = IsFinite(step.RawExit) ? step.RawExit : step.Exit;
            Vector3 identityStepEntry = stepEntry;
            Vector3 identityStepExit = stepExit;
            LearnedTraversalEdge learningV440TakeoffAxisEdge = null;
            bool learningV440PersistentTakeoffAxisApplied = false;
            if ((string.Equals(step.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
            {
                LearnedTraversalEdge authoredJumpEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == step.EdgeId);
                learningV440TakeoffAxisEdge = authoredJumpEdge;
                if (learningV440TakeoffAxisEdge != null &&
                    !IsLearningV3NativeProvenEdge(learningV440TakeoffAxisEdge) &&
                    TryGetLearningV31AuthoritativeProvenParent(
                        learningV440TakeoffAxisEdge, out LearnedTraversalEdge provenJumpParent) &&
                    provenJumpParent != null && IsLearningV3NativeProvenEdge(provenJumpParent))
                {
                    learningV440TakeoffAxisEdge = provenJumpParent;
                }

                if (learningV440TakeoffAxisEdge != null && IsLearningV3NativeProvenEdge(learningV440TakeoffAxisEdge) &&
                    IsFinite(learningV440TakeoffAxisEdge.RawStart) && IsFinite(learningV440TakeoffAxisEdge.RawEnd))
                {
                    bool persistentForward =
                        GetPlanarDistance(stepEntry, learningV440TakeoffAxisEdge.RawStart) <=
                        GetPlanarDistance(stepEntry, learningV440TakeoffAxisEdge.RawEnd);
                    Vector3 persistentEntry = persistentForward
                        ? learningV440TakeoffAxisEdge.RawStart : learningV440TakeoffAxisEdge.RawEnd;
                    Vector3 persistentExit = persistentForward
                        ? learningV440TakeoffAxisEdge.RawEnd : learningV440TakeoffAxisEdge.RawStart;
                    Vector3 persistentDirection = GetFlatDirection(persistentExit - persistentEntry);
                    if (persistentDirection.sqrMagnitude >= 0.5f)
                    {
                        identityStepEntry = persistentEntry;
                        identityStepExit = persistentExit;
                        learningV440PersistentTakeoffAxisApplied =
                            GetPlanarDistance(stepExit, persistentExit) > 0.05f;
                    }
                }
            }

            Vector3 stepDirection = GetFlatDirection(identityStepExit - identityStepEntry);
            if (!IsFinite(stepEntry) || !IsFinite(stepExit) || !IsFinite(identityStepEntry) ||
                !IsFinite(identityStepExit) || stepDirection.sqrMagnitude < 0.5f ||
                GetPlanarDistance(bot.Position, stepEntry) > RouteMissionLocalEntryBridgeMaxDistance)
            {
                return false;
            }

            if (learningV440PersistentTakeoffAxisApplied &&
                ShouldEmitDiagnostic(
                    "learningV440EquivalentActuatorPersistentTakeoffAxis:" +
                    mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                    mission.CurrentStepIndex.ToString(CultureInfo.InvariantCulture), bot, 0.35f))
            {
                WriteEvent("learningV440EquivalentActuatorPersistentTakeoffAxis", bot, new
                {
                    missionId = mission.MissionId,
                    stepIndex = mission.CurrentStepIndex,
                    edgeId = step.EdgeId,
                    episodeId = step.EpisodeId,
                    kind = step.Kind,
                    liveLandingFrontier = Vec(stepExit),
                    persistentTakeoffEntry = Vec(identityStepEntry),
                    persistentClearanceExit = Vec(identityStepExit),
                    authorityEdgeId = learningV440TakeoffAxisEdge?.Id ?? 0,
                    authorityExperienceKey = learningV440TakeoffAxisEdge?.ExperienceKey ?? string.Empty,
                    persistentLearningChanged = false,
                    traversalSuccessRecorded = false,
                    action = "equivalentActuatorSearchUsesObstacleClearanceSkillAxisLandingOverrideRemainsCompletionOnly"
                });
            }

            LearnedTraversalEdge bestEdge = null;
            bool bestForward = true;
            float bestScore = float.MaxValue;
            float bestIdentityDistance = float.MaxValue;
            string bestIdentityProof = string.Empty;
            float nearDestinationDistance = GetPlanarDistance(stepEntry, leader.Position);
            foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges)
            {
                if (candidate == null || candidate.Disabled || candidate.Id == step.EdgeId ||
                    !IsLearningV3NativeProvenEdge(candidate) ||
                    !IsLearningV433ObstacleClearanceActuatorKind(candidate.Kind) ||
                    string.Equals(candidate.Kind, step.Kind, StringComparison.OrdinalIgnoreCase) ||
                    !IsTraversalEdgeTopologicallySelectableForFollower(bot, candidate, out _))
                {
                    continue;
                }

                for (int orientation = 0; orientation < 2; orientation++)
                {
                    bool forward = orientation == 0;
                    Vector3 entry = forward ? candidate.A : candidate.B;
                    Vector3 exit = forward ? candidate.B : candidate.A;
                    Vector3 rawEntry = forward ? candidate.RawStart : candidate.RawEnd;
                    Vector3 rawExit = forward ? candidate.RawEnd : candidate.RawStart;
                    if (!IsFinite(entry) || !IsFinite(exit) || !IsFinite(rawEntry) || !IsFinite(rawExit) ||
                        !IsTraversalOrientationAllowed(candidate, entry, exit))
                    {
                        continue;
                    }

                    if (GetPlanarDistance(bot.Position, rawEntry) > RouteMissionLocalEntryBridgeMaxDistance)
                    {
                        continue;
                    }

                    Vector3 candidateDirection = GetFlatDirection(rawExit - rawEntry);
                    if (candidateDirection.sqrMagnitude < 0.5f ||
                        Vector3.Dot(candidateDirection, stepDirection) < LearningV2RevisionMinDirectionDot)
                    {
                        continue;
                    }

                    {
                        Vector3 liveBodyOffset = bot.Position - rawEntry;
                        liveBodyOffset.y = 0f;
                        float liveBodyForwardProjection = Vector3.Dot(liveBodyOffset, candidateDirection);
                        // The native Vault/Climb entry contract itself rejects a body beyond this
                        // existing overshoot envelope. Do not select such a substitute and then spend
                        // the full convergence timeout trying to run backward into an entry that the
                        // executor can never legally consume. This is admission pruning, not another
                        // retry/fallback rule.
                        if (liveBodyForwardProjection >
                            InjectedNativeVaultEntryMaxForwardOvershoot + LearningV32EntryProgressEpsilon)
                        {
                            if (ShouldEmitDiagnostic(
                                    "learningV449EquivalentActuatorCandidateRejectedPastNativeEntry:" +
                                    candidate.Id.ToString(CultureInfo.InvariantCulture), bot, 0.20f))
                            {
                                WriteEvent("learningV449EquivalentActuatorCandidateRejectedPastNativeEntry", bot, new
                                {
                                    missionId = mission.MissionId,
                                    stepIndex = mission.CurrentStepIndex,
                                    semanticEdgeId = step.EdgeId,
                                    semanticKind = step.Kind,
                                    candidateEdgeId = candidate.Id,
                                    candidateKind = candidate.Kind,
                                    candidateForwardEntryProjection = liveBodyForwardProjection,
                                    nativeEntryMaxForwardOvershoot = InjectedNativeVaultEntryMaxForwardOvershoot,
                                    existingProgressEpsilon = LearningV32EntryProgressEpsilon,
                                    body = Vec(bot.Position),
                                    candidateEntry = Vec(rawEntry),
                                    persistentLearningChanged = false,
                                    traversalSuccessRecorded = false,
                                    bodyRelocated = false,
                                    action = "rejectPhysicallyImpossibleBackwardReacquireBeforeStrategySelection"
                                });
                            }
                            continue;
                        }
                    }

                    if (!TryProveLearningV438EquivalentActuatorFrontierIdentity(
                            candidate, identityStepEntry, identityStepExit, rawEntry, rawExit,
                            out float frontierIdentityDistance, out string frontierIdentityProof))
                    {
                        continue;
                    }

                    float exitDestinationDistance = GetPlanarDistance(exit, leader.Position);
                    float destinationProgress = nearDestinationDistance - exitDestinationDistance;
                    if (destinationProgress < LearningV319ZeroShotMinDestinationProgress)
                    {
                        continue;
                    }

                    StrictPathResult downstream = CalculateStrictPath(exit, leader.Position);
                    if (downstream == null || !downstream.CalculateReturned || downstream.Corners == null ||
                        downstream.Corners.Length == 0)
                    {
                        continue;
                    }
                    Vector3 downstreamTerminal = downstream.Corners[downstream.Corners.Length - 1];
                    float downstreamTerminalDistance = downstream.StrictComplete
                        ? 0f
                        : GetPlanarDistance(downstreamTerminal, leader.Position);
                    if (nearDestinationDistance - downstreamTerminalDistance <
                        LearningV319ZeroShotMinDestinationProgress)
                    {
                        continue;
                    }

                    float score = frontierIdentityDistance + exitDestinationDistance * 0.01f -
                                  Mathf.Min(5, Math.Max(0, candidate.NativeSuccessCount)) * 0.05f;
                    if (bestEdge == null || score < bestScore)
                    {
                        bestEdge = candidate;
                        bestForward = forward;
                        bestScore = score;
                        bestIdentityDistance = frontierIdentityDistance;
                        bestIdentityProof = frontierIdentityProof ?? string.Empty;
                    }
                }
            }

            if (bestEdge == null)
            {
                return false;
            }

            Vector3 bestEntry = bestForward ? bestEdge.A : bestEdge.B;
            Vector3 bestExit = bestForward ? bestEdge.B : bestEdge.A;
            Vector3 bestRawEntry = bestForward ? bestEdge.RawStart : bestEdge.RawEnd;
            Vector3 bestRawExit = bestForward ? bestEdge.RawEnd : bestEdge.RawStart;
            int learningV322ParentAttemptId = 0;
            {
                LearningV322PendingParentAttemptByProfile.TryGetValue(bot.ProfileId, out learningV322ParentAttemptId);
                LearningV322PendingParentAttemptByProfile.Remove(bot.ProfileId);
            }

            transferSource =
                "learningV433EquivalentPhysicalActuatorFrontier:" +
                mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                mission.CurrentStepIndex.ToString(CultureInfo.InvariantCulture) + ":" +
                (step.Kind ?? string.Empty) + "->" + (bestEdge.Kind ?? string.Empty) + ":" +
                (source ?? "unknown");
            LearnedTraversalCommitment transfer = new LearnedTraversalCommitment
            {
                EdgeId = bestEdge.Id,
                EpisodeId = 0,
                ChainId = 0,
                Entry = bestEntry,
                Exit = bestExit,
                RawEntry = bestRawEntry,
                RawExit = bestRawExit,
                HasSettledEntry = true,
                SettledEntry = bestEntry,
                HasSettledExit = true,
                SettledExit = bestExit,
                Kind = bestEdge.Kind,
                SkillTransferTransient = true,
                SkillTemplateEdgeId = bestEdge.Id,
                SkillTransferParentAttemptId = learningV322ParentAttemptId,
                SkillTransferSource = transferSource,
                SkillTransferNearFrontier = bestRawEntry,
                SkillTransferFarFrontier = bestRawExit,
                RouteMissionId = mission.MissionId,
                RouteMissionStepIndex = mission.CurrentStepIndex,
                ExpiresAt = Time.time + LearningV319ZeroShotCommitmentSeconds,
                LastEntryDistance = GetPlanarDistance(bot.Position, bestRawEntry),
                LastEntryProgressAt = Time.time,
                LastLeaderDistanceAtEntryProgress = Vector3.Distance(bot.Position, leader.Position)
            };

            mission.LearningV431EquivalentBarrierRescueAttempts++;
            mission.LearningV431EquivalentBarrierRescuePending = false;
            mission.LearningV431EquivalentBarrierRescueActive = true;
            mission.LearningV431EquivalentBarrierRescueStepIndex = mission.CurrentStepIndex;
            mission.LearningV431EquivalentBarrierRescueEdgeId = step.EdgeId;
            mission.LearningV431EquivalentBarrierRescueEpisodeId = step.EpisodeId;
            mission.LearningV431EquivalentBarrierRescueCapabilityFamily = "ObstacleClearance";
            mission.LearningV431EquivalentBarrierRescueSource = source ?? "unknown";
            mission.LearningV336SelfRescueForceNativeNextAttempt = false;
            mission.LearningV336SelfRescueForceNativeSource = null;
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;

            LearnedTraversalCommitments[bot.ProfileId] = transfer;
            NavigationRecoveryTraversalAnchors.Remove(bot.ProfileId);
            BreadcrumbFollowCommitments.Remove(bot.ProfileId);
            FollowRejectLeases.Remove(bot.ProfileId);
            RetireLearningV446PhysicalStrategy(mission, step, transferSource);
            {
                WriteEvent("learningV446PhysicalStrategyEpochRetired", bot, new
                {
                    missionId = mission.MissionId,
                    stepIndex = mission.CurrentStepIndex,
                    semanticEdgeId = step.EdgeId,
                    semanticKind = step.Kind,
                    retiredPhysicalEdgeId = step.EdgeId,
                    retiredPhysicalKind = step.Kind,
                    substituteEdgeId = bestEdge.Id,
                    substituteKind = bestEdge.Kind,
                    source = transferSource,
                    semanticDebtPreserved = true,
                    physicalStrategyRetiredOnlyForCurrentStepEpoch = true,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "sameSemanticDebtMayChangePhysicalStrategyButRetiredStrategyCannotReacquireUpstreamEntry"
                });
            }
            RecordLearningV433PhysicalChronologyEvidence(
                step.EdgeId, "equivalentPhysicalActuatorSubstitution", transferSource);

            WriteEvent("learningV433EquivalentPhysicalActuatorFrontierCommitted", bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                originalEdgeId = step.EdgeId,
                originalEpisodeId = step.EpisodeId,
                originalKind = step.Kind,
                substituteEdgeId = bestEdge.Id,
                substituteExperienceKey = bestEdge.ExperienceKey,
                substituteKind = bestEdge.Kind,
                substituteNativeSuccesses = bestEdge.NativeSuccessCount,
                frontierIdentityDistance = bestIdentityDistance,
                frontierIdentityProof = bestIdentityProof,
                substituteObstacle = bestEdge.ObstacleFingerprint?.Name ?? string.Empty,
                substituteObstacleCenter = bestEdge.ObstacleFingerprint != null
                    ? Vec(bestEdge.ObstacleFingerprint.BoundsCenter) : null,
                substituteObstacleSize = bestEdge.ObstacleFingerprint != null
                    ? Vec(bestEdge.ObstacleFingerprint.BoundsSize) : null,
                body = Vec(bot.Position),
                originalEntry = Vec(stepEntry),
                liveLandingFrontier = Vec(stepExit),
                equivalentActuatorIdentityEntry = Vec(identityStepEntry),
                equivalentActuatorIdentityExit = Vec(identityStepExit),
