        private static bool TrySelectLearningV431AlternateLocalFrontierDestination(
            BotOwner bot,
            FollowerRouteMissionStep step,
            Vector3 leaderPosition,
            string capabilityFamily,
            out Vector3 destination,
            out Vector3 frontier,
            out string candidateVariant)
        {
            destination = default;
            frontier = default;
            candidateVariant = string.Empty;
            if (bot == null || step == null || !IsFinite(bot.Position) || !IsFinite(leaderPosition))
            {
                return false;
            }

            Vector3 rawEntry = IsFinite(step.RawEntry) ? step.RawEntry : step.Entry;
            Vector3 rawExit = IsFinite(step.RawExit) ? step.RawExit : step.Exit;
            Vector3 forward = GetFlatDirection(rawExit - rawEntry);
            if (forward.sqrMagnitude < 0.5f)
            {
                forward = GetFlatDirection(leaderPosition - bot.Position);
            }
            if (forward.sqrMagnitude < 0.5f)
            {
                return false;
            }

            Vector3 lateral = new Vector3(-forward.z, 0f, forward.x);
            float reach = LearningV319ZeroShotNearFrontierMaxDistance;
            // Reuse existing route-local authority envelopes instead of inventing a new rescue
            // search radius: 0 = direct unresolved frontier, 2.5 m = local-entry bridge,
            // 5.25 m = chain-local successor bridge. The direct candidate is retained only as
            // an evidence sample and is rejected below when it resolves to the authored entry.
            float[] lateralOffsets =
            {
                0f,
                RouteMissionLocalEntryBridgeMaxDistance,
                -RouteMissionLocalEntryBridgeMaxDistance,
                ChainLocalSuccessorBridgeMaxDistance,
                -ChainLocalSuccessorBridgeMaxDistance
            };

            float bestDistance = float.PositiveInfinity;
            float bestLateralMagnitude = float.PositiveInfinity;
            Vector3 authoredEntry = IsFinite(rawEntry) ? rawEntry : step.Entry;
            for (int index = 0; index < lateralOffsets.Length; index++)
            {
                float lateralOffset = lateralOffsets[index];
                Vector3 candidate = bot.Position + forward * reach + lateral * lateralOffset;
                if (string.Equals(capabilityFamily, "DropDown", StringComparison.OrdinalIgnoreCase))
                {
                    candidate.y += Mathf.Min(0f, rawExit.y - rawEntry.y);
                }

                StrictPathResult partial = CalculateStrictPath(bot.Position, candidate);
                if (partial == null || partial.StrictComplete || !partial.CalculateReturned ||
                    partial.Status != NavMeshPathStatus.PathPartial || partial.Corners == null ||
                    partial.Corners.Length == 0)
                {
                    continue;
                }

                Vector3 rawFrontier = partial.Corners[partial.Corners.Length - 1];
                if (!FollowerSafeTeleport.TryValidateLocalTraversalEntryAnchor(
                        bot, rawFrontier, out Vector3 validatedFrontier))
                {
                    continue;
                }

                float frontierDistance = GetPlanarDistance(bot.Position, validatedFrontier);
                if (frontierDistance <= RouteMissionBreadcrumbReachDistance ||
                    frontierDistance > LearningV319ZeroShotNearFrontierMaxDistance)
                {
                    continue;
                }

                // V431 is the ALTERNATE-frontier layer. V336 already owns bounded same-entry
                // recovery, so never silently turn this layer back into another attempt at the
                // authored entrance. This is location-independent: it compares only the current
                // route step identity and the already-established V2 endpoint equivalence radius.
                if (IsFinite(authoredEntry) &&
                    GetPlanarDistance(validatedFrontier, authoredEntry) <= LearningV2RevisionEndpointRadius)
                {
                    continue;
                }

                float lateralMagnitude = Mathf.Abs(lateralOffset);
                bool better = FollowerCapabilityHelperRules.TrySelectLearningV431AlternateLocalFrontierDestination_better_4170E1FF_1(frontierDistance,bestDistance) ||
                              (Mathf.Abs(frontierDistance - bestDistance) <= 0.001f &&
                               lateralMagnitude < bestLateralMagnitude);
                if (!better)
                {
                    continue;
                }

                bestDistance = frontierDistance;
                bestLateralMagnitude = lateralMagnitude;
                destination = candidate;
                frontier = validatedFrontier;
                candidateVariant = lateralOffset == 0f
                    ? "forward"
                    : (lateralOffset > 0f
                        ? "left:" + lateralMagnitude.ToString("0.00", CultureInfo.InvariantCulture)
                        : "right:" + lateralMagnitude.ToString("0.00", CultureInfo.InvariantCulture));
            }

            return IsFinite(destination) && IsFinite(frontier) && !string.IsNullOrEmpty(candidateVariant);
        }

        private static bool TryBeginLearningV431EquivalentLocalBarrierSelfRescue(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep step,
            out string transferSource)
        {
            transferSource = string.Empty;
            if ((bot == null) || mission == null ||
                step == null || !mission.LearningV431EquivalentBarrierRescuePending ||
                mission.LearningV431EquivalentBarrierRescueActive || HasActiveTraversalProbe(bot) ||
                mission.CurrentStepIndex != mission.LearningV431EquivalentBarrierRescueStepIndex ||
                step.EdgeId != mission.LearningV431EquivalentBarrierRescueEdgeId ||
                (mission.LearningV431EquivalentBarrierRescueEpisodeId > 0 &&
                 step.EpisodeId != mission.LearningV431EquivalentBarrierRescueEpisodeId))
            {
                return false;
            }

            Player leader = FollowerEnvironment.LocalPlayer;
            if (!IsLivePlayer(leader) || !IsFinite(leader.Position))
            {
                mission.LearningV431EquivalentBarrierRescuePending = false;
                return false;
            }

            string capabilityFamily = mission.LearningV431EquivalentBarrierRescueCapabilityFamily;
            if (string.IsNullOrEmpty(capabilityFamily))
            {
                capabilityFamily = GetLearningV431CapabilityFamily(step.Kind);
            }
            string recoverySource =
                "learningV431EquivalentLocalBarrierSelfRescue:" +
                mission.MissionId.ToString(CultureInfo.InvariantCulture) + ":" +
                mission.CurrentStepIndex.ToString(CultureInfo.InvariantCulture) + ":" +
                (capabilityFamily ?? string.Empty);

            // The ordinary leader path may be PathComplete only because NavMesh found a very long
            // detour around the barrier. V431 first discovers a DIFFERENT nearby PathPartial frontier
            // in a bounded route-local fan, explicitly excluding the authored entry. Only that one
            // nearest alternate frontier is handed to V319 for capability-backed zero-shot transfer.
            bool haveAlternateFrontier = TrySelectLearningV431AlternateLocalFrontierDestination(
                bot, step, leader.Position, capabilityFamily,
                out Vector3 localRecoveryDestination,
                out Vector3 alternateFrontier,
                out string alternateFrontierVariant);

            // Consume this one bounded opportunity whether or not a candidate exists. V319's
            // persistent template evidence will suppress unreliable skills, and the original route
            // step remains intact if no equivalent local frontier can be instantiated.
            mission.LearningV431EquivalentBarrierRescuePending = false;
            bool started = haveAlternateFrontier &&
                TryBeginLearningV319ZeroShotTraversalRecovery(
                    bot,
                    localRecoveryDestination,
                    recoverySource + ":alternateFrontier:" + alternateFrontierVariant,
                    out transferSource,
                    allowPendingRouteMission: true,
                    allowGraphlessActuatorSkillTransfer: true,
                    requiredCapabilityFamily: capabilityFamily,
                    excludedTemplateEdgeId: step.EdgeId,
                    allowExistingLocalNativeProven: false);

            if (!started)
            {
                mission.LearningV431EquivalentBarrierRescueActive = false;
                WriteEvent("learningV431EquivalentLocalBarrierSelfRescueUnavailable", bot, new
                {
                    missionId = mission.MissionId,
                    stepIndex = mission.CurrentStepIndex,
                    edgeId = step.EdgeId,
                    episodeId = step.EpisodeId,
                    kind = step.Kind,
                    capabilityFamily,
                    leader = Vec(leader.Position),
                    alternateFrontierFound = haveAlternateFrontier,
                    alternateFrontier = haveAlternateFrontier ? Vec(alternateFrontier) : null,
                    alternateFrontierVariant = alternateFrontierVariant ?? string.Empty,
                    source = mission.LearningV431EquivalentBarrierRescueSource ?? "unknown",
                    originalRouteDebtPreserved = true,
                    persistentLearningChanged = false,
                    action = "noEquivalentLocalFrontierKeepOriginalRouteDebtForExistingFallbackPolicy"
                });
                return false;
            }

            mission.LearningV431EquivalentBarrierRescueActive = true;
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;
            WriteEvent("learningV431EquivalentLocalBarrierSelfRescueCommitted", bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                edgeId = step.EdgeId,
                episodeId = step.EpisodeId,
                kind = step.Kind,
                capabilityFamily,
                transferSource,
                originalEntry = Vec(IsFinite(step.RawEntry) ? step.RawEntry : step.Entry),
                originalExit = Vec(IsFinite(step.RawExit) ? step.RawExit : step.Exit),
                localRecoveryDestination = Vec(localRecoveryDestination),
                alternateFrontier = Vec(alternateFrontier),
                alternateFrontierVariant,
                leader = Vec(leader.Position),
                originalRouteSuccessCredit = false,
                persistentLearningChanged = false,
                action = "V319TransientNativeSkillOwnsNearbyUnseenBarrierUntilPhysicalSuccessOrFailure"
            });
            return true;
        }

