                Vector3 learningV437Axis = learningV437Exit - learningV437Entry;
                learningV437Axis.y = 0f;
                float learningV437Span = learningV437Axis.magnitude;
                if (learningV437Span >= 0.25f)
                {
                    Vector3 learningV437Delta = probe.Player.Position - learningV437Entry;
                    learningV437Delta.y = 0f;
                    float learningV437Projection = Vector3.Dot(learningV437Delta, learningV437Axis / learningV437Span);
                    if (learningV437Projection > LearningV352JumpTakeoffCorridorMaxForwardOvershoot)
                    {
                        if (TryBeginLearningV433EquivalentPhysicalActuatorFrontierRecovery(
                                probe.Bot,
                                "learningV437FailedJumpMissedTakeoffFrontierSamePortalSubstitution:" + (source ?? "unknown"),
                                out string learningV437TransferSource,
                                allowActiveProbe: true))
                        {
                            WriteEvent("learningV437FailedJumpYieldedImmediatelyToSamePortalActuator", probe.Bot, new
                            {
                                missionId = mission.MissionId,
                                stepIndex,
                                edgeId = probe.LearnedEdgeId,
                                kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                                projection = learningV437Projection,
                                maxForwardOvershoot = LearningV352JumpTakeoffCorridorMaxForwardOvershoot,
                                transferSource = learningV437TransferSource,
                                failureStage = failureStage ?? string.Empty,
                                traversalSuccessRecorded = false,
                                persistentLearningChanged = false,
                                bodyRelocated = false,
                                action = "failedJumpAlreadyPastLegalTakeoffPlaneCannotRetrySameEntryUseBoundedSamePortalNativeActuator"
                            });
                            FinalizeUnifiedTraversalFailure(
                                probe, "learningV437MissedJumpFrontierSubstitution:" + (source ?? "unknown"));
                            return true;
                        }

                        // V4.54: V449 already proved that running backward into an actuator entry
                        // which is behind the current body is physically impossible. Remember that
                        // fact while the existing current-body equivalent/far-side rescue layers get
                        // one chance below; if they cannot consume the body, fall through to Assist
                        // instead of scheduling V336's guaranteed-to-fail same-entry retry.
                        learningV454MissedJumpFrontierCannotReacquireSameEntry =
                            true;
                    }
                }
            }

            // LearningV4.31: when acquisition itself failed, do not spend the first bounded
            // route-level rescue returning to the same stale entry. Retire this failed probe and
            // let the next RouteMission beat instantiate a nearby unseen equivalent barrier from
            // Native-Proven skill evidence. Executor/landing failures still keep V336's same-entry
            // retry first because the authored entrance was demonstrably reachable.
            if (TryArmLearningV431EquivalentLocalBarrierSelfRescue(
                    probe, mission, step, source, failureStage))
            {
                return true;
            }

            if (TryBeginLearningV337FarSideJumpPhysicalRescue(probe, source, failureStage))
            {
                return true;
            }

            if ((probe.JumpAttempted) &&
                TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment phaseCommitment) &&
                phaseCommitment != null && string.Equals(phaseCommitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                Vector3 phaseEntry = IsFinite(phaseCommitment.RawEntry) ? phaseCommitment.RawEntry : phaseCommitment.Entry;
                Vector3 phaseExit = IsFinite(phaseCommitment.RawExit) ? phaseCommitment.RawExit : phaseCommitment.Exit;
                Vector3 phaseAxis = phaseExit - phaseEntry;
                phaseAxis.y = 0f;
                float phaseSpan = phaseAxis.magnitude;
                if (phaseSpan >= 0.25f)
                {
                    Vector3 phaseDelta = probe.Player.Position - phaseEntry;
                    phaseDelta.y = 0f;
                    float phaseProjection = Vector3.Dot(phaseDelta, phaseAxis / phaseSpan);
                    float phaseRequired = Mathf.Max(0.45f, phaseSpan * JumpNativeLandingMinProjectionRatio);
                    if (phaseProjection >= phaseRequired)
                    {
                        WriteEvent("learningV337FarSideJumpSelfRescueEntryRetrySuppressed", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            source = source ?? "unknown",
                            failureStage = failureStage ?? string.Empty,
                            projection = phaseProjection,
                            requiredProjection = phaseRequired,
                            action = ("neverReturnFarSidePhysicalBodyToEntryContinueCurrentBodyVerify")
                        });
                        {
                            // V337 correctly proved that this body epoch is already beyond the Jump
                            // entry, but returning false here let the V329 caller schedule the same
                            // action again. Keep the current far-side body in the existing egress /
                            // landing verifier instead. Landing proof remains mandatory; only the
                            // backward re-entry transaction is forbidden.
                            BeginUnifiedTraversalEgressOrVerify(
                                probe, "learningV408FarSideJumpCurrentBodyVerify:" + (source ?? "unknown"));
                            WriteEvent("learningV408FarSideJumpRetryConvertedToCurrentBodyVerify", probe.Bot, new
                            {
                                edgeId = probe.LearnedEdgeId,
                                source = source ?? "unknown",
                                failureStage = failureStage ?? string.Empty,
                                projection = phaseProjection,
                                requiredProjection = phaseRequired,
                                landingProofStillRequired = true,
                                newPhysicalTransaction = false,
                                returnToEntry = false,
                                persistentLearningChanged = false,
                                action = "farSidePartialCrossingStaysForwardOnlyUntilExistingLandingOrRecoveryConsumerResolves"
                            });
                            return true;
                        }
                        return false;
                    }
                }
            }

            if (learningV454MissedJumpFrontierCannotReacquireSameEntry)
            {
                WriteEvent("learningV454MissedJumpSameEntryRetrySuppressed", probe.Bot, new
                {
                    missionId = mission.MissionId,
                    stepIndex,
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                    source = source ?? "unknown",
                    failureStage = failureStage ?? string.Empty,
                    body = probe.Player != null ? Vec(probe.Player.Position) : Vec(probe.Bot.Position),
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "missedLegalTakeoffPlaneHasNoCurrentBodyNativeSubstituteYieldDirectlyToExistingAssistRecoveryLayer"
                });
                return false;
            }

            if (mission.LearningV336SelfRescueStepIndex != stepIndex ||
                mission.LearningV336SelfRescueEdgeId != probe.LearnedEdgeId)
            {
                mission.LearningV336SelfRescueStepIndex = stepIndex;
                mission.LearningV336SelfRescueEdgeId = probe.LearnedEdgeId;
                mission.LearningV336SelfRescueAttempts = 0;
            }

            // Reuse the already-proven V3.2 entry reacquire budget instead of inventing a wider
            // traversal/recovery threshold. One route-level self-rescue is therefore allowed after
            // the in-probe reacquire is exhausted; Assist remains the second layer.
            int maxAttempts = Math.Max(1, LearningV32EntryMaxReacquireAttempts);
            if (mission.LearningV336SelfRescueAttempts >= maxAttempts)
            {
                // V434: after the exact actuator has consumed its bounded retry, prefer an already
                // Native-Proven actuator at the SAME physical frontier before a different-frontier
                // rescue or Teleport. Selection may be made while this failed probe is still active,
                // but its transient commitment cannot execute until FinalizeUnifiedTraversalFailure
                // retires the old probe. This closes the V433 "commit selected but never dispatched"
                // lifetime gap without allowing two actuators to own the body simultaneously.
                if ((IsLearningV433ObstacleClearanceActuatorKind(step?.Kind)) &&
                    TryBeginLearningV433EquivalentPhysicalActuatorFrontierRecovery(
                        probe.Bot,
                        "learningV434ExhaustedExactActuatorSameFrontierSubstitution:" +
                            (source ?? "unknown"),
                        out string learningV434ExhaustedTransferSource,
                        allowActiveProbe: true))
                {
                    WriteEvent("learningV434ExhaustedExactActuatorYieldedToSameFrontierSubstitute", probe.Bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex,
                        originalEdgeId = probe.LearnedEdgeId,
                        originalKind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                        transferSource = learningV434ExhaustedTransferSource,
                        failureStage = failureStage ?? string.Empty,
                        attempts = mission.LearningV336SelfRescueAttempts,
                        maxAttempts,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "terminalizeFailedExactProbeThenDispatchAlreadySelectedSameFrontierNativeActuator"
                    });
                    FinalizeUnifiedTraversalFailure(
                        probe,
                        "learningV434SameFrontierSubstitution:" + (source ?? "unknown"));
                    return true;
                }

                // If the original entry was reachable but the bounded same-entry transaction also
                // failed, give one final physical alternative-frontier attempt before Assist /
                // Teleport. This remains one transient V319 instance and cannot loop.
                if (TryArmLearningV431EquivalentLocalBarrierSelfRescue(
                        probe, mission, step, source, failureStage, forceAfterSameEntryExhaustion: true))
                {
                    return true;
                }

                if ((IsLearningV353StrictActuatorBarrierKind(step?.Kind)))
                {
                    mission.LearningV357ExhaustedBarrierStepIndex = stepIndex;
                    mission.LearningV357ExhaustedBarrierEdgeId = probe.LearnedEdgeId;
                    mission.LearningV357ExhaustedBarrierEndBreadcrumbSequence =
                        step != null ? step.EndBreadcrumbSequence : 0;
                    mission.LearningV357ExhaustedBarrierAt = Time.time;
                    WriteEvent("learningV357ExhaustedActuatorDebtAwaitingDownstreamBodyEpoch", probe.Bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex,
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                        endBreadcrumbSequence = mission.LearningV357ExhaustedBarrierEndBreadcrumbSequence,
                        source = source ?? "unknown",
                        failureStage = failureStage ?? string.Empty,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "allowOnlyFutureDownstreamBodyEpochToRetireExecutionDebt"
                    });
                }

                WriteEvent("learningV336TraversalSelfRescueExhausted", probe.Bot, new
                {
                    missionId = mission.MissionId,
                    stepIndex,
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                    source = source ?? "unknown",
                    failureStage = failureStage ?? string.Empty,
                    attempts = mission.LearningV336SelfRescueAttempts,
                    maxAttempts,
                    action = "allowExistingAssistThenRecoveryTeleportFallback"
                });
                return false;
            }

            mission.LearningV336SelfRescueAttempts++;
            mission.LearningV336SelfRescueForceNativeNextAttempt = true;
            mission.LearningV336SelfRescueForceNativeSource = source ?? "unknown";
            // The new transaction must get a fresh local convergence budget. Keep a dedicated
            // SelfRescueAttempts counter so this reset cannot create an unbounded loop.
            mission.LocalRecoveryAttempts = 0;
            mission.NextLocalRecoveryCountAt = Time.time + RouteMissionLocalRecoveryCountInterval;

            float retryAt = Time.time + RouteMissionMoveRetrySeconds;
            // A self-rescue transaction owns this same-step retry cadence. Retire any stale local
            // recovery backoff from the failed transaction so it cannot silently stretch the proven
            // 0.45s RouteMission retry into another multi-second deadband.
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.AttemptOrExplicitHold,retryAt);
            mission.TraversalRetryMovementHoldUntil = retryAt;
            string retryKey = (probe.Bot.ProfileId ?? string.Empty) + ":" +
                              probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture);
            LearnedTraversalRetryAfter[retryKey] = retryAt;

            WriteEvent("learningV336TraversalSelfRescueArmed", probe.Bot, new
            {
                missionId = mission.MissionId,
                stepIndex,
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                source = source ?? "unknown",
                failureStage = failureStage ?? string.Empty,
                attempt = mission.LearningV336SelfRescueAttempts,
                maxAttempts,
                retrySeconds = RouteMissionMoveRetrySeconds,
                forceNativeNextAttempt = true,
                nativeExecutorConsumed = probe.NativeExecutorConsumed,
                nativeActuatorTriggered = WasLearningV330NativeActuatorActuallyAttempted(probe),
                assistedReplayAttempted = probe.AssistedReplayAttempted,
                teleportAttempted = probe.TraversalTeleportAttempted,
                singlePhysicalTransactionPreserved = true,
                action = "terminalizeCurrentProbePreserveCurrentRouteStepReacquireWithNormalMoverAsNewTransaction"
            });

            FinalizeUnifiedTraversalFailure(
                probe, "learningV336TraversalSelfRescue:" + (source ?? "unknown"));
            return true;
        }

        private static bool TryProveLearningV441JumpTypedSuccessorFrontier(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            out TraversalEpisodeMetadata currentEpisode,
            out TraversalEpisodeMetadata successorEpisode,
            out LearnedTraversalEdge successorEdge,
            out Vector3 successorEntry,
            out float successorDistance,
            out float forwardProjection,
            out float requiredProjection,
            out float verticalDelta,
            out string authoritySource)
        {
            currentEpisode = null;
            successorEpisode = null;
            successorEdge = null;
            successorEntry = default;
            successorDistance = float.PositiveInfinity;
            forwardProjection = 0f;
            requiredProjection = float.PositiveInfinity;
            verticalDelta = float.PositiveInfinity;
            authoritySource = string.Empty;
            bool learningV451MonotonicJumpPassage = HasLearningV451MonotonicJumpPhysicalPassageProof(probe);
            if ((probe?.Bot == null) || probe.Player == null ||
                commitment == null || !probe.JumpAttempted ||
                (!probe.NativeTraversalStarted && !learningV451MonotonicJumpPassage) ||
                !string.Equals(commitment.Kind ?? probe.TraversalKind ?? probe.RequestedTraversalKind,
                    "Jump", StringComparison.OrdinalIgnoreCase) ||
                !IsEffectivelySupportedForProbe(probe.Bot, probe.Player))
            {
                return false;
            }

            currentEpisode = TraversalEpisodeStream.LastOrDefault(item =>
                item != null && item.EpisodeId == probe.TraversalEpisodeId);
            if (currentEpisode == null || !IsFinite(currentEpisode.RawStart) || !IsFinite(currentEpisode.RawEnd))
            {
                return false;
            }

            FollowerRouteMission mission = null;
            FollowerRouteMissionStep canonicalSuccessorStep = null;
            bool canonicalMissionSuccessor =
                !string.IsNullOrEmpty(probe.Bot.ProfileId) &&
                FollowerRouteMissions.TryGetValue(probe.Bot.ProfileId, out mission) && mission != null &&
                TryGetLearningV368RouteMissionCanonicalSuccessor(
                    probe, mission, out successorEpisode, out successorEdge, out canonicalSuccessorStep);
            if (canonicalMissionSuccessor)
            {
                authoritySource = "canonicalRouteMission";
            }
            else
            {
                if (!TryGetNextTraversalEpisode(probe.TraversalEpisodeId, out successorEpisode) ||
                    successorEpisode == null)
                {
                    return false;
                }
                TraversalEpisodeMetadata successorEpisodeLocal = successorEpisode;
                successorEdge = LearnedTraversalEdges.FirstOrDefault(item =>
                    item != null && item.Id == successorEpisodeLocal.EdgeId);
                authoritySource = "episodeChain";
            }
            if (successorEpisode == null || successorEdge == null ||
                !IsFinite(successorEpisode.RawStart) || !IsFinite(successorEpisode.RawEnd))
            {
                return false;
            }

            bool sameChainImmediate = IsImmediateTraversalChainSuccessor(
                currentEpisode, successorEpisode, out int breadcrumbGap, out float spatialGap);
            int canonicalBreadcrumbGap = int.MaxValue;
            float canonicalSpatialGap = float.PositiveInfinity;
            bool canonicalImmediate = canonicalMissionSuccessor &&
                IsLearningV441CanonicalMissionImmediateSuccessor(
                    currentEpisode, successorEpisode,
                    out canonicalBreadcrumbGap, out canonicalSpatialGap);
            if (!sameChainImmediate && !canonicalImmediate)
            {
                return false;
            }
            if (canonicalImmediate)
            {
                breadcrumbGap = canonicalBreadcrumbGap;
                spatialGap = canonicalSpatialGap;
            }

            string currentKind = commitment.Kind ?? probe.TraversalKind ?? probe.RequestedTraversalKind ?? "Jump";
            if (!LearningV354CanBridgeOffNavMesh(currentKind, successorEdge.Kind))
            {
                return false;
            }

            successorEntry = successorEpisode.RawStart;
            Vector3 body = probe.Player.Position;
            successorDistance = GetPlanarDistance(body, successorEntry);
            verticalDelta = Mathf.Abs(body.y - successorEntry.y);
            if (successorDistance > JumpNativeLandingMaxExitPlanarDistance ||
                verticalDelta > UnifiedTraversalVerifyMaxNavVertical)
            {
                return false;
            }

            Vector3 axis = currentEpisode.RawEnd - currentEpisode.RawStart;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < 0.35f)
            {
                return false;
            }
            Vector3 direction = axis / span;
            Vector3 fromEntry = body - currentEpisode.RawStart;
            fromEntry.y = 0f;
            forwardProjection = Vector3.Dot(fromEntry, direction);
            requiredProjection = Mathf.Max(0.45f, span * 0.60f);
            if (forwardProjection < requiredProjection)
            {
                return false;
            }

            float entryDistance = GetPlanarDistance(body, currentEpisode.RawStart);
            if (successorDistance + 0.10f >= entryDistance)
            {
                return false;
            }

            if (ShouldEmitDiagnostic(
                    "learningV441JumpTypedSuccessorFrontierProven:" +
                    probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture) + ":" +
                    successorEdge.Id.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.12f))
            {
                WriteEvent("learningV441JumpTypedSuccessorFrontierProven", probe.Bot, new
                {
                    missionId = mission?.MissionId ?? 0,
                    edgeId = probe.LearnedEdgeId,
                    episodeId = probe.TraversalEpisodeId,
                    chainId = probe.TraversalChainId,
                    successorEdgeId = successorEdge.Id,
                    successorEpisodeId = successorEpisode.EpisodeId,
                    successorChainId = successorEpisode.ChainId,
                    successorKind = successorEdge.Kind,
                    authoritySource,
                    sameChainImmediate,
                    canonicalImmediate,
                    breadcrumbGap = breadcrumbGap == int.MaxValue ? (int?)null : breadcrumbGap,
                    spatialGap,
                    position = Vec(body),
                    currentRawStart = Vec(currentEpisode.RawStart),
                    currentRawEnd = Vec(currentEpisode.RawEnd),
                    successorEntry = Vec(successorEntry),
                    successorDistance,
                    verticalDelta,
                    forwardProjection,
                    requiredProjection,
                    navMeshRequired = false,
                    capabilityFinishOffNavMesh = GetLearningV354ActionProfile(currentKind).CanFinishOffNavMesh,
                    capabilitySuccessorAcquireOffNavMesh = GetLearningV354ActionProfile(successorEdge.Kind).CanAcquireFromOffNavMesh,
                    bodyRelocated = false,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "typedImmediateSuccessorEntryIsPhysicalLandingProofNavMeshIsAdvisory"
                });
            }
            return true;
        }

        // TryRecoverPlayerValidatedTraversal is owned by the shared native recovery host.

        // FinalizeOrEscalateTraversalFailure is owned by the shared capability failure host.

        // EscalateTraversalFailureMonotonic is owned by the shared capability failure host.

        private static bool TryGetLearningV331CurrentGroundContinuationProof(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            out float projection,
            out float requiredProjection,
            out float lateralDeviation,
            out float exitDistance)
        {
            projection = 0f;
            requiredProjection = 0f;
            lateralDeviation = 0f;
            exitDistance = float.PositiveInfinity;
            if (probe?.Player == null || commitment == null)
            {
                return false;
            }

            string kind = commitment.Kind ?? probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            if (!string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                bool vaultClimbFarSide = IsVaultClimbFarSideForEgress(
                    probe, commitment, out projection, out requiredProjection);
                exitDistance = GetPlanarDistance(
                    probe.Player.Position,
                    IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit);
                return vaultClimbFarSide && IsEffectivelySupportedForProbe(probe.Bot, probe.Player);
            }

            Vector3 entry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 exit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 axis = exit - entry;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < 0.35f)
            {
                return false;
            }

            Vector3 direction = axis / span;
            Vector3 fromEntry = probe.Player.Position - entry;
            fromEntry.y = 0f;
            projection = Vector3.Dot(fromEntry, direction);
            Vector3 lateral = fromEntry - direction * projection;
            lateralDeviation = lateral.magnitude;
            exitDistance = GetPlanarDistance(probe.Player.Position, exit);
            requiredProjection = Mathf.Max(0.45f, span * JumpNativeLandingMinProjectionRatio);
            bool supported = IsEffectivelySupportedForProbe(probe.Bot, probe.Player) ||
                (NavMesh.SamplePosition(probe.Player.Position, out NavMeshHit landingHit, 0.90f, NavMesh.AllAreas) &&
                 Mathf.Abs(landingHit.position.y - probe.Player.Position.y) <= UnifiedTraversalVerifyMaxNavVertical);
            bool strictLandingProof =
                FollowerCapabilityHelperRules.TryGetLearningV331CurrentGroundContinuationProof_strictLandingProof_9749B9C6_1(supported,projection,requiredProjection,lateralDeviation,JumpNativeLandingMaxLateralDeviation,exitDistance,JumpNativeLandingMaxExitPlanarDistance);
            if (strictLandingProof)
            {
                return true;
            }

            // LearningV4.30: the strict landing window is a proof-acquisition window, not a
            // permanent leash. Once a real Native Jump has started and the supported physical body
            // has continued beyond the authored exit plane, increasing distance from RawExit is
            // downstream progress. Treating that same progress as proof loss lets the stale Jump
            // probe fail later and reanimate an older rawExit/entry consumer.
            bool nativeJumpEpochObserved =
                FollowerCapabilityHelperRules.TryGetLearningV331CurrentGroundContinuationProof_nativeJumpEpochObserved_9749B9C6_2(probe.JumpAttempted,probe.NativeTraversalStarted,probe.NativeStateObserved,probe.NativeLandingRejected,probe.JumpPostLandingCommitStartedAt);
            bool monotonicFarSide =
                FollowerCapabilityHelperRules.TryGetLearningV331CurrentGroundContinuationProof_monotonicFarSide_9749B9C6_3(nativeJumpEpochObserved,supported,projection,span);
            if (monotonicFarSide)
            {
                if (ShouldEmitDiagnostic(
                        "learningV430JumpPhysicalFrontierMonotonic:" +
                            probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture),
                        probe.Bot, 0.20f))
                {
                    WriteEvent("learningV430JumpPhysicalFrontierMonotonic", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        position = Vec(probe.Player.Position),
                        projection,
                        requiredProjection,
                        authoredSpan = span,
                        lateralDeviation,
                        exitDistance,
                        supported,
                        nativeTraversalStarted = probe.NativeTraversalStarted,
                        nativeStateObserved = probe.NativeStateObserved,
                        nativeLandingRejected = probe.NativeLandingRejected,
                        traversalSuccessRecorded = false,
                        nativeSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "strictLandingWindowCannotBecomeHistoricalReturnTargetAfterPhysicalBodyCrossesExitPlane"
                    });
                }
                return true;
            }

            return false;
        }

        private static bool TryBeginLearningV331NativeGroundContinuation(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string source)
        {
            if ((probe?.Player == null) ||
                probe.Bot == null || commitment == null || !IsActiveProbe(probe) ||
                !IsEffectivelySupportedForProbe(probe.Bot, probe.Player))
            {
                return false;
            }

            string kind = commitment.Kind ?? probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            bool jump = string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase);
            bool vaultClimb = string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                              string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase);
            if ((!jump && !vaultClimb) || (jump && !probe.JumpAttempted))
            {
                return false;
            }

            Vector3 entry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 exit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 axis = exit - entry;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < 0.25f)
            {
                return false;
            }
            Vector3 direction = axis / span;
            Vector3 fromEntry = probe.Player.Position - entry;
            fromEntry.y = 0f;
            float currentProjection = Vector3.Dot(fromEntry, direction);
            float exitDistance = GetPlanarDistance(probe.Player.Position, exit);

            if (TryGetLearningV331CurrentGroundContinuationProof(
                    probe, commitment, out float currentProofProjection, out float currentRequiredProjection,
                    out float currentLateral, out float currentExitDistance))
            {
                if (jump)
                {
                    // Current-body proof, not only the older latched witness, owns completion.
                    IsNativeTraversalAlreadyOnFarSide(probe, commitment, exit, out _, out _);
                }
                probe.NativePartialCrossingObserved = false;
                if ((jump) &&
                    probe.LearningV330NativeJumpQualifiedLandingWitness)
                {
                    WriteEvent("learningV437QualifiedNativeJumpLandingCommitsExecutionDebt", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        kind,
                        source = source ?? string.Empty,
                        position = Vec(probe.Player.Position),
                        witness = Vec(probe.LearningV330NativeJumpQualifiedLandingPosition),
                        projection = currentProofProjection,
                        requiredProjection = currentRequiredProjection,
                        lateralDeviation = currentLateral,
                        exitDistance = currentExitDistance,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "qualifiedPhysicalLandingIsMonotonicSuccessFrontierDoNotReopenGenericEgressFailureLifecycle"
                    });
                    CommitUnifiedTraversalSuccess(
                        probe, "learningV437QualifiedNativeJumpLandingAtomicSuccess");
                    return true;
                }
                WriteEvent("learningV331NativeGroundContinuationAlreadySatisfied", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind,
                    source = source ?? string.Empty,
                    position = Vec(probe.Player.Position),
                    projection = currentProofProjection,
                    requiredProjection = currentRequiredProjection,
                    lateralDeviation = currentLateral,
                    exitDistance = currentExitDistance
                });
                BeginUnifiedTraversalEgressOrVerify(
                    probe, "learningV331NativeGroundContinuationAlreadySatisfied:" + (source ?? "unknown"));
                return true;
            }

            // The continuation target may approach RawExit, but it may never move backward to a
            // historical landing point. If RawExit is no longer forward of the real body, try one
            // bounded downstream breadcrumb; otherwise terminate rather than reverse.
            Vector3 desiredTarget = exit;
            Vector3 targetDelta = desiredTarget - entry;
            targetDelta.y = 0f;
