            float computedDuration = Mathf.Max(planarDistance, directDistance * 0.75f) / replaySpeed;
            float authoredDuration =
                FollowerCapabilityHelperRules.TryBeginAssistedTraversalReplay_authoredDuration_12B1232E_3(probe.DemonstratedTraversalDuration,probe.DemonstratedTraversalDuration)
                    ? probe.DemonstratedTraversalDuration
                    : computedDuration;
            // Landing-resume targets are intentionally farther than RawEnd. Do not compress that
            // extra ground/landing distance into the old vault-animation duration.
            if ((assistedVault && commitment.HasSettledExit) || assistedDropDown || probe.JumpBridgeActive)
            {
                authoredDuration = Mathf.Max(authoredDuration, computedDuration);
            }
            probe.AssistedReplayDuration = Mathf.Clamp(
                authoredDuration,
                AssistedReplayMinDuration,
                probe.JumpBridgeActive ? JumpBridgeMaxDuration : AssistedReplayMaxDuration);

            float baseArc = string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase)
                ? 0.62f
                : (string.Equals(commitment.Kind, "Climb", StringComparison.OrdinalIgnoreCase)
                    ? 0.30f
                    : (assistedWalkThrough ? 0.08f : 0.46f));
            probe.AssistedReplayArcHeight = assistedDropDown
                ? 0f
                : (assistedWalkThrough
                    ? Mathf.Clamp(baseArc + Mathf.Abs(requestedExit.y - start.y) * 0.04f, 0.05f, 0.16f)
                    : Mathf.Clamp(
                        baseArc + Mathf.Max(0f, requestedExit.y - start.y) * 0.10f,
                        0.24f,
                        0.82f));
            if (probe.JumpBridgeActive && IsFinite(probe.JumpBridgeLandingTarget))
            {
                float midY = (start.y + requestedExit.y) * 0.5f;
                float requiredArc = Mathf.Max(0.62f, probe.JumpBridgeCrestY + JumpBridgeCrestClearance - midY);
                probe.AssistedReplayArcHeight = Mathf.Clamp(requiredArc, 0.62f, 2.60f);
            }

            float obstacleHeight = 0f;
            try
            {
                obstacleHeight = Mathf.Max(0f, probe.Player.VaultingParameters?.VaultingHeight ?? 0f);
            }
            catch
            {
                obstacleHeight = 0f;
            }
            float obstacleTopY = start.y + obstacleHeight;
            if (assistedWalkThrough)
            {
                // Grounded seam replay: only enough vertical clearance to survive tiny curb/step
                // discontinuities. Do not turn a WalkThrough fallback into a visible Vault arc.
                probe.AssistedReplayLiftY = Mathf.Max(start.y, requestedExit.y) + 0.10f;
            }
            else
            {
                float minimumTopY = Mathf.Max(start.y, requestedExit.y) + AssistedReplayMinimumLift;
                probe.AssistedReplayLiftY = Mathf.Max(
                    minimumTopY,
                    obstacleTopY + AssistedReplayTopClearance);
            }
            probe.AssistedReplayLastDistance = directDistance;
            probe.AssistedReplayLastProgressAt = Time.time;
            probe.AssistedReplayLastObservedPosition = start;
            probe.AssistedReplayActualDisplacement = 0f;
            probe.AssistedReplayPhase = "Lift";
            probe.TraversalKind = string.IsNullOrWhiteSpace(commitment.Kind) ? probe.RequestedTraversalKind : commitment.Kind;
            probe.TriggerPosition = start;

            Vector3 direction = GetFlatDirection(requestedExit - start);
            if (direction.sqrMagnitude > 0.5f)
            {
                probe.RequestedDirection = direction;
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-64F7001EBEAE",@probe?.Bot,direction);
            }

            // Do not StopMove here. V1.3.18 transfers only this follower's fixed-update ownership
            // to Assisted Replay, leaving its existing route/momentum intact for immediate resume on
            // the far side. With per-follower probes, no other teammate is paused or serialized.
            if (probe.Bot.Mover != null)
            {
                probe.Bot.Mover.SetBotMoverPause("R1-04B86A3DC429",@probe?.Bot,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-E00117CA50D2",@probe?.Bot);
            }
            HoldForwardInput(probe);
            TryStartAssistedTraversalAnimation(probe);
            bool assistedCollisionLease = false;
            if (assistedWalkThrough)
            {
                LearnedTraversalEdge assistedEdge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == commitment.EdgeId);
                assistedCollisionLease = TryAcquireAssistedObstacleCollisionLease(
                    probe, assistedEdge, probe.AssistedReplayStart, probe.AssistedReplayExit, "walkThroughAssistedStart");
            }

            WriteEvent("assistedTraversalReplayStarted", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                kind = commitment.Kind,
                source,
                targetSource = probe.JumpBridgeActive
                    ? "jumpBridgeFarSideLanding"
                    : (assistedDropDown && commitment.HasSettledExit
                        ? "dropDownSettledExit"
                        : (assistedVault && commitment.HasSettledExit ? "landingResumeSettledExit" : "rawExit")),
                start = Vec(start),
                exit = Vec(requestedExit),
                directDistance,
                planarDistance,
                duration = probe.AssistedReplayDuration,
                arcHeight = probe.AssistedReplayArcHeight,
                liftY = probe.AssistedReplayLiftY,
                collisionLease = assistedCollisionLease,
                demonstratedApproachSpeed = probe.DemonstratedApproachSpeed,
                demonstratedApproachMode = probe.DemonstratedApproachMode,
                demonstratedTraversalDuration = probe.DemonstratedTraversalDuration,
                jumpBridgeActive = probe.JumpBridgeActive,
                jumpBridgeCrestY = probe.JumpBridgeActive ? probe.JumpBridgeCrestY : 0f,
                jumpBridgeLandingSampleIndex = probe.JumpBridgeActive ? probe.JumpBridgeLandingSampleIndex : -1
            });
            return true;
        }

        private static float GetLearningV329RequiredJumpTakeoffSpeed(ProbeRuntime probe)
        {
            if (probe == null)
            {
                return 0f;
            }
            float demonstratedSpeed = Mathf.Max(0f, probe.DemonstratedApproachSpeed);
            if (string.Equals(probe.DemonstratedApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase) ||
                demonstratedSpeed >= 4.25f)
            {
                return Mathf.Max(4.25f, demonstratedSpeed);
            }
            if (string.Equals(probe.DemonstratedApproachMode, "Run", StringComparison.OrdinalIgnoreCase) ||
                demonstratedSpeed >= 1.55f)
            {
                return Mathf.Max(1.55f, demonstratedSpeed);
            }
            return demonstratedSpeed;
        }

        private static float GetLearningV329PlanarSpeed(Player player)
        {
            if (player == null)
            {
                return 0f;
            }
            Vector3 velocity = GetCapabilityJumpPlanarVelocity(player);
            velocity.y = 0f;
            return velocity.magnitude;
        }

        private static bool IsLearningV414FollowerRunJumpCapabilityReadyForEdge(
            int edgeId,
            float planarSpeed,
            out float learnedMinSuccessfulSpeed,
            out int successfulRunSamples)
        {
            learnedMinSuccessfulSpeed = 0f;
            successfulRunSamples = 0;
            if ((edgeId <= 0))
            {
                return false;
            }
            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == edgeId);
            if (edge == null || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !LearningV322SkillEvidence.TryGetValue(
                    edge.ExperienceKey, out LearningV322PersistentSkillEvidenceRecord record) ||
                record == null)
            {
                return false;
            }
            successfulRunSamples = Math.Max(0, record.NativeJumpRunTakeoffSuccesses);
            learnedMinSuccessfulSpeed = Mathf.Max(0f, record.NativeJumpRunMinSuccessfulTakeoffSpeed);
            return successfulRunSamples > 0 &&
                   learnedMinSuccessfulSpeed > 0f &&
                   planarSpeed >= learnedMinSuccessfulSpeed;
        }

        private static bool IsLearningV418PlayerProvenRunJumpTrialReadyForEdge(
            int edgeId,
            float planarSpeed,
            out float playerMinObservedRunSpeed,
            out int playerRunDemonstrations)
        {
            playerMinObservedRunSpeed = 0f;
            playerRunDemonstrations = 0;
            if ((edgeId <= 0) ||
                planarSpeed < RollingTraversalMinSpeed)
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == edgeId);
            if (edge == null || string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !LearningV322SkillEvidence.TryGetValue(
                    edge.ExperienceKey, out LearningV322PersistentSkillEvidenceRecord record) ||
                record == null)
            {
                return false;
            }

            playerRunDemonstrations = Math.Max(0, record.PlayerJumpRunDemonstrations);
            playerMinObservedRunSpeed = Mathf.Max(0f, record.PlayerJumpRunMinObservedTakeoffSpeed);
            // Player absolute speed is semantic mode evidence, not a follower threshold. Each
            // independent player Run+Jump proof authorizes exactly one follower Run trial on this
            // ExperienceKey. TriggerNativeJump consumes that proof before TryJump. A failed trial
            // therefore closes again until fresh player proof exists; a real native success instead
            // promotes follower-local capability through the existing V414 counters.
            return playerRunDemonstrations > Math.Max(0, record.PlayerJumpRunTrialAttempts);
        }

        private static bool TryConsumeLearningV418PlayerProvenRunJumpTrial(ProbeRuntime probe)
        {
            if ((probe?.Player == null) ||
                probe.Player.CurrentStateName != EPlayerState.Run || probe.LearningV418PlayerRunTrialConsumed ||
                probe.LearnedEdgeId <= 0)
            {
                return false;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == probe.LearnedEdgeId);
            if (edge == null || !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(edge.ApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase) ||
                string.IsNullOrWhiteSpace(edge.ExperienceKey) ||
                !LearningV322SkillEvidence.TryGetValue(
                    edge.ExperienceKey, out LearningV322PersistentSkillEvidenceRecord record) || record == null)
            {
                return false;
            }

            float planarSpeed = GetLearningV329PlanarSpeed(probe.Player);
            if (IsLearningV414FollowerRunJumpCapabilityReadyForEdge(
                    edge.Id, planarSpeed, out _, out _))
            {
                return false;
            }

            int demonstrations = Math.Max(0, record.PlayerJumpRunDemonstrations);
            int attempts = Math.Max(0, record.PlayerJumpRunTrialAttempts);
            if (demonstrations <= attempts || planarSpeed < RollingTraversalMinSpeed)
            {
                return false;
            }

            record.PlayerJumpRunTrialAttempts = attempts + 1;
            record.LastPolicyVersion = TraversalExperiencePolicyVersion;
            record.LastUpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            learningV322SkillEvidenceDirty = true;
            probe.LearningV418PlayerRunTrialConsumed = true;
            probe.LearningV418PlayerRunTrialOrdinal = record.PlayerJumpRunTrialAttempts;
            probe.LearningV418PlayerRunTrialDemonstrationCount = demonstrations;
            WriteEvent("learningV418PlayerProvenRunJumpTrialConsumed", probe.Bot, new
            {
                edgeId = edge.Id,
                experienceKey = edge.ExperienceKey,
                planarSpeed,
                demonstrationCount = demonstrations,
                trialAttempt = record.PlayerJumpRunTrialAttempts,
                previousTrialFailures = record.PlayerJumpRunTrialFailures,
                followerRunCapability = false,
                action = "consumeExactlyOnePlayerProofBeforeNativeTryJumpFreshProofRequiredAfterFailure"
            });
            return true;
        }

        private static bool IsLearningV418PlayerProvenRunJumpTrialReady(
            ProbeRuntime probe,
            float planarSpeed,
            out float playerMinObservedRunSpeed,
            out int playerRunDemonstrations)
        {
            return IsLearningV418PlayerProvenRunJumpTrialReadyForEdge(
                probe?.LearnedEdgeId ?? 0,
                planarSpeed,
                out playerMinObservedRunSpeed,
                out playerRunDemonstrations);
        }

        private static bool IsLearningV414FollowerRunJumpCapabilityReady(
            ProbeRuntime probe,
            float planarSpeed,
            out float learnedMinSuccessfulSpeed,
            out int successfulRunSamples)
        {
            return IsLearningV414FollowerRunJumpCapabilityReadyForEdge(
                probe?.LearnedEdgeId ?? 0,
                planarSpeed,
                out learnedMinSuccessfulSpeed,
                out successfulRunSamples);
        }

        private static bool IsLearningV329JumpTakeoffMomentumReady(
            ProbeRuntime probe,
            out float planarSpeed,
            out float requiredSpeed)
        {
            planarSpeed = GetLearningV329PlanarSpeed(probe?.Player);
            requiredSpeed = GetLearningV329RequiredJumpTakeoffSpeed(probe);
            if(IsCapabilityColdRunJumpTrialReady(probe?.Bot,probe?.LifecycleStep))
            {requiredSpeed=RollingTraversalMinSpeed;return true;}
            ;

            {
                // DemonstratedApproachSpeed is the LOCAL PLAYER's absolute world-space m/s and is
                // not a valid capability threshold for a follower body. V414 keeps that correction
                // but distinguishes actuator legality from obstacle-clearing capability. If this
                // edge was demonstrated as Sprint and the follower is still in Run, Run may trigger
                // only after this same ExperienceKey has persisted a successful follower-local Run
                // takeoff at an equal-or-lower measured speed. Sprint retains the generic follower
                // rolling-momentum proof; no player absolute speed becomes a follower threshold.
                bool demonstratedSprint = string.Equals(
                    probe?.DemonstratedApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase);
                if ((demonstratedSprint) &&
                    probe?.Player?.CurrentStateName == EPlayerState.Run)
                {
                    bool runCapabilityReady = IsLearningV414FollowerRunJumpCapabilityReady(
                        probe, planarSpeed, out float learnedRunMinSpeed, out _);
                    bool learningV418PlayerRunTrialReady =
                        IsLearningV418PlayerProvenRunJumpTrialReady(
                            probe, planarSpeed, out _, out _);
                    requiredSpeed = runCapabilityReady && learnedRunMinSpeed > 0f
                        ? Mathf.Max(RollingTraversalMinSpeed, learnedRunMinSpeed)
                        : RollingTraversalMinSpeed;
                    return runCapabilityReady || learningV418PlayerRunTrialReady;
                }
                return planarSpeed >= RollingTraversalMinSpeed;
            }

            return requiredSpeed <= 0f || planarSpeed >= requiredSpeed;
        }

        private static bool IsLearningV411JumpTakeoffModeReady(ProbeRuntime probe, EPlayerState state)
        {
            if(state==EPlayerState.Run&&IsCapabilityColdRunJumpTrialReady(probe?.Bot,probe?.LifecycleStep))return true;
            bool ordinaryGroundLocomotion = FollowerCapabilityHelperRules.IsLearningV411JumpTakeoffModeReady_ordinaryGroundLocomotion_48CDF17A_1((int)(state),(int)(EPlayerState.Run),(int)(state),(int)(EPlayerState.Sprint));
            if ((probe == null))
            {
                return ordinaryGroundLocomotion;
            }

            {
                // RunStateClass.Jump and SprintStateClass both reach TryJump, so both are actuator-
                // legal. V414 adds follower-local obstacle-clearing capability: a Sprint-demonstrated
                // edge can use Run only after this follower has actually succeeded from Run for this
                // ExperienceKey. Until then, the native input lease keeps forward motion alive while
                // Sprint is requested.
                if ((probe != null) &&
                    state == EPlayerState.Run &&
                    string.Equals(probe.DemonstratedApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase))
                {
                    float planarSpeed = GetLearningV329PlanarSpeed(probe.Player);
                    return IsLearningV414FollowerRunJumpCapabilityReady(
                               probe, planarSpeed, out _, out _) ||
                           IsLearningV418PlayerProvenRunJumpTrialReady(
                               probe, planarSpeed, out _, out _);
                }
                return ordinaryGroundLocomotion;
            }

            // V411 historical behavior retained behind the feature gate for regression audit.
            bool demonstratedSprint = string.Equals(
                probe.DemonstratedApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase);
            return demonstratedSprint ? state == EPlayerState.Sprint : ordinaryGroundLocomotion;
        }

        private static bool ShouldLearningV411RequestJumpSprint(ProbeRuntime probe)
        {
            if(IsCapabilityColdRunJumpTrialReady(probe?.Bot,probe?.LifecycleStep))return false;
            if (probe == null)
            {
                return false;
            }
            if ((probe.Player?.CurrentStateName == EPlayerState.Run))
            {
                float planarSpeed = GetLearningV329PlanarSpeed(probe.Player);
                if (IsLearningV414FollowerRunJumpCapabilityReady(
                        probe, planarSpeed, out _, out _) ||
                    IsLearningV418PlayerProvenRunJumpTrialReady(
                        probe, planarSpeed, out _, out _))
                {
                    return false;
                }
            }
            return string.Equals(
                       probe.DemonstratedApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase) ||
                   probe.PreviousSprinting;
        }

        private static void PublishLearningV411JumpTakeoffLocomotionContinuum(
            ProbeRuntime probe, Vector3 direction, string source)
        {
            if ((probe?.Bot == null) ||
                probe.Player?.MovementContext == null || !IsFinite(direction))
            {
                return;
            }

            direction.y = 0f;
            if (direction.sqrMagnitude <= 0.000001f)
            {
                return;
            }
            direction.Normalize();
            bool profileRequestsSprint = ShouldLearningV411RequestJumpSprint(probe);
            bool currentSprintMode = probe.Bot.Mover?.Sprinting == true ||
                                     probe.Player.CurrentStateName == EPlayerState.Sprint;
            float currentPlanarSpeed = GetLearningV329PlanarSpeed(probe.Player);
            bool learnedRunCapability = IsLearningV414FollowerRunJumpCapabilityReady(
                probe, currentPlanarSpeed, out float learnedRunMinSpeed, out int learnedRunSamples);
            bool learningV418PlayerRunTrialReady = IsLearningV418PlayerProvenRunJumpTrialReady(
                probe, currentPlanarSpeed, out float learningV418PlayerRunMinSpeed,
                out int learningV418PlayerRunDemonstrations);
            bool v414NeedsSprintCapability = (profileRequestsSprint) &&
                                            probe.Player.CurrentStateName == EPlayerState.Run &&
                                            !learnedRunCapability &&
                                            !learningV418PlayerRunTrialReady;
            bool preserveMode = (!v414NeedsSprintCapability);
            bool requestSprint = v414NeedsSprintCapability
                ? true
                : (preserveMode ? currentSprintMode : profileRequestsSprint);
            float dt = Mathf.Max(0.001f, Time.deltaTime);

            // V414 preserves mode on ordinary traversal seams, but Jump is an actuator capability
            // boundary: a Sprint-demonstrated edge without follower-local Run success evidence may
            // explicitly request Sprint while the same native Player.Move producer stays alive.
            Vector3 intentToken = direction * Mathf.Max(0.001f, ChainLocalSuccessorBridgeSpeed * dt);
            if (!TryCommitV2ProbePhysicalMotion(
                probe, direction, intentToken, dt, 1f, requestSprint,
                profileRequestsSprint ? ProbeMomentumFullMoveSpeed : ProbeMomentumNormalMoveSpeed,
                preserveSprintMode: preserveMode))
                return;

            if (ShouldEmitDiagnostic(
                    "learningV411JumpTakeoffLocomotionContinuumPublished:" +
                    probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.12f))
            {
                WriteEvent("learningV411JumpTakeoffLocomotionContinuumPublished", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    source = source ?? string.Empty,
                    state = probe.Player.CurrentStateName.ToString(),
                    demonstratedApproachMode = probe.DemonstratedApproachMode ?? string.Empty,
                    demonstratedApproachSpeed = probe.DemonstratedApproachSpeed,
                    requestSprint,
                    profileRequestsSprint,
                    preserveSprintMode = preserveMode,
                    moverSprinting = probe.Bot.Mover?.Sprinting == true,
                    planarSpeed = currentPlanarSpeed,
                    learnedRunCapability,
                    learnedRunSamples,
                    learnedRunMinSpeed,
                    learningV418PlayerRunTrialReady,
                    learningV418PlayerRunDemonstrations,
                    learningV418PlayerRunMinObservedSpeed = learningV418PlayerRunMinSpeed,
                    v414NeedsSprintCapability,
                    bodyRelocated = false,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "nativePlayerMoveRunupOwnsPhysicalMomentumNoLegacyNavMeshRunupProducer"
                });
            }
        }

        private static bool TryBeginLearnedNativeJump(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string source,
            out string failure)
        {
            failure = string.Empty;
            if (probe?.Player?.MovementContext == null || commitment == null)
            {
                failure = "native Jump movement context/commitment unavailable";
                return false;
            }
            if (probe.NativeExecutorConsumed)
            {
                failure = "native Jump executor already consumed";
                return false;
            }

            // V4.61: V4.29 already proved the current body can physically consume this Jump inside
            // the same Traversal generation. V459 could use that reservation only after V3.2 had
            // independently reacquired the historical entry, which created a second admission gate
            // and allowed a valid Transition-state reservation to age past the takeoff frontier.
            // For an exact rolling/off-NavMesh successor, the live reservation itself is the entry
            // authority. It grants neither Jump success nor landing success; it only prevents an
            // older entry token from delaying the already-proven actuator consumer.
            if ((!probe.LearningV32NativeEntryAcquired) &&
                string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                Vector3 learningV461IdentityEntry =
                    IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
                Vector3 learningV461AdmissionEntry = GetLearningV442JumpAdmissionEntry(commitment);
                Vector3 learningV461Exit =
                    IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
                Vector3 learningV461Direction =
                    GetFlatDirection(learningV461Exit - learningV461IdentityEntry);
                if (IsFinite(learningV461AdmissionEntry) && IsFinite(learningV461Exit) &&
                    learningV461Direction.sqrMagnitude > 0.5f)
                {
                    Vector3 learningV461Offset = probe.Player.Position - learningV461AdmissionEntry;
                    learningV461Offset.y = 0f;
                    float learningV461Projection =
                        Vector3.Dot(learningV461Offset, learningV461Direction);
                    Vector3 learningV461LateralVector =
                        learningV461Offset - learningV461Direction * learningV461Projection;
                    float learningV461Lateral = learningV461LateralVector.magnitude;
                    Vector3 learningV461Forward =
                        GetFlatDirection(probe.Player.MovementContext.PlayerRealForward);
                    float learningV461Alignment = learningV461Forward.sqrMagnitude > 0.5f
                        ? Vector3.Angle(learningV461Forward, learningV461Direction)
                        : 180f;
                    float learningV461Distance =
                        GetPlanarDistance(probe.Player.Position, learningV461AdmissionEntry);
                    if (TryGetLearningV459ReservedJumpExactSuccessorContinuity(
                            probe, learningV461Projection,
                            out FollowerRouteMissionStep learningV461Successor,
                            out float learningV461ReservationMaxForwardProjection))
                    {
                        probe.JumpEntryCaptured = true;
                        MarkLearningV32NativeEntryAcquired(
                            probe,
                            learningV461AdmissionEntry,
                            learningV461Exit,
                            learningV461Distance,
                            learningV461Alignment,
                            learningV461Lateral,
                            learningV461Projection,
                            "learningV461V429ReservationEntryAuthority",
                            directHandoff: true);
                        WriteEvent("learningV461ReservedJumpEntryAuthorityInherited", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            successorEdgeId = learningV461Successor?.EdgeId ?? 0,
                            successorKind = learningV461Successor?.Kind ?? string.Empty,
                            position = Vec(probe.Player.Position),
                            forwardEntryProjection = learningV461Projection,
                            lateralEntryOffset = learningV461Lateral,
                            alignmentAngle = learningV461Alignment,
                            reservationMaxForwardProjection = learningV461ReservationMaxForwardProjection,
                            state = probe.Player.CurrentStateName.ToString(),
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = "sameGenerationV429ReservationConsumesOlderEntryTokenNoSecondHistoricalEntryConvergence"
                        });
                    }
                }
            }
            if ((!probe.LearningV32NativeEntryAcquired))
            {
                return TryBeginLearningV32NativeEntryAcquisition(probe, commitment, source, out failure);
            }

            probe.NativeExecutorConsumed = true;
            probe.NativeStrategySelected = true;
            probe.AssistedStrategySelected = false;

            Vector3 identityRawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawEntry = GetLearningV442JumpAdmissionEntry(commitment);
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 direction = GetFlatDirection(rawExit - identityRawEntry);
            if (direction.sqrMagnitude < 0.5f)
            {
                direction = GetFlatDirection(probe.RequestedDirection);
            }
            if (direction.sqrMagnitude < 0.5f)
            {
                failure = "native Jump direction unavailable";
                return false;
            }

            if (probe.Player.MovementContext.CanJump != true)
            {
                failure = "MovementContext.CanJump=false at learned Jump handoff";
                WriteEvent("nativeLearnedJumpRejected", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    source,
                    reason = failure,
                    position = Vec(probe.Player.Position)
                });
                return false;
            }

            BeginLearningV32NativeExecutionEpoch(probe, "Jump", source);
            probe.RequestedDirection = direction;
            probe.ExclusiveMoverGate = false;
            try
            {
                if (probe.Bot?.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-C7273535A233",@probe?.Bot,false);
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-4A6848308A16",@probe?.Bot);
                }
                probe.Bot?.BotOwnerSetPose("R1-E135FBFCE9D1",@probe?.Bot,1f);
                ApplyProbeLocomotionIntent(
                    probe, ProbeMomentumFullMoveSpeed, allowSprint: true,
                    preserveSprintMode: true);
                probe.Bot?.Steering?.BotSteeringLookToDirection("R1-61E60EB890F9",@probe?.Bot,direction);
            }
            catch
            {
            }

            EPlayerState takeoffState = probe.Player.CurrentStateName;
            bool takeoffGrounded = probe.Player.MovementContext.IsGrounded;
            Vector3 takeoffForward = GetFlatDirection(probe.Player.MovementContext.PlayerRealForward);
            float takeoffFacingDot = takeoffForward.sqrMagnitude > 0.5f
                ? Vector3.Dot(takeoffForward, direction)
                : -1f;
            Vector2 takeoffInput = probe.Player.InputDirection;
            Vector2 takeoffMovement = probe.Player.MovementContext.MovementDirection;
            Vector3 takeoffEntryOffset = probe.Player.Position - rawEntry;
            takeoffEntryOffset.y = 0f;
            float takeoffEntryProjection = Vector3.Dot(takeoffEntryOffset, direction);
