            float readinessDeadlineOrigin = true &&
                                            probe.LearningV450JumpTriggerWindowEnteredAt >= 0f
                ? probe.LearningV450JumpTriggerWindowEnteredAt
                : probe.StageStartedAt;
            bool readinessLatchedBeforeDeadline = true &&
                probe.LearnedJumpTakeoffReadySince >= 0f &&
                FollowerCapabilityDecisionRules.UpdateLearnedJumpTakeoffPriming_readinessLatchedBeforeDeadline_7(probe.LearnedJumpTakeoffReadySince,readinessDeadlineOrigin,LearnedJumpTakeoffTimeout);
            if (learningV450DecisionClockArmed &&
                elapsed >= LearnedJumpTakeoffTimeout && !readinessLatchedBeforeDeadline)
            {
                WriteEvent("nativeLearnedJumpTakeoffReadyTimeout", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    state = currentState.ToString(),
                    forwardProgress,
                    facingDot,
                    canJump,
                    grounded,
                    takeoffPlanarSpeed,
                    requiredTakeoffSpeed,
                    takeoffMomentumReady,
                    movementHeadingDot,
                    physicalHeadingReady,
                    runupProducerActive = true && probe.HasJumpRunupTarget,
                    readinessLatchedBeforeDeadline,
                    moverHasPath = probe.Bot.Mover?.HasPathAndNoComplete == true,
                    elapsed,
                    timeoutClock = true
                        ? "physicalTriggerWindow"
                        : "probeStage"
                });
                TryRecoverPlayerValidatedTraversal(probe, "learnedJumpTakeoffReadyTimeout");
            }
        }

        private static bool TryBeginNativeDropDown(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string source,
            out string failure)
        {
            failure = string.Empty;
            if (probe?.Player?.MovementContext == null || commitment == null)
            {
                failure = "native DropDown movement context/commitment unavailable";
                return false;
            }
            if (FollowerCapabilityPhasePolicy.DropDownEntry(probe.NativeExecutorConsumed,true,probe.LearningV32NativeEntryAcquired)==FollowerCapabilityPhasePolicy.NativeEntry.RejectConsumed)
            {
                failure = "native DropDown executor already consumed";
                return false;
            }
            if (FollowerCapabilityPhasePolicy.DropDownEntry(probe.NativeExecutorConsumed,true,probe.LearningV32NativeEntryAcquired)==FollowerCapabilityPhasePolicy.NativeEntry.AcquireEntry)
            {
                return TryBeginLearningV32NativeEntryAcquisition(probe, commitment, source, out failure);
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 direction = GetFlatDirection(rawExit - rawEntry);
            if (!FollowerCapabilityPhasePolicy.DirectionValid(IsFinite(rawEntry),IsFinite(rawExit),direction.sqrMagnitude))
            {
                failure = "native DropDown geometry/direction invalid";
                return false;
            }

            probe.NativeExecutorConsumed = true;
            probe.NativeStrategySelected = true;
            probe.AssistedStrategySelected = false;
            probe.NativeDropDownAttempted = true;
            probe.NativeDropDownStartPosition = probe.Player.Position;
            probe.NativeDropDownLastPosition = probe.Player.Position;
            probe.NativeDropDownLastProgressAt = Time.time;
            probe.NativeDropDownBestForwardProjection = float.MinValue;
            probe.NativeDropDownAirborneSince = -1f;
            probe.NativeDropDownLandingStableSince = -1f;
            probe.NativeDropDownLandingCandidatePosition = probe.Player.Position;
            probe.NativeDropDownLandingLastPosition = probe.Player.Position;
            probe.NativeDropDownLandingCandidateForwardProjection = float.MinValue;
            probe.NativeDropDownLandingBrakeActive = false;
            probe.NativeDropDownSawAirborne = false;
            probe.NativeDropDownSawDescent = false;
            probe.NativeDropDownSawFarSide = false;
            probe.RequestedDirection = direction;
            probe.TraversalKind = "DropDown";
            probe.TriggerPosition = probe.Player.Position;
            BeginLearningV32NativeExecutionEpoch(probe, "DropDown", source);
            TransitionProbeStage(probe, ProbeStage.NativeDropDown);
            probe.StageStartedAt = Time.time;
            probe.ExclusiveMoverGate = true;
            probe.OwnershipLeaseExpiresAt = Mathf.Max(
                probe.OwnershipLeaseExpiresAt,
                Time.time + NativeDropDownExecutionTimeout + 1.0f);

            try
            {
                // CompileFix46: do NOT stop BotMover at the ledge handoff. Fix45.1 did exactly
                // that and every NativeDropDown either froze 1-1.7 m before the authored edge or
                // briefly toggled airborne without any descent. Keep native EFT locomotion moving
                // toward the authored far side; collision + gravity still own the actual fall.
                if (probe.Bot?.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-D5AEA6E08BA1",@probe?.Bot,false);
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-55143769D448",@probe?.Bot);
                    {
                        if (probe.Bot.Mover.HasPathAndNoComplete)
                        {
                            TryRetireNativeMoverPathPreserveLocomotion(
                                probe.Bot, "learningV414DropDownPathlessEntry", out _);
                        }
                    }
                }
                probe.Bot?.BotOwnerSetPose("R1-2256D4CF805C",@probe?.Bot,1f);
                ApplyProbeLocomotionIntent(
                    probe, ProbeMomentumFullMoveSpeed, allowSprint: true,
                    preserveSprintMode: true);
                probe.Bot?.Steering?.BotSteeringLookToDirection("R1-A0E0F847DBE3",@probe?.Bot,direction);
                HoldForwardInput(probe);
                {
                    TryPublishLearningV414PathlessNativeInputLease(
                        probe, rawExit, ProbeMomentumFullMoveSpeed, "dropDownStart");
                }
            }
            catch
            {
            }

            WriteEvent("nativeDropDownStarted", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                source,
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                start = Vec(probe.Player.Position),
                authoredDrop = rawEntry.y - rawExit.y,
                previousSprinting = probe.PreviousSprinting,
                previousRunning = probe.PreviousRunning
            });
            return true;
        }

        // CF67: once a real V331 PathComplete consumer has been admitted on this
        // exact native DropDown probe, physical support may disappear over a second
        // ledge. The V331 *candidate* must reset, but the predecessor's straight
        // V414 translation writer must not be revived. This identity is retired
        // by the existing native physical terminal / bounded execution timeout;
        // no new grace timer or relaxed landing proof is introduced.
        private static bool IsCf67AcceptedDropDownConsumerEpoch(ProbeRuntime probe)
        {
            return (probe != null) && IsActiveProbe(probe) &&
                probe.Bot?.Mover != null && probe.Player?.MovementContext != null &&
                string.Equals(probe.TraversalKind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                probe.CF67DropDownConsumerEverAccepted &&
                probe.CF67DropDownConsumerAcceptedAt >= 0f &&
                probe.NativeDropDownSawAirborne && probe.NativeDropDownSawDescent &&
                probe.NativeDropDownSawFarSide &&
                !probe.NativeDropDownPhysicalLandingAuthority &&
                Time.time - probe.StageStartedAt < NativeDropDownExecutionTimeout;
        }

        // CF66: V331 has already installed a native landing-path consumer.  A short
        // bounded target may be marked complete between ticks before V334 refreshes
        // the lookahead.  HasPathAndNoComplete == false during that gap is NOT
        // permission to resume the older V414 straight-line producer.  The original
        // V334 refresh and physical landing checks remain authoritative; the grace
        // window grants no success, teleport, or geometry exception.
        private static bool IsCf66DropDownLandingMoverRefreshWindow(
            ProbeRuntime probe, out float targetDistance, out float age)
        {
            targetDistance = float.MaxValue;
            age = -1f;
            if ((probe?.Player?.MovementContext == null) || probe.Bot?.Mover == null ||
                !probe.LearningV331DropDownLandingForwardHandoffActive ||
                probe.NativeDropDownLandingStableSince < 0f ||
                !probe.Player.MovementContext.IsGrounded ||
                !probe.NativeDropDownSawAirborne || !probe.NativeDropDownSawFarSide ||
                !IsFinite(probe.LearningV331DropDownLandingForwardHandoffTarget))
            {
                return false;
            }
            age = Time.time - probe.NativeDropDownLandingStableSince;
            targetDistance = GetPlanarDistance(
                probe.Player.Position, probe.LearningV331DropDownLandingForwardHandoffTarget);
            return age >= 0f &&
                age <= NativeDropDownLandingStableSeconds + 0.20f &&
                targetDistance <= 1.60f;
        }

        // RC53: an exact same-chain DropDown entry can be geometrically reached
        // on a verified grounded predecessor landing although the NEXT portal has
        // no NavMesh polygon near its raw entry. This is a negative predecessor
        // movement guard ONLY; it cannot start, skip, or prove the successor.
        private static bool TryGetV2RC53GroundedSuccessorEntryGuard(
            ProbeRuntime probe, LearnedTraversalCommitment commitment, Vector3 position,
            out FollowerRouteMissionStep successor, out float entryAhead, out float entryLateral)
        {
            return TryCaptureCapabilityLandingEntryFrontier(probe,commitment,position,
                out successor,out entryAhead,out entryLateral);
        }

        private static void UpdateNativeDropDown(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Player?.MovementContext == null ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) || commitment == null)
            {
                return;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 direction = GetFlatDirection(rawExit - rawEntry);
            if (direction.sqrMagnitude < 0.5f)
            {
                direction = GetFlatDirection(probe.RequestedDirection);
            }
            if (direction.sqrMagnitude < 0.5f)
            {
                FinalizeOrEscalateTraversalFailure(probe, "nativeDropDownDirectionLost");
                return;
            }

            // CF66 is scoped to the *same active DropDown probe*, confirmed
            // grounded landing candidate and V331-owned native consumer.  Do not
            // let the generic pathless update or direct steering erase its path.
            bool cf66LandingMoverRefreshWindow =
                IsCf66DropDownLandingMoverRefreshWindow(probe,
                    out float cf66RemainingToTarget, out float cf66LandingAge);
            // RC53: the FIRST predecessor landing may have no sampled near-side
            // target for its typed next DropDown. It must not drive across an
            // entry whose CURRENT grounded body already satisfies the untouched
            // native distance/side geometry. One existing Traversal owner brakes.
            // RC55: EFT may report IsGrounded for one frame on an intermediate ledge
            // while the actor is still descending quickly. That is not a physically
            // stable landing/pose lease. Never issue StopMove / clear native input on
            // transient support; the already-active DropDown retains its real motion.
            bool rc55TransientGroundContact = probe.NativeDropDownLandingStableSince >= 0f &&
                probe.Player.MovementContext.IsGrounded &&
                Mathf.Abs(probe.Player.Velocity.y) > NativeDropDownLandingMaxVerticalSpeed;
            FollowerRouteMissionStep rc53Successor = null;
            float rc53EntryAhead = 0f, rc53EntryLateral = 0f;
            bool rc53GroundedSuccessorEntryGuard =
                !rc55TransientGroundContact &&
                TryGetV2RC53GroundedSuccessorEntryGuard(
                    probe, commitment, probe.Player.Position,
                    out rc53Successor, out rc53EntryAhead, out rc53EntryLateral);
            int rc62NextEdgeId;
            float rc62NextEntryAhead, rc62NextEntryLateral;
            float rc62NativeHorizontalSpeed = GetV2RC62AdjacentDropDownNativeSpeed(
                probe, commitment, probe.Player.Position,
                out rc62NextEdgeId, out rc62NextEntryAhead, out rc62NextEntryLateral);
            if (rc62NextEdgeId > 0 &&
                ShouldEmitDiagnostic("v2rc62SameChainNativeHorizontalEnvelope:" +
                    commitment.EdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.12f))
                WriteEvent("v2rc62SameChainNativeHorizontalEnvelope", probe.Bot, new
                {
                    predecessorEdgeId = commitment.EdgeId,
                    successorEdgeId = rc62NextEdgeId,
                    body = Vec(probe.Player.Position),
                    successorEntryAhead = rc62NextEntryAhead,
                    successorLateral = rc62NextEntryLateral,
                    nativeHorizontalSpeed = rc62NativeHorizontalSpeed,
                    moverSprinting = probe.Bot?.Mover?.Sprinting == true,
                    measuredHorizontalSpeed = new Vector2(probe.Player.Velocity.x,
                        probe.Player.Velocity.z).magnitude,
                    boundedSpeedPolicySelected = true,
                    nativeSuccessRecorded = false, bodyRelocated = false,
                    action = "sameTraversalOwnerRequestsBoundedNativeHorizontalSpeedWithoutFullSprintOverride"
                });
            // RC111: one native-consumer runway contract replaces the late hard-stop exception.
            // Proof maturity and successor admission remain independent and unchanged.
            bool rc65QualifiedContinuousLandingHandoff = rc53GroundedSuccessorEntryGuard&&
                rc53Successor!=null&&rc62NextEdgeId==rc53Successor.EdgeId&&
                TryGetCapabilityRollingLandingHandoff(probe,commitment,rc53Successor,
                    rc53EntryAhead,rc53EntryLateral,rc62NativeHorizontalSpeed);
            if (rc53GroundedSuccessorEntryGuard)
            {
                probe.NativeDropDownLandingBrakeActive = !rc65QualifiedContinuousLandingHandoff;
                if (!rc65QualifiedContinuousLandingHandoff &&
                    ShouldEmitDiagnostic("v2rc53GroundedSuccessorEntryArrest:" +
                        commitment.EdgeId, probe.Bot, 0.12f))
                    WriteEvent("v2rc53GroundedSuccessorEntryArrest", probe.Bot, new
                    {
                        predecessorEdgeId = commitment.EdgeId,
                        successorEdgeId = rc53Successor.EdgeId,
                        successorEpisodeId = rc53Successor.EpisodeId,
                        body = Vec(probe.Player.Position), entry = Vec(rc53Successor.RawEntry),
                        entryAhead = rc53EntryAhead, entryLateral = rc53EntryLateral,
                        nativeSuccessRecorded = false, bodyRelocated = false,
                        action = "holdExistingPredecessorWriterAtGroundedNextNativeEntryNoPathOrSuccessInvented"
                    });
            }
            try
            {
                if (rc53GroundedSuccessorEntryGuard)
                {
                    if (rc65QualifiedContinuousLandingHandoff)
                    {
                        // Neither the old RC53 StopMove nor a replacement Mover
                        // path: preserve native locomotion across the pending
                        // landing proof and the next real Native admission.
                        if (probe.Bot?.Mover != null)
                            probe.Bot.Mover.SetBotMoverPause("R1-41898903CB8C",@probe?.Bot,false);
                        ApplyProbeLocomotionIntent(
                            probe, rc62NativeHorizontalSpeed,
                            allowSprint: true, preserveSprintMode: true,
                            sameChainDropDownNativeEnvelope: rc62NextEdgeId > 0);
                        probe.Bot?.Steering?.BotSteeringLookToDirection("R1-36749DCE8861",@probe?.Bot,direction);
                        HoldForwardInput(probe);
                        if (ShouldEmitDiagnostic("v2rc65ContinuousLandingHandoff:" +
                                commitment.EdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.12f))
                            WriteEvent("v2rc65ContinuousLandingHandoff", probe.Bot, new
                            {
                                predecessorEdgeId = commitment.EdgeId,
                                successorEdgeId = rc53Successor.EdgeId,
                                body = Vec(probe.Player.Position),
                                successorEntryAhead = rc53EntryAhead,
                                successorLateral = rc53EntryLateral,
                                landingProofElapsed = Time.time - probe.NativeDropDownLandingStableSince,
                                nativeHorizontalSpeed = rc62NativeHorizontalSpeed,
                                nativeSuccessRecorded = false, bodyRelocated = false,
                                action = "sameNativeProducerRollsWithinRemainingProofRunwayWithoutStopReplay"
                            });
                    }
                    else
                    {
                        // Preserve RC53's hard safety arrest when physical
                        // evidence is not sufficiently mature for a safe handoff.
                        probe.Bot?.Mover?.BotMoverStop("R1-DFA54F66EB24",@probe?.Bot);
                        probe.Bot?.BotOwnerStopMove("R1-64D440F41040",@probe?.Bot);
                        probe.Player.SetPlayerInputDirection("R1-FC98C14F50C5",@probe?.Bot,Vector2.zero);
                        probe.Player.MovementContext.SetMovementContextMovementDirection("R1-34C03152A49C",@probe?.Bot,Vector2.zero);
                    }
                }
                else if (cf66LandingMoverRefreshWindow)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-202ED5FE74EF",@probe?.Bot,false);
                    if (ShouldEmitDiagnostic("cf66LandingConsumerRefreshGap:" +
                        commitment.EdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.10f))
                    {
                        WriteEvent("cf66LandingMoverRefreshWindowRetained", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            landingCandidateAge = cf66LandingAge,
                            distanceToLastConsumerTarget = cf66RemainingToTarget,
                            moverHasPath = probe.Bot.Mover.HasPathAndNoComplete,
                            movementState = probe.Player.CurrentStateName.ToString(),
                            nativeSuccessRecorded = false,
                            bodyRelocated = false,
                            action = "V331ConsumerOwnsLandingTranslationWhileV334RefreshesNoV414PathlessOverride"
                        });
                    }
                }
                else if (IsCf67AcceptedDropDownConsumerEpoch(probe))
                {
                    // V331 actually installed PathComplete earlier in THIS active
                    // probe. The next ledge revoked the landing candidate, not the
                    // prior producer identity. Do not synthesize another V414
                    // straight-ahead command when its short Mover target completes.
                    // With no live native path, retire stale predecessor input
                    // even through a second airborne epoch. Gravity/inertia remain
                    // native; no movement teleport or physical success is asserted.
                    // This may momentarily pause if no valid successor exists;
                    // the existing Native timeout and bounded recovery remain live.
                    probe.Bot.Mover.SetBotMoverPause("R1-D367399537CC",@probe?.Bot,false);
                    if (!probe.Bot.Mover.HasPathAndNoComplete)
                    {
                        probe.Player.SetPlayerInputDirection("R1-9A5A8DAA66D5",@probe?.Bot,Vector2.zero);
                        probe.Player.MovementContext.SetMovementContextMovementDirection("R1-84D8FF19FEF8",@probe?.Bot,Vector2.zero);
                    }
                    if (ShouldEmitDiagnostic("cf67ConsumerEpoch:" +
                        commitment.EdgeId.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.12f))
                    {
                        WriteEvent("cf67AcceptedConsumerEpochPreserved", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            acceptedAt = probe.CF67DropDownConsumerAcceptedAt,
                            candidateActive = probe.NativeDropDownLandingStableSince >= 0f,
                            grounded = probe.Player.MovementContext.IsGrounded,
                            moverHasPath = probe.Bot.Mover.HasPathAndNoComplete,
                            nativeSuccessRecorded = false,
                            bodyRelocated = false,
                            action = "sameProbePathCompleteConsumerSurvivesSecondaryDescentNoLegacyV414Reentry"
                        });
                    }
                }
                else if (probe.NativeDropDownLandingBrakeActive)
                {
                    {
                        // V413: landing proof is an observer. A previously armed V331/CF53 brake
                        // cannot manufacture a locomotion-state transition while physical landing
                        // truth is still being sampled. Keep the existing mode/input alive.
                        probe.NativeDropDownLandingBrakeActive = false;
                        if (probe.Bot?.Mover != null)
                        {
                            probe.Bot.Mover.SetBotMoverPause("R1-1B39071C18FE",@probe?.Bot,false);
                        }
                        ApplyProbeLocomotionIntent(
                            probe, rc62NativeHorizontalSpeed, allowSprint: true, preserveSprintMode: true,
                            sameChainDropDownNativeEnvelope: rc62NextEdgeId > 0);
                        probe.Bot?.Steering?.BotSteeringLookToDirection("R1-B0406083FAC1",@probe?.Bot,direction);
                        HoldForwardInput(probe);
                    }
                }
                else
                {
                    if (probe.Bot?.Mover != null)
                    {
                        probe.Bot.Mover.SetBotMoverPause("R1-DD6AE6340E88",@probe?.Bot,false);
                        // rawExit is physical ordering geometry, never a ground NavMesh destination
                        // under V414. Older revisions repeatedly reinstalled GoToPointNoWay here,
                        // which could steer a just-arrived successor around its own entry.
                        ;
                    }
                    ApplyProbeLocomotionIntent(
                        probe, rc62NativeHorizontalSpeed, allowSprint: true,
                        preserveSprintMode: true,
                        sameChainDropDownNativeEnvelope: rc62NextEdgeId > 0);
                    probe.Bot?.Steering?.BotSteeringLookToDirection("R1-EE57BE96DA06",@probe?.Bot,direction);
                    HoldForwardInput(probe);
                    if ((probe.Bot?.Mover?.HasPathAndNoComplete != true))
                    {
                        Vector3 learningV414DropTarget = probe.NativeDropDownSawFarSide
                            ? probe.Player.Position + direction
                            : rawExit;
                        TryPublishLearningV414PathlessNativeInputLease(
                            probe, learningV414DropTarget, rc62NativeHorizontalSpeed, "dropDownUpdate");
                    }
                }
            }
            catch
            {
            }

            Vector3 position = probe.Player.Position;
            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            float planarLength = Mathf.Max(0.01f, axis.magnitude);
            Vector3 fromEntry = position - rawEntry;
            fromEntry.y = 0f;
            float forwardProjection = Vector3.Dot(fromEntry, direction);
            float requiredProjection = FollowerCapabilityDropDownTransitionPolicy.RequiredProjection(planarLength, NativeDropDownFarSideRatio);
            float descent = probe.NativeDropDownStartPosition.y - position.y;
            bool grounded = probe.Player.MovementContext.IsGrounded;

            if (forwardProjection > probe.NativeDropDownBestForwardProjection + NativeDropDownProgressEpsilon ||
                Vector3.Distance(position, probe.NativeDropDownLastPosition) > NativeDropDownProgressEpsilon)
            {
                probe.NativeDropDownBestForwardProjection = Mathf.Max(probe.NativeDropDownBestForwardProjection, forwardProjection);
                probe.NativeDropDownLastPosition = position;
                probe.NativeDropDownLastProgressAt = Time.time;
            }

            bool executionEvidenceEligible = FollowerCapabilityDecisionRules.UpdateNativeDropDown_executionEvidenceEligible_2(forwardProjection,LearningV32DropDownAirborneEvidenceMinProjection);
            if (!grounded && executionEvidenceEligible)
            {
                if (probe.NativeDropDownAirborneSince < 0f)
                {
                    probe.NativeDropDownAirborneSince = Time.time;
                    WriteEvent("nativeDropDownAirborne", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        position = Vec(position),
                        forwardProjection,
                        descent,
                        executionEpochStartedAt = probe.LearningV32NativeExecutionEpochStartedAt
                    });
                }
                if (Time.time - probe.NativeDropDownAirborneSince >= NativeDropDownMinAirborneSeconds)
                {
                    probe.NativeDropDownSawAirborne = true;
                }
            }
            else if (!grounded && !executionEvidenceEligible &&
                     ShouldEmitDiagnostic("nativeDropDownPreEntryAirborneIgnored", probe.Bot, 0.20f))
            {
                WriteEvent("nativeDropDownPreEntryAirborneIgnored", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    position = Vec(position),
                    forwardProjection,
                    minEligibleProjection = LearningV32DropDownAirborneEvidenceMinProjection,
                    descent,
                    entryAcquired = probe.LearningV32NativeEntryAcquired
                });
            }

            if (executionEvidenceEligible && descent >= NativeDropDownMinDescent)
            {
                probe.NativeDropDownSawDescent = true;
            }
            if (executionEvidenceEligible && forwardProjection >= requiredProjection)
            {
                probe.NativeDropDownSawFarSide = true;
            }

            bool landingNavSampled = NavMesh.SamplePosition(
                position, out NavMeshHit landingNavHit, UnifiedTraversalVerifyNavRadius, NavMesh.AllAreas);
            float landingNavVertical = landingNavSampled
                ? Mathf.Abs(landingNavHit.position.y - position.y)
                : float.MaxValue;
            bool landingNavStable = FollowerCapabilityDecisionRules.UpdateNativeDropDown_landingNavStable_3(landingNavSampled,landingNavVertical,UnifiedTraversalVerifyMaxNavVertical);
            Vector3 landingDownstreamTarget = default;
            string landingDownstreamSource = string.Empty;
            bool landingDownstreamConnected = landingNavStable &&
                HasTraversalDownstreamConnectivity(
                    probe, commitment, landingNavHit.position,
                    out landingDownstreamTarget, out landingDownstreamSource);
            float verticalSpeed = Mathf.Abs(probe.Player.Velocity.y);
            bool supportedLandingFallback = FollowerCapabilityDecisionRules.UpdateNativeDropDown_supportedLandingFallback_4(grounded,landingNavStable,landingDownstreamConnected,verticalSpeed,NativeDropDownSupportedFallbackMaxVerticalSpeed) &&
                FollowerCapabilityDecisionRules.UpdateNativeDropDown_supportedLandingFallback_5(Time.time,probe.NativeDropDownLastProgressAt,NativeDropDownSupportedFallbackMinStableSeconds);
            // RC68: NavMesh proximity is a reasonable terminal DropDown landing
            // fallback, but it is NOT upper-side support for an immediately pending
            // second DropDown. If that successor still has an untraversed lower
            // exit, retain the predecessor's active native physical producer until
            // actual EFT support or observed onward descent. Do not promote the
            // predecessor fallback into a false successor-ready ground state.
            bool unresolvedAdjacentLowerLanding = false;
            if (supportedLandingFallback &&
                TryResolveLearningV376MissionForProbe(probe,
                    out FollowerRouteMission rc68Mission, out int rc68Index) &&
                rc68Mission?.Steps != null && rc68Index >= 0 &&
                rc68Index + 1 < rc68Mission.Steps.Count &&
                IsRouteMissionSameChainImmediateSuccessor(rc68Mission, rc68Index + 1))
            {
                FollowerRouteMissionStep rc68Next = rc68Mission.Steps[rc68Index + 1];
                if (rc68Next != null &&
                    string.Equals(rc68Next.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                    !rc68Next.AttemptStartedObserved &&
                    IsFinite(rc68Next.RawEntry) && IsFinite(rc68Next.RawExit) &&
                    rc68Next.RawEntry.y - rc68Next.RawExit.y > 0.25f)
                {
                    Vector3 rc68NextAxis = GetFlatDirection(
                        rc68Next.RawExit - rc68Next.RawEntry);
                    Vector3 rc68NextOffset = position - rc68Next.RawEntry;
                    rc68NextOffset.y = 0f;
                    float rc68NextProgress = rc68NextAxis.sqrMagnitude > 0.5f
                        ? Vector3.Dot(rc68NextOffset, rc68NextAxis) : 0f;
                    float rc68NextRequired = Mathf.Max(0.12f,
                        GetPlanarDistance(rc68Next.RawEntry, rc68Next.RawExit) - 0.25f);
                    unresolvedAdjacentLowerLanding =
                        position.y > rc68Next.RawExit.y + DropDownAlreadyBelowLandingMargin ||
                        rc68NextProgress < rc68NextRequired;
                }
            }
            if (unresolvedAdjacentLowerLanding)
            {
                if (ShouldEmitDiagnostic("v2rc68AdjacentDropDownFallbackNotGrounded:" +
                        commitment.EdgeId.ToString(CultureInfo.InvariantCulture),
                        probe.Bot, 0.35f))
                    WriteEvent("v2rc68AdjacentDropDownFallbackNotGrounded", probe.Bot,
                        new { predecessorEdgeId = commitment.EdgeId,
                            body = Vec(position), supportedLandingFallback,
