                    float candidateVerticalDrift = Mathf.Abs(position.y - probe.NativeDropDownLandingCandidatePosition.y);
                    float stepVerticalDrift = Mathf.Abs(position.y - probe.NativeDropDownLandingLastPosition.y);
                    probe.NativeDropDownLandingLastPosition = position;

                    if ((probe.LearningV331DropDownLandingForwardHandoffActive) &&
                        IsFinite(probe.LearningV331DropDownLandingForwardHandoffTarget))
                    {
                        TryRefreshLearningV334DropDownLandingForwardLookahead(
                            probe, commitment, position, direction,
                            landingDownstreamTarget, landingDownstreamSource);
                    }

                    bool learningV331IntentionalSupportedForwardMotion =
                        FollowerCapabilityDecisionRules.UpdateNativeDropDown_learningV331IntentionalSupportedForwardMotion_8(probe.LearningV331DropDownLandingForwardHandoffActive,effectiveLandingSupport,landingNavStable,landingDownstreamConnected,landingCorridorQualified,forwardProjection,probe.NativeDropDownLandingCandidateForwardProjection);
                    // A second ledge/step-down after the first contact restarts the settling window,
                    // unless the vertical change belongs to our explicitly supported downstream
                    // movement. Any support loss still exits this branch and invalidates the candidate.
                    if (!learningV331IntentionalSupportedForwardMotion &&
                        (candidateVerticalDrift > NativeDropDownLandingMaxVerticalDrift ||
                         stepVerticalDrift > NativeDropDownLandingMaxVerticalDrift))
                    {
                        WriteEvent("nativeDropDownLandingCandidateReset", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            previousCandidate = Vec(probe.NativeDropDownLandingCandidatePosition),
                            position = Vec(position),
                            candidateVerticalDrift,
                            stepVerticalDrift,
                            reason = "verticalDrift"
                        });
                        probe.NativeDropDownLandingStableSince = Time.time;
                        probe.NativeDropDownLandingCandidatePosition = position;
                        probe.NativeDropDownLandingCandidateForwardProjection = forwardProjection;
                        if (probe.NativeDropDownLandingBrakeActive)
                        {
                            probe.NativeDropDownLandingBrakeActive = false;
                            WriteEvent("nativeDropDownLandingCandidateBrakeReleased", probe.Bot, new
                            {
                                edgeId = commitment.EdgeId,
                                position = Vec(position),
                                reason = "verticalDrift",
                                candidateVerticalDrift,
                                stepVerticalDrift
                            });
                        }
                    }
                    else if (verticalSpeed <= NativeDropDownLandingMaxVerticalSpeed &&
                             Time.time - probe.NativeDropDownLandingStableSince >= NativeDropDownLandingStableSeconds)
                    {
                        probe.NativeTraversalStarted = true;
                        probe.NativeStateObserved = true;
                        probe.TraversalKind = "DropDown";
                        probe.NativeDropDownPhysicalLandingAuthority = true;
                        // Final authority is always the latest settled body position, never the first
                        // grounded sample.
                        probe.NativeDropDownPhysicalLandingAnchor = position;
                        WriteEvent("nativeDropDownPhysicalLandingAuthorityConfirmed", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            position = Vec(position),
                            candidate = Vec(probe.NativeDropDownLandingCandidatePosition),
                            forwardProjection,
                            requiredProjection,
                            descent,
                            verticalSpeed,
                            stableSeconds = Time.time - probe.NativeDropDownLandingStableSince,
                            navVertical = landingNavVertical,
                            downstreamConnected = landingDownstreamConnected,
                            grounded,
                            supportedLandingFallback,
                            landingLateralDeviation,
                            landingMaxLateralDeviation,
                            landingCorridorQualified,
                            candidateForwardProjection = probe.NativeDropDownLandingCandidateForwardProjection,
                            landingBrakeApplied = probe.NativeDropDownLandingBrakeActive,
                            elapsed = Time.time - probe.StageStartedAt
                        });
                        WriteEvent("nativeDropDownLanded", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            position = Vec(position),
                            forwardProjection,
                            requiredProjection,
                            descent,
                            elapsed = Time.time - probe.StageStartedAt
                        });
                        BeginUnifiedTraversalEgressOrVerify(probe, "nativeDropDownPhysicalLandingConfirmed");
                        return;
