            }
            else
            {
                if (v2ShortSupportFlicker)
                {
                    // Do not infer support on this frame, arm native completion,
                    // or credit this frame toward the existing 0.30s requirement.
                    // The next actual grounded frame must pass the FULL gate.
                    float unsupportedFrame = Mathf.Clamp(Time.deltaTime, 0f, 0.05f);
                    probe.NativeDropDownLandingStableSince = Mathf.Min(Time.time,
                        probe.NativeDropDownLandingStableSince + unsupportedFrame);
                    if (ShouldEmitDiagnostic("v2rc76TransientSupportWitnessHeld:" +
                            commitment.EdgeId.ToString(CultureInfo.InvariantCulture),
                            probe.Bot, 0.25f))
                        WriteEvent("v2rc76TransientSupportWitnessHeld", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId, body = Vec(position),
                            lastConfirmedBody = Vec(probe.NativeDropDownLandingLastPosition),
                            lastActualGroundedAt = probe.V2LandingLastPhysicalSupportAt,
                            elapsedWithoutGrounded = Time.time - probe.V2LandingLastPhysicalSupportAt,
                            unsupportedFrameExcluded = unsupportedFrame,
                            nativeSuccessRecorded = false, successorProofGranted = false,
                            bodyRelocated = false,
                            action = "retainCandidateButRequireFreshPhysicalSupportForAnyNativeCompletion"
                        });
