                // revoke it on a later tick, then relatch it without ever reaching
                // the unchanged 0.30s stability requirement.  Observe the FIRST
                // failed physical predicate; never make evidence sufficient by
                // extending the old candidate through an unknown gap.
                if (probe.NativeDropDownLandingStableSince >= 0f &&
                    ShouldEmitDiagnostic("v2rc74LandingCandidateRevoked:" +
                        commitment.EdgeId.ToString(CultureInfo.InvariantCulture) + ":" +
                        v2LandingBlocker, probe.Bot, 0.15f))
                {
                    WriteEvent("v2rc74LandingCandidateRevoked", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        reason = v2LandingBlocker,
                        body = Vec(position),
                        candidate = Vec(probe.NativeDropDownLandingCandidatePosition),
                        candidateAge = Time.time - probe.NativeDropDownLandingStableSince,
                        grounded, supportedLandingFallback, unresolvedAdjacentLowerLanding,
                        sawAirborne = probe.NativeDropDownSawAirborne,
                        sawDescent = probe.NativeDropDownSawDescent,
                        sawFarSide = probe.NativeDropDownSawFarSide,
                        effectiveLandingSupport, landingNavStable, landingDownstreamConnected,
                        landingCorridorQualified, verticalSpeed,
                        successorProofGranted = false,
                        nativeSuccessRecorded = false, bodyRelocated = false,
                        action = "candidateRevokedByPhysicalEvidenceNeverPromotedToNativeSuccess"
                    });
                }
                if (probe.NativeDropDownSawAirborne && probe.NativeDropDownSawDescent &&
                    probe.NativeDropDownSawFarSide && effectiveLandingSupport && landingNavStable &&
                    landingDownstreamConnected && !landingCorridorQualified &&
                    ShouldEmitDiagnostic("nativeDropDownLandingCorridorRejected:" + commitment.EdgeId, probe.Bot, 0.35f))
                {
                    probe.NativeLandingRejected = true;
                    probe.NativeLandingRejectReason = "dropDownLandingCorridor";
                    probe.NativeLandingRejectLateralDeviation = landingLateralDeviation;
                    probe.NativeLandingRejectExitDistance = GetPlanarDistance(position, rawExit);
                    WriteEvent("nativeDropDownLandingCorridorRejected", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        position = Vec(position),
                        rawEntry = Vec(rawEntry),
                        rawExit = Vec(rawExit),
                        forwardProjection,
                        requiredProjection,
                        landingLateralDeviation,
                        landingMaxLateralDeviation,
                        downstreamConnected = landingDownstreamConnected,
                        grounded,
                        supportedLandingFallback
                    });

                    // V3.87: far-side + supported + downstream-connected means the body has already
                    // left the takeoff transaction.  A landing-corridor rejection is a recovery
                    // decision, not permission to keep holding forward until the body is 10+ metres
                    // beyond the authored portal.  Stop native translation at the first rejected
                    // supported landing and enter the existing bounded Assist/Recovery ladder.
                    {
