                        WriteEvent("learningV387DropDownRejectedLandingNativeDriveRetired", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            position = Vec(position),
                            forwardProjection,
                            landingLateralDeviation,
                            landingMaxLateralDeviation,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            action = "supportedFarSideRejectionImmediatelyYieldsNativeTranslationToBoundedRecovery"
                        });

                        string learningV387AssistFailure = "assisted replay already attempted";
                        if (!probe.AssistedReplayAttempted &&
                            TryBeginAssistedTraversalReplay(
                                probe,
                                "learningV387DropDownLandingCorridorRejected",
                                out learningV387AssistFailure))
                        {
                            return;
                        }
                        if (EscalateTraversalFailureMonotonic(
                                probe,
                                "learningV387DropDownLandingCorridorRejected:" +
                                (learningV387AssistFailure ?? string.Empty)))
                        {
                            return;
                        }
                        FinalizeUnifiedTraversalFailure(
                            probe,
                            "learningV387DropDownLandingCorridorRecoveryRejected:" +
                            (learningV387AssistFailure ?? string.Empty));
