                // invalidates the landing candidate; the bounded native timeout then escalates to
                // AssistedReplay rather than NativeVerified.
                probe.NativeDropDownLandingBrakeActive = false;
                probe.LearningV331DropDownLandingForwardHandoffActive = false;
                probe.NativeDropDownLandingStableSince = -1f;
                probe.V2LandingLastPhysicalSupportAt = -1f;
                }
            }

            float elapsed = Time.time - probe.StageStartedAt;
            bool noProgress = FollowerCapabilityDecisionRules.UpdateNativeDropDown_noProgress_9(Time.time,probe.NativeDropDownLastProgressAt,NativeDropDownNoProgressTimeout);
            if (elapsed >= NativeDropDownExecutionTimeout || noProgress)
            {
                string nativeFailure = elapsed >= NativeDropDownExecutionTimeout
                    ? "nativeDropDownTimeout"
                    : "nativeDropDownNoProgress";
                WriteEvent("nativeDropDownFailed", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    reason = nativeFailure,
                    elapsed,
                    position = Vec(position),
                    grounded,
                    sawAirborne = probe.NativeDropDownSawAirborne,
                    sawDescent = probe.NativeDropDownSawDescent,
                    sawFarSide = probe.NativeDropDownSawFarSide,
                    forwardProjection,
                    requiredProjection,
                    descent
                });

                probe.AssistedStrategySelected = true;
                string assistFailure = "assisted replay already attempted";
                if (!probe.AssistedReplayAttempted &&
                    TryBeginAssistedTraversalReplay(
                        probe,
                        "nativeDropDownFallback:" + nativeFailure,
                        out assistFailure))
                {
                    return;
                }
                FinalizeOrEscalateTraversalFailure(
                    probe,
