        private static bool TryBeginAssistedVaultReplayV2(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string source,
            out string failure)
        {
            failure = string.Empty;
            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == commitment.EdgeId);
            LearnedTraversalEdge collisionEdge = IsLearningV319TransientSkillTransfer(commitment) ? null : edge;
            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 runOutExit = commitment.HasSettledExit && IsFinite(commitment.SettledExit)
                ? commitment.SettledExit
                : rawExit;
            Vector3 start = probe.Player.Position;
            if (!IsFinite(start) || !IsFinite(rawEntry) || !IsFinite(rawExit) || !IsFinite(runOutExit))
            {
                failure = "assisted V2 endpoints are invalid";
                return false;
            }

            float totalDistance = Vector3.Distance(start, runOutExit);
            if (totalDistance < 0.30f || totalDistance > 5.75f || Mathf.Abs(runOutExit.y - start.y) > 3.0f)
            {
                failure = $"assisted V2 geometry rejected distance={totalDistance:0.00}m vertical={runOutExit.y - start.y:0.00}m";
                return false;
            }

            float replaySpeed = probe.DemonstratedApproachSpeed > 0.50f
                ? Mathf.Clamp(probe.DemonstratedApproachSpeed, 1.35f, 4.75f)
                : AssistedReplayMotionSpeed;
            float leadInDistance = GetPlanarDistance(start, rawEntry);
            float crossDistance = Mathf.Max(0.35f, GetPlanarDistance(rawEntry, rawExit));
            float runOutDistance = GetPlanarDistance(rawExit, runOutExit);
            float demonstratedDuration = edge?.MotionSamples != null && edge.MotionSamples.Count > 1
                ? edge.MotionSamples.Max(sample => sample?.Time ?? 0f)
                : 0f;
            if (demonstratedDuration < 0.10f)
            {
                demonstratedDuration = edge?.TraversalDuration > 0.10f
                    ? edge.TraversalDuration
                    : Mathf.Max(0.30f, crossDistance / replaySpeed);
            }

            probe.AssistedReplayAttempted = true;
            probe.AssistedReplayTerminalized = false;
            probe.AssistedStrategySelected = true;
            TransitionProbeStage(probe, ProbeStage.AssistedReplay);
            probe.StageStartedAt = Time.time;
            probe.ExclusiveMoverGate = true;
            probe.AssistedReplayStart = start;
            probe.AssistedReplayRawEntry = rawEntry;
            probe.AssistedReplayRawExit = rawExit;
            probe.AssistedReplayRunOutExit = runOutExit;
            probe.AssistedReplayExit = runOutExit;
            probe.AssistedLeadInDuration = leadInDistance <= 0.12f
                ? 0f
                : Mathf.Clamp(leadInDistance / Mathf.Max(2.25f, replaySpeed), 0.05f, AssistedLeadInMaxSeconds);
            probe.AssistedCrossDuration = Mathf.Clamp(demonstratedDuration, AssistedCrossMinSeconds, AssistedCrossMaxSeconds);
            probe.AssistedRunOutDuration = runOutDistance <= 0.10f
                ? 0f
                : Mathf.Clamp(runOutDistance / AssistedRunOutSpeed, AssistedRunOutMinSeconds, AssistedRunOutMaxSeconds);
            probe.AssistedReplayDuration = probe.AssistedLeadInDuration + probe.AssistedCrossDuration + probe.AssistedRunOutDuration;
            bool forwardMotionCompatible = IsNativeVaultDirectionCompatible(edge, commitment);
            probe.AssistedMotionSamples =
                forwardMotionCompatible &&
                edge?.MotionSamples != null &&
                edge.MotionSamples.Count > 1
                    ? edge.MotionSamples
                        .Where(sample => sample != null && IsFinite(sample.LocalOffset))
                        .Select(CloneTraversalMotionSample)
                        .OrderBy(sample => sample.Time)
                        .ToList()
                    : BuildLinearTraversalMotionFallback(
                        rawEntry, rawExit, probe.AssistedCrossDuration);
            probe.AssistedReplayLastDistance = totalDistance;
            probe.AssistedReplayLastProgressAt = Time.time;
            probe.AssistedReplayLastObservedPosition = start;
            probe.AssistedReplayActualDisplacement = 0f;
            probe.AssistedReplayPhase = probe.AssistedLeadInDuration > 0f ? "LeadIn" : "Cross";
            probe.AssistedDivergenceSince = -1f;
            probe.AssistedCollisionRecoveryAttempted = false;
            probe.TraversalKind = string.IsNullOrWhiteSpace(commitment.Kind) ? probe.RequestedTraversalKind : commitment.Kind;
            probe.TriggerPosition = start;

            Vector3 direction = GetFlatDirection(rawExit - rawEntry);
            if (direction.sqrMagnitude > 0.5f)
            {
                probe.RequestedDirection = direction;
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-53FAB4442B99",@probe?.Bot,direction);
            }
            if (probe.Bot.Mover != null)
            {
                // Assisted V2 owns the crossing continuously. Clear the stale entry path without
                // calling BotOwner.StopMove(); HoldForwardInput keeps locomotion alive while the
                // old NavMesh route can no longer pull the follower back after landing.
                probe.Bot.Mover.BotMoverStop("R1-8873CD326EC9",@probe?.Bot);
                probe.Bot.Mover.SetBotMoverPause("R1-E22B9DAB2520",@probe?.Bot,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-234BD6DA066C",@probe?.Bot);
            }
            HoldForwardInput(probe);
            TryStartAssistedTraversalAnimation(probe);

            bool collisionLease = TryAcquireAssistedObstacleCollisionLease(probe, collisionEdge, rawEntry, rawExit, "authoredFingerprint");
            WriteEvent("assistedTraversalReplayStarted", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                kind = commitment.Kind,
                source,
                targetSource = commitment.HasSettledExit ? "rawEndThenLandingResume" : "rawEnd",
                start = Vec(start),
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                landingResume = Vec(runOutExit),
                leadInDuration = probe.AssistedLeadInDuration,
                crossDuration = probe.AssistedCrossDuration,
                runOutDuration = probe.AssistedRunOutDuration,
                duration = probe.AssistedReplayDuration,
                motionSampleCount = probe.AssistedMotionSamples?.Count ?? 0,
                collisionLease,
                demonstratedApproachSpeed = probe.DemonstratedApproachSpeed,
                demonstratedApproachMode = probe.DemonstratedApproachMode,
                demonstratedTraversalDuration = probe.DemonstratedTraversalDuration
            });
            return true;
        }

        private static List<TraversalMotionSample> BuildLinearTraversalMotionFallback(Vector3 rawEntry, Vector3 rawExit, float duration)
        {
            Vector3 forward = GetFlatDirection(rawExit - rawEntry);
            if (forward.sqrMagnitude < 0.5f)
            {
                forward = Vector3.forward;
            }
            Vector3 right = Vector3.Cross(Vector3.up, forward).normalized;
            Vector3 delta = rawExit - rawEntry;
            Vector3 localEnd = new Vector3(Vector3.Dot(delta, right), delta.y, Vector3.Dot(delta, forward));
            return new List<TraversalMotionSample>
            {
                new TraversalMotionSample { Time = 0f, LocalOffset = Vector3.zero, State = "ClimbOver", Grounded = false },
                new TraversalMotionSample { Time = Mathf.Max(0.10f, duration), LocalOffset = localEnd, State = "VaultingLanding", Grounded = false }
            };
        }

        private static Vector3 EvaluateAssistedTraversalMotion(ProbeRuntime probe, float normalizedT)
        {
            List<TraversalMotionSample> samples = probe?.AssistedMotionSamples;
            Vector3 rawEntry = probe?.AssistedReplayRawEntry ?? Vector3.zero;
            Vector3 rawExit = probe?.AssistedReplayRawExit ?? rawEntry;
            if (samples == null || samples.Count == 0)
            {
                return Vector3.Lerp(rawEntry, rawExit, Mathf.SmoothStep(0f, 1f, normalizedT));
            }

            float maxTime = Mathf.Max(0.10f, samples[samples.Count - 1].Time);
            float sampleTime = Mathf.Clamp01(normalizedT) * maxTime;
            TraversalMotionSample left = samples[0];
            TraversalMotionSample rightSample = samples[samples.Count - 1];
            for (int i = 1; i < samples.Count; i++)
            {
                if (samples[i].Time >= sampleTime)
                {
                    rightSample = samples[i];
                    left = samples[i - 1];
                    break;
                }
            }
            float segmentDuration = Mathf.Max(0.001f, rightSample.Time - left.Time);
            float localT = Mathf.Clamp01((sampleTime - left.Time) / segmentDuration);
            Vector3 localOffset = Vector3.Lerp(left.LocalOffset, rightSample.LocalOffset, Mathf.SmoothStep(0f, 1f, localT));

            Vector3 forward = GetFlatDirection(rawExit - rawEntry);
            if (forward.sqrMagnitude < 0.5f)
            {
                forward = probe.RequestedDirection.sqrMagnitude > 0.5f ? probe.RequestedDirection : Vector3.forward;
            }
            Vector3 right = Vector3.Cross(Vector3.up, forward).normalized;
            return rawEntry + right * localOffset.x + Vector3.up * localOffset.y + forward * localOffset.z;
        }

        private static void UpdateAssistedVaultReplayV2(ProbeRuntime probe)
        {
            if (probe == null || probe.AssistedReplayTerminalized)
            {
                return;
            }

            float elapsed = Time.time - probe.StageStartedAt;
            float leadEnd = probe.AssistedLeadInDuration;
            float crossEnd = leadEnd + probe.AssistedCrossDuration;
            float totalEnd = crossEnd + probe.AssistedRunOutDuration;
            Vector3 desired;
            string phase;
            bool useControllerMove;

            if (probe.AssistedNativeOwned)
            {
                HoldForwardInput(probe);
                float nativeStep = Vector3.Distance(probe.Player.Position, probe.AssistedReplayLastObservedPosition);
                if (nativeStep >= AssistedReplayProgressEpsilon)
                {
                    probe.AssistedReplayActualDisplacement += nativeStep;
                    probe.AssistedReplayLastObservedPosition = probe.Player.Position;
                    probe.AssistedReplayLastProgressAt = Time.time;
                }

                if (IsProbeTraversalState(probe.Player.CurrentStateName))
                {
                    // Native EFT state still owns root motion. Observation only. Keep a bounded
                    // ceiling so an orphaned ClimbOver/Vaulting state cannot own the follower forever.
                    if (Time.time - probe.AssistedNativeEnteredAt >= AssistedNativeOwnershipMaxSeconds)
                    {
                        RestoreAssistedObstacleCollisionLease(probe, "nativeOwnershipTimeout");
                        probe.AssistedReplayTerminalized = true;
                        WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                        {
                            reason = "nativeOwnershipTimeout",
                            state = probe.Player.CurrentStateName.ToString(),
                            elapsed = Time.time - probe.AssistedNativeEnteredAt,
                            position = Vec(probe.Player.Position)
                        });
                        EnterSafetyHold(probe, "native-owned traversal state did not release");
                    }
                    return;
                }

                if (probe.AssistedNativeReleasedAt <= 0f)
                {
                    probe.AssistedNativeReleasedAt = Time.time;
                    probe.AssistedNativeReleasePosition = probe.Player.Position;
                }

                Vector3 nativeForward = GetFlatDirection(probe.AssistedReplayRawExit - probe.AssistedReplayRawEntry);
                float authoredLength = Mathf.Max(0.10f, GetPlanarDistance(probe.AssistedReplayRawEntry, probe.AssistedReplayRawExit));
                float nativeProjection = nativeForward.sqrMagnitude > 0.5f
                    ? Vector3.Dot(probe.Player.Position - probe.AssistedReplayRawEntry, nativeForward)
                    : authoredLength;
                bool nativeReachedFarSideNeighborhood = nativeForward.sqrMagnitude < 0.5f ||
                    nativeProjection >= Mathf.Max(0.35f, authoredLength * 0.55f) ||
                    GetPlanarDistance(probe.Player.Position, probe.AssistedReplayRawExit) + 0.20f <
                    GetPlanarDistance(probe.Player.Position, probe.AssistedReplayRawEntry);

                if (!nativeReachedFarSideNeighborhood)
                {
                    // Native animation released before achieving useful crossing. Only now may the
                    // assisted controller take over; never run both controllers concurrently.
                    probe.AssistedNativeOwned = false;
                    probe.AssistedReplayStart = probe.Player.Position;
                    probe.AssistedReplayRawEntry = probe.Player.Position;
                    probe.AssistedLeadInDuration = 0f;
                    probe.AssistedCrossDuration = Mathf.Clamp(
                        GetPlanarDistance(probe.Player.Position, probe.AssistedReplayRawExit) /
                        Mathf.Max(2.25f, probe.DemonstratedApproachSpeed),
                        AssistedCrossMinSeconds,
                        AssistedCrossMaxSeconds);
                    probe.AssistedMotionSamples = BuildLinearTraversalMotionFallback(
                        probe.AssistedReplayRawEntry,
                        probe.AssistedReplayRawExit,
                        probe.AssistedCrossDuration);
                    probe.StageStartedAt = Time.time;
                    probe.AssistedReplayPhase = "Cross";
                    probe.AssistedDivergenceSince = -1f;
                    probe.AssistedCollisionRecoveryAttempted = false;
                    TryAcquireAssistedObstacleCollisionLease(
                        probe, null, probe.Player.Position, probe.AssistedReplayRawExit, "postNativeFallback");
                    WriteEvent("assistedTraversalNativeReleasedToFallback", probe.Bot, new
                    {
                        kind = probe.TraversalKind,
                        nativeProjection,
                        authoredLength,
                        position = Vec(probe.Player.Position),
                        rawExit = Vec(probe.AssistedReplayRawExit)
                    });
                    return;
                }

                float runOutDuration = Mathf.Max(0.08f, probe.AssistedRunOutDuration);
                float runOutT = Mathf.Clamp01((Time.time - probe.AssistedNativeReleasedAt) / runOutDuration);
                Vector3 runOutStart = IsFinite(probe.AssistedNativeReleasePosition)
                    ? probe.AssistedNativeReleasePosition
                    : probe.Player.Position;
                desired = Vector3.Lerp(runOutStart, probe.AssistedReplayRunOutExit, Mathf.SmoothStep(0f, 1f, runOutT));
                Vector3 nativeRunOutMotion = desired - probe.Player.Position;
                if (nativeRunOutMotion.magnitude > AssistedReplayMaxMotionPerTick)
                {
                    nativeRunOutMotion = nativeRunOutMotion.normalized * AssistedReplayMaxMotionPerTick;
                }
                try
                {
                    probe.Player.MovementContext.TryMovementContextApplyApproachMotion("R1-2EAA37DBD803",@probe?.Bot,nativeRunOutMotion,Mathf.Max(0.001f, Time.deltaTime));
                }
                catch (Exception ex)
                {
                    probe.AssistedReplayTerminalized = true;
                    WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                    {
                        reason = "nativeOwnedRunOutException",
                        error = ex.GetType().Name + ": " + ex.Message,
                        position = Vec(probe.Player.Position)
                    });
                    EnterSafetyHold(probe, "native-owned traversal run-out failed");
                    return;
                }

                if (runOutT < 1f)
                {
                    return;
                }

                float finalProjection = nativeForward.sqrMagnitude > 0.5f
                    ? Vector3.Dot(probe.Player.Position - probe.AssistedReplayRawExit, nativeForward)
                    : 0f;
                bool nativeFarSide = nativeForward.sqrMagnitude < 0.5f || finalProjection >= -AssistedMovingVerifyExitPlaneSlack;
                if (!nativeFarSide)
                {
                    if (probe.AssistedRunOutFarSideGraceUntil <= 0f)
                    {
                        probe.AssistedRunOutFarSideGraceUntil = Time.time + AssistedRunOutFarSideGraceSeconds;
                        WriteEvent("assistedTraversalFarSideGraceArmed", probe.Bot, new
                        {
                            source = "nativeOwned",
                            seconds = AssistedRunOutFarSideGraceSeconds,
                            exitProjection = finalProjection,
                            position = Vec(probe.Player.Position),
                            rawExit = Vec(probe.AssistedReplayRawExit)
                        });
                        return;
                    }
                    if (Time.time < probe.AssistedRunOutFarSideGraceUntil)
                    {
                        return;
                    }
                }

                if (!nativeFarSide &&
                    TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment nativeRecoveryCommitment) &&
                    nativeRecoveryCommitment != null &&
                    !IsVaultClimbFarSideForEgress(probe, nativeRecoveryCommitment, out float nativeGateProjection, out float nativeGateRequired) &&
                    TryRecoverVaultClimbCrossingBeforeEgress(
                        probe, nativeRecoveryCommitment, "nativeOwnedRunOutNotFarSide", nativeGateProjection, nativeGateRequired))
                {
                    // CompileFix33 monotonic crossing recovery: before entering SafetyHold, move to
                    // the next bounded executor stage. The existing attempt cap prevents cycling
                    // back through the same native/assisted failure indefinitely.
                    return;
                }

                probe.AssistedReplayTerminalized = true;
                if (nativeFarSide)
                {
                    WriteEvent("assistedTraversalReplayCompleted", probe.Bot, new
                    {
                        source = "nativeOwned",
                        position = Vec(probe.Player.Position),
                        rawExit = Vec(probe.AssistedReplayRawExit),
                        landingResume = Vec(probe.AssistedReplayRunOutExit),
                        exitProjection = finalProjection,
                        actualDisplacement = probe.AssistedReplayActualDisplacement
                    });
                    probe.TraversalVerifyTarget = probe.AssistedReplayRunOutExit;
                    BeginUnifiedTraversalVerify(probe, "assistedNativeOwnedCompleted");
                }
                else
                {
                    WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                    {
                        reason = "nativeOwnedRunOutNotFarSide",
                        position = Vec(probe.Player.Position),
                        exitProjection = finalProjection,
                        rawExit = Vec(probe.AssistedReplayRawExit)
                    });
                    EnterSafetyHold(probe, "native-owned traversal released without a stable far-side exit");
                }
                return;
            }

            if (elapsed < leadEnd && leadEnd > 0f)
            {
                float t = Mathf.SmoothStep(0f, 1f, elapsed / Mathf.Max(0.001f, leadEnd));
                desired = Vector3.Lerp(probe.AssistedReplayStart, probe.AssistedReplayRawEntry, t);
                phase = "LeadIn";
                useControllerMove = false;
            }
            else if (elapsed < crossEnd || probe.AssistedRunOutDuration <= 0f)
            {
                float t = Mathf.Clamp01((elapsed - leadEnd) / Mathf.Max(0.001f, probe.AssistedCrossDuration));
                desired = EvaluateAssistedTraversalMotion(probe, t);
                phase = "Cross";
                useControllerMove = true;
            }
            else
            {
                if (probe.AssistedIgnoredObstacleColliders.Count > 0)
                {
                    RestoreAssistedObstacleCollisionLease(probe, "crossCompleted");
                }
                float t = Mathf.Clamp01((elapsed - crossEnd) / Mathf.Max(0.001f, probe.AssistedRunOutDuration));
                desired = Vector3.Lerp(probe.AssistedReplayRawExit, probe.AssistedReplayRunOutExit, Mathf.SmoothStep(0f, 1f, t));
                phase = "RunOut";
                useControllerMove = false;
            }

            if (!string.Equals(probe.AssistedReplayPhase, phase, StringComparison.Ordinal))
            {
                probe.AssistedReplayPhase = phase;
                if (string.Equals(phase, "RunOut", StringComparison.Ordinal))
                {
                    TryStartAssistedTraversalLandingAnimation(probe);
                }
                WriteEvent("assistedTraversalReplayPhase", probe.Bot, new
                {
                    phase,
                    elapsed,
                    position = Vec(probe.Player.Position),
                    desired = Vec(desired)
                });
            }

            Vector3 motion = desired - probe.Player.Position;
            if (motion.magnitude > AssistedReplayMaxMotionPerTick)
            {
                motion = motion.normalized * AssistedReplayMaxMotionPerTick;
            }
            HoldForwardInput(probe);
            try
            {
                float dt = Mathf.Max(0.001f, Time.deltaTime);
                if (useControllerMove)
                {
                    probe.Player.CharacterController.TryICharacterControllerMove("R1-C7A4F3962033",@probe?.Bot,motion,dt);
                }
                else
                {
                    probe.Player.MovementContext.TryMovementContextApplyApproachMotion("R1-3004727FDD35",@probe?.Bot,motion,dt);
                }
            }
            catch (Exception ex)
            {
                RestoreAssistedObstacleCollisionLease(probe, "motionException");
                probe.AssistedReplayTerminalized = true;
                WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                {
                    reason = "assistedV2MotionException",
                    phase,
                    error = ex.GetType().Name + ": " + ex.Message,
                    position = Vec(probe.Player.Position),
                    desired = Vec(desired)
                });
                if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "assistedV2MotionException"))
                {
                    EnterSafetyHold(probe, "assisted V2 motion failed and deterministic exit teleport was unavailable");
                }
                return;
            }

            float observedStep = Vector3.Distance(probe.Player.Position, probe.AssistedReplayLastObservedPosition);
            if (observedStep >= AssistedReplayProgressEpsilon)
            {
                probe.AssistedReplayActualDisplacement += observedStep;
                probe.AssistedReplayLastObservedPosition = probe.Player.Position;
                probe.AssistedReplayLastProgressAt = Time.time;
            }

            if (string.Equals(phase, "Cross", StringComparison.Ordinal))
            {
                float divergence = Vector3.Distance(probe.Player.Position, desired);
                if (divergence >= 1.05f)
                {
                    if (!probe.AssistedCollisionRecoveryAttempted)
                    {
                        probe.AssistedCollisionRecoveryAttempted = true;
                        bool acquired = TryAcquireAssistedObstacleCollisionLease(probe, null, probe.Player.Position, desired, "dynamicDivergenceRecovery");
                        probe.AssistedDivergenceSince = Time.time;
                        WriteEvent("assistedTraversalDivergenceRecovery", probe.Bot, new
                        {
                            divergence,
                            acquiredCollisionLease = acquired,
                            position = Vec(probe.Player.Position),
                            desired = Vec(desired)
                        });
                        return;
                    }
                    if (probe.AssistedDivergenceSince < 0f)
                    {
                        probe.AssistedDivergenceSince = Time.time;
                    }
                    if (Time.time - probe.AssistedDivergenceSince >= AssistedDivergenceRecoveryGrace)
                    {
                        RestoreAssistedObstacleCollisionLease(probe, "controllerDivergence");
                        probe.AssistedReplayTerminalized = true;
                        WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                        {
                            reason = "controllerDivergence",
                            phase,
                            elapsed,
                            divergence,
                            position = Vec(probe.Player.Position),
                            desired = Vec(desired),
                            exit = Vec(probe.AssistedReplayRunOutExit)
                        });
                        if (TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment divergenceCommitment) &&
                            divergenceCommitment != null &&
                            !IsVaultClimbFarSideForEgress(probe, divergenceCommitment, out float divergenceProjection, out float divergenceRequired))
                        {
                            probe.AssistedReplayTerminalized = false;
                            if (TryRecoverVaultClimbCrossingBeforeEgress(
                                    probe, divergenceCommitment, "assistedV2ControllerDivergence", divergenceProjection, divergenceRequired))
                            {
                                return;
                            }
                            probe.AssistedReplayTerminalized = true;
                        }
                        if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "assistedReplayControllerDivergence"))
                        {
                            EnterSafetyHold(probe, "assisted V2 controller divergence and deterministic exit teleport was unavailable");
                        }
                        return;
                    }
                }
                else
                {
                    probe.AssistedDivergenceSince = -1f;
                }
            }

            if (elapsed < totalEnd)
            {
                return;
            }

            RestoreAssistedObstacleCollisionLease(probe, "runOutCompleted");
            Vector3 forward = GetFlatDirection(probe.AssistedReplayRawExit - probe.AssistedReplayRawEntry);
            float exitProjection = forward.sqrMagnitude > 0.5f
                ? Vector3.Dot(probe.Player.Position - probe.AssistedReplayRawExit, forward)
                : 0f;
            bool farSide = forward.sqrMagnitude < 0.5f || exitProjection >= -AssistedMovingVerifyExitPlaneSlack;
            float landingError = Vector3.Distance(probe.Player.Position, probe.AssistedReplayRunOutExit);

            // CompileFix16: the replay timeline ending is a one-shot transaction boundary.
            // CompileFix30 keeps that boundary but allows a tiny bounded grace while ApproachMotion
            // is still actively converging on the far-side run-out target. This absorbs the native
            // landing-release timing race without reviving an unbounded replay loop.
            if (!farSide)
            {
                if (probe.AssistedRunOutFarSideGraceUntil <= 0f)
                {
                    probe.AssistedRunOutFarSideGraceUntil = Time.time + AssistedRunOutFarSideGraceSeconds;
                    WriteEvent("assistedTraversalFarSideGraceArmed", probe.Bot, new
                    {
                        source = "assistedRunOut",
                        seconds = AssistedRunOutFarSideGraceSeconds,
                        exitProjection,
                        landingError,
                        position = Vec(probe.Player.Position),
                        rawExit = Vec(probe.AssistedReplayRawExit)
                    });
                    return;
                }
                if (Time.time < probe.AssistedRunOutFarSideGraceUntil)
                {
                    return;
                }
            }

            if (!farSide &&
                TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment runOutRecoveryCommitment) &&
                runOutRecoveryCommitment != null &&
                !IsVaultClimbFarSideForEgress(probe, runOutRecoveryCommitment, out float runOutGateProjection, out float runOutGateRequired) &&
                TryRecoverVaultClimbCrossingBeforeEgress(
                    probe, runOutRecoveryCommitment, "assistedV2RunOutNotFarSide", runOutGateProjection, runOutGateRequired))
            {
                return;
            }

            probe.AssistedReplayTerminalized = true;
            if (farSide)
            {
                WriteEvent("assistedTraversalReplayCompleted", probe.Bot, new
                {
                    position = Vec(probe.Player.Position),
                    rawExit = Vec(probe.AssistedReplayRawExit),
                    landingResume = Vec(probe.AssistedReplayRunOutExit),
                    landingError,
                    exitProjection,
                    farSide = true,
                    actualDisplacement = probe.AssistedReplayActualDisplacement
                });
                probe.TraversalVerifyTarget = probe.AssistedReplayRunOutExit;
                BeginUnifiedTraversalVerify(probe, "assistedV2RunOutCompleted");
                return;
            }

            WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
            {
                reason = "runOutNotFarSide",
                position = Vec(probe.Player.Position),
                rawExit = Vec(probe.AssistedReplayRawExit),
                landingResume = Vec(probe.AssistedReplayRunOutExit),
                landingError,
                exitProjection,
                farSide = false,
                actualDisplacement = probe.AssistedReplayActualDisplacement
            });
            if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "assistedV2RunOutNotFarSide"))
            {
                EnterSafetyHold(probe, "assisted V2 run-out ended on the entry side and deterministic exit teleport was unavailable");
            }
        }

        private static bool TryAcquireAssistedObstacleCollisionLease(
            ProbeRuntime probe,
            LearnedTraversalEdge edge,
            Vector3 from,
            Vector3 to,
            string source)
        {
            if (probe?.Player == null)
            {
                return false;
            }

            Collider obstacle = ResolveTraversalObstacleCollider(probe.Player, edge, from, to);
            if (!IsSafeTraversalObstacleCollider(probe.Player, obstacle))
            {
                return false;
            }
            if (probe.AssistedIgnoredObstacleColliders.Contains(obstacle))
            {
                if (edge != null)
                {
                    return true;
                }

                Vector3 direction = GetFlatDirection(to - from);
                if (direction.sqrMagnitude > 0.5f)
                {
                    RaycastHit[] hits = Physics.RaycastAll(
                        probe.Player.Position + Vector3.up * 0.48f - direction * 0.05f,
                        direction,
                        AssistedCollisionProbeDistance,
                        Physics.AllLayers,
                        QueryTriggerInteraction.Ignore);
                    if (hits != null)
                    {
                        obstacle = hits
                            .OrderBy(hit => hit.distance)
                            .Select(hit => hit.collider)
                            .FirstOrDefault(collider => IsSafeTraversalObstacleCollider(probe.Player, collider) &&
                                                        !probe.AssistedIgnoredObstacleColliders.Contains(collider));
                    }
                }
                if (!IsSafeTraversalObstacleCollider(probe.Player, obstacle) || probe.AssistedIgnoredObstacleColliders.Contains(obstacle))
                {
                    return false;
                }
            }

            long collisionLeasePerfStart = BeginTraversalPerfSample();
            List<Collider> playerColliders = CollectAssistedPlayerCollisionColliders(
                probe, out bool controllerColliderFound);
            if (playerColliders.Count == 0)
            {
                return false;
            }

            int ignoredThisObstacle = 0;
            foreach (Collider playerCollider in playerColliders)
            {
                if (playerCollider == null || ReferenceEquals(playerCollider, obstacle))
                {
                    continue;
                }
                try
                {
                    global::BotTraversal.Core.FollowerControlBackend.PhysicsIgnoreCollision("R1-D31899B502E6",@probe?.Bot,playerCollider,obstacle,true);
                    ignoredThisObstacle++;
                    if (!probe.AssistedIgnoredPlayerColliders.Contains(playerCollider))
                    {
                        probe.AssistedIgnoredPlayerColliders.Add(playerCollider);
                    }
                }
                catch
                {
                    // Some EFT proxy colliders can be disposed mid-state; skip them individually.
                }
            }
            if (ignoredThisObstacle == 0)
            {
                return false;
            }

            probe.AssistedIgnoredObstacleCollider = obstacle;
            probe.AssistedIgnoredObstacleColliders.Add(obstacle);
            EndTraversalPerfSample(
                "CollisionLeaseAcquirePairs",
                collisionLeasePerfStart,
                probe.Bot,
                probe.LearnedEdgeId,
                probe.TraversalKind);
            WriteEvent("assistedTraversalCollisionLeaseAcquired", probe.Bot, new
            {
                source,
                collider = obstacle.name,
                layer = obstacle.gameObject.layer,
                ignoredPlayerColliderCount = ignoredThisObstacle,
                controllerColliderFound,
                ignoredObstacleCount = probe.AssistedIgnoredObstacleColliders.Count,
                center = Vec(obstacle.bounds.center),
                size = Vec(obstacle.bounds.size)
            });
            return true;
        }

        private static List<Collider> CollectAssistedPlayerCollisionColliders(
            ProbeRuntime probe,
            out bool controllerColliderFound)
        {
            controllerColliderFound = false;
            Player player = probe?.Player;
            if (probe == null || player == null)
            {
                return new List<Collider>();
            }

            if (probe.AssistedPlayerColliderCache != null &&
                probe.AssistedPlayerColliderCache.Count > 0)
            {
                probe.AssistedPlayerColliderCache.RemoveAll(collider => collider == null);
                if (probe.AssistedPlayerColliderCache.Count > 0)
                {
                    controllerColliderFound = probe.AssistedPlayerColliderCacheControllerFound;
                    return probe.AssistedPlayerColliderCache;
                }
            }

            bool foundControllerCollider = false;
            List<Collider> colliders = player.GetComponentsInChildren<Collider>(true)
                ?.Where(collider => collider != null)
                .Distinct()
                .ToList() ?? new List<Collider>();

            try
            {
                object rawController = player.CharacterController;
                if (rawController != null)
                {
                    Action<Collider> addControllerCollider = collider =>
                    {
                        if (collider == null)
                        {
                            return;
                        }
                        foundControllerCollider = true;
                        if (!colliders.Contains(collider))
                        {
                            colliders.Add(collider);
                        }
                    };

                    addControllerCollider(rawController as Collider);
                    if (rawController is Component controllerComponent)
                    {
                        addControllerCollider(controllerComponent.GetComponent<Collider>());
                    }

                    Type controllerType = rawController.GetType();
                    foreach (PropertyInfo property in controllerType.GetProperties(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
                    {
                        if (!property.CanRead || property.GetIndexParameters().Length != 0 ||
                            !typeof(Collider).IsAssignableFrom(property.PropertyType))
                        {
                            continue;
                        }
                        try
                        {
                            addControllerCollider(property.GetValue(rawController, null) as Collider);
                        }
                        catch
                        {
                        }
                    }
                    foreach (FieldInfo field in controllerType.GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
                    {
                        if (!typeof(Collider).IsAssignableFrom(field.FieldType))
                        {
                            continue;
                        }
                        try
                        {
                            addControllerCollider(field.GetValue(rawController) as Collider);
                        }
                        catch
                        {
                        }
                    }
                }
            }
            catch
            {
                // Child colliders are still useful even if the EFT controller wrapper is disposed.
            }

            controllerColliderFound = foundControllerCollider;
            probe.AssistedPlayerColliderCache = colliders;
            probe.AssistedPlayerColliderCacheControllerFound = foundControllerCollider;
            return colliders;
        }

        private static Collider ResolveTraversalObstacleCollider(Player player, LearnedTraversalEdge edge, Vector3 from, Vector3 to)
        {
            TraversalObstacleFingerprint fingerprint = edge?.ObstacleFingerprint;
            if (IsSafeTraversalObstacleCollider(player, fingerprint?.RuntimeCollider))
            {
                return fingerprint.RuntimeCollider;
            }

            if (fingerprint != null && IsFinite(fingerprint.BoundsCenter))
            {
                float radius = Mathf.Clamp(fingerprint.BoundsSize.magnitude * 0.55f + 0.75f, 1.0f, 6.0f);
                Collider[] candidates = Physics.OverlapSphere(fingerprint.BoundsCenter, radius, Physics.AllLayers, QueryTriggerInteraction.Ignore);
                Collider matched = candidates?.Where(collider => IsSafeTraversalObstacleCollider(player, collider) &&
                                       (string.IsNullOrEmpty(fingerprint.Name) || string.Equals(collider.name, fingerprint.Name, StringComparison.OrdinalIgnoreCase)))
                    .OrderBy(collider => Vector3.Distance(collider.bounds.center, fingerprint.BoundsCenter) +
                                         Vector3.Distance(collider.bounds.size, fingerprint.BoundsSize) * 0.35f)
                    .FirstOrDefault();
                if (matched != null)
                {
                    fingerprint.RuntimeCollider = matched;
                    return matched;
                }
            }

            Vector3 direction = GetFlatDirection(to - from);
            if (direction.sqrMagnitude > 0.5f)
            {
                Vector3 origin = player.Position + Vector3.up * 0.48f - direction * 0.05f;
                if (TryGetFirstNonSelfRaycastHit(player, origin, direction, AssistedCollisionProbeDistance, out RaycastHit hit) &&
                    IsSafeTraversalObstacleCollider(player, hit.collider))
                {
                    return hit.collider;
                }
            }
            return null;
        }

        private static void RestoreAssistedObstacleCollisionLease(ProbeRuntime probe, string reason)
        {
            if (probe == null || probe.AssistedIgnoredObstacleColliders.Count == 0)
            {
                return;
            }
            Collider[] obstacles = probe.AssistedIgnoredObstacleColliders.Where(collider => collider != null).Distinct().ToArray();
            Collider[] playerColliders = probe.AssistedIgnoredPlayerColliders.Where(collider => collider != null).Distinct().ToArray();
            long collisionRestorePerfStart = BeginTraversalPerfSample();
            int restored = 0;
            foreach (Collider obstacle in obstacles)
            {
                foreach (Collider playerCollider in playerColliders)
                {
                    try
                    {
                        global::BotTraversal.Core.FollowerControlBackend.PhysicsIgnoreCollision("R1-AC473F2C1CE8",@probe?.Bot,playerCollider,obstacle,false);
                        restored++;
                    }
                    catch
                    {
                        // Lifecycle cleanup must continue even if one collider has already been destroyed.
                    }
                }
            }
            string primaryName = probe.AssistedIgnoredObstacleCollider != null ? probe.AssistedIgnoredObstacleCollider.name : null;
            probe.AssistedIgnoredPlayerColliders.Clear();
            probe.AssistedIgnoredObstacleColliders.Clear();
            probe.AssistedIgnoredObstacleCollider = null;
            EndTraversalPerfSample(
                "CollisionLeaseReleasePairs",
                collisionRestorePerfStart,
                probe.Bot,
                probe.LearnedEdgeId,
                probe.TraversalKind);
            WriteEvent("assistedTraversalCollisionLeaseReleased", probe.Bot, new
            {
                reason,
                collider = primaryName,
                restoredPairCount = restored,
                obstacleCount = obstacles.Length
            });
        }

        private static void UpdateAssistedTraversalReplay(ProbeRuntime probe)
        {
            if (probe == null || probe.AssistedReplayTerminalized || !IsActiveProbe(probe) ||
                probe.Player?.MovementContext == null || probe.Player.CharacterController == null)
            {
                return;
            }

            if (probe.VaultControlledBridgeActive)
            {
                UpdateControlledVaultCrossingBridge(probe);
                return;
            }

            if (string.Equals(probe.TraversalKind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(probe.TraversalKind, "Climb", StringComparison.OrdinalIgnoreCase))
            {
                UpdateAssistedVaultReplayV2(probe);
                return;
            }

            float elapsed = Time.time - probe.StageStartedAt;
            if (probe.AssistedAnimationStarted &&
                !string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                elapsed < AssistedAnimationLeadGraceSeconds)
            {
                // Animation/state first: keep facing/locomotion coherent for a few frames before
                // positional fallback begins. This is intentionally short so a missing/rootless
                // animation can never strand the follower.
                probe.Bot.Mover.SetBotMoverPause("R1-B202DEF233CE",@probe?.Bot,false);
                probe.Bot.BotOwnerSetPose("R1-07855F669B4C",@probe?.Bot,1f);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-9BA0EB24516C",@probe?.Bot,probe.RequestedDirection);
                return;
            }
            float replayElapsed = Mathf.Max(0f, elapsed - (probe.AssistedAnimationStarted ? AssistedAnimationLeadGraceSeconds : 0f));
            float t = Mathf.Clamp01(replayElapsed / Mathf.Max(0.01f, probe.AssistedReplayDuration));
            Vector3 desired;
            string phase;

            // V1.3.18 gives each traversal kind its own visual/motion profile. Jump keeps forward
            // momentum on a ballistic arc; Vault and Climb use collision-respecting lift/cross/land.
            bool assistedJump = string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase);
            bool assistedDropDown = string.Equals(probe.TraversalKind, "DropDown", StringComparison.OrdinalIgnoreCase);
            bool assistedWalkThrough = string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            if (assistedDropDown)
            {
                // Natural DropDown replay never fabricates a jump arc. Move across the authored
                // ledge line while descending toward the player's grounded landing; CharacterController
                // collision remains authoritative and teleport stays a bounded last resort.
                float eased = Mathf.SmoothStep(0f, 1f, t);
                desired = Vector3.Lerp(probe.AssistedReplayStart, probe.AssistedReplayExit, eased);
                phase = t < 0.28f ? "EdgeCommit" : "Drop";
            }
            else if (assistedJump || assistedWalkThrough)
            {
                float eased = Mathf.SmoothStep(0f, 1f, t);
                desired = Vector3.Lerp(probe.AssistedReplayStart, probe.AssistedReplayExit, eased);
                desired.y += 4f * probe.AssistedReplayArcHeight * t * (1f - t);
                phase = assistedWalkThrough ? "Cross" : (t < 0.72f ? "Cross" : "Land");
            }
            else
            {
                bool assistedClimb = string.Equals(probe.TraversalKind, "Climb", StringComparison.OrdinalIgnoreCase);
                float liftEnd = assistedClimb ? 0.42f : AssistedReplayLiftEndT;
                float crossEnd = assistedClimb ? 0.76f : AssistedReplayCrossEndT;

                if (t < liftEnd)
                {
                    float localT = Mathf.SmoothStep(0f, 1f, t / liftEnd);
                    Vector3 liftAnchor = probe.AssistedReplayStart;
                    liftAnchor.y = probe.AssistedReplayLiftY;
                    desired = Vector3.Lerp(probe.AssistedReplayStart, liftAnchor, localT);
                    phase = "Lift";
                }
                else if (t < crossEnd)
                {
                    float localT = Mathf.SmoothStep(0f, 1f, (t - liftEnd) / (crossEnd - liftEnd));
                    Vector3 crossStart = probe.AssistedReplayStart;
                    crossStart.y = probe.AssistedReplayLiftY;
                    Vector3 crossEndPoint = probe.AssistedReplayExit;
                    crossEndPoint.y = probe.AssistedReplayLiftY;
                    desired = Vector3.Lerp(crossStart, crossEndPoint, localT);
                    phase = "Cross";
                }
                else
                {
                    float localT = Mathf.SmoothStep(0f, 1f, (t - crossEnd) / (1f - crossEnd));
                    Vector3 landStart = probe.AssistedReplayExit;
                    landStart.y = probe.AssistedReplayLiftY;
                    desired = Vector3.Lerp(landStart, probe.AssistedReplayExit, localT);
                    phase = "Land";
                }
            }

            if (!string.Equals(probe.AssistedReplayPhase, phase, StringComparison.Ordinal))
            {
                probe.AssistedReplayPhase = phase;
                if (string.Equals(phase, "Land", StringComparison.Ordinal))
                {
                    TryStartAssistedTraversalLandingAnimation(probe);
                }
                WriteEvent("assistedTraversalReplayPhase", probe.Bot, new
                {
                    phase,
                    elapsed,
                    t,
                    position = Vec(probe.Player.Position),
                    desired = Vec(desired)
                });
            }

            Vector3 motion = desired - probe.Player.Position;
            if (motion.magnitude > AssistedReplayMaxMotionPerTick)
            {
                motion = motion.normalized * AssistedReplayMaxMotionPerTick;
            }

            HoldForwardInput(probe);
            try
            {
                float deltaTime = Mathf.Max(0.001f, Time.deltaTime);
                // CharacterController.Move is already used by PIT's soft-collision system and keeps
                // EFT world collision active. Unlike ApplyApproachMotion, it can own the vertical
                // lift phase instead of having the first diagonal step cancelled by the wall.
                probe.Player.CharacterController.TryICharacterControllerMove("R1-002B1679A1E2",@probe?.Bot,motion,deltaTime);
            }
            catch (Exception ex)
            {
                probe.AssistedReplayTerminalized = true;
                WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                {
                    reason = "CharacterControllerMoveException",
                    phase,
                    error = ex.GetType().Name + ": " + ex.Message,
                    position = Vec(probe.Player.Position),
                    exit = Vec(probe.AssistedReplayExit)
                });
                if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "assistedReplayMotionException"))
                {
                    EnterSafetyHold(probe, "assisted replay motion failed and deterministic exit teleport was unavailable");
                }
                return;
            }

            // V1.3.23: if EFT's controller is visibly refusing the authored Vault/Climb spline,
            // do not play the remainder of a fake traversal and only discover the miss at Landing.
            // Recover early to the semantic exit so the visual discontinuity is shorter.
            bool assistedVaultOrClimb =
                string.Equals(probe.TraversalKind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(probe.TraversalKind, "Climb", StringComparison.OrdinalIgnoreCase);
            if (assistedVaultOrClimb &&
                t >= 0.55f &&
                !string.Equals(phase, "Lift", StringComparison.Ordinal) &&
                Vector3.Distance(probe.Player.Position, desired) >= 1.15f)
            {
                float divergence = Vector3.Distance(probe.Player.Position, desired);
                WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                {
                    reason = "controllerDivergence",
                    phase,
                    elapsed,
                    t,
                    divergence,
                    position = Vec(probe.Player.Position),
                    desired = Vec(desired),
                    exit = Vec(probe.AssistedReplayExit)
                });
                if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "assistedReplayControllerDivergence"))
                {
                    EnterSafetyHold(probe, "assisted replay diverged from EFT controller and deterministic exit teleport was unavailable");
                }
                return;
            }

            float observedStep = Vector3.Distance(probe.Player.Position, probe.AssistedReplayLastObservedPosition);
            if (observedStep >= AssistedReplayProgressEpsilon)
            {
                probe.AssistedReplayActualDisplacement += observedStep;
                probe.AssistedReplayLastObservedPosition = probe.Player.Position;
                probe.AssistedReplayLastProgressAt = Time.time;
            }
            else if (elapsed >= 0.18f && Time.time - probe.AssistedReplayLastProgressAt >=
                     (assistedDropDown ? DropDownReplayNoProgressTimeout : AssistedReplayNoProgressTimeout))
            {
                bool assistedWalkThroughRecovery = string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
                if (assistedWalkThroughRecovery && !probe.AssistedCollisionRecoveryAttempted)
                {
                    probe.AssistedCollisionRecoveryAttempted = true;
                    bool acquired = TryAcquireAssistedObstacleCollisionLease(
                        probe, null, probe.Player.Position, probe.AssistedReplayExit, "walkThroughNoProgressRecovery");
                    WriteEvent("assistedTraversalDivergenceRecovery", probe.Bot, new
                    {
                        reason = "walkThroughNoProgress",
                        acquiredCollisionLease = acquired,
                        position = Vec(probe.Player.Position),
                        desired = Vec(probe.AssistedReplayExit)
                    });
                    if (acquired)
                    {
                        probe.AssistedReplayLastProgressAt = Time.time;
                        return;
                    }
                }
                float remaining = Vector3.Distance(probe.Player.Position, probe.AssistedReplayExit);
                probe.AssistedReplayTerminalized = true;
                WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
                {
                    reason = "noControllerProgress",
                    phase,
                    elapsed,
                    remaining,
                    actualDisplacement = probe.AssistedReplayActualDisplacement,
                    position = Vec(probe.Player.Position),
                    exit = Vec(probe.AssistedReplayExit)
                });
                if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "assistedReplayNoProgress"))
                {
                    EnterSafetyHold(probe, "assisted replay made no controller progress and deterministic exit teleport was unavailable");
                }
                return;
            }

            if (t < 1f)
            {
                return;
            }

            float landingError = Vector3.Distance(probe.Player.Position, probe.AssistedReplayExit);
            float landingTolerance = probe.JumpBridgeActive ? JumpBridgeLandingTolerance : AssistedReplayLandingTolerance;
            Vector3 completionForward = GetFlatDirection(probe.AssistedReplayRawExit - probe.AssistedReplayRawEntry);
            float completionExitProjection = completionForward.sqrMagnitude > 0.5f
                ? Vector3.Dot(probe.Player.Position - probe.AssistedReplayRawExit, completionForward)
                : 0f;
            bool dropDownFarSide = !assistedDropDown || completionForward.sqrMagnitude < 0.5f ||
                                   completionExitProjection >= -AssistedMovingVerifyExitPlaneSlack;

            if (assistedDropDown && !dropDownFarSide &&
                elapsed < probe.AssistedReplayDuration + DropDownReplayCompletionGraceSeconds)
            {
                if (!probe.AssistedDropDownCompletionExtensionLogged)
                {
                    probe.AssistedDropDownCompletionExtensionLogged = true;
                    WriteEvent("assistedDropDownCompletionExtended", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        elapsed,
                        authoredDuration = probe.AssistedReplayDuration,
                        graceSeconds = DropDownReplayCompletionGraceSeconds,
                        landingError,
                        exitProjection = completionExitProjection,
                        actualDisplacement = probe.AssistedReplayActualDisplacement,
                        position = Vec(probe.Player.Position),
                        exit = Vec(probe.AssistedReplayExit)
                    });
                }
                return;
            }

            if (landingError <= landingTolerance && dropDownFarSide)
            {
                probe.AssistedReplayTerminalized = true;
                WriteEvent("assistedTraversalReplayCompleted", probe.Bot, new
                {
                    position = Vec(probe.Player.Position),
                    exit = Vec(probe.AssistedReplayExit),
                    landingError,
                    landingTolerance,
                    exitProjection = completionExitProjection,
                    dropDownFarSide,
                    actualDisplacement = probe.AssistedReplayActualDisplacement,
                    navMesh = SamplePayload(probe.Player.Position, 1.75f)
                });

                RestoreAssistedObstacleCollisionLease(probe, "assistedReplayCompleted");
                // R8.3: a Jump is not complete while EFT still owns JumpLanding. Starting the
                // egress servo here caused the visible platform slide and could strand the bot in
                // JumpLanding forever even after later teleports.
                if (string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                    probe.Player.CurrentStateName == EPlayerState.JumpLanding)
                {
                    BeginJumpLandingReleaseGate(probe, "assistedReplaySemanticExit");
                    return;
                }

                // WalkThrough Assisted may temporarily ignore only the demonstrated blocking
                // collider. Restore it before normal grounded egress/verify resumes.
                BeginUnifiedTraversalEgressOrVerify(probe, "assistedReplaySemanticExit");
                return;
            }

            probe.AssistedReplayTerminalized = true;
            WriteEvent("assistedTraversalReplayFailed", probe.Bot, new
            {
                reason = "landingValidation",
                position = Vec(probe.Player.Position),
                exit = Vec(probe.AssistedReplayExit),
                landingError,
                landingTolerance,
                exitProjection = completionExitProjection,
                dropDownFarSide,
                actualDisplacement = probe.AssistedReplayActualDisplacement
            });
            if (!TryTeleportPlayerValidatedTraversalAtExit(probe, "assistedReplayLandingFailed"))
            {
                EnterSafetyHold(probe, "assisted replay landing failed and deterministic exit teleport was unavailable");
            }
        }

        private static void CompleteAssistedTraversalReplay(ProbeRuntime probe)
        {
            // Kept as a compatibility shim for old internal call sites. V1.3.21 never treats RawExit
            // as a completed traversal; the unified finalizer is reached only after Verify.
            BeginUnifiedTraversalEgressOrVerify(probe, "assistedReplayCompatibility");
        }

        private static bool TryGetTraversalDownstreamEvidence(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            out Vector3 target,
            out int sequence,
            out string source,
            bool allowLeaderFallback = true)
        {
            target = default;
            sequence = 0;
            source = string.Empty;
            if (probe == null || commitment == null)
            {
                return false;
            }

            if (probe.TraversalDownstreamEvidenceResolved && IsFinite(probe.TraversalDownstreamEvidenceTarget) &&
                (allowLeaderFallback ||
                 !string.Equals(probe.TraversalDownstreamEvidenceSource, "leaderCurrent", StringComparison.OrdinalIgnoreCase)) &&
                !RejectCf22BackwardWalkThroughSuccessor(
                    probe, 0, "WalkThrough", probe.TraversalDownstreamEvidenceTarget, "cachedRouteBreadcrumb"))
            {
                target = probe.TraversalDownstreamEvidenceTarget;
                sequence = probe.TraversalDownstreamEvidenceSequence;
                source = probe.TraversalDownstreamEvidenceSource ?? "cached";
                return true;
            }

            int episodeId = probe.TraversalEpisodeId > 0 ? probe.TraversalEpisodeId : commitment.EpisodeId;
            TraversalEpisodeMetadata episode = TraversalEpisodeStream
                .LastOrDefault(item => item != null && item.EpisodeId == episodeId);
            if (episode == null || episode.EndBreadcrumbSequence <= 0)
            {
                return false;
            }

            string profileId = probe.Bot?.ProfileId ?? string.Empty;
            List<PlayerBreadcrumbNode> routeNodes = null;
            FollowerRouteMission mission = null;
            if (!string.IsNullOrEmpty(profileId) &&
                FollowerRouteMissions.TryGetValue(profileId, out mission) && mission != null)
            {
                RefreshRouteMissionBreadcrumbSnapshot(mission);
                routeNodes = mission.RouteBreadcrumbs;
            }
            routeNodes ??= BreadcrumbRoute;

            int lowerSequence = episode.EndBreadcrumbSequence;
            int upperSequence = int.MaxValue;
            FollowerRouteMissionStep nextMissionStep = null;
            if (mission != null)
            {
                int currentIndex = commitment.RouteMissionId == mission.MissionId && commitment.RouteMissionStepIndex >= 0
                    ? commitment.RouteMissionStepIndex
                    : mission.CurrentStepIndex;
                if (currentIndex >= 0 && currentIndex < mission.Steps.Count)
                {
                    FollowerRouteMissionStep currentMissionStep = mission.Steps[currentIndex];
                    if (currentMissionStep != null && currentMissionStep.EdgeId == commitment.EdgeId &&
                        currentMissionStep.EndBreadcrumbSequence > lowerSequence)
                    {
                        // R9.6: route missions carry the current raid's traversal-tail sequence.
                        // A persisted edge's episode sequence is normally zero, which previously
                        // allowed pre-landing breadcrumbs to be selected as Jump egress evidence.
                        lowerSequence = currentMissionStep.EndBreadcrumbSequence;
                    }
                }
                if (currentIndex + 1 < mission.Steps.Count)
                {
                    nextMissionStep = mission.Steps[currentIndex + 1];
                    if (nextMissionStep != null && nextMissionStep.StartBreadcrumbSequence > lowerSequence)
                    {
                        upperSequence = nextMissionStep.StartBreadcrumbSequence;
                    }
                }
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 referenceExit = commitment.HasSettledExit && IsFinite(commitment.SettledExit)
                ? commitment.SettledExit
                : rawExit;
            Vector3 downstreamAxis = GetFlatDirection(referenceExit - rawEntry);
            PlayerBreadcrumbNode best = null;
            foreach (PlayerBreadcrumbNode node in routeNodes
                .Where(node => node != null &&
                               node.Sequence > lowerSequence &&
                               node.Sequence <= upperSequence &&
                               IsOperationalBreadcrumbNode(node) &&
                               node.NavMeshSampled)
                .OrderBy(node => node.Sequence))
            {
                float fromExit = GetPlanarDistance(referenceExit, node.Position);
                Vector3 fromSettledExit = node.Position - referenceExit;
                fromSettledExit.y = 0f;
                float forwardProjection = downstreamAxis.sqrMagnitude > 0.5f
                    ? Vector3.Dot(fromSettledExit, downstreamAxis)
                    : fromExit;
                // R9.6: never use a breadcrumb that points back toward the traversal crest/entry.
                // The old raw-exit search selected a pre-landing Jump tail and made followers turn
                // around after a successful landing until the 13s hard-stuck recovery fired.
                if (downstreamAxis.sqrMagnitude > 0.5f && forwardProjection < 0.20f)
                {
                    continue;
                }
                // A breadcrumb can be ahead of the old exit but behind the live
                // body. V430 already enforces this in egress; CF22 applies it
                // before the next movement producer is selected.
                Vector3 breadcrumbTarget = node.NavMeshSampled && IsFinite(node.NavMeshPosition)
                    ? node.NavMeshPosition : node.Position;
                if (RejectCf22BackwardWalkThroughSuccessor(
                        probe, 0, "WalkThrough", breadcrumbTarget, "forwardBreadcrumbAdmission"))
                {
                    continue;
                }
                best = node;
                if (fromExit >= 2.25f)
                {
                    break;
                }
            }

            if (best != null && IsFinite(best.Position))
            {
                target = best.NavMeshSampled && IsFinite(best.NavMeshPosition)
                    ? best.NavMeshPosition
                    : best.Position;
                sequence = best.Sequence;
                source = "playerRouteBreadcrumb";
            }
            else if (nextMissionStep != null && IsFinite(nextMissionStep.Entry) &&
                     !RejectCf22BackwardWalkThroughSuccessor(
                         probe, nextMissionStep.EdgeId, nextMissionStep.Kind,
                         nextMissionStep.Entry, "nextMissionBreadcrumbFallback"))
            {
                target = nextMissionStep.Entry;
                sequence = nextMissionStep.StartBreadcrumbSequence;
                source = "nextTraversalEntry";
            }
            else
            {
                if (!allowLeaderFallback)
                {
                    return false;
                }
                Player leader = FollowerEnvironment.LocalPlayer;
                if (IsLivePlayer(leader) && IsFinite(leader.Position) &&
                    GetPlanarDistance(referenceExit, leader.Position) >= 2.25f)
                {
                    Vector3 leaderDelta = leader.Position - referenceExit;
                    leaderDelta.y = 0f;
                    float leaderForwardProjection = downstreamAxis.sqrMagnitude > 0.5f
                        ? Vector3.Dot(leaderDelta, downstreamAxis)
                        : leaderDelta.magnitude;
                    if (downstreamAxis.sqrMagnitude > 0.5f && leaderForwardProjection < -0.25f)
                    {
                        return false;
                    }
                    target = leader.Position;
                    if (NavMesh.SamplePosition(leader.Position, out NavMeshHit leaderNav, 0.75f, NavMesh.AllAreas))
                    {
                        target = leaderNav.position;
                    }
                    sequence = breadcrumbSequence;
                    source = "leaderCurrent";
                }
                else
                {
                    return false;
                }
            }

            probe.TraversalDownstreamEvidenceResolved = true;
            probe.TraversalDownstreamEvidenceTarget = target;
            probe.TraversalDownstreamEvidenceSequence = sequence;
            probe.TraversalDownstreamEvidenceSource = source;
            return true;
        }

        private static bool HasTraversalDownstreamConnectivity(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            Vector3 candidate,
            out Vector3 downstreamTarget,
            out string downstreamSource)
        {
            downstreamTarget = default;
            downstreamSource = string.Empty;
            if (probe == null || commitment == null || !IsFinite(candidate))
            {
                return false;
            }

            Player leader = FollowerEnvironment.LocalPlayer;
            if (IsLivePlayer(leader) && IsFinite(leader.Position))
            {
                StrictPathResult leaderPath = CalculateStrictPath(candidate, leader.Position);
                float leaderDirect = Mathf.Max(0.25f, GetPlanarDistance(candidate, leader.Position));
                if (leaderPath.StrictComplete && leaderPath.PathLength <= leaderDirect * 2.75f + 4.0f)
                {
                    downstreamTarget = leader.Position;
                    downstreamSource = "leaderDirectPath";
                    probe.TraversalDownstreamConnected = true;
                    probe.TraversalDownstreamConnectivityCandidate = candidate;
                    return true;
                }
            }

            if (!TryGetTraversalDownstreamEvidence(
                    probe, commitment, out downstreamTarget, out _, out downstreamSource))
            {
                // No downstream evidence exists yet (for example the leader is still standing on
                // the traversal exit). Do not create a new hard gate from missing telemetry. Once
                // the player moves on, the evidence resolver will become authoritative.
                return true;
            }

            if (GetPlanarDistance(candidate, downstreamTarget) <= 0.85f)
            {
                probe.TraversalDownstreamConnected = true;
                probe.TraversalDownstreamConnectivityCandidate = candidate;
                return true;
            }

            if (Time.time < probe.TraversalDownstreamConnectivityNextCheckAt &&
                GetPlanarDistance(candidate, probe.TraversalDownstreamConnectivityCandidate) <= 0.45f)
            {
                return probe.TraversalDownstreamConnected;
            }

            probe.TraversalDownstreamConnectivityNextCheckAt = Time.time + 0.35f;
            probe.TraversalDownstreamConnectivityCandidate = candidate;
            StrictPathResult path = CalculateStrictPath(candidate, downstreamTarget);
            float direct = Mathf.Max(0.25f, GetPlanarDistance(candidate, downstreamTarget));
            bool connected = FollowerCapabilityHelperRules.HasTraversalDownstreamConnectivity_connected_F62009CE_1(path.StrictComplete,path.PathLength,direct);
            probe.TraversalDownstreamConnected = connected;
            return connected;
        }

        // CF22: the V430 monotonic body/route chronology already forbids driving an
        // egress target behind a crossed WT. Apply the same existing geometry proof at
        // SUCCESSOR ADMISSION; selecting an obsolete same-chain WT entry can otherwise
        // consume the ExitCommit lifetime without ever yielding to a forward producer.
        // This is only a decision filter: no cursor, body, score or success is written.
        private static bool RejectCf22BackwardWalkThroughSuccessor(
            ProbeRuntime probe, int successorEdgeId, string successorKind,
            Vector3 successorEntry, string source)
        {
            if (probe?.Player == null || !IsActiveProbe(probe) ||
                !string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind,
                    "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(successorKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !IsFinite(successorEntry))
            {
                return false;
            }

            if (!TryGetLearningV430UpstreamConsumerTargetRegression(
                    probe, successorEntry, out float currentProjection,
                    out float targetProjection, out float authoredSpan) ||
                currentProjection < authoredSpan + 0.25f)
            {
                return false;
            }

            if (ShouldEmitDiagnostic(
                    "cf22BackwardWalkThroughSuccessorRejected:" +
                        probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture) + ":" +
                        successorEdgeId.ToString(CultureInfo.InvariantCulture),
                    probe.Bot, 0.25f))
            {
                WriteEvent("cf22BackwardWalkThroughSuccessorRejected", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    successorEdgeId,
                    source = source ?? "unknown",
                    body = Vec(probe.Player.Position),
                    rejectedEntry = Vec(successorEntry),
                    currentProjection,
                    targetProjection,
                    authoredSpan,
                    movementWriterGeneration = probe.MovementWriterGeneration,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "alreadyPassedEntryCannotOwnCurrentPhysicalRoute;searchForwardBreadcrumbOrConsumer"
                });
            }
            return true;
        }

        private static bool TryGetLearningV341ImmediateSemanticSuccessor(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            out FollowerRouteMissionStep successor)
        {
            successor = null;
            if ((probe?.Bot == null) || probe.Player == null ||
                commitment == null || string.IsNullOrEmpty(probe.Bot.ProfileId))
            {
                return false;
            }

            if (commitment.RouteMissionId > 0 &&
                FollowerRouteMissions.TryGetValue(probe.Bot.ProfileId, out FollowerRouteMission mission) &&
                mission != null && mission.MissionId == commitment.RouteMissionId)
            {
                int currentIndex = commitment.RouteMissionStepIndex >= 0
                    ? commitment.RouteMissionStepIndex
                    : mission.CurrentStepIndex;
                if (currentIndex >= 0 && currentIndex + 1 < mission.Steps.Count)
                {
                    FollowerRouteMissionStep current = mission.Steps[currentIndex];
                    FollowerRouteMissionStep next = mission.Steps[currentIndex + 1];
                    if (current != null && next != null && current.EdgeId == commitment.EdgeId &&
                        current.ChainId > 0 && next.ChainId == current.ChainId &&
                        IsLearningV340DownstreamBridgeKind(next.Kind) && IsFinite(next.Entry) &&
                        GetPlanarDistance(probe.Player.Position, next.Entry) <= RouteMissionTraversalAdjacentBridgeMaxDistance &&
                        !RejectCf22BackwardWalkThroughSuccessor(
                            probe, next.EdgeId, next.Kind, next.Entry, "routeMissionImmediateSuccessor"))
                    {
                        successor = next;
                        return true;
                    }
                }
            }

            // V3.41: a fresh same-chain WT/DropDown successor may be deliberately absent from the
            // RouteMission because persistent candidate hygiene keeps the DB edge Disabled until it
            // earns bot proof.  Current-raid player provenance is still authoritative enough to
            // continue the physical route locally; it never enables the edge for global planning.
            if (probe.TraversalEpisodeId <= 0 ||
                !TryGetNextTraversalEpisode(
                    probe.TraversalEpisodeId, out TraversalEpisodeMetadata nextEpisode,
                    out int learningV367SkippedSemanticSuccessors) ||
                nextEpisode == null || nextEpisode.ChainId <= 0 || nextEpisode.ChainId != probe.TraversalChainId)
            {
                return false;
            }
            if ((learningV367SkippedSemanticSuccessors > 0))
            {
                WriteEvent("learningV367NonAdvancingSuccessorEpisodesSkipped", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    currentEpisodeId = probe.TraversalEpisodeId,
                    nextEpisodeId = nextEpisode.EpisodeId,
                    nextEdgeId = nextEpisode.EdgeId,
                    skipped = learningV367SkippedSemanticSuccessors,
                    action = "episodeIdCannotMovePhysicalSuccessorBehindConsumedBreadcrumbFrontier"
                });
            }
            LearnedTraversalEdge nextEdge = LearnedTraversalEdges.FirstOrDefault(item =>
                item != null && item.Id == nextEpisode.EdgeId);
            bool localRuntimeAuthority = nextEdge != null &&
                (HasFreshRaidLocalDropDownAuthority(nextEdge, nextEpisode) ||
                 HasLearningV341FreshRaidLocalSemanticSuccessorAuthority(nextEdge, nextEpisode));
            if (nextEdge == null || (!localRuntimeAuthority && nextEdge.Disabled) ||
                !IsLearningV340DownstreamBridgeKind(nextEdge.Kind))
            {
                return false;
            }
            Vector3 entry = localRuntimeAuthority && IsFinite(nextEpisode.RawStart)
                ? nextEpisode.RawStart
                : (nextEdge.HasSettledStart && IsFinite(nextEdge.SettledStart)
                    ? nextEdge.SettledStart
                    : nextEpisode.Entry);
            if (!IsFinite(entry) ||
                GetPlanarDistance(probe.Player.Position, entry) > RouteMissionTraversalAdjacentBridgeMaxDistance ||
                RejectCf22BackwardWalkThroughSuccessor(
                    probe, nextEdge.Id, nextEdge.Kind, entry, "raidEpisodeImmediateSuccessor"))
            {
                return false;
            }
            successor = new FollowerRouteMissionStep
            {
                EpisodeId = nextEpisode.EpisodeId,
                EdgeId = nextEdge.Id,
                Kind = nextEdge.Kind,
                StartBreadcrumbSequence = nextEpisode.StartBreadcrumbSequence,
                EndBreadcrumbSequence = nextEpisode.EndBreadcrumbSequence,
                ChainId = nextEpisode.ChainId,
                Entry = entry,
                Exit = localRuntimeAuthority && IsFinite(nextEpisode.RawEnd)
                    ? nextEpisode.RawEnd
                    : (nextEdge.HasSettledEnd && IsFinite(nextEdge.SettledEnd) ? nextEdge.SettledEnd : nextEpisode.Exit),
                RawEntry = IsFinite(nextEpisode.RawStart) ? nextEpisode.RawStart : nextEdge.RawStart,
                RawExit = IsFinite(nextEpisode.RawEnd) ? nextEpisode.RawEnd : nextEdge.RawEnd
            };
            WriteEvent("learningV341FreshLocalSemanticSuccessorRecovered", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                nextEdgeId = nextEdge.Id,
                nextKind = nextEdge.Kind,
                nextEpisodeId = nextEpisode.EpisodeId,
                chainId = nextEpisode.ChainId,
                persistentDisabled = nextEdge.Disabled,
                localRuntimeAuthority,
                nextEntry = Vec(entry),
                action = "recoverPlayerAuthoredImmediateSuccessorWithoutGlobalEdgeEnable"
            });
            return true;
        }

        private static bool TryBeginPlayerRouteContinuationBridge(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string reason)
        {
            if (probe == null || commitment == null || !IsActiveProbe(probe))
            {
                return false;
            }
            if(TryCloseCapabilityClimbAtSuccessor(probe,commitment))return true;
            if (probe.IslandExitBridgeAttempts >= TraversalIslandExitBridgeMaxAttempts)
            {
                if (ShouldEmitDiagnostic(
                        "traversalIslandExitBridgeSuppressed:" + probe.LearnedEdgeId,
                        probe.Bot,
                        0.75f))
                {
                    WriteEvent("traversalIslandExitBridgeSuppressed", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        reason,
                        attempts = probe.IslandExitBridgeAttempts,
                        maxAttempts = TraversalIslandExitBridgeMaxAttempts
                    });
                }
                return false;
            }
            if (!TryGetTraversalDownstreamEvidence(
                    probe, commitment, out Vector3 downstreamTarget, out int downstreamSequence, out string downstreamSource))
            {
                return false;
            }

            int episodeId = probe.TraversalEpisodeId > 0 ? probe.TraversalEpisodeId : commitment.EpisodeId;
            TraversalEpisodeMetadata episode = TraversalEpisodeStream
                .LastOrDefault(item => item != null && item.EpisodeId == episodeId);
            if (episode == null)
            {
                return false;
            }

            List<PlayerBreadcrumbNode> routeNodes = BreadcrumbRoute;
            string profileId = probe.Bot?.ProfileId ?? string.Empty;
            FollowerRouteMission routeMission = null;
            if (!string.IsNullOrEmpty(profileId) &&
                FollowerRouteMissions.TryGetValue(profileId, out routeMission) && routeMission != null)
            {
                RefreshRouteMissionBreadcrumbSnapshot(routeMission);
                routeNodes = routeMission.RouteBreadcrumbs;
            }

            bool learningV341OffNavContinuation =
                string.Equals(reason, "climbOffNavMeshUpperLanding", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(reason, "verifyDisconnectedNavIsland", StringComparison.OrdinalIgnoreCase);
            if (learningV341OffNavContinuation &&
                TryGetLearningV341ImmediateSemanticSuccessor(probe, commitment, out FollowerRouteMissionStep learningV341Successor))
            {
                if ((TryFinalizeTraversalChainIntermediate(probe, "learningV351OffNavMeshSemanticSuccessor")))
                {
                    WriteEvent("learningV351OffNavMeshSemanticSuccessorCommitted", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        reason,
                        nextEdgeId = learningV341Successor.EdgeId,
                        nextKind = learningV341Successor.Kind,
                        nextEntry = Vec(learningV341Successor.Entry),
                        body = probe.Player != null ? Vec(probe.Player.Position) : null,
                        action = "atomicRouteCursorAndSuccessorOwnershipCommit"
                    });
                    return true;
                }
                WriteEvent("learningV341OffNavMeshSemanticSuccessorHandoff", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    reason,
                    nextEdgeId = learningV341Successor.EdgeId,
                    nextKind = learningV341Successor.Kind,
                    nextEntry = Vec(learningV341Successor.Entry),
                    body = probe.Player != null ? Vec(probe.Player.Position) : null,
                    action = "closeCurrentPhysicalTransactionAndLetSameChainSemanticSuccessorOwnContinuation"
                });
                FinalizeUnifiedTraversalSuccess(probe, "learningV341OffNavMeshSemanticSuccessorHandoff");
                return true;
            }

            // No grounded breadcrumb bridge may consume the next unexecuted actuator's work.
            if(probe.LifecycleMission!=null&&TryRequestCapabilityFullRouteRetry(probe,"routeContinuationNeedsRecovery:"+reason,true))return true;
            int bridgeLowerSequence = episode.EndBreadcrumbSequence;
            if (routeMission != null)
            {
                int currentIndex = commitment.RouteMissionId == routeMission.MissionId && commitment.RouteMissionStepIndex >= 0
                    ? commitment.RouteMissionStepIndex
                    : routeMission.CurrentStepIndex;
                if (currentIndex >= 0 && currentIndex < routeMission.Steps.Count)
                {
                    FollowerRouteMissionStep currentStep = routeMission.Steps[currentIndex];
                    if (currentStep != null && currentStep.EdgeId == commitment.EdgeId &&
                        currentStep.EndBreadcrumbSequence > bridgeLowerSequence)
                    {
                        bridgeLowerSequence = currentStep.EndBreadcrumbSequence;
                    }
                }
            }

            Vector3 bridgeRawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 bridgeReferenceExit = commitment.HasSettledExit && IsFinite(commitment.SettledExit)
                ? commitment.SettledExit
                : (IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit);
            Vector3 bridgeAxis = GetFlatDirection(bridgeReferenceExit - bridgeRawEntry);
            List<Vector3> points = routeNodes
                .Where(node => node != null &&
                               node.Sequence > bridgeLowerSequence &&
                               node.Sequence <= downstreamSequence &&
                               IsOperationalBreadcrumbNode(node) && IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .Select(node => node.Position)
                .Where(point =>
                {
                    if (bridgeAxis.sqrMagnitude < 0.5f)
                    {
                        return true;
                    }
                    Vector3 fromExit = point - bridgeReferenceExit;
                    fromExit.y = 0f;
                    return Vector3.Dot(fromExit, bridgeAxis) >= 0.15f;
                })
                .ToList();
            // CF56: the V341 breadcrumb filter above keeps only forward-side WT samples.
            // Never reintroduce a *near-exit, backwards-of-authored-exit* raw tail after
            // that filter when this exact live WT already has physical crossing proof.
            // Distant authored turns and other actuator kinds retain their old behavior;
            // without a safe continuation candidate, Verify/Recovery keeps its authority.
            if (string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                probe.LearningV372WalkThroughPhysicalPassageProven &&
                probe.TraversalEpisodeId == episodeId &&
                bridgeAxis.sqrMagnitude >= 0.5f &&
                GetPlanarDistance(bridgeReferenceExit, downstreamTarget) <= 1.80f)
            {
                Vector3 cf56TargetFromExit = downstreamTarget - bridgeReferenceExit;
                cf56TargetFromExit.y = 0f;
                float cf56TargetExitProjection = Vector3.Dot(cf56TargetFromExit, bridgeAxis);
                if (cf56TargetExitProjection < 0.15f)
                {
                    if (ShouldEmitDiagnostic(
                            "cf56WtBackwardIslandTail:" + probe.LearnedEdgeId, probe.Bot, 0.5f))
                    {
                        WriteEvent("cf56ExactWtBackwardIslandTailRejected", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            episodeId,
                            reason,
                            downstreamSequence,
                            downstreamSource,
                            exit = Vec(bridgeReferenceExit),
                            target = Vec(downstreamTarget),
                            targetProjection = cf56TargetExitProjection,
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = "doNotReappendBackwardNearExitBreadcrumbAfterForwardOnlyPassageFilter"
                        });
                    }
                    return false;
                }
            }
            if (points.Count == 0 || GetPlanarDistance(points[points.Count - 1], downstreamTarget) > 0.25f)
            {
                points.Add(downstreamTarget);
            }

            List<Vector3> compact = new List<Vector3>();
            foreach (Vector3 point in points)
            {
                if (!IsFinite(point))
                {
                    continue;
                }
                if (compact.Count == 0 || GetPlanarDistance(compact[compact.Count - 1], point) >= 0.30f)
                {
                    compact.Add(point);
                }
            }
            if (compact.Count == 0)
            {
                return false;
            }

            // V3.20: this function is reached only after Verify has already proven the CURRENT
            // traversal is on a supported/Nav-stable far side with traversal state released. For
            // Jump, do not turn a second PathPartial topology break in the player's continuation
            // into "Jump egress". That conflates two physical skills and previously caused the
            // body to wait ~5 s before CompileFix43 teleported it back to RawExit. Close the Jump
            // transaction, then let V3.19 zero-shot recovery infer the next skill from the live
            // follower PathPartial.
            if ((string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
            {
                Vector3 segmentStart = probe.Player.Position;
                for (int segmentIndex = 0; segmentIndex < compact.Count; segmentIndex++)
                {
                    Vector3 segmentEnd = compact[segmentIndex];
                    if (!IsFinite(segmentEnd))
                    {
                        continue;
                    }
                    if (GetPlanarDistance(segmentStart, segmentEnd) <= 0.20f)
                    {
                        segmentStart = segmentEnd;
                        continue;
                    }

                    StrictPathResult segmentPath = CalculateStrictPath(segmentStart, segmentEnd);
                    if (segmentPath != null && segmentPath.CalculateReturned &&
                        !segmentPath.StrictComplete && segmentPath.Status == NavMeshPathStatus.PathPartial)
                    {
                        probe.LearningV320DownstreamZeroShotHandoffPending = true;
                        probe.LearningV320DownstreamGapFrom = segmentStart;
                        probe.LearningV320DownstreamGapTo = segmentEnd;
                        probe.LearningV320DownstreamGapSegmentIndex = segmentIndex;
                        probe.LearningV320DownstreamGapReason = reason ?? "verifyDisconnectedNavIsland";
                        WriteEvent("learningV320PhysicalFarSideDownstreamGapDetected", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            kind = probe.TraversalKind,
                            reason,
                            segmentIndex,
                            from = Vec(segmentStart),
                            to = Vec(segmentEnd),
                            downstreamTarget = Vec(downstreamTarget),
                            segmentPath = segmentPath.ToPayload(),
                            action = "finishCurrentJumpThenZeroShotNextGap"
                        });
                        FinalizeUnifiedTraversalSuccess(
                            probe,
                            "learningV320PhysicalFarSideDownstreamGapHandoff");
                        return true;
                    }

                    if (segmentPath == null || !segmentPath.StrictComplete)
                    {
                        break;
                    }
                    segmentStart = segmentEnd;
                }
            }

            probe.UnifiedTraversalFlow = true;
            probe.ExclusiveMoverGate = true;
            probe.IslandExitBridgeActive = true;
            LearningV354TraversalCapabilityProfile learningV373IslandProfile =
                GetLearningV354ActionProfile(commitment.Kind);
            bool learningV373PhysicalPassageBridge =
                (learningV373IslandProfile != null) &&
                learningV373IslandProfile.PhysicalPassageCanProveCompletion &&
                learningV373IslandProfile.CanFinishOffNavMesh;
            bool learningV373ClimbDirectBridge =
                string.Equals(commitment.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
            probe.IslandExitDirectDrive =
                learningV373ClimbDirectBridge || learningV373PhysicalPassageBridge;
            probe.LearningV373IslandExitMoverEpochPrepared = false;
            if ((probe.IslandExitDirectDrive))
            {
                probe.LearningV341ForcedEgressPhysicalWriterUsed = true;
                WriteEvent("learningV341ForcedEgressSelfRescueArmed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    reason,
                    position = probe.Player != null ? Vec(probe.Player.Position) : null,
                    downstreamTarget = Vec(downstreamTarget),
                    action = "boundedSelfRescueFallbackNotCleanNative"
                });
            }
            probe.IslandExitNominalClimbTopBridge = learningV373ClimbDirectBridge &&
                (string.Equals(reason, "climbOffNavMeshUpperLanding", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(reason, "verifyDisconnectedNavIsland", StringComparison.OrdinalIgnoreCase));
            probe.IslandExitBridgeAttempts++;
            probe.TraversalEgressAttempted = true;
            probe.TraversalEgressCompleted = false;
            probe.TraversalVerifyTarget = downstreamTarget;
            probe.TraversalEgressSource = "playerRouteContinuation:" + downstreamSource;
            probe.UnifiedEgressPoints.Clear();
            probe.UnifiedEgressPoints.AddRange(compact);
            probe.UnifiedEgressIndex = 0;
            while (probe.UnifiedEgressIndex < probe.UnifiedEgressPoints.Count - 1 &&
                   GetPlanarDistance(probe.Player.Position, probe.UnifiedEgressPoints[probe.UnifiedEgressIndex]) <= 0.35f)
            {
                probe.UnifiedEgressIndex++;
            }
            probe.UnifiedEgressLastPosition = probe.Player.Position;
            probe.UnifiedEgressLastDistance = GetPlanarDistance(probe.Player.Position, downstreamTarget);
            probe.UnifiedEgressLastProgressAt = Time.time;
            probe.UnifiedEgressDeadlineAt = Time.time + Mathf.Clamp(
                probe.UnifiedEgressLastDistance / 0.75f + 2.0f,
                UnifiedTraversalEgressTimeout,
                TraversalIslandExitBridgeMaxSeconds);
            probe.UnifiedEgressTimeoutExtensions = 0;
            probe.UnifiedEgressAuthorityReacquireAttempts = 0;
            probe.UnifiedEgressAuthorityNextAttemptAt = 0f;
            probe.UnifiedEgressAuthorityLeaseUntil = 0f;
            probe.UnifiedEgressAuthorityTarget = Vector3.zero;
            probe.IslandExitNextDirectPointAt = Time.time;
            TransitionProbeStage(probe, ProbeStage.Egress);
            probe.StageStartedAt = Time.time;
            probe.OwnershipLeaseExpiresAt = Mathf.Max(
                probe.OwnershipLeaseExpiresAt,
                probe.UnifiedEgressDeadlineAt + UnifiedTraversalVerifyTimeout + 1.0f);

            try
            {
                probe.Bot.Mover?.BotMoverSprint("R1-128995B9EE22",@probe?.Bot,false,false);
                probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-67FFD490A92F",@probe?.Bot);
                if (probe.IslandExitDirectDrive)
                {
                    // Direct physical continuation owns the body through a disconnected island.
                    // Pause stale BotMover navigation, but do not use it as the continuation producer.
                    if (probe.Bot.Mover != null)
                    {
                        probe.Bot.Mover.SetBotMoverPause("R1-BDFD974ABAD1",@probe?.Bot,true);
                    }
                    // Preserve the historical Climb-top reset, but passage-capable WT/PhysicalCorridor
                    // continues directly on the next frame without a hard StopMove boundary.
                    if (!learningV373PhysicalPassageBridge)
                    {
                        probe.Bot.BotOwnerStopMove("R1-154859F12E48",@probe?.Bot);
                    }
                }
                else if ((probe.Bot.Mover != null))
                {
                    // Navigation-backed continuation is allowed only after its native path origin is
                    // rebased to the current physical body. Do not hard-stop a healthy traversal
                    // transaction merely to clear stale native path bookkeeping.
                    probe.Bot.Mover.SetBotMoverPause("R1-88D5645D06F3",@probe?.Bot,false);
                    probe.LearningV373IslandExitMoverEpochPrepared =
                        TryScrubLearningV364NativeMoverEpochAnchor(
                            probe.Bot,
                            probe.Player.Position,
                            "learningV373IslandExitBridgeStart",
                            out string learningV373BridgeScrubDetail);
                    WriteEvent("learningV373IslandExitMoverEpochPrepared", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        position = Vec(probe.Player.Position),
                        prepared = probe.LearningV373IslandExitMoverEpochPrepared,
                        detail = learningV373BridgeScrubDetail,
                        action = "stateOnlyPathOriginRebasePreservesContinuousTraversalMotion"
                    });
                }
            }
            catch
            {
            }

            // CompileFix33: a Climb top is a legitimate intermediate state, not a failure.
            // Replaying the player's authored top -> downstream tail is part of the nominal Climb
            // executor. Only timeout/retry/recenter bridges should inflate RecoveryCost.
            if (!probe.IslandExitNominalClimbTopBridge)
            {
                RegisterTraversalLocalRecovery(probe, "islandExitBridge:" + (reason ?? "unknown"));
            }
            WriteEvent("traversalIslandExitBridgeStarted", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                reason,
                downstreamSource,
                downstreamSequence,
                downstreamTarget = Vec(downstreamTarget),
                pointCount = compact.Count,
                attempt = probe.IslandExitBridgeAttempts,
                maxAttempts = TraversalIslandExitBridgeMaxAttempts,
                position = Vec(probe.Player.Position),
                directDrive = probe.IslandExitDirectDrive
            });
            return true;
        }

        private static bool TryResolveJumpBridgeLandingTarget(
            ProbeRuntime probe,
            LearnedTraversalEdge edge,
            LearnedTraversalCommitment commitment,
            out Vector3 landing,
            out float crestY,
            out int landingSampleIndex)
        {
            landing = default;
            crestY = 0f;
            landingSampleIndex = -1;
            // Template EgressSamples are world-space demonstration data. They are never a valid
            // landing authority for a V3.19 transient instance at a different location.
            if (IsLearningV319TransientSkillTransfer(commitment))
            {
                return false;
            }
            if (edge == null || commitment == null ||
                !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                edge.EgressSamples == null || edge.EgressSamples.Count < JumpPlatformEgressMinSamples)
            {
                return false;
            }

            // EgressSamples are captured in the demonstrated RawStart -> RawEnd direction. Do not
            // apply that tail to a reverse traversal; a future reverse demonstration gets its own
            // directional geometry.
            bool forward = Vector3.Distance(commitment.RawExit, edge.RawEnd) <=
                           Vector3.Distance(commitment.RawExit, edge.RawStart);
            if (!forward)
            {
                return false;
            }

            crestY = Mathf.Max(commitment.RawEntry.y, commitment.RawExit.y);
            for (int i = 0; i < edge.EgressSamples.Count; i++)
            {
                Vector3 point = edge.EgressSamples[i];
                if (IsFinite(point))
                {
                    crestY = Mathf.Max(crestY, point.y);
                }
            }

            // Prefer the demonstrated stable SettledExit when it is a credible far-side anchor.
            // It is exactly the point at which ordinary NavMesh following may safely resume.
            if (commitment.HasSettledExit && IsFinite(commitment.SettledExit) &&
                IsCredibleSettledExit(commitment.Kind, commitment.RawEntry, commitment.RawExit, commitment.SettledExit) &&
                GetPlanarDistance(commitment.RawExit, commitment.SettledExit) >= JumpPlatformEgressMinPlanarProgress &&
                HasTraversalDownstreamConnectivity(probe, commitment, commitment.SettledExit, out _, out _))
            {
                landing = commitment.SettledExit;
                for (int i = edge.EgressSamples.Count - 1; i >= 0; i--)
                {
                    if (IsFinite(edge.EgressSamples[i]) &&
                        GetPlanarDistance(edge.EgressSamples[i], landing) <= 0.75f)
                    {
                        landingSampleIndex = i;
                        break;
                    }
                }
                return true;
            }

            // Otherwise choose the LAST grounded + NavMesh-backed semantic point after the crest.
            // Choosing the first grounded point is unsafe: obstacle tops and sloped junk can report
            // grounded even though they are only transient support and ordinary Follow has no useful
            // path there.
            int crestIndex = 0;
            float bestCrestY = float.MinValue;
            for (int i = 0; i < edge.EgressSamples.Count; i++)
            {
                Vector3 point = edge.EgressSamples[i];
                if (IsFinite(point) && point.y > bestCrestY)
                {
                    bestCrestY = point.y;
                    crestIndex = i;
                }
            }

            if (edge.EgressSemanticSamples != null)
            {
                int count = Math.Min(edge.EgressSamples.Count, edge.EgressSemanticSamples.Count);
                for (int i = count - 1; i > crestIndex; i--)
                {
                    TraversalEgressSemanticSample semantic = edge.EgressSemanticSamples[i];
                    Vector3 point = edge.EgressSamples[i];
                    if (semantic == null || !semantic.Grounded || !semantic.NavMeshSampled ||
                        !IsFinite(point) || !IsFinite(semantic.NavMeshPosition) ||
                        Mathf.Abs(point.y - semantic.NavMeshPosition.y) > JumpBridgeStableNavVertical ||
                        GetPlanarDistance(point, commitment.RawExit) < 0.90f)
                    {
                        continue;
                    }

                    Vector3 forwardDirection = GetFlatDirection(commitment.RawExit - commitment.RawEntry);
                    Vector3 continuation = point - commitment.RawExit;
                    continuation.y = 0f;
                    if (forwardDirection.sqrMagnitude > 0.5f && continuation.sqrMagnitude > 0.01f &&
                        Vector3.Dot(forwardDirection, continuation.normalized) < 0.15f)
                    {
                        continue;
                    }

                    if (!HasTraversalDownstreamConnectivity(probe, commitment, point, out _, out _))
                    {
                        continue;
                    }
                    landing = point;
                    landingSampleIndex = i;
                    return true;
                }
            }

            return false;
        }

        private static bool IsLearningV340DownstreamBridgeKind(string kind)
        {
            ;

            // V3.40: every authored physical traversal can terminate on a transient/off-NavMesh
            // support. Vault and WalkThrough were the two legacy omissions. They must consume the
            // same player-demonstrated continuation/next traversal before ordinary Follow owns the
            // body, rather than treating mere support as a terminal navigation truth.
            return string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase);
        }

        private static bool TryResolveUnifiedTraversalEgressTarget(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            out Vector3 target,
            out string source)
        {
            target = default;
            source = string.Empty;
            if (probe == null || commitment == null)
            {
                return false;
            }

            if(TryResolveCapabilityWalkThroughEgress(probe,commitment,out target,out source))return true;
            bool requiresDownstreamBridge = IsLearningV340DownstreamBridgeKind(commitment.Kind);
            bool demonstratedEgressTailKind =
                FollowerCapabilityHelperRules.TryResolveUnifiedTraversalEgressTarget_demonstratedEgressTailKind_BDA22C82_1(commitment.Kind,commitment.Kind,commitment.Kind);

            if (commitment.HasSettledExit && IsFinite(commitment.SettledExit) &&
                IsCredibleSettledExit(commitment.Kind, commitment.RawEntry, commitment.RawExit, commitment.SettledExit) &&
                (!requiresDownstreamBridge || HasTraversalDownstreamConnectivity(
                    probe, commitment, commitment.SettledExit, out _, out _)))
            {
                target = commitment.SettledExit;
                source = "settledExit";
                return true;
            }

            // R8.7 Off-NavMesh bridge: Jump and Climb may finish their native/animation phase on
            // transient support that has no useful NavMesh. Prefer the LAST grounded + NavMesh-backed
            // point from this exact demonstration. Falling back to RawExit here would make Climb
            // replay the recorded tail and then U-turn back onto the obstacle top.
            if (demonstratedEgressTailKind)
            {
                LearnedTraversalEdge bridgeEdge = IsLearningV319TransientSkillTransfer(commitment)
                    ? null
                    : LearnedTraversalEdges.FirstOrDefault(
                        candidate => candidate != null && candidate.Id == commitment.EdgeId);
                if (bridgeEdge?.EgressSamples != null && bridgeEdge.EgressSamples.Count >= JumpPlatformEgressMinSamples)
                {
                    Vector3 bridgeDirection = GetFlatDirection(commitment.RawExit - commitment.RawEntry);
                    if (bridgeEdge.EgressSemanticSamples != null)
                    {
                        int semanticCount = Math.Min(bridgeEdge.EgressSamples.Count, bridgeEdge.EgressSemanticSamples.Count);
                        for (int i = semanticCount - 1; i >= 0; i--)
                        {
                            TraversalEgressSemanticSample semantic = bridgeEdge.EgressSemanticSamples[i];
                            Vector3 point = bridgeEdge.EgressSamples[i];
                            if (semantic == null || !semantic.Grounded || !semantic.NavMeshSampled ||
                                !IsFinite(point) || !IsFinite(semantic.NavMeshPosition) ||
                                Mathf.Abs(point.y - semantic.NavMeshPosition.y) > JumpBridgeStableNavVertical ||
                                GetPlanarDistance(point, commitment.RawExit) < JumpPlatformEgressMinPlanarProgress)
                            {
                                continue;
                            }

                            Vector3 continuation = point - commitment.RawExit;
                            continuation.y = 0f;
                            if (bridgeDirection.sqrMagnitude > 0.5f && continuation.sqrMagnitude > 0.01f &&
                                Vector3.Dot(bridgeDirection, continuation.normalized) < 0.10f)
                            {
                                continue;
                            }

                            // R8.12.2: this point is authored by the player's same demonstration.
                            // Requiring ordinary downstream NavMesh connectivity here skips the exact
                            // semantic tail we are trying to replay on isolated platforms. Connectivity
                            // is validated only after the demonstrated tail has been consumed.
                            target = semantic.NavMeshSampled && IsFinite(semantic.NavMeshPosition)
                                ? semantic.NavMeshPosition
                                : point;
                            source = string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase)
                                ? "jumpDemonstratedSemanticTail"
                                : "climbDemonstratedSemanticTail";
                            return true;
                        }
                    }

                    Vector3 tail = bridgeEdge.EgressSamples.LastOrDefault(IsFinite);
                    if (IsFinite(tail) &&
                        GetPlanarDistance(tail, commitment.RawExit) >= JumpPlatformEgressMinPlanarProgress)
                    {
                        Vector3 continuation = tail - commitment.RawExit;
                        continuation.y = 0f;
                        if (bridgeDirection.sqrMagnitude < 0.5f || continuation.sqrMagnitude < 0.01f ||
                            Vector3.Dot(bridgeDirection, continuation.normalized) >= 0.10f)
                        {
                            target = tail;
                            source = string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase)
                                ? "jumpDemonstratedEgressTail"
                                : "climbDemonstratedEgressTail";
                            return true;
                        }
                    }
                }
            }

            // V1.3.22 provenance rule: never scan the global breadcrumb history to invent an exit
            // for a traversal whose own demonstration did not capture one. That could select a
            // breadcrumb from seconds earlier, from the wrong side, or from another WalkThrough.
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            if (TrySampleTraversalSettledAnchor(rawExit, TraversalSettledCaptureNavRadius, out Vector3 rawExitNav))
            {
                target = rawExitNav;
                source = "rawExitNav";
                return true;
            }

            target = rawExit;
            source = "rawExitAuthored";
            return IsFinite(target);
        }

        private static bool IsVaultClimbFarSideForEgress(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            out float projection,
            out float requiredProjection)
        {
            projection = 0f;
            requiredProjection = 0f;
            if (probe?.Player == null || commitment == null)
            {
                return false;
            }

            bool gatedKind =
                string.Equals(commitment.Kind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(commitment.Kind, "Climb", StringComparison.OrdinalIgnoreCase);
            if (!gatedKind)
            {
                return true;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            float length = axis.magnitude;
            if (length < 0.30f)
            {
                return GetPlanarDistance(probe.Player.Position, rawExit) <= VaultClimbFarSideNearExitTolerance;
            }

            Vector3 direction = axis / length;
            Vector3 fromEntry = probe.Player.Position - rawEntry;
            fromEntry.y = 0f;
            projection = Vector3.Dot(fromEntry, direction);
            requiredProjection = Mathf.Max(0.12f, length - VaultClimbFarSideEgressSlack);
            bool crossedPlane = projection >= requiredProjection;
            bool nearExit =
                GetPlanarDistance(probe.Player.Position, rawExit) <= VaultClimbFarSideNearExitTolerance &&
                Mathf.Abs(probe.Player.Position.y - rawExit.y) <= 1.10f;

            // CF37: An elevated, same-chain successor cannot consume the Climb while the
            // actual body is only near the upper exit but has NOT crossed its directed plane.
            // Otherwise the successor (e.g. an upper-layer DropDown) takes ownership while
            // the body is still falling beside the obstacle. A new retry of that successor
            // cannot restore the elevation of the already-retired Climb.
            // This is a physical-plane gate, not a timer, teleporter or artificial success.
            bool cf37ElevatedSuccessor = false;
            FollowerRouteMissionStep cf37Next = null;
            if (string.Equals(commitment.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                probe.Bot != null && !string.IsNullOrEmpty(probe.Bot.ProfileId) &&
                commitment.RouteMissionId > 0 &&
                FollowerRouteMissions.TryGetValue(probe.Bot.ProfileId, out FollowerRouteMission cf37Mission) &&
                cf37Mission != null && cf37Mission.MissionId == commitment.RouteMissionId &&
                cf37Mission.Steps != null)
            {
                int cf37Index = commitment.RouteMissionStepIndex >= 0
                    ? commitment.RouteMissionStepIndex : cf37Mission.CurrentStepIndex;
                if (cf37Index >= 0 && cf37Index + 1 < cf37Mission.Steps.Count)
                {
                    FollowerRouteMissionStep cf37Current = cf37Mission.Steps[cf37Index];
                    cf37Next = cf37Mission.Steps[cf37Index + 1];
                    Vector3 cf37NextEntry = cf37Next != null && IsFinite(cf37Next.RawEntry)
                        ? cf37Next.RawEntry : (cf37Next != null ? cf37Next.Entry : Vector3.zero);
                    cf37ElevatedSuccessor =
                        cf37Current != null && cf37Next != null &&
                        cf37Current.EdgeId == commitment.EdgeId &&
                        cf37Current.EpisodeId == probe.TraversalEpisodeId &&
                        cf37Current.ChainId > 0 && cf37Current.ChainId == cf37Next.ChainId &&
                        IsFinite(cf37NextEntry) &&
                        cf37NextEntry.y - rawEntry.y > UnifiedTraversalVerifyMaxNavVertical;
                }
            }
            if (cf37ElevatedSuccessor && !crossedPlane)
            {
                if (ShouldEmitDiagnostic(
                        "cf37ElevatedSuccessorClimbPlaneNotCrossed:" +
                            probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture),
                        probe.Bot, 0.35f))
                {
                    WriteEvent("cf37ElevatedSuccessorClimbPlaneNotCrossed", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        kind = commitment.Kind,
                        successorEdgeId = cf37Next.EdgeId,
                        successorKind = cf37Next.Kind,
                        missionId = commitment.RouteMissionId,
                        current = Vec(probe.Player.Position),
                        rawEntry = Vec(rawEntry),
                        rawExit = Vec(rawExit),
                        successorEntry = Vec(IsFinite(cf37Next.RawEntry) ? cf37Next.RawEntry : cf37Next.Entry),
                        projection,
                        requiredProjection,
                        nearExit,
                        nativeSuccessGranted = false,
                        traversalSuccessRecorded = false,
                        bodyRelocated = false,
                        persistentLearningChanged = false,
                        action = "retainCurrentClimbActuatorAndPhysicalRecoveryBeforeUpperSuccessorHandoff"
                    });
                }
                return false;
            }
            return crossedPlane || nearExit;
        }

        private static bool TryRecoverVaultClimbCrossingBeforeEgress(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string source,
            float projection,
            float requiredProjection)
        {
            if(probe?.LifecycleMission!=null&&TryRequestCapabilityFullRouteRetry(probe,"nativeVaultClimbNearSide:"+source,true))return true;
            if (probe == null || commitment == null ||
                probe.VaultClimbCrossingRecoveryAttempts >= VaultClimbCrossingRecoveryMaxAttempts)
            {
                return false;
            }

            probe.VaultClimbCrossingRecoveryAttempts++;
            string recoveryFailure = string.Empty;
            bool started = false;
            bool previousStageWasAssisted = !string.IsNullOrEmpty(source) &&
                source.IndexOf("assisted", StringComparison.OrdinalIgnoreCase) >= 0;

            bool vaultKind = string.Equals(commitment.Kind, "Vault", StringComparison.OrdinalIgnoreCase);
            float authoredLength = Mathf.Max(0.25f, GetPlanarDistance(commitment.RawEntry, commitment.RawExit));
            float progressRatio = projection / authoredLength;

            // CompileFix35: PartialNative is only semantic if the body already crossed a meaningful
            // fraction of the Vault. Fix34 admitted ~9% progress on edge154, then launched another
            // timeline-assisted controller and immediately diverged again.
            if (probe.NativeStateObserved && (!vaultKind || progressRatio >= VaultPartialNativeMinimumProgressRatio))
            {
                started = TryBeginPartialNativeVaultCompletion(
                    probe,
                    commitment,
                    "farSideGate:" + (source ?? "unknown"),
                    out recoveryFailure);
            }

            // A failed Vault assisted stage must escalate to a genuinely different spatial executor.
            if (!started && vaultKind)
            {
                started = TryBeginControlledVaultCrossingBridge(
                    probe,
                    commitment,
                    "farSideGate:" + (source ?? "unknown"),
                    out string controlledFailure);
                if (!started && !string.IsNullOrEmpty(controlledFailure))
                {
                    recoveryFailure = string.IsNullOrEmpty(recoveryFailure)
                        ? controlledFailure
                        : recoveryFailure + "; " + controlledFailure;
                }
            }

            if (!started && !vaultKind && !previousStageWasAssisted && !probe.AssistedReplayAttempted)
            {
                RestoreAssistedObstacleCollisionLease(probe, "farSideGateRecoveryReset");
                probe.AssistedReplayTerminalized = false;
                probe.AssistedCollisionRecoveryAttempted = false;
                probe.AssistedDivergenceSince = -1f;
                probe.SafetyHoldReason = null;
                probe.NextSafetyRecoveryAttemptAt = 0f;

                started = TryBeginAssistedVaultReplayV2(
                    probe,
                    commitment,
                    "farSideGateRecovery:" + (source ?? "unknown"),
                    out recoveryFailure);
            }
            else if (!started && previousStageWasAssisted)
            {
                recoveryFailure = string.IsNullOrEmpty(recoveryFailure)
                    ? "assisted stage already failed; monotonic recovery forbids replay"
                    : recoveryFailure + "; assisted stage already failed; monotonic recovery forbids replay";
            }

            WriteEvent(started ? "vaultClimbCrossingRecoveryStarted" : "vaultClimbCrossingRecoveryRejected", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                kind = commitment.Kind,
                source = source ?? "unknown",
                attempt = probe.VaultClimbCrossingRecoveryAttempts,
                projection,
                requiredProjection,
                progressRatio,
                position = Vec(probe.Player.Position),
                rawEntry = Vec(commitment.RawEntry),
                rawExit = Vec(commitment.RawExit),
                failure = recoveryFailure ?? string.Empty
            });
            return started;
        }

        private static bool TryReturnLearningV383PartialActuatorToPhysicalPassage(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            string source,
            float actuatorProjection,
            float actuatorRequiredProjection)
        {
            if ((probe?.Bot == null) ||
                probe.Player == null || commitment == null || !probe.InjectedNativeVaultAttempted ||
                !TryGetActiveFollowerRouteMission(probe.Bot, out FollowerRouteMission mission) ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep actuatorStep = mission.Steps[mission.CurrentStepIndex];
            if (actuatorStep == null || actuatorStep.LearningV383PortalPhysicalSourceEdgeId <= 0 ||
                actuatorStep.EpisodeId != commitment.EpisodeId ||
                (commitment.RouteMissionId > 0 && commitment.RouteMissionId != mission.MissionId))
            {
                return false;
            }

            LearnedTraversalEdge physicalEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == actuatorStep.LearningV383PortalPhysicalSourceEdgeId);
            if (physicalEdge == null ||
                !string.Equals(
                    GetLearningV354SemanticKind(physicalEdge.Id, physicalEdge.Kind),
                    "PhysicalCorridor",
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 physicalRawEntry = IsFinite(actuatorStep.LearningV383PortalPhysicalRawEntry)
                ? actuatorStep.LearningV383PortalPhysicalRawEntry
                : physicalEdge.RawStart;
            Vector3 physicalRawExit = IsFinite(actuatorStep.LearningV383PortalPhysicalRawExit)
                ? actuatorStep.LearningV383PortalPhysicalRawExit
                : physicalEdge.RawEnd;
            Vector3 physicalDirection = GetFlatDirection(physicalRawExit - physicalRawEntry);
            if (!IsFinite(physicalRawEntry) || !IsFinite(physicalRawExit) || physicalDirection.sqrMagnitude < 0.5f)
            {
                return false;
            }

            Vector3 currentOffset = probe.Player.Position - physicalRawEntry;
            currentOffset.y = 0f;
            Vector3 startOffset = probe.StartPosition - physicalRawEntry;
            startOffset.y = 0f;
            float currentProjection = Vector3.Dot(currentOffset, physicalDirection);
            float startProjection = Vector3.Dot(startOffset, physicalDirection);
            float currentCorridorLateral = GetPlanarDistanceToSegment(
                probe.Player.Position, physicalRawEntry, physicalRawExit);
            if (currentProjection < startProjection + LearningV354RouteDirectionalProgressEpsilon ||
                currentCorridorLateral > RouteMissionDirectionalWalkThroughMaxLateral)
            {
                return false;
            }

            FollowerRouteMissionStep continuation = new FollowerRouteMissionStep
            {
                EpisodeId = actuatorStep.EpisodeId,
                EdgeId = physicalEdge.Id,
                Kind = "PhysicalCorridor",
                StartBreadcrumbSequence = actuatorStep.StartBreadcrumbSequence,
                EndBreadcrumbSequence = actuatorStep.EndBreadcrumbSequence,
                Entry = IsFinite(actuatorStep.LearningV383PortalPhysicalEntry)
                    ? actuatorStep.LearningV383PortalPhysicalEntry : physicalRawEntry,
                Exit = IsFinite(actuatorStep.LearningV383PortalPhysicalExit)
                    ? actuatorStep.LearningV383PortalPhysicalExit : physicalRawExit,
                RawEntry = physicalRawEntry,
                RawExit = physicalRawExit,
                ChainId = actuatorStep.ChainId,
                ChainLocalExecutable = true,
                CurrentRaidRouteAuthority = true,
                LearningV383PortalPhysicalSourceEdgeId = physicalEdge.Id,
                LearningV383PortalPhysicalEntry = actuatorStep.LearningV383PortalPhysicalEntry,
                LearningV383PortalPhysicalExit = actuatorStep.LearningV383PortalPhysicalExit,
                LearningV383PortalPhysicalRawEntry = physicalRawEntry,
                LearningV383PortalPhysicalRawExit = physicalRawExit,
                LearningV383PhysicalContinuationOnly = true,
                LearningV384ActuatorFallbackArmed = false,
                LearningV384ActuatorFallbackAttempts = actuatorStep.LearningV384ActuatorFallbackAttempts,
                CreatedAt = actuatorStep.CreatedAt
            };
            if (!ReplaceLifecycleMissionStep(mission,mission.CurrentStepIndex,continuation)) return false;
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;

            string profileId = probe.Bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId))
            {
                LearnedTraversalCommitments.Remove(profileId);
            }
            ReturnLearningV375ActuatorBodyAuthority(probe, "learningV383PartialActuatorPhysicalContinuation");
            const string learningV383PartialReason = "learningV383NativeActuatorPartialReturnedToPhysicalPassage";
            if (IsLearningV319TransientSkillTransfer(commitment))
            {
                RecordLearningV322ZeroShotTemplateEvidence(
                    probe, commitment, false, TraversalCompletionMode.Native, learningV383PartialReason);
            }
            else
            {
                LearnedTraversalEdge actuatorEvidenceEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == probe.LearnedEdgeId);
                RecordLearningV322PersistentSkillEvidence(
                    probe, actuatorEvidenceEdge, false, TraversalCompletionMode.Native, learningV383PartialReason);
            }
            EmitLearningV322TraversalAttemptSummary(
                probe,
                false,
                TraversalCompletionMode.Native,
                learningV383PartialReason,
                probe.LearnedEdgeId);
            RestoreProbeInput(probe);
            try
            {
                if (probe.Bot.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-9CA46A4DE5BD",@probe?.Bot,false);
                }
            }
            catch
            {
            }
            RestoreAssistedObstacleCollisionLease(probe, "learningV383PartialActuatorPhysicalContinuation");
            RestoreAssistedTraversalAnimation(probe);
            WriteEvent("learningV383NativeActuatorPartialReturnedToPhysicalPassage", probe.Bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                episodeId = continuation.EpisodeId,
                actuatorEdgeId = probe.LearnedEdgeId,
                actuatorKind = commitment.Kind,
                physicalEdgeId = continuation.EdgeId,
                physicalRawEntry = Vec(physicalRawEntry),
                physicalRawExit = Vec(physicalRawExit),
                startProjection,
                currentProjection,
                currentCorridorLateral,
                maxCorridorLateral = RouteMissionDirectionalWalkThroughMaxLateral,
                actuatorProjection,
                actuatorRequiredProjection,
                traversalSuccessRecorded = false,
                persistentTraversalGeometryChanged = false,
                actuatorSkillEvidenceUpdated = true,
                actuatorTemplateSuccessRecorded = false,
                action = "nativeActuatorMadeRealForwardProgressButDidNotOwnWholePortalReturnRemainingPassageToCurrentEpisodePhysicalProducer"
            });
            DetachProbeStateHandler(probe);
            UnregisterActiveProbe(probe);
            UpdateLearningV375PersistentExecutablePhysicalRouteTransaction(probe.Bot);
            return true;
        }

        private static void BeginUnifiedTraversalEgressOrVerify(ProbeRuntime probe, string source)
