                    float departureDistance = Mathf.Min(0.70f, bridgePlanar * 0.35f);
                    float descentDistance = Mathf.Min(1.35f, bridgePlanar * 0.70f);
                    Vector3 departure = current + bridgeDirection * departureDistance;
                    departure.y = Mathf.Max(current.y, commitment.RawExit.y);
                    Vector3 descent = current + bridgeDirection * descentDistance;
                    descent.y = Mathf.Lerp(departure.y, target.y, 0.58f);
                    probe.UnifiedEgressPoints.Add(departure);
                    if (GetPlanarDistance(departure, descent) >= 0.12f)
                    {
                        probe.UnifiedEgressPoints.Add(descent);
                    }
                    probe.UnifiedEgressPoints.Add(target);
                }
            }

            float planarDistance = GetPlanarDistance(probe.Player.Position, target);
            float directDistance = Vector3.Distance(probe.Player.Position, target);
            float authoredEgressDistance = planarDistance;
            if (probe.UnifiedEgressPoints.Count > 0)
            {
                Vector3 cursor = probe.Player.Position;
                authoredEgressDistance = 0f;
                for (int index = probe.UnifiedEgressIndex; index < probe.UnifiedEgressPoints.Count; index++)
                {
                    authoredEgressDistance += GetPlanarDistance(cursor, probe.UnifiedEgressPoints[index]);
                    cursor = probe.UnifiedEgressPoints[index];
                }
            }
            float egressTimeout = UnifiedTraversalEgressTimeout;
            if (forwardRecordedEgressTail || synthesizedClimbBridge)
            {
                egressTimeout = Mathf.Clamp(
                    authoredEgressDistance / Mathf.Max(0.50f, UnifiedTraversalEgressSpeed) + 0.85f,
                    UnifiedTraversalEgressTimeout,
                    5.25f);
            }
            else if (probe.NativeRunOutActive)
            {
                egressTimeout = Mathf.Clamp(
                    authoredEgressDistance / Mathf.Max(0.50f, UnifiedTraversalEgressSpeed) + NativeTraversalRunOutTimeoutPadding,
                    UnifiedTraversalEgressTimeout,
                    4.25f);
            }
            probe.UnifiedEgressDeadlineAt = Time.time + egressTimeout;
            probe.OwnershipLeaseExpiresAt = Mathf.Max(
                probe.OwnershipLeaseExpiresAt,
                probe.UnifiedEgressDeadlineAt + UnifiedTraversalVerifyTimeout + 1.0f);
            probe.UnifiedEgressLastPosition = probe.Player.Position;
            probe.UnifiedEgressLastDistance = GetPlanarDistance(probe.Player.Position, target);
            probe.UnifiedEgressLastProgressAt = Time.time;
            probe.UnifiedEgressTimeoutExtensions = 0;

            float completionDistance = string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase)
                ? WalkThroughNearExitVerifyDistance
                : UnifiedTraversalEgressCompletionDistance;
            bool recordedTailPending = forwardRecordedEgressTail &&
                probe.UnifiedEgressPoints.Count > 0 &&
                (probe.UnifiedEgressIndex < probe.UnifiedEgressPoints.Count - 1 ||
                 GetPlanarDistance(probe.Player.Position, probe.UnifiedEgressPoints[probe.UnifiedEgressIndex]) > completionDistance);

            WriteEvent("traversalEgressSelected", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                source,
                targetSource,
                current = Vec(probe.Player.Position),
                target = Vec(target),
                planarDistance,
                directDistance,
                authoredEgressDistance,
                egressSampleCount = probe.UnifiedEgressPoints.Count,
                recordedTailPending,
                egressTimeout,
                hasSettledExit = commitment.HasSettledExit
            });
            if (planarDistance > completionDistance || recordedTailPending)
            {
                probe.TraversalEgressAttempted = true;
                probe.TraversalEgressCompleted = false;
                probe.TraversalEgressTimedOut = false;
                TransitionProbeStage(probe, ProbeStage.Egress);
                probe.StageStartedAt = Time.time;
                if (forwardRecordedEgressTail || synthesizedClimbBridge)
                {
                    WriteEvent("traversalBridgeEgressStarted", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        bridgeSource = forwardRecordedEgressTail ? "recorded" : "synthesizedClimbFallback",
                        sampleCount = probe.UnifiedEgressPoints.Count,
                        target = Vec(target),
                        authoredEgressDistance,
                        egressTimeout
                    });
                }
                return;
            }

            probe.TraversalEgressCompleted = true;
            if (!TryFinalizeTraversalChainIntermediate(probe, source + ":egressAlreadyReached"))
            {
                BeginUnifiedTraversalVerify(probe, source + ":egressAlreadyReached");
            }
        }

        private static bool TryGetLearningV430UpstreamConsumerTargetRegression(
            ProbeRuntime probe,
            Vector3 candidateTarget,
            out float currentProjection,
            out float targetProjection,
            out float authoredSpan)
        {
            currentProjection = 0f;
            targetProjection = 0f;
            authoredSpan = 0f;
            if ((probe?.Player == null) || !IsFinite(candidateTarget) ||
                !TryGetLearnedCommitmentForProbe(
                    probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return false;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            authoredSpan = axis.magnitude;
            if (!IsFinite(rawEntry) || !IsFinite(rawExit) || authoredSpan < 0.25f)
            {
                return false;
            }

            Vector3 direction = axis / authoredSpan;
            Vector3 bodyDelta = probe.Player.Position - rawEntry;
            bodyDelta.y = 0f;
            Vector3 targetDelta = candidateTarget - rawEntry;
            targetDelta.y = 0f;
            currentProjection = Vector3.Dot(bodyDelta, direction);
            targetProjection = Vector3.Dot(targetDelta, direction);

            bool crossedFarSide =
                FollowerCapabilityHelperRules.TryGetLearningV430UpstreamConsumerTargetRegression_crossedFarSide_D541078B_1(currentProjection,authoredSpan) ||
                (string.Equals(commitment.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) &&
                 probe.LearningV33PassageBoundaryState >= LearningV33PassageBoundaryState.CrossingCommitted);
            bool strictWalkThroughPhysicalChronology =
                (string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)) &&
                probe.LearningV372WalkThroughPhysicalPassageProven;
            if (strictWalkThroughPhysicalChronology)
            {
                return targetProjection + LearningV32EntryProgressEpsilon < currentProjection;
            }
            return crossedFarSide && targetProjection < currentProjection - 0.25f;
        }

        private static bool TryReacquireUnifiedTraversalEgressAuthority(
            ProbeRuntime probe,
            Vector3 requestedTarget,
            float finalDistance,
            string source)
        {
            if (probe?.Bot?.Mover == null || probe.Player == null ||
                finalDistance > UnifiedTraversalEgressAuthorityMaxDistance ||
                probe.UnifiedEgressAuthorityReacquireAttempts >= UnifiedTraversalEgressAuthorityMaxAttempts ||
                Time.time < probe.UnifiedEgressAuthorityNextAttemptAt)
            {
                return false;
            }

            if (TryGetLearningV430UpstreamConsumerTargetRegression(
                    probe, requestedTarget,
                    out float learningV430CurrentProjection,
                    out float learningV430TargetProjection,
                    out float learningV430AuthoredSpan))
            {
                if ((probe.LearningV372WalkThroughPhysicalPassageProven) &&
                    string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
                {
                    RecordLearningV433PhysicalChronologyEvidence(
                        probe.LearnedEdgeId, "monotonicWalkThroughConsumerRetired", source);
                    WriteEvent("learningV433MonotonicWalkThroughConsumerRetired", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        source = source ?? "unknown",
                        position = Vec(probe.Player.Position),
                        requestedTarget = Vec(requestedTarget),
                        currentProjection = learningV430CurrentProjection,
                        targetProjection = learningV430TargetProjection,
                        authoredSpan = learningV430AuthoredSpan,
                        numericalEnvelope = LearningV32EntryProgressEpsilon,
                        bodyRelocated = false,
                        action = "physicallyProvenWalkThroughMayNeverInstallDownstreamTargetBehindCurrentBody"
                    });
                }
                WriteEvent("learningV430UpstreamEgressAuthorityReacquireRejected", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    requestedTarget = Vec(requestedTarget),
                    position = Vec(probe.Player.Position),
                    currentProjection = learningV430CurrentProjection,
                    targetProjection = learningV430TargetProjection,
                    authoredSpan = learningV430AuthoredSpan,
                    authorityReacquireAttempts = probe.UnifiedEgressAuthorityReacquireAttempts,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "neverInstallMoverTargetBehindConsumedPhysicalFrontier"
                });
                return false;
            }

            // Do not fight a legitimate landing/transition animation immediately after crossing.
            // If the body is still stuck in that state after ~1.1 s the helper is allowed to take
            // over, which preserves the recovery path for genuinely stale Transition states.
            bool bodyTransitionActive = probe.Player.CurrentStateName == EPlayerState.Transition ||
                                        IsProbeTraversalState(probe.Player.CurrentStateName);
            if (bodyTransitionActive && Time.time - probe.StageStartedAt < 1.10f)
            {
                return false;
            }

            probe.UnifiedEgressAuthorityReacquireAttempts++;
            probe.UnifiedEgressAuthorityNextAttemptAt = Time.time + UnifiedTraversalEgressAuthorityRetrySeconds;

            Vector3 candidateTarget = requestedTarget;
            string targetVariant = "exact";
            Vector3 towardTarget = GetFlatDirection(requestedTarget - probe.Player.Position);
            Vector3 perpendicular = towardTarget.sqrMagnitude > 0.5f
                ? new Vector3(-towardTarget.z, 0f, towardTarget.x)
                : Vector3.zero;
            switch (probe.UnifiedEgressAuthorityReacquireAttempts)
            {
                case 2:
                    if (perpendicular.sqrMagnitude > 0.5f)
                    {
                        candidateTarget += perpendicular * UnifiedTraversalEgressAuthorityFanOffset;
                        targetVariant = "fanLeft";
                    }
                    break;
                case 3:
                    if (perpendicular.sqrMagnitude > 0.5f)
                    {
                        candidateTarget -= perpendicular * UnifiedTraversalEgressAuthorityFanOffset;
                        targetVariant = "fanRight";
                    }
                    break;
                case 4:
                    if (towardTarget.sqrMagnitude > 0.5f)
                    {
                        candidateTarget -= towardTarget * UnifiedTraversalEgressAuthorityBackoff;
                        targetVariant = "nearSideBackoff";
                    }
                    break;
            }

            Vector3 moverTarget = candidateTarget;
            bool navSampled = NavMesh.SamplePosition(
                candidateTarget,
                out NavMeshHit navHit,
                UnifiedTraversalEgressAuthorityNavRadius,
                NavMesh.AllAreas);
            float navVertical = navSampled ? Mathf.Abs(navHit.position.y - candidateTarget.y) : float.MaxValue;
            if (navSampled && navVertical <= UnifiedTraversalEgressAuthorityMaxVertical)
            {
                moverTarget = navHit.position;
            }
            else
            {
                navSampled = false;
            }

            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-2487ADB723B7",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverSprint("R1-6FEA74745494",@probe?.Bot,false,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-36B89B1E7C95",@probe?.Bot);
                {
                    if (!TryScrubLearningV364NativeMoverEpochAnchor(
                            probe.Bot,
                            probe.Player.Position,
                            "learningV373EgressAuthorityReacquire",
                            out string learningV373EgressScrubDetail))
                    {
                        WriteEvent("learningV373EgressAuthorityReacquireEpochRejected", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            kind = probe.TraversalKind,
                            source = source ?? "unknown",
                            position = Vec(probe.Player.Position),
                            requestedTarget = Vec(requestedTarget),
                            detail = learningV373EgressScrubDetail,
                            action = "retainPhysicalTraversalAuthorityInsteadOfHardStopOnStaleMoverEpoch"
                        });
                        return false;
                    }
                }
                probe.Bot.Mover.BotMoverGoToPointNoWay("R1-4C8DBAB2D88C",@probe?.Bot,moverTarget);
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-B2FBCE3C1814",@probe?.Bot,0.72f);
                probe.UnifiedEgressAuthorityLeaseUntil = Time.time + UnifiedTraversalEgressAuthorityLeaseSeconds;
                probe.UnifiedEgressAuthorityTarget = moverTarget;
                probe.OwnershipLeaseExpiresAt = Mathf.Max(
                    probe.OwnershipLeaseExpiresAt,
                    probe.UnifiedEgressAuthorityLeaseUntil + UnifiedTraversalVerifyTimeout + 0.5f);
                WriteEvent("traversalEgressAuthorityReacquired", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    attempt = probe.UnifiedEgressAuthorityReacquireAttempts,
                    requestedTarget = Vec(requestedTarget),
                    candidateTarget = Vec(candidateTarget),
                    moverTarget = Vec(moverTarget),
                    targetVariant,
                    finalDistance,
                    navSampled,
                    navVertical
                });
                return true;
            }
            catch (Exception ex)
            {
                WriteEvent("traversalEgressAuthorityReacquireFailed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    attempt = probe.UnifiedEgressAuthorityReacquireAttempts,
                    finalDistance,
                    error = ex.GetType().Name + ": " + ex.Message
                });
                return false;
            }
        }

        private static void UpdateUnifiedTraversalEgress(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Player?.MovementContext == null)
            {
                return;
            }

            BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(probe.Bot?.ProfileId);
            if (follower?.IsTeleportStabilizing == true)
            {
                return;
            }

            if (probe.UnifiedEgressPoints != null && probe.UnifiedEgressPoints.Count > 0)
            {
                probe.UnifiedEgressIndex = Mathf.Clamp(
                    probe.UnifiedEgressIndex,
                    0,
                    probe.UnifiedEgressPoints.Count - 1);
                while (probe.UnifiedEgressIndex < probe.UnifiedEgressPoints.Count - 1)
                {
                    float advanceDistance = string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase)
                        ? JumpEgressSemanticAdvanceDistance
                        : 0.30f;
                    if (GetPlanarDistance(probe.Player.Position, probe.UnifiedEgressPoints[probe.UnifiedEgressIndex]) > advanceDistance)
                    {
                        break;
                    }
                    probe.UnifiedEgressIndex++;
                }
            }

            {
                int retiredPointCount = 0;
                if (probe.UnifiedEgressPoints != null && probe.UnifiedEgressPoints.Count > 0)
                {
                    while (probe.UnifiedEgressIndex < probe.UnifiedEgressPoints.Count - 1 &&
                           TryGetLearningV430UpstreamConsumerTargetRegression(
                               probe,
                               probe.UnifiedEgressPoints[probe.UnifiedEgressIndex],
                               out _,
                               out _,
                               out _))
                    {
                        probe.UnifiedEgressIndex++;
                        retiredPointCount++;
                    }
                }

                if (TryGetLearningV430UpstreamConsumerTargetRegression(
                        probe,
                        probe.TraversalVerifyTarget,
                        out float learningV430CurrentProjection,
                        out float learningV430VerifyProjection,
                        out float learningV430AuthoredSpan))
                {
                    bool persistentChronologyEvidenceChanged =
                        RecordLearningV430MonotonicConsumerEvidence(
                            probe.LearnedEdgeId,
                            "staleUpstreamConsumerRetired",
                            "egressVerifyTarget");
                    WriteEvent("learningV430StaleUpstreamEgressRetired", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        position = Vec(probe.Player.Position),
                        retiredPointCount,
                        egressIndex = probe.UnifiedEgressIndex,
                        egressSampleCount = probe.UnifiedEgressPoints?.Count ?? 0,
                        rejectedVerifyTarget = Vec(probe.TraversalVerifyTarget),
                        currentProjection = learningV430CurrentProjection,
                        targetProjection = learningV430VerifyProjection,
                        authoredSpan = learningV430AuthoredSpan,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = persistentChronologyEvidenceChanged,
                        bodyRelocated = false,
                        action = "downstreamPhysicalBodyOwnsChronologyRetireHistoricalExitTargetAndVerifyCurrentBody"
                    });
                    probe.TraversalEgressCompleted = true;
                    BeginUnifiedTraversalVerify(probe, "learningV430StaleUpstreamEgressRetired");
                    return;
                }

                if (retiredPointCount > 0)
                {
                    WriteEvent("learningV430UpstreamEgressSamplesSkipped", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        position = Vec(probe.Player.Position),
                        retiredPointCount,
                        egressIndex = probe.UnifiedEgressIndex,
                        egressSampleCount = probe.UnifiedEgressPoints?.Count ?? 0,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "egressCursorOnlyMovesForwardAcrossAlreadyConsumedSamples"
                    });
                }
            }

            if (string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                !probe.JumpSemanticDropCommitted &&
                probe.UnifiedEgressPoints != null && probe.UnifiedEgressPoints.Count > 2 &&
                probe.UnifiedEgressSemanticSamples != null &&
                probe.UnifiedEgressSemanticSamples.Count == probe.UnifiedEgressPoints.Count)
            {
                int currentIndex = Mathf.Clamp(probe.UnifiedEgressIndex, 0, probe.UnifiedEgressPoints.Count - 1);
                int airborneIndex = -1;
                for (int index = currentIndex; index < probe.UnifiedEgressSemanticSamples.Count; index++)
                {
                    TraversalEgressSemanticSample semantic = probe.UnifiedEgressSemanticSamples[index];
                    if (semantic != null && !semantic.Grounded)
                    {
                        airborneIndex = index;
                        break;
                    }
                }
                if (airborneIndex >= 0)
                {
                    int landingIndex = -1;
                    for (int index = airborneIndex + 1; index < probe.UnifiedEgressSemanticSamples.Count; index++)
                    {
                        TraversalEgressSemanticSample semantic = probe.UnifiedEgressSemanticSamples[index];
                        if (semantic != null && semantic.Grounded)
                        {
                            landingIndex = index;
                            break;
                        }
                    }
                    Vector3 crestTarget = probe.UnifiedEgressPoints[Mathf.Max(currentIndex, airborneIndex - 1)];
                    float crestPlanar = GetPlanarDistance(probe.Player.Position, crestTarget);
                    if (landingIndex > airborneIndex &&
                        crestPlanar <= JumpEgressSemanticLedgeCommitDistance &&
                        GetPlanarDistance(probe.Player.Position, probe.UnifiedEgressPoints[landingIndex]) <= JumpEgressSemanticMaxLandingLookAhead &&
                        probe.UnifiedEgressPoints[landingIndex].y <= probe.Player.Position.y + 0.20f)
                    {
                        probe.UnifiedEgressIndex = landingIndex;
                        probe.JumpSemanticDropCommitted = true;
                        WriteEvent("jumpEgressSemanticDropCommitted", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            airborneIndex,
                            landingIndex,
                            crestPlanar,
                            position = Vec(probe.Player.Position),
                            landingTarget = Vec(probe.UnifiedEgressPoints[landingIndex])
                        });
                    }
                }
            }

            if (string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                probe.UnifiedEgressPoints != null && probe.UnifiedEgressPoints.Count > 2)
            {
                // R8.1: use downhill look-ahead as a secondary safety net after semantic ledge
                // detection. A lower threshold avoids getting pinned a few centimetres below the
                // player's exact crest height.
                // R8: only use downhill look-ahead after the follower has actually reached the
                // demonstrated crest. Without this guard a low RawExit could see a much later
                // ground sample and incorrectly skip the authored climb across the platform.
                float currentY = probe.Player.Position.y;
                float crestY = probe.UnifiedEgressPoints.Max(point => point.y);
                if (currentY >= crestY - 0.45f)
                {
                    int lookAheadLimit = Math.Min(
                        probe.UnifiedEgressPoints.Count - 1,
                        probe.UnifiedEgressIndex + JumpEgressLookAheadMaxSamples);
                    for (int index = probe.UnifiedEgressIndex + 1; index <= lookAheadLimit; index++)
                    {
                        if (currentY - probe.UnifiedEgressPoints[index].y >= JumpEgressLookAheadDropThreshold)
                        {
                            probe.UnifiedEgressIndex = index;
                            WriteEvent("jumpEgressDropLookAhead", probe.Bot, new
                            {
                                edgeId = probe.LearnedEdgeId,
                                targetIndex = index,
                                currentY,
                                crestY,
                                targetY = probe.UnifiedEgressPoints[index].y
                            });
                            break;
                        }
                    }
                }
            }

            Vector3 activeTarget = probe.UnifiedEgressPoints != null && probe.UnifiedEgressPoints.Count > 0
                ? probe.UnifiedEgressPoints[probe.UnifiedEgressIndex]
                : probe.TraversalVerifyTarget;
            Vector3 fullDeltaToActive = activeTarget - probe.Player.Position;
            Vector3 toTarget = fullDeltaToActive;
            toTarget.y = 0f;
            float activeDistance = toTarget.magnitude;
            float activeSpatialDistance = fullDeltaToActive.magnitude;
            float finalDistance = GetPlanarDistance(probe.Player.Position, probe.TraversalVerifyTarget);
            float physicalProgress = GetPlanarDistance(probe.Player.Position, probe.UnifiedEgressLastPosition);
            if (physicalProgress >= TraversalMeaningfulProgressDistance ||
                finalDistance + 0.08f < probe.UnifiedEgressLastDistance)
            {
                probe.UnifiedEgressLastPosition = probe.Player.Position;
                probe.UnifiedEgressLastDistance = finalDistance;
                probe.UnifiedEgressLastProgressAt = Time.time;
                probe.OwnershipLeaseExpiresAt = Mathf.Max(
                    probe.OwnershipLeaseExpiresAt,
                    Time.time + UnifiedTraversalEgressTimeout + UnifiedTraversalVerifyTimeout + 1.0f);
