            if (finalEgressPoint && finalDistance <= UnifiedTraversalEgressCompletionDistance)
            {
                probe.TraversalEgressCompleted = true;
                if (!TryFinalizeTraversalChainIntermediate(probe, "egressReached"))
                {
                    BeginUnifiedTraversalVerify(probe, "egressReached");
                }
                return;
            }

            float egressNoProgressFor = Mathf.Max(0f, Time.time - probe.UnifiedEgressLastProgressAt);
            if (egressNoProgressFor >= UnifiedTraversalEgressAuthorityNoProgressSeconds &&
                TryReacquireUnifiedTraversalEgressAuthority(
                    probe, activeTarget, finalDistance, "proactiveNoProgress"))
            {
                probe.UnifiedEgressDeadlineAt = Mathf.Max(
                    probe.UnifiedEgressDeadlineAt,
                    Time.time + UnifiedTraversalEgressAuthorityLeaseSeconds + 0.35f);
                return;
            }

            if (probe.UnifiedEgressDeadlineAt <= 0f)
            {
                probe.UnifiedEgressDeadlineAt = probe.StageStartedAt + UnifiedTraversalEgressTimeout;
            }
            if (Time.time >= probe.UnifiedEgressDeadlineAt)
            {
                probe.TraversalEgressTimedOut = true;
                float noProgressFor = egressNoProgressFor;
                bool hardStuck = IsTraversalHardStuck(probe, out string stuckReason);
                WriteEvent("traversalEgressTimeout", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    remaining = finalDistance,
                    activeRemaining = activeDistance,
                    activeSpatialRemaining = activeSpatialDistance,
                    egressIndex = probe.UnifiedEgressIndex,
                    egressSampleCount = probe.UnifiedEgressPoints?.Count ?? 0,
                    target = Vec(probe.TraversalVerifyTarget),
                    position = Vec(probe.Player.Position),
                    noProgressFor,
                    hardStuck,
                    stuckReason,
                    timeoutExtensions = probe.UnifiedEgressTimeoutExtensions
                });

                if (TryReacquireUnifiedTraversalEgressAuthority(
                        probe, activeTarget, finalDistance, "egressTimeout"))
                {
                    probe.TraversalEgressTimedOut = false;
                    probe.UnifiedEgressDeadlineAt = Time.time + UnifiedTraversalEgressAuthorityLeaseSeconds + 0.35f;
                    return;
                }

                if (!hardStuck && probe.UnifiedEgressTimeoutExtensions < 3)
                {
                    probe.UnifiedEgressTimeoutExtensions++;
                    probe.TraversalEgressTimedOut = false;
                    probe.UnifiedEgressDeadlineAt = Time.time + TraversalEgressProgressExtensionSeconds;
                    probe.OwnershipLeaseExpiresAt = Mathf.Max(
                        probe.OwnershipLeaseExpiresAt,
                        probe.UnifiedEgressDeadlineAt + UnifiedTraversalVerifyTimeout + 1.0f);
                    return;
                }

                WriteEvent("traversalEgressEscalatedMonotonic", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    remaining = finalDistance,
                    hardStuck,
                    stuckReason,
                    authorityReacquireAttempts = probe.UnifiedEgressAuthorityReacquireAttempts
                });
                if (EscalateTraversalFailureMonotonic(
                        probe,
                        "egressTimeout:" + (stuckReason ?? "noProgress")))
                {
                    return;
                }

                FinalizeUnifiedTraversalFailure(probe, "egressRecoveryTeleportRejected");
                return;
            }

            if (activeSpatialDistance <= 0.05f)
            {
                return;
            }

            Vector3 fullDelta = fullDeltaToActive;
            Vector3 flatDirection = GetFlatDirection(fullDelta);
            probe.Bot?.Steering?.BotSteeringLookToDirection("R1-0F0B4D0EB475",@probe?.Bot,flatDirection.sqrMagnitude > 0.5f ? flatDirection : probe.RequestedDirection);
            // Use the same native world-direction producer for typed DropDown egress.
            // Pre-acquisition physical crossing may not have populated TraversalKind yet.
            if (FollowerCapabilityPassagePolicy.NativeEgressKind(probe.TraversalKind,probe.RequestedTraversalKind,IsProbeLifecycleCurrent(probe)) &&
                !probe.IslandExitBridgeActive)
            {
                Vector3 nativeDirection = flatDirection.sqrMagnitude > 0.000001f
                    ? flatDirection
                    : GetFlatDirection(probe.RequestedDirection);
                if (nativeDirection.sqrMagnitude > 0.000001f)
                {
