                probe.Bot.Mover.SetBotMoverPause("R1-38D51DC9F1E9",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverSprint("R1-BB83670AF127",@probe?.Bot,false,false);
                NavMeshPathStatus status = probe.Bot.BotOwnerGoToPoint(
"R1-62915647277F",@probe?.Bot,                    boundedHit.position,true,-1f,false,false);
                if (status != NavMeshPathStatus.PathComplete)
                {
                    WriteEvent("learningV333DropDownExitCommitForwardContinuityRejected", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        source = source ?? "unknown",
                        position = Vec(position),
                        target = Vec(boundedHit.position),
                        downstreamSource,
                        pathStatus = status.ToString(),
                        action = "retainExistingExitAuthorityValidationNoSyntheticMovement"
                    });
                    return false;
                }

                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-D5147F94AAA6",@probe?.Bot,0.65f);
                probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-1CBA45572611",@probe?.Bot,0.65f);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-53C21A031C5E",@probe?.Bot,downstreamDirection);
                HoldForwardInput(probe);
                probe.LearningV331DropDownLandingForwardHandoffActive = true;
                probe.LearningV331DropDownLandingForwardHandoffTarget = boundedHit.position;
                WriteEvent("learningV333DropDownExitCommitForwardContinuityInstalled", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    source = source ?? "unknown",
                    position = Vec(position),
                    target = Vec(boundedHit.position),
                    downstreamSource,
                    pathStatus = status.ToString(),
                    successCommitted = false,
                    action = "sameFrameBoundedForwardMoverRestoredAfterZeroDistanceRebase"
                });
                return true;
            }
            catch (Exception ex)
            {
                WriteEvent("learningV333DropDownExitCommitForwardContinuityException", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    source = source ?? "unknown",
                    error = ex.GetType().Name + ": " + ex.Message
                });
                return false;
            }
        }

        private static bool TryInstallLearningV335WalkThroughExitRebaseForwardContinuity(
            ProbeRuntime probe,
            string source)
        {
            if ((probe?.Bot?.Mover == null) ||
                probe.Player == null ||
                !string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return false;
            }

            Vector3 entry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 exit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 direction = GetFlatDirection(exit - entry);
            if (direction.sqrMagnitude < 0.5f)
            {
                direction = GetFlatDirection(probe.RequestedDirection);
            }
            if (direction.sqrMagnitude < 0.5f)
            {
                return false;
            }

            Vector3 position = probe.Player.Position;
            Vector3 target = position + direction * WalkThroughArcLookAheadDistance;
            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-1C606D2BDD8E",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverSprint("R1-73D18FE7024C",@probe?.Bot,false,false);
                NavMeshPathStatus status = probe.Bot.BotOwnerGoToPoint("R1-D38CC55477F3",@probe?.Bot,target,true,-1f,false,false);
                if (status != NavMeshPathStatus.PathComplete)
                {
                    return false;
                }
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-52E87145B590",@probe?.Bot,WalkThroughStepAssistForwardSpeed);
                probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-B9A5AB67F91F",@probe?.Bot,WalkThroughStepAssistForwardSpeed);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-157DBD21B72F",@probe?.Bot,direction);
                HoldForwardInput(probe);
                WriteEvent("learningV335WalkThroughExitRebaseForwardContinuityInstalled", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    source = source ?? "unknown",
                    position = Vec(position),
                    target = Vec(target),
                    pathStatus = status.ToString(),
                    successCommitted = false,
                    action = "boundedAuthoredForwardProducerRestoredAfterZeroDistanceRebase"
                });
                return true;
            }
            catch (Exception ex)
            {
                WriteEvent("learningV335WalkThroughExitRebaseForwardContinuityException", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    source = source ?? "unknown",
                    error = ex.GetType().Name + ": " + ex.Message
                });
                return false;
            }
        }

        private static bool TryInstallLearningV336ExitConsumerContinuity(
            ProbeRuntime probe,
            string source)
        {
            if (!true || probe?.Bot?.Mover == null ||
                probe.Player == null || !IsActiveProbe(probe) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return false;
            }

            Vector3 target = default;
            string targetSource = string.Empty;
            if (TryGetRouteMissionSuccessorRecoveryTarget(probe, commitment, out Vector3 successorTarget) &&
                IsFinite(successorTarget))
            {
                target = successorTarget;
                targetSource = "routeMissionSuccessorEntry";
            }
            else if (TryGetTraversalDownstreamEvidence(
                         probe, commitment, out Vector3 downstreamTarget, out _, out string downstreamSource,
                         allowLeaderFallback: !true) &&
                     IsFinite(downstreamTarget))
            {
                target = downstreamTarget;
                targetSource = string.IsNullOrWhiteSpace(downstreamSource)
                    ? "traversalDownstreamEvidence"
                    : "downstream:" + downstreamSource;
            }
            else if (!true)
            {
                Player leader = FollowerEnvironment.LocalPlayer;
                if (IsLivePlayer(leader) && IsFinite(leader.Position))
                {
                    target = leader.Position;
                    targetSource = "leaderDirectFallback";
                }
            }

            if (!IsFinite(target))
            {
                return false;
            }

            // V3.40: an ExitAuthority consumer is intentionally LOCAL. A later RouteMission
            // traversal tens of metres away is not the current traversal's consumer; ordinary
            // Follow/RouteMission must own that intervening ground segment. Reuse the existing
            // traversal-adjacent bridge envelope instead of inventing a new distance threshold.
            float consumerTargetDistance = GetPlanarDistance(probe.Player.Position, target);
            if (true &&
                consumerTargetDistance > RouteMissionTraversalAdjacentBridgeMaxDistance)
            {
                WriteEvent("learningV340NonLocalExitConsumerRejected", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    targetSource,
                    target = Vec(target),
                    targetDistance = consumerTargetDistance,
                    existingAdjacentEnvelope = RouteMissionTraversalAdjacentBridgeMaxDistance,
                    action = "nonLocalSuccessorBelongsToOrdinaryFollowOrFutureRouteMission"
                });
                return false;
            }

            const string pathSource = "learningV336-exit-consumer-continuity";
            if (!CanAcceptFollowPath(probe.Bot, target, pathSource, out float pathLength, out float detourRatio))
            {
                WriteEvent("learningV336ExitConsumerContinuityRejected", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    targetSource,
                    target = Vec(target),
                    pathLength,
                    detourRatio,
                    action = "retainV333V335FiniteProducerFallback"
                });
                return false;
            }

            NavMeshPathStatus status;
            try
            {
                // V3.73: a physical traversal can move the body several metres while EFT's native
                // BotMover bookkeeping (PositionOnWayInner / PrevSuccessLinkedFrom) still belongs to
                // the pre-crossing path epoch. Installing a semantically correct consumer target on
                // top of that stale origin produced a valid-looking PathComplete whose native mover
                // immediately pulled the body backward. Before the first consumer path write, rebase
                // ONLY the native path-origin bookkeeping onto the current physical body. This is the
                // existing V364 state-only epoch scrub: no Teleport, CharacterController.Move, Stop,
                // new threshold, or traversal-success credit is introduced.
                bool learningV373HadUnsynchronizedPhysicalEpoch =
                    true &&
                    HasLearningV364UnsynchronizedPhysicalNavigationEpoch(
                        probe.Bot, out PhysicalNavigationEpochHandoff learningV373PendingPhysicalEpoch);
                if (learningV373HadUnsynchronizedPhysicalEpoch)
                {
                    Vector3 physicalBody = probe.Player.Position;
                    if (!TryScrubLearningV364NativeMoverEpochAnchor(
                            probe.Bot,
                            physicalBody,
                            "learningV373PreExitConsumerPath",
                            out string learningV373ScrubDetail))
                    {
                        WriteEvent("learningV373ExitConsumerPhysicalEpochScrubFailed", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            kind = probe.TraversalKind,
                            source = source ?? "unknown",
                            targetSource,
                            target = Vec(target),
                            physicalBody = Vec(physicalBody),
                            pendingSourceEdgeId = learningV373PendingPhysicalEpoch?.SourceEdgeId ?? 0,
                            detail = learningV373ScrubDetail,
                            action = "rejectConsumerPathInsteadOfStackingNewTargetOnStaleNativeMoverEpoch"
                        });
                        return false;
                    }

                    WriteEvent("learningV373ExitConsumerPhysicalEpochScrubbedBeforePath", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        source = source ?? "unknown",
                        targetSource,
                        target = Vec(target),
                        physicalBody = Vec(physicalBody),
                        pendingSourceEdgeId = learningV373PendingPhysicalEpoch?.SourceEdgeId ?? 0,
                        action = "stateOnlyNativePathOriginRebasedBeforeDownstreamConsumerInstall"
                    });
                }

                probe.Bot.Mover.SetBotMoverPause("R1-C29834160764",@probe?.Bot,false);
                status = probe.Bot.BotOwnerGoToPoint("R1-5F8DEF3A87AD",@probe?.Bot,target,true,-1f,false,false);
                RecordFollowPathResult(probe.Bot, target, pathSource, status);
                if (status != NavMeshPathStatus.PathComplete)
                {
                    return false;
                }

                if (true &&
                    HasLearningV364UnsynchronizedPhysicalNavigationEpoch(
                        probe.Bot, out PhysicalNavigationEpochHandoff learningV373StillPendingPhysicalEpoch))
                {
                    WriteEvent("learningV373ExitConsumerPathRejectedUnsynchronizedPhysicalEpoch", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        source = source ?? "unknown",
                        targetSource,
                        target = Vec(target),
                        pendingSourceEdgeId = learningV373StillPendingPhysicalEpoch?.SourceEdgeId ?? 0,
                        action = "pathCompleteIsNotConsumerAuthorityUntilNativeMoverBookkeepingSharesBodyEpoch"
                    });
                    return false;
                }
                if (probe.PreviousSprinting || probe.PreviousRunning)
                {
                    probe.Bot.BotOwnerSetTargetMoveSpeed("R1-8C0651B2A69F",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                    probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-6EAFC9760D22",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                }
                if (probe.PreviousSprinting && !probe.Bot.Mover.Sprinting)
                {
                    probe.Bot.Mover.BotMoverSprint("R1-06A4669114DD",@probe?.Bot,true,false);
                }
            }
            catch (Exception ex)
            {
                WriteEvent("learningV336ExitConsumerContinuityException", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    targetSource,
                    error = ex.GetType().Name + ": " + ex.Message
                });
                return false;
            }

            probe.LearningV336ExitConsumerContinuityActive = true;
            probe.LearningV336ExitConsumerContinuityTarget = target;
            probe.LearningV336ExitConsumerContinuitySource = targetSource;
            WriteEvent("learningV336ExitConsumerContinuityInstalled", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                source = source ?? "unknown",
                targetSource,
                target = Vec(target),
                pathLength,
                detourRatio,
                status = status.ToString(),
                traversalOwnershipRetained = true,
                action = "singleDownstreamConsumerPathSurvivesExitAuthorityValidation"
            });
            return true;
        }

        private static bool TryBeginLearningV337ConsumerFirstExitValidation(ProbeRuntime probe, string source)
        {
            if ((probe?.Bot?.Mover == null) ||
                probe.Player == null || !IsActiveProbe(probe) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return false;
            }

            bool walkThrough = string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            bool qualifiedJump = string.Equals(commitment.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                                 probe.JumpAttempted && probe.LearningV330NativeJumpQualifiedLandingWitness;
            bool qualifiedDropDown = (string.Equals(commitment.Kind, "DropDown", StringComparison.OrdinalIgnoreCase)) &&
                                     probe.NativeDropDownPhysicalLandingAuthority;
            if (!walkThrough && !qualifiedJump && !qualifiedDropDown)
            {
                return false;
            }

            bool supported = IsEffectivelySupportedForProbe(probe.Bot, probe.Player);
            bool navStable = NavMesh.SamplePosition(
                probe.Player.Position, out NavMeshHit currentHit,
                ExitAuthorityNavSampleRadius, NavMesh.AllAreas) &&
                Mathf.Abs(currentHit.position.y - probe.Player.Position.y) <= ExitAuthorityMaxNavVertical;
            if (!supported || (!qualifiedJump && !qualifiedDropDown && !navStable))
            {
                return false;
            }

            if ((walkThrough))
            {
                WriteEvent("learningV344WalkThroughNavigationStateSynchronizationRestored", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    source = source ?? "unknown",
                    position = Vec(probe.Player.Position),
                    navStable,
                    supported,
                    action = "restoreV336ZeroDistanceNavigationEpochSynchronizationBeforeConsumerHandoff"
                });
                ArmExitAuthorityRebase(probe, "learningV344V336NavigationStateSync");
                return true;
            }

            // V3.39: downstream consumer availability is not permission to rewrite the physical
            // body. V3.40 additionally separates a LOCAL traversal consumer from the ordinary
            // global Follow target. If no local successor exists but the physical exit is already
            // Nav-stable, ordinary Follow itself is the next consumer; do not keep Traversal ownership
            // pending while chasing a leader target tens of metres away. Off-NavMesh exits still
            // require a real local successor/egress bridge.
            if (!TryInstallLearningV336ExitConsumerContinuity(
                    probe, "learningV339ConsumerFirst:" + (source ?? "unknown")))
            {
                ;

                if ((navStable))
                {
                    probe.LearningV337ConsumerFirstExitValidationActive = true;
                    probe.LearningV339ConsumerPendingNoRebase = false;
                    probe.LearningV339ConsumerProgressTopologyConfirmed = false;
                    probe.LearningV340OrdinaryFollowConsumerAuthority = true;
                    probe.LearningV340LocalConsumerPathTopologyConfirmed = false;
                    probe.ExitAuthorityRebaseStarted = true;
                    probe.ExitAuthorityMoverValidationActive = true;
                    probe.ExitAuthorityValidationStartedAt = Time.time;
                    probe.ExitAuthorityStableSamples = 0;
                    probe.ExitAuthorityLastPosition = probe.Player.Position;
                    probe.ExitAuthorityTopologyRejoinConfirmed = true;
                    probe.ExitAuthorityTopologyRejoinResult = "learningV340OrdinaryFollowConsumer";
                    probe.StageStartedAt = Time.time;
                    WriteEvent("learningV340ExitConsumerReleasedToOrdinaryFollow", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = commitment.Kind,
                        source = source ?? "unknown",
                        position = Vec(probe.Player.Position),
                        navStable,
                        supported,
                        zeroDistanceRebaseSkipped = true,
                        action = "noLocalTraversalSuccessorPhysicalExitBecomesOrdinaryFollowProducer"
                    });
                    return true;
                }

                probe.LearningV340OrdinaryFollowConsumerAuthority = false;
                probe.LearningV340LocalConsumerPathTopologyConfirmed = false;
                probe.LearningV339ConsumerPendingNoRebase = true;
                probe.LearningV339NextConsumerRetryAt = Time.time + RouteMissionMoveRetrySeconds;
                probe.LearningV339ConsumerProgressTopologyConfirmed = false;
                probe.ExitAuthorityRebaseStarted = true;
                probe.ExitAuthorityMoverValidationActive = true;
                probe.ExitAuthorityValidationStartedAt = Time.time;
                probe.ExitAuthorityStableSamples = 0;
                probe.ExitAuthorityLastPosition = probe.Player.Position;
                probe.StageStartedAt = Time.time;
                try
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-8FCF94E060B1",@probe?.Bot,false);
                    probe.Bot.Mover.BotMoverSprint("R1-DD45C2456580",@probe?.Bot,false,false);
                    probe.Bot.BotOwnerSetTargetMoveSpeed("R1-D26B7E755816",@probe?.Bot,ProbeMomentumNormalMoveSpeed);
                }
                catch { }
                WriteEvent("learningV339ExitConsumerPendingNoRebase", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = commitment.Kind,
                    source = source ?? "unknown",
                    position = Vec(probe.Player.Position),
                    supported,
                    navStable,
                    qualifiedJump,
                    qualifiedDropDown,
                    retrySeconds = RouteMissionMoveRetrySeconds,
                    zeroDistanceRebaseSkipped = true,
                    action = "retainPhysicalBodyRetryRealDownstreamConsumer"
                });
                return true;
            }

            probe.LearningV337ConsumerFirstExitValidationActive = true;
            probe.LearningV339ConsumerPendingNoRebase = false;
            probe.LearningV339ConsumerProgressTopologyConfirmed = false;
            probe.LearningV340OrdinaryFollowConsumerAuthority = false;
            probe.LearningV340LocalConsumerPathTopologyConfirmed =
                (IsFinite(probe.LearningV336ExitConsumerContinuityTarget)) &&
                GetPlanarDistance(probe.Player.Position, probe.LearningV336ExitConsumerContinuityTarget) <=
                    ExitAuthorityNoCommandLeaderDistance;
            if (probe.LearningV340LocalConsumerPathTopologyConfirmed)
            {
                probe.ExitAuthorityTopologyRejoinConfirmed = true;
                probe.ExitAuthorityTopologyRejoinResult = "learningV340LocalConsumerPathComplete";
                WriteEvent("learningV340LocalConsumerPathTopologyConfirmed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = commitment.Kind,
                    position = Vec(probe.Player.Position),
                    target = Vec(probe.LearningV336ExitConsumerContinuityTarget),
                    targetDistance = GetPlanarDistance(probe.Player.Position, probe.LearningV336ExitConsumerContinuityTarget),
                    existingEnvelope = ExitAuthorityNoCommandLeaderDistance,
                    action = "localPathCompleteIsTopologyProofPhysicalTraversalAlreadyProvedFarSideBody"
                });
            }
            probe.ExitAuthorityRebaseStarted = true;
            probe.ExitAuthorityMoverValidationActive = true;
            probe.ExitAuthorityValidationStartedAt = Time.time;
            probe.ExitAuthorityStableSamples = 0;
            probe.ExitAuthorityLastPosition = probe.Player.Position;
            probe.StageStartedAt = Time.time;
            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-38FCC6ECDF1D",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverSprint("R1-E040CBE01BEA",@probe?.Bot,false,false);
                probe.Bot.BotOwnerSetTargetMoveSpeed("R1-CD7879B8EFF8",@probe?.Bot,ProbeMomentumNormalMoveSpeed);
            }
            catch { }

            WriteEvent(walkThrough
                    ? "learningV337WalkThroughExitConsumerFirstValidationStarted"
                    : (qualifiedDropDown
                        ? "learningV339QualifiedDropDownExitConsumerFirstValidationStarted"
                        : "learningV337QualifiedJumpExitConsumerFirstValidationStarted"),
                probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = commitment.Kind,
                    source = source ?? "unknown",
                    position = Vec(probe.Player.Position),
                    navStable,
                    supported,
                    qualifiedJump,
                    qualifiedDropDown,
                    zeroDistanceRebaseSkipped = true,
                    action = "physicalBodyTruthThenDownstreamConsumer"
                });
            return true;
        }

        private static void ArmExitAuthorityRebase(ProbeRuntime probe, string source)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Player?.MovementContext == null)
            {
                return;
            }

            Vector3 anchor = probe.ExitAuthorityAnchor;
            if (!IsFinite(anchor))
            {
                anchor = probe.Player.Position;
                probe.ExitAuthorityAnchor = anchor;
            }

            probe.LearningV337ConsumerFirstExitValidationActive = false;
            probe.LearningV339ConsumerPendingNoRebase = false;
            probe.LearningV339ConsumerProgressTopologyConfirmed = false;
            probe.LearningV340OrdinaryFollowConsumerAuthority = false;
            probe.LearningV340LocalConsumerPathTopologyConfirmed = false;
            probe.ExitAuthorityRebaseAttempts++;
            probe.ExitAuthorityRebaseStarted = true;
            probe.ExitAuthorityMoverValidationActive = false;
            probe.ExitAuthorityTopologyRejoinRequested = false;
            probe.ExitAuthorityTopologyRejoinConfirmed = false;
            probe.ExitAuthorityTopologyRejoinRequestedAt = 0f;
            probe.ExitAuthorityTopologyRejoinLinkedDistance = float.MaxValue;
            probe.ExitAuthorityTopologyRejoinResult = null;
            probe.ExitAuthorityActionableTopologyCandidate = false;
            probe.ExitAuthorityActionableTopologyTarget = Vector3.zero;
            probe.ExitAuthorityActionableTopologyPathLength = 0f;
            probe.ExitAuthorityActionableTopologyDetourRatio = 0f;
            probe.ExitAuthorityFollowHandoffActive = false;
            probe.ExitAuthorityFollowPathObserved = false;
            probe.ExitAuthorityFollowHandoffStartedAt = 0f;
            probe.ExitAuthorityFollowPathFirstObservedAt = 0f;
            probe.ExitAuthorityFollowPathObservedAt = 0f;
            probe.ExitAuthorityFollowStartPosition = Vector3.zero;
            probe.ExitAuthorityFollowPathRejected = false;
            probe.ExitAuthorityFollowPathRejectedAt = 0f;
            probe.ExitAuthorityFollowRejectedPathLength = 0f;
            probe.ExitAuthorityFollowRejectedDetourRatio = 0f;
            probe.LearningV336ExitConsumerContinuityActive = false;
            probe.LearningV336ExitConsumerContinuityTarget = Vector3.zero;
            probe.LearningV336ExitConsumerContinuitySource = null;
            probe.ExitAuthorityValidationStartedAt = 0f;
            probe.ExitAuthorityStableSamples = 0;
            probe.StageStartedAt = Time.time;
            probe.ExitAuthorityLastPosition = probe.Player.Position;
            if (!string.IsNullOrEmpty(probe.Bot?.ProfileId))
            {
                FollowRejectLeases.Remove(probe.Bot.ProfileId);
            }

            try
            {
                RestoreAssistedObstacleCollisionLease(probe, "exitAuthorityRebase");
                RestoreAssistedTraversalAnimation(probe);

                // CompileFix26: clear only traversal animator triggers. Do not zero locomotion input
                // or Stop/StopMove the follower on every successful exit. The bookkeeping scrub
                // retains the current physical origin while ordinary
                // locomotion intent stays live across the authority transfer.
                probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoVault("R1-59FCF5ABCB03",@probe?.Bot,false);
                probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoClimb("R1-5C6875843015",@probe?.Bot,false);
                probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-A13281223C45",@probe?.Bot);

                if (probe.Bot.GoToSomePointData != null)
                {
                    // Retire a stale pre-traversal destination without stopping the character; a
                    // fresh Follow target is prewarmed below.
                    probe.Bot.GoToSomePointData.BotGoToPointDataSetPoint("R1-D7D9EBD9073A",@probe?.Bot,probe.Player.Position);
                    probe.Bot.GoToSomePointData.BotGoToPointDataUpdateToGo("R1-868DA6CE2689",@probe?.Bot,false);
                }

                if (probe.Bot.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-0362E60CA539",@probe?.Bot,false);

                    // Synchronize bookkeeping at the actual body; a cached exit anchor is never a relocation target.
                    if(!TryRetireNativeMoverPathPreserveLocomotion(probe.Bot,"exitAuthorityBookkeepingOnly",out _)||
                        !TryScrubLearningV364NativeMoverEpochAnchor(probe.Bot,probe.Player.Position,"exitAuthorityBookkeepingOnly",out _))
                    {FinalizeOrEscalateTraversalFailure(probe,"exitAuthorityBookkeepingUnavailable");return;}
                    if (ShouldPreserveCapabilityProbeGait(probe) && (probe.PreviousSprinting || probe.PreviousRunning))
                    {
                        probe.Bot.BotOwnerSetTargetMoveSpeed("R1-DEFF15A71F0B",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                        probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-AF63739DE96B",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                    }
                    if (ShouldPreserveCapabilityProbeGait(probe) && probe.PreviousSprinting && !probe.Bot.Mover.Sprinting)
                    {
                        probe.Bot.Mover.BotMoverSprint("R1-4055A8C59B8D",@probe?.Bot,true,false);
                    }
                }
                else
                {
                    FinalizeOrEscalateTraversalFailure(probe,"exitAuthorityMoverUnavailable");return;
                }
            }
            catch (Exception ex)
            {
                WriteEvent("exitAuthorityRebaseException", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    attempt = probe.ExitAuthorityRebaseAttempts,
                    error = ex.GetType().Name + ": " + ex.Message
                });
            }

            WriteEvent("exitAuthorityRebaseStarted", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                source = source ?? "unknown",
                attempt = probe.ExitAuthorityRebaseAttempts,
                anchor = Vec(anchor),
                state = probe.Player.CurrentStateName.ToString(),
                body=Vec(probe.Player.Position),bodyRelocated=false,bookkeepingOnly=true,
                moverValidationDeferred = ExitAuthorityRebaseHoldSeconds
            });

            // The physical body remains untouched; the
            // next movement producer is now the actual downstream consumer. Do not install a short
            // authored-forward path merely to replace it with Follow a few frames later. V3.33/V3.35
            // finite producers remain exact fallback when no safe consumer path exists.
            bool learningV336ConsumerInstalled = TryInstallLearningV336ExitConsumerContinuity(
                probe, "exitAuthorityRebase:" + (source ?? "unknown"));
            if (!learningV336ConsumerInstalled)
            {
                TryInstallLearningV333DropDownExitCommitForwardContinuity(
                    probe, "exitAuthorityRebase:" + (source ?? "unknown"));
                TryInstallLearningV335WalkThroughExitRebaseForwardContinuity(
                    probe, "exitAuthorityRebase:" + (source ?? "unknown"));
            }
        }

        private static bool TryStageWalkThroughActionableTopologyCandidate(
            ProbeRuntime probe,
            Vector3 position,
            bool navStable,
            string nativeResult)
        {
            if (probe?.Bot == null || probe.Player == null ||
