        private static bool TryValidateExitAuthorityConsumerReadyPathOwnership(
            ProbeRuntime probe,
            Vector3 requestedTarget,
            string followSource,
            out Vector3 ownedTarget,
            out string ownedTargetSource,
            out float ownedToRequested,
            out float ownedPathLength,
            out float ownedDetourRatio)
        {
            ownedTarget = default;
            ownedTargetSource = "none";
            ownedToRequested = float.MaxValue;
            ownedPathLength = 0f;
            ownedDetourRatio = 0f;
            if (probe?.Bot == null || probe.Player == null ||
                !probe.ExitAuthorityActionableTopologyCandidate ||
                !string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !IsFinite(requestedTarget))
            {
                return false;
            }

            bool ownedPathSane = TryValidateCurrentMoverFollowPath(
                probe.Bot,
                "exit-authority-follow-handoff",
                out ownedTarget,
                out ownedTargetSource,
                out ownedPathLength,
                out ownedDetourRatio);
            ownedToRequested = ownedPathSane && IsFinite(ownedTarget)
                ? GetPlanarDistance(ownedTarget, requestedTarget)
                : float.MaxValue;
            return ownedPathSane &&
                string.Equals(ownedTargetSource, "moverTarget", StringComparison.Ordinal) &&
                ownedToRequested <= FollowPathSanityCacheTargetTolerance;
        }

        private static void ConfirmExitAuthorityConsumerReadyTopology(
            ProbeRuntime probe,
            string proof,
            Vector3 ownedTarget,
            string ownedTargetSource,
            float ownedToRequested,
            float ownedPathLength,
            float ownedDetourRatio)
        {
            if (probe == null || probe.ExitAuthorityTopologyRejoinConfirmed ||
                !probe.ExitAuthorityActionableTopologyCandidate)
            {
                return;
            }

            probe.ExitAuthorityTopologyRejoinConfirmed = true;
            probe.ExitAuthorityTopologyRejoinResult = "actionableConsumerReady";
            WriteEvent("exitAuthorityActionableTopologyConfirmed", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                position = probe.Player != null ? Vec(probe.Player.Position) : null,
                requestedTarget = IsFinite(probe.ExitAuthorityFollowTarget) ? Vec(probe.ExitAuthorityFollowTarget) : null,
                followSource = probe.ExitAuthorityFollowPathSource ?? "unknown",
                proof = proof ?? "unknown",
                ownedTarget = IsFinite(ownedTarget) ? Vec(ownedTarget) : null,
                ownedTargetSource = ownedTargetSource ?? "none",
                ownedToRequested,
                ownedPathLength,
                ownedDetourRatio,
                candidatePathLength = probe.ExitAuthorityActionableTopologyPathLength,
                candidateDetourRatio = probe.ExitAuthorityActionableTopologyDetourRatio,
                nativeBookkeepingRequired = false,
                consumerReady = true,
                policy = "existingFollowDetourSanity+existingPhysicalProgressAck"
            });
        }

        private static NavMeshPathStatus PrimeExitAuthorityFollowPath(ProbeRuntime probe, string source)
        {
            if (probe != null && !probe.ExitAuthorityTopologyRejoinConfirmed &&
                !probe.ExitAuthorityActionableTopologyCandidate)
            {
                WriteEvent("exitAuthorityFollowPathBlockedPendingTopology", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    source = source ?? "unknown",
                    requested = probe.ExitAuthorityTopologyRejoinRequested,
                    linkedDistance = probe.ExitAuthorityTopologyRejoinLinkedDistance,
                    result = probe.ExitAuthorityTopologyRejoinResult
                });
                return NavMeshPathStatus.PathInvalid;
            }
            if (probe?.Bot == null || probe.Bot.IsDead || probe.Bot.Mover == null)
            {
                return NavMeshPathStatus.PathInvalid;
            }

            Vector3 target = Vector3.zero;
            bool haveTarget = false;
            try
            {
                if (probe.Bot.BotFollower?.BossToFollow != null)
                {
                    target = probe.Bot.BotFollower.BossToFollow.Position;
                    haveTarget = IsFinite(target);
                }
            }
            catch
            {
                haveTarget = false;
            }

            if (!haveTarget)
            {
                Player leader = FollowerEnvironment.LocalPlayer;
                if (IsLivePlayer(leader) && IsFinite(leader.Position))
                {
                    target = leader.Position;
                    haveTarget = true;
                }
            }

            if (!haveTarget)
            {
                return NavMeshPathStatus.PathInvalid;
            }

            const string followSource = "exit-authority-follow-handoff";
            if (!CanAcceptFollowPath(probe.Bot, target, followSource, out float pathLength, out float detourRatio))
            {
                RecordFollowPathSanityRejected(probe.Bot, target, followSource, pathLength, detourRatio);
                return NavMeshPathStatus.PathInvalid;
            }

            NavMeshPathStatus status;
            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-1E77A0C56DCC",@probe?.Bot,false);
                status = probe.Bot.BotOwnerGoToPoint("R1-0642A01BCE48",@probe?.Bot,target,true,-1f,false,false);
                RecordFollowPathResult(probe.Bot, target, followSource, status);
                if (status == NavMeshPathStatus.PathComplete)
                {
                    TryDriveCapabilityCompletedPhaseConsumer(probe.Bot,probe.LifecycleMission,probe.LifecycleStep);
                    probe.Bot.BotOwnerSetTargetMoveSpeed("R1-BC0A7F0952FA",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                    probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-B26BB1DE1AE7",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                    {
                        if (probe.Bot.Mover.Sprinting && !ShouldPreserveCapabilityTerminalSprint(probe,target))
                        {
                            probe.Bot.Mover.BotMoverSprint("R1-ACD6CE0B9E9D",@probe?.Bot,false,false);
                        }
                        HoldForwardInput(probe);
                        if (ShouldEmitDiagnostic("learningV357TerminalFollowRunEnvelope:" + probe.LearnedEdgeId, probe.Bot, 0.35f))
                        {
                            WriteEvent("learningV357TerminalFollowRunEnvelope", probe.Bot, new
                            {
                                edgeId = probe.LearnedEdgeId,
                                kind = probe.TraversalKind,
                                source = source ?? "unknown",
                                target = Vec(target),
                                action = "prewarmFollowInRunEnvelopeWithoutSprintBrakeCycle"
                            });
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                RecordFollowPathWriteException(probe.Bot, target, followSource, ex);
                return NavMeshPathStatus.PathInvalid;
            }

            WriteEvent("exitAuthorityFollowPathPrewarmed", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                source = source ?? "unknown",
                target = Vec(target),
                status = status.ToString(),
                sprinting = probe.Bot.Mover.Sprinting
            });
            return status;
        }

        private static void BeginExitAuthorityFollowHandoff(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Stage != ProbeStage.ExitCommit)
            {
                return;
            }

            probe.ExitAuthorityFollowHandoffActive = true;
            probe.ExitAuthorityFollowPathObserved = false;
            probe.ExitAuthorityFollowHandoffStartedAt = Time.time;
            probe.ExitAuthorityFollowPathFirstObservedAt = 0f;
            probe.ExitAuthorityFollowPathObservedAt = 0f;
            probe.ExitAuthorityFollowStartPosition = probe.Player != null ? probe.Player.Position : probe.ExitAuthorityAnchor;
            probe.ExitAuthorityFollowPathRejected = false;
            probe.ExitAuthorityFollowPathRejectedAt = 0f;
            probe.ExitAuthorityFollowRejectedPathLength = 0f;
            probe.ExitAuthorityFollowRejectedDetourRatio = 0f;
            probe.ExitAuthorityStableSamples = 0;

