            // receives a narrow bypass and may install its next ordinary route. This explicitly
            // validates the second writer class seen in R8.11 instead of declaring success before
            // Follow has had a chance to touch BotMover.
            WriteEvent("exitAuthorityFollowHandoffStarted", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                anchor = Vec(probe.ExitAuthorityAnchor),
                current = probe.Player != null ? Vec(probe.Player.Position) : null,
                noCommandGrace = ExitAuthorityFollowNoCommandGraceSeconds
