            // V3.36: if ExitAuthority already installed the downstream consumer immediately after
            // the zero-distance rebase, adopt that exact path as the Follow observation instead of
            // replacing it with another producer. This removes WT foot-pull/overshoot and the
            // ~0.6s DropDown finite-target exhaustion while preserving success validation.
            NavMeshPathStatus prewarmStatus = NavMeshPathStatus.PathInvalid;
            PhysicalNavigationEpochHandoff learningV373PendingHandoffEpoch = null;
            bool learningV373ConsumerMoverEpochReady =
                (!HasLearningV364UnsynchronizedPhysicalNavigationEpoch(
                    probe.Bot, out learningV373PendingHandoffEpoch));
            if ((probe.LearningV336ExitConsumerContinuityActive) &&
                IsFinite(probe.LearningV336ExitConsumerContinuityTarget) &&
                probe.Bot?.Mover != null && probe.Bot.Mover.HasPathAndNoComplete &&
                learningV373ConsumerMoverEpochReady)
            {
                probe.ExitAuthorityFollowPathObserved = true;
                probe.ExitAuthorityFollowPathFirstObservedAt = Time.time;
                probe.ExitAuthorityFollowPathObservedAt = Time.time;
                probe.ExitAuthorityFollowTarget = probe.LearningV336ExitConsumerContinuityTarget;
                probe.ExitAuthorityFollowPathSource =
                    "learningV336ExitConsumer:" +
                    (probe.LearningV336ExitConsumerContinuitySource ?? "unknown");
                probe.ExitAuthorityFollowPathStatus = NavMeshPathStatus.PathComplete.ToString();
                prewarmStatus = NavMeshPathStatus.PathComplete;
                WriteEvent("learningV336ExitConsumerContinuityAdoptedByFollowHandoff", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    target = Vec(probe.ExitAuthorityFollowTarget),
                    source = probe.ExitAuthorityFollowPathSource,
                    action = "reuseExistingMoverProducerNoReplacement"
                });
            }
            else
            {
                if ((!learningV373ConsumerMoverEpochReady))
                {
                    WriteEvent("learningV373ExitConsumerContinuityAdoptionRejectedStaleMoverEpoch", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        target = IsFinite(probe.LearningV336ExitConsumerContinuityTarget)
                            ? (object)Vec(probe.LearningV336ExitConsumerContinuityTarget)
                            : null,
                        pendingSourceEdgeId = learningV373PendingHandoffEpoch?.SourceEdgeId ?? 0,
                        action = "doNotReusePathCompleteProducerWhoseNativeOriginStillBelongsToPreviousPhysicalEpoch"
                    });
                    // Keep Traversal ownership. A global Follow target is not a valid substitute for
                    // an unresolved traversal-local consumer epoch; doing so recreated the same
                    // semantic split through a different producer.
                    prewarmStatus = NavMeshPathStatus.PathInvalid;
                }
                else
                {
                    // CompileFix26 fallback: do not wait for a later FollowAction tick after traversal
                    // has proved a stable far-side body. Install the first ordinary NavMesh target now.
                    prewarmStatus = PrimeExitAuthorityFollowPath(probe, "handoffBegin");
                }
            }
            if ((prewarmStatus == NavMeshPathStatus.PathInvalid) &&
                probe.ExitAuthorityTopologyRejoinConfirmed &&
                probe.ExitAuthorityFollowPathRejected)
            {
                WriteEvent("learningV323ExitAuthorityRejectedPathKnownDuringHandoff", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    pathLength = probe.ExitAuthorityFollowRejectedPathLength,
                    detourRatio = probe.ExitAuthorityFollowRejectedDetourRatio,
                    topologyConfirmed = true,
                    reason = "directLeaderPathSynchronouslyRejected",
                    action = "keepValidationReleaseWithoutRejectGrace"
                });
            }
        }

        private static void CommitUnifiedTraversalSuccess(ProbeRuntime probe, string reason)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            LearnedTraversalCommitment commitment = null;
            TryGetLearnedCommitmentForProbe(probe, out commitment);
            TraversalCompletionMode completionMode = GetTraversalCompletionMode(probe, reason);
            bool learningV348PhysicalRouteCompletion = completionMode != TraversalCompletionMode.TeleportFallback &&
                !probe.TraversalTeleportAttempted && !probe.TeleportFallbackUsed;
            bool learningV410CleanSuccessContinuity =
                (learningV348PhysicalRouteCompletion);

            if (learningV410CleanSuccessContinuity)
            {
                // A clean traversal success is a movement-consumer boundary, not a locomotion stop.
                // Restore transient collision/animation leases but keep the current movement input
                // alive until the already-ordered RouteMission successor or Follow consumer writes.
                RestoreAssistedObstacleCollisionLease(probe, "learningV410CleanSuccessHandoff");
                RestoreAssistedTraversalAnimation(probe);
                if (probe.Bot?.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-780427F08284",@probe?.Bot,false);
                }
            }
            else
            {
                RestoreProbeInput(probe);
                if (probe.Bot?.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-84873ABB726D",@probe?.Bot,false);
                }
            }

            int completedEdgeId = probe.LearnedEdgeId;
            bool zeroShotTransfer = IsLearningV319TransientSkillTransfer(commitment);
            bool learningV320DownstreamZeroShotHandoff =
                (probe.LearningV320DownstreamZeroShotHandoffPending) &&
                string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase);
            if (probe.LearnedEdgeId > 0)
            {
                if (zeroShotTransfer)
                {
                    RecordLearningV322ZeroShotTemplateEvidence(
                        probe, commitment, true, completionMode, reason ?? "verifiedStableExit");
                    // The template edge is read-only evidence. A zero-shot instance may become
                    // persistent only after this new geometry itself earns retainable Native proof.
                    // Assisted/recovery success remains transient and does not mutate template
                    // experience, success counters, failure counters, or geometry.
                    if (TryPromoteLearningV319TransientSkillInstance(
                            probe, commitment, completionMode, reason, out int promotedEdgeId))
                    {
                        completedEdgeId = promotedEdgeId;
                        RecordTraversalExperience(
                            probe, true, completionMode, reason, edgeIdOverride: promotedEdgeId);
                    }
                    else
                    {
                        completedEdgeId = 0;
                        EmitLearningV322TraversalAttemptSummary(
                            probe, true, completionMode, reason ?? "verifiedStableExit", commitment.SkillTemplateEdgeId);
                        WriteEvent("learningV319ZeroShotCompletionNotPersisted", probe.Bot, new
                        {
                            templateEdgeId = commitment.SkillTemplateEdgeId,
                            kind = commitment.Kind,
                            completionMode = completionMode.ToString(),
                            reason = reason ?? string.Empty,
                            retainedNative = false,
                            templateExperienceUnchanged = true
                        });
                    }
                }
                else
                {
                    RecordTraversalExperience(probe, true, completionMode, reason);
                    MarkLearnedTraversalEdgeSuccess(probe.LearnedEdgeId, completionMode, probe);
                }

                if (zeroShotTransfer && learningV348PhysicalRouteCompletion)
                {
                    TryCommitLearningV431EquivalentLocalBarrierSelfRescueSuccess(
                        probe.Bot, probe, commitment, completionMode, reason);
                }

                if (commitment != null && learningV348PhysicalRouteCompletion)
                {
                    if (completedEdgeId > 0)
                    {
                        RegisterRecentTraversalCompletion(probe.Bot, completedEdgeId, commitment,
                            "exitAuthorityCommitAccepted", completionMode,
                            probe.LearningV322AttemptId, probe);
                    }
                    PostTraversalEntryQuarantines[probe.Bot.ProfileId] = new PostTraversalEntryQuarantine
                    {
                        EdgeId = completedEdgeId,
                        Entry = commitment.Entry,
                        Exit = commitment.Exit,
                        ExpiresAt = Time.time + ProbePostTraversalEntryQuarantineSeconds
                    };
                }
            }

            bool learningV355RecoveryExecutionFrontierRetired = false;
            string learningV355RecoveryFrontierDisposition = "notApplicable";
            bool learningV382RouteBoundTransient =
                (zeroShotTransfer) &&
                commitment != null && commitment.LearningV382RouteBoundTransientNativeSkill;
            if ((!zeroShotTransfer || learningV382RouteBoundTransient) && learningV348PhysicalRouteCompletion)
            {
                // A route-bound V3.82 transient keeps the template edge read-only, but it still
                // belongs to this authored episode/chain. Physical Native completion therefore
                // consumes the authored route identity even though persistent skill credit goes
                // only to the promoted directional instance.
                MarkFollowerTraversalEpisodeCompleted(probe, probe.TraversalEpisodeId, probe.LearnedEdgeId, probe.MovementWriterGeneration);
                CompleteCompositeWalkThroughEpisodes(probe, completionMode);
                if (learningV382RouteBoundTransient)
                {
                    WriteEvent("learningV382RouteBoundTransientRouteIdentityConsumed", probe.Bot, new
                    {
                        episodeId = probe.TraversalEpisodeId,
                        chainId = probe.TraversalChainId,
                        executionEdgeId = probe.LearnedEdgeId,
                        templateEdgeId = commitment.SkillTemplateEdgeId,
                        completionMode = completionMode.ToString(),
                        templatePersistentSuccessChanged = false,
                        action = "physicalNativeSuccessAdvancesAuthoredRouteWithoutCreditingTemplateSkill"
                    });
                }
            }
            else if ((!zeroShotTransfer))
            {
                learningV355RecoveryExecutionFrontierRetired =
                    RetireLearningV355ValidatedRecoveryExecutionDebt(
                        probe, completionMode, out learningV355RecoveryFrontierDisposition);
                WriteEvent("learningV348TeleportRecoveryRouteTruthPreserved", probe.Bot, new
                {
                    episodeId = probe.TraversalEpisodeId,
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind,
                    completionMode = completionMode.ToString(),
                    traversalTeleportAttempted = probe.TraversalTeleportAttempted,
                    teleportFallbackUsed = probe.TeleportFallbackUsed,
                    traversalSuccessRecorded = false,
                    routeCursorAdvanced = false,
                    executionFrontierRetired = learningV355RecoveryExecutionFrontierRetired,
                    executionFrontierDisposition = learningV355RecoveryFrontierDisposition,
                    action = learningV355RecoveryExecutionFrontierRetired
                        ? "preserveSemanticTruthRetireValidatedExecutionDebt"
                        : "replanFromActualFollowerPhysicalEpoch"
                });
            }

            WriteEvent("exitAuthorityCommitAccepted", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                reason,
                completionMode = completionMode.ToString(),
                anchor = Vec(probe.ExitAuthorityAnchor),
                position = probe.Player != null ? Vec(probe.Player.Position) : null,
                rebaseAttempts = probe.ExitAuthorityRebaseAttempts,
                stableSamples = probe.ExitAuthorityStableSamples
            });

            WriteEvent("traversalVerifiedCompleted", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                reason,
                completionMode = completionMode.ToString(),
                position = probe.Player != null ? Vec(probe.Player.Position) : null,
                verifyTarget = Vec(probe.TraversalVerifyTarget),
                authorityCommitted = true
            });
            EmitLearningV346PhysicalNavigationEpochSnapshot(probe, "exitConsumerHandoffAccepted");
            ClearLearnedTraversalCommitment(probe.Bot, probe.LearnedEdgeId, "exitAuthorityCommitAccepted");
            bool nextTraversalPreloaded = FollowerCapabilityHelperRules.CommitUnifiedTraversalSuccess_nextTraversalPreloaded_059458A1_1(zeroShotTransfer,learningV382RouteBoundTransient,learningV348PhysicalRouteCompletion,learningV355RecoveryExecutionFrontierRetired,learningV320DownstreamZeroShotHandoff) && TryPreloadNextTraversalChainCommitment(
                    probe.Bot, probe.TraversalEpisodeId, probe.LearnedEdgeId);

            if ((probe.Bot != null) && probe.Player != null)
            {
                bool learningV410RouteSuccessor = TryGetLearningV410CurrentRouteSuccessorAfterProbeNoMutation(
                    probe, out FollowerRouteMission learningV410SuccessorMission,
                    out FollowerRouteMissionStep learningV410SuccessorStep);
                bool learningV410PrewarmedFollowConsumer = probe.ExitAuthorityFollowPathObserved &&
                    string.Equals(probe.ExitAuthorityFollowPathStatus, NavMeshPathStatus.PathComplete.ToString(),
                        StringComparison.OrdinalIgnoreCase);
                bool learningV410PreserveCleanProducer = learningV410CleanSuccessContinuity &&
                    (learningV410RouteSuccessor || learningV410PrewarmedFollowConsumer ||
                     probe.ExitAuthorityFollowHandoffActive || probe.ExitAuthorityFollowPathRejected);

                if (learningV410PreserveCleanProducer)
                {
                    WriteEvent("learningV410CleanSuccessProducerPreserved", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        episodeId = probe.TraversalEpisodeId,
                        kind = probe.TraversalKind,
                        position = Vec(probe.Player.Position),
                        routeSuccessor = learningV410RouteSuccessor,
                        successorMissionId = learningV410SuccessorMission?.MissionId ?? 0,
                        successorStepIndex = learningV410SuccessorMission?.CurrentStepIndex ?? -1,
                        successorEdgeId = learningV410SuccessorStep?.EdgeId ?? 0,
                        successorKind = learningV410SuccessorStep?.Kind ?? string.Empty,
                        prewarmedFollowConsumer = learningV410PrewarmedFollowConsumer,
                        followPathRejected = probe.ExitAuthorityFollowPathRejected,
                        followHandoffActive = probe.ExitAuthorityFollowHandoffActive,
                        movementGeneration = probe.MovementWriterGeneration,
                        stopMoveCalled = false,
                        staleMoverHardRetired = false,
                        traversalSuccessRecorded = true,
                        persistentLearningChanged = false,
                        action = learningV410RouteSuccessor
                            ? "retireOnlyCompletedActionNodeKeepSameRouteMovementProducerAlive"
                            : "terminalSuccessKeepsLocomotionUntilFollowConsumerClaimsMovement"
                    });
                }
                else
                {
                    bool moverRebased = TryRetireNativeMoverPathAtCurrentBody(
                        probe.Bot, "traversalConsumerHandoff", out string moverRebaseDetail);
                    WriteEvent("learningV351TraversalStaleMoverRetired", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        position = Vec(probe.Player.Position),
                        rebased = moverRebased,
                        detail = moverRebaseDetail,
                        action = "retirePreTraversalNativePathBeforeConsumerOwnershipNoRelocationWriter"
                    });
                }
            }

            // The V3.19 zero-shot producer correctly refuses to start while the current probe owns
            // movement. Release this completed Jump first; only then instantiate the next unknown
            // gap. This preserves exactly-once current-edge bookkeeping and keeps the template
            // read-only until the next geometry earns physical Native proof.
            DetachProbeStateHandler(probe);
            UnregisterActiveProbe(probe);

            bool learningV320ZeroShotCommitted = false;
            string learningV320ZeroShotSource = string.Empty;
            if (learningV320DownstreamZeroShotHandoff)
            {
                Player leader = FollowerEnvironment.LocalPlayer;
                if (IsLivePlayer(leader))
                {
                    string learningV322ProfileId = probe.Bot?.ProfileId ?? string.Empty;
                    if ((probe.LearningV322AttemptId > 0) &&
                        !string.IsNullOrEmpty(learningV322ProfileId))
                    {
                        LearningV322PendingParentAttemptByProfile[learningV322ProfileId] = probe.LearningV322AttemptId;
                    }
                    learningV320ZeroShotCommitted = TryBeginLearningV319ZeroShotTraversalRecovery(
                        probe.Bot,
                        leader.Position,
                        "learningV320PhysicalFarSideHandoff",
                        out learningV320ZeroShotSource);
                    if (!learningV320ZeroShotCommitted && !string.IsNullOrEmpty(learningV322ProfileId))
                    {
                        LearningV322PendingParentAttemptByProfile.Remove(learningV322ProfileId);
                    }
                }

                WriteEvent(
                    learningV320ZeroShotCommitted
                        ? "learningV320PhysicalFarSideZeroShotHandoffCommitted"
                        : "learningV320PhysicalFarSideZeroShotHandoffDeferred",
                    probe.Bot,
                    new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        gapFrom = Vec(probe.LearningV320DownstreamGapFrom),
                        gapTo = Vec(probe.LearningV320DownstreamGapTo),
                        gapSegmentIndex = probe.LearningV320DownstreamGapSegmentIndex,
                        gapReason = probe.LearningV320DownstreamGapReason ?? string.Empty,
                        zeroShotSource = learningV320ZeroShotSource ?? string.Empty,
                        committed = learningV320ZeroShotCommitted,
                        legacyTeleportUsed = probe.TraversalTeleportAttempted || probe.TeleportFallbackUsed
                    });
            }

            if (!nextTraversalPreloaded && !learningV320ZeroShotCommitted)
            {
                ArmPostTraversalChaseLease(probe);
            }
        }

        private static bool PrepareProbeForTeleportCommit(ProbeRuntime probe, string source)
        {
            if (probe == null)
            {
                return false;
            }
            // Fail closed at issuance; a stale probe cannot launch an unowned teleport.
            probe.TeleportWriterGeneration = 0;
            long preparedTeleportGeneration = ResetFollowerMovementAuthorityForTeleport(
                probe.Bot, preserveRouteMission: true, preserveActiveCommitment: true, reason: "traversal:" + source);
            if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                probe.Bot, FollowerMovementWriterAuthority.WriterDomain.Teleport, preparedTeleportGeneration,
                out FollowerMovementWriterAuthority.WriteScope preparedTeleportScope, out string teleportTicketReason))
            {
                WriteEvent("v2ProbeTeleportOriginRejected", probe.Bot, new
                {
                    reason = teleportTicketReason,
                    originGeneration = preparedTeleportGeneration,
                    action = "rejectBeforeTeleportPreparationMutation"
                });
                return false;
            }
            probe.MovementWriterGeneration = preparedTeleportGeneration;
            probe.TeleportWriterGeneration = preparedTeleportGeneration;
            using (preparedTeleportScope)
            {
            RestoreAssistedObstacleCollisionLease(probe, "teleportCommit");
            RestoreAssistedTraversalAnimation(probe);
            try
            {
                if (probe.Player?.MovementContext != null)
                {
                    probe.Player.SetPlayerInputDirection("R1-5013A2AB675F",@probe?.Bot,Vector2.zero);
                    probe.Player.MovementContext.SetMovementContextMovementDirection("R1-464CA07A8269",@probe?.Bot,Vector2.zero);
                    if (probe.InjectedNativeVaultAttempted)
                    {
                        // Cancel any pending animator trigger before arming teleport. Otherwise a
                        // delayed ClimbOver transition can start after the teleport commit and write
                        // root motion from the old traversal transaction back into the new position.
                        probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoVault("R1-2DE211E46BE0",@probe?.Bot,false);
                        probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoClimb("R1-A062CDE045A2",@probe?.Bot,false);
                    }
                    probe.Player.MovementContext.TryMovementContextApplyApproachMotion("R1-24E7B8AF4C23",@probe?.Bot,Vector3.zero,Mathf.Max(0.001f, Time.deltaTime));
                }
            }
            catch
            {
            }
            try
            {
                probe.Bot?.Mover?.BotMoverStop("R1-995F3B3483F8",@probe?.Bot);
                probe.Bot?.BotOwnerStopMove("R1-62429AF9DF87",@probe?.Bot);
                if (probe.Bot?.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-F3152EF19DAC",@probe?.Bot,true);
                    probe.Bot.Mover.BotMoverSprint("R1-B639F0792DD5",@probe?.Bot,false,false);
                }
                probe.Bot?.GoToSomePointData?.BotGoToPointDataSetPoint("R1-3EC0248BEB4D",@probe?.Bot,probe.Bot.Position);
                probe.Bot?.GoToSomePointData?.BotGoToPointDataUpdateToGo("R1-A29CA663EDEE",@probe?.Bot,false);
            }
            catch
            {
            }
            probe.ExclusiveMoverGate = true;
            probe.PendingTeleportLastObservedPosition = probe.Player != null ? probe.Player.Position : Vector3.zero;
            probe.PendingTeleportStableSamples = 0;
            WriteEvent("traversalTeleportCommitPrepared", probe.Bot, new
            {
                source,
                state = probe.Player?.CurrentStateName.ToString(),
                position = probe.Player != null ? Vec(probe.Player.Position) : null
            });
            }
            return true;
        }

        private static void RestoreTraversalMovementAuthorityAfterTeleportAttempt(ProbeRuntime probe, string reason)
        {
            if (probe?.Bot == null)
            {
                return;
            }

            long issuedTeleportOrigin = probe.TeleportWriterGeneration;
            if (!FollowerMovementWriterAuthority.TransitionTeleportToFollowExact(
                probe.Bot, issuedTeleportOrigin, "traversalTeleportComplete:" + (reason ?? "unknown")))
            {
                WriteEvent("v2TeleportRetirementOriginRejected", probe.Bot, new
                {
                    reason = reason ?? "unknown",
                    originGeneration = issuedTeleportOrigin,
                    source = "probeTeleportRestore",
                    action = "staleTeleportCallbackCannotRecreateTraversalOwner"
                });
                return;
            }
            probe.TeleportWriterGeneration = 0;
            if(!IsActiveProbe(probe))
            {
                ArmFollowReacquireAfterAuthorityReset(probe.Bot,"retiredProbeTeleportAttempt:"+reason);
                WriteEvent("capabilityRetiredProbeTeleportRemainsFollow",probe.Bot,new{reason,nativeSuccessRecorded=false});
                return;
            }
            probe.MovementWriterGeneration = FollowerMovementWriterAuthority.BeginTraversal(
                probe.Bot,
                $"traversalAfterTeleport edge={probe.LearnedEdgeId} chain={probe.TraversalChainId} reason={reason ?? "unknown"}");
            RebaseLearningV375PersistentRouteTransactionAfterRecovery(
                probe.Bot, probe.TraversalChainId, probe.MovementWriterGeneration,
                probe.Player?.Position ?? probe.Bot.Position,
                "traversalAfterTeleport:" + (reason ?? "unknown"));
            WriteEvent("traversalMovementAuthorityRestoredAfterTeleport", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                chainId = probe.TraversalChainId,
                movementGeneration = probe.MovementWriterGeneration,
                reason = reason ?? "unknown"
            });
        }

        private static bool EnsureLearningV328TraversalAuthorityBeforeVerify(
            ProbeRuntime probe, string reason)
        {
            if (probe?.Bot == null)
            {
                return false;
            }

            FollowerMovementWriterAuthority.WriterDomain owner;
            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(probe.Bot, out owner);
            if (owner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                generation > 0 && generation == probe.MovementWriterGeneration)
            {
                return true;
            }

            if (owner != FollowerMovementWriterAuthority.WriterDomain.Teleport)
            {
                WriteEvent("learningV328TraversalVerifyAuthorityHandbackRejected", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    stage = probe.Stage.ToString(),
                    reason = reason ?? "unknown",
                    currentOwner = owner.ToString(),
                    currentGeneration = generation,
                    probeGeneration = probe.MovementWriterGeneration
                });
                return false;
            }

            RestoreTraversalMovementAuthorityAfterTeleportAttempt(
                probe, "learningV328NoOpTeleportHandback:" + (reason ?? "unknown"));
            long restoredGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(probe.Bot, out owner);
            bool restored = owner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                            restoredGeneration > 0 && restoredGeneration == probe.MovementWriterGeneration;
            WriteEvent("learningV328TeleportNoOpTraversalAuthorityHandback", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                stage = probe.Stage.ToString(),
                reason = reason ?? "unknown",
                restored,
                currentOwner = owner.ToString(),
                currentGeneration = restoredGeneration,
                probeGeneration = probe.MovementWriterGeneration
            });
            return restored;
        }

        private static void UpdateDeferredTraversalTeleport(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Player?.MovementContext == null)
            {
                return;
            }

            try
            {
                probe.Player.SetPlayerInputDirection("R1-1D9CDD516C5C",@probe?.Bot,Vector2.zero);
                probe.Player.MovementContext.SetMovementContextMovementDirection("R1-096911B368A2",@probe?.Bot,Vector2.zero);
                probe.Player.MovementContext.TryMovementContextApplyApproachMotion("R1-DFE7C9EEC341",@probe?.Bot,Vector3.zero,Mathf.Max(0.001f, Time.deltaTime));
                probe.Bot?.Mover?.BotMoverStop("R1-494917D1B0C6",@probe?.Bot);
                probe.Bot?.BotOwnerStopMove("R1-3BAEF603B74E",@probe?.Bot);
                if (probe.Bot?.Mover != null)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-125E32FA7E0C",@probe?.Bot,true);
                    probe.Bot.Mover.BotMoverSprint("R1-9FA999447E70",@probe?.Bot,false,false);
                }
            }
            catch
            {
            }

            float elapsed = Time.time - probe.PendingTeleportRequestedAt;
            Vector3 currentPosition = probe.Player.Position;
            float observedDelta = Vector3.Distance(currentPosition, probe.PendingTeleportLastObservedPosition);
            probe.PendingTeleportLastObservedPosition = currentPosition;
            if (observedDelta <= TeleportQuiescenceSampleDistance)
            {
                probe.PendingTeleportStableSamples++;
            }
            else
            {
                probe.PendingTeleportStableSamples = 0;
            }

            bool stateReleased = !IsProbeTraversalState(probe.Player.CurrentStateName);
            bool quiescent = probe.PendingTeleportStableSamples >= TeleportQuiescenceStableSamplesRequired;
            bool timedOut = elapsed >= TeleportQuiescenceMaxWaitSeconds;
            if (!quiescent && !timedOut)
            {
                return;
            }

            string source = string.IsNullOrWhiteSpace(probe.PendingTeleportSource)
                ? "deferredTraversalFallback"
                : probe.PendingTeleportSource;
            WriteEvent("traversalTeleportQuiescenceReady", probe.Bot, new
            {
                source,
                state = probe.Player.CurrentStateName.ToString(),
                stateReleased,
                quiescent,
                timedOut,
                stableSamples = probe.PendingTeleportStableSamples,
                observedDelta,
                waited = elapsed
            });
            probe.PendingTeleportSource = null;
            probe.PendingTeleportRequestedAt = 0f;
            if (!TryTeleportPlayerValidatedTraversalAtExit(probe, source, false))
            {
                EnterSafetyHold(probe, "deferred traversal teleport could not commit to a validated exit");
            }
        }

        // CompileFix42 removed TryDeferTraversalTeleportToRouteRecovery. Active traversal
        // failures never re-enter RouteMission; they remain inside the monotonic step pipeline.

        private static bool TryGetRouteMissionSuccessorRecoveryTarget(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            out Vector3 target)
        {
            target = default;
            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            if (probe == null || commitment == null || string.IsNullOrEmpty(profileId) ||
                !FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) ||
                mission == null || mission.Steps == null || mission.Steps.Count < 2)
            {
                return false;
            }

            int currentIndex = commitment.RouteMissionStepIndex >= 0
                ? commitment.RouteMissionStepIndex
                : mission.CurrentStepIndex;
            if (currentIndex < 0 || currentIndex >= mission.Steps.Count ||
                mission.Steps[currentIndex]?.EdgeId != commitment.EdgeId)
            {
                currentIndex = mission.Steps.FindIndex(step => step != null && step.EdgeId == commitment.EdgeId);
            }
            int nextIndex = currentIndex + 1;
            if (currentIndex < 0 || nextIndex >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep next = mission.Steps[nextIndex];
            if (next == null || !IsFinite(next.Entry) ||
                (commitment.ChainId > 0 && next.ChainId > 0 && next.ChainId != commitment.ChainId))
            {
                return false;
            }

            float distance = probe.Player != null ? Vector3.Distance(probe.Player.Position, next.Entry) : float.MaxValue;
            if (!IsFinite(distance) || distance > 4.5f)
            {
                return false;
            }

            target = next.Entry;
            return true;
        }

        private static bool TryTeleportPlayerValidatedTraversalAtExit(ProbeRuntime probe, string source, bool allowDeferredStateRelease = true)
        {
            // A live route may not destroy its probe and then defer work to that retired probe.
            if(TryRequestCapabilityFullRouteRetry(probe,"exitRecoveryRequested:"+source,true))return true;
            if (probe == null || !IsLiveBot(probe.Bot) || !IsPlayerValidatedTraversalProbe(probe) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) || commitment == null)
            {
                return false;
            }

            // RC53 final safety gate: no recovery caller may reinterpret a real
            // but INCOMPLETE native Climb back on the low entry floor as permission
            // to teleport onto the upper exit. This checks current physical body
            // height and native history, not raw XZ projection or persistent credit.
            if (string.Equals(commitment.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                probe.Player != null && probe.InjectedNativeVaultAttempted &&
                (probe.NativeStateObserved || probe.NativeTraversalStarted || probe.SawVaultState) &&
                IsEffectivelySupportedForProbe(probe.Bot, probe.Player))
            {
                Vector3 rc53RawEntry = IsFinite(commitment.RawEntry)
                    ? commitment.RawEntry : commitment.Entry;
                Vector3 rc53RawExit = IsFinite(commitment.RawExit)
                    ? commitment.RawExit : commitment.Exit;
                if (rc53RawExit.y - rc53RawEntry.y >= 0.65f &&
                    probe.Player.Position.y <= rc53RawEntry.y + 0.35f &&
                    probe.Player.Position.y <= rc53RawExit.y - 0.55f &&
                    GetPlanarDistance(probe.Player.Position, rc53RawEntry) <= 1.50f)
                {
                    WriteEvent("v2rc53LowerFloorClimbTeleportSafetyGate", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId, source = source ?? string.Empty,
                        body = Vec(probe.Player.Position), entry = Vec(rc53RawEntry),
                        exit = Vec(rc53RawExit), teleportUsed = false,
                        nativeSuccessRecorded = false, bodyRelocated = false,
                        action = "endFailedNativeAttemptFromCurrentBodyNeverForgeUpperExitTeleport"
                    });
                    FinalizeUnifiedTraversalFailure(probe, "v2rc53RejectedUpperExitTeleportOnLowerEntryFloor");
                    return true;
                }
            }

            if (IsLearningV319TransientSkillTransfer(commitment))
            {
                string retryKey = MakeLearningV319ZeroShotTemplateRetryKey(
                    probe.Bot.ProfileId ?? string.Empty, commitment.SkillTemplateEdgeId > 0 ? commitment.SkillTemplateEdgeId : commitment.EdgeId);
                LearningV319ZeroShotTemplateRetryAfter[retryKey] = Time.time + LearningV319ZeroShotTemplateRetrySeconds;
                WriteEvent("learningV319ZeroShotTeleportSuppressed", probe.Bot, new
                {
                    templateEdgeId = commitment.SkillTemplateEdgeId,
                    kind = commitment.Kind,
                    source = source ?? string.Empty,
                    nearFrontier = Vec(commitment.RawEntry),
                    farFrontier = Vec(commitment.RawExit),
                    reason = "predictedFarSideIsNotTeleportAuthority"
                });
                return false;
            }

            if (FollowerStateAuthorityCoordinator.IsLocomotionFaulted(
                    probe.Bot,
                    out float locomotionFaultRemaining,
                    out string locomotionFaultReason))
            {
                // CompileFix55 restores the CompileFix51 recovery contract: locomotion poisoning is
                // a reason to escalate to the validated traversal teleport, not a reason to suppress
                // it forever. Make one best-effort pre-teleport hard repair, but continue to
                // FollowerSafeTeleport even if EFT remains in JumpLanding/Transition. SafeTeleport
                // performs the same hard repair again after the physical rebase.
                bool preTeleportLocomotionRecovered = TryHardRecoverCapabilityProbeLocomotion(
                    probe,
                    "traversalTeleportPreRecovery:" + (source ?? "unknown"),
                    out string preTeleportLocomotionDetail);
                if (preTeleportLocomotionRecovered)
                {
                    FollowerStateAuthorityCoordinator.ClearLocomotionFault(probe.Bot, "traversalTeleportPreRecovery");
                }
                WriteEvent("traversalTeleportLocomotionFaultEscalated", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                    source,
                    stage = probe.Stage.ToString(),
                    remaining = locomotionFaultRemaining,
                    reason = locomotionFaultReason,
                    preTeleportLocomotionRecovered,
                    preTeleportLocomotionDetail,
                    state = probe.Player?.CurrentStateName.ToString(),
                    recoveryContract = "validatedTeleportStillAllowed"
                });
            }

            // CompileFix42 monotonic failure pipeline: an active player-demonstrated traversal
            // never hands a failed step back to RouteMission/NavMesh recovery. Native/direct
            // execution escalates to the existing Assist executor first; once that executor is
            // exhausted, this method is the single final leaf: teleport through THIS traversal,
            // verify its far side, and continue the same chain cursor.

            Vector3 requestedExit;
            string targetSource;
            Vector3 successorRecoveryTarget = default;
            bool haveWalkThroughSuccessor =
                string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                TryGetRouteMissionSuccessorRecoveryTarget(probe, commitment, out successorRecoveryTarget);
            if (haveWalkThroughSuccessor)
            {
                requestedExit = successorRecoveryTarget;
                targetSource = "routeMissionSuccessorEntry";
            }
            else
            {
            bool bridgeKindForTeleport = IsLearningV340DownstreamBridgeKind(commitment.Kind);
            if (commitment.HasSettledExit && IsFinite(commitment.SettledExit) &&
                IsCredibleSettledExit(commitment.Kind, commitment.RawEntry, commitment.RawExit, commitment.SettledExit) &&
                (!bridgeKindForTeleport || HasTraversalDownstreamConnectivity(
                    probe, commitment, commitment.SettledExit, out _, out _)))
            {
                requestedExit = commitment.SettledExit;
                targetSource = "settledExit";
            }
            else if (TryResolveUnifiedTraversalEgressTarget(probe, commitment, out Vector3 egressTarget, out string egressSource))
            {
                requestedExit = egressTarget;
                targetSource = egressSource;
            }
            else
            {
                requestedExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
                targetSource = "rawExit";
            }
            }

            if (!IsFinite(requestedExit))
            {
                return false;
            }

            float directExitDistance = Vector3.Distance(probe.Player.Position, requestedExit);
            if (directExitDistance <= 0.30f)
            {
                // CompileFix53 recognized that no physical teleport is required here, but it then
                // re-entered Verify and could re-arm the same recovery forever.  V3.66 treats this
                // as the same terminal recovery transaction as a committed bounded teleport: retire
                // only execution debt, preserve semantic truth, and never mint clean/native credit.
                probe.RecoveryExitAlreadySatisfied = true;
                probe.TeleportFallbackUsed = true;
                probe.TraversalTeleportAttempted = true;
                probe.TraversalVerifyTarget = requestedExit;
                WriteEvent("traversalRecoveryExitAlreadySatisfied", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    source,
                    targetSource,
                    position = Vec(probe.Player.Position),
                    requestedExit = Vec(requestedExit),
                    directExitDistance
                });
                {
                    WriteEvent("learningV366TerminalRecoveryExitAlreadySatisfied", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        kind = commitment.Kind,
                        source = source ?? string.Empty,
                        targetSource,
                        directExitDistance,
                        completionMode = TraversalCompletionMode.TeleportFallback.ToString(),
                        persistentSemanticMutation = false,
                        action = "terminalizeWithoutReenteringVerify"
                    });
                    CommitUnifiedTraversalSuccess(
                        probe,
                        "learningV366TerminalRecoveryExitAlreadySatisfied:" + (source ?? "unknown"));
                    return true;
                }
                if ((!EnsureLearningV328TraversalAuthorityBeforeVerify(
                        probe, source + ":alreadyAtTarget")))
                {
                    WriteEvent("learningV328TeleportNoOpVerifySuppressedWithoutTraversalAuthority", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        kind = commitment.Kind,
                        source,
                        targetSource,
                        directExitDistance
                    });
                    return false;
                }
                BeginUnifiedTraversalVerify(probe, source + ":alreadyAtTarget");
                return true;
            }

            // v1.3.25 does not trust the animator state name as a movement-authority barrier.
            // Run/Sprint can still have residual root motion after a traversal abort. Neutralize
            // every PIT-controlled writer and require several low-delta samples before one bounded
            // authoritative teleport.
            if (allowDeferredStateRelease)
            {
                // Keep the original issued probe alive while gathering quiescence samples.
                // Destructive authority reset belongs only to the final, synchronous commit below.
                probe.PendingTeleportSource = source ?? "traversalFallback";
                probe.PendingTeleportRequestedAt = Time.time;
                probe.PendingTeleportStableSamples=0;
                probe.PendingTeleportLastObservedPosition=probe.Player.Position;
                TransitionProbeStage(probe, ProbeStage.TeleportArm);
                probe.StageStartedAt = Time.time;
                probe.TraversalVerifyMoving = false;
                probe.OwnershipLeaseExpiresAt = Mathf.Max(
                    probe.OwnershipLeaseExpiresAt,
                    Time.time + TeleportQuiescenceMaxWaitSeconds + TraversalOwnershipLeaseTeleportExtraSeconds);
                WriteEvent("traversalTeleportDeferredForQuiescence", probe.Bot, new
                {
                    source,
                    state = probe.Player.CurrentStateName.ToString(),
                    requestedExit = Vec(requestedExit),
                    directExitDistance,
                    maxWait = TeleportQuiescenceMaxWaitSeconds,
                    stableSamplesRequired = TeleportQuiescenceStableSamplesRequired
                });
                return true;
            }

            probe.TeleportFallbackUsed = true;
            probe.TraversalTeleportAttempted = true;
            // The bounded teleport transaction is unified even when validation rejects every
            // candidate. Mark this before validation so SafetyHold cannot recursively re-arm the
            // same rejected RawExit every ~40ms.
            probe.UnifiedTraversalFlow = true;
            probe.TraversalVerifyMoving = false;
            Vector3 from = probe.Player.Position;
            if (!PrepareProbeForTeleportCommit(probe, source))
            {
                return false;
            }
            string fallbackMode = "validatedFarSideFan";
            bool teleported = FollowerSafeTeleport.TryTeleportAcrossTraversalExit(
                probe.Bot,
                requestedExit,
                $"playerValidatedExit:{commitment.EdgeId}:{source}",
                out Vector3 crossedTo,
                allowAuthoredOffNavMesh: string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase),
                issuedTeleportGeneration: probe.TeleportWriterGeneration);
            if (!teleported)
            {
                RestoreTraversalMovementAuthorityAfterTeleportAttempt(
                    probe,
                    "playerValidatedExitRejected");
                WriteEvent("playerValidatedTraversalExitRejected", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    source,
                    targetSource,
                    from = Vec(from),
                    requestedExit = Vec(requestedExit),
                    directExitDistance
                });
                return false;
            }

            probe.TraversalTeleportCommitted = true;
            probe.UnifiedTraversalFlow = true;
            probe.TraversalVerifyTarget = crossedTo;

            WriteEvent("playerValidatedTraversalExitTeleport", probe.Bot, new
            {
                edgeId = commitment.EdgeId,
                kind = commitment.Kind,
                source,
                targetSource,
                fallbackMode,
                from = Vec(from),
                requestedExit = Vec(requestedExit),
                teleportedTo = Vec(crossedTo),
                directExitDistance,
                assistedReplayAttempted = probe.AssistedReplayAttempted,
                releaseDeferredUntilVerify = false
            });

            {
                // Recovery relocation has already established the new physical body epoch.  Hand
                // ownership back to Follow once, then terminalize the failed traversal transaction.
                // Do NOT BeginTraversal/Verify again: that was the source of the V365 ~1.25 s
                // teleport oscillation.  CommitUnifiedTraversalSuccess records TeleportFallback as
                // non-clean recovery and V3.48/V3.55 retire execution debt without changing semantic
                // or native-success truth.
                long recoveryTeleportOrigin = probe.TeleportWriterGeneration;
                if (!FollowerMovementWriterAuthority.TransitionTeleportToFollowExact(
                    probe.Bot, recoveryTeleportOrigin, "learningV366TerminalRecoveryCommitted"))
                {
                    WriteEvent("v2TeleportRetirementOriginRejected", probe.Bot, new
                    {
                        source = "terminalRecoveryCommitted",
                        originGeneration = recoveryTeleportOrigin,
                        edgeId = commitment.EdgeId,
                        action = "rejectStaleTerminalSuccessAndPreserveCurrentOwner"
                    });
                    return false;
                }
                probe.TeleportWriterGeneration = 0;
                WriteEvent("learningV366TerminalRecoveryCommitted", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    kind = commitment.Kind,
                    source = source ?? string.Empty,
                    targetSource,
                    from = Vec(from),
                    requestedExit = Vec(requestedExit),
                    teleportedTo = Vec(crossedTo),
                    completionMode = TraversalCompletionMode.TeleportFallback.ToString(),
                    restoreSameTraversalProbe = false,
                    persistentSemanticMutation = false,
                    action = "followOwnsRecoveredBodyTerminalizeTraversalTransaction"
                });
                CommitUnifiedTraversalSuccess(
                    probe,
                    "learningV366TerminalRecoveryCommitted:" + (source ?? "unknown"));
                return true;
            }

            RestoreTraversalMovementAuthorityAfterTeleportAttempt(
                probe,
                "playerValidatedExitCommitted");
            probe.OwnershipLeaseExpiresAt = Mathf.Max(
                probe.OwnershipLeaseExpiresAt,
                Time.time + TraversalOwnershipLeaseTeleportExtraSeconds + 0.75f);
            TransitionProbeStage(probe, ProbeStage.Verify);
            probe.StageStartedAt = Time.time;
            probe.TraversalVerifyStableSince = -1f;
            probe.TraversalVerifyLastPosition = crossedTo;
            probe.TraversalVerifyNextLogAt = Time.time;
            return true;
        }

        // RC104: TriggerNativeVaultScan lives in the shared native obstacle capability host.

        // RC104: TryTickNativeVaultScanner lives in the shared native obstacle capability host.


        private static bool TryGetFirstNonSelfRaycastHit(
            Player player,
            Vector3 origin,
            Vector3 direction,
            float maxDistance,
            out RaycastHit selected)
        {
            return TryGetFirstNonSelfRaycastHit(
                player,
                origin,
                direction,
                maxDistance,
                Physics.AllLayers,
                out selected);
        }

        private static bool TryGetFirstNonSelfRaycastHit(
            Player player,
            Vector3 origin,
            Vector3 direction,
            float maxDistance,
            int layerMask,
            out RaycastHit selected)
        {
            selected = default;
            {
                int hitCount = Physics.RaycastNonAlloc(
                    origin,
                    direction,
                    LearningV323RaycastHitBuffer,
                    maxDistance,
                    layerMask,
                    QueryTriggerInteraction.Ignore);
                if (hitCount <= 0)
                {
                    return false;
                }

                if (hitCount < LearningV323RaycastHitBuffer.Length)
                {
                    float bestDistance = float.MaxValue;
                    bool found = false;
                    for (int index = 0; index < hitCount; index++)
                    {
                        RaycastHit hit = LearningV323RaycastHitBuffer[index];
                        if (hit.collider == null || IsIgnoredTraversalCollider(player, hit.collider) ||
                            hit.distance >= bestDistance)
                        {
                            continue;
                        }

                        selected = hit;
                        bestDistance = hit.distance;
                        found = true;
                    }
                    return found;
                }

                if (ShouldEmitDiagnostic("learningV323RaycastNonAllocOverflow", null, 1.0f))
                {
                    WriteEvent("learningV323PhysicsQueryOverflowFallback", null, new
                    {
                        query = "Raycast",
                        capacity = LearningV323RaycastHitBuffer.Length,
                        maxDistance
                    });
                }
            }

            RaycastHit[] hits = Physics.RaycastAll(
                origin,
                direction,
                maxDistance,
                layerMask,
                QueryTriggerInteraction.Ignore);
            if (hits == null || hits.Length == 0)
            {
                return false;
            }

            float fallbackBestDistance = float.MaxValue;
            bool fallbackFound = false;
            for (int index = 0; index < hits.Length; index++)
            {
                RaycastHit hit = hits[index];
                if (hit.collider == null || IsIgnoredTraversalCollider(player, hit.collider) ||
                    hit.distance >= fallbackBestDistance)
                {
                    continue;
                }

                selected = hit;
                fallbackBestDistance = hit.distance;
                fallbackFound = true;
            }

            return fallbackFound;
        }

        private static bool TryGetFirstNonSelfCapsuleCastHit(
            Player player,
            Vector3 point1,
            Vector3 point2,
            float radius,
            Vector3 direction,
            float maxDistance,
            int layerMask,
            out RaycastHit selected)
        {
            selected = default;
            {
                int hitCount = Physics.CapsuleCastNonAlloc(
                    point1,
                    point2,
                    radius,
                    direction,
                    LearningV323CapsuleCastHitBuffer,
                    maxDistance,
                    layerMask,
                    QueryTriggerInteraction.Ignore);
                if (hitCount <= 0)
                {
                    return false;
                }

                if (hitCount < LearningV323CapsuleCastHitBuffer.Length)
                {
                    float bestDistance = float.MaxValue;
                    bool found = false;
                    for (int index = 0; index < hitCount; index++)
                    {
                        RaycastHit hit = LearningV323CapsuleCastHitBuffer[index];
                        if (hit.collider == null || IsIgnoredTraversalCollider(player, hit.collider) ||
                            hit.distance >= bestDistance)
                        {
                            continue;
                        }

                        selected = hit;
                        bestDistance = hit.distance;
                        found = true;
                    }
                    return found;
                }

                if (ShouldEmitDiagnostic("learningV323CapsuleCastNonAllocOverflow", null, 1.0f))
                {
                    WriteEvent("learningV323PhysicsQueryOverflowFallback", null, new
                    {
                        query = "CapsuleCast",
                        capacity = LearningV323CapsuleCastHitBuffer.Length,
                        maxDistance
                    });
                }
            }

            RaycastHit[] hits = Physics.CapsuleCastAll(
                point1,
                point2,
                radius,
                direction,
                maxDistance,
                layerMask,
                QueryTriggerInteraction.Ignore);
            if (hits == null || hits.Length == 0)
            {
                return false;
            }

            float fallbackBestDistance = float.MaxValue;
            bool fallbackFound = false;
            for (int index = 0; index < hits.Length; index++)
            {
                RaycastHit hit = hits[index];
                if (hit.collider == null || IsIgnoredTraversalCollider(player, hit.collider) ||
                    hit.distance >= fallbackBestDistance)
                {
                    continue;
                }

                selected = hit;
                fallbackBestDistance = hit.distance;
                fallbackFound = true;
            }

            return fallbackFound;
        }

        private static bool IsIgnoredTraversalCollider(Player player, Collider collider)
        {
            if (player == null || collider == null)
            {
                return false;
            }

            try
            {
                int colliderId = collider.GetInstanceID();
                if ((LearningV323TraversalColliderPlayerOwnershipCache.TryGetValue(colliderId, out bool cachedPlayerOwned)))
                {
                    return cachedPlayerOwned;
                }

                // EFT.Player.Transform is a BifacialTransform in SPT 4.0.13 and the inherited
                // Player.transform property is Obsolete(error: true), so do not use either for
                // Unity hierarchy comparison here. GetComponentInParent<Player>() already gives
                // the semantic check we need: ignore every collider owned by a player/bot, including
                // body parts, armor, weapons and attached equipment. V3.23 caches this stable
                // semantic per collider for the raid so first-use hierarchy walks are not repeated
                // for every precision floor/body probe.
                Player owner = collider.GetComponentInParent<Player>();
                bool playerOwned = owner != null;
                {
                    LearningV323TraversalColliderPlayerOwnershipCache[colliderId] = playerOwned;
                }
                return playerOwned;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryBeginSafeForwardHopFallback(ProbeRuntime probe, out string failure)
        {
            failure = string.Empty;
            if (probe?.Player?.MovementContext == null)
            {
                failure = "movement context unavailable";
                return false;
            }

            EFT.Vaulting.IVaultingParameters parameters = probe.Player.VaultingParameters;
            if (parameters == null)
            {
                failure = "vault parameters unavailable";
                return false;
            }

            float obstacleHeight;
            float obstacleLength;
            try
            {
                obstacleHeight = parameters.VaultingHeight;
                obstacleLength = parameters.VaultingLength;
            }
            catch (Exception ex)
            {
                failure = "vault parameter read failed: " + ex.GetType().Name;
                return false;
            }

            // Never jump on the scanner's characteristic "nothing useful ahead" result
            // (height≈0, length≈2m in the user's later failed probes). Require a plausible low
            // obstacle first so the fallback cannot become a blind cliff/window jump.
            if (obstacleHeight < ProbeHopMinObstacleHeight ||
                obstacleHeight > ProbeHopMaxObstacleHeight ||
                obstacleLength <= 0f ||
                obstacleLength > ProbeHopMaxObstacleLength)
            {
                failure = $"unsafe obstacle dimensions h={obstacleHeight:0.00} len={obstacleLength:0.00}";
                return false;
            }

            Vector3 forward = GetFlatDirection(probe.RequestedDirection);
            if (forward.sqrMagnitude < 0.5f)
            {
                failure = "invalid forward direction";
                return false;
            }

            // Cross-check the scanner with live physics so stale VaultingParameters cannot turn into
            // a blind hop. There must be a collider at low-body height, while a ray above the allowed
            // low-obstacle envelope must remain clear.
            Vector3 lowRayOrigin = probe.Player.Position + Vector3.up * 0.45f;
            if (!TryGetFirstNonSelfRaycastHit(
                    probe.Player,
                    lowRayOrigin,
                    forward,
                    Mathf.Min(0.95f, ProbeHopForwardDistance),
                    out RaycastHit obstacleHit))
            {
                failure = "no live low obstacle collider ahead";
                return false;
            }

            Vector3 highRayOrigin = probe.Player.Position + Vector3.up * (ProbeHopMaxObstacleHeight + 0.35f);
            if (TryGetFirstNonSelfRaycastHit(
                    probe.Player,
                    highRayOrigin,
                    forward,
                    Mathf.Min(0.95f, ProbeHopForwardDistance),
                    out RaycastHit highHit))
            {
                failure = $"obstacle is not safely low (upper ray hit '{highHit.collider?.name ?? "unknown"}')";
                return false;
            }

            Vector3 desiredLanding = probe.Player.Position + forward * ProbeHopForwardDistance;
            if (!NavMesh.SamplePosition(desiredLanding, out NavMeshHit landingHit, ProbeHopLandingSampleRadius, NavMesh.AllAreas))
            {
                failure = "no NavMesh at forward-hop landing";
                return false;
            }

            float verticalDelta = landingHit.position.y - probe.Player.Position.y;
            if (verticalDelta > ProbeHopMaxLandingRise || verticalDelta < -ProbeHopMaxLandingDrop)
            {
                failure = $"unsafe landing height delta {verticalDelta:0.00}m";
                return false;
            }

            // Require a real floor close to the sampled landing. The hop itself still uses EFT's
            // CharacterController through ApplyApproachMotion, so solid collision remains active.
            Vector3 rayOrigin = landingHit.position + Vector3.up * 1.25f;
            if (!TryGetFirstNonSelfRaycastHit(probe.Player, rayOrigin, Vector3.down, 2.5f, out RaycastHit floorHit) ||
                Mathf.Abs(floorHit.point.y - landingHit.position.y) > 0.65f)
            {
                failure = "landing floor validation failed";
                return false;
            }

            TransitionProbeStage(probe, ProbeStage.ForwardHop);
            probe.StageStartedAt = Time.time;
            probe.ExclusiveMoverGate = true;
            probe.TraversalKind = "ForwardHopFallback";
            probe.TriggerPosition = probe.Player.Position;
            probe.HopStartPosition = probe.Player.Position;
            probe.HopLandingPosition = landingHit.position;
            probe.Bot.BotOwnerStopMove("R1-E2E32D770D75",@probe?.Bot);
            HoldForwardInput(probe);

            WriteEvent("vaultProbeForwardHopStarted", probe.Bot, new
            {
                obstacleHeight,
                obstacleLength,
                obstacleCollider = obstacleHit.collider?.name,
                obstacleHitDistance = obstacleHit.distance,
                start = Vec(probe.HopStartPosition),
                landing = Vec(probe.HopLandingPosition),
                distance = Vector3.Distance(probe.HopStartPosition, probe.HopLandingPosition)
            });
            LogInfo($"native vault refused for {GetBotName(probe.Bot)}; guarded forward-hop fallback started");
            return true;
        }

        private static void UpdateForwardHopFallback(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Player?.MovementContext == null)
            {
                return;
            }

            float elapsed = Time.time - probe.StageStartedAt;
            float t = Mathf.Clamp01(elapsed / ProbeHopDuration);
            Vector3 linear = Vector3.Lerp(probe.HopStartPosition, probe.HopLandingPosition, t);
            float arc = Mathf.Sin(t * Mathf.PI) * ProbeHopArcHeight;
            Vector3 desired = linear + Vector3.up * arc;
            Vector3 motion = desired - probe.Player.Position;
            if (motion.magnitude > 0.35f)
            {
                motion = motion.normalized * 0.35f;
            }

            HoldForwardInput(probe);
            try
            {
                probe.Player.MovementContext.TryMovementContextApplyApproachMotion("R1-3574E64FBAF2",@probe?.Bot,motion,Mathf.Max(0.001f, Time.deltaTime));
            }
            catch (Exception ex)
            {
                EnterSafetyHold(probe, "forward-hop motion failed: " + ex.GetType().Name + ": " + ex.Message);
                return;
            }

            if (t < 1f)
            {
                return;
            }

            if (!TryGetSafeLandingNavMesh(probe.Player.Position, out NavMeshHit landingNav, out string landingFailure))
            {
                EnterSafetyHold(probe, "forward-hop ended off NavMesh: " + landingFailure);
                return;
            }

            float landingError = Vector3.Distance(probe.Player.Position, probe.HopLandingPosition);
            WriteEvent("vaultProbeForwardHopFinished", probe.Bot, new
            {
                landing = Vec(probe.Player.Position),
                target = Vec(probe.HopLandingPosition),
                landingError,
                navMesh = Vec(landingNav.position)
            });

            // A collision-blocked hop is not a traversal success; release the bot on its current safe
            // NavMesh instead of teleporting it through the obstacle.
            if (landingError > 0.85f)
            {
                if (!TryReanchorAndRelease(probe, landingNav.position, "forwardHopBlocked", out string blockedFailure))
                {
                    EnterSafetyHold(probe, blockedFailure);
                }
                return;
            }

            if (!TryReanchorAndRelease(probe, landingNav.position, "forwardHopCompleted", out string failure))
            {
                EnterSafetyHold(probe, failure);
            }
        }

        private static void OnProbeStateChanged(ProbeRuntime probe, EPlayerState previous, EPlayerState next)
        {
            if (!IsProbeLifecycleCurrent(probe)) return;
            if (probe == null || !IsActiveProbe(probe) || probe.Generation != raidGeneration)
            {
                return;
            }

            probe.LastState = next;
            WriteEvent("vaultProbeState", probe.Bot, new
            {
                previous = previous.ToString(),
                next = next.ToString(),
                stage = probe.Stage.ToString(),
                position = Vec(probe.Player.Position),
                grounded = probe.Player.MovementContext?.IsGrounded == true
            });

            if (probe.Stage == ProbeStage.AssistedReplay)
            {
                if ((IsProbeTraversalState(next)))
                {
                    List<string> recoveryActions = new List<string>();
                    TryInvokeOptionalBoolMethod(probe.Bot, probe.Player?.MovementContext, "PlayerAnimatorEnableJump", false, recoveryActions);
                    TryInvokeOptionalBoolMethod(probe.Bot, probe.Player?.MovementContext, "PlayerAnimatorEnableLanding", false, recoveryActions);
                    TryInvokeMovementStateTransition(probe.Bot, probe.Player?.MovementContext, EPlayerState.Run, recoveryActions);
                    TryInvokeMovementStateTransition(probe.Bot, probe.Player, EPlayerState.Run, recoveryActions, allowSignatureFallback: false);
                    probe.AssistedNativeOwned = false;
                    probe.AssistedNativeEnteredAt = -1f;
                    probe.AssistedNativeReleasedAt = Time.time;
                    HoldForwardInput(probe);
                    WriteEvent("learningV324AssistNativeStateSuppressed", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                        previous = previous.ToString(),
                        next = next.ToString(),
                        position = Vec(probe.Player.Position),
                        actions = recoveryActions.ToArray(),
                        action = "assistRetainsBodyAuthority"
                    });
                    return;
                }

                bool assistedVaultOrClimb =
                    string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind, "Vault", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind, "Climb", StringComparison.OrdinalIgnoreCase);
                if (assistedVaultOrClimb && IsProbeTraversalState(next))
                {
                    // CompileFix27: once EFT actually enters ClimbOver/ClimbUp/Vaulting*, native
                    // animation/locomotion owns the body. PIT must stop CharacterController.Move
                    // rather than fighting the native state with a second root-motion controller.
                    if (!probe.AssistedNativeOwned)
                    {
                        probe.AssistedNativeOwned = true;
                        probe.AssistedNativeEnteredAt = Time.time;
                        probe.NativeTraversalStarted = true;
                        probe.NativeStateObserved = true;
                        probe.SawVaultState = true;
                        probe.AssistedReplayLastObservedPosition = probe.Player.Position;
                        probe.AssistedReplayLastProgressAt = Time.time;
                        RestoreAssistedObstacleCollisionLease(probe, "nativeTraversalOwnershipEntered");
                        WriteEvent("assistedTraversalNativeOwnershipEntered", probe.Bot, new
                        {
                            state = next.ToString(),
                            kind = probe.TraversalKind,
                            position = Vec(probe.Player.Position)
                        });
                    }
                    return;
                }

                if (assistedVaultOrClimb && probe.AssistedNativeOwned &&
                    IsProbeTraversalState(previous) && !IsProbeTraversalState(next))
                {
                    probe.AssistedNativeReleasedAt = Time.time;
                    probe.AssistedNativeReleasePosition = probe.Player.Position;
                    WriteEvent("assistedTraversalNativeOwnershipReleased", probe.Bot, new
                    {
                        previous = previous.ToString(),
                        next = next.ToString(),
                        kind = probe.TraversalKind,
                        position = Vec(probe.Player.Position),
                        nativeOwnedSeconds = Time.time - probe.AssistedNativeEnteredAt
                    });
                }
                return;
            }

            if ((probe.LearningV323NativeJumpAuthorityRetired) &&
                string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                (IsJumpState(next) || next == EPlayerState.JumpLanding))
            {
                List<string> recoveryActions = new List<string>();
                TryInvokeOptionalBoolMethod(probe.Bot, probe.Player?.MovementContext, "PlayerAnimatorEnableJump", false, recoveryActions);
                TryInvokeOptionalBoolMethod(probe.Bot, probe.Player?.MovementContext, "PlayerAnimatorEnableLanding", false, recoveryActions);
                TryInvokeMovementStateTransition(probe.Bot, probe.Player?.MovementContext, EPlayerState.Run, recoveryActions);
                TryInvokeMovementStateTransition(probe.Bot, probe.Player, EPlayerState.Run, recoveryActions, allowSignatureFallback: false);
                try
                {
                    probe.Player.SetPlayerInputDirection("R1-9A8D140FFE3D",@probe?.Bot,Vector2.up);
                    probe.Player.MovementContext.SetMovementContextMovementDirection("R1-7A7961C9255C",@probe?.Bot,Vector2.up);
                    if (probe.Bot?.Mover != null)
                    {
                        probe.Bot.Mover.SetBotMoverPause("R1-B1D74233A325",@probe?.Bot,false);
                    }
                }
                catch (Exception ex)
                {
                    recoveryActions.Add("forwardIntent:" + ex.GetType().Name);
                }

                WriteEvent("learningV323StaleNativeJumpStateSuppressed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    previous = previous.ToString(),
                    next = next.ToString(),
                    stage = probe.Stage.ToString(),
                    position = Vec(probe.Player.Position),
                    actions = recoveryActions.ToArray(),
                    action = "keepAssistOrExitAuthorityDoNotReenterTraversing"
                });
                return;
            }

            if (probe.Stage == ProbeStage.WalkThrough && probe.WalkThroughStepAssistActive)
            {
                if ((IsProbeTraversalState(next)))
                {
                    WriteEvent("learningV324WalkThroughStepAssistUnexpectedTraversalState", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        previous = previous.ToString(),
                        next = next.ToString(),
                        position = Vec(probe.Player.Position),
                        blocker = probe.WalkThroughStepAssistBlocker,
                        action = "abortMixedSemanticExecutorAndReplan"
                    });
                    AbortWalkThroughProbe(
                        probe,
                        "learningV324UnexpectedTraversalStateDuringStepAssist",
                        "WalkThrough StepAssist may not transfer body ownership to Vault/Climb/Jump",
                        false);
                    return;
                }

                if (IsProbeTraversalState(next))
                {
                    if (!probe.WalkThroughStepAssistNativeOwned)
                    {
                        probe.WalkThroughStepAssistNativeOwned = true;
                        probe.WalkThroughStepAssistNativeEnteredAt = Time.time;
                        probe.WalkThroughStepAssistNativeReleasedAt = -1f;
                        WriteEvent("walkThroughStepAssistNativeOwnershipEntered", probe.Bot, new
                        {
                            learnedEdgeId = probe.LearnedEdgeId,
                            previous = previous.ToString(),
                            state = next.ToString(),
                            position = Vec(probe.Player.Position),
                            blocker = probe.WalkThroughStepAssistBlocker
                        });
                    }
                    return;
                }

                if (probe.WalkThroughStepAssistNativeOwned &&
                    IsProbeTraversalState(previous) && !IsProbeTraversalState(next))
                {
                    probe.WalkThroughStepAssistNativeOwned = false;
                    probe.WalkThroughStepAssistNativeReleasedAt = Time.time;
                    WriteEvent("walkThroughStepAssistNativeOwnershipReleasedByState", probe.Bot, new
                    {
                        learnedEdgeId = probe.LearnedEdgeId,
                        previous = previous.ToString(),
                        next = next.ToString(),
                        position = Vec(probe.Player.Position),
                        planarProgress = GetPlanarDistance(probe.Player.Position, probe.WalkThroughStepAssistStartPosition)
                    });
                    return;
                }
            }

            if (probe.Stage == ProbeStage.WalkThrough && IsProbeTraversalState(next))
            {
                AbortWalkThroughProbe(
                    probe,
                    "unexpectedTraversalState",
                    $"state changed from {previous} to {next} during WalkThrough",
                    false);
                return;
            }

            if (IsProbeTraversalState(next))
            {
                bool jumpCandidate = probe.Stage == ProbeStage.WaitingForState && probe.JumpAttempted &&
                    string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase);
                if (jumpCandidate)
                {
                    bool physicalTakeoff = HasNativeJumpPhysicalTakeoffEvidence(probe, out float takeoffRise, out bool takeoffAirborne);
                    if (!physicalTakeoff)
                    {
                        if (!probe.NativeJumpStateCandidateObserved)
                        {
                            probe.NativeJumpStateCandidateObserved = true;
                            probe.NativeJumpStateCandidateAt = Time.time;
                            WriteEvent("nativeJumpStateCandidateObserved", probe.Bot, new
                            {
                                edgeId = probe.LearnedEdgeId,
                                previous = previous.ToString(),
                                state = next.ToString(),
                                rise = takeoffRise,
                                airborne = takeoffAirborne,
                                physicalTakeoffConfirmed = false
                            });
                        }
                        return;
                    }
                    RecordLearningV355ConfirmedJumpActuatorLatency(probe, "stateEventPhysicalTakeoff");
                    WriteEvent("nativeJumpPhysicalTakeoffConfirmed", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        state = next.ToString(),
                        rise = takeoffRise,
                        airborne = takeoffAirborne,
                        trigger = Vec(probe.TriggerPosition),
                        position = Vec(probe.Player.Position),
                        source = "stateEvent"
                    });
                }

                BeginTraversalStage(probe, next, jumpCandidate ? "physicalTakeoffProof:event" : "event");
                return;
            }

            if (probe.Stage == ProbeStage.Traversing && probe.SawVaultState && !IsProbeTraversalState(next))
            {
                BeginLandingStage(probe, "event");
            }
        }

        private static void BeginTraversalStage(ProbeRuntime probe, EPlayerState state, string source)
        {
            if (probe.Stage != ProbeStage.Traversing)
            {
                TransitionProbeStage(probe, ProbeStage.Traversing);
                probe.StageStartedAt = Time.time;
                probe.SawVaultState = true;
                probe.NativeTraversalStarted = true;
                probe.NativeStateObserved = true;
                probe.TraversalKind = IsJumpState(state)
                    ? "Jump"
                    : (state == EPlayerState.ClimbUp ? "Climb" : "Vault");

                if (string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                    probe.JumpAttempted)
                {
                    probe.NativeJumpTakeoffPosition = IsFinite(probe.TriggerPosition) ? probe.TriggerPosition : probe.Player.Position;
                    probe.NativeJumpApexY = probe.Player.Position.y;
                    probe.NativeJumpMaxLateralDeviation = 0f;
                    probe.NativeJumpLastTrajectoryLogAt = -1f;
                }

                if (string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                    probe.JumpAttempted &&
                    !probe.JumpTakeoffPathReleased)
                {
                    // CompileFix46: keep BotMover for a bounded airborne carry instead of killing
                    // horizontal momentum on the first Jump frame. UpdateNativeJumpAirborneMoverCarry
                    // releases it after <=0.38 s / <=1.85 m, so the old unlimited air-slide cannot return.
                    WriteEvent("jumpProbeAirborneMomentumCarryStarted", probe.Bot, new
                    {
                        state = state.ToString(),
                        position = Vec(probe.Player.Position),
                        runupGroundProgress = probe.JumpRunupGroundProgress,
                        maxSeconds = NativeJumpAirborneMoverCarrySeconds,
                        maxForward = NativeJumpAirborneMoverCarryMaxForward
                    });
                }

                WriteEvent("vaultProbeTraversalStarted", probe.Bot, new
                {
                    source,
                    kind = probe.TraversalKind,
                    state = state.ToString(),
                    position = Vec(probe.Player.Position)
                });
            }
        }

        private static bool TryInstallLearningV329NativeJumpLandingWitnessMoverAnchor(ProbeRuntime probe)
        {
            if ((probe?.Player?.MovementContext == null) ||
                probe.Bot?.Mover == null || probe.LearningV329NativeJumpLandingWitnessAnchored ||
                !probe.JumpAttempted || !probe.LearningV317NativeJumpSemanticTrajectoryAuthority ||
                probe.Player.CurrentStateName != EPlayerState.JumpLanding ||
                probe.Player.MovementContext.IsGrounded != true ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return false;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 axis = GetFlatDirection(rawExit - rawEntry);
            if (axis.sqrMagnitude < 0.5f)
            {
                return false;
            }

            Vector3 current = probe.Player.Position;
            Vector3 fromEntry = current - rawEntry;
            fromEntry.y = 0f;
            float currentProjection = Vector3.Dot(fromEntry, axis);
            Vector3 previousDestination = Vector3.zero;
            bool havePreviousDestination = false;
            float previousDestinationProjection = float.NegativeInfinity;
            try
            {
                previousDestination = probe.Bot.Mover.RealDestPoint;
                havePreviousDestination = IsFinite(previousDestination);
                if (havePreviousDestination)
                {
                    Vector3 destinationFromEntry = previousDestination - rawEntry;
                    destinationFromEntry.y = 0f;
                    previousDestinationProjection = Vector3.Dot(destinationFromEntry, axis);
                }
            }
            catch
            {
            }

            // This is NOT success authority. It only discards a backward/stale pre-takeoff mover
            // destination after EFT has physically entered grounded JumpLanding. The existing
            // projection/lateral/exit/support validators still decide whether the Jump succeeded.
            if (!havePreviousDestination || previousDestinationProjection >= currentProjection)
            {
                return false;
            }
            if (!NavMesh.SamplePosition(current, out NavMeshHit landingNav, 1.35f, NavMesh.AllAreas) ||
                Mathf.Abs(landingNav.position.y - current.y) > UnifiedTraversalVerifyMaxNavVertical)
            {
                return false;
            }

            Vector3 learningV456LandingConsumerTarget = landingNav.position;
            bool learningV456SuccessorOwnsLandingLocomotion = false;
            int learningV456SuccessorEdgeId = 0;
            string learningV456SuccessorKind = string.Empty;
            if ((TryGetLearningV375FutureSameChainSuccessor(
                    probe, out FollowerRouteMission learningV456LandingMission,
                    out FollowerRouteMissionStep learningV456LandingSuccessor)) &&
                learningV456LandingSuccessor != null)
            {
                LearningV354TraversalCapabilityProfile learningV456SuccessorProfile =
                    GetLearningV354ActionProfile(learningV456LandingSuccessor.Kind);
                Vector3 learningV456CandidateTarget = default;
                bool learningV456HaveTarget = false;
                if (learningV456SuccessorProfile != null && learningV456SuccessorProfile.RequiresActuator)
                {
                    if (string.Equals(
                            learningV456LandingSuccessor.Kind, "Jump",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        learningV456HaveTarget = TryGetLearningV353JumpRouteFunnelTarget(
                            probe.Bot, learningV456LandingSuccessor,
                            out learningV456CandidateTarget, out _, out _, out _, out _, out _, out _);
                    }
                    else
                    {
                        learningV456HaveTarget = TryGetLearningV363ActuatorRouteEntryLaneTarget(
                            probe.Bot, learningV456LandingMission, learningV456LandingSuccessor,
                            out learningV456CandidateTarget, out _, out _, out _, out _, out _, out _, out _, out _);
                    }
                }
                else
                {
                    learningV456CandidateTarget = IsFinite(learningV456LandingSuccessor.Entry)
                        ? learningV456LandingSuccessor.Entry
                        : learningV456LandingSuccessor.Exit;
                    learningV456HaveTarget = IsFinite(learningV456CandidateTarget);
                }

                if (learningV456HaveTarget && IsFinite(learningV456CandidateTarget))
                {
                    Vector3 learningV456ToSuccessor = learningV456CandidateTarget - current;
                    learningV456ToSuccessor.y = 0f;
                    if (learningV456ToSuccessor.sqrMagnitude > 0.000001f &&
                        Vector3.Dot(learningV456ToSuccessor.normalized, axis) >= 0f)
                    {
                        learningV456LandingConsumerTarget = learningV456CandidateTarget;
                        learningV456SuccessorOwnsLandingLocomotion = true;
                        learningV456SuccessorEdgeId = learningV456LandingSuccessor.EdgeId;
                        learningV456SuccessorKind = learningV456LandingSuccessor.Kind ?? string.Empty;
                    }
                }
            }

            try
            {
                probe.Bot.Mover.SetBotMoverPause("R1-2DDE7C2F243E",@probe?.Bot,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-FC56D2159822",@probe?.Bot);
                probe.Bot.Mover.BotMoverGoToPointNoWay("R1-68BB90DFCB7F",@probe?.Bot,learningV456LandingConsumerTarget);
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-40D92CB62A4D",@probe?.Bot,axis);
                HoldForwardInput(probe);
                if ((learningV456SuccessorOwnsLandingLocomotion) &&
                    probe.Player.CurrentStateName == EPlayerState.JumpLanding &&
                    probe.Player.MovementContext.IsGrounded)
                {
                    // SPT 4.0.13 MovementContext has no one-argument EPlayerState transition method.
                    // Reuse the exact lifecycle PIT already uses in V4.45: States[Run] followed by
                    // ProcessStateEnter(BaseMovementState), which performs Exit/Enter, authority
                    // refresh and OnStateChanged without relocating the body or minting success.
                    EPlayerState learningV459StateBefore = probe.Player.CurrentStateName;
                    bool learningV459Released = false;
                    string learningV459ReleaseFailure = string.Empty;
                    try
                    {
                        if (probe.Player.MovementContext.OverridenState == null &&
                            probe.Player.MovementContext.States.TryGetValue(
                                EPlayerState.Run, out BaseMovementState learningV459RunState) &&
                            learningV459RunState != null)
                        {
                            RequestCapabilityLocomotionResume(probe.Bot,probe.Player,learningV459RunState);
                            learningV459Released = probe.Player.CurrentStateName != EPlayerState.JumpLanding;
                        }
                        else
                        {
                            learningV459ReleaseFailure = "runStateUnavailableOrOverridden";
                        }
                    }
                    catch (Exception ex)
                    {
                        learningV459ReleaseFailure = ex.GetType().Name + ": " + ex.Message;
                    }
                    ApplyProbeLocomotionIntent(
                        probe, ProbeMomentumFullMoveSpeed, allowSprint: true, preserveSprintMode: true);
                    HoldForwardInput(probe);
                    WriteEvent(learningV459Released
                        ? "learningV459SourceGroundedJumpLandingStateReleased"
                        : "learningV459SourceGroundedJumpLandingStateReleaseRejected", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        successorEdgeId = learningV456SuccessorEdgeId,
                        successorKind = learningV456SuccessorKind,
                        position = Vec(current),
                        moverTarget = Vec(learningV456LandingConsumerTarget),
                        stateBefore = learningV459StateBefore.ToString(),
                        stateAfter = probe.Player.CurrentStateName.ToString(),
                        failure = learningV459ReleaseFailure,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        bodyRelocated = false,
                        action = "semanticLandingVerificationRemainsObserverExactSuccessorOwnsGroundedPhysicalLocomotion"
                    });
                }
                probe.LearningV329NativeJumpLandingWitnessAnchored = true;
            }
            catch (Exception ex)
            {
                WriteEvent("learningV329NativeJumpLandingWitnessMoverAnchorFailed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    position = Vec(current),
                    landingNav = Vec(landingNav.position),
                    currentProjection,
                    previousDestinationProjection,
                    failure = ex.GetType().Name + ": " + ex.Message
                });
                return false;
            }

            WriteEvent("learningV329NativeJumpLandingWitnessMoverAnchored", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                position = Vec(current),
                landingNav = Vec(landingNav.position),
                moverTarget = Vec(learningV456LandingConsumerTarget),
                successorOwnsLandingLocomotion = learningV456SuccessorOwnsLandingLocomotion,
                successorEdgeId = learningV456SuccessorEdgeId,
                successorKind = learningV456SuccessorKind,
                rawEntry = Vec(rawEntry),
                rawExit = Vec(rawExit),
                currentProjection,
                previousDestination = Vec(previousDestination),
                previousDestinationProjection,
                successAuthorityGranted = false,
                action = learningV456SuccessorOwnsLandingLocomotion
                    ? "groundedJumpLandingKeepsForwardSameChainConsumerAsMoverTargetInsteadOfBrakingAtCurrentBody"
                    : "replaceBackwardPreTakeoffMoverAnchorDuringGroundedJumpLanding"
            });
            return true;
        }

        private static void UpdateNativeJumpAirborneMoverCarry(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.JumpTakeoffPathReleased ||
                !probe.JumpAttempted || !string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            Vector3 direction = GetFlatDirection(probe.RequestedDirection);
            Vector3 displacement = probe.Player.Position - probe.TriggerPosition;
            displacement.y = 0f;
            float forward = direction.sqrMagnitude > 0.5f
                ? Vector3.Dot(displacement, direction)
                : displacement.magnitude;
            float carryStartedAt = probe.NativeJumpTriggerAt > 0f ? probe.NativeJumpTriggerAt : probe.StageStartedAt;
            float elapsed = Time.time - carryStartedAt;

            bool stateBoundSemanticCarry =
                (probe.LearningV317NativeJumpSemanticTrajectoryAuthority) &&
                IsProbeTraversalState(probe.Player.CurrentStateName);
            if (stateBoundSemanticCarry && probe.Player.CurrentStateName == EPlayerState.JumpLanding)
            {
                TryInstallLearningV329NativeJumpLandingWitnessMoverAnchor(probe);
            }
            if (stateBoundSemanticCarry ||
                (elapsed < NativeJumpAirborneMoverCarrySeconds &&
                 forward < NativeJumpAirborneMoverCarryMaxForward))
            {
                try
                {
                    if (probe.Bot?.Mover != null)
                    {
                        probe.Bot.Mover.SetBotMoverPause("R1-6DDD7B8CDFB8",@probe?.Bot,false);
                        ApplyProbeLocomotionIntent(probe, ProbeMomentumFullMoveSpeed, allowSprint: true);
                        if (TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) &&
                            commitment != null)
                        {
                            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
                            Vector3 runOut = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
                            if (IsFinite(runOut))
                            {
                                Vector3 authoredDirection = GetFlatDirection(runOut - rawEntry);
                                if ((probe.LearningV317NativeJumpSemanticTrajectoryAuthority))
                                {
                                    // V3.17: once the strong rolling proof owns this Jump, do not
                                    // feed the physical landing endpoint back into NavMesh. Continue
                                    // only the authored semantic heading under the existing bounded
                                    // CompileFix46 carry window.
                                    Vector3 semanticDirection = authoredDirection.sqrMagnitude > 0.5f
                                        ? authoredDirection
                                        : direction;
                                    probe.Bot.Steering?.BotSteeringLookToDirection("R1-363514E89CCE",@probe?.Bot,semanticDirection);
                                    HoldForwardInput(probe);
                                }
                                else
                                {
                                    probe.Bot.Mover.BotMoverGoToPointNoWay("R1-E9E27C8FEB84",@probe?.Bot,runOut);
                                    Vector3 toLanding = GetFlatDirection(runOut - probe.Player.Position);
                                    Vector3 correctionDirection = authoredDirection.sqrMagnitude > 0.5f
                                        ? authoredDirection
                                        : direction;
                                    if (authoredDirection.sqrMagnitude > 0.5f && toLanding.sqrMagnitude > 0.5f &&
                                        Vector3.Dot(toLanding, authoredDirection) > 0.25f)
                                    {
                                        Vector3 fromEntry = probe.Player.Position - rawEntry;
                                        fromEntry.y = 0f;
                                        float projection = Vector3.Dot(fromEntry, authoredDirection);
                                        Vector3 lateral = fromEntry - authoredDirection * projection;
                                        float lateralDeviation = lateral.magnitude;
                                        float correction01 = Mathf.InverseLerp(
                                            NativeJumpTrajectoryCorrectionStartLateral,
                                            NativeJumpTrajectoryCorrectionFullLateral,
                                            lateralDeviation);
                                        float correctionBlend = Mathf.Clamp01(correction01) * NativeJumpTrajectoryCorrectionMaxBlend;
                                        if (correctionBlend > 0.001f)
                                        {
                                            correctionDirection = Vector3.Slerp(authoredDirection, toLanding, correctionBlend).normalized;
                                        }
                                    }
                                    probe.Bot.Steering?.BotSteeringLookToDirection(
"R1-550B7F00A81D",@probe?.Bot,                                        correctionDirection.sqrMagnitude > 0.5f ? correctionDirection : direction);
                                    HoldForwardInput(probe);
                                }
                            }
                        }
                    }
                }
                catch
                {
                }
                return;
            }

            // V3.27: if semantic Native Jump authority owned the actual EFT Jump state, do not
            // issue StopMove on the exact frame the state transitions to Run/Idle. The 2026-09-12
            // regression physically reached the valid far side, then StopMove/near-side Mover
            // reconciliation pulled the body back before the landing validator sampled it, causing
            // AssistedReplay to draw a second visible jump. Landing now owns the rebase below.
            bool landingTransitionOwnsRebase =
                (probe.LearningV317NativeJumpSemanticTrajectoryAuthority) &&
                !IsProbeTraversalState(probe.Player.CurrentStateName);
            if (!landingTransitionOwnsRebase)
            {
                try
                {
                    probe.Bot?.BotOwnerStopMove("R1-9C701224CE41",@probe?.Bot);
                }
                catch
                {
                }
            }
            probe.JumpTakeoffPathReleased = true;
            WriteEvent("jumpProbeTakeoffPathReleased", probe.Bot, new
            {
                state = probe.Player.CurrentStateName.ToString(),
                position = Vec(probe.Player.Position),
                runupGroundProgress = probe.JumpRunupGroundProgress,
                airborneCarrySeconds = elapsed,
                airborneForwardProgress = forward,
                stateBoundSemanticCarry = (probe.LearningV317NativeJumpSemanticTrajectoryAuthority),
                stopMoveDeferredToLandingRebase = landingTransitionOwnsRebase
            });
        }

        private static void UpdateNativeJumpTrajectoryTelemetry(ProbeRuntime probe)
        {
            if (probe == null || probe.Player == null ||
                !string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) || commitment == null)
            {
                return;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 axis = rawExit - rawEntry;
            axis.y = 0f;
            float span = axis.magnitude;
            Vector3 direction = span > 0.25f ? axis / span : GetFlatDirection(probe.RequestedDirection);
            Vector3 fromEntry = probe.Player.Position - rawEntry;
            fromEntry.y = 0f;
            float projection = direction.sqrMagnitude > 0.5f ? Vector3.Dot(fromEntry, direction) : fromEntry.magnitude;
            Vector3 lateralVector = direction.sqrMagnitude > 0.5f
                ? fromEntry - direction * projection
                : Vector3.zero;
            float lateralDeviation = lateralVector.magnitude;
            probe.NativeJumpMaxLateralDeviation = Mathf.Max(probe.NativeJumpMaxLateralDeviation, lateralDeviation);
            probe.NativeJumpApexY = Mathf.Max(probe.NativeJumpApexY, probe.Player.Position.y);

            if (probe.NativeJumpLastTrajectoryLogAt < 0f ||
                Time.time - probe.NativeJumpLastTrajectoryLogAt >= NativeJumpTrajectoryTelemetryInterval)
            {
                probe.NativeJumpLastTrajectoryLogAt = Time.time;
                Vector3 actualTravel = probe.Player.Position - probe.NativeJumpTakeoffPosition;
                actualTravel.y = 0f;
                Vector3 actualDirection = GetFlatDirection(actualTravel);
                float headingError = direction.sqrMagnitude > 0.5f && actualDirection.sqrMagnitude > 0.5f
                    ? Vector3.Angle(direction, actualDirection)
                    : 0f;
                WriteEvent("nativeJumpTrajectorySample", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    position = Vec(probe.Player.Position),
                    forwardProjection = projection,
                    lateralDeviation,
                    maxLateralDeviation = probe.NativeJumpMaxLateralDeviation,
                    currentRise = probe.Player.Position.y - probe.NativeJumpTakeoffPosition.y,
                    apexRise = probe.NativeJumpApexY - probe.NativeJumpTakeoffPosition.y,
                    headingErrorDegrees = headingError,
                    pathReleased = probe.JumpTakeoffPathReleased,
                    elapsed = Time.time - probe.StageStartedAt
                });
            }
        }

        private static bool TryMaintainLearningV324PreExitContinuity(ProbeRuntime probe, string source)
        {
            if ((probe?.Player?.MovementContext == null) ||
                probe.Bot?.Mover == null || !IsPlayerValidatedTraversalProbe(probe) ||
                IsProbeTraversalState(probe.Player.CurrentStateName) || probe.TraversalTeleportAttempted ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) || commitment == null)
            {
                return false;
            }

            string kind = commitment.Kind ?? probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            bool physicalFarSide = string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase)
                ? probe.NativeDropDownPhysicalLandingAuthority
                : IsNativeTraversalAlreadyOnFarSide(
                    probe,
                    commitment,
                    IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit,
                    out _,
                    out _);
            if (!physicalFarSide || probe.NativeLandingRejected || probe.NativePartialCrossingObserved)
            {
                return false;
            }

            Vector3 direction = GetFlatDirection(
                (IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit) - probe.Player.Position);
            if (direction.sqrMagnitude < 0.5f)
            {
                direction = probe.RequestedDirection;
            }
            if (direction.sqrMagnitude > 0.5f)
            {
                probe.Bot.Steering?.BotSteeringLookToDirection("R1-6FA3EC807273",@probe?.Bot,direction);
            }
            probe.Bot.Mover.SetBotMoverPause("R1-2D899B59395E",@probe?.Bot,false);
            ApplyProbeLocomotionIntent(probe, 0.55f, allowSprint: false);
            HoldForwardInput(probe);

            if (ShouldEmitDiagnostic("learningV324PreExitContinuity:" + probe.LearnedEdgeId, probe.Bot, 0.18f))
            {
                WriteEvent("learningV324PreExitMovementContinuity", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind,
                    stage = probe.Stage.ToString(),
                    source = source ?? "unknown",
                    position = Vec(probe.Player.Position),
                    successCommitted = false,
                    action = "keepTraversalOwnedForwardMotionWhileExistingVerificationMatures"
                });
            }
            return true;
        }

        private static bool TryInstallLearningV327NativeJumpLandingMoverRebase(ProbeRuntime probe)
        {
            if ((probe?.Player == null) ||
                probe.Bot?.Mover == null || !probe.JumpAttempted ||
                !string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                !probe.LearningV317NativeJumpSemanticTrajectoryAuthority ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return false;
            }

            Vector3 requestedExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            if (!IsNativeTraversalAlreadyOnFarSide(
                    probe, commitment, requestedExit, out float forwardProjection, out float requiredProjection))
            {
                return false;
            }

            {
                // Completion proof is an observer, not a movement producer. If the same authored
                // chain already has a successor, V4.51 never brakes the capsule just to protect a
                // landing that is already physically proven. Retire only stale path topology and
                // let the persistent route/successor keep the existing native locomotion epoch.
                probe.LearningV332NativeGroundMoverPermitted = false;
                bool learningV451ContinuousSuccessor =
                    (TryGetLearningV375FutureSameChainSuccessor(
                        probe, out FollowerRouteMission learningV451SuccessorMission,
                        out FollowerRouteMissionStep learningV451SuccessorStep)) &&
                    learningV451SuccessorStep != null;
                if (learningV451ContinuousSuccessor)
                {
                    TryRetireNativeMoverPathPreserveLocomotion(
                        probe.Bot,
                        "learningV451QualifiedJumpLandingContinuousSuccessor",
                        out string learningV451RetireDetail);
                    Vector3 semanticDirection = GetFlatDirection(requestedExit - probe.Player.Position);
                    if (semanticDirection.sqrMagnitude > 0.5f)
                    {
                        probe.Bot.Steering?.BotSteeringLookToDirection("R1-B59B8EA6424D",@probe?.Bot,semanticDirection);
                    }
                    HoldForwardInput(probe);
                    WriteEvent("learningV451QualifiedJumpLandingHandsThroughWithoutBrake", probe.Bot, new
                    {
                        missionId = learningV451SuccessorMission?.MissionId ?? 0,
                        edgeId = probe.LearnedEdgeId,
                        successorEdgeId = learningV451SuccessorStep.EdgeId,
                        successorKind = learningV451SuccessorStep.Kind ?? string.Empty,
                        position = Vec(probe.Player.Position),
                        requestedExit = Vec(requestedExit),
                        forwardProjection,
                        requiredProjection,
                        stalePathRetireDetail = learningV451RetireDetail ?? string.Empty,
                        bodyRelocated = false,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "landingProofObservesAndScrubsTopologySuccessorOwnsContinuousMovement"
                    });
                    return true;
                }

                // Terminal/no-successor case keeps the old conservative anti-reacquire protection.
                try
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-31F09DC04B8C",@probe?.Bot,false);
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-2E9D9BF3015A",@probe?.Bot);
                    probe.Bot.Mover.BotMoverStop("R1-4EE5425E3942",@probe?.Bot);
                    probe.Bot.Mover.SetBotMoverPause("R1-E5C6F760AB76",@probe?.Bot,false);
                    probe.Bot.BotOwnerSetTargetMoveSpeed("R1-C668B2C446C5",@probe?.Bot,0.55f);
                    Vector3 semanticDirection = GetFlatDirection(requestedExit - probe.Player.Position);
                    if (semanticDirection.sqrMagnitude > 0.5f)
                    {
                        probe.Bot.Steering?.BotSteeringLookToDirection("R1-36EE7F1A1A1F",@probe?.Bot,semanticDirection);
                    }
                    HoldForwardInput(probe);
                }
                catch { }
                WriteEvent("learningV335QualifiedJumpLandingPhysicalAuthorityPreserved", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    position = Vec(probe.Player.Position),
                    requestedExit = Vec(requestedExit),
                    forwardProjection,
                    requiredProjection,
                    action = "terminalLandingOnlyStopStaleMoverKeepQualifiedPhysicalBody"
                });
                return true;
            }

            // Reuse the exact existing Jump landing corridor as the proof. Only AFTER that proof is
            // true may the nav/mover anchor move to the far side. V3.32 additionally requires the
            // sampled start anchor to be monotonic relative to the physical landing body. A nearby
            // lower/near-side NavMesh polygon is not allowed to pull a proven landing backward/down.
            if (!NavMesh.SamplePosition(probe.Player.Position, out NavMeshHit landingNav, 1.35f, NavMesh.AllAreas) ||
                Mathf.Abs(landingNav.position.y - probe.Player.Position.y) > UnifiedTraversalVerifyMaxNavVertical)
            {
                return false;
            }

            Vector3 landingAxis = GetFlatDirection(
                (IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit) -
                (IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry));
            float landingNavVerticalDelta = landingNav.position.y - probe.Player.Position.y;
            float landingNavForwardDelta = 0f;
            if (landingAxis.sqrMagnitude > 0.5f)
            {
                Vector3 landingNavDelta = landingNav.position - probe.Player.Position;
                landingNavDelta.y = 0f;
                landingNavForwardDelta = Vector3.Dot(landingNavDelta, landingAxis);
            }

            // GoToPointNoWay may internally anchor its path from the nearest ground NavMesh even
            // when the requested target itself is a valid far-side point. Sample the CURRENT body
            // separately so a landing that is physically above/off the mesh cannot be snapped down
            // to a lower near-side polygon when BotMover acquires path authority.
            bool currentStartSampled = NavMesh.SamplePosition(
                probe.Player.Position, out NavMeshHit currentStartHit,
                UnifiedTraversalEgressAuthorityNavRadius, NavMesh.AllAreas);
            float currentStartVerticalDelta = 0f;
            float currentStartForwardDelta = 0f;
            bool currentStartMonotonic = currentStartSampled;
            if (currentStartSampled)
            {
                currentStartVerticalDelta = currentStartHit.position.y - probe.Player.Position.y;
                if (landingAxis.sqrMagnitude > 0.5f)
                {
                    Vector3 currentStartDelta = currentStartHit.position - probe.Player.Position;
                    currentStartDelta.y = 0f;
                    currentStartForwardDelta = Vector3.Dot(currentStartDelta, landingAxis);
                }
                currentStartMonotonic =
                    currentStartVerticalDelta >= -LearningV332NativeGroundMoverStartMaxVerticalRebase &&
                    currentStartForwardDelta >= -LearningV332NativeGroundMoverStartMaxBackwardProjection;
            }
            bool learningV332LandingAnchorMonotonic =
                FollowerCapabilityHelperRules.TryInstallLearningV327NativeJumpLandingMoverRebase_learningV332LandingAnchorMonotonic_AE4D664F_1(landingNavVerticalDelta,LearningV332NativeGroundMoverStartMaxVerticalRebase,landingNavForwardDelta,LearningV332NativeGroundMoverStartMaxBackwardProjection,currentStartMonotonic);
            if (!learningV332LandingAnchorMonotonic)
            {
                probe.LearningV332NativeGroundMoverPermitted = false;
                try
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-A6352D32E9C3",@probe?.Bot,false);
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-202D96FD9A26",@probe?.Bot);
                    probe.Bot.Mover.BotMoverStop("R1-2A6B8B3E03F6",@probe?.Bot);
                    probe.Bot.Mover.SetBotMoverPause("R1-2E25792AE36F",@probe?.Bot,false);
                    probe.Bot.BotOwnerSetTargetMoveSpeed("R1-781BD63D546F",@probe?.Bot,0.55f);
                    HoldForwardInput(probe);
                }
                catch { }
                WriteEvent("learningV332QualifiedJumpLandingMoverRebaseSuppressed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    position = Vec(probe.Player.Position),
                    rejectedLandingNav = Vec(landingNav.position),
                    landingNavVerticalDelta,
                    landingNavForwardDelta,
                    currentStartSampled,
                    currentStartNav = currentStartSampled ? (object)Vec(currentStartHit.position) : null,
                    currentStartVerticalDelta,
                    currentStartForwardDelta,
                    forwardProjection,
                    requiredProjection,
                    action = "stopStaleMoverPreservePhysicalLandingBodyNoBackwardDownRebase"
                });
                return false;
            }

            probe.LearningV332NativeGroundMoverPermitted = true;
            Vector3 preDestination = Vector3.zero;
            bool hadPreDestination = false;
            try
            {
                preDestination = probe.Bot.Mover.RealDestPoint;
                hadPreDestination = IsFinite(preDestination);
                probe.Bot.Mover.SetBotMoverPause("R1-44C26FB2E725",@probe?.Bot,false);
                probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-EDF17E093B62",@probe?.Bot);
                probe.Bot.Mover.BotMoverStop("R1-28BA4105D768",@probe?.Bot);
                probe.Bot.Mover.SetBotMoverPause("R1-877C5517C650",@probe?.Bot,false);
                probe.Bot.Mover.BotMoverGoToPointNoWay("R1-A121007255A9",@probe?.Bot,landingNav.position);
                Vector3 semanticDirection = GetFlatDirection(requestedExit - probe.Player.Position);
                if (semanticDirection.sqrMagnitude > 0.5f)
                {
                    probe.Bot.Steering?.BotSteeringLookToDirection("R1-AB70BC1573BC",@probe?.Bot,semanticDirection);
                }
            }
            catch (Exception ex)
            {
                WriteEvent("learningV327NativeJumpLandingMoverRebaseFailed", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    position = Vec(probe.Player.Position),
                    landingNav = Vec(landingNav.position),
                    forwardProjection,
                    requiredProjection,
                    failure = ex.GetType().Name + ": " + ex.Message
                });
                return false;
            }

            WriteEvent("learningV327NativeJumpLandingMoverRebased", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                position = Vec(probe.Player.Position),
                landingNav = Vec(landingNav.position),
                requestedExit = Vec(requestedExit),
                forwardProjection,
                requiredProjection,
                previousDestination = hadPreDestination ? (object)Vec(preDestination) : null,
                action = "qualifiedPhysicalLandingOwnsFarSideMoverAnchor"
            });
            return true;
        }

        // CF23: a native Vault/Climb that has released its EFT traversal state is not
        // automatically a failed actuator while its unsupported body is still advancing
        // along the demonstrated exit axis.  This is an observer/producer lease inside the
        // SAME movement epoch.  It cannot create a new executor, extend the existing landing
        // timeout, relax far-side proof, or award Native success.
        private static bool TryPreserveCf23NativeVaultClimbLandingProgress(ProbeRuntime probe)
        {
            if (probe?.Player?.MovementContext == null || probe.Bot?.Mover == null ||
                probe.Stage != ProbeStage.Landing || !probe.InjectedNativeVaultAttempted ||
                !probe.NativeStateObserved || probe.AssistedReplayAttempted ||
                probe.NativeLandingRejected || probe.TraversalTeleportAttempted ||
                !IsPlayerValidatedTraversalProbe(probe) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) ||
                commitment == null)
            {
                return false;
            }

            string kind = commitment.Kind ?? probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            if (!string.Equals(kind, "Vault", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            // CF48: an elevated same-chain Climb -> successor has a stronger, directed upper
            // crossing-plane contract (CF37) than the generic EFT support/near-exit observers.
            // A bot can touch the obstacle top, briefly look supported, and still be on the
            // near side. That observation MUST NOT cause CF23's native landing producer to
            // hand control to partial AssistedReplay while physical forward progress is live.
            // Keep this exact mission/episode/chain/step scoped; never relax generic Climb,
            // Vault, successor admission or the CF37 far-side success predicate.
            bool cf48ExactElevatedSameChainClimb = false;
            if (string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                commitment.RouteMissionId > 0 && probe.TraversalEpisodeId > 0 &&
                !string.IsNullOrEmpty(probe.Bot.ProfileId) &&
                FollowerRouteMissions.TryGetValue(probe.Bot.ProfileId, out FollowerRouteMission cf48Mission) &&
                cf48Mission != null && cf48Mission.MissionId == commitment.RouteMissionId &&
                cf48Mission.Steps != null)
            {
                int cf48StepIndex = commitment.RouteMissionStepIndex >= 0
                    ? commitment.RouteMissionStepIndex : cf48Mission.CurrentStepIndex;
                if (cf48StepIndex >= 0 && cf48StepIndex + 1 < cf48Mission.Steps.Count)
                {
                    FollowerRouteMissionStep cf48Step = cf48Mission.Steps[cf48StepIndex];
                    FollowerRouteMissionStep cf48Next = cf48Mission.Steps[cf48StepIndex + 1];
                    Vector3 cf48NextEntry = cf48Next != null && IsFinite(cf48Next.RawEntry)
                        ? cf48Next.RawEntry : (cf48Next != null ? cf48Next.Entry : Vector3.zero);
                    Vector3 cf48Entry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
                    cf48ExactElevatedSameChainClimb =
                        cf48Step != null && cf48Next != null &&
                        cf48Step.EdgeId == commitment.EdgeId &&
                        cf48Step.EpisodeId == probe.TraversalEpisodeId &&
                        cf48Step.ChainId > 0 && cf48Step.ChainId == cf48Next.ChainId &&
                        IsFinite(cf48NextEntry) &&
                        cf48NextEntry.y - cf48Entry.y > UnifiedTraversalVerifyMaxNavVertical;
                }
            }
            FollowerMovementWriterAuthority.WriterDomain cf48Owner;
            long cf48Generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                probe.Bot, out cf48Owner);
            bool cf48OwnedNativeEpoch =
                cf48Owner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                cf48Generation > 0 && cf48Generation == probe.MovementWriterGeneration;
            Vector3 cf48RawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            // This is a pre-success lease only. It must still satisfy CF37 at completion.
            bool cf48UpperPlanePending = FollowerCapabilityPassagePolicy.ClimbUpperPending(kind=="Climb",cf48OwnedNativeEpoch,
                commitment.RawExit.y-cf48RawEntry.y,commitment.RawExit.y-probe.Player.Position.y) ||
                cf48ExactElevatedSameChainClimb && cf48OwnedNativeEpoch &&
                probe.Player.Position.y - cf48RawEntry.y >= 0.35f &&
                !IsVaultClimbFarSideForEgress(probe, commitment, out _, out _);

            // The original PlayerValidatedLandingTimeout is the absolute safety budget.
            // For the exact CF37 debt, incidental support or generic near-exit guesses do
            // not retire a live native trajectory. Motion/liveness below remains mandatory.
            float landingAge = Time.time - probe.StageStartedAt;
            bool cf48Supported = IsEffectivelySupportedForProbe(probe.Bot, probe.Player);
            bool cf48GenericFarSide = IsNativeTraversalAlreadyOnFarSide(
                probe, commitment,
                IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit,
                out _, out _);
            if (landingAge >= PlayerValidatedLandingTimeout ||
                (cf48Supported && !cf48UpperPlanePending) ||
                IsProbeTraversalState(probe.Player.CurrentStateName) ||
                (cf48GenericFarSide && !cf48UpperPlanePending))
            {
                return false;
            }

            Vector3 rawEntry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            Vector3 rawExit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            Vector3 direction = GetFlatDirection(rawExit - rawEntry);
            if (direction.sqrMagnitude < 0.5f)
            {
                return false;
            }
            Vector3 sinceLanding = probe.Player.Position - probe.Cf23NativeLandingStartPosition;
            sinceLanding.y = 0f;
            // Climb progress includes native ascent; a nearly vertical finish is not a flat-motion stall.
            if(kind=="Climb")sinceLanding=probe.Player.Position-probe.Cf23NativeLandingStartPosition;
            Vector3 progressAxis=kind=="Climb"?(rawExit-rawEntry).normalized:direction;
            float forwardProjection = Vector3.Dot(sinceLanding, progressAxis);
            // Use the canonical physical-producer epsilon, not a new distance threshold.
            if (forwardProjection > probe.Cf23NativeLandingBestForwardProjection + 0.01f)
            {
                probe.Cf23NativeLandingBestForwardProjection = forwardProjection;
                probe.Cf23NativeLandingLastProgressAt = Time.time;
            }
            bool physicallyAdvancing =
                probe.Cf23NativeLandingBestForwardProjection >= 0.01f &&
                Time.time - probe.Cf23NativeLandingLastProgressAt <= ProbeLandingStableTime;
            if (cf48UpperPlanePending && ShouldEmitDiagnostic(
                    "cf48ElevatedClimbNativeLandingLease:" + probe.LearnedEdgeId,
                    probe.Bot, 0.12f))
            {
                WriteEvent("cf48ElevatedClimbNativeLandingLease", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    missionId = commitment.RouteMissionId,
                    episodeId = probe.TraversalEpisodeId,
                    landingAge,
                    supported = cf48Supported,
                    genericFarSide = cf48GenericFarSide,
                    cf37UpperPlaneStillPending = true,
                    body = Vec(probe.Player.Position),
                    forwardProjection,
                    physicallyAdvancing,
                    movementGeneration = cf48Generation,
                    nativeSuccessGranted = false,
                    assistedReplayStarted = false,
                    bodyRelocated = false,
                    action = "sameChainNativeProgressOutranksPrematureSupportedOrGenericFarSideConsumer"
                });
            }
            if (!physicallyAdvancing)
            {
                return false;
            }

            // Preserve only EFT-native locomotion input while the exact Traversal writer
            // is current.  No collision lease, transforms, teleport or success mutation.
            ApplyProbeLocomotionIntent(probe, 0.55f, allowSprint: false);
            HoldForwardInput(probe);
            if (ShouldEmitDiagnostic(
                    "cf23NativeLandingProgressLease:" + probe.LearnedEdgeId,
                    probe.Bot, 0.12f))
            {
                WriteEvent("cf23NativeLandingProgressLease", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    kind,
                    landingAge,
                    body = Vec(probe.Player.Position),
                    forwardProjection,
                    bestForwardProjection = probe.Cf23NativeLandingBestForwardProjection,
                    secondsSinceProgress = Time.time - probe.Cf23NativeLandingLastProgressAt,
                    safetyBudget = PlayerValidatedLandingTimeout,
                    grounded = probe.Player.MovementContext.IsGrounded,
                    movementGeneration = probe.MovementWriterGeneration,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "retainSameNativePhysicalProducerWhileUnsupportedForwardProgressRemainsLive"
                });
            }
            return true;
        }

        private static void BeginLandingStage(ProbeRuntime probe, string source)
        {
            if (probe.Stage == ProbeStage.Landing || probe.Stage == ProbeStage.SafetyHold)
            {
                return;
            }

            TransitionProbeStage(probe, ProbeStage.Landing);
            probe.StageStartedAt = Time.time;
            probe.GroundedStableSince = -1f;
            probe.Cf23NativeLandingStartPosition = probe.Player.Position;
            probe.Cf23NativeLandingBestForwardProjection = 0f;
            probe.Cf23NativeLandingLastProgressAt = Time.time;
            EmitLearningV346PhysicalNavigationEpochSnapshot(probe, "landingAcquired");
            RestoreProbeInput(probe);
            if (string.Equals(probe.TraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) && probe.JumpAttempted)
            {
                probe.NativeJumpApexY = Mathf.Max(probe.NativeJumpApexY, probe.Player.Position.y);
                bool landingMoverRebased = TryInstallLearningV327NativeJumpLandingMoverRebase(probe);
                WriteEvent("nativeJumpApex", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    takeoff = Vec(probe.NativeJumpTakeoffPosition),
                    apexY = probe.NativeJumpApexY,
                    riseHeight = probe.NativeJumpApexY - probe.NativeJumpTakeoffPosition.y,
                    maxLateralDeviation = probe.NativeJumpMaxLateralDeviation,
                    landingTransitionPosition = Vec(probe.Player.Position),
                    landingMoverRebased
                });
            }
            WriteEvent("vaultProbeLandingWait", probe.Bot, new
            {
                source,
                position = Vec(probe.Player.Position),
                grounded = probe.Player.MovementContext?.IsGrounded == true
            });
        }

        private static void CompleteProbeAtLanding(ProbeRuntime probe)
        {
            if (!HasMeaningfulTraversalProgress(probe, out float forwardProgress, out float planarDisplacement))
            {
                // A Vault/Jump state transition alone is not success. The V1.3.2.2 log contained
                // several "completed" probes with 0-0.1m displacement: EFT played the traversal
                // state but the follower never crossed the obstacle. Keep learned-edge commitment
                // intact so Follow can retry instead of falsely considering the shortcut solved.
                WriteEvent("vaultProbeNoProgress", probe.Bot, new
                {
                    kind = probe.TraversalKind,
                    requestedKind = probe.RequestedTraversalKind,
                    forwardProgress,
                    planarDisplacement,
                    trigger = Vec(probe.TriggerPosition),
                    landing = Vec(probe.Player.Position),
                    learnedEdgeId = probe.LearnedEdgeId
                });

                // The player already proved this edge. A native animation that landed on the obstacle
                // top/entry side is an incomplete continuation, not a reason to launch a second long
                // salvage path. Finish the short edge directly at its authored far-side exit.
                if (TryRecoverPlayerValidatedTraversal(probe, "nativeTraversalNoProgress"))
                {
                    return;
                }

                // Non-player-authored diagnostic probes may still salvage low/short geometry with a
                // real EFT Jump before giving up.
                if (!probe.JumpAttempted &&
                    !string.Equals(probe.TraversalKind, "ForwardHopFallback", StringComparison.OrdinalIgnoreCase) &&
                    TryBeginNativeJumpAfterVaultRefusal(probe, out string jumpFailure))
                {
                    WriteEvent("vaultProbeNoProgressJumpRetry", probe.Bot, new
                    {
                        forwardProgress,
                        planarDisplacement,
                        learnedEdgeId = probe.LearnedEdgeId
                    });
                    return;
                }

                if (probe.JumpAttempted &&
                    string.Equals(probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                    !probe.JumpFallbackToVault)
                {
                    // A real jump can collide with the obstacle lip and land on the entry side. Do not
                    // strand the edge after one failed jump: immediately retry the same learned shortcut
                    // through the native Vault scanner, which is often better when the follower was a
                    // little too close to the obstacle.
                    FallbackJumpToVault(probe, "native jump landed without crossing the obstacle");
                    return;
                }

                FinishProbeWithoutReanchor(
                    probe,
                    "traversalNoProgress",
                    $"landed without crossing; forward={forwardProgress:0.00}m planar={planarDisplacement:0.00}m");
                return;
            }

            if (probe.AbortAfterLanding)
            {
                ForceReleaseTraversalProbe(probe, "completedAfterDeferredAbort");
                return;
            }

            // V1.3.17: player-authored Vault/Climb/Jump has exactly three layers. Once a native
            // traversal state ends, either accept a real far-side native result or transfer directly
            // to Assisted Replay. Do not branch into the legacy post-climb egress path.
            if (IsPlayerValidatedTraversalProbe(probe) &&
                TryRecoverPlayerValidatedTraversal(probe, "nativeLandingContinuation"))
            {
                return;
            }

            // Non-player-authored diagnostic probes may still use the legacy egress helper.
            if (TryBeginPostTraversalEgress(probe))
            {
                return;
            }

            if (!TryGetPreferredLandingNavMesh(probe, out NavMeshHit navHit, out string failure, out bool usedLearnedExit))
            {
                EnterSafetyHold(probe, failure);
                return;
            }

            string completionReason = probe.AbortAfterLanding ? "completedAfterDeferredAbort" : "completed";
            if (usedLearnedExit)
            {
                completionReason += "ExitSide";
            }
            if (!TryReanchorAndRelease(probe, navHit.position, completionReason, out string reanchorFailure))
            {
                EnterSafetyHold(probe, reanchorFailure);
            }
        }

        private static bool TryBeginPostTraversalEgress(ProbeRuntime probe)
        {
            if (probe == null || probe.Player?.MovementContext == null)
            {
                return false;
            }

            if (!TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment))
            {
                return false;
            }

            // V1.3.16: PlayerValidated traversal first accepts a natural native far-side landing. If EFT
            // ends on the obstacle top/entry side, immediately continue with Assisted Replay rather than
            // waiting for support, repeating scanner confirmation, or starting a long detour.
            if (IsPlayerValidatedTraversalProbe(probe) &&
                TryRecoverPlayerValidatedTraversal(probe, "postNativeContinuation"))
            {
                return true;
            }

            // Legacy direct/native second-stage egress remains only for non-player-authored Climb
            // diagnostics. PlayerValidated probes never enter this long salvage path anymore.
            if (!string.Equals(probe.TraversalKind, "Climb", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 current = probe.Player.Position;
            float exitDistance = GetPlanarDistance(current, commitment.Exit);
            float entryDistance = GetPlanarDistance(current, commitment.Entry);
            if (exitDistance <= ProbePostTraversalEgressCompletionDistance ||
                exitDistance > 3.40f ||
                Mathf.Abs(current.y - commitment.Exit.y) > 2.25f)
            {
                return false;
            }

            // Only step off when the native climb has already made meaningful progress toward the
            // far side. This avoids converting an entry-side failed climb into direct movement.
            if (entryDistance + 0.10f < exitDistance)
            {
                return false;
            }

            // V1.3.14: a successful ClimbUp may end on the top surface of an obstacle where EFT
            // intentionally has no NavMesh. That top is an intermediate state, not a landing that
            // must be re-anchored. When the player's learned far-side exit is close and safe, step
            // directly to it instead of holding for several seconds and snapping back to the entry.
            bool topHasLocalNavMesh = NavMesh.SamplePosition(current, out NavMeshHit topNav, 0.95f, NavMesh.AllAreas) &&
                                      Mathf.Abs(topNav.position.y - current.y) <= 0.80f;
            bool climbTopHardStuck = IsTraversalHardStuck(probe, out string climbTopStuckReason);
            if (!topHasLocalNavMesh && climbTopHardStuck)
            {
                if (!PrepareProbeForTeleportCommit(
                    probe, $"climbTopExitHardStuck:{commitment.EdgeId}:{climbTopStuckReason}"))
                {
                    return false;
                }
                bool climbTopTeleported = FollowerSafeTeleport.TryTeleportAcrossTraversalExit(
                    probe.Bot,
                    IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit,
                    $"climbTopExitHardStuck:{commitment.EdgeId}:{climbTopStuckReason}",
                    out Vector3 crossedTo,
                    issuedTeleportGeneration: probe.TeleportWriterGeneration);
                RestoreTraversalMovementAuthorityAfterTeleportAttempt(
                    probe,
                    climbTopTeleported ? "climbTopExitCommitted" : "climbTopExitRejected");
                if (!climbTopTeleported)
                {
                    return false;
                }
                WriteEvent("vaultProbeTopExitTeleport", probe.Bot, new
                {
                    edgeId = commitment.EdgeId,
                    from = Vec(current),
                    exit = Vec(commitment.Exit),
                    teleportedTo = Vec(crossedTo),
                    exitDistance,
                    entryDistance
                });

                if (NavMesh.SamplePosition(crossedTo, out NavMeshHit crossedNav, 1.75f, NavMesh.AllAreas) &&
                    TryReanchorAndRelease(probe, crossedNav.position, "climbTopExitTeleportCompleted", out _))
                {
                    return true;
                }
            }

            Vector3 toExit = commitment.Exit - current;
            toExit.y = 0f;
            if (toExit.sqrMagnitude <= 0.0001f)
            {
                return false;
            }
            Vector3 exitDirection = toExit.normalized;

            // The original V1.3.7 plan explicitly required a second native traversal/step-down
            // attempt before using any direct character-controller egress. Try EFT's own vault
            // scanner once from the obstacle top. If it accepts, wait for the normal traversal
            // state machine and only fall back to collision-checked direct egress if that second
            // native traversal later lands short again.
            if (!probe.PostClimbNativeEgressAttempted)
            {
                probe.PostClimbNativeEgressAttempted = true;
                if (TryBeginNativePostClimbEgress(
                        probe,
                        commitment,
                        current,
                        exitDirection,
                        exitDistance,
                        entryDistance))
                {
                    return true;
                }
            }

            if (probe.EgressAttempted)
            {
                return false;
            }

            if (!TryValidatePostTraversalEgressCorridor(
                    probe.Player,
                    current,
                    commitment.Exit,
                    out string corridorFailure,
                    out string blocker))
            {
                WriteEvent("vaultProbeEgressRejected", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    current = Vec(current),
                    exit = Vec(commitment.Exit),
                    reason = corridorFailure,
                    blocker
                });
                return false;
            }

            probe.EgressAttempted = true;
            TransitionProbeStage(probe, ProbeStage.Egress);
            probe.StageStartedAt = Time.time;
            probe.EgressTarget = commitment.Exit;
            probe.EgressLastDistance = exitDistance;
            probe.EgressLastProgressAt = Time.time;
            probe.ExclusiveMoverGate = true;
            probe.Bot.Mover.SetBotMoverPause("R1-B1CFB5FDB765",@probe?.Bot,false);
            probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-0F09E159E38F",@probe?.Bot);
            probe.Bot.BotOwnerSetTargetMoveSpeed("R1-733EAE17DC52",@probe?.Bot,ProbeMomentumNormalMoveSpeed);
            WriteEvent("vaultProbeEgressStarted", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind,
                mode = "collisionCheckedDirectFallback",
                current = Vec(current),
                exit = Vec(commitment.Exit),
                exitDistance,
                entryDistance
            });
            return true;
        }

        private static bool TryBeginNativePostClimbEgress(
            ProbeRuntime probe,
            LearnedTraversalCommitment commitment,
            Vector3 current,
            Vector3 exitDirection,
            float exitDistance,
            float entryDistance)
        {
            if (probe?.Player?.MovementContext == null)
            {
                return false;
            }

            if (!EnsureVaultingComponent(probe.Player, out string componentFailure))
            {
                WriteEvent("vaultProbeEgressNativeAttempt", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    result = false,
                    reason = "vaultingComponentUnavailable",
                    componentFailure,
                    current = Vec(current),
                    exit = Vec(commitment.Exit)
                });
                return false;
            }

            probe.Bot.Mover.SetBotMoverPause("R1-C26C39513895",@probe?.Bot,false);
            probe.Bot.Mover?.LocalAvoidance?.GClass492DropOffset("R1-E6BC531E4AFA",@probe?.Bot);
            probe.Bot.BotOwnerSetTargetMoveSpeed("R1-6F1276094E85",@probe?.Bot,ProbeMomentumNormalMoveSpeed);
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-E1AF6A1BD009",@probe?.Bot,exitDirection);
            HoldForwardInput(probe);

            string vaultTickError = null;
            bool vaultTickInvoked = TryTickNativeVaultScanner(probe.Player, out vaultTickError);

            bool movementContextResult = false;
            bool directComponentAttempted = false;
            bool directComponentResult = false;
            string directComponentError = null;
            try
            {
                movementContextResult = probe.Player.MovementContext.MovementContextTryVaulting("R1-15BEFA6792C9",@probe?.Bot);
            }
            catch (Exception ex)
            {
                directComponentError = "MovementContext:" + ex.GetType().Name + ":" + ex.Message;
            }

            if (!movementContextResult && probe.Player.VaultingComponent != null)
            {
                directComponentAttempted = true;
                try
                {
                    directComponentResult = probe.Player.VaultingComponent.IVaultingComponentTryVaulting("R1-12C7264716B4",@probe?.Bot);
                }
                catch (Exception ex)
                {
                    directComponentError = "VaultingComponent:" + ex.GetType().Name + ":" + ex.Message;
                }
            }

            bool accepted = movementContextResult || directComponentResult;
            WriteEvent("vaultProbeEgressNativeAttempt", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                result = accepted,
                movementContextResult,
                directComponentAttempted,
                directComponentResult,
                directComponentError,
                vaultTickInvoked,
                vaultTickError,
                current = Vec(current),
                exit = Vec(commitment.Exit),
                exitDistance,
                entryDistance,
                parameters = CreateVaultParameterPayload(probe.Player)
            });

            if (!accepted)
            {
                return false;
            }

            TransitionProbeStage(probe, ProbeStage.WaitingForState);
            probe.StageStartedAt = Time.time;
            probe.SawVaultState = false;
            probe.ExclusiveMoverGate = true;
            return true;
        }

        private static void UpdatePostTraversalEgress(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || probe.Player?.MovementContext == null)
            {
                return;
            }

            Player player = probe.Player;
            Vector3 toExit = probe.EgressTarget - player.Position;
            toExit.y = 0f;
            float distance = toExit.magnitude;
            bool supported = IsEffectivelySupportedForProbe(probe.Bot, player);

            if (distance <= ProbePostTraversalEgressCompletionDistance && supported)
            {
                if (TryGetPreferredLandingNavMesh(probe, out NavMeshHit navHit, out string navFailure, out _))
                {
                    if (!TryReanchorAndRelease(probe, navHit.position, "climbEgressCompleted", out string reanchorFailure))
                    {
                        EnterSafetyHold(probe, reanchorFailure);
                    }
                    return;
                }

                EnterSafetyHold(probe, "climb egress reached exit but re-anchor failed: " + navFailure);
                return;
            }

            bool combat = FollowerStateAuthorityCoordinator.HasCombatMovementClaim(probe.Bot, out _);
            if (combat)
            {
                if (TryGetSafeLandingNavMesh(player.Position, out NavMeshHit combatNav, out _))
                {
                    TryReanchorAndRelease(probe, combatNav.position, "climbEgressCombatAbort", out _);
                    return;
                }
                FinishProbeWithoutReanchor(probe, "climbEgressCombatAbort", "combat resumed during post-traversal egress");
                return;
            }

            if (distance + 0.04f < probe.EgressLastDistance)
            {
                probe.EgressLastDistance = distance;
                probe.EgressLastProgressAt = Time.time;
            }
            else if (Time.time - probe.EgressLastProgressAt > 0.60f)
            {
                FinishPostTraversalEgressAtCurrentPosition(probe, "climbEgressNoProgress");
                return;
            }

            if (Time.time - probe.StageStartedAt > ProbePostTraversalEgressTimeout)
            {
                FinishPostTraversalEgressAtCurrentPosition(probe, "climbEgressTimeout");
                return;
            }

            if (toExit.sqrMagnitude <= 0.0001f)
            {
                FinishPostTraversalEgressAtCurrentPosition(probe, "climbEgressZeroDirection");
                return;
            }

            Vector3 direction = toExit / distance;
            probe.Bot.Mover.SetBotMoverPause("R1-699149B5327F",@probe?.Bot,false);
            probe.Bot.BotOwnerSetTargetMoveSpeed("R1-8CBE1B238B81",@probe?.Bot,ProbeMomentumNormalMoveSpeed);
            probe.Bot.Steering?.BotSteeringLookToDirection("R1-A7CA16A7B21B",@probe?.Bot,direction);
            HoldForwardInput(probe);

            float deltaTime = Mathf.Max(0.001f, Time.deltaTime);
            float stepDistance = Mathf.Min(distance, ProbePostTraversalEgressSpeed * deltaTime);
            try
            {
                // Safe step-off uses EFT's MovementContext/character controller: no transform write,
                // teleport, layer change or collision disable occurs here.
                player.MovementContext.TryMovementContextApplyApproachMotion("R1-2726268BA2BE",@probe?.Bot,direction * stepDistance,deltaTime);
            }
            catch (Exception ex)
            {
                FinishPostTraversalEgressAtCurrentPosition(
                    probe,
                    "climbEgressMotionException:" + ex.GetType().Name);
            }
        }

        private static void FinishPostTraversalEgressAtCurrentPosition(ProbeRuntime probe, string reason)
        {
            if (probe?.Player == null || !IsActiveProbe(probe))
            {
                return;
            }

            if (TryGetPreferredLandingNavMesh(probe, out NavMeshHit preferred, out _, out bool usedExit) &&
                (usedExit || Vector3.Distance(preferred.position, probe.Player.Position) <= 1.25f))
            {
                if (TryReanchorAndRelease(probe, preferred.position, reason, out _))
                {
                    return;
                }
            }

            if (TryGetSafeLandingNavMesh(probe.Player.Position, out NavMeshHit current, out string currentFailure))
            {
                if (TryReanchorAndRelease(probe, current.position, reason + "Current", out _))
                {
                    return;
                }
            }

            EnterSafetyHold(probe, reason + ": " + currentFailure);
        }

        private static bool TryValidatePostTraversalEgressCorridor(
            Player player,
            Vector3 start,
            Vector3 exit,
            out string failure,
            out string blocker)
        {
            failure = string.Empty;
            blocker = string.Empty;
            Vector3 planar = exit - start;
            float verticalDelta = Mathf.Abs(planar.y);
            planar.y = 0f;
            float distance = planar.magnitude;
            if (distance < ProbePostTraversalEgressCompletionDistance || distance > 2.60f)
            {
                failure = $"egress distance is outside safe range ({distance:0.00}m)";
                return false;
            }
            if (verticalDelta > ProbePostTraversalExitMaxVerticalOffset)
            {
                failure = $"egress vertical delta is unsafe ({verticalDelta:0.00}m)";
                return false;
            }

            Vector3 direction = planar / distance;
            GetCapabilityCorridorCapsule(player,start,out var capsuleBottom,out var capsuleTop,out float capsuleRadius);
            if (TryGetFirstNonSelfCapsuleCastHit(
                    player,
                    capsuleBottom,
                    capsuleTop,
                    capsuleRadius,
                    direction,
                    Mathf.Max(0.05f, distance - 0.08f),
                    LayersMaskController.HighPolyWithTerrainMask,
                    out RaycastHit hit))
            {
                blocker = hit.collider?.name ?? "unknown";
                failure = $"egress capsule corridor blocked at {hit.distance:0.00}m";
                return false;
            }

            Vector3 floorOrigin = exit + Vector3.up * WalkThroughFloorProbeHeight;
            if (!TryGetFirstNonSelfRaycastHit(
                    player,
                    floorOrigin,
                    Vector3.down,
                    WalkThroughFloorProbeDistance + 0.5f,
                    LayersMaskController.HighPolyWithTerrainMask,
                    out RaycastHit floorHit))
            {
                failure = "egress exit has no physical floor";
                return false;
            }

            if (Mathf.Abs(floorHit.point.y - exit.y) > ProbePostTraversalExitMaxVerticalOffset)
            {
                failure = "egress exit floor is too far from learned exit";
                blocker = floorHit.collider?.name ?? string.Empty;
                return false;
            }
            return true;
        }

        private static bool TryGetPreferredLandingNavMesh(
            ProbeRuntime probe,
            out NavMeshHit navHit,
            out string failure,
            out bool usedLearnedExit)
        {
            navHit = default;
            failure = string.Empty;
            usedLearnedExit = false;
            if (probe?.Player == null)
            {
                failure = "landing player unavailable";
                return false;
            }

            if (TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) &&
                NavMesh.SamplePosition(commitment.Exit, out NavMeshHit exitHit, ProbePostTraversalExitSampleRadius, NavMesh.AllAreas))
            {
                float learnedOffset = Mathf.Abs(exitHit.position.y - commitment.Exit.y);
                float playerVerticalOffset = Mathf.Abs(exitHit.position.y - probe.Player.Position.y);
                float exitDistance = GetPlanarDistance(probe.Player.Position, commitment.Exit);
                float entryDistance = GetPlanarDistance(probe.Player.Position, commitment.Entry);
                bool crossed = FollowerCapabilityHelperRules.TryGetPreferredLandingNavMesh_crossed_06748BFE_1(exitDistance,entryDistance);
                if (learnedOffset <= ProbePostTraversalExitMaxVerticalOffset &&
                    playerVerticalOffset <= ProbePostTraversalExitMaxVerticalOffset + 0.35f &&
                    crossed)
                {
                    navHit = exitHit;
                    usedLearnedExit = true;
                    WriteEvent("vaultProbeExitSideNavMeshPreferred", probe.Bot, new
                    {
                        edgeId = commitment.EdgeId,
                        exit = Vec(commitment.Exit),
                        navMesh = Vec(exitHit.position),
                        exitDistance,
                        entryDistance
                    });
                    return true;
                }
            }

            if (TryGetSafeLandingNavMesh(probe.Player.Position, out navHit, out failure))
            {
                return true;
            }
            return false;
        }

        private static bool TryGetLearningV354DirectionalProgressGeometry(ProbeRuntime probe, out Vector3 entry, out Vector3 exit, out Vector3 axis, out float span)
        {
            entry = default; exit = default; axis = default; span = 0f;
            if ((probe?.Player == null) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) || commitment == null)
            {
                return false;
            }
            entry = IsFinite(commitment.RawEntry) ? commitment.RawEntry : commitment.Entry;
            exit = IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit;
            axis = exit - entry; axis.y = 0f; span = axis.magnitude;
            if (!IsFinite(entry) || !IsFinite(exit) || span < 0.20f) return false;
            axis /= span;
            return true;
        }

        private static void UpdateLearningV354DirectionalProgress(ProbeRuntime probe)
        {
            if (!TryGetLearningV354DirectionalProgressGeometry(probe, out Vector3 entry, out _, out Vector3 axis, out float span)) return;
            Vector3 offset = probe.Player.Position - entry; offset.y = 0f;
            float projection = Vector3.Dot(offset, axis);
            Vector3 lateralVector = offset - axis * projection;
            float lateral = lateralVector.magnitude;
            float entryDistance = GetPlanarDistance(probe.Player.Position, entry);
            if (!probe.LearningV354DirectionalProgressInitialized)
            {
                probe.LearningV354DirectionalProgressInitialized = true;
                probe.LearningV354BestRouteProjection = projection;
                probe.LearningV354BestEntryDistance = entryDistance;
                probe.LearningV354BestLateralOffset = lateral;
                probe.LearningV354LastDirectionalProgressAt = Time.time;
                probe.LearningV354WrongWaySince = -1f;
                return;
            }
            bool beforeFarSide = FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_beforeFarSide_864FC014_1(probe.LearningV354BestRouteProjection,span);
            bool projectionAdvanced = FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_projectionAdvanced_864FC014_2(projection,span,LearningV354RouteFarSideProgressMargin) &&
                FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_projectionAdvanced_864FC014_3(projection,probe.LearningV354BestRouteProjection,LearningV354RouteDirectionalProgressEpsilon);
            bool entryApproached = FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_entryApproached_864FC014_4(beforeFarSide,projection) &&
                FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_entryApproached_864FC014_5(entryDistance,probe.LearningV354BestEntryDistance,LearningV354RouteDirectionalProgressEpsilon);
            bool corridorRecovered = FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_corridorRecovered_864FC014_6(lateral,probe.LearningV354BestLateralOffset,LearningV354RouteDirectionalProgressEpsilon);
            if (projectionAdvanced || entryApproached || corridorRecovered)
            {
                probe.LearningV354BestRouteProjection = Mathf.Max(probe.LearningV354BestRouteProjection, projection);
                probe.LearningV354BestEntryDistance = Mathf.Min(probe.LearningV354BestEntryDistance, entryDistance);
                probe.LearningV354BestLateralOffset = Mathf.Min(probe.LearningV354BestLateralOffset, lateral);
                probe.LearningV354LastDirectionalProgressAt = Time.time;
                probe.LearningV354WrongWaySince = -1f;
                probe.TraversalLastMeaningfulProgressAt = Time.time;
                probe.TraversalLastMeaningfulPosition = probe.Player.Position;
                return;
            }
            bool routeRegressed = FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_routeRegressed_864FC014_7(projection,probe.LearningV354BestRouteProjection,LearningV354RouteWrongWayProjectionSlack);
            bool entryRegressed = projection <= 0.25f && FollowerCapabilityHelperRules.UpdateLearningV354DirectionalProgress_entryRegressed_864FC014_8(entryDistance,probe.LearningV354BestEntryDistance,LearningV354RouteWrongWayEntryDistanceSlack);
            if (routeRegressed || entryRegressed)
            {
                if (probe.LearningV354WrongWaySince < 0f) probe.LearningV354WrongWaySince = Time.time;
            }
            else
            {
                probe.LearningV354WrongWaySince = -1f;
            }
        }

        private static void UpdateTraversalMeaningfulProgress(ProbeRuntime probe)
        {
            if (probe?.Player == null)
            {
                return;
            }
            Vector3 position = probe.Player.Position;
            if (!IsFinite(position))
            {
                return;
            }
            if ((!IsProbeTraversalState(probe.Player.CurrentStateName)))
            {
                UpdateLearningV354DirectionalProgress(probe);
                return;
            }
            if (!IsFinite(probe.TraversalLastMeaningfulPosition) ||
                GetPlanarDistance(position, probe.TraversalLastMeaningfulPosition) >= TraversalMeaningfulProgressDistance)
            {
                probe.TraversalLastMeaningfulPosition = position;
                probe.TraversalLastMeaningfulProgressAt = Time.time;
            }
        }

        private static bool IsTraversalHardStuck(ProbeRuntime probe, out string reason)
        {
            reason = string.Empty;
            if (probe?.Player == null || probe.Bot == null)
            {
                reason = "invalidProbe";
                return false;
            }

            if (FollowerStateAuthorityCoordinator.IsLocomotionFaulted(
                    probe.Bot,
                    out float locomotionFaultRemaining,
                    out string locomotionFaultReason))
            {
                reason = $"locomotionFault:{locomotionFaultReason}:{locomotionFaultRemaining:0.00}s";
                return true;
            }

            if (IsProbeTraversalState(probe.Player.CurrentStateName))
            {
                if (probe.TraversalLastMeaningfulProgressAt <= 0f || !IsFinite(probe.TraversalLastMeaningfulPosition))
                {
                    probe.TraversalLastMeaningfulPosition = probe.Player.Position;
                    probe.TraversalLastMeaningfulProgressAt = Time.time;
                    reason = "nativeProgressBaselineInitialized";
                    return false;
                }

                float nativeStalledFor = Mathf.Max(0f, Time.time - probe.TraversalLastMeaningfulProgressAt);
                Vector3 nativeFlatVelocity = probe.Player.Velocity;
                nativeFlatVelocity.y = 0f;
                if (nativeStalledFor >= TraversalHardStuckSeconds && nativeFlatVelocity.magnitude <= TraversalHardStuckVelocity)
                {
                    reason = $"staleNativeTraversalState:{probe.Player.CurrentStateName}:{nativeStalledFor:0.00}s";
                    return true;
                }

                reason = "nativeTraversalStateActive";
                return false;
            }
            BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(probe.Bot.ProfileId);
            if (follower?.IsTeleportStabilizing == true)
            {
                reason = "teleportTransactionActive";
                return false;
            }
            if (probe.TraversalLastMeaningfulProgressAt <= 0f || !IsFinite(probe.TraversalLastMeaningfulPosition))
            {
                probe.TraversalLastMeaningfulPosition = probe.Player.Position;
                probe.TraversalLastMeaningfulProgressAt = Time.time;
                reason = "progressBaselineInitialized";
                return false;
            }
            float stalledFor = Mathf.Max(0f, Time.time - probe.TraversalLastMeaningfulProgressAt);
            Vector3 flatVelocity = probe.Player.Velocity;
            flatVelocity.y = 0f;
            if ((probe.LearningV354DirectionalProgressInitialized))
            {
                float directionalStalledFor = probe.LearningV354LastDirectionalProgressAt > 0f
                    ? Mathf.Max(0f, Time.time - probe.LearningV354LastDirectionalProgressAt)
                    : stalledFor;
                if (probe.LearningV354WrongWaySince > 0f &&
                    Time.time - probe.LearningV354WrongWaySince >= LearningV354RouteWrongWayGraceSeconds)
                {
                    reason = $"routeWrongWay:{Time.time - probe.LearningV354WrongWaySince:0.00}s:speed={flatVelocity.magnitude:0.00}";
                    return true;
                }
                if (directionalStalledFor >= TraversalHardStuckSeconds)
                {
                    reason = $"routeNoDirectionalProgress:{directionalStalledFor:0.00}s:speed={flatVelocity.magnitude:0.00}";
                    return true;
                }
            }
            if (flatVelocity.magnitude > TraversalHardStuckVelocity)
            {
                reason = $"moving:{flatVelocity.magnitude:0.00}mps";
                return false;
            }
            if (stalledFor < TraversalHardStuckSeconds)
            {
                reason = $"noProgressOnly:{stalledFor:0.00}s";
                return false;
            }
            reason = $"physicalNoProgress:{stalledFor:0.00}s";
            return true;
        }

        private static bool IsCredibleSettledExit(
            string kind,
            Vector3 rawEntry,
            Vector3 rawExit,
            Vector3 settledExit)
        {
            if (!IsFinite(rawExit) || !IsFinite(settledExit))
            {
                return false;
            }
            Vector3 axis = GetFlatDirection(rawExit - rawEntry);
            Vector3 runOut = settledExit - rawExit;
            runOut.y = 0f;
            if (axis.sqrMagnitude > 0.5f && Vector3.Dot(runOut, axis) < -TraversalSettledExitBacktrackSlack)
            {
                return false;
            }
            if (string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                runOut.magnitude > WalkThroughSettledRunOutMaxDistance)
            {
                return false;
            }
            return true;
        }

        private static bool TryGetLearnedCommitmentForProbe(ProbeRuntime probe, out LearnedTraversalCommitment commitment)
        {
            commitment = null;
            if (probe?.FrozenTraversalCommitment != null &&
                (probe.LearnedEdgeId <= 0 || probe.FrozenTraversalCommitment.EdgeId == probe.LearnedEdgeId))
            {
                commitment = probe.FrozenTraversalCommitment;
                return true;
            }

            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            bool found = !string.IsNullOrEmpty(profileId) &&
                         LearnedTraversalCommitments.TryGetValue(profileId, out commitment) &&
                         (probe.LearnedEdgeId <= 0 || commitment.EdgeId == probe.LearnedEdgeId);
            if (found)
            {
                if (!IsLearningV319TransientSkillTransfer(commitment))
                {
                    RefreshLearnedCommitmentAnchors(commitment);
                }
                if (probe != null && probe.LearnedEdgeId > 0)
                {
                    probe.FrozenTraversalCommitment = CloneTraversalCommitment(commitment);
                    commitment = probe.FrozenTraversalCommitment;
                }
            }
            return found;
        }

        private static LearnedTraversalCommitment CloneTraversalCommitment(LearnedTraversalCommitment source)
        {
            if (source == null)
            {
                return null;
            }
            return new LearnedTraversalCommitment
            {
                EdgeId = source.EdgeId,
                EpisodeId = source.EpisodeId,
                ChainId = source.ChainId,
                Entry = source.Entry,
                Exit = source.Exit,
                RawEntry = source.RawEntry,
                RawExit = source.RawExit,
                HasSettledEntry = source.HasSettledEntry,
                SettledEntry = source.SettledEntry,
                HasSettledExit = source.HasSettledExit,
                SettledExit = source.SettledExit,
                Kind = source.Kind,
                ChainLocalExecutable = source.ChainLocalExecutable,
                TraversalAdjacentSuccessor = source.TraversalAdjacentSuccessor,
                SkillTransferTransient = source.SkillTransferTransient,
                SkillTemplateEdgeId = source.SkillTemplateEdgeId,
                SkillTransferParentAttemptId = source.SkillTransferParentAttemptId,
                SkillTransferSource = source.SkillTransferSource,
                LearningV382RouteBoundTransientNativeSkill = source.LearningV382RouteBoundTransientNativeSkill,
                SkillTransferNearFrontier = source.SkillTransferNearFrontier,
                SkillTransferFarFrontier = source.SkillTransferFarFrontier,
                RouteMissionId = source.RouteMissionId,
                RouteMissionStepIndex = source.RouteMissionStepIndex,
                ExpiresAt = source.ExpiresAt,
                LastEntryDistance = source.LastEntryDistance,
                LastEntryProgressAt = source.LastEntryProgressAt,
                NextApproachPathAttemptAt = source.NextApproachPathAttemptAt,
                ApproachPathFailures = source.ApproachPathFailures,
                LastApproachPathRejectedAt = source.LastApproachPathRejectedAt,
                LearningV442HasCurrentEpisodeJumpTakeoffFrontier =
                    source.LearningV442HasCurrentEpisodeJumpTakeoffFrontier,
                LearningV442CurrentEpisodeJumpTakeoffFrontier =
                    source.LearningV442CurrentEpisodeJumpTakeoffFrontier,
                LastLeaderDistanceAtEntryProgress = source.LastLeaderDistanceAtEntryProgress,
                GrenadeHandsBlockedSince = source.GrenadeHandsBlockedSince,
                NextGrenadeHandsRecoveryAt = source.NextGrenadeHandsRecoveryAt,
                GrenadeHandsRecoveryAttempts = source.GrenadeHandsRecoveryAttempts
            };
        }

        private static void RefreshLearnedCommitmentAnchors(LearnedTraversalCommitment commitment)
        {
            if (commitment == null || commitment.EdgeId <= 0 || IsLearningV319TransientSkillTransfer(commitment))
            {
                return;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == commitment.EdgeId);
            if (edge == null)
            {
                return;
            }

            bool forward = Vector3.Distance(commitment.RawEntry, edge.RawStart) <=
                           Vector3.Distance(commitment.RawEntry, edge.RawEnd);
            bool hasSettledEntry = forward ? edge.HasSettledStart : edge.HasSettledEnd;
            Vector3 settledEntry = forward ? edge.SettledStart : edge.SettledEnd;
            bool hasSettledExit = forward ? edge.HasSettledEnd : edge.HasSettledStart;
            Vector3 settledExit = forward ? edge.SettledEnd : edge.SettledStart;

            if (hasSettledEntry && IsFinite(settledEntry))
            {
                commitment.HasSettledEntry = true;
                commitment.SettledEntry = settledEntry;
            }
            if (hasSettledExit && IsFinite(settledExit) &&
                IsCredibleSettledExit(commitment.Kind, commitment.RawEntry, commitment.RawExit, settledExit))
            {
                commitment.HasSettledExit = true;
                commitment.SettledExit = settledExit;
                commitment.Exit = settledExit;
            }
        }

        private static void RegisterPostTraversalEntryQuarantine(ProbeRuntime probe, int edgeIdOverride = 0)
        {
            string profileId = probe?.Bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) || !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment))
            {
                return;
            }

            float entryDistance = GetPlanarDistance(probe.Player.Position, commitment.Entry);
            float exitDistance = GetPlanarDistance(probe.Player.Position, commitment.Exit);
            if (exitDistance > entryDistance + 0.35f)
            {
                return;
            }

            int quarantineEdgeId = edgeIdOverride > 0 ? edgeIdOverride : commitment.EdgeId;
            PostTraversalEntryQuarantines[profileId] = new PostTraversalEntryQuarantine
            {
                EdgeId = quarantineEdgeId,
                Entry = commitment.Entry,
                Exit = commitment.Exit,
                ExpiresAt = Time.time + ProbePostTraversalEntryQuarantineSeconds
            };
            WriteEvent("followTraversalEntrySideQuarantined", probe.Bot, new
            {
                edgeId = quarantineEdgeId,
                entry = Vec(commitment.Entry),
                exit = Vec(commitment.Exit),
                seconds = ProbePostTraversalEntryQuarantineSeconds
            });
        }

        private static bool IsPostTraversalEntryBreadcrumbBlocked(
            BotOwner bot,
            Vector3 breadcrumb,
            out Vector3 entry,
            out Vector3 exit)
        {
            entry = default;
            exit = default;
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !PostTraversalEntryQuarantines.TryGetValue(profileId, out PostTraversalEntryQuarantine quarantine))
            {
                return false;
            }

            if (Time.time > quarantine.ExpiresAt)
            {
                PostTraversalEntryQuarantines.Remove(profileId);
                return false;
            }

            entry = quarantine.Entry;
            exit = quarantine.Exit;
            if (GetPlanarDistance(breadcrumb, quarantine.Entry) > ProbePostTraversalEntryRejectRadius)
            {
                return false;
            }

            float followerEntry = GetPlanarDistance(bot.Position, quarantine.Entry);
            float followerExit = GetPlanarDistance(bot.Position, quarantine.Exit);
            return followerExit + 0.20f < followerEntry || followerExit <= 1.50f;
        }

        private static bool HasMeaningfulTraversalProgress(ProbeRuntime probe, out float forwardProgress, out float planarDisplacement)
        {
            forwardProgress = 0f;
            planarDisplacement = 0f;
            if (probe?.Player == null)
            {
                return false;
            }

            Vector3 origin = probe.TriggerPosition != Vector3.zero ? probe.TriggerPosition : probe.StartPosition;
            Vector3 delta = probe.Player.Position - origin;
            Vector3 planar = new Vector3(delta.x, 0f, delta.z);
            planarDisplacement = planar.magnitude;
            Vector3 direction = GetFlatDirection(probe.RequestedDirection);
            if (direction.sqrMagnitude >= 0.5f)
            {
                forwardProgress = Vector3.Dot(planar, direction);
            }
            else
            {
                forwardProgress = planarDisplacement;
            }

            return planarDisplacement >= ProbeCompletionMinForwardProgress &&
                   forwardProgress >= ProbeCompletionMinForwardProgress * 0.75f;
        }

        private static bool IsLearnedTraversalCompletionSuccessful(ProbeRuntime probe, string reason)
        {
            if (probe == null || probe.LearnedEdgeId <= 0 || probe.Player == null ||
                IsTraversalExecutionFailure(reason) ||
                (!string.IsNullOrEmpty(reason) &&
                 (reason.IndexOf("Blocked", StringComparison.OrdinalIgnoreCase) >= 0 ||
                  reason.IndexOf("Abort", StringComparison.OrdinalIgnoreCase) >= 0 ||
                  reason.IndexOf("Timeout", StringComparison.OrdinalIgnoreCase) >= 0)))
            {
                return false;
            }

            if (!TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment commitment) || commitment == null)
            {
                return false;
            }

            if (probe.WalkThroughMicroTeleported &&
                string.Equals(reason, "walkThroughMicroTeleportCompleted", StringComparison.Ordinal))
            {
                return true;
            }

            if (probe.TraversalEgressTimedOut && !probe.TraversalTeleportAttempted && !probe.TeleportFallbackUsed)
            {
                return false;
            }

            float entryDistance = GetPlanarDistance(probe.Player.Position, commitment.Entry);
            float exitDistance = GetPlanarDistance(probe.Player.Position, commitment.Exit);
            bool walk = string.Equals(commitment.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase);
            float exitTolerance = walk ? 0.80f : 1.10f;
            bool crossedToExitSide = FollowerCapabilityHelperRules.IsLearnedTraversalCompletionSuccessful_crossedToExitSide_73909007_1(exitDistance,entryDistance,exitDistance,exitTolerance);
            return crossedToExitSide && exitDistance <= exitTolerance;
        }

        private static TraversalCompletionMode GetTraversalCompletionMode(ProbeRuntime probe, string reason)
        {
            if (probe?.TeleportFallbackUsed == true)
            {
                return TraversalCompletionMode.TeleportFallback;
            }

            if (probe?.AssistedReplayAttempted == true)
            {
                return TraversalCompletionMode.AssistedReplay;
            }

            if (probe?.NativeLandingRejected == true)
            {
                return TraversalCompletionMode.Legacy;
            }

            if (probe?.NativeTraversalStarted == true ||
                IsLearningV31WalkThroughNativeLocomotionEvidence(probe))
            {
                return TraversalCompletionMode.Native;
            }

            return TraversalCompletionMode.Legacy;
        }

        private static bool TryReanchorAndRelease(
            ProbeRuntime probe,
            Vector3 navMeshPosition,
            string reason,
            out string failure)
        {
            failure = string.Empty;
            if (probe == null || !IsLiveBot(probe.Bot))
            {
                failure = "selected follower is unavailable";
                return false;
            }

            // A legacy scanner rescue can still belong to the original semantic probe.
            // Dispose its separate physical strategy before a re-anchor exposes it to Follow.
            bool capabilityTerminalVerified =
                string.Equals(reason, "nativeExitSideCompleted", StringComparison.Ordinal) ||
                IsLearnedTraversalCompletionSuccessful(probe, reason);
            if (TryHandleCapabilityRescueTerminal(probe, capabilityTerminalVerified, reason))
                return true;

            // R8.8 compatibility guard for legacy completion call-sites. A short local NavMesh
            // re-anchor is not proof that Jump/Climb reached a useful follower route. If this is an
            // active Route Mission and the candidate is an isolated island, keep traversal ownership
            // and consume the player's downstream breadcrumb continuation instead of releasing Follow.
            if (TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment routeCommitment) &&
                routeCommitment != null &&
                TryGetActiveFollowerRouteMission(probe.Bot, out FollowerRouteMission routeMission) &&
                routeCommitment.RouteMissionId == routeMission.MissionId)
            {
                bool bridgeKind = IsLearningV340DownstreamBridgeKind(routeCommitment.Kind);
                if (bridgeKind && !HasTraversalDownstreamConnectivity(
                        probe, routeCommitment, navMeshPosition, out _, out _))
                {
                    if (TryBeginPlayerRouteContinuationBridge(
                            probe, routeCommitment, "legacyReanchorDisconnected:" + (reason ?? "unknown")))
                    {
                        return true;
                    }
                    failure = "candidate NavMesh anchor is not connected to the downstream Player Route Mission";
                    return false;
                }
            }

            bool learningV434EarlyVerifiedSuccess = capabilityTerminalVerified;
            if ((!learningV434EarlyVerifiedSuccess))
            {
                // A semantic completion rejection can still follow a real Jump/Vault/Climb body
                // displacement. Commit that physical body BEFORE StopMove/GoToPoint exposes stale
                // BotMover link anchors to EFT method_12.
                TryCommitLearningV433FailedPhysicalActuatorEpoch(
                    probe, "learningV434TerminalReanchorRejected:" + (reason ?? "unknown"));
            }

            RestoreProbeInput(probe);
            probe.Bot.BotOwnerStopMove("R1-0890B2D6BAE7",@probe?.Bot);
            NavMeshPathStatus anchorStatus;
            try
            {
                anchorStatus = probe.Bot.BotOwnerGoToPoint(
"R1-DC66316B9F4A",@probe?.Bot,                    navMeshPosition,                    true,                    0.2f,                    false,                    false,                    false,                    true,                    true);
            }
            catch (Exception ex)
            {
                failure = $"NavMesh re-anchor threw {ex.GetType().Name}: {ex.Message}";
                return false;
            }

            if (anchorStatus == NavMeshPathStatus.PathInvalid)
            {
                failure = "the short NavMesh re-anchor path was invalid";
                return false;
            }

            WriteEvent("vaultProbeCompleted", probe.Bot, new
            {
                reason,
                kind = probe.TraversalKind,
                start = Vec(probe.StartPosition),
                trigger = Vec(probe.TriggerPosition),
                landing = Vec(probe.Player.Position),
                landingNavMesh = Vec(navMeshPosition),
                displacement = Vector3.Distance(probe.StartPosition, probe.Player.Position),
                anchorStatus = anchorStatus.ToString(),
                elapsed = Time.time - probe.RequestedAt
            });

            string botName = GetBotName(probe.Bot);
            if (probe.LearnedEdgeId > 0)
            {
                TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment completedCommitment);
                bool zeroShotTransfer = IsLearningV319TransientSkillTransfer(completedCommitment);
                TraversalCompletionMode completionMode = GetTraversalCompletionMode(probe, reason);
                bool learningV348LegacyPhysicalRouteCompletion =
                    completionMode != TraversalCompletionMode.TeleportFallback &&
                    !probe.TraversalTeleportAttempted && !probe.TeleportFallbackUsed;
                bool verifiedSuccess = string.Equals(reason, "nativeExitSideCompleted", StringComparison.Ordinal) ||
                                       IsLearnedTraversalCompletionSuccessful(probe, reason);
                if (zeroShotTransfer)
                {
                    RecordLearningV322ZeroShotTemplateEvidence(
                        probe, completedCommitment, verifiedSuccess, completionMode, reason ?? "traversalCompleted");
                    int completedEdgeId = 0;
                    if (verifiedSuccess && TryPromoteLearningV319TransientSkillInstance(
                            probe, completedCommitment, completionMode, reason, out int promotedEdgeId))
                    {
                        completedEdgeId = promotedEdgeId;
                        RecordTraversalExperience(
                            probe, true, completionMode, reason, edgeIdOverride: promotedEdgeId);
                        if (learningV348LegacyPhysicalRouteCompletion)
                        {
                            RegisterPostTraversalEntryQuarantine(probe, promotedEdgeId);
                            RegisterRecentTraversalCompletion(
                                probe.Bot, promotedEdgeId, completedCommitment,
                                reason ?? "traversalCompleted", completionMode, probe.LearningV322AttemptId);
                        }
                    }
                    else if (!verifiedSuccess)
                    {
                        RecordLearningV319TransientTransferFailure(
                            probe, "legacyReanchorCompletionRejected:" + (reason ?? "completionRejected"));
                    }
                    else
                    {
                        EmitLearningV322TraversalAttemptSummary(
                            probe, true, completionMode, reason ?? "traversalCompleted", completedCommitment.SkillTemplateEdgeId);
                        WriteEvent("learningV319ZeroShotLegacyCompletionNotPersisted", probe.Bot, new
                        {
                            templateEdgeId = completedCommitment.SkillTemplateEdgeId,
                            kind = completedCommitment.Kind,
                            completionMode = completionMode.ToString(),
                            reason = reason ?? string.Empty,
                            retainedNative = false,
                            templateExperienceUnchanged = true
                        });
                    }

                    if (verifiedSuccess && learningV348LegacyPhysicalRouteCompletion)
                    {
                        TryCommitLearningV431EquivalentLocalBarrierSelfRescueSuccess(
                            probe.Bot, probe, completedCommitment, completionMode, reason);
                    }

                    WriteEvent("learningV319ZeroShotLegacyReanchorReleased", probe.Bot, new
                    {
                        templateEdgeId = completedCommitment.SkillTemplateEdgeId,
                        completedEdgeId,
                        kind = completedCommitment.Kind,
                        verifiedSuccess,
                        completionMode = completionMode.ToString(),
                        templateExperienceUnchanged = true
                    });
                }
                else if (verifiedSuccess)
                {
                    RecordTraversalExperience(probe, true, completionMode, reason);
                    if (learningV348LegacyPhysicalRouteCompletion)
                    {
                        RegisterPostTraversalEntryQuarantine(probe);
                        if (completedCommitment != null)
                        {
                            RegisterRecentTraversalCompletion(probe.Bot, probe.LearnedEdgeId, completedCommitment, reason ?? "traversalCompleted", completionMode, probe.LearningV322AttemptId);
                        }
                    }
                    MarkLearnedTraversalEdgeSuccess(probe.LearnedEdgeId, completionMode, probe);
                    if (learningV348LegacyPhysicalRouteCompletion)
                    {
                        MarkFollowerTraversalEpisodeCompleted(probe, probe.TraversalEpisodeId, probe.LearnedEdgeId, probe.MovementWriterGeneration);
                    }
                    else {
                        WriteEvent("learningV348TeleportRecoveryRouteTruthPreserved", probe.Bot, new
                        {
                            episodeId = probe.TraversalEpisodeId, edgeId = probe.LearnedEdgeId,
                            kind = probe.TraversalKind, completionMode = completionMode.ToString(),
                            traversalSuccessRecorded = false, routeCursorAdvanced = false,
                            source = "legacyCompletionPath"
                        });
                    }
                }
                else
                {
                    RecordTraversalExperience(probe, false, completionMode, reason ?? "completionRejected");
                    MarkLearnedTraversalEdgeFailure(probe.LearnedEdgeId, reason ?? "completionRejected");
                    WriteEvent("traversalLinkVerificationRejected", probe.Bot, new
                    {
                        edgeId = probe.LearnedEdgeId,
                        kind = probe.TraversalKind,
                        reason,
                        position = Vec(probe.Player.Position)
                    });
                }
                ClearLearnedTraversalCommitment(probe.Bot, probe.LearnedEdgeId, "traversalCompleted");
            }
            DetachProbeStateHandler(probe);
            UnregisterActiveProbe(probe);
            LogInfo($"vault probe {reason} for {botName}");
            return true;
        }


        private static void UpdateSafetyHoldRecovery(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe) || !IsLiveBot(probe.Bot))
            {
                return;
            }

            BotFollowerPlayer teleportFollower = BossPlayers.GetFollowerByProfileId(probe.Bot.ProfileId);
            if (teleportFollower?.IsTeleportStabilizing == true)
            {
                return;
            }

            // V1.3.22: Unified SafetyHold is terminal/bounded. Never restart Verify from here.
            // If no teleport transaction has been attempted yet, allow exactly one authored-exit
            // transaction; otherwise wait for that transaction to finish and release as failure.
            if (probe.UnifiedTraversalFlow)
            {
                if (!probe.TraversalTeleportAttempted)
                {
                    bool teleportArmed = TryTeleportPlayerValidatedTraversalAtExit(
                        probe,
                        "safetyHoldUnifiedTransaction:" + (probe.SafetyHoldReason ?? "unknown"));
                    if (teleportArmed)
                    {
                        return;
                    }
                    // If Teleport was suppressed because the follower is still physically able to
                    // move, SafetyHold must not manufacture a 3s no-progress condition by parking it
                    // forever. Release the failed traversal after the short bounded hold and let
                    // ordinary Follow / NavigationRecovery take ownership again.
                    if (Time.time - probe.StageStartedAt >= ProbeSafetySoftAbortSeconds)
                    {
                        FinalizeOrEscalateTraversalFailure(
                            probe,
                            "safetyHoldUnifiedReleasedNotStuck:" + (probe.SafetyHoldReason ?? "timeout"));
                    }
                    return;
                }

                if (Time.time - probe.StageStartedAt >= ProbeSafetySoftAbortSeconds)
                {
                    FinalizeOrEscalateTraversalFailure(
                        probe,
                        "safetyHoldUnifiedBoundedRelease:" + (probe.SafetyHoldReason ?? "timeout"));
                }
                return;
            }

            if (Time.time >= probe.NextSafetyRecoveryAttemptAt)
            {
                probe.NextSafetyRecoveryAttemptAt = Time.time + 0.45f;

                // Learned/player-authored traversal exits are authoritative recovery targets. In
                // particular, ClimbUp often leaves the bot on an obstacle top with no NavMesh at
                // all. Never prefer a local NavMesh sample beneath that top, because doing so is
                // what produced the visible rollback to the entry side in V1.3.13.
                bool safetyHoldHardStuck = IsTraversalHardStuck(probe, out string safetyHoldStuckReason);
                LearnedTraversalCommitment routeSafetyCommitment = null;
                bool haveRouteSafetyCommitment =
                    TryGetLearnedCommitmentForProbe(probe, out routeSafetyCommitment) &&
                    routeSafetyCommitment != null;
                FollowerRouteMission routeSafetyMission = null;
                bool routeSafetyOwned = haveRouteSafetyCommitment &&
                    TryGetActiveFollowerRouteMission(probe.Bot, out routeSafetyMission) &&
                    routeSafetyCommitment.RouteMissionId == routeSafetyMission.MissionId;

                if (routeSafetyOwned)
                {
                    WriteEvent("safetyHoldRouteMissionEscalatedMonotonic", probe.Bot, new
                    {
                        missionId = routeSafetyMission.MissionId,
                        edgeId = routeSafetyCommitment.EdgeId,
                        hardStuck = safetyHoldHardStuck,
                        stuckReason = safetyHoldStuckReason,
                        stage = probe.Stage.ToString()
                    });
                    if (EscalateTraversalFailureMonotonic(
                            probe,
                            "safetyHold:" + (safetyHoldStuckReason ?? probe.SafetyHoldReason ?? "unknown")))
                    {
                        return;
                    }
                    FinalizeUnifiedTraversalFailure(
                        probe,
                        "safetyHoldRecoveryTeleportRejected:" + (probe.SafetyHoldReason ?? "unknown"));
                    return;
                }

                if (!probe.TraversalTeleportAttempted && safetyHoldHardStuck && haveRouteSafetyCommitment)
                {
                    LearnedTraversalCommitment commitment = routeSafetyCommitment;
                    Vector3 requestedExit = commitment.HasSettledExit && IsFinite(commitment.SettledExit) &&
                                            IsCredibleSettledExit(commitment.Kind, commitment.RawEntry, commitment.RawExit, commitment.SettledExit)
                        ? commitment.SettledExit
                        : (IsFinite(commitment.RawExit) ? commitment.RawExit : commitment.Exit);
                    if (PrepareForAutomaticRecoveryTeleport(
                        probe.Bot, $"safetyHoldExitHardStuck:{commitment.EdgeId}:{safetyHoldStuckReason}") <= 0)
                    {
                        return;
                    }
                    bool safetyExitTeleported = FollowerSafeTeleport.TryTeleportAcrossTraversalExit(
                        probe.Bot,
                        requestedExit,
                        $"safetyHoldExitHardStuck:{commitment.EdgeId}:{safetyHoldStuckReason}",
                        out Vector3 crossedTo,
                        issuedTeleportGeneration: probe.TeleportWriterGeneration);
                    RestoreTraversalMovementAuthorityAfterTeleportAttempt(
                        probe,
                        safetyExitTeleported ? "safetyHoldExitCommitted" : "safetyHoldExitRejected");
                    if (safetyExitTeleported)
                    {
                        WriteEvent("vaultProbeSafetyExitTeleport", probe.Bot, new
                        {
                            edgeId = commitment.EdgeId,
                            reason = probe.SafetyHoldReason,
                            from = Vec(probe.Player.Position),
                            exit = Vec(commitment.Exit),
                            teleportedTo = Vec(crossedTo)
                        });

                        if (NavMesh.SamplePosition(crossedTo, out NavMeshHit crossedNav, 1.75f, NavMesh.AllAreas) &&
                            TryReanchorAndRelease(probe, crossedNav.position, "safetyHoldExitTeleportCompleted", out _))
                        {
                            return;
                        }
                    }
                }
                else
                {
                    Player player = probe.Player;
                    bool supported =
                        player?.MovementContext != null &&
                        IsEffectivelySupportedForProbe(probe.Bot, player) &&
                        !IsProbeTraversalState(player.CurrentStateName);

                    NavMeshHit navHit = default(NavMeshHit);
                    string navFailure = "no safe landing NavMesh candidate";
                    if (supported && TryGetSafeLandingNavMesh(player.Position, out navHit, out navFailure))
                    {
                        if (TryReanchorAndRelease(probe, navHit.position, "safetyHoldAutoRecovered", out string reanchorFailure))
                        {
                            return;
                        }

                        WriteEvent("vaultProbeSafetyAutoRecoverFailed", probe.Bot, new
                        {
                            reason = reanchorFailure,
                            position = Vec(player.Position)
                        });
                    }
                    else if (supported)
                    {
                        WriteEvent("vaultProbeSafetyAutoRecoverFailed", probe.Bot, new
                        {
                            reason = string.IsNullOrEmpty(navFailure) ? "no safe landing NavMesh candidate" : navFailure,
                            position = Vec(player.Position)
                        });
                    }
                }
            }

            // V1.3.22: SafetyHold is no longer a retry loop. A player-authored traversal gets at
            // most the one bounded teleport transaction already recorded by the probe. Once that
            // transaction is gone (or the soft hold expires), release ownership as a failed episode
            // instead of re-entering Verify/SafetyHold forever.
            if (IsActiveProbe(probe) && IsPlayerValidatedTraversalProbe(probe))
            {
                BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(probe.Bot?.ProfileId);
                if (follower?.IsTeleportStabilizing == true)
                {
                    return;
                }
                if (Time.time - probe.StageStartedAt >= ProbeSafetySoftAbortSeconds)
                {
                    if (TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment safetyCommitment) &&
                        safetyCommitment != null &&
                        TryGetActiveFollowerRouteMission(probe.Bot, out FollowerRouteMission safetyMission) &&
                        safetyCommitment.RouteMissionId == safetyMission.MissionId)
                    {
                        if (TryTeleportPlayerValidatedTraversalAtExit(
                                probe, "safetyHoldRouteExhausted:" + (probe.SafetyHoldReason ?? "timeout")))
                        {
                            return;
                        }
                        probe.StageStartedAt = Time.time;
                        if (probe.NativeTraversalStarted || probe.AssistedReplayAttempted || probe.TraversalEgressAttempted)
                        {
                            BeginUnifiedTraversalEgressOrVerify(probe, "safetyHoldRouteRetry");
                        }
                        else
                        {
                            TransitionProbeStage(probe, ProbeStage.Aligning);
                            probe.PoseExclusiveOrientationAuthority = true;
                            probe.AlignStableSince = -1f;
                        }
                        WriteEvent("safetyHoldRouteRecovery", probe.Bot, new
                        {
                            missionId = safetyMission.MissionId,
                            edgeId = probe.LearnedEdgeId,
                            reason = probe.SafetyHoldReason,
                            stage = probe.Stage.ToString()
                        });
                        return;
                    }

                    FinalizeOrEscalateTraversalFailure(
                        probe,
                        "safetyHoldBoundedRelease:" + (probe.SafetyHoldReason ?? "timeout"));
                }
                return;
            }

            if (IsActiveProbe(probe) &&
                Time.time - probe.StageStartedAt >= ProbeSafetySoftAbortSeconds)
            {
                FinishProbeWithoutReanchor(
                    probe,
                    "safetyHoldWatchdogRelease",
                    probe.SafetyHoldReason ?? "safety hold timed out");
            }
        }

        private static void EnterSafetyHold(ProbeRuntime probe, string reason)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            // CompileFix42: SafetyHold is no longer a RouteMission recovery loop. A validated
            // traversal escalates in-place through Assist -> recovery teleport while retaining the
            // same chain cursor. Generic navigation recovery only resumes after the chain releases.
            if (IsPlayerValidatedTraversalProbe(probe) &&
                !probe.TraversalTeleportAttempted &&
                string.IsNullOrEmpty(probe.PendingTeleportSource) &&
                EscalateTraversalFailureMonotonic(probe, "safetyHold:" + (reason ?? "unknown")))
            {
                return;
            }

            RestoreProbeInput(probe);
            TransitionProbeStage(probe, ProbeStage.SafetyHold);
            probe.StageStartedAt = Time.time;
            probe.NextSafetyRecoveryAttemptAt = Time.time + ProbeSafetyAutoRecoverStableSeconds;
            probe.ExclusiveMoverGate = true;
            probe.SafetyHoldReason = reason;
            probe.Bot?.BotOwnerStopMove("R1-98ECEC026BEA",@probe?.Bot);
            WriteEvent("vaultProbeSafetyHold", probe.Bot, new
            {
                reason,
                position = probe.Player != null ? Vec(probe.Player.Position) : null,
                state = probe.Player?.CurrentStateName.ToString()
            });
            LogError($"vault probe safety hold for {GetBotName(probe.Bot)}: {reason}");
        }

        private static bool TryRecordLearningV349ExecutorStrategyVeto(
            ProbeRuntime probe,
            string strategy,
            string reason)
        {
            if ((probe?.Bot == null) || probe.LearnedEdgeId <= 0 ||
                string.IsNullOrWhiteSpace(strategy) ||
                !TryGetActiveFollowerRouteMission(probe.Bot, out FollowerRouteMission mission) || mission == null ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                return false;
            }

            FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            if (step == null || step.EdgeId != probe.LearnedEdgeId)
            {
                return false;
            }

            string key = probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture) + ":" + strategy;
            bool added = mission.LearningV349ExecutorStrategyVetoes.Add(key);
            if (added)
            {
                WriteEvent("learningV349ExecutorStrategyVetoApplied", probe.Bot, new
                {
                    missionId = mission.MissionId,
                    stepIndex = mission.CurrentStepIndex,
                    edgeId = probe.LearnedEdgeId,
                    kind = step.Kind,
                    strategy,
                    reason = reason ?? string.Empty,
                    routeSemanticPreserved = true,
                    persistentLearningChanged = false,
                    action = "rejectExecutorStrategyForCurrentRouteMissionWithoutRejectingPassageSemantic"
                });
            }
            // A previously-recorded veto is still authoritative for this mission. Returning only
            // `added` caused a later terminalizer to misread the second observation as "no veto"
            // and apply semantic failure to the edge. Route truth and executor viability stay split.
            return mission.LearningV349ExecutorStrategyVetoes.Contains(key);
        }

        private static void FinishProbeWithoutReanchor(ProbeRuntime probe, string reason, string details)
        {
            if(TryRequestCapabilityFullRouteRetry(probe,reason,true))return; // A current unpublished route terminal is a failure; the shared admission preserves explicit cancellation.
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }

            {
                TryCommitLearningV433FailedPhysicalActuatorEpoch(
                    probe, "learningV434FinishWithoutReanchor:" + (reason ?? "unknown"));
            }
            RestoreProbeInput(probe);
            WriteEvent("vaultProbeFinished", probe.Bot, new
            {
                reason,
                details,
                stage = probe.Stage.ToString(),
                state = probe.Player?.CurrentStateName.ToString(),
                position = probe.Player != null ? Vec(probe.Player.Position) : null,
                elapsed = Time.time - probe.RequestedAt
            });
            string botName = GetBotName(probe.Bot);
            if (probe.LearnedEdgeId > 0)
            {
                if (TryGetLearningV319TransientSkillTransfer(probe, out _))
                {
                    // Any terminal release without a verified far-side completion is a failed
                    // transfer instance, regardless of whether the legacy reason classifier would
                    // have counted it as an execution failure. Never leave a transient template
                    // commitment alive after its probe has been unregistered.
                    RecordLearningV319TransientTransferFailure(
                        probe, "finishWithoutReanchor:" + (reason ?? "traversalFailed"));
                    ClearLearnedTraversalCommitment(
                        probe.Bot, probe.LearnedEdgeId, "learningV319ZeroShotFinishWithoutReanchor");
                }
                else if (IsTraversalExecutionFailure(reason))
                {
                    bool learningV349ExecutorOnlyFailure =
                        (string.Equals(reason, "scanRefused", StringComparison.OrdinalIgnoreCase)) &&
                        TryRecordLearningV349ExecutorStrategyVeto(
                            probe, "LegacyVaultScanner", "finishWithoutReanchor:scanRefused");
                    if (!learningV349ExecutorOnlyFailure)
                    {
                        MarkLearnedTraversalEdgeFailure(probe.LearnedEdgeId, reason);
                    }
                    else
                    {
                        WriteEvent("learningV349ExecutorFailureSemanticPenaltySuppressed", probe.Bot, new
                        {
                            edgeId = probe.LearnedEdgeId,
                            kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                            strategy = "LegacyVaultScanner",
                            reason,
                            action = "preserveRouteSemanticBecauseOnlyExecutorStrategyWasDisproved"
                        });
                    }
                }
            }
            EnsureLearningV328AttemptTerminalizedBeforeUnregister(
                probe, "finishWithoutReanchor:" + (reason ?? "unknown"));
            DetachProbeStateHandler(probe);
            UnregisterActiveProbe(probe);
            LogInfo($"vault probe ended for {botName}: {reason} ({details})");
        }

        private static void ReleaseProbeForLifecycle(ProbeRuntime probe, string reason)
        {
            if (probe == null)
            {
                return;
            }

            EmitLearningV322TraversalAttemptSummary(
                probe, false, GetTraversalCompletionMode(probe, reason), "lifecycleRelease:" + (reason ?? "unknown"));
            RestoreProbeInput(probe);
            WriteEvent("vaultProbeLifecycleRelease", probe.Bot, new
            {
                reason,
                stage = probe.Stage.ToString()
            });
            RestoreAssistedTraversalAnimation(probe);
            DetachProbeStateHandler(probe);
            UnregisterActiveProbe(probe);
        }

        private static void DetachProbeStateHandler(ProbeRuntime probe)
        {
            try
            {
                if (probe?.Player?.MovementContext != null && probe.StateHandler != null)
                {
                    probe.Player.MovementContext.UnsubscribeMovementContextOnStateChanged("R1-26995F7AEC55",@probe?.Bot,probe.StateHandler);
                }
            }
            catch
            {
                // The player may already be disposed during raid shutdown.
            }
        }

        private static float GetProbeForwardVelocity(Player player)
        {
            try
            {
                return Mathf.Abs(player?.VaultingParameters?.AbsoluteForwardVelocity ?? 0f);
            }
            catch
            {
                return 0f;
            }
        }

        // Shared native probe gait intent is owned by FollowerCapabilityProbeLocomotionHost.

        // Native probe input producer is owned by FollowerCapabilityNativeInputHost.

        private static void TryStartAssistedTraversalAnimation(ProbeRuntime probe)
        {
            if (probe?.Player == null || probe.AssistedAnimationStarted)
            {
                return;
            }

            string kind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? "Vault";
            if (string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }
            if (string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                // CompileFix48: never CrossFade the main Player animator into Fall/Falling for a
                // DropDown assist. Fix47 proved that an interrupted replay can leave the body in a
                // non-locomoting Player layer even though BotMover/path/input all look healthy. EFT
                // owns natural run-off/fall/landing state; assisted position correction is fallback only.
                probe.AssistedAnimationStarted = true;
                probe.AssistedAnimationState = probe.Player.CurrentStateName.ToString();
                WriteEvent("assistedTraversalAnimation", probe.Bot, new
                {
                    phase = "StartNaturalState",
                    kind,
                    played = false,
                    source = "EFTNaturalDropDownState",
                    state = probe.AssistedAnimationState,
                    animator = (string)null,
                    layer = -1
                });
                return;
            }
            {
                probe.AssistedAnimationStarted = true;
                probe.AssistedAnimationState = probe.Player.CurrentStateName.ToString();
                WriteEvent("assistedTraversalAnimation", probe.Bot, new
                {
                    phase = "StartSemanticSuppressed",
                    kind,
                    played = false,
                    source = "LearningV324RecoveryOwnsTraversalSemantics",
                    state = probe.AssistedAnimationState,
                    animator = (string)null,
                    layer = -1
                });
                return;
            }

            string[] candidates = string.Equals(kind, "Climb", StringComparison.OrdinalIgnoreCase)
                ? new[] { "ClimbUp", "Climb", "VaultingClimb" }
                : (string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase)
                    ? new[] { "Jump", "JumpStart" }
                    : new[] { "ClimbOver", "Vault", "Vaulting", "VaultingOver" });

            bool usedPlayerHint = TryCrossFadePlayerAnimatorHint(probe, kind, "Start", false, out string stateName);
            bool played = usedPlayerHint || TryCrossFadeAssistedAnimator(probe, candidates, false, out stateName);
            probe.AssistedAnimationStarted = played;
            probe.AssistedAnimationState = stateName;
            WriteEvent("assistedTraversalAnimation", probe.Bot, new
            {
                phase = "Start",
                kind,
                played,
                source = usedPlayerHint ? "PlayerAnimatorHash" : "NameLookup",
                state = stateName,
                animator = probe.AssistedAnimator != null ? probe.AssistedAnimator.name : null,
                layer = probe.AssistedAnimatorLayer
            });
        }

        private static void TryStartAssistedTraversalLandingAnimation(ProbeRuntime probe)
        {
            if (probe?.Player == null || probe.AssistedLandingAnimationStarted)
            {
                return;
            }

            probe.AssistedLandingAnimationStarted = true;
            string kind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? "Vault";
            if (string.Equals(kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }
            if (string.Equals(kind, "DropDown", StringComparison.OrdinalIgnoreCase))
            {
                WriteEvent("assistedTraversalAnimation", probe.Bot, new
                {
                    phase = "LandNaturalState",
                    kind,
                    played = false,
                    source = "EFTNaturalDropDownState",
                    state = probe.Player.CurrentStateName.ToString(),
                    animator = (string)null,
                    layer = -1
                });
                return;
            }
            {
                WriteEvent("assistedTraversalAnimation", probe.Bot, new
                {
                    phase = "LandSemanticSuppressed",
                    kind,
                    played = false,
                    source = "LearningV324RecoveryOwnsTraversalSemantics",
                    state = probe.Player.CurrentStateName.ToString(),
                    animator = (string)null,
                    layer = -1
                });
                return;
            }

            string[] candidates = string.Equals(kind, "Jump", StringComparison.OrdinalIgnoreCase)
                ? new[] { "JumpLanding", "Landing" }
                : new[] { "VaultingLanding", "Landing" };

            bool usedPlayerHint = TryCrossFadePlayerAnimatorHint(probe, kind, "Land", true, out string stateName, 0.06f);
            bool played = usedPlayerHint || TryCrossFadeAssistedAnimator(probe, candidates, true, out stateName, 0.06f);
            bool locomotionFallback = false;
            if (!played)
            {
                string[] locomotionCandidates = probe.PreviousSprinting
                    ? new[] { "Sprint", "SprintForward", "Run", "Movement" }
                    : (probe.PreviousRunning
                        ? new[] { "Run", "RunForward", "Movement", "Walk" }
                        : new[] { "Walk", "Movement", "Idle" });
                locomotionFallback = TryCrossFadeAssistedAnimator(
                    probe,
                    locomotionCandidates,
                    true,
                    out stateName,
                    0.10f);
                played = locomotionFallback;
            }
            WriteEvent("assistedTraversalAnimation", probe.Bot, new
            {
                phase = locomotionFallback ? "LandLocomotionFallback" : "Land",
                kind,
                played,
                source = usedPlayerHint ? "PlayerAnimatorHash" : (locomotionFallback ? "LocomotionFallback" : "NameLookup"),
                state = stateName,
                animator = probe.AssistedAnimator != null ? probe.AssistedAnimator.name : null,
                layer = probe.AssistedAnimatorLayer
            });
        }

        private static bool TryCrossFadePlayerAnimatorHint(
            ProbeRuntime probe,
            string kind,
            string phase,
            bool preferExistingAnimator,
            out string playedState,
            float blendSeconds = 0.035f)
        {
            playedState = null;
            if (probe?.Player == null ||
                !PlayerTraversalAnimatorHints.TryGetValue(MakeAnimatorHintKey(kind, phase), out PlayerAnimatorHint hint) ||
                hint == null)
            {
                return false;
            }

            try
            {
                Animator[] animators = probe.Player.GetComponentsInChildren<Animator>(true);
                if (animators == null || animators.Length == 0)
                {
                    return false;
                }

                IEnumerable<Animator> ordered = animators
                    .Where(animator => animator != null && animator.runtimeAnimatorController != null);
                if (preferExistingAnimator && probe.AssistedAnimator != null)
                {
                    // Start and landing must stay on the same follower Animator. Searching a second
                    // Animator here would bypass the single root-motion ownership/restore record.
                    ordered = new[] { probe.AssistedAnimator };
                }
                else
                {
                    ordered = ordered.OrderBy(animator =>
                        string.Equals(animator.name, hint.AnimatorName, StringComparison.OrdinalIgnoreCase) ? 0 : 1);
                }

                foreach (Animator animator in ordered)
                {
                    if (hint.Layer < 0 || hint.Layer >= animator.layerCount)
                    {
                        continue;
                    }

                    int hash = hint.FullPathHash;
                    if (hash == 0 || !animator.HasState(hint.Layer, hash))
                    {
                        hash = hint.ShortNameHash;
                    }
                    if (hash == 0 || !animator.HasState(hint.Layer, hash))
                    {
                        continue;
                    }

                    if (probe.AssistedAnimator == null)
                    {
                        probe.AssistedAnimator = animator;
                        probe.AssistedAnimatorLayer = hint.Layer;
                        probe.AssistedAnimatorPreviousRootMotion = animator.applyRootMotion;
                    }
                    if (ReferenceEquals(probe.AssistedAnimator, animator))
                    {
                        animator.SetAnimatorapplyRootMotion("R1-A488A60B36A2",@probe?.Bot,false);
                    }

                    animator.AnimatorCrossFadeInFixedTime("R1-B27127BC9244",@probe?.Bot,hash,Mathf.Max(0.01f, blendSeconds),hint.Layer,0f);
                    playedState = $"hash:{hash}";
                    return true;
                }
            }
            catch (Exception ex)
            {
                WriteEvent("assistedTraversalAnimationError", probe.Bot, new
                {
                    source = "PlayerAnimatorHash",
                    error = ex.GetType().Name + ": " + ex.Message
                });
            }

            return false;
        }

        private static bool TryCrossFadeAssistedAnimator(
            ProbeRuntime probe,
            string[] stateNames,
            bool preferExistingAnimator,
            out string playedState,
            float blendSeconds = 0.035f)
        {
            playedState = null;
            if (probe?.Player == null || stateNames == null || stateNames.Length == 0)
            {
                return false;
            }

            try
            {
                Animator[] animators = probe.Player.GetComponentsInChildren<Animator>(true);
                if (animators == null || animators.Length == 0)
                {
                    return false;
                }

                IEnumerable<Animator> ordered = animators;
                if (preferExistingAnimator && probe.AssistedAnimator != null)
                {
                    // Keep every assisted animation phase on one Animator so applyRootMotion remains
                    // disabled for the entire replay and can be restored exactly once at release.
                    ordered = new[] { probe.AssistedAnimator };
                }

                foreach (Animator animator in ordered)
                {
                    if (animator == null || animator.runtimeAnimatorController == null)
                    {
                        continue;
                    }

                    for (int layer = 0; layer < animator.layerCount; layer++)
                    {
                        string layerName = animator.GetLayerName(layer);
                        foreach (string stateName in stateNames)
                        {
                            string[] paths =
                            {
                                stateName,
                                "Base Layer." + stateName,
                                string.IsNullOrEmpty(layerName) ? stateName : layerName + "." + stateName
                            };

                            foreach (string path in paths.Distinct(StringComparer.Ordinal))
                            {
                                int hash = Animator.StringToHash(path);
                                if (!animator.HasState(layer, hash))
                                {
                                    continue;
                                }

                                if (probe.AssistedAnimator == null)
                                {
                                    probe.AssistedAnimator = animator;
                                    probe.AssistedAnimatorLayer = layer;
                                    probe.AssistedAnimatorPreviousRootMotion = animator.applyRootMotion;
                                }

                                if (ReferenceEquals(probe.AssistedAnimator, animator))
                                {
                                    animator.SetAnimatorapplyRootMotion("R1-FDF5B3A66806",@probe?.Bot,false);
                                }

                                animator.AnimatorCrossFadeInFixedTime("R1-0B6C9D6BBE57",@probe?.Bot,hash,Mathf.Max(0.01f, blendSeconds),layer,0f);
                                playedState = path;
                                return true;
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                WriteEvent("assistedTraversalAnimationError", probe.Bot, new
                {
                    error = ex.GetType().Name + ": " + ex.Message
                });
            }

            return false;
        }

        private static void RestoreAssistedTraversalAnimation(ProbeRuntime probe)
        {
            if (probe?.AssistedAnimator == null)
            {
                return;
            }

            try
            {
                probe.AssistedAnimator.SetAnimatorapplyRootMotion("R1-148BF53F642F",@probe?.Bot,probe.AssistedAnimatorPreviousRootMotion);
            }
            catch
            {
                // Animator may already be disposed during raid/lifecycle cleanup.
            }

            probe.AssistedAnimator = null;
            probe.AssistedAnimatorLayer = -1;
        }

        private static void RestoreProbeInput(ProbeRuntime probe)
        {
            RestoreAssistedObstacleCollisionLease(probe, "probeInputRestore");
            RestoreAssistedTraversalAnimation(probe);
            try
            {
                if (probe?.Player?.MovementContext == null)
                {
                    return;
                }

                probe.Player.SetPlayerInputDirection("R1-D53F25AB6DC7",@probe?.Bot,probe.PreviousInputDirection);
                probe.Player.MovementContext.SetMovementContextMovementDirection("R1-B9826B5457DF",@probe?.Bot,probe.PreviousMovementDirection);

                if (probe.Bot?.Mover != null && !probe.Bot.IsDead)
                {
                    probe.Bot.Mover.SetBotMoverPause("R1-4FF5AEC8E18C",@probe?.Bot,false);

                    // CompileFix26: restoring only the Sprint boolean left the TargetMoveSpeed
                    // limiter written by WalkThrough/Egress behind. The follower could therefore
                    // leave a successful traversal in permanent Walk even though its pre-traversal
                    // intent was Run/Sprint. Restore the locomotion intent as one transaction.
                    if (probe.PreviousSprinting || probe.PreviousRunning)
                    {
                        probe.Bot.BotOwnerSetTargetMoveSpeed("R1-3266CE5A5747",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                        probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-B0D365EB9ACD",@probe?.Bot,ProbeMomentumFullMoveSpeed);
                    }

                    bool sprintingNow = probe.Bot.Mover.Sprinting;
                    if (probe.PreviousSprinting != sprintingNow)
                    {
                        probe.Bot.Mover.BotMoverSprint("R1-B3F405C7904D",@probe?.Bot,probe.PreviousSprinting,false);
                    }
                }
            }
            catch
            {
                // The movement context may already be disposed during lifecycle cleanup.
            }
        }

        // RC104: EnsureVaultingComponent lives in the shared native obstacle capability host.

        private static bool IsEffectivelySupportedForProbe(BotOwner bot, Player player)
        {
            if (player?.MovementContext == null)
            {
                return false;
            }

            ProbeRuntime probe = null;
            bool sameProbe = TryGetActiveProbe(bot, out probe);

            bool nativeSupport = player.MovementContext.IsGrounded || player.MovementContext.CanJump;
            if (nativeSupport)
            {
                if (sameProbe)
                {
                    probe.LastSupportedAt = Time.time;
                }
                return true;
            }

            if (IsProbeTraversalState(player.CurrentStateName))
            {
                return false;
            }

            // EFT's IsGrounded can flicker false when an AI capsule is standing on the edge of a
            // fence/curb. Treat a non-traversal Run/Idle-style state as supported when the player is
            // still directly over nearby NavMesh. This is deliberately a small vertical/radius window
            // so a genuinely falling bot cannot pass the probe precondition.
            if (NavMesh.SamplePosition(
                    player.Position,
                    out NavMeshHit supportHit,
                    ProbeSupportNavMeshRadius,
                    NavMesh.AllAreas) &&
                Mathf.Abs(player.Position.y - supportHit.position.y) <= ProbeSupportMaxVerticalOffset)
            {
                if (sameProbe)
                {
                    probe.LastSupportedAt = Time.time;
                }
                return true;
            }

            return sameProbe &&
                   probe.LastSupportedAt > 0f &&
                   Time.time - probe.LastSupportedAt <= ProbeEffectiveGroundedGraceSeconds;
        }

        private static bool ValidateProbePreconditions(BotOwner bot, out string failure)
        {
            failure = string.Empty;
            if (!IsLiveBot(bot) || !BossPlayers.IsFollower(bot))
            {
                failure = "not a live PIT follower";
                return false;
            }

            Player player = bot.GetPlayer;
            if (player?.MovementContext == null)
            {
                failure = "follower movement context is unavailable";
                return false;
            }

            // V1.3.15: do not use IsGrounded/NavMesh support as a hard traversal gate. The player
            // proved that short uneven seams and curb/fence lips can flicker unsupported for one or
            // more frames while still being completely traversable. Native traversal state, combat,
            // door/medical/command ownership remain hard safety gates; local support is telemetry only.
            if (IsProbeTraversalState(player.CurrentStateName))
            {
                failure = "follower is already in a traversal state";
                return false;
            }

            bool combatMovementClaim = FollowerStateAuthorityCoordinator.HasCombatMovementClaim(bot, out string combatClaimReason);
            if (combatMovementClaim)
            {
                failure = "follower combat movement authority is active: " + combatClaimReason;
                return false;
            }

            if (bot.DoorOpener?.Interacting == true || bot.Mover?.CurrentState == EBotMoverState.NearDoor)
            {
                failure = "follower is interacting with a door";
                return false;
            }

            if (bot.Medecine?.FirstAid?.Using == true || bot.Medecine?.SurgicalKit?.Using == true)
            {
                failure = "follower is healing";
                return false;
            }

            if (player.HandsController is Player.GrenadeHandsController)
            {
                BotGrenadeController grenades = bot.WeaponManager?.Grenades;
                bool grenadeControllerActive = grenades?.ThrowindNow == true || grenades?.ReadyToThrow == true;
                bool activeGrenadeTransaction =
                    FollowerGrenadeRuntimeGate.IsExplicitThrowActive(bot) ||
                    (grenadeControllerActive && !FollowerGrenadeRuntimeGate.IsCurrentTransactionTerminal(bot));
                if (!activeGrenadeTransaction)
                {
                    FollowerStateAuthorityCoordinator.EnsureGrenadeHandsRecovery(bot, "traversalPrecondition");
                    failure = "follower grenade hands recovery in progress";
                }
                else
                {
                    failure = "follower has an active grenade in hand";
                }
                return false;
            }

            BotFollowerPlayer follower = BossPlayers.GetFollowerByProfileId(bot.ProfileId);
            if (follower != null && follower.TryPeekActiveCommand(out FollowerCommandType command, out _, out _))
            {
                // CompileFix15: legacy PushEnemy could remain stale; live player orders now use a finite target lock, but
                // runtime evidence showed it can remain latched after combat is already gone while
                // the follower has returned to FollowerPatrol. The live combat/under-fire gates above
                // remain authoritative. Only this stale tactical command may yield to a player-authored
                // traversal; positional/loot/door/hold commands still own movement and remain blocking.
                if (command == FollowerCommandType.PushEnemy && !combatMovementClaim)
                {
                    WriteEvent("traversalStalePushEnemyCommandBypassed", bot, new
                    {
                        command = command.ToString(),
                        state = player.CurrentStateName.ToString(),
                        haveEnemy = bot.Memory?.HaveEnemy == true,
                        underFire = bot.Memory?.IsUnderFire == true
                    });
                }
                else
                {
                    failure = $"follower has active command {command}";
                    return false;
                }
            }

            return true;
        }

        private static BotOwner FindNearestEligibleFollower(Player localPlayer, out string failure)
        {
            failure = "no living PIT follower was found";
            List<BotFollowerPlayer> followers = BossPlayers.GetFollowersByBoss(localPlayer.ProfileId);
            if (followers == null || followers.Count == 0)
            {
                return null;
            }

            BotOwner nearest = null;
            float nearestDistance = float.MaxValue;
            foreach (BotFollowerPlayer follower in followers)
            {
                BotOwner bot = follower?.GetBot();
                if (!IsLiveBot(bot) || !BossPlayers.IsFollower(bot))
                {
                    continue;
                }

                float distance = Vector3.Distance(localPlayer.Position, bot.Position);
                if (distance < nearestDistance)
                {
                    nearest = bot;
                    nearestDistance = distance;
                }
            }

            if (nearest == null)
            {
                return null;
            }

            if (nearestDistance > ProbeMaxFollowerDistance)
            {
                failure = $"nearest follower is {nearestDistance:0.0}m away (limit {ProbeMaxFollowerDistance:0}m)";
                return null;
            }

            return nearest;
        }

        private static bool TryGetSafeLandingNavMesh(Vector3 position, out NavMeshHit navHit, out string failure)
        {
            navHit = default;
            failure = string.Empty;
            if (!IsFinite(position))
            {
                failure = "landing position is not finite";
                return false;
            }

            if (!NavMesh.SamplePosition(position, out navHit, ProbeLandingNavMeshRadius, NavMesh.AllAreas))
            {
                failure = $"no NavMesh within {ProbeLandingNavMeshRadius:0.00}m of landing";
                return false;
            }

            float verticalOffset = Mathf.Abs(navHit.position.y - position.y);
            if (verticalOffset > ProbeLandingMaxVerticalOffset)
            {
                failure = $"nearest NavMesh vertical offset is {verticalOffset:0.00}m";
                return false;
            }

            return true;
        }

        private static StrictPathResult CalculateStrictPath(Vector3 rawStart, Vector3 rawTarget)
        {
            StrictPathMicroCacheKey cacheKey = StrictPathMicroCacheKey.From(rawStart, rawTarget, StrictPathMicroCacheCellSize);
            if (StrictPathMicroCache.TryGetValue(cacheKey, out StrictPathMicroCacheEntry cached) &&
                cached != null &&
                Time.time - cached.SampledAt <= StrictPathMicroCacheSeconds)
            {
                return cached.Result;
            }

            StrictPathResult result = new StrictPathResult
            {
                RawStart = rawStart,
                RawTarget = rawTarget,
                Status = NavMeshPathStatus.PathInvalid,
                Corners = Array.Empty<Vector3>()
            };

            result.StartSampled = NavMesh.SamplePosition(rawStart, out NavMeshHit startHit, NavMeshSampleRadius, NavMesh.AllAreas);
            result.TargetSampled = NavMesh.SamplePosition(rawTarget, out NavMeshHit targetHit, NavMeshSampleRadius, NavMesh.AllAreas);
            if (result.StartSampled)
            {
                result.SampledStart = startHit.position;
                result.StartSampleOffset = Vector3.Distance(rawStart, startHit.position);
            }
            if (result.TargetSampled)
            {
                result.SampledTarget = targetHit.position;
                result.TargetSampleOffset = Vector3.Distance(rawTarget, targetHit.position);
            }

            if (!result.StartSampled || !result.TargetSampled)
            {
                StoreStrictPathMicroCache(cacheKey, result);
                return result;
            }

            NavMeshPath path = new NavMeshPath();
            long calculatePathPerfStart = BeginTraversalPerfSample();
            result.CalculateReturned = NavMesh.CalculatePath(
                result.SampledStart,
                result.SampledTarget,
                NavMesh.AllAreas,
                path);
            EndTraversalPerfSample("NavMesh.CalculatePath", calculatePathPerfStart);
            result.Status = path.status;
            result.Corners = path.corners ?? Array.Empty<Vector3>();
            result.PathLength = CalculatePathLength(result.Corners);
            if (result.Corners.Length > 0)
            {
                Vector3 terminal = result.Corners[result.Corners.Length - 1];
                result.TerminalToSampledTarget = Vector3.Distance(terminal, result.SampledTarget);
                result.TerminalToRawTarget = Vector3.Distance(terminal, result.RawTarget);
            }
            else
            {
                result.TerminalToSampledTarget = -1f;
                result.TerminalToRawTarget = -1f;
            }

            result.StrictComplete = result.CalculateReturned &&
                                    result.Status == NavMeshPathStatus.PathComplete &&
                                    result.Corners.Length > 0 &&
                                    result.TerminalToSampledTarget <= StrictTerminalTolerance;
            StoreStrictPathMicroCache(cacheKey, result);
            return result;
        }

        private static void StoreStrictPathMicroCache(StrictPathMicroCacheKey key, StrictPathResult result)
        {
            if (result == null)
            {
                return;
            }

            if (StrictPathMicroCache.Count >= StrictPathMicroCacheLimit)
            {
                foreach (StrictPathMicroCacheKey staleKey in StrictPathMicroCache
                    .Where(pair => pair.Value == null || Time.time - pair.Value.SampledAt > StrictPathMicroCacheSeconds)
                    .Select(pair => pair.Key)
                    .Take(StrictPathMicroCacheLimit / 2)
                    .ToArray())
                {
                    StrictPathMicroCache.Remove(staleKey);
                }
                if (StrictPathMicroCache.Count >= StrictPathMicroCacheLimit)
                {
                    StrictPathMicroCache.Clear();
                }
            }

            StrictPathMicroCache[key] = new StrictPathMicroCacheEntry
            {
                SampledAt = Time.time,
                Result = result
            };
        }

        private static float CalculatePathLength(Vector3[] corners)
        {
            if (corners == null || corners.Length < 2)
            {
                return 0f;
            }

            float length = 0f;
            for (int index = 1; index < corners.Length; index++)
            {
                length += Vector3.Distance(corners[index - 1], corners[index]);
            }
            return length;
        }

        private static void AttachLocalPlayer(Player player)
        {
            if (ReferenceEquals(observedLocalPlayer, player))
            {
                return;
            }

            DetachLocalPlayer();
            if (!IsLivePlayer(player) || player.MovementContext == null)
            {
                return;
            }

            observedLocalPlayer = player;
            localPlayerStateHandler = OnLocalPlayerStateChanged;
            observedLocalPlayer.MovementContext.SubscribeMovementContextOnStateChanged("R1-4E3B8A15C6FF",@player?.AIData?.BotOwner,localPlayerStateHandler);
            localJumpCandidateActive = false;
            localJumpAwaitingLanding = false;
            localJumpApproachEdgeId = 0;
            localJumpApproachEpisodeId = 0;
            localJumpStartBreadcrumbSequence = 0;
            localNaturalDropCandidateActive = false;
            localNaturalDropWasGrounded = observedLocalPlayer.MovementContext.IsGrounded;
            localNaturalDropStartBreadcrumbSequence = 0;
            ResetBreadcrumbState();
        }

        private static void DetachLocalPlayer()
        {
            try
            {
                if (observedLocalPlayer?.MovementContext != null && localPlayerStateHandler != null)
                {
                    observedLocalPlayer.MovementContext.UnsubscribeMovementContextOnStateChanged("R1-AEE184B59356",null,localPlayerStateHandler);
                }
            }
            catch
            {
                // Ignore teardown races.
            }

            observedLocalPlayer = null;
            localPlayerStateHandler = null;
            localVaultActive = false;
            localVaultAwaitingLanding = false;
            localJumpCandidateActive = false;
            localJumpAwaitingLanding = false;
            localJumpApproachEdgeId = 0;
            localJumpApproachEpisodeId = 0;
            localJumpStartBreadcrumbSequence = 0;
            localNaturalDropCandidateActive = false;
            localNaturalDropWasGrounded = true;
            localNaturalDropStartBreadcrumbSequence = 0;
            pendingPlayerAnimatorCapture = null;
        }

        private static void OnLocalPlayerStateChanged(EPlayerState previous, EPlayerState next)
        {
            if (observedLocalPlayer == null)
            {
                return;
            }

            WriteEvent("playerState", null, new
            {
                profileId = observedLocalPlayer.ProfileId,
                previous = previous.ToString(),
                next = next.ToString(),
                position = Vec(observedLocalPlayer.Position),
                grounded = observedLocalPlayer.MovementContext?.IsGrounded == true
            });
            CaptureBreadcrumb(observedLocalPlayer, true);

            // V1.3.22 stream handoff: finalize the episode that just ended before opening a new
            // explicit traversal. Fast player chains can transition Vault -> Jump or Jump -> Vault
            // before the normal Update finisher gets another frame.
            if (localJumpCandidateActive && previous == EPlayerState.Jump && next != EPlayerState.Jump)
            {
                if (next == EPlayerState.JumpLanding)
                {
                    SchedulePlayerAnimatorHintCapture("Jump", "Land", next);
                }
                localJumpAwaitingLanding = true;
            }
            if (localVaultActive && !IsVaultState(next))
            {
                localVaultAwaitingLanding = true;
            }

            if (localVaultActive && localVaultAwaitingLanding && next == EPlayerState.Jump)
            {
                CompleteLocalPlayerVaultDemonstration(
                    observedLocalPlayer,
                    observedLocalPlayer.Position,
                    "chainHandoffToJump");
            }
            if (localJumpCandidateActive && localJumpAwaitingLanding &&
                (next == EPlayerState.ClimbOver || next == EPlayerState.ClimbUp))
            {
                // CompileFix46: Jump -> ClimbOver/ClimbUp is not a successful Jump traversal.
                // Fix45.1 finalized this precursor as "chainHandoffToVault", which polluted the
                // persisted map with Jump edges directly on top of real Vault/Climb corridors.
                // Cancel the pending Jump and let the explicit Vault/Climb state own the semantic.
                WriteEvent("playerJumpCandidateCancelledForVaultClimb", null, new
                {
                    start = Vec(localJumpStartPosition),
                    transitionPosition = Vec(observedLocalPlayer.Position),
                    nextState = next.ToString(),
                    duration = Mathf.Max(0f, Time.time - localJumpStartedAt),
                    approachSpeed = localJumpApproachSpeed
                });
                localJumpCandidateActive = false;
                localJumpAwaitingLanding = false;
                localJumpApproachEdgeId = 0;
                localJumpApproachEpisodeId = 0;
                localJumpStartBreadcrumbSequence = 0;
            }

            if (next == EPlayerState.ClimbOver || next == EPlayerState.ClimbUp)
            {
                FinalizeActiveWalkThroughEpisode("explicitTraversalStarted");
                CancelPendingTraversalSettledExitCaptures("supersededByExplicitTraversal");
                localVaultActive = true;
                localVaultAwaitingLanding = false;
                localVaultStartPosition = observedLocalPlayer.Position;
                localVaultKind = next == EPlayerState.ClimbUp ? "Climb" : "Vault";
                localVaultStartedAt = Time.time;
                localTraversalWalkThroughSuppressUntil = Mathf.Max(
                    localTraversalWalkThroughSuppressUntil,
                    Time.time + PlayerTraversalWalkThroughSuppressSeconds);
                // V3.47: force one breadcrumb at the actual EFT Vault/Climb state transition.
                // Completion-time breadcrumbSequence-1 was routinely several samples too late and
                // made the real run-up/off-Nav corridor look like an ordinary NavMesh connector.
                {
                    CaptureBreadcrumb(observedLocalPlayer, true);
                }
                localVaultStartBreadcrumbSequence = breadcrumbSequence;
                CapturePlayerTraversalMotion(
                    observedLocalPlayer,
                    out localVaultApproachDirection,
                    out localVaultApproachSpeed,
                    out localVaultApproachMode);
                localVaultMotionSamples.Clear();
                localVaultLastMotionSampleAt = 0f;
                localVaultLastMotionSamplePosition = localVaultStartPosition;
                localVaultLastMotionSampleState = next.ToString();
                localVaultMotionSamples.Add(new PlayerTraversalWorldSample
                {
                    Time = 0f,
                    Position = localVaultStartPosition,
                    State = next.ToString(),
                    Grounded = observedLocalPlayer.MovementContext.IsGrounded
                });
                localVaultObstacleFingerprint = TryCaptureTraversalObstacleFingerprint(
                    observedLocalPlayer, localVaultStartPosition, localVaultApproachDirection);
                localVaultNativeParameters = CaptureNativeVaultParameters(observedLocalPlayer, next);
                SchedulePlayerAnimatorHintCapture(localVaultKind, "Start", next);
                WriteEvent("playerVaultStart", null, new
                {
                    profileId = observedLocalPlayer.ProfileId,
                    kind = localVaultKind,
                    start = Vec(localVaultStartPosition),
                    startBreadcrumbSequence = localVaultStartBreadcrumbSequence,
                    forward = Vec(observedLocalPlayer.MovementContext.PlayerRealForward),
                    parameters = CreateVaultParameterPayload(observedLocalPlayer)
                });
            }
            if (localVaultActive && next == EPlayerState.VaultingLanding)
            {
                SchedulePlayerAnimatorHintCapture(localVaultKind ?? "Vault", "Land", next);
            }

            // V1.3.1 used MovementContext.IsGrounded edge changes and the 2026-08-13 test log
            // produced hundreds of false airborne starts while sprinting. The exact EFT runtime
            // exposes clean Run -> Jump -> JumpLanding transitions, so use those authoritative
            // states to learn low-wall jump shortcuts.
            if (!localVaultActive && next == EPlayerState.Jump)
            {
                FinalizeActiveWalkThroughEpisode("jumpStarted");
                CancelPendingTraversalSettledExitCaptures("supersededByJump");
                localJumpCandidateActive = true;
                localJumpAwaitingLanding = false;
                localJumpStartPosition = observedLocalPlayer.Position;
                localJumpStartedAt = Time.time;
                localTraversalWalkThroughSuppressUntil = Mathf.Max(
                    localTraversalWalkThroughSuppressUntil,
                    Time.time + PlayerTraversalWalkThroughSuppressSeconds);
                localJumpStartBreadcrumbSequence = breadcrumbSequence;
                bool breadcrumbApproachAuthority =
                    TryCaptureLearningV329JumpApproachMotionFromBreadcrumbs(
                        previous,
                        localJumpStartBreadcrumbSequence,
                        out localJumpApproachDirection,
                        out localJumpApproachSpeed,
                        out localJumpApproachMode);
                if (!breadcrumbApproachAuthority)
                {
                    CapturePlayerTraversalMotion(
                        observedLocalPlayer,
                        out localJumpApproachDirection,
                        out localJumpApproachSpeed,
                        out localJumpApproachMode);
                }
                WriteEvent("learningV329PlayerJumpApproachMotionCaptured", null, new
                {
                    source = breadcrumbApproachAuthority ? "preJumpBreadcrumbs" : "postTransitionVelocityFallback",
                    previousState = previous.ToString(),
                    approachDirection = Vec(localJumpApproachDirection),
                    approachSpeed = localJumpApproachSpeed,
                    approachMode = localJumpApproachMode
                });
                localJumpApproachEdgeId = 0;
                localJumpApproachEpisodeId = 0;
                TryCaptureJumpApproachTraversal(observedLocalPlayer);
                SchedulePlayerAnimatorHintCapture("Jump", "Start", next);
                WriteEvent("playerJumpAirborneStart", null, new
                {
                    profileId = observedLocalPlayer.ProfileId,
                    source = "EPlayerState.Jump",
                    start = Vec(localJumpStartPosition),
                    forward = Vec(observedLocalPlayer.MovementContext.PlayerRealForward)
                });
            }
        }


        private static void TryCaptureJumpApproachTraversal(Player player)
        {
            if (player?.MovementContext == null || BreadcrumbRoute.Count < 2 || !IsFinite(player.Position))
            {
                return;
            }

            Vector3 takeoff = player.Position;
            int takeoffSequence = Math.Max(1, localJumpStartBreadcrumbSequence);
            if (lastPlayerTraversalEpisode != null &&
                string.Equals(lastPlayerTraversalEpisode.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                lastPlayerTraversalEpisode.EndBreadcrumbSequence >= takeoffSequence - 2 &&
                GetPlanarDistance(lastPlayerTraversalEpisode.RawEnd, takeoff) <= 1.0f)
            {
                localJumpApproachEpisodeId = lastPlayerTraversalEpisode.EpisodeId;
                localJumpApproachEdgeId = lastPlayerTraversalEpisode.EdgeId;
                WriteEvent("playerJumpApproachReused", null, new
                {
                    edgeId = localJumpApproachEdgeId,
                    episodeId = localJumpApproachEpisodeId,
                    takeoff = Vec(takeoff),
                    takeoffSequence
                });
                return;
            }

            float oldestAllowedAt = Time.time - JumpApproachCaptureLookbackSeconds;
            List<PlayerBreadcrumbNode> recent = BreadcrumbRoute
                .Where(node => node != null &&
                               node.Sequence < takeoffSequence &&
                               node.CreatedAt >= oldestAllowedAt &&
                               !IsTraversalStateName(node.State) &&
                               GetPlanarDistance(node.Position, takeoff) <= JumpApproachCaptureMaxDistance)
                .OrderBy(node => node.Sequence)
                .ToList();
            if (recent.Count > JumpApproachCaptureMaxBreadcrumbs)
            {
                recent = recent
                    .Skip(recent.Count - JumpApproachCaptureMaxBreadcrumbs)
                    .ToList();
            }
            if (recent.Count < 2)
            {
                return;
            }

            PlayerBreadcrumbNode anchorNode = null;
            for (int index = 0; index < recent.Count; index++)
            {
                PlayerBreadcrumbNode candidate = recent[index];
                if (!candidate.NavMeshSampled)
                {
                    continue;
                }

                float distance = GetPlanarDistance(candidate.Position, takeoff);
                if (distance < JumpApproachCaptureMinDistance)
                {
                    continue;
                }

                float rise = takeoff.y - candidate.Position.y;
                StrictPathResult directPath = CalculateStrictPath(candidate.Position, takeoff);
                bool approachNeedsTraversal =
                    rise >= JumpApproachCaptureMinRise ||
                    !directPath.StrictComplete ||
                    directPath.PathLength >= Mathf.Max(distance + 2.5f, distance * 1.55f);
                if (!approachNeedsTraversal)
                {
                    continue;
                }

                if (TryFindCheapLocalWalkThroughBypass(
                        candidate.Position,
                        takeoff,
                        out _,
                        out _,
                        out _,
                        out _))
                {
                    continue;
                }

                anchorNode = candidate;
                break;
            }

            if (anchorNode == null)
            {
                WriteEvent("playerJumpApproachNotRequired", null, new
                {
                    takeoff = Vec(takeoff),
                    takeoffSequence,
                    recentBreadcrumbs = recent.Count
                });
                return;
            }

            List<Vector3> corridor = recent
                .Where(node => node.Sequence >= anchorNode.Sequence)
                .Select(node => node.Position)
                .Where(IsFinite)
                .ToList();
            if (corridor.Count == 0 ||
                GetPlanarDistance(corridor[corridor.Count - 1], takeoff) > 0.05f)
            {
                corridor.Add(takeoff);
            }

            Vector3 direction = GetFlatDirection(takeoff - anchorNode.Position);
            float approachDistance = GetPlanarDistance(anchorNode.Position, takeoff);
            int edgeId = RememberLearnedTraversalEdge(
                anchorNode.Position,
                takeoff,
                "WalkThrough",
                true,
                new PlayerTraversalMotionProfile
                {
                    ApproachDirection = direction.sqrMagnitude > 0.5f ? direction : localJumpApproachDirection,
                    ApproachSpeed = Mathf.Max(0.75f, localJumpApproachSpeed),
                    ApproachMode = string.IsNullOrWhiteSpace(localJumpApproachMode) ? "Run" : localJumpApproachMode,
                    TraversalDuration = Mathf.Max(0.25f, Time.time - anchorNode.CreatedAt)
                });
            if (edgeId <= 0)
            {
                return;
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == edgeId);
            if (edge != null)
            {
                edge.WalkThroughCorridorSamples = corridor;
                edge.HasSettledStart = true;
                edge.SettledStart = anchorNode.NavMeshSampled ? anchorNode.NavMeshPosition : anchorNode.Position;
                if (edge.HasSettledEnd && !IsCredibleWalkThroughTerminalConnector(
                        edge.RawStart, edge.RawEnd, edge.SettledEnd, edge.WalkThroughCorridorSamples))
                {
                    edge.HasSettledEnd = false;
                    edge.SettledEnd = default(Vector3);
                    edge.SettledBreadcrumbSequence = 0;
                }
                SavePersistentTraversalLinks();
            }

            TraversalEpisodeMetadata episode = RegisterTraversalEpisodeForEdge(
                edgeId,
                "WalkThrough",
                anchorNode.Position,
                takeoff,
                anchorNode.Sequence,
                takeoffSequence,
                true);
            localJumpApproachEdgeId = edgeId;
            localJumpApproachEpisodeId = episode?.EpisodeId ?? 0;

            WriteEvent("playerJumpApproachLearned", null, new
            {
                edgeId,
                episodeId = localJumpApproachEpisodeId,
                startSequence = anchorNode.Sequence,
                endSequence = takeoffSequence,
                start = Vec(anchorNode.Position),
                takeoff = Vec(takeoff),
                approachDistance,
                rise = takeoff.y - anchorNode.Position.y,
                corridorSampleCount = corridor.Count,
                subtype = "RampApproach"
            });
        }

        private static void SchedulePlayerAnimatorHintCapture(string kind, string phase, EPlayerState expectedState)
        {
            if (observedLocalPlayer == null)
            {
                return;
            }

            int baselineHash = 0;
            Animator baselineAnimator = observedLocalPlayer
                .GetComponentsInChildren<Animator>(true)
                .FirstOrDefault(animator => animator != null &&
                    string.Equals(animator.name, "Player", StringComparison.OrdinalIgnoreCase));
            if (baselineAnimator != null && baselineAnimator.layerCount > 0)
            {
                baselineHash = baselineAnimator.GetCurrentAnimatorStateInfo(0).fullPathHash;
            }

            pendingPlayerAnimatorCapture = new PendingPlayerAnimatorCapture
            {
                Kind = string.IsNullOrWhiteSpace(kind) ? "Vault" : kind,
                Phase = phase ?? "Start",
                ExpectedState = expectedState,
                NotBefore = Time.time + PlayerAnimatorHintCaptureDelaySeconds,
                ExpiresAt = Time.time + PlayerAnimatorHintCaptureTimeoutSeconds,
                BaselineFullPathHash = baselineHash
            };
        }

        private static void TryCapturePendingPlayerAnimatorHint(Player player)
        {
            PendingPlayerAnimatorCapture pending = pendingPlayerAnimatorCapture;
            if (pending == null || player == null)
            {
                return;
            }

            if (Time.time > pending.ExpiresAt)
            {
                WriteEvent("playerTraversalAnimatorHintMissed", null, new
                {
                    kind = pending.Kind,
                    phase = pending.Phase,
                    expectedState = pending.ExpectedState.ToString(),
                    reason = "captureTimeout"
                });
                pendingPlayerAnimatorCapture = null;
                return;
            }

            if (Time.time < pending.NotBefore || player.CurrentStateName != pending.ExpectedState)
            {
                return;
            }

            Animator[] animators = player.GetComponentsInChildren<Animator>(true);
            if (animators == null || animators.Length == 0)
            {
                return;
            }

            IEnumerable<Animator> ordered = animators
                .Where(animator => animator != null && animator.runtimeAnimatorController != null)
                .OrderBy(animator => string.Equals(animator.name, "Player", StringComparison.OrdinalIgnoreCase) ? 0 : 1);
            foreach (Animator animator in ordered)
            {
                for (int layer = 0; layer < animator.layerCount; layer++)
                {
                    AnimatorStateInfo stateInfo = animator.IsInTransition(layer)
                        ? animator.GetNextAnimatorStateInfo(layer)
                        : animator.GetCurrentAnimatorStateInfo(layer);
                    int fullPathHash = stateInfo.fullPathHash;
                    if (fullPathHash == 0)
                    {
                        continue;
                    }

                    if (layer == 0 &&
                        fullPathHash == pending.BaselineFullPathHash &&
                        Time.time < pending.NotBefore + 0.10f)
                    {
                        // The preferred Player animator has not advanced yet. Wait for the next
                        // main-thread tick instead of accidentally recording an unrelated upper layer.
                        if (string.Equals(animator.name, "Player", StringComparison.OrdinalIgnoreCase))
                        {
                            return;
                        }
                        continue;
                    }

                    PlayerAnimatorHint hint = new PlayerAnimatorHint
                    {
                        Kind = pending.Kind,
                        Phase = pending.Phase,
                        AnimatorName = animator.name,
                        Layer = layer,
                        FullPathHash = fullPathHash,
                        ShortNameHash = stateInfo.shortNameHash,
                        CapturedAt = Time.time
                    };
                    PlayerTraversalAnimatorHints[MakeAnimatorHintKey(pending.Kind, pending.Phase)] = hint;
                    WriteEvent("playerTraversalAnimatorHintCaptured", null, new
                    {
                        kind = hint.Kind,
                        phase = hint.Phase,
                        expectedState = pending.ExpectedState.ToString(),
                        animator = hint.AnimatorName,
                        layer = hint.Layer,
                        fullPathHash = hint.FullPathHash,
                        shortNameHash = hint.ShortNameHash
                    });
                    pendingPlayerAnimatorCapture = null;
                    return;
                }
            }
        }

        private static string MakeAnimatorHintKey(string kind, string phase)
        {
            return (kind ?? "Vault") + ":" + (phase ?? "Start");
        }

        private static bool TryCaptureLearningV329JumpApproachMotionFromBreadcrumbs(
            EPlayerState previousState,
            int takeoffSequence,
            out Vector3 approachDirection,
            out float approachSpeed,
            out string approachMode)
        {
            approachDirection = Vector3.zero;
            approachSpeed = 0f;
            approachMode = "Walk";
            if ((BreadcrumbRoute.Count < 2))
            {
                return false;
            }

            List<PlayerBreadcrumbNode> recent = BreadcrumbRoute
                .Where(node => node != null &&
                               node.Sequence < takeoffSequence &&
                               node.Grounded &&
                               !IsTraversalStateName(node.State) &&
                               Time.time - node.CreatedAt <= 0.75f)
                .OrderBy(node => node.Sequence)
                .ToList();
            if (recent.Count < 2)
            {
                return false;
            }
            if (recent.Count > 4)
            {
                recent = recent.Skip(recent.Count - 4).ToList();
            }

            PlayerBreadcrumbNode first = recent[0];
            PlayerBreadcrumbNode last = recent[recent.Count - 1];
            float elapsed = last.CreatedAt - first.CreatedAt;
            Vector3 delta = last.Position - first.Position;
            delta.y = 0f;
            if (elapsed <= 0.02f || delta.sqrMagnitude <= 0.0025f)
            {
                return false;
            }

            approachSpeed = delta.magnitude / elapsed;
            approachDirection = GetFlatDirection(delta);
            if (approachDirection.sqrMagnitude < 0.5f)
            {
                approachDirection = GetFlatDirection(last.Direction);
            }
            if (previousState == EPlayerState.Sprint)
            {
                approachMode = "Sprint";
            }
            else if (previousState == EPlayerState.Run)
            {
                approachMode = "Run";
            }
            else
            {
                approachMode = approachSpeed >= 4.25f
                    ? "Sprint"
                    : (approachSpeed >= 1.55f ? "Run" : "Walk");
            }
            return approachDirection.sqrMagnitude > 0.5f;
        }

        private static void CapturePlayerTraversalMotion(
            Player player,
            out Vector3 approachDirection,
            out float approachSpeed,
            out string approachMode)
        {
            approachDirection = Vector3.zero;
            approachSpeed = 0f;
            approachMode = "Walk";
            if (player == null)
            {
                return;
            }

            Vector3 velocity = player.Velocity;
            velocity.y = 0f;
            approachSpeed = velocity.magnitude;
            Vector3 fallbackForward = player.MovementContext != null
                ? player.MovementContext.PlayerRealForward
                : Vector3.forward;
            approachDirection = approachSpeed > 0.15f
                ? GetFlatDirection(velocity)
                : GetFlatDirection(fallbackForward);
            approachMode = approachSpeed >= 4.25f
                ? "Sprint"
                : (approachSpeed >= 1.55f ? "Run" : "Walk");
        }

        private static void CaptureActivePlayerVaultMotion(Player player)
        {
            if (!localVaultActive || player?.MovementContext == null || !IsFinite(player.Position))
            {
                return;
            }

            float elapsed = Mathf.Max(0f, Time.time - localVaultStartedAt);
            string state = player.CurrentStateName.ToString();
            bool shouldSample = localVaultMotionSamples.Count == 0 ||
                                elapsed - localVaultLastMotionSampleAt >= 0.045f ||
                                Vector3.Distance(player.Position, localVaultLastMotionSamplePosition) >= 0.08f ||
                                !string.Equals(state, localVaultLastMotionSampleState, StringComparison.Ordinal);
            if (!shouldSample)
            {
                return;
            }

            localVaultMotionSamples.Add(new PlayerTraversalWorldSample
            {
                Time = elapsed,
                Position = player.Position,
                State = state,
                Grounded = player.MovementContext.IsGrounded
            });
            localVaultLastMotionSampleAt = elapsed;
            localVaultLastMotionSamplePosition = player.Position;
            localVaultLastMotionSampleState = state;
            if (localVaultMotionSamples.Count > 48)
            {
                // Keep endpoints and reduce interior density deterministically.
                List<PlayerTraversalWorldSample> compacted = new List<PlayerTraversalWorldSample>
                {
                    localVaultMotionSamples[0]
                };
                for (int i = 2; i < localVaultMotionSamples.Count - 1; i += 2)
                {
                    compacted.Add(localVaultMotionSamples[i]);
                }
                compacted.Add(localVaultMotionSamples[localVaultMotionSamples.Count - 1]);
                localVaultMotionSamples.Clear();
                localVaultMotionSamples.AddRange(compacted);
            }
        }

        private static PlayerTraversalMotionProfile BuildLocalVaultMotionProfile(Vector3 rawEnd)
        {
            float duration = Mathf.Max(0.10f, Time.time - localVaultStartedAt);
            Vector3 forward = GetFlatDirection(rawEnd - localVaultStartPosition);
            if (forward.sqrMagnitude < 0.5f)
            {
                forward = localVaultApproachDirection.sqrMagnitude > 0.5f
                    ? localVaultApproachDirection
                    : Vector3.forward;
            }
            Vector3 right = Vector3.Cross(Vector3.up, forward).normalized;
            List<PlayerTraversalWorldSample> worldSamples = localVaultMotionSamples
                .Where(sample => sample != null && IsFinite(sample.Position))
                .OrderBy(sample => sample.Time)
                .ToList();
            if (worldSamples.Count == 0 || Vector3.Distance(worldSamples[worldSamples.Count - 1].Position, rawEnd) > 0.03f)
            {
                worldSamples.Add(new PlayerTraversalWorldSample
                {
                    Time = duration,
                    Position = rawEnd,
                    State = observedLocalPlayer?.CurrentStateName.ToString() ?? localVaultKind,
                    Grounded = observedLocalPlayer?.MovementContext?.IsGrounded == true
                });
            }

            List<TraversalMotionSample> samples = new List<TraversalMotionSample>();
            foreach (PlayerTraversalWorldSample sample in worldSamples)
            {
                Vector3 delta = sample.Position - localVaultStartPosition;
                samples.Add(new TraversalMotionSample
                {
                    Time = Mathf.Clamp(sample.Time, 0f, duration),
                    LocalOffset = new Vector3(
                        Vector3.Dot(delta, right),
                        delta.y,
                        Vector3.Dot(delta, forward)),
                    State = sample.State,
                    Grounded = sample.Grounded
                });
            }

            WriteEvent("playerTraversalMotionProfileCaptured", null, new
            {
                kind = localVaultKind,
                sampleCount = samples.Count,
                duration,
                forward = Vec(forward),
                finalLocalOffset = samples.Count > 0 ? Vec(samples[samples.Count - 1].LocalOffset) : null,
                obstacle = localVaultObstacleFingerprint == null ? null : new
                {
                    name = localVaultObstacleFingerprint.Name,
                    layer = localVaultObstacleFingerprint.Layer,
                    center = Vec(localVaultObstacleFingerprint.BoundsCenter),
                    size = Vec(localVaultObstacleFingerprint.BoundsSize)
                }
            });

            return new PlayerTraversalMotionProfile
            {
                ApproachDirection = localVaultApproachDirection,
                ApproachSpeed = localVaultApproachSpeed,
                ApproachMode = localVaultApproachMode,
                TraversalDuration = duration,
                MotionSamples = samples,
                ObstacleFingerprint = localVaultObstacleFingerprint,
                NativeVaultParameters = CloneNativeVaultParameters(localVaultNativeParameters)
            };
        }

        private static TraversalObstacleFingerprint TryCaptureTraversalObstacleFingerprint(
            Player player, Vector3 start, Vector3 direction)
        {
            if (player == null)
            {
                return null;
            }
            Vector3 forward = GetFlatDirection(direction);
            if (forward.sqrMagnitude < 0.5f && player.MovementContext != null)
            {
                forward = GetFlatDirection(player.MovementContext.PlayerRealForward);
            }
            if (forward.sqrMagnitude < 0.5f)
            {
                return null;
            }

            Collider selected = null;
            RaycastHit hit;
            Vector3 lowOrigin = start + Vector3.up * 0.45f - forward * 0.10f;
            if (TryGetFirstNonSelfRaycastHit(player, lowOrigin, forward, AssistedCollisionProbeDistance, out hit))
            {
                selected = hit.collider;
            }
            if (selected == null)
            {
                Vector3 highOrigin = start + Vector3.up * 0.85f - forward * 0.10f;
                if (TryGetFirstNonSelfRaycastHit(player, highOrigin, forward, AssistedCollisionProbeDistance, out hit))
                {
                    selected = hit.collider;
                }
            }
            if (selected == null)
            {
                Collider[] nearby = Physics.OverlapSphere(
                    start + forward * 0.35f + Vector3.up * 0.55f,
                    0.75f,
                    Physics.AllLayers,
                    QueryTriggerInteraction.Ignore);
                if (nearby != null)
                {
                    selected = nearby
                        .Where(collider => IsSafeTraversalObstacleCollider(player, collider))
                        .OrderBy(collider => Vector3.Distance(collider.bounds.ClosestPoint(start), start))
                        .FirstOrDefault();
                }
            }
            if (!IsSafeTraversalObstacleCollider(player, selected))
            {
                return null;
            }

            return new TraversalObstacleFingerprint
            {
                Name = selected.name ?? string.Empty,
                Layer = selected.gameObject.layer,
                BoundsCenter = selected.bounds.center,
                BoundsSize = selected.bounds.size,
                RuntimeCollider = selected
            };
        }

        private static bool IsTerrainTraversalCollider(Collider collider)
        {
            // SPT 4.0.13's client project does not reference UnityEngine.TerrainPhysicsModule.
            // Avoid a hard TerrainCollider type reference so this safety check remains compatible
            // without adding another Unity module dependency to the mod build.
            Type type = collider.GetType();
            return string.Equals(type.FullName, "UnityEngine.TerrainCollider", StringComparison.Ordinal);
        }

        private static bool IsSafeTraversalObstacleCollider(Player player, Collider collider)
        {
            if (collider == null || !collider.enabled || collider.isTrigger ||
                IsTerrainTraversalCollider(collider) || IsIgnoredTraversalCollider(player, collider))
            {
                return false;
            }
            Vector3 size = collider.bounds.size;
            if (!IsFinite(size) || Mathf.Max(size.x, Mathf.Max(size.y, size.z)) > AssistedObstacleFingerprintMaxExtent)
            {
                return false;
            }
            return true;
        }

        private static void TryFinishLocalPlayerVault(Player player)
        {
            if (!localVaultActive || !localVaultAwaitingLanding || player?.MovementContext == null ||
                IsTraversalStateName(player.CurrentStateName.ToString()))
            {
                return;
            }

            CompleteLocalPlayerVaultDemonstration(player, player.Position, "settledUpdate");
        }

        private static void CompleteLocalPlayerVaultDemonstration(Player player, Vector3 end, string source)
        {
            if (!localVaultActive || player?.MovementContext == null || !IsFinite(end))
            {
                return;
            }

            WriteEvent("playerVaultEnd", null, new
            {
                profileId = player.ProfileId,
                kind = localVaultKind,
                start = Vec(localVaultStartPosition),
                end = Vec(end),
                source,
                displacement = Vector3.Distance(localVaultStartPosition, end),
                endNavMesh = SamplePayload(end, NavMeshSampleRadius)
            });
            int learnedVaultEdgeId = RememberLearnedTraversalEdge(
                localVaultStartPosition,
                end,
                localVaultKind,
                false,
                BuildLocalVaultMotionProfile(end));

            // A zero-gap Vault -> Jump chain has no ordinary Run breadcrumb between episodes. The
            // jump start itself is the semantic continuation point, so preserve it as the Vault's
            // chain exit before the Jump episode cancels pending settled-exit capture.
            if (string.Equals(source, "chainHandoffToJump", StringComparison.Ordinal) && learnedVaultEdgeId > 0)
            {
                LearnedTraversalEdge handoffEdge = LearnedTraversalEdges.FirstOrDefault(edge => edge != null && edge.Id == learnedVaultEdgeId);
                if (handoffEdge != null)
                {
                    handoffEdge.HasSettledEnd = true;
                    handoffEdge.SettledEnd = TrySampleTraversalSettledAnchor(end, TraversalSettledCaptureNavRadius, out Vector3 handoffNav)
                        ? handoffNav
                        : end;
                    handoffEdge.SettledBreadcrumbSequence = breadcrumbSequence;
                    PendingTraversalSettledExitCaptures.Remove(learnedVaultEdgeId);
                    SavePersistentTraversalLinks();
                    WriteEvent("playerTraversalChainExitCaptured", null, new
                    {
                        edgeId = learnedVaultEdgeId,
                        kind = localVaultKind,
                        source,
                        settledExit = Vec(handoffEdge.SettledEnd)
                    });
                }
            }
            int vaultClimbStartSequence = (localVaultStartBreadcrumbSequence > 0)
                    ? localVaultStartBreadcrumbSequence
                    : Mathf.Max(0, breadcrumbSequence - 1);
            RegisterTraversalEpisodeForEdge(
                learnedVaultEdgeId,
                localVaultKind,
                localVaultStartPosition,
                end,
                vaultClimbStartSequence,
                breadcrumbSequence);
            localVaultActive = false;
            localVaultAwaitingLanding = false;
            localVaultStartBreadcrumbSequence = 0;
            localVaultMotionSamples.Clear();
            localVaultObstacleFingerprint = null;
            localVaultNativeParameters = null;
            CaptureBreadcrumb(player, true);
        }

        private static void UpdateNaturalDropDownCandidate(Player player)
        {
            if (player?.MovementContext == null || !IsFinite(player.Position))
            {
                return;
            }

            bool grounded = player.MovementContext.IsGrounded;
            string state = player.CurrentStateName.ToString();
            // Natural ledge drops may enter EFT's Fall state without any player-authored Jump.
            // Treat Jump/Vault/Climb as explicit traversal, but keep Fall eligible for DropDown learning.
            bool explicitTraversal = localVaultActive || localJumpCandidateActive ||
                                     state.IndexOf("Jump", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                     state.IndexOf("Vault", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                     state.IndexOf("Climb", StringComparison.OrdinalIgnoreCase) >= 0;

            if (explicitTraversal)
            {
                if (localNaturalDropCandidateActive)
                {
                    WriteEvent("playerNaturalDropDownCancelled", null, new
                    {
                        profileId = player.ProfileId,
                        reason = "explicitTraversalState",
                        state,
                        start = Vec(localNaturalDropStartPosition),
                        current = Vec(player.Position)
                    });
                }
                if (localNaturalDropWalkThroughSnapshot != null)
                {
                    FinalizeCapabilityWalkThroughSnapshot(localNaturalDropWalkThroughSnapshot,"naturalDropCancelledByExplicitTraversal");
                }
                localNaturalDropWalkThroughSnapshot = null;
                localNaturalDropCandidateActive = false;
                localNaturalDropStartBreadcrumbSequence = 0;
                localNaturalDropWasGrounded = grounded;
                return;
            }

            if (!localNaturalDropCandidateActive && localNaturalDropWasGrounded && !grounded)
            {
                // CompileFix12: defer the WalkThrough boundary until this airborne sample proves
                // to be a real ledge drop. Customs rough ground produced ~2-3 cm airborne flickers
                // that used to refresh a long corridor into a 1.08 m micro-edge before DropDown
                // geometry was subsequently rejected.
                localNaturalDropWalkThroughSnapshot = CloneWalkThroughEpisode(activeWalkThroughEpisode);
                localNaturalDropCandidateActive = true;
                localNaturalDropStartPosition = haveLastBreadcrumb && IsFinite(lastBreadcrumbPosition)
                    ? lastBreadcrumbPosition
                    : player.Position;
                localNaturalDropStartedAt = Time.time;
                localNaturalDropStartBreadcrumbSequence = breadcrumbSequence;
                CapturePlayerTraversalMotion(
                    player,
                    out localNaturalDropApproachDirection,
                    out localNaturalDropApproachSpeed,
                    out localNaturalDropApproachMode);
                CaptureBreadcrumb(player, true);
                // CompileFix16: do not emit an event for every 1-frame rough-ground flicker.
                // The candidate remains live and will be logged if it grows into a meaningful drop.
            }

            if (localNaturalDropCandidateActive)
            {
                float elapsed = Mathf.Max(0f, Time.time - localNaturalDropStartedAt);
                if (elapsed > PlayerNaturalDropDownMaxDuration)
                {
                    WriteEvent("playerNaturalDropDownRejected", null, new
                    {
                        profileId = player.ProfileId,
                        reason = "airborneTimeout",
                        elapsed,
                        start = Vec(localNaturalDropStartPosition),
                        current = Vec(player.Position)
                    });
                    if (localNaturalDropWalkThroughSnapshot != null)
                    {
                        FinalizeCapabilityWalkThroughSnapshot(localNaturalDropWalkThroughSnapshot,"naturalDropAirborneTimeoutBoundary");
                    }
                    localNaturalDropWalkThroughSnapshot = null;
                    localNaturalDropCandidateActive = false;
                    localNaturalDropStartBreadcrumbSequence = 0;
                }
                else if (grounded)
                {
                    Vector3 end = player.Position;
                    Vector3 delta = end - localNaturalDropStartPosition;
                    float verticalDrop = localNaturalDropStartPosition.y - end.y;
                    float horizontalDistance = new Vector2(delta.x, delta.z).magnitude;
                    bool plausible = verticalDrop >= PlayerNaturalDropDownMinVerticalDrop &&
                                     verticalDrop <= PlayerNaturalDropDownMaxVerticalDrop &&
                                     horizontalDistance >= 0.10f &&
                                     horizontalDistance <= PlayerNaturalDropDownMaxHorizontalDistance;

                    int learnedEdgeId = 0;
                    StrictPathResult path = CalculateStrictPath(localNaturalDropStartPosition, end);
                    List<PlayerBreadcrumbNode> learningV370DropWindow = BreadcrumbRoute
                        .Where(node => node != null &&
                                       node.Sequence >= localNaturalDropStartBreadcrumbSequence &&
                                       node.Sequence <= breadcrumbSequence && IsFinite(node.Position))
                        .OrderBy(node => node.Sequence)
                        .ToList();
                    // CF43: a demonstrated, continuously airborne ledge drop may exceed the
                    // generic 3.25m horizontal envelope solely because sprint momentum carries
                    // the player farther before the grounded landing sample. Do not widen the
                    // generic gate: require independent kinematic, breadcrumb, top-entry,
                    // supported landing and disconnected-topology witnesses instead.
                    float cf43KinematicMaximum = 0f;
                    int cf43AirborneSamples = 0;
                    bool cf43ExtendedPhysicalDrop = !plausible &&
                        TryVerifyCf43ContinuousNaturalDrop(
                            localNaturalDropStartPosition, end, elapsed,
                            verticalDrop, horizontalDistance, localNaturalDropApproachDirection,
                            localNaturalDropApproachSpeed, path, learningV370DropWindow,
                            out cf43KinematicMaximum, out cf43AirborneSamples);
                    if (cf43ExtendedPhysicalDrop)
                    {
                        plausible = true;
                        WriteEvent("cf43ContinuousPhysicalDropAdmitted", null, new
                        {
                            profileId = player.ProfileId,
                            start = Vec(localNaturalDropStartPosition),
                            end = Vec(end),
                            elapsed,
                            verticalDrop,
                            horizontalDistance,
                            genericHorizontalLimit = PlayerNaturalDropDownMaxHorizontalDistance,
                            kinematicMaximum = cf43KinematicMaximum,
                            airborneSamples = cf43AirborneSamples,
                            breadcrumbSamples = learningV370DropWindow.Count,
                            strictComplete = path.StrictComplete,
                            traversalSuccessRecorded = false,
                            nativeSuccessGranted = false,
                            action = "admitTypedDropFromPhysicalWitnessNotGenericHorizontalThreshold"
                        });
                    }
                    bool learningV370OrdinaryNavMeshDrop =
                        (plausible) &&
                        IsLearningV369OrdinaryNavMeshRouteWindow(learningV370DropWindow, path);
                    bool learningV417NativeProvenDropDownRevalidated = false;
                    LearnedTraversalEdge learningV417ProvenDropDownEdge = null;
                    float learningV417PortalMatchScore = float.MaxValue;
                    if (!plausible &&
                        verticalDrop >= PlayerNaturalDropDownDiagnosticMinVerticalDrop &&
                        verticalDrop < PlayerNaturalDropDownMinVerticalDrop &&
                        horizontalDistance >= 0.10f &&
                        horizontalDistance <= PlayerNaturalDropDownMaxHorizontalDistance &&
                        TryGetLearningV417NativeProvenDropDownPortal(
                            localNaturalDropStartPosition, end, path,
                            out learningV417ProvenDropDownEdge, out learningV417PortalMatchScore))
                    {
                        learningV417NativeProvenDropDownRevalidated = true;
                    }

                    if (learningV370OrdinaryNavMeshDrop)
                    {
                        if (localNaturalDropWalkThroughSnapshot != null)
                        {
                            activeWalkThroughEpisode = MergeRejectedNaturalDropIntoWalkThrough(
                                localNaturalDropWalkThroughSnapshot, activeWalkThroughEpisode, end, breadcrumbSequence);
                        }
                        WriteEvent("learningV370OrdinaryNavMeshDropDownSemanticSuppressed", null, new
                        {
                            profileId = player.ProfileId,
                            start = Vec(localNaturalDropStartPosition),
                            end = Vec(end),
                            elapsed,
                            verticalDrop,
                            horizontalDistance,
                            sampleCount = learningV370DropWindow.Count,
                            strictPath = path.ToPayload(),
                            persistentLearningChanged = false,
                            action = "fullySampledContinuousNavMeshOwnsOrdinarySlopeNoActuatorDebt"
                        });
                        localNaturalDropWalkThroughSnapshot = null;
                    }
                    if (learningV417NativeProvenDropDownRevalidated &&
                        !learningV370OrdinaryNavMeshDrop && learningV417ProvenDropDownEdge != null)
                    {
                        if (localNaturalDropWalkThroughSnapshot != null)
                        {
                            FinalizeCapabilityWalkThroughSnapshot(localNaturalDropWalkThroughSnapshot,"learningV417NativeProvenDropDownRevalidated");
                        }
                        localTraversalWalkThroughSuppressUntil = Mathf.Max(
                            localTraversalWalkThroughSuppressUntil,
                            Time.time + PlayerNaturalDropDownWalkThroughSuppressSeconds);
                        learnedEdgeId = learningV417ProvenDropDownEdge.Id;
                        TraversalEpisodeMetadata learningV417Episode = RegisterTraversalEpisodeForEdge(
                            learningV417ProvenDropDownEdge.Id,
                            "DropDown",
                            localNaturalDropStartPosition,
                            end,
                            localNaturalDropStartBreadcrumbSequence > 0
                                ? localNaturalDropStartBreadcrumbSequence
                                : Mathf.Max(0, breadcrumbSequence - 1),
                            breadcrumbSequence);
                        WriteEvent("learningV417NativeProvenDropDownPortalRevalidated", null, new
                        {
                            profileId = player.ProfileId,
                            edgeId = learningV417ProvenDropDownEdge.Id,
                            experienceKey = learningV417ProvenDropDownEdge.ExperienceKey ?? string.Empty,
                            episodeId = learningV417Episode?.EpisodeId ?? 0,
                            start = Vec(localNaturalDropStartPosition),
                            end = Vec(end),
                            elapsed,
                            measuredVerticalDrop = verticalDrop,
                            minVerticalDrop = PlayerNaturalDropDownMinVerticalDrop,
                            horizontalDistance,
                            portalMatchScore = learningV417PortalMatchScore,
                            nativeSuccessCount = learningV417ProvenDropDownEdge.NativeSuccessCount,
                            strictPath = path.ToPayload(),
                            persistentLearningChanged = false,
                            traversalSuccessRecorded = false,
                            action = "reuseSameDirectionNativeProvenPortalForRuntimeEpisodeWithoutLoweringGlobalDropThreshold"
                        });
                    }

                    if (plausible && !learningV370OrdinaryNavMeshDrop)
                    {
                        if (localNaturalDropWalkThroughSnapshot != null)
                        {
                            FinalizeCapabilityWalkThroughSnapshot(localNaturalDropWalkThroughSnapshot,"naturalDropConfirmed");
                        }
                        localTraversalWalkThroughSuppressUntil = Mathf.Max(
                            localTraversalWalkThroughSuppressUntil,
                            Time.time + PlayerNaturalDropDownWalkThroughSuppressSeconds);
                        learnedEdgeId = RememberLearnedTraversalEdge(
                            localNaturalDropStartPosition,
                            end,
                            "DropDown",
                            true,
                            new PlayerTraversalMotionProfile
                            {
                                ApproachDirection = localNaturalDropApproachDirection,
                                ApproachSpeed = localNaturalDropApproachSpeed,
                                ApproachMode = localNaturalDropApproachMode,
                                TraversalDuration = elapsed
                            });

                        if (learnedEdgeId > 0)
                        {
                            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(item => item != null && item.Id == learnedEdgeId);
                            if (edge != null)
                            {
                                bool credibleTop = TrySampleCredibleDropDownTopEntry(
                                    localNaturalDropStartPosition,
                                    localNaturalDropApproachDirection,
                                    out Vector3 settledStart);
                                if (credibleTop)
                                {
                                    edge.HasSettledStart = true;
                                    edge.SettledStart = settledStart;
                                    edge.A = settledStart;
                                }
                                if (TrySampleTraversalSettledAnchor(end, TraversalSettledCaptureNavRadius, out Vector3 settledEnd))
                                {
                                    edge.HasSettledEnd = true;
                                    edge.SettledEnd = settledEnd;
                                    edge.SettledBreadcrumbSequence = breadcrumbSequence;
                                    edge.Disabled = !credibleTop;
                                }
                                else
                                {
                                    edge.Disabled = true;
                                }
                                PendingTraversalSettledExitCaptures.Remove(learnedEdgeId);
                                SavePersistentTraversalLinks();
                            }

                            RegisterTraversalEpisodeForEdge(
                                learnedEdgeId,
                                "DropDown",
                                localNaturalDropStartPosition,
                                end,
                                localNaturalDropStartBreadcrumbSequence > 0
                                    ? localNaturalDropStartBreadcrumbSequence
                                    : Mathf.Max(0, breadcrumbSequence - 1),
                                breadcrumbSequence);
                        }
                    }

                    bool meaningfulNaturalDropDiagnostic = !learningV370OrdinaryNavMeshDrop &&
                        !learningV417NativeProvenDropDownRevalidated && (plausible ||
                        elapsed >= PlayerNaturalDropDownDiagnosticMinAirborneSeconds ||
                        verticalDrop >= PlayerNaturalDropDownDiagnosticMinVerticalDrop);
                    if (meaningfulNaturalDropDiagnostic)
                    {
                        WriteEvent(plausible ? "playerNaturalDropDownLearned" : "playerNaturalDropDownRejected", null, new
                        {
                            profileId = player.ProfileId,
                            reason = plausible ? "groundedLanding" : "geometryRejected",
                            start = Vec(localNaturalDropStartPosition),
                            end = Vec(end),
                            elapsed,
                            verticalDrop,
                            horizontalDistance,
                            strictPath = path.ToPayload(),
                            learned = learnedEdgeId > 0,
                            edgeId = learnedEdgeId
                        });
                    }

                    if (!plausible && !learningV417NativeProvenDropDownRevalidated &&
                        localNaturalDropWalkThroughSnapshot != null)
                    {
                        bool learningV336MaterialVerticalBoundary =
                            (verticalDrop >= PlayerNaturalDropDownMinVerticalDrop) &&
                            verticalDrop <= PlayerNaturalDropDownMaxVerticalDrop;
                        if (learningV336MaterialVerticalBoundary)
                        {
                            // A material vertical transition is not micro-airborne WT noise. Keep the
                            // already-recorded WT segment truthful even when the separate DropDown
                            // candidate misses its existing horizontal envelope; do not widen that
                            // envelope and do not invent a DropDown edge.
                            FinalizeCapabilityWalkThroughSnapshot(localNaturalDropWalkThroughSnapshot,"learningV336RejectedMajorDropBoundary");
                            localTraversalWalkThroughSuppressUntil = Mathf.Max(
                                localTraversalWalkThroughSuppressUntil,
                                Time.time + PlayerNaturalDropDownWalkThroughSuppressSeconds);
                            WriteEvent("learningV336RejectedMajorDropKeptOutOfWalkThrough", null, new
                            {
                                profileId = player.ProfileId,
                                start = Vec(localNaturalDropStartPosition),
                                end = Vec(end),
                                elapsed,
                                verticalDrop,
                                horizontalDistance,
                                maxHorizontalDistance = PlayerNaturalDropDownMaxHorizontalDistance,
                                action = "finalizeWalkThroughAtDropBoundaryLeaveRejectedDropUnlearned"
                            });
                        }
                        else
                        {
                            activeWalkThroughEpisode = MergeRejectedNaturalDropIntoWalkThrough(
                                localNaturalDropWalkThroughSnapshot,
                                activeWalkThroughEpisode,
                                end,
                                breadcrumbSequence);
                            WriteEvent("playerWalkThroughMicroAirborneMerged", null, new
                            {
                                profileId = player.ProfileId,
                                start = Vec(localNaturalDropStartPosition),
                                end = Vec(end),
                                elapsed,
                                verticalDrop,
                                horizontalDistance,
                                episodeId = activeWalkThroughEpisode?.EpisodeId ?? 0,
                                corridorPointCount = activeWalkThroughEpisode?.CorridorSamples?.Count ?? 0
                            });
                        }
                    }

                    localNaturalDropWalkThroughSnapshot = null;
                    localNaturalDropCandidateActive = false;
                    localNaturalDropStartBreadcrumbSequence = 0;
                    CaptureBreadcrumb(player, true);
                }
            }

            localNaturalDropWasGrounded = grounded;
        }

        // CF43: this is a positive, single-demonstration physical witness, never a
        // generalized horizontal-distance increase or a cached negative route result.
        // The standard DropDown envelope remains authoritative for ordinary samples.
        private static bool TryVerifyCf43ContinuousNaturalDrop(
            Vector3 start, Vector3 end, float elapsed, float verticalDrop,
            float horizontalDistance, Vector3 approachDirection, float approachSpeed,
            StrictPathResult path, List<PlayerBreadcrumbNode> samples,
            out float kinematicMaximum, out int airborneSamples)
        {
            kinematicMaximum = 0f;
            airborneSamples = 0;
            if (!IsFinite(start) || !IsFinite(end) || path == null || path.StrictComplete ||
                samples == null || samples.Count < 4 ||
                verticalDrop < PlayerNaturalDropDownMinVerticalDrop ||
                verticalDrop > PlayerNaturalDropDownMaxVerticalDrop ||
                horizontalDistance <= PlayerNaturalDropDownMaxHorizontalDistance ||
                elapsed < PlayerNaturalDropDownDiagnosticMinAirborneSeconds ||
                elapsed > PlayerNaturalDropDownMaxDuration ||
                approachSpeed < 1.55f)
            {
                return false;
            }

            // The physical bound comes from takeoff speed and recorded airtime, not
            // from raising the global horizontal acceptance threshold. The 0.40m
            // margin covers short sample/landing timing uncertainty; the existing
            // extended jump envelope is a hard ceiling against arbitrarily long gaps.
            kinematicMaximum = Mathf.Min(
                PlayerJumpExtendedMaxHorizontalDistance,
                approachSpeed * elapsed + 0.40f);
            if (horizontalDistance > kinematicMaximum)
            {
                return false;
            }

            Vector3 dropDirection = GetFlatDirection(end - start);
            Vector3 takeoffDirection = GetFlatDirection(approachDirection);
            if (dropDirection.sqrMagnitude < 0.50f ||
                takeoffDirection.sqrMagnitude < 0.50f ||
                Vector3.Dot(dropDirection, takeoffDirection) < 0.70f ||
                GetPlanarDistance(samples[0].Position, start) > 1.25f ||
                GetPlanarDistance(samples[samples.Count - 1].Position, end) > 0.50f)
            {
                return false;
            }

            for (int i = 0; i < samples.Count; i++)
            {
                PlayerBreadcrumbNode sample = samples[i];
                if (sample == null || !IsFinite(sample.Position))
                {
                    return false;
                }
                if (!sample.Grounded)
                {
                    airborneSamples++;
                    if (sample.NavMeshSampled)
                    {
                        return false;
                    }
                }
                if (i == 0)
                {
                    continue;
                }
                PlayerBreadcrumbNode previous = samples[i - 1];
                float dt = sample.CreatedAt - previous.CreatedAt;
                if (dt <= 0f || dt > 0.55f ||
                    Vector3.Distance(sample.Position, previous.Position) >
                    Mathf.Max(0.80f, (approachSpeed + 1.20f) * dt + 0.35f))
                {
                    return false; // Missing chronology or an unexplained body displacement.
                }
            }
            if (airborneSamples < 3 || !samples[samples.Count - 1].Grounded ||
                !TrySampleCredibleDropDownTopEntry(start, takeoffDirection, out _) ||
                !NavMesh.SamplePosition(end, out NavMeshHit landing,
                    DropDownTopEntryProbeRadius, NavMesh.AllAreas) ||
                Mathf.Abs(landing.position.y - end.y) > 0.30f ||
                GetPlanarDistance(landing.position, end) > 0.55f)
            {
                return false;
            }
            return true;
        }

        private static bool TryGetLearningV417NativeProvenDropDownPortal(
            Vector3 rawStart,
            Vector3 rawEnd,
            StrictPathResult currentPath,
            out LearnedTraversalEdge provenEdge,
            out float portalMatchScore)
        {
            provenEdge = null;
            portalMatchScore = float.MaxValue;
            if ((!IsFinite(rawStart)) || !IsFinite(rawEnd) ||
                currentPath == null ||
                !IsSuspiciousBreadcrumbGap(Vector3.Distance(rawStart, rawEnd), currentPath))
            {
                return false;
            }

            foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges)
            {
                if (candidate == null || candidate.Disabled ||
                    !string.Equals(candidate.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                    !IsLearningV3NativeProvenEdge(candidate))
                {
                    continue;
                }

                Vector3 candidateStart = IsFinite(candidate.RawStart) ? candidate.RawStart : candidate.A;
                Vector3 candidateEnd = IsFinite(candidate.RawEnd) ? candidate.RawEnd : candidate.B;
                float provenVerticalDrop = candidateStart.y - candidateEnd.y;
                if (provenVerticalDrop < PlayerNaturalDropDownMinVerticalDrop ||
                    provenVerticalDrop > PlayerNaturalDropDownMaxVerticalDrop ||
                    !AreCrossKindTraversalEndpointsEquivalent(
                        rawStart, rawEnd, candidateStart, candidateEnd,
                        out bool reversed, out float score) ||
                    reversed)
                {
                    continue;
                }

                if (provenEdge == null || score < portalMatchScore)
                {
                    provenEdge = candidate;
                    portalMatchScore = score;
                }
            }

            return provenEdge != null;
        }

        private static bool TryMaterializeLearningV452KnownJumpPortalSubtrajectory(
            Player player,
            Vector3 demonstratedStart,
            Vector3 demonstratedEnd,
            Vector3 demonstratedApproachDirection,
            int demonstratedStartBreadcrumbSequence,
            int demonstratedEndBreadcrumbSequence,
            out int retainedEdgeId)
        {
            retainedEdgeId = 0;
            if ((player == null) ||
                !IsFinite(demonstratedStart) || !IsFinite(demonstratedEnd) ||
                demonstratedStartBreadcrumbSequence <= 0 ||
                demonstratedEndBreadcrumbSequence < demonstratedStartBreadcrumbSequence)
            {
                return false;
            }

            Vector3 demonstratedDirection = GetFlatDirection(demonstratedEnd - demonstratedStart);
            Vector3 approach = GetFlatDirection(demonstratedApproachDirection);
            Vector3 directionWitness = approach.sqrMagnitude > 0.01f ? approach : demonstratedDirection;
            LearnedTraversalEdge bestEdge = null;
            PlayerBreadcrumbNode bestEndNode = null;
            bool bestForward = true;
            float bestScore = float.MaxValue;

            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (edge == null || edge.Disabled || !edge.PlayerValidated ||
                    !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                    !IsLearningV3NativeProvenEdge(edge))
                {
                    continue;
                }

                for (int orientation = 0; orientation < 2; orientation++)
                {
                    bool forward = orientation == 0;
                    Vector3 rawStart = IsFinite(edge.RawStart) ? edge.RawStart : edge.A;
                    Vector3 rawEnd = IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B;
                    Vector3 orientedStart = forward ? rawStart : rawEnd;
                    Vector3 orientedEnd = forward ? rawEnd : rawStart;
                    Vector3 orientedEntry = forward ? edge.A : edge.B;
                    Vector3 orientedExit = forward ? edge.B : edge.A;
                    if (!forward && !IsTraversalOrientationAllowed(edge, orientedEntry, orientedExit))
                    {
                        continue;
                    }
                    if (GetPlanarDistance(demonstratedStart, orientedStart) >
                            PlayerJumpExistingEdgeRevalidationStartRadius ||
                        Mathf.Abs(demonstratedStart.y - orientedStart.y) >
                            PlayerJumpExistingEdgeRevalidationMaxVerticalDelta)
                    {
                        continue;
                    }

                    Vector3 orientedDirection = GetFlatDirection(orientedEnd - orientedStart);
                    if (orientedDirection.sqrMagnitude > 0.01f && directionWitness.sqrMagnitude > 0.01f &&
                        Vector3.Dot(orientedDirection, directionWitness) <
                            PlayerJumpExistingEdgeRevalidationMinDirectionDot)
                    {
                        continue;
                    }

                    PlayerBreadcrumbNode endNode = BreadcrumbRoute
                        .Where(node => node != null && IsFinite(node.Position) &&
                                       node.Sequence >= demonstratedStartBreadcrumbSequence &&
                                       node.Sequence <= demonstratedEndBreadcrumbSequence &&
                                       GetPlanarDistance(node.Position, orientedEnd) <=
                                           PlayerJumpExistingEdgeRevalidationEndRadius &&
                                       Mathf.Abs(node.Position.y - orientedEnd.y) <=
                                           PlayerJumpExistingEdgeRevalidationMaxVerticalDelta)
                        .OrderBy(node => GetPlanarDistance(node.Position, orientedEnd))
                        .ThenBy(node => node.Sequence)
                        .FirstOrDefault();
                    if (endNode == null || endNode.Sequence <= demonstratedStartBreadcrumbSequence)
                    {
                        continue;
                    }

                    float score = GetPlanarDistance(demonstratedStart, orientedStart) +
                                  GetPlanarDistance(endNode.Position, orientedEnd);
                    if (score >= bestScore)
                    {
                        continue;
                    }
                    bestEdge = edge;
                    bestEndNode = endNode;
                    bestForward = forward;
                    bestScore = score;
                }
            }

            if (bestEdge == null || bestEndNode == null)
            {
                return false;
            }

            TraversalEpisodeMetadata duplicateEpisode = TraversalEpisodeStream.FirstOrDefault(item =>
                item != null && item.EdgeId == bestEdge.Id &&
                string.Equals(item.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                item.StartBreadcrumbSequence <= bestEndNode.Sequence &&
                item.EndBreadcrumbSequence >= demonstratedStartBreadcrumbSequence);
            if (duplicateEpisode != null)
            {
                {
                    duplicateEpisode.LearningV453ExistingNativePortalSubtrajectoryRetained = true;
                }
                retainedEdgeId = bestEdge.Id;
                return true;
            }

            PlayerBreadcrumbNode startNode = BreadcrumbRoute
                .Where(node => node != null && IsFinite(node.Position) &&
                               node.Sequence >= demonstratedStartBreadcrumbSequence &&
                               node.Sequence <= bestEndNode.Sequence)
                .OrderBy(node => GetPlanarDistance(node.Position, demonstratedStart))
                .ThenBy(node => node.Sequence)
                .FirstOrDefault();
            Vector3 observedStart = startNode != null ? startNode.Position : demonstratedStart;
            int observedStartSequence = startNode != null
                ? startNode.Sequence
                : demonstratedStartBreadcrumbSequence;
            if (observedStartSequence >= bestEndNode.Sequence)
            {
                observedStartSequence = demonstratedStartBreadcrumbSequence;
                observedStart = demonstratedStart;
            }

            TraversalEpisodeMetadata materialized = RegisterTraversalEpisodeForEdge(
                bestEdge.Id,
                "Jump",
                observedStart,
                bestEndNode.Position,
                observedStartSequence,
                bestEndNode.Sequence,
                allowChain: true);
            if (materialized == null)
            {
                return false;
            }
            {
                materialized.LearningV453ExistingNativePortalSubtrajectoryRetained = true;
            }

            retainedEdgeId = bestEdge.Id;
            Vector3 retainedRawStart = IsFinite(bestEdge.RawStart) ? bestEdge.RawStart : bestEdge.A;
            Vector3 retainedRawEnd = IsFinite(bestEdge.RawEnd) ? bestEdge.RawEnd : bestEdge.B;
            Vector3 retainedOrientedStart = bestForward ? retainedRawStart : retainedRawEnd;
            Vector3 retainedOrientedEnd = bestForward ? retainedRawEnd : retainedRawStart;
            WriteEvent("learningV452KnownJumpPortalSubtrajectoryMaterialized", null, new
            {
                profileId = player.ProfileId,
                episodeId = materialized.EpisodeId,
                chainId = materialized.ChainId,
                edgeId = bestEdge.Id,
                forward = bestForward,
                demonstratedWholeStart = Vec(demonstratedStart),
                demonstratedWholeEnd = Vec(demonstratedEnd),
                observedSubtrajectoryStart = Vec(observedStart),
                observedSubtrajectoryEnd = Vec(bestEndNode.Position),
                portalStart = Vec(retainedOrientedStart),
                portalEnd = Vec(retainedOrientedEnd),
                startDistance = GetPlanarDistance(observedStart, retainedOrientedStart),
                endDistance = GetPlanarDistance(bestEndNode.Position, retainedOrientedEnd),
                directionDot = Vector3.Dot(
                    GetFlatDirection(retainedOrientedEnd - retainedOrientedStart),
                    directionWitness),
                persistentGeometryCreated = false,
                persistentSuccessCredited = false,
                action = "rejectedWholeGestureRetainsOnlyExistingNativeProvenPortalSubtrajectoryAsRaidLocalSemanticDebt"
            });
            WriteEvent("learningV452KnownJumpPortalRetentionUsesExistingNativeProof", null, new
            {
                edgeId = bestEdge.Id,
                nativeVerified = bestEdge.Verified,
                nativeSuccessCount = bestEdge.NativeSuccessCount,
                playerValidated = bestEdge.PlayerValidated,
                reverseAuthorityInheritedOnlyFromExistingEdge = !bestForward,
                startRadius = PlayerJumpExistingEdgeRevalidationStartRadius,
                endRadius = PlayerJumpExistingEdgeRevalidationEndRadius,
                minDirectionDot = PlayerJumpExistingEdgeRevalidationMinDirectionDot,
                maxVerticalDelta = PlayerJumpExistingEdgeRevalidationMaxVerticalDelta,
                persistentLearningChanged = false
            });
            return true;
        }

        private static bool TryFindExistingJumpRevalidationCandidate(
            Vector3 rawStart,
            Vector3 rawEnd,
            Vector3 approachDirection,
            out int edgeId)
        {
            edgeId = 0;
            if (!IsFinite(rawStart) || !IsFinite(rawEnd))
            {
                return false;
            }

            Vector3 demonstratedDirection = GetFlatDirection(rawEnd - rawStart);
            Vector3 approach = GetFlatDirection(approachDirection);
            foreach (LearnedTraversalEdge edge in LearnedTraversalEdges)
            {
                if (edge == null || edge.Disabled ||
                    !string.Equals(edge.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (GetPlanarDistance(rawStart, edge.RawStart) > PlayerJumpExistingEdgeRevalidationStartRadius ||
                    GetPlanarDistance(rawEnd, edge.RawEnd) > PlayerJumpExistingEdgeRevalidationEndRadius)
                {
                    continue;
                }

                Vector3 authoredDirection = GetFlatDirection(edge.RawEnd - edge.RawStart);
                Vector3 candidateDirection = approach.sqrMagnitude > 0.01f ? approach : demonstratedDirection;
                if (authoredDirection.sqrMagnitude > 0.01f && candidateDirection.sqrMagnitude > 0.01f &&
                    Vector3.Dot(authoredDirection, candidateDirection) < PlayerJumpExistingEdgeRevalidationMinDirectionDot)
                {
                    continue;
                }

                edgeId = edge.Id;
                return true;
            }

            return false;
        }

        private static void TryFinishLocalPlayerJumpShortcut(Player player)
        {
            if (!localJumpCandidateActive || !localJumpAwaitingLanding ||
                player?.MovementContext == null || localVaultActive ||
                IsTraversalStateName(player.CurrentStateName.ToString()))
            {
                return;
            }

            CompleteLocalPlayerJumpDemonstration(player, player.Position, "settledUpdate");
        }

        private static bool TryRegisterLearningV458ContinuousNativeJumpRuntimeEpisode(
            Player player,
            Vector3 end,
            float duration,
            float horizontalDistance,
            float verticalDelta,
            out int edgeId)
        {
            edgeId = 0;
            if ((player == null) ||
                !IsFinite(localJumpStartPosition) || !IsFinite(end) ||
                localJumpStartBreadcrumbSequence <= 0 || breadcrumbSequence <= localJumpStartBreadcrumbSequence)
            {
                return false;
            }

            List<PlayerBreadcrumbNode> witness = BreadcrumbRoute
                .Where(node => node != null && IsFinite(node.Position) &&
                               node.Sequence >= localJumpStartBreadcrumbSequence &&
                               node.Sequence <= breadcrumbSequence)
                .OrderBy(node => node.Sequence)
                .ToList();
            if (witness.Count < 3 ||
                !witness.Any(node => string.Equals(node.State, EPlayerState.Jump.ToString(), StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            // V474: observing the player's real EFT Jump trajectory proves what the PLAYER did,
            // not that a FOLLOWER has ever physically cleared the same horizontal displacement.
            // Current-raid, nonpersistent transfer is bounded by the longest strictly native-proven
            // follower Jump in this map (or the existing extended-player candidate envelope).
            // Longer gestures remain in the breadcrumb recording, but do not mint an executable
            // Jump mission which would trap the bot at an unreachable takeoff frontier.
            {
                float provenFollowerHorizontal = 0f;
                foreach (LearnedTraversalEdge proven in LearnedTraversalEdges)
                {
                    if (proven == null || proven.Disabled || !proven.Verified ||
                        proven.NativeSuccessCount <= 0 || proven.RuntimeOnlyTraversal ||
                        !string.Equals(proven.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                        !IsFinite(proven.RawStart) || !IsFinite(proven.RawEnd))
                    {
                        continue;
                    }
                    provenFollowerHorizontal = Mathf.Max(provenFollowerHorizontal,
                        GetPlanarDistance(proven.RawStart, proven.RawEnd));
                }
                float transferableHorizontal = Mathf.Max(
                    PlayerJumpExtendedMaxHorizontalDistance, provenFollowerHorizontal);
                if (horizontalDistance > transferableHorizontal)
                {
                    WriteEvent("learningV474ExtremeJumpRetainedAsObservationNotExecutable", null, new
                    {
                        start = Vec(localJumpStartPosition), end = Vec(end),
                        horizontalDistance, duration, verticalDelta,
                        nativeProvenFollowerHorizontal = provenFollowerHorizontal,
                        currentlyTransferableHorizontal = transferableHorizontal,
                        playerBreadcrumbCount = witness.Count,
                        runtimeEpisodeMinted = false,
                        persistentLearningChanged = false,
                        traversalSuccessRecorded = false,
                        action = "playerPhysicalJumpObservedButFollowerRangeUnprovenKeepBreadcrumbNotActuatorDebt"
                    });
                    return false;
                }
            }

            // This is current-raid execution evidence only. It deliberately bypasses the fixed
            // 5.5/8.5/9.25m persistence envelopes because the actual EFT Jump state plus a finite,
            // ordered body trajectory is stronger evidence that THIS episode happened. RuntimeOnly
            // prevents one extraordinary gesture from teaching permanent global geometry.
            LearnedTraversalEdge runtimeJump = new LearnedTraversalEdge
            {
                Id = ++learnedTraversalEdgeSequence,
                ExperienceKey = null,
                DemonstrationRevision = 1,
                Kind = "Jump",
                A = localJumpStartPosition,
                B = end,
                RawStart = localJumpStartPosition,
                RawEnd = end,
                CreatedAt = Time.time,
                PlayerValidated = true,
                Verified = false,
                Disabled = false,
                RuntimeOnlyTraversal = true,
                RuntimeAlternativeParentEdgeId = 0,
                RuntimeAuthoritySource = "learningV458ContinuousNativeJumpWitness",
                ApproachDirection = localJumpApproachDirection,
                ApproachSpeed = localJumpApproachSpeed,
                ApproachMode = localJumpApproachMode,
                TraversalDuration = duration,
                PlayerTraversalSequence = ++playerTraversalSequence
            };
            LearnedTraversalEdges.Add(runtimeJump);
            TrimLearnedTraversalEdgesToLimit();
            TraversalEpisodeMetadata episode = RegisterTraversalEpisodeForEdge(
                runtimeJump.Id,
                "Jump",
                localJumpStartPosition,
                end,
                localJumpStartBreadcrumbSequence,
                breadcrumbSequence);
            if (episode == null)
            {
                LearnedTraversalEdges.Remove(runtimeJump);
                return false;
            }

            edgeId = runtimeJump.Id;
            WriteEvent("learningV458ContinuousNativeJumpRuntimeEpisodeRegistered", null, new
            {
                profileId = player.ProfileId,
                edgeId = runtimeJump.Id,
                episodeId = episode.EpisodeId,
                chainId = episode.ChainId,
                start = Vec(localJumpStartPosition),
                end = Vec(end),
                duration,
                horizontalDistance,
                verticalDelta,
                breadcrumbSamples = witness.Count,
                runtimeOnly = true,
                persistentLearningChanged = false,
                traversalSuccessRecorded = false,
                action = "actualEftJumpTrajectoryExecutesThisRaidWithoutExpandingGlobalPersistenceDistanceThresholds"
            });
            return true;
        }

        private static void CompleteLocalPlayerJumpDemonstration(Player player, Vector3 end, string source)
        {
            if (!localJumpCandidateActive || player?.MovementContext == null || !IsFinite(end))
            {
                return;
            }

            float duration = Mathf.Max(0f, Time.time - localJumpStartedAt);
            Vector3 delta = end - localJumpStartPosition;
            float horizontalDistance = new Vector2(delta.x, delta.z).magnitude;
            float verticalDelta = delta.y;
            float directDistance = Vector3.Distance(localJumpStartPosition, end);

            bool rampApproach = localJumpApproachEdgeId > 0;
            bool dropDown = verticalDelta <= PlayerJumpDropDownMinVerticalDelta;
            bool existingJumpRevalidation = TryFindExistingJumpRevalidationCandidate(
                localJumpStartPosition,
                end,
                localJumpApproachDirection,
                out int existingJumpRevalidationEdgeId);
            float normalVerticalLimit = existingJumpRevalidation
                ? PlayerJumpExistingEdgeRevalidationMaxVerticalDelta
                : PlayerJumpCandidateMaxVerticalDelta;
            bool normalPlausible = duration >= 0.08f && duration <= 2.25f &&
                                   horizontalDistance >= 0.65f &&
                                   horizontalDistance <= PlayerJumpCandidateMaxHorizontalDistance &&
                                   Mathf.Abs(verticalDelta) <= normalVerticalLimit;
            bool extendedPlausible = duration >= 0.08f && duration <= 2.25f &&
                                     horizontalDistance >= 0.65f &&
                                     horizontalDistance <= PlayerJumpExtendedMaxHorizontalDistance &&
                                     Mathf.Abs(verticalDelta) <= PlayerJumpExtendedMaxVerticalDelta &&
                                     (rampApproach || dropDown);
            bool plausible = normalPlausible || extendedPlausible;
            float learningV380PlayerJumpApexY = localJumpStartPosition.y;
            foreach (PlayerBreadcrumbNode learningV380JumpNode in BreadcrumbRoute)
            {
                if (learningV380JumpNode == null || !IsFinite(learningV380JumpNode.Position) ||
                    learningV380JumpNode.Sequence < localJumpStartBreadcrumbSequence ||
                    learningV380JumpNode.Sequence > breadcrumbSequence)
                {
                    continue;
                }
                learningV380PlayerJumpApexY = Mathf.Max(
                    learningV380PlayerJumpApexY, learningV380JumpNode.Position.y);
            }
            float learningV380PlayerJumpApexRise =
                learningV380PlayerJumpApexY - localJumpStartPosition.y;
            // Reuse the existing Jump-approach physical rise contract.  A tiny automatic threshold
            // hop may transiently enter EFT's Jump/JumpLanding states, but it must not create an
            // actuator affordance over an already-known Vault/Climb portal unless the player's body
            // actually demonstrates Jump-like vertical authority. Ramp/drop subtypes already carry
            // their own independent semantic evidence and remain eligible.
            bool learningV380CrossKindJumpActuatorWitness =
                (rampApproach) || dropDown ||
                learningV380PlayerJumpApexRise >= JumpApproachCaptureMinRise;
            string jumpSubtype = rampApproach
                ? "RampApproach"
                : (dropDown ? "DropDown" : "Normal");
            if (plausible)
            {
                StrictPathResult path = CalculateStrictPath(localJumpStartPosition, end);
                bool navMeshShortcut = !path.StrictComplete ||
                                       path.PathLength >= Mathf.Max(
                                           directDistance * FollowDetourRatioThreshold,
                                           directDistance + 3.0f);
                int learnedJumpEdgeId = 0;
                int semanticSiblingEdgeId = 0;
                string semanticSiblingKind = null;
                LearnedTraversalEdge jumpSemanticSibling = null;
                bool siblingReversed = false;
                bool crossKindAlternativeConfirmed = false;
                int crossKindCandidateDemonstrations = 0;
                bool hasSemanticSibling = navMeshShortcut && TryFindVaultClimbSemanticSibling(
                    localJumpStartPosition, end, out jumpSemanticSibling, out siblingReversed);
                bool semanticSiblingDeduped = false;
                if (hasSemanticSibling)
                {
                    semanticSiblingEdgeId = jumpSemanticSibling.Id;
                    semanticSiblingKind = jumpSemanticSibling.Kind;
                    if (learningV380CrossKindJumpActuatorWitness)
                    {
                        crossKindAlternativeConfirmed = RegisterCrossKindJumpCandidate(
                            jumpSemanticSibling,
                            siblingReversed,
                            localJumpStartPosition,
                            end,
                            out crossKindCandidateDemonstrations);
                    }
                    semanticSiblingDeduped = !crossKindAlternativeConfirmed;

                    if ((!learningV380CrossKindJumpActuatorWitness))
                    {
                        WriteEvent("learningV380CrossKindJumpActuatorAuthoritySuppressed", null, new
                        {
                            profileId = player.ProfileId,
                            start = Vec(localJumpStartPosition),
                            end = Vec(end),
                            siblingEdgeId = semanticSiblingEdgeId,
                            siblingKind = semanticSiblingKind,
                            siblingReversed,
                            apexY = learningV380PlayerJumpApexY,
                            apexRise = learningV380PlayerJumpApexRise,
                            requiredRise = JumpApproachCaptureMinRise,
                            jumpSubtype,
                            persistentLearningChanged = false,
                            action = "automaticThresholdHopRemainsPhysicalCorridorUnlessExistingJumpRiseContractIsProven"
                        });
                    }

                    WriteEvent(
                        crossKindAlternativeConfirmed
                            ? "playerJumpCrossKindAlternativeConfirmed"
                            : "playerJumpCrossKindCandidateQuarantined",
                        null,
                        new
                        {
                            profileId = player.ProfileId,
                            start = Vec(localJumpStartPosition),
                            end = Vec(end),
                            siblingEdgeId = semanticSiblingEdgeId,
                            siblingKind = semanticSiblingKind,
                            siblingReversed,
                            demonstrations = crossKindCandidateDemonstrations,
                            requiredDemonstrations = CrossKindJumpAlternativeRequiredDemonstrations,
                            persisted = crossKindAlternativeConfirmed,
                            reason = crossKindAlternativeConfirmed
                                ? "repeatedPlayerDemonstration"
                                : "firstObservationOverlapsExistingVaultClimb"
                        });
                }

                if (semanticSiblingDeduped)
                {
                    // V3.79 separates execution authority from persistence authority. The player
                    // physically performed a plausible Jump in this exact current route, so the
                    // follower must be allowed to execute Jump now even if a historical Vault/Climb
                    // sibling occupies the same portal. The first observation remains raid-local and
                    // cannot persist until repeated player proof or a clean follower Native success.
                    if ((navMeshShortcut) &&
                        learningV380CrossKindJumpActuatorWitness)
                    {
                        LearnedTraversalEdge currentJump = null;
                        if (existingJumpRevalidation && existingJumpRevalidationEdgeId > 0)
                        {
                            currentJump = LearnedTraversalEdges.FirstOrDefault(candidate =>
                                candidate != null && candidate.Id == existingJumpRevalidationEdgeId &&
                                string.Equals(candidate.Kind, "Jump", StringComparison.OrdinalIgnoreCase));
                            learnedJumpEdgeId = currentJump?.Id ?? 0;
                        }

                        if (learnedJumpEdgeId <= 0)
                        {
                            learnedJumpEdgeId = RememberLearnedTraversalEdge(
                                localJumpStartPosition,
                                end,
                                "Jump",
                                true,
                                new PlayerTraversalMotionProfile
                                {
                                    ApproachDirection = localJumpApproachDirection,
                                    ApproachSpeed = localJumpApproachSpeed,
                                    ApproachMode = localJumpApproachMode,
                                    TraversalDuration = duration
                                },
                                walkThroughCorridorSamples: null,
                                runtimeOnlyTraversal: true,
                                runtimeAlternativeParentEdgeId: semanticSiblingEdgeId,
                                runtimeAuthoritySource: "learningV379CurrentEpisodeCrossKindJump");
                            currentJump = LearnedTraversalEdges.FirstOrDefault(candidate =>
                                candidate != null && candidate.Id == learnedJumpEdgeId);
                        }

                        if (currentJump != null)
                        {
                            if (crossKindAlternativeConfirmed && currentJump.RuntimeOnlyTraversal)
                            {
                                currentJump.RuntimeOnlyTraversal = false;
                                currentJump.DemonstrationRevision = Math.Max(
                                    currentJump.DemonstrationRevision,
                                    CrossKindJumpAlternativeRequiredDemonstrations);
                                currentJump.RuntimeAuthoritySource = null;
                                WriteEvent("learningV379RuntimeAlternativePromotedByRepeatedPlayerProof", null, new
                                {
                                    edgeId = currentJump.Id,
                                    parentEdgeId = currentJump.RuntimeAlternativeParentEdgeId,
                                    demonstrations = crossKindCandidateDemonstrations,
                                    demonstrationRevision = currentJump.DemonstrationRevision,
                                    action = "repeatedIndependentPlayerJumpAllowsPersistentCandidate"
                                });
                                SavePersistentTraversalLinks();
                            }

                            currentJump.PlayerValidated = true;
                            currentJump.Disabled = false;
                            currentJump.CreatedAt = Time.time;
                            RecordLearningV418PlayerJumpApproachEvidence(
                                currentJump, localJumpApproachMode, localJumpApproachSpeed,
                                "currentEpisodeCrossKindJump");
                            TraversalEpisodeMetadata runtimeJumpEpisode = RegisterTraversalEpisodeForEdge(
                                currentJump.Id,
                                "Jump",
                                localJumpStartPosition,
                                end,
                                localJumpStartBreadcrumbSequence > 0
                                    ? localJumpStartBreadcrumbSequence
                                    : Mathf.Max(0, breadcrumbSequence - 1),
                                breadcrumbSequence);
                            WriteEvent("learningV379CurrentEpisodeCrossKindJumpExecutionAuthority", null, new
                            {
                                edgeId = currentJump.Id,
                                episodeId = runtimeJumpEpisode?.EpisodeId ?? 0,
                                chainId = runtimeJumpEpisode?.ChainId ?? 0,
                                siblingEdgeId = semanticSiblingEdgeId,
                                siblingKind = semanticSiblingKind,
                                runtimeOnly = currentJump.RuntimeOnlyTraversal,
                                demonstrations = crossKindCandidateDemonstrations,
                                persistentLearningChanged = crossKindAlternativeConfirmed && !currentJump.RuntimeOnlyTraversal,
                                action = "currentPlayerJumpExecutesImmediatelyPersistenceStillRequiresIndependentProof"
                            });
                        }
                    }
                }
                else if (navMeshShortcut)
                {
                    if (existingJumpRevalidation && existingJumpRevalidationEdgeId > 0)
                    {
                        // CompileFix46: never let a single new jump attempt rewrite a previously
                        // learned Jump geometry before post-landing retention is known. Revalidation
                        // preserves the authored edge; a failed attempt therefore cannot poison the
                        // existing start/end/approach data.
                        LearnedTraversalEdge preservedJump = LearnedTraversalEdges.FirstOrDefault(candidate =>
                            candidate != null && candidate.Id == existingJumpRevalidationEdgeId &&
                            string.Equals(candidate.Kind, "Jump", StringComparison.OrdinalIgnoreCase));
                        if (preservedJump != null)
                        {
                            preservedJump.PlayerValidated = true;
                            preservedJump.Disabled = false;
                            preservedJump.PlayerTraversalSequence = ++playerTraversalSequence;
                            learnedJumpEdgeId = preservedJump.Id;
                            RecordLearningV418PlayerJumpApproachEvidence(
                                preservedJump, localJumpApproachMode, localJumpApproachSpeed,
                                "existingJumpGeometryRevalidation");
                            if ((crossKindAlternativeConfirmed) && preservedJump.RuntimeOnlyTraversal)
                            {
                                preservedJump.RuntimeOnlyTraversal = false;
                                preservedJump.DemonstrationRevision = Math.Max(
                                    preservedJump.DemonstrationRevision,
                                    CrossKindJumpAlternativeRequiredDemonstrations);
                                preservedJump.RuntimeAuthoritySource = null;
                                WriteEvent("learningV379RuntimeAlternativePromotedByRepeatedPlayerProof", null, new
                                {
                                    edgeId = preservedJump.Id,
                                    parentEdgeId = preservedJump.RuntimeAlternativeParentEdgeId,
                                    demonstrations = crossKindCandidateDemonstrations,
                                    demonstrationRevision = preservedJump.DemonstrationRevision,
                                    action = "repeatedIndependentPlayerJumpAllowsPersistentCandidate"
                                });
                            }
                            SavePersistentTraversalLinks();
                            WriteEvent("playerJumpExistingGeometryPreserved", null, new
                            {
                                edgeId = preservedJump.Id,
                                demonstrationRevision = preservedJump.DemonstrationRevision,
                                candidateStart = Vec(localJumpStartPosition),
                                candidateEnd = Vec(end),
                                storedStart = Vec(preservedJump.RawStart),
                                storedEnd = Vec(preservedJump.RawEnd),
                                reason = "awaitPostLandingRetentionWithoutGeometryRewrite"
                            });
                        }
                    }

                    if (learnedJumpEdgeId <= 0)
                    {
                        learnedJumpEdgeId = RememberLearnedTraversalEdge(
                            localJumpStartPosition,
                            end,
                            "Jump",
                            true,
                            new PlayerTraversalMotionProfile
                            {
                                ApproachDirection = localJumpApproachDirection,
                                ApproachSpeed = localJumpApproachSpeed,
                                ApproachMode = localJumpApproachMode,
                                TraversalDuration = duration
                            });

                        // New Jump knowledge starts quarantined. PrepareSettledAnchorsForLearnedEdge
                        // already armed the rolling-landing capture; only a grounded forward
                        // continuation after landing may promote it to PlayerValidated.
                        LearnedTraversalEdge pendingJump = LearnedTraversalEdges.FirstOrDefault(candidate =>
                            candidate != null && candidate.Id == learnedJumpEdgeId);
                        if (pendingJump != null)
                        {
                            RecordLearningV418PlayerJumpApproachEvidence(
                                pendingJump, localJumpApproachMode, localJumpApproachSpeed,
                                "newJumpDemonstration");
                            if (crossKindAlternativeConfirmed)
                            {
                                // The first matching observation lived only in the raid-local
                                // candidate cache, so stamp the persisted alternate as a trusted
                                // repeated demonstration for sanitizer/failure protection.
                                pendingJump.DemonstrationRevision = Math.Max(
                                    pendingJump.DemonstrationRevision,
                                    CrossKindJumpAlternativeRequiredDemonstrations);
                            }
                            pendingJump.PlayerValidated = false;
                            pendingJump.Disabled = true;
                            SavePersistentTraversalLinks();
                            WriteEvent("playerJumpPendingPostLandingValidation", null, new
                            {
                                edgeId = pendingJump.Id,
                                demonstrationRevision = pendingJump.DemonstrationRevision,
                                rawStart = Vec(pendingJump.RawStart),
                                rawEnd = Vec(pendingJump.RawEnd)
                            });
                        }
                    }

                    RegisterTraversalEpisodeForEdge(
                        learnedJumpEdgeId,
                        "Jump",
                        localJumpStartPosition,
                        end,
                        localJumpStartBreadcrumbSequence > 0
                            ? localJumpStartBreadcrumbSequence
                            : Mathf.Max(0, breadcrumbSequence - 1),
                        breadcrumbSequence);
                }

                WriteEvent("playerJumpLanding", null, new
                {
                    profileId = player.ProfileId,
                    source,
                    start = Vec(localJumpStartPosition),
                    end = Vec(end),
                    duration,
                    horizontalDistance,
                    verticalDelta,
                    strictPath = path.ToPayload(),
                    shortcutQualified = navMeshShortcut,
                    jumpSubtype,
                    existingJumpRevalidation,
                    existingJumpRevalidationEdgeId,
                    normalVerticalLimit,
                    rampApproachEdgeId = localJumpApproachEdgeId,
                    rampApproachEpisodeId = localJumpApproachEpisodeId,
                    learned = learnedJumpEdgeId > 0,
                    edgeId = learnedJumpEdgeId,
                    semanticSiblingDeduped,
                    semanticSiblingEdgeId,
                    semanticSiblingKind,
                    crossKindCandidateDemonstrations,
                    crossKindAlternativeConfirmed,
                    apexY = learningV380PlayerJumpApexY,
                    apexRise = learningV380PlayerJumpApexRise,
                    crossKindActuatorWitness = learningV380CrossKindJumpActuatorWitness
                });

                if (navMeshShortcut && learnedJumpEdgeId <= 0 && !semanticSiblingDeduped)
                {
                    WriteEvent("playerJumpEdgePersistRejected", null, new
                    {
                        profileId = player.ProfileId,
                        source,
                        directDistance,
                        horizontalDistance,
                        verticalDelta,
                        jumpSubtype,
                        rampApproachEdgeId = localJumpApproachEdgeId
                    });
                }
            }
            else
            {
                bool learningV452KnownPortalRetained =
                    TryMaterializeLearningV452KnownJumpPortalSubtrajectory(
                        player,
                        localJumpStartPosition,
                        end,
                        localJumpApproachDirection,
                        localJumpStartBreadcrumbSequence > 0
                            ? localJumpStartBreadcrumbSequence
                            : Mathf.Max(0, breadcrumbSequence - 1),
                        breadcrumbSequence,
                        out int learningV452RetainedPortalEdgeId);
                int learningV458RuntimeJumpEdgeId = 0;
                bool learningV458ContinuousRuntimeJump = !learningV452KnownPortalRetained &&
                    TryRegisterLearningV458ContinuousNativeJumpRuntimeEpisode(
                        player, end, duration, horizontalDistance, verticalDelta,
                        out learningV458RuntimeJumpEdgeId);
                WriteEvent("playerJumpLandingRejected", null, new
                {
                    profileId = player.ProfileId,
                    source,
                    start = Vec(localJumpStartPosition),
                    end = Vec(end),
                    duration,
                    horizontalDistance,
                    verticalDelta,
                    jumpSubtype,
                    existingJumpRevalidation,
                    existingJumpRevalidationEdgeId,
                    normalVerticalLimit,
                    rampApproachEdgeId = localJumpApproachEdgeId,
                    learningV452KnownPortalRetained,
                    learningV452RetainedPortalEdgeId,
                    learningV458ContinuousRuntimeJump,
                    learningV458RuntimeJumpEdgeId,
                    wholeRejectedGeometryPersisted = false
                });
            }

            localJumpCandidateActive = false;
            localJumpAwaitingLanding = false;
            localJumpApproachEdgeId = 0;
            localJumpApproachEpisodeId = 0;
            localJumpStartBreadcrumbSequence = 0;
            CaptureBreadcrumb(player, true);
        }


        // RC61: GetLearningV381PortalIdentityEndpoint extracted unchanged to FollowerTraversalPhysicalCorridorPolicy.cs.

        // RC61: GetLearningV381PhysicalCorridorApproachSpeed extracted unchanged to FollowerTraversalPhysicalCorridorPolicy.cs.

        // RC61: GetLearningV381PhysicalCorridorApproachMode extracted unchanged to FollowerTraversalPhysicalCorridorPolicy.cs.

        // RC61: GetLearningV381PhysicalCorridorDriveSpeed extracted unchanged to FollowerTraversalPhysicalCorridorPolicy.cs.

        // RC61: GetLearningV381PhysicalCorridorSprintIntent extracted unchanged to FollowerTraversalPhysicalCorridorPolicy.cs.

        private static bool TryCaptureLearningV379CurrentPortalPhysicalAlternative(
            Player player,
            PlayerBreadcrumbNode currentNode)
        {
            if ((player?.MovementContext == null) ||
                currentNode == null || !IsFinite(currentNode.Position) || IsTraversalStateName(currentNode.State) ||
                BreadcrumbRoute.Count < 3)
            {
                return false;
            }

            LearnedTraversalEdge portalSibling = null;
            PlayerBreadcrumbNode portalStart = null;
            bool portalReversed = false;
            float bestPortalScore = float.MaxValue;
            int currentIndex = BreadcrumbRoute.Count - 1;

            foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges)
            {
                if (candidate == null || candidate.Disabled || candidate.SyntheticPhysicalCorridor ||
                    ((candidate.RuntimeOnlyTraversal) && !candidate.Verified && candidate.NativeSuccessCount <= 0) ||
                    (!string.Equals(candidate.Kind, "Vault", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(candidate.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(candidate.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                Vector3 candidateStart = IsFinite(candidate.RawStart) ? candidate.RawStart : candidate.A;
                Vector3 candidateEnd = IsFinite(candidate.RawEnd) ? candidate.RawEnd : candidate.B;
                if (!IsFinite(candidateStart) || !IsFinite(candidateEnd))
                {
                    continue;
                }

                bool currentNearForwardEnd =
                    GetPlanarDistance(currentNode.Position, candidateEnd) <= CrossKindJumpSiblingPlanarEndpointDistance &&
                    Mathf.Abs(currentNode.Position.y - candidateEnd.y) <= CrossKindJumpSiblingVerticalEndpointDistance;
                bool currentNearReverseEnd =
                    GetPlanarDistance(currentNode.Position, candidateStart) <= CrossKindJumpSiblingPlanarEndpointDistance &&
                    Mathf.Abs(currentNode.Position.y - candidateStart.y) <= CrossKindJumpSiblingVerticalEndpointDistance;
                if (!currentNearForwardEnd && !currentNearReverseEnd)
                {
                    continue;
                }

                for (int index = currentIndex - 1; index >= 0; index--)
                {
                    PlayerBreadcrumbNode startNode = BreadcrumbRoute[index];
                    if (startNode == null || !IsFinite(startNode.Position))
                    {
                        continue;
                    }

                    float age = Mathf.Max(0f, currentNode.CreatedAt - startNode.CreatedAt);
                    if (age > TraversalChainMaxEpisodeGapSeconds)
                    {
                        break;
                    }

                    if (!AreCrossKindTraversalEndpointsEquivalent(
                            startNode.Position,
                            currentNode.Position,
                            candidateStart,
                            candidateEnd,
                            out bool reversed,
                            out float score) ||
                        score >= bestPortalScore)
                    {
                        continue;
                    }

                    float direct = GetPlanarDistance(startNode.Position, currentNode.Position);
                    float vertical = Mathf.Abs(startNode.Position.y - currentNode.Position.y);
                    if (direct < WalkThroughCandidateMinDistance ||
                        direct > WalkThroughMaxExecutionDistance ||
                        vertical > WalkThroughMaxVerticalDelta)
                    {
                        continue;
                    }

                    List<PlayerBreadcrumbNode> window = BreadcrumbRoute
                        .Where(node => node != null &&
                                       node.Sequence >= startNode.Sequence &&
                                       node.Sequence <= currentNode.Sequence &&
                                       IsFinite(node.Position))
                        .OrderBy(node => node.Sequence)
                        .ToList();
                    if (window.Count < 2 || window.Any(node => IsTraversalStateName(node.State)))
                    {
                        continue;
                    }

                    bool typedOverlap = TraversalEpisodeStream.Any(item =>
                        item != null &&
                        item.EndBreadcrumbSequence >= startNode.Sequence &&
                        item.StartBreadcrumbSequence <= currentNode.Sequence &&
                        !string.Equals(item.Kind, "PhysicalCorridor", StringComparison.OrdinalIgnoreCase));
                    if (typedOverlap)
                    {
                        continue;
                    }

                    StrictPathResult strictPath = CalculateStrictPath(startNode.Position, currentNode.Position);
                    bool physicallyUnrepresented =
                        strictPath != null && strictPath.CalculateReturned &&
                        (!strictPath.StrictComplete ||
                         strictPath.PathLength > GetAllowedFollowPathLength(
                             Vector3.Distance(startNode.Position, currentNode.Position), true));
                    if (!physicallyUnrepresented)
                    {
                        continue;
                    }

                    portalSibling = candidate;
                    portalStart = startNode;
                    portalReversed = reversed;
                    bestPortalScore = score;
                }
            }

            if (portalSibling == null || portalStart == null)
            {
                return false;
            }

            List<PlayerBreadcrumbNode> corridor = BreadcrumbRoute
                .Where(node => node != null &&
                               node.Sequence >= portalStart.Sequence &&
                               node.Sequence <= currentNode.Sequence &&
                               IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            if (corridor.Count < 2)
            {
                return false;
            }

            Vector3 portalSiblingStart = IsFinite(portalSibling.RawStart) ? portalSibling.RawStart : portalSibling.A;
            Vector3 portalSiblingEnd = IsFinite(portalSibling.RawEnd) ? portalSibling.RawEnd : portalSibling.B;
            LearnedTraversalEdge synthetic = LearnedTraversalEdges
                .Where(candidate => candidate != null && candidate.SyntheticPhysicalCorridor &&
                                    string.Equals(
                                        GetLearningV354SemanticKind(candidate.Id, candidate.Kind),
                                        "PhysicalCorridor",
                                        StringComparison.OrdinalIgnoreCase))
                .Select(candidate => new
                {
                    Edge = candidate,
                    Start = GetLearningV381PortalIdentityEndpoint(candidate, false),
                    End = GetLearningV381PortalIdentityEndpoint(candidate, true)
                })
                .Where(item =>
                {
                    if ((item.Edge.RuntimeOnlyTraversal) &&
                        AreCrossKindTraversalEndpointsEquivalent(
                            item.Start, item.End,
                            portalSiblingStart, portalSiblingEnd,
                            out _, out _))
                    {
                        // V381: parent action geometry establishes that two runtime corridors refer
                        // to the same physical portal, but direction must come from the player's
                        // observed movement rather than whichever Vault/Climb/Jump sibling happened
                        // to mint the synthetic edge. This prevents opposite-authored siblings from
                        // splitting one direction or merging opposite directions.
                        Vector3 observedStart = IsFinite(item.Edge.RawStart) ? item.Edge.RawStart : item.Edge.A;
                        Vector3 observedEnd = IsFinite(item.Edge.RawEnd) ? item.Edge.RawEnd : item.Edge.B;
                        float observedForwardCost =
                            Vector3.Distance(observedStart, portalSiblingStart) +
                            Vector3.Distance(observedEnd, portalSiblingEnd);
                        float observedReverseCost =
                            Vector3.Distance(observedStart, portalSiblingEnd) +
                            Vector3.Distance(observedEnd, portalSiblingStart);
                        bool observedPortalReversed = observedReverseCost < observedForwardCost;
                        return observedPortalReversed == portalReversed;
                    }
                    return AreCrossKindTraversalEndpointsEquivalent(
                        portalStart.Position, currentNode.Position, item.Start, item.End, out _, out _);
                })
                .Select(item => item.Edge)
                .FirstOrDefault();

            bool created = false;
            if (synthetic == null)
            {
                synthetic = new LearnedTraversalEdge
                {
                    Id = ++learnedTraversalEdgeSequence,
                    ExperienceKey = null,
                    DemonstrationRevision = 1,
                    Kind = ("PhysicalCorridor"),
                    A = portalStart.Position,
                    B = currentNode.Position,
                    RawStart = portalStart.Position,
                    RawEnd = currentNode.Position,
                    CreatedAt = Time.time,
                    PlayerValidated = true,
                    Verified = false,
                    Disabled = false,
                    SyntheticPhysicalCorridor = true,
                    RuntimeSemanticKind = "PhysicalCorridor",
                    RuntimeOnlyTraversal = true,
                    RuntimeAlternativeParentEdgeId = portalSibling.Id,
                    RuntimeAuthoritySource = "learningV379CurrentPortalPhysicalAlternative",
                    ApproachDirection = GetFlatDirection(currentNode.Position - portalStart.Position),
                    ApproachSpeed = GetLearningV381PhysicalCorridorApproachSpeed(corridor),
                    ApproachMode = GetLearningV381PhysicalCorridorApproachMode(corridor),
                    WalkThroughCorridorSamples = corridor.Select(node => node.Position).Where(IsFinite).ToList(),
                    EgressSamples = new List<Vector3>()
                };
                LearnedTraversalEdges.Add(synthetic);
                TrimLearnedTraversalEdgesToLimit();
                created = true;
            }
            else
            {
                TraversalEpisodeMetadata recentEpisode = TraversalEpisodeStream
                    .Where(item => item != null && item.EdgeId == synthetic.Id)
                    .OrderByDescending(item => item.EpisodeId)
                    .FirstOrDefault();
                if ((recentEpisode != null) &&
                    currentNode.Sequence - recentEpisode.EndBreadcrumbSequence <= TraversalChainImmediateMaxBreadcrumbGap &&
                    Time.time - recentEpisode.CreatedAt <= WalkThroughEpisodeCloseGraceSeconds)
                {
                    synthetic.PlayerValidated = true;
                    synthetic.Disabled = false;
                    synthetic.CreatedAt = Time.time;
                    synthetic.RuntimeOnlyTraversal = true;
                    if (synthetic.RuntimeAlternativeParentEdgeId <= 0)
                    {
                        synthetic.RuntimeAlternativeParentEdgeId = portalSibling.Id;
                    }
                    synthetic.RuntimeAuthoritySource = "learningV380PortalPhysicalEpisodeConvergence";
                    synthetic.RawStart = portalStart.Position;
                    synthetic.RawEnd = currentNode.Position;
                    synthetic.A = portalStart.Position;
                    synthetic.B = currentNode.Position;
                    synthetic.ApproachDirection = GetFlatDirection(currentNode.Position - portalStart.Position);
                    synthetic.ApproachSpeed = GetLearningV381PhysicalCorridorApproachSpeed(corridor);
                    synthetic.ApproachMode = GetLearningV381PhysicalCorridorApproachMode(corridor);
                    synthetic.WalkThroughCorridorSamples =
                        corridor.Select(node => node.Position).Where(IsFinite).ToList();

                    int learningV380PreviousEndSequence = recentEpisode.EndBreadcrumbSequence;
                    recentEpisode.EndBreadcrumbSequence = Math.Max(
                        recentEpisode.EndBreadcrumbSequence, currentNode.Sequence);
                    recentEpisode.Exit = currentNode.Position;
                    recentEpisode.RawEnd = currentNode.Position;
                    recentEpisode.LearningV372HasCurrentExecutionGeometry = true;
                    recentEpisode.LearningV372CurrentExecutionStart = portalStart.Position;
                    recentEpisode.LearningV372CurrentExecutionEnd = currentNode.Position;
                    recentEpisode.LearningV372ExecutionGeometrySource =
                        "learningV380PortalPhysicalEpisodeConvergence";

                    WriteEvent("learningV380PortalPhysicalEpisodeExtended", null, new
                    {
                        edgeId = synthetic.Id,
                        episodeId = recentEpisode.EpisodeId,
                        chainId = recentEpisode.ChainId,
                        portalSiblingEdgeId = portalSibling.Id,
                        portalSiblingKind = portalSibling.Kind,
                        portalReversed,
                        fromSequence = portalStart.Sequence,
                        previousEndSequence = learningV380PreviousEndSequence,
                        toSequence = currentNode.Sequence,
                        start = Vec(portalStart.Position),
                        end = Vec(currentNode.Position),
                        sampleCount = corridor.Count,
                        persistentLearningChanged = false,
                        action = "extendSamePortalPassageInsteadOfRegisteringSecondExecutionDebt"
                    });
                    return true;
                }
                ;

                synthetic.PlayerValidated = true;
                synthetic.Disabled = false;
                synthetic.CreatedAt = Time.time;
                synthetic.RuntimeOnlyTraversal = true;
                if (synthetic.RuntimeAlternativeParentEdgeId <= 0)
                {
                    synthetic.RuntimeAlternativeParentEdgeId = portalSibling.Id;
                }
                synthetic.RuntimeAuthoritySource = "learningV379CurrentPortalPhysicalAlternative";
                synthetic.RawStart = portalStart.Position;
                synthetic.RawEnd = currentNode.Position;
                synthetic.A = portalStart.Position;
                synthetic.B = currentNode.Position;
                synthetic.ApproachDirection = GetFlatDirection(currentNode.Position - portalStart.Position);
                synthetic.ApproachSpeed = GetLearningV381PhysicalCorridorApproachSpeed(corridor);
                synthetic.ApproachMode = GetLearningV381PhysicalCorridorApproachMode(corridor);
                synthetic.WalkThroughCorridorSamples =
                    corridor.Select(node => node.Position).Where(IsFinite).ToList();
            }

            StrictPathResult routeProof = CalculateStrictPath(portalStart.Position, currentNode.Position);
            TraversalEpisodeMetadata metadata = RegisterTraversalEpisodeForEdge(
                synthetic.Id,
                "PhysicalCorridor",
                portalStart.Position,
                currentNode.Position,
                portalStart.Sequence,
                currentNode.Sequence,
                allowChain: true,
                preferredEpisodeId: 0,
                skipPreGapEmission: true);

            WriteEvent("learningV379CurrentPortalPhysicalAlternativeRegistered", null, new
            {
                edgeId = synthetic.Id,
                episodeId = metadata?.EpisodeId ?? 0,
                chainId = metadata?.ChainId ?? 0,
                portalSiblingEdgeId = portalSibling.Id,
                portalSiblingKind = portalSibling.Kind,
                portalReversed,
                created,
                fromSequence = portalStart.Sequence,
                toSequence = currentNode.Sequence,
                start = Vec(portalStart.Position),
                end = Vec(currentNode.Position),
                sampleCount = corridor.Count,
                strictPath = routeProof?.ToPayload(),
                persistentLearningChanged = false,
                selectedExecutor = "None",
                action = "currentPlayerPhysicalPassageBecomesRuntimePortalAffordanceWithoutInventingAssistOrActuator"
            });
            return true;
        }

        private static void CaptureBreadcrumb(Player player, bool force)
        {
            if (player?.MovementContext == null || (!force && Time.time < nextBreadcrumbCheckAt))
            {
                return;
            }
            nextBreadcrumbCheckAt = Time.time + BreadcrumbCheckInterval;

            Vector3 position = player.Position;
            Vector3 direction = GetFlatDirection(player.MovementContext.PlayerRealForward);
            if (!IsFinite(position) || direction.sqrMagnitude < 0.5f)
            {
                return;
            }

            bool postureBoundary=BreadcrumbRoute.Count>0&&FollowerCapabilityPosturePolicy.Crouched(BreadcrumbRoute[BreadcrumbRoute.Count-1].Pose)!=FollowerCapabilityPosturePolicy.Crouched(player.MovementContext.PoseLevel);
            bool shouldRecord = postureBoundary || force || !haveLastBreadcrumb ||
                                Vector3.Distance(position, lastBreadcrumbPosition) >= BreadcrumbMinDistance ||
                                Time.time - lastBreadcrumbAt >= BreadcrumbMaxInterval ||
                                Vector3.Angle(direction, lastBreadcrumbDirection) >= BreadcrumbTurnDegrees;
            if (!shouldRecord)
            {
                return;
            }

            PlayerBreadcrumbNode previousNode = BreadcrumbRoute.Count > 0
                ? BreadcrumbRoute[BreadcrumbRoute.Count - 1]
                : null;

            haveLastBreadcrumb = true;
            lastBreadcrumbPosition = position;
            lastBreadcrumbDirection = direction;
            lastBreadcrumbAt = Time.time;
            breadcrumbSequence++;

            bool breadcrumbNavSampled = NavMesh.SamplePosition(position, out NavMeshHit breadcrumbNavHit, NavMeshSampleRadius, NavMesh.AllAreas);
            PlayerBreadcrumbNode node = new PlayerBreadcrumbNode
            {
                Sequence = breadcrumbSequence,
                Position = position,
                Direction = direction,
                State = player.CurrentStateName.ToString(),
                Sprinting = player.MovementContext.IsSprintEnabled || player.CurrentStateName == EPlayerState.Sprint,
                Grounded = player.MovementContext.IsGrounded,
                Pose = player.MovementContext.PoseLevel,
                CreatedAt = Time.time,
                NavMeshSampled = breadcrumbNavSampled,
                NavMeshPosition = breadcrumbNavSampled ? breadcrumbNavHit.position : position
            };
            BreadcrumbRoute.Add(node);
            PruneBreadcrumbRoute();
            UpdatePendingTraversalSettledExitCaptures(node);
            RegisterLearningV347KnownWalkThroughCrossings(node);
            bool crouchSegment=previousNode!=null&&FollowerCapabilityPosturePolicy.Capture(
                previousNode.Pose,node.Pose,previousNode.State,node.State,Vector3.Distance(previousNode.Position,node.Position),
                Mathf.Abs(previousNode.Position.y-node.Position.y),node.CreatedAt-previousNode.CreatedAt);
            bool crouchContinuation=activeWalkThroughEpisode!=null&&FollowerCapabilityPosturePolicy.Crouched(activeWalkThroughEpisode.RequiredPose)&&
                previousNode!=null&&FollowerCapabilityPosturePolicy.Crouched(previousNode.Pose)&&FollowerCapabilityPosturePolicy.Crouched(node.Pose)&&
                FollowerCapabilityPosturePolicy.Locomotion(previousNode.State)&&FollowerCapabilityPosturePolicy.Locomotion(node.State)&&
                Vector3.Distance(previousNode.Position,node.Position)<.15f&&node.CreatedAt-previousNode.CreatedAt<=2f;
            if(postureBoundary&&activeWalkThroughEpisode!=null)
            {
                CompleteCapabilityPostureEpisode(node);
                FinalizeActiveWalkThroughEpisode("postureBoundary");
            }
            if(!crouchSegment&&!crouchContinuation&&!postureBoundary)TryCaptureLearningV379CurrentPortalPhysicalAlternative(player, node);

            // Traversal V3: a short ordinary player step can teach a persistent
            // WalkThrough edge when NavMesh cannot represent the same local move. Grounded/floor
            // continuity is advisory; explicit Jump/Vault/Climb states remain authoritative.
            if (previousNode != null && !postureBoundary &&
                !localNaturalDropCandidateActive &&
                Time.time >= localTraversalWalkThroughSuppressUntil &&
                !IsTraversalStateName(node.State) &&
                !IsTraversalStateName(previousNode.State))
            {
                float stepDirect = Vector3.Distance(previousNode.Position, node.Position);
                float stepVertical = Mathf.Abs(node.Position.y - previousNode.Position.y);
                if (crouchSegment || crouchContinuation || (stepDirect >= WalkThroughCandidateMinDistance &&
                    stepDirect <= WalkThroughCandidateMaxDistance &&
                    stepVertical <= WalkThroughCandidateMaxVerticalDelta))
                {
                    StrictPathResult segmentPath = CalculateStrictPath(previousNode.Position, node.Position);
                    bool walkThroughCandidate = crouchSegment || crouchContinuation || !segmentPath.StrictComplete ||
                                                segmentPath.PathLength >= Mathf.Max(
                                                    stepDirect * 2.0f,
                                                    stepDirect + 3.5f);
                    if (walkThroughCandidate)
                    {
                        bool suppressCandidate = false;
                        if (!crouchSegment&&!crouchContinuation&&TryFindCheapLocalWalkThroughBypass(
                                previousNode.Position,
                                node.Position,
                                out float localBypassCost,
                                out Vector3 localBypassStart,
                                out Vector3 localBypassEnd,
                                out float localBypassShoulder))
                        {
                            bool followerUtilityOverride = ShouldOverrideCheapLocalWalkThroughBypassForFollowers(
                                previousNode.Position, node.Position, null,
                                out string utilityFollowerProfileId,
                                out float utilityDirectDistance,
                                out float utilityPathLength,
                                out float utilityDetourRatio);
                            LearnedTraversalEdge historicalSemantic = FindLearningV344HistoricalWalkThroughMatch(
                                previousNode.Position, node.Position);
                            suppressCandidate = (historicalSemantic != null) || !followerUtilityOverride;
                            if (historicalSemantic != null)
                            {
                                RegisterTraversalEpisodeForEdge(
                                    historicalSemantic.Id, "WalkThrough", previousNode.Position, node.Position,
                                    previousNode.Sequence, node.Sequence, allowChain: true);
                                TryCloseActiveWalkThroughEpisode(node, "learningV344HistoricalSemanticAuthority");
                            }
                            else if (suppressCandidate)
                            {
                                TryCloseActiveWalkThroughEpisode(node, "learningV318CheapLocalNavMeshBypass");
                            }
                            WriteEvent(historicalSemantic != null
                                ? "learningV344HistoricalWalkThroughSemanticAuthorityOverridesLocalBypass"
                                : (followerUtilityOverride)
                                    ? "learningV345FollowerUtilityOverridesCheapLocalWalkThroughBypass"
                                    : "learningV318WalkThroughLocalBypassAuthoritySuppressed", null, new
                            {
                                source = "livePlayerCandidate",
                                historicalEdgeId = historicalSemantic?.Id ?? 0,
                                historicalExperienceKey = historicalSemantic?.ExperienceKey ?? string.Empty,
                                fromSequence = previousNode.Sequence,
                                toSequence = node.Sequence,
                                start = Vec(previousNode.Position),
                                end = Vec(node.Position),
                                directDistance = stepDirect,
                                localBypassCost,
                                bypassStart = Vec(localBypassStart),
                                bypassEnd = Vec(localBypassEnd),
                                shoulderOffset = localBypassShoulder,
                                followerProfileId = utilityFollowerProfileId,
                                followerDirectDistance = utilityDirectDistance,
                                followerPathLength = utilityPathLength,
                                followerDetourRatio = utilityDetourRatio,
                                reason = historicalSemantic != null
                                    ? "historicallyVerifiedTraversalTruthOutranksNavMeshHeuristic"
                                    : (followerUtilityOverride)
                                        ? "followerRouteRequiresPlayerProvenPassage"
                                        : "cheapLocalNavMeshBypassOwnsLocalSemanticTruth"
                            });
                        }

                        if (!suppressCandidate)
                        {
                            bool corridorClear = TryValidateWalkThroughCorridor(
                                player,
                                previousNode.Position,
                                node.Position,
                                out string corridorFailure,
                                out string blocker);
                            int episodeId = ExtendActiveWalkThroughEpisode(previousNode, node);

                            WriteEvent("playerWalkThroughCandidate", null, new
                            {
                                fromSequence = previousNode.Sequence,
                                toSequence = node.Sequence,
                                start = Vec(previousNode.Position),
                                end = Vec(node.Position),
                                directDistance = stepDirect,
                                verticalDelta = stepVertical,
                                strictPath = segmentPath.ToPayload(),
                                corridorClear,
                                corridorFailure,
                                blocker,
                                episodeId,
                                coalesced = true
                            });
                        }
                    }
                    else
                    {
                        TryCloseActiveWalkThroughEpisode(node, "navMeshRecovered");
                    }
                }
            }

            if (activeWalkThroughEpisode != null &&
                ((Time.time - activeWalkThroughEpisode.LastUpdatedAt >= WalkThroughEpisodeCloseGraceSeconds&&
                  !FollowerCapabilityPosturePolicy.HoldDropBoundary(localNaturalDropCandidateActive,
                      localNaturalDropWalkThroughSnapshot?.EpisodeId??0,activeWalkThroughEpisode.EpisodeId)) ||
                 IsTraversalStateName(node.State)))
            {
                FinalizeActiveWalkThroughEpisode(IsTraversalStateName(node.State) ? "stateBoundary" : "candidateGap");
            }

            if (activeWalkThroughEpisode == null &&
                !localNaturalDropCandidateActive &&
                Time.time >= localTraversalWalkThroughSuppressUntil &&
                !IsTraversalStateName(node.State) &&
                (previousNode == null || !IsTraversalStateName(previousNode.State)))
            {
                {
                    TryCaptureLearningV339ForwardKnownWalkThroughRouteFact(node);
                }
                {
                    TryCaptureLearningV314ReverseKnownWalkThroughRouteFact(node);
                }
            }

            WriteEvent("playerBreadcrumb", null, new
            {
                breadcrumbSequence,
                profileId = player.ProfileId,
                position = Vec(position),
                direction = Vec(direction),
                state = player.CurrentStateName.ToString(),
                sprinting = node.Sprinting,
                grounded = player.MovementContext.IsGrounded,
                pose = player.MovementContext.PoseLevel,
                navMesh = breadcrumbNavSampled
                    ? new { sampled = true, radius = NavMeshSampleRadius, position = (object?)Vec(node.NavMeshPosition), offset = Vector3.Distance(position, node.NavMeshPosition), verticalOffset = Mathf.Abs(position.y - node.NavMeshPosition.y) }
                    : new { sampled = false, radius = NavMeshSampleRadius, position = (object?)null, offset = -1f, verticalOffset = -1f }
            });
        }

        private static int ExtendActiveWalkThroughEpisode(PlayerBreadcrumbNode from, PlayerBreadcrumbNode to)
        {
            if (from == null || to == null)
            {
                return 0;
            }

            float requiredPose=FollowerCapabilityPosturePolicy.Required(from.Pose,to.Pose,from.State,to.State);
            Vector3 segmentDirection = GetFlatDirection(to.Position - from.Position);
            bool canExtend = activeWalkThroughEpisode != null &&
                             FollowerCapabilityPosturePolicy.Same(activeWalkThroughEpisode.RequiredPose,requiredPose) &&
                             activeWalkThroughEpisode.EndSequence == from.Sequence &&
                             Time.time - activeWalkThroughEpisode.LastUpdatedAt <= WalkThroughEpisodeMaxGapSeconds &&
                             Vector3.Distance(activeWalkThroughEpisode.RawStart, to.Position) <= WalkThroughEpisodeMaxDirectDistance &&
                             (activeWalkThroughEpisode.Direction.sqrMagnitude < 0.5f ||
                              segmentDirection.sqrMagnitude < 0.5f ||
                              Vector3.Angle(activeWalkThroughEpisode.Direction, segmentDirection) <= WalkThroughEpisodeMaxDirectionChange);

            if (!canExtend)
            {
                FinalizeActiveWalkThroughEpisode("corridorBoundary");
                activeWalkThroughEpisode = new WalkThroughEpisodeBuilder
                {
                    EpisodeId = ++traversalEpisodeSequence,
                    RequiredPose = requiredPose,
                    StartSequence = from.Sequence,
                    EndSequence = to.Sequence,
                    RawStart = from.Position,
                    RawEnd = to.Position,
                    Direction = segmentDirection,
                    StartedAt = from.CreatedAt > 0f ? from.CreatedAt : Time.time,
                    LastUpdatedAt = to.CreatedAt > 0f ? to.CreatedAt : Time.time,
                    MovementMode = string.Equals(from.State, "Sprint", StringComparison.OrdinalIgnoreCase) ||
                                   string.Equals(to.State, "Sprint", StringComparison.OrdinalIgnoreCase)
                        ? "Sprint"
                        : (string.Equals(from.State, "Run", StringComparison.OrdinalIgnoreCase) ||
                           string.Equals(to.State, "Run", StringComparison.OrdinalIgnoreCase) ? "Run" : "Walk"),
                    CorridorSamples = new List<Vector3> { from.Position, to.Position }
                };
                WriteEvent("playerWalkThroughEpisodeStarted", null, new
                {
                    episodeId = activeWalkThroughEpisode.EpisodeId,
                    fromSequence = from.Sequence,
                    toSequence = to.Sequence,
                    start = Vec(from.Position),
                    end = Vec(to.Position)
                });
            }
            else
            {
                activeWalkThroughEpisode.EndSequence = to.Sequence;
                activeWalkThroughEpisode.RawEnd = to.Position;
                activeWalkThroughEpisode.Direction = GetFlatDirection(activeWalkThroughEpisode.RawEnd - activeWalkThroughEpisode.RawStart);
                activeWalkThroughEpisode.LastUpdatedAt = to.CreatedAt > 0f ? to.CreatedAt : Time.time;
                if (string.Equals(to.State, "Sprint", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(from.State, "Sprint", StringComparison.OrdinalIgnoreCase))
                {
                    activeWalkThroughEpisode.MovementMode = "Sprint";
                }
                else if (!string.Equals(activeWalkThroughEpisode.MovementMode, "Sprint", StringComparison.OrdinalIgnoreCase) &&
                         (string.Equals(to.State, "Run", StringComparison.OrdinalIgnoreCase) ||
                          string.Equals(from.State, "Run", StringComparison.OrdinalIgnoreCase)))
                {
                    activeWalkThroughEpisode.MovementMode = "Run";
                }
                if (activeWalkThroughEpisode.CorridorSamples == null)
                {
                    activeWalkThroughEpisode.CorridorSamples = new List<Vector3>();
                }
                if (activeWalkThroughEpisode.CorridorSamples.Count == 0 ||
                    Vector3.Distance(activeWalkThroughEpisode.CorridorSamples[activeWalkThroughEpisode.CorridorSamples.Count - 1], to.Position) > 0.05f)
                {
                    activeWalkThroughEpisode.CorridorSamples.Add(to.Position);
                }
            }

            WriteEvent("playerWalkThroughEpisodeExtended", null, new
            {
                episodeId = activeWalkThroughEpisode.EpisodeId,
                startSequence = activeWalkThroughEpisode.StartSequence,
                endSequence = activeWalkThroughEpisode.EndSequence,
                start = Vec(activeWalkThroughEpisode.RawStart),
                end = Vec(activeWalkThroughEpisode.RawEnd),
                directDistance = Vector3.Distance(activeWalkThroughEpisode.RawStart, activeWalkThroughEpisode.RawEnd)
            });
            return activeWalkThroughEpisode.EpisodeId;
        }

        private static void TryCloseActiveWalkThroughEpisode(PlayerBreadcrumbNode current, string reason)
        {
            if (activeWalkThroughEpisode == null)
            {
                return;
            }

            if (current == null ||
                current.Sequence > activeWalkThroughEpisode.EndSequence ||
                Time.time - activeWalkThroughEpisode.LastUpdatedAt >= WalkThroughEpisodeCloseGraceSeconds)
            {
                if (current != null &&
                    current.Grounded &&
                    !IsTraversalStateName(current.State) &&
                    TrySampleTraversalSettledAnchor(current.Position, 0.80f, out Vector3 recoveredExit))
                {
                    activeWalkThroughEpisode.HasSettledExit = true;
                    activeWalkThroughEpisode.SettledExit = recoveredExit;
                    activeWalkThroughEpisode.SettledExitSequence = current.Sequence;
                }
                FinalizeActiveWalkThroughEpisode(reason);
            }
        }

        private static WalkThroughEpisodeBuilder? MergeRejectedNaturalDropIntoWalkThrough(
            WalkThroughEpisodeBuilder snapshot,
            WalkThroughEpisodeBuilder current,
            Vector3 landing,
            int landingSequence)
        {
            bool published=IsCapabilityWalkThroughSnapshotPublished(snapshot);
            if(!FollowerCapabilityPosturePolicy.MergeSnapshot(published,current!=null,snapshot?.RequiredPose??1f,current?.RequiredPose??1f))
            {
                WriteEvent("capabilityWalkThroughSnapshotRestoreRejected",null,new{snapshotEpisode=snapshot?.EpisodeId??0,
                    currentEpisode=current?.EpisodeId??0,published,snapshotPose=snapshot?.RequiredPose??1f,currentPose=current?.RequiredPose??1f,
                    nativeSuccessRecorded=false});
                return current;
            }
            WalkThroughEpisodeBuilder merged = CloneWalkThroughEpisode(snapshot);
            if (merged == null)
            {
                return current;
            }

            if (merged.CorridorSamples == null)
            {
                merged.CorridorSamples = new List<Vector3>();
            }

            if (current?.CorridorSamples != null)
            {
                // CompileFix13: current normally contains the snapshot prefix plus the samples
                // captured while airborne. Appending the whole list replayed A,B,A,B,C... into
                // persistent corridors and manufactured 180-degree turns. Skip the largest
                // snapshot-suffix/current-prefix overlap and append only genuinely new samples.
                AppendWalkThroughSamplesWithoutPrefixReplay(merged.CorridorSamples, current.CorridorSamples);
            }

            if (IsFinite(landing) &&
                (merged.CorridorSamples.Count == 0 ||
                 Vector3.Distance(merged.CorridorSamples[merged.CorridorSamples.Count - 1], landing) > 0.05f))
            {
                merged.CorridorSamples.Add(landing);
            }

            if (IsFinite(landing))
            {
                merged.RawEnd = landing;
                merged.Direction = GetFlatDirection(merged.RawEnd - merged.RawStart);
            }
            merged.EndSequence = Math.Max(merged.EndSequence, landingSequence);
            merged.LastUpdatedAt = Time.time;
            return merged;
        }

        private static void AppendWalkThroughSamplesWithoutPrefixReplay(
            List<Vector3> destination,
            IEnumerable<Vector3> source)
        {
            if (destination == null || source == null)
            {
                return;
            }

            List<Vector3> incoming = source.Where(IsFinite).ToList();
            if (incoming.Count == 0)
            {
                return;
            }

            int overlap = 0;
            int maxOverlap = Math.Min(destination.Count, incoming.Count);
            for (int candidate = maxOverlap; candidate >= 1; candidate--)
            {
                bool match = true;
                for (int index = 0; index < candidate; index++)
                {
                    Vector3 existing = destination[destination.Count - candidate + index];
                    if (Vector3.Distance(existing, incoming[index]) > 0.08f)
                    {
                        match = false;
                        break;
                    }
                }

                if (match)
                {
                    overlap = candidate;
                    break;
                }
            }

            for (int index = overlap; index < incoming.Count; index++)
            {
                Vector3 sample = incoming[index];
                if (destination.Count == 0 ||
                    Vector3.Distance(destination[destination.Count - 1], sample) > 0.05f)
                {
                    destination.Add(sample);
                }
            }
        }

        private static List<Vector3> RemoveWalkThroughPrefixReplayContamination(IEnumerable<Vector3> source)
        {
            List<Vector3> input = source?.Where(IsFinite).ToList() ?? new List<Vector3>();
            if (input.Count < 4)
            {
                return input;
            }

            List<Vector3> output = new List<Vector3>();
            int index = 0;
            while (index < input.Count)
            {
                // The CompileFix12 bug always replayed the beginning of the same episode. Detect
                // only >=2-point prefix replays so legitimate single-point hairpins are preserved.
                if (output.Count >= 2 && Vector3.Distance(input[index], output[0]) <= 0.08f)
                {
                    int matched = 0;
                    while (index + matched < input.Count && matched < output.Count &&
                           Vector3.Distance(input[index + matched], output[matched]) <= 0.08f)
                    {
                        matched++;
                    }
                    if (matched >= 2)
                    {
                        index += matched;
                        continue;
                    }
                }

                Vector3 sample = input[index++];
                if (output.Count == 0 || Vector3.Distance(output[output.Count - 1], sample) > 0.05f)
                {
                    output.Add(sample);
                }
            }
            return output;
        }

        private static WalkThroughEpisodeBuilder CloneWalkThroughEpisode(WalkThroughEpisodeBuilder source)
        {
            if (source == null)
            {
                return null;
            }

            return new WalkThroughEpisodeBuilder
            {
                EpisodeId = source.EpisodeId,
                RequiredPose = FollowerCapabilityPosturePolicy.Normalize(source.RequiredPose),
                StartSequence = source.StartSequence,
                EndSequence = source.EndSequence,
                RawStart = source.RawStart,
                RawEnd = source.RawEnd,
                Direction = source.Direction,
                StartedAt = source.StartedAt,
                LastUpdatedAt = source.LastUpdatedAt,
                MovementMode = source.MovementMode,
                CorridorSamples = source.CorridorSamples != null
                    ? source.CorridorSamples.Where(IsFinite).ToList()
                    : new List<Vector3>(),
                HasSettledExit = source.HasSettledExit,
                SettledExit = source.SettledExit,
                SettledExitSequence = source.SettledExitSequence
            };
        }

        private static bool HasStrongPersistentWalkThroughTopologyEvidence(
            WalkThroughEpisodeBuilder episode,
            out string evidence)
        {
            evidence = string.Empty;
            if (episode == null || !IsFinite(episode.RawStart) || !IsFinite(episode.RawEnd))
            {
                return false;
            }

            float direct = GetPlanarDistance(episode.RawStart, episode.RawEnd);
            if (direct >= WalkThroughStandalonePersistMinDistance)
            {
                evidence = "passageSpan";
                return true;
            }

            // V3.37: a sub-0.85m passage must be proven by LOCAL topology. A follower can be tens
            // of metres away behind unrelated topology, so its global current-position detour is
            // not admissible evidence for a tiny seam under the player's feet.
            {
                evidence = "localMicroSeamRequiresLocalTopology";
                return false;
            }

            // CompileFix50 legacy fallback for disabled V3.37 contract.
            if (ShouldOverrideCheapLocalWalkThroughBypassForFollowers(
                    episode.RawStart,
                    episode.RawEnd,
                    null,
                    out string followerProfileId,
                    out float followerDirectDistance,
                    out float followerPathLength,
                    out float followerDetourRatio))
            {
                evidence = $"followerTopologyDetour:{followerProfileId}:{followerDirectDistance:0.00}/{followerPathLength:0.00}:{followerDetourRatio:0.00}x";
                return true;
            }

            return false;
        }

        private static List<Vector3> SimplifyWalkThroughPassageSamples(
            IEnumerable<Vector3> source,
            Vector3 rawStart,
            Vector3 rawEnd)
        {
            List<Vector3> input = RemoveWalkThroughPrefixReplayContamination(source);
            if (input.Count == 0)
            {
                input.Add(rawStart);
                input.Add(rawEnd);
            }
            else
            {
                if (Vector3.Distance(input[0], rawStart) > 0.08f)
                {
                    input.Insert(0, rawStart);
                }
                if (Vector3.Distance(input[input.Count - 1], rawEnd) > 0.08f)
                {
                    input.Add(rawEnd);
                }
            }

            // First remove breadcrumb jitter. The vertical component is deliberately ignored for
            // spacing: a 20-30 cm curb/ditch belongs to this passage, but is not a new steering point.
            List<Vector3> spaced = new List<Vector3>();
            foreach (Vector3 point in input.Where(IsFinite))
            {
                if (spaced.Count == 0 ||
                    GetPlanarDistance(spaced[spaced.Count - 1], point) >= WalkThroughPassageSampleMinPlanarSpacing ||
                    point == rawEnd)
                {
                    spaced.Add(point);
                }
            }
            if (spaced.Count < 3)
            {
                return spaced;
            }

            // Iteratively remove micro-terrain vertices that are almost collinear in XZ. This keeps
            // real corners/door approaches while flattening the saw-tooth corridor generated by
            // NavMesh sampled=false / micro-airborne flicker on rough junk piles.
            bool changed;
            do
            {
                changed = false;
                for (int i = 1; i < spaced.Count - 1; i++)
                {
                    Vector3 previous = spaced[i - 1];
                    Vector3 current = spaced[i];
                    Vector3 next = spaced[i + 1];
                    float lateral = GetPlanarDistanceToSegment(current, previous, next);
                    float linearY = Mathf.Lerp(previous.y, next.y,
                        Mathf.Clamp01(GetPlanarDistance(previous, current) /
                                      Mathf.Max(0.001f, GetPlanarDistance(previous, next))));
                    float verticalDeviation = Mathf.Abs(current.y - linearY);
                    Vector3 inDir = GetFlatDirection(current - previous);
                    Vector3 outDir = GetFlatDirection(next - current);
                    float directionDot = inDir.sqrMagnitude >= 0.5f && outDir.sqrMagnitude >= 0.5f
                        ? Vector3.Dot(inDir, outDir)
                        : 1f;

                    bool microTerrain = lateral <= WalkThroughPassageStraightLateralTolerance &&
                                        verticalDeviation <= WalkThroughPassageMicroVerticalDeviation &&
                                        directionDot >= 0.70f;
                    // A tiny reversal inside a sub-metre patch is recorder noise, not an authored
                    // instruction for the follower to turn back.
                    bool localHairpin = directionDot < -0.15f &&
                                        GetPlanarDistance(previous, next) <= 0.85f;
                    if (microTerrain || localHairpin)
                    {
                        spaced.RemoveAt(i);
                        changed = true;
                        break;
                    }
                }
            }
            while (changed && spaced.Count >= 3);

            return spaced;
        }

        private static bool IsMalformedWalkThroughGeometry(LearnedTraversalEdge edge, out string reason)
        {
            reason = string.Empty;
            if (edge == null || !string.Equals(edge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            Vector3 start = IsFinite(edge.RawStart) ? edge.RawStart : edge.A;
            Vector3 end = IsFinite(edge.RawEnd) ? edge.RawEnd : edge.B;
            float direct = GetPlanarDistance(start, end);
            if (direct < 0.05f)
            {
                reason = "degenerateSpan";
                return true;
            }

            List<Vector3> samples = edge.WalkThroughCorridorSamples?.Where(IsFinite).ToList() ?? new List<Vector3>();
            if (samples.Count < 2)
            {
                return false;
            }

            float polyline = 0f;
            float maxLateral = 0f;
            float minY = float.MaxValue;
            float maxY = float.MinValue;
            for (int i = 0; i < samples.Count; i++)
            {
                Vector3 point = samples[i];
                minY = Mathf.Min(minY, point.y);
                maxY = Mathf.Max(maxY, point.y);
                maxLateral = Mathf.Max(maxLateral, GetPlanarDistanceToSegment(point, start, end));
                if (i > 0)
                {
                    polyline += GetPlanarDistance(samples[i - 1], point);
                }
            }

            if (polyline > direct * WalkThroughMalformedPolylineRatio + WalkThroughMalformedPolylineSlack &&
                maxLateral > WalkThroughMalformedLateralExcursion)
            {
                reason = $"hairpinPolyline:{polyline:0.00}/{direct:0.00}:lateral={maxLateral:0.00}";
                return true;
            }
            if (maxY - minY > WalkThroughSemanticVerticalRange && direct <= 3.0f)
            {
                reason = $"semanticVerticalRange:{(maxY - minY):0.00}";
                return true;
            }
            return false;
        }

        private static void FinalizeActiveWalkThroughEpisode(string reason)
        {
            WalkThroughEpisodeBuilder episode = activeWalkThroughEpisode;
            activeWalkThroughEpisode = null;
            if (episode == null)
            {
                return;
            }

            float directDistance = Vector3.Distance(episode.RawStart, episode.RawEnd);
            if (directDistance < WalkThroughCandidateMinDistance || directDistance > WalkThroughEpisodeMaxDirectDistance)
            {
                WriteEvent("playerWalkThroughEpisodeDiscarded", null, new
                {
                    episodeId = episode.EpisodeId,
                    reason,
                    directDistance,
                    startSequence = episode.StartSequence,
                    endSequence = episode.EndSequence
                });
                foreach (string profileId in ProvisionalWalkThroughReservations
                    .Where(pair => pair.Value != null && pair.Value.EpisodeId == episode.EpisodeId)
                    .Select(pair => pair.Key)
                    .ToArray())
                {
                    ProvisionalWalkThroughReservations.Remove(profileId);
                }
                return;
            }

            string tinyTopologyEvidence = string.Empty;
            if (!FollowerCapabilityPosturePolicy.Crouched(episode.RequiredPose)&&directDistance < WalkThroughStandalonePersistMinDistance &&
                !HasStrongPersistentWalkThroughTopologyEvidence(episode, out tinyTopologyEvidence))
            {
                WriteEvent("playerWalkThroughEpisodeDiscarded", null, new
                {
                    episodeId = episode.EpisodeId,
                    reason = "microTerrainPassageSample",
                    originalReason = reason,
                    directDistance,
                    startSequence = episode.StartSequence,
                    endSequence = episode.EndSequence,
                    minimumStandaloneDistance = WalkThroughStandalonePersistMinDistance
                });
                foreach (string profileId in ProvisionalWalkThroughReservations
                    .Where(pair => pair.Value != null && pair.Value.EpisodeId == episode.EpisodeId)
                    .Select(pair => pair.Key)
                    .ToArray())
                {
                    ProvisionalWalkThroughReservations.Remove(profileId);
                }
                return;
            }
            else if (directDistance < WalkThroughStandalonePersistMinDistance)
            {
                WriteEvent("playerWalkThroughMicroSeamTopologyProven", null, new
                {
                    episodeId = episode.EpisodeId,
                    directDistance,
                    evidence = tinyTopologyEvidence
                });
            }

            episode.CorridorSamples = SimplifyWalkThroughPassageSamples(
                episode.CorridorSamples, episode.RawStart, episode.RawEnd);

            if (!FollowerCapabilityPosturePolicy.Crouched(episode.RequiredPose)&&TryFindCheapLocalWalkThroughBypass(
                    episode.RawStart,
                    episode.RawEnd,
                    out float episodeBypassCost,
                    out Vector3 episodeBypassStart,
                    out Vector3 episodeBypassEnd,
                    out float episodeBypassShoulder))
            {
                bool followerUtilityOverride = ShouldOverrideCheapLocalWalkThroughBypassForFollowers(
                    episode.RawStart, episode.RawEnd, null,
                    out string utilityFollowerProfileId,
                    out float utilityDirectDistance,
                    out float utilityPathLength,
                    out float utilityDetourRatio);
                LearnedTraversalEdge historicalSemantic = FindLearningV344HistoricalWalkThroughMatch(
                    episode.RawStart, episode.RawEnd);
                if (historicalSemantic != null)
                {
                    TraversalEpisodeMetadata historicalEpisode = RegisterTraversalEpisodeForEdge(
                        historicalSemantic.Id, "WalkThrough", episode.RawStart, episode.RawEnd,
                        episode.StartSequence, episode.EndSequence, allowChain: true);
                    ApplyLearningV372CurrentEpisodeWalkThroughExecutionGeometry(null,historicalEpisode,historicalSemantic,
                        episode.RawStart,episode.RawEnd,"finalizedPlayerWalkThroughHistoricalIdentity");
                    WriteEvent("learningV344HistoricalWalkThroughEpisodeBoundToRestoredSemantic", null, new
                    {
                        edgeId = historicalSemantic.Id,
                        experienceKey = historicalSemantic.ExperienceKey,
                        episodeId = historicalEpisode?.EpisodeId ?? 0,
                        sourceWalkThroughEpisodeId = episode.EpisodeId,
                        startSequence = episode.StartSequence,
                        endSequence = episode.EndSequence,
                        localBypassCost = episodeBypassCost,
                        followerDirectDistance = utilityDirectDistance,
                        followerPathLength = utilityPathLength,
                        followerDetourRatio = utilityDetourRatio,
                        action = "reuseHistoricalSemanticAuthorityWithoutCreatingNativeSuccessCredit"
                    });
                    foreach (string profileId in ProvisionalWalkThroughReservations
                        .Where(pair => pair.Value != null && pair.Value.EpisodeId == episode.EpisodeId)
                        .Select(pair => pair.Key)
                        .ToArray())
                    {
                        ProvisionalWalkThroughReservations.Remove(profileId);
                    }
                    return;
                }
                if ((followerUtilityOverride))
                {
                    WriteEvent("learningV345FollowerUtilityOverridesCheapLocalWalkThroughBypass", null, new
                    {
                        source = "episodeFinalize",
                        episodeId = episode.EpisodeId,
                        startSequence = episode.StartSequence,
                        endSequence = episode.EndSequence,
                        followerProfileId = utilityFollowerProfileId,
                        followerDirectDistance = utilityDirectDistance,
                        followerPathLength = utilityPathLength,
                        followerDetourRatio = utilityDetourRatio,
                        action = "followerRouteRequiresPlayerProvenPassage"
                    });
                }
                else
                {
                    WriteEvent("learningV318WalkThroughLocalBypassAuthoritySuppressed", null, new
                    {
                    source = "episodeFinalize",
                    episodeId = episode.EpisodeId,
                    startSequence = episode.StartSequence,
                    endSequence = episode.EndSequence,
                    start = Vec(episode.RawStart),
                    end = Vec(episode.RawEnd),
                    directDistance,
                    localBypassCost = episodeBypassCost,
                    bypassStart = Vec(episodeBypassStart),
                    bypassEnd = Vec(episodeBypassEnd),
                    shoulderOffset = episodeBypassShoulder,
                    followerProfileId = utilityFollowerProfileId,
                    followerDirectDistance = utilityDirectDistance,
                    followerPathLength = utilityPathLength,
                    followerDetourRatio = utilityDetourRatio,
                    reason = "cheapLocalNavMeshBypassOwnsLocalSemanticTruth"
                    });
                    foreach (string profileId in ProvisionalWalkThroughReservations
                        .Where(pair => pair.Value != null && pair.Value.EpisodeId == episode.EpisodeId)
                        .Select(pair => pair.Key)
                        .ToArray())
                    {
                        ProvisionalWalkThroughReservations.Remove(profileId);
                    }
                    return;
                }
            }

            int edgeId = RememberLearnedTraversalEdge(
                episode.RawStart,
                episode.RawEnd,
                "WalkThrough",
                true,
                new PlayerTraversalMotionProfile
                {
                    RequiredPose = episode.RequiredPose,
                    ApproachDirection = episode.Direction,
                    ApproachSpeed = directDistance / Mathf.Max(0.10f, episode.LastUpdatedAt - episode.StartedAt),
                    ApproachMode = string.IsNullOrWhiteSpace(episode.MovementMode) ? "Run" : episode.MovementMode,
                    TraversalDuration = Mathf.Max(0.10f, episode.LastUpdatedAt - episode.StartedAt)
                },
                episode.CorridorSamples);
            if (edgeId <= 0)
            {
                return;
            }

            LearnedTraversalEdge learnedEpisodeEdge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == edgeId);
            if (learnedEpisodeEdge != null)
            {
                bool preserveVerifiedGeometry = learnedEpisodeEdge.Verified &&
                    learnedEpisodeEdge.SuccessfulExecutions >= WalkThroughVerifiedGeometryFreezeSuccesses &&
                    learnedEpisodeEdge.WalkThroughCorridorSamples != null &&
                    learnedEpisodeEdge.WalkThroughCorridorSamples.Count >= 2;
                if (!preserveVerifiedGeometry)
                {
                    learnedEpisodeEdge.WalkThroughCorridorSamples = episode.CorridorSamples != null
                        ? episode.CorridorSamples.Where(IsFinite).ToList()
                        : new List<Vector3>();
                    if (episode.HasSettledExit && IsFinite(episode.SettledExit) &&
                        IsCredibleWalkThroughTerminalConnector(
                            learnedEpisodeEdge.RawStart,
                            learnedEpisodeEdge.RawEnd,
                            episode.SettledExit,
                            learnedEpisodeEdge.WalkThroughCorridorSamples))
                    {
                        learnedEpisodeEdge.HasSettledEnd = true;
                        learnedEpisodeEdge.SettledEnd = episode.SettledExit;
                        learnedEpisodeEdge.SettledBreadcrumbSequence = episode.SettledExitSequence;
                    }
                    else if (episode.HasSettledExit && IsFinite(episode.SettledExit))
                    {
                        learnedEpisodeEdge.HasSettledEnd = false;
                        learnedEpisodeEdge.SettledEnd = default(Vector3);
                        learnedEpisodeEdge.SettledBreadcrumbSequence = 0;
                        WriteEvent("walkThroughSettledExitRejected", null, new
                        {
                            edgeId,
                            episodeId = episode.EpisodeId,
                            rawExit = Vec(learnedEpisodeEdge.RawEnd),
                            settledExit = Vec(episode.SettledExit),
                            reason = "recordedTerminalConnectorInvalid"
                        });
                    }
                }
                else
                {
                    WriteEvent("walkThroughCandidateGeometryNotApplied", null, new
                    {
                        episodeId = episode.EpisodeId,
                        edgeId,
                        reason = "verifiedDirectionalGeometryFrozen",
                        candidatePointCount = episode.CorridorSamples?.Count ?? 0,
                        storedPointCount = learnedEpisodeEdge.WalkThroughCorridorSamples.Count
                    });
                }
                SavePersistentTraversalLinks();
            }

            var finalizedEpisode=RegisterTraversalEpisodeForEdge(
                edgeId,
                "WalkThrough",
                episode.RawStart,
                episode.RawEnd,
                episode.StartSequence,
                episode.EndSequence,
                true,
                episode.EpisodeId);
            ApplyLearningV372CurrentEpisodeWalkThroughExecutionGeometry(null,finalizedEpisode,learnedEpisodeEdge,
                episode.RawStart,episode.RawEnd,"finalizedPlayerWalkThroughRecordedLane");
            WriteEvent("playerWalkThroughEpisodeLearned", null, new
            {
                episodeId = episode.EpisodeId,
                edgeId,
                reason,
                posture = FollowerCapabilityPosturePolicy.Crouched(episode.RequiredPose)?"Crouch":"Standing",
                requiredPose = episode.RequiredPose,
                startSequence = episode.StartSequence,
                endSequence = episode.EndSequence,
                start = Vec(episode.RawStart),
                end = Vec(episode.RawEnd),
                directDistance
            });
        }

        private static bool IsLearningV369OrdinaryNavMeshRouteWindow(
            IList<PlayerBreadcrumbNode> samples,
            StrictPathResult strictPath)
        {
            if(samples!=null&&samples.Any(n=>n!=null&&FollowerCapabilityPosturePolicy.Crouched(n.Pose)))return false;
            if ((samples == null) || samples.Count < 2 ||
                strictPath == null || !strictPath.StrictComplete ||
                samples.Any(node => node == null || !node.NavMeshSampled || !IsFinite(node.NavMeshPosition)))
            {
                return false;
            }

            Vector3 start = samples[0].Position;
            Vector3 end = samples[samples.Count - 1].Position;
            if (!IsFinite(start) || !IsFinite(end))
            {
                return false;
            }
            float direct = Vector3.Distance(start, end);
            return strictPath.PathLength <= GetAllowedFollowPathLength(direct, true);
        }

        // RC61: IsLearningV369PhysicalCorridorStep extracted unchanged to FollowerTraversalPhysicalCorridorPolicy.cs.

        private static bool TryGetLearningV381ProvenPortalActuatorStrategy(
            LearnedTraversalEdge physicalEdge,
            FollowerRouteMissionStep physicalStep,
            out LearnedTraversalEdge actuatorEdge,
            out bool forward,
            out float matchScore,
            out string matchSource)
        {
            actuatorEdge = null;
            forward = true;
            matchScore = float.MaxValue;
            matchSource = string.Empty;
            if ((physicalEdge == null) || physicalStep == null ||
                ((physicalStep.LearningV383PhysicalContinuationOnly) &&
                 false))
            {
                return false;
            }

            LearnedTraversalEdge provenanceParent = physicalEdge.RuntimeAlternativeParentEdgeId > 0
                ? LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == physicalEdge.RuntimeAlternativeParentEdgeId)
                : null;
            Vector3 provenanceStart = provenanceParent != null
                ? (IsFinite(provenanceParent.RawStart) ? provenanceParent.RawStart : provenanceParent.A)
                : default(Vector3);
            Vector3 provenanceEnd = provenanceParent != null
                ? (IsFinite(provenanceParent.RawEnd) ? provenanceParent.RawEnd : provenanceParent.B)
                : default(Vector3);

            foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges)
            {
                if (candidate == null || candidate.Disabled || candidate.SyntheticPhysicalCorridor ||
                    !IsLearningV3NativeProvenEdge(candidate) ||
                    (!string.Equals(candidate.Kind, "Vault", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(candidate.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(candidate.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                LearningV354TraversalCapabilityProfile profile =
                    GetLearningV354ActionProfile(GetLearningV354SemanticKind(candidate.Id, candidate.Kind));
                if (profile == null || !profile.RequiresActuator)
                {
                    continue;
                }

                Vector3 candidateStart = IsFinite(candidate.RawStart) ? candidate.RawStart : candidate.A;
                Vector3 candidateEnd = IsFinite(candidate.RawEnd) ? candidate.RawEnd : candidate.B;
                bool observedEquivalent = AreCrossKindTraversalEndpointsEquivalent(
                    physicalStep.RawEntry, physicalStep.RawExit,
                    candidateStart, candidateEnd,
                    out bool observedReversed, out float observedScore);
                float provenanceScore = float.MaxValue;
                bool provenanceEquivalent = provenanceParent != null &&
                    AreCrossKindTraversalEndpointsEquivalent(
                        provenanceStart, provenanceEnd,
                        candidateStart, candidateEnd,
                        out _, out provenanceScore);
                if (!observedEquivalent && !provenanceEquivalent)
                {
                    continue;
                }

                // Portal identity can come from either the observed physical passage or an older
                // proven sibling, but execution direction always follows the current physical
                // passage. This keeps provenance from becoming a stale directional authority.
                bool candidateForward = observedEquivalent
                    ? !observedReversed
                    : GetPlanarDistance(physicalStep.RawEntry, candidateStart) <=
                      GetPlanarDistance(physicalStep.RawEntry, candidateEnd);
                Vector3 candidateEntry = candidateForward ? candidate.A : candidate.B;
                Vector3 candidateExit = candidateForward ? candidate.B : candidate.A;
                if (!IsTraversalOrientationAllowed(candidate, candidateEntry, candidateExit))
                {
                    continue;
                }

                float directionScore =
                    Vector3.Distance(physicalStep.RawEntry, candidateForward ? candidateStart : candidateEnd) +
                    Vector3.Distance(physicalStep.RawExit, candidateForward ? candidateEnd : candidateStart);
                float identityScore = observedEquivalent ? observedScore : provenanceScore;
                float candidateScore = directionScore + identityScore;
                if (candidateScore >= matchScore)
                {
                    continue;
                }

                actuatorEdge = candidate;
                forward = candidateForward;
                matchScore = candidateScore;
                matchSource = observedEquivalent
                    ? "currentPhysicalPassage"
                    : "portalProvenSiblingGeometry";
            }

            return actuatorEdge != null;
        }

        private static bool TryGetLearningV386ProvenSiblingActuatorStrategy(
            FollowerRouteMissionStep authoredStep,
            out LearnedTraversalEdge actuatorEdge,
            out bool forward,
            out float matchScore)
        {
            actuatorEdge = null;
            forward = true;
            matchScore = float.MaxValue;
            if ((authoredStep == null) ||
                !IsFinite(authoredStep.RawEntry) || !IsFinite(authoredStep.RawExit) ||
                (!string.Equals(authoredStep.Kind, "Vault", StringComparison.OrdinalIgnoreCase) &&
                 !string.Equals(authoredStep.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                 !string.Equals(authoredStep.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
            {
                return false;
            }

            LearningV354TraversalCapabilityProfile authoredProfile =
                GetLearningV354ActionProfile(GetLearningV354SemanticKind(authoredStep.EdgeId, authoredStep.Kind));
            if (authoredProfile == null || !authoredProfile.RequiresActuator)
            {
                return false;
            }

            foreach (LearnedTraversalEdge candidate in LearnedTraversalEdges)
            {
                if (candidate == null || candidate.Id == authoredStep.EdgeId || candidate.Disabled ||
                    candidate.SyntheticPhysicalCorridor || !IsLearningV3NativeProvenEdge(candidate) ||
                    string.Equals(candidate.Kind, authoredStep.Kind, StringComparison.OrdinalIgnoreCase) ||
                    (!string.Equals(candidate.Kind, "Vault", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(candidate.Kind, "Climb", StringComparison.OrdinalIgnoreCase) &&
                     !string.Equals(candidate.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                LearningV354TraversalCapabilityProfile candidateProfile =
                    GetLearningV354ActionProfile(GetLearningV354SemanticKind(candidate.Id, candidate.Kind));
                if (candidateProfile == null || !candidateProfile.RequiresActuator)
                {
                    continue;
                }

                Vector3 candidateStart = IsFinite(candidate.RawStart) ? candidate.RawStart : candidate.A;
                Vector3 candidateEnd = IsFinite(candidate.RawEnd) ? candidate.RawEnd : candidate.B;
                if (!AreCrossKindTraversalEndpointsEquivalent(
                        authoredStep.RawEntry, authoredStep.RawExit, candidateStart, candidateEnd,
                        out bool reversed, out float endpointScore))
                {
                    continue;
                }

                bool candidateForward = !reversed;
                Vector3 candidateEntry = candidateForward ? candidate.A : candidate.B;
                Vector3 candidateExit = candidateForward ? candidate.B : candidate.A;
                if (!IsTraversalOrientationAllowed(candidate, candidateEntry, candidateExit))
                {
                    continue;
                }

                // CF55: endpoint similarity is NOT a physical actuator equivalence proof.
                // On CF54 Mission 251, an authored +1.26m Climb was replaced by a
                // +0.16m Vault before Climb was attempted, then both the substitute
                // and its DropDown successor needed TeleportFallback. Permit cross-kind
                // sibling rescue only if the SIGNED vertical displacement is compatible.
                // Post-failure actuator strategies are unchanged.
                float cf55AuthoredElevation = authoredStep.RawExit.y - authoredStep.RawEntry.y;
                float cf55SiblingElevation = (candidateForward ? candidateEnd.y - candidateStart.y
                                                                : candidateStart.y - candidateEnd.y);
                if (Mathf.Abs(cf55AuthoredElevation - cf55SiblingElevation) >
                    UnifiedTraversalVerifyMaxNavVertical)
                {
                    // Rejection is diagnosis only. Never mutate learned sibling competence.
                    continue;
                }

                float directionScore =
                    Vector3.Distance(authoredStep.RawEntry, candidateForward ? candidateStart : candidateEnd) +
                    Vector3.Distance(authoredStep.RawExit, candidateForward ? candidateEnd : candidateStart);
                float score = endpointScore + directionScore;
                if (score >= matchScore)
                {
                    continue;
                }

                actuatorEdge = candidate;
                forward = candidateForward;
                matchScore = score;
            }
            return actuatorEdge != null;
        }

        private static void BindLearningV387AdoptedActuatorStrategy(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep actuatorStep,
            string source)
        {
            if ((bot == null) ||
                mission == null || actuatorStep == null ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count ||
                !ReferenceEquals(mission.Steps[mission.CurrentStepIndex], actuatorStep) ||
                HasActiveTraversalProbe(bot))
            {
                return;
            }

            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;
            bool commitmentBound = EnsureFollowerRouteMissionCommitment(bot, mission);
            string dispatchResult = commitmentBound ? "readinessPending" : "commitmentUnavailable";
            bool dispatched = commitmentBound &&
                TryDispatchLearningV378PersistentActuatorFrontierProbe(
                    bot, mission, actuatorStep.EdgeId, actuatorStep.Kind, out dispatchResult);
            WriteEvent("learningV387AdoptedActuatorStrategyBoundToExecutionPipeline", bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                edgeId = actuatorStep.EdgeId,
                kind = actuatorStep.Kind,
                source = source ?? string.Empty,
                commitmentBound,
                dispatched,
                dispatchResult = dispatchResult ?? string.Empty,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = dispatched
                    ? "adoptedProvenActuatorImmediatelyEnteredExistingProbePipeline"
                    : "adoptedProvenActuatorRetainsExactCommitmentUntilExistingReadinessContractAllowsDispatch"
            });
        }

        private static bool TryAdoptLearningV386ProvenSiblingActuatorStrategy(
            BotOwner bot, FollowerRouteMission mission, FollowerRouteMissionStep authoredStep)
        {
            if ((bot == null) || mission == null ||
                authoredStep == null || HasActiveTraversalProbe(bot) ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count ||
                !ReferenceEquals(mission.Steps[mission.CurrentStepIndex], authoredStep) ||
                authoredStep.AttemptStartedObserved)
            {
                return false;
            }

            // V4.36: V386 is a legacy PRE-probe cross-kind rescue. It must not replace an authored
            // Jump merely because staging has not yet produced the reservation; V433/V434 already
            // provide the bounded cross-kind substitute AFTER the original physical actuator has
            // actually failed. The V435 final-chain regression proved this ordering matters: Jump 79
            // lost momentum during pre-entry, then V386 rewrote the current RouteMission step to
            // Native-Proven Climb 18 before Jump had any attempt lifecycle at all.
            if ((string.Equals(authoredStep.Kind, "Jump", StringComparison.OrdinalIgnoreCase)))
            {
                if (ShouldEmitDiagnostic(
                        "learningV436JumpSiblingRescueDeferredUntilOriginalAttempt:" +
                            authoredStep.EdgeId.ToString(CultureInfo.InvariantCulture),
                        bot, 0.35f))
                {
                    WriteEvent("learningV436JumpSiblingRescueDeferredUntilOriginalAttempt", bot, new
                    {
                        missionId = mission.MissionId,
                        stepIndex = mission.CurrentStepIndex,
                        edgeId = authoredStep.EdgeId,
                        kind = authoredStep.Kind,
                        attemptStartedObserved = authoredStep.AttemptStartedObserved,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false,
                        action = "originalJumpAdmissionPrecedesLegacyPreProbeSiblingRescueV433V434RemainPostFailureFallback"
                    });
                }
                return false;
            }

            int maxFallbacks = Math.Max(1, LearningV32EntryMaxReacquireAttempts);
            if (authoredStep.LearningV384ActuatorFallbackAttempts > maxFallbacks ||
                !TryGetLearningV386ProvenSiblingActuatorStrategy(
                    authoredStep, out LearnedTraversalEdge sibling, out bool forward, out float matchScore))
            {
                return false;
            }

            Vector3 siblingRawStart = IsFinite(sibling.RawStart) ? sibling.RawStart : sibling.A;
            Vector3 siblingRawEnd = IsFinite(sibling.RawEnd) ? sibling.RawEnd : sibling.B;
            FollowerRouteMissionStep strategy = new FollowerRouteMissionStep
            {
                EpisodeId = authoredStep.EpisodeId,
                EdgeId = sibling.Id,
                Kind = sibling.Kind,
                StartBreadcrumbSequence = authoredStep.StartBreadcrumbSequence,
                EndBreadcrumbSequence = authoredStep.EndBreadcrumbSequence,
                Entry = forward ? sibling.A : sibling.B,
                Exit = forward ? sibling.B : sibling.A,
                RawEntry = forward ? siblingRawStart : siblingRawEnd,
                RawExit = forward ? siblingRawEnd : siblingRawStart,
                ChainId = authoredStep.ChainId,
                ChainLocalExecutable = true,
                CurrentRaidRouteAuthority = true,
                AttemptStartedObserved = false,
                AttemptStartedAt = 0f,
                LearningV384ActuatorFallbackArmed = false,
                LearningV384ActuatorFallbackAttempts = authoredStep.LearningV384ActuatorFallbackAttempts + 1,
                LearningV386SemanticSourceEdgeId = authoredStep.EdgeId,
                LearningV386SemanticSourceKind = authoredStep.Kind,
                LearningV386SiblingActuatorStrategy = true,
                CreatedAt = authoredStep.CreatedAt
            };
            if (!ReplaceLifecycleMissionStep(mission,mission.CurrentStepIndex,strategy)) return false;
            CommitCapabilityMoveRetry(mission,FollowerCapabilityRetryPolicy.Change.Reset,0f);
            mission.TraversalRetryMovementHoldUntil = 0f;
            LearnedTraversalCommitments.Remove(bot.ProfileId ?? string.Empty);
            ClearLearningV365ContinuousPhysicalRoute(bot, "learningV386ActuatorFrontierSiblingSelfRescue");
            BindLearningV387AdoptedActuatorStrategy(
                bot, mission, strategy, "learningV386ActuatorFrontierSiblingSelfRescue");
            WriteEvent("learningV386ActuatorFrontierSiblingSelfRescueSelected", bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                episodeId = authoredStep.EpisodeId,
                authoredEdgeId = authoredStep.EdgeId,
                authoredKind = authoredStep.Kind,
                siblingEdgeId = sibling.Id,
                siblingKind = sibling.Kind,
                forward,
                portalMatchScore = matchScore,
                siblingNativeSuccessCount = sibling.NativeSuccessCount,
                fallbackAttempt = strategy.LearningV384ActuatorFallbackAttempts,
                persistentLearningChanged = false,
                traversalSuccessRecorded = false,
                action = "preProbeActuatorFrontierStallBorrowsNativeProvenCrossKindSiblingOnSamePortal"
            });
            return true;
        }

        private static bool TryAdoptLearningV381ProvenPortalActuatorStrategy(
            BotOwner bot,
            FollowerRouteMission mission,
            FollowerRouteMissionStep physicalStep)
        {
            if ((bot == null) || mission == null ||
                physicalStep == null || !IsLearningV369PhysicalCorridorStep(physicalStep) ||
                ((!physicalStep.LearningV384ActuatorFallbackArmed)) ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count ||
                !ReferenceEquals(mission.Steps[mission.CurrentStepIndex], physicalStep) ||
                HasActiveTraversalProbe(bot))
            {
                return false;
            }

            LearnedTraversalEdge physicalEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == physicalStep.EdgeId);
            if (physicalEdge == null || !physicalEdge.SyntheticPhysicalCorridor ||
                !physicalEdge.RuntimeOnlyTraversal)
            {
                return false;
            }

            if (!TryGetLearningV381ProvenPortalActuatorStrategy(
                    physicalEdge, physicalStep,
                    out LearnedTraversalEdge parent,
                    out bool forward,
                    out float portalMatchScore,
                    out string portalMatchSource))
            {
                return false;
            }

            Vector3 parentRawStart = IsFinite(parent.RawStart) ? parent.RawStart : parent.A;
            Vector3 parentRawEnd = IsFinite(parent.RawEnd) ? parent.RawEnd : parent.B;
            Vector3 parentEntry = forward ? parent.A : parent.B;
            Vector3 parentExit = forward ? parent.B : parent.A;
            Vector3 parentExecutionRawEntry = forward ? parentRawStart : parentRawEnd;
            Vector3 parentExecutionRawExit = forward ? parentRawEnd : parentRawStart;

            FollowerRouteMissionStep actuatorStep = new FollowerRouteMissionStep
            {
                EpisodeId = physicalStep.EpisodeId,
                EdgeId = parent.Id,
                Kind = parent.Kind,
                StartBreadcrumbSequence = physicalStep.StartBreadcrumbSequence,
                EndBreadcrumbSequence = physicalStep.EndBreadcrumbSequence,
                Entry = parentEntry,
                Exit = parentExit,
                RawEntry = parentExecutionRawEntry,
                RawExit = parentExecutionRawExit,
                ChainId = physicalStep.ChainId,
                ChainLocalExecutable = true,
                CurrentRaidRouteAuthority = true,
                AttemptStartedObserved = false,
                AttemptStartedAt = 0f,
                LearningV382TransientNativeSkillInstance =
                    (!forward),
                LearningV382SkillTemplateEdgeId =
                    (!forward) ? parent.Id : 0,
                LearningV382SkillTransferSource =
                    (!forward)
                        ? "learningV382ReversePortalNativeSkillInstance"
                        : null,
                LearningV383PortalPhysicalSourceEdgeId = physicalStep.EdgeId,
                LearningV383PortalPhysicalEntry = physicalStep.Entry,
                LearningV383PortalPhysicalExit = physicalStep.Exit,
                LearningV383PortalPhysicalRawEntry = physicalStep.RawEntry,
                LearningV383PortalPhysicalRawExit = physicalStep.RawExit,
                LearningV384ActuatorFallbackArmed = false,
                LearningV384ActuatorFallbackAttempts = physicalStep.LearningV384ActuatorFallbackAttempts + 1,
                CreatedAt = physicalStep.CreatedAt
            };
            if (!ReplaceLifecycleMissionStep(mission,mission.CurrentStepIndex,actuatorStep)) return false;
            LearnedTraversalCommitments.Remove(bot.ProfileId ?? string.Empty);
            ClearLearningV365ContinuousPhysicalRoute(bot, "learningV381ProvenPortalActuatorStrategy");
            BindLearningV387AdoptedActuatorStrategy(
                bot, mission, actuatorStep, "learningV381ProvenPortalActuatorStrategy");
            WriteEvent("learningV381PhysicalCorridorAdoptedProvenActuatorStrategy", bot, new
            {
                missionId = mission.MissionId,
                stepIndex = mission.CurrentStepIndex,
                episodeId = physicalStep.EpisodeId,
                physicalEdgeId = physicalStep.EdgeId,
                provenanceParentEdgeId = physicalEdge.RuntimeAlternativeParentEdgeId,
                actuatorEdgeId = parent.Id,
                actuatorKind = parent.Kind,
                forward,
                portalMatchScore,
                portalMatchSource,
                approachMode = physicalEdge.ApproachMode ?? string.Empty,
                approachSpeed = physicalEdge.ApproachSpeed,
                nativeSuccessCount = parent.NativeSuccessCount,
                locomotionFirstSelfRescue = true,
                actuatorFallbackAttempt = actuatorStep.LearningV384ActuatorFallbackAttempts,
                transientNativeSkillInstance = actuatorStep.LearningV382TransientNativeSkillInstance,
                skillTemplateEdgeId = actuatorStep.LearningV382SkillTemplateEdgeId,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                action = "portalAffordanceKeepsPhysicalSemanticIdentityWhileBestNativeProvenSiblingSuppliesExecutionStrategy"
            });
            return true;
        }

        private static void EmitLearningV341PreEpisodeSemanticGapCandidate(
            int edgeId,
            string kind,
            int startBreadcrumbSequence)
        {
            if ((startBreadcrumbSequence <= 0) || BreadcrumbRoute.Count < 2)
            {
                return;
            }
            float windowStartAt = Time.time - TraversalChainMaxEpisodeGapSeconds;
            List<PlayerBreadcrumbNode> window = BreadcrumbRoute
                .Where(node => node != null && node.Sequence < startBreadcrumbSequence &&
                               node.CreatedAt >= windowStartAt && IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            if (window.Count < 2)
            {
                return;
            }
            int firstSequence = window[0].Sequence;
            int lastSequence = window[window.Count - 1].Sequence;
            bool coveredByRegisteredEpisode = TraversalEpisodeStream.Any(item => item != null &&
                item.StartBreadcrumbSequence <= lastSequence && item.EndBreadcrumbSequence >= firstSequence);
            if (coveredByRegisteredEpisode)
            {
                return;
            }

            {
                PlayerBreadcrumbNode learningV417ActuatorStart = BreadcrumbRoute
                    .Where(node => node != null && node.Sequence == startBreadcrumbSequence && IsFinite(node.Position))
                    .FirstOrDefault();
                LearnedTraversalEdge learningV417NextEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == edgeId);
                Vector3 learningV417ActuatorStartPosition = learningV417ActuatorStart != null
                    ? learningV417ActuatorStart.Position
                    : (learningV417NextEdge != null && IsFinite(learningV417NextEdge.RawStart)
                        ? learningV417NextEdge.RawStart
                        : default(Vector3));
                bool learningV417HaveActuatorStart = learningV417ActuatorStart != null ||
                    (learningV417NextEdge != null && IsFinite(learningV417NextEdge.RawStart));
                int learningV417ExcludedBoundaryStates = 0;

                // The breadcrumb immediately before a registered actuator can already report
                // ClimbOver/ClimbUp/etc. at the actuator entry position. That sample belongs to the
                // NEXT actuator's state transition, not to the physical route that led to it. Strip
                // only trailing traversal-state samples co-located with that start; any earlier
                // off-NavMesh/airborne/path-incomplete evidence remains and can still form a real
                // PhysicalCorridor. Existing BreadcrumbMinDistance and V2 vertical tolerance are
                // reused so this introduces no new geometry threshold.
                while (learningV417HaveActuatorStart && window.Count >= 2)
                {
                    PlayerBreadcrumbNode learningV417Last = window[window.Count - 1];
                    if (!IsTraversalStateName(learningV417Last.State) ||
                        GetPlanarDistance(learningV417Last.Position, learningV417ActuatorStartPosition) > BreadcrumbMinDistance ||
                        Mathf.Abs(learningV417Last.Position.y - learningV417ActuatorStartPosition.y) >
                            LearningV2RevisionVerticalTolerance)
                    {
                        break;
                    }
                    window.RemoveAt(window.Count - 1);
                    learningV417ExcludedBoundaryStates++;
                }

                if (learningV417ExcludedBoundaryStates > 0)
                {
                    WriteEvent("learningV417ActuatorBoundaryStateExcludedFromPreEpisodeDebt", null, new
                    {
                        edgeId,
                        nextRegisteredKind = string.IsNullOrWhiteSpace(kind) ? "Unknown" : kind,
                        startBreadcrumbSequence,
                        excludedBoundaryStates = learningV417ExcludedBoundaryStates,
                        remainingSampleCount = window.Count,
                        actuatorStart = Vec(learningV417ActuatorStartPosition),
                        persistentLearningChanged = false,
                        traversalSuccessRecorded = false,
                        action = "nextActuatorBoundaryStateCannotCreatePreActuatorExecutionDebt"
                    });
                }
            }

            if (window.Count < 2)
            {
                return;
            }

            firstSequence = window[0].Sequence;
            lastSequence = window[window.Count - 1].Sequence;
            float minY = window.Min(node => node.Position.y);
            float maxY = window.Max(node => node.Position.y);
            int airborneSamples = window.Count(node => !node.Grounded);
            int traversalStateSamples = window.Count(node => IsTraversalStateName(node.State));
            int unsampledNavSamples = window.Count(node => !node.NavMeshSampled);
            StrictPathResult windowPath = CalculateStrictPath(window[0].Position, window[window.Count - 1].Position);
            bool learningV387OrdinaryNavMeshWindow =
                IsLearningV369OrdinaryNavMeshRouteWindow(window, windowPath);
            LearningV354TraversalCapabilityProfile learningV387NextProfile =
                GetLearningV354ActionProfile(kind);
            bool learningV387ContinuitySensitivePreActuatorWindow =
                (learningV387NextProfile != null) && learningV387NextProfile.RequiresActuator &&
                (traversalStateSamples > 0 || airborneSamples > 0 ||
                 maxY - minY > LearningV2RevisionVerticalTolerance);
            if (learningV387OrdinaryNavMeshWindow &&
                !learningV387ContinuitySensitivePreActuatorWindow)
            {
                WriteEvent("learningV369OrdinaryNavMeshGapNotPromotedToPhysicalCorridor", null, new
                {
                    edgeId,
                    nextRegisteredKind = string.IsNullOrWhiteSpace(kind) ? "Unknown" : kind,
                    firstBreadcrumbSequence = firstSequence,
                    lastBreadcrumbSequence = lastSequence,
                    sampleCount = window.Count,
                    airborneSamples,
                    verticalSpan = maxY - minY,
                    strictPathLength = windowPath.PathLength,
                    persistentLearningChanged = false,
                    action = "healthyContinuousNavMeshRemainsNormalLocomotionEvenWithAirborneOrSlopeSamples"
                });
                return;
            }
            if (learningV387OrdinaryNavMeshWindow &&
                learningV387ContinuitySensitivePreActuatorWindow)
            {
                WriteEvent("learningV387OrdinaryNavMeshPreActuatorContinuityPreserved", null, new
                {
                    edgeId,
                    nextRegisteredKind = string.IsNullOrWhiteSpace(kind) ? "Unknown" : kind,
                    firstBreadcrumbSequence = firstSequence,
                    lastBreadcrumbSequence = lastSequence,
                    sampleCount = window.Count,
                    airborneSamples,
                    traversalStateSamples,
                    verticalSpan = maxY - minY,
                    strictPathLength = windowPath.PathLength,
                    persistentLearningChanged = false,
                    traversalSuccessRecorded = false,
                    action = "healthyNavMeshDoesNotEraseContinuitySensitiveRuntimePhysicalRouteBeforeActuator"
                });
            }
            bool suspicious = traversalStateSamples > 0 || airborneSamples > 0 || unsampledNavSamples > 0 ||
                              maxY - minY > LearningV2RevisionVerticalTolerance ||
                              (windowPath != null && windowPath.CalculateReturned && !windowPath.StrictComplete);
            if (!suspicious)
            {
                return;
            }

            int syntheticPhysicalCorridorEdgeId = 0;
            int syntheticPhysicalCorridorEpisodeId = 0;
            {
                Vector3 gapStart = window[0].Position;
                Vector3 gapEnd = window[window.Count - 1].Position;
                float gapDistance = GetPlanarDistance(gapStart, gapEnd);
                if (gapDistance >= 0.35f)
                {
                    LearnedTraversalEdge synthetic = new LearnedTraversalEdge
                    {
                        Id = ++learnedTraversalEdgeSequence,
                        ExperienceKey = null,
                        DemonstrationRevision = 1,
                        Kind = ("PhysicalCorridor"),
                        // Runtime-only physical continuity is now a first-class route semantic. The
                        // legacy WalkThrough executor alias is retained only behind the disabled flag.
                        A = gapStart, B = gapEnd, RawStart = gapStart, RawEnd = gapEnd,
                        CreatedAt = Time.time, PlayerValidated = true, Verified = false, Disabled = false,
                        SyntheticPhysicalCorridor = true, RuntimeSemanticKind = "PhysicalCorridor",
                        ApproachDirection = GetFlatDirection(gapEnd - gapStart),
                        ApproachSpeed = GetLearningV381PhysicalCorridorApproachSpeed(window),
                        ApproachMode = GetLearningV381PhysicalCorridorApproachMode(window),
                        WalkThroughCorridorSamples = window.Select(node => node.Position).Where(IsFinite).ToList(),
                        EgressSamples = new List<Vector3>()
                    };
                    LearnedTraversalEdges.Add(synthetic);
                    TrimLearnedTraversalEdgesToLimit();
                    syntheticPhysicalCorridorEdgeId = synthetic.Id;
                    TraversalEpisodeMetadata corridorEpisode = RegisterTraversalEpisodeForEdge(
                        synthetic.Id,
                        ("PhysicalCorridor"),
                        gapStart, gapEnd, firstSequence, lastSequence, true, 0, skipPreGapEmission: true);
                    syntheticPhysicalCorridorEpisodeId = corridorEpisode?.EpisodeId ?? 0;
                    WriteEvent("learningV354AnonymousPhysicalCorridorCaptured", null, new
                    {
                        edgeId = syntheticPhysicalCorridorEdgeId, episodeId = syntheticPhysicalCorridorEpisodeId,
                        semanticKind = "PhysicalCorridor",
                        executorKind = ("PhysicalCorridor"),
                        start = Vec(gapStart), end = Vec(gapEnd), gapDistance, verticalSpan = maxY - minY,
                        approachSpeed = synthetic.ApproachSpeed,
                        approachMode = synthetic.ApproachMode,
                        persistent = false, action = "preservePhysicalRouteContinuityWithoutGuessingTraversalActuatorOrLocomotionEnvelope"
                    });
                }
            }

            WriteEvent("learningV341MissingTraversalEpisodeCandidate", null, new
            {
                edgeId,
                nextRegisteredKind = string.IsNullOrWhiteSpace(kind) ? "Unknown" : kind,
                firstBreadcrumbSequence = firstSequence,
                lastBreadcrumbSequence = lastSequence,
                nextStartBreadcrumbSequence = startBreadcrumbSequence,
                start = Vec(window[0].Position),
                end = Vec(window[window.Count - 1].Position),
                verticalSpan = maxY - minY,
                airborneSamples,
                traversalStateSamples,
                unsampledNavSamples,
                strictPath = windowPath?.ToPayload(),
                classification = "UnknownMissingTraversalSemantic",
                syntheticPhysicalCorridorEdgeId,
                syntheticPhysicalCorridorEpisodeId,
                action = syntheticPhysicalCorridorEdgeId > 0
                    ? "preserveAsRuntimePhysicalCorridorDoNotGuessActuator"
                    : "retainTelemetryDoNotGuessKind"
            });
        }

        private static void EmitLearningV341RegisteredEpisodeSemanticAmbiguity(TraversalEpisodeMetadata metadata)
        {
            if ((metadata == null) || metadata.ChainId <= 0 ||
                !string.Equals(metadata.Kind, "DropDown", StringComparison.OrdinalIgnoreCase) ||
                metadata.StartBreadcrumbSequence <= 0 || metadata.EndBreadcrumbSequence <= metadata.StartBreadcrumbSequence)
            {
                return;
            }

            TraversalEpisodeMetadata predecessor = TraversalEpisodeStream
                .Where(item => item != null && item.ChainId == metadata.ChainId && item.EpisodeId < metadata.EpisodeId)
                .OrderByDescending(item => item.EpisodeId)
                .FirstOrDefault();
            if (predecessor == null || !string.Equals(predecessor.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            List<PlayerBreadcrumbNode> window = BreadcrumbRoute
                .Where(node => node != null && node.Sequence >= metadata.StartBreadcrumbSequence &&
                               node.Sequence <= metadata.EndBreadcrumbSequence && IsFinite(node.Position))
                .OrderBy(node => node.Sequence)
                .ToList();
            if (window.Count < 2)
            {
                return;
            }
            int airborneSamples = window.Count(node => !node.Grounded);
            int unsampledNavSamples = window.Count(node => !node.NavMeshSampled);
            int traversalStateSamples = window.Count(node => IsTraversalStateName(node.State));
            float horizontalDistance = GetPlanarDistance(window[0].Position, window[window.Count - 1].Position);
            if (airborneSamples <= 0 || unsampledNavSamples <= 0 ||
                horizontalDistance <= RouteMissionBreadcrumbReachDistance)
            {
                return;
            }

            Vector3 direction = GetFlatDirection(metadata.RawEnd - metadata.RawStart);
            TraversalObstacleFingerprint obstacle = observedLocalPlayer != null
                ? TryCaptureTraversalObstacleFingerprint(observedLocalPlayer, metadata.RawStart, direction)
                : null;
            StrictPathResult strictPath = CalculateStrictPath(metadata.RawStart, metadata.RawEnd);
            WriteEvent("learningV341TraversalSemanticAmbiguity", null, new
            {
                previousEdgeId = predecessor.EdgeId,
                previousKind = predecessor.Kind,
                edgeId = metadata.EdgeId,
                registeredKind = metadata.Kind,
                episodeId = metadata.EpisodeId,
                chainId = metadata.ChainId,
                startBreadcrumbSequence = metadata.StartBreadcrumbSequence,
                endBreadcrumbSequence = metadata.EndBreadcrumbSequence,
                start = Vec(metadata.RawStart),
                end = Vec(metadata.RawEnd),
                horizontalDistance,
                verticalDelta = metadata.RawEnd.y - metadata.RawStart.y,
                airborneSamples,
                traversalStateSamples,
                unsampledNavSamples,
                states = window.Select(node => node.State ?? string.Empty).Distinct().ToArray(),
                strictPath = strictPath?.ToPayload(),
                obstacle = obstacle == null ? null : new
                {
                    name = obstacle.Name,
                    layer = obstacle.Layer,
                    center = Vec(obstacle.BoundsCenter),
                    size = Vec(obstacle.BoundsSize)
                },
                classification = traversalStateSamples > 0
                    ? "RegisteredDropDownContainsExplicitTraversalStateEvidence"
                    : "UnknownDropDownOrMissingTraversalSemantic",
                action = "retainTelemetryDoNotGuessVaultOrDropDown"
            });
        }

        private static TraversalEpisodeMetadata RegisterTraversalEpisodeForEdge(
            int edgeId,
            string kind,
            Vector3 rawStart,
            Vector3 rawEnd,
            int startBreadcrumbSequence,
            int endBreadcrumbSequence,
            bool allowChain = true,
            int preferredEpisodeId = 0,
            bool skipPreGapEmission = false)
        {
            if (edgeId <= 0 || !IsFinite(rawStart) || !IsFinite(rawEnd))
            {
                return null;
            }

            if (!skipPreGapEmission)
            {
                EmitLearningV341PreEpisodeSemanticGapCandidate(edgeId, kind, startBreadcrumbSequence);
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == edgeId);
            if(edge==null)
            {
                WriteEvent("capabilityEpisodeDefinitionUnavailable",null,new{edgeId,kind,
                    startBreadcrumbSequence,endBreadcrumbSequence,stage="recordEpisode",reason="edgeMissingBeforeEpisodePublication",
                    nativeSuccessRecorded=false});
                return null;
            }

            int episodeId = preferredEpisodeId > 0 ? preferredEpisodeId : ++traversalEpisodeSequence;
            traversalEpisodeSequence = Math.Max(traversalEpisodeSequence, episodeId);
            int chainId = ++traversalChainSequence;
            if (allowChain && lastPlayerTraversalEpisode != null)
            {
                float timeGap = Mathf.Max(0f, Time.time - lastPlayerTraversalEpisode.CreatedAt);
                float spatialGap = Vector3.Distance(lastPlayerTraversalEpisode.RawEnd, rawStart);
                if (timeGap <= TraversalChainMaxEpisodeGapSeconds && spatialGap <= TraversalChainMaxSpatialGap)
                {
                    chainId = lastPlayerTraversalEpisode.ChainId;
                }
            }

            bool forwardEpisode = edge == null ||
                Vector3.Distance(rawStart, edge.RawStart) <= Vector3.Distance(rawStart, edge.RawEnd);
            Vector3 episodeEntry = edge == null
                ? rawStart
                : (forwardEpisode
                    ? (edge.HasSettledStart && IsFinite(edge.SettledStart) ? edge.SettledStart : edge.A)
                    : (edge.HasSettledEnd && IsFinite(edge.SettledEnd) ? edge.SettledEnd : edge.B));
            Vector3 episodeExit = edge == null
                ? rawEnd
                : (forwardEpisode
                    ? (edge.HasSettledEnd && IsFinite(edge.SettledEnd) ? edge.SettledEnd : edge.B)
                    : (edge.HasSettledStart && IsFinite(edge.SettledStart) ? edge.SettledStart : edge.A));

            TraversalEpisodeMetadata metadata = new TraversalEpisodeMetadata
            {
                EpisodeId = episodeId,
                EdgeId = edgeId,
                ChainId = chainId,
                PlayerTraversalSequence = edge?.PlayerTraversalSequence ?? 0,
                StartBreadcrumbSequence = startBreadcrumbSequence,
                EndBreadcrumbSequence = endBreadcrumbSequence,
                Kind = string.IsNullOrWhiteSpace(kind) ? (edge?.Kind ?? "Vault") : kind,
                Entry = episodeEntry,
                Exit = episodeExit,
                RawStart = rawStart,
                RawEnd = rawEnd,
                HasSettledStart = forwardEpisode ? edge?.HasSettledStart == true : edge?.HasSettledEnd == true,
                SettledStart = edge == null ? rawStart : (forwardEpisode ? edge.SettledStart : edge.SettledEnd),
                HasSettledEnd = forwardEpisode ? edge?.HasSettledEnd == true : edge?.HasSettledStart == true,
                SettledEnd = edge == null ? rawEnd : (forwardEpisode ? edge.SettledEnd : edge.SettledStart),
                CreatedAt = Time.time
            };
            TraversalEpisodesByEdge[edgeId] = metadata;
            TraversalEpisodeStream.Add(metadata);
            if (TraversalEpisodeStream.Count > LearnedTraversalEdgeLimit * 8)
            {
                TraversalEpisodeStream.RemoveRange(0, TraversalEpisodeStream.Count - LearnedTraversalEdgeLimit * 8);
            }
            if (allowChain)
            {
                lastPlayerTraversalEpisode = metadata;
            }
            WriteEvent("playerTraversalEpisodeRegistered", null, new
            {
                episodeId = metadata.EpisodeId,
                chainId = metadata.ChainId,
                edgeId,
                kind = metadata.Kind,
                startBreadcrumbSequence,
                endBreadcrumbSequence,
                rawStart = Vec(rawStart),
                rawEnd = Vec(rawEnd)
            });
            EmitLearningV341RegisteredEpisodeSemanticAmbiguity(metadata);
            return metadata;
        }

        private static int GetLearningV442InterveningBreadcrumbCount(int currentEndSequence, int nextStartSequence)
        {
            if (currentEndSequence <= 0 || nextStartSequence <= 0)
            {
                return int.MaxValue;
            }

            // Sequence N -> N+1 has no intervening breadcrumb.  Preserve the historical overlap
            // tolerance separately at each caller; this helper normalizes only forward chronology.
            return nextStartSequence <= currentEndSequence
                ? 0
                : Math.Max(0, nextStartSequence - currentEndSequence - 1);
        }

        private static bool TryResolveLearningV442CurrentEpisodeJumpTakeoffFrontier(
            TraversalEpisodeMetadata episode,
            Vector3 persistentRawEntry,
            Vector3 persistentRawExit,
            out Vector3 takeoffFrontier,
            out float takeoffLayerDelta,
            out float spanRatio,
            out float directionDot,
            out float verticalDeltaError)
        {
            takeoffFrontier = default;
            takeoffLayerDelta = 0f;
            spanRatio = 0f;
            directionDot = -1f;
            verticalDeltaError = float.PositiveInfinity;
            if ((episode == null) ||
                !string.Equals(episode.Kind, "Jump", StringComparison.OrdinalIgnoreCase) ||
                !IsFinite(episode.RawStart) || !IsFinite(episode.RawEnd) ||
                !IsFinite(persistentRawEntry) || !IsFinite(persistentRawExit))
            {
                return false;
            }

            // V4.42 is not a blanket "fresh episode beats Native-Proven" rule.  Current-raid
            // takeoff geometry owns only the runtime admission plane, and only when the persistent
            // entry is demonstrably on a different physical layer.  Reuse the existing V3.32
            // vertical-rebase contract rather than introducing a map/action-specific tolerance.
            takeoffLayerDelta = Mathf.Abs(episode.RawStart.y - persistentRawEntry.y);
            if (takeoffLayerDelta <= LearningV332NativeGroundMoverStartMaxVerticalRebase)
            {
                return false;
            }

            float persistentSpan = GetPlanarDistance(persistentRawEntry, persistentRawExit);
            float episodeSpan = GetPlanarDistance(episode.RawStart, episode.RawEnd);
            if (persistentSpan <= 0.20f || episodeSpan <= 0.20f)
            {
                return false;
            }

            spanRatio = episodeSpan / persistentSpan;
            if (spanRatio < LearningV2RevisionMinSpanRatio || spanRatio > LearningV2RevisionMaxSpanRatio)
            {
                return false;
            }

            Vector3 persistentDirection = GetFlatDirection(persistentRawExit - persistentRawEntry);
            Vector3 episodeDirection = GetFlatDirection(episode.RawEnd - episode.RawStart);
            if (persistentDirection.sqrMagnitude >= 0.5f && episodeDirection.sqrMagnitude >= 0.5f)
            {
                directionDot = Vector3.Dot(persistentDirection, episodeDirection);
                if (directionDot < LearningV2RevisionMinDirectionDot)
                {
                    return false;
                }
            }
            else
            {
                directionDot = 1f;
            }

            float persistentVerticalDelta = persistentRawExit.y - persistentRawEntry.y;
            float episodeVerticalDelta = episode.RawEnd.y - episode.RawStart.y;
            verticalDeltaError = Mathf.Abs(episodeVerticalDelta - persistentVerticalDelta);
            if (verticalDeltaError > LearningV2RevisionVerticalTolerance)
            {
                return false;
            }

            takeoffFrontier = episode.RawStart;
            return true;
        }

        private static Vector3 GetLearningV442JumpAdmissionEntry(FollowerRouteMissionStep step)
        {
            if ((step != null) &&
                step.LearningV442HasCurrentEpisodeJumpTakeoffFrontier &&
                IsFinite(step.LearningV442CurrentEpisodeJumpTakeoffFrontier))
            {
                return step.LearningV442CurrentEpisodeJumpTakeoffFrontier;
            }
            return step != null && IsFinite(step.RawEntry) ? step.RawEntry : (step?.Entry ?? default);
        }

        private static Vector3 GetLearningV442JumpAdmissionEntry(LearnedTraversalCommitment commitment)
        {
            if ((commitment != null) &&
                commitment.LearningV442HasCurrentEpisodeJumpTakeoffFrontier &&
                IsFinite(commitment.LearningV442CurrentEpisodeJumpTakeoffFrontier))
            {
                return commitment.LearningV442CurrentEpisodeJumpTakeoffFrontier;
            }
            return commitment != null && IsFinite(commitment.RawEntry)
                ? commitment.RawEntry
                : (commitment?.Entry ?? default);
        }

        private static bool TryFindLearningV442CanonicalizedPredecessorForDeferredJump(
            FollowerRouteMission mission,
            TraversalEpisodeMetadata jumpEpisode,
            out TraversalEpisodeMetadata predecessorEpisode,
            out FollowerRouteMissionStep canonicalPredecessor,
            out int interveningBreadcrumbs,
            out float successorSpatialGap)
        {
            predecessorEpisode = null;
            canonicalPredecessor = null;
            interveningBreadcrumbs = int.MaxValue;
            successorSpatialGap = float.PositiveInfinity;
            if ((mission?.Steps == null) ||
                jumpEpisode == null || jumpEpisode.ChainId <= 0 ||
                !string.Equals(jumpEpisode.Kind, "Jump", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            predecessorEpisode = TraversalEpisodeStream
                .Where(item => item != null && item.ChainId == jumpEpisode.ChainId &&
                               item.EpisodeId < jumpEpisode.EpisodeId)
                .OrderByDescending(item => item.EpisodeId)
                .FirstOrDefault();
            if (predecessorEpisode == null ||
                (!string.Equals(predecessorEpisode.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) &&
                 !string.Equals(predecessorEpisode.Kind, "PhysicalCorridor", StringComparison.OrdinalIgnoreCase)) ||
                !IsImmediateTraversalChainSuccessor(
                    predecessorEpisode, jumpEpisode, out interveningBreadcrumbs, out successorSpatialGap))
            {
                return false;
            }

            Vector3 predecessorRawEntry = predecessorEpisode.LearningV372HasCurrentExecutionGeometry &&
                                           IsFinite(predecessorEpisode.LearningV372CurrentExecutionStart)
                ? predecessorEpisode.LearningV372CurrentExecutionStart
                : predecessorEpisode.RawStart;
            Vector3 predecessorRawExit = predecessorEpisode.LearningV372HasCurrentExecutionGeometry &&
                                          IsFinite(predecessorEpisode.LearningV372CurrentExecutionEnd)
                ? predecessorEpisode.LearningV372CurrentExecutionEnd
                : predecessorEpisode.RawEnd;
            if (!IsFinite(predecessorRawEntry) || !IsFinite(predecessorRawExit))
            {
                return false;
            }

            FollowerRouteMissionStep predecessorProxy = new FollowerRouteMissionStep
            {
                EpisodeId = predecessorEpisode.EpisodeId,
                EdgeId = predecessorEpisode.EdgeId,
                Kind = predecessorEpisode.Kind,
                StartBreadcrumbSequence = predecessorEpisode.StartBreadcrumbSequence,
                EndBreadcrumbSequence = predecessorEpisode.EndBreadcrumbSequence,
                Entry = predecessorRawEntry,
                Exit = predecessorRawExit,
                RawEntry = predecessorRawEntry,
                RawExit = predecessorRawExit,
                ChainId = predecessorEpisode.ChainId,
                CurrentRaidRouteAuthority = true,
                CreatedAt = predecessorEpisode.CreatedAt
            };

            TraversalEpisodeMetadata predecessorEpisodeLocal = predecessorEpisode;
            canonicalPredecessor = mission.Steps
                .Where(step => step != null &&
                    (step.EpisodeId == predecessorEpisodeLocal.EpisodeId ||
                     AreRouteMissionPassageStepsRedundant(step, predecessorProxy)))
                .OrderByDescending(step => step.EndBreadcrumbSequence)
                .ThenByDescending(step => step.EpisodeId)
                .FirstOrDefault();
            return canonicalPredecessor != null;
        }

        private static bool IsImmediateTraversalChainSuccessor(
            TraversalEpisodeMetadata current,
            TraversalEpisodeMetadata next,
            out int breadcrumbGap,
            out float spatialGap)
        {
            breadcrumbGap = int.MaxValue;
            spatialGap = float.PositiveInfinity;
            if (current == null || next == null || current.ChainId <= 0 || current.ChainId != next.ChainId)
            {
                return false;
            }

            if (IsFinite(current.RawEnd) && IsFinite(next.RawStart))
            {
                spatialGap = GetPlanarDistance(current.RawEnd, next.RawStart);
            }

            bool haveBreadcrumbProvenance =
                current.EndBreadcrumbSequence > 0 && next.StartBreadcrumbSequence > 0;
            if (haveBreadcrumbProvenance)
            {
                if (next.StartBreadcrumbSequence <
                    current.EndBreadcrumbSequence - TraversalChainImmediateMaxBreadcrumbGap)
                {
                    return false;
                }
                breadcrumbGap = (GetLearningV442InterveningBreadcrumbCount(
                        current.EndBreadcrumbSequence, next.StartBreadcrumbSequence));
                return breadcrumbGap <= TraversalChainImmediateMaxBreadcrumbGap &&
                       spatialGap <= TraversalChainImmediateMaxSpatialGap;
            }

            // Bootstrap/persistent episodes do not have current-raid breadcrumb provenance. Do not
            // grant them a permissive 5.5m local bridge merely because they happen to share a chain.
            return spatialGap <= TraversalChainImmediateMaxSpatialGap;
        }

        private static bool IsLearningV441CanonicalMissionImmediateSuccessor(
            TraversalEpisodeMetadata current,
            TraversalEpisodeMetadata next,
            out int breadcrumbGap,
            out float spatialGap)
        {
            breadcrumbGap = int.MaxValue;
            spatialGap = float.PositiveInfinity;
            if ((current == null) || next == null ||
                !IsFinite(current.RawEnd) || !IsFinite(next.RawStart))
            {
                return false;
            }

            spatialGap = GetPlanarDistance(current.RawEnd, next.RawStart);
            if (spatialGap > TraversalChainImmediateMaxSpatialGap)
            {
                return false;
            }

            bool haveBreadcrumbProvenance =
                current.EndBreadcrumbSequence > 0 && next.StartBreadcrumbSequence > 0;
            if (haveBreadcrumbProvenance)
            {
                // Detector windows may overlap by the existing immediate tolerance. The canonical
                // RouteMission order is already the ordering proof; this helper only verifies that
                // the two physical endpoints can be one continuous movement transaction.
                if (next.StartBreadcrumbSequence <
                        current.EndBreadcrumbSequence - TraversalChainImmediateMaxBreadcrumbGap)
                {
                    return false;
                }
                breadcrumbGap = (GetLearningV442InterveningBreadcrumbCount(
                        current.EndBreadcrumbSequence, next.StartBreadcrumbSequence));
                if (breadcrumbGap > TraversalChainImmediateMaxBreadcrumbGap)
                {
                    return false;
                }
                if (current.EndBreadcrumbSequence > 0 && next.EndBreadcrumbSequence > 0 &&
                    next.EndBreadcrumbSequence <= current.EndBreadcrumbSequence)
                {
                    return false;
                }
            }

            Vector3 currentAxis = current.RawEnd - current.RawStart;
            currentAxis.y = 0f;
            Vector3 nextAxis = next.RawEnd - next.RawStart;
            nextAxis.y = 0f;
            if (currentAxis.sqrMagnitude > 0.04f && nextAxis.sqrMagnitude > 0.04f &&
                Vector3.Dot(currentAxis.normalized, nextAxis.normalized) < -0.35f)
            {
                return false;
            }
            return true;
        }

        private static bool TryGetNextTraversalEpisode(int currentEpisodeId, out TraversalEpisodeMetadata next)
        {
            return TryGetNextTraversalEpisode(currentEpisodeId, out next, out _);
        }

        private static bool TryGetNextTraversalEpisode(
            int currentEpisodeId,
            out TraversalEpisodeMetadata next,
            out int learningV367NonAdvancingCandidatesSkipped)
        {
            next = null;
            learningV367NonAdvancingCandidatesSkipped = 0;
            if (currentEpisodeId <= 0)
            {
                return false;
            }

            TraversalEpisodeMetadata current = TraversalEpisodeStream
                .LastOrDefault(item => item != null && item.EpisodeId == currentEpisodeId);
            if (current == null)
            {
                return false;
            }

            List<TraversalEpisodeMetadata> candidates = TraversalEpisodeStream
                .Where(item => item != null &&
                               item.ChainId == current.ChainId &&
                               item.EpisodeId > current.EpisodeId)
                .OrderBy(item => item.EpisodeId)
                .ToList();
            if ((current.EndBreadcrumbSequence <= 0))
            {
                next = candidates.FirstOrDefault(candidate =>
                    (!candidate.LearningV386ExecutionDebtConsumedByPhysicalPassage));
                return next != null;
            }

            // EpisodeId is detector creation order, not a causal physical-route frontier. Overlap
            // detectors can mint a later EpisodeId whose breadcrumb window is actually behind the
            // passage just completed. A successor must advance EndBreadcrumbSequence and may overlap
            // the current end only by the already-existing immediate-chain breadcrumb tolerance. A
            // genuine player reversal recorded later naturally has a newer Start/End and remains valid.
            int minimumStart = Math.Max(0,
                current.EndBreadcrumbSequence - TraversalChainImmediateMaxBreadcrumbGap);
            foreach (TraversalEpisodeMetadata candidate in candidates)
            {
                if ((candidate.LearningV386ExecutionDebtConsumedByPhysicalPassage))
                {
                    learningV367NonAdvancingCandidatesSkipped++;
                    continue;
                }

                bool haveCandidateProvenance =
                    FollowerCapabilityHelperRules.TryGetNextTraversalEpisode_haveCandidateProvenance_448ABAF1_1(candidate.StartBreadcrumbSequence,candidate.EndBreadcrumbSequence);
                bool advancesFrontier = !haveCandidateProvenance ||
                    (candidate.EndBreadcrumbSequence > current.EndBreadcrumbSequence &&
                     candidate.StartBreadcrumbSequence >= minimumStart);
                if (!advancesFrontier)
                {
                    learningV367NonAdvancingCandidatesSkipped++;
                    continue;
                }

                next = candidate;
                return true;
            }
            return false;
        }

        private static bool TryGetLearningV452PendingPlayerTraversalCapture(
            out string kind,
            out int startBreadcrumbSequence,
            out Vector3 startPosition)
        {
            kind = string.Empty;
            startBreadcrumbSequence = 0;
            startPosition = default(Vector3);
            ;

            if (localJumpCandidateActive && localJumpAwaitingLanding &&
                localJumpStartBreadcrumbSequence > 0 && IsFinite(localJumpStartPosition))
            {
                kind = "Jump";
                startBreadcrumbSequence = localJumpStartBreadcrumbSequence;
                startPosition = localJumpStartPosition;
                return true;
            }
            if (localVaultActive && localVaultStartBreadcrumbSequence > 0 &&
                IsFinite(localVaultStartPosition))
            {
                kind = "VaultOrClimb";
                startBreadcrumbSequence = localVaultStartBreadcrumbSequence;
                startPosition = localVaultStartPosition;
                return true;
            }
            if (localNaturalDropCandidateActive && localNaturalDropStartBreadcrumbSequence > 0 &&
                IsFinite(localNaturalDropStartPosition))
            {
                kind = "DropDown";
                startBreadcrumbSequence = localNaturalDropStartBreadcrumbSequence;
                startPosition = localNaturalDropStartPosition;
                return true;
            }
            return false;
        }

        private static bool IsLearningV452PendingAdjacentPlayerTraversalForMission(
            FollowerRouteMission mission,
            out string pendingKind,
            out int pendingStartBreadcrumbSequence,
            out Vector3 pendingStartPosition)
        {
            pendingKind = string.Empty;
            pendingStartBreadcrumbSequence = 0;
            pendingStartPosition = default(Vector3);
            if (mission?.Steps == null || mission.Steps.Count == 0 ||
                !TryGetLearningV452PendingPlayerTraversalCapture(
                    out pendingKind, out pendingStartBreadcrumbSequence, out pendingStartPosition) ||
                pendingStartBreadcrumbSequence < mission.StartBreadcrumbSequence)
            {
                return false;
            }

            FollowerRouteMissionStep last = mission.Steps
                .Where(step => step != null)
                .OrderByDescending(step => step.EndBreadcrumbSequence)
                .FirstOrDefault();
            if (last == null)
            {
                return false;
            }

            Vector3 lastExit = IsFinite(last.RawExit) ? last.RawExit : last.Exit;
            return IsFinite(lastExit) &&
                   GetPlanarDistance(lastExit, pendingStartPosition) <= TraversalChainMaxSpatialGap;
        }

        // V4.71: the recorded Jump is a typed actuator debt, NOT a terminal Follow target.
        // Overlapping WalkThrough detectors can consume the last canonical WT step while a
        // current-raid adjacent Jump has already been observed (V440/V442) but disappears from
        // the refreshed step list.  Rebind only the exact immediately adjacent observed Jump,
        // using existing topology, motion-generation and lane rules. No Native success credit.
        private static bool TryRetainLearningV471AdjacentJumpAtPassageCompletion(
            BotOwner bot, FollowerRouteMission mission,
            TraversalEpisodeMetadata completedEpisode, FollowerTraversalRouteCursor cursor)
        {
            if ((bot == null) || mission?.Steps == null || completedEpisode == null || cursor == null ||
                !string.Equals(completedEpisode.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                mission.CurrentStepIndex != mission.Steps.Count ||
                completedEpisode.EndBreadcrumbSequence < mission.StartBreadcrumbSequence ||
                IsTeleportTransactionActive(bot) || !IsFinite(bot.Position) ||
                FollowerMovementWriterAuthority.GetCurrentGeneration(
                    bot, out FollowerMovementWriterAuthority.WriterDomain boundaryOwner) <= 0 ||
                boundaryOwner != FollowerMovementWriterAuthority.WriterDomain.Traversal)
            {
                return false;
            }

            foreach (TraversalEpisodeMetadata successor in TraversalEpisodeStream
                .Where(item => item != null &&
                    string.Equals(item.Kind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                    item.EpisodeId > completedEpisode.EpisodeId &&
                    item.StartBreadcrumbSequence > 0 &&
                    item.EndBreadcrumbSequence > cursor.ConsumedBreadcrumbSequence &&
                    item.StartBreadcrumbSequence >=
                        completedEpisode.EndBreadcrumbSequence - TraversalChainImmediateMaxBreadcrumbGap &&
                    item.StartBreadcrumbSequence <=
                        completedEpisode.EndBreadcrumbSequence + TraversalChainImmediateMaxBreadcrumbGap)
                .OrderBy(item => item.StartBreadcrumbSequence)
                .ThenBy(item => item.EpisodeId))
            {
                if (!(HasLearningV437JumpEpisodePostLandingRetention(successor) ||
                      IsLearningV453RetainedNativeProvenJumpSubtrajectory(successor)) ||
                    mission.Steps.Any(item => item != null && item.EpisodeId == successor.EpisodeId))
                {
                    continue;
                }
                FollowerRouteMissionStep step = CreateFollowerRouteMissionStep(successor);
                if (step == null || !step.CurrentRaidRouteAuthority ||
                    !IsFinite(step.RawEntry) || !IsFinite(step.RawExit))
                {
                    continue;
                }
                LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(item =>
                    item != null && item.Id == step.EdgeId);
                if (!IsTraversalEdgeTopologicallySelectableForRouteStep(
                        bot, edge, step, out string selectionReason))
                {
                    continue;
                }
                Vector3 completedExit = IsFinite(completedEpisode.RawEnd)
                    ? completedEpisode.RawEnd : completedEpisode.Exit;
                Vector3 jumpAxis = GetFlatDirection(step.RawExit - step.RawEntry);
                Vector3 bodyDelta = bot.Position - step.RawEntry;
                bodyDelta.y = 0f;
                float entryProjection = Vector3.Dot(bodyDelta, jumpAxis);
                float bodyDistance = GetPlanarDistance(bot.Position, step.RawEntry);
                float predecessorGap = GetPlanarDistance(completedExit, step.RawEntry);
                if (!IsFinite(completedExit) || jumpAxis.sqrMagnitude < 0.5f ||
                    bodyDistance > RouteMissionTraversalAdjacentBridgeMaxDistance ||
                    predecessorGap > TraversalChainMaxSpatialGap ||
                    entryProjection > LearningV352JumpTakeoffCorridorMaxForwardOvershoot)
                {
                    continue;
                }

                // Insert at the exact exhausted cursor: no WT is replayed, and a later
                // DropDown still remains a distinct typed debt rather than a body shortcut.
                if (!InsertLifecycleMissionStep(mission,mission.CurrentStepIndex,step)) return false;
                mission.TargetBreadcrumbSequence = Math.Max(
                    mission.TargetBreadcrumbSequence, step.EndBreadcrumbSequence);
                mission.ExpiresAt = Mathf.Max(mission.ExpiresAt, Time.time + RouteMissionLifetimeSeconds);
                WriteEvent("learningV471ObservedJumpDebtRetainedAtWalkThroughBoundary", bot, new
                {
                    missionId = mission.MissionId,
                    completedEpisodeId = completedEpisode.EpisodeId,
                    completedEdgeId = completedEpisode.EdgeId,
                    successorEpisodeId = successor.EpisodeId,
                    successorEdgeId = step.EdgeId,
                    successorKind = step.Kind,
                    consumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence,
                    startBreadcrumbSequence = successor.StartBreadcrumbSequence,
                    endBreadcrumbSequence = successor.EndBreadcrumbSequence,
                    body = Vec(bot.Position),
                    entryProjection,
                    bodyDistance,
                    predecessorGap,
                    movementOwner = "Traversal",
                    nativeSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false,
                    action = "canonicalPassageTerminalCannotDemoteObservedAdjacentJumpToOrdinaryFollowDisplacement"
                });
                return true;
            }
            return false;
        }

        // V2-RC25: the ONE route-cursor mutation seam shared by native episode
        // completion and measured physical-pass consumption. Never infer Native
        // Success or retire a movement Writer here. Admission to the live mission
        // and exactly-once terminal outcome are separate, still-open contracts.
        private static bool CommitFollowerTraversalRouteCursor(
            FollowerTraversalRouteCursor cursor, int episodeId, int chainId,
            int endBreadcrumbSequence, FollowerMovementV2IntentGateway.RouteCursorMutationKind kind)
        {
            if (cursor == null)
                return false;
            FollowerMovementV2IntentGateway.RouteCursorCommitPlan plan =
                FollowerMovementV2IntentGateway.PlanRouteCursorCommit(
                    cursor.LastCompletedEpisodeId, cursor.LastCompletedChainId,
                    cursor.ConsumedBreadcrumbSequence, cursor.PreloadedEpisodeId,
                    episodeId, chainId, endBreadcrumbSequence, kind);
            cursor.LastCompletedEpisodeId = plan.EpisodeId;
            cursor.LastCompletedChainId = plan.ChainId;
            cursor.ConsumedBreadcrumbSequence = plan.ConsumedBreadcrumbSequence;
            if (plan.ClearPreloadedEpisode)
                cursor.PreloadedEpisodeId = 0;
            return plan.Changed;
        }

        // RC34: probe-origin completions carry the generation from the actual
        // producer. Never infer it from a NEW Traversal owner at callback time.
        // Preserve the legacy three-argument API for independent measured physical
        // passage and route-driven completions, which have different proof paths.
        private static void MarkFollowerTraversalEpisodeCompleted(
            ProbeRuntime probe, int episodeId, int edgeId, long probeOriginGeneration)
        {
            BotOwner bot=probe?.Bot;
            if (bot == null)
            {
                return;
            }
            long currentGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain currentOwner);
            if (!FollowerMovementV2IntentGateway.CanAdmitProbeTerminalOrigin(
                    probeOriginGeneration, currentOwner, currentGeneration))
            {
                if (ShouldEmitDiagnostic("rc34ProbeTerminalStaleWriter:" + episodeId,
                        bot, 1.0f))
                {
                    WriteEvent("followerTraversalProbeTerminalOriginRejected", bot, new
                    {
                        episodeId,
                        executionEdgeId = edgeId,
                        probeOriginGeneration,
                        currentGeneration,
                        currentOwner = currentOwner.ToString(),
                        terminalCursorChanged = false,
                        routeStepAdvanced = false,
                        nativeSuccessRecordedByThisCommit = false,
                        action = "oldProbeCannotCompleteUsingSuccessorTraversalWriterGeneration"
                    });
                }
                return;
            }
            if (!PublishProbeLifecycleCompletion(probe,episodeId,edgeId)) return;
            MarkFollowerTraversalEpisodeCompleted(bot, episodeId, edgeId);
        }

        private static void MarkFollowerTraversalEpisodeCompleted(BotOwner bot, int episodeId, int edgeId)
        {
            if(bot!=null&&FollowerRouteMissions.TryGetValue(bot.ProfileId,out var retry)&&IsCapabilityRouteRetryReturning(retry))return;
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return;
            }

            // CompileFix46 remains the stale-probe guard: episode ids and edge ids are independent
            // domains, so a mismatched pair is never trusted merely because the integers exist.
            // V3.7 adds the missing Native-Proven alias contract. A current-raid authored episode may
            // reference a fresh/shadow edge while RouteMission executes its authoritative proven parent.
            // In that case EpisodeId is still the durable route identity and ExecutionEdgeId is an
            // intentional selector alias. Accept the mismatch only when the LIVE commitment or LIVE
            // mission step proves that exact episode->execution-edge pair; stale probes are now fail-closed
            // when they offer an explicit mismatched Episode; true edge-only legacy
            // callers retain the newest-by-edge lookup.
            TraversalEpisodeMetadata requestedEpisode = episodeId > 0
                ? TraversalEpisodeStream.LastOrDefault(item => item != null && item.EpisodeId == episodeId)
                : null;
            bool substitutedExecutionEdge = false;
            string substitutionProof = null;
            if (requestedEpisode != null && edgeId > 0 && requestedEpisode.EdgeId != edgeId)
            {
                if (LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment liveCommitment) &&
                    liveCommitment != null && liveCommitment.EpisodeId == episodeId && liveCommitment.EdgeId == edgeId)
                {
                    substitutedExecutionEdge = true;
                    substitutionProof = "liveCommitment";
                }
                else if (FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission liveMission) &&
                         liveMission != null && liveMission.Steps != null &&
                         liveMission.Steps.Any(step => step != null && step.EpisodeId == episodeId && step.EdgeId == edgeId))
                {
                    substitutedExecutionEdge = true;
                    substitutionProof = "liveRouteMission";
                }
            }

            TraversalEpisodeMetadata episode = requestedEpisode != null &&
                (edgeId <= 0 || requestedEpisode.EdgeId == edgeId || substitutedExecutionEdge)
                    ? requestedEpisode
                    : null;
            // RC32: a callback that *names* an Episode cannot silently complete a
            // different, newer Episode merely because both mention the same Edge.
            // Preserve the pre-existing legacy Edge-only mode (episodeId <= 0).
            // Exact live execution-edge aliases were already resolved above.
            if (episode == null &&
                FollowerMovementV2IntentGateway.CanResolveTerminalEpisodeByEdgeOnly(
                    episodeId, edgeId))
            {
                episode = TraversalEpisodeStream
                    .Where(item => item != null && item.EdgeId == edgeId)
                    .OrderByDescending(item => item.EpisodeId)
                    .FirstOrDefault();
            }
            if (episode == null)
            {
                if (episodeId > 0 && edgeId > 0 &&
                    ShouldEmitDiagnostic("rc32TerminalExplicitEpisodeMismatch:" + episodeId,
                        bot, 1.5f))
                {
                    WriteEvent("followerTraversalTerminalEpisodeIdentityRejected", bot, new
                    {
                        offeredEpisodeId = episodeId,
                        offeredExecutionEdgeId = edgeId,
                        authoredEpisodeFound = requestedEpisode != null,
                        authoredEdgeId = requestedEpisode?.EdgeId ?? 0,
                        liveExecutionAliasProven = substitutedExecutionEdge,
                        routeStepAdvanced = false,
                        terminalCursorChanged = false,
                        nativeSuccessRecorded = false,
                        action = "explicitEpisodeMustNotBeSubstitutedByLatestEdgeEpisode"
                    });
                }
                return;
            }

            if (substitutedExecutionEdge)
            {
                WriteEvent("followerTraversalRouteCompletionAliasAccepted", bot, new
                {
                    episodeId = episode.EpisodeId,
                    chainId = episode.ChainId,
                    authoredEdgeId = episode.EdgeId,
                    executionEdgeId = edgeId,
                    proof = substitutionProof,
                    learningAuthorityChanged = false
                });
            }

            if (!FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) || cursor == null)
            {
                cursor = new FollowerTraversalRouteCursor();
                FollowerTraversalRouteCursors[profileId] = cursor;
            }
            // RC28: derive the ONLY overlapping-episode exception from the live Mission,
            // not from a remembered completion cache or a numeric EpisodeId comparison.
            // A stale terminal callback may reconcile an already-proven breadcrumb floor,
            // but cannot rewrite the canonical Episode/Chain when no step still owns it.
            bool liveMissionPresent =
                FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission terminalMission) &&
                terminalMission != null && terminalMission.Steps != null &&
                terminalMission.CurrentStepIndex >= 0 &&
                terminalMission.CurrentStepIndex < terminalMission.Steps.Count;
            bool liveExactMissionStep = liveMissionPresent &&
                terminalMission.Steps.Skip(Math.Max(0, terminalMission.CurrentStepIndex)).Any(step =>
                    step != null && step.EpisodeId == episode.EpisodeId &&
                    (edgeId <= 0 || step.EdgeId == edgeId));
            // RC30: BOTH terminal cursor identity and RouteMission step advancement
            // must belong to the same live route source. Physical chronology alone
            // cannot make a stale callback from a different mission its terminal owner.
            // Without a live mission, preserve standalone terminal cleanup semantics.
            bool terminalSourceAdmitted =
                FollowerMovementV2IntentGateway.CanAdmitTerminalRouteSource(
                    liveMissionPresent, liveExactMissionStep);
            bool terminalCursorAdmitted = terminalSourceAdmitted &&
                FollowerMovementV2IntentGateway.CanPublishTerminalCursorIdentity(
                    episode.EpisodeId, episode.EndBreadcrumbSequence,
                    cursor.LastCompletedEpisodeId, cursor.ConsumedBreadcrumbSequence,
                    liveExactMissionStep);
            // Completion and physical-pass paths share this ONE typed cursor commit.
            // Physical pass, inherited WT, and route cancellation semantics are unchanged.
            bool terminalCursorChanged = terminalCursorAdmitted &&
                CommitFollowerTraversalRouteCursor(
                    cursor, episode.EpisodeId, episode.ChainId, episode.EndBreadcrumbSequence,
                    FollowerMovementV2IntentGateway.RouteCursorMutationKind.NativeCompletion);
            if (!terminalCursorAdmitted &&
                ShouldEmitDiagnostic("rc28StaleTerminalCursor:" + episode.EpisodeId, bot, 1.5f))
            {
                WriteEvent("followerTraversalTerminalCursorReplayRejected", bot, new
                {
                    episodeId = episode.EpisodeId,
                    executionEdgeId = edgeId,
                    completedCursorEpisodeId = cursor.LastCompletedEpisodeId,
                    cursorConsumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence,
                    liveExactMissionStep,
                    liveMissionPresent,
                    terminalSourceAdmitted,
                    rejectionReason = !terminalSourceAdmitted
                        ? "terminalEpisodeDoesNotBelongToLiveMission"
                        : "staleTerminalCursorNoNewPhysicalFloor",
                    routeStepAdvanced = false,
                    nativeSuccessRecorded = false,
                    action = "unownedTerminalCompletionCannotRewriteCursorOrMission"
                });
            }

            if (BreadcrumbFollowCommitments.TryGetValue(profileId, out BreadcrumbFollowCommitment breadcrumbCommitment) &&
                breadcrumbCommitment != null && breadcrumbCommitment.TargetSequence <= cursor.ConsumedBreadcrumbSequence)
            {
                BreadcrumbFollowCommitments.Remove(profileId);
            }

            // CompileFix46: a live WalkThrough reservation is FIFO state for the same authored
            // episode. Once that episode has physically completed, retaining the reservation can
            // immediately recreate the just-cleared commitment on the next Follow tick and send the
            // follower back toward the old entry. Retire any reservation that is now consumed.
            if (ProvisionalWalkThroughReservations.TryGetValue(profileId, out ProvisionalWalkThroughReservation completedReservation) &&
                completedReservation != null)
            {
                TraversalEpisodeMetadata reservationEpisode = TraversalEpisodeStream.LastOrDefault(item =>
                    item != null && item.EpisodeId == completedReservation.EpisodeId);
                bool reservationConsumed = completedReservation.EpisodeId == episode.EpisodeId ||
                    (reservationEpisode != null && reservationEpisode.EndBreadcrumbSequence > 0 &&
                     reservationEpisode.EndBreadcrumbSequence <= cursor.ConsumedBreadcrumbSequence);
                if (reservationConsumed)
                {
                    ProvisionalWalkThroughReservations.Remove(profileId);
                    WriteEvent("liveWalkThroughReservationRetiredAfterCompletion", bot, new
                    {
                        reservationEpisodeId = completedReservation.EpisodeId,
                        completedEpisodeId = episode.EpisodeId,
                        completedEdgeId = edgeId
                    });
                }
            }

            // RC28: do not emit a second physical-cursor ACK for a no-op replay.
            // The live Mission step is reconciled below regardless of this event.
            if (terminalCursorChanged)
            {
                WriteEvent("followerTraversalRouteCursorAdvanced", bot, new
                {
                    episodeId = episode.EpisodeId,
                    chainId = episode.ChainId,
                    edgeId = episode.EdgeId,
                    authoredEdgeId = episode.EdgeId,
                    executionEdgeId = edgeId,
                    substitutedExecutionEdge,
                    consumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence
                });
            }

            // V2-RC29: the RC28 terminal-cursor replay rejection is also a Mission
            // reconciliation fence. An old callback must not advance a different live
            // RouteMission via a pre-existing breadcrumb floor after its completion
            // identity was rejected. Legitimate measured physical passage, inherited
            // WalkThrough, preloaded cleanup and route cancellation keep their own
            // typed consumers; do not mint Step ACKs from a stale terminal callback.
            if (FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) && mission != null &&
                terminalCursorAdmitted)
            {
                if ((string.Equals(episode.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)))
                {
                    FollowerRouteMissionStep completedPassage = CreateFollowerRouteMissionStep(episode);
                    if (completedPassage != null)
                    {
                        foreach (FollowerRouteMissionStep overlappingStep in mission.Steps
                            .Where(candidate => (candidate != null &&
                                                candidate.EpisodeId != episode.EpisodeId &&
                                                string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase)))
                            .OrderBy(candidate => candidate.EndBreadcrumbSequence)
                            .ToList())
                        {
                            if (!AreRouteMissionWalkThroughStepsRedundant(completedPassage, overlappingStep))
                            {
                                continue;
                            }
                            bool independentlyPassed = IsFollowerRouteMissionStepPhysicallyPassed(
                                bot, overlappingStep, out float overlapProjection, out float overlapRequiredProjection);
                            bool samePhysicalPassageIdentity = ((true));
                            if (!independentlyPassed && !samePhysicalPassageIdentity)
                            {
                                continue;
                            }
                            bool overlapConsumed = independentlyPassed
                                ? ConsumeFollowerRouteMissionPhysicalPass(
                                    bot, mission, overlappingStep, "learningV343CompletedWalkThroughOverlap",
                                    overlapProjection, overlapRequiredProjection)
                                : ConsumeFollowerRouteMissionRedundantWalkThroughIdentity(
                                    bot, mission, overlappingStep, episode.EpisodeId, edgeId);
                            if (overlapConsumed && independentlyPassed)
                            {
                                WriteEvent("learningV343WalkThroughOverlapEpisodeConsumed", bot, new
                                {
                                    completedEpisodeId = episode.EpisodeId,
                                    completedEdgeId = edgeId,
                                    overlappingEpisodeId = overlappingStep.EpisodeId,
                                    overlappingEdgeId = overlappingStep.EdgeId,
                                    chainId = overlappingStep.ChainId,
                                    projection = overlapProjection,
                                    requiredProjection = overlapRequiredProjection,
                                    inheritedFromCompletedPassage = false,
                                    persistentLearningOutcomeChanged = false,
                                    routeIdentityOnly = true
                                });
                            }
                        }
                    }
                }

                int previousStepIndex = mission.CurrentStepIndex;
                while (mission.CurrentStepIndex < mission.Steps.Count)
                {
                    FollowerRouteMissionStep step = mission.Steps[mission.CurrentStepIndex];
            var r2DebtObservation15 = CaptureRouteDebtObservation(bot, mission, step, false);

                    if (step == null)
                    {
                        if (!TryAdvanceRouteMission(bot, mission, mission.CurrentStepIndex + 1, RouteDebtEvidence.PolicySuppression, "MarkFollowerTraversalEpisodeCompleted:12", r2DebtObservation15)) break;
                        continue;
                    }
                    bool exactCompletedStep=step.EpisodeId==episode.EpisodeId && (edgeId<=0 || step.EdgeId==edgeId);
                    bool publishedProbe=exactCompletedStep && step.Lifecycle.Probe?.CompletionPublished==true;
                    bool independentBodyProof=!publishedProbe && IsFollowerRouteMissionStepPhysicallyPassed(bot,step,out _,out _);
                    if (publishedProbe || independentBodyProof)
                    {
                        mission.ApproachBreadcrumbSequence = Math.Max(mission.ApproachBreadcrumbSequence, step.EndBreadcrumbSequence);
                        if (!TryAdvanceRouteMission(bot, mission, mission.CurrentStepIndex + 1, step.Lifecycle.Probe?.CompletionPublished == true ? RouteDebtEvidence.ProbeCompletion : RouteDebtEvidence.PhysicalPass, "MarkFollowerTraversalEpisodeCompleted:13", r2DebtObservation15)) break;
                        continue;
                    }
                    if ((step.EpisodeId < cursor.LastCompletedEpisodeId) &&
                        step.EndBreadcrumbSequence > cursor.ConsumedBreadcrumbSequence)
                    {
                        WriteEvent("learningV325RouteEpisodeIdentityNotUsedAsOrder", bot, new
                        {
                            missionId = mission.MissionId, completedEpisodeId = episode.EpisodeId,
                            preservedSuccessorEpisodeId = step.EpisodeId, preservedSuccessorEdgeId = step.EdgeId,
                            preservedSuccessorKind = step.Kind, consumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence,
                            successorEndBreadcrumbSequence = step.EndBreadcrumbSequence
                        });
                    }
                    break;
                }

                // V2-RC27: a duplicate terminal callback (or a completed overlapping
                // identity without any newly consumed live step) must NOT refresh the
                // liveness clock, clear recovery attempts or erase failure evidence.
                // Otherwise repeated old completion callbacks can indefinitely conceal
                // a genuinely stalled successor. Keep the canonical Refresh below: it
                // still reconciles a mission which became valid independently.
                bool liveStepConsumed = mission.CurrentStepIndex > previousStepIndex;
                if (liveStepConsumed)
                {
                    mission.LastProgressAt = Time.time;
                    mission.LastProgressPosition = bot.Position;
                    mission.NextMoveAttemptAt = 0f;
                    mission.TraversalRetryMovementHoldUntil = 0f;
                    mission.LocalRecoveryAttempts = 0;
                    mission.LearningV336SelfRescueStepIndex = -1;
                    mission.LearningV336SelfRescueEdgeId = 0;
                    mission.LearningV336SelfRescueAttempts = 0;
                    mission.LearningV336SelfRescueForceNativeNextAttempt = false;
                    mission.LearningV336SelfRescueForceNativeSource = null;
                    mission.LastFailedBreadcrumbSequence = 0;
                    mission.LastFailedEdgeId = 0;
                    mission.PathRejectsSinceProgress = 0;
                    mission.RejectedBreadcrumbSequences.Clear();
                    mission.FailureSignatureCounts.Clear();
                }
                RefreshFollowerRouteMission(bot, mission);
                if ((mission.CurrentStepIndex >= 0) && mission.CurrentStepIndex < mission.Steps.Count)
                {
                    // MarkFollowerTraversalEpisodeCompleted is the sole durable mission-cursor
                    // advancement writer. Bind the current 3D body epoch here, at the moment the
                    // successor identity becomes canonical, rather than hoping a later completion
                    // call-site sees the same successor before native FixedUpdate runs.
                    TryArmLearningV427MissionCursorConsumerBoundary(
                        bot,
                        mission,
                        mission.Steps[mission.CurrentStepIndex],
                        episode.EpisodeId,
                        edgeId,
                        "markFollowerTraversalEpisodeCompleted");
                }
                if ((mission.CurrentStepIndex >= 0) && mission.CurrentStepIndex < mission.Steps.Count)
                {
                    FollowerTraversalRouteCursor learningV400Cursor = GetOrCreateLearningV375RouteCursor(bot);
                    TryPrimeLearningV400SuccessorRollingSprintLease(
                        bot, mission, learningV400Cursor, "followerRouteMissionAdvanced");
                }

                // Report an advance only if it actually consumed a new live step.
                // A replay is not another RouteMission ACK, even if the cursor
                // already holds that episode's physical passage evidence.
                if (mission.CurrentStepIndex > previousStepIndex)
                {
                    WriteEvent("followerRouteMissionAdvanced", bot, new
                    {
                        missionId = mission.MissionId,
                        completedEpisodeId = episode.EpisodeId,
                        completedEdgeId = edgeId,
                        previousStepIndex,
                        currentStepIndex = mission.CurrentStepIndex,
                        remainingSteps = Math.Max(0, mission.Steps.Count - mission.CurrentStepIndex),
                        consumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence
                    });
                }

                // V4.71: before the old terminal consumer can drive over the observed Jump,
                // preserve its exact current-raid actuator debt inside the same Mission.
                TryRetainLearningV471AdjacentJumpAtPassageCompletion(
                    bot, mission, episode, cursor);

                if (mission.CurrentStepIndex >= mission.Steps.Count)
                {
                    if (IsLearningV452PendingAdjacentPlayerTraversalForMission(
                            mission, out string learningV452PendingKind,
                            out int learningV452PendingStartBreadcrumbSequence,
                            out Vector3 learningV452PendingStartPosition))
                    {
                        mission.ExpiresAt = Mathf.Max(
                            mission.ExpiresAt, Time.time + RouteMissionLifetimeSeconds);
                        WriteEvent("learningV452RouteMissionTerminalizationDeferredForPendingPlayerTraversal", bot, new
                        {
                            missionId = mission.MissionId,
                            currentStepIndex = mission.CurrentStepIndex,
                            stepCount = mission.Steps.Count,
                            pendingKind = learningV452PendingKind,
                            pendingStartBreadcrumbSequence = learningV452PendingStartBreadcrumbSequence,
                            pendingStart = Vec(learningV452PendingStartPosition),
                            body = Vec(bot.Position),
                            traversalSuccessRecorded = false,
                            persistentLearningChanged = false,
                            bodyRelocated = false,
                            action = "preserveCanonicalMissionIdentityUntilAdjacentPlayerTraversalSemanticSettles"
                        });
                        return;
                    }

                    RemoveLifecycleMission(profileId, "MarkFollowerTraversalEpisodeCompleted");
                    FollowRejectLeases.Remove(profileId);
                    FinalizeLearningV382TerminalRouteFreshFollowFrontier(
                        bot, mission, "markFollowerTraversalEpisodeCompleted");
                    WriteEvent(mission.Lifecycle.HasNonPhysicalRetirement ? "followerRouteMissionEndedWithoutPhysicalCompletion" : "followerRouteMissionCompleted", bot, new
                    {
                        missionId = mission.MissionId,
                        source = mission.Source,
                        completedSteps = mission.Steps.Count
                    });
                }
            }
        }

        private static void CompleteCompositeWalkThroughEpisodes(
            ProbeRuntime probe,
            TraversalCompletionMode completionMode)
        {
            if (probe == null || probe.CompositeWalkThroughEpisodeIds == null ||
                probe.CompositeWalkThroughEdgeIds == null)
            {
                return;
            }

            int count = Math.Min(
                probe.CompositeWalkThroughEpisodeIds.Count,
                probe.CompositeWalkThroughEdgeIds.Count);
            for (int index = 0; index < count; index++)
            {
                int episodeId = probe.CompositeWalkThroughEpisodeIds[index];
                int edgeId = probe.CompositeWalkThroughEdgeIds[index];
                if (episodeId <= 0 || edgeId <= 0)
                {
                    continue;
                }

                LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == edgeId &&
                    string.Equals(candidate.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase));
                if (edge == null)
                {
                    continue;
                }

                MarkLearnedTraversalEdgeSuccess(edgeId, completionMode, probe);
                MarkFollowerTraversalEpisodeCompleted(probe, episodeId, edgeId, probe.MovementWriterGeneration);

                LearnedTraversalCommitment completion = CreateLearnedTraversalCommitment(
                    edge,
                    edge.HasSettledStart ? edge.SettledStart : edge.RawStart,
                    edge.HasSettledEnd ? edge.SettledEnd : edge.RawEnd,
                    edge.RawStart,
                    edge.RawEnd);
                if (completion != null)
                {
                    RegisterRecentTraversalCompletion(
                        probe.Bot, edgeId, completion, "compositeWalkThroughCompleted", completionMode, probe.LearningV322AttemptId);
                }

                WriteEvent("walkThroughCompositeEdgeConsumed", probe.Bot, new
                {
                    rootEdgeId = probe.LearnedEdgeId,
                    consumedEdgeId = edgeId,
                    consumedEpisodeId = episodeId,
                    completionMode = completionMode.ToString(),
                    physical = completionMode != TraversalCompletionMode.TeleportFallback
                });
            }
        }

        private static bool TryConsumeAdjacentWalkThroughMicroEdge(
            ProbeRuntime probe,
            TraversalEpisodeMetadata nextEpisode,
            LearnedTraversalEdge nextEdge)
        {
            if (probe == null || nextEpisode == null || nextEdge == null ||
                !string.Equals(probe.TraversalKind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(nextEdge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            LearnedTraversalEdge currentEdge = LearnedTraversalEdges.FirstOrDefault(edge => edge != null && edge.Id == probe.LearnedEdgeId);
            if (currentEdge == null)
            {
                return false;
            }

            float microLength = GetPlanarDistance(nextEdge.RawStart, nextEdge.RawEnd);
            float authoredGap = GetPlanarDistance(currentEdge.RawEnd, nextEdge.RawStart);
            Vector3 nextExit = nextEdge.HasSettledEnd ? nextEdge.SettledEnd : nextEdge.RawEnd;
            float currentToNextExit = GetPlanarDistance(probe.Player.Position, nextExit);
            if (microLength > WalkThroughMicroEdgeMaxLength ||
                authoredGap > WalkThroughMicroEdgeMaxGap ||
                currentToNextExit > WalkThroughMicroEdgeConsumeDistance)
            {
                return false;
            }

            MarkFollowerTraversalEpisodeCompleted(probe, nextEpisode.EpisodeId, nextEdge.Id, probe.MovementWriterGeneration);
            LearnedTraversalCommitment microCommitment = CreateLearnedTraversalCommitment(
                nextEdge,
                nextEdge.HasSettledStart ? nextEdge.SettledStart : nextEdge.RawStart,
                nextExit,
                nextEdge.RawStart,
                nextEdge.RawEnd);
            if (microCommitment != null)
            {
                RegisterRecentTraversalCompletion(probe.Bot, nextEdge.Id, microCommitment, "microEdgeCoalesced", TraversalCompletionMode.Legacy, probe.LearningV322AttemptId);
            }
            WriteEvent("traversalMicroEdgeCoalesced", probe.Bot, new
            {
                fromEdgeId = probe.LearnedEdgeId,
                consumedEdgeId = nextEdge.Id,
                consumedEpisodeId = nextEpisode.EpisodeId,
                microLength,
                authoredGap,
                currentToNextExit,
                position = Vec(probe.Player.Position),
                nextExit = Vec(nextExit)
            });
            return true;
        }

