        // CF11 diagnostic: only executes for a rejected native teleport, at most
        // once per 2 seconds per follower. Preserves the earlier gate decision.
        internal static void ReportCF11RejectedNativeTeleport(BotOwner bot, object[] args)
        {
            if (bot == null || !IsRaidActive) return;
            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain writerOwner);
            // Manual regroup/F4 and other normal writer domains are never
            // stack-traced; the forensic hook is strictly a traversal handoff probe.
            if ((writerOwner != FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                 writerOwner != FollowerMovementWriterAuthority.WriterDomain.PostTraversal) ||
                !ShouldEmitDiagnostic("cf11RejectedNativeTeleportProvenance", bot, 2.0f))
            {
                return;
            }
            try
            {
                string arguments = string.Empty;
                if (args != null)
                {
                    for (int i = 0; i < args.Length && i < 6; i++)
                    {
                        if (i > 0) arguments += "; ";
                        arguments += args[i] == null ? "null" : args[i].ToString();
                    }
                }
                string callsite = new System.Diagnostics.StackTrace(1, false).ToString();
                if (callsite.Length > 1200) callsite = callsite.Substring(0, 1200);
                WriteEvent("cf11RejectedNativeTeleportProvenance", bot, new
                {
                    writerOwner = writerOwner.ToString(),
                    movementGeneration = generation,
                    botPosition = Vec(bot.Position),
                    playerPosition = bot.GetPlayer == null ? (object)null : Vec(bot.GetPlayer.Position),
                    moverLinkAnchor = Vec(bot.Mover.PositionOnWayInner),
                    moverPreviousLink = Vec(bot.Mover._prevSuccessLinkedFrom),
                    requestedArguments = arguments,
                    caller = callsite,
                    action = "traceRejectedNativeTeleportWithoutGrantingMovementAuthority"
                });
            }
            catch (Exception ex)
            {
                Logger.LogRuntimeInfo("[CF11] Native teleport provenance diagnostic unavailable: " + ex.GetType().Name);
            }
        }

