        private static bool IsTraversalSuccessorPhysicallyAhead(
            ProbeRuntime probe,
            LearnedTraversalEdge nextEdge,
            Vector3 nextEntry,
            out float forwardOffset,
            out float currentProjection,
            out float nextProjection)
        {
            forwardOffset = 0f;
            currentProjection = 0f;
            nextProjection = 0f;
            if (probe?.Player == null || nextEdge == null || !IsFinite(nextEntry) ||
                !TryGetLearnedCommitmentForProbe(probe, out LearnedTraversalCommitment current) || current == null)
            {
                return true;
            }

            if (TryGetLearningV375CanonicalSuccessorArcAuthority(
                    probe, nextEdge, out float learningV375ForwardOffset,
                    out float learningV375BodyArc, out float learningV375NextArc))
            {
                forwardOffset = learningV375ForwardOffset;
                currentProjection = learningV375BodyArc;
                nextProjection = learningV375NextArc;
                return true;
            }

            Vector3 currentEntry = IsFinite(current.RawEntry) ? current.RawEntry : current.Entry;
            Vector3 currentExit = IsFinite(current.RawExit) ? current.RawExit : current.Exit;
            Vector3 axis = currentExit - currentEntry;
            axis.y = 0f;
            float span = axis.magnitude;
            if (span < 0.25f)
            {
                return true;
            }
            Vector3 direction = axis / span;
            Vector3 currentDelta = probe.Player.Position - currentEntry;
            currentDelta.y = 0f;
            Vector3 nextDelta = nextEntry - currentEntry;
            nextDelta.y = 0f;
            currentProjection = Vector3.Dot(currentDelta, direction);
            nextProjection = Vector3.Dot(nextDelta, direction);
            Vector3 relative = nextEntry - probe.Player.Position;
            relative.y = 0f;
            forwardOffset = Vector3.Dot(relative, direction);

            // Once the follower is physically at/beyond the completed far side, a successor whose
            // entry is materially behind the current body cannot be part of a causal forward chain.
            // RouteMission may rediscover it later only if the player actually reverses direction.
            if (currentProjection >= span - 0.20f && forwardOffset < -0.55f)
            {
                return false;
            }
            if (currentProjection > span + 0.45f && nextProjection < currentProjection - 0.75f)
            {
                return false;
            }
            return true;
        }

        private static bool TryGetLearningV368RouteMissionCanonicalSuccessor(
            ProbeRuntime probe,
            FollowerRouteMission mission,
            out TraversalEpisodeMetadata nextEpisode,
            out LearnedTraversalEdge nextEdge,
            out FollowerRouteMissionStep nextStep)
        {
            nextEpisode = null;
            nextEdge = null;
            nextStep = null;
            if ((probe?.Bot == null) || mission?.Steps == null ||
                mission.Steps.Count == 0)
            {
                return false;
            }

            int currentIndex = -1;
            for (int index = Math.Max(0, mission.CurrentStepIndex); index < mission.Steps.Count; index++)
            {
                FollowerRouteMissionStep candidate = mission.Steps[index];
                if (candidate == null)
                {
                    continue;
                }
                if ((probe.TraversalEpisodeId > 0 && candidate.EpisodeId == probe.TraversalEpisodeId) ||
                    (candidate.EdgeId == probe.LearnedEdgeId &&
                     (probe.TraversalChainId <= 0 || candidate.ChainId <= 0 || candidate.ChainId == probe.TraversalChainId)))
                {
                    currentIndex = index;
                    break;
                }
            }
            if (currentIndex < 0)
            {
                currentIndex = mission.CurrentStepIndex;
            }

            int executionFloor = Math.Max(
                GetFollowerRouteExecutionFloor(probe.Bot.ProfileId ?? string.Empty),
                GetFollowerRouteResumeFloor(probe.Bot.ProfileId ?? string.Empty));
            for (int index = currentIndex + 1; index < mission.Steps.Count; index++)
            {
                FollowerRouteMissionStep candidate = mission.Steps[index];
                if (candidate == null ||
                    (candidate.EndBreadcrumbSequence > 0 && candidate.EndBreadcrumbSequence <= executionFloor))
                {
                    continue;
                }
                TraversalEpisodeMetadata episode = TraversalEpisodeStream.LastOrDefault(item =>
                    item != null && item.EpisodeId == candidate.EpisodeId);
                LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(item =>
                    item != null && item.Id == candidate.EdgeId);
                if (episode == null || edge == null)
                {
                    continue;
                }
                if (!IsTraversalEdgeTopologicallySelectableForRouteStep(
                        probe.Bot, edge, candidate, out _))
                {
                    continue;
                }

                nextEpisode = episode;
                nextEdge = edge;
                nextStep = candidate;
                return true;
            }
            return false;
        }

        private static bool TryConsumeLearningV386RedundantPhysicalPassageSuccessor(
            ProbeRuntime probe,
            TraversalEpisodeMetadata currentEpisode,
            TraversalEpisodeMetadata successorEpisode)
        {
            if ((probe?.Bot == null) || probe.Player == null || currentEpisode == null || successorEpisode == null ||
                currentEpisode.ChainId <= 0 || currentEpisode.ChainId != successorEpisode.ChainId ||
                successorEpisode.LearningV386ExecutionDebtConsumedByPhysicalPassage)
            {
                return false;
            }

            LearnedTraversalEdge currentSemanticEdge = LearnedTraversalEdges.FirstOrDefault(edge =>
                edge != null && edge.Id == currentEpisode.EdgeId);
            LearnedTraversalEdge successorSemanticEdge = LearnedTraversalEdges.FirstOrDefault(edge =>
                edge != null && edge.Id == successorEpisode.EdgeId);
            if (currentSemanticEdge == null || successorSemanticEdge == null ||
                !string.Equals(currentSemanticEdge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(successorSemanticEdge.Kind, "WalkThrough", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            if (!IsImmediateTraversalChainSuccessor(
                    currentEpisode, successorEpisode,
                    out int breadcrumbGap, out float spatialGap))
            {
                return false;
            }

            bool samePassageIdentity = currentSemanticEdge.Id == successorSemanticEdge.Id ||
                AreWalkThroughEdgesPassageRedundant(currentSemanticEdge, successorSemanticEdge);
            if (!samePassageIdentity)
            {
                return false;
            }

            Vector3 rawEntry = successorEpisode.LearningV372HasCurrentExecutionGeometry &&
                               IsFinite(successorEpisode.LearningV372CurrentExecutionStart)
                ? successorEpisode.LearningV372CurrentExecutionStart
                : (IsFinite(successorEpisode.RawStart) ? successorEpisode.RawStart : successorSemanticEdge.RawStart);
            Vector3 rawExit = successorEpisode.LearningV372HasCurrentExecutionGeometry &&
                              IsFinite(successorEpisode.LearningV372CurrentExecutionEnd)
                ? successorEpisode.LearningV372CurrentExecutionEnd
                : (IsFinite(successorEpisode.RawEnd) ? successorEpisode.RawEnd : successorSemanticEdge.RawEnd);
            Vector3 entry = successorEpisode.HasSettledStart && IsFinite(successorEpisode.SettledStart)
                ? successorEpisode.SettledStart
                : (IsFinite(successorEpisode.Entry) ? successorEpisode.Entry : rawEntry);
            Vector3 exit = successorEpisode.HasSettledEnd && IsFinite(successorEpisode.SettledEnd)
                ? successorEpisode.SettledEnd
                : (IsFinite(successorEpisode.Exit) ? successorEpisode.Exit : rawExit);
            FollowerRouteMissionStep physicalProofStep = new FollowerRouteMissionStep
            {
                EpisodeId = successorEpisode.EpisodeId,
                EdgeId = successorSemanticEdge.Id,
                Kind = successorSemanticEdge.Kind,
                StartBreadcrumbSequence = successorEpisode.StartBreadcrumbSequence,
                EndBreadcrumbSequence = successorEpisode.EndBreadcrumbSequence,
                Entry = entry,
                Exit = exit,
                RawEntry = rawEntry,
                RawExit = rawExit,
                ChainId = successorEpisode.ChainId,
                ChainLocalExecutable = true,
                CurrentRaidRouteAuthority = true,
                CreatedAt = Time.time
            };

            if (!IsFollowerRouteMissionStepPhysicallyPassed(
                    probe.Bot, physicalProofStep,
                    out float projection, out float requiredProjection))
            {
                return false;
            }

            successorEpisode.LearningV386ExecutionDebtConsumedByPhysicalPassage = true;
            successorEpisode.LearningV386ExecutionDebtPhysicalPassageSource =
                "learningV386RedundantWalkThroughSuccessorIdentityConsumed";

            string profileId = probe.Bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) &&
                LearnedTraversalCommitments.TryGetValue(profileId, out LearnedTraversalCommitment commitment) &&
                commitment != null && commitment.EpisodeId == successorEpisode.EpisodeId)
            {
                LearnedTraversalCommitments.Remove(profileId);
            }

            WriteEvent("learningV386RedundantWalkThroughSuccessorIdentityConsumed", probe.Bot, new
            {
                completedEpisodeId = currentEpisode.EpisodeId,
                completedEdgeId = currentSemanticEdge.Id,
                redundantEpisodeId = successorEpisode.EpisodeId,
                redundantEdgeId = successorSemanticEdge.Id,
                chainId = successorEpisode.ChainId,
                breadcrumbGap,
                spatialGap,
                projection,
                requiredProjection,
                traversalSuccessRecorded = false,
                persistentLearningChanged = false,
                navMeshProofRequired = false,
                action = "samePhysicalWalkThroughAlreadyCoveredConsumesOnlyRuntimeSuccessorDebt"
            });
            return true;
        }

        private static bool TryResolveLearningV422CanonicalSuccessorDebtConsumption(
            BotOwner bot,
            TraversalEpisodeMetadata cachedEpisode,
            out TraversalEpisodeMetadata canonicalEpisode,
            out bool durableEpisodeConsumed,
            out int cursorConsumedBreadcrumbSequence,
            out int executionFloorBreadcrumbSequence,
            out int routeResumeFloorBreadcrumbSequence,
            out string consumptionSource)
        {
            canonicalEpisode = cachedEpisode;
            durableEpisodeConsumed = false;
            cursorConsumedBreadcrumbSequence = 0;
            executionFloorBreadcrumbSequence = 0;
            routeResumeFloorBreadcrumbSequence = 0;
            consumptionSource = null;
            if ((bot == null) || cachedEpisode == null)
            {
                return false;
            }

            // Do not trust a successor reference captured before MarkFollowerTraversalEpisodeCompleted.
            // That completion writer may consume the same episode through RouteMission and/or replace
            // the active runtime representation before this chain dispatcher resumes. EpisodeId plus
            // monotonic route floors are the canonical post-write identity.
            if (cachedEpisode.EpisodeId > 0)
            {
                TraversalEpisodeMetadata refreshedEpisode = TraversalEpisodeStream.LastOrDefault(item =>
                    item != null && item.EpisodeId == cachedEpisode.EpisodeId);
                if (refreshedEpisode != null)
                {
                    canonicalEpisode = refreshedEpisode;
                }
            }

            durableEpisodeConsumed = canonicalEpisode != null &&
                canonicalEpisode.LearningV386ExecutionDebtConsumedByPhysicalPassage;
            if (durableEpisodeConsumed)
            {
                consumptionSource = string.IsNullOrWhiteSpace(
                        canonicalEpisode.LearningV386ExecutionDebtPhysicalPassageSource)
                    ? "canonicalEpisodePhysicalDebtFlag"
                    : canonicalEpisode.LearningV386ExecutionDebtPhysicalPassageSource;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId))
            {
                executionFloorBreadcrumbSequence = GetFollowerRouteExecutionFloor(profileId);
                routeResumeFloorBreadcrumbSequence = GetFollowerRouteResumeFloor(profileId);
                if (FollowerTraversalRouteCursors.TryGetValue(
                        profileId, out FollowerTraversalRouteCursor cursor) && cursor != null)
                {
                    cursorConsumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence;
                }
                routeResumeFloorBreadcrumbSequence = Math.Max(
                    routeResumeFloorBreadcrumbSequence,
                    Math.Max(executionFloorBreadcrumbSequence, cursorConsumedBreadcrumbSequence));
            }

            bool floorConsumed = canonicalEpisode != null && canonicalEpisode.EndBreadcrumbSequence > 0 &&
                canonicalEpisode.EndBreadcrumbSequence <= routeResumeFloorBreadcrumbSequence;
            if (!durableEpisodeConsumed && floorConsumed)
            {
                consumptionSource = "canonicalPostCompletionRouteFloor";
            }
            return durableEpisodeConsumed || floorConsumed;
        }


        private static bool TryResolveLearningV423ExecutionDebtConsumption(
            BotOwner bot,
            int episodeId,
            TraversalEpisodeMetadata fallbackEpisode,
            out TraversalEpisodeMetadata canonicalEpisode,
            out bool durableEpisodeConsumed,
            out int cursorConsumedBreadcrumbSequence,
            out int executionFloorBreadcrumbSequence,
            out int routeResumeFloorBreadcrumbSequence,
            out string consumptionSource)
        {
            canonicalEpisode = fallbackEpisode;
            if ((episodeId > 0))
            {
                TraversalEpisodeMetadata exact = TraversalEpisodeStream.LastOrDefault(item =>
                    item != null && item.EpisodeId == episodeId);
                if (exact != null)
                {
                    canonicalEpisode = exact;
                }
            }

            return TryResolveLearningV422CanonicalSuccessorDebtConsumption(
                bot,
                canonicalEpisode,
                out canonicalEpisode,
                out durableEpisodeConsumed,
                out cursorConsumedBreadcrumbSequence,
                out executionFloorBreadcrumbSequence,
                out routeResumeFloorBreadcrumbSequence,
                out consumptionSource);
        }

        private static bool TryFinalizeLearningV423PostCompletionMissionConsumer(
            ProbeRuntime probe,
            FollowerRouteMission missionAtEntry,
