                    successorForwardOffset,
                    currentRouteProjection,
                    successorRouteProjection
                });
                return false;
            }

            bool sameChainRollingContinuation =
                nextDistance <= TraversalChainIntermediateMaxDistance &&
                IsEffectivelySupportedForProbe(probe.Bot, probe.Player);
            string currentTraversalKind = probe.TraversalKind ?? probe.RequestedTraversalKind;
            bool learningV354ProfileAllowsOffMeshSuccessor = sameChainRollingContinuation &&
                LearningV354CanBridgeOffNavMesh(currentTraversalKind, nextEdge.Kind);
            bool offMeshBarrierToDropDown = (false);
            bool navStable = NavMesh.SamplePosition(
                    probe.Player.Position, out NavMeshHit navHit, UnifiedTraversalVerifyNavRadius, NavMesh.AllAreas) &&
                Mathf.Abs(navHit.position.y - probe.Player.Position.y) <= UnifiedTraversalVerifyMaxNavVertical;
            if (nextDistance > TraversalChainIntermediateMaxDistance ||
                !IsEffectivelySupportedForProbe(probe.Bot, probe.Player) ||
                (!navStable && !learningV354ProfileAllowsOffMeshSuccessor && !offMeshBarrierToDropDown))
            {
                return false;
            }

            if (learningV354ProfileAllowsOffMeshSuccessor)
            {
                WriteEvent("learningV354ProfileOffMeshSuccessorAccepted", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    nextEdgeId = nextEdge.Id,
                    currentKind = currentTraversalKind,
                    nextKind = nextEdge.Kind,
                    chainId = nextEpisode.ChainId,
                    nextDistance,
                    routeMissionPresent,
                    navSampled = navStable,
                    action = "capabilityProfileAuthorizesGenericOffMeshSuccessorTransaction"
                });
            }
            if (offMeshBarrierToDropDown)
            {
                WriteEvent(("learningV351BarrierToDropDownOffMeshContinuationAccepted"), probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
                    nextEdgeId = nextEdge.Id,
                    currentKind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                    nextKind = nextEdge.Kind,
                    chainId = nextEpisode.ChainId,
                    nextDistance,
                    routeMissionPresent,
                    navSampled = navStable,
                    position = Vec(probe.Player.Position),
                    nextEntry = Vec(nextEntry),
                    chainLocalDisabledDropDown = freshRaidLocalSuccessor
                });
            }

            if ((offMeshBarrierToDropDown) &&
                (string.Equals(currentTraversalKind, "Climb", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(currentTraversalKind, "Vault", StringComparison.OrdinalIgnoreCase)) &&
                IsFinite(nextEpisode.RawStart) && IsFinite(nextEpisode.RawEnd))
            {
                Vector3 successorAxis = nextEpisode.RawEnd - nextEpisode.RawStart;
                successorAxis.y = 0f;
                float successorSpan = successorAxis.magnitude;
                if (successorSpan > 0.001f)
                {
                    Vector3 successorDirection = successorAxis / successorSpan;
                    Vector3 successorFromEntry = probe.Player.Position - nextEpisode.RawStart;
                    successorFromEntry.y = 0f;
                    float successorEntryProjection = Vector3.Dot(successorFromEntry, successorDirection);
                    if (successorEntryProjection < NativeDropDownEntryMaxForwardOvershoot)
                    {
                        if (ShouldEmitDiagnostic(
                            "learningV386BarrierToDropDownEntryPlaneRetention:" +
                            probe.LearnedEdgeId.ToString(CultureInfo.InvariantCulture) + ":" +
                            nextEdge.Id.ToString(CultureInfo.InvariantCulture), probe.Bot, 0.20f))
                        {
                            WriteEvent("learningV386BarrierToDropDownEntryPlaneRetention", probe.Bot, new
                            {
                                edgeId = probe.LearnedEdgeId,
                                kind = currentTraversalKind,
                                nextEdgeId = nextEdge.Id,
                                nextKind = nextEdge.Kind,
                                chainId = nextEpisode.ChainId,
                                position = Vec(probe.Player.Position),
                                successorRawEntry = Vec(nextEpisode.RawStart),
                                successorRawExit = Vec(nextEpisode.RawEnd),
                                successorEntryProjection,
                                requiredProjection = NativeDropDownEntryMaxForwardOvershoot,
                                traversalSuccessRecorded = false,
                                persistentLearningChanged = false,
                                action = "keepBarrierProbeAliveUntilBodyReachesSuccessorEntryPlanePreventOriginSideDropBack"
                            });
                        }
                        return false;
                    }
                }
            }

            if (string.Equals(probe.TraversalKind ?? probe.RequestedTraversalKind, "Jump", StringComparison.OrdinalIgnoreCase) &&
                !probe.JumpPostLandingCommitSatisfied &&
                NeedsJumpPostLandingChainCommit(probe))
            {
                BeginJumpPostLandingChainCommit(probe, reason ?? "chainIntermediate");
                return true;
            }

            LearnedTraversalCommitment currentCommitment = null;
            TryGetLearnedCommitmentForProbe(probe, out currentCommitment);
            TraversalCompletionMode completionMode = GetTraversalCompletionMode(probe, "chainIntermediate");
            bool learningV382RouteBoundTransient =
                (IsLearningV319TransientSkillTransfer(currentCommitment)) &&
                currentCommitment.LearningV382RouteBoundTransientNativeSkill;
            if (learningV382RouteBoundTransient)
            {
                RecordLearningV322ZeroShotTemplateEvidence(
                    probe, currentCommitment, true, completionMode, "chainIntermediate");
                int learningV382PromotedEdgeId = 0;
                if (TryPromoteLearningV319TransientSkillInstance(
                        probe, currentCommitment, completionMode, "chainIntermediate",
                        out learningV382PromotedEdgeId))
                {
                    RecordTraversalExperience(
                        probe, true, completionMode, "chainIntermediate",
                        edgeIdOverride: learningV382PromotedEdgeId);
                }
                else
                {
                    EmitLearningV322TraversalAttemptSummary(
                        probe, true, completionMode, "chainIntermediate",
                        currentCommitment.SkillTemplateEdgeId);
                }
                WriteEvent("learningV382RouteBoundTransientNativeSkillCompleted", probe.Bot, new
                {
                    templateEdgeId = currentCommitment.SkillTemplateEdgeId,
                    promotedEdgeId = learningV382PromotedEdgeId,
                    episodeId = probe.TraversalEpisodeId,
                    chainId = probe.TraversalChainId,
                    kind = currentCommitment.Kind,
                    completionMode = completionMode.ToString(),
                    templatePersistentSuccessChanged = false,
                    action = "retainAuthoredChainIdentityWhileNativeReverseInstanceLearnsOnlyFromPhysicalSuccess"
                });
            }
            else
            {
                RecordTraversalExperience(probe, true, completionMode, "chainIntermediate");
                MarkLearnedTraversalEdgeSuccess(probe.LearnedEdgeId, completionMode, probe);
            }
            if (currentCommitment != null)
            {
                RegisterRecentTraversalCompletion(probe.Bot, probe.LearnedEdgeId, currentCommitment,
                    "chainIntermediate", completionMode, probe.LearningV322AttemptId, probe);
            }
            MarkFollowerTraversalEpisodeCompleted(probe, probe.TraversalEpisodeId, probe.LearnedEdgeId, probe.MovementWriterGeneration);
            if (TryFinalizeLearningV423PostCompletionMissionConsumer(
                    probe, routeMission, reason ?? "chainIntermediate"))
            {
                return true;
            }

            // V4.19: MarkFollowerTraversalEpisodeCompleted is allowed to consume one or more
            // downstream runtime steps when the predecessor body already physically spans them.
            // The cached nextEpisode/nextEdge above predates that write. Re-check the canonical
            // consumed breadcrumb floor NOW, immediately before any preload/dispatch. A successor
            // whose execution debt is already below the floor is historical route identity only.
            bool learningV422CanonicalSuccessorDebtConsumed =
                TryResolveLearningV422CanonicalSuccessorDebtConsumption(
                    probe.Bot, nextEpisode,
                    out TraversalEpisodeMetadata learningV422CanonicalSuccessorEpisode,
                    out bool learningV422DurableEpisodeConsumed,
                    out int learningV422CursorConsumedBreadcrumbSequence,
                    out int learningV422ExecutionFloorBreadcrumbSequence,
                    out int learningV422RouteResumeFloorBreadcrumbSequence,
                    out string learningV422ConsumptionSource);
            if ((learningV422CanonicalSuccessorEpisode != null))
            {
                // All dispatch below this point must use the post-completion canonical representation,
                // never the object captured before MarkFollowerTraversalEpisodeCompleted.
                nextEpisode = learningV422CanonicalSuccessorEpisode;
            }

            bool learningV421DurableSuccessorDebtConsumed = (nextEpisode != null) && nextEpisode.LearningV386ExecutionDebtConsumedByPhysicalPassage;
            bool learningV419CachedSuccessorDebtConsumed =
                learningV422CanonicalSuccessorDebtConsumed || learningV421DurableSuccessorDebtConsumed;
            int learningV419ConsumedBreadcrumbSequence =
                learningV422CursorConsumedBreadcrumbSequence;
            int learningV419RouteResumeFloor = Math.Max(
                learningV422RouteResumeFloorBreadcrumbSequence,
                learningV422ExecutionFloorBreadcrumbSequence);
            if ((nextEpisode != null) &&
                nextEpisode.EndBreadcrumbSequence > 0 && !string.IsNullOrEmpty(routeProfileId))
            {
                if (FollowerTraversalRouteCursors.TryGetValue(
                        routeProfileId, out FollowerTraversalRouteCursor learningV419Cursor) &&
                    learningV419Cursor != null)
                {
                    learningV419ConsumedBreadcrumbSequence = Math.Max(
                        learningV419ConsumedBreadcrumbSequence,
                        learningV419Cursor.ConsumedBreadcrumbSequence);
                }
                learningV419RouteResumeFloor = Math.Max(
                    learningV419RouteResumeFloor,
                    Math.Max(
                        GetFollowerRouteExecutionFloor(routeProfileId),
                        Math.Max(
                            GetFollowerRouteResumeFloor(routeProfileId),
                            learningV419ConsumedBreadcrumbSequence)));
                learningV419CachedSuccessorDebtConsumed = learningV419CachedSuccessorDebtConsumed ||
                    nextEpisode.EndBreadcrumbSequence <= learningV419RouteResumeFloor;
            }
            if (learningV419CachedSuccessorDebtConsumed)
            {
                int learningV419CompletedEdgeId = probe.LearnedEdgeId;
                ClearLearnedTraversalCommitment(
                    probe.Bot, learningV419CompletedEdgeId,
                    "learningV419PhysicallySubsumedSuccessorDispatchSuppressed");
                if (nextEdge != null)
                {
                    ClearLearnedTraversalCommitment(
                        probe.Bot, nextEdge.Id,
                        "learningV419PhysicallySubsumedSuccessorDispatchSuppressed");
                }
                ChainHandoffAuthorityGuards.Remove(routeProfileId);
                RestoreAssistedObstacleCollisionLease(
                    probe, "learningV419PhysicallySubsumedSuccessorDispatchSuppressed");
                RestoreAssistedTraversalAnimation(probe);

                bool learningV419RemainingMissionPresent =
                    FollowerRouteMissions.TryGetValue(
                        routeProfileId, out FollowerRouteMission learningV419RemainingMission) &&
                    learningV419RemainingMission != null;
                if ((learningV422CanonicalSuccessorDebtConsumed))
                {
                    WriteEvent("learningV422CanonicalSuccessorDebtRequerySuppressedResurrection", probe.Bot, new
                    {
                        completedEdgeId = learningV419CompletedEdgeId,
                        completedEpisodeId = probe.TraversalEpisodeId,
                        successorEdgeId = nextEdge?.Id ?? 0,
                        successorEpisodeId = nextEpisode?.EpisodeId ?? 0,
                        successorKind = nextEdge?.Kind,
                        successorEndBreadcrumbSequence = nextEpisode?.EndBreadcrumbSequence ?? 0,
                        durableEpisodeConsumed = learningV422DurableEpisodeConsumed,
                        cursorConsumedBreadcrumbSequence = learningV422CursorConsumedBreadcrumbSequence,
                        executionFloorBreadcrumbSequence = learningV422ExecutionFloorBreadcrumbSequence,
                        routeResumeFloorBreadcrumbSequence = learningV422RouteResumeFloorBreadcrumbSequence,
                        consumptionSource = learningV422ConsumptionSource,
                        traversalSuccessRecordedForSuccessor = false,
                        persistentLearningChangedForSuccessor = false,
                        bodyRelocated = false,
                        action = "postCompletionCanonicalIdentityOutranksPreMarkCachedSuccessorBeforeAnyPreloadOrHandoff"
                    });
                }
                if (learningV421DurableSuccessorDebtConsumed)
                {
                    WriteEvent("learningV421PhysicallyConsumedSuccessorRepresentationResurrectionSuppressed", probe.Bot, new
                    {
                        completedEdgeId = learningV419CompletedEdgeId,
                        completedEpisodeId = probe.TraversalEpisodeId,
                        successorEdgeId = nextEdge?.Id ?? 0,
                        successorEpisodeId = nextEpisode.EpisodeId,
                        successorKind = nextEdge?.Kind,
                        chainId = nextEpisode.ChainId,
                        consumedBreadcrumbSequence = learningV419ConsumedBreadcrumbSequence,
                        successorEndBreadcrumbSequence = nextEpisode.EndBreadcrumbSequence,
                        consumptionSource = nextEpisode.LearningV386ExecutionDebtPhysicalPassageSource,
                        traversalSuccessRecordedForSuccessor = false,
                        persistentLearningChangedForSuccessor = false,
                        bodyRelocated = false,
                        action = "canonicalPhysicalDebtConsumptionOutranksCachedMissionShadowAndLegacyChainRepresentations"
                    });
                }
                WriteEvent("learningV419PhysicallySubsumedSuccessorDispatchSuppressed", probe.Bot, new
                {
                    completedEdgeId = learningV419CompletedEdgeId,
                    completedEpisodeId = probe.TraversalEpisodeId,
                    nextEdgeId = nextEdge?.Id ?? 0,
                    authoredNextEdgeId = nextEpisode.EdgeId,
                    nextEpisodeId = nextEpisode.EpisodeId,
                    nextKind = nextEdge?.Kind,
                    chainId = nextEpisode.ChainId,
                    consumedBreadcrumbSequence = learningV419ConsumedBreadcrumbSequence,
                    routeResumeFloor = learningV419RouteResumeFloor,
                    successorEndBreadcrumbSequence = nextEpisode.EndBreadcrumbSequence,
                    learningV421DurableSuccessorDebtConsumed,
                    learningV421DebtConsumptionSource = nextEpisode.LearningV386ExecutionDebtPhysicalPassageSource,
                    remainingMission = learningV419RemainingMissionPresent,
                    remainingMissionId = learningV419RemainingMission?.MissionId ?? 0,
                    traversalSuccessRecordedForSuccessor = false,
                    persistentLearningChangedForSuccessor = false,
                    bodyRelocated = false,
                    action = "consumedExecutionDebtCannotBePreloadedOrDispatchedFromCachedChainSuccessor"
                });

                DetachProbeStateHandler(probe);
                UnregisterActiveProbe(probe);
                if (learningV419RemainingMissionPresent)
                {
                    UpdateLearningV375PersistentExecutablePhysicalRouteTransaction(probe.Bot);
                }
                else if (routeMission != null)
                {
                    FinalizeLearningV382TerminalRouteFreshFollowFrontier(
                        probe.Bot, routeMission,
                        "learningV419PhysicallySubsumedSuccessorDispatchSuppressed");
                }
                else
                {
                    EndLearningV375PersistentRouteTransaction(
                        probe.Bot, "learningV419PhysicallySubsumedSuccessorDispatchSuppressed");
                    TryRetireNativeMoverPathPreserveLocomotion(
                        probe.Bot, "learningV419PhysicallySubsumedSuccessorDispatchSuppressed",
                        out string learningV419TerminalRetireDetail);
                    TryScrubLearningV364NativeMoverEpochAnchor(
                        probe.Bot, probe.Bot.Position,
                        "learningV419PhysicallySubsumedSuccessorDispatchSuppressed",
                        out string learningV419TerminalScrubDetail);
                    long learningV419TerminalTraversalGeneration =
                        FollowerMovementWriterAuthority.GetCurrentGeneration(
                            probe.Bot, out FollowerMovementWriterAuthority.WriterDomain learningV419TerminalOwner);
                    string learningV419TerminalPrimeDetail = "terminalOwnerNotTraversal:" +
                        learningV419TerminalOwner;
                    string learningV423TerminalPhysicalContinuationDetail = string.Empty;
                    bool learningV419TerminalFollowPrimed =
                        learningV419TerminalOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                        TryHandoffLearningV419TraversalToFreshFollowConsumer(
                            probe.Bot, learningV419TerminalTraversalGeneration,
                            "learningV419PhysicallySubsumedSuccessorDispatchSuppressed",
                            "post-traversal-fresh-epoch", out learningV419TerminalPrimeDetail);
                    bool learningV423TerminalPhysicalContinuationInstalled = false;
                    if ((!learningV419TerminalFollowPrimed))
                    {
                        long learningV423TerminalGeneration =
                            FollowerMovementWriterAuthority.GetCurrentGeneration(
                                probe.Bot,
                                out FollowerMovementWriterAuthority.WriterDomain learningV423TerminalOwner);
                        learningV423TerminalPhysicalContinuationInstalled =
                            learningV423TerminalOwner == FollowerMovementWriterAuthority.WriterDomain.Traversal &&
                            learningV423TerminalGeneration > 0 &&
                            TryInstallLearningV423PhysicalContinuationConsumer(
                                probe.Bot, learningV423TerminalGeneration,
                                "learningV423PhysicallySubsumedSuccessorPhysicalContinuation",
                                out learningV423TerminalPhysicalContinuationDetail);
                    }
                    WriteEvent("learningV419ConsumedSuccessorTerminalConsumerResolved", probe.Bot, new
                    {
                        body = Vec(probe.Bot.Position),
                        staleTopologyDetail = learningV419TerminalRetireDetail,
                        epochScrubDetail = learningV419TerminalScrubDetail,
                        freshFollowPrimed = learningV419TerminalFollowPrimed,
                        freshFollowDetail = learningV419TerminalPrimeDetail,
                        physicalContinuationInstalled = learningV423TerminalPhysicalContinuationInstalled,
                        physicalContinuationDetail = learningV423TerminalPhysicalContinuationDetail,
                        bodyRelocated = false,
                        traversalSuccessRecorded = false,
                        persistentLearningChanged = false
                    });
                }
                return true;
            }

            // V3.99 closes a lifetime hole in CompileFix9's RouteMission-authoritative contract.
            // The mission can legitimately become terminal inside MarkFollowerTraversalEpisodeCompleted
            // (for example because V382 proved an immediate successor was already physically subsumed).
            // The predecessor probe is still active at that instant, so V382's terminal fresh-Follow
            // finalizer intentionally waits. Do not let the legacy raw-episode chain see the now-absent
            // mission and recreate that retired successor before the probe is unregistered.
            bool learningV399AuthoritativeMissionTerminalAfterPredecessor =
                (routeMissionPresent) && routeMission != null &&
                !string.IsNullOrEmpty(routeProfileId) &&
                (!FollowerRouteMissions.TryGetValue(
                    routeProfileId, out FollowerRouteMission learningV399RemainingMission) ||
                 learningV399RemainingMission == null);
            if (learningV399AuthoritativeMissionTerminalAfterPredecessor)
            {
                int learningV399CompletedEdgeId = probe.LearnedEdgeId;
                bool learningV399SuccessorRuntimeDebtAlreadyConsumed = false;
                int learningV399ConsumedBreadcrumbSequence = 0;
                int learningV399SuccessorEndBreadcrumbSequence = nextEpisode?.EndBreadcrumbSequence ?? 0;
                if (FollowerTraversalRouteCursors.TryGetValue(
                        routeProfileId, out FollowerTraversalRouteCursor learningV399Cursor) &&
                    learningV399Cursor != null)
                {
                    learningV399ConsumedBreadcrumbSequence = learningV399Cursor.ConsumedBreadcrumbSequence;
                    learningV399SuccessorRuntimeDebtAlreadyConsumed = nextEpisode != null &&
                        nextEpisode.EndBreadcrumbSequence > 0 &&
                        learningV399Cursor.ConsumedBreadcrumbSequence >= nextEpisode.EndBreadcrumbSequence;
                }

                // The current action already completed through its normal success path above. The
                // successor is NOT credited here; this only preserves the authoritative runtime
                // ordering decision and prevents legacy commitment resurrection.
                ClearLearnedTraversalCommitment(
                    probe.Bot, learningV399CompletedEdgeId,
                    "learningV399AuthoritativeRouteMissionTerminalHandoffClosure");
                ChainHandoffAuthorityGuards.Remove(routeProfileId);
                RestoreAssistedObstacleCollisionLease(
                    probe, "learningV399AuthoritativeRouteMissionTerminalHandoffClosure");
                RestoreAssistedTraversalAnimation(probe);
                RecordLearningV354ActionOutcome(
                    currentTraversalKind, true, false,
                    "learningV399AuthoritativeRouteMissionTerminalHandoffClosure");
                WriteEvent("learningV399LegacyChainSuccessorResurrectionSuppressed", probe.Bot, new
                {
                    missionId = routeMission.MissionId,
                    completedEdgeId = learningV399CompletedEdgeId,
                    completedEpisodeId = probe.TraversalEpisodeId,
                    nextEdgeId = nextEdge?.Id ?? 0,
                    nextEpisodeId = nextEpisode?.EpisodeId ?? 0,
                    nextKind = nextEdge?.Kind,
                    chainId = nextEpisode?.ChainId ?? 0,
                    successorRuntimeDebtAlreadyConsumed = learningV399SuccessorRuntimeDebtAlreadyConsumed,
                    consumedBreadcrumbSequence = learningV399ConsumedBreadcrumbSequence,
                    successorEndBreadcrumbSequence = learningV399SuccessorEndBreadcrumbSequence,
                    traversalSuccessRecordedForSuccessor = false,
                    persistentLearningChangedForSuccessor = false,
                    bodyRelocated = false,
                    action = "routeMissionWasAuthoritativeAtHandoffEntryAndIsNowTerminalDoNotFallbackToLegacyRawEpisodeChain"
                });

                DetachProbeStateHandler(probe);
                UnregisterActiveProbe(probe);
                FinalizeLearningV382TerminalRouteFreshFollowFrontier(
                    probe.Bot, routeMission,
                    "learningV399AuthoritativeRouteMissionTerminalHandoffClosure");
                return true;
            }

            bool consumedMicroEdge = TryConsumeAdjacentWalkThroughMicroEdge(probe, nextEpisode, nextEdge);

            int completedEdgeId = probe.LearnedEdgeId;
            bool learningV353SuccessorPreloaded = false;
            {
                // Producer ordering is successor-first: after route cursor advancement, install the
                // exact next commitment while predecessor locomotion is still alive. Only when that
                // proof fails do we fall back to V3.51's stop/scrub boundary.
                learningV353SuccessorPreloaded = consumedMicroEdge
                    ? TryPreloadNextTraversalChainCommitment(probe.Bot, nextEpisode.EpisodeId, nextEdge.Id)
                    : TryPreloadNextTraversalChainCommitment(probe.Bot, probe.TraversalEpisodeId, completedEdgeId);
                WriteEvent("learningV353SuccessorPreloadBeforePredecessorRetire", probe.Bot, new
                {
                    edgeId = completedEdgeId,
                    nextEdgeId = nextEdge.Id,
                authoredNextEdgeId = nextEpisode.EdgeId,
                    nextEpisodeId = nextEpisode.EpisodeId,
                    chainId = nextEpisode.ChainId,
                    preloaded = learningV353SuccessorPreloaded,
                    action = learningV353SuccessorPreloaded
                        ? "keepLocomotionAliveUntilExactSuccessorAcquiresTraversal"
                        : "fallBackToV351StaleMoverRetirement"
                });
            }
            if ((!learningV353SuccessorPreloaded))
            {
                bool chainMoverRebased = TryRetireNativeMoverPathAtCurrentBody(
                    probe.Bot, "chainIntermediate", out string chainMoverRebaseDetail);
                WriteEvent("learningV351ChainStaleMoverRetired", probe.Bot, new
                {
                    edgeId = completedEdgeId,
                    nextEdgeId = nextEdge.Id,
                authoredNextEdgeId = nextEpisode.EdgeId,
                    chainId = nextEpisode.ChainId,
                    position = Vec(probe.Player.Position),
                    rebased = chainMoverRebased,
                    detail = chainMoverRebaseDetail,
                    action = "retirePredecessorNativePathBeforeSuccessorOwnsMovementNoRelocationWriter"
                });
            }
            // CompileFix31: do not restore pre-traversal input here. That vector belongs to the
            // approach before the completed edge and can point back toward the old Mover route.
            // Retire the old route atomically and keep a short chain-authority barrier until the
            // preloaded successor probe takes ownership.
            ArmChainHandoffAuthorityGuard(
                probe,
                completedEdgeId,
                nextEdge.Id,
                nextEpisode.EpisodeId,
                nextEpisode.ChainId,
                nextEntry,
                navStable,
                learningV353SuccessorPreloaded);
            PreserveTraversalChainMovementContinuity(
                probe.Bot,
                completedEdgeId,
                nextEdge.Id,
                probe.TraversalChainId,
                probe.PreviousSprinting,
                probe.PreviousRunning);
            // CompileFix31: do not unconditionally release Mover.Pause here. Off-NavMesh chain
            // handoffs deliberately keep the stale mover writer paused until RegisterActiveProbe
            // installs the successor or the bounded guard expires.
            ClearLearnedTraversalCommitment(probe.Bot, completedEdgeId, "chainIntermediateCompleted");
            if (!learningV353SuccessorPreloaded)
            {
                if (consumedMicroEdge)
                {
                    TryPreloadNextTraversalChainCommitment(probe.Bot, nextEpisode.EpisodeId, nextEdge.Id);
                }
                else
                {
                    TryPreloadNextTraversalChainCommitment(probe.Bot, probe.TraversalEpisodeId, completedEdgeId);
                }
            }
            RecordLearningV354ActionOutcome(currentTraversalKind, true, false, "chainIntermediate");
            RecordLearningV354TransitionOutcome(currentTraversalKind, nextEdge.Kind, learningV353SuccessorPreloaded, false,
                learningV353SuccessorPreloaded ? "exactSuccessorPreloaded" : "routeMissionFallback");
            WriteEvent("traversalChainIntermediateCompleted", probe.Bot, new
            {
                edgeId = completedEdgeId,
                nextEdgeId = nextEdge.Id,
                authoredNextEdgeId = nextEpisode.EdgeId,
                nextEpisodeId = nextEpisode.EpisodeId,
                chainId = nextEpisode.ChainId,
                reason,
                position = Vec(probe.Player.Position),
                nextEntry = Vec(nextEntry),
                nextDistance,
                consumedMicroEdge
            });
            DetachProbeStateHandler(probe);
            UnregisterActiveProbe(probe);
            if ((learningV353SuccessorPreloaded || learningV354ProfileAllowsOffMeshSuccessor || offMeshBarrierToDropDown) && !consumedMicroEdge)
            {
                // V3.7 producer-ordering convergence: the V3.6 trace proved that waiting one BotOwner
                // update let the physical WT body (~0.47m from the DropDown entry) fall back to stale
                // mover state (~1.68m) before the successor probe existed. Reuse the existing guarded
                // successor dispatcher immediately after retiring the predecessor. No teleport, no
                // new movement primitive, and no extra retry budget are introduced.
                UpdateChainHandoffAuthorityGuard(probe.Bot);
                bool immediateSuccessorActive = TryGetActiveProbe(probe.Bot, out ProbeRuntime immediateSuccessorProbe) &&
                    immediateSuccessorProbe != null && immediateSuccessorProbe.LearnedEdgeId == nextEdge.Id &&
                    immediateSuccessorProbe.TraversalChainId == nextEpisode.ChainId;
                WriteEvent("traversalChainImmediateSuccessorDispatch", probe.Bot, new
                {
                    completedEdgeId,
                    nextEdgeId = nextEdge.Id,
                authoredNextEdgeId = nextEpisode.EdgeId,
                    nextEpisodeId = nextEpisode.EpisodeId,
                    chainId = nextEpisode.ChainId,
                    physicalPosition = Vec(probe.Player.Position),
                    nextEntry = Vec(nextEntry),
                    nextDistance = GetPlanarDistance(probe.Player.Position, nextEntry),
                    successorActive = immediateSuccessorActive,
                    successorStage = immediateSuccessorActive ? immediateSuccessorProbe.Stage.ToString() : null
                });
            }
            return true;
        }

        private static bool TryPublishLearningV412MotionCarryingSuccessorLease(
            BotOwner bot,
            LearnedTraversalEdge successorEdge,
            Vector3 successorEntry,
            bool sprint,
            string source,
            int completedEdgeId,
            int successorEdgeId)
        {
            if ((bot?.Mover == null) ||
                successorEdge == null || !IsFinite(successorEntry))
            {
                return false;
            }

            Player player = bot.GetPlayer;
            if (player?.MovementContext == null)
            {
                return false;
            }

            Vector3 rawStart = successorEdge.HasSettledStart && IsFinite(successorEdge.SettledStart)
                ? successorEdge.SettledStart
                : successorEdge.RawStart;
            Vector3 rawEnd = successorEdge.HasSettledEnd && IsFinite(successorEdge.SettledEnd)
                ? successorEdge.SettledEnd
                : successorEdge.RawEnd;
            Vector3 axis = GetFlatDirection(rawEnd - rawStart);
            Vector3 entryOffset = player.Position - rawStart;
            entryOffset.y = 0f;
            float forwardEntryProjection = axis.sqrMagnitude > 0.000001f
                ? Vector3.Dot(entryOffset, axis)
                : -1f;
            bool bodyAtOrBeyondEntry = axis.sqrMagnitude > 0.000001f && forwardEntryProjection >= 0f;
            Vector3 direction = bodyAtOrBeyondEntry ? axis : GetFlatDirection(successorEntry - player.Position);
            if (!IsFinite(direction) || direction.sqrMagnitude <= 0.000001f)
            {
                direction = axis;
            }
            if (!IsFinite(direction) || direction.sqrMagnitude <= 0.000001f)
            {
                return false;
            }
            direction.Normalize();

            bool demonstratedSprint = string.Equals(
                successorEdge.ApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase);
            bool profileLeaseSprint = sprint || demonstratedSprint;
            bool preserveMode = true;
            bool currentSprintMode = bot.Mover.Sprinting || player.CurrentStateName == EPlayerState.Sprint;
            bool leaseSprint = preserveMode ? currentSprintMode : profileLeaseSprint;
            float dt = Mathf.Max(0.001f, Time.deltaTime);
            float targetMoveSpeed = profileLeaseSprint ? ProbeMomentumFullMoveSpeed : LearningV357RouteEnvelopeRunSpeed;
            Vector3 intentToken = direction * Mathf.Max(0.001f, ChainLocalSuccessorBridgeSpeed * dt);
            if (string.IsNullOrEmpty(bot.ProfileId) ||
                !ChainHandoffAuthorityGuards.TryGetValue(bot.ProfileId, out ChainHandoffAuthorityGuard liveChain) ||
                liveChain.CompletedEdgeId != completedEdgeId || liveChain.NextEdgeId != successorEdgeId ||
                liveChain.MovementWriterGeneration <= 0)
                return false;
            if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                bot, FollowerMovementWriterAuthority.WriterDomain.Traversal,
                liveChain.MovementWriterGeneration,
                out FollowerMovementWriterAuthority.WriteScope physicalScope, out _))
                return false;
            using (physicalScope)
            {
                if (!(ApplyCollisionActivePhysicalRouteMotion(
                    bot, player, direction, intentToken, dt, 1f, leaseSprint,
                    targetMoveSpeed, preserveSprintMode: preserveMode,deliveryTarget:bodyAtOrBeyondEntry ? rawEnd : successorEntry,deliveryPurpose:CapabilityMotionPurpose.TypedRoute)).Accepted)
                    return false;
            }

            if (ShouldEmitDiagnostic(
                    "learningV412MotionCarryingChainLease:" +
                    completedEdgeId.ToString(CultureInfo.InvariantCulture) + ":" +
                    successorEdgeId.ToString(CultureInfo.InvariantCulture), bot, 0.12f))
            {
                WriteEvent("learningV412MotionCarryingChainLeasePublished", bot, new
                {
                    completedEdgeId,
                    successorEdgeId,
                    successorKind = successorEdge.Kind ?? string.Empty,
                    source = source ?? string.Empty,
                    state = player.CurrentStateName.ToString(),
                    position = Vec(player.Position),
                    successorEntry = Vec(successorEntry),
                    requestedSprint = sprint,
                    demonstratedApproachMode = successorEdge.ApproachMode ?? string.Empty,
                    profileLeaseSprint,
                    leaseSprint,
                    preserveSprintMode = preserveMode,
                    forwardEntryProjection,
                    bodyAtOrBeyondEntry,
                    directionSource = bodyAtOrBeyondEntry ? "successorForwardAxis" : "entryConvergence",
                    targetMoveSpeed,
                    bodyRelocated = false,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    action = "carryExistingNativePlayerMoveProducerAcrossSuccessorBoundaryUntilSuccessorOwnsNextFrame"
                });
            }
            return true;
        }

        private static void PreserveTraversalChainMovementContinuity(
            BotOwner bot,
            int completedEdgeId,
            int nextEdgeId,
            int chainId,
            bool intendedSprinting,
            bool intendedRunning)
        {
            if (bot == null)
            {
                return;
            }

            LearnedTraversalEdge continuityNextEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == nextEdgeId);
            bool learningV357SuccessorNeedsSprintMomentum =
                (string.Equals(continuityNextEdge?.Kind, "Jump", StringComparison.OrdinalIgnoreCase));
            bool sprinting = intendedSprinting;
            bool moving = intendedRunning || intendedSprinting;
            if ((!learningV357SuccessorNeedsSprintMomentum) &&
                false)
            {
                sprinting = false;
                moving = true;
            }
            if ((bot.Mover != null))
            {
                sprinting = sprinting || bot.Mover.Sprinting;
                moving = moving || bot.Mover.IsMoving || sprinting;
            }
            try
            {
                // CompileFix31 preserves locomotion intent (run/sprint/speed), not the old path.
                // ArmChainHandoffAuthorityGuard has already rebased/scrubbed the previous mover
                // destination. Off-NavMesh handoffs may keep Mover paused for a few frames until the
                // successor probe acquires authority; do not unpause that protective barrier here.
                if (bot.Mover != null)
                {
                    bool chainBarrierActive = AllowsFollowDuringChainHandoff(bot);
                    bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-3F639E0E6C3D",@bot);
                    if (!chainBarrierActive)
                    {
                        bot.Mover.SetBotMoverPause("R1-3E1EDE60DEA2",@bot,false);
                        float continuitySpeed = (sprinting)
                            ? ProbeMomentumFullMoveSpeed
                            : ((!learningV357SuccessorNeedsSprintMomentum)
                                ? LearningV357RouteEnvelopeRunSpeed
                                : ProbeMomentumFullMoveSpeed);
                        bot.BotOwnerSetTargetMoveSpeed("R1-BFEED5CA48A8",@bot,continuitySpeed);
                        bot.Mover.BotMoverSetTargetMoveSpeed("R1-A5438E15C61F",@bot,continuitySpeed);
                        moving = moving || bot.Mover.IsMoving;
                        if ((!learningV357SuccessorNeedsSprintMomentum) &&
                            false)
                        {
                            if (bot.Mover.Sprinting)
                            {
                                bot.Mover.BotMoverSprint("R1-4FBEEA2E24A3",@bot,false,false);
                            }
                            sprinting = false;
                        }
                        else
                        {
                            sprinting = sprinting || bot.Mover.Sprinting;
                            if (sprinting && !bot.Mover.Sprinting)
                            {
                                bot.Mover.BotMoverSprint("R1-F0AE463627DE",@bot,true,false);
                            }
                        }
                    }
                    else ;
                }
            }
            catch
            {
            }

            if ((continuityNextEdge != null))
            {
                Vector3 continuityEntry = continuityNextEdge.HasSettledStart && IsFinite(continuityNextEdge.SettledStart)
                    ? continuityNextEdge.SettledStart
                    : continuityNextEdge.RawStart;
                TryPublishLearningV412MotionCarryingSuccessorLease(
                    bot, continuityNextEdge, continuityEntry, sprinting,
                    "chainIntermediate", completedEdgeId, nextEdgeId);
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (!string.IsNullOrEmpty(profileId) && chainId > 0)
            {
                TraversalChainLocomotionIntents[profileId] = new TraversalChainLocomotionIntent
                {
                    ChainId = chainId,
                    Sprinting = sprinting,
                    Running = moving || sprinting,
                    ExpiresAt = Time.time + 6.0f,
                    Source = "chainIntermediate"
                };
            }

            WriteEvent("traversalChainMovementContinuityPreserved", bot, new
            {
                completedEdgeId,
                nextEdgeId,
                chainId,
                position = Vec(bot.Position),
                sprinting,
                moving,
                targetMoveSpeed = (sprinting)
                    ? ProbeMomentumFullMoveSpeed
                    : ((!learningV357SuccessorNeedsSprintMomentum)
                        ? LearningV357RouteEnvelopeRunSpeed
                        : ProbeMomentumFullMoveSpeed)
            });
        }

        private static void ArmChainHandoffAuthorityGuard(
            ProbeRuntime probe,
            int completedEdgeId,
            int nextEdgeId,
            int nextEpisodeId,
            int chainId,
            Vector3 nextEntry,
            bool navStable,
            bool successorPreloaded)
        {
            if (probe?.Bot == null || probe.Player?.MovementContext == null || string.IsNullOrEmpty(probe.Bot.ProfileId))
            {
                return;
            }

            TraversalEpisodeMetadata learningV423ArmEpisode = nextEpisodeId > 0
                ? TraversalEpisodeStream.LastOrDefault(item =>
                    item != null && item.EpisodeId == nextEpisodeId)
                : TraversalEpisodeStream.LastOrDefault(item =>
                    item != null && item.EdgeId == nextEdgeId &&
                    (chainId <= 0 || item.ChainId == chainId));
            bool learningV423ArmDebtConsumed =
                TryResolveLearningV423ExecutionDebtConsumption(
                    probe.Bot, nextEpisodeId, learningV423ArmEpisode,
                    out TraversalEpisodeMetadata learningV423CanonicalArmEpisode,
                    out bool learningV423ArmDurableConsumed,
                    out int learningV423ArmCursorFloor,
                    out int learningV423ArmExecutionFloor,
                    out int learningV423ArmResumeFloor,
                    out string learningV423ArmConsumptionSource);
            if ((learningV423ArmDebtConsumed))
            {
                ClearLearnedTraversalCommitment(
                    probe.Bot, nextEdgeId,
                    "learningV423ConsumedSuccessorGuardArmSuppressed");
                ChainHandoffAuthorityGuards.Remove(probe.Bot.ProfileId);
                WriteEvent("learningV423ConsumedSuccessorGuardArmSuppressed", probe.Bot, new
                {
                    completedEdgeId,
                    nextEdgeId,
                    nextEpisodeId = learningV423CanonicalArmEpisode?.EpisodeId ?? nextEpisodeId,
                    chainId,
                    successorEndBreadcrumbSequence =
                        learningV423CanonicalArmEpisode?.EndBreadcrumbSequence ?? 0,
                    durableEpisodeConsumed = learningV423ArmDurableConsumed,
                    cursorConsumedBreadcrumbSequence = learningV423ArmCursorFloor,
                    executionFloorBreadcrumbSequence = learningV423ArmExecutionFloor,
                    routeResumeFloorBreadcrumbSequence = learningV423ArmResumeFloor,
                    consumptionSource = learningV423ArmConsumptionSource,
                    traversalSuccessRecordedForSuccessor = false,
                    persistentLearningChangedForSuccessor = false,
                    bodyRelocated = false,
                    action = "consumedExecutionDebtCannotCreateLegacyChainGuard"
                });
                return;
            }

            Vector3 anchor = probe.Player.Position;
            LearnedTraversalEdge nextEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == nextEdgeId);
            string completedKindForProfile = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty;
            string successorKindForProfile = nextEdge?.Kind ?? string.Empty;
            bool continuousWalkThroughDropDownPassage = (false);
            bool continuousExactSuccessor = (successorPreloaded) &&
                ((LearningV354CanUseContinuousSuccessor(completedKindForProfile, successorKindForProfile, successorPreloaded)));
            bool learningV357ContinuousRouteEnvelope = (nextEdge != null) && IsFinite(nextEntry) &&
                GetPlanarDistance(anchor, nextEntry) <= RouteMissionTraversalAdjacentBridgeMaxDistance;
            bool continuousMoverHandoff =
                FollowerCapabilityHelperRules.ArmChainHandoffAuthorityGuard_continuousMoverHandoff_EA50166F_1(continuousWalkThroughDropDownPassage,continuousExactSuccessor,learningV357ContinuousRouteEnvelope);
            Vector3 staleDestination = Vector3.zero;
            bool haveStaleDestination = false;
            try
            {
                if (probe.Bot.Mover != null)
                {
                    staleDestination = probe.Bot.Mover.RealDestPoint;
                    haveStaleDestination = IsFinite(staleDestination);
                }
            }
            catch
            {
            }

            {
                LearnedTraversalEdge completedEpochEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                    candidate != null && candidate.Id == completedEdgeId);
                Vector3 completedEpochEntry = completedEpochEdge != null
                    ? (completedEpochEdge.HasSettledStart && IsFinite(completedEpochEdge.SettledStart)
                        ? completedEpochEdge.SettledStart
                        : completedEpochEdge.RawStart)
                    : anchor;
                Vector3 completedEpochExit = completedEpochEdge != null
                    ? (completedEpochEdge.HasSettledEnd && IsFinite(completedEpochEdge.SettledEnd)
                        ? completedEpochEdge.SettledEnd
                        : completedEpochEdge.RawEnd)
                    : anchor;
                ArmLearningV364PhysicalNavigationEpochHandoff(
                    probe.Bot,
                    completedEdgeId,
                    probe.TraversalEpisodeId,
                    chainId,
                    completedEpochEntry,
                    completedEpochExit,
                    anchor,
                    "chainHandoff:" + completedEdgeId.ToString(CultureInfo.InvariantCulture) +
                    "->" + nextEdgeId.ToString(CultureInfo.InvariantCulture));
            }

            RestoreAssistedObstacleCollisionLease(probe, "chainHandoffAuthority");
            RestoreAssistedTraversalAnimation(probe);

            // V3.76 completes the V3.70 Phase-2 ownership model: once the persistent RouteMission
            // transaction already owns the canonical/proven-parent successor, the old per-edge
            // ChainHandoff guard is no longer an execution authority. Keeping it alive would let
            // legacy Stop/Pause/snapback/Teleport correction race the persistent route producer.
            if ((TryGetLearningV376PersistentMissionSuccessorOwnership(
                    probe.Bot, nextEdgeId, out FollowerTraversalRouteCursor learningV376RouteCursor,
                    out FollowerRouteMission learningV376RouteMission)))
            {
                ChainHandoffAuthorityGuards.Remove(probe.Bot.ProfileId);
                try
                {
                    if (probe.Bot.Mover != null)
                    {
                        probe.Bot.Mover.SetBotMoverPause("R1-21438F009CFB",@probe?.Bot,false);
                        probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-3C935D57C0C5",@probe?.Bot);
                    }
                }
                catch
                {
                }
                WriteEvent("learningV376LegacyChainHandoffGuardYieldedToPersistentMission", probe.Bot, new
                {
                    completedEdgeId,
                    requestedSuccessorEdgeId = nextEdgeId,
                    provenanceChainId = chainId,
                    missionId = learningV376RouteMission.MissionId,
                    currentStepIndex = learningV376RouteMission.CurrentStepIndex,
                    generation = learningV376RouteCursor.LearningV375MovementGeneration,
                    action = "persistentRouteMissionOwnsIntermediateBoundaryNoLegacyStopPauseSnapbackOrTeleport"
                });
                return;
            }

            try
            {
                probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoVault("R1-0899C8C4CCEE",@probe?.Bot,false);
                probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoClimb("R1-0CD1111AD9A8",@probe?.Bot,false);
                if (!continuousMoverHandoff && probe.Bot.GoToSomePointData != null)
                {
                    probe.Bot.GoToSomePointData.BotGoToPointDataSetPoint("R1-CFEFBA5D9C30",@probe?.Bot,anchor);
                    probe.Bot.GoToSomePointData.BotGoToPointDataUpdateToGo("R1-2B5DBD055F5D",@probe?.Bot,false);
                }
                if (probe.Bot.Mover != null)
                {
                    probe.Bot.Mover.LocalAvoidance?.GClass492DropOffset("R1-646AE6B5853F",@probe?.Bot);
                    if (continuousMoverHandoff)
                    {
                        // V3.57 extends successor-first continuity across bounded ordinary ground
                        // segments. Never convert a Sprint boundary into Stop/Pause; taper to Run and
                        // let the successor/route producer take over on the next writer generation.
                        probe.Bot.Mover.SetBotMoverPause("R1-41126A00D218",@probe?.Bot,false);
                        {
                            bool preserveSprint = ((probe.PreviousSprinting || probe.Bot.Mover.Sprinting));
                            if (!preserveSprint && probe.Bot.Mover.Sprinting)
                            {
                                probe.Bot.Mover.BotMoverSprint("R1-5E8716BF636C",@probe?.Bot,false,false);
                            }
                            else if (preserveSprint && !probe.Bot.Mover.Sprinting)
                            {
                                probe.Bot.Mover.BotMoverSprint("R1-1E45A5F638CC",@probe?.Bot,true,false);
                            }
                            float handoffSpeed = preserveSprint
                                ? ProbeMomentumFullMoveSpeed
                                : LearningV357RouteEnvelopeRunSpeed;
                            probe.Bot.BotOwnerSetTargetMoveSpeed("R1-5A0C8D7F14B6",@probe?.Bot,handoffSpeed);
                            probe.Bot.Mover.BotMoverSetTargetMoveSpeed("R1-6CBC968004D4",@probe?.Bot,handoffSpeed);
                            probe.Player.SetPlayerInputDirection("R1-D2848E9C5A31",@probe?.Bot,Vector2.up);
                            probe.Player.MovementContext.SetMovementContextMovementDirection("R1-48F42FE9BF04",@probe?.Bot,Vector2.up);
                        }
                    }
                    else
                    {
                        probe.Bot.Mover.BotMoverStop("R1-570AF8D4040E",@probe?.Bot);
                        probe.Bot.Mover.SetBotMoverPause("R1-4DB9B9E394C8",@probe?.Bot,true);
                        probe.Player.SetPlayerInputDirection("R1-4CE79A2B763F",@probe?.Bot,Vector2.zero);
                        probe.Player.MovementContext.SetMovementContextMovementDirection("R1-ABB633785877",@probe?.Bot,Vector2.zero);
                        if (navStable)
                        {
                            probe.Bot.Mover.BotMoverTeleport("R1-80EEA132FA5B",@probe?.Bot,anchor);
                            probe.Bot.Mover.SetBotMoverPause("R1-D89DB9846B6B",@probe?.Bot,true);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                WriteEvent("chainHandoffMoverScrubException", probe.Bot, new
                {
                    completedEdgeId,
                    nextEdgeId,
                    chainId,
                    error = ex.GetType().Name + ": " + ex.Message
                });
            }

            ChainHandoffAuthorityGuards[probe.Bot.ProfileId] = new ChainHandoffAuthorityGuard
            {
                Generation = raidGeneration,
                MovementWriterGeneration = probe.MovementWriterGeneration,
                ContinuousWalkThroughDropDownPassage = continuousWalkThroughDropDownPassage,
                ContinuousExactSuccessor = continuousExactSuccessor,
                CompletedEdgeId = completedEdgeId,
                NextEdgeId = nextEdgeId,
                NextEpisodeId = nextEpisodeId,
                ChainId = chainId,
                CompletedKind = probe.TraversalKind ?? probe.RequestedTraversalKind ?? string.Empty,
                VerifiedPosition = anchor,
                NextEntry = nextEntry,
                LastSafeSuccessorPosition = anchor,
                HasLastSafeSuccessorPosition = IsFinite(anchor),
                LastSafeSuccessorEntryDistance = IsFinite(nextEntry) ? Vector3.Distance(anchor, nextEntry) : float.MaxValue,
                BestSuccessorEntryDistance = IsFinite(nextEntry) ? Vector3.Distance(anchor, nextEntry) : float.MaxValue,
                StaleMoverDestination = staleDestination,
                HasStaleMoverDestination = haveStaleDestination,
                StartedAt = Time.time,
                ExpiresAt = Time.time + Mathf.Max(ChainHandoffAuthoritySeconds, ChainLocalSuccessorBridgeAbsoluteTimeout + 1.25f),
                NavStableAtArm = navStable
            };

            WriteEvent("chainHandoffGuardArmed", probe.Bot, new
            {
                completedEdgeId,
                nextEdgeId,
                chainId,
                position = Vec(anchor),
                nextEntry = Vec(nextEntry),
                staleMoverDestination = haveStaleDestination ? Vec(staleDestination) : null,
                navStable,
                continuousWalkThroughDropDownPassage,
                continuousExactSuccessor,
                learningV357ContinuousRouteEnvelope,
                successorPreloaded,
                movementGeneration = probe.MovementWriterGeneration,
                seconds = Mathf.Max(ChainHandoffAuthoritySeconds, ChainLocalSuccessorBridgeAbsoluteTimeout + 1.25f)
            });
            WriteEvent("chainHandoffMoverScrubbed", probe.Bot, new
            {
                completedEdgeId,
                nextEdgeId,
                chainId,
                anchor = Vec(anchor),
                navStable,
                continuousWalkThroughDropDownPassage,
                continuousExactSuccessor,
                zeroDistanceRebase = navStable && !continuousMoverHandoff,
                moverPausedUntilSuccessor = !continuousMoverHandoff
            });
        }

        private static void UpdateChainHandoffAuthorityGuard(BotOwner bot)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !ChainHandoffAuthorityGuards.TryGetValue(profileId, out ChainHandoffAuthorityGuard guard) ||
                guard == null)
            {
                return;
            }

            if (guard.Generation != raidGeneration || !IsLiveBot(bot))
            {
                ChainHandoffAuthorityGuards.Remove(profileId);
                return;
            }

            long currentMovementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain currentMovementOwner);
            bool movementGenerationChanged = FollowerCapabilityHelperRules.UpdateChainHandoffAuthorityGuard_movementGenerationChanged_A56455B1_1(guard.MovementWriterGeneration,currentMovementGeneration,currentMovementGeneration,guard.MovementWriterGeneration);
            bool teleportOwnsTemporaryBridge = currentMovementOwner == FollowerMovementWriterAuthority.WriterDomain.Teleport &&
                                               IsTeleportTransactionActive(bot);
            if (movementGenerationChanged && !teleportOwnsTemporaryBridge)
            {
                ChainHandoffAuthorityGuards.Remove(profileId);
                try
                {
                    if (bot.Mover != null) bot.Mover.SetBotMoverPause("R1-D7C5F1323B23",@bot,false);
                }
                catch
                {
                }
                WriteEvent("chainHandoffGuardInvalidatedByMovementGeneration", bot, new
                {
                    completedEdgeId = guard.CompletedEdgeId,
                    nextEdgeId = guard.NextEdgeId,
                    chainId = guard.ChainId,
                    guardGeneration = guard.MovementWriterGeneration,
                    currentGeneration = currentMovementGeneration,
                    currentOwner = currentMovementOwner.ToString()
                });
                return;
            }

            if (FollowerStateAuthorityCoordinator.HasImmediateCombatThreatClaim(bot, out string chainCombatYieldReason))
            {
                ChainHandoffAuthorityGuards.Remove(profileId);
                try
                {
                    if (bot.Mover != null)
                    {
                        bot.Mover.SetBotMoverPause("R1-3B585CE07BF1",@bot,false);
                    }
                }
                catch
                {
                }
                FollowerMovementWriterAuthority.AcquireCombat(
                    bot,
                    "chainHandoffYield:" + (chainCombatYieldReason ?? "immediateCombatThreat"));
                WriteEvent("chainHandoffGuardYieldedToCombat", bot, new
                {
                    completedEdgeId = guard.CompletedEdgeId,
                    nextEdgeId = guard.NextEdgeId,
                    chainId = guard.ChainId,
                    reason = chainCombatYieldReason ?? "immediateCombatThreat"
                });
                return;
            }

            Player player = bot.GetPlayer;

            // CompileFix42: the traversal runtime, not FollowAction, owns every intermediate
            // chain transition. Drive Guard -> exact successor commitment -> local bridge -> probe
            // here on every BotOwner update. This removes the Fix41 deadlock where the guard paused
            // the mover while waiting for a Follow branch that never ticked.
            if (!guard.SuccessorAuthorityAcquired && player != null && !IsTeleportTransactionActive(bot))
            {
                if (TryGetChainHandoffSuccessorTarget(
                        bot, out Vector3 guardedSuccessorEntry, out int guardedSuccessorEdgeId))
                {
                    Vector3 leaderPosition = guardedSuccessorEntry;
                    try
                    {
                        Player leader = FollowerEnvironment.LocalPlayer;
                        if (IsLivePlayer(leader) && IsFinite(leader.Position))
                        {
                            leaderPosition = leader.Position;
                        }
                    }
                    catch
                    {
                    }

                    bool haveTarget = TryGetLearnedTraversalFollowTarget(
                        bot,
                        leaderPosition,
                        out Vector3 successorTarget,
                        out bool successorProbeStarted,
                        out int successorEdgeId);
                    if (successorProbeStarted)
                    {
                        // RegisterActiveProbe has already converted this guard into successor
                        // authority. Do not let the old guard execute another writer this tick.
                        return;
                    }

                    Vector3 bridgeTarget = FollowerCapabilityHelperRules.UpdateChainHandoffAuthorityGuard_bridgeTarget_A56455B1_2(haveTarget,successorEdgeId,guardedSuccessorEdgeId) && IsFinite(successorTarget)
                        ? successorTarget
                        : guardedSuccessorEntry;
                    if (TryDriveChainLocalSuccessorBridge(bot, bridgeTarget, guardedSuccessorEdgeId))
                    {
                        return;
                    }
                }
                if (!ChainHandoffAuthorityGuards.ContainsKey(profileId))
                {
                    // TryGetChainHandoffSuccessorTarget may consume the guard when an exact WT
                    // successor is retired by ordinary NavMesh. Do not continue this frame with
                    // the stale local guard object and accidentally enter terminal bridge recovery.
                    return;
                }
            }
            else if (!guard.SuccessorAuthorityAcquired && IsTeleportTransactionActive(bot))
            {
                // A bounded chain-entry recovery teleport temporarily owns the body. Keep the
                // chain context alive until stabilization hands movement back to Traversal.
                guard.ExpiresAt = Mathf.Max(guard.ExpiresAt, Time.time + 4.0f);
                return;
            }

            Vector3 position = player != null ? player.Position : bot.Position;
            ProbeRuntime successorProbe = null;
            bool haveMatchingSuccessorProbe = guard.SuccessorAuthorityAcquired &&
                TryGetActiveProbe(bot, out successorProbe) && successorProbe != null &&
                successorProbe.Generation == raidGeneration &&
                (guard.SuccessorProbeEdgeId <= 0 || successorProbe.LearnedEdgeId == guard.SuccessorProbeEdgeId) &&
                (guard.SuccessorProbeChainId <= 0 || successorProbe.TraversalChainId <= 0 ||
                 successorProbe.TraversalChainId == guard.SuccessorProbeChainId);

            Vector3 safeReference = guard.HasLastSafeSuccessorPosition
                ? guard.LastSafeSuccessorPosition
                : guard.VerifiedPosition;
            float displacement = IsFinite(position) && IsFinite(safeReference)
                ? Vector3.Distance(position, safeReference)
                : 0f;
            float currentEntryDistance = IsFinite(position) && IsFinite(guard.NextEntry)
                ? Vector3.Distance(position, guard.NextEntry)
                : float.MaxValue;
            bool approachedStaleDestination = false;
            if (guard.HasStaleMoverDestination && IsFinite(position) && IsFinite(safeReference))
            {
                float before = Vector3.Distance(safeReference, guard.StaleMoverDestination);
                float now = Vector3.Distance(position, guard.StaleMoverDestination);
                approachedStaleDestination = now <= ChainHandoffStaleDestinationTolerance || now + 0.25f < before;
            }

            bool successorEntryRegressed = FollowerCapabilityHelperRules.UpdateChainHandoffAuthorityGuard_successorEntryRegressed_A56455B1_3(guard.SuccessorAuthorityAcquired,guard.LastSafeSuccessorEntryDistance,float.MaxValue,currentEntryDistance,float.MaxValue,currentEntryDistance,guard.LastSafeSuccessorEntryDistance,ChainHandoffSuccessorSnapbackEntryRegression);
            bool snapbackDetected = FollowerCapabilityHelperRules.UpdateChainHandoffAuthorityGuard_snapbackDetected_A56455B1_4(displacement,ChainHandoffSnapbackDistance,approachedStaleDestination) &&
                (!guard.SuccessorAuthorityAcquired || successorEntryRegressed);

            if (snapbackDetected)
            {
                guard.SnapbackLogged = true;
                guard.SnapbackCount++;
                Vector3 correctionTarget = guard.SuccessorAuthorityAcquired && guard.HasLastSafeSuccessorPosition
                    ? guard.LastSafeSuccessorPosition
                    : guard.VerifiedPosition;
                WriteEvent(guard.SuccessorAuthorityAcquired
                    ? "chainHandoffSuccessorSnapbackDetected"
                    : "chainHandoffSnapbackDetected", bot, new
                {
                    completedEdgeId = guard.CompletedEdgeId,
                    nextEdgeId = guard.NextEdgeId,
                    chainId = guard.ChainId,
                    verifiedPosition = Vec(guard.VerifiedPosition),
                    lastSafeSuccessorPosition = guard.HasLastSafeSuccessorPosition ? Vec(guard.LastSafeSuccessorPosition) : null,
                    current = Vec(position),
                    displacement,
                    currentEntryDistance,
                    lastSafeEntryDistance = guard.LastSafeSuccessorEntryDistance,
                    staleMoverDestination = guard.HasStaleMoverDestination ? Vec(guard.StaleMoverDestination) : null,
                    elapsed = Time.time - guard.StartedAt,
                    successorAuthorityAcquired = guard.SuccessorAuthorityAcquired,
                    attribution = "StaleMoverSnapback",
                    physicalTraversalPenalty = false
                });

                // CompileFix39: after successor acquisition restore the newest safe successor position,
                // not the old completed-traversal landing anchor. Reset RollingApproach clocks so the
                // corrected body is not failed by the stale no-progress/absolute timeout on the next tick.
                if (guard.NavStableAtArm && guard.CorrectionAttempts < 2 && IsFinite(correctionTarget))
                {
                    guard.CorrectionAttempts++;
                    try
                    {
                        bot.Mover?.BotMoverStop("R1-2FB5FF5C8FC9",@bot);
                        if (bot.Mover != null)
                        {
                            bot.Mover.SetBotMoverPause("R1-392D8DBCF09E",@bot,true);
                            bot.Mover.BotMoverTeleport("R1-36738717A0EB",@bot,correctionTarget);
                            bot.Mover.SetBotMoverPause("R1-7F178E83A98B",@bot,!guard.SuccessorAuthorityAcquired);
                        }
                        if (player?.MovementContext != null)
                        {
                            player.SetPlayerInputDirection("R1-B21FA3CFFA1B",@bot,Vector2.zero);
                            player.MovementContext.SetMovementContextMovementDirection("R1-D854139B75DB",@bot,Vector2.zero);
                        }
                        if (haveMatchingSuccessorProbe)
                        {
                            successorProbe.StageStartedAt = Time.time;
                            successorProbe.RollingApproachLastProgressAt = Time.time;
                            successorProbe.RollingApproachLastDistance = GetPlanarDistance(
                                correctionTarget, successorProbe.RollingApproachTarget);
                            successorProbe.RollingApproachLastLateralOffset = float.MaxValue;
                            successorProbe.RollingApproachLastAlignmentAngle = float.MaxValue;
                            successorProbe.RollingApproachNextDirectPointAt = Time.time;
                            successorProbe.ChainHandoffAuthorityCorrectionCount++;
                            successorProbe.LastChainHandoffAuthorityCorrectionAt = Time.time;
                        }
                        guard.LastSafeSuccessorPosition = correctionTarget;
                        guard.HasLastSafeSuccessorPosition = true;
                        guard.LastSafeSuccessorEntryDistance = IsFinite(guard.NextEntry)
                            ? Vector3.Distance(correctionTarget, guard.NextEntry)
                            : guard.LastSafeSuccessorEntryDistance;
                        guard.BestSuccessorEntryDistance = Mathf.Min(
                            guard.BestSuccessorEntryDistance, guard.LastSafeSuccessorEntryDistance);
                        guard.ExpiresAt = Mathf.Max(guard.ExpiresAt, Time.time + ChainHandoffSuccessorAuthoritySeconds);
                        WriteEvent(guard.SuccessorAuthorityAcquired
                            ? "chainHandoffSuccessorSnapbackCorrected"
                            : "chainHandoffSnapbackCorrected", bot, new
                        {
                            completedEdgeId = guard.CompletedEdgeId,
                            nextEdgeId = guard.NextEdgeId,
                            chainId = guard.ChainId,
                            restored = Vec(correctionTarget),
                            previous = Vec(position),
                            correctionAttempt = guard.CorrectionAttempts,
                            rollingApproachReset = haveMatchingSuccessorProbe,
                            physicalTraversalPenalty = false
                        });
                    }
                    catch (Exception ex)
                    {
                        WriteEvent("chainHandoffSnapbackCorrectionFailed", bot, new
                        {
                            completedEdgeId = guard.CompletedEdgeId,
                            nextEdgeId = guard.NextEdgeId,
                            chainId = guard.ChainId,
                            error = ex.GetType().Name + ": " + ex.Message
                        });
                    }
                }
                return;
            }

            // Advance the safe anchor only when the successor is making real progress toward its
            // authored entry and is not drifting back toward the retired writer destination.
            if (guard.SuccessorAuthorityAcquired && IsFinite(position) && currentEntryDistance < float.MaxValue &&
                !approachedStaleDestination &&
                (currentEntryDistance + 0.035f < guard.BestSuccessorEntryDistance || currentEntryDistance <= 0.75f))
            {
                guard.BestSuccessorEntryDistance = Mathf.Min(guard.BestSuccessorEntryDistance, currentEntryDistance);
                guard.LastSafeSuccessorEntryDistance = currentEntryDistance;
                guard.LastSafeSuccessorPosition = position;
                guard.HasLastSafeSuccessorPosition = true;
            }

            // CompileFix48: ChainHandoffSuccessorAuthoritySeconds is only the budget to get a
            // successor probe started. Once the matching successor owns Traversal, the guard lifetime
            // follows that probe and cannot independently terminal-abort it mid-air/mid-replay.
            if (haveMatchingSuccessorProbe)
            {
                guard.ExpiresAt = Mathf.Max(guard.ExpiresAt, Time.time + ChainHandoffSuccessorAuthoritySeconds);
                return;
            }

            if (Time.time <= guard.ExpiresAt)
            {
                return;
            }

            if (!guard.SuccessorAuthorityAcquired &&
                !guard.LocalBridgeRecoveryTeleportAttempted &&
                FollowerSafeTeleport.TryValidateLocalTraversalEntryAnchor(
                    bot, guard.NextEntry, out Vector3 safeSuccessorEntry))
            {
                guard.LocalBridgeRecoveryTeleportAttempted = true;
                guard.LocalBridgeRecoveryTeleportAt = Time.time;
                guard.ExpiresAt = Time.time + 5.0f;
                if (FollowerSafeTeleport.TryTeleportWithOriginReceipt(
                        bot,
                        safeSuccessorEntry,
                        $"chainEntryRecovery:{guard.NextEdgeId}",
                        out Vector3 recoveredEntry, out long issuedChainEntryTeleport))
                {
                    guard.TeleportWriterGeneration = issuedChainEntryTeleport;
                    guard.LocalBridgeActive = false;
                    guard.LastSafeSuccessorPosition = recoveredEntry;
                    guard.HasLastSafeSuccessorPosition = true;
                    guard.LastSafeSuccessorEntryDistance = Vector3.Distance(recoveredEntry, guard.NextEntry);
                    guard.BestSuccessorEntryDistance = guard.LastSafeSuccessorEntryDistance;
                    string recoveryFromKind = GetLearningV354SemanticKind(guard.CompletedEdgeId, guard.CompletedKind);
                    LearnedTraversalEdge recoveryNextEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                        candidate != null && candidate.Id == guard.NextEdgeId);
                    string recoveryToKind = GetLearningV354SemanticKind(guard.NextEdgeId, recoveryNextEdge?.Kind);
                    RecordLearningV354TransitionOutcome(
                        recoveryFromKind, recoveryToKind, false, true, "chainBridgeRecoveryTeleport");
                    WriteEvent("traversalChainBridgeRecoveryTeleport", bot, new
                    {
                        completedEdgeId = guard.CompletedEdgeId,
                        nextEdgeId = guard.NextEdgeId,
                        chainId = guard.ChainId,
                        requestedEntry = Vec(guard.NextEntry),
                        teleportedTo = Vec(recoveredEntry),
                        reason = "guardExpiredBeforeSuccessor"
                    });
                    return;
                }
            }

            string terminalFromKind = GetLearningV354SemanticKind(guard.CompletedEdgeId, guard.CompletedKind);
            LearnedTraversalEdge terminalNextEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == guard.NextEdgeId);
            string terminalToKind = GetLearningV354SemanticKind(guard.NextEdgeId, terminalNextEdge?.Kind);
            RecordLearningV354TransitionOutcome(
                terminalFromKind, terminalToKind, false, guard.LocalBridgeRecoveryTeleportAttempted,
                "successorUnavailableAfterBoundedBridgeRecovery");
            ChainHandoffAuthorityGuards.Remove(profileId);
            RetireChainGuardToFollowAtOrigin(bot, guard, "traversalChainTerminalAbort:successorUnavailable");
            WriteEvent("traversalChainTerminalAbort", bot, new
            {
                completedEdgeId = guard.CompletedEdgeId,
                nextEdgeId = guard.NextEdgeId,
                chainId = guard.ChainId,
                position = IsFinite(position) ? Vec(position) : null,
                successorAuthorityAcquired = guard.SuccessorAuthorityAcquired,
                snapbackDetected = guard.SnapbackLogged,
                snapbackCount = guard.SnapbackCount,
                corrections = guard.CorrectionAttempts,
                bridgeRecoveryTeleportAttempted = guard.LocalBridgeRecoveryTeleportAttempted,
                reason = "successorUnavailableAfterBoundedBridgeRecovery"
            });
        }

        private static bool TryReleaseLearningV445PostCompletionInheritedTransition(
            BotOwner bot,
            Player player,
            Vector3 nativeDirection)
        {
            if ((bot == null) ||
                player?.MovementContext == null || player.CurrentStateName != EPlayerState.Transition ||
                !player.MovementContext.IsGrounded || HasActiveTraversalProbe(bot))
            {
                return false;
            }

            string profileId = bot.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId) ||
                !FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) ||
                mission?.Steps == null || mission.CurrentStepIndex <= 0 ||
                mission.CurrentStepIndex >= mission.Steps.Count ||
                !FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) ||
                cursor == null)
            {
                return false;
            }

            FollowerRouteMissionStep predecessor = mission.Steps[mission.CurrentStepIndex - 1];
            FollowerRouteMissionStep successor = mission.Steps[mission.CurrentStepIndex];
            if (predecessor == null || successor == null ||
                !predecessor.CurrentRaidRouteAuthority || !successor.CurrentRaidRouteAuthority)
            {
                return false;
            }

            LearningV354TraversalCapabilityProfile predecessorProfile =
                GetLearningV354ActionProfile(predecessor.Kind);
            LearningV354TraversalCapabilityProfile successorProfile =
                GetLearningV354ActionProfile(successor.Kind);
            if (predecessorProfile?.RequiresActuator != true ||
                successorProfile?.RequiresActuator != true ||
                !LearningV354CanUseContinuousSuccessor(predecessor.Kind, successor.Kind, successorPreloaded: true))
            {
                return false;
            }

            bool predecessorConsumed =
                cursor.LastCompletedEpisodeId == predecessor.EpisodeId ||
                (predecessor.EndBreadcrumbSequence > 0 &&
                 cursor.ConsumedBreadcrumbSequence >= predecessor.EndBreadcrumbSequence);
            if (!predecessorConsumed)
            {
                return false;
            }

            TraversalEpisodeMetadata predecessorEpisode = TraversalEpisodeStream.LastOrDefault(item =>
                item != null && item.EpisodeId == predecessor.EpisodeId);
            TraversalEpisodeMetadata successorEpisode = TraversalEpisodeStream.LastOrDefault(item =>
                item != null && item.EpisodeId == successor.EpisodeId);
            bool immediateSuccessor =
                IsImmediateTraversalChainSuccessor(
                    predecessorEpisode, successorEpisode, out int breadcrumbGap, out float spatialGap) ||
                IsLearningV441CanonicalMissionImmediateSuccessor(
                    predecessorEpisode, successorEpisode, out breadcrumbGap, out spatialGap);
            if (!immediateSuccessor)
            {
                return false;
            }

            Vector3 successorRawEntry = IsFinite(successor.RawEntry) ? successor.RawEntry : successor.Entry;
            Vector3 successorRawExit = IsFinite(successor.RawExit) ? successor.RawExit : successor.Exit;
            if (!IsFinite(successorRawEntry) || !IsFinite(successorRawExit))
            {
                return false;
            }

            Vector3 successorAxis = GetFlatDirection(successorRawExit - successorRawEntry);
            Vector3 requestedDirection = nativeDirection;
            requestedDirection.y = 0f;
            if (!IsFinite(successorAxis) || successorAxis.sqrMagnitude <= 0.5f ||
                !IsFinite(requestedDirection) || requestedDirection.sqrMagnitude <= 0.000001f)
            {
                return false;
            }
            requestedDirection.Normalize();
            float directionDot = Vector3.Dot(successorAxis, requestedDirection);
            float successorEntryDistance = GetPlanarDistance(bot.Position, successorRawEntry);
            if (directionDot < LearningV2RevisionMinDirectionDot ||
                successorEntryDistance > RouteMissionTraversalAdjacentBridgeMaxDistance)
            {
                return false;
            }

            long movementGeneration = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (owner != FollowerMovementWriterAuthority.WriterDomain.Traversal || movementGeneration <= 0 ||
                player.MovementContext.OverridenState != null ||
                !player.MovementContext.States.TryGetValue(EPlayerState.Run, out BaseMovementState runState) ||
                runState == null)
            {
                return false;
            }

            EPlayerState stateBefore = player.CurrentStateName;
            try
            {
                // Source-grounded EFT lifecycle (SPT 4.0.13 MovementContext.ProcessStateEnter):
                // CurrentState.Exit -> CurrentState assignment -> Run.Enter -> controller/authority
                // refresh -> OnStateChanged. The body is not relocated and no success is minted.
                RequestCapabilityLocomotionResume(bot,player,runState);
            }
            catch (Exception ex)
            {
                WriteEvent("learningV445PostCompletionInheritedTransitionReleaseFailed", bot, new
                {
                    missionId = mission.MissionId,
                    predecessorStepIndex = mission.CurrentStepIndex - 1,
                    successorStepIndex = mission.CurrentStepIndex,
                    predecessorEdgeId = predecessor.EdgeId,
                    successorEdgeId = successor.EdgeId,
                    predecessorKind = predecessor.Kind,
                    successorKind = successor.Kind,
                    owner = owner.ToString(),
                    generation = movementGeneration,
                    stateBefore = stateBefore.ToString(),
                    error = ex.GetType().Name + ": " + ex.Message,
                    traversalSuccessRecorded = false,
                    persistentLearningChanged = false,
                    bodyRelocated = false
                });
                return false;
            }

            EPlayerState stateAfter = player.CurrentStateName;
            bool released = stateAfter != EPlayerState.Transition;
            WriteEvent(released
                ? "learningV445PostCompletionInheritedTransitionReleased"
                : "learningV445PostCompletionInheritedTransitionReleaseRejected", bot, new
            {
                missionId = mission.MissionId,
                predecessorStepIndex = mission.CurrentStepIndex - 1,
                successorStepIndex = mission.CurrentStepIndex,
                predecessorEpisodeId = predecessor.EpisodeId,
                successorEpisodeId = successor.EpisodeId,
                predecessorEdgeId = predecessor.EdgeId,
                successorEdgeId = successor.EdgeId,
                predecessorKind = predecessor.Kind,
                successorKind = successor.Kind,
                consumedBreadcrumbSequence = cursor.ConsumedBreadcrumbSequence,
                predecessorEndBreadcrumbSequence = predecessor.EndBreadcrumbSequence,
                breadcrumbGap,
                spatialGap,
                successorEntryDistance,
                traversalAdjacentEnvelope = RouteMissionTraversalAdjacentBridgeMaxDistance,
                directionDot,
                minimumDirectionDot = LearningV2RevisionMinDirectionDot,
                owner = owner.ToString(),
                generation = movementGeneration,
                grounded = player.MovementContext.IsGrounded,
                stateBefore = stateBefore.ToString(),
                stateAfter = stateAfter.ToString(),
                traversalSuccessRecorded = false,
                nativeSuccessRecorded = false,
                persistentLearningChanged = false,
                bodyRelocated = false,
                action = "completedPredecessorCannotRetainTransitionPresentationOwnershipAfterCanonicalSuccessorOwnsRoute"
            });

            if (released)
            {
                LearningV444TransitionMomentumEpochs.Remove(profileId);
            }
            return released;
        }

        // RC61: ApplyCollisionActivePhysicalRouteMotion extracted unchanged to FollowerTraversalPhysicalInput.cs.

        // RC107: TryApplyLearningV407CollisionActiveLocomotionPresentation is owned by FollowerCapabilityGeneralRecoveryHost.

        private static bool TryGetLearningV376PersistentMissionSuccessorOwnership(
            BotOwner bot,
            int successorEdgeId,
            out FollowerTraversalRouteCursor cursor,
            out FollowerRouteMission mission)
        {
            cursor = null;
            mission = null;
            string profileId = bot?.ProfileId ?? string.Empty;
            if ((string.IsNullOrEmpty(profileId)) || successorEdgeId <= 0 ||
                !FollowerTraversalRouteCursors.TryGetValue(profileId, out cursor) || cursor == null ||
                !cursor.LearningV375TransactionActive || cursor.LearningV375MovementGeneration <= 0 ||
                !TryResolveLearningV376CursorMission(bot, cursor, out mission) || mission == null ||
                mission.CurrentStepIndex < 0 || mission.CurrentStepIndex >= mission.Steps.Count)
            {
                cursor = null;
                mission = null;
                return false;
            }

            long generation = FollowerMovementWriterAuthority.GetCurrentGeneration(
                bot, out FollowerMovementWriterAuthority.WriterDomain owner);
            if (owner != FollowerMovementWriterAuthority.WriterDomain.Traversal ||
                generation != cursor.LearningV375MovementGeneration)
            {
                cursor = null;
                mission = null;
                return false;
            }

            return mission.Steps.Skip(Math.Max(0, mission.CurrentStepIndex))
                .Any(step => IsLearningV376RouteStepEquivalentToEdgeId(step, successorEdgeId));
        }

        private static bool IsLearningV376RouteStepEquivalentToEdgeId(
            FollowerRouteMissionStep step, int edgeId)
        {
            if (step == null || edgeId <= 0)
            {
                return false;
            }
            if (step.EdgeId == edgeId)
            {
                return true;
            }

            LearnedTraversalEdge requested = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == edgeId);
            if (requested != null &&
                TryGetLearningV31AuthoritativeProvenParent(requested, out LearnedTraversalEdge requestedParent) &&
                requestedParent != null && requestedParent.Id == step.EdgeId)
            {
                return true;
            }

            LearnedTraversalEdge stepEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == step.EdgeId);
            return stepEdge != null &&
                   TryGetLearningV31AuthoritativeProvenParent(stepEdge, out LearnedTraversalEdge stepParent) &&
                   stepParent != null && stepParent.Id == edgeId;
        }

        // RC106: TryDriveChainLocalSuccessorBridge is owned by FollowerCapabilityRouteContinuationHost.


        private static bool TryPreloadNextTraversalChainCommitment(BotOwner bot, int completedEpisodeId, int completedEdgeId)
        {
            string profileId = bot?.ProfileId ?? string.Empty;
            if (string.IsNullOrEmpty(profileId))
            {
                return false;
            }

            // R8.8 Route Mission supersedes the short 2.25s/5.5m chain heuristic. The mission is
            // player-stream ordered and may contain many normal movement gaps between traversals.
            if (FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission mission) && mission != null)
            {
                int authoritativeMissionId = mission.MissionId;
                RefreshFollowerRouteMission(bot, mission);
                if (FollowerRouteMissions.TryGetValue(profileId, out FollowerRouteMission refreshedMission) &&
                    refreshedMission != null &&
                    EnsureFollowerRouteMissionCommitment(bot, refreshedMission))
                {
                    FollowerRouteMissionStep step = refreshedMission.CurrentStepIndex < refreshedMission.Steps.Count
                        ? refreshedMission.Steps[refreshedMission.CurrentStepIndex]
                        : null;
                    WriteEvent("routeMissionNextTraversalPreloaded", bot, new
                    {
                        missionId = refreshedMission.MissionId,
                        completedEpisodeId,
                        completedEdgeId,
                        nextStepIndex = refreshedMission.CurrentStepIndex,
                        nextEpisodeId = step?.EpisodeId ?? 0,
                        nextEdgeId = step?.EdgeId ?? 0,
                        nextKind = step?.Kind
                    });
                    return true;
                }

                // COMPILEFIX9: Route Mission is authoritative once it existed at handoff entry.
                // If Refresh completed/skipped the remaining steps, do NOT fall through to the old
                // episode-chain heuristic: that resurrected an already-skipped DropDown immediately
                // after a successful Jump and left both followers parked on a valid NavMesh route.
                WriteEvent("routeMissionLegacyChainFallbackSuppressed", bot, new
                {
                    missionId = authoritativeMissionId,
                    completedEpisodeId,
                    completedEdgeId,
                    reason = "authoritativeRouteMissionHadNoRemainingCommitment"
                });
                return false;
            }

            if (!TryGetNextTraversalEpisode(
                    completedEpisodeId, out TraversalEpisodeMetadata nextEpisode,
                    out int learningV367SkippedPreloadSuccessors))
            {
                return false;
            }
            if ((learningV367SkippedPreloadSuccessors > 0))
            {
                WriteEvent("learningV367NonAdvancingSuccessorEpisodesSkipped", bot, new
                {
                    completedEpisodeId,
                    completedEdgeId,
                    nextEpisodeId = nextEpisode.EpisodeId,
                    nextEdgeId = nextEpisode.EdgeId,
                    skipped = learningV367SkippedPreloadSuccessors,
                    action = "preloadUsesMonotonicBreadcrumbSuccessorFrontier"
                });
            }

            LearnedTraversalEdge edge = LearnedTraversalEdges.FirstOrDefault(candidate => candidate != null && candidate.Id == nextEpisode.EdgeId);
            bool freshRaidLocalDropDown = edge != null && HasFreshRaidLocalDropDownAuthority(edge, nextEpisode);
            bool learningV341FreshLocalSemanticSuccessor = edge != null &&
                HasLearningV341FreshRaidLocalSemanticSuccessorAuthority(edge, nextEpisode);
            bool learningV347CurrentRaidSuccessor = edge != null &&
                HasLearningV347CurrentRaidTraversalAuthority(edge, nextEpisode);
            bool chainLocalExecutable = FollowerCapabilityHelperRules.TryPreloadNextTraversalChainCommitment_chainLocalExecutable_6FB8F591_1(freshRaidLocalDropDown,learningV341FreshLocalSemanticSuccessor,learningV347CurrentRaidSuccessor);
            if (edge == null || (edge.Disabled && !chainLocalExecutable))
            {
                return false;
            }
            Vector3 entry = chainLocalExecutable && IsFinite(nextEpisode.RawStart)
                ? nextEpisode.RawStart
                : (edge.HasSettledStart ? edge.SettledStart : edge.A);
            Vector3 exit = chainLocalExecutable && IsFinite(nextEpisode.RawEnd)
                ? nextEpisode.RawEnd
                : (edge.HasSettledEnd ? edge.SettledEnd : edge.B);
            float distance = Vector3.Distance(bot.Position, entry);
            if (distance > 12.0f)
            {
                return false;
            }

            LearnedTraversalEdge completedEdge = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == completedEdgeId);
            if (completedEdge != null && IsFinite(completedEdge.RawStart) && IsFinite(completedEdge.RawEnd))
            {
                Vector3 completedAxis = completedEdge.RawEnd - completedEdge.RawStart;
                completedAxis.y = 0f;
                float completedSpan = completedAxis.magnitude;
                if (completedSpan >= 0.25f)
                {
                    Vector3 completedDirection = completedAxis / completedSpan;
                    Vector3 relative = entry - bot.Position;
                    relative.y = 0f;
                    float forwardOffset = Vector3.Dot(relative, completedDirection);
                    Vector3 bodyDelta = bot.Position - completedEdge.RawStart;
                    bodyDelta.y = 0f;
                    float bodyProjection = Vector3.Dot(bodyDelta, completedDirection);
                    if (bodyProjection >= completedSpan - 0.20f && forwardOffset < -0.55f)
                    {
                        WriteEvent("traversalChainPreloadUpstreamSuccessorRejected", bot, new
                        {
                            completedEdgeId,
                            nextEdgeId = edge.Id,
                            position = Vec(bot.Position),
                            entry = Vec(entry),
                            distance,
                            forwardOffset,
                            bodyProjection,
                            completedSpan
                        });
                        return false;
                    }
                }
            }

            Vector3 preloadRawEntry = chainLocalExecutable && IsFinite(nextEpisode.RawStart) ? nextEpisode.RawStart : edge.RawStart;
            Vector3 preloadRawExit = chainLocalExecutable && IsFinite(nextEpisode.RawEnd) ? nextEpisode.RawEnd : edge.RawEnd;
            LearnedTraversalCommitment nextCommitment = CreateLearnedTraversalCommitment(
                edge,
                entry,
                exit,
                preloadRawEntry,
                preloadRawExit,
                nextEpisode.EpisodeId);
            if (nextCommitment == null)
            {
                return false;
            }
            nextCommitment.EpisodeId = nextEpisode.EpisodeId;
            nextCommitment.ChainId = nextEpisode.ChainId;
            // CompileFix52: a persistently disabled DropDown may execute only as the exact fresh
            // successor demonstrated by the player in this raid/chain. This never changes the DB
            // Enabled/Disabled flag and therefore cannot leak into generic planner selection.
            nextCommitment.ChainLocalExecutable = chainLocalExecutable;
            LearnedTraversalCommitments[profileId] = nextCommitment;

            LearnedTraversalEdge completedForPassage = LearnedTraversalEdges.FirstOrDefault(candidate =>
                candidate != null && candidate.Id == completedEdgeId);
            TraversalEpisodeMetadata completedEpisode = TraversalEpisodeStream
                .LastOrDefault(item => item != null && item.EpisodeId == completedEpisodeId);
            bool immediateLegacySuccessor = IsImmediateTraversalChainSuccessor(
                completedEpisode, nextEpisode, out _, out _);
            bool continuousWalkThroughDropDownPassage = (false);
            string completedSemanticKind = GetLearningV354SemanticKind(completedEdgeId, completedForPassage?.Kind);
            string successorSemanticKind = GetLearningV354SemanticKind(edge.Id, edge.Kind);
            bool learningV354ContinuousProfileTransaction =
                (immediateLegacySuccessor) &&
                nextEpisode.ChainId > 0 && distance <= RouteMissionTraversalAdjacentBridgeMaxDistance &&
                LearningV354CanUseContinuousSuccessor(completedSemanticKind, successorSemanticKind, true);

            // V3.54: no action pair owns this producer-order rule. Any exact adjacent successor whose
            // capabilities support rolling entry preserves the live body transaction.
            try
            {
                if (!continuousWalkThroughDropDownPassage && !learningV354ContinuousProfileTransaction)
                {
                    bot.GoToSomePointData?.BotGoToPointDataSetPoint("R1-6F4378CED511",@bot,entry);
                    bool shouldRun = bot.Mover?.Sprinting == true ||
                                     string.Equals(edge.ApproachMode, "Sprint", StringComparison.OrdinalIgnoreCase) ||
                                     string.Equals(edge.ApproachMode, "Run", StringComparison.OrdinalIgnoreCase);
                    bot.GoToSomePointData?.BotGoToPointDataUpdateToGo("R1-E11494C196C6",@bot,shouldRun);
                }
            }
            catch (Exception ex)
            {
                WriteEvent("traversalChainNextApproachPrimeFailed", bot, new
                {
                    nextEdgeId = edge.Id,
                    nextEpisodeId = nextEpisode.EpisodeId,
                    error = ex.GetType().Name + ": " + ex.Message
                });
            }

            if (!FollowerTraversalRouteCursors.TryGetValue(profileId, out FollowerTraversalRouteCursor cursor) || cursor == null)
            {
                cursor = new FollowerTraversalRouteCursor();
                FollowerTraversalRouteCursors[profileId] = cursor;
            }
            cursor.PreloadedEpisodeId = nextEpisode.EpisodeId;
            WriteEvent("traversalChainNextPreloaded", bot, new
            {
                completedEdgeId,
                nextEdgeId = edge.Id,
                nextEpisodeId = nextEpisode.EpisodeId,
                chainId = nextEpisode.ChainId,
                entry = Vec(entry),
                distance,
                persistentDisabled = edge.Disabled,
                chainLocalExecutable,
                continuousWalkThroughDropDownPassage,
                learningV354ContinuousProfileTransaction,
                completedSemanticKind,
                successorSemanticKind
            });
            return true;
        }

        private static void ExpireTraversalOwnershipLease(ProbeRuntime probe)
        {
            if (probe == null || !IsActiveProbe(probe))
            {
                return;
            }
            bool hardStuck = IsTraversalHardStuck(probe, out string stuckReason);
            WriteEvent("movementOwnershipLeaseExpired", probe.Bot, new
            {
                edgeId = probe.LearnedEdgeId,
                kind = probe.TraversalKind ?? probe.RequestedTraversalKind,
                stage = probe.Stage.ToString(),
                heldFor = Mathf.Max(0f, Time.time - probe.RequestedAt),
                position = probe.Player != null ? Vec(probe.Player.Position) : null,
                hardStuck,
                stuckReason
            });

            if (hardStuck && TryTeleportPlayerValidatedTraversalAtExit(probe, "ownershipLeaseHardStuck:" + stuckReason))
            {
                return;
            }

            if ((probe.Stage == ProbeStage.Egress || probe.Stage == ProbeStage.Verify) && !hardStuck)
            {
                probe.OwnershipLeaseExpiresAt = Time.time + TraversalEgressProgressExtensionSeconds + UnifiedTraversalVerifyTimeout;
                WriteEvent("movementOwnershipLeaseExtendedForProgress", probe.Bot, new
                {
                    edgeId = probe.LearnedEdgeId,
