        private static object ReadBoolProperty(object instance, string propertyName)
        {
            if (instance == null || string.IsNullOrEmpty(propertyName))
            {
                return null;
            }

            try
            {
                PropertyInfo property = instance.GetType().GetProperty(
                    propertyName,
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                if (property == null || property.PropertyType != typeof(bool) || property.GetIndexParameters().Length != 0)
                {
                    return null;
                }

                return property.GetValue(instance, null);
            }
            catch (Exception ex)
            {
                return "error:" + ex.GetType().Name;
            }
        }

        private static object CreateVaultRestrictionPayload(Player player)
        {
            object restrictions = player?.VaultingGameplayRestrictions;
            if (restrictions == null)
            {
                return new { available = false };
            }

            try
            {
                Dictionary<string, object> values = new Dictionary<string, object>(StringComparer.Ordinal);
                Type restrictionType = restrictions.GetType();
                foreach (PropertyInfo property in restrictionType.GetProperties(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
                {
                    if (property.PropertyType != typeof(bool) || !property.CanRead || property.GetIndexParameters().Length != 0)
                    {
                        continue;
                    }

                    try
                    {
                        values["property:" + property.Name] = property.GetValue(restrictions, null);
                    }
                    catch (Exception ex)
                    {
                        values["property:" + property.Name] = "error:" + ex.GetType().Name;
                    }
                }

                // GClass2680 in this EFT build exposes most gameplay restrictions as private
                // predicate fields rather than readable bool properties. The previous logger therefore
                // always emitted an empty dictionary. Read simple bools and Func<bool> predicates too;
                // they are diagnostics only and let the next probe identify the exact rejection gate.
                foreach (FieldInfo field in restrictionType.GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
                {
                    try
                    {
                        if (field.FieldType == typeof(bool))
                        {
                            values["field:" + field.Name] = field.GetValue(restrictions);
                        }
                        else if (field.FieldType == typeof(Func<bool>))
                        {
                            Func<bool> predicate = field.GetValue(restrictions) as Func<bool>;
                            values["predicate:" + field.Name] = predicate != null ? predicate() : (object)"null";
                        }
                    }
                    catch (Exception ex)
                    {
                        values["field:" + field.Name] = "error:" + ex.GetBaseException().GetType().Name;
                    }
                }

                return new
                {
                    available = true,
                    type = restrictions.GetType().FullName,
                    values
                };
            }
            catch (Exception ex)
            {
                return new { available = false, error = ex.GetType().Name + ": " + ex.Message };
            }
        }

        private static object CreateVaultParameterPayload(Player player)
        {
            try
            {
                EFT.Vaulting.IVaultingParameters parameters = player?.VaultingParameters;
                if (parameters == null)
                {
                    return new { available = false };
                }

                return new
                {
                    available = true,
                    strategy = parameters.GetVaultingStrategy().ToString(),
                    height = parameters.VaultingHeight,
                    length = parameters.VaultingLength,
                    behindObstacleRatio = parameters.BehindObstacleRatio,
                    absoluteForwardVelocity = parameters.AbsoluteForwardVelocity,
                    maxWeightPoint = Vec(parameters.MaxWeightPointPosition)
                };
            }
            catch (Exception ex)
            {
                return new { available = false, error = ex.GetType().Name + ": " + ex.Message };
            }
        }

        private static object SamplePayload(Vector3 rawPosition, float radius)
        {
            bool sampled = NavMesh.SamplePosition(rawPosition, out NavMeshHit hit, radius, NavMesh.AllAreas);
            return new
            {
                sampled,
                radius,
                position = sampled ? Vec(hit.position) : null,
                offset = sampled ? Vector3.Distance(rawPosition, hit.position) : -1f,
                verticalOffset = sampled ? Mathf.Abs(rawPosition.y - hit.position.y) : -1f
            };
        }

        private static bool TryOpenDiagnostics(string reason, out string error)
        {
            error = string.Empty;
            if (!BotTraversalSharedSettings.DebugLogEnabled)
            {
                error = "Disabled by BotTraversal F12 Debug Log toggle.";
                return false;
            }
            if (diagnosticsEnabled && writer != null)
            {
                return true;
            }
            if (writer != null)
            {
                StopDiagnosticWriterThread();
                DisposeWriter();
            }

            try
            {
                string root = Path.Combine(
                    AppDomain.CurrentDomain.BaseDirectory,
                    "BepInEx",
                    "plugins",
                    "BotTraversal",
                    "Data",
                    "Logs");
                Directory.CreateDirectory(root);
                string timestamp = DateTime.Now.ToString("yyyyMMdd-HHmmss-fff", CultureInfo.InvariantCulture);
                string safeLocation = SanitizeFileName(locationId);
                sessionId = $"{timestamp}-{safeLocation}-g{raidGeneration}";
                currentFilePath = Path.Combine(root, sessionId + ".jsonl");
                writer = new StreamWriter(currentFilePath, false, new UTF8Encoding(false))
                {
                    AutoFlush = false
                };
                diagnosticWriterFailure = null;
                diagnosticWriterStopRequested = false;
                diagnosticDroppedPeriodicEvents = 0;
                lock (DiagnosticQueueSync)
                {
                    DiagnosticWriteQueue.Clear();
                }
                StartDiagnosticWriterThread();
                diagnosticsEnabled = true;
                eventSequence = 0;
                DiagnosticFollowers.Clear();
            CF75FollowPhysicalWatches.Clear();
                ResetBreadcrumbState();
                WriteEvent("diagnosticStart", null, new
                {
                    reason,
                    sessionId,
                    locationId,
                    raidGeneration,
                    snapshotInterval = DiagnosticSnapshotInterval
                });
                CaptureBreadcrumb(FollowerEnvironment.LocalPlayer, true);
                LogInfo($"diagnostics started: {currentFilePath}");
                return true;
            }
            catch (Exception ex)
            {
                diagnosticsEnabled = false;
                DisposeWriter();
                error = ex.GetType().Name + ": " + ex.Message;
                LogError("could not open traversal diagnostics: " + error);
                return false;
            }
        }

        private static void CloseDiagnostics(string reason)
        {
            if (writer != null && diagnosticsEnabled)
            {
                try
                {
                    WriteEvent("diagnosticStop", null, new
                    {
                        reason = reason ?? "unknown",
                        droppedPeriodicEvents = diagnosticDroppedPeriodicEvents
                    });
                }
                catch
                {
                    // Best effort during shutdown.
                }
            }

            diagnosticsEnabled = false;
            StopDiagnosticWriterThread();
            DisposeWriter();
            sessionId = null;
            currentFilePath = null;
            eventSequence = 0;
        }

        private static void StartDiagnosticWriterThread()
        {
            if (diagnosticWriterThread != null && diagnosticWriterThread.IsAlive)
            {
                return;
            }

            diagnosticWriterThread = new Thread(DiagnosticWriterLoop)
            {
                IsBackground = true,
                Name = "PIT Traversal Diagnostics"
            };
            diagnosticWriterThread.Start();
        }

        private static void StopDiagnosticWriterThread()
        {
            diagnosticWriterStopRequested = true;
            DiagnosticWriterSignal.Set();
            Thread thread = diagnosticWriterThread;
            if (thread != null && thread.IsAlive && !object.ReferenceEquals(Thread.CurrentThread, thread))
            {
                try
                {
                    thread.Join(2000);
                }
                catch
                {
                }
            }
            diagnosticWriterThread = null;
        }

        private static void DiagnosticWriterLoop()
        {
            int writesSinceFlush = 0;
            DateTime nextFlushUtc = DateTime.UtcNow.AddMilliseconds(DiagnosticBackgroundFlushMilliseconds);
            try
            {
                while (true)
                {
                    DiagnosticEnvelope envelope = null;
                    lock (DiagnosticQueueSync)
                    {
                        if (DiagnosticWriteQueue.Count > 0)
                        {
                            envelope = DiagnosticWriteQueue.Dequeue();
                        }
                        else if (diagnosticWriterStopRequested)
                        {
                            break;
                        }
                    }

                    if (envelope == null)
                    {
                        DiagnosticWriterSignal.WaitOne(100);
                    }
                    else
                    {
                        writer?.WriteLine(JsonConvert.SerializeObject(envelope, Formatting.None));
                        writesSinceFlush++;
                    }

                    if (writer != null &&
                        (writesSinceFlush >= DiagnosticBackgroundFlushBatch || DateTime.UtcNow >= nextFlushUtc))
                    {
                        writer.Flush();
                        writesSinceFlush = 0;
                        nextFlushUtc = DateTime.UtcNow.AddMilliseconds(DiagnosticBackgroundFlushMilliseconds);
                    }
                }

                while (true)
                {
                    DiagnosticEnvelope envelope;
                    lock (DiagnosticQueueSync)
                    {
                        if (DiagnosticWriteQueue.Count == 0)
                        {
                            break;
                        }
                        envelope = DiagnosticWriteQueue.Dequeue();
                    }
                    writer?.WriteLine(JsonConvert.SerializeObject(envelope, Formatting.None));
                }
                writer?.Flush();
            }
            catch (Exception ex)
            {
                diagnosticWriterFailure = ex.GetType().Name + ": " + ex.Message;
                diagnosticsEnabled = false;
                LogError("Traversal diagnostic background writer failed: " + diagnosticWriterFailure);
            }
        }

        private static void DisposeWriter()
        {
            try
            {
                writer?.Flush();
                writer?.Dispose();
            }
            catch
            {
                // Best effort during teardown.
            }
            finally
            {
                writer = null;
            }
        }

        public static void RecordTeleportDiagnostic(BotOwner bot, string eventType, object payload)
        {
            if (string.IsNullOrWhiteSpace(eventType))
            {
                return;
            }

            WriteEvent(eventType, bot, payload);
        }

        private static bool ShouldEmitDiagnostic(string eventType, BotOwner bot, float intervalSeconds)
        {
            if (!diagnosticsEnabled || writer == null || intervalSeconds <= 0f)
            {
                return diagnosticsEnabled && writer != null;
            }
            string key = (eventType ?? string.Empty) + ":" + (bot?.ProfileId ?? "player");
            if (DiagnosticNextEmitAt.TryGetValue(key, out float nextAt) && Time.time < nextAt)
            {
                return false;
            }
            DiagnosticNextEmitAt[key] = Time.time + intervalSeconds;
            return true;
        }

        private static long BeginTraversalPerfSample()
        {
            return System.Diagnostics.Stopwatch.GetTimestamp();
        }

        private static void EndTraversalPerfSample(
            string operation,
            long startedAt,
            BotOwner bot = null,
            int edgeId = 0,
            string kind = null)
        {
            if (!diagnosticsEnabled || startedAt <= 0)
            {
                return;
            }
            double elapsedMs =
                (System.Diagnostics.Stopwatch.GetTimestamp() - startedAt) * 1000.0 /
                System.Diagnostics.Stopwatch.Frequency;
            if (elapsedMs < TraversalPerfSpikeThresholdMs)
            {
                return;
            }
            WriteEvent("traversalPerfSpike", bot, new
            {
                operation = operation ?? "unknown",
                elapsedMs,
                thresholdMs = TraversalPerfSpikeThresholdMs,
                edgeId,
                kind = kind ?? string.Empty
            });
        }

        private static bool IsDroppableDiagnosticEvent(string eventType)
        {
            switch (eventType ?? string.Empty)
            {
                case "playerBreadcrumb":
                case "followerSnapshot":
                case "walkThroughProgress":
                case "walkThroughMoverCornerIgnoredAsStale":
                case "followTraversalCommitReused":
                case "traversalApproachPathRejected":
                case "exitAuthorityCommitProgress":
                case "traversalVerifyProgress":
                    return true;
                default:
                    return false;
            }
        }

        private static void WriteEvent(string eventType, BotOwner bot, object payload)
        {
            if (!diagnosticsEnabled || writer == null)
            {
                return;
            }

            try
            {
                int sequence;
                lock (WriterSync)
                {
                    sequence = ++eventSequence;
                }
                DiagnosticEnvelope envelope = new DiagnosticEnvelope
                {
                    schema = 1,
                    sessionId = sessionId,
                    sequence = sequence,
                    utc = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture),
                    raidTime = Time.time,
                    frame = Time.frameCount,
                    locationId = locationId,
                    raidGeneration = raidGeneration,
                    eventType = eventType,
                    bot = bot == null ? null : new DiagnosticBotEnvelope
                    {
                        profileId = bot.ProfileId,
                        nickname = bot.Profile?.Nickname,
                        role = bot.Profile?.Info?.Settings?.Role.ToString()
                    },
                    payload = payload
                };
                lock (DiagnosticQueueSync)
                {
                    bool droppable = IsDroppableDiagnosticEvent(eventType);
                    if (DiagnosticWriteQueue.Count >= DiagnosticQueueHardLimit)
                    {
                        if (droppable)
                        {
                            diagnosticDroppedPeriodicEvents++;
                            return;
                        }

                        // Preserve the new state/failure event by sacrificing the oldest queued
                        // diagnostic only under genuine writer back-pressure.
                        if (DiagnosticWriteQueue.Count > 0)
                        {
                            DiagnosticWriteQueue.Dequeue();
                            diagnosticDroppedPeriodicEvents++;
                        }
                    }
                    else if (DiagnosticWriteQueue.Count >= DiagnosticQueueHighWaterMark && droppable)
                    {
                        diagnosticDroppedPeriodicEvents++;
                        return;
                    }

                    DiagnosticWriteQueue.Enqueue(envelope);
                }
                DiagnosticWriterSignal.Set();
            }
            catch (Exception ex)
            {
                DisableDiagnosticsAfterFailure("JSONL enqueue failed", ex);
            }
        }

        private static void DisableDiagnosticsAfterFailure(string reason, Exception ex)
        {
            diagnosticsEnabled = false;
            diagnosticWriterFailure = (reason ?? "diagnostics failed") + ": " + ex.Message;
            diagnosticWriterStopRequested = true;
            DiagnosticWriterSignal.Set();
            LogError(diagnosticWriterFailure);
        }

        private static bool CanUseRaidCommands(out string failure)
        {
            failure = string.Empty;
            if (!raidActive || !Singleton<AbstractGame>.Instantiated || Singleton<GameWorld>.Instance == null)
            {
                failure = "This command can only be used in an active raid.";
                return false;
            }

            Player localPlayer = FollowerEnvironment.LocalPlayer;
            if (!IsLivePlayer(localPlayer))
            {
                failure = "The local player is unavailable or dead.";
                return false;
            }

            return true;
        }

        private static bool IsLiveBot(BotOwner bot)
        {
            return bot != null &&
                   !bot.IsDead &&
                   bot.BotState == EBotState.Active &&
                   IsLivePlayer(bot.GetPlayer);
        }

        private static bool IsLivePlayer(Player player)
        {
            return player != null &&
                   player.HealthController != null &&
                   player.HealthController.IsAlive;
        }

        private static bool IsSameBot(BotOwner left, BotOwner right)
        {
            if (ReferenceEquals(left, right))
            {
                return true;
            }
            return left != null && right != null &&
                   !string.IsNullOrEmpty(left.ProfileId) &&
                   string.Equals(left.ProfileId, right.ProfileId, StringComparison.Ordinal);
        }

        private static bool IsVaultState(EPlayerState state)
        {
            return state == EPlayerState.ClimbOver ||
                   state == EPlayerState.ClimbUp ||
                   state == EPlayerState.VaultingFallDown ||
                   state == EPlayerState.VaultingLanding;
        }

        private static bool IsJumpState(EPlayerState state)
        {
            return state == EPlayerState.Jump ||
                   state == EPlayerState.JumpLanding;
        }

        private static bool IsProbeTraversalState(EPlayerState state)
        {
            return IsVaultState(state) || IsJumpState(state);
        }

        private static Vector3 GetFlatDirection(Vector3 direction)
        {
            direction.y = 0f;
            return direction.sqrMagnitude > 0.0001f ? direction.normalized : Vector3.zero;
        }

        private static bool IsFinite(Vector3 value)
        {
            return IsFinite(value.x) && IsFinite(value.y) && IsFinite(value.z);
        }

        private static bool IsFinite(float value)
        {
            return !float.IsNaN(value) && !float.IsInfinity(value);
        }

        private static object Vec(Vector3 value)
        {
            return new { x = value.x, y = value.y, z = value.z };
        }

        private static object Vec2(Vector2 value)
        {
            return new { x = value.x, y = value.y };
        }

        private static string GetBotName(BotOwner bot)
        {
            return bot?.Profile?.Nickname ?? bot?.ProfileId ?? "unknown follower";
        }

        private static string FormatProbeStatus(ProbeRuntime probe)
        {
            if (probe == null)
            {
                return "none";
            }
            return $"bot={GetBotName(probe.Bot)} stage={probe.Stage} state={probe.Player?.CurrentStateName} " +
                   $"exclusive={probe.ExclusiveMoverGate} elapsed={Mathf.Max(0f, Time.time - probe.RequestedAt):0.0}s" +
                   (string.IsNullOrEmpty(probe.SafetyHoldReason) ? string.Empty : $" hold={probe.SafetyHoldReason}");
        }

        private static string SanitizeFileName(string value)
        {
            string candidate = string.IsNullOrWhiteSpace(value) ? "unknown" : value;
            foreach (char invalid in Path.GetInvalidFileNameChars())
            {
                candidate = candidate.Replace(invalid, '_');
            }
            return candidate;
        }

        private static void LogInfo(string message)
        {
            // V1.3.11: high-frequency traversal traces belong in targeted JSONL diagnostics,
            // not the global BepInEx log. Keep normal raids quiet unless diagnostics are active.
            if (!diagnosticsEnabled)
            {
                return;
            }

            try
            {
                Logger.LogInfo("[TraversalTest] " + message);
            }
            catch
            {
                // Logging must never affect AI behavior.
            }
        }

        private static void LogError(string message)
        {
            try
            {
                Logger.LogError("[TraversalTest] " + message);
            }
            catch
            {
                // Logging must never affect AI behavior.
            }
        }

