        // The one cleanup-side physical actuator path for existing Chain and
        // PostTraversal consumers. A stale callback cannot borrow a newer owner
        // generation, even if it only wants to clear BotMover.Pause.
        private static bool TryReleaseMoverPauseAtOrigin(
            BotOwner bot, FollowerMovementWriterAuthority.WriterDomain owner,
            long originGeneration)
        {
            if (!FollowerMovementWriterAuthority.TryEnterBoundPhysicalMotion(
                bot, owner, originGeneration,
                out FollowerMovementWriterAuthority.WriteScope releaseScope, out _))
            {
                return false;
            }
            using (releaseScope)
            {
                try
                {
                    if (bot.Mover != null)
                    {
                        bot.Mover.SetBotMoverPause("R1-BAB60D417B1C",@bot,false);
                    }
                }
                catch
                {
                    // The token remains authoritative even when Mover is unavailable.
                }
            }
            return true;
        }

        // V2-RC10: the chain guard's born/explicitly transferred writer generation
        // is the ONLY acceptable retirement identity. Never borrow the live owner's
        // newer generation from a stale chain-cleanup callback. Release Pause only
        // while that same physical ticket remains owned by Traversal.
        private static bool RetireChainGuardToFollowAtOrigin(
            BotOwner bot, ChainHandoffAuthorityGuard guard, string reason)
        {
            if (bot == null || guard == null || guard.Generation != raidGeneration ||
                guard.MovementWriterGeneration <= 0)
            {
                return false;
            }
            if (!TryReleaseMoverPauseAtOrigin(
                bot, FollowerMovementWriterAuthority.WriterDomain.Traversal,
                guard.MovementWriterGeneration))
            {
                return false;
            }
            return FollowerMovementWriterAuthority.TransitionTraversalToFollowIfIdleExact(
                bot, guard.MovementWriterGeneration, reason);
        }

