        private sealed class LearningV2StrategyPrior
        {
            public float NativeAttempts;
            public float NativeSuccesses;
            public float AssistedAttempts;
            public float AssistedSuccesses;

            public static LearningV2StrategyPrior Merge(LearningV2StrategyPrior prior, TraversalExperienceRecord record)
            {
                LearningV2StrategyPrior merged = new LearningV2StrategyPrior();
                if (prior != null)
                {
                    // Bound stale influence while preserving monotonic safety across repeated re-teaching.
                    merged.NativeAttempts = prior.NativeAttempts * 0.50f;
                    merged.NativeSuccesses = prior.NativeSuccesses * 0.50f;
                    merged.AssistedAttempts = prior.AssistedAttempts * 0.50f;
                    merged.AssistedSuccesses = prior.AssistedSuccesses * 0.50f;
                }
                if (record != null)
                {
                    merged.NativeAttempts += Math.Max(0, record.NativeExecutorAttempts);
                    merged.NativeSuccesses += Math.Max(0, record.NativeExecutorSuccesses);
                    merged.AssistedAttempts += Math.Max(0, record.AssistedExecutorAttempts);
                    merged.AssistedSuccesses += Math.Max(0, record.AssistedExecutorSuccesses);
                }
                return merged;
            }
        }

