            public int EndBreadcrumbSequence;
            private Vector3 lifecycleEntry;
            public Vector3 Entry
            {
                get => lifecycleEntry;
                set { if (lifecycleEntry.x==value.x && lifecycleEntry.y==value.y && lifecycleEntry.z==value.z) return;
                    lifecycleEntry=value; Lifecycle.GeometryChanged();
                    LearningV468ObservedEntryWitness=false; LearningV429JumpAdmissionReserved=false;
                    V2PhysicalReceiptHasAnchor=false;
                }
            }
            private Vector3 lifecycleExit;
            public Vector3 Exit
            {
                get => lifecycleExit;
                set { if (lifecycleExit.x==value.x && lifecycleExit.y==value.y && lifecycleExit.z==value.z) return;
                    lifecycleExit=value; Lifecycle.GeometryChanged();
                    LearningV468ObservedEntryWitness=false; LearningV429JumpAdmissionReserved=false;
                    V2PhysicalReceiptHasAnchor=false;
                }
            }
