            public Vector3 RawEntry
            {
                get => lifecycleRawEntry;
                set { if (lifecycleRawEntry.x==value.x && lifecycleRawEntry.y==value.y && lifecycleRawEntry.z==value.z) return;
                    lifecycleRawEntry=value; Lifecycle.GeometryChanged();
                    LearningV468ObservedEntryWitness=false; LearningV429JumpAdmissionReserved=false;
                    V2PhysicalReceiptHasAnchor=false;
                }
            }
            private Vector3 lifecycleRawExit;
            public Vector3 RawExit
            {
                get => lifecycleRawExit;
                set { if (lifecycleRawExit.x==value.x && lifecycleRawExit.y==value.y && lifecycleRawExit.z==value.z) return;
                    lifecycleRawExit=value; Lifecycle.GeometryChanged();
                    LearningV468ObservedEntryWitness=false; LearningV429JumpAdmissionReserved=false;
                    V2PhysicalReceiptHasAnchor=false;
                }
            }
            public int ChainId;
