        private struct StrictPathMicroCacheKey : IEquatable<StrictPathMicroCacheKey>
        {
            public int StartX;
            public int StartY;
            public int StartZ;
            public int TargetX;
            public int TargetY;
            public int TargetZ;

            public static StrictPathMicroCacheKey From(Vector3 start, Vector3 target, float cellSize)
            {
                float inverse = 1f / Mathf.Max(0.05f, cellSize);
                return new StrictPathMicroCacheKey
                {
                    StartX = Mathf.RoundToInt(start.x * inverse),
                    StartY = Mathf.RoundToInt(start.y * inverse),
                    StartZ = Mathf.RoundToInt(start.z * inverse),
                    TargetX = Mathf.RoundToInt(target.x * inverse),
                    TargetY = Mathf.RoundToInt(target.y * inverse),
                    TargetZ = Mathf.RoundToInt(target.z * inverse)
                };
            }

            public bool Equals(StrictPathMicroCacheKey other)
            {
                return StartX == other.StartX && StartY == other.StartY && StartZ == other.StartZ &&
                       TargetX == other.TargetX && TargetY == other.TargetY && TargetZ == other.TargetZ;
            }

            public override bool Equals(object obj)
            {
                return obj is StrictPathMicroCacheKey other && Equals(other);
            }

            public override int GetHashCode()
            {
                unchecked
                {
                    int hash = 17;
                    hash = hash * 31 + StartX;
                    hash = hash * 31 + StartY;
                    hash = hash * 31 + StartZ;
                    hash = hash * 31 + TargetX;
                    hash = hash * 31 + TargetY;
                    hash = hash * 31 + TargetZ;
                    return hash;
                }
            }
        }

        private sealed class StrictPathMicroCacheEntry
        {
            public float SampledAt;
            public StrictPathResult Result;
        }

        private sealed class StrictPathResult
        {
            public Vector3 RawStart;
            public Vector3 RawTarget;
            public bool StartSampled;
            public bool TargetSampled;
            public Vector3 SampledStart;
            public Vector3 SampledTarget;
            public float StartSampleOffset;
            public float TargetSampleOffset;
            public bool CalculateReturned;
            public NavMeshPathStatus Status;
            public Vector3[] Corners;
            public float PathLength;
            public float TerminalToSampledTarget;
            public float TerminalToRawTarget;
            public bool StrictComplete;

            public object ToPayload()
            {
                float directDistance = Vector3.Distance(RawStart, RawTarget);
                return new
                {
                    rawStart = Vec(RawStart),
                    rawTarget = Vec(RawTarget),
                    startSampled = StartSampled,
                    targetSampled = TargetSampled,
                    sampledStart = StartSampled ? Vec(SampledStart) : null,
                    sampledTarget = TargetSampled ? Vec(SampledTarget) : null,
                    startSampleOffset = StartSampleOffset,
                    targetSampleOffset = TargetSampleOffset,
                    targetVerticalSampleOffset = TargetSampled ? Mathf.Abs(RawTarget.y - SampledTarget.y) : -1f,
                    calculateReturned = CalculateReturned,
                    status = Status.ToString(),
                    cornerCount = Corners?.Length ?? 0,
                    corners = (Corners ?? Array.Empty<Vector3>()).Select(Vec).ToArray(),
                    pathLength = PathLength,
                    directDistance,
                    detourRatio = directDistance > 0.1f ? PathLength / directDistance : 0f,
                    terminalToSampledTarget = TerminalToSampledTarget,
                    terminalToRawTarget = TerminalToRawTarget,
                    strictComplete = StrictComplete
                };
            }
        }
    }
}
